```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
    struct Record* next;
} Record;

typedef struct {
    size_t capacity;
    size_t size;
    int* key_array;
    int* offset_array;
    Record* head;
    pthread_mutex_t lock;
} RecordList;

#define INITIAL_CAPACITY 10
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 100

int generate_unique_key(int* key_array, size_t size) {
    while (1) {
        int key = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        for (size_t i = 0; i < size; ++i) {
            if (key_array[i] == key)
                return generate_unique_key(key_array, size);
        }
        return key;
    }
}

void initialize_record(Record* record) {
    record->s = rand() % SHRT_MAX;
    record->i = rand() % INT_MAX;
    record->f = (float)rand() / RAND_MAX * 100.0; // Random float between 0 and 100
}

RecordList* create_record_list() {
    RecordList* list = malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->key_array = malloc(list->capacity * sizeof(int));
    list->offset_array = malloc(list->capacity * sizeof(int));
    if (!list->key_array || !list->offset_array) {
        free(list->key_array);
        free(list->offset_array);
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;

    srand(time(NULL)); // Seed random number generator

    return list;
}

void resize_arrays(RecordList* list) {
    size_t new_capacity = list->capacity * 2;
    int* new_key_array = realloc(list->key_array, new_capacity * sizeof(int));
    int* new_offset_array = realloc(list->offset_array, new_capacity * sizeof(int));

    if (!new_key_array || !new_offset_array) return; // Handle error appropriately

    list->key_array = new_key_array;
    list->offset_array = new_offset_array;
    list->capacity = new_capacity;
}

void insert_record(RecordList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity)
        resize_arrays(list);

    int key = generate_unique_key(list->key_array, list->size);
    list->key_array[list->size] = key;

    if (list->size > 0)
        list->offset_array[list->size] =
            list->offset_array[list->size - 1] + list->key_array[list->size - 1];
    else
        list->offset_array[0] = key; // First element

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    initialize_record(new_record);

    new_record->next = list->head;
    list->head = new_record;

    ++list->size;

    pthread_mutex_unlock(&list->lock);
}

void free_records(RecordList* list) {
    Record* current = list->head;
    while (current) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    free(list->key_array);
    free(list->offset_array);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_records(RecordList* list, void (*process)(Record*)) {
    pthread_mutex_lock(&list->lock);

    Record* current = list->head;
    while (current) {
        process(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}
```

### Key Features:
- **Initialization and Memory Allocation**: The `RecordList` structure manages dynamic arrays for keys, offsets, and a linked list head pointer. Initial allocations are set to minimize fragmentation.

- **Thread Safety**: A mutex lock ensures that operations on the `RecordList` are thread-safe.

- **Dynamic Resizing**: The `resize_arrays()` function doubles the capacity of key and offset arrays when needed.

- **Random Key Generation**: Uniqueness is maintained for keys within a specified range using the `generate_unique_key()` function.

- **Clean-up Functionality**: The `free_records()` function safely deallocates all resources used by the `RecordList`. 

This implementation handles insertion, resizing, and iteration efficiently while ensuring thread safety.']

