#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>

#define MAX_FILES 100
#define BUFFER_SIZE 1024

typedef struct {
    char *filename;
    int line_count;
} FileInfo;

typedef struct {
    FileInfo files[MAX_FILES];
    int file_count;
    pthread_mutex_t lock;
} Aggregator;

Aggregator aggregator = {.file_count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

void* process_file(void* arg) {
    char *filename = (char*)arg;
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return NULL;
    }

    int line_count = 0;
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        ++line_count;
    }
    fclose(file);

    pthread_mutex_lock(&aggregator.lock);
    if (aggregator.file_count < MAX_FILES) {
        aggregator.files[aggregator.file_count].filename = filename;
        aggregator.files[aggregator.file_count].line_count = line_count;
        aggregator.file_count++;
    }
    pthread_mutex_unlock(&aggregator.lock);

    return NULL;
}

void write_json(const char *output_file) {
    FILE *file = fopen(output_file, "w");
    if (!file) {
        fprintf(stderr, "Error opening output file: %s\n", output_file);
        return;
    }

    fprintf(file, "[\n");
    for (int i = 0; i < aggregator.file_count; ++i) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "  {\"filename\": \"%s\", \"line_count\": %d}", 
                aggregator.files[i].filename, aggregator.files[i].line_count);
    }
    fprintf(file, "\n]\n");

    fclose(file);
}

void write_csv(const char *output_file) {
    FILE *file = fopen(output_file, "w");
    if (!file) {
        fprintf(stderr, "Error opening output file: %s\n", output_file);
        return;
    }

    fprintf(file, "Filename,Line Count\n");
    for (int i = 0; i < aggregator.file_count; ++i) {
        fprintf(file, "\"%s\",%d\n", aggregator.files[i].filename, aggregator.files[i].line_count);
    }

    fclose(file);
}

void print_manpage() {
    printf("Usage: program [options]\n"
           "Options:\n"
           "--manpage       Display this manual page.\n"
           "-c              Count lines in input files.\n"
           "-o output_file  Specify the output file for results.\n"
           "-f format       Specify the output format (json or csv).\n");
}

void parse_arguments(int argc, char *argv[], char **output_file, char **format) {
    int opt;
    while ((opt = getopt(argc, argv, "co:f:")) != -1) {
        switch (opt) {
            case 'c':
                break;
            case 'o':
                *output_file = optarg;
                break;
            case 'f':
                *format = optarg;
                break;
            default:
                print_manpage();
                exit(EXIT_FAILURE);
        }
    }

    if (argc - optind < 1) {
        fprintf(stderr, "Error: No input files specified.\n");
        print_manpage();
        exit(EXIT_FAILURE);
    }

    for (int i = optind; i < argc; ++i) {
        aggregator.files[aggregator.file_count].filename = argv[i];
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_file, (void*)argv[i])) {
            fprintf(stderr, "Error creating thread for file: %s\n", argv[i]);
        }
        pthread_detach(thread);
    }
}

int main(int argc, char *argv[]) {
    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    char *output_file = NULL;
    char *format = NULL;

    parse_arguments(argc, argv, &output_file, &format);

    // Wait for all threads to finish
    pthread_mutex_lock(&aggregator.lock);
    while (1) {
        int count = 0;
        for (int i = 0; i < MAX_FILES; ++i) {
            if (aggregator.files[i].filename == NULL) break;
            count++;
        }
        if (count == aggregator.file_count) break;
        usleep(10000); // Sleep for 10ms
    }
    pthread_mutex_unlock(&aggregator.lock);

    if (!output_file || !format) {
        fprintf(stderr, "Output file and format must be specified.\n");
        exit(EXIT_FAILURE);
    }

    if (strcmp(format, "json") == 0) {
        write_json(output_file);
    } else if (strcmp(format, "csv") == 0) {
        write_csv(output_file);
    } else {
        fprintf(stderr, "Unsupported format: %s\n", format);
        exit(EXIT_FAILURE);
    }

    gettimeofday(&end_time, NULL);
    long execution_time = (end_time.tv_sec - start_time.tv_sec) * 1000000L + end_time.tv_usec - start_time.tv_usec;
    printf("Execution time: %ld microseconds\n", execution_time);

    return 0;
}
