#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 100

void log_dns_attempt(const char *hostname, int success);
int resolve_hostname(const char *hostname, u_char *ip_address, size_t ip_len);

void process_line(char *line) {
    char *fields[MAX_FIELDS];
    char buffer[MAX_LINE_LENGTH];
    strncpy(buffer, line, sizeof(buffer));
    buffer[sizeof(buffer) - 1] = '\0';

    int field_count = 0;
    char *token = strtok(buffer, " ");
    while (token != NULL && field_count < MAX_FIELDS) {
        fields[field_count++] = token;
        token = strtok(NULL, " ");
    }

    if (field_count >= 2 && is_numeric(fields[field_count - 1]) && is_numeric(fields[field_count - 2])) {
        int num1 = atoi(fields[field_count - 1]);
        int num2 = atoi(fields[field_count - 2]);
        float average = (num1 + num2) / 2.0f;
        printf("Average: %.2f\n", average);
    } else {
        printf("No averaging needed.\n");
    }
}

int main() {
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        process_line(line);
        free(line);
        line = NULL;
        len = 0;
    }

    fclose(file);

    if (line) {
        free(line);
    }

    return EXIT_SUCCESS;
}

int resolve_hostname(const char *hostname, u_char *ip_address, size_t ip_len) {
    struct addrinfo hints, *res, *tmp;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_dns_attempt(hostname, 0);
        return -1;
    }

    for (tmp = res; tmp != NULL; tmp = tmp->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)tmp->ai_addr;
        if (inet_ntop(AF_INET, &(ipv4->sin_addr), (char *)ip_address, ip_len)) {
            log_dns_attempt(hostname, 1);
            freeaddrinfo(res);
            return 0;
        }
    }

    freeaddrinfo(res);
    log_dns_attempt(hostname, 0);
    return -1;
}

void log_dns_attempt(const char *hostname, int success) {
    FILE *log_file = fopen("dns_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "DNS Resolution for %s: %s\n", hostname, success ? "Success" : "Failure");
        fclose(log_file);
    }
}

int is_numeric(const char *str) {
    while (*str) {
        if (!isdigit((unsigned char)*str)) return 0;
        str++;
    }
    return 1;
}
