#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_LOG_SIZE 1024
#define LOG_FREQUENCY_MS 1000 // Log every second

typedef struct {
    char buffer[MAX_LOG_SIZE];
    pthread_mutex_t mutex;
    time_t last_log_time;
} Logger;

static Logger logger_instance = {.buffer = {0}, .mutex = PTHREAD_MUTEX_INITIALIZER, .last_log_time = 0};

void log_performance_metric(const char *format, ...) {
    time_t current_time = time(NULL);

    if (difftime(current_time, logger_instance.last_log_time) < LOG_FREQUENCY_MS / 1000.0) {
        return;
    }

    pthread_mutex_lock(&logger_instance.mutex);

    va_list args;
    va_start(args, format);
    int written = vsnprintf(logger_instance.buffer, MAX_LOG_SIZE, format, args);
    va_end(args);

    if (written < 0 || written >= MAX_LOG_SIZE) {
        pthread_mutex_unlock(&logger_instance.mutex);
        return; // Handle error: buffer too small
    }

    logger_instance.last_log_time = current_time;

    // Simulate asynchronous logging
    if (!simulate_network_failures()) {
        send_to_metrics_repository(logger_instance.buffer, written);
    } else {
        log_locally(logger_instance.buffer, written);
    }

    pthread_mutex_unlock(&logger_instance.mutex);
}

void initialize_logger() {
    memset(&logger_instance, 0, sizeof(Logger));
    logger_instance.last_log_time = time(NULL);
}

int simulate_network_failures() {
    // Simulate network failure scenario for demo purposes
    return rand() % 10 < 2; // 20% chance of network failure
}

void send_to_metrics_repository(const char *message, size_t length) {
    // Placeholder: Code to send log message to the centralized metrics repository
    printf("Sending to repository: %.*s\n", (int)length, message);
}

void log_locally(const char *message, size_t length) {
    // Fallback mechanism for local logging if network fails
