['Below is an implementation of a semaphore management system in C using POSIX semaphores, which are suitable for handling multi-platform requirements across Unix-like operating systems.

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>    // For O_* constants
#include <sys/stat.h> // For mode constants
#include <errno.h>
#include <time.h>

#define MAX_THREADS 500

typedef struct {
    sem_t *sem;
    int timeout_ms;  // Timeout in milliseconds
} Semaphore;

Semaphore* create_semaphore(int initial_value, int timeout_ms) {
    if (initial_value < 0) {
        fprintf(stderr, "Error: Invalid initial value for semaphore\n");
        return NULL;
    }

    Semaphore *s = malloc(sizeof(Semaphore));
    if (!s) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    s->sem = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, initial_value);
    if (s->sem == SEM_FAILED) {
        fprintf(stderr, "Error creating semaphore: %s\n", strerror(errno));
        free(s);
        return NULL;
    }

    s->timeout_ms = timeout_ms;

    return s;
}

int wait_semaphore(Semaphore *s) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += s->timeout_ms / 1000;
    ts.tv_nsec += (s->timeout_ms % 1000) * 1e6;

    if (sem_timedwait(s->sem, &ts) == -1) {
        if (errno == ETIMEDOUT) {
            fprintf(stderr, "Semaphore wait operation timed out\n");
            return -1;
        } else {
            perror("Failed semaphore wait operation");
            return -1;
        }
    }

    return 0; // Success
}

int signal_semaphore(Semaphore *s) {
    if (sem_post(s->sem) == -1) {
        perror("Failed semaphore signal operation");
        return -1;
    }
    return 0; // Success
}

void delete_semaphore(Semaphore *s) {
    if (sem_close(s->sem) == -1) {
        perror("Failed to close semaphore");
    }

    if (sem_unlink("/my_semaphore") == -1) {
        perror("Failed to unlink semaphore");
    }

    free(s);
}

int main() {
    // Example usage
    Semaphore *s = create_semaphore(5, 1000); // Initial value 5, timeout 1000ms

    if (!s) return EXIT_FAILURE;

    if (wait_semaphore(s) == -1) {
        printf("Failed to acquire semaphore\n");
    } else {
        printf("Semaphore acquired successfully\n");

        if (signal_semaphore(s) == -1) {
            printf("Failed to release semaphore\n");
        }
    }

    delete_semaphore(s);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **POSIX Semaphores**: Used for cross-platform compatibility and support for concurrent threads.
- **Timeout Mechanism**: Allows configurable timeout for `sem_timedwait`.
- **Error Handling**: Provides error messages for invalid initial values and wait timeouts.
- **Resource Management**: Proper allocation, deallocation, and cleanup with `malloc`, `free`, `sem_open`, `sem_close`, and `sem_unlink`.

This code is designed to be easily integrated into existing systems while being mindful of performance optimizations and resource constraints.']

