void insertOrAppendNode(std::vector<std::shared_ptr<Node>>& nodeList,
                        std::shared_ptr<Node> nodeToFind, 
                        std::shared_ptr<Node> nodeToAdd) {

    bool found = false;

    for (auto it = nodeList.begin(); it != nodeList.end(); ++it) {
        if (**it == *nodeToFind) { // Assuming Node class has an appropriate equality operator defined
            nodeList.insert(it + 1, nodeToAdd);
            found = true;
            break;
        }
    }

    if (!found) {
        nodeList.push_back(nodeToAdd);
    }
