#include <boost/log/support/date_time.hpp>
#include <boost/log/expressions.hpp>
#include <boost/log/sources/severity_logger.hpp>
#include <boost/log/sources/record_ostream.hpp>
#include <boost/log/sinks/basic_sink_backend.hpp>
#include <boost/log/sinks/sync_frontend.hpp>
#include <boost/log/sinks/text_ostream_backend.hpp>
#include <boost/thread/lock_guard.hpp>
#include <boost/thread/shared_mutex.hpp>
#include <boost/asio.hpp>
#include <iostream>
#include <fstream>
#include <memory>

namespace logging {

    enum class severity_level {
        trace,
        debug,
        info,
        warning,
        error,
        fatal
    };

    BOOST_LOG_ATTRIBUTE_KEYWORD(severity, "Severity", severity_level)
    BOOST_LOG_GLOBAL_LOGGER_INIT(my_logger, boost::log::sources::severity_logger_mt<severity_level>)

    class Logger {
    public:
        static my_logger& instance() {
            static my_logger lg;
            return lg;
        }

        void init(const std::string& log_file) {
            namespace logging = boost::log;
            namespace sinks = boost::log::sinks;

            auto backend = std::make_shared<sinks::text_ostream_backend>();
            auto frontend = std::make_shared<sinks::sync_frontend<std::mutex>>(backend);

            backend->add_stream(boost::shared_ptr<std::ostream>(&std::clog, boost::null_deleter()));
            if (!log_file.empty()) {
                backend->add_stream(std::make_unique<std::ofstream>(log_file));
            }

            logging::core::get()->add_sink(frontend);

            logging::add_common_attributes();
            logging::core::get()->set_filter(
                logging::trivial::severity >= severity_level::info
            );
        }

        void set_severity_level(severity_level level) {
            namespace logging = boost::log;
            logging::core::get()->set_filter(logging::trivial::severity >= level);
        }

        template<typename SeverityLevel>
        BOOST_LOG_INLINE_GLOBAL_LOGGER_ENTITY(my_logger, SeverityLevel)
    };

    class AsyncLoggingManager {
    public:
        static void setup_async_logging(const std::string& log_file) {
            namespace logging = boost::log;
            namespace sinks = boost::log::sinks;

            auto backend = std::make_shared<sinks::text_ostream_backend>();
            backend->locked_backend()->add_stream(std::make_unique<std::ofstream>(log_file));

            typedef sinks::asynchronous_sink<sinks::text_ostream_backend> sink_t;
            static sink_t* sink;
            if (!sink) {
                boost::shared_ptr<sink_t> new_sink(new sink_t(backend, boost::asio::io_service()));
                logging::core::get()->add_sink(new_sink);
                sink = new_sink.get();
            }

            logging::add_common_attributes();
        }
    };

} // namespace logging

int main() {
    std::string log_file = "service_log.txt";
    logging::Logger::instance().init(log_file);

    logging::AsyncLoggingManager::setup_async_logging("async_service_log.txt");

    BOOST_LOG_SEV(logging::my_logger::get(), logging::trivial::info) << "Service started";

    // Simulate dynamic log level adjustment
    logging::Logger::instance().set_severity_level(logging::severity_level::debug);

    BOOST_LOG_SEV(logging::my_logger::get(), logging::trivial::debug) << "Debugging service";

    return 0;
}
```

