public class AsyncHttpRequestProcessor
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentQueue<HttpRequestInfo> _requestQueue = new();
    private readonly int _maxConcurrentRequests;
    private readonly TimeSpan _connectionTimeout;
    private readonly ILogger<AsyncHttpRequestProcessor> _logger;

    public AsyncHttpRequestProcessor(int maxConcurrentRequests, TimeSpan connectionTimeout, ILogger<AsyncHttpRequestProcessor> logger)
    {
        _httpClient = new HttpClient { Timeout = connectionTimeout };
        _maxConcurrentRequests = maxConcurrentRequests;
        _connectionTimeout = connectionTimeout;
        _logger = logger;
    }

    public void EnqueueRequest(HttpRequestInfo requestInfo)
    {
        if (requestInfo == null) throw new ArgumentNullException(nameof(requestInfo));
        _requestQueue.Enqueue(requestInfo);
        ProcessQueue();
    }

    private async Task ProcessQueue()
    {
        while (_requestQueue.TryDequeue(out var requestInfo))
        {
            using var cts = new System.Threading.CancellationTokenSource(_connectionTimeout);
            try
            {
                await ProcessRequestAsync(requestInfo, cts.Token).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error processing request {requestInfo.Url}");
                if (ShouldRetry(requestInfo)) EnqueueRequest(requestInfo); // Retry logic
            }
        }

        // Ensure new requests are processed as they come in
        Task.Delay(100).ContinueWith(_ => ProcessQueue(), TaskScheduler.Default);
    }

    private async Task ProcessRequestAsync(HttpRequestInfo request, System.Threading.CancellationToken cancellationToken)
    {
        HttpResponseMessage response = null;
        try
        {
            if (request.Method == HttpMethod.Get)
                response = await _httpClient.GetAsync(request.Url, cancellationToken).ConfigureAwait(false);
            else if (request.Method == HttpMethod.Post && request.Content != null)
                response = await _httpClient.PostAsync(request.Url, request.Content, cancellationToken).ConfigureAwait(false);

            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Request to {request.Url} failed with status code {response.StatusCode}");

            var content = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            _logger.LogInformation($"Successfully processed request for {request.Url} in {(DateTime.UtcNow - request.Timestamp).TotalMilliseconds} ms");
        }
        catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            throw new HttpRequestException($"Request to {request.Url} timed out.");
        }
        finally
        {
            response?.Dispose();
        }
    }

    private bool ShouldRetry(HttpRequestInfo request)
    {
        // Implement retry logic based on conditions like specific status codes or number of attempts
        return true; // Placeholder for more complex retry logic
    }

    public class HttpRequestInfo
    {
        public string Url { get; set; }
        public HttpMethod Method { get; set; } = HttpMethod.Get;
        public HttpContent Content { get; set; }
        public DateTime Timestamp { get; } = DateTime.UtcNow;

        public HttpRequestInfo(string url, HttpMethod method = null, HttpContent content = null)
        {
            Url = url ?? throw new ArgumentNullException(nameof(url));
            Method = method ?? HttpMethod.Get;
            Content = content;
        }
    }
}

