public class GameSettingsManager : IDisposable
{
    private readonly string _configFilePath = "gameConfig.xml";
    private Dictionary<string, object> _settings;
    private FileSystemWatcher _fileWatcher;
    private bool _disposed = false;

    public GameSettingsManager()
    {
        LoadConfiguration();
        SetupFileWatcher();
    }

    private void LoadConfiguration()
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            if (File.Exists(_configFilePath))
            {
                doc.Load(_configFilePath);
                XmlNode root = doc.DocumentElement;

                _settings = new Dictionary<string, object>
                {
                    { "PlayerCount", int.Parse(root["GameSettings"]["PlayerCount"].InnerText) },
                    { "EnvironmentSize", float.Parse(root["GameSettings"]["EnvironmentSize"].InnerText) },
                    { "AIDifficultyLevel", root["GameSettings"]["AIDifficultyLevel"].InnerText }
                };

                LogConfigurationChange("Loaded configuration from file.");
            }
            else
            {
                UseDefaultSettings();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading config: {ex.Message}. Using default settings.");
            UseDefaultSettings();
        }
    }

    private void UseDefaultSettings()
    {
        _settings = new Dictionary<string, object>
        {
            { "PlayerCount", 4 },
            { "EnvironmentSize", 1000.0f },
            { "AIDifficultyLevel", "Medium" }
        };

        LogConfigurationChange("Loaded default settings.");
    }

    private void SetupFileWatcher()
    {
        _fileWatcher = new FileSystemWatcher(Path.GetDirectoryName(_configFilePath))
        {
            Filter = Path.GetFileName(_configFilePath),
            NotifyFilter = NotifyFilters.LastWrite
        };
        _fileWatcher.Changed += OnConfigChanged;
        _fileWatcher.EnableRaisingEvents = true;
    }

    private void OnConfigChanged(object sender, FileSystemEventArgs e)
    {
        Thread.Sleep(1000); // Debounce the file change event.

        LoadConfiguration();
        NotifyGameSessionsOfChange();  // Placeholder for notifying game sessions
    }

    private void LogConfigurationChange(string message)
    {
        Console.WriteLine($"{DateTime.Now}: {message}");
        // Here you could extend to log to a file or other logging mechanism.
    }

    public Dictionary<string, object> GetCurrentSettings()
    {
        return _settings;
    }

    private void NotifyGameSessionsOfChange()
    {
        // Implement logic for notifying existing game sessions about the configuration change
        Console.WriteLine("Notifying game sessions of new settings.");
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            _fileWatcher?.Dispose();
            _disposed = true;
        }
    }
