using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public class XmlProcessingException : Exception
{
    public XmlProcessingException(string message) : base(message) { }
}

class Program
{
    private const string RootDirectory = @"C:\Data\XMLProcessing";

    static void Main()
    {
        try
        {
            string dirPath = GetOrCreateDirPath();
            Console.WriteLine($"Using directory: {dirPath}");

            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load("example.xml"); // Load your XML document here

            XmlElement element = FindFirstElementByXPath(xmlDoc, "yourElementName");
            if (element != null)
            {
                Console.WriteLine($"Found element: {element.OuterXml}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    private static XmlElement FindFirstElementByXPath(XmlDocument xmlDoc, string elementName)
    {
        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"/descendant-or-self::{elementName}");

        if (!nodes.MoveNext())
        {
            throw new XmlProcessingException($"No element found with name '{elementName}'.");
        }

        if (nodes.Count > 1)
        {
            throw new XmlProcessingException($"Duplicate elements found with name '{elementName}'.");
        }

        return nodes.Current as XmlElement;
    }

    private static string GetOrCreateDirPath()
    {
        string dirPath = Environment.GetEnvironmentVariable("DIR_PATH");

        if (!string.IsNullOrEmpty(dirPath))
        {
            if (Directory.Exists(dirPath))
            {
                return dirPath;
            }
        }

        string newDirPath;

        try
        {
            newDirPath = CreateUniqueDirectory();
            SetEnvVarSecurely("DIR_PATH", newDirPath);
            return newDirPath;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error creating directory: {ex.Message}");
            throw; // Or handle gracefully as needed.
        }
    }

    private static string CreateUniqueDirectory()
    {
        string timestamp = DateTime.Now.ToString("yyyyMMddHHmmssfff");
        string randomString = Guid.NewGuid().ToString("N").Substring(0, 8);
        string dirName = $"XMLProcessing_{timestamp}_{randomString}";
        string fullPath = Path.Combine(RootDirectory, dirName);

        int attempts = 0;
        while (true)
        {
            try
            {
                Directory.CreateDirectory(fullPath);
                return fullPath;
            }
            catch (IOException ex) when ((ex.HResult & 0x0000FFFF) == 0x20 || // ERROR_ALREADY_EXISTS
                                       (ex.HResult & 0x80070070) == 0x80070070) // ERROR_DISK_FULL or similar
            {
                attempts++;
                if (attempts > 5)
                {
                    throw new DirectoryNotFoundException("Failed to create directory after multiple attempts.");
                }
                fullPath = Path.Combine(RootDirectory, $"{dirName}_{attempts}");
            }
        }
    }

    private static void SetEnvVarSecurely(string key, string value)
    {
        Environment.SetEnvironmentVariable(key, value, EnvironmentVariableTarget.Machine);
    }
}
```

### Key Points:

- **Exception Handling**: Custom exceptions are used to handle cases where no elements or multiple elements with the specified name are found.
- **Directory Management**: The function checks for an existing `DIR_PATH` environment variable. If not set or invalid, it creates a uniquely named directory under a predefined root path.
- **Error Handling**: Attempts to create directories include retries and error logging. If unable to create after several attempts, it throws an exception.
- **Security**: Environment variables are managed securely using the `EnvironmentVariableTarget.Machine` scope for persistence across sessions.
- **Performance Considerations**: The environment variable is checked once at the beginning of the operation and stored in a local variable for subsequent use.']

