import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.servlet.http.HttpServletRequest;

public class MD5Service {

    private final ExecutorService executorService;
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final RateLimiter rateLimiter = new RateLimiter(100); // 100 requests per second
    private final Logger logger = Logger.getLogger(MD5Service.class.getName());
    private final String logFilePath;

    public MD5Service(int threadPoolSize, String trustedOriginsFile, String logFilePath) throws IOException {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        loadTrustedOrigins(trustedOriginsFile);
        configureLogger(logFilePath);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> executorService.shutdown()));
    }

    private void loadTrustedOrigins(String trustedOriginsFile) throws IOException {
        // Load trusted origins from a file
        try (BufferedReader reader = new BufferedReader(new FileReader(trustedOriginsFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Add logic to parse and store trusted origins if needed
            }
        }
    }

    private void configureLogger(String logFilePath) throws IOException {
        this.logFilePath = logFilePath != null ? logFilePath : "logs/defaultLog.log";
        FileHandler fileHandler = new FileHandler(logFilePath, true);
        logger.addHandler(fileHandler);

        SimpleFormatter formatter = new SimpleFormatter();
        fileHandler.setFormatter(formatter);
    }

    public void processRequest(HttpServletRequest request) {
        executorService.submit(() -> {
            String requestBody = request.getReader().lines().reduce("", String::concat);

            if (rateLimiter.tryAcquire()) {
                try {
                    String hash = getMD5Hash(requestBody);
                    if (isTrustedOrigin(request.getHeader("Origin"))) {
                        logComputation(requestBody, hash);
                    }
                } catch (NoSuchAlgorithmException e) {
                    logger.log(Level.SEVERE, "Failed to compute MD5 hash", e);
                } finally {
                    rateLimiter.release();
                }
            } else {
                logger.log(Level.WARNING, "Rate limit exceeded");
            }
        });
    }

    private String getMD5Hash(String input) throws NoSuchAlgorithmException {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        String hash = sb.toString();

        cache.putIfAbsent(input, hash);
        return hash;
    }

    private boolean isTrustedOrigin(String originHeader) {
        // Implement logic to check if the origin header matches a trusted origin
        return true; // Placeholder for actual implementation
    }

    private void logComputation(String input, String hash) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFilePath, true))) {
            writer.write(String.format("%s: %s -> %s%n", System.currentTimeMillis(), input, hash));
        }
    }

    public static class RateLimiter {
        private final Semaphore semaphore;
        private final ScheduledExecutorService scheduler;

        public RateLimiter(int permitsPerSecond) {
            this.semaphore = new Semaphore(permitsPerSecond);
            this.scheduler = Executors.newScheduledThreadPool(1);
            scheduler.scheduleAtFixedRate(this::release, 1, 1, TimeUnit.SECONDS);
        }

        public boolean tryAcquire() throws InterruptedException {
            return semaphore.tryAcquire();
        }

        public void release() {
            for (int i = 0; i < semaphore.availablePermits(); i++) {
                semaphore.release();
            }
        }
    }
}
