<?php

function manageUserRequest($request) {
    // Validate input
    if (!isset($request['name'], $request['email'], $request['password'])) {
        logAction('Validation failed: Missing required fields.');
        return json_encode(['message' => 'error', 'details' => 'Missing required fields']);
    }

    if (!validateEmailFormat($request['email'])) {
        logAction('Validation failed: Invalid email format.');
        return json_encode(['message' => 'error', 'details' => 'Invalid email format']);
    }

    if (strlen($request['password']) < 8) {
        logAction('Validation failed: Password too short.');
        return json_encode(['message' => 'error', 'details' => 'Password must be at least 8 characters long']);
    }

    $emailUnique = checkEmailUniqueness($request['email'], isset($request['id']) ? (int)$request['id'] : null);
    if (!$emailUnique) {
        logAction('Validation failed: Email not unique.');
        return json_encode(['message' => 'error', 'details' => 'Email already in use']);
    }

    // Perform health checks
    if (!performHealthChecks()) {
        notifyStakeholders();
        return jsonEncodeError('Service unavailable. Please try again later.');
    }

    $hashedPassword = password_hash($request['password'], PASSWORD_DEFAULT);

    try {
        if (isset($request['id'])) {
            handleUpdateOrDelete((int)$request['id'], $request, $hashedPassword);
        } else {
            createUserAccount($request['name'], $request['email'], $hashedPassword);
        }

        synchronizeWithExternalService($request); // Synchronize user profile

    } catch (Exception $e) {
        logAction('Error: ' . $e->getMessage());
        return jsonEncodeError('An error occurred. Please try again later.');
    }

    return json_encode(['message' => 'success']);
}

function validateEmailFormat($email) {
    return filter_var($email, FILTER_VALIDATE_EMAIL);
}

function checkEmailUniqueness($email, $userId = null) {
    // Implement database query to ensure email uniqueness
    // Use parameterized queries to prevent SQL injection
    $query = "SELECT COUNT(*) FROM users WHERE email = ? AND id != ?";
    $stmt = $db->prepare($query);
    $stmt->bind_param("si", $email, $userId);
    $stmt->execute();
    $result = $stmt->get_result()->fetch_array()[0];
    return $result === 0;
}

function createUserAccount($name, $email, $hashedPassword) {
    // Implement database save with retry logic
    $query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
    executeWithRetry(function() use ($query, $name, $email, $hashedPassword) {
        global $db;
        $stmt = $db->prepare($query);
        return $stmt->execute([$name, $email, $hashedPassword]);
    });
}

function handleUpdateOrDelete($userId, $request, $hashedPassword) {
    if (isset($request['sub_action']) && $request['sub_action'] === 'delete') {
        deleteUserAccount($userId);
    } else {
        updateUserAccount($userId, $request, $hashedPassword);
    }
}

function updateUserAccount($userId, $request, $hashedPassword) {
    // Update user account
    $query = "UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?";
    executeWithRetry(function() use ($query, $request, $hashedPassword, $userId) {
        global $db;
        $stmt = $db->prepare($query);
        return $stmt->execute([$request['name'], $request['email'], $hashedPassword, $userId]);
    });
}

function deleteUserAccount($userId) {
    // Delete user account and invalidate cache
    $query = "DELETE FROM users WHERE id = ?";
    executeWithRetry(function() use ($query, $userId) {
        global $db;
        $stmt = $db->prepare($query);
        return $stmt->execute([$userId]);
    });
}

function synchronizeWithExternalService($request) {
    // Implement API call with retry and backoff
    try {
        $apiResponse = callExternalApi($request); // Simulated function
        if ($apiResponse['status'] !== 'success') {
            throw new Exception('API synchronization failed');
        }
    } catch (Exception $e) {
        logAction('Synchronization failed: ' . $e->getMessage());
        retryWithBackoff(function() use ($request) { synchronizeWithExternalService($request); });
    }
}

function performHealthChecks() {
    // Check database and external service health
    return checkDatabaseConnection() && checkExternalApiStatus();
}

function logAction($message) {
    // Log message to a distributed logging framework
    logger::log($message);
}

function notifyStakeholders() {
    // Send alert notifications if necessary
    alert::notify('Service is down.');
}

function jsonEncodeError($details) {
    return json_encode(['message' => 'error', 'details' => $details]);
}

function executeWithRetry($callback, $retries = 3, $delay = 1000) {
    for ($attempt = 1; $attempt <= $retries; $attempt++) {
        try {
            return $callback();
        } catch (Exception $e) {
            if ($attempt === $retries) throw $e;
            usleep($delay * $attempt);
        }
    }
}

function retryWithBackoff($callback, $maxRetries = 3, $initialDelay = 1000) {
    for ($attempt = 1; $attempt <= $maxRetries; $attempt++) {
        try {
            return $callback();
        } catch (Exception $e) {
            if ($attempt === $maxRetries) throw $e;
            usleep($initialDelay * pow(2, $attempt - 1));
        }
    }
}

