    private readonly ILogger<PageElementController> _logger;
    private readonly IBackgroundJobQueue _backgroundJobQueue;
    private readonly ICdnIntegrationService _cdnIntegrationService;

    public PageElementController(IPageContentService pageContentService, 
                                 ILogger<PageElementController> logger,
                                 IBackgroundJobQueue backgroundJobQueue,
                                 ICdnIntegrationService cdnIntegrationService)
    {
        _pageContentService = pageContentService;
        _logger = logger;
        _backgroundJobQueue = backgroundJobQueue;
        _cdnIntegrationService = cdnIntegrationService;
    }

    [HttpPost("update-element")]
    public async Task<IActionResult> UpdateElement(string sectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrWhiteSpace(sectionId) || !Guid.TryParse(sectionId, out _))
            return BadRequest("Invalid section ID format.");

        if (string.IsNullOrWhiteSpace(elementId) || elementId.Length > 256)
            return BadRequest("Invalid or too long element ID.");

        if (string.IsNullOrWhiteSpace(htmlContent) || htmlContent.Length > 10_000)
            return BadRequest("HTML content is empty or too large.");

        try
        {
            using (_pageContentService.BeginTransaction())
            {
                _logger.LogInformation($"Updating HTML for section {sectionId}, element {elementId}.");
                await _pageContentService.UpdateElementHtmlAsync(sectionId, elementId, htmlContent);

                // Notify CDN to update the content
                await _cdnIntegrationService.UpdateCdnCacheAsync(sectionId, elementId);

                // Queue a background job to refresh page section
                var jobId = _backgroundJobQueue.Enqueue<RefreshPageSectionJob>(
                    new RefreshPageSectionJobParameters { SectionId = sectionId }, 
                    retryCount: 3);

                _logger.LogInformation($"Enqueued background job for refreshing section {sectionId}. Job ID: {jobId}");
            }

            return Ok(new { Status = "Success", Message = "Element updated and refresh queued." });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to update element {elementId} in section {sectionId}.");
            return StatusCode(500, new { Status = "Failure", Message = "Internal server error." });
        }
    }
}

