const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');
const globby = require('globby');

// Simple in-memory cache
const cache = new Map();

async function readFileContent(filePath) {
    try {
        const fileContents = await fs.readFile(filePath, 'utf8');
        return fileContents;
    } catch (error) {
        console.error(`Error reading file ${filePath}:`, error);
        throw error; // Re-throw to handle it outside if needed
    }
}

async function readAndConcatenateFiles(directory, extension, maxFileSize = 1048576 /* 1MB */) {
    const cacheKey = `${directory}-${extension}`;

    if (cache.has(cacheKey)) {
        return cache.get(cacheKey);
    }

    try {
        const filePaths = await globby(path.join(directory, `**/*.${extension}`));

        // Filter files based on size
        const filteredFilePaths = await Promise.all(filePaths.map(async (filePath) => {
            const stats = await fs.stat(filePath);
            return stats.size <= maxFileSize ? filePath : null;
        })).then(results => results.filter(Boolean));

        const fileContents = await Promise.all(filteredFilePaths.map(readFileContent));
        const concatenatedContent = fileContents.join('\n');

        // Update the cache
        cache.set(cacheKey, concatenatedContent);

        return concatenatedContent;
    } catch (error) {
        console.error('Error processing files:', error);
        throw new Error('Failed to process files');
    }
}

// Example usage:
// readAndConcatenateFiles('/path/to/directory', 'txt').then(console.log).catch(console.error);
```

This code uses the `fs.promises` API for asynchronous file operations, and `globby` for efficient glob pattern matching. It includes basic caching to prevent redundant processing of directories with the same parameters. The function handles errors by logging them and re-throwing where necessary to allow higher-level handling if needed. Adjust the `maxFileSize` parameter as required to limit memory usage based on file size constraints."]

