import re
from collections import defaultdict, Counter
from typing import List, Dict, Tuple
import string
import requests

class KeywordProcessor:
    def __init__(self, initial_keywords: List[str]):
        self.keywords = set(initial_keywords)
        self.keyword_frequencies = Counter()
        self.cache = {}

    def _normalize_text(self, text: str) -> str:
        # Convert to lowercase and remove punctuation
        return re.sub(f'[{string.punctuation}]', '', text.lower())

    def _match_keywords(self, normalized_text: str):
        words = set(normalized_text.split())
        matched_keywords = [kw for kw in self.keywords if self._heuristic_match(kw, words)]

        # Update cache and frequency count
        for keyword in matched_keywords:
            self.keyword_frequencies[keyword] += 1
            self.cache[normalized_text] = matched_keywords

    def _heuristic_match(self, keyword: str, word_set: set) -> bool:
        # Simple heuristic match allowing variations (e.g., stemming)
        return any(keyword.startswith(w[:len(keyword)]) for w in word_set)

    def process_review(self, review: str):
        normalized_text = self._normalize_text(review)

        if normalized_text in self.cache:
            matched_keywords = self.cache[normalized_text]
        else:
            self._match_keywords(normalized_text)
            matched_keywords = [kw for kw in self.keywords if self._heuristic_match(kw, set(normalized_text.split()))]

        # Optionally integrate sentiment analysis
        sentiments = {kw: self.get_sentiment_for_keyword(kw) for kw in matched_keywords}

        return matched_keywords, sentiments

    def get_sentiment_for_keyword(self, keyword: str) -> float:
        # Mock function to represent external API call for sentiment analysis
        try:
            response = requests.get(f'https://api.sentiment.com/analyze', params={'text': keyword})
            if response.status_code == 200:
                return response.json().get('sentiment_score', 0.0)
        except requests.RequestException as e:
            print(f"Sentiment analysis API request failed: {e}")

        # Default sentiment score
        return 0.0

    def update_keywords(self, new_keywords: List[str]):
        self.keywords.update(new_keywords)

    def report_top_features(self, top_n: int) -> Dict[str, int]:
        return dict(self.keyword_frequencies.most_common(top_n))

# Example usage:
initial_keywords = ['battery', 'screen', 'camera']
processor = KeywordProcessor(initial_keywords)

reviews_stream = [
    "The battery life is incredible!",
    "I love the screen clarity.",
    "Camera quality could be better."
]

for review in reviews_stream:
    processor.process_review(review)

print(processor.report_top_features(3))
