function integrateScriptsIntoFooter(scriptsArray) {
    // Helper function to safely create a script element from an object
    function createScriptElement(scriptObj) {
        if (!scriptObj || typeof scriptObj !== 'object') return '';

        let scriptContent = '';

        if (typeof scriptObj.src === 'string' && scriptObj.src.trim()) {
            const scriptTag = document.createElement('script');
            scriptTag.type = 'text/javascript';
            scriptTag.async = true; // Asynchronously load the script for better performance
            scriptTag.src = scriptObj.src;

            if (scriptObj.defer) scriptTag.defer = true;

            // Add any other attributes dynamically
            Object.keys(scriptObj).forEach(attr => {
                if (attr !== 'src' && attr !== 'defer') {
                    scriptTag.setAttribute(attr, scriptObj[attr]);
                }
            });

            return scriptTag.outerHTML;
        } else if (typeof scriptObj.content === 'string') {
            const scriptTag = document.createElement('script');
            scriptTag.type = 'text/javascript';

            // Minimize reflows by using textContent for dynamic scripts
            scriptTag.textContent = scriptObj.content.trim();

            // Handle inline event handlers safely
            if (scriptObj.events) {
                Object.keys(scriptObj.events).forEach(event => {
                    scriptTag.addEventListener(event, scriptObj.events[event]);
                });
            }

            return scriptTag.outerHTML;
        }

        return '';
    }

    const scriptsContainer = document.createElement('div');

    // Handle edge cases such as empty arrays or null values
    if (!Array.isArray(scriptsArray) || !scriptsArray.length) {
        return '<!-- No scripts to load -->';
    }

    let footerScriptsHTML = '';

    for (const scriptObj of scriptsArray) {
        const scriptElementHTML = createScriptElement(scriptObj);

        // Append only valid and non-empty script elements
        if (scriptElementHTML.trim()) {
            footerScriptsHTML += scriptElementHTML;
        }
    }

    // Insert the constructed HTML into a container to minimize direct DOM manipulation
    scriptsContainer.innerHTML = footerScriptsHTML;

    return scriptsContainer.innerHTML;
}

// Example usage:
const scriptsArray = [
    { src: 'https://example.com/script1.js', defer: true },
    {
        content: "console.log('Inline script');",
        events: { onload: () => console.log("Loaded inline script") }
    }
];

document.querySelector('footer').innerHTML += integrateScriptsIntoFooter(scriptsArray);
