    private final int maxConcurrentThreads;
    private final Semaphore rateLimiter;
    private final ExecutorService executorService;
    private final Map<String, String> cache = new ConcurrentHashMap<>();
    private final Path configFilePath;
    private final Path logFilePath;

    public DialogFieldRefresherService(int maxConcurrentThreads, int requestsPerSecond, Path configFilePath) {
        this.maxConcurrentThreads = maxConcurrentThreads;
        this.rateLimiter = new Semaphore(requestsPerSecond);
        this.executorService = Executors.newFixedThreadPool(maxConcurrentThreads);
        this.configFilePath = configFilePath;
        this.logFilePath = Paths.get("dialog_refresh_log.txt"); // default log file path

        loadConfig();
