            ObjectMapper mapper = new ObjectMapper();
            List<String> fieldsToMonitor = mapper.readValue(is, new TypeReference<List<String>>() {});
            cache.putAll(fieldsToMonitor.stream().collect(Collectors.toMap(Function.identity(), field -> "defaultValue")));
        } catch (IOException e) {
            logger.error("Failed to load configuration file.", e);
        }
    }

    public void processRequest(HttpRequest request) {
        executorService.submit(() -> {
            rateLimiter.acquireUninterruptibly();
            try {
                if (!authenticate(request)) return;

                String resourceId = extractResourceId(request);
                URL url = new URL(extractUrl(request));
                for (Map.Entry<String, String> entry : cache.entrySet()) {
                    sendRefreshMessage(resourceId, entry.getKey(), entry.getValue());
                }

                logRequest(request, true); // Log successful refresh attempt
            } catch (Exception e) {
                logger.error("Error processing request: " + request.toString(), e);
                logRequest(request, false); // Log failed refresh attempt
            } finally {
                rateLimiter.release();
            }
        });
    }

    private boolean authenticate(HttpRequest request) {
