        DialogFieldRefresherService service = new DialogFieldRefresherService(10, 150, configPath);

        // Simulate incoming requests
        for (int i = 0; i < 1000; i++) {
            service.processRequest(new HttpRequest());
        }

        service.shutdown();
    }
}
