function mergeDataStreams(streams, corruptedByteSequence) {
    const MAX_MEMORY_USAGE = 1024 * 1024; // Example: 1MB limit
    let totalBytesProcessed = 0;
    let currentBuffer = Buffer.allocUnsafe(0);

    async function* streamIterator() {
        for (const stream of streams) {
            const reader = stream.getReader();
            while (true) {
                const { done, value } = await reader.read();
                if (done) break;
                yield value;
            }
        }
    }

    async function processStreams() {
        try {
            for await (const chunk of streamIterator()) {
                // Check memory constraints
                if ((currentBuffer.length + chunk.length) > MAX_MEMORY_USAGE) {
                    throw new Error('Memory limit exceeded');
                }

                // Check for corrupted data
                const corruptionIndex = chunk.indexOf(corruptedByteSequence);
                if (corruptionIndex !== -1) {
                    console.warn('Corrupted data detected, skipping...');
                    continue; // Skip corrupted chunk and proceed with next
                }

                // Merge current buffer with new chunk
                const newBuffer = Buffer.concat([currentBuffer, chunk]);
                totalBytesProcessed += chunk.length;

                // Check if we need to adjust the buffer size dynamically
                currentBuffer = newBuffer;
            }
        } catch (error) {
            console.error('Error processing streams:', error.message);
        }

        return { mergedData: currentBuffer, totalBytesProcessed };
    }

    return processStreams();
}

// Usage example:
