    'background', 'margin', 'padding', 'border'
  ]);

  function fetchCommonAttributesFromAPI(apiUrl) {
    return fetch(apiUrl)
      .then(response => response.json())
      .catch(() => defaultCommonAttributes);
  }

  function getUniqueAttributes(rootElement, customCommonAttributes = []) {
    const commonAttributes = new Set([...defaultCommonAttributes, ...customCommonAttributes]);
    const uniqueAttributesMap = new Map();

    function traverse(element) {
      if (!element || element.nodeType !== Node.ELEMENT_NODE) return;

      for (let i = 0; i < element.attributes.length; i++) {
        const attrName = element.attributes[i].name;

        if (!commonAttributes.has(attrName)) {
          if (!uniqueAttributesMap.has(attrName)) {
            uniqueAttributesMap.set(attrName, new Set());
          }
          uniqueAttributesMap.get(attrName).add(element.tagName.toLowerCase());
        }
      }

      Array.from(element.children).forEach(traverse);
    }

    traverse(rootElement);

    return Array.from(uniqueAttributesMap.entries()).map(([attrName, tags]) => ({
      attribute: attrName,
      foundInTags: Array.from(tags)
    }));
  }

  function generateAttributeReport(rootElement = document.documentElement, options = {}) {
    const { apiUrl } = options;

    // Fetch and merge external common attributes if API URL is provided
    let customCommonAttributesPromise;
    if (apiUrl) {
      customCommonAttributesPromise = fetchCommonAttributesFromAPI(apiUrl)
        .then(commonAttrs => Array.from(commonAttrs));
    }

    const reportPromises = [
      () => getUniqueAttributes(rootElement, options.customCommonAttributes || [])
    ];

    if (customCommonAttributesPromise) {
      reportPromises.push(customCommonAttributesPromise);
    }

    return Promise.all(reportPromises).then(results => {
      let [reportData, externalCommonAttrs] = results;

      if (externalCommonAttrs) {
        reportData = getUniqueAttributes(rootElement, externalCommonAttrs);
      }

      console.log("Attribute Report:", JSON.stringify(reportData, null, 2));
      return reportData; // Return the final report
    }).catch(error => {
      console.error("Error generating attribute report:", error);
      throw new Error('Failed to generate attribute report');
    });
  }

  window.generateAttributeReport = generateAttributeReport;
})();
```

### Usage:

- Call `generateAttributeReport()` on any element or with specific options like a custom list of common attributes.
- Use the optional `apiUrl` option to fetch additional common attributes from an external API.

This implementation balances efficiency and flexibility, incorporating error handling for network operations and DOM traversal.']

