class ScriptLoader {
  constructor() {
    this.loadedScripts = new Map();
    this.loadingQueue = [];
    this.retryCounts = {};
    this.isPaused = false;
    this.cacheTimeout = 300000; // cache timeout in milliseconds (5 minutes)
    this.inactivityTimeout = 60000; // unload scripts after 1 minute of inactivity
    this.retryMaxCount = 3;
    this.loadLog = [];
    this.lastActivityTime = Date.now();
    this.contextIsolationMap = new Map();
  }

  async loadScripts(files) {
    for (const file of files) {
      if (!this.loadedScripts.has(file)) {
        await this.enqueueFileLoading(file);
      }
    }
  }

  enqueueFileLoading(file) {
    return new Promise((resolve, reject) => {
      const scriptLoader = this;
      function loadScript() {
        if (scriptLoader.isPaused) {
          setTimeout(loadScript, 100); // retry loading when not paused
          return;
        }

        const loaded = scriptLoader.loadedScripts.get(file);
        if (loaded) {
          resolve();
          return;
        }

        if (!scriptLoader.retryCounts[file]) {
          scriptLoader.retryCounts[file] = 0;
        }

        scriptLoader.retryCounts[file]++;

        const contextId = Math.random().toString(36).substring(7);
        const scriptElement = document.createElement('script');
        scriptElement.type = 'text/javascript';
        scriptLoader.contextIsolationMap.set(contextId, {});

        // Set the context for script execution
        scriptElement.setAttribute('context-id', contextId);

        function onError(event) {
          if (scriptLoader.retryCounts[file] <= scriptLoader.retryMaxCount) {
            const retryDelay = Math.pow(2, scriptLoader.retryCounts[file]) * 100;
            setTimeout(loadScript, retryDelay);
          } else {
            scriptLoader.log(`Failed to load: ${file} after ${scriptLoader.retryCounts[file]} retries`);
            reject(new Error(`Loading failed for ${file}`));
          }
        }

        function onLoad() {
          scriptLoader.loadedScripts.set(file, true);
          resolve();
          scriptLoader.cleanupCache(file);
          scriptLoader.log(`Successfully loaded: ${file}`);
        }

        // Add error and load handlers
        scriptElement.onerror = onError;
        scriptElement.onload = onLoad;

        if (file.startsWith('http')) { // External file
          scriptElement.src = file;
        } else {
          scriptElement.textContent = await fetch(file).then(res => res.text());
        }

        document.head.appendChild(scriptElement);
      }

      loadScript();
    });
  }

  log(message) {
    console.log(`[ScriptLoader] ${message}`);
    this.loadLog.push({ timestamp: Date.now(), message });

    // Maintain inactivity timeout reset
    if (Date.now() - this.lastActivityTime > this.inactivityTimeout) {
      this.cleanupCache();
      this.lastActivityTime = Date.now();
    }
  }

  cleanupCache(file = null) {
    const now = Date.now();

    if (file && this.loadedScripts.has(file)) {
      const cacheEntry = { timestamp: now };
      this.loadedScripts.set(file, cacheEntry);
    } else {
      for (const [key, value] of this.loadedScripts.entries()) {
        if (now - value.timestamp > this.cacheTimeout) {
          this.loadedScripts.delete(key);
          document.head.querySelectorAll('script').forEach(script => {
            if (script.getAttribute('context-id') === key) {
              script.remove();
            }
          });
        } else {
          // Update timestamp for kept scripts
          this.loadedScripts.set(key, { timestamp: now });
        }
      }
    }
  }

  pauseLoading() {
    this.isPaused = true;
  }

  resumeLoading() {
    this.isPaused = false;

    while (this.loadingQueue.length) {
      const file = this.loadingQueue.shift();
      this.enqueueFileLoading(file);
    }
  }

  unloadUnusedScripts() {
    const now = Date.now();

    for (const [key, value] of this.loadedScripts.entries()) {
      if (!value || now - value.timestamp > this.cacheTimeout + this.inactivityTimeout) {
        this.loadedScripts.delete(key);
        document.head.querySelectorAll('script').forEach(script => {
          if (script.getAttribute('context-id') === key) {
            script.remove();
          }
        });
      }
    }
  }

  handleSystemDependencies() {
    // Placeholder for handling potential system dependencies
    console.log("Checking system dependencies...");
  }

  evaluatePerformanceImpact() {
    const usedMemory = process.memoryUsage().heapUsed / 1024 / 1024;
    const performanceMetrics = {
      memory: `${usedMemory.toFixed(2)} MB`,
      loadedScriptsCount: this.loadedScripts.size,
      retryCounts: this.retryCounts
    };

    console.log(`Performance Metrics: ${JSON.stringify(performanceMetrics)}`);
  }
}

// Usage example:
(async () => {
  const scriptLoader = new ScriptLoader();
  await scriptLoader.loadScripts([
    'localScript.js', 
    'https://example.com/externalScript.js'
  ]);

  // Example pause and resume usage
  scriptLoader.pauseLoading();
  setTimeout(() => scriptLoader.resumeLoading(), 2000);

  // Unload scripts that are not used after a period of inactivity
  setInterval(() => scriptLoader.unloadUnusedScripts(), scriptLoader.inactivityTimeout);
})();
