ProcessResult processAndModify(const char *filename) {
    ProcessResult result = {0, ""};
    int len = strlen(filename);
    char temp[256];
    strcpy(temp, filename);

    // Union-Find setup
    int max_chars = 256;
    int parent[max_chars];
    for (int i = 0; i < max_chars; ++i) {
        parent[i] = i;
    }

    int disjoint_count = 0;

    // Find unique segments using Union-Find
    for (int i = 0; temp[i]; ++i) {
        if (temp[i] == '.' || temp[i] == '_') {
            continue;
        }
        start = clock();
        unionSet(parent, i, i + 1);
        end = clock();
        printf("Processing segment %c took %f milliseconds\n", temp[i], ((double)(end - start)) / CLOCKS_PER_SEC * 1000);

        if (find(parent, i) != find(parent, i + 1)) {
            disjoint_count++;
        }
    }

    // Modify filename extension
    const char *allowed_extensions[] = {"txt", "md", "log"};
    int allowed_count = sizeof(allowed_extensions) / sizeof(allowed_extensions[0]);

    char original_extension[16];
    char *dot_pos = strrchr(temp, '.');
    if (dot_pos && dot_pos != temp) {
        strcpy(original_extension, dot_pos + 1);
    } else {
        strcat(temp, ".txt");
        strcpy(original_extension, "txt");
    }

    int num_digits = len % 10 + 1; // Number of digits derived from length
    char new_extension[16];
    sprintf(new_extension, "%d%s", num_digits, original_extension);

    if (isValidExtension(new_extension, allowed_extensions, allowed_count)) {
        strcpy(dot_pos ? dot_pos : temp + strlen(temp), new_extension);
    } else {
        strcat(temp, ".txt");
    }

    strncpy(result.modified_filename, temp, sizeof(result.modified_filename) - 1);
    result.modified_filename[sizeof(result.modified_filename) - 1] = '\0';

    result.count = disjoint_count;
    return result;
