import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ServiceLifecycleManager {

    private static final Logger logger = LoggerFactory.getLogger(ServiceLifecycleManager.class);
    private boolean isRunning = false;
    private ExecutorService executorService;
    private HealthCheck healthCheck;
    private MessagingSystem messagingSystem;

    public ServiceLifecycleManager(HealthCheck healthCheck, MessagingSystem messagingSystem) {
        this.healthCheck = healthCheck;
        this.messagingSystem = messagingSystem;
        this.executorService = Executors.newCachedThreadPool();
    }

    public void startService() {
        if (isRunning || !healthCheck.isReady()) {
            logger.warn("Service cannot be started. Health check failed or service is already running.");
            return;
        }

        isRunning = true;
        logger.info("Starting service...");

        executorService.submit(this::monitorHealth);
        messagingSystem.connect();
    }

    public void stopService() {
        if (!isRunning) {
            logger.warn("Service is not running. Cannot be stopped.");
            return;
        }

        logger.info("Stopping service...");
        executorService.shutdownNow();
        messagingSystem.disconnect();

        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            executorService.shutdownNow();
        }

        isRunning = false;
    }

    private void monitorHealth() {
        while (isRunning) {
            if (!healthCheck.isHealthy()) {
                logger.warn("Service health check failed. Attempting to restart...");

                stopService();
                startService();
            }

            try {
                TimeUnit.SECONDS.sleep(5);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) {
        HealthCheck healthCheck = new SimpleHealthCheck(); // Implement this class based on specific criteria
        MessagingSystem messagingSystem = new KafkaMessagingSystem(); // Choose between Kafka or RabbitMQ

        ServiceLifecycleManager manager = new ServiceLifecycleManager(healthCheck, messagingSystem);

        for (int i = 0; i < 10000; i++) {
            if (i % 2 == 0) {
                manager.startService();
            } else {
                manager.stopService();
            }

            try {
                TimeUnit.MILLISECONDS.sleep(3600 / 10000); // Distribute the cycles over an hour
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

