function setEnvVariables($configUrl) {
    $retryCount = 0;

    while ($retryCount < MAX_RETRIES) {
        try {
            $response = file_get_contents($configUrl);
            if ($response !== false) {
                parse_str($response, $envVars);
                foreach ($envVars as $key => $value) {
                    putenv("$key=$value");
                    $_ENV[$key] = $value;
                    $_SERVER[$key] = $value;
                }
                return true;
            }
        } catch (Exception $e) {
            $retryCount++;
            sleep(2); // Exponential backoff could be implemented here
