// Configuration for the HTTP client
#[derive(Clone)]
pub struct HttpClientConfig {
    pub timeout: Option<Duration>,
    pub verify_tls: bool,
}

impl Default for HttpClientConfig {
    fn default() -> Self {
        HttpClientConfig {
            timeout: Some(Duration::from_secs(30)),
            verify_tls: true,
        }
    }
}

// HTTP client library
pub struct HttpClient {
    inner: Client,
    config: Arc<Mutex<HttpClientConfig>>,
}

impl HttpClient {
    pub fn new(config: HttpClientConfig) -> Self {
        let tls_client_config = if config.verify_tls {
            reqwest::ClientBuilder::new()
        } else {
            reqwest::ClientBuilder::builder().danger_accept_invalid_certs(true)
        };

        let client = Client::builder()
            .timeout(config.timeout.clone())
            .build(tls_client_config)
            .expect("Failed to build HTTP client");

        HttpClient {
            inner: client,
            config: Arc::new(Mutex::new(config)),
        }
    }

    pub async fn get(&self, url: &str, headers: Option<reqwest::header::HeaderMap>) -> Result<Response, ReqwestError> {
        let mut request = self.inner.get(url);

        if let Some(headers) = headers {
            request = request.headers(headers);
        }

        request.send().await
    }

    pub async fn post(&self, url: &str, body: Option<&[u8]>, headers: Option<reqwest::header::HeaderMap>) -> Result<Response, ReqwestError> {
        let mut request = self.inner.post(url);

        if let Some(headers) = headers {
            request = request.headers(headers);
        }

        if let Some(body) = body {
            request = request.body(reqwest::Body::from(*body));
        }

        request.send().await
    }
}

// Middleware for retry and rate limiting

struct RetryPolicy;

impl tower_retry::RetryPolicy for RetryPolicy {
    type Error = ReqwestError;
    type Future = Pin<Box<dyn std::future::Future<Output = Result<(), Self::Error>> + Send>>;
    type Service = HttpClient;

    fn retry(&self, _error: Self::Error, _num_retries: u32) -> Option<Self::Future> {
        let delay = Duration::from_millis(100 * 2_u32.pow(_num_retries as u32));
        Some(Box::pin(async move {
            time::sleep(delay).await;
            Ok(())
        }))
    }
}

// Adapter for integrating HttpClient into tower's ecosystem

struct HttpClientAdapter(Client);

impl Service<http::Request<Vec<u8>>> for HttpClientAdapter {
    type Response = Result<Response, ReqwestError>;
    type Error = ReqwestError;
    type Future = Pin<Box<dyn std::future::Future<Output = Self::Response> + Send>>;

    fn poll_ready(&mut self, _cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
        std::task::Poll::Ready(Ok(()))
    }

    fn call(&mut self, req: http::Request<Vec<u8>>) -> Self::Future {
        let client = self.0.clone();
        Box::pin(async move {
            let mut request_builder = client.request(req.method().clone(), req.uri().clone());

            if let Some(headers) = req.headers() {
                for (name, value) in headers {
                    request_builder = request_builder.header(name, value.to_str().unwrap());
                }
            }

            match req.body() {
                None => request_builder.send().await,
                Some(body) => request_builder
                    .body(reqwest::Body::from(body))
                    .send()
                    .await,
            }
        })
    }
}

// Function to create a configured service with middleware

pub fn build_http_client_service(client: HttpClient, config: HttpClientConfig) -> impl tower::Service<http::Request<Vec<u8>>, Response = Result<Response, ReqwestError>, Error = ReqwestError> + Clone {
    let adapter = HttpClientAdapter(client.inner.clone());
    let retry_layer = RetryLayer::new(RetryPolicy);
    let rate_limit_layer = RateLimitLayer::layer(LeakyBucketLayer::new(10, Duration::from_secs(1)));

    ServiceBuilder::new()
        .layer(retry_layer)
        .layer(rate_limit_layer)
        .service_fn(move |req| {
            let client = adapter.clone();
            async move { Ok(client.call(req).await?) }
        })
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = HttpClientConfig::default();
    let client = HttpClient::new(config);

    // Example GET request
    let response = client.get("https://httpbin.org/get", None).await?;
    println!("GET Response: {:?}", response.status());

    // Example POST request
    let body = b"Hello, world!";
    let headers = reqwest::header::HeaderMap::new();
    let post_response = client.post("https://httpbin.org/post", Some(body), Some(headers)).await?;
    println!("POST Response: {:?}", post_response.status());

    Ok(())
}
```

**Notes:**

1. **Concurrency and Thread Safety:** Using `Arc` and `Mutex` ensures that the configuration can be safely shared across threads.
2. **Retry Logic:** Implemented using `tower_retry`, with exponential backoff strategy for transient errors.
3. **Rate Limiting:** Managed by `LeakyBucketLayer`.
4. **Configuration:** Can handle custom timeouts, certificate validation settings, etc.
5. **Middleware Integration:** Uses `tower` for composing retry and rate limiting middleware.

This design provides a modular and extensible HTTP client library in Rust, leveraging async capabilities and third-party crates to enhance functionality and efficiency.']

