import requests
from cachetools import TTLCache, cached
from datetime import timedelta
import threading
import time

class UserProfileRetriever:
    def __init__(self, service_url, group_id, cache_ttl=300, max_retries=5):
        self.service_url = service_url
        self.group_id = group_id
        self.cache = TTLCache(maxsize=1000, ttl=cache_ttl)
        self.max_retries = max_retries
        self.lock = threading.Lock()

    def _get_user_profiles(self):
        headers = {'User-Agent': 'UserProfileRetriever/1.0'}
        params = {'group_id': self.group_id}

        for attempt in range(self.max_retries):
            try:
                response = requests.get(f"{self.service_url}/user-profiles", headers=headers, params=params)
                response.raise_for_status()

                data = response.json()
                if 'users' not in data:
                    raise ValueError("Invalid response structure")

                return [
                    {
                        'email': user['email'],
                        'last_login': user['last_login_timestamp'],
                        'creation_date': user['profile_creation_date']
                    } for user in data['users']
                ]
            except (requests.HTTPError, requests.ConnectionError) as e:
                if response.status_code >= 500:  # Transient server errors
                    backoff_time = min(2 ** attempt, 32)
                    time.sleep(backoff_time)
                else:
                    raise e

    @cached(cache=lambda self: self.cache, lock=lambda self: self.lock)
    def get_user_profiles(self):
        with self.lock:
            return self._get_user_profiles()

# Integration into an existing application framework
def integrate_with_application(user_retriever):
    try:
        profiles = user_retriever.get_user_profiles()

        # Assuming there's a logging system in place
        log.info(f"Fetched {len(profiles)} user profiles")

        # Further processing of profiles as needed by the application

    except Exception as e:
        log.error("Failed to fetch user profiles", exc_info=True)

# Usage example
service_url = "https://api.example.com"
group_id = 123

user_retriever = UserProfileRetriever(service_url, group_id)
integrate_with_application(user_retriever)
