<?php

class SessionTokenService
{
    private $pdo;
    private $tokenTTL; // Token Time To Live in seconds
    private $authAPIUrl;

    public function __construct(PDO $pdo, int $tokenTTL = 3600, string $authAPIUrl)
    {
        $this->pdo = $pdo;
        $this->tokenTTL = $tokenTTL;
        $this->authAPIUrl = $authAPIUrl;
    }

    public function generateToken(string $username, string $ip): ?string
    {
        // Verify user with external API
        if (!$this->verifyUser($username)) {
            return null;
        }

        do {
            $token = bin2hex(random_bytes(16));  // Generate a unique token
        } while ($this->isTokenExists($token));

        // Save the new token to the database with current timestamp and IP
        $stmt = $this->pdo->prepare("INSERT INTO session_tokens (token, username, ip_address, created_at) VALUES (?, ?, ?, NOW())");
        $stmt->execute([$token, $username, $ip]);

        // Log token generation attempt
        $this->logTokenGeneration($username, $ip);

        return $token;
    }

    private function verifyUser(string $username): bool
    {
        // Placeholder for calling external authentication API
        $response = file_get_contents("{$this->authAPIUrl}?user={$username}");

        if ($response === false) {
            // Handle network errors or retry logic here
            return false;
        }

        $data = json_decode($response, true);
        return isset($data['verified']) && $data['verified'];
    }

    private function isTokenExists(string $token): bool
    {
        $stmt = $this->pdo->prepare("SELECT COUNT(*) FROM session_tokens WHERE token = ?");
        $stmt->execute([$token]);
        return (int)$stmt->fetchColumn() > 0;
    }

    public function invalidateOldTokens(): void
    {
        $expirationTime = time() - $this->tokenTTL;

        // Invalidate old tokens
        $stmt = $this->pdo->prepare("DELETE FROM session_tokens WHERE created_at < FROM_UNIXTIME(?)");
        $stmt->execute([$expirationTime]);
    }

    private function logTokenGeneration(string $username, string $ip): void
    {
        $stmt = $this->pdo->prepare("INSERT INTO token_logs (username, ip_address, action, timestamp) VALUES (?, ?, 'GENERATE', NOW())");
        $stmt->execute([$username, $ip]);
    }

    public function handleRequest(): void
    {
        // Example endpoint to invalidate old tokens via an API call
        if ($_SERVER['REQUEST_METHOD'] === 'POST' && $_GET['action'] === 'invalidate') {
            $this->invalidateOldTokens();
            echo json_encode(['status' => 'success']);
            exit;
        }
    }
}

// Usage example with database connection setup
try {
    $pdo = new PDO('mysql:host=localhost;dbname=sessiondb', 'user', 'password');
    $tokenService = new SessionTokenService($pdo, 3600, 'https://auth.api/verify');

    // To generate a token:
    $username = $_POST['username'] ?? '';
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $token = $tokenService->generateToken($username, $ipAddress);

    if ($token) {
        echo json_encode(['status' => 'success', 'token' => $token]);
    } else {
        http_response_code(401);
        echo json_encode(['status' => 'error', 'message' => 'User verification failed']);
    }

    // Example to handle requests
    $tokenService->handleRequest();

} catch (PDOException $e) {
    echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
}
