const fs = require('fs').promises;
const path = require('path');
const { readFileSync } = require('crypto');
const tls = require('tls');

// Whitelist of allowed paths for security
const WHITELISTED_PATHS = ['/valid/path1', '/valid/path2'];

async function generateTLSChain(oauthRequest) {
    const { issuerDetails, validityPeriod, keyLength, directoryPath } = oauthRequest;

    // Validate the requested path against whitelist
    if (!WHITELISTED_PATHS.includes(directoryPath)) {
        throw new Error('Unauthorized access: Path is not whitelisted.');
    }

    try {
        // Fetch the certificate and private key asynchronously
        const [certData, privateKeyData] = await Promise.all([
            fs.readFile(path.join(directoryPath, 'certificate.pem')),
            fs.readFile(path.join(directoryPath, 'privateKey.pem'))
        ]);

        const certificateBuffer = Buffer.from(certData);
        const privateKeyBuffer = Buffer.from(privateKeyData);

        // Check if the private key matches the certificate
        if (!tls.checkPrivateKey(certificateBuffer, privateKeyBuffer)) {
            throw new Error('The provided private key does not match the certificate.');
        }

        // Validate validity period (assuming validityPeriod is an object with startDate and endDate)
        const now = Date.now();
        if (now < validityPeriod.startDate || now > validityPeriod.endDate) {
            throw new Error('Certificate is expired or not yet valid.');
        }

        // Concatenate certificate and private key in PEM format
        const concatenatedChain = `${certData.toString()}\n${privateKeyData.toString()}`;

        // Optionally, use an in-memory cache for frequently accessed certificates
        // This can be implemented using a simple object or more advanced caching libraries

        return concatenatedChain;
    } catch (error) {
        console.error('Error generating TLS chain:', error);
        throw new Error('Failed to generate TLS certificate chain.');
    }
}

module.exports = { generateTLSChain };
