<?php

function authenticateAndStoreToken($clientId, $clientSecret, $redirectUri) {
    session_start();

    if (isset($_GET['code'])) {
        $code = $_GET['code'];
        $url = 'https://authorization-server.com/token';

        $postData = [
            'grant_type' => 'authorization_code',
            'code' => $code,
            'redirect_uri' => $redirectUri,
            'client_id' => $clientId,
            'client_secret' => $clientSecret
        ];

        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($postData));

        for ($attempt = 0; $attempt < 3; $attempt++) {
            $response = curl_exec($ch);

            if ($response !== false) {
                break;
            }

            // Exponential backoff
            sleep(pow(2, $attempt));
        }

        if ($response === false) {
            error_log('CURL Error: ' . curl_error($ch), 0);
            die('Authentication failed. Please try again later.');
        }

        curl_close($ch);

        $data = json_decode($response, true);

        if (isset($data['access_token'])) {
            $_SESSION['access_token'] = $data['access_token'];
            return true;
        } else {
            error_log('Token request failed: ' . print_r($data, true), 0);
            die('Authentication failed. Please check your credentials.');
        }
    }

    // Redirect to authorization URL if no code present
    $authUrl = "https://authorization-server.com/auth?response_type=code&client_id={$clientId}&redirect_uri=" . urlencode($redirectUri) . "&scope=read";
    header("Location: $authUrl");
    exit;
}

