```javascript
async function collectDataFromStream(streamUrl, maxChunks = 10) {
    let dataArray = [];
    let isPaused = false;

    const fetchDataChunk = async (chunkSize, offset) => {
        try {
            if (isPaused) return;

            const response = await fetch(`${streamUrl}?offset=${offset}&limit=${chunkSize}`);

            if (!response.ok) throw new Error('Network response was not ok');

            const data = await response.json();
            dataArray.push(...data);

            if (data.length === chunkSize) {
                offset += chunkSize;
                if (dataArray.length < maxChunks * chunkSize) {
                    await fetchDataChunk(chunkSize, offset);
                }
            }

        } catch (error) {
            console.error('Fetch Error:', error.message);
            setTimeout(() => fetchDataChunk(chunkSize, offset), 1000); // Retry after a delay
        }
    };

    const start = () => fetchDataChunk(1000, 0);

    return {
        data: () => dataArray,
        pause: () => { isPaused = true; },
        resume: () => {
            if (isPaused) {
                isPaused = false;
                start();
            }
        },
        reset: () => {
            dataArray = [];
            fetchDataChunk(1000, 0);
        },
    };
}
