```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/nameser.h>
#include <resolv.h>

#define MAX_DNS_REQUESTS_PER_SECOND 5

// Function to resolve a hostname to an IP address.
int resolveHostname(const char *hostname, u_char ip_array[16]) {
    static int request_count = 0;
    static time_t last_request_time = 0;

    // Rate limiting for DNS requests
    time_t current_time = time(NULL);
    if (current_time == last_request_time) {
        if (++request_count > MAX_DNS_REQUESTS_PER_SECOND) {
            return -1; // Too many requests in a second
        }
    } else {
        request_count = 0;
        last_request_time = current_time;
    }

    struct hostent *he;
    int result = gethostbyname_r(hostname, &he, ip_array, sizeof(ip_array), NULL, 0, NULL);

    if (result != 0) {
        return -1; // DNS resolution failed
    }

    if (!he || !he->h_addr_list[0]) {
        return -2; // No addresses found for hostname
    }

    // Copy the first resolved IP address into the provided array
    memcpy(ip_array, he->h_addr_list[0], he->h_length);

    return 0; // Success
}
```

