```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int *states;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} StateList;

typedef struct {
    int num_states;
    // Add more FSA-related fields as necessary
} FSA;

// Function prototypes for logging and hash calculation (to be implemented externally)
void log_operation(const char *operation, const char *details);
unsigned long calculate_hash(int *states, size_t count);

StateList* create_state_list(int *state_array, int num_states, FSA *fsa, int last_state) {
    if (!state_array || !fsa) return NULL;

    StateList *state_list = (StateList *)malloc(sizeof(StateList));
    if (!state_list) {
        log_operation("ERROR", "Memory allocation failed for state list");
        return NULL;
    }

    state_list->capacity = num_states;
    state_list->count = 0;
    state_list->states = (int *)aligned_alloc(64, num_states * sizeof(int)); // Ensure cache-friendly alignment
    if (!state_list->states) {
        log_operation("ERROR", "Memory allocation failed for states");
        free(state_list);
        return NULL;
    }

    pthread_mutex_init(&state_list->lock, NULL);

    unsigned long hash = 0;

    // Add the last state to the list
    pthread_mutex_lock(&state_list->lock);
    if (last_state >= 0 && last_state < num_states) {
        state_list->states[state_list->count++] = state_array[last_state];
        hash = calculate_hash(state_list->states, state_list->count);
        log_operation("CREATE", "Added last state to the list");
    }
    pthread_mutex_unlock(&state_list->lock);

    // Initialize with states from FSA if necessary
    for (int i = 0; i < fsa->num_states; ++i) {
        pthread_mutex_lock(&state_list->lock);
        if (state_array[i] != -1 && state_list->count < num_states) { // Assuming -1 indicates unused state
            state_list->states[state_list->count++] = state_array[i];
            hash = calculate_hash(state_list->states, state_list->count);
            log_operation("CREATE", "Added state from FSA");
        }
        pthread_mutex_unlock(&state_list->lock);
    }

    // Store or use the hash as needed
    printf("Initial Hash: %lu\n", hash);

    return state_list;
}

void free_state_list(StateList *state_list) {
    if (state_list) {
        pthread_mutex_lock(&state_list->lock);
        if (state_list->states) {
            free(state_list->states);
            log_operation("DELETE", "Freed state memory");
        }
        pthread_mutex_unlock(&state_list->lock);

        pthread_mutex_destroy(&state_list->lock);
        free(state_list);
        log_operation("DELETE", "Freed state list structure");
    }
}

int main() {
    // Example usage
    int states[] = {0, 1, 2, -1}; // Assuming -1 indicates unused or invalid state
    FSA fsa = {.num_states = 4};
    StateList *state_list = create_state_list(states, 4, &fsa, 3);

    if (state_list) {
        // Perform operations on the state list...
        free_state_list(state_list);
    }

    return 0;
}
```

### Key Considerations:
- **Memory Management**: Uses `aligned_alloc` for cache-friendly memory alignment.
- **Thread Safety**: Utilizes a mutex (`pthread_mutex_t`) to ensure thread-safe access and modifications.
- **Logging**: Logs operations using an external function `log_operation`.
- **Hash Calculation**: Maintains a consistent hash value updated upon changes, calculated via `calculate_hash`.

### Notes:
- The logging and hash calculation functions are assumed to be implemented externally.
- This implementation assumes that `-1` in the state array indicates an unused or invalid state. Adjust as necessary based on actual FSA requirements.
- The mutex ensures thread safety but may introduce contention; consider using more sophisticated synchronization if needed for high-performance scenarios.']

