class OctreeNode {
public:
    bool isLeaf;
    std::unique_ptr<OctreeNode> children[8];
    std::vector<int> data; // Simplified for demonstration
    int dataSize;

    OctreeNode() : isLeaf(true), dataSize(0) {}
};

class Octree {
private:
    std::shared_ptr<OctreeNode> root;
    int featureSize, numLeafNodes, dataCapacity, cacheSize;
    std::mutex treeMutex;
    std::unordered_map<int, std::shared_ptr<OctreeNode>> cache; // Simple cache for demonstration

    void insertRecursive(std::shared_ptr<OctreeNode>& node, const std::vector<int>& point) {
        if (node->isLeaf && node->data.size() < dataCapacity) {
            node->data.push_back(point[0]); // Simplified
            node->dataSize++;
        } else if (!node->isLeaf) {
            int index = 0; // Determine which child to traverse based on point
            for (int i = 0; i < featureSize; ++i)
                index |= ((point[i] > 0.5) << i);

            if (!node->children[index])
                node->children[index] = std::make_shared<OctreeNode>();

            insertRecursive(node->children[index], point);
        } else {
            // Split node and redistribute data
            node->isLeaf = false;
            for (int i = 0; i < dataCapacity && !node->data.empty(); ++i) {
                int index = 0; // Determine which child to place the data in
                for (int j = 0; j < featureSize; ++j)
                    index |= ((node->data[i] > 0.5) << j);

                if (!node->children[index])
                    node->children[index] = std::make_shared<OctreeNode>();

                node->children[index]->data.push_back(node->data[i]);
                node->children[index]->dataSize++;
            }

            node->data.clear();
            insertRecursive(node, point); // Retry insertion
        }
    }

    void deleteRecursive(std::shared_ptr<OctreeNode>& node, const std::vector<int>& point) {
        if (node->isLeaf) {
            for (auto it = node->data.begin(); it != node->data.end(); ++it)
                if (*it == point[0]) { // Simplified
                    node->data.erase(it);
                    node->dataSize--;
                    break;
                }
        } else {
            int index = 0; // Determine which child to traverse based on point
            for (int i = 0; i < featureSize; ++i)
                index |= ((point[i] > 0.5) << i);

            if (node->children[index])
                deleteRecursive(node->children[index], point);
        }
    }

public:
    Octree(int fs, int ln, int dc, int cs)
        : featureSize(fs), numLeafNodes(ln), dataCapacity(dc), cacheSize(cs) {
        root = std::make_shared<OctreeNode>();
    }

    void insert(const std::vector<int>& point) {
        std::lock_guard<std::mutex> lock(treeMutex);
        insertRecursive(root, point);
    }

    void remove(const std::vector<int>& point) {
        std::lock_guard<std::mutex> lock(treeMutex);
        deleteRecursive(root, point);
    }

    // Cache management and memory monitoring functions can be added here

