        // Placeholder for memory usage reporting
        std::cout << "Reporting memory usage..." << std::endl;
    }
};

int main() {
    Octree octree(3, 10, 5, 100);
    octree.insert({1, 0, 0});
    octree.remove({1, 0, 0});
    octree.reportMemoryUsage();

    return 0;
}
