using UnityEngine;

public class RandomValueGenerator : IComparable<RandomValueGenerator>
{
    private float _minFloat;
    private float _maxFloat;
    private int _minInt;
    private int _maxInt;
    private readonly object _lock = new object();
    private static readonly Logger _logger = new Logger();

    public RandomValueGenerator(float min, float max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max");
        _minFloat = min;
        _maxFloat = max;
        _minInt = Mathf.FloorToInt(min);
        _maxInt = Mathf.CeilToInt(max);
    }

    public void SetSeed(int seed)
    {
        Random.InitState(seed);
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            var value = UnityEngine.Random.Range(_minFloat, _maxFloat);
            ValidateRange(value, _minFloat, _maxFloat);
            _logger.Log($"Generated Float: {value}");
            return value;
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lock)
        {
            var value = UnityEngine.Random.Range(_minInt, _maxInt + 1);
            ValidateRange(value, _minInt, _maxInt);
            _logger.Log($"Generated Int: {value}");
            return value;
        }
    }

    public Vector3 GenerateRandomVector3()
    {
        lock (_lock)
        {
            var x = UnityEngine.Random.Range(_minFloat, _maxFloat);
            var y = UnityEngine.Random.Range(_minFloat, _maxFloat);
            var z = UnityEngine.Random.Range(_minFloat, _maxFloat);
            ValidateRange(x, _minFloat, _maxFloat);
            ValidateRange(y, _minFloat, _maxFloat);
            ValidateRange(z, _minFloat, _maxFloat);
            var vector3 = new Vector3(x, y, z);
            _logger.Log($"Generated Vector3: {vector3}");
            return vector3;
        }
    }

    public Vector2 GenerateRandomVector2()
    {
        lock (_lock)
        {
            var x = UnityEngine.Random.Range(_minFloat, _maxFloat);
            var y = UnityEngine.Random.Range(_minFloat, _maxFloat);
            ValidateRange(x, _minFloat, _maxFloat);
            ValidateRange(y, _minFloat, _maxFloat);
            var vector2 = new Vector2(x, y);
            _logger.Log($"Generated Vector2: {vector2}");
            return vector2;
        }
    }

    public Color GenerateRandomColor()
    {
        lock (_lock)
        {
            var r = UnityEngine.Random.Range(_minFloat, _maxFloat);
            var g = UnityEngine.Random.Range(_minFloat, _maxFloat);
            var b = UnityEngine.Random.Range(_minFloat, _maxFloat);
            ValidateRange(r, _minFloat, _maxFloat);
            ValidateRange(g, _minFloat, _maxFloat);
            ValidateRange(b, _minFloat, _maxFloat);
            var color = new Color(r, g, b);
            _logger.Log($"Generated Color: {color}");
            return color;
        }
    }

    private void ValidateRange(float value, float min, float max)
    {
        if (value < min || value > max)
        {
            throw new InvalidOperationException($"Value {value} is out of range [{min}, {max}]");
        }
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: Float Range = [{_minFloat}, {_maxFloat}], Int Range = [{_minInt}, {_maxInt}]";
    }

    public int CompareTo(RandomValueGenerator other)
    {
        if (other == null) return 1;
        var result = _minFloat.CompareTo(other._minFloat);
        return result != 0 ? result : _maxFloat.CompareTo(other._maxFloat);
    }
}

public class Logger
{
    private readonly object _lock = new object();

    public void Log(string message)
    {
        lock (_lock)
        {
            Debug.Log(message); // Assuming Unity's Debug is used for logging
        }
    }
}
