    char *description;
    time_t timestamp;
} ResourceItem;

// Structure for the resource bundle
typedef struct {
    size_t count;
    ResourceItem **items;
    pthread_mutex_t lock;  // Mutex for thread safety
} ResourceBundle;

// Function prototypes
ResourceBundle* load_resource_bundle(const char *config_path, const char *file_paths[], int file_count);
void free_resource_bundle(ResourceBundle *bundle);
int add_item_to_bundle(ResourceBundle *bundle, const char *key, const char *value, const char *description, time_t timestamp);

// Implementation of the resource bundle loader
ResourceBundle* load_resource_bundle(const char *config_path, const char *file_paths[], int file_count) {
    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    pthread_mutex_init(&bundle->lock, NULL);
    bundle->count = 0;
    bundle->items = NULL;

    // Load configuration and parse files
    for (int i = 0; i < file_count; ++i) {
        const char *file_path = file_paths[i];

