            free_resource_bundle(bundle);
            return NULL;
        }

        pthread_mutex_unlock(&bundle->lock);
    }

    return bundle;
}

// Function to add an item to the resource bundle
int add_item_to_bundle(ResourceBundle *bundle, const char *key, const char *value, const char *description, time_t timestamp) {
    ResourceItem *item = (ResourceItem *)malloc(sizeof(ResourceItem));
    if (!item) return ERROR_MEMORY_ALLOCATION;

    item->key = strdup(key);
    item->value = strdup(value);
    item->description = description ? strdup(description) : NULL;
    item->timestamp = timestamp;

    // Resize the items array
    ResourceItem **new_items = (ResourceItem **)realloc(bundle->items, (bundle->count + 1) * sizeof(ResourceItem *));
    if (!new_items) {
        free(item->key);
        free(item->value);
        free(item->description);
        free(item);
        return ERROR_MEMORY_ALLOCATION;
    }

    bundle->items = new_items;
    bundle->items[bundle->count++] = item;

    // Handle duplicate keys (simple overwrite strategy)
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->items[i]->key, key) == 0) {
            free(bundle->items[i]->value);
            free(bundle->items[i]->description);

            bundle->items[i]->value = item->value;
            bundle->items[i]->description = item->description;
            free(item->key);
            free(item->value);
            free(item->description);
            free(item);
            return SUCCESS;
        }
    }

    return SUCCESS;
}

// Function to clean up the resource bundle
void free_resource_bundle(ResourceBundle *bundle) {
    if (!bundle) return;

    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]->description);
        free(bundle->items[i]);
    }

    free(bundle->items);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

// Example usage
int main() {
    const char *file_paths[] = {"resource1.json", "resource2.xml"};
    ResourceBundle *bundle = load_resource_bundle("config.cfg", file_paths, 2);

    if (bundle) {
        printf("Loaded %zu items successfully.\n", bundle->count);
        free_resource_bundle(bundle);
    } else {
        fprintf(stderr, "Failed to load resource bundle.\n");
    }

    return 0;
}
```

This code provides a basic framework for managing a flexible resource management system in C. It includes structures for holding resources and bundles, functions for loading resources, adding items with conflict resolution, and cleaning up resources. Thread safety is ensured using mutex locks, and error handling is implemented through return codes. The design allows for future extensions by modifying the parsing logic based on configuration files.']

