#define DEFAULT_BUFFER_SIZE 256

static pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

int fetch_default_buffer_size() {
    // Simulate fetching from external configuration service
    return DEFAULT_BUFFER_SIZE;
}

void log_error(const char* message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    fprintf(stderr, "Error: %s\n", message);
    pthread_mutex_unlock(&log_lock);
}

char* modify_file_path(const char* file_path, size_t max_buffer_size, int integration_mode, int version_number) {
    if (file_path == NULL) {
        log_error("File path is null");
        return NULL;
    }

    if (max_buffer_size == 0) {
        pthread_mutex_lock(&config_lock);
        max_buffer_size = fetch_default_buffer_size();
        pthread_mutex_unlock(&config_lock);
    }

    size_t path_length = strlen(file_path);
    size_t version_str_length = snprintf(NULL, 0, "_v%d", version_number);

    if (integration_mode) {
        if (path_length + version_str_length >= max_buffer_size) {
            log_error("Buffer too small for integration mode");
            return NULL;
        }
        path_length += version_str_length; // Include space for null terminator
    }

    char* buffer = malloc(max_buffer_size);
    if (!buffer) {
        log_error("Memory allocation failed");
        return NULL;
    }

    strncpy(buffer, file_path, max_buffer_size - 1);

    if (integration_mode && path_length + version_str_length < max_buffer_size) {
        snprintf(buffer + path_length, max_buffer_size - path_length, "_v%d", version_number);
    } else if (path_length >= max_buffer_size) {
        // Truncate path to fit within buffer
        strncpy(buffer, file_path, max_buffer_size - 1);
        buffer[max_buffer_size - 1] = '\0';
    }

    return buffer;
}

// Unit Tests

#include <assert.h>

void test_modify_file_path() {
    char* result;

    // Test with null pointer
    assert(modify_file_path(NULL, 100, 0, 1) == NULL);

    // Test default buffer size
    result = modify_file_path("/path/to/file", 0, 0, 1);
    assert(result != NULL && strcmp(result, "/path/to/file") == 0);
    free(result);

    // Test integration mode with version number
    result = modify_file_path("/path/to/file", 50, 1, 2);
    assert(result != NULL && strcmp(result, "/path/to/file_v2") == 0);
    free(result);

    // Test buffer size truncation
    result = modify_file_path("/this/is/a/very/long/path/name.txt", 20, 0, 1);
    assert(result != NULL && strcmp(result, "/this/is/a/ve") == 0);
    free(result);

    // Test integration mode with insufficient buffer size
    result = modify_file_path("/path/to/file", 10, 1, 2);
    assert(result == NULL);

    printf("All tests passed.\n");
}

int main() {
    test_modify_file_path();
    return 0;
}
