```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Assuming we have some existing libraries for handling TIFF and PNG files.
#include "tiff_lib.h"
#include "png_lib.h"

#define MAX_CACHE_SIZE 1024

typedef struct {
    int bits_per_sample;
    int extra_samples_count;
    char* extra_samples_info;
} ImageMetadata;

typedef struct {
    void* themeBitmap; // Pointer to the theme bitmap
    char defaultThemeDir[MAX_PATH];
} ThemeCache;

// Function prototypes
int checkAndSetDefaultThemeDirectory(ThemeCache *cache, const char *defaultDir);
ImageMetadata extractTiffMetadata(const char *filePath);
ImageMetadata extractPngMetadata(const char *filePath);
void cacheImageToThemeCache(const char *imagePath, ThemeCache *cache);

// Main function to manage theme caching
int manageThemeCaching(ThemeCache *themeCache, const char *defaultDir) {
    if (!checkAndSetDefaultThemeDirectory(themeCache, defaultDir)) {
        return -1; // Error setting default directory
    }

    char imageFiles[MAX_CACHE_SIZE][MAX_PATH];
    int numFiles = loadImageFileList(imageFiles, MAX_CACHE_SIZE);

    for (int i = 0; i < numFiles; ++i) {
        const char *filePath = imageFiles[i];
        ImageMetadata metadata;

        if (isTiff(filePath)) {
            metadata = extractTiffMetadata(filePath);
        } else if (isPng(filePath)) {
            metadata = extractPngMetadata(filePath);
        } else {
            continue; // Unsupported file type
        }

        cacheImageToThemeCache(filePath, themeCache);

        // Handle extracted metadata as needed...
    }

    return 0;
}

int checkAndSetDefaultThemeDirectory(ThemeCache *cache, const char *defaultDir) {
    if (strcmp(cache->defaultThemeDir, "") == 0) {
        strncpy(cache->defaultThemeDir, defaultDir, MAX_PATH);
        cache->defaultThemeDir[MAX_PATH - 1] = '\0';
        return 1;
    }
    return strcmp(cache->defaultThemeDir, defaultDir) != 0 ? 1 : 0;
}

ImageMetadata extractTiffMetadata(const char *filePath) {
    ImageMetadata metadata = {0, 0, NULL};

    TIFFInfo tiffInfo;
    if (TIFFReadInfo(filePath, &tiffInfo)) {
        metadata.bits_per_sample = tiffInfo.bitsPerSample;
        metadata.extra_samples_count = tiffInfo.extraSamplesCount;

        // Allocate and copy extra samples info
        metadata.extra_samples_info = malloc(tiffInfo.extraSamplesInfoLen);
        if (metadata.extra_samples_info) {
            memcpy(metadata.extra_samples_info, tiffInfo.extraSamplesInfo,
                   tiffInfo.extraSamplesInfoLen);
        }
    }

    return metadata;
}

ImageMetadata extractPngMetadata(const char *filePath) {
    ImageMetadata metadata = {0, 0, NULL};

    PNGInfo pngInfo;
    if (PNGReadInfo(filePath, &pngInfo)) {
        // PNG does not have extra samples info like TIFF
        metadata.bits_per_sample = pngInfo.bitsPerSample;
    }

    return metadata;
}

void cacheImageToThemeCache(const char *imagePath, ThemeCache *cache) {
    // Check if the theme bitmap is recycled and set it to null if necessary
    if (cache->themeBitmap != NULL) {
        free(cache->themeBitmap);
        cache->themeBitmap = NULL;
    }

    // Load image from cache root directory into theme cache
    char cachedPath[MAX_PATH];
    snprintf(cachedPath, MAX_PATH, "%s/%s", cache->defaultThemeDir, imagePath);

    FILE *file = fopen(cachedPath, "rb");
    if (file) {
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        fseek(file, 0, SEEK_SET);

        cache->themeBitmap = malloc(fileSize);
        fread(cache->themeBitmap, 1, fileSize, file);
        fclose(file);
    }
}

// Stub functions to represent image loading and checking functionality
int loadImageFileList(char files[][MAX_PATH], int maxFiles) {
    // Implement logic to populate `files` with paths of images in the cache directory.
    return 0; // Return number of loaded files
}

int isTiff(const char *filePath) {
    // Implement check if file at `filePath` is a TIFF image.
    return 1;
}

int isPng(const char *filePath) {
    // Implement check if file at `filePath` is a PNG image.
    return 0;
}
