#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <openssl/md5.h>

#define MAX_FILENAME_LENGTH 256

void log_error(const char *error_message) {
    FILE *log_file = fopen("errors.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", error_message);
        fclose(log_file);
    }
}

char* generate_timestamp() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", t);
    return strdup(timestamp);
}

char* generate_uuid() {
    uuid_t binuuid;
    char *uuid_str = malloc(37); // UUID string length
    if (uuid_generate_random(binuuid)) {
        uuid_unparse_lower(binuuid, uuid_str);
        return uuid_str;
    } else {
        free(uuid_str);
        return NULL;
    }
}

void process_filenames(const char *config_file_path) {
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        log_error("Failed to open configuration file.");
        return;
    }

    char line[MAX_FILENAME_LENGTH];
    int sequence_number = 0;

    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        if (strlen(line) == 0 || strchr(line, '.') == NULL) {
            log_error("Malformed filename: ");
            continue;
        }

        char *original_filename = strdup(line);
        char *extension_start = strrchr(original_filename, '.');
        if (!extension_start) {
            free(original_filename);
            log_error("Invalid character in filename: ");
            continue;
        }

        int original_length = strlen(original_filename);

        // Append timestamp
        char *timestamp = generate_timestamp();
        if (!timestamp) {
            free(original_filename);
            log_error("Failed to generate timestamp for filename: ");
            continue;
        }

        // Append UUID
        char *uuid_str = generate_uuid();
        if (!uuid_str) {
            free(original_filename);
            free(timestamp);
            log_error("Failed to generate UUID for filename: ");
            continue;
        }

        // Append sequence number based on original length
        int seq_num_length = snprintf(NULL, 0, "%d", original_length);
        char *sequence_number_str = malloc(seq_num_length + 1);
        if (!sequence_number_str) {
            free(original_filename);
            free(timestamp);
            free(uuid_str);
            log_error("Failed to allocate memory for sequence number: ");
            continue;
        }
        snprintf(sequence_number_str, seq_num_length + 1, "%d", original_length);

        // Construct new filename
        char new_filename[MAX_FILENAME_LENGTH];
        snprintf(new_filename, sizeof(new_filename), 
                 "%s_%s_%s_%s",
                 original_filename,
                 timestamp,
                 uuid_str,
                 sequence_number_str);

        free(timestamp);
        free(uuid_str);
        free(sequence_number_str);

        // Generate MD5 hash
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)new_filename, strlen(new_filename), (unsigned char *)&digest);

        // Convert to hexadecimal string
        char md5_hexstring[2 * MD5_DIGEST_LENGTH + 1];
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            snprintf(&(md5_hexstring[i*2]), 3, "%02x", (unsigned int)digest[i]);
        }

        printf("MD5: %s\n", md5_hexstring);

        free(original_filename);
    }

    fclose(file);
}
