#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

#define KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];
} AES256Cipher;

void handleErrors(void) {
    ERR_print_errors_fp(stderr);
    abort();
}

int derive_key_and_iv(const char *password, size_t password_len,
                      const unsigned char *salt, int salt_len,
                      unsigned char *key, unsigned char *iv,
                      int iterations) {
    if (EVP_PBE_derive_KEY_rfc8018(EVP_aes_256_cbc(), EVP_sha256(),
                                   key, KEY_LENGTH, iv, IV_LENGTH,
                                   password, password_len, salt, salt_len,
                                   iterations) <= 0) {
        handleErrors();
        return -1;
    }
    return 0;
}

int init_cipher(AES256Cipher *cipher, const char *password, size_t password_len,
                unsigned char *salt, int salt_len, int iterations) {
    if (!cipher || !password || !salt) {
        return -1;
    }

    if (derive_key_and_iv(password, password_len, salt, salt_len,
                          cipher->key, cipher->iv, iterations)) {
        return -1;
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        handleErrors();
        return -1;
    }

    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL,
                           cipher->key, cipher->iv) != 1) {
        handleErrors();
        cleanup_cipher(cipher);
        return -1;
    }

    return 0;
}

void cleanup_cipher(AES256Cipher *cipher) {
    if (cipher && cipher->ctx) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        cipher->ctx = NULL;

        // Secure zeroization of key and IV
        OPENSSL_cleanse(cipher->key, KEY_LENGTH);
        OPENSSL_cleanse(cipher->iv, IV_LENGTH);
    }
}

// Usage example (not part of the function)
