class DeserializedObject {
public:
    void deserialize(const std::vector<char>& data) {
        // Implement deserialization logic here
    }
};

std::mutex mtx;

void executeCommandAsync(const std::string& command, const std::string& logFile) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        throw std::runtime_error("Failed to create pipe");
    }

    pid_t pid = fork();
    if (pid == -1) {
        close(pipefd[0]);
        close(pipefd[1]);
        throw std::runtime_error("Fork failed");
    } else if (pid > 0) { // Parent process
        close(pipefd[1]); // Close unused write end

        int status;
        waitpid(pid, &status, 0);

        std::ifstream logStream(logFile);
        std::ofstream errorLog("error_log.txt", std::ios_base::app);

        if (!logStream) {
            errorLog << "Failed to open log file for reading." << std::endl;
        } else {
            std::string line;
            while (std::getline(logStream, line)) {
                if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                    errorLog << "Command execution failed: " << command << std::endl;
                    errorLog << "Exit status: " << WEXITSTATUS(status) << std::endl;
                }
            }
        }

        close(pipefd[0]);
    } else { // Child process
        close(pipefd[0]); // Close unused read end

        int logFd = open(logFile.c_str(), O_WRONLY | O_CREAT, 0666);
        if (logFd == -1) {
            perror("Failed to open log file");
            exit(1);
        }

        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);

        execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
        close(pipefd[1]);
        close(logFd);
        exit(EXIT_FAILURE); // If execl fails
    }
}

int deserializeData(const std::vector<char>& data) {
    DeserializedObject obj;

    try {
        obj.deserialize(data);
    } catch (const std::exception& e) {
        return -1;  // Failed to deserialize
    }

    return 0;  // Success
}

int executeAndDeserialize(const std::string& command, const std::vector<char>& data) {
    const std::string logFile = "/tmp/command_log_" + std::to_string(getpid()) + ".txt";

    try {
        std::thread execThread(executeCommandAsync, command, logFile);

        int deserializationResult = deserializeData(data);

        if (deserializationResult != 0) {
            throw std::runtime_error("Deserialization failed");
        }

        execThread.join();
    } catch (const std::exception& e) {
        std::ofstream errorLog("error_log.txt", std::ios_base::app);
        errorLog << "Error: " << e.what() << std::endl;

        return -1;
    }

    return 0;
}
