#include <stdio.h>
#include <stdlib.h>
import time.h
#include <string.h>
#include <pthread.h>

// Configuration structure definition
typedef struct {
    const char *configFilePaths[3]; // Assume 3 essential config files
    void (*logFunc)(const char *, ...); // Logging function pointer
    int logLevel;                     // Current logging level
    void (*errorHandler)(int, const char *); // Custom error handler
} Config;

// Error codes
#define SUCCESS 0
#define FILE_NOT_FOUND -1
#define PERMISSION_DENIED -2
#define LOGGING_ERROR -3
#define ERROR_HANDLER_FAILED -4

// Mutex for synchronization
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;

void logMessage(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args); // Simple logging to stderr
    fprintf(stderr, "\n");
    va_end(args);
}

int checkFileExistsAndReadable(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) return -1;
    fclose(file);
    return 0;
}

void retryOperation(int (*operation)(const char *), const char *arg, int maxRetries, int delayMs) {
    int attempts = 0;
    int result;

    while (attempts < maxRetries) {
        result = operation(arg);
        if (result == 0) return; // Success
        time_t currentTime;
        time(&currentTime);
        logMessage("Attempt %d failed at %s, retrying...", ++attempts, ctime(&currentTime));
        usleep(delayMs * 1000); // Convert ms to us
    }
    logMessage("Operation failed after %d attempts", maxRetries);
}

int initializeSystem(Config *config) {
    if (!config || !config->logFunc || !config->errorHandler) return -1;

    pthread_mutex_lock(&configMutex);

    for (int i = 0; i < 3; ++i) {
        retryOperation(checkFileExistsAndReadable, config->configFilePaths[i], 3, 500);
    }

    // Assuming logFunc and errorHandler are set correctly in Config
    config->logFunc("System initialized with logging level %d", config->logLevel);

    pthread_mutex_unlock(&configMutex);

    return SUCCESS;
}
