bool decrypt_with_3des(const std::string &ciphertext, std::string &plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return false;

    // Initialize decryption with the key and IV
    if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, reinterpret_cast<const unsigned char*>(DECRYPTION_KEY.c_str()), 
                                reinterpret_cast<const unsigned char*>(INIT_VECTOR.c_str()))) {
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }

    std::vector<unsigned char> ciphertext_vec(ciphertext.begin(), ciphertext.end());
    std::vector<unsigned char> decryptedtext_vec(ciphertext.size());

    // Decrypt the data
    if (1 != EVP_DecryptUpdate(ctx, &decryptedtext_vec[0], &len, &ciphertext_vec[0], ciphertext_vec.size())) {
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }
    plaintext_len = len;

    // Finalize decryption
    if (1 != EVP_DecryptFinal_ex(ctx, &decryptedtext_vec[0] + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return false;
    }
    plaintext_len += len;

    decryptedtext_vec.resize(plaintext_len);

    plaintext.assign(decryptedtext_vec.begin(), decryptedtext_vec.end());

    EVP_CIPHER_CTX_free(ctx);
    return true;
}

void check_for_updates(const std::string &module_name) {
