['Below is an implementation of the C# function that processes a large binary file using custom streaming algorithms, handling multiple concurrent requests efficiently with options for compression and encryption transformations:

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileProcessorConfig
{
    public bool EnableCompression { get; set; }
    public bool EnableEncryption { get; set; }
    public int MaxConcurrentTasks { get; set; } = 4;
    public long MemoryLimitBytes { get; set; } = 512 * 1024 * 1024; // 512 MB
}

public class ProcessingSummary
{
    public long TotalBytesProcessed { get; set; }
    public int SuccessfulRequests { get; set; }
    public int FailedRequests { get; set; }
    public double ThroughputMbps => (TotalBytesProcessed / (double)(FailedRequests + SuccessfulRequests)) * 8 / 1024 / 1024;
    public List<string> ErrorsEncountered { get; } = new List<string>();
}

public class FileProcessor
{
    private readonly SemaphoreSlim _semaphore;

    public FileProcessor(FileProcessorConfig config)
    {
        _semaphore = new SemaphoreSlim(config.MaxConcurrentTasks, config.MaxConcurrentTasks);
    }

    public async Task<ProcessingSummary> ProcessFileAsync(string filePath, FileProcessorConfig config)
    {
        var summary = new ProcessingSummary();

        try
        {
            await _semaphore.WaitAsync();

            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                long totalBytesProcessed = 0;

                while (fileStream.Position < fileStream.Length)
                {
                    byte[] buffer = new byte[config.MemoryLimitBytes];
                    int bytesRead;

                    try
                    {
                        bytesRead = await fileStream.ReadAsync(buffer, 0, buffer.Length);
                        if (bytesRead == 0) break; // End of stream

                        totalBytesProcessed += bytesRead;

                        // Process the buffer with optional compression and encryption
                        byte[] processedData = await ProcessBufferAsync(buffer[..bytesRead], config);

                        // Write or further process `processedData` as needed.
                    }
                    catch (Exception ex)
                    {
                        summary.FailedRequests++;
                        summary.ErrorsEncountered.Add(ex.Message);
                    }

                    Console.WriteLine($"Progress: {totalBytesProcessed} bytes processed.");
                }

                summary.TotalBytesProcessed = totalBytesProcessed;
                summary.SuccessfulRequests++;
            }
        }
        finally
        {
            _semaphore.Release();
        }

        return summary;
    }

    private async Task<byte[]> ProcessBufferAsync(byte[] buffer, FileProcessorConfig config)
    {
        byte[] processedData = buffer;

        if (config.EnableCompression)
        {
            processedData = await CompressDataAsync(processedData);
        }

        if (config.EnableEncryption)
        {
            processedData = await EncryptDataAsync(processedData);
        }

        return processedData;
    }

    private Task<byte[]> CompressDataAsync(byte[] data)
    {
        // Example compression using System.IO.Compression
        using (var compressedStream = new MemoryStream())
        using (var compressor = new System.IO.Compression.GZipStream(compressedStream, System.IO.Compression.CompressionMode.Compress))
        {
            compressor.Write(data, 0, data.Length);
            compressor.Close();
            return Task.FromResult(compressedStream.ToArray());
        }
    }

    private async Task<byte[]> EncryptDataAsync(byte[] data)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = GenerateRandomKey(32); // AES-256
            aes.IV = new byte[16];

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            using (var resultStream = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(resultStream, encryptor, CryptoStreamMode.Write))
                {
                    await cryptoStream.WriteAsync(data, 0, data.Length);
                    cryptoStream.Close();
                }
                return resultStream.ToArray();
            }
        }
    }

    private byte[] GenerateRandomKey(int size)
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var key = new byte[size];
            rng.GetBytes(key);
            return key;
        }
    }
}

// Usage Example
public static async Task Main(string[] args)
{
    var config = new FileProcessorConfig 
    { 
        EnableCompression = true, 
        EnableEncryption = true,
        MaxConcurrentTasks = 4,
        MemoryLimitBytes = 10 * 1024 * 1024 // 10 MB buffer size
    };

    var processor = new FileProcessor(config);

    string filePath = "path_to_large_file.bin";
    ProcessingSummary summary = await processor.ProcessFileAsync(filePath, config);

    Console.WriteLine($"Total Bytes Processed: {summary.TotalBytesProcessed}");
    Console.WriteLine($"Successful Requests: {summary.SuccessfulRequests}");
    Console.WriteLine($"Failed Requests: {summary.FailedRequests}");
    Console.WriteLine($"Throughput Mbps: {summary.ThroughputMbps}");
    foreach (var error in summary.ErrorsEncountered)
    {
        Console.WriteLine($"Error: {error}");
    }
}
```

This implementation includes:

- A semaphore to limit concurrent processing tasks.
- Options for compression and encryption transformations using third-party libraries like `System.IO.Compression` and the built-in AES encryption.
- Error handling with logging of encountered issues.
- Progress reporting via console output showing bytes processed.
- Memory management by controlling buffer size relative to a configurable memory limit.']

