["```javascript
const axios = require('axios');
const crypto = require('crypto');
const { Storage } = require('@google-cloud/storage'); // Example cloud storage SDK
const NodeCache = require('node-cache');

// Initialize Google Cloud Storage client (assuming GCS)
const storage = new Storage();
const cache = new NodeCache({ stdTTL: 86400 }); // Cache TTL of 24 hours

async function calculateChecksum(fileUrl) {
    const response = await axios.get(fileUrl, { responseType: 'arraybuffer' });
    return crypto.createHash('sha256').update(response.data).digest('hex');
}

async function uploadFileToCloudStorage(fileUrl) {
    try {
        const checksum = await calculateChecksum(fileUrl);

        // Check cache to avoid redundant uploads
        if (cache.get(checksum)) {
            console.log(`Skipping cached file: ${fileUrl}`);
            return null;
        }

        const bucketName = 'your-bucket-name';  // Replace with your bucket name
        const destinationFileName = new URL(fileUrl).pathname.split('/').pop();

        const [file] = await storage.bucket(bucketName).upload({
            uri: fileUrl,
            gzip: true,
            metadata: {
                cacheControl: 'public, max-age=31536000',
            },
        });

        console.log(`File uploaded to ${file.name}`);
        cache.set(checksum, file.name);

        return file.publicUrl;
    } catch (error) {
        console.error(`Error uploading file from ${fileUrl}:`, error.message);
        return null;
    }
}

async function uploadFilesFromUrls(urls) {
    const uploads = urls.map(url => 
        uploadFileToCloudStorage(url)
    );

    // Use Promise.allSettled to handle multiple concurrent uploads
    const results = await Promise.allSettled(uploads);

    // Filter successful uploads and return their URLs
    return results
        .filter(result => result.status === 'fulfilled' && result.value !== null)
        .map(result => result.value);
}

// Example usage:
(async () => {
    const fileUrls = [
        'https://example.com/file1.jpg',
        'https://example.com/file2.png',
        // Add more URLs as needed
    ];

    const successfulUploads = await uploadFilesFromUrls(fileUrls);
    console.log('Successfully uploaded files:', successfulUploads);
})();
```

### Notes:
- The code uses the Google Cloud Storage SDK for uploading files, so make sure to set up your credentials and replace `'your-bucket-name'` with your actual bucket name.
- `axios` is used for downloading files to calculate their checksum.
- A cache mechanism using `node-cache` prevents redundant uploads by storing checksums of uploaded files for 24 hours.
- The function handles errors gracefully, logging any issues during the upload process and continuing with other files.
- This solution assumes a Node.js environment; adjust SDK imports and configurations according to your specific cloud storage provider if different."]

