// cComponent.c

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct Record {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    atomic_uintptr_t next; // Use uintptr_t for pointer-sized storage
    Record data;
} Node;

