// Helper function to generate a random number in range [min, max]
int randRange(int min, int max) {
    return min + rand() % (max - min + 1);
}

Node* create_node(Record record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    atomic_store(&node->next, (uintptr_t)NULL);
    node->data = record;
    return node;
}

void add_record(Record record) {
    Node* new_node = create_node(record);

    do {
        Node* old_head = head;
        atomic_store(&new_node->next, (uintptr_t)old_head);
    } while (!atomic_compare_exchange_weak((atomic_uintptr_t*)&head, &old_head, (uintptr_t)new_node));

    // Handle memory cleanup and other operations as needed
}

void process_input(char* input) {
    // Parse JSON input and extract record data
    Record record = { .s = randRange(0, 100), .i = randRange(0, 10000), .f = (float)(rand() / RAND_MAX * 100.0) };
    add_record(record);

    printf("{\"status\":\"success\"}\n");
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <json_input>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_input(argv[1]);

    // Cleanup and deallocate memory as necessary
    Node* current = head;
    while (current != NULL) {
        Node* next = (Node*)atomic_load(&current->next);
        free(current);
        current = next;
    }

    return EXIT_SUCCESS;
}
```

### Explanation

- **JavaScript Component**: Uses Express.js to handle HTTP POST requests and spawns a C process for record management.

- **C Component**:
  - Implements a lock-free linked list using atomic operations.
  - Records are added concurrently with minimal contention.
  - Random values are generated within specified ranges for testing purposes.
  - Memory cleanup is performed at the end to prevent leaks.

This setup ensures efficient memory usage and concurrency handling, balancing performance and reliability.']

