            if graph_id in self.graphs and vertex in self.graphs[graph_id]:
                for key, value in properties.items():
                    self.graphs[graph_id].nodes[vertex][key] = value

    def add_edge(self, graph_id, edge, weight=1, properties=None):
        with self.lock:
            if graph_id not in self.graphs:
                self.graphs[graph_id] = nx.Graph()

            self.graphs[graph_id].add_edge(*edge, weight=weight, **(properties or {}))

    def update_edge(self, graph_id, edge, weight=None, properties=None):
