#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define LOG_FILE "metrics.log"
#define RATE_LIMIT_SECONDS 1

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void initialize_logging() {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }
}

void log_performance_metrics(const char *message) {
    pthread_mutex_lock(&log_mutex);

    time_t now;
    time(&now);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            local_time->tm_year + 1900,
            local_time->tm_mon + 1,
            local_time->tm_mday,
            local_time->tm_hour,
            local_time->tm_min,
            local_time->tm_sec,
            message);

    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

void dynamic_rate_limiting() {
    static time_t last_log_time = 0;
    time_t current_time;

    time(&current_time);
    if (difftime(current_time, last_log_time) >= RATE_LIMIT_SECONDS) {
        log_performance_metrics("Rate limited logging event");
        last_log_time = current_time;
    }
}

void integrate_crypto_primitives() {
    initialize_logging();

    // Add AES and Camellia ciphers
    EVP_add_cipher(&evp_aes_128_cbc());
    EVP_add_cipher(&evp_camellia_128_cbc());

    // Add MD5 and SHA digests
    EVP_add_digest(&evp_md5());
    EVP_add_digest(&evp_sha1());

    // Add RSA with SHA1
    EVP_add_cipher(&evp_aes_256_gcm());
    EVP_add_digest_alias("sha1", "SHA");

    dynamic_rate_limiting();

    log_performance_metrics("Crypto primitives integrated successfully");
}

int main() {
    integrate_crypto_primitives();
    return 0;
}
