['```cpp
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <iostream>
#include <fstream>
#include <sstream>
#include <map>
#include <memory>
#include <random>
#include <mutex>
#include <chrono>

namespace CryptoUtil {

    class SecureRandomGenerator {
    public:
        SecureRandomGenerator() : rng_(std::mt19937(std::random_device{}())) {}

        ~SecureRandomGenerator() = default;

        template<typename T, typename... Args>
        T get_random(Args&&... args) {
            std::uniform_int_distribution<T> dist(std::forward<Args>(args)...);
            return dist(rng_);
        }

    private:
        std::mt19937 rng_;
    };

    class Logger {
    public:
        static void log(const std::string& message) {
            std::lock_guard<std::mutex> lock(mutex_);
            std::ofstream log_file("crypto_operations.log", std::ios_base::app);
            if (log_file.is_open()) {
                auto now = std::chrono::system_clock::now();
                auto now_c = std::chrono::system_clock::to_time_t(now);
                log_file << std::ctime(&now_c) << ": " << message << "\n";
            }
        }

    private:
        static std::mutex mutex_;
    };

    std::mutex Logger::mutex_;

    class CryptoManager {
    public:
        enum Algorithm { AES, RSA };

        CryptoManager(const std::string& config_file) {
            load_config(config_file);
        }

        ~CryptoManager() {
            EVP_cleanup();
        }

        bool encrypt(const unsigned char* plaintext, int plaintext_len,
                     unsigned char* ciphertext, int& ciphertext_len) {
            return perform_operation(plaintext, plaintext_len, ciphertext, ciphertext_len, true);
        }

        bool decrypt(const unsigned char* ciphertext, int ciphertext_len,
                     unsigned char* plaintext, int& plaintext_len) {
            return perform_operation(ciphertext, ciphertext_len, plaintext, plaintext_len, false);
        }

    private:
        void load_config(const std::string& config_file) {
            std::ifstream file(config_file);
            if (!file.is_open()) {
                Logger::log("Failed to open config file.");
                throw std::runtime_error("Config file not found");
            }
            std::stringstream buffer;
            buffer << file.rdbuf();
            std::string content = buffer.str();

            // Basic parsing logic
            if (content.find("AES") != std::string::npos) {
                algorithm_ = AES;
            } else if (content.find("RSA") != std::string::npos) {
                algorithm_ = RSA;
            }
        }

        bool perform_operation(const unsigned char* input, int input_len,
                               unsigned char* output, int& output_len,
                               bool encrypt) const {
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            if (!ctx) return false;

            int len;
            int ciphertext_len;
            if (encrypt) {
                if (!EVP_EncryptInit_ex(ctx, algorithm_ == AES ? EVP_aes_256_cbc() : EVP_RSA_public_encrypt(),
                                        nullptr, key_.data(), iv_.data())) {
                    Logger::log("Encryption init failed.");
                    EVP_CIPHER_CTX_free(ctx);
                    return false;
                }
            } else {
                if (!EVP_DecryptInit_ex(ctx, algorithm_ == AES ? EVP_aes_256_cbc() : EVP_RSA_private_decrypt(),
                                        nullptr, key_.data(), iv_.data())) {
                    Logger::log("Decryption init failed.");
                    EVP_CIPHER_CTX_free(ctx);
                    return false;
                }
            }

            if (!encrypt && !EVP_DecryptUpdate(ctx, output, &len, input, input_len)) {
                Logger::log("Decryption update failed.");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            } else if (encrypt && !EVP_EncryptUpdate(ctx, output, &len, input, input_len)) {
                Logger::log("Encryption update failed.");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            ciphertext_len = len;

            if (!encrypt && !EVP_DecryptFinal_ex(ctx, output + len, &len)) {
                Logger::log("Decryption finalization failed.");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            } else if (encrypt && !EVP_EncryptFinal_ex(ctx, output + len, &len)) {
                Logger::log("Encryption finalization failed.");
                EVP_CIPHER_CTX_free(ctx);
                return false;
            }
            ciphertext_len += len;

            EVP_CIPHER_CTX_free(ctx);

            output_len = ciphertext_len;
            return true;
        }

        Algorithm algorithm_;
        std::vector<unsigned char> key_ = {0x00, 0x01, 0x02}; // Example key
        std::vector<unsigned char> iv_ = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07}; // Example IV
    };

} // namespace CryptoUtil

int main() {
    try {
        CryptoUtil::CryptoManager manager("config.txt");
        unsigned char plaintext[] = "This is a test.";
        unsigned char ciphertext[128];
        unsigned char decryptedtext[128];
        int len, decryptedtext_len;

        if (manager.encrypt(plaintext, sizeof(plaintext) - 1, ciphertext, len)) {
            std::cout << "Encryption successful." << std::endl;
            if (manager.decrypt(ciphertext, len, decryptedtext, decryptedtext_len)) {
                std::cout << "Decryption successful." << std::endl;
                decryptedtext[decryptedtext_len] = '\0';
                std::cout << "Decrypted text: " << decryptedtext << std::endl;
            }
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
```

