#define INITIAL_CAPACITY 1000
#define MAX_ITEMS 10000

typedef struct item {
    double value;
    int number;
    struct item *next;
} item;

item **initialize_items(int total_count, int range_min, int range_max) {
    if (total_count > MAX_ITEMS || total_count <= 0)
        return NULL;

    srand(time(NULL));

    item **items = malloc(INITIAL_CAPACITY * sizeof(item *));
    if (!items)
        return NULL;

    size_t capacity = INITIAL_CAPACITY;
    int count = 0;

    while (count < total_count) {
        // Resize array if needed
        if (count >= capacity) {
            capacity *= 2;
            item **new_items = realloc(items, capacity * sizeof(item *));
            if (!new_items)
                break;  // Failed to reallocate memory
            items = new_items;
        }

        // Allocate and initialize each struct item
        items[count] = malloc(sizeof(item));
        if (!items[count])
            break;  // Failed to allocate memory for an item

        items[count]->value = (double)rand() / RAND_MAX * 100.0;  // Random double between 0 and 100
        items[count]->number = range_min + rand() % (range_max - range_min + 1);  // Random int within specified range
        items[count]->next = NULL;

        count++;
    }

    return items;
}

void free_items(item **items, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (items[i]) {
            free(items[i]);
        }
    }
    free(items);
}

