#[derive(Debug)]
struct Record {
    short: i16,
    integer: i32,
    floating_point: f64,
}

struct RecordManager {
    records: LinkedList<Record>,
    offset: Vec<i32>,
    key: Vec<u32>,
    rng: rand::rngs::ThreadRng,
}

impl RecordManager {
    fn new() -> Self {
        let mut manager = RecordManager {
            records: LinkedList::new(),
            offset: Vec::new(),
            key: Vec::new(),
            rng: rand::thread_rng(),
        };

        // Initialize with some predefined values
        manager.add_record();
        manager
    }

    fn add_record(&mut self) {
        let record = Record {
            short: (self.rng.gen_range(0..=32767)) as i16,
            integer: (self.rng.gen_range(0..=2147483647)) as i32,
            floating_point: self.rng.gen::<f64>(),
        };

        // Insert the new record
        self.records.push_back(record);

        let key_value = self.generate_key();
        self.key.push(key_value);

        let offset_value = if self.offset.is_empty() {
            42 // predefined constant for first element
        } else {
            self.offset.last().unwrap() + (key_value as i32) + 42
        };

        self.offset.push(offset_value);
    }

    fn generate_key(&self) -> u32 {
        let mut key = self.rng.gen_range(1000..=9999);
        while self.key.contains(&key) {
            key = self.rng.gen_range(1000..=9999);
        }
        key
    }

    fn resize_arrays(&mut self) {
        if self.key.capacity() == self.key.len() {
            let new_capacity = (self.key.capacity() * 3 / 2) + 1;
            self.key.reserve(new_capacity - self.key.capacity());
            self.offset.reserve(new_capacity - self.offset.capacity());
        }
    }

    fn iterate_records(&self) {
        for record in &self.records {
            // Simulate processing each record
            println!("{:?}", record);
        }
    }

    fn request_builder(url: &str, insecure: bool) -> reqwest::RequestBuilder {
        let client = if insecure {
            ClientBuilder::new()
                .danger_accept_invalid_certs(true)
                .build().unwrap()
        } else {
            ClientBuilder::new().build().unwrap()
