// Union-Find (Disjoint Set) data structure for finding disjoint pairs.
public class UnionFind
{
    private readonly Dictionary<int, int> parent;

    public UnionFind(int size)
    {
        parent = new Dictionary<int, int>();
        for (int i = 0; i < size; i++)
            parent[i] = i;
    }

    public int Find(int x)
    {
        if (parent[x] != x)
            parent[x] = Find(parent[x]);
        return parent[x];
    }

    public void Union(int x, int y)
    {
        int rootX = Find(x);
        int rootY = Find(y);

        if (rootX != rootY)
            parent[rootY] = rootX;
    }
}

// Main Game Configuration Manager
public class ConfigurationManager
{
    private static MemoryCache _cache = new MemoryCache("GameConfigCache");
    private static readonly object _lockObject = new object();

    public static async Task<GameConfiguration> LoadConfigurationAsync(string filePath)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                string json = await reader.ReadToEndAsync();
                return JsonConvert.DeserializeObject<GameConfiguration>(json);
            }
        }
        catch (Exception ex)
        {
            // Log exception details here.
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            throw;
        }
    }

    public static GameConfiguration GetCachedConfiguration(string filePath)
    {
        if (!_cache.Contains(filePath))
        {
            lock (_lockObject)
            {
                if (!_cache.Contains(filePath))  // Double-check locking
                {
                    var config = LoadConfigurationAsync(filePath).Result;
                    _cache.Set(filePath, config, DateTimeOffset.Now.AddMinutes(10)); // Cache for 10 minutes
                }
            }
        }

        return (GameConfiguration)_cache.Get(filePath);
    }

    public static void UpdateConfiguration(GameConfiguration newConfig)
    {
        lock (_lockObject) 
        {
            // Here you might update the configuration in a database or file.
            Console.WriteLine("Updating Configuration...");

            // Simulating an update
            _cache.Remove(newConfig.GetType().Name); // Invalidate cache after updating
        }
    }

    public static List<Tuple<int, int>> FindDisjointPairs(int[] array)
    {
        var disjointPairs = new List<Tuple<int, int>>();
        if (array == null || array.Length < 2) return disjointPairs;

        UnionFind uf = new UnionFind(array.Max() + 1);

        for (int i = 0; i < array.Length; i++)
        {
            // Example logic to find pairs: union elements with their indices
            uf.Union(i, array[i]);
        }

        HashSet<int> seenRoots = new HashSet<int>();

        for (int i = 0; i < array.Length; i++)
        {
            int root = uf.Find(array[i]);

            if (!seenRoots.Contains(root))
                seenRoots.Add(root);
            else
                disjointPairs.Add(Tuple.Create(i, array[i]));
        }

        return disjointPairs;
    }
}

