using System;
using UnityEngine;

namespace RandomUtilityLibrary
{
    public sealed class RandomGenerator : IDisposable
    {
        private readonly float _minFloat;
        private readonly float _maxFloat;
        private readonly int _minInt;
        private readonly int _maxInt;
        private static readonly object LockObject = new object();

        private System.Random _random;

        public RandomGenerator(float minFloat, float maxFloat, int minInt, int maxInt, int seed)
        {
            _minFloat = minFloat;
            _maxFloat = maxFloat;
            _minInt = minInt;
            _maxInt = maxInt;
            _random = new System.Random(seed);
        }

        public float GenerateFloat(bool inclusiveMin, bool inclusiveMax)
        {
            lock (LockObject)
            {
                float value;
                do
                {
                    value = inclusiveMin ? _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat 
                                         : _random.NextDouble() * (_maxFloat - _minFloat + 1f) + _minFloat;
                } while ((inclusiveMax && value > _maxFloat) || (!inclusiveMax && value >= _maxFloat));

                LogActivity("Generated float: " + value);
                ValidateRange(value, _minFloat, _maxFloat);

                return value;
            }
        }

        public int GenerateInt(bool inclusiveMin, bool inclusiveMax)
        {
            lock (LockObject)
            {
                int value;
                do
                {
                    value = inclusiveMin ? _random.Next(_minInt, _maxInt + 1) 
                                         : _random.Next(_minInt + 1, _maxInt + 2);
                } while ((inclusiveMax && value > _maxInt) || (!inclusiveMax && value >= _maxInt));

                LogActivity("Generated int: " + value);
                ValidateRange(value, _minInt, _maxInt);

                return value;
            }
        }

        public Vector3 GenerateVector3(bool inclusiveMin, bool inclusiveMax)
        {
            lock (LockObject)
            {
                var x = GenerateFloat(inclusiveMin, inclusiveMax);
                var y = GenerateFloat(inclusiveMin, inclusiveMax);
                var z = GenerateFloat(inclusiveMin, inclusiveMax);

                LogActivity($"Generated Vector3: ({x}, {y}, {z})");

                return new Vector3(x, y, z);
            }
        }

        public Vector2 GenerateVector2(bool inclusiveMin, bool inclusiveMax)
        {
            lock (LockObject)
            {
                var x = GenerateFloat(inclusiveMin, inclusiveMax);
                var y = GenerateFloat(inclusiveMin, inclusiveMax);

                LogActivity($"Generated Vector2: ({x}, {y})");

                return new Vector2(x, y);
            }
        }

        public Color GenerateColor(bool inclusiveMin, bool inclusiveMax)
        {
            lock (LockObject)
            {
                var r = GenerateFloat(inclusiveMin, inclusiveMax);
                var g = GenerateFloat(inclusiveMin, inclusiveMax);
                var b = GenerateFloat(inclusiveMin, inclusiveMax);

                LogActivity($"Generated Color: ({r}, {g}, {b})");

                return new Color(r, g, b);
            }
        }

        private void ValidateRange(float value, float min, float max)
        {
            if (value < min || value > max)
            {
                throw new InvalidOperationException("Random value out of expected range.");
            }
        }

        private void LogActivity(string message)
        {
#if UNITY_EDITOR
            Debug.Log(message);
#else
            Console.WriteLine(message); // Replace with more sophisticated logging in production.
#endif
        }

        public void Dispose()
        {
            _random?.Dispose();
        }
    }
}

