    char* theme_dir = DEFAULT_THEME_DIR; // Assume this is checked/configured elsewhere

    if (strcmp(theme_dir, "") == 0) {
        theme_dir = FALLBACK_THEME_DIR;
    }

    pthread_t png_thread;
    pthread_create(&png_thread, NULL, parse_png_from_theme_dir, NULL);
    pthread_detach(png_thread);

    int conversion_result = jpeg_to_pdf_converter(file_path, output_file_name, theme_bitmap);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + 
                            (current_time.tv_nsec - start_time.tv_nsec);

        if (elapsed_time >= MAX_CONVERSION_TIME * 1000000000L) {
            send_notification("JPEG to PDF conversion exceeded time limit.");
            printf("Conversion exceeded time limit.\n");
            break;
        }

        // Check periodically for completion
        if (conversion_result != -1) { // Assuming -1 indicates ongoing process
            break;
        }
    }

    if (conversion_result == 0) {
        send_notification("JPEG to PDF conversion completed successfully.");
    } else {
        send_notification("Error during JPEG to PDF conversion.");
    }

    return conversion_result; // 0 on success, 1 or other values for error states
}
```

### Key Points:
- **Bitmap Recycling:** Checks if the bitmap is in use and recycles it if not.
- **Theme Directory Check:** Defaults to a fallback directory if none configured.
- **Non-blocking PNG Parsing:** Uses a separate thread to parse PNG files without blocking.
- **Time Limit Enforcement:** Monitors conversion time and handles timeouts gracefully.
- **Concurrency:** Supports concurrent processing of bitmaps using threads.
- **Error Handling and Notifications:** Logs errors and uses an external service for notifications.']

