char *decryptMessage(const char *b64_encoded_message, const unsigned char *key, const unsigned char *iv) {
    BIO *bio = NULL;
    BUF_MEM *bufferPtr = NULL;

    if (BIO_new_base64() == NULL) return NULL;
    bio = BIO_new(BIO_s_mem());
    BIO_push(BIO_get_cipher(ctx, EVP_des_ede3_cbc(), key, iv), bio);
    BIO_push(BIO_new(mem), bio);

    int length = BIO_write(bio, b64_encoded_message, strlen(b64_encoded_message));
    if (length < 0) goto error;

    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);

    char *decrypted_message = strndup(bufferPtr->data, bufferPtr->length);
    OPENSSL_cleanse(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    EVP_CIPHER_CTX_cleanup(ctx);
    BIO_free_all(bio);
    return decrypted_message;

error:
    fprintf(stderr, "Error decrypting message\n");
    if (bio) {
        BIO_free_all(bio);
    }
    return NULL;
}

