    struct Record* next;
} Record;

// Define constants for the size of arrays and ranges
#define INITIAL_CAPACITY 10
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 1000
#define SHORT_FIELD_MIN -32768
#define SHORT_FIELD_MAX 32767
#define INT_FIELD_MIN -2147483648
#define INT_FIELD_MAX 2147483647
#define RANDOM_STRING_LENGTH 20

// Global variables for data structures and their current sizes
long* offsets;
int* keys;
Record** head_record;
time_t* event_timestamps;

size_t offset_count = 0, key_count = 0, record_count = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void resize_memory(void **array, size_t *capacity) {
    size_t new_capacity = (*capacity) * 2;
    void **new_array = realloc(*array, new_capacity * sizeof(**array));
    if (!new_array) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

void initialize_arrays(size_t initial_size) {
    offsets = malloc(initial_size * sizeof(long));
    keys = malloc(initial_size * sizeof(int));
    event_timestamps = malloc(initial_size * sizeof(time_t));

    if (!offsets || !keys || !event_timestamps) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void initialize_record_list(size_t initial_size) {
    head_record = malloc(initial_size * sizeof(Record*));
    for (size_t i = 0; i < initial_size; ++i)
        head_record[i] = NULL;

    if (!head_record) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void insert_record(size_t index, const char* string) {
    pthread_mutex_lock(&list_lock);

    // Dynamic resizing of arrays
    if (record_count == key_count && record_count >= offset_count) {
        resize_memory((void**)&keys, &key_count);
        resize_memory((void**)&offsets, &offset_count);
        resize_memory((void**)&event_timestamps, &event_timestamps);
    }

    // Create a new record
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list_lock);
        exit(EXIT_FAILURE);
    }

    // Initialize random fields
    srand(time(NULL) ^ (getpid() << 16));
    new_record->s_field = SHORT_FIELD_MIN + rand() % ((SHORT_FIELD_MAX - SHORT_FIELD_MIN) + 1);
    new_record->i_field = INT_FIELD_MIN + rand() % ((INT_FIELD_MAX - INT_FIELD_MIN) + 1);
    strncpy(new_record->c_array, string, RANDOM_STRING_LENGTH);

    // Calculate offset and key values
    keys[key_count] = KEY_RANGE_MIN + (rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1));
    if (key_count > 0)
        offsets[offset_count] = offsets[offset_count-1] + keys[key_count-1];
    else
        offsets[0] = keys[0];

    event_timestamps[event_count] = time(NULL);

    // Insert into linked list
    new_record->next = head_record[index % key_count];
    head_record[index % key_count] = new_record;

    record_count++;
    pthread_mutex_unlock(&list_lock);
}

void iterate_records(void (*callback)(Record*)) {
    pthread_mutex_lock(&list_lock);
    for (size_t i = 0; i < key_count; ++i) {
        Record* current = head_record[i];
        while (current) {
            callback(current);
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void free_memory() {
    // Free linked list
    for (size_t i = 0; i < key_count; ++i) {
        Record* current = head_record[i];
        while (current) {
            Record* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(head_record);
    free(offsets);
    free(keys);
    free(event_timestamps);
}

int main() {
    initialize_arrays(INITIAL_CAPACITY);
    initialize_record_list(INITIAL_CAPACITY);

    // Simulate inserting records
    for (size_t i = 0; i < 50; ++i) {
        char random_string[RANDOM_STRING_LENGTH + 1];
        for (int j = 0; j < RANDOM_STRING_LENGTH; ++j)
            random_string[j] = 'a' + rand() % 26;
        random_string[RANDOM_STRING_LENGTH] = '\0';
        insert_record(i, random_string);
    }

    // Iterate over records and perform a sample operation
    iterate_records([](Record* record) {
        printf("Short: %d, Int: %d, String: %s\n", record->s_field, record->i_field, record->c_array);
    });

    free_memory();
    return 0;
}
```

