```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

// Define record structure
typedef struct Record {
    short s;
    int i;
    float f;
    int timestamp;
} Record;

// Node for doubly linked list
typedef struct ListNode {
    Record data;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

// Linked list with thread-safe operations
typedef struct LinkedList {
    ListNode* head;
    ListNode* tail;
    pthread_rwlock_t lock;
} LinkedList;

// Memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    void** free_list;
    size_t free_count;
    size_t capacity;
    pthread_mutex_t mutex;
} MemoryPool;

// Initialize memory pool
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t initial_capacity) {
    pool->block_size = block_size;
    pool->capacity = initial_capacity;
    pool->free_count = 0;
    pool->free_list = malloc(sizeof(void*) * initial_capacity);
    pthread_mutex_init(&pool->mutex, NULL);
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->free_count > 0) {
        void** block = pool->free_list + --pool->free_count;
        pthread_mutex_unlock(&pool->mutex);
        return *block;
    }
    pthread_mutex_unlock(&pool->mutex);

    size_t new_capacity = pool->capacity * 2;
    void** new_free_list = realloc(pool->free_list, sizeof(void*) * new_capacity);

    if (new_free_list == NULL) {
        perror("Failed to expand memory pool");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&pool->mutex);
    for (size_t i = pool->capacity; i < new_capacity; ++i) {
        new_free_list[i] = malloc(pool->block_size);
    }
    pool->free_list = new_free_list;
    pool->capacity = new_capacity;

    void* block = new_free_list[pool->capacity - 1];
    pthread_mutex_unlock(&pool->mutex);

    return block;
}

// Free memory back to the pool
void free_to_pool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->free_count < pool->capacity) {
        pool->free_list[pool->free_count++] = ptr;
    } else {
        free(ptr); // Handle case where capacity is reached
    }
    pthread_mutex_unlock(&pool->mutex);
}

// Destroy memory pool
void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool->mutex);
}

// Initialize linked list
void init_linked_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_init(&list->lock, NULL);
}

// Add record to linked list
void add_record(LinkedList* list, Record data) {
    ListNode* node = (ListNode*)allocate_from_pool(pool);
    node->data = data;
    node->next = NULL;
    node->prev = list->tail;

    pthread_rwlock_wrlock(&list->lock);
    if (list->tail != NULL) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
    pthread_rwlock_unlock(&list->lock);
}

// Iterator for linked list
typedef struct ListIterator {
    ListNode* current;
} ListIterator;

ListIterator create_iterator(LinkedList* list) {
    ListIterator iter = { list->head };
    return iter;
}

int has_next(ListIterator* iter) {
    return iter->current != NULL;
}

Record next(ListIterator* iter) {
    Record data = iter->current->data;
    iter->current = iter->current->next;
    return data;
}

// Initialize offset and key arrays
void init_offset_key(int* offsets, int* keys, size_t size, const int range_start, const int range_end) {
    srand((unsigned)time(NULL) ^ (uintptr_t)getpid());
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        if (i > 0) {
            offsets[i] = offsets[i - 1] + keys[i - 1];
        } else {
            offsets[i] = keys[i];
        }
    }
}

// Populate records
void populate_records(Record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        records[i].s = rand() % SHRT_MAX;
        records[i].i = rand() % INT_MAX;
        records[i].f = (float)rand() / RAND_MAX * 100.0f;
        records[i].timestamp = time(NULL);
    }
}

// Function to manage memory and initialize data structures
void manage_records(size_t record_count, int offset_range_start, int offset_range_end, int key_range_start, int key_range_end) {
    MemoryPool pool;
    init_memory_pool(&pool, sizeof(Record), 10);

    LinkedList list;
    init_linked_list(&list);

    int* offsets = (int*)malloc(record_count * sizeof(int));
    int* keys = (int*)malloc(record_count * sizeof(int));

    init_offset_key(offsets, keys, record_count, key_range_start, key_range_end);

    Record* records = (Record*)allocate_from_pool(&pool);

    populate_records(records, record_count);

    for (size_t i = 0; i < record_count; ++i) {
        add_record(&list, records[i]);
    }

    // Iterate and print records
    ListIterator iter = create_iterator(&list);
    while (has_next(&iter)) {
        Record rec = next(&iter);
        printf("Record: %d, %f, %d\n", rec.s, rec.f, rec.timestamp);
    }

    // Clean up
    free(offsets);
    free(keys);
    destroy_memory_pool(&pool);

    pthread_rwlock_destroy(&list.lock);
}

int main() {
    manage_records(1000, 10, 20, 1, 100);
    return 0;
}
```

