    new_node->record = rec;
    new_node->next = NULL;
    return new_node;
}

// Free the linked list
void free_linked_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
}

// Initialize a dynamic array with initial capacity
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }

    arr->offset = calloc(initial_capacity, sizeof(long));
    arr->key = calloc(initial_capacity, sizeof(int));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

// Resize the dynamic array
int resize_dynamic_array(DynamicArray *arr, size_t new_capacity) {
    if (new_capacity <= arr->capacity) return -1;

    long *new_offset = realloc(arr->offset, new_capacity * sizeof(long));
    int *new_key = realloc(arr->key, new_capacity * sizeof(int));

    if (!new_offset || !new_key) {
        perror("Failed to resize dynamic array");
        free(new_offset);
        free(new_key);
        return -1;
    }

    arr->offset = new_offset;
    arr->key = new_key;
    arr->capacity = new_capacity;

    return 0;
}

// Insert a key and update offsets
void insert_key_and_update_offset(DynamicArray *arr, int key_value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2);
    }

    arr->key[arr->size] = key_value;
    arr->offset[arr->size] = (arr->size > 0) ? arr->offset[arr->size - 1] + key_value : key_value;

    arr->size++;
    pthread_mutex_unlock(&arr->lock);
}

// Process input and initialize data structures
void process_input_and_initialize() {
    int *numbers = NULL;
    size_t capacity = 10, size = 0;

    printf("Enter integers (type 'done' to finish):\n");
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (sscanf(buffer, "%d", &buffer) == 1) {
            if (size == capacity) {
                capacity *= 2;
                numbers = realloc(numbers, capacity * sizeof(int));
                if (!numbers) {
                    perror("Failed to reallocate memory for numbers");
                    exit(EXIT_FAILURE);
                }
            }
            numbers[size++] = buffer;
        } else if (strncmp(buffer, "done", 4) == 0) break;
    }

    // Process integers with threads
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_array, numbers);
    pthread_join(thread_id, NULL);

    // Find the largest integer in the array
    int largest = find_largest_integer(numbers, size);
    printf("Largest integer: %d\n", largest);

    free(numbers);
}

// Process the array of integers
void* process_array(void* args) {
    int *numbers = (int*)args;
    DynamicArray *arr = init_dynamic_array(10);

    for (size_t i = 0; i < size; ++i) {
        insert_key_and_update_offset(arr, numbers[i]);
    }

    free(arr->key);
    free(arr->offset);
    pthread_mutex_destroy(&arr->lock);
    free(arr);

    return NULL;
}

// Find the largest integer in an array
int find_largest_integer(int *array, size_t n) {
    int max = array[0];
    for (size_t i = 1; i < n; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int main() {
    srand(time(NULL));
    process_input_and_initialize();
    return 0;
}
