#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PROFILES 1000
#define MAX_POSTS 100
#define NAME_LEN 50
#define POST_TEXT_LEN 256

typedef struct {
    char content[POST_TEXT_LEN];
    time_t timestamp;
} Post;

typedef struct {
    char name[NAME_LEN];
    int age;
    char email[NAME_LEN];
    Post *posts;
    size_t post_count;
} UserProfile;

typedef struct {
    UserProfile *profiles;
    size_t profile_count;
    pthread_mutex_t lock;
} ProfileManager;

// Random number generator
int random_age(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to initialize a new post with random content and current timestamp
void init_post(Post *post) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < POST_TEXT_LEN - 1; i++) {
        int key = rand() % (sizeof(charset) - 1);
        post->content[i] = charset[key];
    }
    post->content[POST_TEXT_LEN - 1] = '\0';
    post->timestamp = time(NULL);
}

// Initialize a new user profile
UserProfile* create_profile(const char *name, const char *email) {
    UserProfile *profile = (UserProfile *)malloc(sizeof(UserProfile));
    strncpy(profile->name, name, NAME_LEN);
    profile->name[NAME_LEN - 1] = '\0';
    profile->age = random_age(18, 99);
    strncpy(profile->email, email, NAME_LEN);
    profile->email[NAME_LEN - 1] = '\0';
    profile->posts = NULL;
    profile->post_count = 0;
    return profile;
}

// Add a post to a user profile
void add_post(UserProfile *profile) {
    Post *new_posts = (Post *)realloc(profile->posts, sizeof(Post) * (profile->post_count + 1));
    if (new_posts) {
        profile->posts = new_posts;
        init_post(&profile->posts[profile->post_count]);
        profile->post_count++;
    }
}

// Search profiles by name or age
UserProfile* search_profile(ProfileManager *manager, const char *name, int age) {
    for (size_t i = 0; i < manager->profile_count; i++) {
        if ((strcmp(manager->profiles[i].name, name) == 0 || manager->profiles[i].age == age)) {
            return &manager->profiles[i];
        }
    }
    return NULL;
}

// Initialize the profile manager
void init_manager(ProfileManager *manager) {
    manager->profiles = (UserProfile *)malloc(MAX_PROFILES * sizeof(UserProfile));
    manager->profile_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add a new profile to the manager
void add_profile(ProfileManager *manager, const char *name, const char *email) {
    pthread_mutex_lock(&manager->lock);
    if (manager->profile_count < MAX_PROFILES) {
        UserProfile *profile = create_profile(name, email);
        manager->profiles[manager->profile_count++] = *profile;
        free(profile);
    }
    pthread_mutex_unlock(&manager->lock);
}

// Delete a profile by name
void delete_profile(ProfileManager *manager, const char *name) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->profile_count; i++) {
        if (strcmp(manager->profiles[i].name, name) == 0) {
            free(manager->profiles[i].posts);
            memmove(&manager->profiles[i], &manager->profiles[i + 1], sizeof(UserProfile) * (manager->profile_count - i - 1));
            manager->profile_count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Export profiles to a file
void export_profiles(ProfileManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file) {
        for (size_t i = 0; i < manager->profile_count; i++) {
            fprintf(file, "Name: %s, Age: %d, Email: %s\n", manager->profiles[i].name, manager->profiles[i].age, manager->profiles[i].email);
            for (size_t j = 0; j < manager->profiles[i].post_count; j++) {
                fprintf(file, "Post: %s at %ld\n", manager->profiles[i].posts[j].content, manager->profiles[i].posts[j].timestamp);
            }
        }
        fclose(file);
    }
}

// Cleanup the profile manager
void cleanup_manager(ProfileManager *manager) {
    for (size_t i = 0; i < manager->profile_count; i++) {
        free(manager->profiles[i].posts);
    }
    free(manager->profiles);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL));

    ProfileManager manager;
    init_manager(&manager);

    add_profile(&manager, "Alice", "alice@example.com");
    UserProfile *profile = search_profile(&manager, "Alice", 0);
    if (profile) {
        add_post(profile);
    }

    export_profiles(&manager, "profiles.txt");

    delete_profile(&manager, "Alice");
    cleanup_manager(&manager);

    return 0;
}
```

