    return mp;
}

void free_memory_pool(memory_pool* mp) {
    if (mp) {
        free(mp->pool);
        free(mp);
    }
}

long* allocate_array_with_initial_values(int count, size_t element_size) {
    long* arr = (long*)malloc(count * element_size);
    if (!arr) return NULL;

    // Initialize with cumulative sums and constant factor
    for (int i = 0; i < count; ++i) {
        arr[i] = i * 100 + (i == 0 ? 0 : arr[i - 1]); // Example initialization
    }
    return arr;
}

int* allocate_int_array(int count) {
    int* arr = (int*)malloc(count * sizeof(int));
    if (!arr) return NULL;

    for (int i = 0; i < count; ++i) {
        arr[i] = i + 1; // Example initialization
    }
    return arr;
}

record* create_linked_list(int record_count) {
    record* head = NULL, *current = NULL;
    pthread_mutex_t list_lock;

    if (pthread_mutex_init(&list_lock, NULL) != 0) return NULL;

    for (int i = 0; i < record_count; ++i) {
        record* new_record = (record*)malloc(sizeof(record));
        if (!new_record) continue;

        new_record->s = rand() % 100;
        new_record->i = rand() % 10000;
        new_record->f = (float)(rand()) / RAND_MAX * 100.0;

        pthread_mutex_lock(&list_lock);
        new_record->next = head;
        head = new_record;
        current = head; // Simplified, assumes single-threaded addition
        pthread_mutex_unlock(&list_lock);
    }

    return head;
}

data_manager* initialize_data_manager(int offset_count, int key_count, int record_count) {
    data_manager* dm = (data_manager*)malloc(sizeof(data_manager));
    if (!dm) return NULL;

    // Initialize mutexes and atomic variables
    pthread_mutex_init(&dm->offset_lock, NULL);
    pthread_mutex_init(&dm->key_lock, NULL);
    pthread_mutex_init(&dm->record_lock, NULL);
    pthread_mutex_init(&dm->resize_lock, NULL);

    dm->offsets = allocate_array_with_initial_values(offset_count, sizeof(long));
    dm->keys = allocate_int_array(key_count);
    dm->head_record = create_linked_list(record_count);

    atomic_store(&dm->offset_count, offset_count);
    atomic_store(&dm->key_count, key_count);
    atomic_store(&dm->record_count, record_count);

    return dm;
}

void resize_arrays(data_manager* dm, int new_offset_count, int new_key_count) {
    pthread_mutex_lock(&dm->resize_lock);

    // Resize logic
    long* new_offsets = allocate_array_with_initial_values(new_offset_count, sizeof(long));
    if (new_offsets) {
        memcpy(new_offsets, dm->offsets, atomic_load(&dm->offset_count) * sizeof(long));
        free(dm->offsets);
        dm->offsets = new_offsets;
    }

    int* new_keys = allocate_int_array(new_key_count);
    if (new_keys) {
        memcpy(new_keys, dm->keys, atomic_load(&dm->key_count) * sizeof(int));
        free(dm->keys);
        dm->keys = new_keys;
    }

    pthread_mutex_unlock(&dm->resize_lock);
}

void populate_data_structures(data_manager* dm, int factor) {
    pthread_mutex_lock(&dm->offset_lock);
    for (int i = 0; i < atomic_load(&dm->offset_count); ++i) {
        dm->offsets[i] += factor;
    }
    pthread_mutex_unlock(&dm->offset_lock);

    pthread_mutex_lock(&dm->key_lock);
    for (int i = 1; i < atomic_load(&dm->key_count); ++i) {
        dm->keys[i] += factor * i;
    }
    pthread_mutex_unlock(&dm->key_lock);
}

// Usage example
int main() {
    srand(time(NULL)); // Seed the random number generator

    int offset_count = 10, key_count = 10, record_count = 5;
    data_manager* dm = initialize_data_manager(offset_count, key_count, record_count);

    populate_data_structures(dm, 42); // Example factor
    resize_arrays(dm, 20, 20); // Example resizing

    // Clean up resources (not fully implemented for brevity)
    pthread_mutex_destroy(&dm->offset_lock);
    pthread_mutex_destroy(&dm->key_lock);
    pthread_mutex_destroy(&dm->record_lock);
    pthread_mutex_destroy(&dm->resize_lock);

    free(dm->offsets);
    free(dm->keys);

    // Free linked list records
    record* current = dm->head_record;
    while (current) {
        record* next = current->next;
        free(current);
        current = next;
    }

    free(dm);

    return 0;
}
