typedef struct Entry {
    int key;
    long offset;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct ThreadSafeList {
    Node* head;
    pthread_mutex_t mutex;
} ThreadSafeList;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

ThreadSafeList* create_list() {
    ThreadSafeList* list = malloc(sizeof(ThreadSafeList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list.\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void lock_list(ThreadSafeList* list) {
    pthread_mutex_lock(&list->mutex);
}

void unlock_list(ThreadSafeList* list) {
    pthread_mutex_unlock(&list->mutex);
}

void destroy_node(Node* node) {
    free(node);
}

void clear_list(ThreadSafeList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    list->head = NULL;
}

void destroy_list(ThreadSafeList* list) {
    clear_list(list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

Node* create_node(int key, long offset) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for node.\n");
        exit(EXIT_FAILURE);
    }
    node->entry.key = key;
    node->entry.offset = offset;
    node->next = NULL;
    return node;
}

void add_entry(ThreadSafeList* list, int key, long offset) {
    lock_list(list);

    Node* new_node = create_node(key, offset);
    new_node->next = list->head;
    list->head = new_node;

    unlock_list(list);
}

Entry* get_first_entry(ThreadSafeList* list) {
    lock_list(list);

    if (!list->head) {
        unlock_list(list);
        return NULL;
    }

    Entry* entry = &list->head->entry;
    unlock_list(list);
    return entry;
}

void initialize_collection(int num_entries, int key_min, int key_max) {
    if (num_entries <= 0 || key_min > key_max) {
        fprintf(stderr, "Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

    ThreadSafeList* list = create_list();
    initialize_random();

    for (int i = 0; i < num_entries; ++i) {
        int key = random_int(key_min, key_max);
        long offset = rand() % ((1L << 31) - 1); // Random offset value
        add_entry(list, key, offset);
    }

    Entry* entry = get_first_entry(list);
    if (entry) {
        printf("First entry: Key=%d, Offset=%ld\n", entry->key, entry->offset);
    }

    destroy_list(list);
}

int main() {
    initialize_collection(1000, 1, 10000);
    return 0;
}
