    if (pool->keys) free(pool->keys);
    if (pool->records) free(pool->records);
}

DataStructureManager* initialize_data_structures(size_t num_offsets, size_t num_keys, size_t num_records) {
    if (!num_offsets && !num_keys && !num_records) return NULL;

    DataStructureManager *manager = malloc(sizeof(DataStructureManager));
    if (!manager) return (void*)ERROR_CODE;

    pthread_mutex_init(&manager->lock, NULL);
    manager->pool.num_offsets = num_offsets;
    manager->pool.num_keys = num_keys;
    manager->pool.num_records = num_records;

    size_t total_size = num_offsets + num_keys + num_records;
    if (total_size > MAX_POOL_SIZE) {
        free(manager);
        return (void*)ERROR_CODE;
    }

    manager->max_pool_size = MAX_POOL_SIZE;
    manager->used_slots = total_size;

    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    void **records = malloc(num_records * sizeof(void*));

    if (!offsets || !keys || !records) {
        free_memory(&manager->pool);
        free(manager);
        return (void*)ERROR_CODE;
    }

    long used_offsets[num_offsets] = {0};
    int used_keys[num_keys] = {0};

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = generate_unique_offset(used_offsets, num_offsets);
        // Ensure uniqueness logic here
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = generate_unique_key(used_keys, num_keys);
        // Ensure uniqueness and collision handling here
    }

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(int)); // Assuming `record` is just an int for simplicity
        if (!records[i]) {
            free_memory(&manager->pool);
            pthread_mutex_unlock(&manager->lock);
            free(manager);
            return (void*)ERROR_CODE;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    manager->pool.offsets = offsets;
    manager->pool.keys = keys;
    manager->pool.records = records;

    return manager;
}

// Cleanup function to be called when done with the data structures
void cleanup_data_structures(DataStructureManager *manager) {
    if (manager) {
        free_memory(&manager->pool);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
