long* allocate_offsets() {
    long *offsets = (long*)malloc(OFFSET_COUNT * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return NULL;
    }
    return offsets;
}

int* allocate_unique_keys() {
