    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return NULL;
    }
    return keys;
}

Record* allocate_records(size_t record_count) {
    Record *records = (Record*)malloc(record_count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = NULL;
        records[i].valid = '\0';
        records[i].status = FREE;
    }
    return records;
}

int is_within_int_bounds(int value) {
    return value >= INT_MIN && value <= INT_MAX;
}

