    long *offsets = allocate_offsets();
    if (!offsets) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int *keys = allocate_unique_keys();
    if (!keys) {
        free(offsets);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

