#define INT_RANGE_HIGH 1000
#define OFFSET_CONSTANT 42

typedef struct Record {
    unsigned short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

int dns_resolve(const char *domain) {
    struct hostent *host_info;
    if ((host_info = gethostbyname(domain)) == NULL) {
        herror("DNS resolution");
        return -1;
    }
    printf("Domain %s resolved to IP: %s\n", domain, inet_ntoa(*(struct in_addr*)*host_info->h_addr_list));
    return 0;
}

void *process_domain(void *arg) {
    char *domain = (char *)arg;
    dns_resolve(domain);
    free(arg);
    pthread_exit(NULL);
}

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void lock_free_insert(Record data) {
    Node *old_head = head, *new_node = create_node(data);
    while (1) {
        __sync_bool_compare_and_swap(&head, old_head, new_node);
        if (old_head == head) break;
        free(new_node);
        old_node = head;
        new_node->next = old_head;
    }
}

void generate_records() {
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < NUM_RECORDS; ++i) {
        Record rec;
        rec.s = rand() % (SHORT_RANGE_HIGH - SHORT_RANGE_LOW + 1) + SHORT_RANGE_LOW;
        rec.i = rand() % (INT_RANGE_HIGH - INT_RANGE_LOW + 1) + INT_RANGE_LOW;

        int key = rand() % (KEY_RANGE_HIGH - KEY_RANGE_LOW + 1) + KEY_RANGE_LOW;
        float offset = OFFSET_CONSTANT;
        if (i > 0) {
            Node* current = head;
            while (current->next != NULL) {
                offset += current->data.i; // Assuming 'key' is stored in `i`
                current = current->next;
            }
        }
        rec.f = offset + key;

        lock_free_insert(rec);

        char domain[MAX_DOMAIN_LENGTH];
        snprintf(domain, sizeof(domain), "example%d.com", i);
        pthread_create(&threads[i % MAX_THREADS], NULL, process_domain, strdup(domain));

        if (i % MAX_THREADS == MAX_THREADS - 1) {
            for (int j = 0; j < MAX_THREADS; ++j) {
                pthread_join(threads[j], NULL);
            }
        }
    }

    for (int i = 0; i < NUM_RECORDS % MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_list() {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("File opening failed");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        pthread_create(NULL, NULL, process_domain, strdup(line));
    }
    free(line);
    fclose(file);

    generate_records();
    free_list();

    return EXIT_SUCCESS;
}
```

### Key Points:

- **DNS Resolution**: Uses `gethostbyname` for DNS resolution and handles errors gracefully.
- **Concurrency**: Employs threads to handle domain resolution concurrently. Each thread processes a line from the file.
- **Lock-Free Linked List**: Implements a simple lock-free insertion mechanism using atomic operations.
- **Record Generation**: Generates records with random values, calculating `offset[i]` as specified.
- **Memory Management**: Dynamically allocates and frees memory to prevent leaks.
- **Error Handling**: Includes basic error handling for file operations and DNS resolution.']

