Node* initializeLinkedList() {
    int totalNodes = MAX_NODES;
    int nodesAllocated = 0;
    Node *head = NULL, **tailPtr = &head;

    while (nodesAllocated < totalNodes) {
        size_t currentChunkSize = ((totalNodes - nodesAllocated) > CHUNK_SIZE) ? CHUNK_SIZE : (totalNodes - nodesAllocated);
        for (size_t i = 0; i < currentChunkSize; ++i, ++nodesAllocated) {
            Node *newNode = (Node *)malloc(sizeof(Node));
            if (!newNode) {
                // Handle memory allocation failure gracefully
                while (*tailPtr != NULL) {
                    Node *temp = *tailPtr;
                    *tailPtr = (*tailPtr)->next;
                    free(temp);
                }
                return NULL;
            }

            newNode->value = (double)nodesAllocated;
            newNode->identifier = '?'; // Default invalid identifier
            newNode->next = NULL;

            *tailPtr = newNode;
            tailPtr = &newNode->next;
        }
    }

    Node *current = head;
    for (int i = 0; current != NULL && i < totalNodes; ++i) {
        char newIdentifier = updateIdentifier(i);
        if (newIdentifier != '?') {
            current->identifier = newIdentifier;
        } else {
            // Handle invalid identifier
            fprintf(stderr, "Warning: Invalid identifier for node %d\n", i);
        }
        current = current->next;
    }

    return head;
}

void freeLinkedList(Node *head) {
