#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

typedef struct Entry {
    int key;
    long offset;
    struct Entry* next;
} Entry;

typedef struct {
    Entry* head;
    pthread_mutex_t lock;
    size_t count;
    const size_t max_entries;
} Collection;

void initialize_collection(Collection* collection, size_t initial_capacity) {
    if (!collection || initial_capacity == 0) return;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;
    collection->max_entries = initial_capacity;
}

static Entry* create_entry(int key, long offset) {
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return NULL;

    new_entry->key = key;
    new_entry->offset = offset;
    new_entry->next = NULL;
    return new_entry;
}

static void free_collection(Collection* collection) {
    if (!collection) return;

    Entry* current = collection->head;
    while (current) {
        Entry* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&collection->lock);
}

int add_entry(Collection* collection, int key_range_start, int key_range_end) {
    if (!collection || key_range_start >= key_range_end) return -1;

    srand(time(NULL));
    int new_key = rand() % (key_range_end - key_range_start) + key_range_start;

    Entry* new_entry = create_entry(new_key, rand());
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for a new entry.\n");
        return -1;
    }

    pthread_mutex_lock(&collection->lock);
    if (collection->count < collection->max_entries) {
        new_entry->next = collection->head;
        collection->head = new_entry;
        collection->count++;
    } else {
        free(new_entry); // No space left, discard the entry
    }
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

long get_offset(Collection* collection, int key) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->lock);
    Entry* current = collection->head;
    while (current) {
        if (current->key == key) {
            pthread_mutex_unlock(&collection->lock);
            return current->offset;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);

    return -1; // Key not found
}

void* update_entries_from_source(void* arg) {
    Collection* collection = (Collection*)arg;

    while (1) { // Simulate periodic updates
        sleep(5); // Wait for 5 seconds

        pthread_mutex_lock(&collection->lock);
        Entry* current = collection->head;
        while (current) {
            // Simulating update from an external data source
            current->offset += rand();
            current = current->next;
        }
        pthread_mutex_unlock(&collection->lock);

        printf("Entries updated from external source.\n");
    }

    return NULL;
}

int main() {
    Collection collection;
    initialize_collection(&collection, 100); // Initial capacity of 100

    for (int i = 0; i < 200; i++) { // Attempt to add more entries than initial capacity
        if (add_entry(&collection, 0, 100) == -1) {
            fprintf(stderr, "Failed to add entry.\n");
        }
    }

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, update_entries_from_source, &collection);

    // Simulate some operations
    sleep(15); 

    free_collection(&collection);
    return 0;
}
```

This code provides a basic implementation of the task requirements. It uses a mutex to ensure thread safety when adding and retrieving entries. The collection automatically grows by allowing multiple threads to add new entries without blocking each other unnecessarily, as long as memory allocation is successful. The `update_entries_from_source` function simulates periodic updates from an external source. Note that this code doesn't handle all edge cases or optimizations for large-scale use but serves as a foundation to build upon. Further improvements could include using more advanced concurrency mechanisms (like read-write locks or lock-free data structures) and integrating with real external sources.']

