#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_IP_LENGTH 16
#define BUFFER_SIZE 1024

typedef struct {
    char sourceIP[MAX_IP_LENGTH];
    char destinationIP[MAX_IP_LENGTH];
    char protocolType[10];
    time_t lastUpdate;
} TrafficFlow;

TrafficFlow *traffic_flows = NULL;
size_t flow_count = 0;
size_t allocated_size = 0;

void add_flow(const char *source, const char *dest, const char *protocol) {
    if (flow_count == allocated_size) {
        size_t new_size = (allocated_size == 0) ? 10 : allocated_size * 2;
        traffic_flows = realloc(traffic_flows, new_size * sizeof(TrafficFlow));
        if (!traffic_flows) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        allocated_size = new_size;
    }

    TrafficFlow *flow = &traffic_flows[flow_count++];
    strncpy(flow->sourceIP, source, MAX_IP_LENGTH - 1);
    strncpy(flow->destinationIP, dest, MAX_IP_LENGTH - 1);
    strncpy(flow->protocolType, protocol, sizeof(flow->protocolType) - 1);
    flow->lastUpdate = time(NULL);
}

void remove_flow(const char *ip_address) {
    for (size_t i = 0; i < flow_count; ++i) {
        if ((strcmp(traffic_flows[i].sourceIP, ip_address) == 0) ||
            (strcmp(traffic_flows[i].destinationIP, ip_address) == 0)) {

            memmove(&traffic_flows[i], &traffic_flows[i + 1],
                    (flow_count - i - 1) * sizeof(TrafficFlow));
            --flow_count;
            break; // Remove one match at a time
        }
    }
}

size_t query_protocol_flow_count(const char *protocol) {
    size_t count = 0;
    for (size_t i = 0; i < flow_count; ++i) {
        if (strcmp(traffic_flows[i].protocolType, protocol) == 0) {
            ++count;
        }
    }
    return count;
}

void batch_delete_inactive_flows() {
    time_t current_time = time(NULL);
    size_t new_flow_count = 0;

    for (size_t i = 0; i < flow_count; ++i) {
        if (difftime(current_time, traffic_flows[i].lastUpdate) <= 86400) { // 24 hours in seconds
            traffic_flows[new_flow_count++] = traffic_flows[i];
        }
    }

    flow_count = new_flow_count;
}

void processTrafficAndGenerateReport(const char *traffic_log_path,
                                     const char *report_output_path,
                                     const char *integration_tool_path) {
    FILE *log_file = fopen(traffic_log_path, "r");
    if (!log_file) {
        perror("Failed to open traffic log file");
        exit(EXIT_FAILURE);
    }

    char line[BUFFER_SIZE];
    while (fgets(line, sizeof(line), log_file)) {
        char sourceIP[MAX_IP_LENGTH], destinationIP[MAX_IP_LENGTH], protocolType[10];
        if (sscanf(line, "%15[^,],%15[^,],%9s", sourceIP, destinationIP, protocolType) == 3) {
            add_flow(sourceIP, destinationIP, protocolType);
        }
    }

    fclose(log_file);

    batch_delete_inactive_flows();

    FILE *report_file = fopen(report_output_path, "w");
    if (!report_file) {
        perror("Failed to open report output file");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < flow_count; ++i) {
        fprintf(report_file, "%s,%s,%s\n", traffic_flows[i].sourceIP,
                traffic_flows[i].destinationIP, traffic_flows[i].protocolType);
    }

    fclose(report_file);

    // Integration with third-party tool
    char command[BUFFER_SIZE];
    snprintf(command, sizeof(command), "%s %s", integration_tool_path, report_output_path);
    if (system(command) != 0) {
        fprintf(stderr, "Failed to execute integration tool\n");
    }
}

int main() {
    // Example usage of the function
    processTrafficAndGenerateReport("traffic_log.txt", "report_output.txt", "integration_tool");

    free(traffic_flows);
    return 0;
}
