#include <time.h>

typedef struct {
    long timestamp;
    int unique_id;
    long offsets[10];
} Record;

int is_unique(int id, Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].unique_id == id) {
            return 0;
        }
    }
    return 1;
}

void populate_record(Record *record) {
    record->timestamp = time(NULL);
    int unique_found = 0;
    while (!unique_found) {
        record->unique_id = rand() % 10000; // Adjust range as needed
        if (is_unique(record->unique_id, records, count)) {
            unique_found = 1;
        }
    }
    for (int i = 0; i < 10; ++i) {
        record->offsets[i] = rand() % 1000000; // Adjust range as needed
    }
}

void manage_records(size_t num_records, Record **records_out) {
    *records_out = malloc(num_records * sizeof(Record));
    if (!*records_out) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_records; ++i) {
        populate_record(&((*records_out)[i]));
    }
}

void free_records(Record *records) {
    free(records);
}
