<?php

function fetchUserData($userId) {
    $apiUrl = "https://api.example.com/users/$userId";

    try {
        $response = file_get_contents($apiUrl, false, stream_context_create([
            'http' => [
                'timeout' => 2 // Timeout in seconds
            ]
        ]));

        if ($response === FALSE) {
            throw new Exception("API request failed");
        }

        return json_decode($response, true);
    } catch (Exception $e) {
        error_log("Error fetching user data: " . $e->getMessage());
        return null;
    }
}

function updatePassword($userId, $newPassword) {
    if (!passwordStrengthValid($newPassword)) {
        throw new Exception("Password does not meet complexity requirements");
    }

    $userData = fetchUserData($userId);
    if (!$userData) {
        throw new Exception("Unable to fetch user data for password update");
    }

    try {
        // Database connection and query execution
        $pdo = new PDO('mysql:host=localhost;dbname=testdb', 'username', 'password');
        $stmt = $pdo->prepare("UPDATE users SET password = :password WHERE id = :id");

        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
        $stmt->execute([':password' => $hashedPassword, ':id' => $userId]);

        return true;
    } catch (PDOException $e) {
        error_log("Database update failed: " . $e->getMessage());
        return false;
    }
}

function passwordStrengthValid($password) {
    // Example validation: min 8 characters, include letters and numbers
    return strlen($password) >= 8 && preg_match('/[A-Za-z]/', $password) && preg_match('/\d/', $password);
}
