#define CONFIG_KEY_RANGE_MIN 1000
#define CONFIG_KEY_RANGE_MAX 9999

typedef struct Record {
    short sField;
    int iField;
    float fField;
    char cArray[64];
    uint8_t binaryData[MAX_BINARY_SIZE];
    size_t binarySize;
    time_t eventTimestamp;
} Record;

typedef struct Node {
    Record *record;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
    int size;
    int capacity;
    int *offsets;
    int *keys;
    int dataSizeArrayCapacity;
    uint8_t compressionFlagsArrayCapacity;
    time_t *eventTimestampArrayCapacity;
} RecordList;

RecordList* create_record_list() {
    RecordList *list = malloc(sizeof(RecordList));
    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = INITIAL_ARRAY_SIZE;
    list->offsets = malloc(list->capacity * sizeof(int));
    list->keys = malloc(list->capacity * sizeof(int));
    list->dataSizeArrayCapacity = malloc(list->capacity * sizeof(size_t));
    list->compressionFlagsArrayCapacity = malloc(list->capacity * sizeof(uint8_t));
    list->eventTimestampArrayCapacity = malloc(list->capacity * sizeof(time_t));
    return list;
}

void resize_record_list(RecordList *list) {
    int new_capacity = list->capacity * 2;
    int *new_offsets = realloc(list->offsets, new_capacity * sizeof(int));
    int *new_keys = realloc(list->keys, new_capacity * sizeof(int));
    size_t *new_dataSizeArrayCapacity = realloc(list->dataSizeArrayCapacity, new_capacity * sizeof(size_t));
    uint8_t *new_compressionFlagsArrayCapacity = realloc(list->compressionFlagsArrayCapacity, new_capacity * sizeof(uint8_t));
    time_t *new_eventTimestampArrayCapacity = realloc(list->eventTimestampArrayCapacity, new_capacity * sizeof(time_t));

    if (new_offsets && new_keys && new_dataSizeArrayCapacity && 
        new_compressionFlagsArrayCapacity && new_eventTimestampArrayCapacity) {
        list->offsets = new_offsets;
        list->keys = new_keys;
        list->dataSizeArrayCapacity = new_dataSizeArrayCapacity;
        list->compressionFlagsArrayCapacity = new_compressionFlagsArrayCapacity;
        list->eventTimestampArrayCapacity = new_eventTimestampArrayCapacity;
        list->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize record list\n");
        exit(EXIT_FAILURE);
    }
}

int generate_unique_key(int *keys, int size, int min_range, int max_range) {
    int key;
    do {
        key = rand() % (max_range - min_range + 1) + min_range;
    } while (contains(keys, size, key));
    return key;
}

int contains(int *array, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (array[i] == value) {
            return 1;
        }
    }
    return 0;
}

void insert_record(RecordList *list, Record *record) {
    if (list->size >= list->capacity) {
        resize_record_list(list);
    }

    Node *new_node = malloc(sizeof(Node));
    new_node->record = record;

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    int offset_sum = 0;
    for (int i = 0; i < list->size; ++i) {
        list->offsets[i] = offset_sum;
        offset_sum += list->keys[i];
    }
    list->offsets[list->size] = offset_sum;

    record->eventTimestamp = time(NULL);
    list->eventTimestampArrayCapacity[list->size] = record->eventTimestamp;

    int key = generate_unique_key(list->keys, list->size, CONFIG_KEY_RANGE_MIN, CONFIG_KEY_RANGE_MAX);
    list->keys[list->size] = key;

    list->dataSizeArrayCapacity[list->size] = record->binarySize;
    list->compressionFlagsArrayCapacity[list->size] = 0; // Placeholder for compression flag

    list->size++;
}

void free_record_list(RecordList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->record);
        free(current);
        current = next;
    }
    free(list->offsets);
    free(list->keys);
    free(list->dataSizeArrayCapacity);
    free(list->compressionFlagsArrayCapacity);
    free(list->eventTimestampArrayCapacity);
    free(list);
}

void log_event_timestamp(time_t timestamp) {
    // Placeholder for logging mechanism
    printf("Logging event at timestamp: %ld\n", timestamp);
}

void initialize_record(Record *record, size_t binarySize) {
    record->sField = rand() % 100;
    record->iField = rand() % 1000;
    record->fField = (float)rand() / RAND_MAX * 100.0;
    for (int i = 0; i < 64; ++i) {
        record->cArray[i] = 'A' + rand() % 26;
    }
    memset(record->binaryData, rand() % 256, binarySize);
    record->binarySize = binarySize;
}

void simulate_record_insertion(RecordList *list, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(Record));
        size_t binary_size = rand() % MAX_BINARY_SIZE + 1;
        initialize_record(record, binary_size);
        insert_record(list, record);
        log_event_timestamp(record->eventTimestamp);
    }
}

int main() {
    srand(time(NULL));

    RecordList *list = create_record_list();
    simulate_record_insertion(list, 50);

    // Clean up
    free_record_list(list);

    return 0;
}
```

This code implements a dynamic data structure using a doubly linked list to manage records. Each record contains various fields and is initialized with random values. The list can dynamically resize itself when necessary, and it includes mechanisms for efficient traversal and memory management. Additionally, timestamps are logged, simulating an external event capture system.']

