#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define MAC_RX_CONTEXT_T structure with a placeholder for MAC_RX_OBJECT_T link
typedef struct {
    void* mac_rx_object;  // Pointer to corresponding MAC_RX_OBJECT_T
    int state;            // State of the context (e.g., INIT, ACTIVE, DEINIT)
    pthread_mutex_t lock; // Mutex for thread-safe access
} MAC_RX_CONTEXT_T;

// Define an enum for state transitions
typedef enum {
    STATE_INIT,
    STATE_ACTIVE,
    STATE_DEINIT
} ContextState;

// Initialize a dynamic array of MAC_RX_CONTEXT_T structures
MAC_RX_CONTEXT_T* init_mac_rx_context_array(size_t count) {
    if (count == 0) return NULL;

    // Allocate memory for the context array
    MAC_RX_CONTEXT_T* contexts = (MAC_RX_CONTEXT_T*)malloc(count * sizeof(MAC_RX_CONTEXT_T));
    if (!contexts) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t init_lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize each context and its corresponding MAC_RX_OBJECT_T
    for (size_t i = 0; i < count; ++i) {
        contexts[i].mac_rx_object = malloc(sizeof(void*));  // Example allocation
        if (!contexts[i].mac_rx_object) {
            fprintf(stderr, "Memory allocation failed for mac_rx_object at index %zu\n", i);
            free(contexts);  // Free previously allocated memory
            return NULL;
        }

        pthread_mutex_init(&contexts[i].lock, NULL);
        contexts[i].state = STATE_INIT;

        // Log context creation
        printf("Context %zu created and initialized.\n", i);
    }

    printf("All contexts initialized successfully.\n");

    return contexts;
}

// Function to safely transition the state of a MAC_RX_CONTEXT_T instance
void set_context_state(MAC_RX_CONTEXT_T* context, ContextState new_state) {
    if (!context) return;

    pthread_mutex_lock(&context->lock);

    // Log state transition
    printf("Transitioning context from state %d to %d.\n", context->state, new_state);

    context->state = new_state;
    pthread_mutex_unlock(&context->lock);
}

// Function to deinitialize and free the array of MAC_RX_CONTEXT_T structures
void deinit_mac_rx_context_array(MAC_RX_CONTEXT_T* contexts, size_t count) {
    if (!contexts) return;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&contexts[i].lock);

        // Log context destruction
        printf("Destroying context %zu.\n", i);

        free(contexts[i].mac_rx_object);
        pthread_mutex_unlock(&contexts[i].lock);
        pthread_mutex_destroy(&contexts[i].lock);
    }

    free(contexts);
}

// Function to query the state of a MAC_RX_CONTEXT_T instance
ContextState get_context_state(const MAC_RX_CONTEXT_T* context) {
    if (!context) return -1;

    // Ensure non-blocking access using lock-free read (assuming single-writer scenario)
    return context->state;
}
```

### Key Features:
- **Thread Safety**: Uses mutex locks to ensure that state transitions and other operations on `MAC_RX_CONTEXT_T` instances are thread-safe.
- **Dynamic Memory Management**: Efficiently allocates memory for both the array of contexts and individual `mac_rx_object` pointers, with checks for allocation failures.
- **State Management**: Implements a simple state machine using an enum to manage context states.
- **Logging**: Provides logging via standard output. In real-world applications, you might want to replace it with a more sophisticated logging mechanism optimized for performance.
- **Scalability**: The code is structured to handle multiple contexts efficiently while minimizing the memory footprint by careful management of allocated resources.']

