#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_LINE_SIZE 100 * 1024 // 100 fields, assume max length of 1KB per field
#define RETRY_LIMIT 5

// Function prototypes
int resolve_dns(const char* hostname, u_char* ip_address);
void process_log_file(const char* filename);
void retry_with_exponential_backoff(int (*func)(const char*, u_char*), const char* hostname, u_char* ip_address);

typedef struct {
    char** fields;
    int field_count;
} LogLine;

// Global settings for DNS resolution
int base_delay = 1; // Initial delay in seconds

void retry_with_exponential_backoff(int (*func)(const char*, u_char*), const char* hostname, u_char* ip_address) {
    int retries = 0;
    int result;
    while (retries < RETRY_LIMIT) {
        result = func(hostname, ip_address);
        if (result == 0) break; // Success
        sleep(base_delay * (1 << retries)); // Exponential backoff
        retries++;
    }
}

int resolve_dns(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for simplicity

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1; // DNS resolution failed
    }

    struct sockaddr_in* addr = (struct sockaddr_in*) res->ai_addr;
    memcpy(ip_address, &(addr->sin_addr), sizeof(struct in_addr));

    freeaddrinfo(res);
    return 0; // Success
}

void process_log_line(LogLine* line) {
    if (line->field_count >= 2 && isdigit(line->fields[line->field_count - 1][0]) &&
        isdigit(line->fields[line->field_count - 2][0])) {

        int num1 = atoi(line->fields[line->field_count - 1]);
        int num2 = atoi(line->fields[line->field_count - 2]);
        float avg = (num1 + num2) / 2.0f;

        char* new_field = malloc(20); // Buffer for the average
        snprintf(new_field, 20, "%f", avg);

        line->fields[line->field_count] = new_field;
        line->field_count++;
    } else {
        line->fields[line->field_count] = strdup("");
        line->field_count++;
    }
}

void process_log_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char* buffer = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&buffer, &len, file)) != -1) {
        LogLine line = {NULL, 0};

        // Allocate memory for fields
        line.fields = malloc(MAX_LINE_SIZE);
        if (!line.fields) {
            perror("Failed to allocate memory");
            free(buffer);
            fclose(file);
            return;
        }

        char* token = strtok(buffer, " \t\n");
        while (token != NULL && line.field_count < MAX_LINE_SIZE) {
            line.fields[line.field_count++] = strdup(token);
            token = strtok(NULL, " \t\n");
        }

        // Process the log line
        process_log_line(&line);

        // Print processed fields for demonstration purposes
        for (int i = 0; i < line.field_count; ++i) {
            printf("%s ", line.fields[i]);
        }
        printf("\n");

        // Free allocated memory for fields
        for (int i = 0; i < line.field_count; ++i) {
            free(line.fields[i]);
        }
        free(line.fields);
    }

    free(buffer);
    fclose(file);
}

void* dns_resolver_thread(void* arg) {
    const char* hostname = (const char*)arg;
    u_char ip_address[4];

    retry_with_exponential_backoff(resolve_dns, hostname, ip_address);

    // Print IP address for demonstration purposes
    printf("Resolved %s to %s\n", hostname, inet_ntoa(*(struct in_addr*)&ip_address));
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_log_file(argv[1]);

    // Example DNS resolution
    pthread_t dns_thread;
    const char* hostname = "example.com";

    if (pthread_create(&dns_thread, NULL, dns_resolver_thread, (void*)hostname) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(dns_thread, NULL);

    return EXIT_SUCCESS;
}
