#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct item {
    double dbl;
    int num;
    struct item *next;
    long id;
    unsigned int index;
} item_t;

// Function prototypes
void initialize_arrays(size_t initial_capacity, size_t **double_array, char ***char_array,
                       item_t ***item_array, long **long_array, unsigned int **unsigned_int_array);
void populate_items(item_t **item_array, size_t current_size, size_t capacity,
                    long *last_id, pthread_mutex_t *mutex);
void resize_arrays(size_t **double_array, char ***char_array, item_t ***item_array,
                   long **long_array, unsigned int **unsigned_int_array, size_t new_capacity);
void free_memory(double *dbl_array, char **char_array, item_t *item_array,
                 long *long_array, unsigned int *unsigned_int_array, size_t size);

// Recursive function to populate the arrays
void recursive_populate(size_t current_index, size_t capacity, double *dbl_array,
                        char ***char_array, item_t **item_array, long *long_array,
                        unsigned int *unsigned_int_array, long *last_id,
                        pthread_mutex_t *mutex) {
    if (current_index >= capacity) return;

    // Simulate dynamic resizing
    if (current_index == capacity - 1) {
        resize_arrays(&dbl_array, char_array, &item_array, &long_array, &unsigned_int_array, capacity * 2);
    }

    pthread_mutex_lock(mutex);

    dbl_array[current_index] = ((double)rand() / RAND_MAX) * 100.0;
    int random_value = rand() % 100 + 1; // Random value between 1 and 100
    item_t *new_item = malloc(sizeof(item_t));
    new_item->dbl = ((double)rand() / RAND_MAX) * 50.0;
    new_item->num = random_value;
    new_item->next = NULL;
    (*last_id)++;
    new_item->id = *last_id;
    new_item->index = current_index;

    item_array[current_index] = new_item;

    char key[11];
    snprintf(key, sizeof(key), "%010lu", (unsigned long)new_item->id);
    *char_array = realloc(*char_array, sizeof(char*) * (current_index + 1));
    (*char_array)[current_index] = strdup(key);

    long_array[current_index] = new_item->id;
    unsigned_int_array[current_index] = current_index;

    pthread_mutex_unlock(mutex);

    recursive_populate(current_index + 1, capacity, dbl_array, char_array,
                       item_array, long_array, unsigned_int_array, last_id, mutex);
}

void initialize_arrays(size_t initial_capacity, size_t **double_array, char ***char_array,
                       item_t ***item_array, long **long_array, unsigned int **unsigned_int_array) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(time(NULL)); // Seed the random number generator

    *double_array = malloc(initial_capacity * sizeof(double));
    *char_array = malloc(sizeof(char*) * initial_capacity);
    *item_array = malloc(initial_capacity * sizeof(item_t*));
    *long_array = malloc(initial_capacity * sizeof(long));
    *unsigned_int_array = malloc(initial_capacity * sizeof(unsigned int));

    long last_id = 0;

    recursive_populate(0, initial_capacity, *double_array, char_array, item_array,
                       long_array, unsigned_int_array, &last_id, &mutex);
}

void resize_arrays(size_t **double_array, char ***char_array, item_t ***item_array,
                   long **long_array, unsigned int **unsigned_int_array, size_t new_capacity) {
    *double_array = realloc(*double_array, new_capacity * sizeof(double));
    *char_array = realloc(*char_array, sizeof(char*) * new_capacity);
    *item_array = realloc(*item_array, new_capacity * sizeof(item_t*));
    *long_array = realloc(*long_array, new_capacity * sizeof(long));
    *unsigned_int_array = realloc(*unsigned_int_array, new_capacity * sizeof(unsigned int));
}

void free_memory(double *dbl_array, char **char_array, item_t *item_array,
                 long *long_array, unsigned int *unsigned_int_array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (char_array[i]) free(char_array[i]);
        if (item_array[i]) free(item_array[i]);
    }
    free(dbl_array);
    free(char_array);
    free(item_array);
    free(long_array);
    free(unsigned_int_array);
}

// Example usage
int main() {
    size_t initial_capacity = 5;
    size_t *double_array, **char_array, **item_array, *long_array, *unsigned_int_array;

    initialize_arrays(initial_capacity, &double_array, &char_array,
                      &item_array, &long_array, &unsigned_int_array);

    // Example of accessing the arrays
    for (size_t i = 0; i < initial_capacity; ++i) {
        printf("Item %zu: dbl=%.2f, num=%d, id=%ld\n", i, double_array[i],
               item_array[i]->num, item_array[i]->id);
    }

    // Free memory
    free_memory(double_array, char_array, *item_array,
                long_array, unsigned_int_array, initial_capacity);

    return 0;
}
