// Assume these are defined elsewhere
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI_VALUE 1023

// Function prototypes for utility functions
bool generate_unique_rnti(uint16_t rnti_range, uint16_t *rnti_set, size_t set_size, uint16_t *out_rnti);
void initialize_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu, double probability);

pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pdus(size_t n, size_t max_memory, double crc_probability) {
    if (n == 0 || max_memory < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }

    // Determine the maximum number of structures that can fit within the memory limit
    size_t pdus_fit = max_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (n > pdus_fit) {
        n = pdus_fit;  // Adjust to fit within the limit
    }

    pthread_mutex_lock(&allocation_mutex);

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;  // Memory allocation failed
    }

    uint16_t unique_rntis[MAX_RNTI_VALUE + 1] = {0};
    size_t set_size = n;

    for (size_t i = 0; i < n; ++i) {
        if (!generate_unique_rnti(MAX_RNTI_VALUE, unique_rntis, set_size, &pdus[i].RNTI)) {
            free(pdus);
            pthread_mutex_unlock(&allocation_mutex);
            return NULL;  // Failed to generate a unique RNTI
        }

        pdus[i].RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
        initialize_crc_flag(&pdus[i], crc_probability);  // Set the CRC flag based on probability
    }

    pthread_mutex_unlock(&allocation_mutex);
    return pdus;
}

bool generate_unique_rnti(uint16_t rnti_range, uint16_t *rnti_set, size_t set_size, uint16_t *out_rnti) {
    static const unsigned int max_attempts = 1000;

    for (unsigned int attempt = 0; attempt < max_attempts; ++attempt) {
        uint16_t candidate_rnti = rand() % rnti_range;

        bool is_unique = true;
        for (size_t i = 0; i < set_size; ++i) {
            if (rnti_set[i] == candidate_rnti) {
                is_unique = false;
                break;
            }
        }

        if (is_unique) {
            *out_rnti = candidate_rnti;

            // Record this RNTI as taken
            for (size_t i = 0; i < set_size; ++i) {
                if (rnti_set[i] == 0) {  // Find the first empty slot
                    rnti_set[i] = candidate_rnti;
                    return true;
                }
            }
        }
    }

    return false;  // Failed to find a unique RNTI after max_attempts
}

void initialize_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu, double probability) {
    if (pdu) {
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = ((double)rand() / RAND_MAX < probability);
    }
}
```

In this code:
- The function `allocate_nfa_pdus` dynamically allocates memory for an array of `NFAPI_CRC_INDICATION_PDU_T` structures while ensuring the total memory does not exceed a specified limit.
- A mutex (`allocation_mutex`) is used to handle potential race conditions when called from multiple threads concurrently.
- Unique RNTI values are generated and stored in the array, with uniqueness checked by `generate_unique_rnti`.
- CRC flags are set based on a predefined probability using `initialize_crc_flag`.']

