int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <static_rules> <config_file> <incremental_flag>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *static_rules_str = argv[3];
    const char *config_file_path = argv[4];
    int enable_incremental_updates = atoi(argv[5]);

    RuleProcessor rp;
    rp.static_rules = strdup(static_rules_str);
    rp.config_file = fopen(config_file_path, "r");
    if (!rp.config_file) {
        perror("Failed to open config file");
        return EXIT_FAILURE;
    }

    rp.config_fd = open(config_file_path, O_RDONLY);
    if (rp.config_fd == -1) {
        perror("Failed to open config file for monitoring");
        fclose(rp.config_file);
        free(rp.static_rules);
        return EXIT_FAILURE;
    }

    struct stat config_stat;
    if (fstat(rp.config_fd, &config_stat)) {
        perror("Failed to get configuration file stats");
        close(rp.config_fd);
        fclose(rp.config_file);
        free(rp.static_rules);
        return EXIT_FAILURE;
    }
    rp.last_config_mod_time = config_stat.st_mtime;

    FILE *input_fp = fopen(input_file, "rb");
    if (!input_fp) {
        perror("Failed to open input file");
        close(rp.config_fd);
        fclose(rp.config_file);
        free(rp.static_rules);
        return EXIT_FAILURE;
    }

    FILE *output_fp = fopen(output_file, "wb");
    if (!output_fp) {
        perror("Failed to open output file");
        fclose(input_fp);
        close(rp.config_fd);
        fclose(rp.config_file);
        free(rp.static_rules);
        return EXIT_FAILURE;
    }

    rp.enable_incremental_updates = enable_incremental_updates;

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input_fp)) {
        if (enable_incremental_updates) {
            struct stat new_config_stat;
            if (fstat(rp.config_fd, &new_config_stat) == 0 && new_config_stat.st_mtime != rp.last_config_mod_time) {
                fprintf(stdout, "Config file updated. Reloading dynamic rules.\n");
                load_dynamic_rules(&rp);
                rp.last_config_mod_time = new_config_stat.st_mtime;
            }
        }

        process_log_entry(buffer, &rp);
    }

    free(rp.static_rules);
    fclose(input_fp);
    fclose(output_fp);
    close(rp.config_fd);
    fclose(rp.config_file);

    return EXIT_SUCCESS;
}

void load_dynamic_rules(RuleProcessor *rp) {
