['Below is a C implementation that fulfills your requirements for managing memory dynamically using memory pools and handling concurrent operations in a thread-safe manner:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_METADATA_LENGTH 128

typedef struct Metadata {
    char *data;
} Metadata;

typedef struct Record {
    short field1;
    int field2;
    float field3;
    int timestamp;
    Metadata *metadata;
    struct Record *prev, *next;
} Record;

typedef struct MemoryPool {
    size_t element_size;
    void **free_list;
    size_t capacity;
} MemoryPool;

typedef struct LinkedList {
    pthread_mutex_t lock;
    Record *head;
    Record *tail;
    size_t count;
} LinkedList;

// Initialize memory pool
MemoryPool* init_memory_pool(size_t element_size, size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->element_size = element_size;
    pool->capacity = initial_capacity;
    pool->free_list = (void **)calloc(initial_capacity, sizeof(void *));

    for (size_t i = 0; i < initial_capacity - 1; ++i) {
        pool->free_list[i] = (char *)pool->free_list + element_size;
    }
    pool->free_list[initial_capacity - 1] = NULL;

    return pool;
}

// Allocate from memory pool
void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    void *allocated_memory = pool->free_list[0];
    if (allocated_memory != NULL) {
        size_t i = 0;
        while (pool->free_list[i] != allocated_memory) {
            ++i;
        }
        for (; pool->free_list[i] != NULL; i++) {
            pool->free_list[i] = pool->free_list[i + 1];
        }
    } else {
        size_t new_capacity = pool->capacity * 2;
        void **new_free_list = (void **)realloc(pool->free_list, new_capacity * sizeof(void *));

        if (!new_free_list) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle error
        }

        for (size_t i = pool->capacity; i < new_capacity - 1; ++i) {
            new_free_list[i] = (char *)new_free_list[i - 1] + pool->element_size;
        }
        new_free_list[new_capacity - 1] = NULL;

        pool->free_list = new_free_list;
        pool->capacity = new_capacity;

        allocated_memory = new_free_list[0];
    }

    pthread_mutex_unlock(&pool->lock);
    return allocated_memory;
}

// Initialize linked list
LinkedList* init_linked_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    return list;
}

// Add record to linked list
void add_record(LinkedList *list, Record *record) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }
    ++list->count;

    pthread_mutex_unlock(&list->lock);
}

// Iterate over linked list
void iterate_list(LinkedList *list, void (*func)(Record*)) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current != NULL) {
        func(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Initialize data structures
void initialize_data_structures(long **offset, int **key, size_t num_elements, int constant_offset,
                                int key_min, int key_max, LinkedList *list, MemoryPool *record_pool) {
    srand(time(NULL));

    *offset = (long *)malloc(num_elements * sizeof(long));
    *key = (int *)malloc(num_elements * sizeof(int));

    long current_offset_sum = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        int key_value = rand() % (key_max - key_min + 1) + key_min;
        while (key_value == 0) { // Ensure no zero keys
            key_value = rand() % (key_max - key_min + 1) + key_min;
        }
        (*key)[i] = key_value;
        current_offset_sum += key_value;

        (*offset)[i] = current_offset_sum + constant_offset;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        Record *record = (Record *)allocate_from_pool(record_pool);
        if (!record) break; // Handle allocation failure

        record->field1 = rand() % 32768;
        record->field2 = rand();
        record->field3 = (float)(rand()) / RAND_MAX * 100.0f;
        record->timestamp = time(NULL);

        char metadata_content[MAX_METADATA_LENGTH];
        snprintf(metadata_content, MAX_METADATA_LENGTH, "Meta_%d", i); // Simulate unique content
        record->metadata = (Metadata *)malloc(sizeof(Metadata));
        record->metadata->data = strdup(metadata_content);

        record->prev = NULL;
        record->next = NULL;

        add_record(list, record);
    }
}

int main() {
    size_t num_elements = 1000;
    int constant_offset = 10;
    int key_min = 1, key_max = 10000;

    long *offsets;
    int *keys;
    LinkedList *records_list;
    MemoryPool *record_pool;

    record_pool = init_memory_pool(sizeof(Record), 10);
    records_list = init_linked_list();

    initialize_data_structures(&offsets, &keys, num_elements, constant_offset,
                               key_min, key_max, records_list, record_pool);

    iterate_list(records_list, [](Record *record) {
        printf("Record: (%d, %f, %d)\n", record->field1, record->field3, record->timestamp);
        printf("Metadata: %s\n", record->metadata->data);
    });

    // Clean up omitted for brevity

    return 0;
}
```

### Key Points:
- **Memory Pool Management:** A memory pool is used to manage `Record` allocations efficiently. This helps in minimizing fragmentation and improving cache locality.
- **Thread Safety:** The linked list operations are protected by a mutex (`pthread_mutex_t`) to ensure thread safety during concurrent access or modifications.
- **Initialization and Iteration:** The function initializes arrays with unique keys and offsets while populating the doubly linked list of records. It also iterates over the list safely, allowing efficient read/write access.
- **Dynamic Resizing:** Dynamic resizing is incorporated within the `allocate_from_pool` function to handle exhausted memory by expanding the pool capacity.
- **Random Data Initialization:** Random data for each record is initialized with constraints on length and format.

This implementation assumes you have a C environment set up that supports POSIX threads (`pthreads`). Adjustments might be necessary based on your specific runtime and concurrency needs.']

["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
