#include <pthread.h>

typedef struct Record {
    short field1;
    int field2;
    float field3;
    char name[10];
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct MemoryManager {
    void* pool; // Pool of memory
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryManager;

void* allocate_block(MemoryManager* mm);
void deallocate_memory(MemoryManager* mm);
MemoryManager* create_memory_manager(size_t block_size, size_t total_blocks);

typedef struct DataManager {
    long *offsets;
    int *keys;
    Node* head;
    double* event_timestamps;
    char** log_entries;

    MemoryManager* mem_mgr;
} DataManager;

DataManager* initialize_data_manager(int num_records);
void free_data_manager(DataManager* dm);

void populate_record(Record* record, unsigned int seed);
unsigned int generate_unique_key(unsigned int range);
double get_high_res_time();

DataManager* initialize_data_manager(int num_records) {
    DataManager* dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    // Memory Manager for custom allocation
    dm->mem_mgr = create_memory_manager(sizeof(Record), num_records);

    // Allocate and manage memory for arrays using the custom allocator
    void* pool = malloc(sizeof(long) * num_records + sizeof(int) * num_records +
                        sizeof(double) * num_records + (num_records * 100));

    if (!pool) {
        free_data_manager(dm);
        return NULL;
    }

    dm->offsets = (long*)pool;
    void* temp_ptr = ((char*)pool) + sizeof(long) * num_records;
    dm->keys = (int*)temp_ptr;
    temp_ptr = ((char*)temp_ptr) + sizeof(int) * num_records;
    dm->event_timestamps = (double*)temp_ptr;
    temp_ptr = ((char*)temp_ptr) + sizeof(double) * num_records;
    dm->log_entries = (char**)temp_ptr;

    // Initialize keys and offsets
    unsigned int seed = time(NULL);
    for (int i = 0; i < num_records; ++i) {
        unsigned int range = 1000;
        dm->keys[i] = generate_unique_key(range);

        if (i == 0)
            dm->offsets[i] = dm->keys[i] + 10; // example constant
        else
            dm->offsets[i] = dm->offsets[i - 1] + dm->keys[i] + 10;

        Node* new_node = allocate_block(dm->mem_mgr);
        populate_record(&new_node->record, seed + i);

        new_node->next = dm->head;
        dm->head = new_node;

        // Record event timestamp
        dm->event_timestamps[i] = get_high_res_time();

        // Populate log entry with a random string
        char* log_entry = malloc(100);
        if (log_entry) {
            for (int j = 0; j < 9; ++j)
                log_entry[j] = 'A' + rand_r(&seed) % 26;
            log_entry[9] = '\0';
            dm->log_entries[i] = log_entry;
        }
    }

    return dm;
}

void free_data_manager(DataManager* dm) {
    Node* current = dm->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        deallocate_block(dm->mem_mgr, temp);
    }
    free(dm->log_entries);
    free(dm->event_timestamps);
    free(dm->keys);
    free(dm->offsets);

    // Free custom memory manager pool
    if (dm->mem_mgr) {
        deallocate_memory(dm->mem_mgr);
        free(dm->mem_mgr);
    }

    free(dm);
}

void populate_record(Record* record, unsigned int seed) {
    rand_r(&seed);  // For reproducibility with given seed
    record->field1 = (short)(rand_r(&seed) % 1000 + 1);
    record->field2 = rand_r(&seed) % 10000 + 1;
    record->field3 = (float)(rand_r(&seed) / RAND_MAX * 100.0);

    for (int i = 0; i < 9; ++i)
        record->name[i] = 'A' + rand_r(&seed) % 26;

    record->name[9] = '\0';
}

unsigned int generate_unique_key(unsigned int range) {
    unsigned int key;
    do {
        key = rand() % range;
    } while (/* check if key already exists, pseudocode */);

    return key;
}

double get_high_res_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

void* allocate_block(MemoryManager* mm) {
    pthread_mutex_lock(&mm->lock);
    if (mm->used_blocks < mm->total_blocks) {
        void* block = ((char*)mm->pool) + (mm->block_size * mm->used_blocks++);
        pthread_mutex_unlock(&mm->lock);
        return block;
    }
    pthread_mutex_unlock(&mm->lock);
    return NULL; // Out of memory
}

void deallocate_memory(MemoryManager* mm) {
    free(mm->pool);
}

MemoryManager* create_memory_manager(size_t block_size, size_t total_blocks) {
    MemoryManager* mm = malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->block_size = block_size;
    mm->total_blocks = total_blocks;
    mm->used_blocks = 0;
    pthread_mutex_init(&mm->lock, NULL);

    mm->pool = malloc(block_size * total_blocks);
    if (!mm->pool) {
        free(mm);
        return NULL;
    }

    return mm;
}
