['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for an event record.
typedef struct {
    time_t timestamp;
    char type;
    void *payload;
    size_t payload_size;
} EventRecord;

// Define a struct for the duration interval.
typedef struct DurationInterval {
    double start;
    double end;
} DurationInterval;

// Define a hash map entry for quick lookup by event type.
typedef struct HashMapEntry {
    char key; // The type
    EventRecord *event; // Pointer to an event record
    struct HashMapEntry *next; // Next element in case of collision
} HashMapEntry;

// Memory pool structure.
typedef struct MemoryPool {
    size_t block_size;
    unsigned char *pool;
    size_t pool_size;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryPool;

// Global structures
MemoryPool memory_pool;
DurationInterval **duration_intervals;
HashMapEntry *hash_map;
size_t hash_map_capacity = 256; // Initial capacity of the hash map
pthread_mutex_t data_lock;

// Function prototypes.
void initialize_memory_pool(size_t block_size, size_t pool_size);
void* allocate_from_pool(MemoryPool *pool, size_t size);
void free_memory_pool(MemoryPool *pool);
unsigned int hash_function(char key);
void resize_hash_map();
void log_event(const char *message);

// Initialize the memory pool.
void initialize_memory_pool(size_t block_size, size_t pool_size) {
    pthread_mutex_init(&memory_pool.lock, NULL);
    memory_pool.block_size = block_size;
    memory_pool.pool_size = pool_size;
    memory_pool.pool = (unsigned char*)malloc(pool_size);
    if (!memory_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    memory_pool.used_memory = 0;
}

// Allocate memory from the pool.
void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->block_size || pool->used_memory + size > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Not enough space
    }

    void* ptr = &pool->pool[pool->used_memory];
    pool->used_memory += size;
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Free the memory pool.
void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);
}

// Hash function for event types.
unsigned int hash_function(char key) {
    return (unsigned int)(key % hash_map_capacity);
}

// Resize the hash map to accommodate more entries.
void resize_hash_map() {
    size_t new_capacity = hash_map_capacity * 2;
    HashMapEntry **new_map = (HashMapEntry**)calloc(new_capacity, sizeof(HashMapEntry*));

    for (size_t i = 0; i < hash_map_capacity; ++i) {
        HashMapEntry *entry = hash_map[i];

        while (entry) {
            HashMapEntry *next_entry = entry->next;

            unsigned int new_index = hash_function(entry->key) % new_capacity;
            entry->next = new_map[new_index];
            new_map[new_index] = entry;

            entry = next_entry;
        }
    }

    free(hash_map);
    hash_map = new_map;
    hash_map_capacity = new_capacity;
}

// Log event changes.
void log_event(const char *message) {
    // Integrate with external logging library here
    printf("%s\n", message); // Placeholder for actual logging
}

// Main function to initialize and manage memory for duration intervals and events.
void manage_memory_and_events(size_t num_intervals, double time_window_start, 
                              double time_window_end, size_t min_duration,
                              size_t max_duration, char *event_types, size_t num_event_types) {

    pthread_mutex_init(&data_lock, NULL);

    initialize_memory_pool(sizeof(EventRecord) + sizeof(time_t) + 256, 1024 * 1024); // 1MB pool

    duration_intervals = (DurationInterval**)malloc(num_intervals * sizeof(DurationInterval*));
    if (!duration_intervals) {
        perror("Failed to allocate memory for duration intervals");
        exit(EXIT_FAILURE);
    }

    double interval_duration = (time_window_end - time_window_start) / num_intervals;

    for (size_t i = 0; i < num_intervals; ++i) {
        DurationInterval *interval = (DurationInterval*)allocate_from_pool(&memory_pool, sizeof(DurationInterval));

        if (!interval) {
            perror("Failed to allocate memory for duration interval");
            exit(EXIT_FAILURE);
        }

        interval->start = time_window_start + i * interval_duration;
        interval->end = interval->start + interval_duration;

        duration_intervals[i] = interval;
    }

    hash_map = (HashMapEntry*)calloc(hash_map_capacity, sizeof(HashMapEntry*));

    for (size_t i = 0; i < num_event_types; ++i) {
        char event_type = event_types[i];

        size_t payload_size = rand() % 256 + 1;
        void *payload = allocate_from_pool(&memory_pool, payload_size);

        if (!payload) {
            perror("Failed to allocate memory for event payload");
            exit(EXIT_FAILURE);
        }

        EventRecord *event = (EventRecord*)allocate_from_pool(&memory_pool, sizeof(EventRecord));

        if (!event) {
            perror("Failed to allocate memory for event record");
            exit(EXIT_FAILURE);
        }

        event->timestamp = time(NULL);
        event->type = event_type;
        event->payload = payload;
        event->payload_size = payload_size;

        unsigned int index = hash_function(event_type);

        pthread_mutex_lock(&data_lock);
        HashMapEntry *entry = (HashMapEntry*)allocate_from_pool(&memory_pool, sizeof(HashMapEntry));

        if (!entry) {
            perror("Failed to allocate memory for hash map entry");
            exit(EXIT_FAILURE);
        }

        entry->key = event_type;
        entry->event = event;
        entry->next = hash_map[index];
        hash_map[index] = entry;

        log_event("Event added to hash map");

        if (memory_pool.used_memory > memory_pool.pool_size / 2) {
            resize_hash_map();
        }

        pthread_mutex_unlock(&data_lock);
    }
}

// Call this function periodically or based on certain conditions
