#define MAX_METADATA_LENGTH 256
#define METADATA_CACHE_SIZE 100
#define RECORDS_MAX 1024

typedef struct MetadataCache {
    char **cache;
    size_t capacity;
    size_t count;
} MetadataCache;

typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    int timestamp;
    char *metadata;
    int status_flag;
    int event_type;
    struct Record *prev;
    struct Record *next;
} Record;

typedef struct LinkedList {
    Record *head;
    Record *tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct MemoryPool {
    size_t element_size;
    void **free_list;
    size_t capacity;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

// Function declarations
MemoryPool* create_memory_pool(size_t element_size, size_t capacity);
void destroy_memory_pool(MemoryPool *pool);

Record* allocate_record(MemoryPool *record_pool);
void free_record(MemoryPool *record_pool, Record *record);

LinkedList* initialize_linked_list();
void destroy_linked_list(LinkedList *list);

MetadataCache* create_metadata_cache(size_t capacity);
void destroy_metadata_cache(MetadataCache *cache);

char* get_cached_metadata(MetadataCache *cache, const char *metadata);
void add_to_metadata_cache(MetadataCache *cache, char *metadata);

int main() {
    // Example usage
    MemoryPool *long_pool = create_memory_pool(sizeof(long), 1000);
    MemoryPool *int_pool = create_memory_pool(sizeof(int), 1000);
    MemoryPool *record_pool = create_memory_pool(sizeof(Record), RECORDS_MAX);
    LinkedList *records_list = initialize_linked_list();
    MetadataCache *metadata_cache = create_metadata_cache(METADATA_CACHE_SIZE);

    // Populate collections
    long *offsets = malloc(7 * sizeof(long));
    int *keys = malloc(7 * sizeof(int));

    long offset_sum = 0;
    for (int i = 0; i < 7; ++i) {
        keys[i] = rand() % 100 + 1; // Unique integer in range [1, 100]
        offset_sum += keys[i];
        offsets[i] = offset_sum + 10; // Constant value added

        Record *record = allocate_record(record_pool);
        record->s_field = (short)rand();
        record->i_field = rand() % 1000;
        record->f_field = (float)(rand() / RAND_MAX);
        record->timestamp = rand() % 1000000;

        char metadata[64];
        snprintf(metadata, sizeof(metadata), "Metadata_%d", i);
        record->metadata = get_cached_metadata(metadata_cache, metadata);

        record->status_flag = rand() % 2;
        record->event_type = rand() % 10;

        pthread_mutex_lock(&records_list->lock);
        if (records_list->head == NULL) {
            records_list->head = record;
            records_list->tail = record;
        } else {
            records_list->tail->next = record;
            record->prev = records_list->tail;
            records_list->tail = record;
        }
        pthread_mutex_unlock(&records_list->lock);
    }

    // Clean up
    destroy_linked_list(records_list);
    destroy_metadata_cache(metadata_cache);
    destroy_memory_pool(record_pool);
    destroy_memory_pool(long_pool);
    destroy_memory_pool(int_pool);

    free(offsets);
    free(keys);

    return 0;
}

// Implementations

MemoryPool* create_memory_pool(size_t element_size, size_t capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->element_size = element_size;
    pool->capacity = capacity;
    pool->used_count = 0;

    pthread_mutex_init(&pool->lock, NULL);
    pool->free_list = calloc(capacity, sizeof(void*));

    for (size_t i = 0; i < capacity; ++i) {
        pool->free_list[i] = malloc(element_size);
    }

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* allocate_record(MemoryPool *record_pool) {
    pthread_mutex_lock(&record_pool->lock);

    if (record_pool->used_count < record_pool->capacity) {
        void **ptr = &record_pool->free_list[record_pool->used_count];
        Record *record = *(Record **)ptr;
        ++record_pool->used_count;
        pthread_mutex_unlock(&record_pool->lock);
        return record;
    }

    pthread_mutex_unlock(&record_pool->lock);
    return NULL; // Out of memory
}

void free_record(MemoryPool *record_pool, Record *record) {
    if (record == NULL) return;

    pthread_mutex_lock(&record_pool->lock);

    size_t index = record_pool->used_count--;
    void **ptr = &record_pool->free_list[index];
    *(Record **)ptr = record;

    pthread_mutex_unlock(&record_pool->lock);
}

LinkedList* initialize_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free(current->metadata);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

MetadataCache* create_metadata_cache(size_t capacity) {
    MetadataCache *cache = malloc(sizeof(MetadataCache));
    cache->capacity = capacity;
    cache->count = 0;
    cache->cache = calloc(capacity, sizeof(char *));
    return cache;
}

void destroy_metadata_cache(MetadataCache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->cache[i]);
    }
    free(cache->cache);
    free(cache);
}

char* get_cached_metadata(MetadataCache *cache, const char *metadata) {
    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->cache[i], metadata) == 0) {
            return cache->cache[i];
        }
    }

    if (cache->count < cache->capacity) {
        char *new_metadata = strdup(metadata);
        cache->cache[cache->count++] = new_metadata;
        return new_metadata;
    }

    // Cache full, implement replacement strategy or ignore
    return NULL;
}

void add_to_metadata_cache(MetadataCache *cache, char *metadata) {
    if (cache->count < cache->capacity) {
        cache->cache[cache->count++] = metadata;
    }
}
