#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <arpa/inet.h> // For IP address conversion
#include <time.h>      // For timestamp
#include <pthread.h>   // For thread safety

// Define the structure for a network packet header
typedef struct {
    uint32_t source_ip;  // Compact binary format (IPv4)
    uint32_t dest_ip;    // Compact binary format (IPv4)
    uint8_t protocol_type;
    uint16_t packet_length;
    time_t timestamp;
    uint16_t checksum;
    uint64_t packet_id;
} PacketHeader;

// Define the structure for a network packet
typedef struct {
    PacketHeader header;
    char *payload;
} NetworkPacket;

// Memory pool management
#define INITIAL_POOL_SIZE 1024
#define PACKET_HEADER_SIZE sizeof(PacketHeader)

typedef struct MemoryPool {
    void *base;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->base = malloc(initial_size);
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->base);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        // Resize the memory pool
        size_t new_size = pool->size * 2;
        void *new_base = realloc(pool->base, new_size);
        if (!new_base) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure gracefully
        }
        pool->base = new_base;
        pool->size = new_size;
    }

    void *ptr = (char*)pool->base + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Packet collection management
typedef struct {
    NetworkPacket **packets;
    size_t count;
    size_t capacity;
    MemoryPool *header_pool;
    MemoryPool *payload_pool;
    pthread_rwlock_t rwlock;
} PacketCollection;

PacketCollection* create_packet_collection() {
    PacketCollection *collection = malloc(sizeof(PacketCollection));
    collection->packets = NULL;
    collection->count = 0;
    collection->capacity = 0;
    collection->header_pool = create_memory_pool(INITIAL_POOL_SIZE);
    collection->payload_pool = create_memory_pool(INITIAL_POOL_SIZE * sizeof(char*)); // For pointers
    pthread_rwlock_init(&collection->rwlock, NULL);
    return collection;
}

void free_packet_collection(PacketCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->packets[i]->payload);
        free(collection->packets[i]);
    }
    free(collection->packets);
    free_memory_pool(collection->header_pool);
    free_memory_pool(collection->payload_pool);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

NetworkPacket* create_network_packet(PacketCollection *collection, uint8_t protocol_type, size_t payload_size) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : INITIAL_POOL_SIZE;
        NetworkPacket **new_packets = realloc(collection->packets, new_capacity * sizeof(NetworkPacket*));
        if (!new_packets) {
            pthread_rwlock_unlock(&collection->rwlock);
            return NULL; // Handle allocation failure gracefully
        }
        collection->packets = new_packets;
        collection->capacity = new_capacity;
    }

    NetworkPacket *packet = malloc(sizeof(NetworkPacket));
    packet->header.source_ip = inet_addr("0.0.0.0");  // Default IP address
    packet->header.dest_ip = inet_addr("255.255.255.255");
    packet->header.protocol_type = protocol_type;
    packet->header.packet_length = (uint16_t)payload_size + PACKET_HEADER_SIZE;
    packet->header.timestamp = time(NULL);
    packet->header.checksum = 0; // To be calculated
    packet->header.packet_id = rand(); // Simple random ID, consider a more robust method

    packet->payload = (char*)allocate_from_pool(collection->payload_pool, payload_size);
    if (!packet->payload) {
        free(packet);
        pthread_rwlock_unlock(&collection->rwlock);
        return NULL;
    }

    collection->packets[collection->count++] = packet;

    // Calculate checksum
    calculate_checksum(packet);

    pthread_rwlock_unlock(&collection->rwlock);
    return packet;
}

void calculate_checksum(NetworkPacket *packet) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < packet->header.packet_length - sizeof(packet->header.checksum); ++i) {
        if (i < PACKET_HEADER_SIZE) {
            checksum += ((uint8_t*)&packet->header)[i];
        } else {
            checksum += packet->payload[i - PACKET_HEADER_SIZE];
        }
    }
    packet->header.checksum = htons(checksum);
}

// Iterator for traversing packets
typedef struct {
    const NetworkPacket **current;
    const NetworkPacket **end;
} PacketIterator;

PacketIterator create_packet_iterator(PacketCollection *collection, int reverse) {
    pthread_rwlock_rdlock(&collection->rwlock);

    const NetworkPacket **packets = (const NetworkPacket**)collection->packets;
    if (reverse) {
        packets += collection->count - 1;
    }

    PacketIterator iterator = { packets, (const NetworkPacket**)(reverse ? collection->packets : collection->packets + collection->count) };
    pthread_rwlock_unlock(&collection->rwlock);
    return iterator;
}

int packet_iterator_has_next(const PacketIterator *iterator) {
    return iterator->current < iterator->end;
}

NetworkPacket* packet_iterator_next(PacketIterator *iterator, int reverse) {
    NetworkPacket *packet = *iterator->current;
    if (reverse) {
        --iterator->current;
    } else {
        ++iterator->current;
    }
    return packet;
}

// Example usage
int main() {
    PacketCollection *collection = create_packet_collection();

    // Create packets
    for (int i = 0; i < 10; ++i) {
        NetworkPacket *packet = create_network_packet(collection, i % 256, 128);
        if (!packet) {
            fprintf(stderr, "Failed to allocate network packet\n");
            break;
        }
    }

    // Iterate over packets
    PacketIterator iterator = create_packet_iterator(collection, 0);
    while (packet_iterator_has_next(&iterator)) {
        NetworkPacket *packet = packet_iterator_next(&iterator, 0);
        printf("Packet ID: %llu, Source IP: %u\n", packet->header.packet_id, ntohl(packet->header.source_ip));
    }

    // Clean up
    free_packet_collection(collection);

    return 0;
}
```

This code provides a basic implementation of the requested functionality. It includes memory pool management for efficient allocation, packet creation with default IP initialization, checksum calculation, dynamic resizing of collections, and thread-safe access using read-write locks. The iterator allows both forward and reverse traversal of packets.']

