#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct item {
    double random_double;
    int random_int;
    struct item *next;
    long unique_id;
} Item;

typedef struct record {
    time_t timestamp;
    long unique_identifier;
    Item *offsets;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    list->records = (Record **)malloc(initial_capacity * sizeof(Record *));
    for (size_t i = 0; i < initial_capacity; ++i) {
        list->records[i] = NULL;
    }
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_item(Item *item) {
    if (item) {
        free_item(item->next);
        free(item);
    }
}

void free_record(Record *record) {
    if (record) {
        free_item(record->offsets);
        free(record);
    }
}

void destroy_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->capacity; ++i) {
        free_record(list->records[i]);
    }
    free(list->records);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int is_unique(long unique_id, DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->records[i] && list->records[i]->unique_identifier == unique_id) {
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return 1;
}

long generate_unique_id(DynamicList *list, long max_range) {
    srand(time(NULL));
    long id = rand() % max_range;
    while (!is_unique(id, list)) {
        id = rand() % max_range;
    }
    return id;
}

Item* create_item(long unique_id) {
    Item *item = (Item *)malloc(sizeof(Item));
    item->random_double = ((double)rand() / RAND_MAX);
    item->random_int = rand() % 100; // Adjust the range as needed
    item->next = NULL;
    item->unique_id = unique_id;
    return item;
}

void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->mutex);
    Record **new_records = (Record **)realloc(list->records, new_capacity * sizeof(Record *));
    for (size_t i = list->capacity; i < new_capacity; ++i) {
        new_records[i] = NULL;
    }
    list->records = new_records;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->mutex);
}

void add_record(DynamicList *list, Record *record) {
    pthread_mutex_lock(&list->mutex);
    if (list->capacity == 0 || record->unique_identifier < 0) return;

    for (size_t i = 0; i < list->capacity; ++i) {
        if (!list->records[i]) {
            list->records[i] = record;
            break;
        }
    }

    // Resize if necessary
    double load_factor = 0.75;
    size_t num_records = 0;
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->records[i]) num_records++;
    }
    if ((double)num_records / list->capacity >= load_factor) {
        resize_dynamic_list(list, list->capacity * 2);
        add_record(list, record); // Re-add to ensure proper placement
    }

    pthread_mutex_unlock(&list->mutex);
}

Record* create_random_record(long max_id_range, int num_offsets) {
    Record *record = (Record *)malloc(sizeof(Record));
    record->timestamp = time(NULL);
    record->unique_identifier = generate_unique_id(NULL, max_id_range); // Pass the dynamic list if needed
    Item *offsets_head = NULL;
    Item **current_offset = &offsets_head;

    for (int i = 0; i < num_offsets; ++i) {
        long unique_id = generate_unique_id(NULL, max_id_range);
        *current_offset = create_item(unique_id);
        current_offset = &(*current_offset)->next;
    }
    record->offsets = offsets_head;
    return record;
}

int main() {
    DynamicList *list = create_dynamic_list(MAX_RECORDS);

    for (int i = 0; i < 10; ++i) { // Example: Add 10 records
        Record *record = create_random_record(100000, 5);
        add_record(list, record);
    }

    destroy_dynamic_list(list);
    return 0;
}
