#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int ProtocolType;
    time_t LastUpdateTimestamp;
} TrafficFlow;

typedef struct Node {
    TrafficFlow data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TrafficList;

void initTrafficList(TrafficList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroyTrafficList(TrafficList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int addTrafficFlow(TrafficList* list, TrafficFlow flow) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->data = flow;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeTrafficFlow(TrafficList* list, const char* ip, int protocolType) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if ((protocolType == -1 || current->data.ProtocolType == protocolType) &&
            (ip == NULL || strcmp(current->data.SourceIP, ip) == 0 || strcmp(current->data.DestinationIP, ip) == 0)) {

            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int queryTrafficFlowCount(TrafficList* list, int protocolType) {
    pthread_mutex_lock(&list->lock);

    int count = 0;
    Node *current = list->head;
    while (current != NULL) {
        if (protocolType == -1 || current->data.ProtocolType == protocolType)
            count++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return count;
}

void batchDeleteInactiveFlows(TrafficList* list, int timeoutMinutes) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (difftime(currentTime, current->data.LastUpdateTimestamp) > timeoutMinutes * 60) {
            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;

            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int generateReport(const char* traffic_file_path, const char* output_pdf_path, const char* report_gen_tool_path, const char* third_party_tool_path) {
    FILE *logFile = fopen(log_file_path, "a");
    if (!logFile) return -1;

    for (int attempt = 0; attempt < 3; ++attempt) {
        time_t startTime = time(NULL);

        // Simulate image generation
        int jpegResult = system(third_party_tool_path); 
        if (jpegResult != 0) {
            fprintf(logFile, "Image generation failed on attempt %d at %ld\n", attempt + 1, startTime);
            sleep(1 << attempt);  // Exponential backoff
            continue;
        }

        // Simulate report generation
        int pdfResult = system(report_gen_tool_path);
        if (pdfResult == 0) {
            fprintf(logFile, "Report generated successfully at %ld\n", time(NULL));
            fclose(logFile);
            return 0;
        } else {
            fprintf(logFile, "PDF generation failed on attempt %d at %ld\n", attempt + 1, startTime);
            sleep(1 << attempt); // Exponential backoff
        }
    }

    fclose(logFile);
    return -1;
}

void manageTrafficAndGenerateReport(const char* traffic_file_path, const char* output_pdf_path,
                                    const char* report_gen_tool_path, const char* third_party_tool_path,
                                    const char* log_file_path) {
    TrafficList trafficList;
    initTrafficList(&trafficList);

    // Example usage
    addTrafficFlow(&trafficList, (TrafficFlow){.SourceIP = "192.168.1.1", .DestinationIP = "10.0.0.1", .ProtocolType = 6, .LastUpdateTimestamp = time(NULL)});
    removeTrafficFlow(&trafficList, NULL, -1);
    int count = queryTrafficFlowCount(&trafficList, 6);

    batchDeleteInactiveFlows(&trafficList, 20);

    if (generateReport(traffic_file_path, output_pdf_path, report_gen_tool_path, third_party_tool_path) == -1) {
        FILE *logFile = fopen(log_file_path, "a");
        if (logFile) {
            fprintf(logFile, "Failed to generate report after multiple attempts.\n");
            fclose(logFile);
        }
    }

    destroyTrafficList(&trafficList);
}
