#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_METADATA_LENGTH 256
#define KEY_RANGE_START 0
#define KEY_RANGE_END 1000000
#define INITIAL_POOL_SIZE 1024

typedef struct Metadata {
    char *data;
} Metadata;

typedef enum EventType {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add other event types as needed
};

typedef enum StatusIndicator {
    STATUS_OK,
    STATUS_ERROR,
    // Add other status indicators as needed
};

typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    int timestamp;
    Metadata *metadata;
    EventType event_type;
    StatusIndicator status_indicator;
} Record;

typedef struct Node {
    Record record;
    struct Node *prev, *next;
} Node;

typedef struct DoublyLinkedList {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList *initialize_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_record(DoublyLinkedList *list, Record record) {
    Node *new_node = malloc(sizeof(Node));
    new_node->record = record;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        if (current->record.metadata != NULL) {
            free(current->record.metadata->data);
            free(current->record.metadata);
        }
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to generate unique keys and calculate offsets
void initialize_key_offset(int *keys, long *offsets, int n) {
    for (int i = 0; i < n; ++i) {
        keys[i] = KEY_RANGE_START + rand() % (KEY_RANGE_END - KEY_RANGE_START + 1);
        if (i > 0) {
            offsets[i] = offsets[i-1] + keys[i];
        } else {
            offsets[i] = keys[i];
        }
    }
}

// Function to populate records with random values
void populate_records(Record *records, int n) {
    for (int i = 0; i < n; ++i) {
        records[i].s_field = rand() % 100;
        records[i].i_field = rand() % 1000;
        records[i].f_field = (float)(rand() % 10000) / 100.0;
        records[i].timestamp = time(NULL);

        records[i].metadata = malloc(sizeof(Metadata));
        int metadata_length = rand() % MAX_METADATA_LENGTH + 1;
        records[i].metadata->data = malloc(metadata_length * sizeof(char));
        for (int j = 0; j < metadata_length; ++j) {
            records[i].metadata->data[j] = 'a' + rand() % 26;
        }

        records[i].event_type = rand() % 2; // Assuming two event types
        records[i].status_indicator = rand() % 2; // Assuming two status indicators
    }
}

// Main function to demonstrate the setup
int main() {
    int n = 1000; // Number of elements in each collection

    // Memory allocation for collections
    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    Record *records = malloc(n * sizeof(Record));

    // Initialize key and offset collections
    initialize_key_offset(keys, offsets, n);

    // Populate records with random data
    populate_records(records, n);

    // Create a doubly linked list for the records
    DoublyLinkedList *record_list = initialize_list();
    for (int i = 0; i < n; ++i) {
        insert_record(record_list, records[i]);
    }

    // Clean up resources
    free(offsets);
    free(keys);
    free(records);

    // Free the doubly linked list
    free_list(record_list);

    return 0;
}
