#define MAX_OPTIONS 1000
#define OPTION_NAME_LENGTH 16
#define DESCRIPTION_LENGTH 64

typedef enum { TYPE_A, TYPE_B, TYPE_C } OptionType;

typedef struct {
    char *option_name;
    int default_value;
    OptionType option_type;
    time_t timestamp;
    bool enabled;
    int priority_level;
    char description[DESCRIPTION_LENGTH];
} ConfigSetting;

typedef struct {
    ConfigSetting *settings[MAX_OPTIONS];
    pthread_mutex_t lock;
} ConfigStore;

typedef struct IteratorNode {
    ConfigSetting *setting;
    struct IteratorNode *next;
} IteratorNode;

typedef struct {
    IteratorNode *current;
} ConfigIterator;

ConfigStore* create_config_store() {
    ConfigStore *store = malloc(sizeof(ConfigStore));
    store->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < MAX_OPTIONS; ++i) {
        store->settings[i] = NULL;
    }
    return store;
}

void destroy_config_store(ConfigStore *store) {
    pthread_mutex_lock(&store->lock);
    for (int i = 0; i < MAX_OPTIONS; ++i) {
        if (store->settings[i]) {
            free(store->settings[i]->option_name);
            free(store->settings[i]);
        }
    }
    pthread_mutex_unlock(&store->lock);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

void initialize_random_seed() {
    srand((unsigned)time(NULL) ^ (getpid() << 16));
}

char* generate_option_name(int index) {
    static const char valid_chars[] = "abcdefghijklmnopqrstuvwxyz";
    char *name = malloc(OPTION_NAME_LENGTH + 1);
    for (int i = 0; i < OPTION_NAME_LENGTH; ++i) {
        name[i] = valid_chars[rand() % (sizeof(valid_chars) - 1)];
    }
    name[OPTION_NAME_LENGTH] = '\0';
    return name;
}

ConfigSetting* create_config_setting(int index, ConfigStore *store) {
    pthread_mutex_lock(&store->lock);

    char *option_name = generate_option_name(index);
    ConfigSetting *setting = malloc(sizeof(ConfigSetting));
    setting->option_name = option_name;
    setting->default_value = rand() % 100;
    setting->option_type = (OptionType)(rand() % 3);
    time(&setting->timestamp);
    setting->enabled = rand() % 2 == 0;
    setting->priority_level = rand() % 10;

    snprintf(setting->description, DESCRIPTION_LENGTH, "Description for option %d", index);

    store->settings[index] = setting;

    pthread_mutex_unlock(&store->lock);
    return setting;
}

ConfigIterator* create_iterator(ConfigStore *store) {
    ConfigIterator *iterator = malloc(sizeof(ConfigIterator));
    iterator->current = NULL;
    for (int i = 0; i < MAX_OPTIONS; ++i) {
        if (!iterator->current && store->settings[i]) {
            IteratorNode *node = malloc(sizeof(IteratorNode));
            node->setting = store->settings[i];
            node->next = NULL;
            iterator->current = node;
        } else if (store->settings[i]) {
            IteratorNode *node = iterator->current;
            while (node->next) {
                node = node->next;
            }
            node->next = malloc(sizeof(IteratorNode));
            node->next->setting = store->settings[i];
            node->next->next = NULL;
        }
    }
    return iterator;
}

void free_iterator(ConfigIterator *iterator) {
    IteratorNode *current = iterator->current;
    while (current) {
        IteratorNode *next = current->next;
        free(current);
        current = next;
    }
    free(iterator);
}

ConfigSetting* get_next_setting(ConfigIterator *iterator) {
    if (!iterator->current) return NULL;

    ConfigSetting *setting = iterator->current->setting;
    IteratorNode *node = iterator->current;
    iterator->current = node->next;
    free(node);

    return setting;
}

void log_change(const char* message, int user_id) {
    // Placeholder for logging logic
