```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_RECORDS 10000
#define WARNING_THRESHOLD 0.8 * MAX_RECORDS

typedef struct {
    int key;
    long offset;
} Record;

Record* create_records(size_t num_records, long min_offset, long max_offset) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Warning: Requested number of records exceeds the maximum allowed.\n");
        return NULL;
    }

    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    Record* cache = NULL;

    // Lock to ensure thread-safe access to shared resources
    pthread_mutex_lock(&lock);

    // Check if records are already cached
    if (cache == NULL) {
        cache = malloc(MAX_RECORDS * sizeof(Record));
        if (!cache) {
            fprintf(stderr, "Memory allocation failed for records.\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Seed the thread-local random number generator with the current time
        srandom(time(NULL));

        for (size_t i = 0; i < MAX_RECORDS; ++i) {
            long tid = getpid(); // Use process ID as a proxy for thread ID in this context
            cache[i].key = tid * 1000000 + i;  // Generate unique key

            if (min_offset > max_offset) {
                fprintf(stderr, "Invalid offset range.\n");
                free(cache);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            // Initialize the offset with a random number within specified range
            cache[i].offset = min_offset + (random() % (max_offset - min_offset + 1));
        }
    }

    // Log warning if approaching threshold
    if (num_records > WARNING_THRESHOLD) {
        fprintf(stderr, "Warning: Approaching maximum records limit.\n");
    }

    pthread_mutex_unlock(&lock);

    return &cache[0];
}

void free_records(Record* records) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Lock to ensure thread-safe access
    pthread_mutex_lock(&lock);
    free(records);  // Free the allocated memory for records
    pthread_mutex_unlock(&lock);
}
```

### Key Points:

1. **Thread-Safety**: Mutex locks are used around shared resources and critical sections to prevent race conditions.
2. **Caching Mechanism**: Static allocation of a maximum allowed number of `Record` structures (`MAX_RECORDS`) prevents repeated memory allocations, improving performance by caching records.
3. **Unique Key Generation**: A unique key is generated using the process ID (as thread ID proxy) and a sequential index to ensure global uniqueness within the application.
4. **Random Offset Initialization**: Each record's offset is initialized with a random number within a specified range, seeded using the current time to maintain uniqueness across concurrent executions.
5. **Memory Management**: The function ensures proper memory allocation and deallocation to prevent leaks, logging warnings if limits are approached.

This implementation provides a basic structure to manage records efficiently in a multi-threaded environment as described.']

