#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define WARNING_THRESHOLD (MAX_TASKS * 0.8)

typedef struct {
    char* name;
    int priority_level;
    struct timeval start_time;
} task_t;

typedef struct {
    pthread_mutex_t lock;
    task_t** tasks;
    size_t count;
    float historical_priority_average; // Assume this is calculated elsewhere
    float dynamic_factor;              // Assume this is computed based on system load
} task_manager_t;

task_manager_t* create_task_manager() {
    task_manager_t* manager = malloc(sizeof(task_manager_t));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->tasks = malloc(MAX_TASKS * sizeof(task_t*));
    if (!manager->tasks) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    // Placeholder values for average and factor
    manager->historical_priority_average = 5.0f; 
    manager->dynamic_factor = 1.2f; 

    return manager;
}

void destroy_task_manager(task_manager_t* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->tasks[i]->name);
        free(manager->tasks[i]);
    }
    free(manager->tasks);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

char* generate_unique_identifier(const char* task_name, struct timeval current_time, int index) {
    static const int timestamp_size = 20; // YYYYMMDDHHMMSS.msec
    char buffer[timestamp_size + strlen(task_name) + 10]; // extra for index and null-terminator

    snprintf(buffer, sizeof(buffer), "%s_%ld.%06d_%d", task_name, current_time.tv_sec,
             (int)current_time.tv_usec, index);

    char* identifier = malloc(strlen(buffer) + 1);
    if (!identifier) return NULL;
    strcpy(identifier, buffer);
    return identifier;
}

task_t* create_task(const char* name, float historical_priority_average, float dynamic_factor) {
    task_t* new_task = malloc(sizeof(task_t));
    if (!new_task) return NULL;

    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    int priority_level = (int)(historical_priority_average * dynamic_factor);

    new_task->name = strdup(name); // Duplicates the name string
    if (!new_task->name) {
        free(new_task);
        return NULL;
    }

    new_task->priority_level = priority_level;
    new_task->start_time = start_time;

    char* unique_id = generate_unique_identifier(name, start_time, 0); // Index can be used for uniqueness
    if (!unique_id) {
        free(new_task->name);
        free(new_task);
        return NULL;
    }

    printf("Created task with identifier: %s\n", unique_id);
    free(unique_id);

    return new_task;
}

int add_task(task_manager_t* manager, const char* name) {
    if (!manager || !name) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_TASKS) {
        printf("Warning: Task limit reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (manager->count >= WARNING_THRESHOLD)
        printf("Warning: Approaching task limit threshold.\n");

    task_t* new_task = create_task(name, manager->historical_priority_average, manager->dynamic_factor);
    if (!new_task) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->tasks[manager->count++] = new_task;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int main() {
    task_manager_t* manager = create_task_manager();

    for (int i = 0; i < MAX_TASKS + 50; ++i) { // Test with more tasks than limit to trigger warnings
        char name[20];
        snprintf(name, sizeof(name), "Task_%d", i);
        add_task(manager, name);
    }

    destroy_task_manager(manager);

    return 0;
}
