#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

// Define a structure for records
typedef struct {
    char* unique_id;
    time_t timestamp;
    long* offsets;
    size_t num_offsets;
} Record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Allocate and initialize memory for an array of records
Record* allocate_records(size_t num_records, size_t num_offsets, int range_min, int range_max) {
    pthread_mutex_lock(&mutex);

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand((unsigned)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records[i].unique_id = (char*)malloc(20 * sizeof(char));
        snprintf(records[i].unique_id, 20, "ID_%zu", i);
        records[i].timestamp = time(NULL);

        records[i].offsets = (long*)malloc(num_offsets * sizeof(long));
        if (!records[i].offsets) {
            perror("Failed to allocate memory for offsets");
            exit(EXIT_FAILURE);
        }

        records[i].num_offsets = num_offsets;
        for (size_t j = 0; j < num_offsets; ++j) {
            records[i].offsets[j] = range_min + rand() % (range_max - range_min + 1);
        }
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

// Free allocated memory for records
void free_records(Record* records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].unique_id);
        free(records[i].offsets);
    }
    free(records);
}

// Retry mechanism
int retry(int attempts, int (*func)(void)) {
    for (int i = 0; i < attempts; ++i) {
        if (func() == 0) return 0;
        sleep(1); // Wait before retrying
    }
    return -1;
}

// Callback function to handle HTTP responses
size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Update or insert a resource using the HTTP PUT method
Record update_or_insert_resource(const char* url, const char* unique_id, const char* json_body) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        exit(EXIT_FAILURE);
    }

    struct curl_slist* headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    Record resource = {strdup(unique_id), time(NULL), NULL, 0};

    int status_code = -1;

    // Wrapper function for CURL operations
    auto perform_request = [&]() -> int {
        char post_fields[128];
        snprintf(post_fields, sizeof(post_fields), "{\"uniqueId\":\"%s\",\"data\":%s}", unique_id, json_body);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_fields);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resource);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) return -1;

        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
        return status_code == 200 || status_code == 201 ? 0 : -1;
    };

    // Attempt to update or insert the resource
    int result = retry(3, perform_request);

    if (result != 0) {
        fprintf(stderr, "Failed to update or insert resource after retries\n");
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);

    return resource;
}

// Delete a resource using the HTTP DELETE method
Record delete_resource(const char* url, const char* unique_id) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        exit(EXIT_FAILURE);
    }

    Record default_resource = {strdup("default"), time(NULL), NULL, 0};

    // Wrapper function for DELETE operation
    auto perform_delete = [&]() -> int {
        char url_with_id[256];
        snprintf(url_with_id, sizeof(url_with_id), "%s/%s", url, unique_id);

        curl_easy_setopt(curl, CURLOPT_URL, url_with_id);
        curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "DELETE");
        CURLcode res = curl_easy_perform(curl);
        return res == CURLE_OK ? 0 : -1;
    };

    int result = retry(5, perform_delete);
    if (result != 0) {
        fprintf(stderr, "Failed to delete resource after retries\n");
    }

    curl_easy_cleanup(curl);

    // Return a new default resource upon successful deletion
    return default_resource;
}

// Main function for demonstration purposes
int main() {
    size_t num_records = 5;
    size_t num_offsets = 3;

    Record* records = allocate_records(num_records, num_offsets, 0, 100);

    const char* url = "http://example.com/resources";
    const char* unique_id = "12345";
    const char* json_body = "{\"key\":\"value\"}";

    Record updated_resource = update_or_insert_resource(url, unique_id, json_body);
    printf("Updated resource ID: %s\n", updated_resource.unique_id);

    Record new_default_resource = delete_resource(url, updated_resource.unique_id);
    printf("New default resource ID: %s\n", new_default_resource.unique_id);

    free_records(records, num_records);
    free(updated_resource.unique_id);
    free(new_default_resource.unique_id);

    return 0;
}
```

### Key Points:
- **Memory Management**: The `allocate_records` and `free_records` functions manage dynamic memory allocation and deallocation for records.
- **Thread Safety**: Mutex locks ensure thread safety when accessing shared resources.
- **HTTP Operations**: Using libcurl, the code handles HTTP PUT and DELETE requests with retry logic.
- **Error Handling**: Errors are logged, and operations are retried as necessary to handle network issues.']

