#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

// Thread lock for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* allocate_and_initialize_records(size_t max_memory, size_t num_records, 
                                        long offset_range, int key_range, 
                                        int value_min, int value_max) {
    if (max_memory < sizeof(long) + sizeof(int)) {
        fprintf(stderr, "Insufficient memory for at least one record.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    size_t long_size = num_records * sizeof(long);
    size_t int_size = num_records * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    if (long_size + int_size + records_size > max_memory) {
        fprintf(stderr, "Not enough memory to allocate arrays and records.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    long* offsets = (long*)malloc(long_size);
    int* keys = (int*)malloc(int_size);

    if (!offsets || !keys) {
        perror("Failed to allocate memory for arrays");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    record* records = (record*)calloc(num_records, sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize arrays and records
    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = value_min + (rand() % (value_max - value_min + 1));
    }

    pthread_mutex_unlock(&lock);

    // Free the offset and key arrays as they are no longer needed
    free(offsets);
    free(keys);

    return records;
}

int main() {
    size_t max_memory = 1024 * 1024;  // Example: 1 MB limit
    size_t num_records = 1000;
    long offset_range = 10000;
    int key_range = 500;
    int value_min = 10, value_max = 20;

    record* records = allocate_and_initialize_records(max_memory, num_records, 
                                                      offset_range, key_range, 
                                                      value_min, value_max);

    if (records) {
        printf("Records allocated and initialized successfully.\n");
        // Do something with the records...

        free(records);  // Don't forget to free the allocated memory
    }

    return 0;
}
