void insert_task() {
    pthread_mutex_lock(&list_mutex);

    Task* new_task = (Task*)malloc(sizeof(Task));
    strcpy(new_task->id, generate_uuid());
    new_task->priority = generate_random_priority(1, 10); // Example priority range
    new_task->status = NEW;
    new_task->next = NULL;

    if (!head) {
        head = new_task;
    } else {
        Task* current = head;
        while (current->next) {
            if (strcmp(current->id, new_task->id) == 0) { // Handle collisions
                free(new_task);
                pthread_mutex_unlock(&list_mutex);
                return;
            }
            current = current->next;
        }
        current->next = new_task;
    }

    pthread_mutex_unlock(&list_mutex);
}

void update_task_status(const char* task_id, const char* new_status) {
    pthread_mutex_lock(&list_mutex);

    Task* current = head;
    while (current) {
        if (strcmp(current->id, task_id) == 0) {
            handle_http_patch(task_id, new_status);
            // Update status
            if (strcmp(new_status, "NEW") == 0)
                current->status = NEW;
            else if (strcmp(new_status, "IN_PROGRESS") == 0)
                current->status = IN_PROGRESS;
            else if (strcmp(new_status, "DONE") == 0)
                current->status = DONE;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

Task* delete_task(const char* task_id) {
    pthread_mutex_lock(&list_mutex);

    Task dummy_head = { "", -1, NEW, head };
    Task *prev = &dummy_head, *current = head;

    while (current) {
        if (strcmp(current->id, task_id) == 0) {
            handle_http_delete(task_id);
            prev->next = current->next;
            Task* new_task = (Task*)malloc(sizeof(Task));
            strcpy(new_task->id, generate_uuid());
            new_task->priority = -1; // Default value
            new_task->status = NEW;  // Default status
            new_task->next = NULL;

            free(current);
            pthread_mutex_unlock(&list_mutex);
            return new_task;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void print_tasks() {
    pthread_mutex_lock(&list_mutex);

    Task* current = head;
    while (current) {
        printf("Task ID: %s, Priority: %d, Status: %d\n",
               current->id,
               current->priority,
               current->status);
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    srand(time(NULL));

    insert_task();
    insert_task();

    update_task_status("some-uuid", "IN_PROGRESS");

    Task* deleted_task = delete_task("another-uuid");
    if (deleted_task) {
        printf("New task created with ID: %s\n", deleted_task->id);
        free(deleted_task);
    }

    print_tasks();

    return 0;
}
