['Below is an example implementation in C that addresses the requirements for managing memory dynamically with hash maps, event records, duration intervals, and concurrent access considerations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define HASH_MAP_SIZE 101
#define CACHE_MAX_SIZE 50

typedef struct {
    int timestamp;
    char type[10];
    unsigned char *payload;
    size_t payload_size;
} Event;

typedef struct Node {
    Event event;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t size;
    pthread_mutex_t lock;
} HashMap;

typedef struct {
    int min_duration;
    int max_duration;
    int num_intervals;
    int *intervals;
} DurationTable;

typedef struct {
    Event *cache[CACHE_MAX_SIZE];
    size_t count;
    pthread_rwlock_t lock;
} Cache;

// Function Prototypes
HashMap* create_hash_map();
void free_hash_map(HashMap *map);
void insert_event(HashMap *map, const Event *event);
Event* get_event_by_type(HashMap *map, const char *type);
DurationTable* create_duration_table(int min_duration, int max_duration, int num_intervals);
void free_duration_table(DurationTable *table);
Cache* create_cache();
void free_cache(Cache *cache);
void cache_event(Cache *cache, Event *event);
Event* get_cached_event(Cache *cache, const char *type);

HashMap* create_hash_map() {
    HashMap *map = (HashMap*)malloc(sizeof(HashMap));
    map->buckets = (Node**)calloc(HASH_MAP_SIZE, sizeof(Node*));
    map->size = HASH_MAP_SIZE;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void free_hash_map(HashMap *map) {
    for (int i = 0; i < map->size; ++i) {
        Node *node = map->buckets[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp->event.payload);
            free(temp);
        }
    }
    free(map->buckets);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

void insert_event(HashMap *map, const Event *event) {
    pthread_mutex_lock(&map->lock);
    size_t index = hash(event->type) % map->size;
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->event = *event;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;
    pthread_mutex_unlock(&map->lock);
}

Event* get_event_by_type(HashMap *map, const char *type) {
    size_t index = hash(type) % map->size;
    pthread_mutex_lock(&map->lock);
    Node *node = map->buckets[index];
    while (node) {
        if (strcmp(node->event.type, type) == 0) {
            Event *result = malloc(sizeof(Event));
            *result = node->event;
            pthread_mutex_unlock(&map->lock);
            return result;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}

DurationTable* create_duration_table(int min_duration, int max_duration, int num_intervals) {
    DurationTable *table = (DurationTable*)malloc(sizeof(DurationTable));
    table->min_duration = min_duration;
    table->max_duration = max_duration;
    table->num_intervals = num_intervals;
    table->intervals = (int*)malloc(num_intervals * sizeof(int));

    int range = max_duration - min_duration;
    for (int i = 0; i < num_intervals; ++i) {
        table->intervals[i] = min_duration + (range / num_intervals) * i;
    }
    return table;
}

void free_duration_table(DurationTable *table) {
    free(table->intervals);
    free(table);
}

Cache* create_cache() {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    cache->count = 0;
    pthread_rwlock_init(&cache->lock, NULL);
    return cache;
}

void free_cache(Cache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->cache[i]->payload);
        free(cache->cache[i]);
    }
    pthread_rwlock_destroy(&cache->lock);
    free(cache);
}

void cache_event(Cache *cache, Event *event) {
    pthread_rwlock_wrlock(&cache->lock);
    if (cache->count < CACHE_MAX_SIZE) {
        cache->cache[cache->count++] = event;
    } else {
        // Simple eviction policy
        free(cache->cache[0]->payload);
        free(cache->cache[0]);
        memmove(cache->cache, cache->cache + 1, (CACHE_MAX_SIZE - 1) * sizeof(Event*));
        cache->cache[CACHE_MAX_SIZE - 1] = event;
    }
    pthread_rwlock_unlock(&cache->lock);
}

Event* get_cached_event(Cache *cache, const char *type) {
    pthread_rwlock_rdlock(&cache->lock);
    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->cache[i]->type, type) == 0) {
            Event *result = malloc(sizeof(Event));
            *result = *cache->cache[i];
            pthread_rwlock_unlock(&cache->lock);
            return result;
        }
    }
    pthread_rwlock_unlock(&cache->lock);
    return NULL;
}

size_t hash(const char *str) {
    size_t hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

int main() {
    HashMap *event_map = create_hash_map();
    DurationTable *duration_table = create_duration_table(10, 1000, 10);
    Cache *event_cache = create_cache();

    // Example usage: Insert events and utilize cache
    Event event1 = { .timestamp = 1625150000, .type = "login", .payload = (unsigned char*)"data", .payload_size = 4 };
    insert_event(event_map, &event1);
    cache_event(event_cache, &event1);

    Event *cached_event = get_cached_event(event_cache, "login");
    if (cached_event) {
        printf("Cached Event: %s\n", cached_event->type);
        free(cached_event->payload);
        free(cached_event);
    }

    // Clean up
    free_hash_map(event_map);
    free_duration_table(duration_table);
    free_cache(event_cache);

    return 0;
}
```

### Key Points:
- **HashMap**: Uses a simple hash function for storing events by type.
- **DurationTable**: Manages evenly spaced duration intervals.
- **Cache**: Implements a basic LRU eviction policy with read-write locks for thread safety.
- **Concurrency**: Utilizes mutexes and read-write locks to handle concurrent access.
- **Memory Management**: Ensures no memory leaks by freeing allocated resources. 

This code provides a foundation for managing events, durations, and caching in a multi-threaded environment, focusing on performance and memory efficiency. Adjustments may be needed based on specific requirements or constraints.']

['Below is a C code example that addresses the specified requirements. This implementation uses mutexes for thread safety, manages memory pools for efficient allocation, and includes basic JSON parsing logic.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define CACHE_SIZE 100

typedef struct {
    size_t size;
    int timestamp;
    char *metadata_tag;
    int status;
} Document;

typedef struct {
    long offset;
    char *key;
    Document document;
    pthread_mutex_t lock;
} CollectionEntry;

typedef struct {
    CollectionEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t map_lock;
} HashMap;

typedef struct {
    char **cache;
    int *usage_count;
    pthread_mutex_t cache_lock;
} MetadataCache;

long offset_values[5];
char *string_keys[5];
Document documents[5];
int timestamp_integers[5];
char metadata_tags[5][MAX_METADATA_LENGTH];

MetadataCache metadata_cache;
HashMap document_map;

void init_metadata_cache() {
    metadata_cache.cache = malloc(CACHE_SIZE * sizeof(char *));
    metadata_cache.usage_count = calloc(CACHE_SIZE, sizeof(int));
    pthread_mutex_init(&metadata_cache.cache_lock, NULL);
}

char* get_metadata_from_cache(const char* tag) {
    pthread_mutex_lock(&metadata_cache.cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (metadata_cache.usage_count[i] > 0 && strcmp(metadata_cache.cache[i], tag) == 0) {
            metadata_cache.usage_count[i]++;
            pthread_mutex_unlock(&metadata_cache.cache_lock);
            return metadata_cache.cache[i];
        }
    }
    pthread_mutex_unlock(&metadata_cache.cache_lock);

    // Not found in cache, add new
    pthread_mutex_lock(&metadata_cache.cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (metadata_cache.usage_count[i] == 0) {
            metadata_cache.cache[i] = strdup(tag);
            metadata_cache.usage_count[i]++;
            pthread_mutex_unlock(&metadata_cache.cache_lock);
            return metadata_cache.cache[i];
        }
    }

    // Cache is full, replace the least used entry
    int min_index = 0;
    for (int i = 1; i < CACHE_SIZE; ++i) {
        if (metadata_cache.usage_count[i] < metadata_cache.usage_count[min_index]) {
            min_index = i;
        }
    }

    free(metadata_cache.cache[min_index]);
    metadata_cache.cache[min_index] = strdup(tag);
    metadata_cache.usage_count[min_index] = 1;

    pthread_mutex_unlock(&metadata_cache.cache_lock);
    return metadata_cache.cache[min_index];
}

void init_document_map() {
    document_map.entries = malloc(10 * sizeof(CollectionEntry));
    document_map.capacity = 10;
    document_map.count = 0;
    pthread_mutex_init(&document_map.map_lock, NULL);
}

Document create_random_document(int index) {
    Document doc;
    srand(time(NULL) + index);

    doc.size = rand() % 1024 + 1; // Random size between 1 and 1024
    doc.timestamp = time(NULL) + (rand() % 1000); // Random timestamp within the next 1000 seconds
    char metadata[MAX_METADATA_LENGTH];
    snprintf(metadata, sizeof(metadata), "Metadata%d", rand());
    doc.metadata_tag = get_metadata_from_cache(metadata);
    doc.status = rand() % 2; // Random status: 0 or 1

    return doc;
}

void init_collections() {
    long offset_sum = 0;

    for (int i = 0; i < 5; ++i) {
        char key[50];
        snprintf(key, sizeof(key), "Key%d", i + 1);

        string_keys[i] = strdup(key);

        offset_values[i] = offset_sum + strlen(string_keys[i]) + 10;

        documents[i] = create_random_document(i);

        pthread_mutex_init(&document_map.entries[document_map.count].lock, NULL);
        document_map.entries[document_map.count++] = (CollectionEntry){
            .offset = offset_values[i],
            .key = string_keys[i],
            .document = documents[i]
        };
    }
}

void parse_json_and_store() {
    char json_line[1024];

    while (fgets(json_line, sizeof(json_line), stdin)) {
        // Basic JSON parsing logic
        Document doc;
        sscanf(json_line, "{\"size\":%zu,\"timestamp\":%d}", &doc.size, &doc.timestamp);

        char metadata[MAX_METADATA_LENGTH] = "ParsedMetadata";
        doc.metadata_tag = get_metadata_from_cache(metadata);
        doc.status = 1;

        pthread_mutex_lock(&document_map.map_lock);
        document_map.entries[document_map.count++] = (CollectionEntry){
            .offset = offset_values[document_map.count - 1],
            .key = string_keys[document_map.count - 1],
            .document = doc
        };
        pthread_mutex_unlock(&document_map.map_lock);
    }
}

void free_resources() {
    for (int i = 0; i < document_map.count; ++i) {
        free(document_map.entries[i].key);
        free(document_map.entries[i].document.metadata_tag);
    }

    free(document_map.entries);
    pthread_mutex_destroy(&document_map.map_lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (metadata_cache.usage_count[i] > 0) {
            free(metadata_cache.cache[i]);
        }
    }
    free(metadata_cache.cache);
    free(metadata_cache.usage_count);
    pthread_mutex_destroy(&metadata_cache.cache_lock);
}

int main() {
    init_metadata_cache();
    init_document_map();
    init_collections();

    parse_json_and_store();

    free_resources();

    return 0;
}
