['Below is a C code implementation for the described task using thread-safe mechanisms to ensure concurrency safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MEMORY_ALLOCATION_FAILED -1

typedef struct {
    int value;
} record;

// Thread lock for synchronization
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_and_initialize_data_structures(long *offsets, size_t offset_count,
                                            int *keys, size_t key_count,
                                            record **records, size_t record_count) {
    if (pthread_mutex_lock(&lock)) {
        return MEMORY_ALLOCATION_FAILED;
    }

    // Allocate memory for offsets
    long *allocated_offsets = malloc(offset_count * sizeof(long));
    if (!allocated_offsets) {
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_FAILED;
    }
    memcpy(allocated_offsets, offsets, offset_count * sizeof(long));

    // Allocate memory for keys
    int *allocated_keys = malloc(key_count * sizeof(int));
    if (!allocated_keys) {
        free(allocated_offsets);
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_FAILED;
    }
    memcpy(allocated_keys, keys, key_count * sizeof(int));

    // Allocate memory for records and initialize them
    record *allocated_records = malloc(record_count * sizeof(record));
    if (!allocated_records) {
        free(allocated_offsets);
        free(allocated_keys);
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_FAILED;
    }

    int start_value = 0; // Assuming you have a specified range starting from 0
    for (size_t i = 0; i < record_count; ++i) {
        allocated_records[i].value = start_value;
        start_value += 2; // Ensure no two consecutive records share the same value
    }

    *offsets = allocated_offsets;
    *keys = allocated_keys;
    *records = allocated_records;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void free_allocated_resources(long *offsets, int *keys, record *records) {
    if (pthread_mutex_lock(&lock)) {
        return;
    }

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_unlock(&lock);
}
```

### Key Points:

1. **Thread Safety**: The function uses a mutex (`pthread_mutex_t lock`) to ensure that only one thread can allocate resources at any given time, preventing data races and ensuring consistency.

2. **Memory Allocation Checks**: Each memory allocation step checks for failure, freeing previously allocated resources if an error occurs.

3. **Record Initialization**: Records are initialized with unique values such that no two consecutive records have the same value.

4. **Responsiveness Under High Concurrency**: The use of a mutex ensures that multiple threads can safely call this function concurrently without causing corruption or race conditions.

5. **Freeing Resources**: A separate function `free_allocated_resources` is provided to safely free allocated memory, also using the mutex for thread safety.

This setup balances between performance and memory efficiency while ensuring safe concurrent execution in a multi-threaded environment.']

['Below is a C code example that addresses the requirements for managing a dynamic list of records. This implementation includes functions to add, update, and remove records, as well as synchronize with an external data service. It uses mutexes for thread safety and handles memory allocation efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_record_list() {
    RecordList* list = malloc(sizeof(RecordList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_record_list(RecordList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int find_record(RecordList* list, int key, Record** record_out) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->record.key == key) {
            *record_out = &current->record;
            pthread_mutex_unlock(&list->lock);
            return 1; // Found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // Not found
}

void add_or_update_record(RecordList* list, int key, long offset) {
    Record* record = NULL;
    if (find_record(list, key, &record)) {
        pthread_mutex_lock(&list->lock);
        *record = (Record){.key = key, .offset = offset};
        pthread_mutex_unlock(&list->lock);
    } else {
        Node* new_node = malloc(sizeof(Node));
        new_node->record = (Record){.key = key, .offset = offset};
        new_node->next = NULL;
        pthread_mutex_lock(&list->lock);
        new_node->next = list->head;
        list->head = new_node;
        pthread_mutex_unlock(&list->lock);
    }
}

void remove_record(RecordList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->record.key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void synchronize_with_remote(RecordList* list, void (*fetch_updates)(RecordList*)) {
    fetch_updates(list); // Assume this function updates the local list with remote data
}

// Example of a mock function to simulate fetching updates from a remote service
void fetch_updates_from_remote(RecordList* list) {
    // Simulate fetching records: Add or update some records
    add_or_update_record(list, 1, 100);
    add_or_update_record(list, 2, 200);
}

int main() {
    RecordList* record_list = create_record_list();

    add_or_update_record(record_list, 1, 50);
    remove_record(record_list, 3); // Key not present
    synchronize_with_remote(record_list, fetch_updates_from_remote);

    destroy_record_list(record_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the list.
- **Memory Management**: Efficiently allocates and deallocates memory for nodes in the linked list.
- **Synchronization**: Simulates synchronization with a remote service using a callback function.
- **Efficiency**: Minimizes locking duration to improve performance under concurrent access.']

