int generate_unique_key(int min, int max, HashTable *ht, int *key_set);

DataStructure* manage_memory_allocation_and_initialization(size_t num_offsets,
                                                           size_t num_keys,
                                                           size_t num_records,
                                                           long offset_min,
                                                           long offset_max,
                                                           int key_min,
                                                           int key_max,
                                                           int record_min,
                                                           int record_max) {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        return NULL; // Failed to initialize mutex
    }

    DataStructure *ds = malloc(sizeof(DataStructure));
    if (!ds) {
        pthread_mutex_destroy(&lock);
        return (DataStructure*)ERROR_MEMORY_ALLOCATION;
    }

    ds->offsets = calloc(num_offsets, sizeof(long));
    if (!ds->offsets) {
        free(ds);
        pthread_mutex_destroy(&lock);
        return (DataStructure*)ERROR_MEMORY_ALLOCATION;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        ds->offsets[i] = generate_unique_random(offset_min, offset_max, ds->offsets, i);
    }

