    if (!ht) {
        free(ds->offsets);
        free(ds);
        pthread_mutex_destroy(&lock);
        return (DataStructure*)ERROR_MEMORY_ALLOCATION;
    }

    ds->keys = malloc(sizeof(int) * num_keys);
    if (!ds->keys) {
        free_hash_table(ht);
        free(ds->offsets);
        free(ds);
        pthread_mutex_destroy(&lock);
        return (DataStructure*)ERROR_MEMORY_ALLOCATION;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        int key;
        if (!generate_unique_key(key_min, key_max, ht, &key)) {
            free(ds->keys);
            ds->keys = NULL;
            break;
        }
        ds->keys[i] = key;
    }

    ds->records = malloc(sizeof(struct record *) * num_records);
    if (!ds->records) {
        free(ds->keys);
        free_hash_table(ht);
        free(ds->offsets);
        free(ds);
        pthread_mutex_destroy(&lock);
        return (DataStructure*)ERROR_MEMORY_ALLOCATION;
    }

    int last_value = -1;
    for (size_t i = 0; i < num_records; ++i) {
        ds->records[i] = malloc(sizeof(struct record));
        if (!ds->records[i]) {
            while (--i >= 0) free(ds->records[i]);
            free(ds->records);
            ds->records = NULL;
            break;
