    size_t total_records;
    long highest_value;
    long lowest_value;
    double average_value;
} metadata;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    metadata stats;
} data_structures;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t sem;
int active_calls = 0;

void initialize_data_structures(long offset_size, int key_size, size_t record_count, long value_range_start, long value_range_end) {
    if (sem_trywait(&sem) != 0) {
        printf("System is currently overloaded. Please try again later.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    active_calls++;
    pthread_mutex_unlock(&lock);

    data_structures ds;

    // Allocate memory
    ds.offsets = (long *)malloc(offset_size * sizeof(long));
    ds.keys = (int *)malloc(key_size * sizeof(int));
    ds.records = (record *)malloc(record_count * sizeof(record));

    if (!ds.offsets || !ds.keys || !ds.records) {
        printf("Memory allocation failed.\n");
        cleanup(&ds);
        sem_post(&sem);
        return;
    }

    // Initialize records with unique values
    long value_range = value_range_end - value_range_start + 1;
    if (value_range < record_count) {
        printf("Insufficient range to generate unique values.\n");
        cleanup(&ds);
        sem_post(&sem);
        return;
    }

    for (size_t i = 0; i < record_count; ++i) {
        long value;
        do {
            value = value_range_start + rand() % value_range;
        } while ((i > 0 && ds.records[i - 1].value == value));
        ds.records[i].value = value;
    }

    // Calculate metadata
    ds.stats.total_records = record_count;
    ds.stats.highest_value = value_range_start;
    ds.stats.lowest_value = value_range_end;

    long sum_values = 0;
    for (size_t i = 0; i < record_count; ++i) {
        if (ds.records[i].value > ds.stats.highest_value)
            ds.stats.highest_value = ds.records[i].value;
        if (ds.records[i].value < ds.stats.lowest_value)
            ds.stats.lowest_value = ds.records[i].value;
        sum_values += ds.records[i].value;
    }
    ds.stats.average_value = (double)sum_values / record_count;

    // Example of storage method choice
    int use_disk_storage = 0; // Set to 1 for disk-based storage

    if (use_disk_storage) {
        save_to_disk(&ds);
    } else {
        // In-memory processing
        printf("Records initialized with metadata.\n");
        printf("Total Records: %zu\n", ds.stats.total_records);
        printf("Highest Value: %ld\n", ds.stats.highest_value);
        printf("Lowest Value: %ld\n", ds.stats.lowest_value);
        printf("Average Value: %.2f\n", ds.stats.average_value);
    }

    cleanup(&ds);

    pthread_mutex_lock(&lock);
    active_calls--;
    pthread_mutex_unlock(&lock);
    sem_post(&sem);
}

void save_to_disk(data_structures *ds) {
    // Implement serialization and disk storage logic
    printf("Saving data structures to disk.\n");
}

void cleanup(data_structures *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}

int main() {
    sem_init(&sem, 0, MAX_CONCURRENT_CALLS);

    // Example usage
    initialize_data_structures(10, 5, 100, 1, 200);

    sem_destroy(&sem);
    return 0;
}
