```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_PATH_LENGTH 256
#define INITIAL_POOL_SIZE 1024

typedef struct {
    uint16_t mode;
    uid_t uid;
    gid_t gid;
    size_t size;
    char *path;
} Inode;

typedef struct Node {
    void *key;
    void *value;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
} HashMap;

typedef struct {
    void **pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->pool = calloc(initial_size, sizeof(void *));
    mp->capacity = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + size > mp->capacity) {
        size_t new_capacity = mp->capacity * 2;
        void **new_pool = realloc(mp->pool, new_capacity * sizeof(void *));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }

    void *ptr = malloc(size);
    mp->pool[mp->used++] = ptr;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    for (size_t i = 0; i < mp->used; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

HashMap* create_hash_map(size_t bucket_count) {
    HashMap *map = malloc(sizeof(HashMap));
    map->buckets = calloc(bucket_count, sizeof(Node *));
    map->bucket_count = bucket_count;
    pthread_mutex_init(&mp->lock, NULL);
    return map;
}

unsigned long hash_function(const void *key, size_t key_size) {
    const uint8_t *data = (const uint8_t *)key;
    unsigned long hash = 5381;
    for (size_t i = 0; i < key_size; ++i) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash;
}

void hashmap_insert(HashMap *map, const void *key, size_t key_size, void *value) {
    unsigned long index = hash_function(key, key_size) % map->bucket_count;
    Node *new_node = malloc(sizeof(Node));
    new_node->key = malloc(key_size);
    memcpy(new_node->key, key, key_size);
    new_node->value = value;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;
}

void* hashmap_get(HashMap *map, const void *key, size_t key_size) {
    unsigned long index = hash_function(key, key_size) % map->bucket_count;
    Node *node = map->buckets[index];
    while (node) {
        if (memcmp(node->key, key, key_size) == 0)
            return node->value;
        node = node->next;
    }
    return NULL;
}

void initialize_collections(size_t num_inodes) {
    MemoryPool *file_pool = create_memory_pool(INITIAL_POOL_SIZE);
    MemoryPool *dir_pool = create_memory_pool(INITIAL_POOL_SIZE);
    MemoryPool *inode_pool = create_memory_pool(INITIAL_POOL_SIZE);

    char **directories = malloc(num_inodes * sizeof(char *));
    Inode *inodes = malloc(num_inodes * sizeof(Inode));
    HashMap *inode_map = create_hash_map(128);

    for (size_t i = 0; i < num_inodes; ++i) {
        size_t dir_len = snprintf(NULL, 0, "/dir_%zu", i);
        directories[i] = memory_pool_alloc(dir_pool, dir_len + 1);
        snprintf(directories[i], dir_len + 1, "/dir_%zu", i);

        inodes[i].mode = rand() % 256;
        inodes[i].uid = rand() % 10000;
        inodes[i].gid = rand() % 10000;
        inodes[i].size = (i > 0 ? inodes[i - 1].size : 0) + rand() % 1024 + 100;

        size_t path_len = snprintf(NULL, 0, "%s/file_%zu", directories[i], i);
        inodes[i].path = memory_pool_alloc(inode_pool, path_len + 1);
        snprintf(inodes[i].path, path_len + 1, "%s/file_%zu", directories[i], i);

        hashmap_insert(inode_map, inodes[i].path, path_len + 1, &inodes[i]);
    }

    // Cleanup
    for (size_t i = 0; i < num_inodes; ++i) {
        free(directories[i]);
    }
    free(directories);
    free(inodes);

    free_memory_pool(file_pool);
    free_memory_pool(dir_pool);
    free_memory_pool(inode_pool);
}

int main() {
    srand(time(NULL));
    initialize_collections(1000);
    return 0;
}
```

### Key Points:
- **Memory Pools:** Memory pools are used for managing memory allocations efficiently, reducing fragmentation and improving cache locality.
- **Thread Safety:** The `pthread_mutex_t` locks ensure that operations on shared data structures are thread-safe.
- **Hash Map:** A simple hash map implementation is provided to manage inodes with a basic collision handling mechanism.
- **Initialization:** Directories and inodes are initialized with random values, ensuring unique paths and sizes.
- **Dynamic Resizing:** The hash map and memory pools can dynamically resize as needed.

This code provides a foundational structure for managing file descriptors, directory paths, and inode structures efficiently. Adjustments may be necessary based on specific requirements or constraints of the target environment.']

