#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 8
#define PROTOCOLS 3 // Example: TCP, UDP, ICMP
#define MAX_LOG_SIZE 1024

typedef struct TrafficFlow {
    char SourceIP[16];
    char DestinationIP[16];
    int ProtocolType;
    time_t LastUpdate;
    struct TrafficFlow* next;
} TrafficFlow;

typedef struct HashTable {
    TrafficFlow** buckets;
    size_t size;
    pthread_rwlock_t lock;
} HashTable;

typedef struct LogEntry {
    char operation[MAX_LOG_SIZE];
    time_t timestamp;
    struct LogEntry* next;
} LogEntry;

typedef struct LogManager {
    LogEntry* head;
    pthread_mutex_t lock;
    FILE* logFile;
} LogManager;

HashTable* createHashTable(size_t size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(size, sizeof(TrafficFlow*));
    table->size = size;
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

unsigned long hashFunction(const char* ip) {
    unsigned long hash = 5381;
    int c;
    while ((c = *ip++))
        hash = ((hash << 5) + hash) + c;
    return hash;
}

void logOperation(LogManager* manager, const char* operation) {
    pthread_mutex_lock(&manager->lock);
    LogEntry* entry = malloc(sizeof(LogEntry));
    strncpy(entry->operation, operation, MAX_LOG_SIZE);
    entry->timestamp = time(NULL);
    entry->next = manager->head;
    manager->head = entry;

    fseek(manager->logFile, 0, SEEK_END);
    fprintf(manager->logFile, "%s - %ld\n", operation, entry->timestamp);

    pthread_mutex_unlock(&manager->lock);
}

LogManager* createLogManager(const char* filename) {
    LogManager* manager = malloc(sizeof(LogManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->logFile = fopen(filename, "a");
    return manager;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        TrafficFlow* entry = table->buckets[i];
        while (entry) {
            TrafficFlow* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_rwlock_destroy(&table->lock);
    free(table);
}

void addTrafficFlow(HashTable* table, const char* sourceIP, const char* destIP, int protocol) {
    unsigned long index = hashFunction(sourceIP) % table->size;
    TrafficFlow* newEntry = malloc(sizeof(TrafficFlow));
    strncpy(newEntry->SourceIP, sourceIP, 15);
    strncpy(newEntry->DestinationIP, destIP, 15);
    newEntry->ProtocolType = protocol;
    newEntry->LastUpdate = time(NULL);

    pthread_rwlock_wrlock(&table->lock);
    newEntry->next = table->buckets[index];
    table->buckets[index] = newEntry;
    pthread_rwlock_unlock(&table->lock);

    char logMsg[256];
    snprintf(logMsg, sizeof(logMsg), "Added flow: %s -> %s, Protocol: %d", sourceIP, destIP, protocol);
    logOperation(manager, logMsg);
}

void updateTrafficFlow(HashTable* table, const char* sourceIP, const char* destIP) {
    unsigned long index = hashFunction(sourceIP) % table->size;
    pthread_rwlock_wrlock(&table->lock);
    TrafficFlow* entry = table->buckets[index];
    while (entry) {
        if (strcmp(entry->SourceIP, sourceIP) == 0 && strcmp(entry->DestinationIP, destIP) == 0) {
            entry->LastUpdate = time(NULL);
            pthread_rwlock_unlock(&table->lock);

            char logMsg[256];
            snprintf(logMsg, sizeof(logMsg), "Updated flow: %s -> %s", sourceIP, destIP);
            logOperation(manager, logMsg);
            return;
        }
        entry = entry->next;
    }
    pthread_rwlock_unlock(&table->lock);

    char logMsg[256];
    snprintf(logMsg, sizeof(logMsg), "Update failed: %s -> %s not found", sourceIP, destIP);
    logOperation(manager, logMsg);
}

void deleteTrafficFlow(HashTable* table, const char* sourceIP, const char* destIP) {
    unsigned long index = hashFunction(sourceIP) % table->size;
    pthread_rwlock_wrlock(&table->lock);
    TrafficFlow *entry = table->buckets[index], *prev = NULL;
    while (entry) {
        if (strcmp(entry->SourceIP, sourceIP) == 0 && strcmp(entry->DestinationIP, destIP) == 0) {
            if (prev)
                prev->next = entry->next;
            else
                table->buckets[index] = entry->next;

            free(entry);
            pthread_rwlock_unlock(&table->lock);

            char logMsg[256];
            snprintf(logMsg, sizeof(logMsg), "Deleted flow: %s -> %s", sourceIP, destIP);
            logOperation(manager, logMsg);
            return;
        }
        prev = entry;
        entry = entry->next;
    }
    pthread_rwlock_unlock(&table->lock);

    char logMsg[256];
    snprintf(logMsg, sizeof(logMsg), "Delete failed: %s -> %s not found", sourceIP, destIP);
    logOperation(manager, logMsg);
}

int queryProtocolFlows(HashTable* table, int protocol) {
    pthread_rwlock_rdlock(&table->lock);
    int count = 0;
    for (size_t i = 0; i < table->size; ++i) {
        TrafficFlow* entry = table->buckets[i];
        while (entry) {
            if (entry->ProtocolType == protocol)
                count++;
            entry = entry->next;
        }
    }
    pthread_rwlock_unlock(&table->lock);
    return count;
}

void batchDeleteInactiveFlows(HashTable* table, time_t threshold) {
    pthread_rwlock_wrlock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        TrafficFlow *entry = table->buckets[i], *prev = NULL;
        while (entry) {
            if (difftime(time(NULL), entry->LastUpdate) > threshold) {
                if (prev)
                    prev->next = entry->next;
                else
                    table->buckets[i] = entry->next;

                char logMsg[256];
                snprintf(logMsg, sizeof(logMsg), "Deleted inactive flow: %s -> %s", entry->SourceIP, entry->DestinationIP);
                logOperation(manager, logMsg);

                TrafficFlow* temp = entry;
                entry = entry->next;
                free(temp);
            } else {
                prev = entry;
                entry = entry->next;
            }
        }
    }
    pthread_rwlock_unlock(&table->lock);
}

void exportToCSV(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "SourceIP,DestinationIP,ProtocolType,LastUpdate\n");

    for (size_t i = 0; i < table->size; ++i) {
        TrafficFlow* entry = table->buckets[i];
        while (entry) {
            fprintf(file, "%s,%s,%d,%ld\n", entry->SourceIP, entry->DestinationIP, entry->ProtocolType, entry->LastUpdate);
            entry = entry->next;
        }
    }

    fclose(file);
}

void compressAndArchiveOldData(HashTable* table, time_t archiveThreshold) {
    // Implement compression and archiving logic here.
    // This could involve moving old data to a separate file or database.
}

int main() {
    HashTable* trafficTable = createHashTable(1024);
    LogManager* manager = createLogManager("traffic_log.txt");

    addTrafficFlow(trafficTable, "192.168.1.1", "192.168.1.2", 0); // Example protocol
    updateTrafficFlow(trafficTable, "192.168.1.1", "192.168.1.2");
    deleteTrafficFlow(trafficTable, "192.168.1.1", "192.168.1.2");

    int tcpFlows = queryProtocolFlows(trafficTable, 0);
    printf("TCP Flows: %d\n", tcpFlows);

    time_t fifteenMinutesAgo = time(NULL) - (15 * 60);
    batchDeleteInactiveFlows(trafficTable, fifteenMinutesAgo);

    exportToCSV(trafficTable, "traffic_data.csv");

    compressAndArchiveOldData(trafficTable, time(NULL) - (7 * 24 * 60 * 60));

    destroyHashTable(trafficTable);
    fclose(manager->logFile);
    free(manager);

    return 0;
}
