['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
    double d;
    struct Record* next;
    struct Record* prev;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records_head, *records_tail;
    char *statuses;
    time_t *timestamps;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

int generate_unique_key(int range_start, int range_end, int* keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        int key;
        do {
            key = rand() % (range_end - range_start + 1) + range_start;
        } while (key_in_array(key, keys, i));
        keys[i] = key;
    }
}

int key_in_array(int key, int* array, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (array[i] == key) return 1;
    }
    return 0;
}

void initialize_data_structure(DataStructure *ds, size_t initial_size, int range_start, int range_end, char initial_status) {
    ds->count = initial_size;

    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = malloc(sizeof(long) * ds->count);
    ds->keys = malloc(sizeof(int) * ds->count);
    generate_unique_key(range_start, range_end, ds->keys, ds->count);

    long cumulative_sum = 0;
    for (size_t i = 0; i < ds->count; ++i) {
        cumulative_sum += ds->keys[i];
        ds->offsets[i] = cumulative_sum + 1000; // Arbitrary constant
    }

    ds->records_head = NULL;
    ds->records_tail = NULL;

    ds->statuses = malloc(sizeof(char) * ds->count);
    memset(ds->statuses, initial_status, ds->count);

    ds->timestamps = malloc(sizeof(time_t) * ds->count);
    time(&ds->timestamps[0]);
}

void resize_data_structure(DataStructure *ds, size_t new_size) {
    pthread_mutex_lock(&ds->lock);

    ds->offsets = realloc(ds->offsets, sizeof(long) * new_size);
    ds->keys = realloc(ds->keys, sizeof(int) * new_size);
    ds->statuses = realloc(ds->statuses, sizeof(char) * new_size);
    ds->timestamps = realloc(ds->timestamps, sizeof(time_t) * new_size);

    for (size_t i = ds->count; i < new_size; ++i) {
        ds->keys[i] = rand() % 1000 + 1;
        ds->offsets[i] = ds->offsets[i-1] + ds->keys[i];
        ds->statuses[i] = 'I'; // Initial status
        time(&ds->timestamps[i]);
    }

    ds->count = new_size;

    pthread_mutex_unlock(&ds->lock);
}

void insert_record(DataStructure *ds, Record *new_record) {
    pthread_mutex_lock(&ds->lock);

    if (!ds->records_head) {
        ds->records_head = new_record;
        ds->records_tail = new_record;
    } else {
        ds->records_tail->next = new_record;
        new_record->prev = ds->records_tail;
        ds->records_tail = new_record;
    }

    pthread_mutex_unlock(&ds->lock);
}

Record* delete_record(DataStructure *ds, Record *record) {
    pthread_mutex_lock(&ds->lock);

    if (record == ds->records_head && record == ds->records_tail) {
        ds->records_head = NULL;
        ds->records_tail = NULL;
    } else if (record == ds->records_head) {
        ds->records_head = record->next;
        if (ds->records_head)
            ds->records_head->prev = NULL;
    } else if (record == ds->records_tail) {
        ds->records_tail = record->prev;
        if (ds->records_tail)
            ds->records_tail->next = NULL;
    } else {
        Record *prev_rec = record->prev;
        Record *next_rec = record->next;
        prev_rec->next = next_rec;
        if (next_rec) next_rec->prev = prev_rec;
    }

    pthread_mutex_unlock(&ds->lock);
    return record;
}

void serialize(DataStructure *ds, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&ds->count, sizeof(size_t), 1, file);

    fwrite(ds->offsets, sizeof(long), ds->count, file);
    fwrite(ds->keys, sizeof(int), ds->count, file);
    fwrite(ds->statuses, sizeof(char), ds->count, file);
    fwrite(ds->timestamps, sizeof(time_t), ds->count, file);

    Record *current = ds->records_head;
    while (current) {
        fwrite(&current->s, sizeof(short), 1, file);
        fwrite(&current->i, sizeof(int), 1, file);
        fwrite(&current->f, sizeof(float), 1, file);
        fwrite(&current->d, sizeof(double), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize(DataStructure *ds, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    ds->offsets = realloc(ds->offsets, sizeof(long) * count);
    ds->keys = realloc(ds->keys, sizeof(int) * count);
    ds->statuses = realloc(ds->statuses, sizeof(char) * count);
    ds->timestamps = realloc(ds->timestamps, sizeof(time_t) * count);

    fread(ds->offsets, sizeof(long), count, file);
    fread(ds->keys, sizeof(int), count, file);
    fread(ds->statuses, sizeof(char), count, file);
    fread(ds->timestamps, sizeof(time_t), count, file);

    ds->records_head = NULL;
    ds->records_tail = NULL;

    Record *current = NULL;
    while (!feof(file)) {
        Record *new_record = malloc(sizeof(Record));
        if (fread(&new_record->s, sizeof(short), 1, file) == 0) break;
        if (fread(&new_record->i, sizeof(int), 1, file) == 0) break;
        if (fread(&new_record->f, sizeof(float), 1, file) == 0) break;
        if (fread(&new_record->d, sizeof(double), 1, file) == 0) break;

        new_record->next = NULL;
        new_record->prev = current;

        if (!ds->records_head) ds->records_head = new_record;
        if (current) current->next = new_record;
        current = new_record;
    }

    if (current) ds->records_tail = current;

    fclose(file);
}

int main() {
    srand(time(NULL));
    DataStructure ds;
    initialize_data_structure(&ds, 10, 1, 1000, 'I');

    for (size_t i = 0; i < 5; ++i) {
        Record *record = malloc(sizeof(Record));
        record->s = rand() % SHRT_MAX + 1;
        record->i = rand() % INT_MAX + 1;
        record->f = ((float)rand() / RAND_MAX) * 100.0f;
        record->d = (double)rand() / RAND_MAX * 1000.0;

        insert_record(&ds, record);
    }

    serialize(&ds, "data.bin");

    DataStructure ds_new;
    deserialize(&ds_new, "data.bin");

    return 0;
}
