#define INITIAL_SIZE 10
#define MAX_RANDOM_INT 100
#define DOUBLE_FACTOR (double)RAND_MAX

typedef struct item {
    double value;
    int key;
    struct item *next;
} item_t;

typedef struct DataStructure {
    long *offsets;
    int *keys;
    item_t **items;
    size_t num_offsets;
    size_t num_keys;
    size_t num_items;
    pthread_mutex_t lock;
} DataStructure;

int allocate_and_initialize(DataStructure *ds, size_t initial_size) {
    if (initial_size == 0 || ds == NULL) return -1;

    pthread_mutex_init(&ds->lock, NULL);

    size_t capacity = initial_size;
    long *offsets = malloc(capacity * sizeof(long));
    int *keys = malloc(capacity * sizeof(int));
    item_t **items = malloc(capacity * sizeof(item_t*));

    if (!offsets || !keys || !items) {
        free(offsets);
        free(keys);
        free(items);
        pthread_mutex_destroy(&ds->lock);
        return -1;
    }

    ds->num_offsets = ds->num_keys = ds->num_items = 0;
    ds->offsets = offsets;
    ds->keys = keys;
    ds->items = items;

    for (size_t i = 0; i < capacity; ++i) {
        ds->offsets[i] = rand(); // Or any specific offset logic
        ds->keys[i] = rand() % MAX_RANDOM_INT;

        item_t *item = malloc(sizeof(item_t));
        if (!item) {
            for (size_t j = 0; j < i; ++j) free(ds->items[j]);
            free(offsets);
            free(keys);
            free(items);
            pthread_mutex_destroy(&ds->lock);
            return -1;
        }

        item->value = ((double)rand() / DOUBLE_FACTOR); // Random double
        item->key = rand() % MAX_RANDOM_INT;
        item->next = NULL; // Initially set to NULL, can be linked later

        ds->items[i] = item;
    }

    return 0;
}

int resize_data_structure(DataStructure *ds, size_t new_size) {
    pthread_mutex_lock(&ds->lock);

    long *new_offsets = realloc(ds->offsets, new_size * sizeof(long));
    int *new_keys = realloc(ds->keys, new_size * sizeof(int));
    item_t **new_items = realloc(ds->items, new_size * sizeof(item_t*));

    if (!new_offsets || !new_keys || !new_items) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->items = new_items;

    for (size_t i = ds->num_items; i < new_size; ++i) {
        item_t *item = malloc(sizeof(item_t));
        if (!item) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        item->value = ((double)rand() / DOUBLE_FACTOR); // Random double
        item->key = rand() % MAX_RANDOM_INT;
        item->next = NULL;

        ds->items[i] = item;
    }

    ds->num_items = new_size;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

void free_data_structure(DataStructure *ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->num_items; ++i) {
        free(ds->items[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->items);

    pthread_mutex_destroy(&ds->lock);
}

// Additional functions such as update, query can be added here with appropriate locking mechanisms
