    std::unordered_map<int, StrategyRecord> cache;

    const StrategyRecord* getStrategy(int strategyID) {
        auto it = cache.find(strategyID);
        return (it != cache.end()) ? &(it->second) : nullptr;
    }

    void updateStrategy(int strategyID, const StrategyRecord& record) {
