void StrategyManager::selectAndExecuteStrategy(int strategyID) {
    std::lock_guard<std::mutex> lock(mtx);

    Logger::log(Logger::INFO, "Selecting strategy " + std::to_string(strategyID));

    const StrategyRecord* record = cache.getStrategy(strategyID);
    if (!record || !record->isAvailable) {
        Logger::log(Logger::WARNING, "Strategy not available or on cooldown");
        return;
    }

    try {
        fetchDataFromAPI();
        if (apiSuccess()) {
            executeStrategy(strategyID);
            record->reset();
            cache.updateStrategy(strategyID, *record);

            Logger::log(Logger::INFO, "Executed strategy successfully");

            if (performanceTuningMode) {
                // Adjust caching and logging levels based on load
            }

            persistState();

        } else {
            Logger::log(Logger::ERROR, "API call failed");
        }
    } catch (...) {
        Logger::log(Logger::ERROR, "Exception occurred during strategy execution");
    }
}

void StrategyManager::executeStrategy(int strategyID) {
    // Implementation for executing the chosen strategy
    void* memory = allocateForStrategy(sizeof(StrategyRecord));
    // Use allocated memory and perform operations
    deallocateStrategy(memory);
}

void StrategyManager::persistState() {
    std::ofstream file("strategy_state.txt");
    if (file.is_open()) {
        // Write state to disk
        file.close();
    }
}

void* StrategyManager::allocateForStrategy(size_t size) {
    return strategyPool.allocate(size);  // Use custom memory pool for allocation
}

void StrategyManager::deallocateStrategy(void* ptr) {
    strategyPool.deallocate(ptr);  // Deallocate using the memory pool
}

