} memory_manager;

#define MEMORY_ERROR -1
#define SUCCESS 0

// Function prototypes
int initialize_memory_manager(memory_manager *manager, size_t num_records, int key_min, int key_max, size_t max_lookup);
void resize_array_if_needed(memory_manager *manager, const char *array_name, size_t current_size, size_t capacity);
