// Function to initialize the memory manager
int initialize_memory_manager(memory_manager *manager, size_t num_records, int key_min, int key_max, size_t max_lookup) {
    if (pthread_mutex_init(&manager->mutex, NULL) != 0) return MEMORY_ERROR;

    manager->offset_size = manager->capacity_offset = num_records;
    manager->keys = manager->lookup_table = NULL;
    manager->key_size = manager->lookup_size = 0;

    manager->records = (record *)malloc(num_records * sizeof(record));
    if (!manager->records) return MEMORY_ERROR;

    manager->capacity_record = num_records;
    manager->record_size = 0;

    manager->lookup_table = (int **)malloc(max_lookup * sizeof(int *));
    if (!manager->lookup_table) {
        free(manager->records);
        pthread_mutex_destroy(&manager->mutex);
        return MEMORY_ERROR;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int key, unique_key_found;
        do {
            unique_key_found = 1;
            key = rand() % (key_max - key_min + 1) + key_min;

            pthread_mutex_lock(&manager->mutex);
            for (size_t j = 0; j < manager->lookup_size; ++j) {
                if (manager->lookup_table[j] && *manager->lookup_table[j] == key) {
                    unique_key_found = 0;
                    break;
                }
            }
            pthread_mutex_unlock(&manager->mutex);
        } while (!unique_key_found);

        manager->records[manager->record_size].value = rand(); // Random value initialization

        if (insert_key_to_lookup_table(manager, key, manager->record_size) == MEMORY_ERROR) {
            free(manager->records);
            for (size_t j = 0; j < manager->lookup_size; ++j) {
                free(manager->lookup_table[j]);
            }
            free(manager->lookup_table);
            pthread_mutex_destroy(&manager->mutex);
            return MEMORY_ERROR;
        }

        manager->record_size++;
    }

    return SUCCESS;
}

void resize_array_if_needed(memory_manager *manager, const char *array_name, size_t current_size, size_t capacity) {
    if (current_size >= capacity) {
        size_t new_capacity = capacity * 2;

        pthread_mutex_lock(&manager->mutex);
        void *new_ptr = NULL;
        if (strcmp(array_name, "offsets") == 0) {
            new_ptr = realloc(manager->offsets, new_capacity * sizeof(long));
        } else if (strcmp(array_name, "keys") == 0) {
            new_ptr = realloc(manager->keys, new_capacity * sizeof(int));
        } else if (strcmp(array_name, "records") == 0) {
            new_ptr = realloc(manager->records, new_capacity * sizeof(record));
        }

        if (!new_ptr) {
            fprintf(stderr, "Memory allocation failed while resizing %s.\n", array_name);
            exit(MEMORY_ERROR);
        }

        if (strcmp(array_name, "offsets") == 0) manager->offsets = (long *)new_ptr;
        else if (strcmp(array_name, "keys") == 0) manager->keys = (int *)new_ptr;
        else if (strcmp(array_name, "records") == 0) manager->records = (record *)new_ptr;

        if (strcmp(array_name, "offsets") == 0) manager->capacity_offset = new_capacity;
        else if (strcmp(array_name, "keys") == 0) manager->capacity_key = new_capacity;
        else if (strcmp(array_name, "records") == 0) manager->capacity_record = new_capacity;

        pthread_mutex_unlock(&manager->mutex);
    }
}

int insert_key_to_lookup_table(memory_manager *manager, int key, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    resize_array_if_needed(manager, "lookup_table", manager->lookup_size, manager->capacity_lookup);

    for (size_t i = 0; i < manager->lookup_size; ++i) {
        if (!manager->lookup_table[i]) {
            manager->lookup_table[i] = malloc(sizeof(int));
            if (!manager->lookup_table[i]) {
                pthread_mutex_unlock(&manager->mutex);
                return MEMORY_ERROR;
            }
            *manager->lookup_table[i] = key;
            *(int *)(malloc(sizeof(int))) = index; // Allocate space for the record index
            manager->lookup_size++;
            pthread_mutex_unlock(&manager->mutex);
            return SUCCESS;
        } else if (*manager->lookup_table[i] == key) {
            pthread_mutex_unlock(&manager->mutex);
            return MEMORY_ERROR; // Key already exists, should handle differently in real use-case
        }
    }

    manager->lookup_table[manager->lookup_size++] = malloc(2 * sizeof(int));
    if (!manager->lookup_table[manager->lookup_size - 1]) {
        pthread_mutex_unlock(&manager->mutex);
        return MEMORY_ERROR;
    }

    *(int *)(manager->lookup_table[manager->lookup_size - 1]) = key;
    *((int *)(manager->lookup_table[manager->lookup_size - 1] + sizeof(int))) = index;

    pthread_mutex_unlock(&manager->mutex);
    return SUCCESS;
}

int get_record_index_from_lookup_table(memory_manager *manager, int key) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->lookup_size; ++i) {
        if (manager->lookup_table[i] && *(int *)(manager->lookup_table[i]) == key) {
            size_t index = *((int *)(manager->lookup_table[i] + sizeof(int)));
            pthread_mutex_unlock(&manager->mutex);
            return (int)index;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Not found
}

// Example usage
int main() {
    memory_manager manager;
    size_t num_records = 1000;
    int key_min = 1, key_max = 2000;
    size_t max_lookup = 1500;

    if (initialize_memory_manager(&manager, num_records, key_min, key_max, max_lookup) == MEMORY_ERROR) {
        fprintf(stderr, "Failed to initialize memory manager.\n");
        return EXIT_FAILURE;
    }

    int test_key = key_min + rand() % (key_max - key_min);
    size_t record_index = get_record_index_from_lookup_table(&manager, test_key);

    if (record_index != (size_t)-1) {
        printf("Record index for key %d: %zu\n", test_key, record_index);
    } else {
        printf("Key %d not found.\n", test_key);
    }

    // Free allocated resources
    free(manager.records);
    for (size_t i = 0; i < manager.lookup_size; ++i) {
        free(manager.lookup_table[i]);
    }
    free(manager.lookup_table);
    pthread_mutex_destroy(&manager.mutex);

    return EXIT_SUCCESS;
}
