int initialize_arrays(const char *jsonFilePath, size_t initialSize, double minDoubleValue, double maxDoubleValue) {
    // Step 1: Parse JSON file to get initial values
    json_error_t error;
    json_t *root = json_load_file(jsonFilePath, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON file: %s\n", error.text);
        return -1; // Indicate failure due to JSON parse errors
    }

    json_t *valuesArray = json_array();
    int success = json_unpack(root, "{s:o}", "initial_values", valuesArray);

    if (!success) {
        fprintf(stderr, "Error parsing 'initial_values' in JSON file\n");
        json_decref(root);
        return -1;
    }

    // Allocate memory for double and short arrays
    double *doubles = (double*)malloc(initialSize * sizeof(double));
    short *keys = (short*)malloc(initialSize * sizeof(short));

    if (!doubles || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(doubles);
        free(keys);
        json_decref(root);
        return -1;
    }

    // Initialize doubles and keys
    for (size_t i = 0; i < initialSize && i < json_array_size(valuesArray); ++i) {
        json_t *valueObj = json_array_get(valuesArray, i);

        if (!json_is_object(valueObj)) continue;

        double dValue;
        short sKey;

        success = json_unpack(valueObj, "{ds,sH}", "double", &dValue, "short", &sKey);
        if (success) {
            doubles[i] = dValue;
            keys[i] = sKey;
        } else {
            fprintf(stderr, "Malformed data for record %zu\n", i);
            doubles[i] = 0.0; // Default value
            keys[i] = -1;     // Default key (indicating an issue)
        }
    }

    // Allocate memory for records and pointers array
    Record *records = (Record*)malloc(initialSize * sizeof(Record));
    Record **recordPointers = (Record**)malloc(initialSize * sizeof(Record*));

    if (!records || !recordPointers) {
        fprintf(stderr, "Memory allocation failed\n");
        free(doubles);
        free(keys);
        free(records);
        free(recordPointers);
        json_decref(root);
        return -1;
    }

    // Initialize records
    for (size_t i = 0; i < initialSize; ++i) {
        if (keys[i] == -1 || !doubles[i]) continue;

        records[i].value = doubles[i];
        records[i].key = keys[i];

        // Create custom data and assign to record
        CustomDataType *customData = third_party_create_custom_data(); // Placeholder for library function
        if (!customData) {
            fprintf(stderr, "Failed to create custom data object\n");
            continue;
        }

        records[i].customData = customData;

        // Set value to random within range and ensure unique key
        records[i].value = (double)rand() / RAND_MAX * (maxDoubleValue - minDoubleValue) + minDoubleValue;
        keys[i] += i;  // Simple strategy for ensuring uniqueness

        // Store pointer to record in the pointers array
        recordPointers[i] = &records[i];
    }

    json_decref(root);

    // Return number of successfully initialized records
    return (int)initialSize;
}

// Function to free allocated memory
void cleanup(double *doubles, short *keys, Record *records, Record **recordPointers, size_t count) {
    if (doubles) free(doubles);
    if (keys) free(keys);

    for (size_t i = 0; i < count; ++i) {
        if (records[i].customData) third_party_free_custom_data(records[i].customData); // Placeholder
    }
    if (records) free(records);
    if (recordPointers) free(recordPointers);
}
