#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    double *value_ptr;
} element;

typedef struct HashTableEntry {
    int key;
    double value;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **table;
    size_t size;
} HashTable;

void init_random() {
    srand(time(NULL));
}

double generate_random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

size_t hash(int key, size_t table_size) {
    return key % table_size;
}

HashTable* create_hash_table(size_t initial_size) {
    HashTable *hash_table = malloc(sizeof(HashTable));
    if (!hash_table) return NULL;

    hash_table->table = calloc(initial_size, sizeof(HashTableEntry *));
    if (!hash_table->table) {
        free(hash_table);
        return NULL;
    }

    hash_table->size = initial_size;
    return hash_table;
}

int add_to_hash_table(HashTable *hash_table, int key, double value) {
    size_t index = hash(key, hash_table->size);

    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (!entry) return -1;

    entry->key = key;
    entry->value = value;
    entry->next = hash_table->table[index];
    hash_table->table[index] = entry;

    return 0;
}

double* allocate_double_array(size_t *capacity, size_t growth_factor, double min, double max) {
    *capacity = 10; // Initial capacity
    while (1) {
        double *array = malloc(*capacity * sizeof(double));
        if (array) break;

        *capacity = (size_t)((double)*capacity * growth_factor);
    }

    for (size_t i = 0; i < *capacity; ++i) {
        array[i] = generate_random_double(min, max);
    }
    return array;
}

element* allocate_element_array(size_t *capacity, size_t growth_factor) {
    *capacity = 10; // Initial capacity
    while (1) {
        element *array = malloc(*capacity * sizeof(element));
        if (array) break;

        *capacity = (size_t)((double)*capacity * growth_factor);
    }
    return array;
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_data_structures(size_t initial_capacity, double min, double max, size_t hash_table_size, size_t element_growth_factor, size_t double_growth_factor) {
    pthread_mutex_lock(&lock);

    size_t capacity;
    double *double_array = allocate_double_array(&capacity, double_growth_factor, min, max);
    if (!double_array) {
        printf("Memory allocation failed for double array.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    element *element_array = allocate_element_array(&capacity, element_growth_factor);
    if (!element_array) {
        free(double_array);
        printf("Memory allocation failed for element array.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    HashTable *hash_table = create_hash_table(hash_table_size);
    if (!hash_table) {
        free(double_array);
        free(element_array);
        printf("Memory allocation failed for hash table.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    for (size_t i = 0; i < capacity; ++i) {
        element_array[i].id = rand() % capacity + 1;
        element_array[i].value_ptr = &double_array[i];

        if (add_to_hash_table(hash_table, element_array[i].id, double_array[i]) != 0) {
            printf("Failed to add entry to hash table.\n");
        }
    }

    pthread_mutex_unlock(&lock);
}

void free_data_structures(double *double_array, size_t double_capacity, element *element_array, HashTable *hash_table) {
    free(double_array);

    for (size_t i = 0; i < hash_table->size; ++i) {
        HashTableEntry *entry = hash_table->table[i];
        while (entry) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }

    free(hash_table->table);
    free(hash_table);

    free(element_array);
}
