void resizeIfNeeded(size_t new_size) {
    pthread_mutex_lock(&lock);

    if (new_size > capacity) {
        size_t new_capacity = capacity * 2;
        while (new_capacity < new_size) new_capacity *= 2;

        offsets = realloc(offsets, new_capacity * sizeof(long));
        keys = realloc(keys, new_capacity * sizeof(int));
        records = realloc(records, new_capacity * sizeof(record_t*));

        if (!offsets || !keys || !records) {
