        lookup_table = realloc(lookup_table, new_capacity * sizeof(int));
        memset(offsets + capacity, 0, (new_capacity - capacity) * sizeof(long));
        memset(keys + capacity, 0, (new_capacity - capacity) * sizeof(int));
        for (size_t i = capacity; i < new_capacity; ++i) records[i] = NULL;
        memset(lookup_table + capacity, 0, (new_capacity - capacity) * sizeof(int));

        capacity = new_capacity;
    }

    pthread_mutex_unlock(&lock);
}

