#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <random>
#include <unordered_map>
#include <vector>
#include <fstream>

// External library headers (mocked for illustration)
#include "ExternalDataProcessingLibrary.h" // For disjoint pair analysis
#include "MemoryPool.h"                    // For memory pooling

// Constants
const int COOLDOWN_PERIOD = 15; // seconds
const int USER_ID_RANGE = 100;
const int ACTION_TYPE_RANGE = 10;

// Structure to hold action records
struct ActionRecord {
    int actionType;
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
    int userId;
};

// Memory pool for efficient memory management
MemoryPool<ActionRecord> actionPool(1024);

// Linked list node
struct ListNode {
    ActionRecord data;
    ListNode* next;
};

// Function declarations
void selectAndAnalyzeActions();
void saveStateToDisk(const std::unordered_map<int, int>& freqMap);
void generateReports();

std::mutex mtx; // Mutex for thread safety
ListNode* head = nullptr;
std::chrono::time_point<std::chrono::steady_clock> lastActionTime;

// Cache mechanism (simple LRU cache)
class LRUCache {
public:
    void put(int key, int value) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(key) != cache.end()) {
            cache[key] = value;
            usageOrder.erase(key);
        } else {
            if (cache.size() >= capacity) {
                auto last = usageOrder.back();
                usageOrder.pop_back();
                cache.erase(last);
            }
            cache[key] = value;
        }
        usageOrder.push_front(key);
    }

    int get(int key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cache.find(key) != cache.end()) {
            usageOrder.erase(key);
            usageOrder.push_front(key);
            return cache[key];
        }
        return -1; // Not found
    }

private:
    std::unordered_map<int, int> cache;
    std::list<int> usageOrder;
    const size_t capacity = 1000;
    std::mutex cacheMutex;
};

LRUCache actionCache(100);

int main() {
    selectAndAnalyzeActions();
    return 0;
}

void selectAndAnalyzeActions() {
    auto currentTime = std::chrono::steady_clock::now();

    // Cooldown check
    if (std::chrono::duration_cast<std::chrono::seconds>(currentTime - lastActionTime).count() < COOLDOWN_PERIOD) {
        return;
    }

    lastActionTime = currentTime;

    // Random action selection
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> actionDist(1, ACTION_TYPE_RANGE);
    std::uniform_int_distribution<> userIdDist(1, USER_ID_RANGE);

    int selectedAction = actionDist(gen);
    int userId = userIdDist(gen);
    auto timestamp = currentTime;

    // Insert new action record
    std::lock_guard<std::mutex> lock(mtx);
    ListNode* newNode = actionPool.allocate();
    newNode->data.actionType = selectedAction;
    newNode->data.timestamp = timestamp;
    newNode->data.userId = userId;
    newNode->next = head;
    head = newNode;

    // Print the selected action
    std::cout << "Selected Action: " << selectedAction << std::endl;

    // Analyze disjoint pairs using external library
    ExternalDataProcessingLibrary edpl;
    auto startAnalysisTime = std::chrono::high_resolution_clock::now();
    int disjointPairCount = edpl.analyzeDisjointPairs(head);
    auto endAnalysisTime = std::chrono::high_resolution_clock::now();

    // Print analysis results
    std::cout << "Disjoint Pair Count: " << disjointPairCount 
              << ", Computation Time: " 
              << std::chrono::duration_cast<std::chrono::milliseconds>(endAnalysisTime - startAnalysisTime).count() << " ms" << std::endl;

    // Cache frequently accessed records and results
    actionCache.put(selectedAction, userId);

    // Periodically save state to disk
    static int saveCounter = 0;
    if (++saveCounter % 10 == 0) {
        std::unordered_map<int, int> freqMap; // Mock frequency map for illustration
        saveStateToDisk(freqMap);
    }

    // Generate reports periodically
    generateReports();
}

void saveStateToDisk(const std::unordered_map<int, int>& freqMap) {
    std::lock_guard<std::mutex> lock(mtx);
    std::ofstream file("state_backup.txt", std::ios::app);
    if (file.is_open()) {
        for (const auto& pair : freqMap) {
            file << "ActionType: " << pair.first << ", Frequency: " << pair.second << "\n";
        }
        file.close();
    }
}

void generateReports() {
    // Mock implementation for generating reports
    std::cout << "Generating detailed reports..." << std::endl;
    // Report generation logic...
}
```

### Key Points:

- **Thread Safety**: A mutex (`mtx`) is used to ensure thread-safe modifications of the linked list.
- **Memory Pool**: `MemoryPool<ActionRecord>` manages dynamic memory allocation efficiently.
- **External Library Integration**: Mocked as `ExternalDataProcessingLibrary` for disjoint pair analysis.
- **Caching Mechanism**: Implemented a simple LRU cache (`LRUCache`) to store frequently accessed records and results.
- **Periodic Disk Saving**: The state is saved periodically to disk without becoming a bottleneck.
- **Report Generation**: Placeholder function `generateReports()` for periodic detailed reporting.

This code provides a comprehensive framework that addresses the requirements of dynamic action selection, efficient memory management, thread safety, caching, and external library integration. Adjustments may be necessary based on specific system dependencies and performance testing.']

