    char Description[256];
    char OriginatingHost[64];
} EventDetails;

typedef struct NetworkEventNode {
    long Timestamp;
    char EventType[32];
    EventDetails *EventDetails;
    struct NetworkEventNode *next;
} NetworkEventNode;

typedef struct {
    NetworkEventNode *head;
} EventList;

void initEventList(EventList *list) {
    list->head = NULL;
