NetworkEventNode* createEvent(long timestamp, const char *eventType,
                              int severityLevel, const char *description,
                              const char *originatingHost) {
    NetworkEventNode *newEvent = (NetworkEventNode *)malloc(sizeof(NetworkEventNode));
    if (!newEvent) {
        fprintf(stderr, "Memory allocation failed for new event.\n");
        return NULL;
    }

    newEvent->Timestamp = timestamp;
    strncpy(newEvent->EventType, eventType, sizeof(newEvent->EventType) - 1);
    newEvent->EventType[sizeof(newEvent->EventType) - 1] = '\0';

    EventDetails *details = (EventDetails *)malloc(sizeof(EventDetails));
    if (!details) {
        fprintf(stderr, "Memory allocation failed for event details.\n");
        free(newEvent);
        return NULL;
    }

    newEvent->EventDetails = details;
    newEvent->EventDetails->SeverityLevel = severityLevel;
    strncpy(newEvent->EventDetails->Description, description,
            sizeof(newEvent->EventDetails->Description) - 1);
    newEvent->EventDetails->Description[sizeof(newEvent->EventDetails->Description) - 1] = '\0';

    strncpy(newEvent->EventDetails->OriginatingHost, originatingHost,
            sizeof(newEvent->EventDetails->OriginatingHost) - 1);
    newEvent->EventDetails->OriginatingHost[sizeof(newEvent->EventDetails->OriginatingHost) - 1] = '\0';

    newEvent->next = NULL;
    return newEvent;
}

void addEvent(EventList *list, NetworkEventNode *newEvent) {
    if (!newEvent) {
        return;
    }

    newEvent->next = list->head;
    list->head = newEvent;
}

int retrieveEventsByType(const EventList *list, const char *eventType,
                         NetworkEventNode **events, int *count) {
    NetworkEventNode *current = list->head;
    while (current != NULL && *count < 100) { // Assume a max of 100 events to avoid overflow
        if (strcmp(current->EventType, eventType) == 0) {
            events[*count] = current;
            (*count)++;
        }
        current = current->next;
    }
    return *count; // Return the number of events found
}

void freeEventList(EventList *list) {
    NetworkEventNode *current = list->head;
    while (current != NULL) {
        NetworkEventNode *temp = current;
        current = current->next;
        free(temp->EventDetails);
        free(temp);
    }
    list->head = NULL;
}

void addExternalEventData(EventList *list, long timestamp,
                          const char *eventType, int severityLevel,
                          const char *description, const char *originatingHost) {
    // Simulate possible delay
    // In real scenarios, this would involve asynchronous calls and callbacks

    NetworkEventNode *newEvent = createEvent(timestamp, eventType, severityLevel,
                                             description, originatingHost);
    if (newEvent) {
        addEvent(list, newEvent);
    } else {
        fprintf(stderr, "Failed to add external event data due to memory allocation issues.\n");
        // Handle the failure gracefully
    }
}

// Example usage

int main() {
    EventList events;
    initEventList(&events);

    addExternalEventData(&events, 1234567890, "ERROR", 5,
                         "Critical error occurred.", "127.0.0.1");

    NetworkEventNode *foundEvents[100];
    int count = 0;
