```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <unistd.h>

#define INITIAL_CAPACITY 10
#define MAX_PROTOCOL_NAME_LEN 5

typedef struct {
    char *protocol;
    int port;
    unsigned long identifier;
} Connection;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    Connection **configurations;
} ConfigManager;

// Function prototypes
ConfigManager* create_config_manager();
void destroy_config_manager(ConfigManager *manager);
bool add_configuration(ConfigManager *manager, const char *protocol, int port, unsigned long identifier);
Connection* get_random_string(int length);
unsigned long generate_unique_identifier(ConfigManager *manager);

// Utility functions
static void resize_configs(ConfigManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Connection **new_array = realloc(manager->configurations, new_capacity * sizeof(Connection *));
    if (new_array == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    memset(new_array + manager->capacity, 0, new_capacity - manager->capacity);
    manager->configurations = new_array;
    manager->capacity = new_capacity;
}

// Implementation
ConfigManager* create_config_manager() {
    ConfigManager *manager = (ConfigManager *)malloc(sizeof(ConfigManager));
    if (!manager) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    manager->configurations = (Connection **)calloc(manager->capacity, sizeof(Connection *));

    return manager;
}

void destroy_config_manager(ConfigManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configurations[i]->protocol);
        free(manager->configurations[i]);
    }
    free(manager->configurations);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

bool add_configuration(ConfigManager *manager, const char *protocol, int port, unsigned long identifier) {
    if (port < 1024 || port > 65535) return false;

    pthread_mutex_lock(&manager->lock);

    while (manager->count >= manager->capacity) {
        resize_configs(manager);
    }

    Connection *conn = (Connection *)malloc(sizeof(Connection));
    if (!conn) {
        perror("Failed to allocate memory for connection");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    conn->protocol = strdup(protocol);
    conn->port = port;
    conn->identifier = identifier;

    manager->configurations[manager->count++] = conn;
    pthread_mutex_unlock(&manager->lock);

    return true;
}

Connection* get_random_string(int length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    Connection *conn = (Connection *)malloc(sizeof(Connection));
    if (!conn) {
        perror("Failed to allocate memory for connection");
        exit(EXIT_FAILURE);
    }

    conn->protocol = (char *)malloc(length + 1);
    if (!conn->protocol) {
        perror("Failed to allocate protocol string");
        free(conn);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        conn->protocol[i] = charset[key];
    }
    conn->protocol[length] = '\0';

    return conn;
}

unsigned long generate_unique_identifier(ConfigManager *manager) {
    unsigned long identifier;
    do {
        identifier = rand();
    } while (!add_configuration(manager, "TCP", 8080, identifier));

    return identifier;
}

// Unit Tests
void test_add_configuration() {
    ConfigManager *manager = create_config_manager();

    char protocols[3][MAX_PROTOCOL_NAME_LEN] = {"TCP", "UDP", "ICMP"};
    for (int i = 0; i < 20; ++i) { // More than initial capacity to trigger resize
        int port = rand() % (65535 - 1024 + 1) + 1024;
        add_configuration(manager, protocols[i % 3], port, generate_unique_identifier(manager));
    }

    printf("Added %zu configurations.\n", manager->count);
    destroy_config_manager(manager);
}

int main() {
    srand(time(NULL));
    test_add_configuration();
    return 0;
}
```

This code provides a thread-safe mechanism for managing network configurations dynamically. It uses mutex locks to ensure data integrity during concurrent access and automatically resizes the internal array when needed. Unique identifiers are generated with retries in case of collisions, ensuring each configuration has a unique ID. The `get_random_string` function creates random protocol names as specified.']

