    Document document;
    struct DocumentMapNode *next;
} DocumentMapNode;

#define HASH_MAP_SIZE 1024

DocumentMapNode *document_map[HASH_MAP_SIZE];
pthread_mutex_t map_locks[HASH_MAP_SIZE];

unsigned int hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % HASH_MAP_SIZE;
}

void init_document_map() {
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        document_map[i] = NULL;
        pthread_mutex_init(&map_locks[i], NULL);
    }
}

void free_document_map() {
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        DocumentMapNode *current = document_map[i];
        while (current != NULL) {
            DocumentMapNode *next = current->next;
            if (current->metadata)
                mem_pool_free(current->metadata);
            mem_pool_free(current);
            current = next;
        }
        pthread_mutex_destroy(&map_locks[i]);
    }
}

char* generate_key(const char *content, int index) {
    // Simple unique key generation based on content and index
    static char buffer[256];
    snprintf(buffer, sizeof(buffer), "%d_%s", index, content);
    return strdup(buffer);  // In a real scenario, use memory pool allocation
}

void initialize_collections(const char *json_input, int *offsets, char **keys) {
    // Assume json_parser_parse returns an array of JSON objects and the count.
    int doc_count = 0;
    JSON_Object **documents = json_parser_parse(json_input, &doc_count);

    for (int i = 0; i < doc_count; ++i) {
        const char *content = json_parser_get_content(documents[i]);
        keys[i] = generate_key(content, i);

        if (i > 0)
            offsets[i] = offsets[i - 1] + strlen(keys[i - 1]) + strlen(content) + 1;
        else
            offsets[i] = strlen(keys[i]) + strlen(content) + 1;

        // Random size and timestamp generation
        srand(time(NULL) ^ (getpid()<<16));
        int size = rand() % 1024;  // Example range for document size.
        int ts = rand() % 1000000; // Example range for timestamps.

        Document doc;
        doc.size = size;
        doc.timestamp = ts;

        MetadataTag *metadata = (MetadataTag*)mem_pool_alloc(sizeof(MetadataTag));
        const char *meta_content = json_parser_get_metadata(documents[i]);

        if (strlen(meta_content) > MAX_METADATA_LENGTH || !validate_metadata(meta_content)) {
            snprintf(doc.error_message, ERROR_MESSAGE_SIZE, "Invalid metadata: %s", meta_content);
            doc.status = 1; // Error status
        } else {
            strncpy(metadata->data, meta_content, MAX_METADATA_LENGTH - 1);
            metadata->data[MAX_METADATA_LENGTH - 1] = '\0';
            doc.metadata = metadata;
            doc.status = 0;
        }

        unsigned int hash_idx = hash_function(keys[i]);
        pthread_mutex_lock(&map_locks[hash_idx]);

        DocumentMapNode *node = (DocumentMapNode*)mem_pool_alloc(sizeof(DocumentMapNode));
        node->offset = offsets[i];
        strncpy(node->key, keys[i], sizeof(node->key) - 1);
        node->key[sizeof(node->key) - 1] = '\0';
        node->document = doc;
        node->next = document_map[hash_idx];
        document_map[hash_idx] = node;

        pthread_mutex_unlock(&map_locks[hash_idx]);
    }

    // Clean up
    for (int i = 0; i < doc_count; ++i) {
        mem_pool_free((void*)keys[i]);  // Assume keys are allocated from memory pool
    }
    json_parser_cleanup(documents, doc_count);
}

int validate_metadata(const char *metadata) {
    const char *valid_chars = METADATA_VALID_CHAR_SET;
    while (*metadata) {
        if (strchr(valid_chars, *metadata) == NULL)
            return 0;
        metadata++;
    }
    return 1;
}

// Assume mem_pool_alloc and mem_pool_free are part of the memory pool implementation
void* mem_pool_alloc(size_t size) {
    // Implementation specific to your memory pool
}

void mem_pool_free(void *ptr) {
    // Implementation specific to your memory pool
}

