void initialize_pool(MemoryPool* mp, size_t initial_capacity) {
    mp->pool = malloc(initial_capacity * sizeof(void*));
    mp->capacity = initial_capacity;
    mp->size = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void resize_pool(MemoryPool* mp, size_t new_capacity) {
    void** new_pool = realloc(mp->pool, new_capacity * sizeof(void*));
    if (new_pool) {
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }
}

void* pool_allocate(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->size >= mp->capacity) {
        resize_pool(mp, mp->capacity * 2);
    }
    void* ptr = malloc(size);
    mp->pool[mp->size++] = ptr;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

