// Linked List Operations
void init_linked_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(MemoryPool* mp, Record record) {
    Node* node = pool_allocate(mp, sizeof(Node));
    node->record = record;
    node->last_accessed = current_timestamp();
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void append_to_list(LinkedList* list, MemoryPool* mp, Record record) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(mp, record);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void* resize_background_thread(void* arg) {
    MemoryPool* mp = (MemoryPool*)arg;
    while (1) {
        // Perform background resizing
        sleep(10);  // Example interval for checking and resizing
        if (mp->size >= mp->capacity - 2) {  // Threshold to trigger resize
            resize_pool(mp, mp->capacity * 2);
        }
    }
}

// Iterator Pattern
typedef struct {
    Node* current;
    LinkedList* list;
} ListIterator;

void iterator_init(ListIterator* it, LinkedList* list, int direction) {
    pthread_mutex_lock(&list->lock);
    if (direction == 0 && list->head) {  // Forward traversal
        it->current = list->head;
    } else if (direction == 1 && list->tail) {  // Backward traversal
        it->current = list->tail;
    }
    it->list = list;
    pthread_mutex_unlock(&list->lock);
}

int iterator_has_next(ListIterator* it, int direction) {
    if (direction == 0) {
        return it->current && it->current->next != NULL;
    } else {
        return it->current && it->current->prev != NULL;
    }
}

Node* iterator_next(ListIterator* it, int direction) {
    Node* node = it->current;
    if (direction == 0) {
        it->current = node ? node->next : NULL;
    } else {
        it->current = node ? node->prev : NULL;
    }
    return node;
}

// Cache Implementation
typedef struct {
    Record records[100];  // Example cache size
    int indices[100];
    int top;
    pthread_mutex_t lock;
} LRUCache;

void init_cache(LRUCache* cache) {
    for (int i = 0; i < 100; ++i) {
        cache->indices[i] = -1;
    }
    cache->top = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void access_record_cache(LRUCache* cache, size_t index, Record record) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < 100; ++i) {
        if (cache->indices[i] == index) {
            // Move accessed item to top
            int temp_record = cache->records[i];
            int temp_index = cache->indices[i];

            while (i > 0) {
                cache->records[i] = cache->records[i - 1];
                cache->indices[i] = cache->indices[i - 1];
                --i;
            }
            cache->records[0] = temp_record;
            cache->indices[0] = temp_index;

            log_access(record, "Cache Hit");
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }

    if (cache->top < 100) {
        cache->records[cache->top] = record;
        cache->indices[cache->top++] = index;
    } else {
        // Evict the least recently used item
        for (int i = 1; i < 100; ++i) {
            cache->records[i - 1] = cache->records[i];
            cache->indices[i - 1] = cache->indices[i];
        }
        cache->records[99] = record;
        cache->indices[99] = index;
    }

    log_access(record, "Cache Miss");
    pthread_mutex_unlock(&cache->lock);
}

int main() {
    unsigned int seed = 1234;  // Example user-provided seed
    MemoryPool mp;
    LinkedList list;
    LRUCache cache;

    initialize_pool(&mp, 10);   // Initial capacity for memory pool
    init_linked_list(&list);
    init_cache(&cache);

    pthread_t resize_thread;
    pthread_create(&resize_thread, NULL, resize_background_thread, (void*)&mp);

    // Example usage of the linked list and cache
    Record rec = generate_random_record(seed);
    append_to_list(&list, &mp, rec);
    access_record_cache(&cache, 0, rec);

    ListIterator it;
    iterator_init(&it, &list, 0);  // Forward iteration

    while (iterator_has_next(&it, 0)) {
        Node* node = iterator_next(&it, 0);
        printf("Record: %d\n", node->record.i);
    }

    return 0;
}
