        LinkedListNode* node1 = malloc(sizeof(LinkedListNode));
        node1->record = new_record1;
        node1->next = NULL;
        list_tail1->next = node1;
        list_tail1 = node1;

        Record* new_record2 = malloc(sizeof(Record));
        new_record2->s_field = rand() % 100;
        new_record2->i_field = rand() % 1000;
        new_record2->f_field = (float)(rand() % 10000) / 100.0;
        new_record2->d_field = (double)(rand() % 100000) / 100.0;

        LinkedListNode* node2 = malloc(sizeof(LinkedListNode));
        node2->record = new_record2;
        node2->next = NULL;
        list_tail2->next = node2;
        list_tail2 = node2;

        Metadata* metadata = malloc(sizeof(Metadata));
        metadata->last_accessed = time(NULL);
        metadata->access_count = 1;
        metadata->record_ptr = new_record1; // Example association

        int hash_index = keys[i] % INITIAL_ARRAY_SIZE;
        HashTableEntry* entry = &hash_table[hash_index];
        while (entry->next) {
            entry = entry->next;
        }
        entry->key = malloc(12); // Enough for an integer
        sprintf(entry->key, "%d", keys[i]);
        entry->metadata = metadata;
        entry->next = calloc(1, sizeof(HashTableEntry));
    }

    pthread_join(background_thread, NULL);

    free(offsets);
    free(keys);
}

int main() {
    initialize_data(0, 100, 42); // Example usage
    return 0;
}
