#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for sizes and ranges
#define INITIAL_OFFSET_SIZE 100
#define INITIAL_KEY_RANGE 1000
#define RECORDS_COUNT 50

typedef struct {
    short short_field;
    int int_field;
    float float_field;
    long timestamp;
    char* metadata;
    int status_flag;
    int event_type;
    double metrics_double;
} Record;

// External logging library simulation (placeholder)
void log_access(const char* message) {
    printf("LOG: %s\n", message);
}

typedef struct MemoryPool {
    void** blocks;
    size_t block_size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t initial_count) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->blocks = (void**)calloc(initial_count, sizeof(void*));
    pool->block_size = block_size;
    pool->count = initial_count;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to allocate memory from the pool
void* mem_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == 0) {
        size_t new_size = pool->count * 2;
        void** new_blocks = (void**)realloc(pool->blocks, new_size * sizeof(void*));
        if (!new_blocks) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        memset(new_blocks + pool->count, 0, (new_size - pool->count) * sizeof(void*));
        pool->blocks = new_blocks;
        pool->count *= 2;
    }

    void** block_ptr = pool->blocks + --pool->count;
    void* block = malloc(pool->block_size);
    if (!block) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    *block_ptr = block;
    log_access("Allocated memory from pool");
    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Function to free all allocated memory in the pool
void mem_free_all(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < INITIAL_OFFSET_SIZE - pool->count; ++i) {
        if (pool->blocks[i]) {
            free(pool->blocks[i]);
        }
    }
    free(pool->blocks);
    pool->blocks = NULL;
    pool->count = 0;
    pthread_mutex_unlock(&pool->lock);
}

// Thread-safe linked list node
typedef struct ListNode {
    Record record;
    struct ListNode* next;
} ListNode;

// Function to create a new list node
ListNode* create_list_node(Record record) {
    ListNode* node = (ListNode*)mem_alloc(init_memory_pool(sizeof(ListNode), 1));
    if (!node) return NULL;
    node->record = record;
    node->next = NULL;
    return node;
}

// Example function to initialize and use the memory pool
void manage_memory() {
    MemoryPool* offset_pool = init_memory_pool(sizeof(long), INITIAL_OFFSET_SIZE);
    MemoryPool* key_pool = init_memory_pool(sizeof(int), INITIAL_KEY_RANGE);

    long* offsets = (long*)mem_alloc(offset_pool);
    int* keys = (int*)mem_alloc(key_pool);

    srand(time(NULL));
    for (size_t i = 0; i < RECORDS_COUNT; ++i) {
        keys[i] = rand() % INITIAL_KEY_RANGE;
        if (i > 0) {
            offsets[i] = offsets[i - 1] + keys[i - 1] + 10; // Constant is 10
        } else {
            offsets[i] = keys[i] + 10;
        }
    }

    MemoryPool* record_pool = init_memory_pool(sizeof(Record), RECORDS_COUNT);
    ListNode* head = NULL, *tail = NULL;

    for (size_t i = 0; i < RECORDS_COUNT; ++i) {
        Record rec = { .short_field = rand() % 100,
                       .int_field = rand() % 1000,
                       .float_field = rand() / (RAND_MAX + 1.0),
                       .timestamp = time(NULL) + rand(),
                       .metadata = "Sample metadata",
                       .status_flag = rand() % 2,
                       .event_type = rand() % 5,
                       .metrics_double = rand() / (double)(RAND_MAX + 1) };
        ListNode* node = create_list_node(rec);
        if (!node) {
            printf("Failed to allocate list node\n");
            break;
        }

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    // Example cleanup
    mem_free_all(offset_pool);
    mem_free_all(key_pool);
    mem_free_all(record_pool);

    ListNode* current = head;
    while (current) {
        ListNode* next_node = current->next;
        free(current);
        current = next_node;
    }
}

int main() {
    manage_memory();
    return 0;
}
