    int i;
    float f;
} Record;

typedef struct Node {
    Record rec;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Global variables
long* offsets = NULL;
int* keys = NULL;
size_t count = 0, capacity = 10;
LinkedList list;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_arrays(size_t initial_capacity);
void resize_arrays(size_t new_capacity);
void add_record(Record rec);
void iterate_list();
void compress_list();
void batch_insert(Record* records, size_t num_records);
void serialize_to_file(const char* filename);
void deserialize_from_file(const char* filename);
void handle_memory_pool();

// Initialize arrays and linked list
void initialize_arrays(size_t initial_capacity) {
    pthread_mutex_lock(&memory_lock);

    offsets = malloc(initial_capacity * sizeof(long));
    keys = malloc(initial_capacity * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    list.head = NULL;
    pthread_mutex_init(&list.lock, NULL);

    capacity = initial_capacity;

    pthread_mutex_unlock(&memory_lock);
}

// Resize arrays
void resize_arrays(size_t new_capacity) {
    pthread_mutex_lock(&memory_lock);

    long* temp_offsets = realloc(offsets, new_capacity * sizeof(long));
    int* temp_keys = realloc(keys, new_capacity * sizeof(int));

    if (!temp_offsets || !temp_keys) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    offsets = temp_offsets;
    keys = temp_keys;

    capacity = new_capacity;

    pthread_mutex_unlock(&memory_lock);
}

// Add a record to the linked list
void add_record(Record rec) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation for node failed\n");
        return;
    }

    node->rec = rec;
    node->next = NULL;

    pthread_mutex_lock(&list.lock);

    if (list.head == NULL) {
        list.head = node;
    } else {
        Node* current = list.head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    pthread_mutex_unlock(&list.lock);
}

// Iterate over the linked list
void iterate_list() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        printf("Record: %d, %d, %f\n", current->rec.s, current->rec.i, current->rec.f);
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);
}

// Compress the linked list
void compress_list() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL && current->next != NULL) {
        if ((current->rec.s == current->next->rec.s) &&
            (current->rec.i == current->next->rec.i) &&
            (current->rec.f == current->next->rec.f)) {

            Node* to_delete = current->next;
            current->next = to_delete->next;
            free(to_delete);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list.lock);
}

// Batch insert records
void batch_insert(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        add_record(records[i]);
    }
}

// Serialize the linked list to a file
void serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        fwrite(&(current->rec), sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list.lock);
}

// Deserialize the linked list from a file
void deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    Record rec;
    while (fread(&rec, sizeof(Record), 1, file)) {
        add_record(rec);
    }

    fclose(file);
}

// Handle memory pool
void handle_memory_pool() {
    // Implement custom memory pool logic here
}

int main() {
    srand(time(NULL));
    initialize_arrays(10);

    for (size_t i = 0; i < capacity; ++i) {
        keys[i] = rand() % 100;
        offsets[i] = (i == 0) ? keys[i] : offsets[i - 1] + keys[i];
    }

    // Example usage
    Record rec = { .s = rand() % 100, .i = rand() % 1000, .f = rand() / (float)RAND_MAX };
    add_record(rec);

    iterate_list();
    compress_list();

    serialize_to_file("data.bin");
    deserialize_from_file("data.bin");

    return 0;
}
