#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct item {
    double value;
    int number;
    struct item *next;
} item;

typedef struct {
    double tile_size;
    int world_width;
    int world_height;
    double camera_speed;
} Config;

Config config;

void log_message(const char *message) {
    printf("%s\n", message);
}

int resize_array(void **array, size_t current_size, size_t new_size, size_t element_size) {
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) return -1;
    *array = new_array;
    return 0;
}

void initializeWorld(int initial_capacity, int min_val, int max_val) {
    srand(time(NULL));

    double *values = NULL;
    char **keys = NULL;
    item **items = NULL;

    size_t capacity = initial_capacity;
    size_t count = 0;

    if (resize_array((void**)&values, 0, capacity, sizeof(double)) ||
        resize_array((void**)&keys, 0, capacity, sizeof(char*)) ||
        resize_array((void**)&items, 0, capacity, sizeof(item*))) {
        log_message("Memory allocation failed");
        return;
    }

    for (size_t i = 0; i < capacity; ++i) {
        values[i] = ((double)rand() / RAND_MAX) * 100.0;

        keys[i] = malloc(10);
        snprintf(keys[i], 10, "key_%zu", i);

        items[i] = malloc(sizeof(item));
        items[i]->value = values[i];
        items[i]->number = min_val + rand() % (max_val - min_val + 1);

        if (i < capacity - 1) {
            items[i]->next = items[i+1];
        } else {
            items[i]->next = NULL;
        }
    }

    count = capacity;

    // Example of dynamic resizing
    size_t new_capacity = capacity * 2;
    if (resize_array((void**)&values, capacity, new_capacity, sizeof(double)) ||
        resize_array((void**)&keys, capacity, new_capacity, sizeof(char*)) ||
        resize_array((void**)&items, capacity, new_capacity, sizeof(item*))) {
        log_message("Memory reallocation failed");
    } else {
        for (size_t i = capacity; i < new_capacity; ++i) {
            values[i] = ((double)rand() / RAND_MAX) * 100.0;

            keys[i] = malloc(10);
            snprintf(keys[i], 10, "key_%zu", i);

            items[i] = malloc(sizeof(item));
            items[i]->value = values[i];
            items[i]->number = min_val + rand() % (max_val - min_val + 1);

            if (i < new_capacity - 1) {
                items[i]->next = items[i+1];
            } else {
                items[i]->next = NULL;
            }
        }

        count = new_capacity;
    }

    log_message("World initialized successfully");

    // Free allocated memory
    for (size_t i = 0; i < count; ++i) {
        free(keys[i]);
        item *current = items[i];
        while (current != NULL) {
            item *next = current->next;
            free(current);
            current = next;
        }
    }

    free(values);
    free(keys);
    free(items);
}

void loadConfig(const char *filename) {
    xmlDocPtr doc = xmlReadFile(filename, NULL, 0);
    if (doc == NULL) {
        log_message("Failed to parse XML");
        return;
    }

    xmlNode *root_element = xmlDocGetRootElement(doc);

    for (xmlNode *node = root_element->children; node != NULL; node = node->next) {
        if (node->type == XML_ELEMENT_NODE) {
            if (!strcmp((const char *)node->name, "tile_size")) {
                xmlChar *value = xmlNodeListGetString(doc, node->xmlChildrenNode, 1);
                config.tile_size = atof((const char *)value);
                xmlFree(value);
            } else if (!strcmp((const char *)node->name, "world_width")) {
                xmlChar *value = xmlNodeListGetString(doc, node->xmlChildrenNode, 1);
                config.world_width = atoi((const char *)value);
                xmlFree(value);
            } else if (!strcmp((const char *)node->name, "world_height")) {
                xmlChar *value = xmlNodeListGetString(doc, node->xmlChildrenNode, 1);
                config.world_height = atoi((const char *)value);
                xmlFree(value);
            } else if (!strcmp((const char *)node->name, "camera_speed")) {
                xmlChar *value = xmlNodeListGetString(doc, node->xmlChildrenNode, 1);
                config.camera_speed = atof((const char *)value);
                xmlFree(value);
            }
        }
    }

    xmlFreeDoc(doc);

    log_message("Configuration loaded successfully");
}

int main() {
    loadConfig("config.xml");

    initializeWorld(10, 0, 100);

    return 0;
}
