['Below is a C implementation of a dynamically allocated hash table for managing `UserSession` structures with support for concurrent operations using traditional locking mechanisms. This example uses mutexes for concurrency control, which provides simplicity while balancing performance needs. For more sophisticated scenarios, you might consider lock-free or fine-grained locking techniques.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct {
    int UserID;
    time_t LastActiveTime;
    char SessionData[256];
} UserSession;

typedef struct Node {
    UserSession session;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_mutex_t locks[TABLE_SIZE];
} HashTable;

unsigned int hash(int userID, size_t tableSize) {
    return (unsigned int)userID % tableSize;
}

HashTable* create_table(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Node**)calloc(size, sizeof(Node*));

    for (int i = 0; i < size; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    return table;
}

void destroy_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(table->buckets);

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table);
}

void add_session(HashTable* table, UserSession session) {
    int index = hash(session.UserID, table->size);
    pthread_mutex_lock(&table->locks[index]);

    Node* newNode = (Node*)malloc(sizeof(Node));
    *newNode = (Node){.session = session, .next = NULL};

    if (table->buckets[index] == NULL) {
        table->buckets[index] = newNode;
    } else {
        Node* current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&table->locks[index]);
}

UserSession* get_session(HashTable* table, int userID) {
    int index = hash(userID, table->size);
    pthread_mutex_lock(&table->locks[index]);

    Node* current = table->buckets[index];
    while (current != NULL) {
        if (current->session.UserID == userID) {
            pthread_mutex_unlock(&table->locks[index]);
            return &current->session;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

void update_session(HashTable* table, UserSession session) {
    int index = hash(session.UserID, table->size);
    pthread_mutex_lock(&table->locks[index]);

    Node* current = table->buckets[index];
    while (current != NULL) {
        if (current->session.UserID == session.UserID) {
            current->session.LastActiveTime = time(NULL);
            strncpy(current->session.SessionData, session.SessionData, sizeof(session.SessionData));
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
}

void delete_expired_sessions(HashTable* table, time_t gracePeriod) {
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < table->size; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        Node *current = table->buckets[i], *prev = NULL;
        while (current != NULL) {
            if ((currentTime - current->session.LastActiveTime) > gracePeriod) {
                if (prev == NULL) {
                    table->buckets[i] = current->next;
                    free(current);
                    current = table->buckets[i];
                } else {
                    prev->next = current->next;
                    free(current);
                    current = prev->next;
                }
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&table->locks[i]);
    }
}

// Main function for testing
int main() {
    HashTable* table = create_table(TABLE_SIZE);

    UserSession session1 = { .UserID = 1, .LastActiveTime = time(NULL), .SessionData = "data1" };
    add_session(table, session1);

    update_session(table, (UserSession){.UserID = 1, .LastActiveTime = time(NULL), .SessionData = "updated_data"});

    UserSession* retrievedSession = get_session(table, 1);
    if (retrievedSession != NULL) {
        printf("Retrieved Session: %d, Data: %s\n", retrievedSession->UserID, retrievedSession->SessionData);
    }

    delete_expired_sessions(table, 60); // Example grace period of 60 seconds

    destroy_table(table);

    return 0;
}
```

### Key Points:
- **Hash Function**: Simple modulo operation is used for hashing.
- **Concurrency**: Uses a separate mutex per bucket to reduce lock contention.
- **Memory Management**: Allocates and frees nodes dynamically, with consideration for potential memory leaks if operations are not properly synchronized.
- **Session Management**: Supports adding, updating, retrieving, and deleting sessions based on expiration time.

This code provides a foundation that can be expanded upon by exploring alternative hash functions or collision resolution strategies to optimize performance under different workloads. Additionally, you could investigate lock-free data structures for further optimization in high-concurrency environments.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>

typedef struct record {
    short s;
    int i;
    float f;
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    size_t offset_size;
    int *keys;
    size_t key_size;
    Record *head;
    pthread_mutex_t lock;
    void *memory_pool; // Custom memory pool
    size_t pool_size;
} DataManager;

DataManager* create_data_manager(size_t initial_key_size, int key_range_start, int key_range_end) {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->offsets = calloc(initial_key_size, sizeof(long));
    dm->keys = malloc(initial_key_size * sizeof(int));
    if (!dm->offsets || !dm->keys) {
        free(dm->offsets);
        free(dm->keys);
        free(dm);
        return NULL;
    }

    dm->offset_size = initial_key_size;
    dm->key_size = initial_key_size;

    for (size_t i = 0; i < initial_key_size; ++i) {
        dm->keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);
    }

    long cumulative_sum = 0;
    for (size_t i = 0; i < initial_key_size; ++i) {
        cumulative_sum += dm->keys[i];
        dm->offsets[i] = cumulative_sum + 10; // Example constant value
    }

    dm->head = NULL;

    pthread_mutex_init(&dm->lock, NULL);

    // Custom memory pool initialization (e.g., size of 1024 nodes)
    dm->pool_size = 1024;
    dm->memory_pool = malloc(dm->pool_size * sizeof(Record));
    if (!dm->memory_pool) {
        free(dm->offsets);
        free(dm->keys);
        pthread_mutex_destroy(&dm->lock);
        free(dm);
        return NULL;
    }

    signal(SIGTERM, handle_termination);

    return dm;
}

void resize_arrays(DataManager *dm, size_t new_key_size) {
    long *new_offsets = realloc(dm->offsets, new_key_size * sizeof(long));
    int *new_keys = realloc(dm->keys, new_key_size * sizeof(int));

    if (new_offsets && new_keys) {
        for (size_t i = dm->key_size; i < new_key_size; ++i) {
            new_keys[i] = rand() % 100; // Random unique integer within a range
        }

        long cumulative_sum = 0;
        for (size_t i = 0; i < new_key_size; ++i) {
            cumulative_sum += new_keys[i];
            new_offsets[i] = cumulative_sum + 10; // Example constant value
        }

        dm->offsets = new_offsets;
        dm->keys = new_keys;

        dm->key_size = new_key_size;
        dm->offset_size = new_key_size;
    } else {
        fprintf(stderr, "Failed to resize arrays\n");
        exit(EXIT_FAILURE);
    }
}

Record* allocate_record(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    if (dm->head && !dm->head->next) { // Simple pool management
        Record *new_node = malloc(sizeof(Record));
        if (!new_node) {
            pthread_mutex_unlock(&dm->lock);
            return NULL;
        }
        dm->head = new_node;
    } else {
        Record *new_node = (Record*)malloc(sizeof(Record)); // Pool exhausted, allocate normally
        if (!new_node) {
            pthread_mutex_unlock(&dm->lock);
            return NULL;
        }

        static size_t next_free_index = 0;
        if (next_free_index < dm->pool_size) {
            new_node = (Record*)((char*)dm->memory_pool + next_free_index * sizeof(Record));
            next_free_index++;
        }
    }

    pthread_mutex_unlock(&dm->lock);

    if (!new_node) return NULL;

    new_node->s = rand() % 1000; // Short random value
    new_node->i = rand() % 10000; // Int random value
    new_node->f = (float)(rand() / (RAND_MAX / 100.0)); // Float random value
    new_node->next = NULL;

    return new_node;
}

void append_record(DataManager *dm, Record *record) {
    pthread_mutex_lock(&dm->lock);

    if (!dm->head) {
        dm->head = record;
    } else {
        Record *current = dm->head;
        while (current->next) {
            current = current->next;
        }
        current->next = record;
    }

    pthread_mutex_unlock(&dm->lock);
}

void handle_termination(int signum) {
    fprintf(stderr, "Process terminated gracefully\n");
    exit(EXIT_FAILURE); // Or perform any cleanup
}

void free_data_manager(DataManager *dm) {
    Record *current = dm->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }

    free(dm->offsets);
    free(dm->keys);
    free(dm->memory_pool);

    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

int main() {
    srand(time(NULL));

    DataManager *dm = create_data_manager(10, 1, 100);
    if (!dm) {
        fprintf(stderr, "Failed to initialize data manager\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 20; ++i) { // Append more records than initial key size
        Record *record = allocate_record(dm);
        if (!record) {
            fprintf(stderr, "Failed to allocate record\n");
            free_data_manager(dm);
            return EXIT_FAILURE;
        }
        append_record(dm, record);
    }

    free_data_manager(dm);

    return 0;
}
