            result = chacha20_encrypt(ctx, plaintext, plaintext_len, *ciphertext, ciphertext_len);
            break;
        // Add more cases for other algorithms
    }

    pthread_mutex_unlock(&ctx->lock);

    return result;
}

// Clean up the context
