['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct Record1 {
    short s;
    int i;
    float f;
} Record1;

typedef struct Record2 {
    double d;
    char *str;
} Record2;

typedef union Record {
    Record1 r1;
    Record2 r2;
} Record;

typedef struct Node {
    atomic_int key;
    atomic_long offset;
    Record record;
    struct Node *next;
    struct Node *prev; // For doubly linked configuration
    _Atomic(struct Node *) next_atomic; // For lock-free operations
} Node;

typedef struct LinkedList {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
    int mode; // 0 for singly, 1 for doubly
} LinkedList;

// Function prototypes
void init_linked_list(LinkedList *list, int initial_capacity);
void insert_record(LinkedList *list, Record record, int key_range_min, int key_range_max);
void resize_arrays(long **offsets, int **keys, size_t current_size, size_t new_size);
void iterate_list(const LinkedList *list);
void compress_list(LinkedList *list);
void batch_insert_records(LinkedList *list, Record records[], size_t count);
void serialize_list_to_file(const LinkedList *list, const char *filename);

// Initialize the linked list
void init_linked_list(LinkedList *list, int initial_capacity) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = list->tail = NULL;
    list->mode = 0; // Start with singly linked configuration

    long *offsets = (long *)malloc(initial_capacity * sizeof(long));
    int *keys = (int *)malloc(initial_capacity * sizeof(int));

    for (size_t i = 0; i < initial_capacity; ++i) {
        keys[i] = rand() % key_range_max + key_range_min;
        offsets[i] = (i > 0) ? offsets[i - 1] + keys[i - 1] : keys[0];
    }

    // Initialize linked list with the first element
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->key.store(keys[0]);
    new_node->offset.store(offsets[0]);
    list->head = new_node;
    list->tail = new_node;
}

// Insert a record into the linked list
void insert_record(LinkedList *list, Record record, int key_range_min, int key_range_max) {
    pthread_mutex_lock(&list->mutex);

    // Generate a unique key and calculate offset
    int key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
    long offset = list->tail ? list->tail->offset.load() + list->tail->key.load() : key;

    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->key.store(key);
    new_node->offset.store(offset);
    memcpy(&new_node->record, &record, sizeof(Record));

    if (list->mode == 0) { // Singly linked
        new_node->next = NULL;
        list->tail->next = new_node;
        list->tail = new_node;
    } else { // Doubly linked
        new_node->prev = list->tail;
        new_node->next = NULL;
        if (list->head == NULL) {
            list->head = new_node;
        }
        list->tail->next = new_node;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Resize arrays when needed
void resize_arrays(long **offsets, int **keys, size_t current_size, size_t new_size) {
    long *new_offsets = (long *)realloc(*offsets, new_size * sizeof(long));
    int *new_keys = (int *)realloc(*keys, new_size * sizeof(int));

    if (!new_offsets || !new_keys) {
        free(new_offsets);
        free(new_keys);
        perror("Failed to resize arrays");
        exit(EXIT_FAILURE);
    }

    *offsets = new_offsets;
    *keys = new_keys;

    for (size_t i = current_size; i < new_size; ++i) {
        (*keys)[i] = rand() % key_range_max + key_range_min;
        (*offsets)[i] = (i > 0) ? (*offsets)[i - 1] + (*keys)[i - 1] : (*keys)[0];
    }
}

// Iterate over the linked list
void iterate_list(const LinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key.load(), current->offset.load());
        if (list->mode == 0) {
            current = current->next;
        } else {
            current = current->next; // For doubly linked
        }
    }
}

// Compress the linked list by merging consecutive nodes with identical values
void compress_list(LinkedList *list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current != NULL && current->next != NULL) {
        if ((memcmp(&current->record.r1, &current->next->record.r1, sizeof(Record1)) == 0) ||
            (memcmp(&current->record.r2, &current->next->record.r2, sizeof(Record2)) == 0)) {

            // Merge nodes
            current->next = current->next->next;
            if (list->mode == 1 && current->next != NULL) {
                current->next->prev = current;
            }
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Batch insert records into the linked list
void batch_insert_records(LinkedList *list, Record records[], size_t count) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < count; ++i) {
        int key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        long offset = list->tail ? list->tail->offset.load() + list->tail->key.load() : key;

        Node *new_node = (Node *)malloc(sizeof(Node));
        new_node->key.store(key);
        new_node->offset.store(offset);
        memcpy(&new_node->record, &records[i], sizeof(Record));

        if (list->mode == 0) { // Singly linked
            new_node->next = NULL;
            list->tail->next = new_node;
            list->tail = new_node;
        } else { // Doubly linked
            new_node->prev = list->tail;
            new_node->next = NULL;
            if (list->head == NULL) {
                list->head = new_node;
            }
            list->tail->next = new_node;
            list->tail = new_node;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Serialize the linked list to a file
void serialize_list_to_file(const LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    Node *current = list->head;
    while (current != NULL) {
        fwrite(&current->key.load(), sizeof(int), 1, file);
        fwrite(&current->offset.load(), sizeof(long), 1, file);
        fwrite(&current->record, sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);
}

int main() {
    LinkedList list;
    init_linked_list(&list, 10);

    Record rec1 = {.r1 = {1, 2, 3.0}};
    insert_record(&list, rec1, 0, 100);

    Record records[5];
    for (size_t i = 0; i < 5; ++i) {
        records[i] = (Record){.r1 = {(short)i, (int)(i * 10), (float)i + 0.5}};
    }
    batch_insert_records(&list, records, 5);

    iterate_list(&list);
    compress_list(&list);
    serialize_list_to_file(&list, "linked_list.dat");

    return 0;
}
