#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
} Record;

// Global synchronization primitives
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t condition_var = PTHREAD_COND_INITIALIZER;
static size_t max_memory_usage = 1024 * 1024; // Example threshold (1MB)

// Log function
void log_operation(const char* message) {
    FILE* log_file = fopen("memory_operations.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

// Memory management
Record* allocate_records(size_t count, int min_val, int max_val, const int* static_init_data) {
    pthread_mutex_lock(&memory_lock);

    Record* records = NULL;
    size_t allocated_size = 0;

    if (static_init_data != NULL && count <= sizeof(static_init_data) / sizeof(static_init_data[0])) {
        // Static initialization
        records = malloc(count * sizeof(Record));
        for (size_t i = 0; i < count; ++i) {
            records[i].value = static_init_data[i];
            allocated_size += sizeof(Record);
        }
    } else {
        // Dynamic population
        records = malloc(count * sizeof(Record));
        if (!records) {
            log_operation("Memory allocation failed");
            pthread_mutex_unlock(&memory_lock);
            return NULL;
        }

        for (size_t i = 0; i < count; ++i) {
            records[i].value = rand() % (max_val - min_val + 1) + min_val;
            allocated_size += sizeof(Record);

            if (allocated_size > max_memory_usage) {
                log_operation("Memory usage exceeded threshold, initiating cleanup");
                free(records);
                pthread_mutex_unlock(&memory_lock);
                return NULL;
            }
        }
    }

    if (!records) {
        log_operation("Failed to allocate records due to insufficient memory");
    } else {
        log_operation("Records successfully allocated and initialized");
    }

    pthread_mutex_unlock(&memory_lock);

    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
        log_operation("Memory freed for records");
    }
}

// Usage example
int main() {
    srand((unsigned int)time(NULL));

    const int static_data[] = {10, 20, 30};
    size_t record_count = 5;

    Record* my_records = allocate_records(record_count, 0, 100, NULL);
    if (my_records) {
        // Use records...

        free_records(my_records);
    }

    return 0;
}
