#[derive(Debug)]
struct Node {
    record: Record,
    prev: Option<Arc<RwLock<Node>>>,
    next: Option<Arc<RwLock<Node>>>,
}

impl Node {
    fn new(record: Record) -> Self {
        Node {
            record,
            prev: None,
            next: None,
        }
    }
}

// Define the doubly linked list.
#[derive(Debug)]
struct DoublyLinkedList {
    head: Option<Arc<RwLock<Node>>>,
    tail: Option<Arc<RwLock<Node>>>,
    len: usize,
}

impl DoublyLinkedList {
    fn new() -> Self {
        DoublyLinkedList {
            head: None,
            tail: None,
            len: 0,
        }
    }

    fn append(&mut self, record: Record) {
        let node = Arc::new(RwLock::new(Node::new(record)));
        let mut node = node.clone();

        if let Some(tail) = &self.tail {
            let mut tail_node = tail.write().unwrap();
            tail_node.next = Some(node.clone());
            node.prev = Some(Arc::clone(tail));
        } else {
            self.head = Some(node.clone());
        }

        *node.write().unwrap().next = None;
        self.tail = Some(node);
        self.len += 1;
    }
}

