#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct item {
    double value;
    int random_int;
    struct item *next;
    long identifier;
    unsigned int index;
} Item;

#define INITIAL_CAPACITY 10

pthread_mutex_t counter_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long global_item_count = 0;

Item* create_items(int initial_capacity, int range_min, int range_max) {
    pthread_mutex_lock(&counter_lock);
    global_item_count += initial_capacity;
    pthread_mutex_unlock(&counter_lock);

    Item *items = (Item *)malloc(initial_capacity * sizeof(Item));
    if (!items) {
        perror("Failed to allocate memory for items");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < initial_capacity; ++i) {
        items[i].value = ((double)rand() / RAND_MAX) * 100.0;
        items[i].random_int = rand() % (range_max - range_min + 1) + range_min;
        items[i].next = NULL;
        items[i].identifier = i; // Simple unique identifier for demonstration
        items[i].index = i;
    }

    return items;
}

Item* resize_items(Item *items, int new_capacity) {
    Item *new_items = (Item *)realloc(items, new_capacity * sizeof(Item));
    if (!new_items) {
        perror("Failed to reallocate memory for items");
        free(items);
        exit(EXIT_FAILURE);
    }

    for (int i = new_capacity / 2; i < new_capacity; ++i) {
        new_items[i].value = ((double)rand() / RAND_MAX) * 100.0;
        new_items[i].random_int = rand() % 100 + 1; // Assuming a range of 1 to 100
        new_items[i].next = NULL;
        new_items[i].identifier = global_item_count + i - (new_capacity / 2);
        new_items[i].index = i;
    }

    pthread_mutex_lock(&counter_lock);
    global_item_count += new_capacity / 2;
    pthread_mutex_unlock(&counter_lock);

    return new_items;
}

void free_items(Item *items) {
    free(items);
}

// Unit tests
void test_create_and_resize() {
    Item *items = create_items(INITIAL_CAPACITY, 1, 10);
    printf("Initial items created: %lu\n", global_item_count);

    int new_capacity = INITIAL_CAPACITY * 2;
    items = resize_items(items, new_capacity);
    printf("Items after resizing: %lu\n", global_item_count);

    free_items(items);
}

int main() {
    test_create_and_resize();
    return 0;
}
```

### Explanation:
- **Thread Safety:** A mutex `counter_lock` is used to ensure thread-safe access and modification of the `global_item_count`.
- **Dynamic Memory Management:** The function `create_items` initializes a collection with an initial capacity. If more space is needed, `resize_items` reallocates memory.
- **Initialization:** Each item is initialized with random values for `value` and `random_int`, a unique identifier, and a sequential index.
- **Unit Test:** A simple test function `test_create_and_resize` validates the creation and resizing of items.

This code provides a foundation for integrating into a concurrent data processing pipeline while maintaining thread safety and performance.']

