#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1000
#define INITIAL_SIZE 10
#define OFFSET_CONSTANT 5

typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    char c_field[100];
    struct Record* next;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    size_t size;
    size_t capacity;
} KeyArray;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long calculate_offset(int key, int index, const int* keys) {
    return (index > 0 ? keys[index - 1] : 0) + OFFSET_CONSTANT + key;
}

void init_random() {
    srand(time(NULL));
}

int generate_random_key(int range_min, int range_max) {
    return rand() % (range_max - range_min + 1) + range_min;
}

short generate_random_short(short min, short max) {
    return (short)(rand() % ((max - min) + 1)) + min;
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

float generate_random_float(float min, float max) {
    return min + static_cast <float> (rand()) /( static_cast <float> (RAND_MAX/(max-min)));
}

void fill_random_chars(char* str, int length, const char* prefix) {
    for (int i = 0; i < length - strlen(prefix); ++i) {
        while (1) {
            str[i + strlen(prefix)] = 'a' + rand() % 26;
            if (str[i + strlen(prefix)] != prefix[i]) break;
        }
    }
    str[length] = '\0';
}

Record* create_record(const char* prev_prefix) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->s_field = generate_random_short(1, 32767);
    record->i_field = generate_random_int(1, 10000);
    record->f_field = generate_random_float(0.0, 100.0);

    char prefix[3] = { 'a' + rand() % 26, 'a' + rand() % 26, '\0' };
    fill_random_chars(record->c_field, sizeof(record->c_field), prev_prefix ? prev_prefix : "");

    record->next = NULL;
    return record;
}

void resize_key_array(KeyArray* key_array) {
    size_t new_capacity = key_array->capacity * 2;
    int* new_keys = (int*)realloc(key_array->keys, new_capacity * sizeof(int));
    long* new_offsets = (long*)realloc(key_array->offsets, new_capacity * sizeof(long));

    if (!new_keys || !new_offsets) {
        perror("Failed to resize arrays");
        exit(EXIT_FAILURE);
    }

    key_array->keys = new_keys;
    key_array->offsets = new_offsets;
    key_array->capacity = new_capacity;
}

void process_data(KeyArray* key_array, Record** head) {
    pthread_mutex_lock(&lock);

    if (key_array->size >= key_array->capacity) {
        resize_key_array(key_array);
    }

    int new_key = generate_random_key(1, 10000); // Ensure uniqueness as needed
    while (new_key == key_array->keys[key_array->size - 1]) { // Simple check for example purposes
        new_key = generate_random_key(1, 10000);
    }
    key_array->keys[key_array->size++] = new_key;

    long offset = calculate_offset(new_key, key_array->size - 1, key_array->keys);
    key_array->offsets[key_array->size - 1] = offset;

    char prev_prefix[3] = { 'x', 'x', '\0' }; // Assume no prefix for the first record
    if (*head) {
        Record* current = *head;
        while (current->next) {
            memcpy(prev_prefix, current->c_field, 2);
            current = current->next;
        }
    }

    Record* new_record = create_record(prev_prefix);
    if (!new_record) {
        perror("Failed to allocate record");
        exit(EXIT_FAILURE);
    }

    new_record->next = *head;
    *head = new_record;

    pthread_mutex_unlock(&lock);
}

void free_memory(KeyArray* key_array, Record* head) {
    while (head) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
    free(key_array->keys);
    free(key_array->offsets);
}

int main() {
    init_random();

    KeyArray key_array = { .size = 0, .capacity = INITIAL_SIZE };
    key_array.keys = (int*)malloc(INITIAL_SIZE * sizeof(int));
    key_array.offsets = (long*)malloc(INITIAL_SIZE * sizeof(long));

    if (!key_array.keys || !key_array.offsets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    Record* head = NULL;
    for (int i = 0; i < MAX_KEYS; ++i) {
        process_data(&key_array, &head);
    }

    // Example iteration
    for (Record* current = head; current != NULL; current = current->next) {
        printf("Short: %d, Int: %d, Float: %.2f, String: %s\n", 
               current->s_field, current->i_field, current->f_field, current->c_field);
    }

    free_memory(&key_array, head);

    pthread_mutex_destroy(&lock);
    return 0;
}
