    {
        SourceIP = sourceIP;
        DestinationIP = destinationIP;
        ProtocolType = protocolType;
    }
}

public class TrafficFlowManager : MonoBehaviour
{
    private ConcurrentDictionary<string, List<TrafficFlow>> trafficFlows;
    private static readonly HttpClient httpClient = new HttpClient();
    private string cacheKey = "trafficData";
    private DateTime lastFetchTime;
    private TimeSpan cacheDuration;

    public TrafficFlowManager(TimeSpan cacheExpiry)
    {
        trafficFlows = new ConcurrentDictionary<string, List<TrafficFlow>>();
        cacheDuration = cacheExpiry;
        lastFetchTime = DateTime.MinValue;
    }

    public void Initialize()
    {
        // Perform initial setup if needed
    }

    public bool AddTrafficFlow(TrafficFlow flow)
    {
        var key = $"{flow.SourceIP}-{flow.DestinationIP}";
        if (!trafficFlows.ContainsKey(key))
            trafficFlows[key] = new List<TrafficFlow>();

        return trafficFlows[key].Add(flow);
    }

    public bool RemoveTrafficFlow(string sourceIP, string destinationIP)
    {
        var key = $"{sourceIP}-{destinationIP}";
        if (trafficFlows.TryGetValue(key, out var flows))
        {
            var flowToRemove = flows.FirstOrDefault(f => f.SourceIP == sourceIP && f.DestinationIP == destinationIP);
            if (flowToRemove != null)
                return flows.Remove(flowToRemove);

            trafficFlows.TryRemove(key, out _);
            return true;
        }

        return false;
    }

    public async Task FetchAndUpdateTrafficDataAsync(string apiEndpoint, string authToken)
    {
        try
        {
            if ((DateTime.UtcNow - lastFetchTime) >= cacheDuration)
            {
                var request = new HttpRequestMessage(HttpMethod.Get, apiEndpoint);
                request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", authToken);

                var response = await httpClient.SendAsync(request);
                response.EnsureSuccessStatusCode();

                var data = await response.Content.ReadAsStringAsync();
                // Assume a method to parse and update trafficFlows from the response
                UpdateTrafficData(data);

                lastFetchTime = DateTime.UtcNow;
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error fetching traffic data: {ex.Message}");
        }
    }

    private void UpdateTrafficData(string jsonData)
    {
        // Implement JSON parsing and updating logic here
    }

    public override string ToString()
    {
        var totalFlows = trafficFlows.Sum(kvp => kvp.Value.Count);
        return $"Total Traffic Flows: {totalFlows}";
    }

    // Unit tests and performance benchmarks should be implemented separately.
}
