// Function to initialize records with random words
int init_records(Record **records, size_t num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds the maximum limit.\n");
        return -1;
    }

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        return -1;
    }

    // Simulate fetching random words (for demonstration)
    const char *word_pool[] = {"apple", "banana", "cherry", "date", "elderberry"};
    size_t pool_size = sizeof(word_pool) / sizeof(word_pool[0]);

    srand(time(NULL)); // Seed for deterministic shuffle

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = rand() % 100000;
        (*records)[i].key = rand() % 100;

        size_t word_index = rand() % pool_size;
        size_t word_len = strlen(word_pool[word_index]) + 1;
        (*records)[i].word = malloc(word_len);
        if ((*records)[i].word == NULL) {
            perror("Failed to allocate memory for word");
            // Free already allocated resources
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].word);
            }
            free(*records);
            *records = NULL;
            return -1;
        }
        strcpy((*records)[i].word, word_pool[word_index]);
    }

    // Shuffle records based on offset
    for (size_t i = num_records; i > 0; --i) {
        size_t j = rand() % i;
        Record temp = (*records)[i - 1];
        (*records)[i - 1] = (*records)[j];
        (*records)[j] = temp;
    }

    return 0;
}

// Function to free allocated records
void free_records(Record *records, size_t num_records) {
    if (records == NULL) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].word);
    }
    free(records);
}

int main() {
    Record *records = NULL;
    size_t num_records = 5000; // Example number of records

    if (init_records(&records, num_records) == 0) {
        printf("Records initialized successfully.\n");

        // Example: Accessing a record
        if (num_records > 0) {
            printf("Record %zu: Offset=%ld, Key=%d, Word=%s\n",
                   0, records[0].offset, records[0].key, records[0].word);
        }

        free_records(records, num_records);
    } else {
        fprintf(stderr, "Failed to initialize records.\n");
    }

    return 0;
}
