typedef struct FileInfo {
    char FilePath[256];
    time_t ModificationTime;
    off_t FileSize;
    char OwnerName[50];
} FileInfo;

typedef struct TreeNode {
    FileInfo *file_info;
    struct TreeNode **children;
    int children_count;
} TreeNode;

TreeNode* create_node() {
    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));
    node->file_info = NULL;
    node->children = NULL;
    node->children_count = 0;
    return node;
}

void free_tree(TreeNode *root) {
    if (!root) return;
    for (int i = 0; i < root->children_count; ++i)
        free_tree(root->children[i]);
    free(root->file_info);
    free(root->children);
    free(root);
}

TreeNode* find_node(TreeNode *root, const char *path) {
    if (!strcmp(root->file_info->FilePath, path)) return root;
    for (int i = 0; i < root->children_count; ++i)
        TreeNode *found = find_node(root->children[i], path);
        if (found) return found;
    return NULL;
}

void add_or_update_node(TreeNode **root, const char *path, time_t mod_time, off_t file_size, const char *owner_name) {
    TreeNode *node = find_node(*root, path);
    if (!node) {
        node = create_node();
        strcpy(node->file_info->FilePath, path);
        node->file_info->ModificationTime = mod_time;
        node->file_info->FileSize = file_size;
        strcpy(node->file_info->OwnerName, owner_name);

        // Add to tree (simplified)
        int new_children_count = (*root)->children_count + 1;
        (*root)->children = realloc((*root)->children, sizeof(TreeNode*) * new_children_count);
        (*root)->children[(*root)->children_count] = node;
        (*root)->children_count = new_children_count;
    } else {
        node->file_info->ModificationTime = mod_time;
        node->file_info->FileSize = file_size;
        strcpy(node->file_info->OwnerName, owner_name);
    }
}

void batch_delete_old_files(TreeNode *root) {
    time_t now = time(NULL);
    if (difftime(now, root->file_info->ModificationTime) > 60*24*60*60) { // Older than 60 days
        free_tree(root); 
        return;
    }

    for (int i = 0; i < root->children_count; ++i)
        batch_delete_old_files(root->children[i]);
}

void compress_directory(TreeNode *node) {
    if (node->children_count > 100) {
        // Pseudo-compression logic
        printf("Compressing directory at %s\n", node->file_info->FilePath);
    }
    for (int i = 0; i < node->children_count; ++i)
        compress_directory(node->children[i]);
}

void archive_large_directories(TreeNode *root, off_t size_threshold) {
    off_t total_size = 0;
    for (int i = 0; i < root->children_count; ++i) 
        total_size += root->children[i]->file_info->FileSize + archive_large_directories(root->children[i], size_threshold);

    if (total_size > size_threshold) {
        // Pseudo-archive logic
        printf("Archiving directory at %s\n", root->file_info->FilePath);
    }
    return total_size;
}

void process_images(const char *image_folder_path, const char *processing_script_path, const char *output_directory_path) {
