int generate_directory_path(char *dir_path, size_t buf_size) {
    const char *env_dir = getenv("DIR_PATH");
    char root_dir[] = "/default/root/directory";
    char timestamp[20];
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&now));

    if (env_dir && strlen(env_dir) + strlen(timestamp) + 10 < buf_size) {
        snprintf(dir_path, buf_size, "%s/%s_%lu", env_dir, timestamp, rand());
    } else {
        snprintf(dir_path, buf_size, "%s/%s_%lu", root_dir, timestamp, rand());
    }
    setenv("DIR_PATH", dir_path, 1);
    return access(dir_path, F_OK | X_OK) != -1;
}

