    // Create and store chunk in the hash table
    Chunk* new_chunk = create_chunk(strlen(file_content), checksum);
    if (!new_chunk) {
        log_error("Memory allocation failed for chunk");
        return NULL;
    }

    pthread_mutex_lock(&hash_locks[hash_function(unique_id)]);
    node->data = strdup(new_chunk);  // Store the pointer to chunk
    pthread_mutex_unlock(&hash_locks[hash_function(unique_id)]);

    pthread_mutex_destroy(&status_lock);
    free(path);
    return NULL;
}

// Create a new chunk with dynamic memory management
Chunk* create_chunk(size_t length, unsigned int checksum) {
    pthread_mutex_lock(&pool_mutex);

    if (pool_offset + sizeof(Chunk) > MEMORY_POOL_SIZE) {
        log_error("Memory pool exhausted");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    Chunk *chunk = (Chunk *)(memory_pool + pool_offset);
    pool_offset += sizeof(Chunk);

    chunk->length = length;
    chunk->checksum = checksum;
    chunk->metadata = malloc(MAX_METADATA_SIZE);  // Allocate metadata
    if (!chunk->metadata) {
        log_error("Memory allocation failed for metadata");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    strcpy((char *)chunk->metadata, "example_metadata");
    chunk->status = 'P';  // Assume initial status is 'Pending'
    chunk->error_message = malloc(128);  // Allocate error message storage
    if (!chunk->error_message) {
        free(chunk->metadata);
        log_error("Memory allocation failed for error message");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    strcpy(chunk->error_message, "No error");

    pthread_mutex_unlock(&pool_mutex);

    return chunk;
}

// Compute checksum (simple sum of bytes for demo)
unsigned int calculate_checksum(const void *data, size_t length) {
    const unsigned char *bytes = data;
    unsigned int checksum = 0;
    while (length--) {
        checksum += *bytes++;
    }
    return checksum;
}

// Hash function to determine index in the hash table
int hash_function(int key) {
