#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000

typedef struct {
    short field1;
    int field2;
    float field3;
    uint64_t timestamp; // Assuming UNIX epoch time as integer
    float weight;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    long* offsets;
    int* keys;
    Node* head;
    Node* tail;
    size_t capacity;
    pthread_mutex_t lock; // Simplified locking for demonstration
    unsigned long seed;
} RecordCollection;

RecordCollection* init_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->offsets = (long*)calloc(initial_capacity, sizeof(long));
    collection->keys = (int*)malloc(initial_capacity * sizeof(int));
    collection->head = NULL;
    collection->tail = NULL;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    srand(time(NULL)); // Seed for random number generation
    collection->seed = rand(); 

    return collection;
}

int is_prime(int n) {
    if (n <= 1) return 0;
    if (n <= 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;

    for (int i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0)
            return 0;
    return 1;
}

void populate_keys(int* keys, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        int key;
        do {
            key = rand() % (MAX_RECORDS * 10);
        } while (!is_prime(key));
        keys[i] = key;
    }
}

void calculate_offsets(long* offsets, int* keys, size_t size) {
    long cumulative_sum = 0;
    for (size_t i = 0; i < size; ++i) {
        cumulative_sum += keys[i];
        offsets[i] = cumulative_sum + (i * 10); // Example increment
    }
}

void generate_random_record(Record* record, unsigned long seed) {
    srand(seed);
    record->field1 = rand() % 100;
    record->field2 = rand() % 10000;
    record->field3 = ((float)rand()) / RAND_MAX * 100.0f;
    record->timestamp = (uint64_t)time(NULL) + rand() % 1000000; // Example range
    record->weight = ((float)rand()) / RAND_MAX * 10.0f;
}

void add_record(RecordCollection* collection, Record record) {
    pthread_mutex_lock(&collection->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    new_node->record = record;
    new_node->next = NULL;

    if (collection->tail == NULL) {
        collection->head = collection->tail = new_node;
    } else {
        collection->tail->next = new_node;
        new_node->prev = collection->tail;
        collection->tail = new_node;
    }

    pthread_mutex_unlock(&collection->lock);
}

void resize_record_collection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    size_t new_capacity = collection->capacity * 2;
    long* new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        pthread_mutex_unlock(&collection->lock);
        return; // Handle memory allocation failure
    }

    collection->offsets = new_offsets;
    collection->keys = new_keys;
    collection->capacity = new_capacity;

    populate_keys(collection->keys + collection->capacity / 2, collection->capacity / 2);
    calculate_offsets(collection->offsets + (collection->capacity / 2), 
                      collection->keys + (collection->capacity / 2), 
                      collection->capacity / 2);

    pthread_mutex_unlock(&collection->lock);
}

void free_record_collection(RecordCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(collection->offsets);
    free(collection->keys);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Example usage
int main() {
    RecordCollection* collection = init_record_collection(1000);

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if ((i + 1) % 500 == 0) { // Simple resize condition
            resize_record_collection(collection);
        }

        Record record;
        generate_random_record(&record, collection->seed++);
        add_record(collection, record);
    }

    free_record_collection(collection);
    return 0;
}
