void* thread_safe_alloc(memory_pool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + size > mp->size) {
        // Implement graceful degradation strategy here
        fprintf(stderr, "Memory pool exhausted\n");
        exit(1);  // or handle gracefully
    }
    void* ptr = (char*)mp->pool + mp->used;
    mp->used += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void init_memory_pools() {
    offset_pool.size = MAX_RECORDS * sizeof(long);
    key_pool.size = MAX_RECORDS * sizeof(int);
    priority_pool.size = MAX_RECORDS * sizeof(int);
    record_pool.size = MAX_RECORDS * sizeof(record);

    offset_pool.pool = malloc(offset_pool.size);
    key_pool.pool = malloc(key_pool.size);
    priority_pool.pool = malloc(priority_pool.size);
    record_pool.pool = malloc(record_pool.size);

    pthread_mutex_init(&offset_pool.lock, NULL);
    pthread_mutex_init(&key_pool.lock, NULL);
    pthread_mutex_init(&priority_pool.lock, NULL);
    pthread_mutex_init(&record_pool.lock, NULL);
}

void free_memory_pools() {
    free(offset_pool.pool);
    free(key_pool.pool);
    free(priority_pool.pool);
    free(record_pool.pool);

    pthread_mutex_destroy(&offset_pool.lock);
    pthread_mutex_destroy(&key_pool.lock);
    pthread_mutex_destroy(&priority_pool.lock);
    pthread_mutex_destroy(&record_pool.lock);
}

long compute_offset(long* offsets, int i, const int* keys, const int* priorities) {
    long weighted_sum = 0;
    for (int j = 0; j < i; ++j) {
