}

void initialize_arrays(long* offsets, int* keys, int* priorities, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&key_pool.lock);
        keys[i] = rand() % 100000 + i;
        pthread_mutex_unlock(&key_pool.lock);

        pthread_mutex_lock(&priority_pool.lock);
        priorities[i] = rand() % 1000 + 1;
        pthread_mutex_unlock(&priority_pool.lock);

        offsets[i] = compute_offset(offsets, i, keys, priorities);
    }
}

record* create_record(int64_t timestamp, int priority) {
    record* r = thread_safe_alloc(&record_pool, sizeof(record));
    r->field1 = rand() % 100;
