    record* current = head;

    for (size_t i = 1; i < n; ++i) {
        record* new_rec = create_record(time(NULL), rand() % 100 + 1);
        current->next = new_rec;
        new_rec->prev = current;
        current = new_rec;
    }
    return head;
}

void dynamic_resize(int** array, size_t* capacity, size_t new_capacity) {
    int* temp = realloc(*array, new_capacity * sizeof(int));
    if (!temp) {
        fprintf(stderr, "Failed to resize memory\n");
