        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Session *session = &manager->sessions[manager->count++];
    generate_unique_token(session->token, TOKEN_SIZE);
    session->expiration = calculate_random_expiration();
    strncpy(session->metadata, metadata, METADATA_SIZE - 1);

    printf("Session created: %s\n", session->token); // Replace with logging

    pthread_mutex_unlock(&manager->lock);
}

