#define METADATA_LENGTH 64

typedef struct {
    char token[SESSION_TOKEN_LENGTH];
    time_t expiration;
    char metadata[METADATA_LENGTH];
} Session;

typedef struct {
    Session *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For managing concurrency
} SessionManager;

// Utility function to log messages
void log_message(const char *message) {
    printf("%s\n", message); // Replace with actual logging mechanism
}

// Function to generate a unique session token
char* generate_unique_token(SessionManager *manager) {
    static const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123459";
    char token[SESSION_TOKEN_LENGTH];

    for (int i = 0; i < SESSION_TOKEN_LENGTH - 1; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        token[i] = charset[key];
    }
    token[SESSION_TOKEN_LENGTH - 1] = '\0';

    // Ensure uniqueness within the current session pool
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].token, token) == 0) {
            return generate_unique_token(manager); // Recursively generate a new token if collision occurs
        }
    }

    strcpy(manager->sessions[manager->count].token, token);
    log_message("Session created with token: ");
    printf("%s\n", manager->sessions[manager->count].token);

    return manager->sessions[manager->count].token;
}

// Function to initialize the session manager
void init_session_manager(SessionManager *manager) {
    manager->capacity = INITIAL_POOL_SIZE;
    manager->count = 0;
    manager->sessions = malloc(manager->capacity * sizeof(Session));

    if (!manager->sessions) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL); // Initialize the mutex
}

// Function to set a randomized expiration time
time_t set_randomized_expiration() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec + rand() % (60 * 30) + 1; // Random between 1 and 30 minutes
}

// Function to add a new session
void add_session(SessionManager *manager, const char *metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Session *new_sessions = realloc(manager->sessions, new_capacity * sizeof(Session));

        if (!new_sessions) {
            perror("Failed to reallocate memory for sessions");
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }

        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    generate_unique_token(manager);
    strcpy(manager->sessions[manager->count].metadata, metadata);
    manager->sessions[manager->count].expiration = set_randomized_expiration();
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);

    log_message("Session added.");
}

// Function to iterate over sessions and perform cleanup
void cleanup_sessions(SessionManager *manager) {
    time_t now;
    time(&now);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].expiration <= now) {
            log_message("Session expired and removed: ");
            printf("%s\n", manager->sessions[i].token);

            // Shift remaining sessions
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(Session));
            --manager->count;
            --i; // Re-check the same index after shift
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to free resources
void destroy_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    SessionManager manager;
    init_session_manager(&manager);

    // Simulate adding sessions
    for (int i = 0; i < 10; ++i) {
        char metadata[METADATA_LENGTH] = "UserMetadata";
        add_session(&manager, metadata);
    }

    // Perform cleanup
    cleanup_sessions(&manager);

    destroy_session_manager(&manager);

    return 0;
}
```

