// Define packet structure with metadata, payload, and timestamp
typedef struct Packet {
    uint64_t id;
    time_t timestamp;
    char *payload;
    size_t payload_size;
    struct Packet *next;
} Packet;

#define MAX_PAYLOAD_SIZE 1024
#define MEMORY_POOL_SIZE 10000

// Global variables for memory pool and thread safety
char *memory_pool = NULL;
size_t pool_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Packet *head = NULL; // Linked list head for packet management

void initialize_memory_pool() {
    memory_pool = (char *)malloc(sizeof(Packet) * MEMORY_POOL_SIZE);
    if (!memory_pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
}

// Function to generate a unique packet ID
uint64_t generate_unique_id() {
    static uint64_t last_id = 0;
    return __sync_fetch_and_add(&last_id, 1); // Atomic increment for thread safety
}

// Allocate a new packet from the memory pool
Packet *allocate_packet(size_t payload_size) {
    if (pool_index + sizeof(Packet) + payload_size > MEMORY_POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }

    Packet *packet = (Packet *)(memory_pool + pool_index);
    packet->payload = (char *)packet + sizeof(Packet);
    packet->payload_size = payload_size;
    memcpy(packet->payload, "\0", payload_size);

    pool_index += sizeof(Packet) + payload_size;

    return packet;
}

// Insert a new packet into the system
void insert_packet() {
    pthread_mutex_lock(&mutex);

    time_t timestamp = time(NULL);
    size_t payload_size = rand() % MAX_PAYLOAD_SIZE; // Random payload size

    Packet *new_packet = allocate_packet(payload_size);
    if (!new_packet) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_packet->id = generate_unique_id();
    new_packet->timestamp = timestamp;

    new_packet->next = head;
    head = new_packet;

    // Log packet insertion (stub)
    printf("Packet ID: %llu, Timestamp: %ld, Size: %zu\n", new_packet->id, timestamp, payload_size);

    pthread_mutex_unlock(&mutex);
}

// Delete a packet by ID
void delete_packet(uint64_t id) {
    pthread_mutex_lock(&mutex);

    Packet *current = head;
    Packet *prev = NULL;

    while (current != NULL && current->id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return; // Packet not found
    }

    if (prev == NULL) { // Head needs to be updated
        head = current->next;
    } else {
        prev->next = current->next;
    }

    pool_index -= sizeof(Packet) + current->payload_size;

    pthread_mutex_unlock(&mutex);
}

// Aggregate and report packet statistics periodically
void aggregate_statistics() {
    pthread_mutex_lock(&mutex);

    size_t total_packets = 0;
    double average_payload_size = 0.0;

    Packet *current = head;
    while (current != NULL) {
        total_packets++;
        average_payload_size += current->payload_size;
        current = current->next;
    }

    if (total_packets > 0) {
        average_payload_size /= total_packets;
    }

    printf("Total Packets: %zu, Average Payload Size: %.2f\n", total_packets, average_payload_size);

    pthread_mutex_unlock(&mutex);
}

// Periodically save the state to disk
void save_state_to_disk() {
    pthread_mutex_lock(&mutex);

    // Stub function for saving packet state to disk
    FILE *file = fopen("packet_state.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    Packet *current = head;
    while (current != NULL) {
        fwrite(current, sizeof(Packet), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&mutex);
}

int main() {
    initialize_memory_pool();

    // Example usage
    insert_packet();
    aggregate_statistics();
    save_state_to_disk();

    return 0;
}
```

