} config_manager;

unsigned long generate_unique_id(config_manager *manager) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    unsigned long id = rand() % 1000000; // Simple random number for demonstration
    while (1) {
        int unique = 1;
        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->configurations[i]->identifier == id) {
                unique = 0;
                break;
            }
        }
        pthread_mutex_unlock(&manager->lock);
        if (unique) return id;
        id = rand() % 1000000;
    }
}

char *generate_random_string(size_t length) {
    char *str = malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
    return str;
}

void init_config_manager(config_manager *manager, size_t initial_capacity) {
    manager->configurations = malloc(initial_capacity * sizeof(struct_connection *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void resize_configurations(config_manager *manager) {
    size_t new_capacity = manager->capacity * 2;
    struct_connection **new_configs = realloc(manager->configurations, new_capacity * sizeof(struct_connection *));
    if (new_configs) {
        manager->configurations = new_configs;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize configurations");
        exit(EXIT_FAILURE);
    }
}

void add_configuration(config_manager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        resize_configurations(manager);
    }

    struct_connection *config = malloc(sizeof(struct_connection));
    config->protocol = generate_random_string(rand() % 32 + 1);
    config->port = PORT_MIN + rand() % (PORT_MAX - PORT_MIN + 1);
    config->identifier = generate_unique_id(manager);

    manager->configurations[manager->count++] = config;
    pthread_mutex_unlock(&manager->lock);
}

void free_config_manager(config_manager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configurations[i]->protocol);
        free(manager->configurations[i]);
    }
    free(manager->configurations);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL));

    config_manager manager;
    init_config_manager(&manager, INITIAL_CAPACITY);

    // Simulate adding configurations
    for (size_t i = 0; i < MAX_CONFIGS; ++i) {
        add_configuration(&manager);
    }

    free_config_manager(&manager);
    return 0;
}
