#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define KEY_RANGE_MAX 1000
#define CHAR_STRING_LENGTH 100

typedef struct {
    short field1;
    int field2;
    float field3;
    char string[CHAR_STRING_LENGTH];
} Record;

typedef struct EventNode {
    long timestamp;
    Record *record;
    struct EventNode *left, *right;
} EventNode;

typedef struct BSTNode {
    int key;
    EventNode *event_node;
    struct BSTNode *left, *right;
} BSTNode;

typedef struct LinkedListNode {
    Record record;
    struct LinkedListNode *prev, *next;
} LinkedListNode;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    long *timestamps;
    size_t size;
    size_t capacity;
    pthread_mutex_t bst_lock;
    pthread_mutex_t list_lock;
} EventLogger;

// Utility functions
void random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Memory management
void resize_array(EventLogger *logger, size_t new_capacity) {
    logger->offsets = (long *)realloc(logger->offsets, new_capacity * sizeof(long));
    logger->keys = (int *)realloc(logger->keys, new_capacity * sizeof(int));
    logger->records = (Record **)realloc(logger->records, new_capacity * sizeof(Record *));
    logger->timestamps = (long *)realloc(logger->timestamps, new_capacity * sizeof(long));

    if (!logger->offsets || !logger->keys || !logger->records || !logger->timestamps) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    logger->capacity = new_capacity;
}

// Initialize arrays
void initialize_logger(EventLogger *logger) {
    logger->size = 0;
    logger->capacity = INITIAL_SIZE;
    resize_array(logger, INITIAL_SIZE);

    for (size_t i = 0; i < logger->capacity; ++i) {
        logger->keys[i] = rand() % KEY_RANGE_MAX + 1;

        if (i > 0) {
            logger->offsets[i] = logger->offsets[i - 1] + logger->keys[i - 1];
        } else {
            logger->offsets[i] = logger->keys[i];
        }

        logger->records[i] = malloc(sizeof(Record));
        if (!logger->records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Populate Record with random values
        logger->records[i]->field1 = rand() % 100;
        logger->records[i]->field2 = rand() % 1000;
        logger->records[i]->field3 = (float)rand() / RAND_MAX * 100.0f;
        random_string(logger->records[i]->string, CHAR_STRING_LENGTH);

        // Assign a timestamp
        logger->timestamps[i] = time(NULL); 
    }
}

// BST operations
BSTNode* bst_insert(BSTNode *root, int key, EventLogger *logger) {
    if (!root) return (BSTNode *)malloc(sizeof(BSTNode));

    if (key < root->key)
        root->left  = bst_insert(root->left, key, logger);
    else if (key > root->key)
        root->right = bst_insert(root->right, key, logger);
    else
        return root; // Duplicate keys not allowed

    return root;
}

BSTNode* bst_search(BSTNode *root, int key) {
    if (!root || root->key == key)
        return root;

    if (key < root->key)
        return bst_search(root->left, key);

    return bst_search(root->right, key);
}

// Linked list operations
LinkedListNode* create_linked_list_node(Record *record) {
    LinkedListNode *node = malloc(sizeof(LinkedListNode));
    node->record = *record;
    node->prev = node->next = NULL;
    return node;
}

void append_to_linked_list(LinkedListNode **head, Record *record) {
    LinkedListNode *new_node = create_linked_list_node(record);

    if (*head == NULL) {
        *head = new_node;
    } else {
        LinkedListNode *last = *head;
        while (last->next != NULL)
            last = last->next;

        last->next = new_node;
        new_node->prev = last;
    }
}

// Initialize the EventLogger
void init_event_logger(EventLogger *logger) {
    pthread_mutex_init(&logger->bst_lock, NULL);
    pthread_mutex_init(&logger->list_lock, NULL);

    initialize_logger(logger);
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    EventLogger logger;
    init_event_logger(&logger);

    // Example usage of BST insertion
    for (size_t i = 0; i < logger.capacity; ++i) {
        pthread_mutex_lock(&logger.bst_lock);
        BSTNode *root = bst_insert(NULL, logger.keys[i], &logger);
        pthread_mutex_unlock(&logger.bst_lock);
    }

    // Example usage of linked list
    LinkedListNode *head = NULL;
    for (size_t i = 0; i < logger.capacity; ++i) {
        append_to_linked_list(&head, logger.records[i]);
    }

    return 0;
}
```

