    void addPreference(std::forward_list<std::string>& preferences, const std::string& pref1, const std::string& pref2) {
        static std::mutex mtx;

        // Acquire a lock to ensure thread-safe operations
        std::lock_guard<std::mutex> lock(mtx);

        size_t max_size = calculateDynamicMaxSize();

        // Check if pref1 is already in the list
        auto it = preferences.begin();
        bool found_pref1 = false;
        for (; it != preferences.end(); ++it) {
            if (*it == pref1) {
                found_pref1 = true;
                break;
            }
        }

        // Add pref1 if not present
        if (!found_pref1 && preferences.size() < max_size) {
            preferences.push_front(pref1);
        }

        // Add pref2 regardless (but will be removed if it exceeds the size)
        preferences.push_front(pref2);

        // If list size exceeds max_size, remove the least recently used element
        while (preferences.size() > max_size) {
            auto next_it = std::next(preferences.begin(), 1);
            preferences.erase_after(preferences.before_begin());
        }
    }

