#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_SIZE 10
#define OFFSET 1000

typedef struct {
    char event_type[10];
    float latency;
} access_log;

typedef struct access_log_node {
    access_log log;
    struct access_log_node* next;
} access_log_node;

typedef struct {
    char buffer[20];
    unsigned long timestamp;
    access_log_node* logs;
} file_entry;

typedef struct {
    file_entry** entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} hash_table;

typedef struct {
    unsigned int id;
    unsigned long cumulative_timestamp;
} file_metadata;

typedef struct {
    file_metadata* metadata_array;
    size_t metadata_size;
    hash_table hash;
} core_components;

void init_access_log_node(access_log_node** node, const char* event_type, float latency) {
    *node = (access_log_node*)malloc(sizeof(access_log_node));
    strncpy((*node)->log.event_type, event_type, sizeof((*node)->log.event_type));
    (*node)->log.latency = latency;
    (*node)->next = NULL;
}

void init_file_entry(file_entry** entry, const char* buffer_id) {
    *entry = (file_entry*)malloc(sizeof(file_entry));
    strncpy((*entry)->buffer, buffer_id, sizeof((*entry)->buffer));
    (*entry)->timestamp = 0;
    (*entry)->logs = NULL;
}

void init_hash_table(hash_table* hash) {
    hash->entries = calloc(INITIAL_SIZE, sizeof(file_entry*));
    hash->size = 0;
    hash->capacity = INITIAL_SIZE;
    pthread_mutex_init(&hash->lock, NULL);
}

unsigned long hash_function(const char* buffer) {
    unsigned long hash = 5381;
    int c;
    while ((c = *buffer++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % INITIAL_SIZE;
}

void resize_hash_table(hash_table* hash) {
    size_t new_capacity = hash->capacity * 2;
    file_entry** new_entries = calloc(new_capacity, sizeof(file_entry*));

    for (size_t i = 0; i < hash->capacity; ++i) {
        if (hash->entries[i]) {
            unsigned long index = hash_function(hash->entries[i]->buffer) % new_capacity;
            new_entries[index] = hash->entries[i];
        }
    }

    free(hash->entries);
    hash->entries = new_entries;
    hash->capacity = new_capacity;
}

void init_core_components(core_components* components, size_t metadata_count) {
    components->metadata_array = (file_metadata*)malloc(metadata_count * sizeof(file_metadata));
    components->metadata_size = 0;

    unsigned long cumulative_timestamp = 0;
    for (size_t i = 0; i < metadata_count; ++i) {
        components->metadata_array[i].id = i + 1;
        cumulative_timestamp += OFFSET;
        components->metadata_array[i].cumulative_timestamp = cumulative_timestamp;
        snprintf(components->metadata_array[i].buffer, sizeof(components->metadata_array[i].buffer), "ID_%zu", i + 1);
    }

    init_hash_table(&components->hash);
}

void free_access_log(access_log_node* node) {
    while (node) {
        access_log_node* temp = node;
        node = node->next;
        free(temp);
    }
}

void free_core_components(core_components* components) {
    for (size_t i = 0; i < components->metadata_size; ++i) {
        // Free any resources related to metadata if necessary
    }

    for (size_t i = 0; i < components->hash.capacity; ++i) {
        if (components->hash.entries[i]) {
            free_access_log(components->hash.entries[i]->logs);
            free(components->hash.entries[i]);
        }
    }

    free(components->metadata_array);
    free(components->hash.entries);
    pthread_mutex_destroy(&components->hash.lock);
}

int main() {
    core_components components;
    init_core_components(&components, 100);

    // Example usage
    file_entry* entry = (file_entry*)malloc(sizeof(file_entry));
    init_file_entry(&entry, "ExampleBuffer");
    pthread_mutex_lock(&components.hash.lock);
    if (components.hash.size >= components.hash.capacity) {
        resize_hash_table(&components.hash);
    }
    unsigned long index = hash_function(entry->buffer) % components.hash.capacity;
    components.hash.entries[index] = entry;
    pthread_mutex_unlock(&components.hash.lock);

    // Clean up
    free_core_components(&components);
    return 0;
}
