    processor->attributes = (char**) malloc(processor->attribute_count * sizeof(char*));
    processor->chunks = (Chunk*) malloc(processor->chunk_count * sizeof(Chunk));

    if (!processor->paths || !processor->attributes || !processor->chunks) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize paths and attributes
