        processor->attributes[i] = (char*) malloc(attribute_length * sizeof(char));
        snprintf(processor->attributes[i], attribute_length, "metadata_%zu", i);
    }

    // Initialize chunks with random values
    for (size_t i = 0; i < processor->chunk_count; ++i) {
        processor->chunks[i].length = rand() % 4096 + 1;
        processor->chunks[i].checksum = rand();
        processor->chunks[i].metadata = processor->attributes[rand() % processor->attribute_count];
        processor->chunks[i].status = 0; // Initialized status
        processor->chunks[i].error_message = NULL;
        processor->chunks[i].metrics = (double)rand() / RAND_MAX * 100.0;

        // Randomly assign an error message to some chunks for demonstration purposes.
        if (rand() % 10 == 0) {
            size_t error_length = rand() % 64 + 1;
            processor->chunks[i].error_message = (char*) malloc(error_length);
            snprintf(processor->chunks[i].error_message, error_length, "Error_%zu", i);
        }
    }
}

void cleanup_collections(FileProcessor* processor) {
    pthread_mutex_destroy(&processor->lock);

    for (size_t i = 0; i < processor->path_count; ++i) {
        free(processor->paths[i]);
    }

    for (size_t i = 0; i < processor->attribute_count; ++i) {
        free(processor->attributes[i]);
    }

    for (size_t i = 0; i < processor->chunk_count; ++i) {
        if (processor->chunks[i].error_message) {
            free(processor->chunks[i].error_message);
        }
    }

    free(processor->paths);
    free(processor->attributes);
    free(processor->chunks);
}

int main() {
    FileProcessor processor;
    initialize_collections(&processor);

    // Simulate some work...

    cleanup_collections(&processor);

    return 0;
}
