    // Allocate memory for keys
    *keys = (int *)malloc(*keys_count * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets); // Free previously allocated memory
        return ALLOCATION_ERROR;
    }

    // Allocate and initialize records array
    *records = (record **)malloc((*offsets_count + *keys_count) * sizeof(record *));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        return ALLOCATION_ERROR;
    }

    // Initialize records with random values
    for (size_t i = 0; i < *offsets_count + *keys_count; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);

            // Free all previously allocated memory
            while (--i >= 0) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            return ALLOCATION_ERROR;
        }
        (*records)[i]->value = rand() % 100; // Random value between 0 and 99
    }

    return SUCCESS;
}

// Example of function usage:
void example_usage() {
    size_t offsets_count, keys_count;
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;

    int result = allocate_arrays(&offsets_count, &keys_count, &offsets, &keys, &records);

    if (result == SUCCESS) {
        printf("Arrays allocated successfully.\n");

        // Use the arrays as needed...

        // Free allocated memory
        for (size_t i = 0; i < offsets_count + keys_count; ++i)
            free(records[i]);
        free(records);
        free(offsets);
        free(keys);
    } else if (result == INVALID_INPUT) {
        printf("Invalid input provided.\n");
    } else {
        printf("Memory allocation error occurred.\n");
    }
}

int main() {
    example_usage();
    return 0;
}
```

### Design Considerations

1. **Input Validation**: The function checks for valid user inputs, ensuring they are within specified bounds to prevent excessive memory allocation requests.

2. **Memory Allocation and Error Handling**: Each memory allocation is checked immediately after the call. In case of a failure at any step, all previously allocated resources are deallocated before returning an error code.

3. **Random Initialization**: The records array is initialized with random integers using `rand()` seeded by `srand(time(NULL))`, ensuring consistent results across calls unless explicitly reset.

4. **Thread Safety**: The function does not use global variables and relies on local storage, making it suitable for multithreaded applications when used appropriately with thread-safe practices in broader code.

5. **Scalability**: By defining a `MAX_SIZE` constant, the function is designed to avoid overwhelming system resources with large allocations, balancing efficiency with resource constraints.

6. **Resource Management**: In case of failure after partial allocation, all allocated resources are freed correctly to prevent memory leaks.

This design ensures that the function can handle both small and very large array sizes efficiently while maintaining usability and maintainability in a production environment.']

