#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define LOG_FILE "memory_management.log"
#define MAX_MEMORY_THRESHOLD_MB 100

typedef struct {
    int value;
} record;

enum ErrorCode {
    SUCCESS,
    INVALID_INPUT,
    ALLOCATION_FAILURE,
    MEMORY_THRESHOLD_EXCEEDED
};

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        time_t now = time(NULL);
        fprintf(log, "[%s] %s\n", ctime(&now), message);
        fclose(log);
    }
}

int allocate_memory(long **offsets, int **keys, record **records, size_t num_elements, int min_value, int max_value, size_t memory_threshold_mb) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    log_message("Starting memory allocation.");

    if (num_elements <= 0 || min_value > max_value) {
        log_message("Invalid input parameters.");
        pthread_mutex_unlock(&lock);
        return INVALID_INPUT;
    }

    size_t total_memory_bytes = sizeof(long) * num_elements + sizeof(int) * num_elements + sizeof(record) * num_elements;

    if (total_memory_bytes > memory_threshold_mb * 1024 * 1024) {
        log_message("Memory threshold exceeded.");
        pthread_mutex_unlock(&lock);
        return MEMORY_THRESHOLD_EXCEEDED;
    }

    // Allocate memory for offsets, keys, and records
    *offsets = malloc(sizeof(long) * num_elements);
    if (*offsets == NULL) {
        log_message("Failed to allocate memory for offsets.");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_FAILURE;
    }

    *keys = malloc(sizeof(int) * num_elements);
    if (*keys == NULL) {
        free(*offsets);
        log_message("Failed to allocate memory for keys.");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_FAILURE;
    }

    *records = malloc(sizeof(record) * num_elements);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        log_message("Failed to allocate memory for records.");
        pthread_mutex_unlock(&lock);
        return ALLOCATION_FAILURE;
    }

    // Initialize random seed and fill records with random values
    srand(42);  // Consistent seed for reproducibility
    for (size_t i = 0; i < num_elements; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    log_message("Memory allocation successful.");
    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

void free_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

// Unit tests
