    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    printf("Test 1: Valid input\n");
    if (allocate_memory(&offsets, &keys, &records, 10, 0, 100, MAX_MEMORY_THRESHOLD_MB) == SUCCESS) {
        printf("Passed\n");
    } else {
        printf("Failed\n");
    }

    printf("Test 2: Invalid input size\n");
    if (allocate_memory(&offsets, &keys, &records, -1, 0, 100, MAX_MEMORY_THRESHOLD_MB) != INVALID_INPUT) {
        printf("Failed\n");
    } else {
        printf("Passed\n");
    }

    printf("Test 3: Memory threshold exceeded\n");
    size_t large_size = (MAX_MEMORY_THRESHOLD_MB + 10) * 1024 * 1024 / (sizeof(long) + sizeof(int) + sizeof(record));
    if (allocate_memory(&offsets, &keys, &records, large_size, 0, 100, MAX_MEMORY_THRESHOLD_MB) != MEMORY_THRESHOLD_EXCEEDED) {
        printf("Failed\n");
    } else {
        printf("Passed\n");
    }

    free_memory(offsets, keys, records);
}

int main() {
    test_allocate_memory();
    return 0;
}
