```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdatomic.h>

#define KEY_RANGE 1000
#define OFFSET_CONSTANT 10
#define CACHE_SIZE 50

typedef struct Record {
    short sh;
    int i;
    float f;
    struct Record* next;
} Record;

typedef struct CacheEntry {
    Record* record;
    atomic_uint access_count;
} CacheEntry;

typedef struct {
    long* offsets;
    int size_offsets;
    int capacity_offsets;

    int* keys;
    int size_keys;
    int capacity_keys;

    Record* head;
    pthread_mutex_t list_lock;

    CacheEntry* cache;
    int cache_size;
    atomic_uint usage_counter;
} DataStructure;

DataStructure* init_data_structure(int initial_capacity) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = aligned_alloc(64, sizeof(long) * initial_capacity);
    ds->keys = aligned_alloc(64, sizeof(int) * initial_capacity);

    ds->size_offsets = 0;
    ds->capacity_offsets = initial_capacity;

    ds->size_keys = 0;
    ds->capacity_keys = initial_capacity;

    ds->head = NULL;
    pthread_mutex_init(&ds->list_lock, NULL);

    ds->cache = malloc(sizeof(CacheEntry) * CACHE_SIZE);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        ds->cache[i].record = NULL;
        atomic_store(&ds->cache[i].access_count, 0);
    }

    ds->cache_size = CACHE_SIZE;
    atomic_init(&ds->usage_counter, 0);

    return ds;
}

void free_data_structure(DataStructure* ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);

    pthread_mutex_lock(&ds->list_lock);
    Record* current = ds->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&ds->list_lock);
    pthread_mutex_destroy(&ds->list_lock);

    free(ds->cache);
    free(ds);
}

void resize_arrays(DataStructure* ds, int new_capacity) {
    long* new_offsets = aligned_alloc(64, sizeof(long) * new_capacity);
    int* new_keys = aligned_alloc(64, sizeof(int) * new_capacity);

    for (int i = 0; i < ds->size_offsets; ++i) {
        new_offsets[i] = ds->offsets[i];
    }

    for (int i = 0; i < ds->size_keys; ++i) {
        new_keys[i] = ds->keys[i];
    }

    free(ds->offsets);
    free(ds->keys);

    ds->offsets = new_offsets;
    ds->capacity_offsets = new_capacity;

    ds->keys = new_keys;
    ds->capacity_keys = new_capacity;
}

void populate_data_structure(DataStructure* ds, int num_elements) {
    pthread_mutex_lock(&ds->list_lock);

    if (num_elements > ds->capacity_keys - ds->size_keys) {
        resize_arrays(ds, ds->capacity_keys * 2);
    }

    long cumulative_sum = 0;
    for (int i = ds->size_keys; i < num_elements + ds->size_keys; ++i) {
        ds->keys[i] = rand() % KEY_RANGE;
        cumulative_sum += ds->keys[i];
        ds->offsets[i] = cumulative_sum + OFFSET_CONSTANT;

        Record* new_record = malloc(sizeof(Record));
        if (!new_record) break;

        new_record->sh = (short)(rand() % 32768);
        new_record->i = rand() % 1000000;
        new_record->f = (float)(rand()) / RAND_MAX;
        new_record->next = ds->head;
        ds->head = new_record;

        atomic_fetch_add(&ds->usage_counter, 1);

        // Logging logic can be placed here
    }

    ds->size_keys = num_elements + ds->size_keys;
    ds->size_offsets = num_elements + ds->size_offsets;

    pthread_mutex_unlock(&ds->list_lock);
}

void access_record(DataStructure* ds) {
    pthread_mutex_lock(&ds->list_lock);

    Record* current = ds->head;
    while (current) {
        // Access or modify record
        atomic_fetch_add(&ds->usage_counter, 1);
        current = current->next;
    }

    pthread_mutex_unlock(&ds->list_lock);
}

void cache_management(DataStructure* ds) {
    for (int i = 0; i < ds->cache_size; ++i) {
        if (atomic_load(&ds->cache[i].access_count) == 0) {
            // Evict from cache
            free(ds->cache[i].record);
            ds->cache[i].record = NULL;
        }
    }
}

void periodic_save(DataStructure* ds) {
    pthread_mutex_lock(&ds->list_lock);

    FILE* file = fopen("data_structure_backup.dat", "wb");
    if (file) {
        fwrite(ds->offsets, sizeof(long), ds->size_offsets, file);
        fwrite(ds->keys, sizeof(int), ds->size_keys, file);

        Record* current = ds->head;
        while (current) {
            fwrite(current, sizeof(Record), 1, file);
            current = current->next;
        }

        fclose(file);
    }

    pthread_mutex_unlock(&ds->list_lock);
}

int main() {
    DataStructure* ds = init_data_structure(10);

    populate_data_structure(ds, 20);

    access_record(ds);

    cache_management(ds);

    periodic_save(ds);

    free_data_structure(ds);

    return 0;
}
```

### Key Points:
- **Memory Allocation**: Uses `aligned_alloc` for optimal performance.
- **Thread Safety**: Utilizes mutexes and atomic operations to ensure safe concurrent access.
- **Dynamic Resizing**: Provides a mechanism to resize arrays when needed.
- **Linked List Management**: Ensures thread-safe access and modification.
- **Caching Strategy**: Implements basic caching with eviction based on usage.
- **Periodic Saving**: Saves data structures periodically to disk for recovery.

This implementation is designed to be efficient, maintainable, and adaptable to real-world constraints.']

