    pthread_rwlock_wrlock(&hash_map_locks[index]);

    HashMapNode **node = &hash_map[index];
    while (*node) node = &(*node)->next;

    *node = (HashMapNode *)malloc(sizeof(HashMapNode));
    if (!*node) {
        pthread_rwlock_unlock(&hash_map_locks[index]);
        return -1;
    }

    (*node)->key = key;
    (*node)->file_chunk = file_chunk;
    (*node)->next = NULL;

    pthread_rwlock_unlock(&hash_map_locks[index]);

    log_change("Added to hash map.");
    return 0;
}

// Retrieve a file chunk from the hash map
FileChunk* get_from_hash_map(int key) {
    unsigned int index = hash(key);
    pthread_rwlock_rdlock(&hash_map_locks[index]);

    HashMapNode *node = hash_map[index];
    while (node && node->key != key) node = node->next;

    FileChunk *file_chunk = NULL;
    if (node) file_chunk = node->file_chunk;

    pthread_rwlock_unlock(&hash_map_locks[index]);
    return file_chunk;
}

// Add a file chunk to the linked list
void add_to_linked_list(FileChunk *new_chunk) {
    pthread_mutex_lock(&record_list_lock);

    new_chunk->next = record_list;
    record_list = new_chunk;

    pthread_mutex_unlock(&record_list_lock);
}

