#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>
#include <stdio.h>

#define CACHE_SIZE 1024 // Example size, adjust as needed
#define METADATA_ENTRY_SIZE sizeof(MetadataEntry)
#define ALIGNMENT 64

typedef struct MetadataEntry {
    uint32_t fileId;
    off_t fileSize;
    time_t modTime;
    char accessPermissions[16];
    atomic_int accessCount;
} __attribute__((aligned(ALIGNMENT))) MetadataEntry;

typedef struct CacheNode {
    MetadataEntry entry;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct MemoryPool {
    void *pool;
    size_t poolSize;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    CacheNode *head, *tail;
    atomic_size_t nodeCount;
    MemoryPool memPool;
    pthread_rwlock_t cacheLock;
} MetadataCache;

// Function prototypes
MetadataCache* initialize_cache();
void free_cache(MetadataCache *cache);
int update_entry(MetadataCache *cache, uint32_t fileId, off_t fileSize, time_t modTime, const char *permissions);
void evict_least_frequently_used(MetadataCache *cache);
void synchronize_with_external_source(MetadataCache *cache);

MetadataCache* initialize_cache() {
    MetadataCache *cache = (MetadataCache*)malloc(sizeof(MetadataCache));
    pthread_rwlock_init(&cache->cacheLock, NULL);

    cache->head = cache->tail = NULL;
    atomic_store(&cache->nodeCount, 0);

    // Initialize memory pool
    size_t blockSize = CACHE_SIZE * METADATA_ENTRY_SIZE;
    cache->memPool.poolSize = blockSize;
    cache->memPool.pool = malloc(blockSize);
    pthread_mutex_init(&cache->memPool.lock, NULL);

    return cache;
}

void free_cache(MetadataCache *cache) {
    pthread_rwlock_wrlock(&cache->cacheLock);
    CacheNode *node = cache->head;

    while (node) {
        CacheNode *next = node->next;
        free(node);  // Deallocate nodes individually
        node = next;
    }

    pthread_rwlock_unlock(&cache->cacheLock);

    pthread_mutex_destroy(&cache->memPool.lock);
    free(cache->memPool.pool);
    pthread_rwlock_destroy(&cache->cacheLock);
    free(cache);
}

int update_entry(MetadataCache *cache, uint32_t fileId, off_t fileSize, time_t modTime, const char *permissions) {
    pthread_rwlock_wrlock(&cache->cacheLock);

    CacheNode *node = cache->head;

    while (node) {
        if (node->entry.fileId == fileId) {
            node->entry.fileSize = fileSize;
            node->entry.modTime = modTime;
            strncpy(node->entry.accessPermissions, permissions, sizeof(node->entry.accessPermissions));
            atomic_fetch_add(&node->entry.accessCount, 1);

            pthread_rwlock_unlock(&cache->cacheLock);
            return 0; // Updated existing entry
        }
        node = node->next;
    }

    pthread_mutex_lock(&cache->memPool.lock);

    void *chunk = malloc(METADATA_ENTRY_SIZE); // Allocate aligned memory
    if (!chunk) {
        pthread_rwlock_unlock(&cache->cacheLock);
        pthread_mutex_unlock(&cache->memPool.lock);
        return -1; // Memory allocation failed
    }

    CacheNode *newNode = (CacheNode*)chunk;
    memset(&newNode->entry, 0, METADATA_ENTRY_SIZE);

    newNode->entry.fileId = fileId;
    newNode->entry.fileSize = fileSize;
    newNode->entry.modTime = modTime;
    strncpy(newNode->entry.accessPermissions, permissions, sizeof(newNode->entry.accessPermissions));
    atomic_init(&newNode->entry.accessCount, 1);

    newNode->prev = cache->tail;
    if (cache->tail) {
        cache->tail->next = newNode;
    } else {
        cache->head = newNode;
    }
    cache->tail = newNode;

    pthread_mutex_unlock(&cache->memPool.lock);

    pthread_rwlock_unlock(&cache->cacheLock);
    return 1; // Added new entry
}

void evict_least_frequently_used(MetadataCache *cache) {
    pthread_rwlock_wrlock(&cache->cacheLock);

    CacheNode *node = cache->head;
    CacheNode *lfu_node = NULL;
    int min_access_count = INT_MAX;

    while (node) {
        int access_count = atomic_load(&node->entry.accessCount);

        if (access_count < min_access_count) {
            lfu_node = node;
            min_access_count = access_count;
        }
        node = node->next;
    }

    if (lfu_node) {
        if (lfu_node == cache->head) {
            cache->head = lfu_node->next;
        } else {
            lfu_node->prev->next = lfu_node->next;
        }

        if (lfu_node == cache->tail) {
            cache->tail = lfu_node->prev;
        } else {
            lfu_node->next->prev = lfu_node->prev;
        }

        free(lfu_node);
    }

    pthread_rwlock_unlock(&cache->cacheLock);
}

void synchronize_with_external_source(MetadataCache *cache) {
    // Implementation of external synchronization, possibly using a background thread
    // Here we'll simply print an action for illustrative purposes

    printf("Synchronizing with external source...\n");

    // Acquire lock to update cache safely
    pthread_rwlock_wrlock(&cache->cacheLock);

    // Simulate fetching data from external source and updating the cache
    // In practice, use thread-safe mechanisms to handle network communication

    pthread_rwlock_unlock(&cache->cacheLock);
}

int main() {
    MetadataCache *cache = initialize_cache();

    if (!cache) return 1;

    update_entry(cache, 1, 1024, time(NULL), "rw-r--r--");
    evict_least_frequently_used(cache);

    synchronize_with_external_source(cache);

    free_cache(cache);
    return 0;
}
```

