#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define TOKEN_LENGTH 32
#define HASH_TABLE_SIZE 1024

typedef struct {
    char token[TOKEN_LENGTH];
    time_t expiration_time;
    void* metadata; // User-specific data, could be a pointer to another structure
} Session;

typedef struct {
    Session** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

unsigned int hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

char* generate_token(SessionManager* manager, const char* charset, size_t length) {
    static const char chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* token = malloc(length + 1);
    if (!token) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < length; ++i) {
        int index = rand() % strlen(charset);
        token[i] = charset[index];
    }
    token[length] = '\0';

    // Check for collisions
    unsigned int hash_value = hash(token);
    while (manager->sessions[hash_value]) {
        free(token);
        for (size_t i = 0; i < length; ++i) {
            int index = rand() % strlen(charset);
            token[i] = charset[index];
        }
        token[length] = '\0';
        hash_value = hash(token);
    }

    return token;
}

void initialize_session_manager(SessionManager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->sessions = malloc(initial_capacity * sizeof(Session*));
    if (!manager->sessions) exit(EXIT_FAILURE);

    manager->capacity = initial_capacity;
    manager->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->sessions[i] = NULL;
    }
}

void resize_session_manager(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    size_t new_capacity = manager->capacity * 2;
    Session** new_sessions = malloc(new_capacity * sizeof(Session*));
    if (!new_sessions) exit(EXIT_FAILURE);

    for (size_t i = 0; i < new_capacity; ++i) {
        new_sessions[i] = NULL;
    }

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->sessions[i]) {
            unsigned int hash_value = hash(manager->sessions[i]->token);
            while (new_sessions[hash_value]) {
                hash_value = (hash_value + 1) % new_capacity;
            }
            new_sessions[hash_value] = manager->sessions[i];
        }
    }

    free(manager->sessions);
    manager->sessions = new_sessions;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->lock);
}

void add_session(SessionManager* manager, void* metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity * 0.75) {
        resize_session_manager(manager);
    }

    char* token = generate_token(manager, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", TOKEN_LENGTH - 1);
    if (!token) {
        printf("Failed to generate a unique session token.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Session* new_session = malloc(sizeof(Session));
    if (!new_session) exit(EXIT_FAILURE);

    strncpy(new_session->token, token, TOKEN_LENGTH - 1);
    free(token);

    // Set expiration time with random offset
    double average_lifespan = 3600.0; // e.g., one hour
    double random_offset = (rand() / (double)RAND_MAX) * average_lifespan;
    new_session->expiration_time = time(NULL) + average_lifespan + random_offset;

    new_session->metadata = metadata;

    unsigned int hash_value = hash(new_session->token);
    while (manager->sessions[hash_value]) {
        hash_value = (hash_value + 1) % manager->capacity;
    }

    manager->sessions[hash_value] = new_session;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

void iterate_sessions(SessionManager* manager, void (*callback)(Session*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->sessions[i]) {
            callback(manager->sessions[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_sessions(SessionManager* manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->expiration_time <= now) {
            free(manager->sessions[i]);
            manager->sessions[i] = NULL;
            manager->count--;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_session_manager(SessionManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->sessions[i]) {
            free(manager->sessions[i]);
        }
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    SessionManager manager;
    initialize_session_manager(&manager, INITIAL_CAPACITY);

    // Example usage
    add_session(&manager, NULL);
    iterate_sessions(&manager, [](Session* session) {
        printf("Session token: %s\n", session->token);
    });
    cleanup_sessions(&manager);
    destroy_session_manager(&manager);

    return 0;
}
```

