#define MAX_METADATA_LENGTH 255
#define METADATA_CHARSET "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
#define SLIDING_WINDOW_SIZE 10

// Define event types, status indicators, priority levels, and other enums as necessary
typedef enum { EVENT_TYPE_1, EVENT_TYPE_2 } EventType;
typedef enum { STATUS_ACTIVE, STATUS_INACTIVE } StatusIndicator;
typedef int PriorityLevel;

// Record structure
typedef struct Record {
    short sField;
    int iField;
    float fField;
    int timestamp;
    char *metadata;
    EventType event;
    StatusIndicator status;
    PriorityLevel priority;
    double weight;
    struct { double x, y; } location;
    int duration;

    // Pointers for doubly linked list
    struct Record* prev;
    struct Record* next;
} Record;

// Node structure for linked list
typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

// Function prototypes
void initialize_record_list(RecordList *list);
void add_record(RecordList *list, Record record);
void remove_record(RecordList *list, Record *record);
void iterate_records(const RecordList *list);

// Initialize list with mutex
void initialize_record_list(RecordList *list) {
    list->records = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add record to the list in a thread-safe manner
void add_record(RecordList *list, Record record) {
    pthread_mutex_lock(&list->lock);

    // Create new node and allocate memory
    Record *new_node = (Record*)malloc(sizeof(Record));
    memcpy(new_node, &record, sizeof(Record));

    // Insert at the end of the list
    if (list->records == NULL) {
        list->records = new_node;
        new_node->prev = new_node->next = NULL;
    } else {
        Record *last = list->records;
        while (last->next != NULL) last = last->next;

        last->next = new_node;
        new_node->prev = last;
        new_node->next = NULL;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Remove record from the list
void remove_record(RecordList *list, Record *record) {
    pthread_mutex_lock(&list->lock);

    if (list->records == NULL || record == NULL) return;

    // Find the node to remove
    Record *current = list->records;
    while (current != NULL && current != record) current = current->next;

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;  // Not found
    }

    // Adjust pointers
    if (current->prev != NULL) current->prev->next = current->next;
    if (current->next != NULL) current->next->prev = current->prev;

    if (current == list->records) list->records = current->next;  // Update head if necessary

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

// Iterate over the records
void iterate_records(const RecordList *list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Record *current = list->records;
    while (current != NULL) {
        // Process each record as needed
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Function to generate random metadata strings
char* generate_random_metadata(size_t length) {
    char *metadata = malloc(length + 1);
    if (!metadata) return NULL;

    for (size_t i = 0; i < length; ++i) {
        const char charset[] = METADATA_CHARSET;
        size_t max_index = sizeof(charset) - 2;
        metadata[i] = charset[rand() % max_index + 1];
    }
    metadata[length] = '\0';

    return metadata;
}

// Main function demonstrating initialization and usage
int main() {
    srand(time(NULL));  // Seed random number generator

    RecordList list;
    initialize_record_list(&list);

    for (size_t i = 0; i < SLIDING_WINDOW_SIZE; ++i) {
        Record record;
        record.sField = rand() % SHORT_MAX;
        record.iField = rand() % INT_MAX;
        record.fField = (float)(rand() / (float)RAND_MAX * FLOAT_MAX);
        record.timestamp = rand() % TIMESTAMP_MAX;
        record.metadata = generate_random_metadata(MAX_METADATA_LENGTH);
        record.event = i % 2 == 0 ? EVENT_TYPE_1 : EVENT_TYPE_2;
        record.status = i % 2 == 0 ? STATUS_ACTIVE : STATUS_INACTIVE;
        record.priority = (PriorityLevel)(rand() % INT_MAX);
        record.weight = rand() / (float)RAND_MAX;
        record.location.x = (double)rand() / RAND_MAX * 100.0;
        record.location.y = (double)rand() / RAND_MAX * 100.0;
        record.duration = rand() % INT_MAX;

        add_record(&list, record);
    }

    iterate_records(&list);

    // Cleanup: Iterate and free records
    Record *current = list.records;
    while (current != NULL) {
        Record *next = current->next;
        free(current->metadata);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list.lock);

    return 0;
}
