void* memory_pool[POOL_SIZE];
size_t pool_index = 0;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;

// External data store simulation (stub functions)
void external_data_store_put(char key, double value);
double external_data_store_get(char key);

// Function to initialize the memory pool
void init_memory_pool() {
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(Node));
    }
}

// Custom allocator using memory pool
Node* allocate_node() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    Node* node = (Node*)memory_pool[pool_index++];
    pthread_mutex_unlock(&pool_mutex);
    memset(node, 0, sizeof(Node));
    return node;
}

// Function to free the memory pool
void free_memory_pool() {
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        if (memory_pool[i] != NULL) {
            free(memory_pool[i]);
            memory_pool[i] = NULL;
        }
    }
}

// Insert a node into the linked list
void insert_node(char key, double value) {
    pthread_rwlock_wrlock(&list_lock);

    Node* new_node = allocate_node();
    if (new_node == NULL) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    new_node->key = key;
    new_node->value = value;

    // Insert at the beginning for simplicity
    Node* head;
    extern Node* get_head();  // Function to get list head
    head = get_head();

    if (head == NULL) {
        // Assume set_head sets a global pointer
        extern void set_head(Node* node);
        new_node->next = NULL;
        set_head(new_node);
    } else {
        new_node->next = head;
        set_head(new_node);
    }

    external_data_store_put(key, value);

    pthread_rwlock_unlock(&list_lock);
}

// Delete a node from the linked list
void delete_node(char key) {
    pthread_rwlock_wrlock(&list_lock);

    Node* current = get_head();
    Node* prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_rwlock_unlock(&list_lock);
        return;  // Key not found
    }

    if (prev == NULL) {
        // Removing the head node
        Node* new_head = current->next;
        set_head(new_head);
    } else {
        prev->next = current->next;
    }

    external_data_store_put(current->key, -1);  // Simulate deletion

    pthread_mutex_lock(&pool_mutex);
    free(memory_pool[--pool_index]);  // Return to pool
    pthread_mutex_unlock(&pool_mutex);

    pthread_rwlock_unlock(&list_lock);
}

// Lookup a node in the linked list
double lookup_node(char key) {
    double value;
    pthread_rwlock_rdlock(&list_lock);

    Node* current = get_head();
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        // Key not found, check external store
        value = external_data_store_get(key);
    } else {
        value = current->value;
    }

    pthread_rwlock_unlock(&list_lock);

    return value;
}

// Synchronize with external data store in background
void* sync_with_external_store(void* arg) {
    while (1) {
        sleep(10);  // Simulate periodic update

        pthread_rwlock_rdlock(&list_lock);

        Node* current = get_head();
        while (current != NULL) {
            external_data_store_put(current->key, current->value);
            current = current->next;
        }

        pthread_rwlock_unlock(&list_lock);
    }
    return NULL;
}

int main() {
    init_memory_pool();

    // Start background synchronization
    pthread_t sync_thread;
    pthread_create(&sync_thread, NULL, sync_with_external_store, NULL);

    // Example usage:
    insert_node('A', 3.14);
    printf("Value for 'A': %f\n", lookup_node('A'));
    delete_node('A');

    free_memory_pool();
    pthread_join(sync_thread, NULL);

    return 0;
}
```

