    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_record(LinkedList* list, Record* record) {
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_record(LinkedList* list, Record* record) {
    pthread_mutex_lock(&list->lock);
    if (record->prev) record->prev->next = record->next;
    if (record->next) record->next->prev = record->prev;
    if (record == list->head) list->head = record->next;
    if (record == list->tail) list->tail = record->prev;
    pthread_mutex_unlock(&list->lock);
}

void batch_delete_inactive(LinkedList* list, time_t threshold) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current) {
        if (current->timestamp < threshold) {
            Record* to_delete = current;
            current = current->next;
            delete_record(list, to_delete);
            free_record(to_delete, NULL); // Assuming pool is accessible
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

