    size_t capacity;
    size_t count;
    FILE* logFile; // For logging operations.
} TrafficManager;

TrafficManager* createTrafficManager(size_t initialCapacity) {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)malloc(initialCapacity * sizeof(TrafficFlow));
    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->logFile = fopen("traffic_log.txt", "a"); // Open a log file for appending.
    if (!manager->logFile) {
        perror("Failed to open log file");
        free(manager);
        return NULL;
    }
    return manager;
}

void deleteTrafficManager(TrafficManager* manager) {
    if (manager) {
        fclose(manager->logFile); // Close the log file
        free(manager->flows);
        free(manager);
    }
}

void logOperation(const TrafficManager* manager, const char* operation) {
    fprintf(manager->logFile, "%s: %zu flows\n", operation, manager->count);
    fflush(manager->logFile); // Ensure data is written to disk immediately.
}

int addFlow(TrafficManager* manager, const char* sourceIP, const char* destIP, int protocolType) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        TrafficFlow* newFlows = (TrafficFlow*)realloc(manager->flows, newCapacity * sizeof(TrafficFlow));
        if (!newFlows) return -1; // Allocation failed
        manager->flows = newFlows;
        manager->capacity = newCapacity;
    }

    TrafficFlow flow;
    snprintf(flow.SourceIP, 16, "%s", sourceIP);
    snprintf(flow.DestinationIP, 16, "%s", destIP);
    flow.ProtocolType = protocolType;
    time(&flow.lastUpdateTimestamp);

    manager->flows[manager->count++] = flow;
    logOperation(manager, "Add Flow");
    return 0; // Success
}

int removeFlow(TrafficManager* manager, const char* sourceIP, const char* destIP) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].SourceIP, sourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, destIP) == 0) {

            // Shift elements to the left
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->flows[j] = manager->flows[j + 1];
            }
            --manager->count;
            logOperation(manager, "Remove Flow");
            return 0; // Success
        }
    }
    return -1; // Not found
}

size_t queryFlowsByProtocol(const TrafficManager* manager, int protocolType) {
    size_t count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->flows[i].ProtocolType == protocolType) {
            ++count;
        }
    }
    return count;
}

void batchDeleteInactiveFlows(TrafficManager* manager, time_t currentTime) {
    size_t activeIndex = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(currentTime, manager->flows[i].lastUpdateTimestamp) <= 15 * 60) {
            manager->flows[activeIndex++] = manager->flows[i];
        } else {
            // Log deletion
            logOperation(manager, "Batch Delete Inactive Flow");
        }
    }

    manager->count = activeIndex;
}

