['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    char executor[32];
    int priority;
    char status[16];
    char metadata[64];
    int dependencies_count;
    int* dependencies; // Array of task IDs
} Task;

typedef struct {
    Task* tasks;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int version;
} TaskSystem;

void init_task_system(TaskSystem* system, size_t initial_capacity) {
    system->tasks = (Task*)malloc(initial_capacity * sizeof(Task));
    if (!system->tasks) {
        perror("Failed to allocate memory for tasks");
        exit(EXIT_FAILURE);
    }
    system->capacity = initial_capacity;
    system->used = 0;
    pthread_mutex_init(&system->lock, NULL);
    pthread_cond_init(&system->cond_var, NULL);
    system->version = 0;

    pthread_mutex_lock(&system->lock);
}

void resize_task_system(TaskSystem* system) {
    size_t new_capacity = system->capacity * 2;
    Task* new_tasks = (Task*)realloc(system->tasks, new_capacity * sizeof(Task));
    if (!new_tasks) {
        perror("Failed to reallocate memory for tasks");
        exit(EXIT_FAILURE);
    }
    system->tasks = new_tasks;
    system->capacity = new_capacity;
    pthread_mutex_unlock(&system->lock);
}

void add_task(TaskSystem* system, Task task) {
    pthread_mutex_lock(&system->lock);

    if (system->used >= system->capacity) {
        resize_task_system(system);
    }

    system->tasks[system->used++] = task;
    system->version++;

    pthread_cond_signal(&system->cond_var);
    pthread_mutex_unlock(&system->lock);
}

void garbage_collect(TaskSystem* system) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->used;) {
        if (strcmp(system->tasks[i].status, "completed") == 0) {
            memmove(&system->tasks[i], &system->tasks[i + 1],
                    (system->used - i - 1) * sizeof(Task));
            system->used--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&system->lock);
}

void cleanup_task_system(TaskSystem* system) {
    free(system->tasks);
    pthread_mutex_destroy(&system->lock);
    pthread_cond_destroy(&system->cond_var);
}

void randomize_task(Task* task, int executor_range, int priority_range,
                    int dependency_range, TaskSystem* existing_tasks) {
    time_t now;
    time(&now);

    // Random timestamp
    task->timestamp = now - (rand() % 86400); // Last 24 hours

    // Valid executor ID
    snprintf(task->executor, sizeof(task->executor), "user_%d", rand() % executor_range);

    // Unique priority level
    task->priority = rand() % priority_range;

    // Status is initially pending
    strcpy(task->status, "pending");

    // Random metadata
    snprintf(task->metadata, sizeof(task->metadata), "meta_%d", rand());

    // Random number of dependencies (0 to dependency_range)
    task->dependencies_count = rand() % dependency_range;
    task->dependencies = (int*)malloc(task->dependencies_count * sizeof(int));

    for (size_t i = 0; i < task->dependencies_count; ++i) {
        task->dependencies[i] = rand() % existing_tasks->used;
    }
}

void iterate_and_process(TaskSystem* system, void (*process)(Task*)) {
    pthread_mutex_lock(&system->lock);

    for (size_t i = 0; i < system->used; ++i) {
        process(&system->tasks[i]);
    }

    pthread_mutex_unlock(&system->lock);
}

// Example usage
void example_process(Task* task) {
    printf("Processing Task ID %d with priority %d\n", task->id, task->priority);
}

int main() {
    srand(time(NULL));
    TaskSystem system;
    init_task_system(&system, INITIAL_POOL_SIZE);

    for (int i = 0; i < 1000; ++i) {
        Task new_task = {.id = i};
        randomize_task(&new_task, 100, 50, 10, &system);
        add_task(&system, new_task);
    }

    iterate_and_process(&system, example_process);

    cleanup_task_system(&system);
    return 0;
}
```']

