#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct item {
    double d;
    int i;
    struct item* next_item;
    long id;
    unsigned short length_of_key;
} Item;

typedef struct record {
    double num;
    char* str;
    Item* item;
    long l;
    unsigned short us;
} Record;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Record* create_record_array(size_t initial_size);
void destroy_record_array(Record* array, size_t size);
void resize_record_array(Record** array, size_t current_size, size_t new_size);
void initialize_records(Record* array, size_t size, const char* key, int int_min, int int_max);
void log_operation(const char* message);

// Function to create and initialize the record array
Record* create_record_array(size_t initial_size) {
    Record* array = (Record*)malloc(initial_size * sizeof(Record));
    if (!array) {
        log_operation("Failed to allocate memory for records");
        return NULL;
    }
    initialize_records(array, initial_size, "example_key", 1, 100);
    return array;
}

// Function to destroy the record array
void destroy_record_array(Record* array, size_t size) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; ++i) {
        free(array[i].str);
        free(array[i].item);
    }
    free(array);
    pthread_mutex_unlock(&mutex);
}

// Function to resize the record array
void resize_record_array(Record** array, size_t current_size, size_t new_size) {
    pthread_mutex_lock(&mutex);
    Record* temp = (Record*)realloc(*array, new_size * sizeof(Record));
    if (!temp) {
        log_operation("Failed to reallocate memory for records");
        return;
    }
    initialize_records(temp + current_size, new_size - current_size, "example_key", 1, 100);
    *array = temp;
    pthread_mutex_unlock(&mutex);
}

// Function to initialize records with random data
void initialize_records(Record* array, size_t size, const char* key, int int_min, int int_max) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        array[i].num = ((double)rand() / RAND_MAX);
        array[i].str = strdup(key); // Simplified string allocation
        array[i].item = (Item*)malloc(sizeof(Item));
        if (!array[i].item) {
            log_operation("Failed to allocate memory for item");
            continue;
        }
        array[i].item->d = ((double)rand() / RAND_MAX);
        array[i].item->i = rand() % (int_max - int_min + 1) + int_min;
        array[i].item->next_item = NULL;
        array[i].item->id = rand();
        array[i].item->length_of_key = strlen(key);
        array[i].l = rand(); // Unique IDs should be managed more carefully in practice
        array[i].us = (unsigned short)strlen(key);
    }
}

// Function to log operations with timestamps
void log_operation(const char* message) {
    time_t now;
    time(&now);
    printf("[%s] %s\n", ctime(&now), message);
}

// Example unit test function
void test_record_array() {
    size_t initial_size = 10;
    Record* array = create_record_array(initial_size);
    if (!array) return;

    // Test resizing
    resize_record_array(&array, initial_size, 20);

    destroy_record_array(array, 20);
}

int main() {
    test_record_array();
    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex is used to ensure thread-safe operations.
- **Dynamic Resizing**: The `resize_record_array` function handles resizing of the array.
- **Logging**: Logs are printed with timestamps for monitoring and debugging.
- **Unit Test**: A simple test case checks creation, resizing, and destruction.

### Considerations:
- **Unique IDs**: In practice, ensure unique identifiers are managed correctly across threads.
- **Concurrency**: Further enhancements may be needed for high concurrency scenarios.
- **Memory Management**: Ensure all allocations are freed appropriately to prevent leaks.']

['Here is a C implementation that manages a dynamically allocated array of `TrafficFlow` structures, addressing the constraints and requirements mentioned:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FLOWS 1024
#define INACTIVE_THRESHOLD 600 // 10 minutes in seconds

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int ProtocolType;
    time_t LastUpdateTimestamp;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t count;
    pthread_mutex_t lock;
} FlowManager;

FlowManager* initialize_flow_manager() {
    FlowManager *manager = malloc(sizeof(FlowManager));
    manager->flows = calloc(MAX_FLOWS, sizeof(TrafficFlow));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void log_event(const char *event) {
    // Placeholder for logging mechanism
    printf("Log: %s\n", event);
}

int add_traffic_flow(FlowManager *manager, const TrafficFlow *flow) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_FLOWS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Array full
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].SourceIP, flow->SourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, flow->DestinationIP) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Error: Flow already exists
        }
    }

    manager->flows[manager->count++] = *flow;
    log_event("Added traffic flow");
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int remove_traffic_flow(FlowManager *manager, const char *sourceIP, const char *destIP) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].SourceIP, sourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, destIP) == 0) {
            memmove(&manager->flows[i], &manager->flows[i + 1],
                    (manager->count - i - 1) * sizeof(TrafficFlow));
            manager->count--;
            log_event("Removed traffic flow");
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Flow not found
}

int count_flows_by_protocol(FlowManager *manager, int protocolType) {
    size_t count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->flows[i].ProtocolType == protocolType) {
            count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return count;
}

void delete_inactive_flows(FlowManager *manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);

    size_t i = 0;
    while (i < manager->count) {
        if (difftime(now, manager->flows[i].LastUpdateTimestamp) > INACTIVE_THRESHOLD) {
            memmove(&manager->flows[i], &manager->flows[i + 1],
                    (manager->count - i - 1) * sizeof(TrafficFlow));
            manager->count--;
            log_event("Deleted inactive traffic flow");
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void flush_flow_cache(FlowManager *manager) {
    pthread_mutex_lock(&manager->lock);

    manager->count = 0;
    memset(manager->flows, 0, MAX_FLOWS * sizeof(TrafficFlow));
    log_event("Flushed flow cache");

    pthread_mutex_unlock(&manager->lock);
}

void export_flow_data(const FlowManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < manager->count; ++i) {
        fprintf(file, "%s %s %d %ld\n",
                manager->flows[i].SourceIP,
                manager->flows[i].DestinationIP,
                manager->flows[i].ProtocolType,
                manager->flows[i].LastUpdateTimestamp);
    }

    fclose(file);
}

void periodic_flush(FlowManager *manager) {
    while (1) {
        sleep(3600); // Wait for an hour
        flush_flow_cache(manager);
    }
}

int main() {
    FlowManager *manager = initialize_flow_manager();

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, (void *)periodic_flush, manager);

    // Example usage:
    TrafficFlow flow1 = {"192.168.0.1", "10.0.0.1", 6, time(NULL)};
    add_traffic_flow(manager, &flow1);

    delete_inactive_flows(manager);

    export_flow_data(manager, "traffic_data.txt");

    pthread_join(flush_thread, NULL);

    free(manager->flows);
    free(manager);
    return 0;
}
```

This code provides a thread-safe implementation for managing traffic flows with periodic flushing and logging. It includes memory management strategies to prevent leaks and fragmentation while maintaining performance.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENT_TYPE 100
#define MAX_PAYLOAD_SIZE 256
#define INITIAL_TABLE_SIZE 64
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    unsigned long timestamp;
    int type;
    char *payload;
} Event;

typedef struct {
    size_t count;
    size_t capacity;
    Event **events;
} EventTable;

typedef struct {
    unsigned long start;
    unsigned long end;
} DurationInterval;

typedef struct {
    size_t count;
    size_t capacity;
    DurationInterval *intervals;
} DurationTable;

typedef struct Node {
    int type;
    Event *event;
    struct Node *next;
} HashNode;

typedef struct {
    size_t capacity;
    size_t size;
    HashNode **buckets;
} HashMap;

#define HASH_MAP_INITIAL_CAPACITY 64

static pthread_mutex_t event_table_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t duration_table_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t hash_map_lock = PTHREAD_MUTEX_INITIALIZER;

// Memory Pool
typedef struct {
    size_t block_size;
    void *pool;
    size_t pool_size;
} MemoryPool;

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    if (size > mp->block_size || mp->pool == NULL) return malloc(size);
    char *ptr = mp->pool;
    mp->pool = ((char*)mp->pool) + mp->block_size;
    return ptr;
}

void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t num_blocks) {
    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = malloc(mp->pool_size);
}

// Hash Map Functions
static unsigned int hash(int type, size_t capacity) {
    return (unsigned int)(type % capacity);
}

HashMap* create_hash_map(size_t initial_capacity) {
    HashMap *map = (HashMap *)malloc(sizeof(HashMap));
    map->capacity = initial_capacity;
    map->size = 0;
    map->buckets = (HashNode **)calloc(map->capacity, sizeof(HashNode *));
    return map;
}

void rehash(HashMap *map) {
    size_t old_capacity = map->capacity;
    HashNode **old_buckets = map->buckets;

    map->capacity *= 2;
    map->size = 0;
    map->buckets = (HashNode **)calloc(map->capacity, sizeof(HashNode *));

    for (size_t i = 0; i < old_capacity; ++i) {
        HashNode *node = old_buckets[i];
        while (node != NULL) {
            unsigned int new_index = hash(node->type, map->capacity);
            HashNode *next_node = node->next;

            node->next = map->buckets[new_index];
            map->buckets[new_index] = node;
            node = next_node;
        }
    }

    free(old_buckets);
}

void insert_event(HashMap *map, int type, Event *event) {
    pthread_mutex_lock(&hash_map_lock);

    if ((double)map->size / map->capacity > LOAD_FACTOR_THRESHOLD) {
        rehash(map);
    }

    unsigned int index = hash(type, map->capacity);
    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    node->type = type;
    node->event = event;
    node->next = map->buckets[index];
    map->buckets[index] = node;

    map->size++;
    pthread_mutex_unlock(&hash_map_lock);
}

Event* get_event_by_type(HashMap *map, int type) {
    unsigned int index = hash(type, map->capacity);
    HashNode *node = map->buckets[index];

    while (node != NULL) {
        if (node->type == type) return node->event;
        node = node->next;
    }

    return NULL;
}

// Event Table Functions
void initialize_event_table(EventTable *table, size_t initial_capacity) {
    table->capacity = initial_capacity;
    table->count = 0;
    table->events = (Event **)malloc(table->capacity * sizeof(Event *));
}

void resize_event_table(EventTable *table) {
    pthread_mutex_lock(&event_table_lock);

    if (table->count >= table->capacity) {
        table->capacity *= 2;
        table->events = (Event **)realloc(table->events, table->capacity * sizeof(Event *));
    }

    pthread_mutex_unlock(&event_table_lock);
}

void insert_event_to_table(EventTable *table, Event *event) {
    pthread_mutex_lock(&event_table_lock);

    resize_event_table(table);
    table->events[table->count++] = event;

    pthread_mutex_unlock(&event_table_lock);
}

// Duration Table Functions
void initialize_duration_table(DurationTable *table, size_t initial_capacity) {
    table->capacity = initial_capacity;
    table->count = 0;
    table->intervals = (DurationInterval *)malloc(table->capacity * sizeof(DurationInterval));
}

void resize_duration_table(DurationTable *table) {
    pthread_mutex_lock(&duration_table_lock);

    if (table->count >= table->capacity) {
        table->capacity *= 2;
        table->intervals = (DurationInterval *)realloc(table->intervals, table->capacity * sizeof(DurationInterval));
    }

    pthread_mutex_unlock(&duration_table_lock);
}

void insert_duration_interval(DurationTable *table, unsigned long start, unsigned long end) {
    pthread_mutex_lock(&duration_table_lock);

    resize_duration_table(table);
    table->intervals[table->count++] = (DurationInterval){start, end};

    pthread_mutex_unlock(&duration_table_lock);
}

// Initialization Function
void initialize_tables(unsigned long time_window_start, unsigned long time_window_end, size_t num_events) {
    MemoryPool event_pool;
    initialize_memory_pool(&event_pool, sizeof(Event), num_events);

    EventTable event_table;
    initialize_event_table(&event_table, INITIAL_TABLE_SIZE);

    DurationTable duration_table;
    initialize_duration_table(&duration_table, INITIAL_TABLE_SIZE / 2);

    HashMap event_map = *create_hash_map(HASH_MAP_INITIAL_CAPACITY);

    unsigned long interval_size = (time_window_end - time_window_start) / (duration_table.capacity - 1);
    for (size_t i = 0; i < duration_table.capacity; ++i) {
        insert_duration_interval(&duration_table, time_window_start + i * interval_size,
                                time_window_start + (i + 1) * interval_size);
    }

    for (size_t i = 0; i < num_events; ++i) {
        unsigned long timestamp = time_window_start + rand() % (time_window_end - time_window_start);
        int type = rand() % MAX_EVENT_TYPE;
        size_t payload_length = rand() % MAX_PAYLOAD_SIZE;

        Event *event = (Event *)memory_pool_alloc(&event_pool, sizeof(Event));
        event->timestamp = timestamp;
        event->type = type;
        event->payload = (char *)malloc(payload_length);
        memset(event->payload, 0, payload_length);

        insert_event_to_table(&event_table, event);
        insert_event(&event_map, type, event);
    }
}

// Cleanup Functions
void cleanup_tables(EventTable *event_table, DurationTable *duration_table, HashMap *event_map, MemoryPool *event_pool) {
    for (size_t i = 0; i < event_table->count; ++i) {
        free(event_table->events[i]->payload);
        free(event_table->events[i]);
    }
    free(event_table->events);

    free(duration_table->intervals);

    for (size_t i = 0; i < event_map->capacity; ++i) {
        HashNode *node = event_map->buckets[i];
        while (node != NULL) {
            HashNode *next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(event_map->buckets);
    free(event_map);

    free(event_pool->pool);
}

int main() {
    initialize_tables(0, 1000000, 1000);

    // Simulate operations...

    return 0;
}
