int manage_memory_and_resolve_dns(int num_entries, size_t max_buffer_size) {
    // Allocate memory for entries
    Entry *entries = (Entry *)malloc(num_entries * sizeof(Entry));
    if (!entries) return ALLOCATION_FAILURE;

    // Allocate buffer for each entry and handle partial allocation
    for (int i = 0; i < num_entries; ++i) {
        entries[i].buffer = (char *)malloc(max_buffer_size);
        if (!entries[i].buffer) {
            printf("Partial allocation detected at index %d\n", i);

            // Free already allocated buffers before returning error
            for (int j = 0; j < i; ++j) {
                free(entries[j].buffer);
            }
            free(entries);
            return ALLOCATION_FAILURE;
        }
