    public string DestinationIP { get; set; }
    public string ProtocolType { get; set; }
    public DateTime LastUpdate { get; set; }

    public TrafficFlow(string sourceIp, string destinationIp, string protocolType)
    {
        SourceIP = sourceIp;
        DestinationIP = destinationIp;
        ProtocolType = protocolType;
        LastUpdate = DateTime.Now;
    }
}

public class DuplicateElementException : Exception
{
    public DuplicateElementException(string message) : base(message) { }
}

public class ElementNotFoundException : Exception
{
    public ElementNotFoundException(string message) : base(message) { }
}

public class TrafficManager
{
    private List<TrafficFlow> _trafficFlows = new List<TrafficFlow>();
    private const string RootDirectory = @"C:\Data\XMLProcessing";

    public void ManageTrafficAndParseXML()
    {
        // Example usage of adding, removing, and querying traffic flows
        AddTrafficFlow("192.168.1.1", "10.0.0.1", "TCP");

        try
        {
            string elementName = "exampleElement";
            ParseXmlForFirstElement(@"C:\Data\sample.xml", elementName);
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }

        BatchDeleteInactiveFlows();
    }

    public void AddTrafficFlow(string sourceIp, string destinationIp, string protocolType)
    {
        _trafficFlows.Add(new TrafficFlow(sourceIp, destinationIp, protocolType));
    }

    public bool RemoveTrafficFlowByIP(string ip)
    {
        var flow = _trafficFlows.FirstOrDefault(f => f.SourceIP == ip || f.DestinationIP == ip);
        if (flow != null)
        {
            _trafficFlows.Remove(flow);
            return true;
        }
        return false;
    }

    public int QueryFlowsByProtocol(string protocolType)
    {
        return _trafficFlows.Count(f => f.ProtocolType.Equals(protocolType, StringComparison.OrdinalIgnoreCase));
    }

    private void BatchDeleteInactiveFlows()
    {
        var cutoff = DateTime.Now.AddMinutes(-15);
        _trafficFlows.RemoveAll(f => f.LastUpdate < cutoff);
    }

    public string GetOrCreateDirPath()
    {
        string dirPath = Environment.GetEnvironmentVariable("DIR_PATH");
        if (!string.IsNullOrEmpty(dirPath) && Directory.Exists(dirPath))
            return dirPath;

        try
        {
            dirPath = Path.Combine(RootDirectory, $"{DateTime.Now:yyyyMMddHHmmssfff}_{Guid.NewGuid():N}");
            Directory.CreateDirectory(dirPath);
            Environment.SetEnvironmentVariable("DIR_PATH", dirPath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error creating directory: {ex.Message}");
        }

        return dirPath;
    }

    public void ParseXmlForFirstElement(string xmlFilePath, string elementName)
    {
        if (!File.Exists(xmlFilePath))
            throw new FileNotFoundException("XML file not found.");

        var doc = new XmlDocument();
        doc.Load(xmlFilePath);

        var nodes = doc.SelectNodes($"//{elementName}");
        if (nodes.Count > 1)
            throw new DuplicateElementException($"Multiple elements with name '{elementName}' found.");
        else if (nodes.Count == 0)
            throw new ElementNotFoundException($"Element '{elementName}' not found.");

        // Process the first element as needed
    }
}
