['Below is a C code implementation for managing a collection of network packet headers and associated payload data, optimized for high-throughput network traffic analysis applications in a cloud-native environment.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024
#define HEADER_SIZE sizeof(PacketHeader)
#define MAX_PACKETS 10000

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint8_t protocol_type;
    uint32_t packet_length;
    struct timespec timestamp;
    uint32_t checksum;
} PacketHeader;

typedef struct {
    void *payload;
    size_t payload_size;
} PayloadData;

typedef struct {
    PacketHeader *headers;
    PayloadData *payloads;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PacketPool;

PacketPool* create_packet_pool(size_t initial_capacity) {
    PacketPool *pool = (PacketPool *)malloc(sizeof(PacketPool));
    pool->headers = (PacketHeader *)malloc(initial_capacity * HEADER_SIZE);
    pool->payloads = (PayloadData *)malloc(initial_capacity * sizeof(PayloadData));
    pool->count = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void free_packet_pool(PacketPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool->headers);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->payloads[i].payload);
    }
    free(pool->payloads);
    free(pool);
}

int add_packet(PacketPool *pool, const char *src_ip, const char *dst_ip, uint8_t protocol_type,
               uint32_t packet_length, uint32_t checksum, void *payload_data, size_t payload_size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        PacketHeader *new_headers = (PacketHeader *)realloc(pool->headers, new_capacity * HEADER_SIZE);
        PayloadData *new_payloads = (PayloadData *)realloc(pool->payloads, new_capacity * sizeof(PayloadData));

        if (!new_headers || !new_payloads) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }

        pool->headers = new_headers;
        pool->payloads = new_payloads;
        pool->capacity = new_capacity;
    }

    PacketHeader *header = &pool->headers[pool->count];
    PayloadData *payload = &pool->payloads[pool->count];

    strncpy(header->src_ip, src_ip, sizeof(header->src_ip) - 1);
    strncpy(header->dst_ip, dst_ip, sizeof(header->dst_ip) - 1);
    header->protocol_type = protocol_type;
    header->packet_length = packet_length;
    clock_gettime(CLOCK_REALTIME, &header->timestamp);
    header->checksum = checksum;

    payload->payload = malloc(payload_size);
    if (!payload->payload) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory allocation failed
    }
    memcpy(payload->payload, payload_data, payload_size);
    payload->payload_size = payload_size;

    ++pool->count;
    pthread_cond_signal(&pool->cond);

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void* packet_iterator(PacketPool *pool, int reverse) {
    pthread_mutex_lock(&pool->lock);
    size_t start = (reverse ? pool->count - 1 : 0);
    size_t end = (reverse ? -1 : pool->count);
    size_t step = (reverse ? -1 : 1);

    for (size_t i = start; reverse ? i >= end : i < end; i += step) {
        pthread_mutex_unlock(&pool->lock);
        yield_packet_header(pool, i);
        pthread_mutex_lock(&pool->lock);
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void yield_packet_header(PacketPool *pool, size_t index) {
    if (index < pool->count) {
        PacketHeader *header = &pool->headers[index];
        printf("Packet %zu: Src IP: %s, Dst IP: %s, Protocol: %d\n",
               index, header->src_ip, header->dst_ip, header->protocol_type);
    }
}

int main() {
    PacketPool *pool = create_packet_pool(INITIAL_POOL_SIZE);

    // Example usage
    const char *src_ip = "192.168.1.1";
    const char *dst_ip = "192.168.1.2";
    uint8_t protocol_type = 6; // TCP
    uint32_t packet_length = 1500;
    uint32_t checksum = 12345;
    char payload_data[] = { 'H', 'e', 'l', 'l', 'o' };

    add_packet(pool, src_ip, dst_ip, protocol_type, packet_length, checksum, payload_data, sizeof(payload_data));

    packet_iterator(pool, 0);

    free_packet_pool(pool);
    return 0;
}
