#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include "mrand.h"  // Assume this is an external library for optimized random number generation

typedef struct item {
    double value;
    int number;
    struct item *next;
} item_t;

// Memory pool structure
typedef struct memory_pool {
    size_t block_size;
    size_t max_blocks;
    size_t current_blocks;
    void *memory;
    pthread_mutex_t lock;
} memory_pool_t;

// Initialize a new memory pool
int init_memory_pool(memory_pool_t *pool, size_t block_size, size_t max_blocks) {
    pool->block_size = block_size;
    pool->max_blocks = max_blocks;
    pool->current_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);

    if (block_size == 0 || max_blocks == 0) return -1;

    pool->memory = malloc(block_size * max_blocks);
    if (!pool->memory) {
        perror("Failed to allocate memory for the pool");
        pthread_mutex_destroy(&pool->lock);
        return -1;
    }

    return 0;
}

// Free all resources associated with the memory pool
void free_memory_pool(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->memory) free(pool->memory);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Allocate a block from the memory pool
item_t* allocate_from_pool(memory_pool_t *pool) {
    item_t *block = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->current_blocks < pool->max_blocks) {
        block = (item_t*) ((char*) pool->memory + pool->block_size * pool->current_blocks);
        pool->current_blocks++;
    }
    pthread_mutex_unlock(&pool->lock);

    if (!block) {
        fprintf(stderr, "Insufficient memory in the pool\n");
    }

    return block;
}

// Function to initialize the data structure
void* populate_items(void *arg);

item_t* create_hierarchical_structure(memory_pool_t *pool, int depth, int min_val, int max_val) {
    if (depth < 0) return NULL;

    item_t *root = allocate_from_pool(pool);
    if (!root) return NULL;

    root->value = mrand_double(); // Use external library for random double
    root->number = mrand_int(min_val, max_val); // Use external library for random int

    pthread_t thread;
    void *result;
    pthread_create(&thread, NULL, populate_items, (void*) &root->next);
    pthread_join(thread, &result);

    return root;
}

// Recursive function to populate items
void* populate_items(void *arg) {
    item_t **item_ptr = (item_t **) arg;

    for (int i = 0; i < 10; ++i) { // Arbitrary number of children per node
        (*item_ptr)[i] = create_hierarchical_structure(pool, depth - 1, min_val, max_val);
    }

    return NULL;
}

// Example usage and test cases

int main() {
    memory_pool_t pool;
    int depth = 5; // Example depth for the hierarchy
    int min_val = 0, max_val = 100;

    if (init_memory_pool(&pool, sizeof(item_t), 1000000) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return -1;
    }

    srand(time(NULL)); // Seed the random number generator
    item_t *root = create_hierarchical_structure(&pool, depth, min_val, max_val);

    if (!root) {
        fprintf(stderr, "Failed to create hierarchical structure\n");
        free_memory_pool(&pool);
        return -1;
    }

    printf("Root value: %f, number: %d\n", root->value, root->number);

    // Free memory and clean up
    free_memory_pool(&pool);
    return 0;
}
