// Memory Pool Management
#define POOL_SIZE 1000

typedef struct MemoryPool {
    void *pool[POOL_SIZE];
    size_t block_size;
    int next_free;
    pthread_mutex_t pool_lock;
} MemoryPool;

void initMemoryPool(MemoryPool *mp, size_t block_size) {
    mp->block_size = block_size;
    for (int i = 0; i < POOL_SIZE; ++i) {
        mp->pool[i] = malloc(block_size);
    }
    mp->next_free = 0;
    pthread_mutex_init(&mp->pool_lock, NULL);
}

void *allocateFromPool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->pool_lock);
    if (mp->next_free < POOL_SIZE) {
        void *block = mp->pool[mp->next_free++];
        pthread_mutex_unlock(&mp->pool_lock);
        return block;
    }
    pthread_mutex_unlock(&mp->pool_lock);
    return NULL; // Pool exhausted
}

void freeMemoryPool(MemoryPool *mp) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        free(mp->pool[i]);
    }
    pthread_mutex_destroy(&mp->pool_lock);
}

