// Define constants for collection sizes and maximum string length
#define COLLECTION_SIZE 9
#define MAX_METADATA_LENGTH 256

typedef struct record {
    short sh_val;
    int i_val;
    float f_val;
    int timestamp;
    char *metadata; 
    char event_type;
    char status_indicator;
    double location_coord;
    int priority_level;
} Record;

// Node structure for doubly linked list
typedef struct node {
    Record data;
    struct node *prev;
    struct node *next;
} Node;

// Memory pool management structures
typedef struct memory_pool {
    size_t block_size;
    void *start;
    void *current;
    void *end;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* initialize_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->start = malloc(block_size * num_blocks);
    if (!pool->start) return NULL;
    pool->current = pool->start;
    pool->end = (char *)pool->start + block_size * num_blocks;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if ((char*)pool->current + pool->block_size > pool->end) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }
    void *allocated = pool->current;
    pool->current = (void*)((char*)pool->current + pool->block_size);
    pthread_mutex_unlock(&pool->lock);
    return allocated;
}

// Function to initialize collections and linked list
void manage_memory_and_initialize_collections() {
