    char *event_types = (char*) allocate_from_pool(record_pool);
    char *status_indicators = (char*) allocate_from_pool(record_pool);
    double *locations = (double*) allocate_from_pool(record_pool);
    int *priorities = (int*) allocate_from_pool(record_pool);

    // Initialize keys and offsets
    srand(time(NULL)); // Seed for random number generation
    long offset_sum = 0;
    const int key_range_start = 1, key_range_end = 1000;

    for (int i = 0; i < COLLECTION_SIZE; ++i) {
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        offset_sum += keys[i];
        offsets[i] = offset_sum + i * 10; // Constant value added
    }

    Node *head = NULL, *tail = NULL;

    for (int i = 0; i < COLLECTION_SIZE; ++i) {
        records[i].sh_val = rand() % 100;
        records[i].i_val = rand() % 1000;
        records[i].f_val = ((float)rand()) / RAND_MAX * 100.0;
        timestamps[i] = rand() % (3600 * 24); // Seconds in a day

        metadata[i] = (char*) allocate_from_pool(record_pool);
