        Node *new_node = (Node*) allocate_from_pool(record_pool);
        new_node->data = records[i];
        new_node->prev = tail;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;
    }

    // Free resources after use (example)
    free(record_pool->start);
    free(record_pool);

    printf("Initialization complete. Head record short value: %d\n", head ? head->data.sh_val : -1);
}

int main() {
