#define DOUBLE_RANGE_MAX 1.0
#define INT_RANGE_MIN -10000
#define INT_RANGE_MAX 10000

typedef struct {
    double value;
    int number;
    struct item* next_item;
    long identifier;
    unsigned int index;
} item;

typedef struct record {
    short s_value;
    int i_value;
    float f_value;
    int timestamp;
    char* metadata;
    double d_value;
    item inner_item;
} record;

typedef struct Node {
    record data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    long* offset;
    int size_offset;
    int capacity_offset;
    int* key;
    int size_key;
    int capacity_key;
    record* records;
    int size_records;
    int capacity_records;
    pthread_mutex_t lock;
    Node* head;
    Node* tail;
} DataManager;

void initialize_rng() {
    srand(time(NULL));
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

double generate_random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

bool is_valid_metadata(const char* metadata) {
    if (strlen(metadata) > MAX_METADATA_LENGTH) return false;
    for (int i = 0; i < strlen(metadata); ++i) {
        if (!isprint(metadata[i])) return false;
    }
    return true;
}

void resize_arrays(DataManager* dm, int new_capacity) {
    pthread_mutex_lock(&dm->lock);

    dm->offset = realloc(dm->offset, new_capacity * sizeof(long));
    dm->key = realloc(dm->key, new_capacity * sizeof(int));
    dm->records = realloc(dm->records, new_capacity * sizeof(record));

    if (dm->capacity_offset < new_capacity) {
        memset(dm->offset + dm->size_offset, 0, (new_capacity - dm->size_offset) * sizeof(long));
    }
    if (dm->capacity_key < new_capacity) {
        for (int i = dm->size_key; i < new_capacity; ++i) {
            dm->key[i] = generate_random_int(KEY_RANGE_START, KEY_RANGE_END);
        }
    }

    dm->capacity_offset = new_capacity;
    dm->capacity_key = new_capacity;
    dm->capacity_records = new_capacity;

    pthread_mutex_unlock(&dm->lock);
}

void initialize_data_manager(DataManager* dm) {
    pthread_mutex_init(&dm->lock, NULL);

    dm->offset = malloc(10 * sizeof(long));
    dm->key = malloc(10 * sizeof(int));
    dm->records = malloc(10 * sizeof(record));

    dm->size_offset = 0;
    dm->size_key = 0;
    dm->size_records = 0;

    dm->capacity_offset = 10;
    dm->capacity_key = 10;
    dm->capacity_records = 10;

    dm->head = NULL;
    dm->tail = NULL;
}

void add_record(DataManager* dm, const char* metadata) {
    pthread_mutex_lock(&dm->lock);

    if (is_valid_metadata(metadata)) {
        if (dm->size_records >= dm->capacity_records) {
            resize_arrays(dm, dm->capacity_records * 2);
        }

        record new_rec;
        new_rec.s_value = generate_random_int(INT_RANGE_MIN, INT_RANGE_MAX);
        new_rec.i_value = generate_random_int(INT_RANGE_MIN, INT_RANGE_MAX);
        new_rec.f_value = (float)generate_random_double(DOUBLE_RANGE_MIN, DOUBLE_RANGE_MAX);
        new_rec.timestamp = time(NULL);
        new_rec.metadata = strdup(metadata);
        new_rec.d_value = generate_random_double(DOUBLE_RANGE_MIN, DOUBLE_RANGE_MAX);

        item* new_item = &new_rec.inner_item;
        new_item->value = generate_random_double(DOUBLE_RANGE_MIN, DOUBLE_RANGE_MAX);
        new_item->number = generate_random_int(INT_RANGE_MIN, INT_RANGE_MAX);
        new_item->next_item = NULL;
        new_item->identifier = rand();
        new_item->index = dm->size_records;

        if (dm->head == NULL) {
            dm->head = malloc(sizeof(Node));
            dm->tail = dm->head;
            dm->head->data = new_rec;
            dm->head->prev = NULL;
            dm->head->next = NULL;
        } else {
            Node* new_node = malloc(sizeof(Node));
            dm->tail->next = new_node;
            new_node->prev = dm->tail;
            new_node->next = NULL;
            new_node->data = new_rec;
            dm->tail = new_node;
        }

        long cumulative_sum = 0;
        if (dm->size_key > 0) {
            for (int i = 0; i < dm->size_key; ++i) {
                cumulative_sum += dm->key[i];
            }
        }
        dm->offset[dm->size_records] = cumulative_sum + KEY_RANGE_START;

        dm->key[dm->size_key] = generate_random_int(KEY_RANGE_START, KEY_RANGE_END);
        dm->records[dm->size_records] = new_rec;

        dm->size_records++;
        dm->size_offset++;
        dm->size_key++;

    } else {
        printf("Invalid metadata: %s\n", metadata);
    }

    pthread_mutex_unlock(&dm->lock);
}

void free_data_manager(DataManager* dm) {
    pthread_mutex_lock(&dm->lock);

    Node* current = dm->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.metadata);
        free(current);
        current = next;
    }

    free(dm->offset);
    free(dm->key);
    free(dm->records);

    pthread_mutex_unlock(&dm->lock);
    pthread_mutex_destroy(&dm->lock);
}

void test_data_manager() {
    DataManager dm;
    initialize_data_manager(&dm);
    initialize_rng();

    add_record(&dm, "Test metadata 1");
    add_record(&dm, "Valid metadata 2");

    // Add more tests to stress the system with large datasets
    for (int i = 0; i < 1000; ++i) {
        char buffer[MAX_METADATA_LENGTH];
        snprintf(buffer, MAX_METADATA_LENGTH, "Metadata %d", i);
        add_record(&dm, buffer);
    }

    free_data_manager(&dm);
}

int main() {
    test_data_manager();
    return 0;
}
```

