} DynamicStructure;

// Function prototypes
DynamicStructure* initialize_dynamic_structure(size_t initial_size, unsigned int seed);
void cleanup_dynamic_structure(DynamicStructure *ds);
int insert_record(DynamicStructure *ds, int key, long offset);
int delete_record(DynamicStructure *ds, int key);
Record* find_record_by_key(const DynamicStructure *ds, int key);

// Initialize the dynamic structure
DynamicStructure* initialize_dynamic_structure(size_t initial_size, unsigned int seed) {
    DynamicStructure *ds = malloc(sizeof(DynamicStructure));
    if (!ds) return NULL;

    ds->offsets_count = 0;
    ds->keys_count = 0;

    // Allocate memory for offsets and keys with bounds checking
    ds->offsets = calloc(initial_size, sizeof(long));
    if (!ds->offsets) {
        free(ds);
        return NULL;
    }

    ds->keys = calloc(initial_size, sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    // Initialize linked list head
    ds->records_head = NULL;

    // Initialize mutex for thread safety
    pthread_mutex_init(&ds->mutex, NULL);

    srand(seed);  // Seed the random number generator

    return ds;
}

// Cleanup function to release allocated memory
void cleanup_dynamic_structure(DynamicStructure *ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);

    Record *current = ds->records_head, *temp;
    while (current) {
        temp = current->next;
        free(current);
        current = temp;
    }

    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

// Insert a new record into the structure
int insert_record(DynamicStructure *ds, int key, long offset) {
    if (!ds) return -1;

    pthread_mutex_lock(&ds->mutex);

    // Bounds checking for offsets and keys arrays
    if (ds->offsets_count >= MAX_MEMORY_USAGE / sizeof(long)) {
        pthread_mutex_unlock(&ds->mutex);
        return -2;  // Memory limit exceeded
    }

    ds->keys[ds->keys_count] = key;
    ds->offsets[ds->offsets_count++] = offset;

    // Create a new record with random value in the range [0, 100)
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&ds->mutex);
        return -3;  // Memory allocation failed
    }

    new_record->value = rand() % 101;
    new_record->next = ds->records_head;
    ds->records_head = new_record;

    pthread_mutex_unlock(&ds->mutex);

    return 0;  // Success
}

// Delete a record by key from the structure
int delete_record(DynamicStructure *ds, int key) {
    if (!ds) return -1;

    pthread_mutex_lock(&ds->mutex);

    Record **current = &ds->records_head;
    while (*current) {
        Record *entry = *current;
        if (entry->value == key) {  // Match found
            *current = entry->next;
            free(entry);
            break;
        }
        current = &entry->next;
    }

    pthread_mutex_unlock(&ds->mutex);

    return 0;  // Success or not found (does not affect integrity)
}

// Find a record by key in the structure
Record* find_record_by_key(const DynamicStructure *ds, int key) {
    if (!ds) return NULL;

    Record *current = ds->records_head;
    while (current) {
        if (current->value == key) return current;
        current = current->next;
    }

    return NULL;  // Not found
}

