} DataStructure;

DataStructure* create_data_structure(size_t size) {
    if (size == 0) return NULL;

    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate memory for data structure");
        return NULL;
    }

    ds->offset = (long*)calloc(size, sizeof(long));
    if (!ds->offset) {
        free(ds);
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    ds->keys = (int*)malloc(size * sizeof(int));
    if (!ds->keys) {
        free(ds->offset);
        free(ds);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    ds->records = (record**)malloc(size * sizeof(record*));
    if (!ds->records) {
        free(ds->keys);
        free(ds->offset);
        free(ds);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    ds->size = size;
    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        ds->records[i] = NULL;
    }

    return ds;
}

void free_data_structure(DataStructure* ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]);
        }
    }

    free(ds->offset);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);

    free(ds);
}

record* allocate_record() {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) {
        perror("Failed to allocate memory for record");
    }
    return rec;
}

void set_record(DataStructure* ds, size_t index, int value) {
    if (!ds || index >= ds->size) return;

    pthread_mutex_lock(&ds->lock);

    if (index < ds->size && ds->records[index] == NULL) {
        ds->records[index] = allocate_record();
    }

    if (ds->records[index]) {
        ds->records[index]->value = value;
    }

    pthread_mutex_unlock(&ds->lock);
}

int get_record(DataStructure* ds, size_t index) {
    if (!ds || index >= ds->size) return -1;

    int value = -1;

    pthread_mutex_lock(&ds->lock);

    if (index < ds->size && ds->records[index]) {
        value = ds->records[index]->value;
    }

    pthread_mutex_unlock(&ds->lock);

    return value;
}

void log_message(const char* message) {
