    printf("%s\n", message);
}

int main() {
    size_t dataset_size = 1000; // Example dataset size

    DataStructure* ds = create_data_structure(dataset_size);
    if (!ds) return EXIT_FAILURE;

    set_record(ds, 5, 42);

    int value = get_record(ds, 5);
    log_message(value != -1 ? "Record retrieved successfully" : "Failed to retrieve record");

    free_data_structure(ds);

    return EXIT_SUCCESS;
}
