['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 100 // 100 MB limit for simplicity
#define KEY_RANGE 1000

typedef struct record {
    int value;
    struct record* next;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safety
    Record* head;
} DynamicDataStructure;

// Secondary index structure
typedef struct {
    int key;
    Record** records;
    size_t count;
    pthread_rwlock_t rwlock; // Read-write lock for secondary index
} SecondaryIndex;

void initialize_random(int seed) {
    srand(seed);
}

int random_int_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DynamicDataStructure* create_structure(size_t initial_size, int seed) {
    DynamicDataStructure* ds = malloc(sizeof(DynamicDataStructure));
    if (!ds) exit(1);

    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = malloc(initial_size * sizeof(long));
    ds->keys = malloc(initial_size * sizeof(int));
    ds->size = 0;

    initialize_random(seed);

    ds->head = NULL;
    return ds;
}

SecondaryIndex* create_secondary_index(size_t initial_capacity) {
    SecondaryIndex* si = malloc(sizeof(SecondaryIndex));
    if (!si) exit(1);

    pthread_rwlock_init(&si->rwlock, NULL);
    si->records = calloc(initial_capacity, sizeof(Record*)); // Preallocate for efficiency
    si->count = 0;

    return si;
}

void insert_record(DynamicDataStructure* ds, SecondaryIndex* si, int key) {
    pthread_mutex_lock(&ds->lock);

    if (ds->size >= MAX_MEMORY_USAGE / sizeof(long)) { // Simplified memory check
        printf("Memory limit reached.\n");
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    long offset = rand(); // Randomly generate for example purposes

    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&ds->lock);
        exit(1);
    }

    new_record->value = random_int_in_range(0, 100); // Random value
    new_record->next = ds->head;
    ds->head = new_record;

    // Update secondary index
    pthread_rwlock_wrlock(&si->rwlock);

    for (size_t i = 0; i < si->count; ++i) {
        if (si->records[i]->key == key) {
            si->records[i] = realloc(si->records[i], sizeof(Record*) * (ds->size + 1));
            si->records[i][ds->size] = new_record;
            pthread_rwlock_unlock(&si->rwlock);
            pthread_mutex_unlock(&ds->lock);
            return;
        }
    }

    if (si->count >= si->capacity) {
        size_t new_capacity = si->count * 2;
        si->records = realloc(si->records, sizeof(Record*) * new_capacity);
        si->capacity = new_capacity;
    }

    si->records[si->count] = malloc(sizeof(Record*));
    si->records[si->count][0] = new_record;
    ++si->count;

    pthread_rwlock_unlock(&si->rwlock);

    ds->size++;
    pthread_mutex_unlock(&ds->lock);
}

void delete_record(DynamicDataStructure* ds, SecondaryIndex* si, int key) {
    pthread_mutex_lock(&ds->lock);

    Record **current = &ds->head;
    while (*current && (*current)->value != key) {
        current = &(*current)->next;
    }

    if (*current) { // If record found
        Record *to_delete = *current;
        *current = to_delete->next;

        pthread_rwlock_wrlock(&si->rwlock);
        for (size_t i = 0; i < si->count; ++i) {
            for (size_t j = 0; j <= ds->size; ++j) {
                if (si->records[i][j] == to_delete) {
                    // Shift array left and free
                    memmove(&si->records[i][j], &si->records[i][j + 1],
                            sizeof(Record*) * ((ds->size - j) - 1));
                    --si->count;
                    break;
                }
            }
        }

        pthread_rwlock_unlock(&si->rwlock);

        free(to_delete);
    }

    pthread_mutex_unlock(&ds->lock);
}

void traverse_records(DynamicDataStructure* ds) {
    Record* current = ds->head;

    while (current) {
        printf("Record Value: %d\n", current->value);
        current = current->next;
    }
}

int main() {
    DynamicDataStructure* ds = create_structure(100, 12345);
    SecondaryIndex* si = create_secondary_index(50);

    insert_record(ds, si, 5);
    insert_record(ds, si, 10);

    traverse_records(ds);
    delete_record(ds, si, 5);

    free(ds->offsets);
    free(ds->keys);
    pthread_mutex_destroy(&ds->lock);

    free(si->records);
    pthread_rwlock_destroy(&si->rwlock);

    return 0;
}
```

