### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LENGTH 256
#define INITIAL_SIZE 10

typedef struct {
    double file_size;
    time_t modification_time;
    int access_rights; // Bitmask for permissions (e.g., read, write)
} file_metadata;

// Linked list node
typedef struct file_node {
    file_metadata metadata;
    char *file_path;
    struct file_node *next;
} file_node;

// Function prototypes
void initialize_file_system(double **file_sizes, char ***file_paths, int *path_count);
void free_resources(file_node *head, double *file_sizes, char **file_paths, int path_count);
int validate_and_add_file(char *file_path, file_node **head, double *file_sizes, int *index);
void apply_filter_condition(const char *condition, file_node *head);

// Python C API initialization
#include <Python.h>

static PyObject* py_apply_filter(PyObject *self, PyObject *args) {
    const char *condition;
    if (!PyArg_ParseTuple(args, "s", &condition))
        return NULL;

    apply_filter_condition(condition, head);
    Py_RETURN_NONE;
}

// Module method definitions
static PyMethodDef FileMethods[] = {
    {"apply_filter", py_apply_filter, METH_VARARGS, "Apply a filter condition to file paths."},
    {NULL, NULL, 0, NULL}
};

// Module definition
static struct PyModuleDef filemodule = {
    PyModuleDef_HEAD_INIT,
    "file_manager",
    NULL,
    -1,
    FileMethods
};

PyMODINIT_FUNC PyInit_file_manager(void) {
    return PyModule_Create(&filemodule);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <python_script.py>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double *file_sizes = NULL;
    char **file_paths = NULL;
    int path_count = 0;

    // Initialize file system components
    initialize_file_system(&file_sizes, &file_paths, &path_count);

    // Load Python module and execute script
    Py_Initialize();
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open Python script.\n");
        free_resources(NULL, file_sizes, file_paths, path_count);
        return EXIT_FAILURE;
    }
    PyRun_SimpleFile(fp, argv[1]);
    fclose(fp);

    // Clean up resources
    free_resources(NULL, file_sizes, file_paths, path_count);
    Py_Finalize();

    return 0;
}

void initialize_file_system(double **file_sizes, char ***file_paths, int *path_count) {
    *file_sizes = (double *)malloc(INITIAL_SIZE * sizeof(double));
    if (*file_sizes == NULL) {
        fprintf(stderr, "Failed to allocate memory for file sizes.\n");
        exit(EXIT_FAILURE);
    }

    *file_paths = (char **)malloc(INITIAL_SIZE * sizeof(char *));
    if (*file_paths == NULL) {
        fprintf(stderr, "Failed to allocate memory for file paths.\n");
        free(*file_sizes);
        exit(EXIT_FAILURE);
    }

    *path_count = 0;
}

void free_resources(file_node *head, double *file_sizes, char **file_paths, int path_count) {
    // Free linked list
    while (head != NULL) {
        file_node *temp = head;
        head = head->next;
        free(temp->file_path);
        free(temp);
    }

    // Free arrays
    free(file_sizes);
    for (int i = 0; i < path_count; i++) {
        free(file_paths[i]);
    }
    free(file_paths);
}

int validate_and_add_file(char *file_path, file_node **head, double *file_sizes, int *index) {
    if (strlen(file_path) >= MAX_PATH_LENGTH) return -1;

    // Allocate new node
    file_node *new_node = (file_node *)malloc(sizeof(file_node));
    if (!new_node) return -1;

    new_node->file_path = strdup(file_path);
    if (!new_node->file_path) {
        free(new_node);
        return -1;
    }

    // Mock metadata
    new_node->metadata.file_size = file_sizes[*index];
    new_node->metadata.modification_time = time(NULL);
    new_node->metadata.access_rights = 0x01; // Example permission

    new_node->next = *head;
    *head = new_node;

    (*index)++;
    if (*index >= INITIAL_SIZE) {
        *file_sizes = (double *)realloc(*file_sizes, (*index + INITIAL_SIZE) * sizeof(double));
        if (*file_sizes == NULL) {
            free_resources(*head, file_sizes, NULL, 0);
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

void apply_filter_condition(const char *condition, file_node *head) {
    // Example filter implementation
    while (head != NULL) {
        if (strstr(head->file_path, condition)) {
            printf("Filtered File: %s\n", head->file_path);
        }
        head = head->next;
    }
}
```

