```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define POOL_SIZE 1024

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int keys;
    record_t *records;
} data_structure_t;

typedef struct {
    void* blocks[POOL_SIZE];
    size_t block_size;
    pthread_mutex_t lock;
} memory_pool_t;

// Initialize a custom memory pool
void init_memory_pool(memory_pool_t *pool, size_t block_size) {
    pool->block_size = block_size;
    pthread_mutex_init(&pool->lock, NULL);
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Allocate memory from the custom memory pool
void* allocate_from_pool(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->blocks[i] != NULL) {
            void* block = pool->blocks[i];
            pool->blocks[i] = NULL;
            pthread_mutex_unlock(&pool->lock);
            return block;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return malloc(pool->block_size); // Fallback to standard allocation
}

// Free memory back to the custom memory pool
void free_to_pool(memory_pool_t *pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->blocks[i] == NULL) {
            pool->blocks[i] = block;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Initialize the data structure
data_structure_t* init_data_structure(long offset, int keys, size_t record_count) {
    memory_pool_t pool;
    init_memory_pool(&pool, sizeof(data_structure_t));

    data_structure_t *ds = (data_structure_t*)allocate_from_pool(&pool);
    if (!ds) {
        fprintf(stderr, "Memory allocation for data structure failed\n");
        return NULL;
    }

    ds->offset = offset;
    ds->keys = keys;
    ds->records = (record_t*)allocate_from_pool(&pool);

    if (!ds->records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        free_to_pool(&pool, ds);
        return NULL;
    }

    memset(ds->records, 0, record_count * sizeof(record_t));

    return ds;
}

// Free the data structure
void free_data_structure(data_structure_t* ds) {
    if (ds) {
        // Assuming memory pool is accessible or passed along with `ds`
        // Example:
        // free_to_pool(&pool, ds->records);
        // free_to_pool(&pool, ds);

        // If no custom free logic, default to:
        free(ds->records);
        free(ds);
    }
}

// Example usage
int main() {
    data_structure_t *ds = init_data_structure(42L, 100, 1000);
    if (ds) {
        printf("Data structure initialized with offset: %ld\n", ds->offset);

        // Perform operations...

        free_data_structure(ds);
    }
    return 0;
}
```

### Key Features Explained:
- **Memory Pool**: A custom memory pool is used to manage allocations efficiently, reducing the overhead of frequent `malloc`/`free` calls.
- **Locking**: Mutexes ensure thread safety during allocation and deallocation from the memory pool. This can be optimized further for high-concurrency scenarios using lock-free techniques if needed.
- **Error Handling**: Checks are in place to handle failures gracefully, providing meaningful feedback when allocations fail.
- **Scalability Considerations**: The design supports scaling by allowing easy integration with distributed storage solutions and parallel processing (though not explicitly implemented here).
- **Thread Safety**: Basic thread safety is provided through mutexes; further optimizations can be done using atomic operations or lock-free data structures.

This code provides a foundational approach to managing memory efficiently in a C environment that interfaces with PHP components, considering performance, scalability, and error handling.']

