```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2
#define OFFSET_CONSTANT 5

typedef struct {
    short field1;
    int field2;
    float field3;
} Record;

typedef struct Element {
    int id;
    double *value;
    struct Element *next;
} Element;

typedef struct {
    long *offsets;
    int size;
} OffsetArray;

typedef struct {
    int *keys;
    int size;
} KeyArray;

typedef struct {
    Record **records;
    int size;
    pthread_mutex_t lock;
} RecordLinkedList;

typedef struct {
    double *float_values;
    int size;
} FloatArray;

typedef struct {
    Element **elements;
    int size;
    int capacity;
    pthread_mutex_t lock;
} HashTable;

// Function Prototypes
void initOffsetArray(OffsetArray *oa, int initial_size);
void resizeOffsetArray(OffsetArray *oa);
void freeOffsetArray(OffsetArray *oa);

void initKeyArray(KeyArray *ka, int range_min, int range_max, int initial_size);
void resizeKeyArray(KeyArray *ka);
void freeKeyArray(KeyArray *ka);

void initRecordLinkedList(RecordLinkedList *rl, int initial_size);
void addRecord(RecordLinkedList *rl, Record record);
void freeRecordLinkedList(RecordLinkedList *rl);

void initFloatArray(FloatArray *fa, double min, double max, int initial_size);
void resizeFloatArray(FloatArray *fa);
void freeFloatArray(FloatArray *fa);

void initHashTable(HashTable *ht, int initial_capacity);
void addElement(HashTable *ht, int id, double value);
double getElementValue(HashTable *ht, int id);
void resizeHashTable(HashTable *ht);
void freeHashTable(HashTable *ht);

// Function Implementations
void initOffsetArray(OffsetArray *oa, int initial_size) {
    oa->size = 0;
    oa->offsets = malloc(initial_size * sizeof(long));
}

void resizeOffsetArray(OffsetArray *oa) {
    if (oa->size >= oa->capacity) {
        oa->capacity = oa->capacity ? oa->capacity * GROWTH_FACTOR : INITIAL_SIZE;
        oa->offsets = realloc(oa->offsets, oa->capacity * sizeof(long));
    }
}

void freeOffsetArray(OffsetArray *oa) {
    free(oa->offsets);
}

void initKeyArray(KeyArray *ka, int range_min, int range_max, int initial_size) {
    ka->size = 0;
    ka->keys = malloc(initial_size * sizeof(int));
    srand(time(NULL));

    while (ka->size < initial_size) {
        int key = rand() % (range_max - range_min + 1) + range_min;
        // Ensure unique keys
        for (int i = 0; i < ka->size; ++i) {
            if (ka->keys[i] == key) break;
            if (i == ka->size - 1) {
                ka->keys[ka->size++] = key;
                break;
            }
        }
    }
}

void resizeKeyArray(KeyArray *ka) {
    if (ka->size >= ka->capacity) {
        ka->capacity = ka->capacity ? ka->capacity * GROWTH_FACTOR : INITIAL_SIZE;
        ka->keys = realloc(ka->keys, ka->capacity * sizeof(int));
    }
}

void freeKeyArray(KeyArray *ka) {
    free(ka->keys);
}

void initRecordLinkedList(RecordLinkedList *rl, int initial_size) {
    rl->size = 0;
    pthread_mutex_init(&rl->lock, NULL);
    rl->records = malloc(initial_size * sizeof(Record *));
}

void addRecord(RecordLinkedList *rl, Record record) {
    pthread_mutex_lock(&rl->lock);
    if (rl->size >= rl->capacity) resizeRecordLinkedList(rl);

    rl->records[rl->size++] = &record;
    pthread_mutex_unlock(&rl->lock);
}

void freeRecordLinkedList(RecordLinkedList *rl) {
    pthread_mutex_destroy(&rl->lock);
    free(rl->records);
}

void initFloatArray(FloatArray *fa, double min, double max, int initial_size) {
    fa->size = 0;
    fa->float_values = malloc(initial_size * sizeof(double));
    srand(time(NULL));

    for (int i = 0; i < initial_size; ++i) {
        fa->float_values[i] = ((double)rand() / RAND_MAX) * (max - min) + min;
    }
}

void resizeFloatArray(FloatArray *fa) {
    if (fa->size >= fa->capacity) {
        fa->capacity = fa->capacity ? fa->capacity * GROWTH_FACTOR : INITIAL_SIZE;
        fa->float_values = realloc(fa->float_values, fa->capacity * sizeof(double));
    }
}

void freeFloatArray(FloatArray *fa) {
    free(fa->float_values);
}

void initHashTable(HashTable *ht, int initial_capacity) {
    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->elements = calloc(initial_capacity, sizeof(Element *));
    pthread_mutex_init(&ht->lock, NULL);
}

void addElement(HashTable *ht, int id, double value) {
    pthread_mutex_lock(&ht->lock);

    if (ht->size >= ht->capacity) resizeHashTable(ht);

    Element *new_element = malloc(sizeof(Element));
    new_element->id = id;
    new_element->value = malloc(sizeof(double));
    *(new_element->value) = value;

    int index = id % ht->capacity;
    while (ht->elements[index]) {
        index = (index + 1) % ht->capacity;
    }

    new_element->next = ht->elements[index];
    ht->elements[index] = new_element;
    ht->size++;

    pthread_mutex_unlock(&ht->lock);
}

double getElementValue(HashTable *ht, int id) {
    pthread_mutex_lock(&ht->lock);

    int index = id % ht->capacity;
    Element *current = ht->elements[index];
    while (current && current->id != id) {
        current = current->next;
    }

    double value = 0.0;
    if (current) value = *(current->value);

    pthread_mutex_unlock(&ht->lock);
    return value;
}

void resizeHashTable(HashTable *ht) {
    int new_capacity = ht->capacity * GROWTH_FACTOR;
    Element **new_elements = calloc(new_capacity, sizeof(Element *));
    for (int i = 0; i < ht->capacity; ++i) {
        Element *current = ht->elements[i];
        while (current) {
            Element *next = current->next;

            int index = current->id % new_capacity;
            current->next = new_elements[index];
            new_elements[index] = current;

            current = next;
        }
    }

    free(ht->elements);
    ht->elements = new_elements;
    ht->capacity = new_capacity;
}

void freeHashTable(HashTable *ht) {
    for (int i = 0; i < ht->capacity; ++i) {
        Element *current = ht->elements[i];
        while (current) {
            Element *next = current->next;
            free(current->value);
            free(current);
            current = next;
        }
    }

    free(ht->elements);
    pthread_mutex_destroy(&ht->lock);
}

// Main function for testing
int main() {
    OffsetArray oa;
    initOffsetArray(&oa, INITIAL_SIZE);

    KeyArray ka;
    initKeyArray(&ka, 1, 100, INITIAL_SIZE);

    RecordLinkedList rl;
    initRecordLinkedList(&rl, INITIAL_SIZE);

    FloatArray fa;
    initFloatArray(&fa, -10.0, 10.0, INITIAL_SIZE);

    HashTable ht;
    initHashTable(&ht, INITIAL_SIZE);

    // Example usage
    addElement(&ht, 1, 3.14);
    double value = getElementValue(&ht, 1);

    printf("Double value: %f\n", value);

    freeOffsetArray(&oa);
    freeKeyArray(&ka);
    freeRecordLinkedList(&rl);
    freeFloatArray(&fa);
    freeHashTable(&ht);

    return 0;
}
