['Below is a C implementation that addresses the requirements for dynamically managing cryptographic algorithms within a system:

```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <dlfcn.h>  // For dynamic loading

// Define a structure to represent an algorithm
typedef struct {
    char *name;
    void (*init)(void);
    void (*cleanup)(void);
    int (*process)(const unsigned char *, size_t, unsigned char *);
} Algorithm;

// List to manage algorithms with thread-safe operations
typedef struct {
    Algorithm **algorithms;
    size_t count;
    pthread_mutex_t lock;
} AlgorithmList;

AlgorithmList algorithm_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function declarations for loading and unloading algorithms
int load_algorithm(const char *path);
void unload_algorithm(const char *name);
void list_algorithms();
void process_data_with_algorithm(Algorithm *alg, const unsigned char *data, size_t data_size);

// Dynamic loading of algorithm from shared library
int load_algorithm(const char *path) {
    void *handle;
    Algorithm *alg;

    handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading %s: %s\n", path, dlerror());
        return -1;
    }

    alg = malloc(sizeof(Algorithm));
    if (!alg) {
        dlclose(handle);
        return -1;
    }

    // Load functions from the shared library
    alg->init = dlsym(handle, "init");
    alg->cleanup = dlsym(handle, "cleanup");
    alg->process = dlsym(handle, "process");

    if (!alg->init || !alg->cleanup || !alg->process) {
        fprintf(stderr, "Error loading symbols for %s: %s\n", path, dlerror());
        free(alg);
        dlclose(handle);
        return -1;
    }

    // Add algorithm to the list
    pthread_mutex_lock(&algorithm_list.lock);
    algorithm_list.count++;
    algorithm_list.algorithms = realloc(algorithm_list.algorithms, sizeof(Algorithm *) * algorithm_list.count);
    algorithm_list.algorithms[algorithm_list.count - 1] = alg;
    pthread_mutex_unlock(&algorithm_list.lock);

    return 0;
}

// Unload an algorithm from the list
void unload_algorithm(const char *name) {
    size_t i;

    pthread_mutex_lock(&algorithm_list.lock);
    for (i = 0; i < algorithm_list.count; ++i) {
        if (strcmp(algorithm_list.algorithms[i]->name, name) == 0) {
            free(algorithm_list.algorithms[i]);
            // Shift remaining elements
            memmove(&algorithm_list.algorithms[i], &algorithm_list.algorithms[i + 1],
                    sizeof(Algorithm *) * (algorithm_list.count - i - 1));
            algorithm_list.count--;
            break;
        }
    }
    pthread_mutex_unlock(&algorithm_list.lock);
}

// List all loaded algorithms
void list_algorithms() {
    size_t i;

    pthread_mutex_lock(&algorithm_list.lock);
    for (i = 0; i < algorithm_list.count; ++i) {
        printf("Algorithm %zu: %s\n", i + 1, algorithm_list.algorithms[i]->name);
    }
    pthread_mutex_unlock(&algorithm_list.lock);
}

// Process data using a specified algorithm
void process_data_with_algorithm(Algorithm *alg, const unsigned char *data, size_t data_size) {
    if (alg && alg->process) {
        unsigned char output[1024];
        int result = alg->process(data, data_size, output);
        if (result == 0) {
            printf("Processing successful\n");
        } else {
            fprintf(stderr, "Error processing data: %d\n", result);
        }
    } else {
        fprintf(stderr, "Invalid algorithm provided\n");
    }
}

// Main function to demonstrate functionality
int main() {
    // Load an example algorithm (replace with actual path)
    load_algorithm("./example_algorithm.so");

    // List available algorithms
    list_algorithms();

    // Example data processing
    unsigned char data[] = {0x01, 0x02, 0x03};
    size_t data_size = sizeof(data);

    if (algorithm_list.count > 0) {
        process_data_with_algorithm(algorithm_list.algorithms[0], data, data_size);
    }

    // Clean up
    unload_algorithm("ExampleAlgorithm");

    return 0;
}
```

### Key Points:
- **Dynamic Loading**: Uses `dlopen` and `dlsym` for loading shared libraries at runtime.
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread-safe operations on the algorithm list.
- **Resource Management**: Handles dynamic memory allocation for algorithms, ensuring proper cleanup with `free`.
- **Error Handling**: Provides error messages for failed loads and missing symbols.
- **Scalability**: Supports adding and removing algorithms dynamically.

This code provides a foundational structure that can be extended to include performance monitoring, adaptive resource management, and integration with existing systems as per the requirements.']

