```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MULTIPLIER 2

typedef struct record {
    short s;
    int i;
    float f;
    struct record *next;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    size_t capacity;
} dynamic_array_t;

typedef struct hash_table_node {
    int key;
    void *value;
    struct hash_table_node *next;
} hash_table_node_t;

typedef struct {
    hash_table_node_t **buckets;
    size_t num_buckets;
    pthread_mutex_t *locks;
} hash_table_t;

// Initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Generate a random short, int and float within specified ranges
short rand_short(short min, short max) {
    return (short)(rand() % ((max - min) + 1) + min);
}

int rand_int(int min, int max) {
    return rand() % ((max - min) + 1) + min;
}

float rand_float(float min, float max) {
    return (min + ((float)rand() / RAND_MAX * (max - min)));
}

// Create a new record with random values
record_t* create_record(short s_range_min, short s_range_max,
                        int i_range_min, int i_range_max,
                        float f_range_min, float f_range_max) {
    record_t *new_record = malloc(sizeof(record_t));
    if (new_record == NULL) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    new_record->s = rand_short(s_range_min, s_range_max);
    new_record->i = rand_int(i_range_min, i_range_max);
    new_record->f = rand_float(f_range_min, f_range_max);
    new_record->next = NULL;

    return new_record;
}

// Initialize dynamic arrays
void init_dynamic_arrays(dynamic_array_t *array, size_t initial_capacity) {
    array->offsets = malloc(initial_capacity * sizeof(long));
    if (array->offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    array->keys = malloc(initial_capacity * sizeof(int));
    if (array->keys == NULL) {
        free(array->offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    array->size = 0;
    array->capacity = initial_capacity;
}

// Resize dynamic arrays
void resize_dynamic_arrays(dynamic_array_t *array) {
    size_t new_capacity = array->capacity * MULTIPLIER;
    long *new_offsets = realloc(array->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(array->keys, new_capacity * sizeof(int));

    if (new_offsets == NULL || new_keys == NULL) {
        perror("Failed to resize arrays");
        free(new_offsets);
        free(new_keys);
        exit(EXIT_FAILURE);
    }

    array->offsets = new_offsets;
    array->keys = new_keys;
    array->capacity = new_capacity;
}

// Add an element to the dynamic arrays
void add_to_dynamic_arrays(dynamic_array_t *array, int key, long constant_value) {
    if (array->size == array->capacity) {
        resize_dynamic_arrays(array);
    }

    array->keys[array->size] = key;
    if (array->size > 0) {
        array->offsets[array->size] = array->offsets[array->size - 1] + key + constant_value;
    } else {
        array->offsets[0] = key + constant_value;
    }

    array->size++;
}

// Initialize hash table
void init_hash_table(hash_table_t *table, size_t num_buckets) {
    table->buckets = calloc(num_buckets, sizeof(hash_table_node_t*));
    if (table->buckets == NULL) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    table->num_buckets = num_buckets;
    table->locks = malloc(num_buckets * sizeof(pthread_mutex_t));

    for (size_t i = 0; i < num_buckets; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
}

// Hash function
unsigned int hash(int key, size_t num_buckets) {
    return key % num_buckets;
}

// Insert into hash table
void insert_hash_table(hash_table_t *table, int key, void *value) {
    unsigned int index = hash(key, table->num_buckets);

    pthread_mutex_lock(&table->locks[index]);

    hash_table_node_t *node = malloc(sizeof(hash_table_node_t));
    if (node == NULL) {
        perror("Failed to allocate memory for hash table node");
        exit(EXIT_FAILURE);
    }

    node->key = key;
    node->value = value;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_unlock(&table->locks[index]);
}

// Free hash table
void free_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->num_buckets; ++i) {
        hash_table_node_t *node = table->buckets[i];

        while (node != NULL) {
            hash_table_node_t *temp = node;
            node = node->next;

            free(temp);
        }
    }

    free(table->buckets);
    for (size_t i = 0; i < table->num_buckets; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table->locks);
}

// Free dynamic arrays
void free_dynamic_arrays(dynamic_array_t *array) {
    free(array->offsets);
    free(array->keys);
}

// Iterator for linked list of records
typedef struct record_iterator {
    record_t *current;
} record_iterator_t;

record_iterator_t* create_record_iterator(record_t *head) {
    record_iterator_t *iter = malloc(sizeof(record_iterator_t));
    if (iter == NULL) {
        perror("Failed to allocate memory for iterator");
        exit(EXIT_FAILURE);
    }

    iter->current = head;
    return iter;
}

void free_record_iterator(record_iterator_t *iter) {
    free(iter);
}

record_t* next_record(record_iterator_t *iter) {
    if (iter == NULL || iter->current == NULL) {
        return NULL;
    }

    record_t *record = iter->current;
    iter->current = record->next;
    return record;
}

// Example usage
int main() {
    init_random();

    dynamic_array_t arrays;
    hash_table_t hashTable;

    init_dynamic_arrays(&arrays, INITIAL_SIZE);
    init_hash_table(&hashTable, 100);

    // Add keys and offsets with a constant value of 10
    for (int i = 0; i < 20; ++i) {
        add_to_dynamic_arrays(&arrays, rand_int(1, 100), 10);
    }

    record_t *head = NULL;
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    // Add records to linked list
    for (int i = 0; i < arrays.size; ++i) {
        pthread_mutex_lock(&list_lock);

        record_t *new_record = create_record(1, 10, 100, 200, 0.0f, 1.0f);
        new_record->next = head;
        head = new_record;

        insert_hash_table(&hashTable, arrays.keys[i], (void*)new_record);

        pthread_mutex_unlock(&list_lock);
    }

    // Iterate over the linked list
    record_iterator_t *iter = create_record_iterator(head);
    record_t *record;
    while ((record = next_record(iter)) != NULL) {
        printf("Record: s=%d, i=%d, f=%.2f\n", record->s, record->i, record->f);
    }

    // Cleanup
    free_record_iterator(iter);
    free_dynamic_arrays(&arrays);
    free_hash_table(&hashTable);

    pthread_mutex_destroy(&list_lock);

    return 0;
}
```

### Key Features:

1. **Dynamic Array Management**: Implements dynamic resizing for `offset` and `key` arrays using a simple multiplier.
2. **Randomized Record Creation**: Random values are generated within specified ranges, ensuring reproducibility by initializing the random number generator once.
3. **Thread-Safe Hash Table**: Utilizes mutexes per bucket to allow concurrent access while preventing race conditions.
4. **Linked List with Iterator**: Provides a basic iterator for traversing the linked list efficiently.
5. **Batch Processing and Atomic Operations**: Supports batch operations through iteration, though explicit atomicity should be ensured by locking mechanisms where necessary.

This code serves as a foundational implementation that can be further optimized based on specific application requirements and performance testing.']

