#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

typedef struct {
    json_object *data;
    pthread_mutex_t lock;
} ConfigManager;

#define CONFIG_LOAD_SUCCESS 0
#define CONFIG_LOAD_ERROR -1

ConfigManager* config_manager_init(const char *source_path) {
    ConfigManager *manager = malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->data = json_object_new_object();
    pthread_mutex_init(&manager->lock, NULL);

    // Load configuration from the external data source
    FILE *file = fopen(source_path, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", source_path);
        free(manager);
        return NULL;
    }

    struct json_object *parsed_json;
    const char *content;
    size_t content_size;

    // Read the entire file into a buffer
    fseek(file, 0, SEEK_END);
    content_size = ftell(file);
    rewind(file);

    content = malloc(content_size + 1);
    if (!content) {
        fclose(file);
        free(manager);
        return NULL;
    }

    fread(content, 1, content_size, file);
    content[content_size] = '\0';
    fclose(file);
    free(content);

    // Parse JSON
    int parse_result = json_tokener_parse_ex(&parsed_json, content, strlen(content), NULL);
    if (parse_result != 0 || !json_object_is_type(parsed_json, json_type_object)) {
        fprintf(stderr, "Invalid JSON format.\n");
        free(manager);
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);
    json_object_object_add(manager->data, parsed_json);
    pthread_mutex_unlock(&manager->lock);

    return manager;
}

int config_manager_set(ConfigManager *manager, const char *key, json_type type, void *value) {
    if (!manager || !key) return CONFIG_LOAD_ERROR;

    pthread_mutex_lock(&manager->lock);
    switch (type) {
        case json_type_string:
            json_object_object_add(manager->data, key, json_object_new_string((char *)value));
            break;
        case json_type_int:
            json_object_object_add(manager->data, key, json_object_new_int(*((int *)value)));
            break;
        case json_type_boolean:
            json_object_object_add(manager->data, key, json_object_new_boolean(*((int *)value)));
            break;
        default:
            pthread_mutex_unlock(&manager->lock);
            return CONFIG_LOAD_ERROR;
    }
    pthread_mutex_unlock(&manager->lock);

    return CONFIG_LOAD_SUCCESS;
}

json_type config_manager_get(ConfigManager *manager, const char *key, void **value) {
    if (!manager || !key) return -1;

    pthread_mutex_lock(&manager->lock);
    struct json_object *obj = json_object_object_get(manager->data, key);

    if (json_object_is_type(obj, json_type_string)) {
        *value = strdup(json_object_get_string(obj));
        pthread_mutex_unlock(&manager->lock);
        return json_type_string;
    } else if (json_object_is_type(obj, json_type_int)) {
        int *int_val = malloc(sizeof(int));
        if (!int_val) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        *int_val = json_object_get_int(obj);
        *value = int_val;
        pthread_mutex_unlock(&manager->lock);
        return json_type_int;
    } else if (json_object_is_type(obj, json_type_boolean)) {
        int *bool_val = malloc(sizeof(int));
        if (!bool_val) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        *bool_val = json_object_get_boolean(obj);
        *value = bool_val;
        pthread_mutex_unlock(&manager->lock);
        return json_type_boolean;
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void config_manager_free(ConfigManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    json_object_put(manager->data);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

This code provides a basic implementation of a flexible configuration manager using JSON for data storage. It includes functions to initialize, set, get, and free the configuration manager while ensuring thread safety with mutex locks. Error handling is also included for invalid JSON formats and memory allocation failures.']

