#include <string.h>
#include <time.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    char ProtocolType[10];
    time_t LastUpdatedTimestamp;
} NetworkFlow;

int processNetworkTrafficAndGenerateReport(
    const char *network_traffic_log,
    const char *output_report_path,
    const char *external_converter_executable,
    size_t max_entries,
    int inactivity_threshold_minutes,
    const char *log_directory) {

    // Function to log messages
    void logMessage(const char *message) {
        FILE *logFile = fopen("network_flow_log.txt", "a");
        if (logFile) {
            time_t now = time(NULL);
            fprintf(logFile, "[%s] %s\n", ctime(&now), message);
            fclose(logFile);
        }
    }

    // Array of NetworkFlow and count
    NetworkFlow *flows = NULL;
    size_t flowCount = 0;

    // Allocate initial memory for flows
    flows = malloc(max_entries * sizeof(NetworkFlow));
    if (!flows) {
        logMessage("Memory allocation failed.");
        return 1;
    }

    // Simulate adding, removing and querying network flows
    void addFlow(const char *sourceIP, const char *destIP, const char *protocol) {
        if (flowCount >= max_entries) {
            // Remove least recently updated flow to make space
            for (size_t i = 0; i < flowCount; ++i) {
                if (flows[i].LastUpdatedTimestamp == 0) { // Assuming uninitialized timestamp is 0
                    logMessage("Removing oldest flow to add new one.");
                    memmove(&flows[i], &flows[i + 1], (--flowCount - i) * sizeof(NetworkFlow));
                    break;
                }
            }
        }

        NetworkFlow newFlow = {
            .LastUpdatedTimestamp = time(NULL)
        };
        strncpy(newFlow.SourceIP, sourceIP, sizeof(newFlow.SourceIP));
        strncpy(newFlow.DestinationIP, destIP, sizeof(newFlow.DestinationIP));
        strncpy(newFlow.ProtocolType, protocol, sizeof(newFlow.ProtocolType));

        flows[flowCount++] = newFlow;
        logMessage("Added a new flow.");
    }

    void removeFlowBySource(const char *sourceIP) {
        for (size_t i = 0; i < flowCount; ++i) {
            if (strcmp(flows[i].SourceIP, sourceIP) == 0) {
                memmove(&flows[i], &flows[i + 1], (--flowCount - i) * sizeof(NetworkFlow));
                logMessage("Removed a flow by Source IP.");
                break;
            }
        }
    }

    size_t queryFlowsByProtocol(const char *protocolType) {
        size_t count = 0;
        for (size_t i = 0; i < flowCount; ++i) {
            if (strcmp(flows[i].ProtocolType, protocolType) == 0) {
                ++count;
            }
        }
        logMessage("Queried flows by Protocol Type.");
        return count;
    }

    void batchDeleteInactiveFlows(int inactivityMinutes) {
        time_t currentTime = time(NULL);
        time_t thresholdTime = currentTime - (inactivityMinutes * 60);

        for (size_t i = 0; i < flowCount;) {
            if (flows[i].LastUpdatedTimestamp <= thresholdTime) {
                memmove(&flows[i], &flows[i + 1], (--flowCount - i) * sizeof(NetworkFlow));
                logMessage("Batch deleted inactive flow.");
            } else {
                ++i;
            }
        }
    }

    // Example operations
    addFlow("192.168.1.1", "10.0.0.1", "TCP");
    removeFlowBySource("192.168.1.1");
    size_t tcpFlows = queryFlowsByProtocol("TCP");
    batchDeleteInactiveFlows(inactivity_threshold_minutes);

    // Execute external converter
    char command[512];
    snprintf(command, sizeof(command), "%s %s %s", external_converter_executable, network_traffic_log, output_report_path);
    int result = system(command);

    // Free allocated memory
    free(flows);

    if (result == 0) {
        logMessage("Conversion successful.");
        return 0;
    } else {
        logMessage("Conversion failed.");
        return 1;
    }
}
