#define MAX_RESOURCES 1024

typedef struct {
    char **resources;
    size_t count;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle *create_resource_bundle() {
    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    bundle->resources = NULL;
    bundle->count = 0;
    pthread_mutex_init(&bundle->lock, NULL);
    return bundle;
}

int load_resources(ResourceBundle *bundle, const char *filepath) {
    FILE *file = fopen(filepath, "r");
    if (!file) return -1;

    pthread_mutex_lock(&bundle->lock);

    // Load resources and validate format
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Validate and parse line
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[--len] = '\0';

        pthread_mutex_lock(&bundle->lock);
        if (bundle->count >= bundle->resources) {
            size_t new_size = bundle->count ? bundle->count * 2 : 16;
            char **new_resources = realloc(bundle->resources, new_size * sizeof(char *));
            if (!new_resources) {
                pthread_mutex_unlock(&bundle->lock);
                fclose(file);
                return -2; // Memory allocation failure
            }
            bundle->resources = new_resources;
        }

        bundle->resources[bundle->count++] = strdup(line);
        pthread_mutex_unlock(&bundle->lock);
    }

    pthread_mutex_unlock(&bundle->lock);
    fclose(file);
    return 0;
}

int get_resource_count(ResourceBundle *bundle) {
    pthread_mutex_lock(&bundle->lock);
    int count = bundle->count;
    pthread_mutex_unlock(&bundle->lock);
    return count;
}

void destroy_resource_bundle(ResourceBundle *bundle) {
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->resources[i]);
    }
    free(bundle->resources);
    pthread_mutex_unlock(&bundle->lock);

    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

