}

// Main function to allocate and initialize arrays
array_of_records* create_record_array(size_t offset_count, size_t key_count, unsigned int seed) {
    pthread_mutex_lock(&lock);

    // Initialize random number generator
    init_random(seed);

    // Validate input counts
    if (offset_count <= 0 || key_count <= 0) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate memory for offset array
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    if (!offsets) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Populate keys with unique values
    for (size_t i = 0; i < key_count; ++i) {
        keys[i] = (int)i;
    }

    // Allocate memory for records array
    record* records_array = (record*)malloc(offset_count * sizeof(record));
    if (!records_array) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize records with random values and unique keys
    for (size_t i = 0; i < offset_count; ++i) {
        records_array[i].value = (int*)malloc(sizeof(int));
        if (!records_array[i].value) {
            for (size_t j = 0; j < i; ++j) {
                free(records_array[j].value);
            }
            free(records_array);
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        *(records_array[i].value) = get_random_int();

        // Assign a unique key index
        records_array[i].key_index = keys[rand() % key_count];
    }

    // Create and populate the array_of_records structure
    array_of_records* result = (array_of_records*)malloc(sizeof(array_of_records));
    if (!result) {
        for (size_t i = 0; i < offset_count; ++i) {
            free(records_array[i].value);
        }
        free(records_array);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    result->records = records_array;
    result->count = offset_count;

    // Unlock mutex and return the result
    pthread_mutex_unlock(&lock);
    return result;
}
```

This function dynamically allocates memory for the arrays, initializes them according to the specified requirements, and ensures thread safety using a mutex. It also handles input validation and cleans up in case of allocation failures.']

