MediaMetaData* addOrUpdateEntry(MediaMetaData** mediaArray, size_t* arraySize, const char* filePath, MediaType mediaType, const char* resolution) {
    // Search for existing entry and update or create a new one
    MediaMetaData* entry = NULL;
    for (size_t i = 0; i < *arraySize; ++i) {
        if (strcmp((*mediaArray)[i].MediaFilePath, filePath) == 0) {
            entry = &(*mediaArray)[i];
            break;
        }
    }

    if (!entry) {
        // Allocate new space for the media array
        *mediaArray = realloc(*mediaArray, (*arraySize + 1) * sizeof(MediaMetaData));
        entry = &(*mediaArray)[*arraySize];
        ++(*arraySize);
    }

    entry->MediaFilePath = strdup(filePath);
    entry->MediaType = mediaType;
    entry->Resolution = resolution ? strdup(resolution) : NULL;
    entry->LastProcessedTime = time(NULL);
    entry->ProcessingStatus = 0;

    return entry;
}

void removeEntry(MediaMetaData** mediaArray, size_t* arraySize, const char* filePath) {
    // Remove an entry based on the file path
    for (size_t i = 0; i < *arraySize; ++i) {
        if (strcmp((*mediaArray)[i].MediaFilePath, filePath) == 0) {
            free((*mediaArray)[i].MediaFilePath);
            free((*mediaArray)[i].Resolution);

            memmove(&(*mediaArray)[i], &(*mediaArray)[i + 1], (*arraySize - i - 1) * sizeof(MediaMetaData));
            --(*arraySize);
            *mediaArray = realloc(*mediaArray, *arraySize * sizeof(MediaMetaData));

            break;
        }
    }
}

size_t queryFilesProcessed(const MediaMetaData* mediaArray, size_t arraySize, const char* resolution, time_t startTime, time_t endTime) {
    // Query the number of processed files within a specific resolution and time range
    size_t count = 0;

    for (size_t i = 0; i < arraySize; ++i) {
        if (
            mediaArray[i].ProcessingStatus == 2 &&
            strcmp(mediaArray[i].Resolution, resolution) == 0 &&
            mediaArray[i].LastProcessedTime >= startTime &&
            mediaArray[i].LastProcessedTime <= endTime
        ) {
            ++count;
        }
    }

    return count;
}

int manageMediaProcessingAndLogStatistics(
    const char* media_files[], 
    size_t num_media_files, 
    const char* output_directory,
    const char* processing_tool_path,
    const char* log_file_path,
    int max_workers,
    size_t cache_capacity,
    unsigned int timeout_seconds,
    const char** supported_extensions,
    size_t extensions_count
) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    MediaMetaData* mediaArray = NULL;
    size_t arraySize = 0;

    LRUCache* cache = createLRU(cache_capacity);

    // Process each media file
    for (size_t i = 0; i < num_media_files; ++i) {
        const char* filePath = media_files[i];

        // Check if the extension is supported
        int isSupported = 0;
        for (size_t j = 0; j < extensions_count; ++j) {
            size_t len = strlen(supported_extensions[j]);
            if (strstr(filePath + strlen(filePath) - len, supported_extensions[j]) == filePath + strlen(filePath) - len) {
                isSupported = 1;
                break;
            }
        }

        if (!isSupported) continue;

        // Check cache
        MediaMetaData metaData = { .MediaFilePath = strdup(filePath), .Resolution = NULL, .MediaType = IMAGE };
        int cacheFound = LRUGet(cache, filePath, &metaData);

        if (!cacheFound) {
            pthread_mutex_lock(&lock);

            addOrUpdateEntry(&mediaArray, &arraySize, filePath, IMAGE, "1920x1080");

            // Process the media file
            char command[1024];
            snprintf(command, sizeof(command), "%s %s -o %s", processing_tool_path, filePath, output_directory);

            int retries = 3;
            while (retries > 0) {
                FILE* pipe = popen(command, "r");
                if (!pipe) break;

                // Wait for the process to finish
                pclose(pipe);

                // Assume success for this example
                addOrUpdateEntry(&mediaArray, &arraySize, filePath, IMAGE, "1920x1080")->ProcessingStatus = 2;

                FILE* logFile = fopen(log_file_path, "a");
                if (logFile) {
                    fprintf(logFile, "Successfully processed: %s\n", filePath);
                    fclose(logFile);
                }

                break; // Success, exit retry loop

            } else {
                FILE* logFile = fopen(log_file_path, "a");
                if (logFile) {
                    fprintf(logFile, "Failed to process after retries: %s\n", filePath);
                    fclose(logFile);
                }

                return 1;
            }

            pthread_mutex_unlock(&lock);

            // Add to cache
            LRUPut(cache, metaData);
        } else {
            free(metaData.MediaFilePath); 
        }
    }

    // Batch delete unprocessed files
    time_t currentTime = time(NULL);
    for (size_t i = 0; i < arraySize; ++i) {
        if (
            mediaArray[i].ProcessingStatus == 0 &&
            difftime(currentTime, mediaArray[i].LastProcessedTime) > timeout_seconds
        ) {
            removeEntry(&mediaArray, &arraySize, mediaArray[i].MediaFilePath);
        }
    }

    // Clean up
    destroyLRU(cache);

    pthread_mutex_destroy(&lock);

    for (size_t i = 0; i < arraySize; ++i) {
        free(mediaArray[i].MediaFilePath);
        free(mediaArray[i].Resolution);
    }
    free(mediaArray);

    return 0;
}

void validateResolutionRange(const char* jsonString, MediaMetaData metaData, const char* log_file_path) {
    // Placeholder for JSON parsing logic

    int minRes = 640;
    int maxRes = 1920;

    if (metaData.Resolution != NULL) {
        int width, height;
        sscanf(metaData.Resolution, "%dx%d", &width, &height);

        if ((width < minRes || width > maxRes) && (height < minRes || height > maxRes)) {
            FILE* logFile = fopen(log_file_path, "a");
            if (logFile) {
                fprintf(
                    logFile,
                    "Warning: Media file %s with resolution %s is out of range.\n",
                    metaData.MediaFilePath, 
                    metaData.Resolution
                );
                fclose(logFile);
            }
        }
    }
}
