// Function to initialize arrays and records, thread-safe with concurrency control
void init_data(long num_offsets, int key_range, int record_count) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Allocate memory for offset values and keys
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_offsets * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        log_message("Memory allocation failed.");
        pthread_mutex_destroy(&mutex);
        free(offsets); // Safe to call with NULL
        free(keys);    // Safe to call with NULL
        return;
    }

    log_message("Allocated memory for offsets and keys.");

    record *records = malloc(record_count * sizeof(record));
    if (records == NULL) {
        log_message("Memory allocation failed for records.");
        pthread_mutex_lock(&mutex);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        pthread_mutex_destroy(&mutex);
        return;
    }

    log_message("Allocated memory for records.");

    // Initialize offset values and keys
    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = i; // Example initialization, can be customized
        keys[i] = rand() % key_range;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize records with random values within a specified range
    pthread_mutex_lock(&mutex);
    for (int j = 0; j < record_count; ++j) {
        records[j].value = rand() % key_range;
    }
    pthread_mutex_unlock(&mutex);

    log_message("Initialized offset values, keys, and records.");

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);

    log_message("Freed allocated memory.");

    pthread_mutex_destroy(&mutex);
}
