#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>

// Define a record structure
typedef struct {
    int value;
} Record;

// Logging function prototype
void log_message(const char *message);

// Function to load the resource bundle
int load_resource_bundle(const char *directory, const char *extension, Record ***bundle, size_t *num_items) {
    DIR *dir = opendir(directory);
    if (!dir) {
        log_message("Failed to open directory");
        return -1;
    }

    struct dirent *entry;
    int count = 0;

    // Count files with the specific extension
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
        struct stat path_stat;

        if (stat(path, &path_stat) != 0) {
            log_message("Failed to get file status");
            closedir(dir);
            return -1;
        }

        if (S_ISREG(path_stat.st_mode)) {
            const char *dot = strrchr(entry->d_name, '.');
            if (dot && strcmp(dot, extension) == 0)
                count++;
        }
    }

    closedir(dir);

    // Allocate memory for the bundle
    *bundle = malloc(count * sizeof(Record *));
    if (!*bundle) {
        log_message("Memory allocation failed");
        return -1;
    }

    // Re-open directory to populate records
    dir = opendir(directory);
    if (!dir) {
        free(*bundle);
        log_message("Failed to open directory");
        return -1;
    }

    int index = 0;
    while ((entry = readdir(dir)) != NULL && index < count) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
        struct stat path_stat;

        if (stat(path, &path_stat) != 0) {
            log_message("Failed to get file status");
            closedir(dir);
            free(*bundle);
            return -1;
        }

        const char *dot = strrchr(entry->d_name, '.');
        if (S_ISREG(path_stat.st_mode) && dot && strcmp(dot, extension) == 0) {
            (*bundle)[index] = malloc(sizeof(Record));
            if (!(*bundle)[index]) {
                log_message("Memory allocation failed");
                for (int i = 0; i < index; i++) free((*bundle)[i]);
                closedir(dir);
                free(*bundle);
                return -1;
            }
            (*bundle)[index]->value = rand() % 100 + 1; // Random int between 1 and 100
            index++;
        }
    }

    closedir(dir);

    *num_items = count;
    return 0;
}

// Seed the random number generator for reproducibility
void seed_random_number_generator(unsigned int seed) {
    srand(seed);
}

// Logging function implementation
void log_message(const char *message) {
    fprintf(stderr, "%s\n", message);
}
