#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

// Enum for preference type options
typedef enum {
    PREFERENCE_TYPE_INT,
    PREFERENCE_TYPE_ENUM,
    PREFERENCE_TYPE_TIMESTAMP
} PreferenceType;

// Structure to store preference settings
typedef struct {
    char *name;
    int default_value;
    bool active;
    int priority_level;
    char *description;
    pthread_rwlock_t lock;
} Preference;

// Structure to manage file metadata
typedef struct {
    char *filename;
    off_t size;
    time_t last_modified;
    int status_flags;
    pthread_rwlock_t lock;
} MetadataEntry;

// Hash table for preferences
#define TABLE_SIZE 1024
Preference **preference_table[TABLE_SIZE];
MetadataEntry **metadata_table[TABLE_SIZE];

// Function prototypes
unsigned int hash(const char *str);
void initialize_preference(Preference **entry, const char *name, int default_value, PreferenceType type, bool active, int priority, const char *description);
void initialize_metadata(MetadataEntry **entry, const char *filename, off_t size, time_t last_modified, int status_flags);
void cleanup();

// Hash function
unsigned int hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;

    return hash % TABLE_SIZE;
}

// Initialize preference entry with random values
void initialize_preference(Preference **entry, const char *name, int default_value, PreferenceType type, bool active, int priority, const char *description) {
    pthread_rwlock_init(&((*entry)->lock), NULL);

    (*entry)->name = strdup(name);
    (*entry)->default_value = default_value;
    (*entry)->active = active;
    (*entry)->priority_level = priority;
    (*entry)->description = strdup(description);
}

// Initialize metadata entry
void initialize_metadata(MetadataEntry **entry, const char *filename, off_t size, time_t last_modified, int status_flags) {
    pthread_rwlock_init(&((*entry)->lock), NULL);

    (*entry)->filename = strdup(filename);
    (*entry)->size = size;
    (*entry)->last_modified = last_modified;
    (*entry)->status_flags = status_flags;
}

// Cleanup function to free allocated memory
void cleanup() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        if (preference_table[i]) {
            for (Preference *p = preference_table[i]; p != NULL;) {
                Preference *next = *(Preference **)p;
                pthread_rwlock_destroy(&p->lock);
                free(p->name);
                free(p->description);
                free(p);
                p = next;
            }
        }

        if (metadata_table[i]) {
            for (MetadataEntry *m = metadata_table[i]; m != NULL;) {
                MetadataEntry *next = *(MetadataEntry **)m;
                pthread_rwlock_destroy(&m->lock);
                free(m->filename);
                free(m);
                m = next;
            }
        }
    }

    // Free tables
    free(preference_table);
    free(metadata_table);
}

// Main function to initialize preferences and metadata
void init_memory_management() {
    preference_table = calloc(TABLE_SIZE, sizeof(Preference *));
    metadata_table = calloc(TABLE_SIZE, sizeof(MetadataEntry *));

    srand(time(NULL) ^ getpid() ^ getloadavg(NULL, 3)[0]); // Seed with system time, process ID, and load average

    // Example of initializing preferences
    for (int i = 0; i < 10; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "pref_%d", i);

        Preference *preference = malloc(sizeof(Preference));
        initialize_preference(&preference, name, rand() % 100, PREFERENCE_TYPE_INT, true, rand() % 10, "Sample preference");

        unsigned int index = hash(preference->name);
        pthread_rwlock_wrlock(&preference_table[index]->lock);

        *(Preference **)preference_table[index] = (Preference *)malloc(sizeof(Preference *));
        *preference_table[index] = preference;

        pthread_rwlock_unlock(&preference_table[index]->lock);
    }

    // Example of initializing metadata
    for (int i = 0; i < 5; ++i) {
        char filename[30];
        snprintf(filename, sizeof(filename), "file_%d", i);

        MetadataEntry *metadata = malloc(sizeof(MetadataEntry));
        initialize_metadata(&metadata, filename, rand() % 1000000, time(NULL), rand() % 16);

        unsigned int index = hash(metadata->filename);
        pthread_rwlock_wrlock(&metadata_table[index]->lock);

        *(MetadataEntry **)metadata_table[index] = (MetadataEntry *)malloc(sizeof(MetadataEntry *));
        *metadata_table[index] = metadata;

        pthread_rwlock_unlock(&metadata_table[index]->lock);
    }

    // Note: In a real application, you should handle cleanup when done
}

int main() {
    init_memory_management();

    // Simulate some operations

    cleanup();  // Ensure to clean up resources

    return 0;
}
```

This C code provides an implementation for dynamically managing memory and initializing data structures that store user preferences and file metadata. It uses a hash table with separate chaining for collision resolution, initialized through function calls that allocate memory for each entry. Each preference setting has an active flag, priority level, and description, while metadata entries hold filenames, sizes, timestamps, and status flags.

The code includes thread-safe locking mechanisms (read-write locks) to ensure concurrent access safety. A hash function is used to distribute keys efficiently across the table. Memory management and cleanup are handled carefully to avoid leaks. The initialization of preferences and metadata uses random values for demonstration purposes.']

