#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_OPTION_NAME_LENGTH 20
#define MAX_OPTIONS 100

typedef enum { OPT_TYPE_A, OPT_TYPE_B } option_type;

typedef struct {
    char* name;
    int default_value;
    option_type type;
    time_t timestamp;
} config_setting;

typedef struct {
    bool enabled;
    int priority;
    char* description;
    config_setting setting;
} config_entry;

typedef struct {
    int key;
    long offset;
    int value;
} record;

typedef struct Node {
    config_entry entry;
    struct Node* next;
} config_node;

typedef struct {
    config_node** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} config_store;

static const char predefined_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
static uint32_t seed = 0;

void initialize_seed() {
    time_t current_time;
    time(&current_time);
    seed ^= (uint32_t)current_time << 16;
}

char* generate_option_name(size_t length) {
    char* name = malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        name[i] = predefined_chars[rand_r(&seed) % (sizeof(predefined_chars) - 1)];
    }
    name[length] = '\0';
    return name;
}

config_entry* create_config_entry(const char* description, int priority, bool enabled, option_type type) {
    config_entry* entry = malloc(sizeof(config_entry));
    if (!entry) {
        perror("Failed to allocate memory for config_entry");
        exit(EXIT_FAILURE);
    }
    entry->setting.name = generate_option_name(rand_r(&seed) % MAX_OPTION_NAME_LENGTH + 1);
    entry->setting.default_value = rand_r(&seed) % 100;
    entry->setting.type = type;
    entry->setting.timestamp = time(NULL);
    entry->enabled = enabled;
    entry->priority = priority;
    entry->description = strdup(description);
    return entry;
}

config_store* initialize_config_store(size_t capacity) {
    config_store* store = malloc(sizeof(config_store));
    if (!store) {
        perror("Failed to allocate memory for config_store");
        exit(EXIT_FAILURE);
    }
    store->buckets = calloc(capacity, sizeof(config_node*));
    if (!store->buckets) {
        free(store);
        perror("Failed to allocate memory for buckets");
        exit(EXIT_FAILURE);
    }
    store->capacity = capacity;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void add_config_entry(config_store* store, config_entry* entry) {
    size_t index = hash_function(entry->setting.name, store->capacity);
    pthread_mutex_lock(&store->lock);
    config_node** ptr = &store->buckets[index];
    while (*ptr) {
        ptr = &(*ptr)->next;
    }
    *ptr = malloc(sizeof(config_node));
    if (!*ptr) {
        perror("Failed to allocate memory for config_node");
        exit(EXIT_FAILURE);
    }
    (*ptr)->entry = *entry;
    (*ptr)->next = NULL;
    pthread_mutex_unlock(&store->lock);
}

size_t hash_function(const char* str, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

void free_config_store(config_store* store) {
    for (size_t i = 0; i < store->capacity; ++i) {
        config_node* node = store->buckets[i];
        while (node) {
            config_node* next = node->next;
            free(node->entry.setting.name);
            free(node->entry.description);
            free(node);
            node = next;
        }
    }
    free(store->buckets);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

int main() {
    initialize_seed();

    config_store* store = initialize_config_store(10);

    // Example of adding entries
    for (int i = 0; i < 5; ++i) {
        char desc[50];
        snprintf(desc, sizeof(desc), "Description %d", i);
        add_config_entry(store, create_config_entry(desc, rand_r(&seed) % 10 + 1, true, OPT_TYPE_A));
    }

    // Cleanup
    free_config_store(store);

    return 0;
}
