using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using UnityEngine;

public class TrafficFlowManager : MonoBehaviour
{
    private readonly ConcurrentDictionary<string, List<TrafficFlow>> trafficFlows = new();
    private static readonly object logLock = new();

    public void AddTrafficFlow(TrafficFlow flow)
    {
        var key = $"{flow.SourceIP}_{flow.ProtocolType}";
        trafficFlows.AddOrUpdate(key,
            k => new List<TrafficFlow> { flow },
            (k, existing) =>
            {
                lock (existing) // Ensure thread safety
                {
                    existing.Add(flow);
                }
                return existing;
            });
    }

    public bool RemoveTrafficFlow(TrafficFlow flow)
    {
        var key = $"{flow.SourceIP}_{flow.ProtocolType}";
        if (!trafficFlows.TryGetValue(key, out var flows)) return false;

        lock (flows) // Ensure thread safety
        {
            return flows.Remove(flow);
        }
    }

    public List<TrafficFlow> GetTrafficFlowsBySourceIp(string sourceIp)
    {
        return trafficFlows.Values.SelectMany(list => list.Where(f => f.SourceIP == sourceIp)).ToList();
    }

    public async Task FetchAndUpdateTrafficDataAsync(string apiUrl, string token)
    {
        using var client = new HttpClient();
        client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

        try
        {
            var response = await client.GetStringAsync(apiUrl);
            var trafficDataList = JsonSerializer.Deserialize<List<TrafficFlow>>(response);

            foreach (var flow in trafficDataList)
                AddTrafficFlow(flow);
        }
        catch (Exception ex)
        {
            Log($"Error fetching data: {ex.Message}");
        }
    }

    public void OverrideToString()
    {
        Console.WriteLine(string.Join(Environment.NewLine, GetTrafficFlowsBySourceIp("Any")));
    }

    private static void Log(string message)
    {
        lock (logLock)
        {
            Debug.Log(message); // Use Unity's logging system
        }
    }

    [Serializable]
    public class TrafficFlow
    {
        public string SourceIP { get; set; }
        public string DestinationIP { get; set; }
        public string ProtocolType { get; set; }

        public override string ToString()
        {
            return $"Source: {SourceIP}, Destination: {DestinationIP}, Protocol: {ProtocolType}";
        }
    }

    // Example unit test method
    public void RunUnitTests()
    {
        AddTrafficFlow(new TrafficFlow { SourceIP = "192.168.1.1", DestinationIP = "10.0.0.1", ProtocolType = "TCP" });
        var flows = GetTrafficFlowsBySourceIp("192.168.1.1");
        Debug.Assert(flows.Count == 1);
    }

    // Example performance benchmark method
    public void RunPerformanceBenchmarks()
    {
        for (int i = 0; i < 100000; i++)
            AddTrafficFlow(new TrafficFlow { SourceIP = $"192.168.1.{i}", DestinationIP = "10.0.0.1", ProtocolType = "TCP" });

        var sw = System.Diagnostics.Stopwatch.StartNew();
        for (int i = 0; i < 100000; i++)
            GetTrafficFlowsBySourceIp($"192.168.1.{i}");
        sw.Stop();

        Log($"Performance benchmark: {sw.ElapsedMilliseconds} ms");
    }
}
