#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    long timestamp;
    int event_type;
    char *event_details;
} Entry;

typedef struct LogNode {
    Entry data;
    struct LogNode *next;
} LogNode;

LogNode* create_entry(long timestamp, int event_type, const char *default_message) {
    if (default_message == NULL) return NULL;

    Entry *entry = malloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    entry->event_type = event_type;
    entry->event_details = strdup(default_message);

    if (!entry->event_details) {
        free(entry);
        return NULL;
    }

    LogNode *node = malloc(sizeof(LogNode));
    if (!node) {
        free(entry->event_details);
        free(entry);
        return NULL;
    }

    node->data = *entry;
    node->next = NULL;

    return node;
}

void update_event_details(LogNode *log_node, const char *new_message) {
    if (log_node && new_message) {
        free(log_node->data.event_details);
        log_node->data.event_details = strdup(new_message);

        if (!log_node->data.event_details) {
            // Handle allocation failure by setting to static message
            log_node->data.event_details = strdup("Error: Failed to update event details");
        }
    }
}

LogNode* create_log(int num_entries, long start_epoch, const char *default_message) {
    if (num_entries <= 0 || default_message == NULL) return NULL;

    LogNode *head = NULL;
    LogNode **tail_ptr = &head;

    for (int i = 0; i < num_entries; ++i) {
        LogNode *new_node = create_entry(start_epoch + i, rand() % 100, default_message);
        if (!new_node) break;

        *tail_ptr = new_node;
        tail_ptr = &new_node->next;
    }

    return head;
}

void clear_log(LogNode **log_head) {
    LogNode *current = *log_head;
    while (current) {
        LogNode *next_node = current->next;
        free(current->data.event_details);
        free(current);
        current = next_node;
    }
    *log_head = NULL;
}

void print_log(LogNode *log_head) {
