#include <time.h>

typedef struct {
    int value;
    double number;
    char *text;
} record;

#define INITIAL_RECORD_SIZE 10
#define TEXT_MAX_LENGTH 256

// Logging mechanism
static int logging_enabled = 1; // Set to 0 in production for performance optimization

void log_operation(const char* operation, const char* message) {
    if (logging_enabled) {
        time_t now;
        time(&now);
        printf("[%s] %s: %s\n", ctime(&now), operation, message);
    }
}

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *manage_records(void *arg);

int main() {
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, manage_records, (void *)(intptr_t)i);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void *manage_records(void *arg) {
    int thread_id = (intptr_t)arg;

    pthread_mutex_lock(&lock);

    size_t record_size = INITIAL_RECORD_SIZE;
    long *offsets = malloc(record_size * sizeof(long));
    if (!offsets) {
        log_operation("ERROR", "Failed to allocate memory for offsets.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int *keys = malloc(record_size * sizeof(int));
    if (!keys) {
        log_operation("ERROR", "Failed to allocate memory for keys.");
        free(offsets);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    record *records = malloc(record_size * sizeof(record));
    if (!records) {
        log_operation("ERROR", "Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    log_operation("INFO", "Memory allocated successfully.");

    // Initialize arrays
    for (size_t i = 0; i < record_size; ++i) {
        offsets[i] = i * 10L;
        keys[i] = i;

        records[i].value = i;
        records[i].number = i + 0.5;

        char text[TEXT_MAX_LENGTH];
        snprintf(text, sizeof(text), "Text data %d", i);
        records[i].text = strdup(text); // Allocate and duplicate string
        if (!records[i].text) {
            log_operation("ERROR", "Failed to allocate memory for record text.");
            break;
        }
    }

    log_operation("INFO", "Arrays initialized successfully.");

    // Free resources
    for (size_t i = 0; i < record_size; ++i) {
        free(records[i].text);
    }

    free(offsets);
    free(keys);
    free(records);

    log_operation("INFO", "Memory deallocated successfully.");

    pthread_mutex_unlock(&lock);
    return NULL;
}
```

