#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 5
#define GROWTH_FACTOR 1.5

typedef enum {
    STATUS_A,
    STATUS_B,
    // Add more statuses as needed
} Status;

typedef enum {
    PRIORITY_LOW,
    PRIORITY_MEDIUM,
    PRIORITY_HIGH,
    // Add more priorities as needed
} Priority;

typedef struct Record {
    short field_short;
    int field_int;
    float field_float;
    char status_indicator;
    Priority priority_level;
    struct Record *next;
} Record;

typedef struct {
    long *offsets;
    size_t offset_size;

    int *keys;
    size_t key_size;

    Record *records_head;
    pthread_mutex_t records_mutex;

    int *priorities;
    size_t priority_size;
} DataStructure;

DataStructure* initialize_data_structure() {
    DataStructure *ds = (DataStructure*) malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = (long*) malloc(INITIAL_SIZE * sizeof(long));
    ds->keys = (int*) malloc(INITIAL_SIZE * sizeof(int));
    ds->priorities = (int*) malloc(INITIAL_SIZE * sizeof(int));

    ds->offset_size = INITIAL_SIZE;
    ds->key_size = INITIAL_SIZE;
    ds->priority_size = INITIAL_SIZE;

    pthread_mutex_init(&ds->records_mutex, NULL);
    ds->records_head = NULL;

    return ds;
}

void resize_array(DataStructure *ds, void **array, size_t *current_size, size_t element_size) {
    size_t new_size = (size_t)(*current_size * GROWTH_FACTOR);
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) return;

    *array = new_array;
    *current_size = new_size;
}

void initialize_arrays(DataStructure *ds, int key_range_start, int key_range_end) {
    for (size_t i = 0; i < ds->key_size; ++i) {
        ds->keys[i] = key_range_start + (int)((double)i / ds->key_size * (key_range_end - key_range_start));

        if (i > 0) {
            ds->offsets[i] = ds->offsets[i-1] + ds->keys[i];
        } else {
            ds->offsets[i] = ds->keys[i]; // Base offset
        }
    }

    for (size_t i = 0; i < ds->priority_size; ++i) {
        ds->priorities[i] = rand() % 3; // Random priority between 0 and 2
    }
}

Record* create_record(short short_val, int int_val, float float_val, char status, Priority priority) {
    Record *new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->field_short = short_val;
    new_record->field_int = int_val;
    new_record->field_float = float_val;
    new_record->status_indicator = status;
    new_record->priority_level = priority;
    new_record->next = NULL;

    return new_record;
}

void add_record(DataStructure *ds, Record *new_record) {
    pthread_mutex_lock(&ds->records_mutex);

    if (!ds->records_head) {
        ds->records_head = new_record;
    } else {
        Record *current = ds->records_head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_record;
    }

    pthread_mutex_unlock(&ds->records_mutex);
}

void iterate_records(DataStructure *ds, void (*callback)(Record*)) {
    pthread_mutex_lock(&ds->records_mutex);

    Record *current = ds->records_head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&ds->records_mutex);
}

void free_data_structure(DataStructure **ds_ptr) {
    if (!*ds_ptr) return;

    DataStructure *ds = *ds_ptr;

    Record *current, *tmp;
    pthread_mutex_lock(&ds->records_mutex);

    current = ds->records_head;
    while (current) {
        tmp = current;
        current = current->next;
        free(tmp);
    }

    pthread_mutex_unlock(&ds->records_mutex);

    free(ds->offsets);
    free(ds->keys);
    free(ds->priorities);

    pthread_mutex_destroy(&ds->records_mutex);
    free(*ds_ptr);
    *ds_ptr = NULL;
}

// Debugging function for logging memory usage
void log_memory_usage(DataStructure *ds) {
    printf("Offsets size: %zu\n", ds->offset_size * sizeof(long));
    printf("Keys size: %zu\n", ds->key_size * sizeof(int));
    printf("Priorities size: %zu\n", ds->priority_size * sizeof(int));

    Record *current = ds->records_head;
    int record_count = 0;

    while (current) {
        current = current->next;
        ++record_count;
    }

    printf("Number of records: %d\n", record_count);
}

int main() {
    srand(time(NULL));

    DataStructure *ds = initialize_data_structure();
    if (!ds) return EXIT_FAILURE;

    initialize_arrays(ds, 0, 100);

    for (size_t i = 0; i < ds->key_size; ++i) {
        Record *new_record = create_record(
            rand() % 32768, // short value
            rand(),         // int value
            ((float)rand()) / RAND_MAX, // float value
            STATUS_A + (rand() % 2),    // status A or B
            PRIORITY_LOW + (rand() % 3) // priority level
        );

        if (new_record) {
            add_record(ds, new_record);
        }
    }

    iterate_records(ds, [](Record *record) {
        printf("Record: short=%d, int=%d, float=%.2f, status=%c, priority=%d\n",
               record->field_short, record->field_int, record->field_float,
               record->status_indicator, record->priority_level);
    });

    log_memory_usage(ds);

    free_data_structure(&ds);

    return EXIT_SUCCESS;
}
```

