}

// Check if a key is unique within the current keys array
int is_unique_key(int* keys, size_t size, int new_key) {
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] == new_key) return 0;
    }
    return 1;
}

// Free resources allocated by the data manager
