    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->offsets);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_lock(&manager->lock_keys);
    free(manager->keys);
    pthread_mutex_unlock(&manager->lock_keys);

    // Free linked list
