char* decrypt_message(const char* encoded_msg, const unsigned char* key, const unsigned char* iv) {
    if (!encoded_msg || !key || !iv) return NULL;

    unsigned char decoded[BUFFER_SIZE] = {0}; // Define BUFFER_SIZE appropriately
    int decoded_len = base64_decode(decoded, sizeof(decoded), (unsigned char*)encoded_msg);

    DES_cblock des_key[3];
    for (int i = 0; i < 3; ++i) {
        memcpy(des_key[i].bytes, key + i * 8, 8);
    }

    DES_key_schedule ks1, ks2, ks3;
    DES_set_odd_parity(&des_key[0]);
    DES_set_even_parity(&des_key[1]);
    DES_set_odd_parity(&des_key[2]);

    DES_key_sched(des_key[0], &ks1);
    DES_key_sched(des_key[1], &ks2);
    DES_key_sched(des_key[2], &ks3);

    unsigned char decrypted[BUFFER_SIZE] = {0};
    DES_ncbc_decrypt(decoded, decoded_len, &ks1, &ks2, &ks3, des_key, iv, decrypted);

    return strdup((const char*)decrypted);
}

