```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef enum {
    STATUS_A,
    STATUS_B,
    STATUS_C
} Status;

typedef struct Record {
    short s_value;
    int i_value;
    float f_value;
    Status status;
    char metadata[16];
    int key;
    unsigned long offset;
    struct Record* next;
} Record;

// Custom memory allocator context
typedef struct MemoryAllocator {
    size_t block_size;
    void *memory_pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryAllocator;

// Global variables for thread-safety and logging
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
MemoryAllocator* allocator;
size_t record_count = 0;

// Function prototypes
void init_memory_allocator(size_t block_size, size_t pool_size);
void* custom_alloc(size_t size);
void custom_free(void *ptr);
Record* fetch_initial_records(int count);
Record* create_record(int index, int key);
unsigned long compute_metadata_hash(int key, int index);
char* get_status_string(Status status);

// Initialize custom memory allocator
void init_memory_allocator(size_t block_size, size_t pool_size) {
    allocator = malloc(sizeof(MemoryAllocator));
    allocator->block_size = block_size;
    allocator->pool_size = pool_size;
    allocator->memory_pool = malloc(pool_size);
    pthread_mutex_init(&allocator->lock, NULL);
}

// Custom allocation function
void* custom_alloc(size_t size) {
    if (size > allocator->block_size) return NULL; // Simplified for fixed-size blocks

    pthread_mutex_lock(&allocator->lock);

    static void *current_ptr = allocator->memory_pool;
    void *ptr = current_ptr;

    current_ptr += size;
    if ((char*)current_ptr - (char*)allocator->memory_pool > allocator->pool_size) {
        // Compaction or re-allocation logic would go here
        pthread_mutex_unlock(&allocator->lock);
        return NULL; // Pool exhausted
    }

    pthread_mutex_unlock(&allocator->lock);
    return ptr;
}

// Custom free function (noop for fixed block allocation)
void custom_free(void *ptr) {
    // No-op in this simplified example
}

// Fetch initial records from external source
Record* fetch_initial_records(int count) {
    Record* head = NULL, **tail = &head;

    for (int i = 0; i < count; ++i) {
        int key = rand() % 100 - 50; // Range [-50, 49]
        *tail = create_record(i, key);
        tail = &((*tail)->next);
    }

    return head;
}

// Create a new record
Record* create_record(int index, int key) {
    Record* rec = custom_alloc(sizeof(Record));
    if (!rec) return NULL;

    rec->s_value = rand() % 100; // Random short value
    rec->i_value = rand() % 1000; // Random int value
    rec->f_value = (float)(rand() % 10000) / 100.0f; // Random float value

    rec->status = Status(rand() % 3);
    snprintf(rec->metadata, sizeof(rec->metadata), "%lu", compute_metadata_hash(key, index));
    rec->key = key;
    rec->offset = (index > 0) ? ((Record*)rec)->next->offset + key : key;

    rec->next = NULL;
    record_count++;

    return rec;
}

// Compute metadata hash
unsigned long compute_metadata_hash(int key, int index) {
    unsigned long hash = 5381;
    char str[20];
    sprintf(str, "%d_%d", key, index);
    for (char* p = str; *p != '\0'; ++p) {
        hash = ((hash << 5) + hash) + (*p);
    }
    return hash;
}

// Get status string
const char* get_status_string(Status status) {
    switch (status) {
        case STATUS_A: return "STATUS_A";
        case STATUS_B: return "STATUS_B";
        case STATUS_C: return "STATUS_C";
        default: return "UNKNOWN";
    }
}

// Logging function
void log_memory_usage() {
    pthread_rwlock_rdlock(&rwlock);
    printf("Current record count: %zu\n", record_count);
    pthread_rwlock_unlock(&rwlock);
}

// Thread-safe iteration over records using cursor-based approach
Record* iterate_records(void **cursor) {
    pthread_rwlock_rdlock(&rwlock);

    if (*cursor == NULL) *cursor = fetch_initial_records(10); // Initial load

    Record* rec = *cursor;

    while (rec && rec->next != NULL) {
        *cursor = rec->next;
        pthread_rwlock_unlock(&rwlock);
        return rec;
