import java.util.concurrent.*;
import java.util.logging.Logger;
import java.util.HashMap;
import java.util.Map;

public class NetworkConfigManager {
    private static final Logger logger = Logger.getLogger(NetworkConfigManager.class.getName());
    private final ConcurrentMap<String, NetworkConfiguration> configStore;
    private final ExecutorService executorService;

    public NetworkConfigManager(int initialCapacity) {
        this.configStore = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public boolean addConfiguration(NetworkConfiguration config) {
        if (config == null || config.getProtocol() == null || config.getPortNumber() <= 0 || config.getId() == null) {
            return false;
        }
        return configStore.putIfAbsent(config.getId(), config) == null;
    }

    public void updateConfiguration(String id, NetworkConfiguration updatedConfig) {
        configStore.compute(id, (key, existingConfig) -> 
                existingConfig != null ? updatedConfig : null);
    }

    public boolean removeConfiguration(String id) {
        return configStore.remove(id) != null;
    }

    public NetworkConfiguration getConfiguration(String id) {
        return configStore.get(id);
    }

    public void processBatchConfigs(ConcurrentLinkedQueue<NetworkConfiguration> configs) {
        executorService.submit(() -> {
            try {
                int batchSize = 1000; // Adjust based on performance
                List<NetworkConfiguration> batch;

                while (!configs.isEmpty()) {
                    batch = new ArrayList<>();
                    for (int i = 0; i < batchSize && !configs.isEmpty(); i++) {
                        batch.add(configs.poll());
                    }

                    for (NetworkConfiguration config : batch) {
                        addConfiguration(config);
                        logger.info("Added configuration: " + config.getId());
                    }
                }

            } catch (Exception e) {
                logger.severe("Error processing configurations: " + e.getMessage());
            }
        });
    }

    public void startService() throws InterruptedException {
        // Simulate service starting
        Thread.sleep((long) (Math.random() * 1000));
        logger.info("Service started");

        // Start monitoring and recovery mechanisms if needed
    }

    public void stopService() {
        // Notify messaging system
        sendMessageToSystem("Service stopped.");
        logger.info("Service stopped with message sent to the messaging system.");

        executorService.shutdown();
    }

    private void sendMessageToSystem(String message) {
        // Implement integration with messaging system
        logger.info("Message sent: " + message);
    }

    public static class NetworkConfiguration {
        private final String protocol;
        private final int portNumber;
        private final long timeout; // in milliseconds
        private final long bandwidthLimit; // bytes per second
        private final String id;

        public NetworkConfiguration(String protocol, int portNumber, long timeout, 
                                    long bandwidthLimit, String id) {
            this.protocol = protocol;
            this.portNumber = portNumber;
            this.timeout = timeout;
            this.bandwidthLimit = bandwidthLimit;
            this.id = id;
        }

        // Getters
        public String getProtocol() { return protocol; }
        public int getPortNumber() { return portNumber; }
        public long getTimeout() { return timeout; }
        public long getBandwidthLimit() { return bandwidthLimit; }
        public String getId() { return id; }
    }

    public static void main(String[] args) {
        NetworkConfigManager manager = new NetworkConfigManager(100);

        // Example configuration
        NetworkConfiguration config1 = new NetworkConfigManager.NetworkConfiguration(
            "TCP", 8080, 5000L, 1024 * 1024, "config-001");

        // Adding configurations
        manager.addConfiguration(config1);

        // Starting and stopping the service with a random delay
        try {
            manager.startService();
            Thread.sleep((long) (Math.random() * 2000));
            manager.stopService();
        } catch (InterruptedException e) {
            logger.severe("Interrupted: " + e.getMessage());
        }
    }
}
