    if (!new_node) return -1;

    memcpy(&(new_node->flow), flow, sizeof(NetworkFlow));
    new_node->flow.FlowID = flow_id;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    log_message("Inserted a new network flow.");
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int delete_flow(FlowList* list, const char* SourceIP, const char* DestinationIP) {
    pthread_mutex_lock(&list->lock);
    Node *prev = NULL, *current = list->head;

    while (current != NULL && strcmp(current->flow.SourceIP, SourceIP) != 0 ||
                                              strcmp(current->flow.DestinationIP, DestinationIP) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    log_message("Deleted a network flow.");
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

NetworkFlow* get_flow_by_ip(FlowList* list, const char* SourceIP, const char* DestinationIP) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (strcmp(current->flow.SourceIP, SourceIP) == 0 &&
            strcmp(current->flow.DestinationIP, DestinationIP) == 0) {
            pthread_mutex_unlock(&list->lock);
            return &(current->flow);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void init_flow_list(FlowList* list) {
