void initialize_system() {
    // Create tables and hash maps
    DurationTable *duration_table = create_duration_table();
    EventTable *event_table = create_event_table();
    ResourceTable *resource_table = create_resource_table();

    HashMap *event_type_map = create_hash_map(1024);
    HashMap *metadata_map = create_hash_map(512);

    Cache *event_cache = create_cache(256);

    // Initialize duration intervals
    for (size_t i = 0; i < NUM_DURATIONS; ++i) {
        uint32_t start_time = MIN_DURATION + (MAX_DURATION - MIN_DURATION) * i / (NUM_DURATIONS - 1);
        uint32_t end_time = start_time + ((MAX_DURATION - MIN_DURATION) / (NUM_DURATIONS - 1));
        pthread_rwlock_wrlock(&duration_table->lock);
        if (duration_table->count >= duration_table->capacity) {
            resize_duration_intervals(duration_table);
        }
        duration_table->intervals[duration_table->count].start_time = start_time;
        duration_table->intervals[duration_table->count++].end_time = end_time;
        pthread_rwlock_unlock(&duration_table->lock);
    }

    // Populate event records
    for (size_t i = 0; i < MAX_EVENTS; ++i) {
        Event *event = (Event*)allocate_memory(sizeof(Event));
        event->timestamp = rand() % MAX_DURATION;
        snprintf(event->type, sizeof(event->type), "Type%d", rand() % 10);
        size_t payload_size = rand() % 100 + 1;
        event->payload = allocate_memory(payload_size);
        memset(event->payload, rand(), payload_size);
        event->payload_size = payload_size;

        Metadata *metadata = (Metadata*)allocate_memory(sizeof(Metadata));
        snprintf(metadata->data, sizeof(metadata->data), "Metadata%d", i);

        pthread_rwlock_wrlock(&event_table->lock);
        if (event_table->count >= event_table->capacity) {
            // Resize logic
        }
        event_table->events[event_table->count++] = event;
        pthread_rwlock_unlock(&event_table->lock);

        pthread_rwlock_wrlock(&resource_table->lock);
        if (resource_table->count >= resource_table->capacity) {
            // Resize logic
        }
        resource_table->metadata[resource_table->count++] = *metadata;
        pthread_rwlock_unlock(&resource_table->lock);

        event->metadata_ptr = metadata;

        hash_map_insert(event_type_map, event->type, event);
    }

    // Destroy resources on exit
    destroy_duration_table(duration_table);
    destroy_event_table(event_table);
    destroy_resource_table(resource_table);
    destroy_hash_map(event_type_map);
    destroy_cache(event_cache);
}

int main() {
    initialize_system();
    return 0;
}
