    Record *head;
} ConfigManager;

void resize_array(long **array, size_t current_size, size_t new_capacity) {
    *array = realloc(*array, sizeof(long) * new_capacity);
}

void resize_int_array(int **array, size_t current_size, size_t new_capacity) {
    *array = realloc(*array, sizeof(int) * new_capacity);
}

void initialize_config_manager(ConfigManager *manager) {
    pthread_mutex_init(&manager->mutex, NULL);

    manager->offsets = malloc(sizeof(long));
    manager->max_offset_capacity = 10;
    manager->offset_size = 0;

    manager->keys = malloc(sizeof(int));
    manager->max_key_capacity = 10;
    manager->key_size = 0;

    manager->head = NULL;
}

void append_record(ConfigManager *manager, short s, int i, float f) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->offset_size >= manager->max_offset_capacity) {
        resize_array(&manager->offsets, manager->offset_size, manager->max_offset_capacity * 2);
        manager->max_offset_capacity *= 2;
    }

    if (manager->key_size >= manager->max_key_capacity) {
        resize_int_array(&manager->keys, manager->key_size, manager->max_key_capacity * 2);
        manager->max_key_capacity *= 2;
    }

    Record *new_record = malloc(sizeof(Record));
    new_record->s = s;
    new_record->i = i;
    new_record->f = f;
    new_record->next = manager->head;

    manager->offsets[manager->offset_size++] = (long)new_record;  // Store pointer as offset
    manager->keys[manager->key_size++] = rand() % 1000;            // Random key for demonstration

    manager->head = new_record;

    pthread_mutex_unlock(&manager->mutex);
}

void process_config_file(ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "r+");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Simulate libsed operations for substitution
    sed_t *s = sed_open(file);
    if (s == NULL) {
        perror("Failed to initialize libsed");
        fclose(file);
        return;
    }

    // Placeholder for actual pattern substitution logic using libsed
    sed_sub(s, "PLACEHOLDER", "ACTUAL_VALUE");

    // Securely append encrypted password at the end of file
    const char *encrypted_password = "ENCRYPTED_PASSWORD";
    fseek(file, 0, SEEK_END);
    size_t len = strlen(encrypted_password);

    if (len > 0 && fwrite(encrypted_password, 1, len, file) != len) {
        perror("Failed to write encrypted password");
    }

    fclose(file);
}

void cleanup_config_manager(ConfigManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    Record *current = manager->head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }

    free(manager->offsets);
    free(manager->keys);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

int main() {
    ConfigManager manager;
    initialize_config_manager(&manager);

    // Example usage
    append_record(&manager, 1, 42, 3.14f);
    process_config_file(&manager, "config.txt");

    cleanup_config_manager(&manager);
    return 0;
}
