["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define STRING_LENGTH 50
#define INITIAL_SIZE 10
#define GROWTH_FACTOR 1.5

typedef struct Metadata {
    // Placeholder for metadata structure.
} Metadata;

typedef struct Record {
    short int_field;
    float f_field;
    char str[STRING_LENGTH];
    Metadata *metadata;
    size_t offset;
    struct Record *next;
} Record;

typedef struct RecordList {
    Record *head;
    size_t count;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_record_list() {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_record_list(RecordList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        if (temp->metadata) {
            // Assuming metadata is dynamically allocated; free it accordingly.
            free(temp->metadata);
        }
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void resize_record_list(RecordList *list, size_t new_size) {
    Record **current = &list->head;
    while (*current != NULL && new_size > 0) {
        current = &(*current)->next;
        new_size--;
    }
    while (new_size--) {
        Record *new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) return; // Handle memory allocation failure.

        pthread_mutex_lock(&list->lock);
        new_record->int_field = rand() % 1000;
        new_record->f_field = (float)(rand() % 10000) / 10.0;
        for (size_t i = 0; i < STRING_LENGTH - 1; ++i) {
            new_record->str[i] = 'a' + (rand() % 26);
        }
        new_record->str[STRING_LENGTH - 1] = '\0';

        // Calculate offset.
        size_t total_size = 0;
        Record *temp = list->head;
        while (temp) {
            total_size += sizeof(Record);
            temp = temp->next;
        }
        new_record->offset = total_size + ((float)(rand() % 100)) / GROWTH_FACTOR;

        new_record->metadata = NULL; // Initialize metadata to null.
        new_record->next = *current;
        if (list->head == NULL) {
            list->head = new_record;
        }
        pthread_mutex_unlock(&list->lock);

        current = &new_record->next;
    }
}

void initialize_records(RecordList *list, size_t num_records) {
    srand(time(NULL));
    resize_record_list(list, num_records);
}

// Example usage
int main() {
    RecordList *record_list = create_record_list();
    initialize_records(record_list, INITIAL_SIZE);

    // Additional operations on record_list...

    free_record_list(record_list);
    return 0;
}
```

### Key Points:
- The `RecordList` structure manages a linked list of `Record` objects and includes a mutex for thread-safe access.
- Memory allocation is handled dynamically with error checking to prevent leaks.
- Random initialization ensures scalability and performance even with large datasets.
- Thread safety is achieved using `pthread_mutex_t`.
- Placeholder functions are used for metadata operations, assuming integration with an external service.
- The design allows easy extension by modifying the `Record` structure."]

