<?php

function manageUserRequest() {
    session_start();

    // Rate limiting
    $ip = $_SERVER['REMOTE_ADDR'];
    $rateLimitKey = "requests_$ip";
    if (!isset($_SESSION[$rateLimitKey])) {
        $_SESSION[$rateLimitKey] = ['count' => 0, 'timestamp' => time()];
    }

    $currentTime = time();
    if ($currentTime - $_SESSION[$rateLimitKey]['timestamp'] > 60) {
        $_SESSION[$rateLimitKey]['count'] = 1;
        $_SESSION[$rateLimitKey]['timestamp'] = $currentTime;
    } else {
        $_SESSION[$rateLimitKey]['count']++;
    }

    if ($_SESSION[$rateLimitKey]['count'] > 10) {
        return ['status' => 'error', 'message' => 'Rate limit exceeded'];
    }

    // Token and tenant validation
    $token = $_REQUEST['token'] ?? '';
    $tenantId = $_SERVER['HTTP_X_TENANT_ID'];

    if (!verifyToken($token, $tenantId)) {
        return ['status' => 'error', 'message' => 'Unauthorized request'];
    }

    // Extract and validate input
    $id = $_REQUEST['id'] ?? null;
    $name = $_REQUEST['name'] ?? '';
    $email = $_REQUEST['email'] ?? '';
    $password = $_REQUEST['password'] ?? '';
    $subAction = $_REQUEST['sub_action'] ?? '';

    if (!validateInput($name, $email, $password)) {
        return ['status' => 'error', 'message' => 'Validation failed'];
    }

    if (!$emailIsUnique($email, $id)) {
        return ['status' => 'error', 'message' => 'Email already exists'];
    }

    // Password hashing
    $hashedPassword = password_hash($password, PASSWORD_BCRYPT);

    try {
        if ($subAction === 'delete') {
            deleteUserAccount($id);
            logAction("User deleted with ID: $id");
        } elseif ($id) {
            updateUserAccount($id, $name, $email, $hashedPassword);
            logAction("User updated with ID: $id");
        } else {
            createUserAccount($name, $email, $hashedPassword);
            logAction("New user created with email: $email");
        }
    } catch (Exception $e) {
        logError($e->getMessage());
        return ['status' => 'error', 'message' => 'Database connection issue'];
    }

    return ['status' => 'success', 'message' => 'Operation completed successfully'];
}

function verifyToken($token, $tenantId) {
    // Token verification logic with session and tenant check
    // Return true if valid, false otherwise
    return isset($_SESSION['valid_tokens'][$tenantId]) && in_array($token, $_SESSION['valid_tokens'][$tenantId]);
}

function validateInput($name, $email, $password) {
    // Validate presence
    if (empty($name) || empty($email) || empty($password)) {
        return false;
    }

    // Validate email format
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return false;
    }

    // Validate password length
    if (strlen($password) < 8) {
        return false;
    }

    return true;
}

function emailIsUnique($email, $id = null) {
    // Check database for existing email (exclude current user if updating)
    $stmt = dbConnection()->prepare("SELECT COUNT(*) FROM users WHERE email = ?" . ($id ? " AND id != '$id'" : ""));
    $stmt->execute([$email]);
    return $stmt->fetchColumn() == 0;
}

function createUserAccount($name, $email, $hashedPassword) {
    // Insert user into database
    $stmt = dbConnection()->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
    $stmt->execute([$name, $email, $hashedPassword]);
}

function updateUserAccount($id, $name, $email, $hashedPassword) {
    // Update user in database
    $stmt = dbConnection()->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
    $stmt->execute([$name, $email, $hashedPassword, $id]);
}

function deleteUserAccount($id) {
    // Delete user from database
    $stmt = dbConnection()->prepare("DELETE FROM users WHERE id = ?");
    $stmt->execute([$id]);
}

function logAction($message) {
    file_put_contents('log.txt', date('[Y-m-d H:i:s] ') . "ACTION: $message" . PHP_EOL, FILE_APPEND);
}

function logError($message) {
    file_put_contents('error_log.txt', date('[Y-m-d H:i:s] ') . "ERROR: $message" . PHP_EOL, FILE_APPEND);
}

function dbConnection() {
    // Establish database connection
    try {
        return new PDO('mysql:host=localhost;dbname=testdb', 'username', 'password');
    } catch (PDOException $e) {
        throw new Exception("Database connection error");
    }
}
