using System;
using System.Net;
using System.Text;
using System.Threading.Tasks;

public class WebApplicationService
{
    private readonly IContentUpdateService _contentUpdateService;
    private readonly ICdnIntegration _cdnIntegration;
    private readonly IBgJobScheduler _bgJobScheduler;
    private readonly ILogger _logger;

    public WebApplicationService(
        IContentUpdateService contentUpdateService,
        ICdnIntegration cdnIntegration,
        IBgJobScheduler bgJobScheduler,
        ILogger logger)
    {
        _contentUpdateService = contentUpdateService ?? throw new ArgumentNullException(nameof(contentUpdateService));
        _cdnIntegration = cdnIntegration ?? throw new ArgumentNullException(nameof(cdnIntegration));
        _bgJobScheduler = bgJobScheduler ?? throw new ArgumentNullException(nameof(bgJobScheduler));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<(int StatusCode, string Message)> UpdateElementWithDNSLookup(
        int pageSectionId,
        int elementId,
        string htmlContent)
    {
        // Validate inputs
        if (pageSectionId <= 0 || elementId <= 0 || htmlContent == null || htmlContent.Length > 1024 * 1024) // 1 MB limit
        {
            _logger.LogError("Invalid input parameters.");
            return (400, "Bad Request");
        }

        try
        {
            string[] parts = htmlContent.Split(' ');
            if (parts.Length < 2)
            {
                _logger.LogError("HTML content does not contain a valid hostname for DNS lookup.");
                return (400, "Invalid HTML Content Format");
            }

            string hostname = parts[1];
            u_char[] ipAddressBytes = new byte[4];

            // Perform DNS lookup
            IPHostEntry hostEntry = Dns.GetHostEntry(hostname);
            IPAddress ipAddress = hostEntry.AddressList[0]; // Get first resolved address
            Array.Copy(ipAddress.GetAddressBytes(), 0, ipAddressBytes, 0, ipAddressBytes.Length);

            _logger.LogInformation($"DNS Lookup for {hostname} succeeded with IP: {ipAddress}");

            using (var transaction = new TransactionScope())
            {
                bool updateSuccess = await _contentUpdateService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

                if (!updateSuccess)
                {
                    _logger.LogError("Failed to update the content in the service.");
                    return (500, "Internal Server Error");
                }

                // Cache and CDN integration
                bool cacheSuccess = await _cdnIntegration.CacheUpdatedContentAsync(elementId, htmlContent);

                if (!cacheSuccess)
                {
                    _logger.LogWarning("CDN caching failed. Proceeding without it.");
                }

                transaction.Complete();
            }

            // Schedule background job for refresh with retry logic
            bool bgJobScheduled = await ScheduleRefreshWithRetry(pageSectionId);

            if (!bgJobScheduled)
            {
                _logger.LogError("Failed to schedule page section refresh.");
                return (500, "Background Job Scheduling Error");
            }

            _logger.LogInformation($"Element {elementId} in Page Section {pageSectionId} updated successfully.");

            return (200, "Page should be refreshed");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error during element update or DNS lookup.");
            return (500, "Internal Server Error");
        }
    }

    private async Task<bool> ScheduleRefreshWithRetry(int pageSectionId)
    {
        int retryCount = 0;
        while (retryCount < 3)
        {
            try
            {
                await _bgJobScheduler.ScheduleAsync(pageSectionId);
                return true;
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, $"Attempt {retryCount + 1} to schedule background job failed.");
                retryCount++;
            }
        }

        return false;
    }
}

// Define interfaces for dependency injection
public interface IContentUpdateService
{
    Task<bool> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent);
}

public interface ICdnIntegration
{
    Task<bool> CacheUpdatedContentAsync(int elementId, string content);
}

public interface IBgJobScheduler
{
    Task ScheduleAsync(int pageSectionId);
}

// Logger interface example
public interface ILogger
{
    void LogError(string message);
    void LogError(Exception ex, string message);
    void LogWarning(Exception ex, string message);
    void LogInformation(string message);
}
