#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "libsed.h"  // Assume libsed is properly included and linked

#define INITIAL_CAPACITY 16

typedef struct record {
    short s;
    int i;
    float f;
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    size_t offset_count;
    size_t offset_capacity;

    int *keys;
    size_t key_count;
    size_t key_capacity;

    Record **records;
    Record *head_record;

    // Simplified hash table for demonstration
    void **hash_table; 
    size_t hash_capacity;
} ConfigManager;

pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_config_manager(ConfigManager *cm) {
    cm->offsets = malloc(INITIAL_CAPACITY * sizeof(long));
    cm->offset_count = 0;
    cm->offset_capacity = INITIAL_CAPACITY;

    cm->keys = malloc(INITIAL_CAPACITY * sizeof(int));
    cm->key_count = 0;
    cm->key_capacity = INITIAL_CAPACITY;

    cm->records = malloc(sizeof(Record*)); // Start with one slot for linked list head
    cm->head_record = NULL;

    cm->hash_table = calloc(INITIAL_CAPACITY, sizeof(void*));
