#include <zlib.h> // For CRC32

#define INITIAL_POOL_SIZE 1024
#define RECORD_ID_HASH_SEED 0x314159265359

typedef struct {
    uint64_t id;
    int value;
    struct timespec timestamp;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} RecordPool;

RecordPool* create_record_pool(size_t initial_capacity) {
    RecordPool *pool = malloc(sizeof(RecordPool));
    pool->records = calloc(initial_capacity, sizeof(Record));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void free_record_pool(RecordPool *pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

uint64_t generate_unique_id() {
    static uint64_t seed = RECORD_ID_HASH_SEED;
    return __sync_fetch_and_add(&seed, 1);
}

void init_record(Record *record, int value) {
    record->id = generate_unique_id();
    record->value = (rand() % 100); // Random value between 0 and 99
    clock_gettime(CLOCK_REALTIME, &record->timestamp);
}

uint32_t compute_checksum(const Record *records, size_t count, const char *algorithm) {
    if (strcmp(algorithm, "CRC32") == 0) {
        uint32_t checksum = crc32(0L, Z_NULL, 0);
        for (size_t i = 0; i < count; ++i) {
            checksum = crc32(checksum, (const unsigned char*)&records[i], sizeof(Record));
        }
        return checksum;
    }
    // Add other algorithms like Adler32 if needed
    return 0;
}

void resize_record_pool_if_needed(RecordPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record *new_records = realloc(pool->records, new_capacity * sizeof(Record));
        if (new_records) {
            pool->records = new_records;
            pool->capacity = new_capacity;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void add_record_to_pool(RecordPool *pool, int value) {
    resize_record_pool_if_needed(pool);
    pthread_mutex_lock(&pool->lock);
    init_record(&pool->records[pool->count], value);
    pool->count++;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

void traverse_records(RecordPool *pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        printf("ID: %llu, Value: %d, Timestamp: %ld.%09ld\n",
               pool->records[i].id,
               pool->records[i].value,
               pool->records[i].timestamp.tv_sec,
               pool->records[i].timestamp.tv_nsec);
    }
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    srand(time(NULL));
    RecordPool *pool = create_record_pool(INITIAL_POOL_SIZE);

    for (int i = 0; i < 2000; ++i) { // Simulate adding records
        add_record_to_pool(pool, i);
    }

    traverse_records(pool);

    free_record_pool(pool);
    return 0;
}
