#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h> // For JSON parsing

#define MAX_THREADS 10
#define HASH_TABLE_SIZE 1024
#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 512
#define EXPIRY_RANGE 3600 // 1 hour in seconds

typedef struct Setting {
    char *key;
    char *value;
    time_t last_updated;
} Setting;

typedef struct Node {
    Setting setting;
    struct Node* next;
} Node;

Node** hash_table = NULL;
pthread_mutex_t* mutexes = NULL; // For simplifying, using mutex locks instead of lock-free

unsigned int hash(const char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c;
    return hash % HASH_TABLE_SIZE;
}

void init_hash_table() {
    hash_table = (Node**) calloc(HASH_TABLE_SIZE, sizeof(Node*));
    mutexes = (pthread_mutex_t*) malloc(HASH_TABLE_SIZE * sizeof(pthread_mutex_t));

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void insert_setting(const char *key, const char *value) {
    unsigned int index = hash(key);
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->setting.key = strdup(key);
    new_node->setting.value = strdup(value);
    new_node->setting.last_updated = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&mutexes[index]);
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
    pthread_mutex_unlock(&mutexes[index]);
}

void* process_json_file(void* arg) {
    const char *filename = (const char*)arg;
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON file %s: %s\n", filename, error.text);
        return NULL;
    }

    // Assume predefined schema validation function exists
    if (json_validate(root)) { // Placeholder for actual validation logic
        json_t *key_value_pairs = json_object_get(root, "settings");

        if (!json_is_array(key_value_pairs)) {
            fprintf(stderr, "Invalid settings format in %s\n", filename);
            json_decref(root);
            return NULL;
        }

        size_t index;
        json_t *value_pair;

        json_array_foreach(key_value_pairs, index, value_pair) {
            if (!json_is_object(value_pair)) continue;

            const char* key = json_string_value(json_object_get(value_pair, "key"));
            const char* value = json_string_value(json_object_get(value_pair, "value"));

            if (key && value) {
                insert_setting(key, value);
            }
        }

        json_decref(root);
    } else {
        fprintf(stderr, "Schema validation failed for %s\n", filename);
    }

    return NULL;
}

void process_files_concurrently(const char *files[], size_t count) {
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (size_t i = 0; i < count; ++i) {
        if (thread_count >= MAX_THREADS) {
            for (int j = 0; j < MAX_THREADS; ++j)
                pthread_join(threads[j], NULL);
            thread_count = 0;
        }

        pthread_create(&threads[thread_count++], NULL, process_json_file, files[i]);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_hash_table() {
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = hash_table[i];
        while (node) {
            Node* tmp = node;
            node = node->next;
            free(tmp->setting.key);
            free(tmp->setting.value);
            free(tmp);
        }
    }

    free(hash_table);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i)
        pthread_mutex_destroy(&mutexes[i]);
    free(mutexes);
}

void summarize_configurations() {
    // Summarize the configurations
    printf("Configuration Summary:\n");
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = hash_table[i];
        while (node) {
            printf("Key: %s, Value: %s\n", node->setting.key, node->setting.value);
            node = node->next;
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <json_file1> <json_file2> ... \n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* files[argc - 1];
    for (int i = 1; i < argc; ++i)
        files[i - 1] = argv[i];

    init_hash_table();
    process_files_concurrently(files, argc - 1);
    summarize_configurations();
    free_hash_table();

    return EXIT_SUCCESS;
}
```

