void log_message(const char *message);

// Thread-safe initialization and memory management function
record* initialize_records(size_t count, size_t max_memory_usage, pthread_mutex_t *mutex, FILE *log_file) {
    if (count == 0 || max_memory_usage == 0 || !mutex) return NULL;

    // Calculate the maximum number of records we can allocate without exceeding max_memory_usage
    size_t record_size = sizeof(record);
    size_t max_records = max_memory_usage / record_size;

    // Adjust count to not exceed calculated max_records
    if (count > max_records) {
        log_message("Requested more memory than allowed, adjusting the number of records.");
        count = max_records;
    }

    record *records = malloc(count * record_size);
    if (!records) {
        log_message("Memory allocation failed for records array.");
        return NULL;
    }

    // Lock mutex before accessing shared resources
    pthread_mutex_lock(mutex);

    // Initialize the records with random keys and offsets
    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % max_key_value;
        records[i].offset = rand();
    }

    // Unlock mutex after modifying shared resources
    pthread_mutex_unlock(mutex);

    log_message("Records initialized successfully.");

    return records;
}

// Function to free allocated memory for records
void cleanup_records(record *records) {
    if (records) {
        free(records);
    }
}

// Simple logger function
void log_message(const char *message) {
    static FILE *log_file = NULL;

    // Initialize logging file once, handle errors appropriately
    if (!log_file) {
        log_file = fopen("memory_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file.");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure the message is written immediately
}

// Function to read configuration from a file
void load_configuration(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open config file.");
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d", &max_key_value);
    fclose(file);

    log_message("Configuration loaded successfully.");
}

int main() {
    // Initialize the random number generator
    srand((unsigned int)time(NULL));

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex init failed");
        return EXIT_FAILURE;
    }

    load_configuration("config.txt");

    size_t record_count = 100; // example value
    size_t max_memory_usage = 1024 * 1024; // 1 MB

    record *records = initialize_records(record_count, max_memory_usage, &mutex, fopen("memory_log.txt", "a"));
    if (records) {
        cleanup_records(records);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}
