typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int ProtocolType;
    time_t Timestamp;
} NetworkTraffic;

typedef struct Node {
    NetworkTraffic data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TrafficCollection;

TrafficCollection* create_collection() {
    TrafficCollection* collection = malloc(sizeof(TrafficCollection));
    if (collection) {
        collection->head = NULL;
        pthread_mutex_init(&collection->lock, NULL);
    }
    return collection;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

int add_record(TrafficCollection* collection, NetworkTraffic record) {
    if (!collection) return -1;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    memcpy(&new_node->data, &record, sizeof(NetworkTraffic));
    new_node->next = NULL;

    pthread_mutex_lock(&collection->lock);

    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

int remove_record(TrafficCollection* collection, char* SourceIP) {
    if (!collection || !SourceIP) return -1;

    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head, *prev = NULL;
    while (current && strcmp(current->data.SourceIP, SourceIP) != 0) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Record not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        collection->head = current->next;
    }

    free_node(current);

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

int update_record(TrafficCollection* collection, char* SourceIP, NetworkTraffic updated_data) {
    if (!collection || !SourceIP) return -1;

    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current && strcmp(current->data.SourceIP, SourceIP) != 0) {
        current = current->next;
    }

    if (current) {
        memcpy(&current->data, &updated_data, sizeof(NetworkTraffic));
    } else {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Record not found
    }

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void list_records(TrafficCollection* collection, char* rangeStartIP, char* rangeEndIP) {
    if (!collection || !rangeStartIP || !rangeEndIP) return;

    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        // Assuming a simple lexicographical comparison for IP ranges
        if (strcmp(current->data.SourceIP, rangeStartIP) >= 0 && strcmp(current->data.SourceIP, rangeEndIP) <= 0) {
            printf("Source: %s, Destination: %s, Protocol: %d, Timestamp: %ld\n",
                   current->data.SourceIP,
                   current->data.DestinationIP,
                   current->data.ProtocolType,
                   current->data.Timestamp);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

void export_to_file(TrafficCollection* collection, const char* filename) {
    if (!collection || !filename) return;

    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        fprintf(file, "%s,%s,%d,%ld\n",
                current->data.SourceIP,
                current->data.DestinationIP,
                current->data.ProtocolType,
                current->data.Timestamp);
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);

    fclose(file);
}

void free_collection(TrafficCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free_node(temp);
    }

    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
