    record->status_indicator = (StatusIndicator)(rand() % 3);
    record->priority_level = (PriorityLevel)(rand() % 3);

    snprintf(record->context_id, sizeof(record->context_id), "Ctx-%d", rand());

    record->prev = NULL;
    record->next = NULL;

    return record;
}

Metadata* createMetadata(const char *data) {
    Metadata *metadata = malloc(sizeof(Metadata));
    if (!metadata) return NULL;

    metadata->data = strdup(data);
    if (!metadata->data) {
        free(metadata);
        return NULL;
    }

