}

void freeList(LinkedList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        if (current->metadata) {
            free(current->metadata->data);
            free(current->metadata);
        }
        free(current);
        current = next;
    }
}

