#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_ITEMS 10000
#define ITEM_SIZE sizeof(struct item)
#define POOL_SIZE (MAX_ITEMS * ITEM_SIZE)

typedef struct item {
    double value;
    int number;
    struct item* next;
    struct item* prev;
} item;

typedef struct pool {
    item* items[MAX_ITEMS];
    pthread_mutex_t lock;
    size_t count;
} pool;

pool* create_pool() {
    pool* p = (pool*)malloc(sizeof(pool));
    if (!p) return NULL;

    pthread_mutex_init(&p->lock, NULL);
    memset(p->items, 0, sizeof(item*) * MAX_ITEMS);
    p->count = 0;

    for (int i = 0; i < MAX_ITEMS; ++i) {
        p->items[i] = (item*)malloc(ITEM_SIZE);
    }
    return p;
}

void destroy_pool(pool* p) {
    if (!p) return;
    pthread_mutex_lock(&p->lock);

    for (size_t i = 0; i < MAX_ITEMS; ++i) {
        free(p->items[i]);
        p->items[i] = NULL;
    }
    pthread_mutex_unlock(&p->lock);
    pthread_mutex_destroy(&p->lock);
    free(p);
}

item* allocate_item(pool* p) {
    pthread_mutex_lock(&p->lock);
    if (p->count >= MAX_ITEMS) {
        pthread_mutex_unlock(&p->lock);
        return NULL;
    }

    item* it = p->items[p->count++];
    pthread_mutex_unlock(&p->lock);
    return it;
}

void free_item(pool* p, item* it) {
    pthread_mutex_lock(&p->lock);
    for (size_t i = 0; i < MAX_ITEMS; ++i) {
        if (p->items[i] == it) {
            p->items[--p->count] = p->items[i];
            free(it);
            break;
        }
    }
    pthread_mutex_unlock(&p->lock);
}

void initialize_item(item* it, int min, int max) {
    uint64_t rand_int;
    if (RAND_bytes((unsigned char*)&rand_int, sizeof(rand_int)) != 1) {
        perror("Random number generation failed");
        exit(EXIT_FAILURE);
    }

    it->number = ((rand_int % (max - min + 1)) + min);

    double rand_double;
    RAND_bytes((unsigned char*)&rand_double, sizeof(rand_double));
    it->value = fabs(rand_double) / UINT64_MAX;

    it->next = NULL;
    it->prev = NULL;
}

void recursive_populate(pool* p, item** head, int depth) {
    if (depth > MAX_ITEMS) return;

    item* new_item = allocate_item(p);
    if (!new_item) return;

    initialize_item(new_item, 1, 100);

    pthread_mutex_lock(&p->lock);
    if (*head == NULL) {
        *head = new_item;
    } else {
        item* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_item;
        new_item->prev = current;
    }
    pthread_mutex_unlock(&p->lock);

    recursive_populate(p, head, depth + 1);
}

void free_list(item* head) {
    while (head != NULL) {
        item* temp = head;
        head = head->next;
        free_item(NULL, temp); // Pool is used for allocation, so directly freeing here
    }
}

typedef struct iterator {
    item* current;
    int direction; // 1 for forward, -1 for backward
} iterator;

iterator create_iterator(item* start) {
    iterator it = {start, 1};
    return it;
}

item* iterate(iterator* it) {
    if (it->current == NULL) return NULL;

    item* result = it->current;
    if (it->direction == 1 && it->current->next != NULL) {
        it->current = it->current->next;
    } else if (it->direction == -1 && it->current->prev != NULL) {
        it->current = it->current->prev;
    } else {
        return NULL; // End of list
    }

    return result;
}

int main() {
    pool* p = create_pool();
    item* head = NULL;

    recursive_populate(p, &head, 0);

    iterator it = create_iterator(head);
    while ((it.current = iterate(&it)) != NULL) {
        printf("Item: %f, %d\n", it.current->value, it.current->number);
    }

    free_list(head);
    destroy_pool(p);

    return 0;
}
```

