typedef struct MemoryPool {
    size_t block_size;
    void *free_list_head;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct DoublyLinkedList {
    Record *head;
    Record *tail;
    pthread_rwlock_t list_lock;
} DoublyLinkedList;

MemoryPool* create_memory_pool(size_t initial_size, size_t block_size);
