// Implementations

MemoryPool* create_memory_pool(size_t initial_size, size_t block_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->free_list_head = malloc(initial_size * block_size);
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize free list blocks
    char *current = pool->free_list_head;
    for (size_t i = 0; i < initial_size - 1; ++i) {
        *((void**)current) = current + block_size;
        current += block_size;
    }
    *(void**)current = NULL;

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->free_list_head);
    free(pool);
}

Record* allocate_record(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    void *block = pool->free_list_head;
    if (!block) {
        // Handle memory exhaustion, e.g., resize
        // For simplicity, this is not implemented here.
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pool->free_list_head = *(void**)block;

    pthread_mutex_unlock(&pool->lock);
    return (Record*)block;
}

void free_record(Record* record, MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    *((void**)record) = pool->free_list_head;
    pool->free_list_head = record;

    pthread_mutex_unlock(&pool->lock);
}

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_init(&list->list_lock, NULL);

    return list;
}

void destroy_doubly_linked_list(DoublyLinkedList* list) {
    pthread_rwlock_destroy(&list->list_lock);
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free_record(current, /* memory pool */ NULL); // Pass actual pool if used
        current = next;
    }
    free(list);
}

int add_record_to_list(DoublyLinkedList* list, Record* record) {
    pthread_rwlock_wrlock(&list->list_lock);

    if (!list->head) {
        list->head = record;
        list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }

    pthread_rwlock_unlock(&list->list_lock);
    return 0; // success
}

Record* remove_record_from_list(DoublyLinkedList* list, int key) {
    pthread_rwlock_wrlock(&list->list_lock);

    Record *current = list->head;
    while (current && current->iField != key) {
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->list_lock);
        return NULL; // not found
    }

    if (current->prev) current->prev->next = current->next;
    else list->head = current->next;

    if (current->next) current->next->prev = current->prev;
    else list->tail = current->prev;

    pthread_rwlock_unlock(&list->list_lock);
    return current;
}

void iterate_records(const DoublyLinkedList* list, void (*callback)(const Record*)) {
    pthread_rwlock_rdlock(&list->list_lock);

    for (Record *current = list->head; current; current = current->next) {
        callback(current);
    }

    pthread_rwlock_unlock(&list->list_lock);
}

Metadata* create_metadata(const char *data) {
    Metadata *metadata = (Metadata*)malloc(sizeof(Metadata));
    size_t len = strlen(data);

    if (len > MAX_METADATA_LENGTH - 1) {
        len = MAX_METADATA_LENGTH - 1;
    }

    metadata->data = (char*)malloc(len + 1);
    strncpy(metadata->data, data, len);
    metadata->data[len] = '\0';

    return metadata;
}

void validate_and_truncate_metadata(char *metadata, size_t max_length) {
    if (strlen(metadata) > max_length - 1) {
        metadata[max_length - 1] = '\0';
    }

    for (size_t i = 0; metadata[i]; ++i) {
        if (!strchr(METADATA_ALLOWED_CHARS, metadata[i])) {
            metadata[i] = '_'; // or handle invalid chars differently
        }
    }
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

float generate_random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

short generate_random_short(short min, short max) {
    return (short)(rand() % (max - min + 1) + min);
}

timestamp_t generate_random_timestamp(timestamp_t start, timestamp_t end) {
    long range = end - start;
    return (timestamp_t)((double)rand() / RAND_MAX * range + start);
}
