#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_PROFILE_SIZE 10
#define MAX_NAME_LENGTH 50
#define MAX_EMAIL_LENGTH 100

typedef struct Role {
    char *name;
    struct Role *next;
} Role;

typedef struct UserProfile {
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    time_t last_login;
    Role *roles;
} UserProfile;

typedef struct UserSystem {
    UserProfile **profiles;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UserSystem;

UserSystem* init_user_system() {
    UserSystem *system = malloc(sizeof(UserSystem));
    system->capacity = INITIAL_PROFILE_SIZE;
    system->count = 0;
    system->profiles = calloc(system->capacity, sizeof(UserProfile *));
    pthread_mutex_init(&system->lock, NULL);
    return system;
}

void resize_user_system(UserSystem *system) {
    pthread_mutex_lock(&system->lock);
    size_t new_capacity = system->capacity * 2;
    UserProfile **new_profiles = realloc(system->profiles, new_capacity * sizeof(UserProfile *));
    if (new_profiles) {
        system->profiles = new_profiles;
        system->capacity = new_capacity;
    }
    pthread_mutex_unlock(&system->lock);
}

void add_user_profile(UserSystem *system, const char *name, const char *email) {
    pthread_mutex_lock(&system->lock);

    if (system->count == system->capacity) {
        resize_user_system(system);
    }

    UserProfile *profile = malloc(sizeof(UserProfile));
    strncpy(profile->name, name, MAX_NAME_LENGTH - 1);
    profile->name[MAX_NAME_LENGTH - 1] = '\0';
    strncpy(profile->email, email, MAX_EMAIL_LENGTH - 1);
    profile->email[MAX_EMAIL_LENGTH - 1] = '\0';
    profile->last_login = time(NULL) + rand() % (3600 * 24); // Random timestamp within a day
    profile->roles = NULL;

    system->profiles[system->count++] = profile;
    pthread_mutex_unlock(&system->lock);
}

void log_profile_change(UserProfile *profile, const char *change_desc) {
    printf("Profile %s changed: %s at %ld\n", profile->name, change_desc, time(NULL));
}

Role* add_role_to_user(UserSystem *system, size_t user_index, const char *role_name) {
    pthread_mutex_lock(&system->lock);

    if (user_index >= system->count) {
        pthread_mutex_unlock(&system->lock);
        return NULL;
    }

    UserProfile *profile = system->profiles[user_index];
    Role *new_role = malloc(sizeof(Role));
    new_role->name = strdup(role_name);
    new_role->next = profile->roles;
    profile->roles = new_role;

    log_profile_change(profile, "Role added");

    pthread_mutex_unlock(&system->lock);
    return new_role;
}

void free_user_system(UserSystem *system) {
    for (size_t i = 0; i < system->count; ++i) {
        UserProfile *profile = system->profiles[i];
        Role *role = profile->roles;
        while (role) {
            Role *next = role->next;
            free(role->name);
            free(role);
            role = next;
        }
        free(profile);
    }
    free(system->profiles);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

int main() {
