        key[i] = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        offset[i] = (i == 0) ? 0 : offset[i - 1] + key[i - 1];
    }

    // Function to add a record
    auto add_record = [&]() {
        pthread_mutex_lock(&list_lock);

        Record* new_record = (Record*)allocate_from_pool(pool, sizeof(Record));
        new_record->short_val = rand() % 32768;
        new_record->int_val = rand() % 1000000;
        new_record->float_val = ((float)rand() / RAND_MAX) * 100.0f;
        new_record->timestamp = time(NULL);
        new_record->string = (char*)allocate_from_pool(pool, 256 * sizeof(char));
        snprintf(new_record->string, 256, "Record %lu", rand());

        new_record->next = head;
        if (head != NULL) {
            head->prev = new_record;
        }
        head = new_record;

        pthread_mutex_unlock(&list_lock);
    };

    // Populate records
    for (size_t i = 0; i < INITIAL_SIZE / 10; ++i) {
        add_record();
    }

    // Function to iterate over the linked list
    auto iterate_records = [&]() {
        pthread_mutex_lock(&list_lock);

        Record* current = head;
        while (current != NULL) {
            printf("Record: %d, %f, %s\n", current->int_val, current->float_val, current->string);
            current = current->next;
        }

        pthread_mutex_unlock(&list_lock);
    };

    iterate_records();

    // Cleanup
    free_memory_pool(pool);
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->size = size;
    pool->data = malloc(size);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->size) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void* ptr = pool->data;
    pool->data = (char*)pool->data + size;
    pool->size -= size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool != NULL) {
        free(pool->data);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
