```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *data;
    int index;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

Node* create_node(const char *data, int index) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = strdup(data);  // Duplicate the string for safe memory management
    new_node->index = index;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(LinkedList *list, const char *data, int index) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = create_node(data, index);

    if (list->head == NULL || list->head->index >= index) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next != NULL && current->next->index < index) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->data);  // Free the duplicated string
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void print_list(const LinkedList *list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        printf("Index: %d, Data: %s\n", current->index, current->data);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

int main() {
    LinkedList *list = create_list();

    insert_sorted(list, "Data 1", 3);
    insert_sorted(list, "Data 2", 1);
    insert_sorted(list, "Data 3", 5);

    print_list(list);

    delete_list(list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The list is protected by a mutex to ensure thread safety during insertion and iteration.
- **Memory Management**: Strings are duplicated using `strdup` to avoid shared data issues, and memory is properly freed when nodes are deleted.
- **Scalability**: The list maintains order upon each insertion, allowing efficient traversal and updates even as it grows.
- **Integration**: Handles varying string lengths by dynamically allocating memory for the strings.']

['```c
// MemoryManager.h

#ifndef MEMORY_MANAGER_H
#define MEMORY_MANAGER_H

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double temperature;
    double humidity;
    double pressure;
} SensorReading;

typedef enum {
    INIT_SUCCESS,
    INIT_FAILURE,
    ALLOC_FAILURE,
    LOG_FAILURE
} Status;

typedef struct {
    void* data;
    size_t element_size;
    size_t capacity;
    size_t length;
    char type[20]; // Type of data structure: "double", "char", "struct"
} MemoryBlock;

typedef struct {
    FILE* log_file;
} Logger;

// Function prototypes
Status initialize_memory_block(MemoryBlock* block, const char* type, size_t initial_capacity);
Status resize_memory_block(MemoryBlock* block, size_t new_capacity);
void free_memory_block(MemoryBlock* block);
Status create_logger(Logger* logger, const char* filename);
void log_event(Logger* logger, const char* event_description);
void shutdown_logger(Logger* logger);

#endif // MEMORY_MANAGER_H

// MemoryManager.c

#include "MemoryManager.h"

Status initialize_memory_block(MemoryBlock* block, const char* type, size_t initial_capacity) {
    if (block == NULL || type == NULL) return INIT_FAILURE;

    block->data = malloc(initial_capacity * sizeof(double)); // Default to double for simplicity
    if (!block->data) return ALLOC_FAILURE;

    block->element_size = (strcmp(type, "double") == 0) ? sizeof(double) :
                          (strcmp(type, "char") == 0) ? sizeof(char) : sizeof(SensorReading);

    block->capacity = initial_capacity;
    block->length = 0;
    strncpy(block->type, type, sizeof(block->type) - 1);

    return INIT_SUCCESS;
}

Status resize_memory_block(MemoryBlock* block, size_t new_capacity) {
    if (block == NULL || new_capacity <= block->capacity) return ALLOC_FAILURE;

    void* temp_data = realloc(block->data, new_capacity * block->element_size);
    if (!temp_data) return ALLOC_FAILURE;

    block->data = temp_data;
    block->capacity = new_capacity;

    return INIT_SUCCESS;
}

void free_memory_block(MemoryBlock* block) {
    if (block && block->data) {
        free(block->data);
        block->data = NULL;
        block->length = 0;
        block->capacity = 0;
    }
}

Status create_logger(Logger* logger, const char* filename) {
    if (logger == NULL || filename == NULL) return INIT_FAILURE;

    logger->log_file = fopen(filename, "a");
    if (!logger->log_file) return LOG_FAILURE;

    return INIT_SUCCESS;
}

void log_event(Logger* logger, const char* event_description) {
    if (logger && logger->log_file) {
        fprintf(logger->log_file, "%s\n", event_description);
        fflush(logger->log_file); // Ensure the log is written immediately
    }
}

void shutdown_logger(Logger* logger) {
    if (logger && logger->log_file) {
        fclose(logger->log_file);
        logger->log_file = NULL;
    }
}

// main.c

#include "MemoryManager.h"

int main() {
    MemoryBlock array_block;
    Logger logger;

    if (initialize_memory_block(&array_block, "double", 10) != INIT_SUCCESS) {
        fprintf(stderr, "Failed to initialize memory block\n");
        return EXIT_FAILURE;
    }

    create_logger(&logger, "memory_manager.log");
    log_event(&logger, "Initialized double array with capacity 10");

    if (resize_memory_block(&array_block, 20) == INIT_SUCCESS) {
        log_event(&logger, "Resized double array to capacity 20");
    } else {
        fprintf(stderr, "Failed to resize memory block\n");
    }

    free_memory_block(&array_block);
    log_event(&logger, "Freed double array");

    shutdown_logger(&logger);

    return EXIT_SUCCESS;
}
```

This code provides a basic framework for managing dynamic arrays of `double`, `char` strings, and `SensorReading` structs. It includes functions to initialize, resize, and free memory blocks, as well as logging capabilities to track these operations. The library is designed to handle memory allocation failures gracefully and logs events for auditing purposes.']

['Here's a C program implementing the specified requirements for managing a doubly linked list of custom `node` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char *data;
    int index;
    struct Node *next;
    struct Node *prev;
} Node;

Node* create_node(const char* data, int index) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = strdup(data);
    new_node->index = index;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_sorted(Node** head, Node* new_node) {
    if (!head || !new_node) return;

    if (*head == NULL || (*head)->index >= new_node->index) {
        new_node->next = *head;
        if (*head != NULL) (*head)->prev = new_node;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->index < new_node->index) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next != NULL) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
    }
}

void delete_node(Node** head, Node* del_node) {
    if (!head || !del_node) return;

    if (*head == del_node) *head = del_node->next;
    if (del_node->next) del_node->next->prev = del_node->prev;
    if (del_node->prev) del_node->prev->next = del_node->next;

    free(del_node->data);
    free(del_node);
}

void print_list(Node* head, int direction) {
    Node* current = head;
    if (direction == 0) { // Forward
        while (current) {
            printf("Index: %d, Data: %s\n", current->index, current->data);
            current = current->next;
        }
    } else { // Backward
        while (current && current->next) current = current->next; // Move to end
        while (current) {
            printf("Index: %d, Data: %s\n", current->index, current->data);
            current = current->prev;
        }
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current) {
        next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}

int main(int argc, char *argv[]) {
    Node* head = NULL;
    char command[256];
    int index;
    char data[256];

    while (1) {
        printf("Enter command: ");
        fgets(command, sizeof(command), stdin);
        if (strncmp(command, "insert", 6) == 0) {
            sscanf(command + 7, "%d %[^\n]", &index, data);
            Node* new_node = create_node(data, index);
            insert_sorted(&head, new_node);
        } else if (strncmp(command, "print", 5) == 0) {
            int direction;
            sscanf(command + 6, "%d", &direction);
            print_list(head, direction);
        } else if (strcmp(command, "exit\n") == 0) {
            break;
        } else {
            printf("Invalid command.\n");
        }
    }

    free_list(&head);
    return 0;
}
```

### Explanation:

- **Node Structure**: Each node contains a `char*` for data, an `int` index, and pointers to the next and previous nodes.

- **Insertion**: Nodes are inserted in sorted order based on their index. The function checks if the new node should be placed at the head or iterates through the list to find its position.

- **Deletion**: Removes a node from the list while maintaining the integrity of the pointers.

- **Traversal**: Supports forward and backward traversal, printing each node's data and index.

- **Memory Management**: Uses `malloc` and `free` for dynamic memory management. The `create_node` function duplicates strings to ensure each node manages its own data.

- **Command-Line Interface**: Simple CLI allows inserting nodes and printing the list in both directions. Handles invalid commands gracefully.

- **Cleanup**: Frees all allocated memory before exiting to prevent leaks.

This implementation is modular, allowing for future enhancements such as additional data types or integration with other systems.']

