    struct timeval timestamp;
    TaskState state;
    pthread_mutex_t lock;
} Task;

typedef struct TaskCollection {
    Task **tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} TaskCollection;

TaskCollection* create_task_collection(size_t initial_capacity) {
    TaskCollection *collection = malloc(sizeof(TaskCollection));
    collection->tasks = calloc(initial_capacity, sizeof(Task *));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void free_task(Task *task) {
    if (task) {
        pthread_mutex_lock(&task->lock);
        free(task->name);
        pthread_mutex_unlock(&task->lock);
        free(task);
    }
}

Task* create_task(const char *name, int priority_level) {
    Task *task = malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority_level = priority_level;
    gettimeofday(&task->timestamp, NULL);
    task->state = INIT;
    pthread_mutex_init(&task->lock, NULL);
    return task;
}

void log_event(const char *event) {
    printf("[LOG] %s\n", event); // Replace with a more efficient logging mechanism
}

void add_task(TaskCollection *collection, Task *task) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Task **new_tasks = realloc(collection->tasks, new_capacity * sizeof(Task *));
        if (!new_tasks) {
            free_task(task);
            log_event("Task creation failed due to memory allocation error.");
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }

    collection->tasks[collection->count++] = task;
    pthread_mutex_unlock(&collection->mutex);

    log_event("Task created successfully.");
}

void transition_task_state(Task *task, TaskState state) {
    pthread_mutex_lock(&task->lock);
    task->state = state;
    pthread_mutex_unlock(&task->lock);
}

TaskState get_task_state(Task *task) {
    pthread_mutex_lock(&task->lock);
    TaskState state = task->state;
    pthread_mutex_unlock(&task->lock);
    return state;
}

void free_task_collection(TaskCollection *collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->count; ++i) {
        free_task(collection->tasks[i]);
    }

    free(collection->tasks);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void handle_external_dependencies(Task *task, int delay) {
    // Simulating an external dependency with a sleep (replace this in real scenarios)
    usleep(delay * 1000); 
    if (delay % 2 == 0) { // Randomized failure simulation
        transition_task_state(task, FAILED);
        log_event("Task failed due to external dependency.");
    } else {
        transition_task_state(task, EXECUTING);
        log_event("Task is executing.");
        usleep(100000); // Simulate work being done
        transition_task_state(task, COMPLETED);
        log_event("Task completed successfully.");
    }
}

void process_tasks(TaskCollection *collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->count; ++i) {
        Task *task = collection->tasks[i];

        if (task->state == INIT) {
            handle_external_dependencies(task, task->priority_level);
        }
    }

    pthread_mutex_unlock(&collection->mutex);
}

int main() {
    TaskCollection *collection = create_task_collection(10);

    add_task(collection, create_task("Task1", 3));
    add_task(collection, create_task("Task2", 1));

    process_tasks(collection);

    free_task_collection(collection);

    return 0;
}
