#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

// Enum for status indicator
typedef enum {
    STATUS_NEW,
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_DELETED
} Status;

// Custom memory allocator interface
typedef struct {
    void *(*allocate)(size_t size);
    void (*deallocate)(void *ptr, size_t size);
} MemoryAllocator;

// Record structure
typedef struct Record {
    short short_field;
    int int_field;
    float float_field;
    Status status;
    uint64_t metadata;
    int key;
    int offset;
    struct Record* next;
} Record;

// Linked list of records with thread safety mechanisms
typedef struct {
    Record *head;
    pthread_rwlock_t lock;
    MemoryAllocator allocator;
} RecordList;

// Hash function for metadata computation
uint64_t hash_function(int key, int index) {
    return ((uint64_t)key << 32) | (uint64_t)index;
}

// Custom memory allocator implementation
void* custom_allocate(size_t size) {
    // Implement a simple fixed-size and variable-sized allocation strategy
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_deallocate(void *ptr, size_t size) {
    free(ptr);
}

// Initialize the memory allocator
MemoryAllocator init_allocator() {
    MemoryAllocator allocator = {custom_allocate, custom_deallocate};
    return allocator;
}

// Function to initialize a record with random values
Record* create_record(int key, int index, MemoryAllocator allocator) {
    Record *record = (Record*)allocator.allocate(sizeof(Record));
    if (!record) {
        perror("Failed to allocate record");
        exit(EXIT_FAILURE);
    }

    // Initialize fields with random values
    srand(time(NULL) ^ (intptr_t)record);  // Seed based on time and pointer address
    record->short_field = rand() % 100;
    record->int_field = rand() % 1000;
    record->float_field = ((float)rand() / RAND_MAX) * 100.0f;
    record->status = (Status)(rand() % 4);
    record->metadata = hash_function(key, index);
    record->key = key;
    record->next = NULL;

    return record;
}

// Function to add a record to the list
void add_record(RecordList *list, int key, int index) {
    pthread_rwlock_wrlock(&list->lock);

    Record *new_record = create_record(key, index, list->allocator);

    if (!list->head) {
        list->head = new_record;
    } else {
        Record *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_record;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Function to iterate over records
void iterate_records(RecordList *list, void (*process)(Record*)) {
    pthread_rwlock_rdlock(&list->lock);

    Record *current = list->head;
    while (current) {
        process(current);
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Function to initialize the record list
void init_record_list(RecordList *list, MemoryAllocator allocator) {
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    list->allocator = allocator;
}

// Function to destroy the record list and free memory
void destroy_record_list(RecordList *list) {
    pthread_rwlock_wrlock(&list->lock);

    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        list->allocator.deallocate(current, sizeof(Record));
        current = next;
    }

    list->head = NULL;
    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
}

// Example process function for iteration
void print_record(Record *record) {
    printf("Key: %d, Offset: %d, Short: %hd, Int: %d, Float: %.2f, Status: %d, Metadata: %" PRIu64 "\n",
           record->key, record->offset, record->short_field, record->int_field,
           record->float_field, record->status, record->metadata);
}

// Main function to demonstrate usage
int main() {
    RecordList list;
    MemoryAllocator allocator = init_allocator();
    init_record_list(&list, allocator);

    // Add records
    for (int i = 0; i < 10; ++i) {
        add_record(&list, i * 10 - 5, i);
    }

    // Iterate and print records
    iterate_records(&list, print_record);

    // Clean up
    destroy_record_list(&list);

    return 0;
}
