#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TASK_NAME_LENGTH 256
#define MAX_TASK_SIZE 1024
#define MAX_TASKS 1000

typedef struct Task {
    char name[MAX_TASK_NAME_LENGTH];
    int priority;
    time_t timestamp;
    int payload;
    size_t size;
    struct Task* next;
} Task;

typedef struct {
    Task* head;
    pthread_mutex_t lock;
    size_t task_count;
    void (*notification_callback)(size_t);
    size_t notification_threshold;
} TaskQueue;

// Function to create a new task
Task* create_task(const char* name, int priority, time_t timestamp, int payload) {
    if (strlen(name) + sizeof(int) * 3 > MAX_TASK_SIZE - sizeof(struct Task)) {
        return NULL; // Exceeds memory constraint
    }

    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        return NULL;
    }

    strncpy(task->name, name, MAX_TASK_NAME_LENGTH);
    task->priority = priority;
    task->timestamp = timestamp;
    task->payload = payload;
    task->size = sizeof(struct Task) + strlen(name) + 1 + sizeof(int) * 3;

    task->next = NULL;
    return task;
}

// Initialize the task queue
void init_task_queue(TaskQueue* queue, void (*notification_callback)(size_t), size_t notification_threshold) {
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = NULL;
    queue->task_count = 0;
    queue->notification_callback = notification_callback;
    queue->notification_threshold = notification_threshold;
}

// Add a task to the queue
int add_task(TaskQueue* queue, Task* task) {
    pthread_mutex_lock(&queue->lock);

    if (queue->task_count >= MAX_TASKS || !task) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is full or invalid task
    }

    task->next = queue->head;
    queue->head = task;
    queue->task_count++;

    if (queue->task_count >= queue->notification_threshold && queue->notification_callback) {
        queue->notification_callback(queue->task_count);
    }

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

// Remove a task from the queue by priority and timestamp
int remove_task(TaskQueue* queue, int priority, time_t timestamp) {
    pthread_mutex_lock(&queue->lock);

    Task *current = queue->head, *prev = NULL;
    while (current != NULL && !(current->priority == priority && current->timestamp == timestamp)) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Task not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        queue->head = current->next;
    }

    free(current);
    queue->task_count--;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

// Serialize task data for storage or transmission
void serialize_task(Task* task, char** buffer) {
    if (!task) {
        *buffer = NULL;
        return;
    }

    size_t total_size = sizeof(int) + MAX_TASK_NAME_LENGTH + sizeof(time_t) + sizeof(int);
    *buffer = (char*)malloc(total_size);
    if (!*buffer) {
        return; // Memory allocation failed
    }

    int offset = 0;
    memcpy(*buffer + offset, &task->priority, sizeof(int));
    offset += sizeof(int);

    memcpy(*buffer + offset, task->name, MAX_TASK_NAME_LENGTH);
    offset += MAX_TASK_NAME_LENGTH;

    memcpy(*buffer + offset, &task->timestamp, sizeof(time_t));
    offset += sizeof(time_t);

    memcpy(*buffer + offset, &task->payload, sizeof(int));
}

// Background processing function
void* process_tasks(void* arg) {
    TaskQueue* queue = (TaskQueue*)arg;

    while (1) {
        pthread_mutex_lock(&queue->lock);

        Task* current = queue->head;
        while (current) {
            if (/* condition to check high priority and time */) {
                // Process the task
                printf("Processing task: %s\n", current->name);

                remove_task(queue, current->priority, current->timestamp);
                free(current);

                // Move to next task
                current = queue->head;
            } else {
                break; // Exit if no high-priority task is found
            }
        }

        pthread_mutex_unlock(&queue->lock);

        sleep(1); // Simulate processing delay
    }

    return NULL;
}

// Cleanup the task queue
void cleanup_task_queue(TaskQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    Task* current = queue->head;
    while (current != NULL) {
        Task* next = current->next;
        free(current);
        current = next;
    }

    queue->task_count = 0;
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
}

// Notification callback example
void notification_callback(size_t task_count) {
    printf("Notification: Task count is at %zu\n", task_count);
}
