#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct {
    double number;
    char *char_array;
} Node;

double gaussian_sample(double mean, double stddev) {
    static double V1, V2, S;
    static int phase = 0;
    double X;

    if (phase == 0) {
        do {
            double U1 = (double)rand() / RAND_MAX;
            double U2 = (double)rand() / RAND_MAX;

            V1 = 2 * U1 - 1;
            V2 = 2 * U2 - 1;
            S = V1 * V1 + V2 * V2;
        } while (S >= 1 || S == 0);

        X = V1 * sqrt(-2 * log(S) / S);
    } else {
        X = V2 * sqrt(-2 * log(S) / S);
    }

    phase = 1 - phase;

    return mean + stddev * X;
}

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

Node* create_nodes(int num_nodes, double mean_size, double stddev_size, size_t max_memory_usage) {
    if (num_nodes <= 0 || mean_size < 0 || stddev_size < 0 || max_memory_usage == 0) {
        return NULL;
    }

    Node *nodes = malloc(num_nodes * sizeof(Node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes array.\n");
        return NULL;
    }

    size_t total_allocated_memory = 0;
    initialize_random_seed();

    for (int i = 0; i < num_nodes; ++i) {
        double char_array_size = gaussian_sample(mean_size, stddev_size);
        if (char_array_size <= 0) char_array_size = 1;

        size_t required_memory = sizeof(char) * (size_t)char_array_size;
        total_allocated_memory += required_memory;

        if (total_allocated_memory > max_memory_usage) {
            fprintf(stderr, "Memory usage exceeded limit at node %d.\n", i);
            break; // Prevent exceeding the memory limit
        }

        nodes[i].number = (double)i;  // Example of assigning a number
        nodes[i].char_array = malloc(required_memory);

        if (!nodes[i].char_array) {
            fprintf(stderr, "Memory allocation failed for char array at node %d.\n", i);
            break;
        }

        for (size_t j = 0; j < (size_t)char_array_size; ++j) {
            nodes[i].char_array[j] = rand() % 128; // Random ASCII character
        }
    }

    return nodes;
}

void free_nodes(Node *nodes, int num_nodes) {
    if (!nodes) return;

    for (int i = 0; i < num_nodes; ++i) {
        if (nodes[i].char_array != NULL) {
            free(nodes[i].char_array);
        }
    }

    free(nodes);
}

void log_memory_usage(size_t total_allocated_memory, size_t interval_size, int iteration) {
    if (iteration % interval_size == 0) {
        printf("Iteration %d: Total Memory Usage = %zu bytes\n", iteration, total_allocated_memory);
    }
}

int main() {
    const int num_nodes = 100000; // Number of nodes to create
    const double mean_size = 50.0;
    const double stddev_size = 10.0;
    const size_t max_memory_usage = 100 * 1024 * 1024; // 100 MB limit

    Node* nodes = create_nodes(num_nodes, mean_size, stddev_size, max_memory_usage);

    if (nodes) {
        for (int i = 0; i < num_nodes; ++i) {
            // Example processing loop
            log_memory_usage(sizeof(Node) * i + (nodes[i].char_array ? sizeof(char) * strlen(nodes[i].char_array) : 0), 10000, i);
        }

        free_nodes(nodes, num_nodes);
    } else {
        fprintf(stderr, "Failed to create nodes.\n");
    }

    return 0;
}
```

### Explanation of Code:
- **Gaussian Sampling**: The `gaussian_sample` function generates a random sample from a Gaussian distribution using the Box-Muller transform.
- **Memory Management**: The function `create_nodes` allocates memory for an array of `Node` structures and their associated `char` arrays, ensuring that total allocated memory does not exceed the specified limit. It uses logging to track memory usage periodically.
- **Error Handling**: Checks for allocation failures are included with appropriate error messages.
- **Memory Cleanup**: The function `free_nodes` deallocates all dynamically allocated memory once processing is complete.

### Key Considerations:
- Ensure that random seed initialization (`initialize_random_seed`) is called before using the Gaussian sampling to ensure varied results across runs.
- Adjust parameters such as `num_nodes`, `mean_size`, and `max_memory_usage` to suit specific application requirements.']

