    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to allocate memory from the pool
void* pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    PoolNode *node = pool->free_list;
    if (node) {
        pool->free_list = node->next;
        void *data = node->data;
        free(node);
        pthread_mutex_unlock(&pool->lock);
        return data;
    }

    // Allocate new block
    void *data = malloc(pool->block_size);
    if (!data) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;  // Handle failure gracefully
    }

    pthread_mutex_unlock(&pool->lock);
    return data;
}

// Function to free memory back to the pool
void pool_free(MemoryPool *pool, void *data) {
    pthread_mutex_lock(&pool->lock);

    PoolNode *node = (PoolNode*)malloc(sizeof(PoolNode));
    if (!node) {
        pthread_mutex_unlock(&pool->lock);
        return;  // Handle failure gracefully
    }
    node->data = data;
    node->next = pool->free_list;
    pool->free_list = node;

    pthread_mutex_unlock(&pool->lock);
}

// Function to initialize the pipeline with dynamic memory allocation
void* initialize_pipeline(Config config) {
    MemoryPool *pool = NULL;

    if (strcmp(config.allocation_strategy, "pool") == 0) {
        pool = create_memory_pool(sizeof(int)); // Adjust block size as needed
    }

    // Process each record within the limits specified by config
    for (size_t i = 0; i < config.max_records; ++i) {
        int *record = NULL;

        if (pool) {
            record = pool_alloc(pool);
            if (!record) {
                // Handle allocation failure gracefully
                break;
            }
        } else {
            record = malloc(sizeof(int));
            if (!record) {
                fprintf(stderr, "Memory allocation failed\n");
                break;  // Handle failure gracefully
            }
        }

        *record = (rand() % (config.max_value - config.min_value + 1)) + config.min_value;

        // Here would go the processing/transformation of the record

        if (pool) {
            pool_free(pool, record);
        } else {
            free(record);
        }
    }

    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }

    return NULL;  // Return appropriate value or status
}

// Example usage
int main() {
    Config config = {1000, 1, 100, "pool"};

    // Initialize pipeline in a thread-safe manner if needed
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)initialize_pipeline, &config);
    pthread_join(thread, NULL);

    return 0;
}
```

This code sets up a dynamic memory allocation strategy using a pool-based approach to minimize fragmentation and improve performance under heavy load. It handles memory allocation failures gracefully by providing feedback through standard error output. The structure also allows for thread-safe operations suitable for a high-throughput data processing pipeline.']

