// Define a simple LRU Cache
template<typename K, typename V>
class LRUCache {
private:
    struct Node {
        K key;
        V value;
        Node* prev;
        Node* next;
        Node(K k, V v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    std::unordered_map<K, Node*> cacheMap;
    Node *head, *tail;
    size_t capacity;

public:
    LRUCache(size_t cap) : capacity(cap), head(new Node("", "")), tail(new Node("", "")) {
        head->next = tail;
        tail->prev = head;
    }

    ~LRUCache() {
        clear();
        delete head;
        delete tail;
    }

    void put(const K &key, const V &value) {
        auto it = cacheMap.find(key);
        if (it != cacheMap.end()) {
            Node* node = it->second;
            node->value = value;
            moveToHead(node);
        } else {
            Node* newNode = new Node(key, value);
            cacheMap[key] = newNode;
            addToHead(newNode);

            if (cacheMap.size() > capacity) {
                Node* lru = tail->prev;
                removeNode(lru);
                cacheMap.erase(lru->key);
                delete lru;
            }
        }
    }

    bool get(const K &key, V &value) {
        auto it = cacheMap.find(key);
        if (it != cacheMap.end()) {
            Node* node = it->second;
            moveToHead(node);
            value = node->value;
            return true;
        }
        return false;
    }

private:
    void addToHead(Node *node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

    void removeNode(Node* node) {
        Node* prev = node->prev;
        Node* next = node->next;
        prev->next = next;
        next->prev = prev;
    }

    void moveToHead(Node *node) {
        removeNode(node);
        addToHead(node);
    }

    void clear() {
        Node* current = head->next;
        while (current != tail) {
            Node* temp = current;
            current = current->next;
            delete temp;
        }
        cacheMap.clear();
    }
};

// Process function
void processTrafficAndInsertString(std::forward_list<std::string>& list, const std::string& needle, 
                                   const std::string& haystack, const std::string& insertion_string) {
    static std::mutex mtx;

    // Lock for thread-safety
    std::lock_guard<std::mutex> lock(mtx);

    bool inserted = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == needle) {
            auto nextIt = std::next(it);
            list.insert_after(it, insertion_string);
            inserted = true;
            break;
        }
    }

    if (!inserted) {
        list.push_back(haystack);
        list.push_front(insertion_string);
    }
}

