bool validateOAuth2Token(const std::unordered_map<std::string, std::string>& tokenInfo) {
    const auto& access_token = tokenInfo.at("access_token");
    const auto& expires_in = tokenInfo.at("expires_in");
    const auto& token_type = tokenInfo.at("token_type");

    if (token_type != "Bearer" || !std::all_of(expires_in.begin(), expires_in.end(), ::isdigit)) {
        std::cerr << "Invalid token type or expiration value." << std::endl;
        return false;
    }

    int expiresInValue = std::stoi(expires_in);
    if (expiresInValue <= 0) {
