['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1048576 // Example limit: 1MB
#define RESIZE_THRESHOLD 0.75    // Resize when 75% full

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    size_t count;
    double load_factor;
} HashTable;

// Function prototypes
HashTable* init_hash_table(size_t initial_capacity, double load_factor);
void free_hash_table(HashTable *table);
int hash_function(int key, size_t capacity);
Node* create_node(const Record *record);
void insert_record(HashTable *table, const Record *record);
Record* find_record(HashTable *table, int key);
void resize_hash_table(HashTable *table);
void log_memory_usage(size_t used_memory);
void export_to_file(const char *filename, HashTable *table);

// Initialize the hash table
HashTable* init_hash_table(size_t initial_capacity, double load_factor) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node **)calloc(initial_capacity, sizeof(Node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;
    table->load_factor = load_factor;

    return table;
}

// Free the hash table
void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

// Hash function
int hash_function(int key, size_t capacity) {
    return key % capacity;
}

// Create a new node
Node* create_node(const Record *record) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;

    node->record.key = record->key;
    node->record.offset = record->offset;
    node->next = NULL;

    return node;
}

// Insert a record into the hash table
void insert_record(HashTable *table, const Record *record) {
    int index = hash_function(record->key, table->capacity);
    Node *node = create_node(record);

    if (!node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return;
    }

    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->count++;

    // Check if resizing is needed
    double current_load_factor = (double)table->count / table->capacity;
    if (current_load_factor > table->load_factor) {
        resize_hash_table(table);
    }
}

// Find a record by key
Record* find_record(HashTable *table, int key) {
    int index = hash_function(key, table->capacity);
    Node *node = table->buckets[index];

    while (node) {
        if (node->record.key == key) {
            return &node->record;
        }
        node = node->next;
    }

    return NULL; // Record not found
}

// Resize the hash table
void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Node **new_buckets = (Node **)calloc(new_capacity, sizeof(Node *));
    if (!new_buckets) {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        return;
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node) {
            Node *next_node = node->next;
            int new_index = hash_function(node->record.key, new_capacity);
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Log memory usage
void log_memory_usage(size_t used_memory) {
    printf("Current memory usage: %zu bytes\n", used_memory);
}

// Export hash table to a file
void export_to_file(const char *filename, HashTable *table) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *node = table->buckets[i];
        while (node) {
            fprintf(file, "%d,%ld\n", node->record.key, node->record.offset);
            node = node->next;
        }
    }

    fclose(file);
}

// Example usage
int main() {
    HashTable *table = init_hash_table(16, RESIZE_THRESHOLD);

    if (!table) {
        fprintf(stderr, "Failed to initialize hash table.\n");
        return EXIT_FAILURE;
    }

    // Simulate adding records from an external data source
    for (int i = 0; i < 100; ++i) {
        Record record = { .key = i, .offset = i * 100 };
        insert_record(table, &record);
    }

    // Example of finding a record
    Record *found = find_record(table, 42);
    if (found) {
        printf("Found record: key=%d, offset=%ld\n", found->key, found->offset);
    } else {
        printf("Record not found.\n");
    }

    // Export to file
    export_to_file("records.txt", table);

    // Free resources
    free_hash_table(table);

    return EXIT_SUCCESS;
}
