// External logging library (mockup)
void log_message(const char *message) {
    printf("LOG: %s\n", message);
}

typedef struct access_log {
    short event_type;
    float latency_value;
    struct access_log *next;
} access_log_t;

typedef struct file_entry {
    char buffer[256];
    unsigned long timestamp;
    access_log_t *access_logs_head;
    pthread_mutex_t lock;
} file_entry_t;

typedef struct record {
    int value;
} record_t;

typedef struct file_metadata {
    time_t timestamp;
    char unique_id[16];
} file_metadata_t;

#define INITIAL_RECORD_COUNT 10
#define INITIAL_FILE_METADATA_COUNT 5
#define HASH_TABLE_SIZE 50

// Global variables
record_t *records = NULL;
size_t record_count = 0;
file_metadata_t *file_metadata_array = NULL;
size_t file_metadata_count = 0;
file_entry_t **hash_table = NULL;

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Memory pool structure
typedef struct memory_pool {
    void *pool;
    size_t block_size;
    size_t total_blocks;
} memory_pool_t;

memory_pool_t record_pool, file_entry_pool;

void init_memory_pool(memory_pool_t *pool, size_t block_size, size_t initial_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = initial_blocks;
    pool->pool = malloc(block_size * initial_blocks);
}

void *allocate_from_pool(memory_pool_t *pool) {
    static void *free_ptr = NULL;
    if (!free_ptr) free_ptr = pool->pool;

    if (free_ptr + pool->block_size > pool->pool + pool->total_blocks * pool->block_size) {
        return malloc(pool->block_size);
    }

    void *block = free_ptr;
    free_ptr += pool->block_size;
    return block;
}

void deallocate_from_pool(memory_pool_t *pool, void *ptr) {
    // Implement a simple stack-based deallocation strategy
    if (ptr >= pool->pool && ptr < pool->pool + pool->total_blocks * pool->block_size) {
        free_ptr = ptr;
    } else {
        free(ptr);
    }
}

void init_data_management_system(size_t record_count, size_t file_metadata_count) {
    records = malloc(record_count * sizeof(record_t));
    if (!records) exit(EXIT_FAILURE);

    for (size_t i = 0; i < record_count; i++) {
        records[i].value = rand() % 100 + 1;
    }

    file_metadata_array = malloc(file_metadata_count * sizeof(file_metadata_t));
    if (!file_metadata_array) exit(EXIT_FAILURE);

    time_t cumulative_time = 0;
    for (size_t i = 0; i < file_metadata_count; i++) {
        cumulative_time += rand() % 10 + 1; // Random offset
        file_metadata_array[i].timestamp = cumulative_time;

        snprintf(file_metadata_array[i].unique_id, sizeof(file_metadata_array[i].unique_id), "ID%zu", i);
    }

    hash_table = malloc(HASH_TABLE_SIZE * sizeof(file_entry_t *));
    if (!hash_table) exit(EXIT_FAILURE);

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hash_table[i] = NULL;
    }

    init_memory_pool(&record_pool, sizeof(record_t), record_count);
    init_memory_pool(&file_entry_pool, sizeof(file_entry_t), record_count);

    pthread_mutex_init(&hash_table_lock, NULL);
}

void cleanup_data_management_system() {
    free(records);
    free(file_metadata_array);
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hash_table[i]) {
            access_log_t *log_entry = hash_table[i]->access_logs_head;
            while (log_entry) {
                access_log_t *to_delete = log_entry;
                log_entry = log_entry->next;
                deallocate_from_pool(&file_entry_pool, to_delete);
            }
            pthread_mutex_destroy(&(hash_table[i]->lock));
            deallocate_from_pool(&file_entry_pool, hash_table[i]);
        }
    }
    free(hash_table);

    free(record_pool.pool);
    free(file_entry_pool.pool);
}

void add_file_entry(const char *buffer_content) {
    pthread_mutex_lock(&hash_table_lock);

    size_t index = (uintptr_t)(rand() % HASH_TABLE_SIZE); // Simplified hash function
    file_entry_t *entry = allocate_from_pool(&file_entry_pool);

    if (!entry) exit(EXIT_FAILURE);
    entry->timestamp = time(NULL);
    strncpy(entry->buffer, buffer_content, sizeof(entry->buffer));
    entry->access_logs_head = NULL;

    pthread_mutex_init(&(entry->lock), NULL);
    hash_table[index] = entry;

    log_message("Added file entry.");
    pthread_mutex_unlock(&hash_table_lock);
}

void remove_file_entry(size_t index) {
    pthread_mutex_lock(&hash_table_lock);

    if (index >= HASH_TABLE_SIZE || !hash_table[index]) {
        pthread_mutex_unlock(&hash_table_lock);
        return;
    }

    file_entry_t *entry = hash_table[index];
    access_log_t *log_entry = entry->access_logs_head;

    while (log_entry) {
        access_log_t *to_delete = log_entry;
        log_entry = log_entry->next;
        deallocate_from_pool(&file_entry_pool, to_delete);
    }

    pthread_mutex_destroy(&(entry->lock));
    hash_table[index] = NULL;
    deallocate_from_pool(&file_entry_pool, entry);

    log_message("Removed file entry.");
    pthread_mutex_unlock(&hash_table_lock);
}

void periodic_save_to_disk() {
    while (1) {
        sleep(60); // Save every 60 seconds
        pthread_mutex_lock(&hash_table_lock);

        for (int i = 0; i < HASH_TABLE_SIZE; i++) {
            if (hash_table[i]) {
                log_message("Saving file entry to disk.");
                // Implement actual save logic here.
            }
        }

        pthread_mutex_unlock(&hash_table_lock);
    }
}

void *async_file_access(void *arg) {
    size_t index = *(size_t *)arg;
    free(arg);

    pthread_mutex_lock(&hash_table_lock);

    if (index < HASH_TABLE_SIZE && hash_table[index]) {
        log_message("Accessing file entry asynchronously.");
        // Perform non-blocking operations here.
    }

    pthread_mutex_unlock(&hash_table_lock);
    return NULL;
}

int main() {
    srand(time(NULL));

    init_data_management_system(INITIAL_RECORD_COUNT, INITIAL_FILE_METADATA_COUNT);

    pthread_t save_thread;
    pthread_create(&save_thread, NULL, periodic_save_to_disk, NULL);

    // Example usage
    add_file_entry("Sample buffer content");

    size_t index = 0;
    pthread_t async_thread;
    pthread_create(&async_thread, NULL, async_file_access, &index);

    pthread_join(async_thread, NULL);
    pthread_cancel(save_thread); // For demonstration; normally wait for thread to finish

    cleanup_data_management_system();

    return 0;
}
