pthread_rwlock_t rwlock;

void init_rwlock() {
    pthread_rwlock_init(&rwlock, NULL);
}

void update_setting_with_rwlock(ConfigSetting *setting, int integer_val, double dbl_val) {
    pthread_rwlock_wrlock(&rwlock);
    setting->integer = integer_val;
    setting->dbl = dbl_val;
    pthread_rwlock_unlock(&rwlock);
}

void read_setting_with_rwlock(ConfigSetting *setting) {
    pthread_rwlock_rdlock(&rwlock);
    printf("Integer: %d, Double: %.2f\n", setting->integer, setting->dbl);
    pthread_rwlock_unlock(&rwlock);
}

// Cleanup function
void free_settings(ConfigSetting *settings, size_t num_settings) {
    for (size_t i = 0; i < num_settings; ++i) {
        free(settings[i].name);
        pthread_mutex_destroy(&settings[i].lock);
    }
    custom_free(settings);
    pthread_rwlock_destroy(&rwlock);
}

// Entry point
int main() {
    const char *setting_names[] = {"Setting1", "Setting2"};
    size_t num_settings = sizeof(setting_names) / sizeof(const char*);

    init_rwlock();
    ConfigSetting *settings = init_settings(setting_names, num_settings);

    fetch_settings_from_server(settings, num_settings);

    update_setting_with_rwlock(&settings[0], 42, 3.14);
    read_setting_with_rwlock(&settings[0]);

    free_settings(settings, num_settings);

    return 0;
}
```

