['Below is a C implementation that addresses your requirements for managing dynamic memory allocation and initialization of multiple linked lists along with a hash table to map nodes by their `char*` pointers.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct Node {
    double value;
    char *data;
    struct Node *next;
} Node;

typedef struct HashTable {
    Node **buckets;
    pthread_mutex_t locks[HASH_TABLE_SIZE];
} HashTable;

// Initialize a hash table
HashTable* init_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(HASH_TABLE_SIZE, sizeof(Node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

// Hash function
unsigned int hash_function(const char *key, size_t len) {
    unsigned int hash = 0;
    for (size_t i = 0; i < len; ++i) {
        hash = (hash * 31) + key[i];
    }
    return hash % HASH_TABLE_SIZE;
}

// Add a node to the linked list in a thread-safe manner
int add_node(HashTable *table, double value, const char *data) {
    unsigned int index = hash_function(data, strlen(data));

    pthread_mutex_lock(&table->locks[index]);

    Node *newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&table->locks[index]);
        return -1;
    }

    newNode->value = value;
    char *data_copy = strdup(data);
    if (!data_copy) {
        free(newNode);
        pthread_mutex_unlock(&table->locks[index]);
        return -1;
    }
    newNode->data = data_copy;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->locks[index]);

    return 0;
}

// Free the hash table and all associated nodes
void free_hash_table(HashTable *table) {
    if (!table) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        Node *current = table->buckets[i];
        while (current) {
            Node *temp = current;
            current = current->next;
            free(temp->data);
            free(temp);
        }

        pthread_mutex_unlock(&table->locks[i]);
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table->buckets);
    free(table);
}

// Initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Generate a random double within a specified range [min, max]
double generate_random_double(double min, double max) {
    return min + ((max - min) * rand()) / RAND_MAX;
}

int main() {
    // Example usage

    HashTable *table = init_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return EXIT_FAILURE;
    }

    init_random();

    const double min_value = 0.0;
    const double max_value = 100.0;

    // Example: adding nodes
    for (int i = 0; i < 10; ++i) {
        char buffer[20];
        snprintf(buffer, sizeof(buffer), "key%d", i);

        double random_value = generate_random_double(min_value, max_value);

        if (add_node(table, random_value, buffer) != 0) {
            fprintf(stderr, "Failed to add node for key: %s\n", buffer);
        }
    }

    // Cleanup
    free_hash_table(table);

    return EXIT_SUCCESS;
}
```

### Key Considerations:

- **Thread Safety**: The code uses `pthread_mutex_t` arrays to ensure thread safety during concurrent insertions.

- **Memory Management**: Allocates nodes dynamically and handles allocation failures gracefully.

- **Hash Table Implementation**: Chaining is used, which allows for handling collisions without excessive performance penalties under moderate load.

- **Random Number Generation**: A simple random number generator initializes the `double` values of each node within a specified range.

- **Resource Cleanup**: Properly frees memory to prevent leaks.

This implementation aims to balance efficiency and safety in concurrent environments while minimizing fragmentation. Adjustments might be necessary depending on specific application constraints or performance benchmarks.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Configuration structure for memory pool
typedef struct {
    size_t max_records;
    int min_value;
    int max_value;
    bool use_fixed_allocation;
} Config;

// Node in the memory pool linked list
typedef struct MemoryNode {
    void *data;
    struct MemoryNode *next;
} MemoryNode;

// Pool structure
typedef struct {
    MemoryNode *free_list_head;
    size_t node_size;
    pthread_mutex_t lock;
} MemoryPool;

// Function declarations
MemoryPool* create_memory_pool(size_t max_records, size_t element_size);
void destroy_memory_pool(MemoryPool *pool);
void* allocate_from_pool(MemoryPool *pool);
void free_to_pool(MemoryPool *pool, void *ptr);

// Create a memory pool with preallocated nodes
MemoryPool* create_memory_pool(size_t max_records, size_t element_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->free_list_head = NULL;
    pool->node_size = element_size + sizeof(MemoryNode);
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < max_records; ++i) {
        MemoryNode *node = malloc(pool->node_size);
        if (!node) {
            destroy_memory_pool(pool);
            return NULL;
        }

        node->data = ((char*)node + sizeof(MemoryNode));
        node->next = pool->free_list_head;
        pool->free_list_head = node;
    }

    return pool;
}

// Destroy the memory pool and free all nodes
void destroy_memory_pool(MemoryPool *pool) {
    MemoryNode *current = pool->free_list_head;
    while (current) {
        MemoryNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->free_list_head) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    MemoryNode *node = pool->free_list_head;
    pool->free_list_head = node->next;

    void *data_ptr = node->data;
    pthread_mutex_unlock(&pool->lock);

    return data_ptr;
}

// Free memory back to the pool
void free_to_pool(MemoryPool *pool, void *ptr) {
    if (!ptr) return;

    MemoryNode *node = (MemoryNode*)((char*)ptr - sizeof(MemoryNode));

    pthread_mutex_lock(&pool->lock);
    node->next = pool->free_list_head;
    pool->free_list_head = node;
    pthread_mutex_unlock(&pool->lock);
}

// Usage example
void* data_processing_thread(void *arg) {
    Config config = *(Config*)arg;
    MemoryPool *pool = create_memory_pool(config.max_records, sizeof(int));

    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return NULL;
    }

    int *data = (int*)allocate_from_pool(pool);
    if (!data) {
        fprintf(stderr, "Allocation from memory pool failed\n");
        destroy_memory_pool(pool);
        return NULL;
    }

    // Simulate data processing
    for (int i = 0; i < config.max_records; ++i) {
        *data = rand() % (config.max_value - config.min_value + 1) + config.min_value;

        // Process the data...

        free_to_pool(pool, data);

        data = (int*)allocate_from_pool(pool);
    }

    destroy_memory_pool(pool);
    return NULL;
}

// Main function to start threads
int main() {
    Config config = {1000, 1, 100, true};

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_processing_thread, &config) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);
    return EXIT_SUCCESS;
}
```

