#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define INITIAL_POOL_SIZE 1024

typedef struct {
    int key;
} Record;

typedef struct MetadataNode {
    char *metadata;
    struct MetadataNode *next;
} MetadataNode;

typedef struct {
    short s_value;
    int i_value;
    float f_value;
    time_t timestamp;
    MetadataNode *metadata;
    int status; // Example: 0 = inactive, 1 = active
} RecordData;

typedef struct Node {
    long offset;
    Record record;
    RecordData data;
    struct Node* next;
} Node;

typedef struct {
    void **pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool create_memory_pool(size_t initial_size, size_t block_size) {
    MemoryPool mp;
    mp.pool = malloc(initial_size * sizeof(void*));
    mp.block_size = block_size;
    mp.pool_size = initial_size;
    pthread_mutex_init(&mp.lock, NULL);
    return mp;
}

void* pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->pool_size == 0) {
        size_t new_size = (pool->pool_size == 0) ? INITIAL_POOL_SIZE : pool->pool_size * 2;
        void **new_pool = realloc(pool->pool, new_size * sizeof(void*));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Memory exhaustion handling
        }
        memset(new_pool + pool->pool_size, 0, (new_size - pool->pool_size) * sizeof(void*));
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }
    void *block = pool->pool[--pool->pool_size];
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void pool_free(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    pool->pool[pool->pool_size++] = block;
    pthread_mutex_unlock(&pool->lock);
}

Node* create_node(MemoryPool *mp, int key, float weight_avg) {
    Node *node = (Node*)pool_alloc(mp);
    if (!node) return NULL;

    node->offset = (long)(key * weight_avg); // Simplified initialization
    node->record.key = key;
    node->data.s_value = rand() % 1000;
    node->data.i_value = rand() % 10000;
    node->data.f_value = (float)rand() / RAND_MAX * 100.0f;
    node->data.timestamp = time(NULL);
    node->data.metadata = NULL; // Will be allocated separately
    node->data.status = rand() % 2; // Random status

    node->data.metadata = pool_alloc(mp);
    if (!node->data.metadata) {
        free(node); // Clean up in case of allocation failure
        return NULL;
    }

    MetadataNode *metadata_node = (MetadataNode*)node->data.metadata;
    metadata_node->metadata = malloc(MAX_METADATA_LENGTH);
    snprintf(metadata_node->metadata, MAX_METADATA_LENGTH, "Meta_%d", key);
    metadata_node->next = NULL;

    node->next = NULL; // Initially no next node
    return node;
}

void initialize_list(MemoryPool *mp, int num_elements) {
    if (!mp || num_elements <= 0) return;

    Node *head = NULL, *tail = NULL;
    float weight_avg = 1.5f; // Example dynamic adjustment factor

    for (int i = 0; i < num_elements; ++i) {
        int key = rand() % 10000;
        Node *node = create_node(mp, key, weight_avg);
        if (!node) break;

        if (!head) head = node;
        if (tail) tail->next = node;
        tail = node;

        // Update weighted average
        weight_avg = ((weight_avg * i) + key) / (i + 1.0f);
    }

    printf("Initialized %d nodes\n", num_elements);
}

void free_list(Node *head, MemoryPool *mp) {
    Node *current = head;
    while (current) {
        MetadataNode *metadata_node = (MetadataNode*)current->data.metadata;
        if (metadata_node->metadata) free(metadata_node->metadata);

        Node *next = current->next;
        pool_free(mp, current);
        pool_free(mp, metadata_node);
        current = next;
    }
}

int main() {
    srand(time(NULL));

    MemoryPool mp = create_memory_pool(INITIAL_POOL_SIZE, sizeof(Node));
    initialize_list(&mp, 100); // Initialize list with 100 elements

    // Additional operations like resizing can be implemented here...

    Node *head; // Assume this is managed elsewhere
    free_list(head, &mp);

    pthread_mutex_destroy(&mp.lock);
    free(mp.pool);
    return 0;
}
```

