void rehash_if_needed(HashMap* map);

// Initialize a memory pool for resource management
void initialize_memory_pool(MemoryPool* mp, size_t pool_size) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->memory_pool = malloc(pool_size);
    if (mp->memory_pool == NULL) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mp->pool_size = pool_size;
    mp->free_list_head = (void**)mp->memory_pool;
    for (size_t i = 0; i < pool_size / sizeof(void*); ++i) {
        ((void**)(mp->memory_pool))[i] = (void*)((char*)mp->memory_pool + ((i+1) * sizeof(void*)));
    }
    ((void**)((char*)mp->memory_pool + pool_size - sizeof(void*)))[0] = NULL; // Terminate the free list
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_list_head == NULL) {
        pthread_mutex_unlock(&mp->lock);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }

    void** free_ptr = mp->free_list_head;
    mp->free_list_head = *mp->free_list_head;
    pthread_mutex_unlock(&mp->lock);

    if (size > sizeof(void*)) {
        // Align for cache optimization
        char* aligned_memory = (char*)free_ptr + ((sizeof(void*) - ((uintptr_t)free_ptr & (sizeof(void*)-1))) % sizeof(void*));
        return (void*)(aligned_memory);
    }

    return free_ptr;
}

// Deallocate memory back to the pool
void deallocate_to_pool(MemoryPool* mp, void* ptr) {
    pthread_mutex_lock(&mp->lock);
    *(void**)ptr = mp->free_list_head;  // Add the pointer at the start of the free list
    mp->free_list_head = (void**)ptr;
    pthread_mutex_unlock(&mp->lock);
}

// Initialize hash map for event records
void initialize_hash_map(HashMap* map) {
    pthread_mutex_init(&map->lock, NULL);
    map->size = 0;
    map->capacity = INITIAL_HASH_MAP_SIZE;
    map->table = calloc(map->capacity, sizeof(HashMapNode*));
}

// Insert event record into hash map with potential rehashing
void insert_event_to_hash_map(HashMap* map, EventRecord* event) {
    pthread_mutex_lock(&map->lock);

    // Calculate index using a simple hash function (mod capacity)
    size_t index = event->timestamp % map->capacity;
    HashMapNode* node = calloc(1, sizeof(HashMapNode));
    node->event = event;

    // Insert into the hash table
    node->next = map->table[index];
    map->table[index] = node;

    atomic_fetch_add(&map->size, 1);

    if ((float)atomic_load(&map->size) / map->capacity > 0.75f) {
        rehash_if_needed(map);
    }

    pthread_mutex_unlock(&map->lock);
}

// Rehash the hash map if load factor exceeds a threshold
void rehash_if_needed(HashMap* map) {
    size_t old_capacity = map->capacity;
    size_t new_capacity = old_capacity * 2;

    HashMapNode** new_table = calloc(new_capacity, sizeof(HashMapNode*));

    for (size_t i = 0; i < old_capacity; ++i) {
        HashMapNode* node = map->table[i];
        while (node != NULL) {
            size_t index = node->event->timestamp % new_capacity;

            HashMapNode* next_node = node->next;
            node->next = new_table[index];
            new_table[index] = node;

            node = next_node;
        }
    }

    free(map->table);
    map->capacity = new_capacity;
    map->table = new_table;
}

// Main function to demonstrate memory pool and hash map usage
int main() {
    MemoryPool mp;
    initialize_memory_pool(&mp, 1024 * 1024); // 1 MB pool

    HashMap event_map;
    initialize_hash_map(&event_map);

    // Example of inserting an event record
    EventRecord* event = (EventRecord*)allocate_from_pool(&mp, sizeof(EventRecord));
    if (event) {
        event->timestamp = 1234567890;
        snprintf(event->type, sizeof(event->type), "example");
        event->payload_size = 128; // Example payload size
        event->payload = allocate_from_pool(&mp, event->payload_size);

        insert_event_to_hash_map(&event_map, event);
    }

    // Cleanup (for demonstration purposes)
    free(mp.memory_pool);
    for (size_t i = 0; i < event_map.capacity; ++i) {
        HashMapNode* node = event_map.table[i];
        while (node != NULL) {
            HashMapNode* next_node = node->next;
            deallocate_to_pool(&mp, node->event->payload);
            deallocate_to_pool(&mp, node);
            node = next_node;
        }
    }
    free(event_map.table);

    return 0;
}
```

This code provides a basic structure for managing the specified data structures using a memory pool and hash map with rehashing to handle concurrency and efficient memory usage. It uses atomic operations and mutexes to ensure thread safety during concurrent modifications.']

