#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_DOCUMENTS 10000
#define MAX_METADATA_SIZE 256
#define CACHE_SIZE 1024

typedef struct Metadata {
    char mime_type[32];
    uint64_t last_modified;
    int is_compressed;
} Metadata;

typedef struct Warning {
    char message[128];
} Warning;

typedef struct ContentFragment {
    size_t length;
    uint8_t digest[16]; // Assuming SHA-256
    Metadata *metadata;
    int status;
    Warning *warning;
    float metric; // Compression efficiency
} ContentFragment;

typedef struct MemoryPool {
    void *memory;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

// Hash table structure for thread-safe storage of content fragments
typedef struct HashTable {
    ContentFragment **buckets;
    size_t capacity;
    pthread_mutex_t locks[];
} HashTable;

// Function prototypes
MemoryPool* create_memory_pool(size_t size);
void free_memory_pool(MemoryPool *pool);
ContentFragment* allocate_content_fragment(MemoryPool *pool);
Metadata* allocate_metadata(MemoryPool *pool);
Warning* allocate_warning(MemoryPool *pool);
HashTable* create_hash_table(size_t capacity);
void destroy_hash_table(HashTable *table);
void store_content_fragment(HashTable *table, ContentFragment *fragment);
ContentFragment* retrieve_content_fragment(HashTable *table, uint8_t *digest);

// Global cache and monitoring variables
Metadata **metadata_cache;
size_t metadata_cache_size = 0;

pthread_mutex_t cache_lock;
pthread_mutex_t monitor_lock;
uint64_t total_memory_usage = 0;

void initialize_system() {
    // Initialize memory pools for each collection type
    MemoryPool id_pool = *create_memory_pool(MAX_DOCUMENTS * sizeof(uint32_t));
    MemoryPool meta_pool = *create_memory_pool(MAX_DOCUMENTS * sizeof(Metadata));
    MemoryPool content_pool = *create_memory_pool(MAX_DOCUMENTS * sizeof(ContentFragment));
    MemoryPool status_pool = *create_memory_pool(MAX_DOCUMENTS * sizeof(int));
    MemoryPool warning_pool = *create_memory_pool(MAX_DOCUMENTS * sizeof(Warning));

    // Initialize hash table for content fragments
    HashTable content_table = *create_hash_table(1024);

    // Initialize metadata cache
    pthread_mutex_init(&cache_lock, NULL);
    metadata_cache = malloc(CACHE_SIZE * sizeof(Metadata*));
}

void shutdown_system() {
    free(metadata_cache);
    pthread_mutex_destroy(&cache_lock);
    pthread_mutex_destroy(&monitor_lock);
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->memory = malloc(size);
    pool->size = size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory);
    free(pool);
}

ContentFragment* allocate_content_fragment(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(sizeof(ContentFragment));
    if (ptr == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

Metadata* allocate_metadata(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(sizeof(Metadata));
    if (ptr == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

Warning* allocate_warning(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(sizeof(Warning));
    if (ptr == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable) + capacity * sizeof(pthread_mutex_t));
    table->buckets = calloc(capacity, sizeof(ContentFragment*));
    table->capacity = capacity;
    for (size_t i = 0; i < capacity; ++i) {
        pthread_mutex_init(&((pthread_mutex_t*)table)[capacity + i], NULL);
    }
    return table;
}

void destroy_hash_table(HashTable *table) {
    free(table->buckets);
    for (size_t i = 0; i < table->capacity; ++i) {
        pthread_mutex_destroy(&((pthread_mutex_t*)table)[table->capacity + i]);
    }
    free(table);
}

uint32_t hash_digest(uint8_t *digest) {
    uint32_t hash = 5381;
    for (int i = 0; i < 16; ++i) {
        hash = ((hash << 5) + hash) + digest[i];
    }
    return hash;
}

void store_content_fragment(HashTable *table, ContentFragment *fragment) {
    uint32_t index = hash_digest(fragment->digest) % table->capacity;
    pthread_mutex_lock(&((pthread_mutex_t*)table)[table->capacity + index]);
    table->buckets[index] = fragment;
    pthread_mutex_unlock(&((pthread_mutex_t*)table)[table->capacity + index]);
}

ContentFragment* retrieve_content_fragment(HashTable *table, uint8_t *digest) {
    uint32_t index = hash_digest(digest) % table->capacity;
    pthread_mutex_lock(&((pthread_mutex_t*)table)[table->capacity + index]);
    ContentFragment *fragment = table->buckets[index];
    pthread_mutex_unlock(&((pthread_mutex_t*)table)[table->capacity + index]);
    return fragment;
}

void monitor_memory_usage(size_t size) {
    pthread_mutex_lock(&monitor_lock);
    total_memory_usage += size;
    if (total_memory_usage > 1e9) { // Example threshold
        printf("Memory usage alert: %lu bytes\n", total_memory_usage);
    }
    pthread_mutex_unlock(&monitor_lock);
}

int main() {
    initialize_system();

    // Simulate operations...

    shutdown_system();
    return 0;
}
```

