#define INITIAL_PROFILE_COUNT 10
#define PROFILE_NAME_MAX_LEN 50
#define EMAIL_MAX_LEN 100
#define ROLE_LIST_INITIAL_SIZE 5

typedef struct Role {
    char *name;
    struct Role *next;
} Role;

typedef struct UserProfile {
    char name[PROFILE_NAME_MAX_LEN];
    char email[EMAIL_MAX_LEN];
    time_t last_login;
    Role *roles;
    struct UserPreferences {
        char theme[20];
        int notifications_enabled;
        int privacy_level;
    } preferences;
    pthread_mutex_t lock;
} UserProfile;

typedef struct {
    UserProfile **profiles;
    size_t capacity;
    size_t count;
    pthread_mutex_t array_lock;
} UserProfileManager;

UserProfileManager *init_user_profile_manager() {
    UserProfileManager *manager = malloc(sizeof(UserProfileManager));
    manager->capacity = INITIAL_PROFILE_COUNT;
    manager->count = 0;
    manager->profiles = malloc(manager->capacity * sizeof(UserProfile*));
    pthread_mutex_init(&manager->array_lock, NULL);
    return manager;
}

void cleanup_user_profile_manager(UserProfileManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        UserProfile *profile = manager->profiles[i];
        pthread_mutex_destroy(&profile->lock);
        Role *role = profile->roles;
        while (role != NULL) {
            Role *next_role = role->next;
            free(role->name);
            free(role);
            role = next_role;
        }
        free(profile);
    }
    free(manager->profiles);
    pthread_mutex_destroy(&manager->array_lock);
    free(manager);
}

void resize_user_profile_array(UserProfileManager *manager) {
    pthread_mutex_lock(&manager->array_lock);
    size_t new_capacity = manager->capacity * 2;
    UserProfile **new_profiles = realloc(manager->profiles, new_capacity * sizeof(UserProfile*));

    if (new_profiles != NULL) {
        manager->profiles = new_profiles;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->array_lock);
}

void add_user_profile(UserProfileManager *manager, const char *name, const char *email) {
    pthread_mutex_lock(&manager->array_lock);

    if (manager->count == manager->capacity) {
        resize_user_profile_array(manager);
    }

    UserProfile *profile = malloc(sizeof(UserProfile));
    strncpy(profile->name, name, PROFILE_NAME_MAX_LEN - 1);
    profile->name[PROFILE_NAME_MAX_LEN - 1] = '\0';

    strncpy(profile->email, email, EMAIL_MAX_LEN - 1);
    profile->email[EMAIL_MAX_LEN - 1] = '\0';

    // Generate random last login timestamp
    time_t current_time;
    time(&current_time);
    srandom((unsigned int)time(NULL)); // Seed with current time for randomness
    profile->last_login = current_time - (rand() % (3600 * 24 * 30)); // Random last month

    profile->roles = NULL;

    pthread_mutex_init(&profile->lock, NULL);

    profile->preferences.theme[19] = '\0';
    strcpy(profile->preferences.theme, "light");  // Default theme
    profile->preferences.notifications_enabled = 1;
    profile->preferences.privacy_level = 2;  // Default privacy level

    pthread_mutex_lock(&manager->array_lock);
    manager->profiles[manager->count++] = profile;
    pthread_mutex_unlock(&manager->array_lock);

    pthread_mutex_unlock(&manager->array_lock);
}

void add_role_to_profile(UserProfile *profile, const char *role_name) {
    pthread_mutex_lock(&profile->lock);

    Role *new_role = malloc(sizeof(Role));
    new_role->name = strdup(role_name);
    new_role->next = profile->roles;
    profile->roles = new_role;

    pthread_mutex_unlock(&profile->lock);
}

void iterate_user_profiles(UserProfileManager *manager, void (*callback)(UserProfile*)) {
    for (size_t i = 0; i < manager->count; ++i) {
        UserProfile *profile = manager->profiles[i];
        pthread_mutex_lock(&profile->lock);
        callback(profile);
        pthread_mutex_unlock(&profile->lock);
    }
}

void log_profile_change(const char *message, const char *user_id) {
    // Simplified logging implementation
    printf("Log: %s - UserID: %s\n", message, user_id);
}

int main() {
    UserProfileManager *manager = init_user_profile_manager();

    add_user_profile(manager, "Alice Smith", "alice@example.com");
    add_user_profile(manager, "Bob Johnson", "bob@example.com");

    iterate_user_profiles(manager, [](UserProfile *profile) {
        printf("Profile: %s, Email: %s\n", profile->name, profile->email);
        log_profile_change("Accessed Profile", profile->email);
    });

    cleanup_user_profile_manager(manager);

    return 0;
}
