#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct Node {
    double num;
    char *str;
    struct Node* next;
} Node;

// Memory pool for records
#define MAX_RECORDS 1000
Record* record_pool[MAX_RECORDS];
size_t current_record_index = 0;

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(size_t count) {
    pthread_mutex_lock(&record_lock);
    if (current_record_index + count > MAX_RECORDS) {
        printf("Exceeded maximum records limit.\n");
        pthread_mutex_unlock(&record_lock);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for a record");
            break;
        }
        record->value = rand() % 100; // Random integer between 0 and 99
        record_pool[current_record_index++] = record;
    }
    pthread_mutex_unlock(&record_lock);
}

// Memory pool for linked list nodes
#define MAX_NODES 5000
Node* node_pool[MAX_NODES];
size_t current_node_index = 0;

pthread_mutex_t node_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_linked_list(size_t count) {
    pthread_mutex_lock(&node_lock);
    if (current_node_index + count > MAX_NODES) {
        printf("Exceeded maximum nodes limit.\n");
        pthread_mutex_unlock(&node_lock);
        return;
    }

    Node* head = NULL, * tail = NULL;

    for (size_t i = 0; i < count; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            perror("Failed to allocate memory for a linked list node");
            break;
        }

        node->num = ((double)rand() / RAND_MAX) * 100.0; // Random double between 0 and 99
        char str[10];
        snprintf(str, sizeof(str), "%d", rand() % 100); // Random integer as string
        node->str = strdup(str);

        if (!head) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;

        node_pool[current_node_index++] = node;
    }

    pthread_mutex_unlock(&node_lock);
}

void free_resources() {
    pthread_mutex_lock(&record_lock);
    for (size_t i = 0; i < current_record_index; ++i) {
        free(record_pool[i]);
    }
    current_record_index = 0;
    pthread_mutex_unlock(&record_lock);

    pthread_mutex_lock(&node_lock);
    for (size_t i = 0; i < current_node_index; ++i) {
        free(node_pool[i]->str);
        free(node_pool[i]);
    }
    current_node_index = 0;
    pthread_mutex_unlock(&node_lock);
}

int main() {
    srand(time(NULL));

    // Initialize records and linked lists
    initialize_records(100);       // Example: initializing with 100 records
    initialize_linked_list(200);   // Example: initializing with 200 nodes

    // Simulate other processing...

    free_resources();

    return 0;
}
```

### Explanation of Code Structure:

1. **Data Structures**: Two main structures are used—`Record` for the array and `Node` for linked lists.

2. **Memory Management**: 
   - A memory pool approach is employed to minimize fragmentation, using predefined maximum sizes.
   - Dynamic allocation (`malloc`) is used for both records and linked list nodes, with mutex locks ensuring thread safety during initialization.

3. **Initialization**:
   - `initialize_records()` populates the record array with random integers.
   - `initialize_linked_list()` creates a singly linked list of nodes with random doubles and strings.

4. **Thread Safety**: 
   - Mutexes (`pthread_mutex_t`) protect shared resources (record_pool and node_pool) during concurrent operations.

5. **Resource Cleanup**:
   - `free_resources()` ensures all allocated memory is properly deallocated, preventing leaks.

6. **Scalability Considerations**:
   - The code accommodates dynamic resizing by allowing incremental additions within set limits.
   - Efficient allocation and initialization methods are designed to minimize performance bottlenecks. 

This solution provides a robust foundation for integrating new data structures into an existing pipeline while maintaining backward compatibility and scalability.']

