int pool_index = 0;

// Helper function to initialize a random int within range [min, max]
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize the memory pool
void init_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(DataRecord));
        if (!memory_pool[i]) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
    }
}

// Allocate a DataRecord from the pool
DataRecord* allocate_record() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index < POOL_SIZE) {
        DataRecord* record = memory_pool[pool_index++];
        pthread_mutex_unlock(&pool_mutex);
        return record;
    } else {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Pool is exhausted
    }
}

// Free a DataRecord back to the pool (not implemented for simplicity)
