    // Reinsert into memory pool if needed (omitted for brevity)
}

// Generate unique IDs using hash-based mechanism
uint64_t generate_unique_id(const char *data, size_t len) {
    uint64_t hash = 5381;
    for (size_t i = 0; i < len; ++i) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash;
}

// Validate IP address format
int validate_ip(const char *ip, char *out_buf) {
    if (inet_pton(AF_INET, ip, out_buf)) {
        return 1; // Valid IPv4
    } else if (inet_pton(AF_INET6, ip, out_buf)) {
        return 2; // Valid IPv6
    }
    return 0; // Invalid IP
}

// Calculate checksum using CRC32 (simplified version)
uint32_t crc32(const void *data, size_t n_bytes) {
    const uint8_t *buf = data;
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < n_bytes; ++i) {
        uint8_t c = buf[i];
        crc = crc ^ c;
        for (uint8_t k = 0; k < 8; ++k) {
            crc = crc & 1 ? (crc >> 1) ^ 0xEDB88320 : crc >> 1;
        }
    }
    return ~crc;
}

// Initialize a DataRecord
void init_data_record(DataRecord* record, long offset, int key, const char* src_ip, const char* dst_ip) {
    pthread_mutex_lock(&pool_mutex);
    if (record) {
        record->offset = offset;
        record->key = key;
        record->record.value = random_int(0, 100); // Random value between 0 and 100
        strncpy(record->src_ip, src_ip, sizeof(record->src_ip));
        strncpy(record->dst_ip, dst_ip, sizeof(record->dst_ip));

        uint8_t ip_buf[INET6_ADDRSTRLEN];
        if (validate_ip(src_ip, ip_buf)) {
            inet_ntop(AF_INET, &ip_buf, record->src_ip, INET6_ADDRSTRLEN);
        }
        if (validate_ip(dst_ip, ip_buf)) {
            inet_ntop(AF_INET, &ip_buf, record->dst_ip, INET6_ADDRSTRLEN);
        }

        record->checksum = crc32(record, sizeof(Record));
        record->timestamp = time(NULL); // Simplified timestamp
    }
    pthread_mutex_unlock(&pool_mutex);
}

