```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Record structure definition
typedef struct {
    int value;
} record;

// Node for the linked list
typedef struct ListNode {
    double number;
    char *string;
    struct ListNode* next;
} ListNode;

// Thread-safe initialization function using mutexes
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* initialize_record_array(size_t size, int min_value, int max_value) {
    record* array = malloc(sizeof(record) * size);
    if (!array) return NULL;

    srand((unsigned)time(NULL));
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        array[i].value = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_unlock(&lock);
    }

    return array;
}

ListNode* initialize_linked_list(size_t node_count, double min_double, double max_double) {
    ListNode* head = NULL;

    srand((unsigned)time(NULL));
    for (size_t i = 0; i < node_count; ++i) {
        ListNode* new_node = malloc(sizeof(ListNode));
        if (!new_node) return NULL;

        pthread_mutex_lock(&lock);
        new_node->number = ((double)rand() / RAND_MAX) * (max_double - min_double) + min_double;
        new_node->string = strdup("Sample String");
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);
    }

    return head;
}

void free_record_array(record* array, size_t size) {
    if (array) {
        free(array);
    }
}

void free_linked_list(ListNode* head) {
    ListNode* current = head;
    while (current) {
        ListNode* next_node = current->next;
        free(current->string);
        free(current);
        current = next_node;
    }
}

// Optional: Thread-safe dynamic resizing function for the array
record* resize_record_array(record* array, size_t old_size, size_t new_size, int min_value, int max_value) {
    if (new_size <= old_size) return initialize_record_array(new_size, min_value, max_value);

    record* resized_array = malloc(sizeof(record) * new_size);
    if (!resized_array) return NULL;

    for (size_t i = 0; i < old_size; ++i) {
        pthread_mutex_lock(&lock);
        resized_array[i] = array[i];
        pthread_mutex_unlock(&lock);
    }

    for (size_t i = old_size; i < new_size; ++i) {
        pthread_mutex_lock(&lock);
        resized_array[i].value = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_unlock(&lock);
    }

    free_record_array(array, old_size);
    return resized_array;
}

int main() {
    size_t record_count = 10;
    size_t node_count = 5;

    // Initialize a dynamic array of records
    record* records = initialize_record_array(record_count, -1000, 1000);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return EXIT_FAILURE;
    }

    // Initialize a linked list
    ListNode* list_head = initialize_linked_list(node_count, 0.0, 10.0);
    if (!list_head) {
        fprintf(stderr, "Failed to allocate memory for linked list nodes.\n");
        free_record_array(records, record_count);
        return EXIT_FAILURE;
    }

    // Example: Resize the records array
    size_t new_size = 20;
    records = resize_record_array(records, record_count, new_size, -1000, 1000);

    // Clean up
    free_linked_list(list_head);
    free_record_array(records, new_size);

    return EXIT_SUCCESS;
}
