#include <time.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_OFFSETS 10000
#define MAX_RECORDS 10000
#define UNIQUE_KEYS_LIMIT 7000

typedef enum {
    UNINITIALIZED,
    VALID,
    INVALID
} status;

typedef struct record {
    int *int_value;
    char valid;
    status state;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
bool allocated_keys[UNIQUE_KEYS_LIMIT + 1] = { false };

void log_memory_action(const char* action, size_t size) {
    time_t now;
    time(&now);
    printf("[%s] %s: %zu bytes\n", ctime(&now), action, size);
}

int *allocate_unique_keys(int num_keys, bool *success) {
    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        *success = false;
        return NULL;
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand() % UNIQUE_KEYS_LIMIT + 1;

        while (allocated_keys[keys[i]]) {
            keys[i] = rand() % UNIQUE_KEYS_LIMIT + 1;
        }
        allocated_keys[keys[i]] = true;
    }

    log_memory_action("Allocated unique keys", num_keys * sizeof(int));
    return keys;
}

record* allocate_records(size_t num_records, bool *success) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        *success = false;
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].int_value = malloc(sizeof(int));
        if (!records[i].int_value) {
            *success = false;
            for (size_t j = 0; j < i; ++j) {
                free(records[j].int_value);
            }
            free(records);
            return NULL;
        }

        int random_number;
        do {
            random_number = rand() % 201 - 100;
        } while (allocated_keys[random_number + UNIQUE_KEYS_LIMIT]);

        records[i].int_value[0] = random_number;
        allocated_keys[random_number + UNIQUE_KEYS_LIMIT] = true;

        records[i].valid = false;
        records[i].state = UNINITIALIZED;

        log_memory_action("Allocated record", sizeof(record));
    }

    return records;
}

void* manage_memory(void *arg) {
    long *offsets = malloc(MAX_OFFSETS * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return NULL;
    }
    log_memory_action("Allocated offsets", MAX_OFFSETS * sizeof(long));

    int num_keys = 5000;
    bool keys_success = true;

    pthread_mutex_lock(&lock);
    int *keys = allocate_unique_keys(num_keys, &keys_success);
    pthread_mutex_unlock(&lock);

    if (!keys || !keys_success) {
        fprintf(stderr, "Memory allocation failed for unique keys.\n");
        free(offsets);
        return NULL;
    }

    bool records_success = true;
    record *records = allocate_records(MAX_RECORDS, &records_success);

    if (!records || !records_success) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(keys);
        free(offsets);
        return NULL;
    }

    // Free allocated resources
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i].int_value) {
            free(records[i].int_value);
        }
    }

    log_memory_action("Freed records", MAX_RECORDS * sizeof(record));
    free(records);
    free(keys);
    log_memory_action("Freed keys", num_keys * sizeof(int));
    free(offsets);
    log_memory_action("Freed offsets", MAX_OFFSETS * sizeof(long));

    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_memory, NULL) != 0) {
        fprintf(stderr, "Thread creation failed.\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
```

### Key Points:
1. **Concurrency Handling**: We use a mutex (`pthread_mutex_t`) to synchronize access when allocating unique keys.
2. **Memory Management**: Memory allocation failures are handled by checking pointers and freeing already allocated memory if an error occurs.
3. **Logging**: A simple logging function is used for tracking memory actions, with timestamps for performance analysis.
4. **Unique Key Constraints**: Ensure no duplicate keys using a boolean array to track allocations within a limit of 7,000 unique values.
5. **Cleanup**: Proper deallocation of all resources to prevent leaks.

This code provides the requested functionality under constrained conditions and handles edge cases such as memory exhaustion gracefully.']

['Below is the implementation of the C function that dynamically manages a collection of records while addressing the specified constraints:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct record {
    short field1;
    int field2;
    float field3;
    struct record* next;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* head;
    size_t size;
    pthread_mutex_t lock; // For thread safety
    void (*log)(const char* message); // Logging function pointer for custom logging
} DataManager;

DataManager* create_data_manager(size_t initial_size, void (*log_func)(const char*)) {
    DataManager* manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_size, sizeof(long));
    manager->keys = (int*)calloc(initial_size, sizeof(int));
    manager->head = NULL;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log = log_func;

    if (!manager->offsets || !manager->keys) {
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    return manager;
}

void resize_data_manager(DataManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->lock);

    long* temp_offsets = (long*)realloc(manager->offsets, new_size * sizeof(long));
    int* temp_keys = (int*)realloc(manager->keys, new_size * sizeof(int));

    if (!temp_offsets || !temp_keys) {
        manager->log("Failed to resize data manager.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->offsets = temp_offsets;
    manager->keys = temp_keys;

    memset(manager->offsets + manager->size, 0, (new_size - manager->size) * sizeof(long));
    memset(manager->keys + manager->size, 0, (new_size - manager->size) * sizeof(int));

    pthread_mutex_unlock(&manager->lock);
}

void add_record(DataManager* manager, long offset, int key, Record record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == 0 || manager->offsets[manager->size - 1] != offset) {
        resize_data_manager(manager, manager->size + 1);
        manager->offsets[manager->size] = offset;
        manager->keys[manager->size - 1] = key;
    }

    Record* new_node = (Record*)malloc(sizeof(Record));
    if (!new_node) {
        manager->log("Memory allocation failed for new record.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    *new_node = record;
    new_node->next = manager->head;
    manager->head = new_node;

    manager->size++;
    manager->log("Record added.");

    pthread_mutex_unlock(&manager->lock);
}

void remove_record(DataManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    Record** current = &manager->head;
    while (*current != NULL) {
        if ((*current)->field2 == key) {
            Record* to_free = *current;
            *current = (*current)->next;
            free(to_free);
            manager->log("Record removed.");
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_data_manager(DataManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Record* current = manager->head;
    while (current != NULL) {
        Record* to_free = current;
        current = current->next;
        free(to_free);
    }

    free(manager->offsets);
    free(manager->keys);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    // Log cleanup action
}

void default_log(const char* message) {
    printf("%s\n", message);
}

// Example usage
int main() {
    DataManager* manager = create_data_manager(10, default_log);

    Record rec1 = { .field1 = 5, .field2 = 100, .field3 = 12.34f };
    add_record(manager, 12345L, 100, rec1);

    Record rec2 = { .field1 = 6, .field2 = 101, .field3 = 23.45f };
    add_record(manager, 67890L, 101, rec2);

    remove_record(manager, 100);

    cleanup_data_manager(manager);
    return 0;
}
```

### Explanation
- **Thread Safety**: `pthread_mutex_t` is used to ensure that access to shared resources (`offsets`, `keys`, and linked list) is synchronized among multiple threads.
- **Dynamic Resizing**: The function dynamically resizes the arrays holding offsets and keys when necessary, reallocating memory as needed while preserving existing data.
- **Logging Mechanism**: A logging function pointer allows custom logging implementations, ensuring flexibility in handling log outputs without affecting performance critically.
- **Memory Management**: Proper allocation and deallocation ensure no memory leaks occur. The linked list management is done through careful pointer manipulation.
- **Scalability**: The design facilitates easy extension for additional features or data sources by modularizing components like the logger and allowing dynamic resizing of storage arrays.

This code represents a foundational approach to efficiently managing a high-performance, scalable data system while ensuring thread safety and robustness.']

