#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h> // For JSON parsing

#define HASH_TABLE_SIZE 1048576 // Initial size, can be adjusted
#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 1024
#define EXPIRY_RANGE 3600 // Expiry time range in seconds

typedef struct Setting {
    char *key;
    char *value;
    time_t timestamp;
    time_t expiry;
} Setting;

typedef struct Node {
    Setting setting;
    struct Node* next;
} Node;

Node* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % HASH_TABLE_SIZE;
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hash_table[i] = NULL;
    }
}

void insert_setting(const char* key, const char* value) {
    unsigned long index = hash(key);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->setting.key = strdup(key);
    new_node->setting.value = malloc(rand() % (MAX_VALUE_LENGTH - 20) + 20); // Random length
    strcpy(new_node->setting.value, value);
    new_node->setting.timestamp = time(NULL);
    new_node->setting.expiry = new_node->setting.timestamp + rand() % EXPIRY_RANGE;

    pthread_mutex_lock(&lock);
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
    pthread_mutex_unlock(&lock);
}

Setting* get_setting(const char* key) {
    unsigned long index = hash(key);
    Node* current = hash_table[index];

    pthread_mutex_lock(&lock);
    while (current) {
        if (strcmp(current->setting.key, key) == 0) {
            pthread_mutex_unlock(&lock);
            return &(current->setting);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

void cleanup_expired_settings() {
    time_t now = time(NULL);
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node* current = hash_table[i];
        Node* prev = NULL;

        pthread_mutex_lock(&lock);
        while (current) {
            if (current->setting.expiry <= now) {
                if (prev) {
                    prev->next = current->next;
                } else {
                    hash_table[i] = current->next;
                }
                Node* to_delete = current;
                current = current->next;
                free(to_delete->setting.key);
                free(to_delete->setting.value);
                free(to_delete);
            } else {
                prev = current;
                current = current->next;
            }
        }
        pthread_mutex_unlock(&lock);
    }
}

int validate_json(const char* filename, json_t** config) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    *config = json_loadf(file, 0, NULL);
    fclose(file);

    if (json_typeof(*config) != JSON_OBJECT) {
        json_decref(*config);
        return -2;
    }

    // Example validation: Check for required keys
    if (!json_object_get(*config, "required_key")) {
        json_decref(*config);
        return -3;
    }

    return 0;
}

void* process_file(void* arg) {
    const char* filename = (const char*)arg;
    json_t *root;

    int status = validate_json(filename, &root);
    if (status != 0) {
        printf("Error processing %s: %d\n", filename, status);
        return NULL;
    }

    json_object_foreach(root, key, val) {
        char* value = json_dumps(val, JSON_COMPACT);
        insert_setting(key, value);
        free(value);
    }

    json_decref(root);

    return NULL;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <json_file>...\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_hash_table();

    pthread_t threads[argc - 1];
    for (int i = 1; i < argc; i++) {
        pthread_create(&threads[i-1], NULL, process_file, (void*)argv[i]);
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_expired_settings();

    // Print summary
    printf("Configuration Summary:\n");
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node* current = hash_table[i];
        while (current) {
            printf("%s: %s\n", current->setting.key, current->setting.value);
            current = current->next;
        }
    }

    return EXIT_SUCCESS;
}
```

### Key Points:
- **JSON Parsing**: Uses `jansson` library for parsing and validating JSON.
- **Hash Table**: Implements a basic hash table with chaining to handle collisions.
- **Thread Safety**: Uses mutexes for synchronization in the hash table operations.
- **Concurrency**: Processes each JSON file in a separate thread.
- **Cleanup**: Periodically cleans up expired settings from the hash table.

This code is a starting point and can be expanded to include more sophisticated features such as dynamic resizing of the hash table, lock-free mechanisms, or more complex validation rules.']

