    }

    float generateRandomFloat() {
        return static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    void clearRecords() {
        Record* current = records.empty() ? nullptr : records[0];
        while (current) {
            Record* next = current->next;
            delete current;
            current = next;
        }
        records.clear();
    }
