} record_v2;

// Define a node in the linked list
typedef struct Node {
    union {
        long offset;
        int key;
        record_v1 rec_v1;
        record_v2 rec_v2;
    } data;
    char type; // 'o' for offset, 'k' for key, 'r1' for record v1, 'r2' for record v2
    struct Node *next;
} Node;

// Memory pool structure
typedef struct {
    size_t block_size;
    void *pool;
    size_t pool_size;
    size_t allocated_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Linked list structure with mutexes and condition variables for thread safety
typedef struct {
    Node *head;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} LinkedList;

// Function prototypes
void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t initial_blocks);
void* allocate_from_pool(MemoryPool *mp);
void free_memory_pool(MemoryPool *mp);

void initialize_linked_list(LinkedList *list);
void insert_record(LinkedList *list, Node *node);
void remove_record(LinkedList *list, long offset);
void update_record_status(LinkedList *list, long offset, int new_status);

void log_operation(const char *operation, const Node *node);
void export_to_csv(const LinkedList *list, const char *filename);
void export_to_json(const LinkedList *list, const char *filename);

int validate_linked_list(const LinkedList *list);

// Implementations
void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t initial_blocks) {
    mp->block_size = block_size;
    mp->pool_size = block_size * initial_blocks;
    mp->allocated_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);
    mp->pool = malloc(mp->pool_size);
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->allocated_blocks < (mp->pool_size / mp->block_size)) {
        void *ptr = (char*)mp->pool + mp->allocated_blocks * mp->block_size;
        mp->allocated_blocks++;
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

void initialize_linked_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void insert_record(LinkedList *list, Node *node) {
    pthread_mutex_lock(&list->mutex);
    node->next = list->head;
    list->head = node;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    log_operation("insert", node);
}

void remove_record(LinkedList *list, long offset) {
    pthread_mutex_lock(&list->mutex);
    Node **indirect = &list->head;
    while (*indirect && ((Node*)*indirect)->data.offset != offset) {
        indirect = &(*indirect)->next;
    }
    if (*indirect) {
        Node *to_delete = *indirect;
        *indirect = to_delete->next;
        free(to_delete);
        log_operation("remove", to_delete);
    }
    pthread_mutex_unlock(&list->mutex);
}

void update_record_status(LinkedList *list, long offset, int new_status) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    while (current && current->data.offset != offset) {
        current = current->next;
    }
    if (current) {
        // Assume status is part of the record structure
        ((record_v1*)(&current->data))->status = new_status;
        log_operation("update", current);
    }
    pthread_mutex_unlock(&list->mutex);
}

void log_operation(const char *operation, const Node *node) {
    printf("%s: %ld\n", operation, node ? node->data.offset : -1);
}

void export_to_csv(const LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;
    for (Node *current = list->head; current != NULL; current = current->next) {
        fprintf(file, "%ld,%d\n", current->data.offset, current->type);
    }
    fclose(file);
}

void export_to_json(const LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;
    fprintf(file, "[\n");
    for (Node *current = list->head; current != NULL; current = current->next) {
        fprintf(file, "  {\"offset\": %ld, \"type\": \"%c\"},\n", current->data.offset, current->type);
    }
    fseek(file, -2, SEEK_CUR); // Remove last comma
    fprintf(file, "\n]");
    fclose(file);
}

int validate_linked_list(const LinkedList *list) {
    for (Node *current = list->head; current != NULL; current = current->next) {
        if (!current || (current->data.offset < 0)) return 0;
    }
    return 1;
}
```

This code provides a basic framework to manage a dynamic linked list with custom memory management, thread safety, logging, and export capabilities. Adjustments may be needed for specific application requirements.']

