#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <errno.h>

#define LOG_BUFFER_SIZE 1024

typedef struct {
    char **fileNames;
    size_t count;
    pthread_mutex_t lock;
} ResourceBundle;

// Logging function
void log_message(const char *message) {
    static char logBuffer[LOG_BUFFER_SIZE];
    snprintf(logBuffer, sizeof(logBuffer), "%s\n", message);
    printf("%s", logBuffer); // Replace with a thread-safe logging mechanism if necessary.
}

// Function to handle memory allocation failures gracefully
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_message("Memory allocation failed");
        exit(EXIT_FAILURE); // Handle as appropriate for your application
    }
    return ptr;
}

int add_file_to_bundle(ResourceBundle *bundle, const char *filename) {
    pthread_mutex_lock(&bundle->lock);

    bundle->fileNames = realloc(bundle->fileNames, sizeof(char *) * (bundle->count + 1));
    if (!bundle->fileNames) {
        log_message("Failed to resize file names array");
        pthread_mutex_unlock(&bundle->lock);
        return -1;
    }

    size_t len = strlen(filename) + 1;
    bundle->fileNames[bundle->count] = malloc(len);
    if (!bundle->fileNames[bundle->count]) {
        log_message("Failed to allocate memory for file name");
        pthread_mutex_unlock(&bundle->lock);
        return -1;
    }
    strcpy(bundle->fileNames[bundle->count], filename);

    bundle->count++;
    pthread_mutex_unlock(&bundle->lock);
    return 0;
}

int process_directory(const char *dirPath, const char *extension, ResourceBundle *bundle) {
    DIR *directory = opendir(dirPath);
    if (!directory) {
        log_message("Failed to open directory");
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(directory)) != NULL) {
        // Filtering files based on extension
        const char *dot = strrchr(entry->d_name, '.');
        if (dot && strcmp(dot, extension) == 0) {
            add_file_to_bundle(bundle, entry->d_name);
        }
    }

    closedir(directory);
    return 0;
}

int create_resource_bundle(const char *dirPath, const char *extension, ResourceBundle **bundle) {
    *bundle = safe_malloc(sizeof(ResourceBundle));
    (*bundle)->fileNames = NULL;
    (*bundle)->count = 0;

    pthread_mutex_init(&(*bundle)->lock, NULL);

    if (process_directory(dirPath, extension, *bundle)) {
        log_message("Error processing directory");
        return -1;
    }

    log_message("Resource bundle created successfully");
    return 0;
}

void destroy_resource_bundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->fileNames[i]);
    }
    free(bundle->fileNames);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

// Usage example
int main() {
    ResourceBundle *bundle;
    const char *directoryPath = "./example_dir";
    const char *fileExtension = ".txt";

    if (create_resource_bundle(directoryPath, fileExtension, &bundle) != 0) {
        log_message("Failed to create resource bundle");
        return EXIT_FAILURE;
    }

    // Example: Access and print the files in the bundle
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        printf("%s\n", bundle->fileNames[i]);
    }
    pthread_mutex_unlock(&bundle->lock);

    destroy_resource_bundle(bundle);
    return EXIT_SUCCESS;
}
```

