// Custom memory pool management (simplified)
template<typename T, size_t PoolSize = 1024>
class MemoryPool {
public:
    MemoryPool() {
        for (size_t i = 0; i < PoolSize; ++i) {
            freeList.push_back(new T());
        }
    }

    ~MemoryPool() {
        for (auto ptr : freeList) {
            delete ptr;
        }
    }

    T* allocate() {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (!freeList.empty()) {
            T* obj = freeList.back();
            freeList.pop_back();
            return obj;
        } else {
            // Pool exhausted, expand or handle error
            return new T();
        }
    }

    void deallocate(T* ptr) {
        std::lock_guard<std::mutex> lock(poolMutex);
        freeList.push_back(ptr);
    }

private:
    std::vector<T*> freeList;
    std::mutex poolMutex;
};

// Record structure definition
struct Record {
    short sValue;
    int iValue;
    float fValue;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string* metadataPtr;
    char eventType;
    bool statusIndicator;
    int priorityLevel;
    double weightFactor;
    void* contextData; // Can be cast to appropriate type

    Record(short s, int i, float f, const std::chrono::time_point<std::chrono::system_clock>& ts,
           std::string* meta, char eventT, bool status, int priority, double weight, void* context)
        : sValue(s), iValue(i), fValue(f), timestamp(ts),
          metadataPtr(meta), eventType(eventT), statusIndicator(status),
          priorityLevel(priority), weightFactor(weight), contextData(context) {}
};

// Doubly linked list node
struct ListNode {
    Record data;
    ListNode* prev;
    ListNode* next;

    ListNode(const Record& rec) : data(rec), prev(nullptr), next(nullptr) {}
};

// Thread-safe doubly linked list management
class SafeDoublyLinkedList {
public:
    SafeDoublyLinkedList() : head(nullptr), tail(nullptr) {}

    ~SafeDoublyLinkedList() {
        std::lock_guard<std::mutex> lock(listMutex);
        while (head) {
            ListNode* tmp = head;
            head = head->next;
            delete tmp;
        }
    }

    void addRecord(const Record& rec) {
        auto newNode = new ListNode(rec);

        std::lock_guard<std::mutex> lock(listMutex);
        if (!tail) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

private:
    ListNode* head;
    ListNode* tail;
    std::mutex listMutex;
};

