                      std::chrono::system_clock::now(), metadataPtr,
                      'E', (bool)(gen() % 2), gen() % 10, static_cast<double>(gen() % 100.0) / 10.0, nullptr);

        records.push_back(rec);
        recordList.addRecord(*rec);
    }

    // Attack selection logic with cooldown and thread safety
    std::atomic<bool> canSelect(true);
    auto lastAttackTime = std::chrono::system_clock::now();

    while (true) {
        if (!canSelect.load()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
