        int attack = dis(gen); // Randomly select attack 0 or 1

        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() >= 9) {
            canSelect.store(false);
            lastAttackTime = now;
            // Execute the attack logic based on `attack`

