typedef struct {
    double value;
    int count;
    char *key;
    long id;
    unsigned short length;
} Record;

typedef struct Item {
    double data;
    int index;
    struct Item *next;
    long unique_id;
    unsigned short key_length;
} Item;

typedef struct ListNode {
    short sVal;
    int iVal;
    float fVal;
    time_t timestamp;
    int statusFlag;
    struct ListNode *next;
} ListNode;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
ListNode *head = NULL;

void initRecordArray(Record **array, size_t size) {
    if (!array) return;

    *array = malloc(size * sizeof(Record));
    for (size_t i = 0; i < size; ++i) {
        (*array)[i].value = 0.0;
        (*array)[i].count = 0;
        (*array)[i].key = NULL;
        (*array)[i].id = 0;
        (*array)[i].length = 0;
    }
}

void addRecord(short s, int i, float f, time_t ts, int status) {
    ListNode *newNode = malloc(sizeof(ListNode));
    if (!newNode) return;

    newNode->sVal = s;
    newNode->iVal = i;
    newNode->fVal = f;
    newNode->timestamp = ts;
    newNode->statusFlag = status;
    newNode->next = NULL;

    pthread_mutex_lock(&listMutex);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&listMutex);
}

void deleteRecord(short s) {
    pthread_mutex_lock(&listMutex);

    ListNode **indirect = &head;
    while (*indirect && (*indirect)->sVal != s) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        ListNode *toDelete = *indirect;
        *indirect = toDelete->next;
        free(toDelete);
    }

    pthread_mutex_unlock(&listMutex);
}

void iterateRecords(void (*callback)(ListNode *)) {
    pthread_mutex_lock(&listMutex);

    ListNode *current = head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&listMutex);
}

void freeRecordArray(Record **array, size_t size) {
    if (!array || !*array) return;

    for (size_t i = 0; i < size; ++i) {
        free((*array)[i].key);
    }
    free(*array);
    *array = NULL;
}

void logChange(const char *action, ListNode *node) {
    if (!node) return;
    printf("Action: %s | Short: %d | Int: %d | Float: %.2f | Timestamp: %ld | Status: %d\n",
           action, node->sVal, node->iVal, node->fVal, node->timestamp, node->statusFlag);
}

void exportListToFile(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&listMutex);

    ListNode *current = head;
    while (current) {
        fprintf(file, "%d %d %.2f %ld %d\n",
                current->sVal, current->iVal, current->fVal,
                current->timestamp, current->statusFlag);
        current = current->next;
    }

    pthread_mutex_unlock(&listMutex);
    fclose(file);
}

// Unit test example
void testAddAndDelete() {
    addRecord(1, 100, 10.5, time(NULL), 1);
    addRecord(2, 200, 20.5, time(NULL), 0);

    iterateRecords(logChange);

    deleteRecord(1);
    iterateRecords(logChange);
}

int main() {
    testAddAndDelete();

    // Initialize and use record array
    Record *records;
    initRecordArray(&records, 10);
    freeRecordArray(&records, 10);

    return 0;
}
```

### Explanation:

- **Thread-Safety**: The linked list is protected with a mutex (`pthread_mutex_t`) to ensure thread safety during concurrent modifications.

- **Dynamic Memory Management**: Memory allocation and deallocation are carefully handled to prevent leaks. The `initRecordArray` and `freeRecordArray` functions manage memory for the array of structures.

- **Efficient Iteration**: The `iterateRecords` function allows iteration over the linked list with minimal overhead, using a callback mechanism.

- **Logging System**: The `logChange` function provides a simple logging mechanism to track changes to the list.

- **Export Functionality**: The `exportListToFile` function exports the linked list to a file in a specified format.

- **Unit Test Example**: A basic unit test (`testAddAndDelete`) is provided to demonstrate adding and deleting records, with iteration and logging. 

This code provides a foundation for managing a thread-safe linked list and an array of structures, ensuring memory safety and providing mechanisms for concurrent access, logging, and exporting data.']

