#include <stdbool.h>
#include <ctype.h>

#define MAX_FILES 1000000
#define CACHE_SIZE 256
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    char *path;
} ResourceFile;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    pthread_mutex_t lock;
} ResourceBundle;

static const char* log_level_names[] = {"DEBUG", "INFO"};
int current_log_level = LOG_LEVEL_INFO;

void log_message(int level, const char *message) {
    if (level <= current_log_level) {
        printf("[%s] %s\n", log_level_names[level], message);
    }
}

bool is_extension_match(const char *filename, const char *extension) {
    const char *dot = strrchr(filename, '.');
    return dot && strcmp(dot, extension) == 0;
}

size_t count_files_with_extension(const char *dir_path, const char *extension) {
    DIR *dir = opendir(dir_path);
    if (!dir) return 0;

    size_t count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (is_extension_match(entry->d_name, extension)) {
            count++;
        }
    }

    closedir(dir);
    return count;
}

ResourceFile* load_resource_files(const char *dir_path, const char *extension) {
    size_t file_count = count_files_with_extension(dir_path, extension);
    ResourceFile *files = malloc(sizeof(ResourceFile) * file_count);

    if (!files) {
        log_message(LOG_LEVEL_DEBUG, "Memory allocation failed for resource files.");
        return NULL;
    }

    DIR *dir = opendir(dir_path);
    if (!dir) {
        free(files);
        log_message(LOG_LEVEL_INFO, "Failed to open directory.");
        return NULL;
    }

    size_t index = 0;
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (is_extension_match(entry->d_name, extension)) {
            files[index].path = malloc(strlen(dir_path) + strlen(entry->d_name) + 2);
            snprintf(files[index].path, strlen(dir_path) + strlen(entry->d_name) + 2, "%s/%s", dir_path, entry->d_name);
            index++;
        }
    }

    closedir(dir);
    return files;
}

ResourceBundle* create_resource_bundle(const char *dir_path, const char *extension) {
    ResourceFile *files = load_resource_files(dir_path, extension);
    if (!files) {
        log_message(LOG_LEVEL_INFO, "Failed to load resource files.");
        return NULL;
    }

    size_t file_count = count_files_with_extension(dir_path, extension);
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        free(files);
        log_message(LOG_LEVEL_DEBUG, "Memory allocation failed for resource bundle.");
        return NULL;
    }

    bundle->items = calloc(file_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!bundle->items) {
        free(bundle->items);
        free(bundle);
        free(files);
        log_message(LOG_LEVEL_DEBUG, "Memory allocation failed for bundle items.");
        return NULL;
    }

    pthread_mutex_init(&bundle->lock, NULL);
    bundle->count = file_count;

    for (size_t i = 0; i < file_count; ++i) {
        bundle->items[i].RX_UE_INFORMATION_TAG = rand();
        bundle->items[i].RNTI = rand();
        bundle->items[i].CRCFLAG = rand() % 2;
    }

    free(files);
    return bundle;
}

void free_resource_bundle(ResourceBundle *bundle) {
    if (bundle) {
        pthread_mutex_destroy(&bundle->lock);
        free(bundle->items);
        free(bundle);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <directory_path> <file_extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *dir_path = argv[1];
    const char *extension = argv[2];

    ResourceBundle *bundle = create_resource_bundle(dir_path, extension);
    if (!bundle) {
        log_message(LOG_LEVEL_INFO, "Failed to create resource bundle.");
        return EXIT_FAILURE;
    }

    // Example usage of the bundle
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        printf("Item %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
               i, bundle->items[i].RX_UE_INFORMATION_TAG,
               bundle->items[i].RNTI, bundle->items[i].CRCFLAG);
    }
    pthread_mutex_unlock(&bundle->lock);

    free_resource_bundle(bundle);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Dynamic Allocation**: The function dynamically allocates memory for files and bundles.
- **Error Handling**: Handles potential errors in directory access and memory allocation gracefully.
- **Logging**: Implements a simple logging mechanism to track operations.
- **Thread Safety**: Uses mutexes to ensure thread-safe access to the resource bundle.
- **Scalability**: Designed to handle large directories efficiently, although actual performance will depend on system capabilities.
- **Modularity**: The code is structured for easy extension and integration with other systems.']

