pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory and initialize arrays
int init_arrays(long **offsets, int **keys, long *offset_array_size, int *key_array_size) {
    if (*offset_array_size <= 0 || *key_array_size <= 0) {
        return -1; // Error code for invalid input parameters
    }

    *offsets = (long *)malloc(*offset_array_size * sizeof(long));
    *keys = (int *)malloc(*key_array_size * sizeof(int));

    if (*offsets == NULL || *keys == NULL) {
        free(*offsets);
        free(*keys);
        return -2; // Error code for memory allocation failure
    }

    for (long i = 0; i < *offset_array_size; i++) {
        (*offsets)[i] = i;
    }
    for (int i = 0; i < *key_array_size; i++) {
        (*keys)[i] = i;
    }

    return 0; // Success
}

// Function to allocate and initialize record structures
int init_records(record **records, long array_size, int num_records, 
                 int min_value, int max_value, long *offsets, int *keys) {
    if (num_records > array_size || num_records <= 0 || array_size <= 0) {
        return -3; // Error code for invalid input parameters
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return -2; // Error code for memory allocation failure
    }

    srand(time(NULL)); // Seed random number generator

    pthread_mutex_lock(&mutex); // Ensure thread safety during initialization
    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        long offset_index = rand() % array_size;
        int key_index = rand() % array_size;

        if (offsets != NULL && keys != NULL) {
            (*records)[i].offset_ptr = &offsets[offset_index];
            (*records)[i].key_index = keys[key_index];
        } else {
            free(*records);
            pthread_mutex_unlock(&mutex);
            return -4; // Error code for mismatched array lengths
        }
    }
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

// Function to deallocate memory
void cleanup(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

int main() {
