    if (init_arrays(&offsets, &keys, &array_size, &array_size) != 0) {
        fprintf(stderr, "Error initializing arrays\n");
        return -1;
    }

    // Initialize records
    if (init_records(&records, array_size, num_records, min_value, max_value, offsets, keys) != 0) {
        fprintf(stderr, "Error initializing records\n");
        cleanup(offsets, keys, NULL);
        return -1;
    }

    // Use the records...

    // Cleanup
    cleanup(offsets, keys, records);

    return 0;
}
