                 rand() & 0xFF, rand() & 0xFF, rand() & 0xFF);
    }
    return manager;
}

void free_device_manager(DeviceManager *manager) {
    if (manager) {
        free(manager->devices);
        free(manager);
    }
}

bool add_device(DeviceManager *manager) {
    if (manager->device_count >= manager->capacity) {
        resize_devices(manager);
    }
    Device *new_device = &manager->devices[manager->device_count++];
    new_device->temperature = ((float)rand() / RAND_MAX) * 30.0 + 15.0; // Random temp between 15 and 45
    new_device->humidity = rand() % 50 + 20; // Random humidity between 20 and 70
    new_device->battery_level = 100;
    time(&new_device->last_update);
    return true;
}

void update_device(Device *device, float temperature, int humidity, int battery_decrement) {
    device->temperature = temperature;
    device->humidity = humidity;
    if (device->battery_level > battery_decrement)
        device->battery_level -= battery_decrement;
    else
        device->battery_level = 0; // Avoid negative battery level

    time(&device->last_update);
}

void log_update(const Device *device, const char *reading_type, float value) {
    printf("Device %s - %s: %.2f\n", device->mac_address, reading_type, value);
}

void handle_disconnections(DeviceManager *manager, time_t disconnection_threshold) {
    time_t current_time;
    time(&current_time);

    for (size_t i = 0; i < manager->device_count; ++i) {
        if (difftime(current_time, manager->devices[i].last_update) > disconnection_threshold) {
            log_update(&manager->devices[i], "Disconnected", 0.0);
        }
    }
}

void garbage_collect(DeviceManager *manager) {
    time_t current_time;
    time(&current_time);

    size_t active_count = 0;
    for (size_t i = 0; i < manager->device_count; ++i) {
        if (difftime(current_time, manager->devices[i].last_update) <= 3600) { // Keep data updated in last hour
            if (active_count != i) {
                manager->devices[active_count] = manager->devices[i];
            }
            active_count++;
        }
    }

    manager->device_count = active_count;
}

void resize_devices(DeviceManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Device *new_devices = (Device*)realloc(manager->devices, new_capacity * sizeof(Device));

    if (new_devices) {
        for (size_t i = manager->capacity; i < new_capacity; ++i) {
            snprintf(new_devices[i].mac_address, MAC_ADDRESS_LENGTH, "%02X:%02X:%02X:%02X:%02X:%02X",
                     rand() & 0xFF, rand() & 0xFF, rand() & 0x7F,
                     rand() & 0xFF, rand() & 0xFF, rand() & 0xFF);
        }
        manager->devices = new_devices;
        manager->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize devices array\n");
    }
}

// Example of usage
int main() {
    DeviceManager *manager = init_device_manager(10, 12345);

    for (size_t i = 0; i < 15; ++i) {
        add_device(manager);
    }

    update_device(&manager->devices[0], 22.5f, 55, 1);
    log_update(&manager->devices[0], "Temperature", manager->devices[0].temperature);

    handle_disconnections(manager, 300); // Devices offline for more than 5 minutes
    garbage_collect(manager);

    free_device_manager(manager);
    return 0;
}
