pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER; // Lock for the linked list

// Function prototypes
void add_record(Record *rec);
void remove_all();
int validate_domain(const char* domain);
float calculate_average(int num1, int num2);
