    return rand() % range;
}

long calculate_offset(int* keys, size_t size, const int constant) {
    long offset = 0;
    for (size_t i = 0; i < size; ++i) {
        offset += keys[i];
    }
    return offset + constant;
}

// Thread function to process log entries
void *process_log_entries(void* arg) {
    char** log_entries = (char**)arg;

    for (int i = 0; log_entries[i] != NULL; ++i) {
        process_log_entry(log_entries[i]);
    }

    return NULL;
}

// Add a record to the linked list
void add_record(Record *rec) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list_lock);

    new_node->record = rec;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&list_lock);
}

// Remove all nodes from the linked list
void remove_all() {
    Node *current = head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp->record);
        free(temp);
    }
    head = NULL;
}

