    if ((host_info = gethostbyname(domain)) == NULL) {
        herror("DNS query failed");
        return 0;
    }
    return 1;
}

// Calculate average of two numerical fields in a log entry
float calculate_average(int num1, int num2) {
    return (num1 + num2) / 2.0f;
}

// Process individual log entries
void process_log_entry(char* entry) {
    char domain[256];
    int num1, num2;

    if (sscanf(entry, "%255s %d %d", domain, &num1, &num2) == 3) {
        if (validate_domain(domain)) {
            Record *record = malloc(sizeof(Record));
            if (!record) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }

            record->s = rand() % 1000;
            record->i = rand() % 10000;
            record->f = calculate_average(num1, num2);

            add_record(record);
        } else {
            printf("Invalid domain: %s\n", domain);
        }
    }
}

