    srand((unsigned int)time(NULL));

    // Example log entries (normally loaded from a file or network source)
    char* log_entries[] = {"example.com 10 20", "invalid.com 30 40", NULL};

    pthread_t threads[2];

    // Create threads to process log entries
    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, process_log_entries, &log_entries)) {
