#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_OFFSETS 10000
#define MAX_KEYS 5000
#define MAX_UNIQUE_KEYS 7000
#define MAX_RECORDS 10000

typedef enum { UNINITIALIZED, VALID, INVALID } status_t;

typedef struct {
    int *value;
    char valid;
    status_t status;
} record_t;

void log_allocation(const char* message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    time_t now;
    time(&now);
    printf("[%s] %s\n", ctime(&now), message);
    pthread_mutex_unlock(&log_mutex);
}

void free_memory(long* offsets, int* keys, record_t* records) {
    for (int i = 0; i < MAX_RECORDS && records[i].value != NULL; ++i) {
        free(records[i].value);
    }
    free(offsets);
    free(keys);
    free(records);
}

long* allocate_offsets() {
    long *offsets = calloc(MAX_OFFSETS, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate offsets array.\n");
        return NULL;
    }
    log_allocation("Allocated offsets array.");
    return offsets;
}

int* allocate_unique_keys(int size) {
    int *keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate unique keys array.\n");
        return NULL;
    }
    log_allocation("Allocated unique keys array.");
    return keys;
}

record_t* initialize_records() {
    record_t *records = malloc(MAX_RECORDS * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Failed to allocate records array.\n");
        return NULL;
    }

    static int used_numbers[MAX_RECORDS] = {0};
    int count = 0;

    for (int i = 0; i < MAX_RECORDS && count < MAX_UNIQUE_KEYS; ++i) {
        records[i].value = malloc(sizeof(int));
        if (!records[i].value) {
            fprintf(stderr, "Failed to allocate memory for record value.\n");
            free_memory(NULL, NULL, records);
            return NULL;
        }

        int rand_num;
        do {
            rand_num = rand() % 201 - 100; // Random number between -100 and 100
        } while (used_numbers[rand_num + 100] != 0);

        used_numbers[rand_num + 100] = 1;

        *records[i].value = rand_num;
        records[i].valid = 0;
        records[i].status = UNINITIALIZED;

        ++count;
    }

    log_allocation("Initialized records array.");
    return records;
}

void* manage_memory(void* arg) {
    long* offsets = allocate_offsets();
    if (!offsets) return NULL;

    int keys_size = (MAX_KEYS < MAX_UNIQUE_KEYS) ? MAX_KEYS : MAX_UNIQUE_KEYS;
    int *keys = allocate_unique_keys(keys_size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record_t* records = initialize_records();
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Simulate usage
    sleep(1);

    // Free all allocated memory
    free_memory(offsets, keys, records);

    return NULL;
}

int main() {
    srand(time(NULL));
    manage_memory(NULL);
    return 0;
}
```

This code defines a function `manage_memory` that allocates and initializes memory for offsets, unique keys, and records under constrained conditions. It handles allocation failures gracefully and logs each significant memory operation. The code also includes functions to initialize and free the allocated resources while managing potential concurrency issues with logging.']

