```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <json-c/json.h>
#include <curl/curl.h>
#include <sys/time.h>

#define MAX_THREADS 10
#define DNS_QUERY_LIMIT 5

typedef struct {
    char *hostname;
    int port;
    char *token_json;
} ServerConfig;

typedef struct {
    char *data;
    size_t length;
} CurlResponse;

void *dns_resolve(void *arg);
int validate_token(const char *json_data, const char *api_url);
size_t curl_write_callback(void *contents, size_t size, size_t nmemb, void *userp);

// Rate limiting structure
typedef struct {
    int queries;
    time_t last_query_time;
} DnsRateLimiter;

DnsRateLimiter rate_limiter = {0};

void log_event(const char *message) {
    printf("%s\n", message);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    int active_threads = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        ServerConfig *config = malloc(sizeof(ServerConfig));
        if (!config) {
            perror("Failed to allocate memory for config");
            continue;
        }

        // Parse the configuration line
        if (sscanf(line, "%ms %d %[^\n]", &config->hostname, &config->port, &config->token_json) != 3) {
            free(config);
            continue;
        }

        pthread_create(&threads[active_threads++], NULL, dns_resolve, config);

        if (active_threads >= MAX_THREADS) {
            for (int i = 0; i < MAX_THREADS; ++i) {
                pthread_join(threads[i], NULL);
            }
            active_threads = 0;
        }
    }

    fclose(file);

    // Join remaining threads
    while (active_threads > 0) {
        --active_threads;
        pthread_join(threads[active_threads], NULL);
    }

    return EXIT_SUCCESS;
}

void *dns_resolve(void *arg) {
    ServerConfig *config = (ServerConfig *)arg;

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // set to AF_INET to force IPv4
    hints.ai_socktype = SOCK_STREAM;

    if (rate_limiter.queries >= DNS_QUERY_LIMIT) {
        time_t now = time(NULL);
        if (now - rate_limiter.last_query_time < 1) {
            sleep(1 - (now - rate_limiter.last_query_time));
        }
        rate_limiter.last_query_time = time(NULL);
        rate_limiter.queries = 0;
    }

    if ((status = getaddrinfo(config->hostname, NULL, &hints, &res)) != 0) {
        log_event("DNS resolution failed for hostname");
        free(config);
        pthread_exit(NULL);
    }

    rate_limiter.queries++;
    rate_limiter.last_query_time = time(NULL);

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        log_event("Resolved IP: ");
        log_event(ipstr);
    }

    freeaddrinfo(res);

    // Validate token
    const char *api_url = "https://example.com/token/verify";
    if (!validate_token(config->token_json, api_url)) {
        log_event("Token validation failed");
    } else {
        log_event("Token is valid");
    }

    free(config);
    pthread_exit(NULL);
}

int validate_token(const char *json_data, const char *api_url) {
    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(json_data);

    if (!json_object_object_get_ex(parsed_json, "access_token", NULL) ||
        !json_object_object_get_ex(parsed_json, "expires_in", NULL) ||
        strcmp(json_object_get_string(
            json_object_object_get(parsed_json, "token_type")), "Bearer") != 0) {
        json_object_put(parsed_json);
        return 0;
    }

    // Check expires_in is a positive integer
    int expires_in = (int)json_object_get_int(json_object_object_get(parsed_json, "expires_in"));
    if (expires_in <= 0) {
        json_object_put(parsed_json);
        return 0;
    }

    // Fetch additional metadata from REST API
    CURL *curl;
    CURLcode res;
    CurlResponse response = {NULL, 0};

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, curl_write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            log_event("Failed to fetch token metadata");
        } else {
            // Parse and validate the response
            // Assume the API returns a JSON object with a "valid" field
            struct json_object *metadata;
            metadata = json_tokener_parse(response.data);

            int valid = json_object_get_boolean(json_object_object_get(metadata, "valid"));
            json_object_put(metadata);
            curl_free(response.data);

            if (!valid) {
                log_event("Token is revoked");
                return 0;
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    json_object_put(parsed_json);
    return 1;
}

size_t curl_write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    CurlResponse *response = (CurlResponse *)userp;

    response->data = realloc(response->data, response->length + realsize + 1);
    if (!response->data) {
        log_event("Failed to allocate memory for CURL response");
        return 0;
    }

    memcpy(&(response->data[response->length]), contents, realsize);
    response->length += realsize;
    response->data[response->length] = '\0';

    return realsize;
}
