#define MAX_METADATA_LENGTH 256
#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB memory pool for simplicity

typedef struct {
    short sh;
    int i;
    float f;
    time_t ts;
    char metadata[MAX_METADATA_LENGTH];
