    size_t used;
    size_t capacity;
    pthread_mutex_t pool_lock;
} MemoryPool;

MemoryPool memory_pool;

unsigned int hash_function(const void *key, int len) {
    const unsigned char *data = (const unsigned char *)key;
    unsigned int hash = 0;
    for (int i = 0; i < len; ++i)
        hash ^= data[i] + (hash << 10) + (hash >> 6);
    return hash % MEMORY_POOL_SIZE;
}

