        return NULL;
    }

    void* ptr = memory_pool.pool + memory_pool.used;
    memory_pool.used += size;

    pthread_mutex_unlock(&memory_pool.pool_lock);
    return ptr;
}

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const Record* record) {
    Node* node = (Node*)allocate_from_pool(sizeof(Node));
    if (!node)
        return NULL;

    *node->record = *record;
    node->next = NULL;
    return node;
}

void insert_record(LinkedList* list, const Record* record) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(record);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void random_record(Record* record) {
    static const char valid_chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    record->sh = rand() % 32768 - 16384; // Random short
    record->i = rand();                  // Random int
    record->f = (float)rand() / RAND_MAX * 100.0; // Random float between 0 and 100

    time(&record->ts); // Current timestamp

    for (int i = 0; i < MAX_METADATA_LENGTH - 1; ++i)
        record->metadata[i] = valid_chars[rand() % sizeof(valid_chars) - 1];
    record->metadata[MAX_METADATA_LENGTH - 1] = '\0';
}

void init_random_seed() {
    srand((unsigned int)time(NULL));
}

typedef struct {
    Node* current;
} ListIterator;

ListIterator create_iterator(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    ListIterator it = { .current = list->head };
    pthread_mutex_unlock(&list->lock);

    return it;
}

int has_next(ListIterator* it) {
    return it->current != NULL;
}

Record get_next(ListIterator* it) {
    if (!has_next(it))
        exit(EXIT_FAILURE); // or handle error

    Record record = it->current->record;
    it->current = it->current->next;

    return record;
}

void free_memory_pool() {
    free(memory_pool.pool);
}

int main() {
    init_random_seed();
    init_memory_pool();

    LinkedList list;
    init_linked_list(&list);

    for (int i = 0; i < 100; ++i) { // Insert records
        Record record;
        random_record(&record);
        insert_record(&list, &record);
    }

    ListIterator it = create_iterator(&list);
    while (has_next(&it)) {
        Record rec = get_next(&it);
        printf("Record: %d, %.2f, %ld\n", rec.i, rec.f, rec.ts);
    }

    free_memory_pool();
    return 0;
}
``` 

This code provides a framework for managing a collection of records with dynamic memory allocation from a memory pool. The structure supports concurrent access and insertion using mutex locks. It also includes functions to generate random record values and iterate through the linked list. Note that real-world applications may require more sophisticated thread synchronization, error handling, resizing strategies, logging, and monitoring than illustrated here.']

