}

TaskCollection* init_task_collection(size_t initial_count, int min_priority, int max_priority) {
    TaskCollection *collection = malloc(sizeof(TaskCollection));
    if (!collection) return NULL;

    collection->tasks = calloc(initial_count, sizeof(Task *));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }

    collection->num_tasks = initial_count;
    pthread_mutex_init(&collection->lock, NULL);

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < initial_count; ++i) {
