        if (!task) continue;

        task->priority = rand() % (max_priority - min_priority + 1) + min_priority;
        task->callback = NULL; // Assign actual callbacks as needed
        memset(task->buffer, 0, sizeof(task->buffer));

        pthread_mutex_lock(&collection->lock);
        collection->tasks[i] = task;
        pthread_mutex_unlock(&collection->lock);
    }

    return collection;
}

void free_task_collection(TaskCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->num_tasks; ++i) {
        Task *task = collection->tasks[i];
        if (task) free(task);
    }
    free(collection->tasks);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void adjust_task_count(TaskCollection *collection, size_t new_count) {
    if (!collection || !new_count) return;

    pthread_mutex_lock(&collection->lock);
    Task **temp = realloc(collection->tasks, new_count * sizeof(Task *));
    if (temp) collection->tasks = temp;

    for (size_t i = collection->num_tasks; i < new_count; ++i) {
        Task *task = malloc(sizeof(Task));
        if (!task) continue;

        task->priority = rand() % 10 + 1; // Example range
        task->callback = NULL; // Assign actual callbacks as needed
        memset(task->buffer, 0, sizeof(task->buffer));

        collection->tasks[i] = task;
    }

    if (new_count < collection->num_tasks) {
        for (size_t i = new_count; i < collection->num_tasks; ++i) {
            free(collection->tasks[i]);
            collection->tasks[i] = NULL;
        }
    }

    collection->num_tasks = new_count;
    pthread_mutex_unlock(&collection->lock);
}

// Example callback function
void example_callback() {
