        free_task_collection(task_collection);
        return EXIT_FAILURE;
    }

    // Example usage
    adjust_task_count(task_collection, 15);

    // Clean up
    free_status_records(status_records, task_collection->num_tasks);
    free_task_collection(task_collection);

    return EXIT_SUCCESS;
}
