['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    size_t num_readings;
    double *readings;
    char *metadata;
} TimeSeriesRecord;

typedef struct RecordNode {
    TimeSeriesRecord record;
    struct RecordNode *next;
} RecordNode;

typedef struct {
    RecordNode *head;
    pthread_mutex_t lock;
} TimeSeriesCollection;

TimeSeriesCollection* create_collection() {
    TimeSeriesCollection *collection = malloc(sizeof(TimeSeriesCollection));
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_sensor_reading(TimeSeriesCollection *collection, time_t timestamp, double reading, char *metadata) {
    pthread_mutex_lock(&collection->lock);

    RecordNode **current = &collection->head;

    while (*current && (*current)->record.timestamp != timestamp) {
        current = &(*current)->next;
    }

    if (*current) { // Existing record
        TimeSeriesRecord *record = &(*current)->record;
        double *new_readings = realloc(record->readings, (record->num_readings + 1) * sizeof(double));
        if (!new_readings) {
            perror("Failed to allocate memory for new reading");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        record->readings = new_readings;
        record->readings[record->num_readings++] = reading;
    } else { // New record
        RecordNode *new_node = malloc(sizeof(RecordNode));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        new_node->record.timestamp = timestamp;
        new_node->record.num_readings = 1;
        new_node->record.readings = malloc(sizeof(double));
        if (!new_node->record.readings) {
            perror("Failed to allocate memory for readings");
            free(new_node);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        new_node->record.readings[0] = reading;

        size_t metadata_len = strlen(metadata) + 1;
        new_node->record.metadata = malloc(metadata_len);
        if (!new_node->record.metadata) {
            perror("Failed to allocate memory for metadata");
            free(new_node->record.readings);
            free(new_node);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        strcpy(new_node->record.metadata, metadata);

        new_node->next = *current;
        *current = new_node;
    }

    pthread_mutex_unlock(&collection->lock);
}

void serialize_records(TimeSeriesCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    RecordNode *current = collection->head;

    pthread_mutex_lock(&collection->lock);
    while (current) {
        fwrite(&(current->record.timestamp), sizeof(time_t), 1, file);
        fwrite(&(current->record.num_readings), sizeof(size_t), 1, file);

        fwrite(current->record.readings, sizeof(double), current->record.num_readings, file);

        size_t metadata_len = strlen(current->record.metadata) + 1;
        fwrite(&metadata_len, sizeof(size_t), 1, file);
        fwrite(current->record.metadata, sizeof(char), metadata_len, file);

        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);

    fclose(file);
}

void deserialize_records(TimeSeriesCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    time_t timestamp;
    size_t num_readings;
    double *readings;
    char *metadata;

    pthread_mutex_lock(&collection->lock);
    while (fread(&timestamp, sizeof(time_t), 1, file)) {
        fread(&num_readings, sizeof(size_t), 1, file);

        readings = malloc(num_readings * sizeof(double));
        if (!readings) {
            perror("Failed to allocate memory for readings");
            fclose(file);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        fread(readings, sizeof(double), num_readings, file);

        size_t metadata_len;
        fread(&metadata_len, sizeof(size_t), 1, file);
        metadata = malloc(metadata_len * sizeof(char));
        if (!metadata) {
            perror("Failed to allocate memory for metadata");
            free(readings);
            fclose(file);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        fread(metadata, sizeof(char), metadata_len, file);

        RecordNode *new_node = malloc(sizeof(RecordNode));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            free(readings);
            free(metadata);
            fclose(file);
            pthread_mutex_unlock(&collection->lock);
            return;
        }

        new_node->record.timestamp = timestamp;
        new_node->record.num_readings = num_readings;
        new_node->record.readings = readings;
        new_node->record.metadata = metadata;

        new_node->next = collection->head;
        collection->head = new_node;
    }
    pthread_mutex_unlock(&collection->lock);

    fclose(file);
}

void free_collection(TimeSeriesCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    RecordNode *current = collection->head;
    while (current) {
        RecordNode *next = current->next;
        free(current->record.readings);
        free(current->record.metadata);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

This code provides a basic implementation of a thread-safe time-series record manager in C. It includes functions for creating and managing a collection, adding sensor readings, serializing to a file, deserializing from a file, and freeing resources. The use of mutexes ensures thread safety for concurrent access.']

