#define POOL_SIZE 1024 * 16 // Adjust size as needed

void* memory_pool[POOL_SIZE] = {NULL};
size_t pool_index = 0;

void* allocate_from_pool(size_t size) {
    if (pool_index + (size / sizeof(void*)) > POOL_SIZE)
        return NULL;

    void* ptr = &memory_pool[pool_index];
    memset(ptr, 0, size);
    pool_index += (size / sizeof(void*));
    return ptr;
}

void reset_memory_pool() {
