        if (!handler) break;

        handler->health_check = NULL; // No-op for demo
        devices[i]->handler = handler;
    }

    *status_records = allocate_from_pool(MAX_DEVICES * sizeof(DeviceStatus));
    if (!(*status_records)) return NULL;

    for (int i = 0; i < MAX_DEVICES; ++i) {
        snprintf((*status_records)[i].description, sizeof((*status_records)[i].description), "Device %d Status", i);
        (*status_records)[i].state = READY;
    }

    return devices;
}

// Function to free allocated resources
void cleanup_devices(Device** devices, DeviceStatus* status_records) {
    if (devices) {
        for (int i = 0; i < MAX_DEVICES && devices[i] != NULL; ++i) {
            if (devices[i]->handler)
                free(devices[i]->handler);
            free(devices[i]);
        }
        free(devices);
    }

    if (status_records)
        free(status_records);

    reset_memory_pool();
}

// Function for periodic health check
void perform_health_checks(Device** devices, size_t device_count) {
    if (!devices) return;

    for (size_t i = 0; i < device_count && devices[i] != NULL; ++i) {
        if (devices[i]->handler->health_check)
            devices[i]->handler->health_check(devices[i]);
    }
}

int main() {
    srand(time(NULL));

    Device** devices;
    DeviceStatus* status_records;

    // Initialize
