    if (!devices || !status_records) {
        fprintf(stderr, "Initialization failed.\n");
        return 1;
    }

    // Simulate periodic health checks (e.g., every minute)
    perform_health_checks(devices, MAX_DEVICES);

    // Cleanup when done
    cleanup_devices(devices, status_records);

    return 0;
}
