#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int outcome;  // Could be an enum or specific values indicating success/failure, etc.
    int error_code;
} history_entry;

typedef void (*action_function)(void);

typedef struct worker {
    char log_buffer[256];
    float performance_metric;
    action_function action;
    history_entry* history;
    size_t history_size;
    pthread_mutex_t mutex;  // For thread-safe access to the worker
} worker;

// Function prototypes
worker* initialize_worker(int id, action_function act);
void adjust_workers(worker** workers, size_t* worker_count, int load_threshold);
int generate_initial_history_entry(history_entry* entry);
float get_random_performance_metric(float min, float max);

// Worker initialization function
worker* initialize_worker(int id, action_function act) {
    worker* w = (worker*)malloc(sizeof(worker));
    if (!w) return NULL;

    pthread_mutex_init(&w->mutex, NULL);

    // Initialize performance metric with random value
    w->performance_metric = get_random_performance_metric(0.5, 1.0);

    // Set action function
    w->action = act;

    // Initialize history entries
    w->history_size = 1;  // Start with one idle entry
    w->history = (history_entry*)malloc(w->history_size * sizeof(history_entry));
    if (!w->history) {
        free(w);
        return NULL;
    }

    generate_initial_history_entry(&w->history[0]);

    snprintf(w->log_buffer, sizeof(w->log_buffer), "Worker %d initialized", id);

    return w;
}

// Adjust the number of workers based on load
void adjust_workers(worker** workers, size_t* worker_count, int load_threshold) {
    // Example logic to increase or decrease workers based on some metric
    pthread_mutex_lock(&workers[*worker_count - 1]->mutex);

    if (*worker_count < MAX_WORKERS && load_is_higher_than(load_threshold)) { 
        worker** new_workers = realloc(workers, sizeof(worker*) * (*worker_count + 1));
        if (new_workers) {
            workers = new_workers;
            workers[*worker_count] = initialize_worker(*worker_count, NULL);  // Example action function
            (*worker_count)++;
        }
    } else if (*worker_count > MIN_WORKERS && load_is_lower_than(load_threshold)) {
        free(workers[--(*worker_count)]->history);
        pthread_mutex_destroy(&workers[*worker_count]->mutex);
        free(workers[*worker_count]);
        worker** new_workers = realloc(workers, sizeof(worker*) * (*worker_count));
        if (new_workers) workers = new_workers;
    }

    pthread_mutex_unlock(&workers[*worker_count - 1]->mutex);
}

int generate_initial_history_entry(history_entry* entry) {
    time_t now = time(NULL);
    entry->timestamp = now;
    entry->outcome = 0; // Idle
    entry->error_code = 0;

    return 0; // Success
}

float get_random_performance_metric(float min, float max) {
    return ((float)rand() / (RAND_MAX)) * (max - min) + min;
}

// Dummy function to simulate load check
int load_is_higher_than(int threshold) {
    // Implement actual logic here
    return rand() % 2; // Randomly simulating high or low load for demonstration
}

int load_is_lower_than(int threshold) {
    // Implement actual logic here
    return !load_is_higher_than(threshold);
}
