typedef struct Node {
    char *data;
    int value;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node *node) {
    free(node->data);
    free(node);
}

Node* create_node(const char *data, int value) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = strdup(data);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void add_node(List *list, const char *data, int value) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = create_node(data, value);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

Node* search_by_string(List *list, const char *target) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (strcmp(current->data, target) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_node(List *list, int index, const char *new_data, int new_value) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    int i = 0;
    while (current != NULL && i < index) {
        current = current->next;
        i++;
    }

    if (current != NULL) {
        free(current->data);
        current->data = strdup(new_data);
        current->value = new_value;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(List *list, int index) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node *current = list->head;
    Node *prev = NULL;

    if (index == 0) {
        list->head = current->next;
        destroy_node(current);
    } else {
        int i = 0;
        while (current != NULL && i < index) {
            prev = current;
            current = current->next;
            i++;
        }

        if (current != NULL) {
            prev->next = current->next;
            destroy_node(current);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void synchronize_with_external_source(List *list, void (*sync_func)(List*)) {
