['Here's a C function that initializes and manages a dynamically allocated array of `UserSession` structures with thread safety, logging, and cleanup mechanisms:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int UserID;
    char IPAddress[16];
    time_t SessionStartTimestamp;
    time_t SessionEndTimestamp;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// External logging function (stub for demonstration)
void log_audit(const char *message) {
    printf("Audit Log: %s\n", message);
}

// Initialize the session manager
int init_session_manager(SessionManager *manager) {
    if (!manager) return -1;

    pthread_mutex_init(&manager->lock, NULL);
    manager->sessions = malloc(INITIAL_CAPACITY * sizeof(UserSession));
    if (!manager->sessions) return -1;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    log_audit("Initialized session manager");
    return 0;
}

// Add a new session
int add_session(SessionManager *manager, int UserID, const char *IPAddress, time_t startTimestamp) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    UserSession session;
    session.UserID = UserID;
    strncpy(session.IPAddress, IPAddress, sizeof(session.IPAddress));
    session.SessionStartTimestamp = startTimestamp;
    session.SessionEndTimestamp = 0; // Open-ended for now

    manager->sessions[manager->count++] = session;

    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Added new session: UserID=%d", UserID);
    log_audit(log_msg);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update session end time
int update_session_end(SessionManager *manager, int UserID, time_t endTimestamp) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].UserID == UserID && manager->sessions[i].SessionEndTimestamp == 0) {
            manager->sessions[i].SessionEndTimestamp = endTimestamp;

            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Updated session end time: UserID=%d", UserID);
            log_audit(log_msg);

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found or already ended
}

// Find sessions active within a specified time range
size_t find_active_sessions(SessionManager *manager, time_t startRange, time_t endRange, UserSession **activeSessions) {
    size_t count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if ((manager->sessions[i].SessionStartTimestamp <= endRange &&
             manager->sessions[i].SessionEndTimestamp >= startRange) ||
            (manager->sessions[i].SessionStartTimestamp == 0 && // Open-ended sessions
             manager->sessions[i].SessionEndTimestamp > startRange)) {

            *activeSessions = realloc(*activeSessions, (count + 1) * sizeof(UserSession));
            if (!*activeSessions) break;
            (*activeSessions)[count++] = manager->sessions[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return count;
}

// Clean up expired sessions
void cleanup_expired_sessions(SessionManager *manager, time_t currentTime) {
    pthread_mutex_lock(&manager->lock);

    size_t valid_count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].SessionEndTimestamp > currentTime || manager->sessions[i].SessionEndTimestamp == 0) {
            if (valid_count != i) {
                manager->sessions[valid_count] = manager->sessions[i];
            }
            valid_count++;
        } else {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Removed expired session: UserID=%d", manager->sessions[i].UserID);
            log_audit(log_msg);
        }
    }

    manager->count = valid_count;
    pthread_mutex_unlock(&manager->lock);
}

// Free resources
void free_session_manager(SessionManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->sessions);
    manager->sessions = NULL;
    log_audit("Freed session manager resources");
}
```

This code provides a thread-safe, scalable way to manage user sessions, with logging and periodic cleanup of expired sessions. Adjust the `INITIAL_CAPACITY` or other parameters as needed based on expected load and performance requirements.']

