#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct entry {
    int key;
    long offset;
} Entry;

typedef struct record {
    int value;
} Record;

#define INITIAL_CAPACITY 16
#define MAX_LOAD_FACTOR 0.75

// Custom memory allocator
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

typedef struct collection {
    Entry* entries;
    int capacity;
    size_t size;
    pthread_mutex_t lock;
} Collection;

Collection* initialize_collection(int num_entries, int key_range_min, int key_range_max) {
    if (num_entries <= 0 || key_range_min >= key_range_max) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    srand((unsigned)time(NULL));

    Collection* collection = custom_malloc(sizeof(Collection));
    collection->entries = custom_malloc(INITIAL_CAPACITY * sizeof(Entry));
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    for (int i = 0; i < num_entries; ++i) {
        int key = rand() % (key_range_max - key_range_min + 1) + key_range_min;

        // Simulate insertion into a concurrent data structure
        pthread_mutex_lock(&collection->lock);
        if (collection->size >= collection->capacity * MAX_LOAD_FACTOR) {
            int new_capacity = collection->capacity * 2;
            Entry* new_entries = custom_malloc(new_capacity * sizeof(Entry));
            memcpy(new_entries, collection->entries, collection->size * sizeof(Entry));
            custom_free(collection->entries);
            collection->entries = new_entries;
            collection->capacity = new_capacity;
        }

        for (int j = 0; j < collection->size; ++j) {
            if (collection->entries[j].key == key) {
                pthread_mutex_unlock(&collection->lock);
                i--; // Retry with a new random key
                break;
            }
        } else {
            collection->entries[collection->size++] = (Entry){.key = key, .offset = rand() % 1000};
        }
        pthread_mutex_unlock(&collection->lock);
    }

    return collection;
}

void* initialize_records(int num_records, int value_range_min, int value_range_max) {
    if (num_records <= 0 || value_range_min >= value_range_max) {
        fprintf(stderr, "Invalid input parameters for records\n");
        return NULL;
    }

    Record* records = custom_malloc(num_records * sizeof(Record));
    srand((unsigned)time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    }

    return records;
}

void free_collection(Collection* collection) {
    if (!collection) return;

    custom_free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
    custom_free(collection);
}

int main() {
    Collection* myCollection = initialize_collection(100, 0, 10000);
    Record* records = (Record*)initialize_records(50, -500, 500);

    // Use the collection and records as needed...

    free_collection(myCollection);
    custom_free(records);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for concurrent access.
- **Custom Memory Allocator**: Simplified allocation and deallocation functions.
- **Dynamic Resizing**: Collection resizes when reaching load factor threshold.
- **Random Initialization**: Keys and record values are initialized randomly within specified ranges.
- **Error Handling**: Checks for invalid parameters with error messages.
- **Memory Management Logging**: Can be extended to include logging for debugging.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define HASH_MAP_SIZE 101

typedef struct node {
    char *data;
    int value;
} node;

typedef struct list_node {
    node data;
    struct list_node *next;
} list_node;

typedef struct hash_map_entry {
    char *key;
    list_node *node;
    struct hash_map_entry *next;
} hash_map_entry;

typedef struct {
    list_node *head;
    hash_map_entry *hash_map[HASH_MAP_SIZE];
    pthread_mutex_t lock;
} node_list;

unsigned int hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash % HASH_MAP_SIZE;
}

node_list* create_node_list() {
    node_list *list = malloc(sizeof(node_list));
    list->head = NULL;
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        list->hash_map[i] = NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void log_operation(const char *operation, const char *details) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), operation, details);
}

void add_node(node_list *list, node new_data) {
    pthread_mutex_lock(&list->lock);

    list_node *new_node = malloc(sizeof(list_node));
    new_node->data = (node){.data = strdup(new_data.data), .value = new_data.value};
    new_node->next = list->head;
    list->head = new_node;

    unsigned int index = hash_function(new_node->data.data);
    hash_map_entry *entry = malloc(sizeof(hash_map_entry));
    entry->key = strdup(new_node->data.data);
    entry->node = new_node;
    entry->next = list->hash_map[index];
    list->hash_map[index] = entry;

    log_operation("ADD", new_data.data);

    pthread_mutex_unlock(&list->lock);
}

void remove_node(node_list *list, int index) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || index < 0) {
        log_operation("REMOVE (INVALID)", "Invalid index");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list_node **current = &(list->head), *temp;
    int i = 0;

    while (*current && i < index) {
        current = &((*current)->next);
        i++;
    }

    if (!*current) {
        log_operation("REMOVE (INVALID)", "Index out of bounds");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    temp = *current;
    *current = (*current)->next;

    unsigned int hash_index = hash_function(temp->data.data);
    hash_map_entry **hash_current = &(list->hash_map[hash_index]);

    while (*hash_current && strcmp((*hash_current)->key, temp->data.data) != 0) {
        hash_current = &((*hash_current)->next);
    }

    if (*hash_current) {
        *hash_current = (*hash_current)->next;
        free((*hash_current)->key);
        free(*hash_current);
    }

    log_operation("REMOVE", temp->data.data);

    free(temp->data.data);
    free(temp);

    pthread_mutex_unlock(&list->lock);
}

void update_node(node_list *list, int index, node new_data) {
    pthread_mutex_lock(&list->lock);

    list_node **current = &(list->head);
    int i = 0;

    while (*current && i < index) {
        current = &((*current)->next);
        i++;
    }

    if (!*current) {
        log_operation("UPDATE (INVALID)", "Index out of bounds");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    free((*current)->data.data);
    (*current)->data.data = strdup(new_data.data);
    (*current)->data.value = new_data.value;

    unsigned int hash_index = hash_function(new_data.data);
    hash_map_entry **hash_current = &(list->hash_map[hash_index]);

    while (*hash_current && strcmp((*hash_current)->key, (*current)->data.data) != 0) {
        hash_current = &((*hash_current)->next);
    }

    if (!*hash_current || strcmp((*hash_current)->key, (*current)->data.data) != 0) {
        free((*hash_current)->key);
        (*hash_current)->key = strdup(new_data.data);
        *hash_current = *current;
    }

    log_operation("UPDATE", new_data.data);

    pthread_mutex_unlock(&list->lock);
}

list_node* search_node(node_list *list, const char *search_str) {
    unsigned int index = hash_function(search_str);
    hash_map_entry *entry = list->hash_map[index];

    while (entry) {
        if (strcmp(entry->key, search_str) == 0) {
            log_operation("SEARCH", entry->key);
            return entry->node;
        }
        entry = entry->next;
    }

    log_operation("SEARCH", "Not found");
    return NULL;
}

void serialize_node_list(node_list *list, const char *filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list_node *current = list->head;
    while (current) {
        fwrite(&(current->data.value), sizeof(int), 1, file);
        size_t len = strlen(current->data.data) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->data.data, sizeof(char), len, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

node_list* deserialize_node_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    node_list *list = create_node_list();

    pthread_mutex_lock(&list->lock);

    int value;
    size_t len;
    char *data;

    while (fread(&value, sizeof(int), 1, file)) {
        fread(&len, sizeof(size_t), 1, file);
        data = malloc(len);
        fread(data, sizeof(char), len, file);

        node new_data = {.data = data, .value = value};
        add_node(list, new_data);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return list;
}

void free_node_list(node_list *list) {
    pthread_mutex_lock(&list->lock);

    list_node *current = list->head;
    while (current) {
        list_node *temp = current;
        current = current->next;

        hash_map_entry **hash_current = &(list->hash_map[hash_function(temp->data.data)]);
        while (*hash_current && strcmp((*hash_current)->key, temp->data.data) != 0) {
            hash_current = &((*hash_current)->next);
        }
        if (*hash_current && strcmp((*hash_current)->key, temp->data.data) == 0) {
            *hash_current = (*hash_current)->next;
            free((*hash_current)->key);
            free(*hash_current);
        }

        free(temp->data.data);
        free(temp);
    }

    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        hash_map_entry *entry = list->hash_map[i];
        while (entry) {
            hash_map_entry *temp = entry;
            entry = entry->next;
            free(temp->key);
            free(temp);
        }
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

This code provides a thread-safe implementation of a dynamically allocated list with concurrent access, a hash map for fast lookups, logging, serialization, and batch operations. The use of mutexes ensures that the shared data structures are accessed safely by multiple threads. The hash map is designed to minimize collisions and memory usage, while the logging mechanism records all operations with timestamps. Serialization allows saving and loading the list from disk efficiently.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Node {
    char *mac_address;
    int battery_level;
} Node;

typedef struct List {
    Node **nodes;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} List;

List* create_list(size_t initial_capacity) {
    List *list = malloc(sizeof(List));
    list->nodes = malloc(initial_capacity * sizeof(Node *));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_list(List *list) {
    size_t new_capacity = list->capacity * 2;
    Node **new_nodes = realloc(list->nodes, new_capacity * sizeof(Node *));
    if (new_nodes) {
        list->nodes = new_nodes;
        list->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize list\n");
        exit(EXIT_FAILURE);
    }
}

void add_node(List *list, const char *mac_address, int battery_level) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_list(list);
    }

    Node *node = malloc(sizeof(Node));
    node->mac_address = strdup(mac_address);
    node->battery_level = battery_level;

    list->nodes[list->size++] = node;

    log_update(node, "add");
    pthread_mutex_unlock(&list->lock);
}

void remove_node(List *list, size_t index) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    Node *node = list->nodes[index];
    free(node->mac_address);
    free(node);

    memmove(&list->nodes[index], &list->nodes[index + 1], 
            (list->size - index - 1) * sizeof(Node *));
    list->size--;

    log_update(NULL, "remove");
    pthread_mutex_unlock(&list->lock);
}

void update_node(List *list, size_t index, const char *mac_address, int battery_level) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    Node *node = list->nodes[index];
    free(node->mac_address);
    node->mac_address = strdup(mac_address);
    node->battery_level = battery_level;

    log_update(node, "update");
    pthread_mutex_unlock(&list->lock);
}

Node* find_node_by_mac(List *list, const char *mac_address) {
    for (size_t i = 0; i < list->size; ++i) {
        if (strcmp(list->nodes[i]->mac_address, mac_address) == 0) {
            return list->nodes[i];
        }
    }
    return NULL;
}

void log_update(Node *node, const char *action) {
    time_t now = time(NULL);
    printf("[%s] Action: %s, MAC Address: %s, Battery Level: %d\n", 
           ctime(&now), action, node ? node->mac_address : "N/A", node ? node->battery_level : -1);
}

void traverse_list(List *list, void (*callback)(Node *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        callback(list->nodes[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage of the library
void print_node(Node *node) {
    printf("MAC Address: %s, Battery Level: %d\n", node->mac_address, node->battery_level);
}

int main() {
    List *sensor_list = create_list(10);

    add_node(sensor_list, "00:11:22:33:44:55", 95);
    add_node(sensor_list, "66:77:88:99:AA:BB", 80);

    Node *found = find_node_by_mac(sensor_list, "00:11:22:33:44:55");
    if (found) update_node(sensor_list, 0, "00:11:22:33:44:56", 90);

    traverse_list(sensor_list, print_node);
    remove_node(sensor_list, 1);

    free_sensor_list(sensor_list); // Implement a function to properly free the list and its nodes
    return 0;
}

