#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char title[256];
    char author[256];
    time_t publication_date;
    int content_length;
} Document;

typedef struct {
    Document *documents;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DocumentCollection;

DocumentCollection* init_document_collection(size_t initial_capacity) {
    DocumentCollection *collection = malloc(sizeof(DocumentCollection));
    if (!collection) return NULL;

    collection->documents = malloc(initial_capacity * sizeof(Document));
    if (!collection->documents) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_document_collection(DocumentCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->documents);
        free(collection);
    }
}

int resize_if_needed(DocumentCollection *collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Document *new_documents = realloc(collection->documents, new_capacity * sizeof(Document));
        if (!new_documents) return -1;

        collection->documents = new_documents;
        collection->capacity = new_capacity;
    }
    return 0;
}

void add_document(DocumentCollection *collection, const char *title, const char *author, time_t publication_date, int content_length) {
    pthread_mutex_lock(&collection->lock);

    if (resize_if_needed(collection) != 0) {
        fprintf(stderr, "Failed to resize document collection\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Document doc;
    snprintf(doc.title, sizeof(doc.title), "%s-%zu", title, collection->count + 1);
    snprintf(doc.author, sizeof(doc.author), "Author%d", rand() % 1000);
    doc.publication_date = publication_date;
    doc.content_length = content_length;

    collection->documents[collection->count++] = doc;

    pthread_mutex_unlock(&collection->lock);
}

void sort_documents(DocumentCollection *collection, int (*comparator)(const Document *, const Document *)) {
    pthread_mutex_lock(&collection->lock);

    qsort(collection->documents, collection->count, sizeof(Document), comparator);

    pthread_mutex_unlock(&collection->lock);
}

int compare_by_publication_date(const void *a, const void *b) {
    return ((Document *)a)->publication_date - ((Document *)b)->publication_date;
}

int compare_by_content_length(const void *a, const void *b) {
    return ((Document *)a)->content_length - ((Document *)b)->content_length;
}

void query_documents(DocumentCollection *collection, const char *author_filter, time_t start_date, time_t end_date) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if ((strcmp(collection->documents[i].author, author_filter) == 0 || !*author_filter) &&
            collection->documents[i].publication_date >= start_date &&
            collection->documents[i].publication_date <= end_date) {
            printf("Document: %s by %s on %ld\n",
                   collection->documents[i].title,
                   collection->documents[i].author,
                   collection->documents[i].publication_date);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Example usage
int main() {
    srand(time(NULL));

    DocumentCollection *collection = init_document_collection(10);

    time_t current_time = time(NULL);
    for (int i = 0; i < 15; ++i) {
        add_document(collection, "Title", "", current_time + (60 * i), rand() % 10000);
    }

    sort_documents(collection, compare_by_publication_date);
    query_documents(collection, "Author500", time(NULL), time(NULL) + (3600));

    destroy_document_collection(collection);

    return 0;
}
```

