#define MAX_DOCUMENTS 1000
#define MAX_TITLE_LEN 256
#define MAX_AUTHOR_LEN 256

typedef struct {
    char title[MAX_TITLE_LEN];
    char author[MAX_AUTHOR_LEN];
    time_t publication_date;
    int content_length;
} Document;

// Custom allocator structure
typedef struct {
    size_t block_size;
    void *start;
    size_t used;
} CustomAllocator;

void init_allocator(CustomAllocator *allocator, size_t block_size) {
    allocator->block_size = block_size;
    allocator->start = malloc(block_size);
    allocator->used = 0;
}

void* custom_alloc(CustomAllocator *allocator, size_t size) {
    if (size > allocator->block_size - allocator->used)
        return NULL; // Not enough space
    void *ptr = (char*)allocator->start + allocator->used;
    allocator->used += size;
    return ptr;
}

void free_allocator(CustomAllocator *allocator) {
    free(allocator->start);
}

typedef struct {
    Document *documents[MAX_DOCUMENTS];
    int count;
    CustomAllocator document_alloc;
} DocumentManager;

void init_document_manager(DocumentManager *dm) {
    dm->count = 0;
    init_allocator(&dm->document_alloc, MAX_DOCUMENTS * sizeof(Document*));
}

Document* create_document(DocumentManager *dm) {
    if (dm->count >= MAX_DOCUMENTS)
        return NULL; // No space for more documents
    Document *doc = custom_alloc(&dm->document_alloc, sizeof(Document));
    if (!doc) return NULL;

    snprintf(doc->title, MAX_TITLE_LEN, "Title_%d", rand() % 1000);
    snprintf(doc->author, MAX_AUTHOR_LEN, "Author_%d", rand() % 500);
    doc->publication_date = time(NULL) + (rand() % 10000); // Simulate rolling timestamp
    doc->content_length = rand() % 10000;

    dm->documents[dm->count++] = doc;
    return doc;
}

void delete_document(DocumentManager *dm, int index) {
    if (index < 0 || index >= dm->count)
        return; // Invalid index
    free(dm->documents[index]);
    for (int i = index; i < dm->count - 1; ++i) {
        dm->documents[i] = dm->documents[i + 1];
    }
    dm->count--;
}

Document* query_document_by_title(DocumentManager *dm, const char *title) {
    for (int i = 0; i < dm->count; ++i) {
        if (strcmp(dm->documents[i]->title, title) == 0)
            return dm->documents[i];
    }
    return NULL;
}

void sort_documents_by_date(DocumentManager *dm) {
