['```cpp
#include <iostream>
#include <mutex>

struct Node {
    int id;
    std::string metadata;
    Node* next;

    Node(int identifier, const std::string& meta) : id(identifier), metadata(meta), next(nullptr) {}
};

class LinkedList {
private:
    Node* head;
    mutable std::mutex mtx; // Mutex for thread-safe operations

public:
    LinkedList() : head(nullptr) {}

    ~LinkedList() {
        clear();
    }

    void insertAfterTarget(int targetId, const Node& newNode) {
        std::lock_guard<std::mutex> lock(mtx);  // Ensure thread safety
        if (!head) {  // If list is empty
            head = new Node(newNode.id, newNode.metadata);
            return;
        }

        Node* current = head;
        Node* prev = nullptr;

        while (current && current->id != targetId) {
            prev = current;
            current = current->next;
        }

        if (current) {  // Target found
            Node* new_node_ptr = new Node(newNode.id, newNode.metadata);
            new_node_ptr->next = current->next;
            current->next = new_node_ptr;
        } else {  // Append to the end
            Node* last = head;
            while (last->next) {
                last = last->next;
            }
            last->next = new Node(newNode.id, newNode.metadata);
        }
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mtx);  // Ensure thread safety
        Node* current = head;
        while (current) {
            Node* next = current->next;
            delete current;
            current = next;
        }
        head = nullptr;
    }

    void printList() const {  // Helper function for debugging
        std::lock_guard<std::mutex> lock(mtx);
        Node* current = head;
        while (current) {
            std::cout << "Node ID: " << current->id << ", Metadata: " << current->metadata << '\n';
            current = current->next;
        }
    }
};

int main() {
    LinkedList list;

    // Example usage
    list.insertAfterTarget(2, Node(3, "New after 2"));
    list.insertAfterTarget(1, Node(4, "New after 1"));
    list.insertAfterTarget(5, Node(6, "Append to end"));

    list.printList();

    return 0;
}
```

### Key Points:
- **Thread Safety:** The linked list operations are protected by a mutex (`std::mutex`) to ensure thread-safe modifications.
- **Memory Management:** Nodes are dynamically allocated and properly deallocated in the destructor with `delete` calls within a clear method.
- **Efficiency:** The function traverses the list only once per insertion, ensuring optimal time complexity. Memory usage is kept minimal by only allocating necessary nodes.
- **Concurrency Handling:** A single mutex lock (`std::lock_guard`) ensures that modifications are atomic and consistent, preventing race conditions.
- **Edge Cases:** Handles empty lists and cases where the target node isn't found by appending to the end.']

