    public async Task ProcessLogFileAsync(string logFilePath)
    {
        var bufferSize = _configManager.GetParameter<int>("BufferSize");
        byte[] buffer = new byte[bufferSize];

        using (var fs = File.OpenRead(logFilePath))
        {
            int bytesRead;
