        let mut cache = cache.lock().unwrap();
        if let Some(entry) = cache.get(&file_path) {
            let metadata = fs::metadata(&file_path).map_err(|e| e.to_string())?;
            if entry.modification_time < metadata.modified()?;
                if SystemTime::now() - entry.modification_time > cache_policy {
                    drop(cache);
                    // Re-process the file
