        }

        // Update cache
        let metadata = fs::metadata(&file_path).map_err(|e| e.to_string())?;
        drop(cache);

        let processing_time_ms = start_time.elapsed().as_millis();

        Ok(FileProcessingResult {
            file_path,
            processing_time_ms,
            pass_times_ms: pass_times,
        })
    }

    fn log_results(results: &Vec<FileProcessingResult>) {
        // Implement detailed logging logic here
        for result in results {
            println!("Processed: {:?}, Time (ms): {}", result.file_path, result.processing_time_ms);
            for (pass, time) in &result.pass_times_ms {
                println!("  Pass: {}, Time (ms): {}", pass, time);
            }
        }
    }

