// Memory pool functions
MemoryPool* createMemoryPool(size_t objSize, size_t numObjects) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->objSize = objSize;
    mp->poolSize = objSize * numObjects;
    mp->pool = malloc(mp->poolSize);
    mp->freeList = (unsigned char *)mp->pool;

    pthread_mutex_init(&mp->lock, NULL);

    // Initialize free list
    for (size_t i = 0; i < mp->poolSize - objSize; i += objSize) {
        *((void **)(mp->freeList + i)) = mp->freeList + i + objSize;
    }
    *(void **)(mp->freeList + mp->poolSize - objSize) = NULL;

    return mp;
}

void* memoryPoolAlloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    void *ptr = mp->freeList;
    if (ptr) {
        mp->freeList = *(void **)(ptr);
    }
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

void memoryPoolFree(MemoryPool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    *((void **)ptr) = mp->freeList;
    mp->freeList = (unsigned char *)ptr;
    pthread_mutex_unlock(&mp->lock);
}

void freeMemoryPool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

