Record* addToList(Record **head, Record **tail, Record *newNode) {
    if (!(*head)) {
        *head = *tail = newNode;
    } else {
        (*tail)->next = newNode;
        newNode->prev = *tail;
        *tail = newNode;
    }
    return *head;
}

void removeFromList(Record **head, Record **tail, Record *node) {
    if (node == *head) {
        *head = node->next;
    }
    if (node == *tail) {
        *tail = node->prev;
    }
    if (node->prev) {
        node->prev->next = node->next;
    }
    if (node->next) {
        node->next->prev = node->prev;
    }
}

