        }
        ds->keys[i] = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        sum += ds->keys[i];
        ds->offsets[i] = sum + (rand() % 10 + 1);
    }
}

Record* createRandomRecord(MemoryPool *mp) {
    return createLinkedListNode(NULL, NULL); // Simplified for demonstration
}

void resizeArrays(DataStructure *ds, size_t newSize) {
    pthread_mutex_lock(&ds->lock);
    long *newOffsets = realloc(ds->offsets, newSize * sizeof(long));
    int *newKeys = realloc(ds->keys, newSize * sizeof(int));

    if (newOffsets && newKeys) {
        ds->offsets = newOffsets;
        ds->keys = newKeys;
        ds->size = newSize;
    } else {
        // Handle allocation failure
        free(newOffsets);
        free(newKeys);
        fprintf(stderr, "Failed to resize arrays\n");
    }
    pthread_mutex_unlock(&ds->lock);
}
