['Below is a C code implementation that meets the requirements described in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    int timestamp;
    int status;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    size_t capacity;
    void** blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->capacity = block_size * num_blocks;
    pool->blocks = calloc(num_blocks, sizeof(void*));

    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->capacity / sizeof(void*); ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->capacity / sizeof(void*); ++i) {
        if (!pool->blocks[i]) {
            void* block = malloc(size);
            pool->blocks[i] = block;
            pthread_mutex_unlock(&pool->lock);
            return block;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Pool exhausted
}

void initialize_system(MemoryPool* pool, size_t num_records, int key_range_start, int key_range_end) {
    static pthread_once_t once = PTHREAD_ONCE_INIT;

    pthread_once(&once, []() {
        srand(time(NULL));
    });

    long *offsets = allocate_from_pool(pool, sizeof(long) * num_records);
    int *keys = allocate_from_pool(pool, sizeof(int) * num_records);
    int *status_flags = allocate_from_pool(pool, sizeof(int) * num_records);

    if (!offsets || !keys || !status_flags) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    long cumulative_sum = 0;
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);
        offsets[i] = cumulative_sum += keys[i];
        status_flags[i] = rand() % 2;
    }

    Node* head = NULL;
    Node* tail = NULL;

    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_records; ++i) {
        Node* node = allocate_from_pool(pool, sizeof(Node));
        if (!node) break;

        node->data.s_field = rand() % 32768;
        node->data.i_field = rand() % 1000000;
        node->data.f_field = (float)(rand() / (RAND_MAX + 1.0)) * 10000.0f;
        node->data.timestamp = rand() % 1000000000;
        node->data.status = status_flags[i];
        node->next = NULL;
        node->prev = tail;

        pthread_mutex_lock(&list_lock);
        if (tail) {
            tail->next = node;
        } else {
            head = node;
        }
        tail = node;
        pthread_mutex_unlock(&list_lock);
    }

    // Provide a function to iterate over the list
    void iterate_list() {
        Node* current = head;
        while (current) {
            printf("Record: %d, %f, %d\n", current->data.s_field, current->data.f_field, current->data.timestamp);
            current = current->next;
        }
    }

    // Provide a function to resize arrays if needed
    void* resize_array(void** array, size_t old_size, size_t new_size) {
        void* resized = realloc(*array, new_size * sizeof(**array));
        if (resized) {
            *array = resized;
        }
        return resized;
    }

    // Add code for dynamic resizing logic and thread-safe modification handling here
}

int main() {
    MemoryPool* pool = create_memory_pool(1024, 1000);
    initialize_system(pool, 10000, 1, 100000);

    destroy_memory_pool(pool);
    return 0;
}
