    if (!node) return NULL;

    node->offsets = custom_alloc(size * sizeof(long));
    node->keys = custom_alloc(size * sizeof(int));
    node->records = custom_alloc(size * sizeof(Record));
    node->timestamps = custom_alloc(size * sizeof(int));
    node->statuses = custom_alloc(size * sizeof(char));

    if (!node->offsets || !node->keys || !node->records || !node->timestamps || !node->statuses) {
        custom_free(node->offsets);
        custom_free(node->keys);
        custom_free(node->records);
        custom_free(node->timestamps);
        custom_free(node->statuses);
        custom_free(node);
        return NULL;
    }

    node->size = size;

    // Initialize keys and offsets
    int cumulative_sum = 0;
    for (size_t i = 0; i < size; ++i) {
        node->keys[i] = generate_key(100000); // Arbitrary range
        cumulative_sum += node->keys[i];
        node->offsets[i] = cumulative_sum + (long)i * 10; // Constant value added
    }

    initialize_records(node->records, size);

    node->prev = NULL;
    node->next = NULL;

    return node;
}

// Add a new node to the linked list in a thread-safe manner
void add_node(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    } else {
        list->head = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Initialize the linked list
LinkedList* initialize_linked_list() {
    LinkedList* list = custom_alloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_node(Node* node) {
    if (node) {
        custom_free(node->offsets);
        custom_free(node->keys);
        custom_free(node->records);
        custom_free(node->timestamps);
        custom_free(node->statuses);
        custom_free(node);
    }
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    custom_free(list);
}

// Example usage
