#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LEN 256
#define INITIAL_CAPACITY 100
#define CONFIG_CONSTANT 10

typedef struct {
    short sh_val;
    int i_val;
    float f_val;
    char str[MAX_STRING_LEN];
    _Bool b_val;
} Record;

typedef struct Node {
    Record record;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

typedef struct {
    int *offset;
    int *key;
    Record **records;
    char ***strings;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DistributedCollection;

// External system stubs (to be implemented as per specific APIs)
void external_kv_store_put(int key, const void *value, size_t value_size);
void* external_kv_store_get(int key);
void message_queue_notify_change(int key);

// Function prototypes
DistributedCollection* init_collection();
void resize_collection(DistributedCollection *dc);
void add_record(DistributedCollection *dc, Record record);
Record* get_record_by_key(DistributedCollection *dc, int key);
void save_state_periodically(DistributedCollection *dc);
void compress_and_save(const void *data, size_t data_size);

DistributedCollection* init_collection() {
    DistributedCollection *dc = malloc(sizeof(DistributedCollection));
    dc->offset = calloc(INITIAL_CAPACITY, sizeof(int));
    dc->key = malloc(INITIAL_CAPACITY * sizeof(int));
    dc->records = malloc(INITIAL_CAPACITY * sizeof(Record *));
    dc->strings = malloc(INITIAL_CAPACITY * sizeof(char **));
    dc->capacity = INITIAL_CAPACITY;
    dc->count = 0;

    pthread_mutex_init(&dc->lock, NULL);
    return dc;
}

void resize_collection(DistributedCollection *dc) {
    size_t new_capacity = dc->capacity * 2;
    int *new_offset = realloc(dc->offset, new_capacity * sizeof(int));
    int *new_key = realloc(dc->key, new_capacity * sizeof(int));
    Record **new_records = realloc(dc->records, new_capacity * sizeof(Record *));
    char ***new_strings = realloc(dc->strings, new_capacity * sizeof(char **));

    if (new_offset && new_key && new_records && new_strings) {
        dc->offset = new_offset;
        dc->key = new_key;
        dc->records = new_records;
        dc->strings = new_strings;
        dc->capacity = new_capacity;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Failed to resize collection\n");
        exit(EXIT_FAILURE);
    }
}

void add_record(DistributedCollection *dc, Record record) {
    pthread_mutex_lock(&dc->lock);

    if (dc->count == dc->capacity) {
        resize_collection(dc);
    }

    // Generate unique key and calculate offset
    int new_key = rand() % 1000; // Example range
    while (new_key < dc->count && strcmp(record.str, dc->records[new_key]->str) != 0) { // Ensure uniqueness
        new_key = rand() % 1000;
    }

    dc->key[dc->count] = new_key;
    if (dc->count > 0) {
        dc->offset[dc->count] = dc->offset[dc->count - 1] + CONFIG_CONSTANT;
    } else {
        dc->offset[dc->count] = CONFIG_CONSTANT;
    }

    // Allocate and assign record
    Record *new_record = malloc(sizeof(Record));
    memcpy(new_record, &record, sizeof(Record));
    dc->records[dc->count] = new_record;

    pthread_mutex_unlock(&dc->lock);

    // Notify external systems of the change
    external_kv_store_put(new_key, new_record, sizeof(Record));
    message_queue_notify_change(new_key);
}

Record* get_record_by_key(DistributedCollection *dc, int key) {
    for (size_t i = 0; i < dc->count; ++i) {
        if (dc->key[i] == key) {
            return dc->records[i];
        }
    }
    return NULL;
}

void save_state_periodically(DistributedCollection *dc) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))compress_and_save, dc) != 0) {
        fprintf(stderr, "Failed to create background thread for periodic saving\n");
    }
}

void compress_and_save(const void *data, size_t data_size) {
    while (1) {
        sleep(60); // Save every minute
        // Example compression function; implement as needed
        char compressed_data[1024];
        size_t compressed_size = 0;

        // Simulate compression (actual implementation required)
        memcpy(compressed_data, data, MIN(data_size, sizeof(compressed_data)));
        compressed_size = data_size < sizeof(compressed_data) ? data_size : sizeof(compressed_data);

        // Example save function; implement as needed
        FILE *file = fopen("backup.bin", "wb");
        if (file) {
            fwrite(compressed_data, 1, compressed_size, file);
            fclose(file);
        }
    }
}

int main() {
    srand(time(NULL));

    DistributedCollection *dc = init_collection();
    Record record = { .sh_val = rand() % 1000, .i_val = rand() % 10000, .f_val = (float)rand() / RAND_MAX,
                      .str = "Sample String", .b_val = rand() % 2 };

    add_record(dc, record);
    Record *retrieved = get_record_by_key(dc, dc->key[0]);
    if (retrieved) {
        printf("Retrieved: %d\n", retrieved->i_val);
    }

    save_state_periodically(dc);

    // Cleanup
    for (size_t i = 0; i < dc->count; ++i) {
        free(dc->records[i]);
    }
    free(dc->offset);
    free(dc->key);
    free(dc->records);
    free(dc->strings);
    pthread_mutex_destroy(&dc->lock);
    free(dc);

    return 0;
}
