    size_t block_size;
    void* free_list;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t num_blocks);
void* allocate_from_pool(MemoryPool* pool);
void deallocate_to_pool(MemoryPool* pool, void* ptr);

// Logging functions (simplified)
typedef struct {
    char buffer[256];
    pthread_mutex_t lock;
} LogBuffer;

void log_message(LogBuffer* log_buffer, const char* message) {
    pthread_mutex_lock(&log_buffer->lock);
    snprintf(log_buffer->buffer, sizeof(log_buffer->buffer), "%s", message);
    // Simulate asynchronous logging
    printf("%s\n", log_buffer->buffer);
    pthread_mutex_unlock(&log_buffer->lock);
}

// Function to initialize memory pool
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->free_list = malloc(block_size * num_blocks);
    memset(pool->free_list, 0, block_size * num_blocks);
    pthread_mutex_init(&pool->lock, NULL);
}

// Function to allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    void* ptr = pool->free_list;
    if (ptr != NULL) {
        size_t old_free_list = (uintptr_t)pool->free_list + pool->block_size;
        pool->free_list = *(void**)old_free_list;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to deallocate memory back to the pool
void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    *(void**)(ptr + pool->block_size - sizeof(void*)) = pool->free_list;
    pool->free_list = ptr;
    pthread_mutex_unlock(&pool->lock);
}

// Function to manage dynamic collection of records
void manage_records(int seed, int range_start, int range_end, size_t initial_capacity) {
    MemoryPool key_pool, offset_pool, node_pool;
    init_memory_pool(&key_pool, sizeof(int), initial_capacity);
    init_memory_pool(&offset_pool, sizeof(long), initial_capacity);
    init_memory_pool(&node_pool, sizeof(Node), initial_capacity);

    LogBuffer log_buffer = { .lock = PTHREAD_MUTEX_INITIALIZER };

    atomic_int key_counter = 0;
    long* offsets = (long*)allocate_from_pool(&offset_pool);
    int* keys = (int*)allocate_from_pool(&key_pool);
    Node* head = NULL;

    // Initialize keys and offsets
    for (size_t i = 0; i < initial_capacity; ++i) {
        int key = rand_r(&seed) % (range_end - range_start + 1) + range_start;
        keys[i] = key;
        if (i == 0) offsets[i] = key;
        else offsets[i] = offsets[i - 1] + key;

        Node* node = (Node*)allocate_from_pool(&node_pool);
        node->key = key;
        node->data.s_field = rand() % 100; // Example range
        node->data.i_field = rand() % 1000; // Example range
        node->data.f_field = (float)rand() / RAND_MAX;

        node->next = head;
        head = node;
    }

    // Simulate logging
    log_message(&log_buffer, "Initialized records");

    // Periodically save state to disk (simplified)
    FILE* file = fopen("records_backup.bin", "wb");
    if (file) {
        fwrite(keys, sizeof(int), initial_capacity, file);
        fwrite(offsets, sizeof(long), initial_capacity, file);
        fclose(file);

        log_message(&log_buffer, "State saved to disk");
    }

    // Free resources
    for (Node* current = head; current != NULL;) {
        Node* next = current->next;
        deallocate_to_pool(&node_pool, current);
        current = next;
    }
    deallocate_to_pool(&offset_pool, offsets);
    deallocate_to_pool(&key_pool, keys);

    pthread_mutex_destroy(&log_buffer.lock);
}

int main() {
    manage_records(42, 0, 100, 10);
    return 0;
}
```

