            HashTableNode* next_node = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(manager->buckets);
    manager->buckets = new_buckets;
    manager->capacity = new_capacity;
}

void add_connection(ConnectionStateManager* manager, ConnectionState* state) {
    pthread_mutex_lock(&manager->lock);

    if (manager->recent_count >= manager->recent_capacity) {
        // Resize recent connections array
        size_t new_recent_capacity = manager->recent_capacity ? manager->recent_capacity * 2 : INITIAL_CAPACITY;
        manager->recent_connections = (ConnectionState*)realloc(manager->recent_connections, 
                                                                new_recent_capacity * sizeof(ConnectionState));
    }

    manager->recent_connections[manager->recent_count++] = *state;

    size_t index = hash_function(state->connection_id, manager->capacity);
    HashTableNode* node = manager->buckets[index];

    while (node) {
        if (node->key == state->connection_id) break;
        node = node->next;
    }

    if (!node) { // New connection
        node = (HashTableNode*)malloc(sizeof(HashTableNode));
        node->key = state->connection_id;
        *node->data = *state;
        node->next = manager->buckets[index];
        manager->buckets[index] = node;

        if (manager->recent_count == manager->capacity) {
            resize_manager(manager);
        }
    } else { // Update existing connection
        node->data.last_active_timestamp = state->last_active_timestamp;
        node->data.bytes_sent += state->bytes_sent;
        node->data.bytes_received += state->bytes_received;
    }

    pthread_mutex_unlock(&manager->lock);

