void remove_connection(ConnectionStateManager* manager, uint64_t connection_id) {
    pthread_mutex_lock(&manager->lock);

    size_t index = hash_function(connection_id, manager->capacity);
    HashTableNode *node = manager->buckets[index], *prev = NULL;

    while (node) {
        if (node->key == connection_id) break;
        prev = node;
        node = node->next;
    }

    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (prev) {
        prev->next = node->next;
    } else {
        manager->buckets[index] = node->next;
    }

    free(node);

    pthread_mutex_unlock(&manager->lock);

    printf("Connection %llu removed.\n", connection_id);
}

