            node = node->next;
        }
    }

    fclose(file);
}

void destroy_manager(ConnectionStateManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        HashTableNode* node = manager->buckets[i];
        while (node) {
            HashTableNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(manager->buckets);
    free(manager->recent_connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

