    short s_field;
    int i_field;
    float f_field;
    EventTimestamp *event;
} Record;

typedef struct ListNode {
    long offset;
    int key;
    Record record;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} ThreadSafeList;

void initialize_rng() {
    srand((unsigned)time(NULL));
}

long calculate_offset(int *keys, size_t index) {
    long offset = 0;
    for (size_t i = 0; i < index; ++i) {
        offset += keys[i];
    }
    return offset + 100; // Constant added to each cumulative sum
}

int generate_key(size_t index) {
    return rand() % 100 + 1; // Keys in the range [1, 100]
}

void fill_random_record(Record *record) {
    record->s_field = rand() % 32768;
    record->i_field = rand() % 1000;
    record->f_field = (float)(rand() % 10000) / 100.0;
    record->event = malloc(sizeof(EventTimestamp));
    record->event->timestamp = time(NULL);
    record->event->type = EventType(rand() % 3);
}

ThreadSafeList* create_list() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(ThreadSafeList *list, long offset, int key, Record record) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    new_node->offset = offset;
    new_node->key = key;
    new_node->record = record;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        ListNode *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list(ThreadSafeList *list, void (*func)(ListNode*)) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        func(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void log_operation(const char* operation, const char* details) {
    printf("Log: %s - %s\n", operation, details);
}

void export_to_json(ThreadSafeList *list, FILE *file) {
    fprintf(file, "[\n");
    iterate_list(list, [](ListNode* node) {
        fprintf(file, "  {\n"
                     "    \"offset\": %ld,\n"
                     "    \"key\": %d,\n"
                     "    \"s_field\": %hd,\n"
                     "    \"i_field\": %d,\n"
                     "    \"f_field\": %.2f,\n"
                     "    \"event\": {\n"
                     "      \"timestamp\": %ld,\n"
                     "      \"type\": \"%s\"\n"
                     "    }\n"
                     "  }%s\n",
                     node->offset, node->key,
                     node->record.s_field, node->record.i_field,
                     node->record.f_field,
                     node->record.event->timestamp,
                     (node->record.event->type == EVENT_A ? "A" :
                      node->record.event->type == EVENT_B ? "B" : "C"),
                     (node->next != NULL ? "," : ""));
    });
    fprintf(file, "]");
}

void cleanup_list(ThreadSafeList *list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp->record.event);
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void create_and_manage_components(size_t num_elements) {
    initialize_rng();

    int *keys = (int*)malloc(num_elements * sizeof(int));
    long *offsets = (long*)malloc(num_elements * sizeof(long));

    for (size_t i = 0; i < num_elements; ++i) {
        keys[i] = generate_key(i);
        offsets[i] = calculate_offset(keys, i);
    }

    ThreadSafeList* list = create_list();

    for (size_t i = 0; i < num_elements; ++i) {
        Record record;
        fill_random_record(&record);

        insert_node(list, offsets[i], keys[i], record);
    }

    FILE *file = fopen("data.json", "w");
    if (file != NULL) {
        export_to_json(list, file);
        fclose(file);
    }

    cleanup_list(list);
    free(keys);
    free(offsets);
}

int main() {
    create_and_manage_components(1000);
    return 0;
}
