import threading
from hashlib import sha256
import uuid
import random
import string
from flask import Flask, jsonify, request

# Define a User Profile structure
class UserProfile:
    def __init__(self, user_name, email, password_hash, settings):
        self.user_id = str(uuid.uuid4())
        self.user_name = user_name
        self.email = email
        self.password_hash = password_hash
        self.settings = settings

# Helper function to generate random strings for testing
def random_string(length=10):
    return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

# Recursive function to ensure unique user_id
def create_user_profile(user_profiles, index, size):
    if index >= size:
        raise Exception("Unable to generate unique user profiles.")

    user_name = random_string()
    email = f"{user_name}@example.com"
    password_hash = sha256(random_string().encode()).hexdigest()
    settings = {
        'privacy_level': random.choice(['public', 'private']),
        'notification_preferences': random.choice(['email', 'sms', 'none'])
    }

    new_profile = UserProfile(user_name, email, password_hash, settings)

    if new_profile.user_id in user_profiles:
        return create_user_profile(user_profiles, index + 1, size)

    user_profiles[new_profile.user_id] = new_profile
    return new_profile

# Initialize and manage the profiles list with threading support
class UserProfileManager:
    def __init__(self):
        self.profiles_lock = threading.Lock()
        self.profiles = {}

    def initialize_profiles(self, initial_capacity=100):
        for i in range(initial_capacity):
            create_user_profile(self.profiles, 0, len(self.profiles))

    def add_profile(self):
        with self.profiles_lock:
            return create_user_profile(self.profiles, 0, len(self.profiles))

# Flask app to expose RESTful API
app = Flask(__name__)
profile_manager = UserProfileManager()

@app.route('/profiles', methods=['GET'])
def get_profiles():
    with profile_manager.profiles_lock:
        profiles_data = [{k: v.__dict__ for k, v in profile.items()} for profile in profile_manager.profiles.values()]
    return jsonify(profiles_data)

# Example of creating initial profiles
profile_manager.initialize_profiles()

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
```

