            if (res == CURLE_OK) {
                log_status("Resource updated successfully.");
                break;
            } else {
                log_status("Failed to update resource. Retrying...");
                retry_count++;
                sleep(2 * retry_count); // Exponential backoff
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (retry_count < MAX_RETRIES_PUT) ? 0 : -1;
}

int delete_resource_with_retry(const char *url) {
    CURL *curl;
    CURLcode res;
    int retry_count = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

