                retry_count++;
                sleep(2 * retry_count); // Exponential backoff
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (retry_count < MAX_RETRIES_DELETE) ? 0 : -1;
}

