#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 10000

typedef struct Node {
    double value;
    char *identifier;
    int ref_count;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

Node* create_node(double value, const char *identifier) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->identifier = strdup(identifier);
    node->ref_count = 1; // Initialize with a reference count of 1
    node->next = NULL;
    return node;
}

void insert_node(LinkedList* list, double value, const char *identifier) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(value, identifier);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void delete_node(LinkedList* list, const char *identifier) {
    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect) {
        if (strcmp((*indirect)->identifier, identifier) == 0) {
            Node* node_to_delete = *indirect;
            if (--node_to_delete->ref_count == 0) {
                *indirect = node_to_delete->next;
                free(node_to_delete->identifier);
                free(node_to_delete);
            }
            break;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void increase_ref_count(LinkedList* list, const char *identifier) {
    pthread_mutex_lock(&list->lock);

    Node* node = list->head;
    while (node) {
        if (strcmp(node->identifier, identifier) == 0) {
            ++node->ref_count;
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        if (--current->ref_count == 0) {
            free(current->identifier);
            free(current);
        }
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* list = create_list();

    // Example usage
    insert_node(list, 3.14, "node1");
    increase_ref_count(list, "node1");
    delete_node(list, "node1");

    cleanup_list(list);
    return 0;
}
