    int pipefd[2];
    pid_t cpid;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    cpid = fork();
    if (cpid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (cpid == 0) { // Child process
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        execlp("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else { // Parent process
        close(pipefd[1]);
        char buffer[256];
        ssize_t count;

        while ((count = read(pipefd[0], buffer, sizeof(buffer) - 1)) > 0) {
            buffer[count] = '\0';
            *output_array = realloc(*output_array, (*index + count + 1) * sizeof(char));
            if (!*output_array) exit(EXIT_FAILURE);
            strcpy(&((*output_array)[*index]), buffer);
            *index += count;
        }

        wait(NULL); // Wait for child process to finish
    }
}

void initialize_collections() {
    pthread_mutex_lock(&offset_pool.lock);
    pthread_mutex_lock(&key_pool.lock);

    long cumulative_sum = 0;
    int keys[INITIAL_POOL_SIZE];
    long offsets[INITIAL_POOL_SIZE];

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        keys[i] = rand() % 1000 + 1; // Unique integers from a specified range
        cumulative_sum += keys[i];
        offsets[i] = cumulative_sum + 10; // Constant value

        allocate_from_pool(&key_pool);
        allocate_from_pool(&offset_pool);
    }

    pthread_mutex_unlock(&key_pool.lock);
    pthread_mutex_unlock(&offset_pool.lock);
}

void* thread_safe_add_record(void *arg) {
    Record *record = (Record *)arg;

    pthread_rwlock_wrlock(&records_list.list_lock);
    if (!records_list.head) {
        records_list.head = record;
        records_list.tail = record;
    } else {
        records_list.tail->next = record;
        record->prev = records_list.tail;
        records_list.tail = record;
    }
    pthread_rwlock_unlock(&records_list.list_lock);

    return NULL;
}

void* allocate_record() {
    Record *record = (Record *)allocate_from_pool(&offset_pool);
    if (!record) return NULL;

    record->s_field = rand();
    record->i_field = rand();
    record->f_field = rand();
    record->timestamp = rand();
    record->metadata = (Metadata *)allocate_from_pool(&offset_pool);
    record->status_flag = rand() % 2;
    record->event_type = rand() % 10;
    record->metrics = rand();

    pthread_t thread;
    if (pthread_create(&thread, NULL, thread_safe_add_record, record)) {
        perror("Failed to create thread");
        return NULL;
    }
    pthread_join(thread, NULL);

    return record;
}

void cleanup() {
    Record *current = records_list.head;
    while (current) {
        Record *next = current->next;
        deallocate_to_pool(&offset_pool, current);
        current = next;
    }

    pthread_rwlock_destroy(&records_list.list_lock);
}

int main() {
    // Initialize memory pools
    init_memory_pools(&offset_pool);
    init_memory_pools(&key_pool);

    // Read integers from standard input
    int *integers = NULL;
    size_t integer_count = 0;
    if (read_integers(&integers, &integer_count) == -1) {
        perror("Failed to read integers");
        exit(EXIT_FAILURE);
    }

    // Find the largest integer
    int largest_integer = find_largest_integer(integers, integer_count);

    // Initialize collections and populate records with random values
    initialize_collections();
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        allocate_record();
    }

    // Execute a shell command and append output to collected data
    char *command_output = NULL;
    size_t output_index = 0;
    append_command_output(&command_output, &output_index, "echo 'Command Output'");

    printf("Largest integer: %d\n", largest_integer);
    if (command_output) {
        printf("Command output: %s\n", command_output);
    }

    // Cleanup resources
    cleanup();
    free(integers);

    return 0;
}

void init_memory_pools(MemoryPool *pool) {
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        pool->blocks[i] = malloc(pool->block_size);
        if (!pool->blocks[i]) {
            perror("Failed to allocate memory block");
            exit(EXIT_FAILURE);
        }
    }
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count > 0) {
        void *block = pool->blocks[--pool->count];
        pthread_mutex_unlock(&pool->lock);
        return block;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return malloc(pool->block_size);
    }
}

void deallocate_to_pool(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < INITIAL_POOL_SIZE) {
        pool->blocks[pool->count++] = block;
    } else {
        free(block);
    }
    pthread_mutex_unlock(&pool->lock);
}
