#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define enum for metadata categorization
typedef enum {
    CATEGORY_A,
    CATEGORY_B,
    CATEGORY_C
} Category;

// Metadata structure
typedef struct Metadata {
    char *string;
    Category category;
} Metadata;

// Event timestamp structure
typedef struct Event {
    time_t timestamp;
} Event;

// Record structure
typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    Event *event_ptr;
    unsigned long unique_id;
    Metadata *metadata;
    struct RecordNode *next;
} Record;

// Node for linked list
typedef struct RecordNode {
    Record record;
    struct RecordNode *next;
} RecordNode;

// Thread-safe linked list structure
typedef struct {
    RecordNode *head;
    pthread_mutex_t lock;
    size_t count;
} ThreadSafeList;

// Function prototypes
ThreadSafeList* initialize_list();
void free_list(ThreadSafeList *list);
void resize_array(int **array, size_t *size, size_t new_size);
void populate_record_fields(Record *record);
unsigned long generate_unique_id(size_t index);

// Initialize the list with thread-safe properties
ThreadSafeList* initialize_list() {
    ThreadSafeList *list = malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    // Initialize arrays
    size_t offset_size = 5, key_size = 5;
    long *offsets = calloc(offset_size, sizeof(long));
    int *keys = malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        free_list(list);
        return NULL;
    }

    // Initialize keys deterministically
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = (int)(i + 1) * 10; // Deterministic initialization example
    }

    // Calculate offsets
    long cumulative_sum = 0;
    for (size_t i = 0; i < offset_size; ++i) {
        cumulative_sum += keys[i % key_size]; // Wrap around if needed
        offsets[i] = cumulative_sum + 100;   // Constant addition example
    }

    printf("Offsets: ");
    for (size_t i = 0; i < offset_size; ++i) {
        printf("%ld ", offsets[i]);
    }
    printf("\nKeys: ");
    for (size_t i = 0; i < key_size; ++i) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    free(offsets);
    free(keys);

    return list;
}

// Free the memory allocated by the list
void free_list(ThreadSafeList *list) {
    if (!list) return;

    RecordNode *current = list->head;
    while (current) {
        RecordNode *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Resize an array dynamically
void resize_array(int **array, size_t *size, size_t new_size) {
    int *new_array = realloc(*array, new_size * sizeof(int));
    if (!new_array) return; // Handle failed allocation

    for (size_t i = *size; i < new_size; ++i) {
        new_array[i] = 0; // Initialize new elements
    }

    *array = new_array;
    *size = new_size;
}

// Populate fields of a record with random values
void populate_record_fields(Record *record) {
    if (!record) return;

    record->s_field = rand() % 100;
    record->i_field = rand() % 1000;
    record->f_field = (float)(rand() % 100) / 10.0f;
}

// Generate a unique identifier
unsigned long generate_unique_id(size_t index) {
    return (unsigned long)index * 123456789L; // Example deterministic ID generation
}

int main() {
    ThreadSafeList *list = initialize_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize list\n");
        return EXIT_FAILURE;
    }

    // Insert records into the list
    for (size_t i = 0; i < 5; ++i) {
        RecordNode *node = malloc(sizeof(RecordNode));
        if (!node) continue;

        populate_record_fields(&node->record);
        node->record.unique_id = generate_unique_id(i);

        Metadata metadata;
        metadata.string = "Example String";
        metadata.category = CATEGORY_A;
        node->record.metadata = &metadata;

        Event event;
        time(&event.timestamp);
        node->record.event_ptr = malloc(sizeof(Event));
        *node->record.event_ptr = event;

        pthread_mutex_lock(&list->lock);
        node->next = list->head;
        list->head = node;
        list->count++;
        pthread_mutex_unlock(&list->lock);
    }

    // Free the list
    free_list(list);

    return EXIT_SUCCESS;
}
