```python
import os
import logging
from PIL import Image
from concurrent.futures import ThreadPoolExecutor
import requests
from threading import Lock

# Initialize logger
logging.basicConfig(level=logging.INFO)

class ThemeCacheManager:
    def __init__(self, cache_root='themes_cache', max_cache_size=1024*1024*100):
        self.cache_root = os.getenv('THEME_CACHE_DIR', cache_root)
        if not os.path.exists(self.cache_root):
            os.makedirs(self.cache_root)

        self.max_cache_size = max_cache_size
        self.lock = Lock()
        self.cache_store = {}

    def get_bitmap_from_cache(self, filename):
        with self.lock:
            return self.cache_store.get(filename)

    def cache_bitmap(self, filename, image_data):
        try:
            img = Image.open(image_data)
            if os.path.exists(os.path.join(self.cache_root, filename)):
                os.remove(os.path.join(self.cache_root, filename))

            img.save(os.path.join(self.cache_root, filename))
            with self.lock:
                self.cache_store[filename] = img
        except Exception as e:
            logging.error(f"Error caching bitmap {filename}: {e}")

    def parse_and_cache_pngs(self):
        files = os.listdir(self.cache_root)
        for file in files:
            if file.endswith('.png'):
                filepath = os.path.join(self.cache_root, file)
                try:
                    with open(filepath, 'rb') as f:
                        self.cache_bitmap(file, f)
                except Exception as e:
                    logging.error(f"Error parsing PNG {file}: {e}")

    def cleanup_cache(self):
        total_size = sum(os.path.getsize(os.path.join(self.cache_root, f)) for f in os.listdir(self.cache_root))
        if total_size > self.max_cache_size:
            files = [(f, os.path.getmtime(os.path.join(self.cache_root, f))) for f in os.listdir(self.cache_root)]
            files.sort(key=lambda x: x[1])

            while total_size > self.max_cache_size and files:
                oldest_file, _ = files.pop(0)
                file_path = os.path.join(self.cache_root, oldest_file)
                total_size -= os.path.getsize(file_path)
                try:
                    with self.lock:
                        del self.cache_store[oldest_file]
                    os.remove(file_path)
                except Exception as e:
                    logging.error(f"Error cleaning up {file}: {e}")

    def background_cleanup(self):
        with ThreadPoolExecutor() as executor:
            while True:
                executor.submit(self.cleanup_cache)
                # Simulate periodic cleanup
                time.sleep(3600)

    def handle_external_data_sources(self, urls):
        for url in urls:
            try:
                response = requests.get(url)
                if response.status_code == 200:
                    with open(os.path.join(self.cache_root, 'external_' + os.path.basename(url)), 'wb') as f:
                        f.write(response.content)
                        self.cache_bitmap('external_' + os.path.basename(url), f)
            except Exception as e:
                logging.error(f"Error fetching from {url}: {e}")

    def configure_cache_policy(self, max_size=None, expiration_time=None):
        if max_size is not None:
            self.max_cache_size = max_size
        # Set cache expiration policies here

def start_theme_caching_system():
    theme_manager = ThemeCacheManager()

    external_sources = [
        'https://example.com/themes/theme1.png',
        'https://another-source.com/themes/theme2.png'
    ]
    theme_manager.handle_external_data_sources(external_sources)

    with ThreadPoolExecutor() as executor:
        executor.submit(theme_manager.background_cleanup)

    # Initial cache load
    theme_manager.parse_and_cache_pngs()

if __name__ == "__main__":
    start_theme_caching_system()
```

### Key Points:

1. **Initialization and Environment Configuration**: Checks for a default cache directory, initializes it if not present.
2. **Bitmap Caching and Recycling**: Uses `Pillow` to open and save images with error handling. Bitmaps are cached in memory and file system.
3. **Concurrent Access Handling**: Utilizes threading locks to manage concurrent access safely.
4. **Periodic Cleanup**: Runs a background cleanup task using a thread pool executor for periodic cache maintenance.
5. **Handling External Sources**: Fetches themes from external URLs with error handling.
6. **Configurable Policies**: Placeholder for configuring maximum size and expiration policies.

This code provides the foundation for a robust caching solution, focusing on efficient bitmap management, concurrency, and extensibility to support cloud integration and multiple data sources. Adjustments can be made to tailor it to specific application requirements and environments.']

