const crypto = require('crypto');

// Cache configuration
let cache = new Map();
const maxCacheSize = 10; // Adjust based on system load and resource constraints

function getFilePaths(certDir, privateKeyFile) {
    const certFile = path.join(certDir, 'cert.pem');
    return { certFile, privateKeyFile };
}

async function readAndCombineFiles(certPath, privateKeyPath) {
    try {
        const [certData, privateKeyData] = await Promise.all([
            fs.promises.readFile(certPath),
            fs.promises.readFile(privateKeyPath)
        ]);
        return Buffer.concat([Buffer.from('-----BEGIN CERTIFICATE-----\n'), certData, Buffer.from('\n-----END CERTIFICATE-----\n'), Buffer.from('-----BEGIN PRIVATE KEY-----\n'), privateKeyData, Buffer.from('\n-----END PRIVATE KEY-----')]).toString();
    } catch (error) {
        console.error(`Error reading files: ${error.message}`);
        throw new Error('Failed to read certificate or private key.');
    }
}

async function getCachedCertificate(certDir, privateKeyFile, requestId) {
    const cacheKey = `${certDir}-${privateKeyFile}`;

    if (cache.has(cacheKey)) {
        console.log(`Cache hit for request ID: ${requestId}`);
        return cache.get(cacheKey);
    }

    try {
        const { certFile } = getFilePaths(certDir, privateKeyFile);
        const pemData = await readAndCombineFiles(certFile, privateKeyFile);

        if (cache.size >= maxCacheSize) {
            // Evict the least recently used item
            const firstKey = cache.keys().next().value;
            cache.delete(firstKey);
        }

        cache.set(cacheKey, pemData);
        console.log(`Cache stored for request ID: ${requestId}`);

        return pemData;
    } catch (error) {
        console.error(`Error processing request ID: ${requestId}, Error: ${error.message}`);
        throw error; // Rethrow to handle at a higher level if necessary
    }
}

