            }
            catch (Exception ex)
            {
                Log($"Validation failed on attempt {attempt}: {ex.Message}");
                if (attempt < 3) Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))).Wait();
                else throw new Exception("Max retry attempts reached for validation");
            }
        }
