import threading
from functools import lru_cache
from typing import Callable, Dict, Any, Optional
import xml.etree.ElementTree as ET

class FactoryRegistry:
    def __init__(self):
        self._factories = {}
        self._lock = threading.Lock()

    def register(self, factory_id: str, factory_function: Callable[..., Any]) -> None:
        with self._lock:
            self._factories[factory_id] = factory_function

    def unregister(self, factory_id: str) -> None:
        with self._lock:
            if factory_id in self._factories:
                del self._factories[factory_id]

    def get_factory(self, factory_id: str) -> Optional[Callable[..., Any]]:
        with self._lock:
            return self._factories.get(factory_id)

class XMLSerializer:
    @staticmethod
    def serialize(data: Dict[str, Any], metadata: Optional[Dict[str, str]] = None) -> str:
        root = ET.Element("root")

        if metadata:
            meta_elem = ET.SubElement(root, "metadata")
            for key, value in metadata.items():
                meta_tag = ET.SubElement(meta_elem, key)
                meta_tag.text = value

        def build_xml_element(parent: ET.Element, data):
            if isinstance(data, dict):
                for key, value in data.items():
                    child = ET.SubElement(parent, key)
                    build_xml_element(child, value)
            else:
                parent.text = str(data)

        build_xml_element(root, data)
        return ET.tostring(root).decode()

    @staticmethod
    def deserialize(xml_data: str) -> Dict[str, Any]:
        try:
            root = ET.fromstring(xml_data)
            metadata = {child.tag: child.text for child in root.find("metadata") or []}

            def parse_xml_element(element):
                if list(element):
                    return {child.tag: parse_xml_element(child) for child in element}
                else:
                    return element.text

            data = parse_xml_element(root)
            return {"data": data, "metadata": metadata}
        except ET.ParseError as e:
            raise ValueError(f"Deserialization failed at node '{e.position}': {e}") from e

class CacheManager:
    def __init__(self):
        self._cache_lock = threading.Lock()
        self._cache = {}

    @lru_cache(maxsize=128)
    def get_cached_xml(self, key: str) -> Optional[str]:
        with self._cache_lock:
            return self._cache.get(key)

    def set_cache(self, key: str, value: str):
        with self._cache_lock:
            self._cache[key] = value

class DataProcessingFramework:
    def __init__(self):
        self.factory_registry = FactoryRegistry()
        self.cache_manager = CacheManager()

    def register_factory(self, factory_id: str, factory_function: Callable[..., Any]) -> None:
        self.factory_registry.register(factory_id, factory_function)

    def unregister_factory(self, factory_id: str) -> None:
        self.factory_registry.unregister(factory_id)

    def get_xml_representation(self, data_id: str, data_structure: Dict[str, Any], metadata: Optional[Dict[str, str]] = None) -> str:
        cached_xml = self.cache_manager.get_cached_xml(data_id)
        if cached_xml:
            return cached_xml

        xml_data = XMLSerializer.serialize(data_structure, metadata)
        self.cache_manager.set_cache(data_id, xml_data)
        return xml_data

    def process_from_xml(self, xml_data: str) -> Dict[str, Any]:
        parsed_data = XMLSerializer.deserialize(xml_data)
        factory_function = self.factory_registry.get_factory(parsed_data['data'].get('type'))

        if not factory_function:
            raise ValueError(f"Factory function for type '{parsed_data['data'].get('type')}' not found.")

        return factory_function(**parsed_data['data'])

# Example Usage
def sample_factory_function(**kwargs):
    # Sample processing logic here
    return kwargs

framework = DataProcessingFramework()
framework.register_factory("sample_type", sample_factory_function)

xml_representation = framework.get_xml_representation(
    "unique_id_1",
    {"type": "sample_type", "value": 42},
    metadata={"version": "1.0"}
)
result_data = framework.process_from_xml(xml_representation)

print(result_data)  # Output processed data
```']

