```java
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import io.projectreactor.core.publisher.Flux;
import io.projectreactor.netty.http.client.HttpClient;
import reactor.core.scheduler.Schedulers;
import reactor.netty.http.client.HttpClientResponse;
import reactor.util.context.Context;

import java.net.URI;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

// Mock ServiceConfiguration
class ServiceConfiguration {
    public String getServiceUrl(int index) {
        List<String> trustedServices = List.of("http://service1", "http://service2", "http://service3");
        return trustedServices.get(index % trustedServices.size());
    }
}

public class ReactiveHttpClient {

    private final HttpClient httpClient;
    private final ServiceConfiguration serviceConfig;
    private final AtomicInteger successCount = new AtomicInteger();
    private final AtomicInteger errorCount = new AtomicInteger();

    public ReactiveHttpClient() {
        this.httpClient = HttpClient.create()
                .wiretap(true)
                .responseTimeout(Duration.ofSeconds(10))
                .doOnConnected(conn -> conn
                        .addHandlerLast((req, resp) -> {
                            System.out.println("Request: " + req.headers().toSingleValueMap());
                            return resp;
                        }))
                .doAfterResponse(resp -> {
                    System.out.println("Response Status Code: " + resp.status());
                    System.out.println("Response Headers: " + resp.responseHeaders().asHttpHeaders().toString());
                });

        this.serviceConfig = new ServiceConfiguration();

        RetryConfig retryConfig = RetryConfig.custom()
                .maxAttempts(5)
                .waitDuration(Duration.ofMillis(100))
                .jitterer(RetryConfig.Jiterrer.DEFAULT)
                .build();

        Retry retry = Retry.of("http-retry", retryConfig);
    }

    public void sendRequests(int requestCount) {
        Flux.range(0, requestCount)
            .flatMap(index -> httpClient.get()
                    .uri(serviceConfig.getServiceUrl(index))
                    .retrieve()
                    .bodyToMono(String.class)
                    .retryWhen(Retry.backoff(3, Duration.ofMillis(100), Duration.ofSeconds(1)))
                    .doOnSuccess(response -> successCount.incrementAndGet())
                    .doOnError(error -> errorCount.incrementAndGet()))
            .subscribe(
                response -> System.out.println("Response: " + response),
                error -> System.err.println("Error: " + error)
            );
    }

    public void start() {
        sendRequests(1000);
    }

    public static void main(String[] args) {
        ReactiveHttpClient client = new ReactiveHttpClient();
        client.start();
    }
}
