#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct node {
    unsigned int data;
    struct node *next;
    struct node *prev;
} Node;

typedef unsigned long timestamp;

typedef struct memory_pool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->used_blocks = 0;
    mp->pool = malloc(block_size * pool_size);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks >= mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }
    void *block = ((char*)mp->pool) + (mp->used_blocks * mp->block_size);
    mp->used_blocks++;
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

unsigned long hash_function(unsigned int index, unsigned int rand_const) {
    return (index * 2654435761u) ^ rand_const; // Simple FNV-like hash
}

void initialize_arrays_and_list(size_t size, unsigned long **identifiers, Node ***nodes, timestamp **timestamps) {
    srand(time(NULL));

    MemoryPool *node_pool = create_memory_pool(sizeof(Node), size);

    *identifiers = (unsigned long*)malloc(size * sizeof(unsigned long));
    *nodes = (Node**)malloc(size * sizeof(Node*));
    *timestamps = (timestamp*)malloc(size * sizeof(timestamp));

    unsigned int rand_const = rand() % 10 + 1;

    for (size_t i = 0; i < size; ++i) {
        (*identifiers)[i] = hash_function(i, rand_const);

        Node *new_node = (Node*)allocate_from_pool(node_pool);
        if (!new_node) {
            fprintf(stderr, "Memory pool exhausted\n");
            exit(EXIT_FAILURE);
        }
        new_node->data = rand() % 100; // Arbitrary range
        (*nodes)[i] = new_node;

        (*timestamps)[i] = (timestamp)(rand() % 1000000); // Arbitrary timestamp

        if (i > 0) {
            (*nodes)[i-1]->next = new_node;
            new_node->prev = (*nodes)[i-1];
        }
    }

    (*nodes)[size - 1]->next = (*nodes)[0]; // Circular link
    (*nodes)[0]->prev = (*nodes)[size - 1];

    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    void resize_identifiers(unsigned long **identifiers, size_t *current_size) {
        size_t new_size = *current_size * 2;
        unsigned long *new_array = (unsigned long*)realloc(*identifiers, new_size * sizeof(unsigned long));

        if (!new_array) {
            fprintf(stderr, "Failed to resize identifiers array\n");
            exit(EXIT_FAILURE);
        }
        *identifiers = new_array;
        *current_size = new_size;
    }

    void iterate_circular_list(Node *start_node) {
        Node *current = start_node;
        do {
            printf("Node Data: %u, Timestamp: %lu\n", current->data, *(timestamp*)current);
            current = current->next;
        } while (current != start_node);
    }

    // Example usage of resizing
    size_t identifiers_size = size;
    resize_identifiers(identifiers, &identifiers_size);

    // Example iteration over the circular list
    iterate_circular_list((*nodes)[0]);

    free_memory_pool(node_pool);
}

int main() {
    unsigned long *identifiers = NULL;
    Node **nodes = NULL;
    timestamp *timestamps = NULL;

    initialize_arrays_and_list(10, &identifiers, &nodes, &timestamps);

    free(identifiers);
    free(nodes);
    free(timestamps);

    return 0;
}
