#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s_val;
    int i_val;
    float f_val;
    uint64_t timestamp;
    char event_type;
    struct Record* prev;
    struct Record* next;
} Record;

typedef struct MemoryPool {
    void** blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct LinkedList {
    Record* head;
    Record* tail;
    pthread_rwlock_t rwlock;
} LinkedList;

MemoryPool* create_memory_pool(size_t initial_size, size_t block_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->blocks = (void**)calloc(initial_size, sizeof(void*));
    pool->block_size = block_size;
    pool->num_blocks = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->blocks[0] == NULL) {  // Expand pool
        void** new_blocks = (void**)realloc(pool->blocks, (pool->num_blocks + 10) * sizeof(void*));
        for (size_t i = 0; i < 10; ++i) {
            new_blocks[pool->num_blocks + i] = malloc(pool->block_size);
        }
        pool->blocks = new_blocks;
        pool->num_blocks += 10;
    }
    void* block = pool->blocks[0];
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i] != NULL) {
            pool->blocks[i] = pool->blocks[i + 1];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i] != NULL) {
            free(pool->blocks[i]);
        }
    }
    free(pool->blocks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void initialize_arrays(long* offsets, int* keys, size_t n) {
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        keys[i] = rand() % 100000 + 1;
        if (i > 0) {
            offsets[i] = offsets[i - 1] + keys[i - 1];
        } else {
            offsets[i] = keys[0];
        }
    }
}

Record* create_record(MemoryPool* pool, uint64_t timestamp, char event_type) {
    Record* record = (Record*)allocate_from_pool(pool);
    record->s_val = rand() % 100;
    record->i_val = rand() % 100000;
    record->f_val = ((float)rand()) / RAND_MAX * 100.0f;
    record->timestamp = timestamp ? timestamp : time(NULL);
    record->event_type = event_type;
    record->prev = NULL;
    record->next = NULL;
    return record;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void insert_record(LinkedList* list, Record* new_record) {
    pthread_rwlock_wrlock(&list->rwlock);
    if (list->tail == NULL) {
        list->head = new_record;
        list->tail = new_record;
    } else {
        list->tail->next = new_record;
        new_record->prev = list->tail;
        list->tail = new_record;
    }
    pthread_rwlock_unlock(&list->rwlock);
}

void iterate_linked_list(LinkedList* list, void (*callback)(Record*)) {
    Record* current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}

void free_linked_list(LinkedList* list, MemoryPool* pool) {
    pthread_rwlock_wrlock(&list->rwlock);
    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_unlock(&list->rwlock);
}

void free_linked_list_resources(LinkedList* list, MemoryPool* pool) {
    free_linked_list(list, pool);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
    free_memory_pool(pool);
}

int main() {
    size_t num_records = 1000;
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    MemoryPool* pool = create_memory_pool(10, sizeof(Record));
    LinkedList* list = create_linked_list();

    initialize_arrays(offsets, keys, num_records);

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = create_record(pool, time(NULL), 'A' + rand() % 26);
        insert_record(list, record);
    }

    iterate_linked_list(list, [](Record* r) { printf("Record: %d\n", r->i_val); });

    free(offsets);
    free(keys);

    free_linked_list_resources(list, pool);

    return 0;
}
