void mem_pool_init(MemoryPool *pool, size_t block_size, int count) {
    pool->block_size = block_size;
    pool->free_count = count;
    pthread_mutex_init(&pool->lock, NULL);
    pool->free_list = (void **)malloc(count * sizeof(void *));

    for (int i = 0; i < count; ++i) {
        pool->free_list[i] = malloc(block_size);
    }
}

void* mem_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *block = NULL;
    if (atomic_fetch_sub_explicit(&pool->free_count, 1, memory_order_relaxed) > 0) {
        block = pool->free_list[pool->free_count];
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void mem_pool_free(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    if (atomic_fetch_add_explicit(&pool->free_count, 1, memory_order_relaxed) < MAX_ALLOCATIONS) {
        pool->free_list[pool->free_count] = block;
    }
    pthread_mutex_unlock(&pool->lock);
}

// Initialize arrays
void init_arrays(int range) {
    int initial_size = 1000; // Initial size for offset and key arrays

    if (offset == NULL || key == NULL) {
        offset = (int*)mem_pool_alloc(&mem_pool);
        key = (int*)mem_pool_alloc(&mem_pool);

        atomic_store(&offset_size, initial_size);
        atomic_store(&key_size, initial_size);

        for (int i = 0; i < initial_size; ++i) {
            key[i] = generate_unique_key(range);
            offset[i] = (i == 0) ? key[0] + 100 : offset[i - 1] + key[i];
        }
    } else {
        // Resize logic if needed
    }
}

// Initialize the doubly linked list
void init_doubly_linked_list() {
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = tail = (Record*)mem_pool_alloc(&mem_pool);
        head->prev = head->next = NULL;
        init_random();
        // Initialize with random values
        head->s_value = rand() % 32767;
        head->i_value = rand() % INT_MAX;
        head->f_value = ((float)rand()) / RAND_MAX;
        head->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&list_lock);
}

// Dynamic resizing function
void resize_arrays(int new_size) {
    pthread_mutex_t resize_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&resize_lock);

    int *new_offset = (int*)mem_pool_alloc(&mem_pool);
    int *new_key = (int*)mem_pool_alloc(&mem_pool);

    for (int i = 0; i < new_size; ++i) {
        if (i < atomic_load(&offset_size)) {
            new_offset[i] = offset[i];
            new_key[i] = key[i];
        } else {
            new_key[i] = generate_unique_key(10000); // Example range
            new_offset[i] = (i == 0) ? new_key[0] + 100 : new_offset[i - 1] + new_key[i];
        }
    }

    free(offset);
    free(key);

    offset = new_offset;
    key = new_key;

    atomic_store(&offset_size, new_size);
    atomic_store(&key_size, new_size);

    pthread_mutex_unlock(&resize_lock);
}

// Linked list traversal
void traverse_linked_list_forward() {
    Record *current = head;
    while (current != NULL) {
        // Process current record
        printf("Short: %d, Int: %d, Float: %.2f, Timestamp: %ld\n", 
               current->s_value, current->i_value, current->f_value, current->timestamp);
        current = current->next;
    }
}

void traverse_linked_list_backward() {
    Record *current = tail;
    while (current != NULL) {
        // Process current record
        printf("Short: %d, Int: %d, Float: %.2f, Timestamp: %ld\n", 
               current->s_value, current->i_value, current->f_value, current->timestamp);
        current = current->prev;
    }
}

