```javascript
async function processRecordsAsync(records, initialValue, callback) {
  return new Promise((resolve, reject) => {
    try {
      const result = records.reduce(async (accPromise, currentRecord) => {
        try {
          const acc = await accPromise;
          return callback(acc, currentRecord);
        } catch (error) {
          throw error;
        }
      }, Promise.resolve(initialValue));

      resolve(result);
    } catch (error) {
      reject(`Error processing records: ${error.message}`);
    }
  });
}

// Sample usage
(async () => {
  const sampleRecords = [
    { value: Math.floor(Math.random() * 100) },
    { value: Math.floor(Math.random() * 100) },
    { value: Math.floor(Math.random() * 100) },
  ];

  const initialValue = 0;

  function sumCallback(accumulated, currentRecord) {
    return new Promise((resolve) => {
      setTimeout(() => resolve(accumulated + currentRecord.value), 10);
    });
  }

  try {
    const result = await processRecordsAsync(sampleRecords, initialValue, sumCallback);
