Record* initialize_records(size_t initial_size, size_t max_capacity, int seed, int str_range_start, int str_range_end, size_t string_pool_size) {
    srand(seed);
    char *string_pool = malloc(string_pool_size);

    if (!string_pool) {
        return NULL; // Handle memory allocation failure
    }

    Record *records = malloc(initial_size * sizeof(Record));
    if (!records) {
        free(string_pool);
        return NULL;
    }

    size_t current_capacity = initial_size;

    for (size_t i = 0; i < current_capacity; ++i) {
        records[i].offset = rand() % 1000000L;
        records[i].key = rand() % 1000;

        int value = rand() % (str_range_end - str_range_start + 1) + str_range_start;
        records[i].data.value = value;

        size_t len = rand() % 10 + 5; // Random length between 5 and 14
        if (string_pool_size < len) {
            free(records);
            free(string_pool);
            return NULL; // Handle invalid string length allocation
        }

        records[i].data.str = strndup(string_pool, len);
        if (!records[i].data.str) {
            for (size_t j = 0; j < i; ++j) {
                free(records[j].data.str);
            }
            free(records);
            free(string_pool);
            return NULL;
        }

        memmove(string_pool, string_pool + len, string_pool_size - len);
    }

    return records;
}

void free_records(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].data.str);
    }
    free(records);
}
