async function processRecordsAsync(records) {
    try {
        let totalWeight = 0;
        let weightedSum = 0;

        for (const record of records) {
            const weight = record.data.value + record.data.str.length;
            weightedSum += weight * record.data.value;
            totalWeight += weight;
        }

        if (totalWeight === 0) return 0; // Avoid division by zero

        return weightedSum / totalWeight;
    } catch (error) {
        console.error('Error processing records:', error);
        return null;
    }
}

// Sample usage
(async () => {
    const initialSize = 5;
    const maxCapacity = 10;
    const seed = 42;
    const strRangeStart = 1;
    const strRangeEnd = 100;
    const stringPoolSize = 1000; // Arbitrary size for the example

    const records = initialize_records(initialSize, maxCapacity, seed, strRangeStart, strRangeEnd, stringPoolSize);

    if (records) {
        console.log('Processing records...');
        const result = await processRecordsAsync(records);
        console.log('Weighted average:', result);

        free_records(records, initialSize);
    } else {
        console.error('Failed to initialize records.');
    }
})();
