#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

typedef struct Metadata {
    char data[MAX_METADATA_LENGTH];
} Metadata;

typedef enum EventType { TYPE_A, TYPE_B, TYPE_C } EventType;
typedef enum Status { STATUS_OK, STATUS_ERROR } Status;
typedef struct Record {
    long offset;
    int key;
    struct Record *prev;
    struct Record *next;
    int timestamp;
    Metadata metadata;
    EventType event_type;
    Status status;
    int priority;
    double weight;
    double location_x;
    double location_y;
    int duration;
} Record;

typedef struct MemoryPool {
    void* memory;
    size_t size;
    pthread_mutex_t lock;
    // Additional fields for adaptive sizing strategies
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->memory = malloc(initial_size);
    pool->size = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* allocate_record(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate record");
        exit(EXIT_FAILURE);
    }
    // Populate the record with random values
    record->offset = rand();
    record->key = rand() % 1000;
    record->timestamp = time(NULL);
    snprintf(record->metadata.data, MAX_METADATA_LENGTH, "RandomMetadata_%d", rand());
    record->event_type = (EventType)(rand() % 3);
    record->status = (Status)(rand() % 2);
    record->priority = rand() % 10;
    record->weight = (double)rand() / RAND_MAX * 100.0;
    record->location_x = (double)rand() / RAND_MAX * 100.0;
    record->location_y = (double)rand() / RAND_MAX * 100.0;
    record->duration = rand() % 60;
    pthread_mutex_unlock(&pool->lock);
    return record;
}

typedef struct {
    Record *head;
    Record *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(DoublyLinkedList *list) {
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_record(DoublyLinkedList *list, Record *record) {
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = record;
        list->tail = record;
        record->prev = NULL;
        record->next = NULL;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        record->next = NULL;
        list->tail = record;
    }
    pthread_mutex_unlock(&list->lock);
}

void initialize_records(size_t num_records, DoublyLinkedList **records_list) {
    *records_list = create_list();
    MemoryPool *pool = create_memory_pool(num_records * sizeof(Record));
    pthread_t threads[num_records];

    for (size_t i = 0; i < num_records; ++i) {
        pthread_create(&threads[i], NULL, [](void* arg) -> void* {
            size_t index = *(size_t*)arg;
            MemoryPool *pool = create_memory_pool(1024); // Simplified example
            Record *record = allocate_record(pool);
            insert_record(*((DoublyLinkedList**)arg + 1), record);
            return NULL;
        }, &i);
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_memory_pool(pool);
}

int main() {
    srand(time(NULL));
    size_t num_records = 10;
    DoublyLinkedList *records_list;

    initialize_records(num_records, &records_list);

    // Traverse and print the records for demonstration
    Record *current = records_list->head;
    while (current) {
        printf("Record Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }

    free_list(records_list);
    return 0;
}
```

