#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 100

typedef struct Item {
    double value;
    char buffer[MAX_STRING_LENGTH + 1];
    unsigned int ref_count;
    struct Item* next; // For linked list management
} Item;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Item* create_item(double value, const char* str) {
    if (strlen(str) >= MAX_STRING_LENGTH) {
        fprintf(stderr, "String length exceeds maximum limit.\n");
        return NULL;
    }

    Item* item = malloc(sizeof(Item));
    if (!item) {
        perror("Failed to allocate memory for item");
        return NULL;
    }

    item->value = value;
    strncpy(item->buffer, str, MAX_STRING_LENGTH);
    item->buffer[MAX_STRING_LENGTH] = '\0';
    item->ref_count = 1;
    item->next = NULL;

    return item;
}

void add_ref(Item* item) {
    if (item) {
        pthread_mutex_lock(&lock);
        item->ref_count++;
        pthread_mutex_unlock(&lock);
    }
}

void release_item(Item** head, Item* item) {
    if (!head || !item) return;

    pthread_mutex_lock(&lock);

    if (*head == item) {
        *head = item->next;
    } else {
        Item* current = *head;
        while (current && current->next != item) {
            current = current->next;
        }
        if (current) {
            current->next = item->next;
        }
    }

    pthread_mutex_unlock(&lock);

    if (--item->ref_count == 0) {
        free(item);
    }
}

double calculate_average(Item* head) {
    double sum = 0.0;
    unsigned int count = 0;

    Item* current = head;
    while (current) {
        sum += current->value;
        count++;
        current = current->next;
    }

    return count ? sum / count : 0.0;
}

void free_items(Item** head) {
    pthread_mutex_lock(&lock);

    Item* current = *head;
    while (current) {
        Item* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;

    pthread_mutex_unlock(&lock);
}
