#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    double value;
    int count;
    char* name;
} item;

void free_resources(double* doubles, char** strings, item** items, size_t num_items) {
    if (doubles) free(doubles);
    for (size_t i = 0; i < num_items; ++i) {
        if (strings && strings[i]) free(strings[i]);
        if (items && items[i]) {
            free(items[i]->name);
            free(items[i]);
        }
    }
    if (strings) free(strings);
    if (items) free(items);
}

item** manage_memory(const char* filename, double** doubles, char*** strings, size_t* num_items) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    *num_items = 0;
    size_t capacity = 10;
    *doubles = malloc(capacity * sizeof(double));
    *strings = malloc(capacity * sizeof(char*));

    item** items = malloc(capacity * sizeof(item*));
    if (!(*doubles) || !(*strings) || !items) {
        perror("Memory allocation failed");
        fclose(file);
        free_resources(*doubles, *strings, (item**)items, 0);
        return NULL;
    }

    char line[MAX_STRING_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        if (*num_items >= capacity) {
            capacity *= 2;
            *doubles = realloc(*doubles, capacity * sizeof(double));
            *strings = realloc(*strings, capacity * sizeof(char*));
            item** new_items = realloc(items, capacity * sizeof(item*));
            if (!(*doubles) || !(*strings) || !new_items) {
                perror("Memory reallocation failed");
                fclose(file);
                free_resources(*doubles, *strings, (item**)items, 0);
                return NULL;
            }
            items = new_items;
        }

        char* token = strtok(line, ",\n");
        if (!token) continue;

        double value = strtod(token, NULL);
        (*doubles)[(*num_items)] = value;

        token = strtok(NULL, ",\n");
        int count = (token) ? atoi(token) : 0;

        token = strtok(NULL, "\n");
        char* name = (token && *token) ? strdup(token) : strdup("");
        if (!name) {
            perror("String duplication failed");
            fclose(file);
            free_resources(*doubles, *strings, items, *num_items);
            return NULL;
        }

        (*strings)[(*num_items)] = name;

        item* new_item = malloc(sizeof(item));
        if (!new_item) {
            perror("Memory allocation for struct failed");
            free(name);
            fclose(file);
            free_resources(*doubles, *strings, items, *num_items);
            return NULL;
        }
        new_item->value = value;
        new_item->count = count;
        new_item->name = name;

        items[*num_items] = new_item;
        (*num_items)++;
    }

    fclose(file);

    // Shrink memory allocations to the used size
    *doubles = realloc(*doubles, (*num_items) * sizeof(double));
    *strings = realloc(*strings, (*num_items) * sizeof(char*));

    return items;
}
```

This code defines a `manage_memory` function which reads from a file and populates arrays for doubles, strings, and structs. It handles memory allocation dynamically and gracefully manages I/O errors and potential data inconsistencies. Resources are freed using the `free_resources` helper function to ensure no leaks occur.']

