#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char buffer[1]; // Flexible array member, actual size set dynamically
} Item;

typedef struct {
    Item *items;
    size_t capacity;
    pthread_mutex_t lock; // For thread-safe operations
} ItemArray;

ItemArray* create_item_array(size_t count, size_t max_length) {
    if (count == 0 || max_length == 0) return NULL;

    ItemArray *array = malloc(sizeof(ItemArray));
    if (!array) return NULL;

    array->items = calloc(count, sizeof(Item) + max_length - 1);
    if (!array->items) {
        free(array);
        return NULL;
    }

    array->capacity = count;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void validate_and_set_string(Item *item, const char *str, size_t max_length) {
    size_t len = strlen(str);
    if (len >= max_length) {
        fprintf(stderr, "String too long: %zu > %zu\n", len, max_length - 1);
        return;
    }
    memcpy(item->buffer, str, len + 1);
}

double calculate_average(ItemArray *array) {
    if (!array) return 0.0;

    double sum = 0.0;
    size_t count = array->capacity;

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < count; ++i) {
        sum += array->items[i].value;
    }
    pthread_mutex_unlock(&array->lock);

    return count ? (sum / count) : 0.0;
}

void filter_items(ItemArray *array, double min_val, double max_val, ItemArray **filtered_array) {
    if (!array || !filtered_array) return;

    size_t filtered_count = 0;
    for (size_t i = 0; i < array->capacity; ++i) {
        if (array->items[i].value >= min_val && array->items[i].value <= max_val)
            filtered_count++;
    }

    *filtered_array = create_item_array(filtered_count, strlen(array->items[0].buffer));
    if (!*filtered_array) return;

    pthread_mutex_lock(&array->lock);
    size_t j = 0;
    for (size_t i = 0; i < array->capacity; ++i) {
        if (array->items[i].value >= min_val && array->items[i].value <= max_val) {
            (*filtered_array)->items[j] = array->items[i];
            j++;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void free_item_array(ItemArray *array) {
    if (array) {
        free(array->items);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

// Example usage
int main() {
    ItemArray *array = create_item_array(5, 50);
    if (!array) return EXIT_FAILURE;

    validate_and_set_string(&array->items[0], "Example string", 50);
    array->items[0].value = 10.5;

    // Add more items...

    double avg = calculate_average(array);
    printf("Average: %f\n", avg);

    ItemArray *filtered_array = NULL;
    filter_items(array, 9.0, 11.0, &filtered_array);
    if (filtered_array) {
        free_item_array(filtered_array);
    }

    free_item_array(array);
    return EXIT_SUCCESS;
}
```

### Explanation:
