    collection->buckets = (Node**)custom_alloc(bucket_count * sizeof(Node*));
    for (size_t i = 0; i < bucket_count; ++i) {
        collection->buckets[i] = NULL;
    }
    collection->bucket_count = bucket_count;
    collection->item_count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    collection->cache.head = NULL;
    collection->cache.tail = NULL;
    collection->cache.capacity = cache_capacity;
    pthread_mutex_init(&collection->cache.lock, NULL);

    return collection;
}

void destroy_collection(Collection *collection) {
    // Free all items and nodes
    for (size_t i = 0; i < collection->bucket_count; ++i) {
        Node *node = collection->buckets[i];
        while (node) {
            Node *next = node->next;
            custom_free(node->item);
            custom_free(node);
            node = next;
        }
    }
    custom_free(collection->buckets);
    pthread_mutex_destroy(&collection->lock);

    // Clear cache
    Node *node = collection->cache.head;
    while (node) {
        Node *next = node->next;
        custom_free(node->item);
        custom_free(node);
        node = next;
    }
    pthread_mutex_destroy(&collection->cache.lock);

    custom_free(collection);
}

Item* insert_item(Collection *collection, double value, const char *str) {
    size_t index = get_bucket_index(collection, value);
    Node **bucket = &collection->buckets[index];

    pthread_mutex_lock(&collection->lock);

    // Check for existing item
    Node *node = *bucket;
    while (node) {
        if (node->item->value == value && strcmp(node->item->buffer, str) == 0) {
            increment_ref(node->item);
            pthread_mutex_unlock(&collection->lock);
            return node->item;
        }
        node = node->next;
    }

    // Create new item
    Item *item = (Item*)custom_alloc(sizeof(Item));
    item->value = value;
    strncpy(item->buffer, str, MAX_BUFFER_SIZE - 1);
    atomic_init(&item->ref_count, 1);

    Node *new_node = (Node*)custom_alloc(sizeof(Node));
    new_node->item = item;
    new_node->next = *bucket;
    new_node->prev = NULL;

    if (*bucket) {
        (*bucket)->prev = new_node;
    }
    *bucket = new_node;

    collection->item_count++;

    pthread_mutex_unlock(&collection->lock);

    cache_access(&collection->cache, new_node);
    return item;
}

void delete_item(Collection *collection, Item *item) {
    if (atomic_fetch_sub(&item->ref_count, 1) > 1) {
        return;
    }

    size_t index = get_bucket_index(collection, item->value);

    pthread_mutex_lock(&collection->lock);
    Node **bucket = &collection->buckets[index];
    Node *node = *bucket;

    while (node && node->item != item) {
        node = node->next;
    }

    if (!node) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    if (node->prev) {
        node->prev->next = node->next;
    } else {
        *bucket = node->next;
    }
    if (node->next) {
        node->next->prev = node->prev;
    }

    custom_free(node->item);
    custom_free(node);

    collection->item_count--;

    pthread_mutex_unlock(&collection->lock);
}

Item* find_item(Collection *collection, double value) {
    size_t index = get_bucket_index(collection, value);

    pthread_mutex_lock(&collection->lock);
    Node *node = collection->buckets[index];

    while (node) {
        if (node->item->value == value) {
            increment_ref(node->item);
            cache_access(&collection->cache, node);
            pthread_mutex_unlock(&collection->lock);
            return node->item;
        }
        node = node->next;
