    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void cache_access(Cache *cache, Node *node) {
    pthread_mutex_lock(&cache->lock);

    if (cache->head != node) {
        if (node->prev) {
            node->prev->next = node->next;
        }
        if (node->next) {
            node->next->prev = node->prev;
        }

        node->next = cache->head;
        if (cache->head) {
            cache->head->prev = node;
        }
        cache->head = node;

        if (!cache->tail) {
            cache->tail = node;
        }

        if (node == cache->tail) {
            // Node is at the end, no need to move
        } else {
            if (cache->tail) {
                cache->tail = cache->tail->prev;
            }
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

Node* evict_from_cache(Cache *cache) {
    pthread_mutex_lock(&cache->lock);

    Node *node_to_evict = cache->tail;

    if (node_to_evict) {
        if (node_to_evict->prev) {
            node_to_evict->prev->next = NULL;
        } else {
            cache->head = NULL;
        }
        cache->tail = node_to_evict->prev;
    }

    pthread_mutex_unlock(&cache->lock);
    return node_to_evict;
}

int serialize_collection(Collection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&collection->bucket_count, sizeof(size_t), 1, file);
    fwrite(&collection->item_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->bucket_count; ++i) {
        Node *node = collection->buckets[i];
        while (node) {
            fwrite(&node->item->value, sizeof(double), 1, file);
            fwrite(node->item->buffer, MAX_BUFFER_SIZE, 1, file);
            node = node->next;
        }
    }

    fclose(file);
    return 0;
}

Collection* deserialize_collection(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t bucket_count, item_count;
    fread(&bucket_count, sizeof(size_t), 1, file);
    fread(&item_count, sizeof(size_t), 1, file);

    Collection *collection = create_collection(bucket_count, 0); // Cache capacity is not serialized

    for (size_t i = 0; i < item_count; ++i) {
        double value;
        char buffer[MAX_BUFFER_SIZE];
        fread(&value, sizeof(double), 1, file);
        fread(buffer, MAX_BUFFER_SIZE, 1, file);

        insert_item(collection, value, buffer);
    }

    fclose(file);
    return collection;
}

void increment_ref(Item *item) {
    atomic_fetch_add(&item->ref_count, 1);
}

void decrement_ref(Item *item) {
    if (atomic_fetch_sub(&item->ref_count, 1) == 1) {
        delete_item(NULL, item); // Pass the actual collection
    }
}

unsigned long hash_double(double value) {
    return ((unsigned long)value) % ULONG_MAX;
}

size_t get_bucket_index(Collection *collection, double value) {
    unsigned long hash = hash_double(value);
    return hash % collection->bucket_count;
}

