    free(ptr);
}

// Doubly linked list structure with mutex for thread safety
typedef struct LinkedList {
    Record* head;
    Record* tail;
    pthread_mutex_t listMutex;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->listMutex, NULL);
    return list;
}

void insertRecord(LinkedList* list, int value, long offset, int key, double metric) {
    Record* newRecord = malloc(sizeof(Record));

    newRecord->value = value;
    newRecord->offset = *allocateLong();
    *(newRecord->offset) = offset;

    newRecord->key = *allocateInt();
    *(newRecord->key) = key;

    newRecord->metric = metric; // Polynomial function not detailed here

    pthread_mutex_lock(&list->listMutex);

    if (list->head == NULL) {
        list->head = newRecord;
        list->tail = newRecord;
        newRecord->prev = NULL;
        newRecord->next = NULL;
    } else {
        list->tail->next = newRecord;
        newRecord->prev = list->tail;
        newRecord->next = NULL;
        list->tail = newRecord;
    }

    pthread_mutex_unlock(&list->listMutex);
}

void deleteRecord(LinkedList* list, Record* record) {
    if (record == NULL) return;

    pthread_mutex_lock(&list->listMutex);

    if (record->prev != NULL)
        record->prev->next = record->next;
    else
        list->head = record->next;

    if (record->next != NULL)
        record->next->prev = record->prev;
    else
        list->tail = record->prev;

    freeLong(&record->offset);
    freeInt(&record->key);

    pthread_mutex_unlock(&list->listMutex);

    free(record);
}

void destroyList(LinkedList* list) {
    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        deleteRecord(list, current);
        current = next;
    }
    pthread_mutex_destroy(&list->listMutex);
    free(list);
}

// Example usage
int main() {
    initMemoryPools();

    LinkedList* list = createList();

    insertRecord(list, 10, 100L, 1, 2.5);
    // Additional operations...

    destroyList(list);

    return 0;
}
