#define INITIAL_HASH_TABLE_SIZE 16
#define MAX_PROTOCOLS 5

typedef struct Event {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol;
    size_t payload_size;
    struct Event *next;
} Event;

typedef struct HashNode {
    Event *event;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    unsigned int size;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    Event *head;
    Event *tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = malloc(pool_size);
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->offset + mp->block_size > mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }
    void *ptr = (char*)mp->pool + mp->offset;
    mp->offset += mp->block_size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

HashTable* create_hash_table(unsigned int size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned int hash_function(const char *ip) {
    unsigned long hash = 0;
    while (*ip) {
        hash = (hash << 5) + *ip++;
    }
    return hash % INITIAL_HASH_TABLE_SIZE;
}

void add_event(HashTable *ht, LinkedList *ll, const char *source_ip, const char *dest_ip, int protocol, size_t payload_size) {
    Event *event = (Event*)allocate_from_pool(/* memory pool */);
    if (!event) return;

    time(&event->timestamp);
    strncpy(event->source_ip, source_ip, sizeof(event->source_ip));
    strncpy(event->destination_ip, dest_ip, sizeof(event->destination_ip));
    event->protocol = protocol;
    event->payload_size = payload_size;
    event->next = NULL;

    pthread_mutex_lock(&ht->lock);
    unsigned int index = hash_function(source_ip);
    HashNode *node = (HashNode*)allocate_from_pool(/* memory pool */);
    if (!node) {
        free(event); // handle allocation failure
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    node->event = event;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    pthread_mutex_unlock(&ht->lock);

    pthread_mutex_lock(&ll->lock);
    if (ll->tail) {
        ll->tail->next = event;
    } else {
        ll->head = event;
    }
    ll->tail = event;
    pthread_mutex_unlock(&ll->lock);
}

void resize_hash_table(HashTable *ht) {
    unsigned int new_size = ht->size * 2;
    HashNode **new_buckets = (HashNode**)calloc(new_size, sizeof(HashNode*));

    for (unsigned int i = 0; i < ht->size; ++i) {
        HashNode *node = ht->buckets[i];
        while (node) {
            HashNode *next = node->next;
            unsigned int index = hash_function(node->event->source_ip) % new_size;
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = next;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->size = new_size;
}

void iterate_linked_list(LinkedList *ll, void (*callback)(Event*)) {
    pthread_mutex_lock(&ll->lock);
    Event *current = ll->head;
    while (current) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&ll->lock);
}

void log_event_change(const char *message) {
