    Session** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Lock for thread-safe operations
    MemoryPool* memory_pool; // Memory pool to manage fragmentation
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (Session**)memory_pool_allocate(manager->memory_pool, initial_capacity * sizeof(Session*));
    memset(manager->sessions, 0, initial_capacity * sizeof(Session*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_session(Activity** activities, int num_activities) {
    for (int i = 0; i < num_activities; ++i) {
        memory_pool_free(manager->memory_pool, activities[i]->activity);
        memory_pool_free(manager->memory_pool, activities[i]);
    }
    memory_pool_free(manager->memory_pool, activities);
}

void free_session_manager(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]) {
            free_session(manager->sessions[i]->activities, manager->sessions[i]->num_activities);
            memory_pool_free(manager->memory_pool, manager->sessions[i]->session_id);
            memory_pool_free(manager->memory_pool, manager->sessions[i]);
        }
    }

    memory_pool_free(manager->memory_pool, manager->sessions);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

