Session* create_new_session(SessionManager* manager) {
    Session* session = (Session*)memory_pool_allocate(manager->memory_pool, sizeof(Session));

    session->session_id = generate_unique_session_id();
    session->creation_time = distributed_clock_current_time();
    session->last_active_time = session->creation_time;
    session->activities = NULL;
    session->num_activities = 0;

    // Initialize metadata (assuming functions to get this info are available)
    session->metadata.ip_address = strdup("127.0.0.1");
    session->metadata.browser_type = strdup("BrowserX");

    return session;
}

void add_activity(Session* session, const char* activity_description) {
    pthread_mutex_lock(&session->lock);

    Activity* new_activities = (Activity*)memory_pool_reallocate(session->memory_pool, 
        session->activities, (session->num_activities + 1) * sizeof(Activity));

    new_activities[session->num_activities].activity = strdup(activity_description);
    new_activities[session->num_activities].timestamp = distributed_clock_current_time();
    ++session->num_activities;
    session->last_active_time = new_activities[session->num_activities - 1].timestamp;

    session->activities = new_activities;

    pthread_mutex_unlock(&session->lock);
}

void resize_session_array(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Session** new_sessions = (Session**)memory_pool_reallocate(manager->memory_pool, 
            manager->sessions, new_capacity * sizeof(Session*));

        memset(new_sessions + manager->capacity, 0, manager->capacity * sizeof(Session*));
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->lock);
}

void add_session(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    resize_session_array(manager);

    Session* session = create_new_session(manager);
    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    SessionManager* manager = create_session_manager(10);

    add_session(manager);
    // Use the session manager

    free_session_manager(manager);
    return 0;
}
