    struct LinkedListNode *next;
} LinkedListNode;

typedef struct HashTableEntry {
    int key;
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

#define INITIAL_CAPACITY 16
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 1000

typedef struct {
    long *offsets;
    size_t offset_count;
    size_t offset_capacity;
    int *keys;
    size_t key_count;
    size_t key_capacity;
    Record **records_pool;
    size_t records_pool_size;
    LinkedListNode *head;
    HashTableEntry **hash_table;
    size_t hash_table_capacity;
