} MemoryManager;

static void log_event(const char *message, const char *user_id) {
    // Placeholder for logging function from the external library
    extern void external_log(const char *, const char *);
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "[%s] [%s] %s", timestamp, user_id, message);
    external_log(log_message, "user_id_placeholder"); // Replace with actual user ID
}

static int hash_function(int key, size_t capacity) {
    return key % capacity;
}

static void resize_hash_table(MemoryManager *manager) {
    size_t new_capacity = manager->hash_table_capacity * 2;
    HashTableEntry **new_hash_table = calloc(new_capacity, sizeof(HashTableEntry *));
    if (!new_hash_table) {
        log_event("Failed to allocate memory for hash table resizing", "user_id_placeholder");
        return;
    }

    for (size_t i = 0; i < manager->hash_table_capacity; ++i) {
        HashTableEntry *entry = manager->hash_table[i];
        while (entry) {
            size_t new_index = hash_function(entry->key, new_capacity);
            HashTableEntry *next_entry = entry->next;
            entry->next = new_hash_table[new_index];
            new_hash_table[new_index] = entry;
            entry = next_entry;
        }
    }

    free(manager->hash_table);
    manager->hash_table = new_hash_table;
    manager->hash_table_capacity = new_capacity;

    log_event("Hash table resized", "user_id_placeholder");
}

static void resize_offsets_and_keys(MemoryManager *manager) {
    size_t new_capacity = manager->offset_capacity * 2;
    long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        log_event("Failed to allocate memory for offsets and keys resizing", "user_id_placeholder");
        return;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->offset_capacity = new_capacity;
    manager->key_capacity = new_capacity;

    log_event("Offsets and keys arrays resized", "user_id_placeholder");
}

static void initialize_memory_manager(MemoryManager *manager, size_t initial_records_count) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->offsets = malloc(INITIAL_CAPACITY * sizeof(long));
    manager->keys = malloc(INITIAL_CAPACITY * sizeof(int));
    manager->records_pool = malloc(initial_records_count * sizeof(Record *));
    for (size_t i = 0; i < initial_records_count; ++i) {
        manager->records_pool[i] = calloc(1, sizeof(Record));
    }
    manager->offset_capacity = INITIAL_CAPACITY;
    manager->key_capacity = INITIAL_CAPACITY;
    manager->record_count = 0;
    manager->head = NULL;
    manager->hash_table_capacity = INITIAL_CAPACITY;
    manager->hash_table = calloc(manager->hash_table_capacity, sizeof(HashTableEntry *));
}

static void free_memory_manager(MemoryManager *manager) {
    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->records_pool[i]);
    }
    free(manager->records_pool);
    free(manager->offsets);
    free(manager->keys);
    LinkedListNode *current = manager->head;
    while (current) {
        LinkedListNode *next = current->next;
        free(current);
        current = next;
    }
    for (size_t i = 0; i < manager->hash_table_capacity; ++i) {
        HashTableEntry *entry = manager->hash_table[i];
        while (entry) {
            HashTableEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
    free(manager->hash_table);
    pthread_mutex_destroy(&manager->lock);

    log_event("Memory manager cleaned up", "user_id_placeholder");
}

static void add_record(MemoryManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->record_count >= manager->offset_capacity) {
        resize_offsets_and_keys(manager);
    }

    manager->keys[manager->key_count] = key;
    long offset_sum = 0;
    for (size_t i = 0; i < manager->key_count; ++i) {
        offset_sum += manager->keys[i];
    }
    manager->offsets[manager->offset_count++] = offset_sum + 100;

    Record *record = manager->records_pool[manager->record_count++];
    record->field1 = (short)(rand() % 100);
    record->field2 = rand() % 1000;
    record->field3 = (float)rand() / RAND_MAX;

    LinkedListNode *node = malloc(sizeof(LinkedListNode));
    node->key = key;
    node->record = record;
    node->next = manager->head;
    manager->head = node;

    size_t index = hash_function(key, manager->hash_table_capacity);
    node->next = manager->hash_table[index];
    manager->hash_table[index] = node;

    pthread_mutex_unlock(&manager->lock);

    log_event("Record added", "user_id_placeholder");
}

static void iterate_and_log_records(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    LinkedListNode *current = manager->head;
    while (current) {
        printf("Key: %d, Field1: %hd, Field2: %d, Field3: %.2f\n",
               current->key, current->record->field1,
               current->record->field2, current->record->field3);
        log_event("Record accessed", "user_id_placeholder");
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

static void save_state_to_disk(MemoryManager *manager) {
    FILE *file = fopen("memory_manager_state.dat", "wb");
    if (!file) {
        log_event("Failed to open file for saving state", "user_id_placeholder");
        return;
    }

    fwrite(manager, sizeof(MemoryManager), 1, file);
    fclose(file);

    log_event("State saved to disk", "user_id_placeholder");
}

void manage_memory() {
    MemoryManager manager;
    initialize_memory_manager(&manager, INITIAL_CAPACITY);

    for (int i = 0; i < 100; ++i) {
        int key = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        add_record(&manager, key);
    }

    iterate_and_log_records(&manager);
    save_state_to_disk(&manager);

    free_memory_manager(&manager);
}
