typedef struct Record {
    short field1;
    int field2;
    float field3;
    struct Record* next;
} Record;

typedef struct CacheNode {
    Record *record;
    struct CacheNode *next;
} CacheNode;

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables
MemoryPool offset_pool, key_pool, record_pool;
int max_size = 1000; // Example maximum size for arrays
pthread_rwlock_t list_lock;
Record* head = NULL;
CacheNode* cache_head = NULL;
size_t cache_size = 10;

void init_memory_pool(MemoryPool *pool, size_t block_size, size_t pool_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->pool = malloc(pool->block_size * pool->pool_size);
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (!pool->pool) return NULL;

    void *ptr = pool->pool;
    pool->pool = (char*)pool->pool + pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void* realloc_array(MemoryPool *pool, size_t new_size) {
    void *new_pool = malloc(pool->block_size * new_size);
    if (!new_pool) return NULL;

    memcpy(new_pool, pool->pool - (pool->pool_size * pool->block_size), 
           pool->block_size * pool->pool_size);

    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pool->pool = new_pool;
    pool->pool_size = new_size;
    pthread_mutex_unlock(&pool->lock);

    return pool->pool;
}

void init_arrays(int* keys, long* offsets, int initial_capacity) {
    srand(time(NULL));

    for (int i = 0; i < initial_capacity; ++i) {
        keys[i] = rand() % 100 + 1; // Example range
        if (i > 0)
            offsets[i] = offsets[i - 1] + keys[i - 1] + 10;
        else
            offsets[i] = keys[i] + 10;
    }
}

