    rec->field1 = rand() % 1000; // Example range
    rec->field2 = rand() % 5000;
    rec->field3 = (float)(rand() % 100) / 10.0f;

    pthread_rwlock_wrlock(&list_lock);
    if (!head) {
        head = rec;
    } else {
        Record *tmp = head;
        while (tmp->next) tmp = tmp->next;
        tmp->next = rec;
    }
    pthread_rwlock_unlock(&list_lock);

    return rec;
}

void add_to_cache(Record* record) {
    if (!cache_head || cache_size >= 10) { // Example max cache size
        CacheNode *new_node = (CacheNode*)malloc(sizeof(CacheNode));
        new_node->record = record;
        new_node->next = cache_head;
        cache_head = new_node;
    }
}

Record* get_from_cache() {
    if (!cache_head) return NULL;

    Record* rec = cache_head->record;
    CacheNode *tmp = cache_head;
    cache_head = cache_head->next;
    free(tmp);

    return rec;
}

void iterate_linked_list(void (*func)(Record*)) {
    pthread_rwlock_rdlock(&list_lock);
    for (Record* current = head; current != NULL; current = current->next) {
        func(current);
    }
    pthread_rwlock_unlock(&list_lock);
