// Custom hash function
unsigned long hash_function(int key) {
    return (unsigned long)(key * 2654435761 % TABLE_SIZE);
}

// Initialize the hash table
HashTable* init_hash_table() {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    ht->buckets = calloc(TABLE_SIZE, sizeof(Record*));
    if (!ht->buckets) {
        free(ht);
        perror("Failed to allocate memory for buckets");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&ht->locks[i], NULL);
    }

    return ht;
}

// Insert a record into the hash table
void insert_record(HashTable* ht, int key, int value) {
    unsigned long index = hash_function(key);

    pthread_mutex_lock(&ht->locks[index]);

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    new_record->key = key;
    new_record->value = value;
    new_record->next = ht->buckets[index];
    ht->buckets[index] = new_record;

    pthread_mutex_unlock(&ht->locks[index]);
}

// Retrieve a record from the hash table
Record* get_record(HashTable* ht, int key) {
    unsigned long index = hash_function(key);

    pthread_mutex_lock(&ht->locks[index]);

    Record* current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&ht->locks[index]);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ht->locks[index]);
    return NULL;
}

// Delete a record from the hash table
void delete_record(HashTable* ht, int key) {
    unsigned long index = hash_function(key);

    pthread_mutex_lock(&ht->locks[index]);

    Record *current = ht->buckets[index], *prev = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (prev)
                prev->next = current->next;
            else
                ht->buckets[index] = current->next;

            free(current);
            pthread_mutex_unlock(&ht->locks[index]);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&ht->locks[index]);
}

// Destroy the hash table and free memory
void destroy_hash_table(HashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->buckets);
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&ht->locks[i]);
    }
    free(ht);
}

// Example usage
void example_usage() {
    HashTable* ht = init_hash_table();

    // Insert random records
    for (int i = 0; i < 1000000; ++i) {
        int key = rand() % RANGE;
        int value = rand() % RANGE;
        insert_record(ht, key, value);
    }

    // Retrieve a record
    Record* rec = get_record(ht, 123);
    if (rec) {
        printf("Key: %d, Value: %d\n", rec->key, rec->value);
    } else {
        printf("Record not found.\n");
    }

    // Delete a record
    delete_record(ht, 123);

    // Clean up
    destroy_hash_table(ht);
}

int main() {
    srand(time(NULL));
    example_usage();
    return 0;
}
```

### Design Choices and Justifications:
- **Chaining for Collision Handling**: Chaining was chosen over open addressing because it scales better with high load factors, which is crucial given the potential for up to 10 million records.
- **Mutexes for Thread Safety**: Using a separate mutex per bucket allows fine-grained locking, reducing contention in multi-threaded environments.
- **Prime Table Size**: A prime number size helps distribute keys more evenly across buckets, minimizing collisions.
- **Robust Error Handling**: The code checks for memory allocation failures and exits gracefully with error messages.
- **Dynamic Allocation**: Memory is allocated dynamically to handle varying loads efficiently.']

