    std::string DestinationIP;
    std::string ProtocolType;
    std::chrono::system_clock::time_point LastUpdateTimestamp;
    int TrafficVolume;

    TrafficFlow(std::string src, std::string dest, std::string proto, int volume)
        : SourceIP(std::move(src)), DestinationIP(std::move(dest)),
          ProtocolType(std::move(proto)), TrafficVolume(volume) {
        LastUpdateTimestamp = std::chrono::system_clock::now();
    }
};

// LRU Cache implementation
template <typename Key, typename Value>
class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity) {}

    void put(const Key& key, const Value& value);
    bool get(const Key& key, Value& value);

private:
    struct Node {
        Key key;
        Value value;
        std::list<Key>::iterator it;
        Node(const Key& k, const Value& v)
            : key(k), value(v) {}
    };
    size_t _capacity;
    std::unordered_map<Key, Node> _cacheMap;
    std::list<Key> _lruList;

    void updateLRU(const Key& key);
};

template <typename Key, typename Value>
void LRUCache<Key, Value>::put(const Key& key, const Value& value) {
    auto it = _cacheMap.find(key);
    if (it != _cacheMap.end()) {
        it->second.value = value;
        updateLRU(it->first);
        return;
    }

    if (_cacheMap.size() == _capacity) {
        Key lruKey = _lruList.back();
        _lruList.pop_back();
        _cacheMap.erase(lruKey);
    }

    _lruList.push_front(key);
    _cacheMap[key] = {key, value, _lruList.begin()};
}

template <typename Key, typename Value>
bool LRUCache<Key, Value>::get(const Key& key, Value& value) {
    auto it = _cacheMap.find(key);
    if (it == _cacheMap.end()) return false;

    value = it->second.value;
    updateLRU(it->first);
    return true;
}

template <typename Key, typename Value>
void LRUCache<Key, Value>::updateLRU(const Key& key) {
    auto nodeIt = _cacheMap[key].it;
    _lruList.erase(nodeIt);
    _lruList.push_front(key);
    _cacheMap[key].it = _lruList.begin();
}

// Thread-safe Traffic Manager
class TrafficManager {
public:
    TrafficManager(size_t maxThreads) : _maxThreads(maxThreads), _stop(false) {}

    void addFlow(const TrafficFlow& flow);
    void removeFlowsByIP(const std::string& ip);
    void removeFlowsByProtocol(const std::string& protocol);
    void removeFlowsByVolume(int volume);
    size_t getFlowsCountByProtocol(const std::string& protocol) const;

    void batchRemoveInactiveFlows();
    void processTrafficAndInsertString(std::forward_list<std::string>& list, 
                                       const std::string& needle,
                                       const std::string& haystack,
                                       const std::string& insertion_string);

private:
    mutable std::mutex _trafficMutex;
    std::vector<TrafficFlow> _flows;
    LRUCache<std::string, bool> _insertionCache{100};

    void fetchRealTimeData();
    void manageResources();

    std::atomic<bool> _stop;
    size_t _maxThreads;
    std::thread _dataFetcherThread;

    void workerFunction();
};

void TrafficManager::addFlow(const TrafficFlow& flow) {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    _flows.push_back(flow);
}

void TrafficManager::removeFlowsByIP(const std::string& ip) {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    _flows.erase(std::remove_if(_flows.begin(), _flows.end(),
        [&ip](const TrafficFlow& flow) {
            return flow.SourceIP == ip || flow.DestinationIP == ip;
        }), _flows.end());
}

void TrafficManager::removeFlowsByProtocol(const std::string& protocol) {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    _flows.erase(std::remove_if(_flows.begin(), _flows.end(),
        [&protocol](const TrafficFlow& flow) {
            return flow.ProtocolType == protocol;
        }), _flows.end());
}

void TrafficManager::removeFlowsByVolume(int volume) {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    _flows.erase(std::remove_if(_flows.begin(), _flows.end(),
        [volume](const TrafficFlow& flow) {
            return flow.TrafficVolume >= volume;
        }), _flows.end());
}

size_t TrafficManager::getFlowsCountByProtocol(const std::string& protocol) const {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    size_t count = 0;
    for (const auto& flow : _flows) {
        if (flow.ProtocolType == protocol) ++count;
    }
    return count;
}

void TrafficManager::batchRemoveInactiveFlows() {
    std::lock_guard<std::mutex> lock(_trafficMutex);
    auto now = std::chrono::system_clock::now();
    _flows.erase(std::remove_if(_flows.begin(), _flows.end(),
        [now](const TrafficFlow& flow) {
            return std::chrono::duration_cast<std::chrono::minutes>(now - flow.LastUpdateTimestamp).count() > 20;
        }), _flows.end());
}

void TrafficManager::processTrafficAndInsertString(std::forward_list<std::string>& list, 
                                                   const std::string& needle,
                                                   const std::string& haystack,
                                                   const std::string& insertion_string) {
    std::lock_guard<std::mutex> lock(_trafficMutex);

    bool inserted = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == needle && !_insertionCache.get(haystack, inserted)) {
            auto nextIt = std::next(it);
            list.insert_after(it, insertion_string);
            _insertionCache.put(haystack, true);
            break;
        }
    }

    if (!inserted) {
        list.push_back(insertion_string);
    }
}

