    pthread_mutex_lock(&map->lock);

    unsigned int index = hash(key, map->capacity);
    hashmap_node *node = malloc(sizeof(hashmap_node));
    if (!node) {
        pthread_mutex_unlock(&map->lock);
        return;
    }

    node->key = key;
    node->data = data;
    node->next = map->buckets[index];
    map->buckets[index] = node;
    map->size++;

    float load_factor = (float)map->size / map->capacity;
    if (load_factor > LOAD_FACTOR_THRESHOLD) {
        rehash_hashmap(map);
    }

    pthread_mutex_unlock(&map->lock);
}

record* lookup_in_hashmap(hashmap *map, int key) {
    pthread_mutex_lock(&map->lock);

    unsigned int index = hash(key, map->capacity);
    hashmap_node *node = map->buckets[index];

    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&map->lock);
            return &node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void rehash_hashmap(hashmap *map) {
    size_t new_capacity = map->capacity * 2;
    hashmap_node **new_buckets = (hashmap_node **)calloc(new_capacity, sizeof(hashmap_node*));

    for (size_t i = 0; i < map->capacity; ++i) {
        hashmap_node *node = map->buckets[i];
        while (node) {
            unsigned int new_index = hash(node->key, new_capacity);
            hashmap_node *next = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next;
        }
    }

    free(map->buckets);
    map->buckets = new_buckets;
    map->capacity = new_capacity;
}

// Main function to demonstrate usage
int main() {
    memory_pool *pool = create_memory_pool(INITIAL_POOL_SIZE);
    if (!pool) {
        log_message("Failed to create memory pool");
        return EXIT_FAILURE;
    }

    hashmap *map = create_hashmap(16);
    if (!map) {
        log_message("Failed to create hash map");
        free(pool->pool);
        free(pool);
        return EXIT_FAILURE;
    }

    // Example usage
    srand(time(NULL));
    for (int i = 0; i < 100; ++i) {
        record data = { rand() % 100 };
        insert_into_hashmap(map, i, data);
    }

    // Lookup example
    record *data = lookup_in_hashmap(map, 42);
    if (data) {
        printf("Record found with value: %d\n", data->value);
    } else {
        printf("Record not found.\n");
    }

    // Cleanup
    free(pool->pool);
    free(pool);
    free(map->buckets);
    pthread_mutex_destroy(&map->lock);
    free(map);

    return EXIT_SUCCESS;
}
```

This code provides a foundation for managing dynamic memory with a custom pool and buddy system. It includes hash map operations, concurrent access handling, and basic logging. For full functionality, you would need to extend this framework with additional features like event management, further concurrency control, detailed logging, and more robust error handling as per the task requirements.']

