void initialize_records(record *records, int min, int max, size_t n);
void free_memory(long *offsets, int *keys, record *records);

pthread_mutex_t lock;

// Main function to allocate and initialize memory
record* create_arrays(int min, int max, const char *filename, int n) {
    pthread_mutex_init(&lock, NULL);
    srand(time(NULL));  // Seed the random number generator

    size_t longSize = n;   // Default size for 'long' offsets array
    size_t intKeySize = n; // Default size for 'int' keys array

    if (read_config(filename, &longSize, &intKeySize) != 0) {
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    long *offsets = malloc(longSize * sizeof(long));
    int *keys = malloc(intKeySize * sizeof(int));
    record *records = malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        free_memory(offsets, keys, records);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Initialize allocated memory
    memset(offsets, 0, longSize * sizeof(long));
    memset(keys, 0, intKeySize * sizeof(int));

    for (size_t i = 0; i < n; ++i) {
        records[i].str = malloc(100); // Assume a maximum string length of 100
        if (!records[i].str) {
            free_memory(offsets, keys, records);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
        snprintf(records[i].str, 100, "Record %zu", i + 1); // Example initialization
    }

    initialize_records(records, min, max, n);

    pthread_mutex_destroy(&lock);
    return records;
}

int read_config(const char *filename, size_t *longSize, size_t *intKeySize) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return -1; // Error opening file
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Example of reading configuration settings
        if (sscanf(line, "longSize %zu", longSize) == 1 || sscanf(line, "intKeySize %zu", intKeySize) == 1) {
            continue;
        }
    }

    fclose(file);
    return 0; // Success
}

void initialize_records(record *records, int min, int max, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % (max - min + 1) + min;
        pthread_mutex_unlock(&lock);
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; i < n; ++i) {
            if (records[i].str) free(records[i].str);
        }
        free(records);
    }
}
