#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_PROTOCOLS 5

typedef struct Event {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol;
    size_t payload_size;
} Event;

typedef struct ListNode {
    Event event;
    struct ListNode *next;
    struct ListNode *prev;
} ListNode;

typedef struct {
    ListNode *head;
    ListNode *tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct HashTableEntry {
    char key[16];
    ListNode *node;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    size_t capacity;
    HashTableEntry **buckets;
    LinkedList linked_list;
    pthread_rwlock_t rwlock;
    int protocol_set[MAX_PROTOCOLS];
} EventCollection;

#define HASH_SIZE 256

EventCollection* create_event_collection() {
    EventCollection *ec = malloc(sizeof(EventCollection));
    ec->capacity = HASH_SIZE;
    ec->buckets = calloc(ec->capacity, sizeof(HashTableEntry*));
    pthread_rwlock_init(&ec->rwlock, NULL);
    pthread_mutex_init(&ec->linked_list.lock, NULL);
    return ec;
}

unsigned int hash_function(const char *ip) {
    unsigned long hash = 5381;
    int c;
    while ((c = *ip++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % HASH_SIZE;
}

void insert_event(EventCollection *ec, Event event) {
    pthread_rwlock_wrlock(&ec->rwlock);

    unsigned int index = hash_function(event.source_ip);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    strcpy(entry->key, event.source_ip);
    entry->node = malloc(sizeof(ListNode));

    entry->node->event = event;
    entry->next = ec->buckets[index];
    ec->buckets[index] = entry;

    pthread_mutex_lock(&ec->linked_list.lock);

    if (!ec->linked_list.head) {
        ec->linked_list.head = entry->node;
        ec->linked_list.tail = entry->node;
    } else {
        ec->linked_list.tail->next = entry->node;
        entry->node->prev = ec->linked_list.tail;
        ec->linked_list.tail = entry->node;
    }

    pthread_mutex_unlock(&ec->linked_list.lock);

    pthread_rwlock_unlock(&ec->rwlock);
}

void cleanup_event_collection(EventCollection *ec) {
    for (size_t i = 0; i < ec->capacity; ++i) {
        HashTableEntry *entry = ec->buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp->node);
            free(temp);
        }
    }

    ListNode *current = ec->linked_list.head;
    while (current) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }

    free(ec->buckets);
    pthread_rwlock_destroy(&ec->rwlock);
    pthread_mutex_destroy(&ec->linked_list.lock);
    free(ec);
}

// Additional functions for resizing, iteration, and logging would be implemented here...

