}

// Allocator functions
CustomAllocator* init_allocator(size_t initial_capacity, size_t block_size, float growth_factor) {
    CustomAllocator* allocator = malloc(sizeof(CustomAllocator));
    allocator->blocks = calloc(initial_capacity, sizeof(void*));
    allocator->block_size = block_size;
    allocator->current_capacity = initial_capacity;
    allocator->growth_factor = (size_t)(growth_factor * initial_capacity);
    return allocator;
}

void* custom_alloc(CustomAllocator* allocator, size_t size) {
    if (size > allocator->block_size || allocator->count >= allocator->current_capacity) {
        // Reallocate memory with growth factor
        size_t new_capacity = allocator->current_capacity + allocator->growth_factor;
        void** new_blocks = realloc(allocator->blocks, new_capacity * sizeof(void*));
        if (!new_blocks) return NULL;

        allocator->blocks = new_blocks;
        allocator->current_capacity = new_capacity;
    }

    for (size_t i = 0; i < allocator->count; ++i) {
        if (!allocator->blocks[i]) {
            void* ptr = malloc(allocator->block_size);
            allocator->blocks[i] = ptr;
            allocator->count++;
            return ptr;
        }
    }

    // Allocate a new block if no empty slot is found
    void* ptr = malloc(allocator->block_size);
    allocator->blocks[allocator->count++] = ptr;
    return ptr;
}

void custom_free(CustomAllocator* allocator, void* ptr) {
    for (size_t i = 0; i < allocator->current_capacity; ++i) {
        if (allocator->blocks[i] == ptr) {
            free(ptr);
            allocator->blocks[i] = NULL;
            return;
        }
    }
}

void compact_memory(CustomAllocator* allocator) {
    size_t write_index = 0;
    for (size_t i = 0; i < allocator->current_capacity; ++i) {
        if (allocator->blocks[i]) {
            if (write_index != i) {
                void* temp = allocator->blocks[i];
                allocator->blocks[i] = NULL;
                allocator->blocks[write_index] = temp;
            }
            write_index++;
        }
    }
}

// Script list functions
ScriptList* init_script_list() {
    ScriptList* list = malloc(sizeof(ScriptList));
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void insert_script(ScriptList* list, Script script) {
    pthread_rwlock_wrlock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->script.key == script.key) {
            pthread_rwlock_unlock(&list->lock);
            return; // Key already exists
        }
        current = &(*current)->next;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->script = script;
    new_node->next = NULL;
    *current = new_node;

    list->count++;
    pthread_rwlock_unlock(&list->lock);
}

Script* find_script(ScriptList* list, uint32_t key) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->script.key == key) {
            Script* script = &current->script;
            pthread_rwlock_unlock(&list->lock);
            return script;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

void remove_script(ScriptList* list, uint32_t key) {
    pthread_rwlock_wrlock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->script.key == key) {
            Node* to_remove = *current;
            *current = (*current)->next;
            free(to_remove);
            list->count--;
            pthread_rwlock_unlock(&list->lock);
            return;
        }
        current = &(*current)->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

void free_script_list(ScriptList* list) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

// Metadata computation
uint32_t compute_metadata(uint32_t key, size_t index) {
    return hash_function(key, index);
}

int main() {
    srand(time(NULL));

    // Initialize custom allocator
    CustomAllocator* allocator = init_allocator(10, 128, 1.5);

    // Initialize script list
    ScriptList* script_list = init_script_list();

    // Example: Insert scripts with random values
    for (size_t i = 0; i < 20; ++i) {
        Script script;
        script.key = rand() % 100 - 50; // Range from -50 to 49
        script.offset = i * 10 + 5; // Example offset calculation
        script.metadata = random_float(0.0, 1.0);
        insert_script(script_list, script);
    }

    // Find and print a script
    Script* found_script = find_script(script_list, 25); // Example key
    if (found_script) {
        printf("Found script with key %u: offset=%d, metadata=%.2f\n",
               found_script->key, found_script->offset, found_script->metadata);
    }

    // Free resources
    free_script_list(script_list);
    compact_memory(allocator);

    return 0;
}
```

