typedef struct Record {
    short s;
    int i;
    float f;
    struct Record *next;
} Record;

typedef struct ResourceBundle {
    char **files;
    size_t file_count;
    pthread_mutex_t lock;
    Record *head;
} ResourceBundle;

ResourceBundle* create_resource_bundle(const char *dir_path, const char *extension) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        LOG_ERROR("Failed to open directory");
        return NULL;
    }

    struct dirent *entry;
    size_t initial_capacity = 1000; // Initial capacity for files array
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        closedir(dir);
        LOG_ERROR("Memory allocation failed for bundle");
        return NULL;
    }

    bundle->files = calloc(initial_capacity, sizeof(char*));
    if (!bundle->files) {
        free(bundle);
        closedir(dir);
        LOG_ERROR("Memory allocation failed for files array");
        return NULL;
    }

    bundle->file_count = 0;
    pthread_mutex_init(&bundle->lock, NULL);
    bundle->head = NULL;

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, extension) == entry->d_name + strlen(extension) - strlen(".ext")) {
            // Resize array if needed
            if (bundle->file_count >= initial_capacity) {
                size_t new_capacity = initial_capacity * 2;
                char **new_files = realloc(bundle->files, new_capacity * sizeof(char*));
                if (!new_files) {
                    LOG_ERROR("Failed to resize files array");
                    // Clean up
                    while (bundle->file_count > 0) free(bundle->files[--bundle->file_count]);
                    free(bundle->files);
                    closedir(dir);
                    pthread_mutex_destroy(&bundle->lock);
                    free(bundle);
                    return NULL;
                }
                bundle->files = new_files;
                initial_capacity = new_capacity;
            }

            // Allocate memory for file path
            size_t name_len = strlen(entry->d_name) + 1;
            char *file_path = malloc(name_len);
            if (!file_path) {
                LOG_ERROR("Memory allocation failed for file path");
                continue; // Skip this file due to memory error
            }
            snprintf(file_path, name_len, "%s/%s", dir_path, entry->d_name);

            bundle->files[bundle->file_count++] = file_path;
        }
    }

    closedir(dir);

    LOG_INFO("Resource bundle created with %zu files", bundle->file_count);

    return bundle;
}

void free_resource_bundle(ResourceBundle *bundle) {
    if (!bundle) return;

    // Free all file paths
    for (size_t i = 0; i < bundle->file_count; ++i) {
        free(bundle->files[i]);
    }
    free(bundle->files);

    // Free linked list
    Record *current = bundle->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

int main() {
    const char *directory_path = "./resources";
    const char *file_extension = ".ext";

    ResourceBundle *bundle = create_resource_bundle(directory_path, file_extension);
    if (!bundle) {
        LOG_ERROR("Failed to create resource bundle");
        return EXIT_FAILURE;
    }

    // Use the bundle...

    free_resource_bundle(bundle);

    return EXIT_SUCCESS;
}
```

