#define MAX_SESSIONS 1000

typedef struct {
    int session_id;
    char user_metadata[256];
    char auth_token[128];
    time_t last_activity_timestamp;
    int duration;
} Session;

typedef struct {
    Session *sessions[MAX_SESSIONS];
    size_t count;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
} SessionManager;

SessionManager manager;

void init_memory_pool() {
    // Initialize memory pool (simple example, could be more sophisticated)
}

Session* create_session(const char* user_metadata) {
    static int session_id_counter = 0;
    pthread_rwlock_wrlock(&manager.rwlock);

    if (manager.count >= MAX_SESSIONS) {
        pthread_rwlock_unlock(&manager.rwlock);
        return NULL; // No space to create new sessions
    }

    Session *session = malloc(sizeof(Session));
    session->session_id = ++session_id_counter;
    strncpy(session->user_metadata, user_metadata, sizeof(session->user_metadata));
    snprintf(session->auth_token, sizeof(session->auth_token), "token_%d", session->session_id);
    session->last_activity_timestamp = time(NULL);
    session->duration = rand() % 3600 + 600; // Random duration between 10 to 60 minutes

    manager.sessions[manager.count++] = session;

    pthread_rwlock_unlock(&manager.rwlock);

    // Log the creation of a new session
    printf("Session created: ID=%d, UserMetadata=%s\n", session->session_id, user_metadata);

    return session;
}

void destroy_session(Session *session) {
    pthread_rwlock_wrlock(&manager.rwlock);

    for (size_t i = 0; i < manager.count; ++i) {
        if (manager.sessions[i] == session) {
            free(manager.sessions[i]);
            memmove(&manager.sessions[i], &manager.sessions[i + 1], sizeof(Session*) * (manager.count - i - 1));
            --manager.count;
            break;
        }
    }

    pthread_rwlock_unlock(&manager.rwlock);

    // Log the destruction of a session
    printf("Session destroyed: ID=%d\n", session->session_id);
}

void iterate_sessions(void (*func)(Session*)) {
    pthread_rwlock_rdlock(&manager.rwlock);
    for (size_t i = 0; i < manager.count; ++i) {
        func(manager.sessions[i]);
    }
    pthread_rwlock_unlock(&manager.rwlock);
}

void save_state_to_disk() {
    // Implement disk saving with optimized I/O
    FILE *file = fopen("session_backup.bin", "wb");
    if (file) {
        fwrite(&manager, sizeof(SessionManager), 1, file);
        fclose(file);
    }
}

void load_state_from_disk() {
    // Load state from the disk
    FILE *file = fopen("session_backup.bin", "rb");
    if (file) {
        fread(&manager, sizeof(SessionManager), 1, file);
        fclose(file);
    }
}

void initialize_manager() {
    pthread_mutex_init(&manager.mutex, NULL);
    pthread_rwlock_init(&manager.rwlock, NULL);
    manager.count = 0;
    memset(manager.sessions, 0, sizeof(manager.sessions));
}

int main() {
    srand(time(NULL));
    initialize_manager();

    // Example usage
    create_session("User1");
    create_session("User2");

    iterate_sessions([](Session *session) {
        printf("Iterating: Session ID=%d\n", session->session_id);
    });

    save_state_to_disk();

    return 0;
}
```

