(function() {
    const commonAttributes = new Set(['style', 'class', 'id', 'width', 'height', 'margin', 'padding']);

    function filterAttributes(attributes) {
        return attributes.filter(attr => !commonAttributes.has(attr));
    }

    async function generateReport(rootElement, customFilter = () => true) {
        const uniqueAttributes = new Set();

        const traverse = async (node) => {
            if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

            const attrs = Array.from(node.attributes)
                .map(attr => attr.name)
                .filter(customFilter);

            filterAttributes(attrs).forEach(attr => uniqueAttributes.add(attr));

            for (let child of node.children) {
                await traverse(child);
            }
        };

        await traverse(rootElement);

        console.log("Report:", [...uniqueAttributes]);
    }

    // Example usage
    document.addEventListener('DOMContentLoaded', async () => {
        const customFilter = attr => !attr.startsWith('data-'); // Customizable filter logic
        await generateReport(document.body, customFilter);
    });

})();
