    void *elements;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    Record *records;
    size_t current_capacity;
    size_t max_capacity;
    size_t record_count;
    MemoryPool pool;
    Metadata *metadata_source;
    pthread_rwlock_t rwlock; // Read-write lock for concurrent access
    Record **cache;
    size_t cache_size;
} DataStore;

// Function declarations
void initialize_data_store(DataStore *store, size_t initial_capacity, size_t max_capacity);
void free_data_store(DataStore *store);
void *allocate_from_pool(MemoryPool *pool, size_t count);
void deallocate_to_pool(MemoryPool *pool, void *ptr, size_t count);
Record *add_record(DataStore *store);
void resize_storage(DataStore *store);
void iterate_records(const DataStore *store);
void update_metadata(DataStore *store);
bool is_cache_hit(DataStore *store, short s, int i);
void log_changes(const char *message);

// Initialize data store with specified capacity
void initialize_data_store(DataStore *store, size_t initial_capacity, size_t max_capacity) {
    pthread_rwlock_init(&store->rwlock, NULL);
    pthread_mutex_init(&store->pool.lock, NULL);

    store->current_capacity = initial_capacity;
    store->max_capacity = max_capacity;
    store->record_count = 0;

    allocate_from_pool(&store->pool, initial_capacity); // Allocate memory pool

    // Initialize cache
    store->cache_size = (initial_capacity > 10) ? 5 : 2; // Simple heuristic for cache size
    store->cache = malloc(sizeof(Record*) * store->cache_size);
}

// Free allocated resources in data store
void free_data_store(DataStore *store) {
    deallocate_to_pool(&store->pool, store->records, store->current_capacity);
    free(store->cache);
    pthread_rwlock_destroy(&store->rwlock);
    pthread_mutex_destroy(&store->pool.lock);
}

// Allocate memory from pool
void *allocate_from_pool(MemoryPool *pool, size_t count) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used + count > pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : count;
        void *new_elements = realloc(pool->elements, new_capacity * pool->element_size);

        if (!new_elements) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Allocation failed
        }

        pool->elements = new_elements;
        pool->capacity = new_capacity;
    }

    void *ptr = (char*)pool->elements + (pool->used * pool->element_size);
    pool->used += count;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Deallocate memory to pool
void deallocate_to_pool(MemoryPool *pool, void *ptr, size_t count) {
    // Simple garbage collection by resetting used space (naive approach)
    pthread_mutex_lock(&pool->lock);

    if (pool->used > 0 && ptr >= pool->elements &&
        ((char*)ptr + count * pool->element_size) <= (char*)pool->elements + (pool->used * pool->element_size)) {
        pool->used -= count; // Adjust used space
    }

    pthread_mutex_unlock(&pool->lock);
}

// Add a new record to the data store with random initialization
Record *add_record(DataStore *store) {
    if ((double)(store->record_count + 1) / (double)store->current_capacity > 0.8) {
        resize_storage(store); // Trigger resize if over threshold
    }

    Record *new_record = (Record *)allocate_from_pool(&store->pool, 1);
    if (!new_record) return NULL; // Allocation failed

    pthread_rwlock_wrlock(&store->rwlock);

    new_record->s = rand() % 1000; // Random short in range [0, 999]
    new_record->i = rand() % 10000; // Random int in range [0, 9999]
    new_record->f = (float)(rand() / (double)RAND_MAX);

    // Metadata update (simplified)
    // This is where you would integrate with an external source
    // For simplicity, assume metadata_source updates directly

    pthread_rwlock_unlock(&store->rwlock);

    store->record_count++;
    log_changes("Added new record");

    return new_record;
}

// Resize storage to accommodate more records
void resize_storage(DataStore *store) {
    size_t new_capacity = (store->current_capacity < store->max_capacity) ?
                          store->current_capacity * 2 : store->max_capacity;

    Record *new_records = realloc(store->records, new_capacity * sizeof(Record));
    if (!new_records) return; // Allocation failed

    pthread_rwlock_wrlock(&store->rwlock);

    store->records = new_records;
    store->current_capacity = new_capacity;

    pthread_rwlock_unlock(&store->rwlock);

    log_changes("Storage resized");
}

// Iterate over records in a thread-safe manner
void iterate_records(const DataStore *store) {
    pthread_rwlock_rdlock(&store->rwlock);

    for (size_t i = 0; i < store->record_count; ++i) {
        // Process record (example)
        printf("Record %zu: short=%d, int=%d, float=%.2f\n", i,
               store->records[i].s, store->records[i].i, store->records[i].f);
    }

    pthread_rwlock_unlock(&store->rwlock);
}

// Update metadata from an external source
void update_metadata(DataStore *store) {
