    log_changes("Metadata updated");
}

// Check if a record is in the cache
bool is_cache_hit(DataStore *store, short s, int i) {
    for (size_t j = 0; j < store->cache_size; ++j) {
        Record *cached_record = store->cache[j];
        if (cached_record && cached_record->s == s && cached_record->i == i) {
            return true;
        }
    }
    return false;
}

// Log changes to the data store
