#include <time.h>

#define MAX_DEVICES 1024
#define MAC_ADDRESS_LENGTH 6
#define TEMPERATURE_RANGE (20.0, 30.0)
#define HUMIDITY_RANGE (30, 70)

typedef struct {
    unsigned char mac_address[MAC_ADDRESS_LENGTH];
    float temperature;
    int humidity;
    int battery_level;
    time_t last_update;
    int is_online;
} Device;

Device* devices = NULL;
size_t device_count = 0;
unsigned long mac_seed = 1; // Seed for MAC address generation

// Utility function to generate a random floating point number within a range
float random_float(float min, float max) {
    return (rand() / (float)RAND_MAX) * (max - min) + min;
}

// Utility function to generate a random integer within a range
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Memory pool for devices
void* memory_pool[MAX_DEVICES];
size_t memory_pool_index = 0;

// Custom allocator from the memory pool
Device* allocate_device() {
    if (memory_pool_index < MAX_DEVICES) {
        void* ptr = malloc(sizeof(Device));
        if (ptr) {
            memory_pool[memory_pool_index++] = ptr;
            return (Device*)ptr;
        }
    }
    return NULL; // Memory allocation failed or pool exhausted
}

// Custom deallocator to the memory pool
void free_device(Device* device) {
    for (size_t i = 0; i < memory_pool_index; ++i) {
        if (memory_pool[i] == device) {
            free(memory_pool[i]);
            memory_pool[i] = NULL;
            break;
        }
    }
}

// Function to generate a unique MAC address
void generate_mac_address(unsigned char* mac, unsigned long seed) {
    srand(seed);
    for (int i = 0; i < MAC_ADDRESS_LENGTH - 2; ++i) {
        mac[i] = rand() % 256;
    }
    // Set the last two bytes to unicast and locally administered
    mac[MAC_ADDRESS_LENGTH - 2] = 0x02;
    mac[MAC_ADDRESS_LENGTH - 1] = 0x00;
}

// Initialize devices with random sensor data
void initialize_devices(size_t count) {
    device_count = count;
    devices = (Device*)malloc(count * sizeof(Device));
    if (!devices) return;

    for (size_t i = 0; i < count; ++i) {
        generate_mac_address(devices[i].mac_address, mac_seed++);
        devices[i].temperature = random_float(TEMPERATURE_RANGE[0], TEMPERATURE_RANGE[1]);
        devices[i].humidity = random_int(HUMIDITY_RANGE[0], HUMIDITY_RANGE[1]);
        devices[i].battery_level = 100;
        devices[i].last_update = time(NULL);
        devices[i].is_online = 1;
    }
}

// Log device data
void log_device_data(Device* device) {
    printf("MAC: ");
    for (int i = 0; i < MAC_ADDRESS_LENGTH; ++i) {
        printf("%02X:", device->mac_address[i]);
    }
    printf("\nTemperature: %.2f\nHumidity: %d\nBattery Level: %d%%\nTimestamp: %ld\n",
           device->temperature, device->humidity, device->battery_level, device->last_update);
}

// Handle graceful disconnection
void handle_disconnections() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < device_count; ++i) {
        if (!devices[i].is_online && difftime(current_time, devices[i].last_update) > 3600) { // 1 hour threshold
            free_device(&devices[i]);
            memmove(&devices[i], &devices[i + 1], (device_count - i - 1) * sizeof(Device));
            --device_count;
        }
    }
}

// Garbage collection process
void garbage_collection() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < device_count; ++i) {
        if (!devices[i].is_online && difftime(current_time, devices[i].last_update) > 7200) { // 2 hours threshold
            free_device(&devices[i]);
            memmove(&devices[i], &devices[i + 1], (device_count - i - 1) * sizeof(Device));
            --device_count;
        }
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    initialize_devices(10); // Initialize with 10 devices

    // Simulate device updates
    for (size_t i = 0; i < device_count; ++i) {
        log_device_data(&devices[i]);
    }

    // Handle disconnections and garbage collection
    handle_disconnections();
    garbage_collection();

    free(devices);
    return 0;
}
