#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int seconds;
    int minutes;
    int hours;
    int day;
    int month;
    int year;
} timestamp;

typedef struct {
    int value;
    char *key;
    timestamp ts;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize arrays
void* initialize_data(size_t num_elements, int min_val, int max_val) {
    pthread_mutex_lock(&mutex);

    long *offsets = malloc(num_elements * sizeof(long));
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int *keys = malloc(num_elements * sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    record *records = malloc(num_elements * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = rand() % 1000000;

        keys[i] = rand() % (max_val - min_val + 1) + min_val;

        records[i].value = rand() % (max_val - min_val + 1) + min_val;

        records[i].key = malloc(33); // Max length of 32 + null terminator
        if (records[i].key == NULL) {
            perror("Failed to allocate memory for key string");
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        snprintf(records[i].key, 33, "Key_%zu", i); // Example of string initialization

        records[i].ts.seconds = rand() % 60;
        records[i].ts.minutes = rand() % 60;
        records[i].ts.hours = rand() % 24;
        records[i].ts.day = rand() % 31 + 1;
        records[i].ts.month = rand() % 12 + 1;
        records[i].ts.year = rand() % 100 + 2000; // Example years between 2000 and 2099
    }

    pthread_mutex_unlock(&mutex);

    return (void*)malloc(sizeof(long *) * 3);
}

// Function to free allocated memory
void cleanup(void* data, size_t num_elements) {
    if (!data) return;

    long **arrays = (long **)data;
    long *offsets = arrays[0];
    int *keys = (int *)arrays[1];
    record *records = (record *)arrays[2];

    for (size_t i = 0; i < num_elements; ++i) {
        free(records[i].key);
    }

    free(offsets);
    free(keys);
    free(records);

    free(data);
}

// Sample usage of the function
void print_records(void* data, size_t num_elements) {
    if (!data) return;

    long **arrays = (long **)data;
    record *records = (record *)arrays[2];

    for (size_t i = 0; i < num_elements; ++i) {
        printf("Record %zu:\n", i);
        printf("  Value: %d\n", records[i].value);
        printf("  Key: %s\n", records[i].key);
        printf("  Timestamp: %04d-%02d-%02d %02d:%02d:%02d\n",
               records[i].ts.year, records[i].ts.month,
               records[i].ts.day, records[i].ts.hours,
               records[i].ts.minutes, records[i].ts.seconds);
        printf("\n");
    }
}

int main() {
    size_t num_elements = 5; // Example number of elements
    int min_val = -1000, max_val = 1000;

    void* data = initialize_data(num_elements, min_val, max_val);
    if (data) {
        print_records(data, num_elements);
        cleanup(data, num_elements);
    }

    return 0;
}
