#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum { UNINITIALIZED, VALID, INVALID } Status;

typedef struct {
    int *value;
    char isValid;
    Status status;
} Record;

// Function to log memory operations
void log_memory_operation(const char *operation, size_t size) {
    time_t now = time(NULL);
    printf("[%s] %s: %zu bytes\n", ctime(&now), operation, size);
}

// Memory pool for efficient management
typedef struct {
    void *memory;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory = malloc(size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pthread_mutex_init(&pool->lock, NULL);

    log_memory_operation("Allocate Memory Pool", size);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        pthread_mutex_lock(&pool->lock);
        free(pool->memory);
        pthread_mutex_unlock(&pool->lock);

        pthread_mutex_destroy(&pool->lock);
        free(pool);
        log_memory_operation("Free Memory Pool", pool->size);
    }
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(size);
    if (ptr) {
        log_memory_operation("Allocate Block", size);
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_to_pool(void *ptr, size_t size) {
    if (ptr) {
        log_memory_operation("Free Block", size);
        free(ptr);
    }
}

// Function to manage memory for arrays and structures
void* manage_memory(size_t num_records, int max_unique_keys) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = (long*)malloc(10000 * sizeof(long));
    if (!offsets) return NULL;
    memset(offsets, 0, 10000 * sizeof(long));

    int *keys = (int*)malloc(max_unique_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    Record **records = (Record**)allocate_from_pool(create_memory_pool(5000 * sizeof(Record*)), 5000 * sizeof(Record*));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    int unique_keys[7000];
    memset(unique_keys, -1, 7000 * sizeof(int));

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        Record *record = (Record*)allocate_from_pool(create_memory_pool(sizeof(Record)), sizeof(Record));
        if (!record) break;

        record->value = (int*)allocate_from_pool(create_memory_pool(sizeof(int)), sizeof(int));
        if (!record->value) {
            free_to_pool(record, sizeof(Record));
            continue;
        }

        int value = rand() % 201 - 100; // Random number between -100 and 100
        while (1) {
            int is_unique = 1;
            for (int j = 0; j < max_unique_keys && unique_keys[j] != -1; ++j) {
                if (unique_keys[j] == value) {
                    is_unique = 0;
                    break;
                }
            }

            if (is_unique) {
                *(record->value) = value;
                int key_index = rand() % max_unique_keys;
                while (unique_keys[key_index] != -1) {
