#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "json-c/json.h"

#define MAX_THREADS 10
#define HASH_TABLE_SIZE 1024
#define EXP_TIME_RANGE 60

typedef enum { ACTIVE, INACTIVE } Status;

typedef struct {
    int *value;
    char validity;
    Status status;
} Record;

typedef struct Setting {
    char *key;
    char *value;
    time_t timestamp;
    struct Setting *next;
} Setting;

static inline unsigned int hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

Setting **create_hash_table() {
    Setting **table = calloc(HASH_TABLE_SIZE, sizeof(Setting *));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    return table;
}

void free_setting(Setting *setting) {
    free(setting->key);
    free(setting->value);
    free(setting);
}

void insert_into_hash_table(Setting **table, const char *key, const char *value) {
    unsigned int hash = hash_function(key);
    Setting *new_setting = malloc(sizeof(Setting));
    if (!new_setting) {
        perror("Failed to allocate memory for setting");
        exit(EXIT_FAILURE);
    }

    new_setting->key = strdup(key);
    size_t value_len = rand() % 50 + 10;
    new_setting->value = malloc(value_len * sizeof(char));
    if (!new_setting->value) {
        free(new_setting->key);
        free(new_setting);
        perror("Failed to allocate memory for setting value");
        exit(EXIT_FAILURE);
    }

    snprintf(new_setting->value, value_len, "RandomValue_%zu", rand() % 1000);
    new_setting->timestamp = time(NULL) + (rand() % EXP_TIME_RANGE);
    new_setting->next = table[hash];
    table[hash] = new_setting;
}

void free_hash_table(Setting **table) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Setting *current = table[i];
        while (current) {
            Setting *temp = current;
            current = current->next;
            free_setting(temp);
        }
    }
    free(table);
}

typedef struct {
    char *filename;
    Setting **settings;
} ThreadData;

void* process_json_file(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        fprintf(stderr, "Could not open file %s\n", data->filename);
        pthread_exit(NULL);
    }

    struct json_object *parsed_json;
    struct json_object *config_section;

    parsed_json = json_object_from_file(data->filename);
    if (json_object_get_type(parsed_json) != json_type_object) {
        fprintf(stderr, "Invalid JSON format in %s\n", data->filename);
        fclose(file);
        pthread_exit(NULL);
    }

    if (!json_object_object_get_ex(parsed_json, "config", &config_section)) {
        fprintf(stderr, "Missing 'config' section in %s\n", data->filename);
        fclose(file);
        pthread_exit(NULL);
    }

    struct json_object *key;
    struct json_object *value;

    json_object_object_foreach(config_section, key, value) {
        insert_into_hash_table(data->settings, (char *)json_object_get_string(key), (char *)json_object_get_string(value));
    }

    fclose(file);
    pthread_exit(NULL);
}

void manage_memory() {
    long *offsets = malloc(10000 * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    int *keys = calloc(5000, sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    Record *records = malloc(10000 * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 10000; ++i) {
        records[i].value = malloc(sizeof(int));
        if (!records[i].value) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }
        *(records[i].value) = rand() % INT_MAX;
        records[i].validity = (rand() % 2 == 0) ? 'v' : 'i';
        records[i].status = (rand() % 2 == 0) ? ACTIVE : INACTIVE;
    }

    free(keys);
    free(offsets);
}

int main(int argc, char *argv[]) {
    if (argc < 2 || argc > MAX_THREADS + 1) {
        fprintf(stderr, "Usage: %s <json_file_1> ... <json_file_n>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Setting **settings = create_hash_table();
    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[MAX_THREADS];

    for (int i = 0; i < argc - 1; ++i) {
        thread_data[i].filename = argv[i + 1];
        thread_data[i].settings = settings;

        if (pthread_create(&threads[i], NULL, process_json_file, &thread_data[i])) {
            perror("Failed to create thread");
            free_hash_table(settings);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    manage_memory();

    // Summary or additional processing can be done here

    free_hash_table(settings);
    printf("All configurations processed successfully.\n");
    return EXIT_SUCCESS;
}
