#define INITIAL_SIZE 1024

typedef struct {
    void **pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock; // Mutex for thread safety during resizing
} mem_pool;

mem_pool* create_mem_pool(size_t initial_size) {
    mem_pool *p = (mem_pool *)malloc(sizeof(mem_pool));
    p->pool = (void **)malloc(initial_size * sizeof(void *));
    p->size = initial_size;
    p->used = 0;
    pthread_mutex_init(&p->lock, NULL);
    return p;
}

void* pool_alloc(mem_pool *p) {
    pthread_mutex_lock(&p->lock);
    if (p->used >= p->size) {
        size_t new_size = p->size * 2; // Double the size
        void **new_pool = (void **)realloc(p->pool, new_size * sizeof(void *));
        if (!new_pool) {
            pthread_mutex_unlock(&p->lock);
            return NULL;
        }
        memset(new_pool + p->size, 0, (new_size - p->size) * sizeof(void *));
        p->pool = new_pool;
        p->size = new_pool;
    }
    void *ptr = p->pool[p->used++];
    pthread_mutex_unlock(&p->lock);
    return ptr;
}

void pool_free(mem_pool *p) {
    free(p->pool);
    pthread_mutex_destroy(&p->lock);
    free(p);
}

