            log_change("Memory allocation failed for record");
            pthread_mutex_unlock(&list_lock);
            continue;
        }

        rec->s = rand() % 100; // Random short
        rec->i = rand() % 10000; // Random int
        rec->f = (float)(rand() % 1000) / 10.0f; // Random float
        rec->timestamp = time(NULL);

        Node *node = (Node *)malloc(sizeof(Node));
        if (!node) {
