static void resize_if_needed(int **offsets, int *keys, size_t *size, size_t current_size) {
    size_t new_size = *size * 2;
    int *new_offsets = (int *)realloc(*offsets, new_size * sizeof(int));
    if (!new_offsets) return; // Handle allocation failure gracefully

    int *new_keys = (int *)realloc(keys, new_size * sizeof(int));
    if (!new_keys) {
        free(new_offsets);
        return;
    }

    memset(new_offsets + *size, 0, (*size) * sizeof(int));
    memset(new_keys + *size, 0, (*size) * sizeof(int));
    *offsets = new_offsets;
    keys = new_keys;
