typedef struct Metadata {
    char *data;
} Metadata;

typedef struct Record {
    short s_val;
    int i_val;
    float f_val;
    int timestamp;
    Metadata *metadata;
    struct Record *prev, *next;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record *record;
} Node;

typedef struct DoublyLinkedList {
    Node *head;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Memory pool structures
#define POOL_SIZE 1024

long *offset_pool;
int *key_pool;
Record *record_pool;
int timestamp_pool[POOL_SIZE];
Metadata *metadata_pool[POOL_SIZE];

pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_memory_pools(int num_elements);
Node *create_node(int index, int key_value);
void populate_record(Record *record, Metadata *metadata);
DoublyLinkedList *initialize_linked_list();
void insert_record(DoublyLinkedList *list, Node *node);
void iterate_over_list(DoublyLinkedList *list);

// Initialize memory pools
void initialize_memory_pools(int num_elements) {
    offset_pool = malloc(num_elements * sizeof(long));
    key_pool = malloc(num_elements * sizeof(int));

    record_pool = malloc(num_elements * sizeof(Record));
    for (int i = 0; i < num_elements; i++) {
        metadata_pool[i] = malloc(sizeof(Metadata));
    }
}

// Create a node with initialized values
Node *create_node(int index, int key_value) {
    Node *node = malloc(sizeof(Node));

    pthread_mutex_lock(&offset_lock);
    node->offset = (index == 0 ? 0 : offset_pool[index - 1]) + key_value;
    offset_pool[index] = node->offset;
    pthread_mutex_unlock(&offset_lock);

    pthread_mutex_lock(&key_lock);
    node->key = key_value;
    key_pool[index] = key_value;
    pthread_mutex_unlock(&key_lock);

    node->record = &record_pool[index];
    populate_record(node->record, metadata_pool[index]);

    return node;
}

// Populate a record with random values
void populate_record(Record *record, Metadata *metadata) {
    srand(time(NULL));

    record->s_val = rand() % 1000; // Short range
    record->i_val = rand() % 1000000; // Int range
    record->f_val = (float)(rand()) / RAND_MAX * 100.0; // Float range
    record->timestamp = timestamp_pool[rand() % POOL_SIZE]; // Use a random timestamp from pool

    metadata->data = malloc(50); // Max length of metadata string
    snprintf(metadata->data, 50, "Metadata_%d", rand()); // Random metadata
}

// Initialize the doubly linked list
DoublyLinkedList *initialize_linked_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a node into the doubly linked list
void insert_record(DoublyLinkedList *list, Node *node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        node->prev = node->next = NULL;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
        node->prev = NULL;
    }

    pthread_mutex_unlock(&list->lock);
}

// Iterate over the doubly linked list
void iterate_over_list(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        printf("Offset: %ld, Key: %d\n", current->offset, current->key);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    int num_elements = 10;

    initialize_memory_pools(num_elements);

    DoublyLinkedList *list = initialize_linked_list();

    for (int i = 0; i < num_elements; i++) {
        Node *node = create_node(i, rand() % 10000 + 1); // Unique key generation
        insert_record(list, node);
    }

    iterate_over_list(list);

    return 0;
}
