['Below is a C implementation outline to manage a dynamic in-memory database-like structure with the described features. This example uses POSIX threads for concurrency management and provides mechanisms for handling key-value pairs using a hash table.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_TABLE_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct {
    time_t timestamp;
    int status;
    char *data;
} DataRecord;

typedef struct ListNode {
    char *key;
    DataRecord record;
    struct ListNode *next;
} ListNode;

typedef struct HashTable {
    int size;
    int count;
    ListNode **buckets;
    pthread_rwlock_t *locks;
} HashTable;

// Memory pool structure
typedef struct MemoryPool {
    size_t blockSize;
    void *pool;
    size_t poolSize;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->blockSize = block_size;
    mp->poolSize = pool_size;
    mp->pool = malloc(pool_size);
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void *memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->offset + mp->blockSize > mp->poolSize) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }
    void *ptr = (char *)mp->pool + mp->offset;
    mp->offset += mp->blockSize;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void memory_pool_free(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

unsigned int hash_function(const char *key, int table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % table_size;
}

HashTable *create_hash_table(size_t initial_size, MemoryPool *mp) {
    HashTable *ht = (HashTable *)memory_pool_alloc(mp);
    ht->size = initial_size;
    ht->count = 0;
    ht->buckets = (ListNode **)malloc(initial_size * sizeof(ListNode *));
    for (int i = 0; i < initial_size; ++i)
        ht->buckets[i] = NULL;

    ht->locks = (pthread_rwlock_t *)malloc(initial_size * sizeof(pthread_rwlock_t));
    for (int i = 0; i < initial_size; ++i)
        pthread_rwlock_init(&ht->locks[i], NULL);

    return ht;
}

void free_hash_table(HashTable *ht, MemoryPool *mp) {
    for (int i = 0; i < ht->size; ++i) {
        ListNode *node = ht->buckets[i];
        while (node) {
            ListNode *temp = node;
            node = node->next;
            free(temp->key);
            free(temp->record.data);
            free(temp);
        }
    }

    for (int i = 0; i < ht->size; ++i)
        pthread_rwlock_destroy(&ht->locks[i]);

    free(ht->buckets);
    free(ht->locks);
    free(mp);

    free_ht(mp, ht);
}

void resize_hash_table(HashTable *ht, MemoryPool *mp) {
    int new_size = ht->size * 2;
    ListNode **new_buckets = (ListNode **)malloc(new_size * sizeof(ListNode *));
    pthread_rwlock_t *new_locks = (pthread_rwlock_t *)malloc(new_size * sizeof(pthread_rwlock_t));

    for (int i = 0; i < new_size; ++i) {
        new_buckets[i] = NULL;
        pthread_rwlock_init(&new_locks[i], NULL);
    }

    for (int i = 0; i < ht->size; ++i) {
        ListNode *node = ht->buckets[i];
        while (node) {
            unsigned int idx = hash_function(node->key, new_size);
            pthread_rwlock_wrlock(&ht->locks[i]);
            node->next = new_buckets[idx];
            new_buckets[idx] = node;
            pthread_rwlock_unlock(&ht->locks[i]);
            node = node->next;
        }
    }

    free(ht->buckets);
    for (int i = 0; i < ht->size; ++i)
        pthread_rwlock_destroy(&ht->locks[i]);

    ht->buckets = new_buckets;
    ht->size = new_size;
    ht->locks = new_locks;
}

void insert_data(HashTable *ht, const char *key, DataRecord record) {
    unsigned int idx = hash_function(key, ht->size);

    pthread_rwlock_wrlock(&ht->locks[idx]);

    ListNode *new_node = (ListNode *)memory_pool_alloc(ht->mp);
    new_node->key = strdup(key);
    new_node->record = record;
    new_node->next = ht->buckets[idx];
    ht->buckets[idx] = new_node;

    if (++ht->count > (int)(LOAD_FACTOR * ht->size)) {
        resize_hash_table(ht, ht->mp);
    }

    pthread_rwlock_unlock(&ht->locks[idx]);
}

DataRecord *get_data(HashTable *ht, const char *key) {
    unsigned int idx = hash_function(key, ht->size);

    pthread_rwlock_rdlock(&ht->locks[idx]);

    ListNode *node = ht->buckets[idx];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            DataRecord *record = &node->record;
            pthread_rwlock_unlock(&ht->locks[idx]);
            return record;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&ht->locks[idx]);
    return NULL;
}

int main() {
    MemoryPool *mp = create_memory_pool(sizeof(ListNode), 1024);
    HashTable *database = create_hash_table(INITIAL_TABLE_SIZE, mp);

    // Example usage
    DataRecord record = { time(NULL), 1, strdup("Example data") };
    insert_data(database, "key1", record);

    DataRecord *retrieved = get_data(database, "key1");
    if (retrieved) {
        printf("Data: %s\n", retrieved->data);
    }

    free_hash_table(database, mp);

    return 0;
}
```

### Key Points:
- **Memory Pool:** Utilized for efficient memory allocation and deallocation.
- **Hash Table & Linked List:** Stores key-value pairs with conflict resolution via linked lists.
- **Concurrency:** Managed using `pthread_rwlock_t` for read-write locks, providing thread safety.
- **Dynamic Resizing:** Implemented to handle hash table expansion when load factor is exceeded.
- **Data Persistence and Caching:** Not directly included in the code but can be integrated as needed.

The implementation is a simplified model and should be extended with error handling, logging, persistence integration, caching mechanisms, and more refined memory management for production environments.']

