```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Logging function prototype (assuming an external logging system)
void log_event(const char *message);

typedef struct {
    int value;
} record_t;

typedef struct {
    size_t max_size;         // Maximum total memory size for all datasets
    size_t current_usage;    // Current memory usage
    pthread_mutex_t lock;    // Mutex for thread safety

    long *long_offsets;      // Array of 'long' offset values
    int *keys;               // Array of 'int' keys
    record_t **records;      // Array of pointers to records

    size_t num_long_offsets;
    size_t num_keys;
    size_t num_records;
} dataset_t;

// Initialize a random number generator for thread safety
void init_random() {
    pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
    static int is_initialized = 0;
    if (!is_initialized) {
        pthread_mutex_lock(&rand_lock);
        if (!is_initialized) { // Double-checked locking
            srand(time(NULL));
            is_initialized = 1;
        }
        pthread_mutex_unlock(&rand_lock);
    }
}

// Generate a random number within a specified range [min, max]
int generate_random(int min, int max) {
    static pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&rand_lock);
    int num = (rand() % (max - min + 1)) + min;
    pthread_mutex_unlock(&rand_lock);
    return num;
}

// Function to create and manage datasets
int create_datasets(dataset_t *dataset, size_t num_long_offsets, size_t num_keys,
                    size_t num_records, const char *log_prefix) {
    // Initialize random number generator
    init_random();

    if (pthread_mutex_init(&dataset->lock, NULL) != 0) {
        log_event("Mutex initialization failed");
        return -1;
    }

    dataset->max_size = 1024 * 1024 * 100; // Example: 100 MB limit
    dataset->current_usage = 0;

    size_t total_required_memory = 
        (num_long_offsets * sizeof(long)) +
        (num_keys * sizeof(int)) +
        (num_records * sizeof(record_t*));

    pthread_mutex_lock(&dataset->lock);
    if ((dataset->current_usage + total_required_memory) > dataset->max_size) {
        log_event("Memory allocation exceeds maximum threshold");
        pthread_mutex_unlock(&dataset->lock);
        return -1;
    }

    dataset->long_offsets = (long *)malloc(num_long_offsets * sizeof(long));
    dataset->keys = (int *)malloc(num_keys * sizeof(int));
    dataset->records = (record_t **)malloc(num_records * sizeof(record_t*));

    if (!dataset->long_offsets || !dataset->keys || !dataset->records) {
        log_event("Memory allocation failed");
        pthread_mutex_unlock(&dataset->lock);
        free_resources(dataset, 0); // Clean-up on failure
        return -1;
    }

    dataset->current_usage += total_required_memory;
    dataset->num_long_offsets = num_long_offsets;
    dataset->num_keys = num_keys;
    dataset->num_records = num_records;

    for (size_t i = 0; i < num_records; ++i) {
        dataset->records[i] = (record_t *)malloc(sizeof(record_t));
        if (!dataset->records[i]) {
            log_event("Record allocation failed");
            free_resources(dataset, i); // Clean-up on failure
            pthread_mutex_unlock(&dataset->lock);
            return -1;
        }
        dataset->records[i]->value = generate_random(0, 100); // Example range
    }

    log_event("Dataset creation successful");
    pthread_mutex_unlock(&dataset->lock);

    return 0; // Success
}

// Free resources and set pointers to NULL
void free_resources(dataset_t *dataset, size_t num_records_freed) {
    if (dataset->long_offsets) {
        free(dataset->long_offsets);
        dataset->long_offsets = NULL;
    }
    if (dataset->keys) {
        free(dataset->keys);
        dataset->keys = NULL;
    }
    for (size_t i = 0; i < num_records_freed; ++i) {
        if (dataset->records[i]) {
            free(dataset->records[i]);
            dataset->records[i] = NULL;
        }
    }
    if (num_records_freed < dataset->num_records) {
        for (size_t i = num_records_freed; i < dataset->num_records; ++i) {
            if (dataset->records[i]) {
                free(dataset->records[i]);
                dataset->records[i] = NULL;
            }
        }
    }
    if (dataset->records) {
        free(dataset->records);
        dataset->records = NULL;
    }

    pthread_mutex_destroy(&dataset->lock);
}

// Example logging function implementation
void log_event(const char *message) {
    // Integrate with an external logging system here
    printf("%s\n", message); // Placeholder for actual logging mechanism
}
