LogEntry logs[MAX_LOG_ENTRIES];
int current_log_count = 0;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_logs(int num_entries) {
    pthread_mutex_lock(&log_lock);

    if (current_log_count != 0) {
        // Reset existing entries
        for (int i = 0; i < current_log_count; ++i) {
            free(logs[i].message);
            logs[i].id = -1;
        }
        current_log_count = 0;
    }

    time_t now = time(NULL);

    if (num_entries <= MAX_LOG_ENTRIES && num_entries > 0) {
        for (int i = 0; i < num_entries; ++i) {
            LogEntry *entry = &logs[current_log_count];

            entry->id = current_log_count + 1;
            entry->timestamp = now + i;

            size_t message_length = rand() % 256 + 1; // Example constraint
            entry->message = (char *)malloc(message_length);

            if (!entry->message) {
                fprintf(stderr, "Memory allocation failed for log message\n");
                pthread_mutex_unlock(&log_lock);
                return;
            }

            for (size_t j = 0; j < message_length; ++j) {
                entry->message[j] = rand() % 128 + 32; // Random ASCII
            }

            current_log_count++;
        }
    } else {
        fprintf(stderr, "Invalid number of log entries requested\n");
    }

    pthread_mutex_unlock(&log_lock);
}

void reset_logs() {
    initialize_logs(current_log_count);
}

int main() {
