import <time.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    time_t timestamp;
    uint16_t sensor_id;
    float measurement_value;
} DataPoint;

DataPoint* load_data_from_csv(const char *filename, size_t *data_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    size_t buffer_size = INITIAL_BUFFER_SIZE;
    DataPoint *buffer = malloc(buffer_size * sizeof(DataPoint));
    if (!buffer) {
        fclose(file);
        return NULL;
    }

    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (count >= buffer_size) {
            size_t new_buffer_size = buffer_size * 2;
            DataPoint *new_buffer = realloc(buffer, new_buffer_size * sizeof(DataPoint));
            if (!new_buffer) {
                free(buffer);
                fclose(file);
                return NULL;
            }
            buffer = new_buffer;
            buffer_size = new_buffer_size;
        }

        // Parse the line (assuming CSV format: timestamp,sensor_id,measurement_value)
        sscanf(line, "%ld,%hu,%f", &buffer[count].timestamp, &buffer[count].sensor_id, &buffer[count].measurement_value);
        count++;
    }

    *data_count = count;

    fclose(file);

    // Shrink buffer to fit the actual data size
    DataPoint *final_buffer = realloc(buffer, count * sizeof(DataPoint));
    if (!final_buffer) {
        free(buffer);
        return NULL;
    }

    return final_buffer;
}

void free_data(DataPoint *data) {
    free(data);
}
