typedef struct {
    int *keys;
    size_t size;
} key_array;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_memory(offset_array *offset_arr, key_array *key_arr, record **record_list_head) {
    pthread_mutex_lock(&lock);

    // Free offset_array
    if (offset_arr->data != NULL) {
        free(offset_arr->data);
        offset_arr->data = NULL;
        offset_arr->size = 0;
    }

    // Free key_array
    if (key_arr->keys != NULL) {
        free(key_arr->keys);
        key_arr->keys = NULL;
        key_arr->size = 0;
    }

    // Free record_list
    record *current = *record_list_head, *next_record;
    while (current != NULL) {
        next_record = current->next;
        if (current->buffer != NULL) {
            free(current->buffer);
        }
        free(current);
        current = next_record;
    }
    *record_list_head = NULL;

    pthread_mutex_unlock(&lock);
}

int read_keys_from_csv(const char *filename, key_array *key_arr) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: File not found.\n");
        return -1;
    }

    int key;
    size_t count = 0;

    // Count keys
    while (fscanf(file, "%d,", &key) == 1) {
        count++;
    }
    rewind(file);

    key_arr->keys = malloc(count * sizeof(int));
    if (!key_arr->keys) {
        fclose(file);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -2;
    }
    key_arr->size = count;

    // Read keys
    for (size_t i = 0; i < count; ++i) {
        if (fscanf(file, "%d,", &key) != 1) {
            free(key_arr->keys);
            fclose(file);
            fprintf(stderr, "Error: Incorrect file format.\n");
            return -3;
        }
        key_arr->keys[i] = key;
    }

    fclose(file);
    return 0;
}

void initialize_record_list(record **record_list_head, int min_val, int max_val, size_t max_size) {
    pthread_mutex_lock(&lock);

    record *head = NULL, *tail = NULL;

    for (size_t i = 0; i < max_size; ++i) {
        record *new_record = malloc(sizeof(record));
        if (!new_record) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            break;
        }

        new_record->buffer = malloc(MAX_RECORD_SIZE);
        if (!new_record->buffer) {
            free(new_record);
            fprintf(stderr, "Error: Memory allocation failed.\n");
            break;
        }
        memset(new_record->buffer, 0, MAX_RECORD_SIZE);

        new_record->value = rand() % (max_val - min_val + 1) + min_val;
        new_record->next = NULL;

        if (!head) {
            head = tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }
    }

    *record_list_head = head;
    pthread_mutex_unlock(&lock);
}

void manage_dynamic_memory(const char *csv_filename, int min_val, int max_val, size_t offset_size, size_t key_count, size_t record_max_size) {
    offset_array offset_arr;
    key_array key_arr;
    record *record_list_head = NULL;

    // Initialize dynamic memory
    pthread_mutex_lock(&lock);

    offset_arr.data = malloc(offset_size * sizeof(long));
    if (!offset_arr.data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free_memory(&offset_arr, &key_arr, &record_list_head);
        return;
    }
    offset_arr.size = offset_size;

    int key_read_result = read_keys_from_csv(csv_filename, &key_arr);
    if (key_read_result != 0) {
        free(offset_arr.data);
        free_memory(&offset_arr, &key_arr, &record_list_head);
        return;
    }

    initialize_record_list(&record_list_head, min_val, max_val, record_max_size);

    pthread_mutex_unlock(&lock);

    // Log memory usage
    printf("Memory allocated for offset_array: %zu bytes\n", offset_arr.size * sizeof(long));
    printf("Memory allocated for key_array: %zu keys\n", key_arr.size);
    printf("Memory allocated for record_list: %zu records\n", record_max_size);

    // Simulate some operations...

    // Free all dynamically allocated memory
    free_memory(&offset_arr, &key_arr, &record_list_head);
}

int main() {
    srand(time(NULL));
    manage_dynamic_memory("keys.csv", 1, 100, 10, 5, 50);
    return 0;
}
