int allocate_memory(int num_doubles, int num_chars, int num_structs, size_t max_memory) {
    time_t current_time;
    double *doubles = NULL;
    char **char_array = NULL;
    Data *struct_array = NULL;

    // Calculate total memory needed
    size_t memory_needed = 
        (num_doubles * sizeof(double)) +
        (num_chars * sizeof(char *)) + // Pointers to strings
        (num_structs * sizeof(Data)) +
        (num_chars * sizeof(char));     // Assuming 1 char per string for simplicity

    if (memory_needed > max_memory) {
        log_event("Memory allocation exceeds maximum threshold.");
        return -1; // Allocation failed due to memory limit.
    }

    // Allocate memory and handle failures
    doubles = (double *)malloc(num_doubles * sizeof(double));
    if (!doubles) {
        log_event("Failed to allocate memory for doubles.");
        goto cleanup;
    }

    char_array = (char **)malloc(num_chars * sizeof(char *));
    if (!char_array) {
        log_event("Failed to allocate memory for char pointers.");
        free(doubles);
        goto cleanup;
    }

    struct_array = (Data *)malloc(num_structs * sizeof(Data));
    if (!struct_array) {
        log_event("Failed to allocate memory for Data structs.");
        free(doubles);
        free(char_array);
        goto cleanup;
    }

    // Allocate strings
    char **temp_char_array = char_array;
    for (int i = 0; i < num_chars; ++i, ++temp_char_array) {
        *temp_char_array = (char *)malloc(sizeof(char));
        if (!*temp_char_array) {
            log_event("Failed to allocate memory for a char string.");
            while (--temp_char_array >= char_array)
                free(*temp_char_array);
            free(struct_array);
            free(char_array);
            free(doubles);
            goto cleanup;
        }
    }

    // Initialize Data structs
    current_time = time(NULL); // Get the current time
    for (int i = 0; i < num_structs; ++i) {
        struct_array[i].value = 0.0;               // Example initialization
        struct_array[i].string = NULL;             // No string initially assigned
        struct_array[i].timestamp = current_time;  // Initialize timestamp
    }

    log_event("Memory allocation successful.");
    return 0;

cleanup:
    if (doubles) free(doubles);
    if (char_array) {
        char **temp_char_array = char_array;
        for (int i = 0; i < num_chars && *temp_char_array; ++i, ++temp_char_array)
            free(*temp_char_array);
        free(char_array);
    }
    if (struct_array) free(struct_array);

    return -1; // Indicate failure
}

// Usage example
int main() {
    const size_t max_memory = 1024 * 1024; // Example: 1MB limit

    int status = allocate_memory(100, 50, 25, max_memory);
    if (status == 0) {
        printf("Memory allocation succeeded.\n");
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
