#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example max memory usage in bytes
#define RECORD_SIZE sizeof(record)
#define INIT_POOL_SIZE 100

typedef struct {
    int value;
    long offset;
} record;

typedef struct MemoryPool {
    size_t pool_size;
    record* records;
    size_t used_count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->records = (record*)aligned_alloc(alignof(record), initial_size * RECORD_SIZE);
    if (!pool->records) {
        free(pool->records);
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        pool->records[i].value = rand() % 100; // Random int in range [0, 99]
        pool->records[i].offset = rand() % 1000000L;
    }

    return pool;
}

int allocate_record(MemoryPool* pool, record** out_record) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_count >= pool->pool_size || 
        ((size_t)pool->records + (pool->used_count + 1) * RECORD_SIZE - (size_t)malloc(0)) > MAX_MEMORY_USAGE) {

        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory usage exceeded or no space left
    }

    *out_record = &pool->records[pool->used_count++];
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->records);
        pthread_mutex_destroy(&pool->lock);
        pthread_cond_destroy(&pool->cond);
        free(pool);
    }
}

record* get_record_by_offset(MemoryPool* pool, long offset) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->used_count; ++i) {
        if (pool->records[i].offset == offset) {
            pthread_mutex_unlock(&pool->lock);
            return &pool->records[i];
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void* garbage_collector(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;

    while (1) {
        // Simulate low activity period check
        sleep(10);

        pthread_mutex_lock(&pool->lock);

        if (rand() % 2 == 0) { // Randomly trigger garbage collection
            printf("Running garbage collector...\n");
            pool->used_count = 0; // Simplistic garbage collection for illustration
        }

        pthread_mutex_unlock(&pool->lock);
    }
}

int main() {
    srand(time(NULL));

    MemoryPool* pool = create_memory_pool(INIT_POOL_SIZE);
    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return 1;
    }

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collector, (void*)pool);

    record* rec;
    while (allocate_record(pool, &rec) == 0) {
        printf("Allocated Record: %d at offset %ld\n", rec->value, rec->offset);

        // For demonstration, we'll stop after a few allocations
        if (rand() % 10 < 2)
            break;
    }

    record* found = get_record_by_offset(pool, 500000L);
    if (found) {
        printf("Found Record with offset 500000: %d\n", found->value);
    } else {
        printf("Record not found.\n");
    }

    pthread_join(gc_thread, NULL);
    free_memory_pool(pool);

    return 0;
}
