['Below is a C code implementation of the task described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
import <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    uint16_t sensor_id;
    float measurement;
} DataPoint;

typedef struct {
    DataPoint* data_points;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
} DataManager;

void init_data_manager(DataManager* manager, size_t initial_capacity) {
    manager->data_points = malloc(initial_capacity * sizeof(DataPoint));
    if (!manager->data_points) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);
}

void resize_data_manager(DataManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    DataPoint* new_array = realloc(manager->data_points, new_capacity * sizeof(DataPoint));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->data_points = new_array;
    manager->capacity = new_capacity;
}

void add_data_point(DataManager* manager, DataPoint point) {
    pthread_rwlock_wrlock(&manager->rwlock);

    // Check for duplicate sensor_id and consolidate
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->data_points[i].sensor_id == point.sensor_id) {
            float new_average = ((manager->data_points[i].measurement * i) + point.measurement) / (i + 1);
            manager->data_points[i].measurement = new_average;
            pthread_rwlock_unlock(&manager->rwlock);
            return;
        }
    }

    if (manager->count == manager->capacity) {
        resize_data_manager(manager);
    }

    manager->data_points[manager->count++] = point;

    pthread_rwlock_unlock(&manager->rwlock);
}

void populate_from_csv(DataManager* manager, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    const size_t buffer_size = 1024;
    char line[buffer_size];
    while (fgets(line, sizeof(line), file)) {
        time_t timestamp;
        uint16_t sensor_id;
        float measurement;

        if (sscanf(line, "%ld,%hu,%f", &timestamp, &sensor_id, &measurement) == 3) {
            DataPoint point = {timestamp, sensor_id, measurement};
            add_data_point(manager, point);
        }
    }

    fclose(file);
}

void free_data_manager(DataManager* manager) {
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager->data_points);
}

// Usage
int main() {
    DataManager manager;
    init_data_manager(&manager, 10); // Initial capacity of 10

    populate_from_csv(&manager, "sensor_data.csv");

    // Use the data...

    free_data_manager(&manager);

    return 0;
}
```

### Key Features:
- **Initialization and Memory Management**: The `DataManager` structure is initialized with a given capacity, and memory is dynamically resized when needed.
- **Concurrency**: A read-write lock (`pthread_rwlock_t`) ensures thread-safe access to the data array. This minimizes contention for read operations while still protecting write operations.
- **CSV Parsing**: Data from a CSV file is parsed and added to the manager, with duplicates handled by averaging measurements.
- **Error Handling**: Proper error messages are provided for file and memory allocation issues.']

