#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    char *str_ptr;
} record;

// Custom random number generator interface (user-provided)
int custom_random(int min, int max);

void manage_memory_allocation_and_initialization(
    long offset_range_min, long offset_range_max,
    int key_range_min, int key_range_max,
    int record_count, int record_value_min, int record_value_max) {

    if (record_count <= 0) {
        fprintf(stderr, "Record count must be positive.\n");
        return;
    }

    // Allocate memory for offsets
    long *offsets = malloc(record_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        goto error_cleanup;
    }

    // Allocate memory for keys
    int *keys = malloc(record_count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        goto error_cleanup;
    }

    // Initialize unique offsets and keys
    for (int i = 0; i < record_count; ++i) {
        long offset;
        int key;

        do {
            offset = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);
        } while (find_in_array(offset, offsets, i));

        do {
            key = key_range_min + rand() % (key_range_max - key_range_min + 1);
        } while (find_in_array(key, keys, i));

        offsets[i] = offset;
        keys[i] = key;
    }

    // Allocate memory for records
    record *records = malloc(record_count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        goto error_cleanup;
    }

    // Initialize records with unique random values and strings
    for (int i = 0; i < record_count; ++i) {
        int value;
        do {
            value = custom_random(record_value_min, record_value_max);
        } while (find_in_array(value, (int *)records, i));

        records[i].value = value;

        // Allocate memory for string
        char *str = malloc(256 * sizeof(char));
        if (!str) {
            perror("Failed to allocate memory for string");
            free_records(records, i);
