// Function to handle memory allocation and resizing
static void* reallocate_buffer(void *buffer, size_t current_size, size_t new_size) {
    if (new_size == 0) {
        free(buffer);
        return NULL;
    }
    void *new_buffer = realloc(buffer, new_size);
    if (!new_buffer) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return new_buffer;
}

// Function to read CSV file and manage DataPoint array
void process_csv_file(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Buffer setup for dynamic resizing
    size_t buffer_size = INITIAL_BUFFER_SIZE;
    DataPoint *data_buffer = realloc(NULL, buffer_size * sizeof(DataPoint));
    if (!data_buffer) {
        fclose(file);
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }

    size_t data_count = 0;

    char line[256]; // Assuming max line length for CSV entry
    while (fgets(line, sizeof(line), file)) {
        // Simple CSV parsing assuming three fields: timestamp, sensor_id, measurement_value
        char *token = strtok(line, ",");
        if (!token || !strtok(NULL, ",") || !strtok(NULL, ",")) continue; // Malformed line

        DataPoint new_point;
        new_point.timestamp = (time_t)atoi(token);

        token = strtok(NULL, ",");
        new_point.sensor_id = (uint16_t)atoi(token);

        token = strtok(NULL, ",");
        new_point.measurement_value = strtof(token, NULL);

        // Check if we need to resize the buffer
        if (data_count >= buffer_size - 1) {
            size_t new_buffer_size = buffer_size * 2;
            data_buffer = reallocate_buffer(data_buffer, buffer_size * sizeof(DataPoint), new_buffer_size * sizeof(DataPoint));
            buffer_size = new_buffer_size;

            // Log memory allocation
            fprintf(stderr, "Buffer resized to %zu entries\n", buffer_size);
        }

        data_buffer[data_count++] = new_point;
    }

    fclose(file);

    // Finalize - processing or saving the loaded data can happen here
    printf("Loaded %zu DataPoints.\n", data_count);

    // Free allocated memory
    free(data_buffer);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_csv_file(argv[1]);

    return EXIT_SUCCESS;
}
```

