void free_resources(long* offsets, int* keys, Record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int sort_records(Record* records, int* keys, size_t num_records) {
    if (!records || !keys) return -1;

    // Sort based on the keys using a simple comparison function
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = 0; j < num_records - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                // Swap records
                Record temp_record = records[j];
                int temp_key = keys[j];

                records[j] = records[j + 1];
                records[j + 1] = temp_record;

                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;
            }
        }
    }

    return 0;
}
