} DataStructures;

void initialize_random() {
    srand((unsigned int) time(NULL));
}

int generate_unique_key(int *array, size_t count, int max_value) {
    static int used[max_value + 1] = {0};
    for (int i = 0; i < max_value + 1; ++i) {
        if (!used[i]) {
            int potential_key = i;
            for (size_t j = 0; j < count; ++j) {
                if (array[j] == potential_key) {
                    used[i] = 1;
                    return generate_unique_key(array, count, max_value);
                }
            }
            used[i] = 1;
            return potential_key;
        }
    }
    return -1; // Should never reach here if max_value is appropriate
}

DataStructures* create_data_structures(size_t element_count, int record_min, int record_max) {
    if (element_count <= 0 || record_min > record_max) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    DataStructures *ds = malloc(sizeof(DataStructures));
    if (!ds) {
        perror("Failed to allocate memory for DataStructures");
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = malloc(element_count * sizeof(long));
    if (!ds->offsets) {
        free(ds);
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    ds->keys = malloc(element_count * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    ds->records = malloc(element_count * sizeof(record));
    if (!ds->records) {
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    initialize_random();

    pthread_mutex_lock(&ds->lock);

    // Initialize offsets with random long integers
    for (size_t i = 0; i < element_count; ++i) {
        ds->offsets[i] = rand() % 10000; // example range, adjust as needed
    }

    // Initialize keys ensuring no duplicates
    for (size_t i = 0; i < element_count; ++i) {
        int key;
        do {
            key = generate_unique_key(ds->keys, i, element_count - 1);
        } while (key == -1);

        ds->keys[i] = key;
    }

    // Initialize records with random values within a specified range
    for (size_t i = 0; i < element_count; ++i) {
        ds->records[i].value = rand() % (record_max - record_min + 1) + record_min;
    }

    ds->count = element_count;

    pthread_mutex_unlock(&ds->lock);
    return ds;
}

void free_data_structures(DataStructures *ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Usage example:
// DataStructures *ds = create_data_structures(100, 10, 20);
// ... use ds ...
// free_data_structures(ds);
