#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Define global logging level and mutex for thread safety
int log_level = 1; // 0: None, 1: Stdout, 2: File
FILE *log_file = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    if (log_level == 1) {
        printf("%s\n", message);
    } else if (log_level == 2 && log_file != NULL) {
        pthread_mutex_lock(&lock);
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
        pthread_mutex_unlock(&lock);
    }
}

void free_resources(long* offsets, int* keys, record** records) {
    free(offsets);
    free(keys);
    free(*records);
    *records = NULL;
}

long* allocate_aligned(size_t size, size_t alignment) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        log_message("Memory allocation failed");
        return NULL;
    }
    return (long*)ptr;
}

record* manage_memory_allocation(int record_count, int initial_capacity, int key_range_start, int key_range_end) {
    if (record_count <= 0 || initial_capacity <= 0 || key_range_start >= key_range_end) {
        log_message("Invalid input parameters");
        return NULL;
    }

    long* offsets = allocate_aligned(record_count * sizeof(long), alignof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(record_count * sizeof(int));
    if (!keys) { free(offsets); return NULL; }

    // Initialize the record array with dynamic resizing capability
    record* records = (record*)malloc(initial_capacity * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Random number generation setup
    srand((unsigned int)time(NULL));

    for (int i = 0; i < record_count; ++i) {
        offsets[i] = rand() % key_range_end + key_range_start;

        if (i >= initial_capacity) {
            // Resize records array
            initial_capacity *= 2;
            record* temp = realloc(records, initial_capacity * sizeof(record));
            if (!temp) { free_resources(offsets, keys, &records); return NULL; }
            records = temp;
        }

        records[i].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    }

    log_message("Memory allocation and initialization successful");
    return records; // Caller is responsible for freeing this
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [log level: 0|1|2]\n", argv[0]);
        return EXIT_FAILURE;
    }

    log_level = atoi(argv[1]);

    if (log_level == 2) {
        log_file = fopen("app.log", "w");
        if (!log_file) { perror("Failed to open log file"); exit(EXIT_FAILURE); }
    }

    int record_count = 10; // Example count
    int initial_capacity = 5;
    int key_range_start = 0;
    int key_range_end = 100;

    pthread_t threads[2];

    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, (void* (*)(void*))manage_memory_allocation, (void*)&record_count)) {
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    record* result = NULL;
    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], (void**)&result);
    }

    if (log_level == 2 && log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}
