    pthread_mutex_lock(&mem_manager.lock);
    record *rec = (record *)(mem_manager.records_pool + mem_manager.records_count * RECORD_STRUCT_SIZE);
    rec->value = rand() % 100; // Initialize with random value in range
    mem_manager.records_count++;
    pthread_mutex_unlock(&mem_manager.lock);

    return rec;
}

