        long *new_offsets = realloc(mem_manager.offsets, num_offsets * sizeof(long));
        if (!new_offsets) exit(EXIT_FAILURE);
        memset(new_offsets + mem_manager.offsets_size, 0, (num_offsets - mem_manager.offsets_size) * sizeof(long));
        mem_manager.offsets_size = num_offsets;
