    pthread_mutex_init(&pool->lock, NULL);
    for (size_t i = 0; i < capacity; ++i) {
        pool->free_list[i] = malloc(block_size);
    }
    return pool;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->free_list[i] != NULL) {
            void *block = pool->free_list[i];
            pool->free_list[i] = NULL;
            pthread_mutex_unlock(&pool->lock);
            return block;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return malloc(size); // Fallback if no free blocks
}

void free_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
```

