// Define a structure for points with x and y coordinates.
typedef struct {
    double x;
    double y;
} point;

// Define a structure for polygons containing an array of points and the number of vertices.
typedef struct {
    int num_vertices;
    point *vertices;
} polygon;

// Function to initialize random number generator
void init_random_generator() {
    srand((unsigned) time(NULL));
}

// Function to generate Gaussian-distributed double value
double gaussian(double mean, double stddev) {
    static double v1, v2, s;
    static int phase = 0;

    if (phase == 0) {
        do {
            double u1 = ((double)rand() / RAND_MAX);
            double u2 = ((double)rand() / RAND_MAX);

            v1 = 2 * u1 - 1;
            v2 = 2 * u2 - 1;
            s = v1 * v1 + v2 * v2;
        } while (s >= 1 || s == 0);

        double multiplier = sqrt(-2 * log(s) / s);
        phase = 1;

        return mean + stddev * v1 * multiplier;
    }

    phase = 0;
    return mean + stddev * v2 * multiplier;
}

// Function to allocate and initialize polygons with Gaussian-distributed coordinates
polygon* create_polygons(int num_polygons, int vertices_per_polygon, double mean_x, double stddev_x, double mean_y, double stddev_y) {
    if (num_polygons <= 0 || vertices_per_polygon <= 0) {
        return NULL;
    }

    // Allocate memory for an array of polygons
    polygon *polygons = (polygon *)malloc(num_polygons * sizeof(polygon));
    if (!polygons) {
        fprintf(stderr, "Memory allocation failed for polygons.\n");
        return NULL;
    }

    init_random_generator();

    for (int i = 0; i < num_polygons; ++i) {
        // Allocate memory for vertices of the polygon
        point *vertices = (point *)malloc(vertices_per_polygon * sizeof(point));
        if (!vertices) {
            fprintf(stderr, "Memory allocation failed for points in polygon %d.\n", i);

            // Free previously allocated polygons and vertices before returning
            while (--i >= 0) {
                free(polygons[i].vertices);
            }
            free(polygons);
            return NULL;
        }

        // Initialize the coordinates of each vertex using Gaussian distribution
        for (int j = 0; j < vertices_per_polygon; ++j) {
            vertices[j].x = gaussian(mean_x, stddev_x);
            vertices[j].y = gaussian(mean_y, stddev_y);
        }

        polygons[i].num_vertices = vertices_per_polygon;
        polygons[i].vertices = vertices;
    }

    return polygons;
}

// Function to free allocated memory for polygons
void destroy_polygons(polygon *polygons, int num_polygons) {
    if (!polygons) return;

    for (int i = 0; i < num_polygons; ++i) {
        free(polygons[i].vertices);
    }
    free(polygons);
}

// Example usage of the function
int main() {
    int num_polygons = 5;
    int vertices_per_polygon = 4;
    double mean_x = 0.0, stddev_x = 1.0;
    double mean_y = 0.0, stddev_y = 1.0;

    polygon *polygons = create_polygons(num_polygons, vertices_per_polygon, mean_x, stddev_x, mean_y, stddev_y);

    if (polygons) {
        for (int i = 0; i < num_polygons; ++i) {
            printf("Polygon %d:\n", i + 1);
            for (int j = 0; j < polygons[i].num_vertices; ++j) {
                printf("Vertex %d: (%f, %f)\n", j + 1, polygons[i].vertices[j].x, polygons[i].vertices[j].y);
            }
        }

        // Free the allocated memory
        destroy_polygons(polygons, num_polygons);
    } else {
        fprintf(stderr, "Failed to create polygons.\n");
    }

    return 0;
}
