#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdatomic.h>
#include <pthread.h>

// Record structure definition
typedef struct {
    int value;
} record;

// Memory pool definition
typedef struct {
    size_t element_size;
    size_t capacity;
    atomic_uintptr_t free_list_head;
    void* memory_block;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} memory_pool;

// Random number generator cache
typedef struct {
    int cached_value;
    unsigned long last_seed;
} random_cache;

// Logging configuration
typedef enum { LOG_TO_STDOUT, LOG_TO_FILE } log_destination;
typedef struct {
    log_destination destination;
    FILE* file_handle; // Used if logging to a file
} logging_config;

// Function prototypes
void* memory_pool_allocate(memory_pool* pool);
void memory_pool_deallocate(memory_pool* pool, void* ptr);
memory_pool* create_memory_pool(size_t element_size, size_t capacity);
void destroy_memory_pool(memory_pool* pool);

int generate_random(int min, int max, random_cache* cache, uint32_t seed);
void initialize_record_array(memory_pool* pool, record** records, size_t initial_capacity);
void resize_record_array(record*** records, size_t new_capacity, memory_pool* pool);

// Function implementations
memory_pool* create_memory_pool(size_t element_size, size_t capacity) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->capacity = capacity;
    pool->free_list_head = 0;
    pthread_mutex_init(&pool->lock, NULL);

    size_t total_memory_size = element_size * capacity;
    pool->memory_block = malloc(total_memory_size);
    if (!pool->memory_block) {
        free(pool);
        return NULL;
    }

    void** entries = (void**)pool->memory_block;
    for (size_t i = 0; i < capacity - 1; ++i) {
        entries[i] = ((char*)entries) + element_size;
    }
    entries[capacity - 1] = NULL;

    atomic_store(&pool->free_list_head, (uintptr_t)entries);

    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    if (!pool) return;
    free(pool->memory_block);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void* memory_pool_allocate(memory_pool* pool) {
    if (!pool) return NULL;

    void** head = (void**)atomic_load(&pool->free_list_head);
    while (head && *head != NULL) {
        void* ptr = atomic_exchange(head, *(void**)head);
        if (ptr) return ptr;
    }
    pthread_mutex_lock(&pool->lock);
    // If allocation from free list failed
    for (size_t i = 0; i < pool->capacity; ++i) {
        void** entry = ((void**)pool->memory_block) + i;
        void* ret = atomic_exchange(entry, NULL);
        if (ret) {
            pthread_mutex_unlock(&pool->lock);
            return ret;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Pool exhausted
}

void memory_pool_deallocate(memory_pool* pool, void* ptr) {
    if (!ptr || !pool) return;

    pthread_mutex_lock(&pool->lock);
    // Add to free list (simple LIFO)
    ((void**)atomic_load(&pool->free_list_head))[0] = ptr;
    pthread_mutex_unlock(&pool->lock);
}

int generate_random(int min, int max, random_cache* cache, uint32_t seed) {
    if (!cache || !seed) return 0;

    unsigned long current_time = (unsigned long)time(NULL); // Simplistic time-based randomness
    if (current_time != cache->last_seed) { // Refresh cache when seed changes
        srand(seed + current_time);
        cache->cached_value = rand() % (max - min + 1) + min;
        cache->last_seed = current_time;
    }

    return cache->cached_value;
}

void initialize_record_array(memory_pool* pool, record** records, size_t initial_capacity) {
    if (!pool || !records) return;

    *records = (record*)memory_pool_allocate(pool);
    if (*records) {
        for (size_t i = 0; i < initial_capacity; ++i) {
            random_cache cache;
            cache.cached_value = 0;
            cache.last_seed = 0;
            (*records)[i].value = generate_random(1, 100, &cache, time(NULL));
        }
    }
}

void resize_record_array(record*** records, size_t new_capacity, memory_pool* pool) {
    if (!records || !pool) return;

    record* old_records = *records;
    if (old_records) {
        memory_pool_deallocate(pool, old_records);
    }

    *records = (record*)memory_pool_allocate(pool);
    if (*records) {
        // Initialize or move data as needed
    }
}

void configure_logging(logging_config* config, log_destination destination, const char* file_path) {
    if (!config) return;

    config->destination = destination;
    if (destination == LOG_TO_FILE) {
        config->file_handle = fopen(file_path, "a");
    } else {
        config->file_handle = stdout;
    }
}

void log_event(logging_config* config, const char* message) {
    if (!config || !message) return;

    FILE* dest = (config && config->destination == LOG_TO_FILE) ? config->file_handle : stdout;
    fprintf(dest, "%s\n", message);
    fflush(dest); // Ensure immediate output
}

// Example usage of the functions above
int main() {
    memory_pool* pool = create_memory_pool(sizeof(record), 1024);
    if (!pool) return EXIT_FAILURE;

    record* records = NULL;
    initialize_record_array(pool, &records, 256);

    // Further operations...

    resize_record_array(&records, 512, pool);

    // Clean-up
    memory_pool_deallocate(pool, records);
    destroy_memory_pool(pool);

    logging_config log_config;
    configure_logging(&log_config, LOG_TO_STDOUT, NULL);
    log_event(&log_config, "Completed example execution");

    return EXIT_SUCCESS;
}
```

