#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    float value;
    char *name;
} record;

typedef struct MemoryPool {
    size_t unit_size;
    unsigned char *pool;
    size_t pool_size;
    void **free_list;
    size_t free_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t unit_size, size_t count) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->unit_size = unit_size;
    mp->pool_size = unit_size * count;
    mp->pool = (unsigned char*)aligned_alloc(alignof(long), mp->pool_size);
    mp->free_count = count;

    mp->free_list = (void**)malloc(count * sizeof(void*));
    for (size_t i = 0; i < count; ++i) {
        mp->free_list[i] = mp->pool + i * unit_size;
    }
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_count == 0) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void *ptr = mp->free_list[--mp->free_count];
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void memory_pool_free(MemoryPool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_count < mp->pool_size / mp->unit_size) {
        mp->free_list[mp->free_count++] = ptr;
    }
    pthread_mutex_unlock(&mp->lock);
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->free_list);
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* manage_records(size_t record_count, const char *log_file) {
    MemoryPool *mp = create_memory_pool(sizeof(record), record_count);

    record *records = (record*)memory_pool_alloc(mp);
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    initialize_random_seed();

    FILE *log_fp = strcmp(log_file, "stdout") == 0 ? stdout : fopen(log_file, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        free_memory_pool(mp);
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].id = generate_random_int(1, 100);
        records[i].value = (float)i * 1.23f; // Example default value
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "Record_%zu", i + 1);
        records[i].name = strdup(buffer);

        fprintf(log_fp, "Initialized record %zu with id %d\n", i + 1, records[i].id);
    }

    if (strcmp(log_file, "stdout") != 0) {
        fclose(log_fp);
    }

    return records;
}

void cleanup_records(record *records, size_t record_count, MemoryPool *mp) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].name);
    }
    memory_pool_free(mp, records);
    free_memory_pool(mp);
}
