void freeResources(float **timestamps, short **identifiers, Event **events, size_t numEvents);

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processLogFile(argv[1]);

    return EXIT_SUCCESS;
}

void processLogFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    float *timestamps = NULL;
    short *identifiers = NULL;
    Event *events = NULL;
    size_t capacity = 0, numEvents = 0;

    const size_t bufferSize = 256;
    char buffer[bufferSize];

    while (fgets(buffer, bufferSize, file)) {
        if (numEvents == capacity) {
            // Double the current capacity to accommodate more events
            capacity = capacity ? capacity * 2 : 4;
            timestamps = realloc(timestamps, capacity * sizeof(float));
            identifiers = realloc(identifiers, capacity * sizeof(short));
            events = realloc(events, capacity * sizeof(Event));

            handleMemoryAllocationError(timestamps, "realloc for timestamps");
            handleMemoryAllocationError(identifiers, "realloc for identifiers");
            handleMemoryAllocationError(events, "realloc for events");
        }

        float timestamp;
        short identifier;
        int status;

        if (sscanf(buffer, "%f %hd %d", &timestamp, &identifier, &status) == 3) {
            timestamps[numEvents] = timestamp;
            identifiers[numEvents] = identifier;
            events[numEvents].timestamp = timestamp;
            events[numEvents].identifier = identifier;
            events[numEvents].status = status;

            // Assume integration with external systems here
            numEvents++;
        }
    }

    fclose(file);

    // Handle or process the populated structures as needed.
    // For demonstration, we simply free the allocated memory.

    freeResources(&timestamps, &identifiers, &events, numEvents);
}

void handleMemoryAllocationError(void *ptr, const char *allocationType) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for %s\n", allocationType);
        exit(EXIT_FAILURE);
    }
}

void freeResources(float **timestamps, short **identifiers, Event **events, size_t numEvents) {
    free(*timestamps);
    free(*identifiers);
    free(*events);

    *timestamps = NULL;
    *identifiers = NULL;
    *events = NULL;
}
