    r_struct->buffer[MAX_BUFFER_LENGTH - 1] = '\0';

    Metadata *metadata = (Metadata *)malloc(METADATA_SIZE);
    if (!metadata) {
        log_message("Memory allocation for metadata failed");
        free(r_struct->buffer);
        free(record);
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    metadata->timestamp = timestamp;
    metadata->status_flag = status_flag;

    r_struct->metadata = metadata;

    pthread_mutex_unlock(&lock);
    log_message("DataRecord initialized successfully");

