}

// Function to validate log entry format
int is_valid_log_entry(const char* timestamp, const char* user_id_str, const char* message) {
    // Simple validation logic
    if (strlen(message) >= MAX_LOG_SIZE)
        return 0;
    for (char* p = timestamp; *p; ++p)
        if (*p < '0' || *p > '9')
            return 0;
    for (char* p = user_id_str; *p; ++p)
        if (*p < '0' || *p > '9')
            return 0;
    return 1;
}

// Function to append a new log entry
void append_log_entry(ThreadSafeLinkedList* list, LogEntry entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    node->data = entry;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    node->next = list->head;
    list->head = node;
    log_change("Log entry added.");
    pthread_mutex_unlock(&list->lock);
}

// Function to process a log entry
void process_log_entry(ThreadSafeLinkedList* list, const char* timestamp, int user_id, const char* message) {
    LogEntry entry = {0};
    snprintf(entry.timestamp, sizeof(entry.timestamp), "%s", timestamp);
    entry.user_id = user_id;

    if (is_valid_log_entry(timestamp, "1234", message)) {
        strncpy(entry.message, message, MAX_LOG_SIZE - 1);
        append_log_entry(list, entry);
    } else {
        snprintf(entry.message, MAX_LOG_SIZE, "%s%s%s", message, LOG_ENTRY_SEPARATOR, message);
        append_log_entry(list, entry);
    }
}

// Function to initialize the thread-safe linked list
void init_list(ThreadSafeLinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Cache functions
void cache_init(Cache* cache) {
    cache->count = 0;
    pthread_rwlock_init(&cache->rwlock, NULL);
}

void cache_add(Cache* cache, LogEntry* entry) {
    pthread_rwlock_wrlock(&cache->rwlock);
    if (cache->count < CACHE_SIZE) {
        cache->entries[cache->count++] = entry;
    }
    pthread_rwlock_unlock(&cache->rwlock);
}

LogEntry* cache_get(Cache* cache, int index) {
    pthread_rwlock_rdlock(&cache->rwlock);
    LogEntry* entry = (index >= 0 && index < cache->count) ? cache->entries[index] : NULL;
    pthread_rwlock_unlock(&cache->rwlock);
    return entry;
}

// Function to dynamically allocate and initialize arrays
void allocate_arrays(long long* offset_array, int offset_count, int* key_array, int key_count) {
    offset_array = (long long*)malloc(offset_count * sizeof(long long));
    if (!offset_array) {
        perror("Failed to allocate memory for offset array");
        exit(EXIT_FAILURE);
