        if (!records[i].string) {
            perror("Failed to allocate memory for string");
            // Free previously allocated strings
            for (int j = 0; j < i; ++j)
                free(records[i].string);
            free(offset_array);
            free(key_array);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to periodically save the linked list state to disk
void* periodic_save_to_disk(void* arg) {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)arg;
    while (1) {
        sleep(DISK_SAVE_INTERVAL);
        pthread_mutex_lock(&list->lock);
        // Save logic here
        log_change("Linked list saved to disk.");
        pthread_mutex_unlock(&list->lock);
    }
}

int main() {
    ThreadSafeLinkedList list;
    Cache cache;

    init_list(&list);
    cache_init(&cache);

    pthread_t save_thread;
    pthread_create(&save_thread, NULL, periodic_save_to_disk, &list);

