        perror("Failed to allocate memory for records");
        free(offset_array);
        free(key_array);
        exit(EXIT_FAILURE);
    }

    init_records(records, 100, 1, 1000, NULL);

    // Cleanup
    pthread_cancel(save_thread);
    pthread_join(save_thread, NULL);

    while (list.head) {
        Node* temp = list.head;
        list.head = list.head->next;
        free(temp);
    }

    pthread_mutex_destroy(&list.lock);
    pthread_rwlock_destroy(&cache.rwlock);

    for (int i = 0; i < 100; ++i)
        free(records[i].string);
    free(records);
    free(offset_array);
    free(key_array);

    return 0;
}
