#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int short_field;
    int int_field;
    long value; // Unique value
    struct Record* next;
} Record;

typedef struct Metadata {
    size_t total_records;
    long highest_value;
    long lowest_value;
    double average_value;
} Metadata;

typedef struct CacheEntry {
    long key;
    Record* record;
    struct CacheEntry* next;
} CacheEntry;

#define CACHE_SIZE 100
#define OFFSET_INCREMENT 10

// Global lock for synchronization
pthread_mutex_t data_lock = PTHREAD_MUTEX_INITIALIZER;
CacheEntry* cache_head = NULL;

// Function prototypes
void init_data_structures(size_t num_records, long value_min, long value_max);
Record* create_record(long value);
Metadata calculate_metadata(Record* head);
void add_to_cache(long key, Record* record);
Record* get_from_cache(long key);
void save_state_to_disk(const char* filename, Record* head);

void init_data_structures(size_t num_records, long value_min, long value_max) {
    pthread_mutex_lock(&data_lock);

    size_t i;
    long current_value = value_min;
    long prev_value = -1; // Initialize with an impossible value
    long offset_sum = 0;

    Record* head = NULL;
    Record** tail = &head;

    Metadata metadata = {0, value_min, value_max, 0.0};

    for (i = 0; i < num_records; ++i) {
        // Ensure unique non-consecutive values
        do {
            current_value += rand() % (value_max - value_min + 1);
        } while (current_value == prev_value);

        *tail = create_record(current_value);
        (*tail)->short_field = rand() % 1000;
        (*tail)->int_field = rand() % 10000;

        Record* new_tail = create_record(0); // Dummy node for tail management
        (*tail)->next = new_tail;
        tail = &(*tail)->next;

        prev_value = current_value;
        offset_sum += OFFSET_INCREMENT; // Example calculation

        metadata.total_records++;
    }
    *tail = NULL;

    if (metadata.total_records > 0) {
        metadata.highest_value = value_max;
        metadata.lowest_value = value_min;
        metadata.average_value = ((double)value_min + (double)value_max) / 2.0;
    }

    printf("Metadata: Total Records=%zu, Highest Value=%ld, Lowest Value=%ld, Average Value=%.2f\n",
           metadata.total_records, metadata.highest_value, metadata.lowest_value, metadata.average_value);

    // Cache initialization
    for (i = 0; i < CACHE_SIZE; ++i) {
        CacheEntry* entry = malloc(sizeof(CacheEntry));
        entry->next = cache_head;
        cache_head = entry;
    }

    pthread_mutex_unlock(&data_lock);
}

Record* create_record(long value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    return record;
}

Metadata calculate_metadata(Record* head) {
    Metadata metadata = {0, LLONG_MAX, LLONG_MIN, 0.0};
    Record* current = head;

    while (current != NULL) {
        if (current->value > metadata.highest_value) {
            metadata.highest_value = current->value;
        }
        if (current->value < metadata.lowest_value) {
            metadata.lowest_value = current->value;
        }

        metadata.total_records++;
        metadata.average_value += current->value;

        current = current->next;
    }

    if (metadata.total_records > 0) {
        metadata.average_value /= metadata.total_records;
    }

    return metadata;
}

void add_to_cache(long key, Record* record) {
    pthread_mutex_lock(&data_lock);

    CacheEntry* entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        perror("Failed to allocate memory for cache entry");
        exit(EXIT_FAILURE);
    }
    entry->key = key;
    entry->record = record;
    entry->next = cache_head;
    cache_head = entry;

    pthread_mutex_unlock(&data_lock);
}

Record* get_from_cache(long key) {
    pthread_mutex_lock(&data_lock);

    CacheEntry* current = cache_head;
    while (current != NULL) {
        if (current->key == key) {
            Record* record = current->record;
            // Remove from cache
            cache_head = current->next;
            free(current);
            pthread_mutex_unlock(&data_lock);
            return record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&data_lock);
    return NULL;
}

void save_state_to_disk(const char* filename, Record* head) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for saving state");
        exit(EXIT_FAILURE);
    }

    Record* current = head;
    while (current != NULL) {
        fprintf(file, "%ld %d %d\n", current->value, current->short_field, current->int_field);
        current = current->next;
    }

    fclose(file);
}

// Example usage
int main() {
    srand(time(NULL));
    init_data_structures(1000, 1, 10000);

    // Simulate access and caching
    Record* record = get_from_cache(5); // Assuming key '5' is present

    if (record) {
        printf("Record Retrieved: Value=%ld, ShortField=%d, IntField=%d\n",
               record->value, record->short_field, record->int_field);
    } else {
        printf("Record not found in cache.\n");
    }

    // Save state to disk
    save_state_to_disk("state.txt", NULL); // Provide actual head pointer

    return 0;
}
```

### Key Features:
- **Dynamic Memory Allocation**: Uses `malloc` for dynamic memory allocation of records and cache entries.
- **Linked List Management**: Manages a linked list of `Record` structures with unique non-consecutive values.
- **Metadata Calculation**: Calculates metadata including total records, highest/lowest values, and average value.
- **Caching Mechanism**: Implements a simple LRU-like caching mechanism using a singly-linked list.
- **Concurrency Handling**: Uses mutex locks to ensure thread-safe access and modifications.
- **Periodic State Saving**: Provides a function to save the state of data structures to disk.

This code is designed to be modular, allowing for easy extension and integration with additional features such as logging and external libraries.']

