#define INITIAL_HASH_TABLE_SIZE 16
#define MAX_MEMORY_USAGE 1048576 // in bytes, adjust as needed

typedef struct record {
    int value;
    struct record *next;
} record_t;

typedef struct hashtable_node {
    int key;
    record_t *records;
    pthread_mutex_t lock;
} hashtable_node_t;

typedef struct {
    long *offsets;
