} data_structure_t;

void init_random(unsigned seed) {
    srand(seed);
}

int random_value_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

hash_table_t *create_hash_table(size_t initial_size, unsigned seed) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->size = initial_size;
    table->count = 0;
    table->memory_usage = sizeof(hash_table_t);
    table->seed = seed;

    init_random(seed);

    table->nodes = calloc(table->size, sizeof(hashtable_node_t *));
    for (size_t i = 0; i < table->size; ++i) {
        table->nodes[i] = NULL;
        pthread_mutex_init(&table->lock, NULL);
    }

    pthread_rwlock_init(&table->cache_lock, NULL);

    // Allocate cache memory
    table->cache_keys = malloc(table->size * sizeof(int)); 
    table->cache_records = malloc(table->size * sizeof(record_t *));
    if (!table->cache_keys || !table->cache_records) {
        free(table->nodes);
        free(table);
        return NULL;
    }

    return table;
}

unsigned hash_function(int key, size_t size) {
    unsigned int hash = (unsigned int)key;
    hash ^= (hash >> 20) ^ (hash >> 12);
    return hash % size;
}

int add_record(data_structure_t *ds, int key) {
    pthread_mutex_lock(&ds->lock);

    if (ds->memory_usage + sizeof(record_t) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&ds->lock);
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }

    unsigned index = hash_function(key, ds->hash_table_size);
    hashtable_node_t *node = ds->hash_table[index];

    if (!node) {
        node = malloc(sizeof(hashtable_node_t));
        if (!node) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        pthread_mutex_init(&node->lock, NULL);
        node->key = key;
        node->records = NULL;

        ds->hash_table[index] = node;
    } else {
        while (node && node->key != key) {
            node = node->next;
        }
    }

    if (!node || !node->records) {
        record_t *new_record = malloc(sizeof(record_t));
        if (!new_record) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        new_record->value = random_value_in_range(0, 100); // Adjust range as needed
        new_record->next = node ? node->records : NULL;

        if (node && !node->records) {
            pthread_mutex_lock(&node->lock);
        }

        if (!node->records) {
            node->records = new_record;
        } else {
            record_t *current = node->records;
            while (current->next) {
                current = current->next;
            }
            current->next = new_record;
        }

        if (node && !node->records) {
            pthread_mutex_unlock(&node->lock);
        }
    }

    ds->memory_usage += sizeof(record_t);

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

record_t *get_record(data_structure_t *ds, int key) {
    unsigned index = hash_function(key, ds->hash_table_size);
    hashtable_node_t *node = ds->hash_table[index];

    if (pthread_rwlock_rdlock(&ds->cache_lock) == 0) {
        for (size_t i = 0; i < ds->count; ++i) {
            if (ds->keys[i] == key) {
                pthread_rwlock_unlock(&ds->cache_lock);
                return ds->cache_records[i];
            }
        }
        pthread_rwlock_unlock(&ds->cache_lock);
    }

    while (node && node->key != key) {
        node = node->next;
    }

    if (!node || !node->records) {
        return NULL;
    }

    record_t *record = node->records;
    // Update cache with this entry
    pthread_rwlock_wrlock(&ds->cache_lock);
    ds->keys[ds->count] = key;
    ds->cache_records[ds->count] = record;
    ds->count++;
    pthread_rwlock_unlock(&ds->cache_lock);

    return record;
}

void resize_hash_table(data_structure_t *ds) {
    size_t new_size = ds->hash_table_size * 2;

    hashtable_node_t **new_nodes = calloc(new_size, sizeof(hashtable_node_t *));
    if (!new_nodes) {
        fprintf(stderr, "Failed to allocate memory for resizing hash table\n");
        return;
    }

    pthread_mutex_lock(&ds->lock);

    // Rehash all entries
    for (size_t i = 0; i < ds->hash_table_size; ++i) {
        hashtable_node_t *node = ds->hash_table[i];
        while (node) {
            unsigned new_index = hash_function(node->key, new_size);

            if (!new_nodes[new_index]) {
                new_nodes[new_index] = node;
                node->next = NULL;
            } else {
                hashtable_node_t *current = new_nodes[new_index];
                while (current->next) {
                    current = current->next;
                }
                current->next = node;
            }

            node = node->next;
        }
    }

    free(ds->hash_table);
    ds->hash_table = new_nodes;
    ds->hash_table_size = new_size;

    pthread_mutex_unlock(&ds->lock);
}

void save_to_disk(data_structure_t *ds) {
    // Implement data persistence logic
}

void cleanup_data_structure(data_structure_t *ds) {
    for (size_t i = 0; i < ds->hash_table_size; ++i) {
        hashtable_node_t *node = ds->hash_table[i];
        while (node) {
            record_t *record = node->records;
            while (record) {
                record_t *temp = record;
                record = record->next;
                free(temp);
                ds->memory_usage -= sizeof(record_t);
            }

            hashtable_node_t *to_delete = node;
            node = node->next;

            pthread_mutex_destroy(&to_delete->lock);
            free(to_delete);
        }
    }

    free(ds->hash_table);
    free(ds->offsets);
    free(ds->keys);
    free(ds->cache_keys);
    free(ds->cache_records);

    pthread_rwlock_destroy(&ds->cache_lock);
}

