    }
    free(pool->events);

    for (size_t i = 0; i < pool->attribute_count; ++i) {
        free(pool->attributes[i]);
    }
    free(pool->attributes);

    for (size_t i = 0; i < pool->capacity; ++i) {
        Node *node = pool->buckets[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            free(temp->key);
