['Below is a C implementation for managing a dynamic record store that supports efficient insertion, retrieval, and iteration over records with integer keys, long offsets, and double timestamps. The design uses a hash table combined with linked lists to handle collisions efficiently, ensuring fast access times and scalability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TABLE_SIZE 10000000

typedef struct Record {
    int key;
    long offset;
    double timestamp;
    struct Record* next;
} Record;

typedef struct {
    Record** table;
    size_t table_size;
    double min_timestamp;
    double max_timestamp;
} RecordStore;

// Hash function for integer keys
unsigned int hash(int key, size_t table_size) {
    return (unsigned int)(key % table_size);
}

// Initialize the record store
void init_record_store(RecordStore* store, size_t size) {
    store->table = calloc(size, sizeof(Record*));
    if (!store->table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    store->table_size = size;
    store->min_timestamp = 0.0;
    store->max_timestamp = time(NULL); // Initialize with current time
}

// Insert a record into the store
void insert_record(RecordStore* store, int key, long offset, double timestamp) {
    unsigned int index = hash(key, store->table_size);
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        exit(EXIT_FAILURE);
    }
    new_record->key = key;
    new_record->offset = offset;
    new_record->timestamp = timestamp;
    new_record->next = store->table[index];
    store->table[index] = new_record;
}

// Retrieve a record by key
Record* get_record(RecordStore* store, int key) {
    unsigned int index = hash(key, store->table_size);
    Record* current = store->table[index];
    while (current) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL; // Not found
}

// Update a record's timestamp
void update_record_timestamp(RecordStore* store, int key, double new_timestamp) {
    Record* record = get_record(store, key);
    if (record) {
        record->timestamp = new_timestamp;
    }
}

// Delete a record by key
void delete_record(RecordStore* store, int key) {
    unsigned int index = hash(key, store->table_size);
    Record *current = store->table[index], *prev = NULL;
    while (current) {
        if (current->key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                store->table[index] = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Iterate over all records
void iterate_records(RecordStore* store, void (*func)(int key, long offset, double timestamp)) {
    for (size_t i = 0; i < store->table_size; ++i) {
        Record* current = store->table[i];
        while (current) {
            func(current->key, current->offset, current->timestamp);
            current = current->next;
        }
    }
}

// Update the timestamp range
void update_timestamp_range(RecordStore* store, double min_timestamp, double max_timestamp) {
    store->min_timestamp = min_timestamp;
    store->max_timestamp = max_timestamp;
}

// Free all resources used by the record store
void free_record_store(RecordStore* store) {
    for (size_t i = 0; i < store->table_size; ++i) {
        Record* current = store->table[i];
        while (current) {
            Record* to_delete = current;
            current = current->next;
            free(to_delete);
        }
    }
    free(store->table);
}

// Example usage
void print_record(int key, long offset, double timestamp) {
    printf("Key: %d, Offset: %ld, Timestamp: %.2f\n", key, offset, timestamp);
}

int main() {
    RecordStore store;
    init_record_store(&store, TABLE_SIZE);

    insert_record(&store, 1, 100, 1625155200.0);
    insert_record(&store, 2, 200, 1625241600.0);

    Record* record = get_record(&store, 1);
    if (record) {
        printf("Retrieved: Key: %d, Offset: %ld, Timestamp: %.2f\n", record->key, record->offset, record->timestamp);
    }

    update_record_timestamp(&store, 1, 1625328000.0);

    delete_record(&store, 2);

    iterate_records(&store, print_record);

    free_record_store(&store);
    return 0;
}
```

This implementation uses a hash table with chaining to handle collisions and supports insertion, retrieval, updating, deletion, iteration, and timestamp range updates efficiently. It is designed for scalability and low memory footprint while maintaining fast access times.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    float value;
} Record;

// Function prototypes
void manage_memory_and_initialize_records(const char *filename, size_t num_records);
void cleanup(Record **records_array, size_t num_records, long *offsets, int *keys, float *values);
int validate_record_integrity(Record *record);

void manage_memory_and_initialize_records(const char *filename, size_t num_records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Allocate memory for offset, key, and value arrays
    long *offsets = aligned_alloc(alignof(long), num_records * sizeof(long));
    int *keys = aligned_alloc(alignof(int), num_records * sizeof(int));
    float *values = aligned_alloc(alignof(float), num_records * sizeof(float));

    if (!offsets || !keys || !values) {
        perror("Memory allocation failed");
        cleanup(NULL, num_records, offsets, keys, values);
        return;
    }

    // Initialize arrays by reading from the file
    size_t chunk_size = 1024; // Adjust this based on performance testing
    size_t total_read = 0;

    while (total_read < num_records) {
        size_t to_read = (num_records - total_read > chunk_size / (sizeof(long) + sizeof(int) + sizeof(float))) ?
                         chunk_size / (sizeof(long) + sizeof(int) + sizeof(float)) : num_records - total_read;

        for (size_t i = 0; i < to_read; ++i) {
            if (fread(&offsets[total_read + i], sizeof(long), 1, file) != 1 ||
                fread(&keys[total_read + i], sizeof(int), 1, file) != 1 ||
                fread(&values[total_read + i], sizeof(float), 1, file) != 1) {
                fprintf(stderr, "Failed to read record at index %zu\n", total_read + i);
                cleanup(NULL, num_records, offsets, keys, values);
                fclose(file);
                return;
            }
        }

        total_read += to_read;
    }

    if (ferror(file)) {
        perror("Error reading file");
        cleanup(NULL, num_records, offsets, keys, values);
        fclose(file);
        return;
    }

    // Allocate memory for the array of record pointers
    Record **records_array = malloc(num_records * sizeof(Record *));
    if (!records_array) {
        perror("Memory allocation failed");
        cleanup(NULL, num_records, offsets, keys, values);
        fclose(file);
        return;
    }

    srand((unsigned int)time(NULL)); // Seed for random number generation

    // Populate the record structures
    for (size_t i = 0; i < num_records; ++i) {
        records_array[i] = malloc(sizeof(Record));
        if (!records_array[i]) {
            perror("Memory allocation failed");
            cleanup(records_array, i, offsets, keys, values);
            fclose(file);
            return;
        }

        records_array[i]->offset = offsets[i];
        records_array[i]->key = keys[i];
        records_array[i]->value = (float)rand() / RAND_MAX * 100.0f; // Random value between 0 and 100

        if (!validate_record_integrity(records_array[i])) {
            fprintf(stderr, "Record validation failed at index %zu\n", i);
            cleanup(records_array, num_records, offsets, keys, values);
            fclose(file);
            return;
        }
    }

    // Cleanup
    cleanup(records_array, num_records, offsets, keys, values);
    fclose(file);

    // Output for demonstration purposes (not part of the requirements)
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: Offset=%ld, Key=%d, Value=%.2f\n", i, records_array[i]->offset, records_array[i]->key, records_array[i]->value);
    }
}

void cleanup(Record **records_array, size_t num_records, long *offsets, int *keys, float *values) {
    for (size_t i = 0; i < num_records && records_array[i]; ++i) {
        free(records_array[i]);
    }
    free(records_array);
    free(offsets);
    free(keys);
    free(values);
}

int validate_record_integrity(Record *record) {
    // Simple validation: check if values are within reasonable bounds
    return record->offset >= 0 && record->key >= 0 && record->value >= 0.0f && record->value <= 100.0f;
}
