#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_LINES 10000
#define MAX_RECORDS 7000
#define INT_RANGE -100
#define INT_MAX_VALUE 100

typedef enum { UNINITIALIZED, VALID, INVALID } Status;

typedef struct {
    int *value;
    char valid;
    Status status;
} Record;

Record records[MAX_RECORDS];
int allocated_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log_event(const char *event) {
    FILE *log_file = fopen("memory_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), event);
        fclose(log_file);
    }
}

// Function to allocate memory for a record
int allocate_record(int key) {
    pthread_mutex_lock(&lock);

    if (allocated_records >= MAX_RECORDS) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    int value = rand() % (INT_MAX_VALUE - INT_RANGE + 1) + INT_RANGE;
    for (int i = 0; i < allocated_records; ++i) {
        if (*records[i].value == value) {
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    records[allocated_records].value = malloc(sizeof(int));
    *records[allocated_records].value = value;
    records[allocated_records].valid = 0;
    records[allocated_records].status = UNINITIALIZED;

    char log_buffer[100];
    snprintf(log_buffer, sizeof(log_buffer), "Allocated memory for key %d: size %lu", key, sizeof(int));
    log_event(log_buffer);

    allocated_records++;
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to free all allocated records
void free_all_records() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < allocated_records; ++i) {
        if (records[i].value) {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Freed memory for key %d: size %lu", i, sizeof(int));
            log_event(log_buffer);
            free(records[i].value);
        }
    }

    allocated_records = 0;
    pthread_mutex_unlock(&lock);
}

// DNS resolution function
int resolve_dns(const char *hostname) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return -1;
    }

    addr_list = (struct in_addr **) he->h_addr_list;
    for(int i = 0; addr_list[i] != NULL; i++) {
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, addr_list[i], ipstr, sizeof(ipstr));
        printf("Resolved IP: %s\n", ipstr);
    }
    return 0;
}

// Function to process log lines
void process_log_line(const char *line) {
    int num_fields = 0;
    int sum = 0, count = 0;

    char *token = strtok(line, " ");
    while (token != NULL) {
        char *endptr;
        long value = strtol(token, &endptr, 10);
        if (*endptr == '\0' && value >= INT_RANGE && value <= INT_MAX_VALUE) {
            sum += value;
            count++;
        }
        num_fields++;
        token = strtok(NULL, " ");
    }

    if (num_fields >= 2) {
        float average = (count > 0) ? (float)sum / count : 0.0;
        printf("Average: %.2f\n", average);
    } else {
        printf("Invalid line format.\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        process_log_line(line);

        // Simulate DNS resolution for domain names in the line
        resolve_dns("example.com");
    }

    free_all_records();
    fclose(file);

    if (line)
        free(line);

    return EXIT_SUCCESS;
}
```

### Design Decisions:
- **Memory Management**: A simple array-based memory pool is used to manage records. This approach minimizes fragmentation and simplifies allocation/deallocation.
- **Synchronization**: A mutex lock ensures thread safety during record allocation and deallocation, preventing race conditions.
- **Logging**: Logs are written to a file with timestamps for each allocation and deallocation event. This provides traceability without significantly impacting performance.
- **DNS Resolution**: Uses `gethostbyname` for DNS resolution, with caching not implemented due to simplicity. Consider parallel resolution or caching in a more complex system.
- **Error Handling**: Graceful handling of errors such as file opening failures and invalid lines.

This program balances efficiency, maintainability, and scalability while ensuring accurate processing of log files.']

