typedef enum {
    ACTIVE,
    INACTIVE
} SessionState;

typedef struct {
    int UserID;
    time_t LastAccessTime;
    SessionState SessionState;
    int ActiveDeviceCount;
} UserSession;

#define SESSION_EXPIRY_TIME 86400 // 24 hours in seconds

// Define a structure for managing sessions
typedef struct {
    UserSession **sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

// Function prototypes
void init_session_manager(SessionManager *manager, size_t initial_capacity);
void add_user_session(SessionManager *manager, int user_id);
void update_user_session(SessionManager *manager, int user_id, time_t last_access_time, int active_device_count);
int get_active_sessions_for_user(SessionManager *manager, int user_id);
int get_active_sessions_for_device_type(SessionManager *manager, const char *device_type);
void delete_inactive_sessions(SessionManager *manager);

// Initialize the session manager
void init_session_manager(SessionManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->sessions = malloc(initial_capacity * sizeof(UserSession *));
    if (!manager->sessions) exit(EXIT_FAILURE); // Handle allocation failure
    manager->count = 0;
    manager->capacity = initial_capacity;
}

// Add a new user session or update an existing one
void add_user_session(SessionManager *manager, int user_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->UserID == user_id) {
            time(&manager->sessions[i]->LastAccessTime);
            manager->sessions[i]->SessionState = ACTIVE;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Resize array if needed
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession **new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession *));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE); // Handle allocation failure
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    UserSession *session = malloc(sizeof(UserSession));
    if (!session) {
        pthread_mutex_unlock(&manager->lock);
        exit(EXIT_FAILURE); // Handle allocation failure
    }

    session->UserID = user_id;
    time(&session->LastAccessTime);
    session->SessionState = ACTIVE;
    session->ActiveDeviceCount = 1;

    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->lock);
}

// Update an existing user session
void update_user_session(SessionManager *manager, int user_id, time_t last_access_time, int active_device_count) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->UserID == user_id) {
            manager->sessions[i]->LastAccessTime = last_access_time;
            manager->sessions[i]->ActiveDeviceCount = active_device_count;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Get the number of active sessions for a specific user
int get_active_sessions_for_user(SessionManager *manager, int user_id) {
    int count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->UserID == user_id && manager->sessions[i]->SessionState == ACTIVE) {
            ++count;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return count;
}

// Placeholder function for device type session count
int get_active_sessions_for_device_type(SessionManager *manager, const char *device_type) {
    // Implement logic based on actual requirements and available data
    (void)device_type;  // Unused parameter
    pthread_mutex_lock(&manager->lock);

    int count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->SessionState == ACTIVE) {
            // Placeholder condition to match device type
            ++count;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return count;
}

// Delete sessions inactive for more than 24 hours
void delete_inactive_sessions(SessionManager *manager) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    size_t i = 0;
    while (i < manager->count) {
        if (now - manager->sessions[i]->LastAccessTime > SESSION_EXPIRY_TIME && manager->sessions[i]->SessionState == ACTIVE) {
            free(manager->sessions[i]);
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(UserSession *));
            --manager->count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Free resources
void free_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}
