```python
import asyncio
from concurrent.futures import ThreadPoolExecutor
import uuid
import hashlib
import random
import string
import logging
from aiohttp import web
import threading
from functools import wraps

# Set up logging
logging.basicConfig(level=logging.INFO)

class UserProfile:
    def __init__(self, name, email, password_hash, settings):
        self.profile_id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self.password_hash = password_hash
        self.settings = settings

class ProfileManager:
    def __init__(self, initial_capacity=1000):
        self.profiles = {}
        self.lock = threading.Lock()

    async def initialize_profiles(self, count):
        loop = asyncio.get_event_loop()
        with ThreadPoolExecutor() as pool:
            tasks = [
                loop.run_in_executor(pool, self._create_profile)
                for _ in range(count)
            ]
            await asyncio.gather(*tasks)

    def _create_profile(self):
        name = ''.join(random.choices(string.ascii_letters, k=8))
        email = f"{name}@example.com"
        password_hash = hashlib.sha256('password'.encode()).hexdigest()
        settings = {
            'privacy_level': random.choice(['public', 'private']),
            'notifications': random.choice([True, False]),
        }

        with self.lock:
            profile = UserProfile(name, email, password_hash, settings)
            if profile.profile_id not in self.profiles:
                self.profiles[profile.profile_id] = profile
                logging.info(f"Profile {profile.profile_id} created.")

    def get_profile(self, profile_id):
        with self.lock:
            return self.profiles.get(profile_id)

    def update_profile(self, profile_id, updates):
        with self.lock:
            if profile_id in self.profiles:
                for key, value in updates.items():
                    setattr(self.profiles[profile_id], key, value)

    async def handle_large_scale_reconfigurations(self, profiles):
        loop = asyncio.get_event_loop()
        with ThreadPoolExecutor() as pool:
            tasks = [
                loop.run_in_executor(pool, self.update_profile, profile['id'], profile['updates'])
                for profile in profiles
            ]
            await asyncio.gather(*tasks)

# RESTful API
def rate_limit(func):
    @wraps(func)
    async def wrapper(request, *args, **kwargs):
        # Implement rate-limiting logic here
        return await func(request, *args, **kwargs)
    return wrapper

app = web.Application()
manager = ProfileManager()

@app.route('/profile/{profile_id}', methods=['GET'])
@rate_limit
async def get_profile(request):
    profile_id = request.match_info['profile_id']
    profile = manager.get_profile(profile_id)
    if profile:
        return web.json_response({
            'profile_id': profile.profile_id,
            'name': profile.name,
            'email': profile.email,
            'settings': profile.settings
        })
    else:
        return web.Response(status=404)

@app.route('/profile/{profile_id}', methods=['POST'])
@rate_limit
async def update_profile(request):
    profile_id = request.match_info['profile_id']
    updates = await request.json()
    manager.update_profile(profile_id, updates)
    return web.Response(status=204)

if __name__ == '__main__':
    loop = asyncio.get_event_loop()
    loop.run_until_complete(manager.initialize_profiles(1000))
    web.run_app(app, port=8080)
```

