#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <stdatomic.h>
#include <stdbool.h>

// Assume external libraries for logging and data source are available.
#include "external_logging_lib.h"
#include "data_source_lib.h"

#define INITIAL_CAPACITY 10
#define MAX_VERSIONS 5

typedef struct Entry {
    short field1;
    int field2;
    float field3;
    time_t timestamp;
    uint64_t unique_id;
    struct Entry *next;
    _Atomic int version_count;
} Entry;

typedef struct Collection {
    Entry *head;
    size_t capacity;
    pthread_mutex_t lock; // Use mutex for critical sections
    atomic_uintptr_t tail; // Lock-free access to the last element
} Collection;

// Function prototypes
void init_collection(Collection *collection);
Entry* create_entry(uint64_t unique_id, Entry **next_ptr);
void free_collection(Collection *collection);
void add_entry(Collection *collection, uint64_t unique_id);
void log_change(const char *message, const Entry *entry);
void save_state_to_disk(Collection *collection);
void compact_memory(Collection *collection);

// Initialize the collection
void init_collection(Collection *collection) {
    collection->head = NULL;
    collection->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&collection->lock, NULL);
    atomic_store(&collection->tail, (uintptr_t)NULL);
}

// Create a new entry with random values and unique ID
Entry* create_entry(uint64_t unique_id, Entry **next_ptr) {
    Entry *entry = malloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->field1 = rand() % 100; // Example short value
    entry->field2 = rand() % 1000 + 1; // Random int in range [1, 1000]
    entry->field3 = (float)(rand() / (RAND_MAX + 1.0)); // Random float [0.0, 1.0)
    entry->timestamp = time(NULL);
    entry->unique_id = unique_id;
    entry->next = NULL;
    atomic_store(&entry->version_count, 1);

    if (*next_ptr) {
        entry->next = *next_ptr;
    }
    *next_ptr = entry;

    return entry;
}

// Add an entry to the collection
void add_entry(Collection *collection, uint64_t unique_id) {
    pthread_mutex_lock(&collection->lock);

    Entry **current = &collection->head;
    while (*current) {
        current = &(*current)->next;
    }
    *current = create_entry(unique_id, NULL);

    log_change("Added entry", *current);
    pthread_mutex_unlock(&collection->lock);
}

// Log changes to entries
void log_change(const char *message, const Entry *entry) {
    // Use external logging library
    external_log("%s: ID=%llu at %ld\n", message, entry->unique_id, entry->timestamp);
}

// Save the current state of the collection to disk
void save_state_to_disk(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    // Serialize and write to disk logic here

    pthread_mutex_unlock(&collection->lock);
}

// Compact memory in a background thread
void compact_memory(Collection *collection) {
    while (true) {
        sleep(60); // Run every minute

        pthread_mutex_lock(&collection->lock);

        // Memory compaction logic here

        pthread_mutex_unlock(&collection->lock);
    }
}

// Free the collection and its entries
void free_collection(Collection *collection) {
    Entry *current = collection->head;
    while (current) {
        Entry *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    Collection collection;
    init_collection(&collection);

    // Example usage
    add_entry(&collection, 1);
    save_state_to_disk(&collection);

    // Start background thread for memory compaction
    pthread_t compact_thread;
    pthread_create(&compact_thread, NULL, (void *(*)(void *))compact_memory, &collection);

    // Simulate workload
    for (int i = 0; i < 100; ++i) {
        add_entry(&collection, i + 2);
    }

    pthread_join(compact_thread, NULL);

    free_collection(&collection);
    return 0;
}
```

