trusted_host_t whitelist[MAX_HOSTS];
int trusted_hosts_count = 0;
pthread_mutex_t whitelist_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to load the whitelist from a file
void load_trusted_hosts() {
    FILE *file = fopen(WHITELIST_FILE, "r");
    if (!file) return;

    while (fscanf(file, "%255s", whitelist[trusted_hosts_count].hostname) == 1) {
        trusted_hosts_count++;
        if (trusted_hosts_count >= MAX_HOSTS) break;
    }
    fclose(file);
}

// Function to perform DNS resolution and validate against the whitelist
dns_result_t resolve_and_validate(const char *hostname) {
    dns_result_t result = {{0}, 0};
    struct addrinfo hints, *res, *p;
    int gai_error;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((gai_error = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        result.error_code = gai_error;
        return result;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        char host[256];
        if (getnameinfo(p->ai_addr, p->ai_addrlen, host, sizeof(host), NULL, 0, NI_NAMEREQD) == 0) {
            pthread_mutex_lock(&whitelist_lock);
            for (int i = 0; i < trusted_hosts_count; i++) {
                if (strcmp(whitelist[i].hostname, host) == 0) {
                    memcpy(result.ip_address, p->ai_addr, p->ai_addrlen);
                    pthread_mutex_unlock(&whitelist_lock);
                    freeaddrinfo(res);
                    return result;
                }
            }
            pthread_mutex_unlock(&whitelist_lock);
        }
    }

    freeaddrinfo(res);
    result.error_code = ENXIO; // No such host entry in the whitelist
    return result;
}

// Function to process log entries from a source
void *process_log_source(void *arg) {
    FILE *log_file = (FILE *)arg;

    char buffer[LOG_BUFFER_SIZE];
    while (fgets(buffer, sizeof(buffer), log_file)) {
        // Parse log entry here (simplified for brevity)
        log_entry_t entry;
        sscanf(buffer, "%*d/%*d:%*d %9[^ ] %255[^ ] %d %15[^\n]",
               entry.method, entry.uri, &entry.status_code, entry.client_ip);

        // Validate client IP address
        dns_result_t result = resolve_and_validate(entry.client_ip);
        if (result.error_code) {
            fprintf(stderr, "Invalid or untrusted host: %s\n", entry.client_ip);
            continue;
        }

        // Further processing like calculating average response time can be added here

        free(buffer); // Simulate memory management
    }
    fclose(log_file);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log file1> [<log file2> ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    load_trusted_hosts();

    int num_threads = argc - 1;
    pthread_t threads[num_threads];
    FILE *files[num_threads];

    for (int i = 0; i < num_threads; i++) {
        files[i] = fopen(argv[i + 1], "r");
        if (!files[i]) {
            fprintf(stderr, "Error opening file: %s\n", argv[i + 1]);
            continue;
        }
        pthread_create(&threads[i], NULL, process_log_source, (void *)files[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        if (files[i]) {
            pthread_join(threads[i], NULL);
            fclose(files[i]);
        }
    }

    return 0;
}
