#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DEVICES 1000
#define INITIAL_CAPACITY 10
#define TIME_THRESHOLD 3600 // seconds

typedef struct {
    char mac_address[18];
    float temperature;
    int humidity;
    int battery_level;
    time_t last_update;
} Device;

typedef struct {
    Device *devices;
    size_t capacity;
    size_t count;
    unsigned long seed;
    size_t disconnection_threshold; // in seconds
} NetworkManager;

void initialize_mac_address(char *mac, unsigned long seed) {
    srand(seed);
    sprintf(mac, "%02x:%02x:%02x:%02x:%02x:%02x",
            rand() % 256,
            rand() % 256,
            rand() % 256,
            rand() % 256,
            rand() % 256,
            rand() % 256);
}

void initialize_device(Device *device, unsigned long seed) {
    initialize_mac_address(device->mac_address, seed++);
    device->temperature = (float)(rand() % 100);
    device->humidity = rand() % 101;
    device->battery_level = 100;
    device->last_update = time(NULL);
}

void resize_network_manager(NetworkManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Device *new_devices = realloc(manager->devices, new_capacity * sizeof(Device));
    if (new_devices) {
        manager->devices = new_devices;
        manager->capacity = new_capacity;
    }
}

void add_device(NetworkManager *manager) {
    if (manager->count >= manager->capacity) {
        resize_network_manager(manager);
    }
    initialize_device(&manager->devices[manager->count++], manager->seed++);
}

void update_device(NetworkManager *manager, size_t index) {
    if (index < manager->count) {
        Device *device = &manager->devices[index];
        device->temperature += 0.1f; // Simulate change
        device->humidity += 1;
        device->battery_level -= 1;
        device->last_update = time(NULL);

        printf("Updated MAC: %s, Temp: %.2f, Humidity: %d, Battery: %d%%\n",
               device->mac_address,
               device->temperature,
               device->humidity,
               device->battery_level);
    }
}

void process_updates(NetworkManager *manager) {
    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count; ++i) {
        Device *device = &manager->devices[i];

        if (difftime(now, device->last_update) > manager->disconnection_threshold) {
            printf("Device %s is offline.\n", device->mac_address);
            continue;
        }

        update_device(manager, i);
    }
}

void garbage_collect(NetworkManager *manager) {
    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count;) {
        Device *device = &manager->devices[i];

        if (difftime(now, device->last_update) > manager->disconnection_threshold ||
            device->battery_level <= 0) {

            printf("Garbage collecting MAC: %s\n", device->mac_address);
            memmove(&manager->devices[i], &manager->devices[i + 1],
                    (manager->count - i - 1) * sizeof(Device));
            manager->count--;
        } else {
            ++i;
        }
    }
}

void iterate_devices(NetworkManager *manager, int reverse) {
    size_t start = 0;
    size_t end = manager->count;
    if (reverse) {
        for (size_t i = end; i > start; --i) {
            printf("Device MAC: %s\n", manager->devices[i - 1].mac_address);
        }
    } else {
        for (size_t i = start; i < end; ++i) {
            printf("Device MAC: %s\n", manager->devices[i].mac_address);
        }
    }
}

void initialize_network_manager(NetworkManager *manager, unsigned long seed,
                                size_t disconnection_threshold) {
    manager->devices = malloc(INITIAL_CAPACITY * sizeof(Device));
    if (!manager->devices) exit(EXIT_FAILURE);

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->seed = seed;
    manager->disconnection_threshold = disconnection_threshold;

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        add_device(manager);
    }
}

void free_network_manager(NetworkManager *manager) {
    free(manager->devices);
}

int main() {
    NetworkManager manager;
    initialize_network_manager(&manager, 12345, TIME_THRESHOLD);

    process_updates(&manager);
    garbage_collect(&manager);
    iterate_devices(&manager, 0);

    free_network_manager(&manager);
    return 0;
}
