    int *keys = malloc(size * sizeof(int));

    LinkedList list;
    pthread_mutex_init(&list.lock, NULL);
    list.head = NULL;

    initializeOffsetsAndKeys(offsets, keys, size, 0, 100);  // Example range
    populateRecords(&list, 9);  // For nine records

    free(offsets);
    free(keys);

    // Clean up linked list resources
    pthread_mutex_lock(&list.lock);
    struct Record *current = list.head;
    while (current) {
        Metadata *metadata = current->metadata;
        if (metadata && metadata->data)
            free(metadata->data);
        free(metadata);

        struct Record *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list.lock);
    pthread_mutex_destroy(&list.lock);
}

void initializeOffsetsAndKeys(long **offsets, int **keys, int size, int keyRangeMin, int keyRangeMax) {
    for (int i = 0; i < size; ++i) {
        (*keys)[i] = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        if (i > 0)
            (*offsets)[i] = (*offsets)[i-1] + (*keys)[i] + 10; // Constant value
    }
}

void populateRecords(LinkedList *list, int recordCount) {
    pthread_mutex_lock(&list.lock);

    for (int i = 0; i < recordCount; ++i) {
        struct Record *newRecord = malloc(sizeof(struct Record));

        newRecord->sValue = rand() % 32768;
        newRecord->iValue = rand();
        newRecord->fValue = (float)(rand()) / RAND_MAX;
        newRecord->timestamp = rand();

