        newRecord->statusIndicator = STATUS_OK;  // Simplified for demo purposes
        newRecord->priorityLevel = "LMH"[rand() % 3];  // 'L', 'M' or 'H'
        newRecord->sourceIdentifier = 'A' + (rand() % 26);  // Random ASCII char

        newRecord->next = list->head;
        if (list->head != NULL)
            list->head->prev = newRecord;

        newRecord->prev = NULL;
        list->head = newRecord;
    }

    pthread_mutex_unlock(&list.lock);
}

int main() {
    initializeMemoryPools();
    allocateCollections(9);  // Example size for nine records

    return 0;
