#include <time.h>

#define MAX_RECORDS 100000

typedef struct {
    int value;
    long offset;
    int key;
    double metric;
} Record;

typedef struct MemoryBlock {
    size_t size;
    void *memory;
    struct MemoryBlock *next;
} MemoryBlock;

typedef struct {
    MemoryBlock *head;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
} DataStore;

// Function declarations
void initializeMemoryPool(MemoryPool *pool, size_t initialSize);
void* allocateFromPool(MemoryPool *pool, size_t size);
void freeToPool(MemoryPool *pool, void *ptr);

void initializeDataStore(DataStore *store, size_t capacity);
Record* createRecord(int value, long offset, int key, double metric);
void insertRecord(DataStore *store, Record *record);
void processRecordsConcurrently(DataStore *store);

double computePolynomialMetric(int value, long offset) {
    // Example polynomial function
    return (value * 0.5 + offset * 0.01);
}

// Memory pool management functions
void initializeMemoryPool(MemoryPool *pool, size_t initialSize) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < initialSize; ++i) {
        void *memory = malloc(sizeof(Record));
        if (!memory) exit(EXIT_FAILURE);

        MemoryBlock *block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
        block->size = sizeof(Record);
        block->memory = memory;
        block->next = pool->head;
        pool->head = block;
    }
}

void* allocateFromPool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryBlock *prev = NULL;
    for (MemoryBlock *block = pool->head; block != NULL; prev = block, block = block->next) {
        if (block->size >= size) {
            void *memory = block->memory;
            if (prev) {
                prev->next = block->next;
            } else {
                pool->head = block->next;
            }
            free(block);
            pthread_mutex_unlock(&pool->lock);
            return memory;
        }
    }

    // If no suitable block is found, allocate new
    void *memory = malloc(size);
    if (!memory) exit(EXIT_FAILURE);

    pthread_mutex_unlock(&pool->lock);
    return memory;
}

void freeToPool(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);

    MemoryBlock *block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    block->size = sizeof(Record); // Assuming records only for simplicity
    block->memory = ptr;
    block->next = pool->head;
    pool->head = block;

    pthread_mutex_unlock(&pool->lock);
}

// Data store functions
void initializeDataStore(DataStore *store, size_t capacity) {
    store->records = (Record**)malloc(capacity * sizeof(Record*));
    if (!store->records) exit(EXIT_FAILURE);

    store->capacity = capacity;
    store->count = 0;

    pthread_rwlock_init(&store->rwlock, NULL);
}

Record* createRecord(int value, long offset, int key, double metric) {
    Record *record = (Record*)allocateFromPool(&globalMemoryPool, sizeof(Record));
    record->value = value;
    record->offset = offset;
    record->key = key;
    record->metric = metric ? metric : computePolynomialMetric(value, offset);
    return record;
}

void insertRecord(DataStore *store, Record *record) {
    pthread_rwlock_wrlock(&store->rwlock);

    if (store->count >= store->capacity) {
        // Handle resizing or reject insertion
    }

    store->records[store->count++] = record;

    pthread_rwlock_unlock(&store->rwlock);
}

void processRecordsConcurrently(DataStore *store) {
    size_t numThreads = 4; // Example thread count

    pthread_t threads[numThreads];

    for (size_t i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, (void*)processRecordsThread, store)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example function to simulate processing
void* processRecordsThread(void *arg) {
    DataStore *store = (DataStore*)arg;

    pthread_rwlock_rdlock(&store->rwlock);

    for (size_t i = 0; i < store->count; ++i) {
        Record *record = store->records[i];
        // Process record
    }

    pthread_rwlock_unlock(&store->rwlock);
    return NULL;
}

int main() {
    MemoryPool globalMemoryPool;
    DataStore dataStore;

    initializeMemoryPool(&globalMemoryPool, 1024);
    initializeDataStore(&dataStore, MAX_RECORDS);

    // Simulate adding records
    for (int i = 0; i < 100000; ++i) {
        Record *record = createRecord(i, i * 10, i % 256, 0);
        insertRecord(&dataStore, record);
    }

    processRecordsConcurrently(&dataStore);

    // Cleanup
    pthread_rwlock_destroy(&dataStore.rwlock);
    free(dataStore.records);
    while (globalMemoryPool.head) {
        MemoryBlock *block = globalMemoryPool.head;
        globalMemoryPool.head = block->next;
        free(block->memory);
        free(block);
    }

    return 0;
}
