    Task *task = (Task*)custom_alloc(sizeof(Task));
    task->name = strdup(name);

    // Initialize fields with random values
    srand(time(NULL) + (uintptr_t)task);
    for (int i = 0; i < 10; ++i) {
        dynamic_content[i] = ((float)rand() / RAND_MAX) * 100.0;
        task->dynamic_content[i] = dynamic_content[i];
        task->key[i] = rand() % 200 - 100; // Range [-100, 99]
    }

    for (int i = 1; i <= 10; ++i) {
        task->offset[i] = task->offset[i-1] + task->key[i-1] + METADATA_CONSTANT;
    }

    task->priority = priority_base + rand() % 5 - 2; // Adjust with dynamic factor
    gettimeofday((struct timeval *)&task->start_time, NULL);
    task->status = STATUS_PENDING;

    // Compute metadata hash (simple example)
    uint32_t hash = 0;
    for (int i = 0; i < 10 && i < strlen(name); ++i) {
        hash = (hash * 31) + name[i];
    }
    task->metadata = hash ^ ((uint32_t)task);

    // Assign event handler
    task->event_handler = event_handler;

    return task;
}

void insert_task(TaskList *list, Task *new_task) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        // Handle reallocation
        list->head = (Node*)custom_alloc(new_capacity * sizeof(Node));
        memcpy(list->head, &((struct { Node head[INITIAL_CAPACITY]; }){.head[0] = { .task = new_task }}).head[0], 
               list->count * sizeof(Node));
        custom_free(&list->head[-1]);
        list->capacity = new_capacity;
    }

    Node *new_node = (Node*)custom_alloc(sizeof(Node));
    new_node->task = new_task;
    new_node->next = list->head;
    list->head = new_node;
    ++list->count;

    pthread_rwlock_unlock(&list->rwlock);
}

void release_tasks(TaskList *list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        custom_free(current->task->name);
        custom_free(current->task);
        custom_free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);

    pthread_rwlock_destroy(&list->rwlock);
}

void initialize_task_list(TaskList *list) {
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_rwlock_init(&list->rwlock, NULL);
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->condvar, NULL);
}

// Sample event handler
void sample_event_handler(void) {
    printf("Event handled!\n");
}

int main() {
    TaskList task_list;
    initialize_task_list(&task_list);

    // Create and insert tasks with dynamic content
    float content[10] = {0};
    for (int i = 0; i < 15; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "Task_%d", i);
        Task *task = create_task(name, 5, content, sample_event_handler);
        insert_task(&task_list, task);
    }

    release_tasks(&task_list);

    return 0;
}
```

This code provides a basic implementation of managing tasks in a dynamic collection with custom memory allocation and thread safety. It includes functions for creating tasks with random values, inserting them into the list, releasing resources, and initializing the list structure with locks for concurrency management. Further enhancements would be required to fully satisfy all specific requirements such as cache mechanisms or complete handling of distributed systems intricacies.']

