// Define structures
typedef struct record {
    short field1;
    int field2;
    float field3;
    int timestamp;
    char *metadata;
} record_t;

typedef struct Node {
    record_t data;
    struct Node* prev;
    struct Node* next;
} Node;

// Thread-safe doubly linked list
typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* lst = malloc(sizeof(List));
    lst->head = NULL;
    lst->tail = NULL;
    pthread_mutex_init(&lst->lock, NULL);
    return lst;
}

void insert_record(List* lst, record_t data) {
    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&lst->lock);

    if (lst->head == NULL) {
        lst->head = lst->tail = new_node;
    } else {
        lst->tail->next = new_node;
        new_node->prev = lst->tail;
        lst->tail = new_node;
    }

    pthread_mutex_unlock(&lst->lock);
}

Node* iterate_list(List* lst, int index) {
    Node* current = lst->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    return current;
}

