        // Implement resizing or allocation failure handling
        return NULL;
    }
    void* block = (char*)pool->start + pool->offset;
    pool->offset += size;
    return block;
}

// Function to manage memory and initialize data structures
void dynamic_memory_management(int range_min, int range_max, int constant_offset) {
    MemoryPool* pool = create_memory_pool(POOL_SIZE);

    // Define arrays
    long* offsets = (long*)allocate_from_pool(pool, 5 * sizeof(long));
    int* keys = (int*)allocate_from_pool(pool, 5 * sizeof(int));
    record_t* records = (record_t*)allocate_from_pool(pool, 5 * sizeof(record_t));
    int* timestamps = (int*)allocate_from_pool(pool, 5 * sizeof(int));
    char** metadata = (char**)allocate_from_pool(pool, 5 * sizeof(char*));

    // Initialize random seed
    srand(time(NULL));

    long sum_keys = 0;
    for (int i = 0; i < 5; ++i) {
        keys[i] = rand() % (range_max - range_min + 1) + range_min;

        if (keys[i] <= 0) { // Validation mechanism
            fprintf(stderr, "Key generation failed.\n");
            exit(EXIT_FAILURE);
        }

        sum_keys += keys[i];
        offsets[i] = sum_keys + constant_offset;
    }

    List* record_list = create_list();

    for (int i = 0; i < 5; ++i) {
        records[i].field1 = rand() % 32767;
        records[i].field2 = rand();
        records[i].field3 = (float)rand() / RAND_MAX * 100.0;

        timestamps[i] = rand();

        metadata[i] = (char*)allocate_from_pool(pool, 20);
        snprintf(metadata[i], 20, "Meta_%d", i);

        records[i].metadata = metadata[i];

        records[i].timestamp = timestamps[i];
        insert_record(record_list, records[i]);
    }

    // Example of iterating over the list
    for (int i = 0; i < 5; ++i) {
        Node* node = iterate_list(record_list, i);
        if (node != NULL) {
            printf("Record %d: (%hd, %d, %.2f, %d, %s)\n", i,
                   node->data.field1, node->data.field2, node->data.field3,
                   node->data.timestamp, node->data.metadata);
        }
    }

    // Cleanup (not shown)
}

int main() {
    dynamic_memory_management(1, 100, 10);
    return 0;
}
