#include <stdio.h>
#include <stdlib.h>
import string.h

typedef struct {
    float value;
    int index;
    char *description;
} data_point;

typedef struct {
    long* offsets;
    int* keys;
    float* values;
    data_point** points;
    size_t capacity;
    size_t count;
} data_collection;

data_collection* initialize_data_collection(size_t initial_capacity) {
    if (initial_capacity == 0) {
        return NULL;
    }

    data_collection* collection = malloc(sizeof(data_collection));
    if (!collection) {
        return NULL;
    }

    collection->offsets = calloc(initial_capacity, sizeof(long));
    collection->keys = calloc(initial_capacity, sizeof(int));
    collection->values = calloc(initial_capacity, sizeof(float));
    collection->points = calloc(initial_capacity, sizeof(data_point*));

    if (!(collection->offsets && collection->keys && collection->values && collection->points)) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->values);
        free(collection->points);
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void add_data_point(data_collection* collection, float value, int index, const char* description) {
    if (!collection || !description) {
        return;
    }

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;

        long* new_offsets = realloc(collection->offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(collection->keys, new_capacity * sizeof(int));
        float* new_values = realloc(collection->values, new_capacity * sizeof(float));
        data_point** new_points = realloc(collection->points, new_capacity * sizeof(data_point*));

        if (!(new_offsets && new_keys && new_values && new_points)) {
            free(new_offsets);
            free(new_keys);
            free(new_values);
            free(new_points);
            return;
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->values = new_values;
        collection->points = new_points;

        collection->capacity = new_capacity;
    }

    data_point* point = malloc(sizeof(data_point));
    if (!point) {
        return;
    }

    point->value = value;
    point->index = index;
    size_t desc_len = strlen(description) + 1; // +1 for null terminator
    point->description = malloc(desc_len);
    if (!point->description) {
        free(point);
        return;
    }
    strcpy(point->description, description);

    collection->points[collection->count] = point;
    collection->count++;
}

void cleanup_data_collection(data_collection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->points[i]->description);
            free(collection->points[i]);
        }

        free(collection->offsets);
        free(collection->keys);
        free(collection->values);
        free(collection->points);

        free(collection);
    }
}

int main() {
    data_collection* collection = initialize_data_collection(10);

    if (!collection) {
        fprintf(stderr, "Failed to initialize data collection\n");
        return EXIT_FAILURE;
    }

    add_data_point(collection, 3.14f, 1, "Sample description 1");
    add_data_point(collection, 2.71f, 2, "Sample description 2");

    // Example usage
    for (size_t i = 0; i < collection->count; ++i) {
        printf("Index: %d, Value: %.2f, Description: %s\n",
               collection->points[i]->index,
               collection->points[i]->value,
               collection->points[i]->description);
    }

    cleanup_data_collection(collection);

    return EXIT_SUCCESS;
}
