        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Min cannot be greater than Max");
        offsetMin = min;
        offsetMax = max;
        offsetRangeInitialized = true;
    }

    void InitializeKeyRange(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Min cannot be greater than Max");
        keyMin = min;
        keyMax = max;
        keyRangeInitialized = true;
    }

    void InitializeValueRange(float min, float max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Min cannot be greater than Max");
        valueMin = min;
        valueMax = max;
        valueRangeInitialized = true;
    }

