        if (!dataPointRangeInitialized || fixedString.size() > 9)
            throw std::runtime_error("Data point range not initialized or string too long");

        DataPoint dp;
        dp.floatValue = GetRandomFloat(valueMin, valueMax);
        dp.intValue = GetRandomInt(keyMin, keyMax);
        std::copy(fixedString.begin(), fixedString.end(), dp.charField);

        return dp;
    }

    void Log(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMtx);
        // Simple logging mechanism
        if (logLevel > 0) { // Assuming logLevel is set elsewhere
            std::cout << "[" << GetCurrentTime() << "] " << message << std::endl;
        }
