#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
} record_t;

typedef struct Node {
    record_t data;
    struct Node* next;
} node_t;

typedef struct LinkedList {
    node_t* head;
    pthread_mutex_t lock;
} linked_list_t;

typedef struct MemoryPool {
    size_t size;
    void* pool;
} memory_pool_t;

void* initialize_memory_pool(size_t size) {
    memory_pool_t* mem_pool = malloc(sizeof(memory_pool_t));
    if (!mem_pool) return NULL;

    mem_pool->size = size;
    mem_pool->pool = malloc(size);
    if (!mem_pool->pool) {
        free(mem_pool);
        return NULL;
    }

    return mem_pool;
}

void* allocate_from_pool(memory_pool_t* pool, size_t size) {
    if (pool->size < size) return NULL; // Simple check for pool exhaustion
    void* ptr = pool->pool;
    pool->pool += size;
    pool->size -= size;
    return ptr;
}

linked_list_t* create_linked_list() {
    linked_list_t* list = malloc(sizeof(linked_list_t));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

node_t* add_record_to_list(linked_list_t* list, record_t data) {
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return NULL;

    new_node->data = data;
    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    return new_node;
}

void manage_memory_and_initialize(size_t num_elements, int key_range_start, int key_range_end) {
    memory_pool_t* mem_pool = initialize_memory_pool(1024 * 1024); // 1MB pool
    if (!mem_pool) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return;
    }

    long* offset_array = allocate_from_pool(mem_pool, num_elements * sizeof(long));
    int* key_array = allocate_from_pool(mem_pool, num_elements * sizeof(int));

    linked_list_t* record_list = create_linked_list();
    if (!record_list) {
        fprintf(stderr, "Failed to create linked list.\n");
        return;
    }

    srand(time(NULL)); // Seed random number generator

    long offset_sum = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        key_array[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        offset_array[i] = offset_sum + key_array[i];
        offset_sum += key_array[i];

        record_t record;
        record.s = rand() % 100; // Short range example
        record.i = rand() % 1000; // Int range example
        record.f = (float)rand() / RAND_MAX; // Float range

        add_record_to_list(record_list, record);
    }

    // Here we could integrate logging and checkpointing mechanisms as required

    pthread_mutex_destroy(&record_list->lock);
    free(mem_pool->pool);
    free(mem_pool);
}

int main() {
    size_t num_elements = 1000;
    int key_range_start = 1;
    int key_range_end = 10;

    manage_memory_and_initialize(num_elements, key_range_start, key_range_end);

    return 0;
}
