#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    short s;
    int i;
    float f;
} record_t;

typedef struct node {
    record_t data;
    struct node* next;
} node_t;

typedef struct memory_pool {
    size_t size;
    void* pool;
} memory_pool_t;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
node_t* head = NULL;
int key_range_start = 0, key_range_end = 10000;
int current_key_index = 0;
memory_pool_t mem_pool = { .size = 1024 * 1024, .pool = NULL }; // Initial pool size of 1MB

// Function to initialize the memory pool
void init_memory_pool(memory_pool_t* mp, size_t size) {
    if (mp->pool) free(mp->pool);
    mp->size = size;
    mp->pool = malloc(size);
}

// Function to resize the memory pool
void resize_memory_pool(memory_pool_t* mp, size_t new_size) {
    void* new_pool = realloc(mp->pool, new_size);
    if (new_pool) {
        mp->pool = new_pool;
        mp->size = new_size;
    } else {
        fprintf(stderr, "Failed to resize memory pool\n");
    }
}

// Function to allocate a record from the memory pool
record_t* allocate_record(memory_pool_t* mp) {
    static void* cursor = NULL;

    if (cursor == NULL || ((char*)cursor - (char*)mp->pool + sizeof(record_t)) > mp->size) {
        resize_memory_pool(mp, mp->size * 2); // Double the size
        cursor = mp->pool;
    }

    record_t* record = (record_t*)cursor;
    cursor = (void*)((char*)cursor + sizeof(record_t));

    return record;
}

// Function to initialize arrays and linked list
int init_arrays_and_list(long** offsets, int** keys, node_t** head_node) {
    pthread_mutex_lock(&list_lock);

    size_t initial_size = 1000;
    *offsets = malloc(initial_size * sizeof(long));
    *keys = malloc(initial_size * sizeof(int));

    if (!*offsets || !*keys) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    srand(time(NULL)); // Seed random number generator

    long offset_sum = 0;
    for (size_t i = 0; i < initial_size; ++i) {
        (*keys)[i] = key_range_start + (current_key_index % (key_range_end - key_range_start));
        current_key_index++;
        if (current_key_index > key_range_end) {
            // Handle key range exhaustion
            current_key_index = key_range_start;
        }
        offset_sum += (*keys)[i];
        (*offsets)[i] = offset_sum + i * 100; // Example constant

        record_t* rec = allocate_record(&mem_pool);
        rec->s = rand() % 32768;
        rec->i = rand() % 2147483647;
        rec->f = (float)rand() / RAND_MAX;

        node_t* new_node = (node_t*)malloc(sizeof(node_t));
        if (!new_node) {
            fprintf(stderr, "Memory allocation for linked list failed\n");
            pthread_mutex_unlock(&list_lock);
            return -1;
        }
        new_node->data = *rec;
        new_node->next = (*head_node);

        *head_node = new_node;
    }

    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Function to dynamically resize arrays
int resize_arrays(long** offsets, int** keys) {
    pthread_mutex_lock(&list_lock);

