use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use crossbeam_queue::SegQueue;
use rand::Rng;
use time::{self, Tm};

const MAX_METADATA_LENGTH: usize = 256;

// A basic node structure.
#[derive(Debug)]
struct Node {
    value: f64,
    char_ptr: *mut u8,
    next: Option<Arc<Mutex<Node>>>,
}

impl Node {
    fn new(value: f64, char_ptr: *mut u8) -> Self {
        Node { value, char_ptr, next: None }
    }

    // Memory pool for nodes
    static NODE_POOL: SegQueue<Arc<Mutex<Node>>> = SegQueue::new();

    fn allocate_node(value: f64, char_ptr: *mut u8) -> Arc<Mutex<Node>> {
        if let Some(node) = Node::NODE_POOL.pop() {
            node.lock().unwrap().value = value;
            node.lock().unwrap().char_ptr = char_ptr;
            return node;
        }

        // Allocate a new node
        Arc::new(Mutex::new(Node::new(value, char_ptr)))
    }

    fn recycle_node(node: Arc<Mutex<Node>>) {
        Node::NODE_POOL.push(node);
    }
}

// A record structure containing various data types.
#[derive(Debug)]
struct Record {
    short_val: i16,
    int_val: i32,
    float_val: f32,
    timestamp: Tm,
    metadata_ptr: *mut u8,
    event_type: String,  // Placeholder for actual enum type
    status_indicator: bool,
    priority_level: u8,
    weight_factor: f64,
}

impl Record {
    fn new(short_val: i16, int_val: i32, float_val: f32, metadata_ptr: *mut u8) -> Self {
        let timestamp = time::now();
        Record {
            short_val,
            int_val,
            float_val,
            timestamp,
            metadata_ptr,
            event_type: String::from("default_event"),
            status_indicator: true,
            priority_level: 1,
            weight_factor: rand::thread_rng().gen(),
        }
    }

    // Memory pool for records
    static RECORD_POOL: SegQueue<Arc<Mutex<Record>>> = SegQueue::new();

    fn allocate_record(short_val: i16, int_val: i32, float_val: f32, metadata_ptr: *mut u8) -> Arc<Mutex<Record>> {
        if let Some(record) = Record::RECORD_POOL.pop() {
            let mut record = record.lock().unwrap();
            record.short_val = short_val;
            record.int_val = int_val;
            record.float_val = float_val;
            record.metadata_ptr = metadata_ptr;
            record.timestamp = time::now();
            return record.clone();
        }

        // Allocate a new record
        Arc::new(Mutex::new(Record::new(short_val, int_val, float_val, metadata_ptr)))
    }

    fn recycle_record(record: Arc<Mutex<Record>>) {
        Record::RECORD_POOL.push(record);
    }
}

// A thread-safe linked list structure.
#[derive(Debug)]
struct LinkedList {
    head: Option<Arc<Mutex<Node>>>,
}

impl LinkedList {
    fn new() -> Self {
        LinkedList { head: None }
    }

    // Insert a node into the list
    fn insert(&self, value: f64, char_ptr: *mut u8) {
        let new_node = Node::allocate_node(value, char_ptr);

        match self.head.clone() {
            Some(ref head) => {
                let mut current_head = head.lock().unwrap();
                while let Some(next) = &current_head.next {
                    current_head = next.lock().unwrap();
                }

                current_head.next = Some(new_node);
            },
            None => {
                self.head = Some(new_node);
            }
        }
    }

    // Efficient iteration over the list
    fn iterate(&self) -> Vec<f64> {
        let mut values = Vec::new();

        if let Some(ref head) = self.head {
            let mut current = head.lock().unwrap();

            while let Some(node) = &current.next {
                let node = node.lock().unwrap();
                values.push(node.value);
                current = node;
            }

            // Include the first node
            values.push(current.value);
        }

        values
    }
}

// A manager for linked lists and records.
struct Manager {
    lists: Vec<Arc<Mutex<LinkedList>>>,
    records: HashMap<usize, Arc<Mutex<Record>>>,
}

impl Manager {
    fn new() -> Self {
        Manager { 
            lists: Vec::new(), 
            records: HashMap::new(),
        }
    }

    // Insert a record into the manager's collection
    fn insert_record(&mut self, short_val: i16, int_val: i32, float_val: f32, metadata_ptr: *mut u8) {
        let new_record = Record::allocate_record(short_val, int_val, float_val, metadata_ptr);

        // Generate a unique key for the record
        let key = rand::thread_rng().gen_range(0..1_000_000);

        self.records.insert(key, new_record);
    }

    // Concurrent insertions and lookups
    fn concurrent_operations(&self) {
        crossbeam_utils::thread::scope(|s| {
            for i in 0..10 {
                s.spawn(move |_| {
                    let manager = self.clone();

                    // Insert operations in a thread-safe manner
                    manager.lists.iter().for_each(|list| {
                        list.lock().unwrap().insert(rand::random::<f64>(), std::ptr::null_mut());
                    });
                });

                s.spawn(move |_| {
                    let records = &self.records;

                    // Lookup operation
                    for (_key, record) in records.iter() {
                        println!("{:?}", record);
                    }
                });
            }
        }).unwrap();
    }
}

fn main() {
    let manager = Manager::new();

    manager.concurrent_operations();
}
