['Below is a C implementation that addresses the requirements outlined in your task. This code includes managing a linked list with enhanced features, handling dynamic resizing, ensuring thread safety, optimizing memory usage, and providing serialization/deserialization capabilities.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>
#include <stdint.h>

// Record structure
typedef struct Record {
    short s;
    int i;
    float f;
    struct Record* next;
} Record;

// Node structure for memory pool management
typedef struct NodePool {
    size_t block_size;
    size_t count;
    void** blocks;
    pthread_mutex_t lock;
} NodePool;

// Linked list and arrays
typedef struct LinkedListManager {
    long *offsets;
    int *keys;
    size_t capacity;
    Record* head;
    size_t record_count;
    pthread_rwlock_t rwlock; // Read-write lock for the linked list
    NodePool pool;
} LinkedListManager;

// Function prototypes
LinkedListManager* init_manager(size_t initial_capacity, size_t key_range);
void destroy_manager(LinkedListManager* manager);
void add_record(LinkedListManager* manager, short s, int i, float f);
Record* get_random_record(LinkedListManager* manager);
void serialize_list(const char* filename, LinkedListManager* manager);
void deserialize_list(const char* filename, LinkedListManager* manager);

// Helper functions
static inline void lock_node_pool(NodePool* pool) {
    pthread_mutex_lock(&pool->lock);
}

static inline void unlock_node_pool(NodePool* pool) {
    pthread_mutex_unlock(&pool->lock);
}

static void* allocate_from_pool(NodePool* pool) {
    lock_node_pool(pool);
    if (pool->count > 0) {
        void** blocks = pool->blocks;
        void* block = blocks[--(pool->count)];
        unlock_node_pool(pool);
        return block;
    }
    unlock_node_pool(pool);
    return malloc(pool->block_size);
}

static void deallocate_to_pool(NodePool* pool, void* ptr) {
    lock_node_pool(pool);
    if (pool->count < (size_t)(-1) / sizeof(void*)) { // Prevent overflow
        void** blocks = realloc(pool->blocks, (pool->count + 1) * sizeof(void*));
        if (blocks) {
            pool->blocks = blocks;
            pool->blocks[pool->count++] = ptr;
        } else {
            free(ptr);
        }
    } else {
        free(ptr);
    }
    unlock_node_pool(pool);
}

static void init_node_pool(NodePool* pool, size_t block_size, size_t initial_count) {
    pool->block_size = block_size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->blocks = malloc(initial_count * sizeof(void*));
}

// Implementation of LinkedListManager functions
LinkedListManager* init_manager(size_t initial_capacity, size_t key_range) {
    LinkedListManager* manager = calloc(1, sizeof(*manager));
    if (!manager) return NULL;

    pthread_rwlock_init(&manager->rwlock, NULL);

    // Initialize offset and keys arrays
    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->capacity = initial_capacity;

    // Node pool for memory management
    init_node_pool(&manager->pool, sizeof(Record), 10);

    return manager;
}

void destroy_manager(LinkedListManager* manager) {
    if (!manager) return;

    pthread_rwlock_destroy(&manager->rwlock);
    free(manager->offsets);
    free(manager->keys);

    for (size_t i = 0; i < manager->pool.count; ++i) {
        free(manager->pool.blocks[i]);
    }
    free(manager->pool.blocks);

    // Free remaining records
    while (manager->head) {
        Record* temp = manager->head;
        manager->head = manager->head->next;
        deallocate_to_pool(&manager->pool, temp);
    }

    pthread_mutex_destroy(&manager->pool.lock);
    free(manager);
}

void add_record(LinkedListManager* manager, short s, int i, float f) {
    if (!manager || manager->record_count >= manager->capacity) return;

    Record** node = &(manager->head);

    pthread_rwlock_wrlock(&manager->rwlock);
    while (*node) {
        node = &((*node)->next);
    }

    // Allocate and initialize a new record
    Record* new_record = allocate_from_pool(&manager->pool);
    if (!new_record) return;

    new_record->s = s;
    new_record->i = i;
    new_record->f = f;
    new_record->next = NULL;

    *node = new_record;
    manager->record_count++;

    // Update offset and key arrays
    int key = rand() % 100 + 1; // Example range [1, 100]
    if (manager->record_count == 1) {
        manager->keys[0] = key;
        manager->offsets[0] = key;
    } else {
        manager->keys[manager->record_count - 1] = key;
        manager->offsets[manager->record_count - 1] =
            manager->offsets[manager->record_count - 2] + key;
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

Record* get_random_record(LinkedListManager* manager) {
    if (!manager || manager->record_count == 0) return NULL;

    size_t index = rand() % manager->record_count;
    Record* current = manager->head;

    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < index && current; ++i) {
        current = current->next;
    }
    pthread_rwlock_unlock(&manager->rwlock);

    return current;
}

void serialize_list(const char* filename, LinkedListManager* manager) {
    if (!manager || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_rwlock_rdlock(&manager->rwlock);
    Record* current = manager->head;

    while (current) {
        fwrite(&(current->s), sizeof(current->s), 1, file);
        fwrite(&(current->i), sizeof(current->i), 1, file);
        fwrite(&(current->f), sizeof(current->f), 1, file);
        current = current->next;
    }

    pthread_rwlock_unlock(&manager->rwlock);
    fclose(file);
}

void deserialize_list(const char* filename, LinkedListManager* manager) {
    if (!manager || !filename) return;

    FILE* file = fopen(filename, "rb");
    if (!file) return;

    while (1) {
        Record* new_record = allocate_from_pool(&manager->pool);
        if (!new_record) break;

        fread(&(new_record->s), sizeof(new_record->s), 1, file);
        fread(&(new_record->i), sizeof(new_record->i), 1, file);
        fread(&(new_record->f), sizeof(new_record->f), 1, file);

        pthread_rwlock_wrlock(&manager->rwlock);
        new_record->next = manager->head;
        manager->head = new_record;
        pthread_rwlock_unlock(&manager->rwlock);

        if (feof(file)) break;
    }

    fclose(file);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    LinkedListManager* manager = init_manager(10, 100); // Example initial capacity and key range
    add_record(manager, rand(), rand(), (float)rand());

    serialize_list("list.dat", manager);

    destroy_manager(manager);
    return 0;
}
