// Define a simple UserProfile structure
struct UserProfile {
    int UserID;
    std::string Preferences;
    std::chrono::system_clock::time_point LastAccessTime;
    std::string NotificationSettings;

    UserProfile(int userID, const std::string& prefs, const std::string& notifications)
        : UserID(userID), Preferences(prefs), LastAccessTime(std::chrono::system_clock::now()), 
          NotificationSettings(notifications) {}
};

// Define a class for managing user profiles
class UserProfileManager {
private:
    struct LRUEntry {
        int UserID;
        std::shared_ptr<UserProfile> Profile;
        std::chrono::system_clock::time_point LastAccessTime;

        LRUEntry(int userID, std::shared_ptr<UserProfile> profile)
            : UserID(userID), Profile(profile), LastAccessTime(std::chrono::system_clock::now()) {}
    };

    struct {
        std::list<LRUEntry> entries;
        std::unordered_map<int, decltype(entries.begin())> cacheMap;
        std::size_t capacity;

        void touch(int userID) {
            auto it = cacheMap.find(userID);
            if (it != cacheMap.end() && it->second != entries.begin()) {
                entries.splice(entries.begin(), entries, it->second);
                it->second = entries.begin();
                (*it->second).LastAccessTime = std::chrono::system_clock::now();
            }
        }

        void put(int userID, const std::shared_ptr<UserProfile>& profile) {
            auto it = cacheMap.find(userID);
            if (it != cacheMap.end()) {
                touch(userID);
                (*it->second).Profile = profile;
            } else {
                if (entries.size() == capacity) {
                    auto last = entries.back();
                    cacheMap.erase(last.UserID);
                    entries.pop_back();
                }
                entries.push_front(LRUEntry(userID, profile));
                cacheMap[userID] = entries.begin();
            }
        }

        std::shared_ptr<UserProfile> get(int userID) {
            touch(userID);
            return (cacheMap.find(userID)->second)->Profile;
        }
    } lruCache;

    std::unordered_map<int, std::shared_ptr<UserProfile>> profiles;
    mutable std::shared_mutex mutex;
    int maxThreads;
    std::atomic<int> activeRequests{0};

public:
    UserProfileManager(int capacity = 1000, int maxThreadsCount = 10)
        : lruCache{{}, {}, capacity}, maxThreads(maxThreadsCount) {}

    void manageUserPreferencesAndFetchSettings(std::string key, const std::string& value,
                                               const std::string& default_value);

    void addProfile(int userID, const std::string& preferences, const std::string& notifications);
    void removeProfileByUserID(int userID);
    void batchRemoveOldProfiles();
    int countProfilesWithNotificationSettings(const std::string& setting) const;

private:
    void integrateRealTimeDataAsync();
    void handleNetworkErrorsAndValidateData();
    void memoryProfiler();

    using ThreadPool = std::vector<std::thread>;
    ThreadPool threadPool;
};

void UserProfileManager::manageUserPreferencesAndFetchSettings(std::string key, 
                                                               const std::string& value,
                                                               const std::string& default_value) {
    std::shared_lock lock(mutex);
    if (profiles.find(key.hashCode()) != profiles.end() || key == default_value) {
        auto profile = lruCache.get(key.hashCode());
        profile->Preferences = (value.empty() ? default_value : value);
        lruCache.put(key.hashCode(), profile);
    } else {
        std::shared_ptr<UserProfile> newProfile(new UserProfile(key.hashCode(), default_value, ""));
        profiles[key.hashCode()] = newProfile;
        lruCache.put(key.hashCode(), newProfile);
    }
}

void UserProfileManager::addProfile(int userID, const std::string& preferences, 
                                    const std::string& notifications) {
    std::unique_lock lock(mutex);
    if (profiles.find(userID) == profiles.end()) {
        auto profile = std::make_shared<UserProfile>(userID, preferences, notifications);
        profiles[userID] = profile;
        lruCache.put(userID, profile);
    }
}

void UserProfileManager::removeProfileByUserID(int userID) {
    std::unique_lock lock(mutex);
    if (profiles.erase(userID)) {
        lruCache.cacheMap.erase(userID);
    }
}

void UserProfileManager::batchRemoveOldProfiles() {
    std::unique_lock lock(mutex);
    auto now = std::chrono::system_clock::now();
    for (auto it = profiles.begin(); it != profiles.end();) {
        if (std::chrono::duration_cast<std::chrono::hours>(now - it->second->LastAccessTime).count() >= 24) {
            lruCache.cacheMap.erase(it->first);
            it = profiles.erase(it);
        } else {
            ++it;
        }
    }
}

int UserProfileManager::countProfilesWithNotificationSettings(const std::string& setting) const {
    int count = 0;
    std::shared_lock lock(mutex);
    for (const auto& [_, profile] : profiles) {
        if (profile->NotificationSettings == setting) {
            ++count;
        }
    }
    return count;
}

