#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2
#define MAX_ARRAY_SIZE 1024
#define THREAD_COUNT 4

typedef struct record {
    short s_field;
    int i_field;
    float f_field;
    struct record* next;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} dynamic_array_t;

// Function prototypes
void init_dynamic_array(dynamic_array_t *array);
int resize_dynamic_array(dynamic_array_t *array);
void free_dynamic_array(dynamic_array_t *array);
void initialize_data(dynamic_array_t *offsets, dynamic_array_t *keys, record_t **head_ptr);
record_t* create_record();
void insert_record(record_t **head_ptr, record_t *new_node);
void free_linked_list(record_t *head);
long calculate_offset(int i, const int *keys);

// Initialize a dynamic array
void init_dynamic_array(dynamic_array_t *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->size = 0;
    array->capacity = INITIAL_SIZE;
    array->offsets = (long *)malloc(array->capacity * sizeof(long));
    array->keys = (int *)malloc(array->capacity * sizeof(int));
}

// Resize the dynamic array if needed
int resize_dynamic_array(dynamic_array_t *array) {
    if (array->size >= array->capacity && array->capacity < MAX_ARRAY_SIZE) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        pthread_mutex_lock(&array->lock);
        long *new_offsets = realloc(array->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(array->keys, new_capacity * sizeof(int));
        if (new_offsets && new_keys) {
            array->offsets = new_offsets;
            array->keys = new_keys;
            array->capacity = new_capacity;
            pthread_mutex_unlock(&array->lock);
            return 1; // Success
        }
        pthread_mutex_unlock(&array->lock);
    }
    return 0; // No resize needed or reached max size
}

// Free resources for dynamic array
void free_dynamic_array(dynamic_array_t *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->offsets);
    free(array->keys);
}

// Initialize the data structures with thread-safe operations
void initialize_data(dynamic_array_t *offsets, dynamic_array_t *keys, record_t **head_ptr) {
    srand(time(NULL));

    for (size_t i = 0; i < offsets->capacity; ++i) {
        while (!resize_dynamic_array(offsets)) break;

        pthread_mutex_lock(&offsets->lock);
        pthread_mutex_lock(&keys->lock);

        keys->keys[i] = rand() % 100 + 1; // Unique integer in the range [1, 100]
        offsets->offsets[i] = i > 0 ? calculate_offset(i, keys->keys) : keys->keys[0];

        pthread_mutex_unlock(&keys->lock);
        pthread_mutex_unlock(&offsets->lock);

        record_t *new_record = create_record();
        insert_record(head_ptr, new_record);
    }
}

// Calculate offset value
long calculate_offset(int i, const int *keys) {
    long sum = 0;
    for (int j = 0; j < i; ++j) {
        sum += keys[j];
    }
    return sum + 42; // constant value
}

// Create a new record with random values
record_t* create_record() {
    record_t *new_node = malloc(sizeof(record_t));
    if (new_node) {
        new_node->s_field = rand() % 100;
        new_node->i_field = rand() % 1000 + 1;
        new_node->f_field = (float)rand() / RAND_MAX * 100.0f;
        new_node->next = NULL;
    }
    return new_node;
}

// Insert a record into the linked list
void insert_record(record_t **head_ptr, record_t *new_node) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    if (*head_ptr == NULL || (*head_ptr)->s_field > new_node->s_field) {
        new_node->next = *head_ptr;
        *head_ptr = new_node;
    } else {
        record_t *current = *head_ptr;
        while (current->next && current->next->s_field <= new_node->s_field) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

// Free the linked list
void free_linked_list(record_t *head) {
    while (head != NULL) {
        record_t *temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    dynamic_array_t offsets, keys;
    record_t *linked_list_head = NULL;

    init_dynamic_array(&offsets);
    init_dynamic_array(&keys);

    initialize_data(&offsets, &keys, &linked_list_head);

    // Perform operations on linked list (omitted for brevity)

    free_linked_list(linked_list_head);
    free_dynamic_array(&offsets);
    free_dynamic_array(&keys);

    return 0;
}
```

This C code snippet implements dynamic memory management and concurrent processing of an array and a linked list. The arrays are resized dynamically, the initialization is thread-safe, and random values populate records. Locking mechanisms manage access to shared resources, ensuring safe multithreaded operations.']

['Below is a C implementation for dynamically managing memory for an array of records with concurrent access handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes

typedef struct {
    int key;
    size_t offset;
    char* data_buffer;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!mm->records) {
        free(mm);
        return NULL;
    }

    mm->capacity = initial_capacity;
    mm->used_memory = 0;
    pthread_mutex_init(&mm->lock, NULL);

    return mm;
}

int add_record(MemoryManager* mm, int key, size_t buffer_size) {
    pthread_mutex_lock(&mm->lock);

    if (mm->used_memory + sizeof(Record) + buffer_size > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Error: Exceeding memory limit\n");
        pthread_mutex_unlock(&mm->lock);
        return -1;
    }

    if (mm->capacity == 0 || mm->records[mm->capacity - 1].key != 0) { // Assuming key 0 means unused
        Record* new_records = realloc(mm->records, sizeof(Record) * (mm->capacity + 10));
        if (!new_records) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }
        mm->records = new_records;
        mm->capacity += 10;
    }

    for (size_t i = 0; i < mm->capacity; ++i) {
        if (mm->records[i].key == 0) { // Unused slot
            mm->records[i].key = key;
            mm->records[i].offset = mm->used_memory + sizeof(Record);
            mm->records[i].data_buffer = malloc(buffer_size);
            if (!mm->records[i].data_buffer) {
                pthread_mutex_unlock(&mm->lock);
                return -1;
            }
            mm->used_memory += sizeof(Record) + buffer_size;
            break;
        }
    }

    pthread_mutex_unlock(&mm->lock);
    return 0;
}

void free_memory_manager(MemoryManager* mm) {
    if (!mm) return;

    pthread_mutex_lock(&mm->lock);

    for (size_t i = 0; i < mm->capacity; ++i) {
        if (mm->records[i].key != 0) {
            free(mm->records[i].data_buffer);
        }
    }

    free(mm->records);
    pthread_mutex_unlock(&mm->lock);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

int main() {
    MemoryManager* mm = create_memory_manager(10);
    if (!mm) return 1;

    add_record(mm, 1, 256);
    add_record(mm, 2, 512);

    free_memory_manager(mm);
    return 0;
}
```

### Design Choices and Rationale:

1. **Memory Management**: 
   - Used `calloc` for initial allocation to zero-initialize records.
   - Employed `realloc` for dynamic expansion of the records array, adding a buffer size increment (10) to minimize frequent reallocations.

2. **Concurrency**:
   - Utilized `pthread_mutex_t` to ensure thread-safe access to shared memory structures, preventing race conditions.
   - Locks are used during both allocation and deallocation to maintain data integrity.

3. **Error Handling**:
   - Checked for out-of-memory conditions before attempting allocations and logged errors when limits were exceeded.

4. **Performance Considerations**:
   - Chose a simple mutex lock strategy for synchronization, balancing performance with safety.
   - Incremental reallocations reduce fragmentation and improve performance by minimizing frequent memory operations.

5. **Memory Usage Monitoring**:
   - Kept track of used memory to ensure allocations do not exceed the predefined limit (`MAX_MEMORY_LIMIT`).

This implementation provides efficient dynamic memory management while ensuring thread safety and handling potential out-of-memory conditions gracefully.']

