['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

#define ALIGNMENT 16

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#else
#error "Platform not supported"
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    free(ptr);
#else
#error "Platform not supported"
#endif
}

Record* initializeDataStructures(size_t numRecords, int offsetRangeMin, int offsetRangeMax, unsigned int seed) {
    if (numRecords == 0 || offsetRangeMin > offsetRangeMax) return NULL;

    // Align the allocation for optimal performance
    Record *records = (Record *)aligned_alloc(ALIGNMENT, sizeof(Record) * numRecords);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed);

    for (size_t i = 0; i < numRecords; ++i) {
        // Bounds checking is implicit by the loop condition
        records[i].offset = (long)(rand() % (offsetRangeMax - offsetRangeMin + 1)) + offsetRangeMin;
        records[i].key = i ^ seed; // Derive key from index and seed
        records[i].value = (double)(rand() % (offsetRangeMax - offsetRangeMin + 1)) / RAND_MAX * (offsetRangeMax - offsetRangeMin) + offsetRangeMin;
    }

    return records;
}

void freeDataStructures(Record *records) {
    if (records) {
        aligned_free(records);
    }
}
