class DynamicMemoryManager {
private:
    std::vector<Record> records;
    std::mutex mtx;  // Mutex for thread-safe operations.
    size_t totalMemoryUsage;
    const size_t maxMemoryLimit;

public:
    DynamicMemoryManager(size_t memoryLimit) : totalMemoryUsage(0), maxMemoryLimit(memoryLimit) {}

    bool addRecord(int key, size_t bufferSize) {
        std::lock_guard<std::mutex> lock(mtx);

        if (totalMemoryUsage + bufferSize > maxMemoryLimit) {
            std::cerr << "Error: Memory limit exceeded.\n";
            return false;
        }

        records.emplace_back(key, totalMemoryUsage, bufferSize);
        totalMemoryUsage += bufferSize;

        return true;
    }

    void freeAll() {
        std::lock_guard<std::mutex> lock(mtx);

        for (auto& record : records) {
            delete[] record.dataBuffer;
        }
        records.clear();
        totalMemoryUsage = 0;
    }

