['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_MEMORY_MB 10

typedef struct {
    long offset;
    int key;
    int value;
} record;

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocated_memory = 0;
static size_t peak_usage = 0;

void log_event(const char *event) {
    FILE *log_file = fopen("memory_logs.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", event);
        fclose(log_file);
    }
}

size_t calculate_size(size_t num_records) {
    size_t record_size = sizeof(record);
    return num_records * record_size;
}

int validate_parameters(size_t num_records) {
    if (num_records > MAX_RECORDS) {
        log_event("Error: Number of records exceeds maximum limit.");
        return 0;
    }

    size_t memory_needed_mb = calculate_size(num_records) / (1024 * 1024);
    if (memory_needed_mb > MAX_MEMORY_MB) {
        log_event("Error: Memory allocation request exceeds the allowed limit.");
        return 0;
    }

    return 1;
}

record* allocate_memory(size_t num_records, long offset[], int key[]) {
    pthread_mutex_lock(&memory_lock);

    size_t memory_size = calculate_size(num_records);
    if (total_allocated_memory + memory_size > MAX_MEMORY_MB * 1024 * 1024) {
        pthread_mutex_unlock(&memory_lock);
        log_event("Error: Not enough available memory.");
        return NULL;
    }

    record* records = (record*)malloc(memory_size);
    if (!records) {
        pthread_mutex_unlock(&memory_lock);
        log_event("Error: Memory allocation failed.");
        return NULL;
    }

    total_allocated_memory += memory_size;
    if (total_allocated_memory > peak_usage) {
        peak_usage = total_allocated_memory;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offset[i];
        records[i].key = key[i];
        records[i].value = rand() % 1000 + 1; // Random value between 1 and 1000
    }

    pthread_mutex_unlock(&memory_lock);
    log_event("Memory allocated successfully.");
    return records;
}

void deallocate_memory(record* records, size_t num_records) {
    if (records) {
        pthread_mutex_lock(&memory_lock);

        free(records);
        total_allocated_memory -= calculate_size(num_records);

        pthread_mutex_unlock(&memory_lock);
        log_event("Memory deallocated successfully.");
    }
}

size_t get_current_usage() {
    pthread_mutex_lock(&memory_lock);

    size_t usage = total_allocated_memory;
    pthread_mutex_unlock(&memory_lock);

    return usage;
}

void release_resources() {
    pthread_mutex_destroy(&memory_lock);
}
