// Structure definition for a record
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
#endif
    return ptr;
}

// Function to free aligned memory
void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Initialize random number generator with a seed
static inline void init_random_seed(unsigned int seed) {
    srand(seed + time(NULL));
}

// Generate a random long value within range [min, max]
long generate_random_long(long min, long max) {
    return rand() % (max - min + 1) + min;
}

// Generate a random double value within range [min, max)
double generate_random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

// Function to allocate and initialize an array of records
Record* create_records(size_t array_size, size_t num_records, size_t alignment,
                       long offset_min, long offset_max, int seed,
                       double value_min, double value_max) {
    if (array_size == 0 || num_records == 0 || alignment < sizeof(void*)) {
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    Record *records = aligned_alloc(alignment, array_size * num_records * sizeof(Record));
    if (!records) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Allocation failed
    }

    init_random_seed(seed);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = generate_random_long(offset_min, offset_max);
        records[i].key = i + seed;
        records[i].value = generate_random_double(value_min, value_max);
    }

    pthread_mutex_unlock(&mutex);

    return records;
}

// Function to deallocate the array of records
void free_records(Record *records) {
    if (records) {
        aligned_free(records);
    }
}

// Example usage and testing
int main() {
    size_t array_size = 10;
    size_t num_records = 5;
    size_t alignment = 16;
    long offset_min = 0, offset_max = 100;
    int seed = 42;
    double value_min = 0.0, value_max = 1.0;

    Record *records = create_records(array_size, num_records, alignment,
                                     offset_min, offset_max, seed,
                                     value_min, value_max);

    if (records) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu: Offset = %ld, Key = %d, Value = %.2f\n",
                   i, records[i].offset, records[i].key, records[i].value);
        }
        free_records(records);
    } else {
        fprintf(stderr, "Failed to allocate memory for records.\n");
    }

    return 0;
}
