#else
    free(ptr);
#endif
}

int initializeWorld(size_t numRecords, long offsetRange, unsigned int seed,
                    Record*** recordsArray, double** valuesArray,
                    char*** keysArray, item*** itemsArray) {

    // Seed random number generator for reproducibility
    srand(seed);

    // Initialize arrays to NULL in case of allocation failure
    *recordsArray = NULL;
    *valuesArray = NULL;
    *keysArray = NULL;
    *itemsArray = NULL;

    size_t recordSize = sizeof(Record);
    size_t valueSize = sizeof(double);
    size_t keyBufferSize = numRecords * 256; // Assuming max key length of 255 + null terminator
    size_t itemStructSize = sizeof(item);

    // Allocate memory for the records array with alignment
    *recordsArray = (Record**)aligned_malloc(numRecords * recordSize, ALIGNMENT);
    if (*recordsArray == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }

    // Allocate and initialize each Record
    for (size_t i = 0; i < numRecords; ++i) {
        (*recordsArray)[i] = (Record*)aligned_malloc(recordSize, ALIGNMENT);
        if ((*recordsArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record at index %zu.\n", i);
            // Free previously allocated memory
            while (--i >= 0) {
                aligned_free((*recordsArray)[i]);
            }
            aligned_free(*recordsArray);
            *recordsArray = NULL;
            return -1;
        }

        (*recordsArray)[i]->offset = rand() % offsetRange;
        (*recordsArray)[i]->key = (rand() + seed) % 10000; // Example key derivation
        (*recordsArray)[i]->value = ((double)rand() / RAND_MAX) * offsetRange;

        // Allocate and initialize values array
        *valuesArray = (double*)aligned_malloc(numRecords * valueSize, ALIGNMENT);
        if (*valuesArray == NULL) {
            fprintf(stderr, "Memory allocation failed for values.\n");
            while (--i >= 0) {
                aligned_free((*recordsArray)[i]);
            }
            aligned_free(*recordsArray);
            *recordsArray = NULL;
            return -1;
        }
        (*valuesArray)[i] = (*recordsArray)[i]->value;

        // Allocate and initialize keys array
        *keysArray = (char**)aligned_malloc(numRecords * sizeof(char*), ALIGNMENT);
        if (*keysArray == NULL) {
            fprintf(stderr, "Memory allocation failed for keys.\n");
            aligned_free(*valuesArray);
            while (--i >= 0) {
                aligned_free((*recordsArray)[i]);
            }
            aligned_free(*recordsArray);
            *recordsArray = NULL;
            return -1;
        }

        (*keysArray)[i] = (char*)aligned_malloc(keyBufferSize, ALIGNMENT);
        if ((*keysArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for key at index %zu.\n", i);
            aligned_free(*valuesArray);
            while (--i >= 0) {
                free((*keysArray)[i]);
                aligned_free((*recordsArray)[i]);
            }
            aligned_free(*keysArray);
            aligned_free(*recordsArray);
            *keysArray = NULL;
            *recordsArray = NULL;
            return -1;
        }

        snprintf((*keysArray)[i], keyBufferSize, "key_%zu", i);

        // Allocate and initialize items array
        *itemsArray = (item**)aligned_malloc(numRecords * sizeof(item*), ALIGNMENT);
        if (*itemsArray == NULL) {
            fprintf(stderr, "Memory allocation failed for items.\n");
            aligned_free((*keysArray)[i]);
            while (--i >= 0) {
                free((*keysArray)[i]);
                aligned_free((*recordsArray)[i]);
            }
            aligned_free(*keysArray);
            aligned_free(*valuesArray);
            aligned_free(*recordsArray);
            *itemsArray = NULL;
            return -1;
        }

        (*itemsArray)[i] = (item*)aligned_malloc(itemStructSize, ALIGNMENT);
        if ((*itemsArray)[i] == NULL) {
