### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define CACHE_SIZE 1000
#define LOG_BATCH_SIZE 100

typedef struct record {
    short id;
    int key;
    float value;
    struct record *next;
} Record;

typedef struct cache_entry {
    short id;
    struct record *record;
    struct cache_entry *prev, *next;
} CacheEntry;

Record *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

CacheEntry *cache_head = NULL, *cache_tail = NULL;
int cache_count = 0;

typedef struct log_entry {
    time_t timestamp;
    short user_id;
    char data[256];
    struct log_entry *next;
} LogEntry;

LogEntry *log_head = NULL, *log_tail = NULL;

void add_log_entry(time_t timestamp, short user_id, const char *data) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->user_id = user_id;
    snprintf(entry->data, sizeof(entry->data), "%s", data);
    entry->next = NULL;

    pthread_mutex_lock(&lock);
    if (!log_head) {
        log_head = log_tail = entry;
    } else {
        log_tail->next = entry;
        log_tail = entry;
    }
    pthread_mutex_unlock(&lock);

    if ((log_tail - log_head + 1) % LOG_BATCH_SIZE == 0) {
        // Trigger asynchronous logging (e.g., write to file)
    }
}

void init_database() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        Record *new_record = (Record *)malloc(sizeof(Record));
        new_record->id = rand() % MAX_RECORDS;
        new_record->key = rand() % MAX_RECORDS;
        new_record->value = ((float)rand() / RAND_MAX) * 100.0;
        new_record->next = head;
        head = new_record;
    }
}

void init_cache() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        CacheEntry *entry = (CacheEntry *)malloc(sizeof(CacheEntry));
        entry->id = -1;
        entry->record = NULL;
        entry->prev = cache_tail;
        entry->next = NULL;

        if (!cache_head) {
            cache_head = cache_tail = entry;
        } else {
            cache_tail->next = entry;
            cache_tail = entry;
        }
    }
    pthread_mutex_unlock(&lock);
}

void access_record(short id) {
    pthread_mutex_lock(&lock);

    // Check cache first
    CacheEntry *current = cache_head;
    while (current) {
        if (current->id == id) {
            pthread_mutex_unlock(&lock);
            return; // Record found in cache
        }
        current = current->next;
    }

    // If not in cache, find in records
    Record *record = head;
    while (record) {
        if (record->id == id) {
            // Move to front of cache (LRU policy)
            if (current) {
                current->prev->next = current->next;
                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    cache_tail = current->prev;
                }
            }

            current->id = id;
            current->record = record;

            // Move to front of cache
            current->next = cache_head;
            if (cache_head) {
                cache_head->prev = current;
            }
            cache_head = current;
            if (!current->prev) {
                cache_tail = current;
            }

            pthread_mutex_unlock(&lock);
            return;
        }
        record = record->next;
    }

    pthread_mutex_unlock(&lock);
}

void save_to_disk() {
    FILE *file = fopen("database_backup.dat", "wb");
    Record *record = head;

    while (record) {
        fwrite(record, sizeof(Record), 1, file);
        record = record->next;
    }
    fclose(file);
}

void load_from_disk() {
    FILE *file = fopen("database_backup.dat", "rb");
    if (!file) return;

    Record *new_record;
    while (fread(&new_record, sizeof(Record), 1, file)) {
        new_record->next = head;
        head = new_record;
    }
    fclose(file);
}
```

