    char file_type;
    access_level permissions;
    time_t last_accessed_time;
    char *file_name;
} inode;

// Memory pool structure
typedef struct memory_pool {
    size_t block_size;
    void **blocks;
    int num_blocks;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t block_size, int num_blocks) {
    memory_pool *pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->blocks = (void**)calloc(num_blocks, sizeof(void*));
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);

    for (int i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
        if (!pool->blocks[i]) {
            // Cleanup on failure
            for (int j = 0; j < i; ++j) free(pool->blocks[j]);
            free(pool->blocks);
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }
    }

    log_memory_operation("Memory pool created", block_size * num_blocks);
    return pool;
}

void* allocate_from_pool(memory_pool *pool, size_t size) {
    if (size > pool->block_size) {
        fprintf(stderr, "Requested size exceeds memory pool block size\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i]) continue;
        void *block = malloc(pool->block_size);
        if (!block) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->blocks[i] = block;
        log_memory_operation("Allocated from memory pool", pool->block_size);
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);

    fprintf(stderr, "Memory pool exhausted\n");
    return NULL;
}

void free_to_pool(memory_pool *pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i] == ptr) {
            log_memory_operation("Freed to memory pool", pool->block_size);
            free(ptr);
            pool->blocks[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(memory_pool *pool) {
    for (int i = 0; i < pool->num_blocks; ++i) {
        if (pool->blocks[i]) free(pool->blocks[i]);
    }
    free(pool->blocks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void log_memory_operation(const char *operation, size_t size) {
    time_t now = time(NULL);
    printf("[%s] %s: %zu bytes\n", ctime(&now), operation, size);
}

inode** initialize_inodes(int num_inodes) {
    if (num_inodes > UNIQUE_ID_LIMIT || num_inodes > MAX_INODES) {
        fprintf(stderr, "Number of inodes exceeds limits\n");
        return NULL;
    }

    memory_pool *pool = create_memory_pool(sizeof(inode), num_inodes);
    if (!pool) return NULL;

    inode **inodes = (inode**)malloc(num_inodes * sizeof(inode*));
    if (!inodes) {
        destroy_memory_pool(pool);
        fprintf(stderr, "Failed to allocate inodes array\n");
        return NULL;
    }

    char name_buffer[256];
    for (int i = 0; i < num_inodes; ++i) {
        inode *new_inode = (inode*)allocate_from_pool(pool, sizeof(inode));
        if (!new_inode) {
            destroy_memory_pool(pool);
            free(inodes);
            fprintf(stderr, "Failed to allocate inode\n");
            return NULL;
        }

        new_inode->inode_number = i;
        new_inode->file_type = 'f'; // Example file type
        new_inode->permissions = READ_ONLY;
        new_inode->last_accessed_time = time(NULL);

        snprintf(name_buffer, sizeof(name_buffer), "file_%ld", (long)i);
        new_inode->file_name = strdup(name_buffer);
        if (!new_inode->file_name) {
            free_to_pool(pool, new_inode);
            destroy_memory_pool(pool);
            for (int j = 0; j < i; ++j) free_to_pool(pool, inodes[j]);
            free(inodes);
            fprintf(stderr, "Failed to allocate file name\n");
            return NULL;
        }

        inodes[i] = new_inode;
    }

    log_memory_operation("Inodes initialized", num_inodes * sizeof(inode*));
    return inodes;
}

void cleanup_inodes(inode **inodes, int num_inodes, memory_pool *pool) {
    for (int i = 0; i < num_inodes; ++i) {
        if (!inodes[i]) continue;
        free_to_pool(pool, inodes[i]->file_name);
        free_to_pool(pool, inodes[i]);
    }
    free(inodes);
    destroy_memory_pool(pool);
}

int main() {
    int num_inodes = 30000; // Example number of inodes
    inode **inodes = initialize_inodes(num_inodes);

    if (inodes) {
        printf("Inodes initialized successfully.\n");

        // Perform operations...

        cleanup_inodes(inodes, num_inodes, NULL);
    }

    return 0;
}
```

### Key Features:
