```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <yaml.h>

#define INITIAL_TABLE_SIZE 1024
#define MAX_LOAD_FACTOR 0.8

typedef struct ConfigSetting {
    char *key;
    char *value;
    time_t expiry;
} ConfigSetting;

typedef struct HashNode {
    ConfigSetting setting;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    size_t size;
    size_t count;
    HashNode** buckets;
} HashTable;

unsigned long hash_function(const char* key, size_t table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % table_size;
}

HashTable* create_table(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->count = 0;
    table->buckets = (HashNode**)calloc(table->size, sizeof(HashNode*));
    return table;
}

void resize_table_if_needed(HashTable* table) {
    if ((double)table->count / table->size > MAX_LOAD_FACTOR) {
        size_t new_size = table->size * 2;
        HashNode** new_buckets = (HashNode**)calloc(new_size, sizeof(HashNode*));

        for (size_t i = 0; i < table->size; ++i) {
            HashNode* node = table->buckets[i];
            while (node) {
                HashNode* next = node->next;
                size_t index = hash_function(node->setting.key, new_size);
                node->next = new_buckets[index];
                new_buckets[index] = node;
                node = next;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->size = new_size;
    }
}

void insert_setting(HashTable* table, ConfigSetting setting) {
    resize_table_if_needed(table);

    size_t index = hash_function(setting.key, table->size);
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->setting = setting;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    ++table->count;
}

void remove_expired_settings(HashTable* table) {
    time_t now = time(NULL);
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            if (node->setting.expiry <= now) {
                HashNode* to_remove = node;
                node = node->next;
                free(to_remove->setting.key);
                free(to_remove->setting.value);
                free(to_remove);
                continue;
            }
            node = node->next;
        }
    }
}

void cleanup(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node->setting.key);
            free(node->setting.value);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

void parse_yaml_file(const char* filename, HashTable* table) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    yaml_parser_t parser;
    if (!yaml_parser_initialize(&parser)) {
        fclose(file);
        return;
    }

    yaml_parser_set_input_file(&parser, file);

    yaml_event_t event;
    while (1) {
        if (!yaml_parser_parse(&parser, &event))
            break;

        // Simplified parsing logic for demonstration purposes
        if (event.type == YAML_SCALAR_EVENT) {
            char* key = strdup((char*)event.data.scalar.value);
            char* value = "dummy_value";  // Replace with actual parsed value
            time_t expiry = time(NULL) + rand() % 3600;  // Random expiration

            ConfigSetting setting = { .key = key, .value = strdup(value), .expiry = expiry };
            insert_setting(table, setting);
        }

        if (event.type == YAML_STREAM_END_EVENT)
            break;

        yaml_event_delete(&event);
    }

    yaml_parser_delete(&parser);
    fclose(file);
}

void* thread_function(void* arg) {
    const char** filenames = (const char**)arg;
    HashTable* table = create_table(INITIAL_TABLE_SIZE);

    for (int i = 0; filenames[i]; ++i) {
        parse_yaml_file(filenames[i], table);
    }

    remove_expired_settings(table);
    // Aggregate results into a hierarchical structure here
    cleanup(table);

    return NULL;
}

void process_files_concurrently(const char** filenames, int num_threads) {
    pthread_t threads[num_threads];
    const char** files_per_thread = (const char**)malloc(num_threads * sizeof(const char*));

    for (int i = 0; i < num_threads; ++i) {
        files_per_thread[i] = &filenames[i * (num_files / num_threads)];
        pthread_create(&threads[i], NULL, thread_function, (void*)files_per_thread);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(files_per_thread);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <yaml_file1> [<yaml_file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char** filenames = &argv[1];
    int num_files = argc - 1;
    int num_threads = 4;  // Adjust based on your system

    process_files_concurrently(filenames, num_threads);

    return EXIT_SUCCESS;
}
```

