// Custom memory pool structure for efficient allocation
typedef struct {
    size_t block_size;
    unsigned char *pool;
    size_t pool_size;
    pthread_mutex_t mutex;
} MemoryPool;

// Initialize the memory pool
int init_memory_pool(MemoryPool *mp, size_t pool_size, size_t block_size) {
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->pool = (unsigned char *)malloc(pool_size);
    if (!mp->pool) return -1;
    pthread_mutex_init(&mp->mutex, NULL);
    return 0;
}

// Allocate memory from the custom pool
void *mem_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->mutex);
    void *ptr = mp->pool; // Simplified allocation logic for demonstration
    mp->pool += mp->block_size;
    pthread_mutex_unlock(&mp->mutex);
    return ptr;
}

// Free the memory pool
void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->mutex);
}

// Function to manage records
typedef struct {
    long *offsets;
    int *keys;
    Record *records_head;
    size_t current_size;
    size_t capacity;
    MemoryPool mp;
    pthread_rwlock_t rwlock;
} RecordManager;

void init_record_manager(RecordManager *rm, size_t initial_capacity) {
    rm->current_size = 0;
    rm->capacity = initial_capacity;

    if (init_memory_pool(&rm->mp, initial_capacity * sizeof(long) + initial_capacity * sizeof(int) +
                        initial_capacity * sizeof(Record), sizeof(Record)) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(EXIT_FAILURE);
    }

    rm->offsets = (long *)mem_pool_alloc(&rm->mp);
    rm->keys = (int *)mem_pool_alloc(&rm->mp);
    rm->records_head = (Record *)mem_pool_alloc(&rm->mp);

    pthread_rwlock_init(&rm->rwlock, NULL);
}

void resize_arrays(RecordManager *rm) {
    pthread_rwlock_wrlock(&rm->rwlock);

    size_t new_capacity = rm->capacity * 2;
    long *new_offsets = (long *)realloc(rm->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(rm->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        fprintf(stderr, "Failed to resize arrays\n");
        exit(EXIT_FAILURE);
    }

    rm->offsets = new_offsets;
    rm->keys = new_keys;
    rm->capacity = new_capacity;

    pthread_rwlock_unlock(&rm->rwlock);
}

void populate_data(RecordManager *rm, int key_range_start, int key_range_end) {
    pthread_rwlock_wrlock(&rm->rwlock);

    for (size_t i = 0; i < rm->current_size; ++i) {
        rm->keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);
        rm->offsets[i] = (i == 0) ? 0 : rm->offsets[i - 1] + rm->keys[i - 1] + 100;
    }

    Record *current = rm->records_head;
    for (size_t i = 0; i < rm->current_size; ++i, current = current->next) {
        if (!current->next && i < rm->current_size - 1) {
            current->next = (Record *)mem_pool_alloc(&rm->mp);
        }
        current->field1 = rand() % 100;
        current->field2 = rand() % 1000;
        current->field3 = (float)(rand() / (RAND_MAX + 1.0)) * 1000.0f;
    }

    pthread_rwlock_unlock(&rm->rwlock);
}

void cleanup_record_manager(RecordManager *rm) {
    pthread_rwlock_wrlock(&rm->rwlock);

    Record *current = rm->records_head;
    while (current) {
        Record *next = current->next;
        free(current); // Assuming `mem_pool_alloc` allocates with `malloc`
        current = next;
    }

    free(rm->offsets);
    free(rm->keys);

    pthread_rwlock_unlock(&rm->rwlock);
    pthread_rwlock_destroy(&rm->rwlock);
    free_memory_pool(&rm->mp);
}

// Example usage
int main() {
    RecordManager rm;
    init_record_manager(&rm, 10000);

    // Populate data with random keys in the range [1, 1000]
    populate_data(&rm, 1, 1000);

    // Cleanup resources
    cleanup_record_manager(&rm);

    return 0;
}
