#include <stdio.h>
#include <stdlib.h>
import time.h
#include <pthread.h>
#include <stdint.h>

typedef struct Record {
    short s;
    int i;
    float f;
    double d;
} Record;

typedef struct Node {
    Record data;
    struct Node *next;
    struct Node *prev;
} Node;

typedef struct LinkedList {
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct HashTableEntry {
    int key;
    Node *record_node;
    struct HashTableEntry *next;
} HashTableEntry;

#define INITIAL_SIZE 16
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 10000

typedef struct DataPipelineComponent {
    long *offsets;
    int *keys;
    size_t num_elements;
    LinkedList records_list;
    time_t *event_timestamps;
    HashTableEntry **hash_table;
    size_t hash_size;

    pthread_mutex_t offset_lock;
    pthread_mutex_t key_lock;
    pthread_mutex_t timestamp_lock;
} DataPipelineComponent;

void initialize_component(DataPipelineComponent *component, size_t initial_capacity) {
    component->num_elements = 0;

    pthread_mutex_init(&component->offset_lock, NULL);
    pthread_mutex_init(&component->key_lock, NULL);
    pthread_mutex_init(&component->timestamp_lock, NULL);

    pthread_mutex_init(&component->records_list.lock, NULL);
    component->records_list.head = NULL;
    component->records_list.tail = NULL;

    component->hash_size = INITIAL_SIZE;
    component->hash_table = calloc(component->hash_size, sizeof(HashTableEntry*));

    component->offsets = malloc(initial_capacity * sizeof(long));
    component->keys = malloc(initial_capacity * sizeof(int));
    component->event_timestamps = malloc(initial_capacity * sizeof(time_t));

    if (!component || !component->offsets || !component->keys || !component->event_timestamps || !component->hash_table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_component(DataPipelineComponent *component) {
    pthread_mutex_destroy(&component->offset_lock);
    pthread_mutex_destroy(&component->key_lock);
    pthread_mutex_destroy(&component->timestamp_lock);

    pthread_mutex_destroy(&component->records_list.lock);

    Node *node = component->records_list.head;
    while (node) {
        Node *temp = node;
        node = node->next;
        free(temp);
    }

    for (size_t i = 0; i < component->hash_size; ++i) {
        HashTableEntry *entry = component->hash_table[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(component->offsets);
    free(component->keys);
    free(component->event_timestamps);
    free(component->hash_table);

    component->offsets = NULL;
    component->keys = NULL;
    component->event_timestamps = NULL;
    component->hash_table = NULL;
}

unsigned int hash_function(int key, size_t hash_size) {
    return (unsigned int)(key % hash_size);
}

void add_record(DataPipelineComponent *component, Record record) {
    pthread_mutex_lock(&component->offset_lock);
    pthread_mutex_lock(&component->key_lock);

    if (component->num_elements >= component->hash_size) { // Resize logic
        size_t new_capacity = component->num_elements * 2;
        long *new_offsets = realloc(component->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(component->keys, new_capacity * sizeof(int));
        time_t *new_timestamps = realloc(component->event_timestamps, new_capacity * sizeof(time_t));

        if (new_offsets && new_keys && new_timestamps) {
            component->offsets = new_offsets;
            component->keys = new_keys;
