#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <yaml.h>
#include <time.h>
#include <stdint.h>

#define HASH_TABLE_SIZE 1048576 // 1 million buckets
#define LOCK_FREE true

typedef struct {
    char *key;
    char *value;
    time_t timestamp;
} Setting;

typedef struct Node {
    Setting setting;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    pthread_mutex_t mutexes[HASH_TABLE_SIZE];
} HashTable;

uint32_t hash_function(const char *str) {
    uint32_t hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % HASH_TABLE_SIZE;
}

void init_hash_table(HashTable* table) {
    table->buckets = calloc(HASH_TABLE_SIZE, sizeof(Node*));
    if (!table->buckets) {
        perror("Failed to allocate memory for buckets");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->mutexes[i], NULL);
    }
}

void insert_setting(HashTable* table, const char *key, const char *value) {
    uint32_t index = hash_function(key);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->setting.key = strdup(key);
    new_node->setting.value = strdup(value);
    new_node->setting.timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&table->mutexes[index]);
    if (LOCK_FREE) {
        // Implement lock-free insertion logic here
        // For simplicity, using a mutex in this example
    } else {
        new_node->next = table->buckets[index];
        table->buckets[index] = new_node;
    }
    pthread_mutex_unlock(&table->mutexes[index]);
}

void cleanup_expired_settings(HashTable* table) {
    time_t current_time = time(NULL);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table->mutexes[i]);
        Node *prev = NULL, *curr = table->buckets[i];
        while (curr) {
            if (current_time - curr->setting.timestamp > EXPIRY_DURATION) {
                if (prev) {
                    prev->next = curr->next;
                } else {
                    table->buckets[i] = curr->next;
                }
                Node* to_free = curr;
                curr = curr->next;
                free(to_free->setting.key);
                free(to_free->setting.value);
                free(to_free);
            } else {
                prev = curr;
                curr = curr->next;
            }
        }
        pthread_mutex_unlock(&table->mutexes[i]);
    }
}

void* process_yaml_file(void *arg) {
    char *filename = (char*) arg;
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    yaml_document_t doc;
    yaml_parser_t parser;

    if (!yaml_parser_initialize(&parser)) {
        fprintf(stderr, "Failed to initialize YAML parser!\n");
        fclose(file);
        return NULL;
    }

    yaml_parser_set_input_file(&parser, file);

    HashTable table;
    init_hash_table(&table);

    while (1) {
        if (!yaml_parser_parse(&parser, &doc)) {
            fprintf(stderr, "Failed to parse YAML!\n");
            break;
        }

        yaml_node_t *root = doc.data.root_node;

        // Perform schema validation and extraction of settings here
        // Example pseudo-code:
        // if (validate_schema(root)) {
        //     extract_settings_from_yaml(root, &table);
        // }

        yaml_document_delete(&doc);

        if (!yaml_parser_has_more_tokens(&parser))
            break;
    }

    cleanup_expired_settings(&table);

    yaml_parser_delete(&parser);
    fclose(file);

    // Cleanup hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node *curr = table.buckets[i];
        while (curr) {
            Node* to_free = curr;
            curr = curr->next;
            free(to_free->setting.key);
            free(to_free->setting.value);
            free(to_free);
        }
    }

    free(table.buckets);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <yaml_file1> [<yaml_file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[argc - 1];
    for (int i = 1; i < argc; ++i) {
        if (pthread_create(&threads[i-1], NULL, process_yaml_file, argv[i])) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All configurations processed.\n");

    return EXIT_SUCCESS;
}
