            if (seed == 0) break; // Avoid infinite loop
        }

        devices[i].temperature = TEMP_MIN + ((float)rand() / RAND_MAX) * (TEMP_MAX - TEMP_MIN);
        devices[i].humidity = HUMIDITY_MIN + rand() % (HUMIDITY_MAX - HUMIDITY_MIN + 1);
        devices[i].batteryLevel = 100;
        devices[i].lastUpdateTimestamp = time(NULL);
        devices[i].isOnline = true;
    }

    return devices;
