    return (mac[0] & 1) == 0; // Unicast bit check
}

// Function to log updates
void log_update(Device* device, const char* readingType, float value) {
    FILE* logFile = fopen("device_log.txt", "a");
    if (!logFile) return;

    time_t now = time(NULL);
    fprintf(logFile, "%02x:%02x:%02x:%02x:%02x:%02x %s %f %ld\n",
            device->mac[0], device->mac[1], device->mac[2],
            device->mac[3], device->mac[4], device->mac[5],
