    for (int i = 0; i < MAX_DEVICES; ++i) {
        if (devices[i].isOnline) {
            float activityFactor = 1.0f; // Placeholder for actual logic

            devices[i].batteryLevel -= BATTERY_CONSUMPTION_RATE * activityFactor;
            if (!activityFactor && devices[i].batteryLevel < 100) {
                devices[i].batteryLevel += LOW_ACTIVITY_RECHARGE_RATE;
            }

            if (devices[i].batteryLevel > 100) devices[i].batteryLevel = 100;
            if (devices[i].batteryLevel < 0) devices[i].batteryLevel = 0;
        }
    }
}

// Function to handle device disconnections
void update_device_status(Device* devices, unsigned char* offlineMac) {
    for (int i = 0; i < MAX_DEVICES; ++i) {
        if (memcmp(devices[i].mac, offlineMac, 6) == 0) {
            devices[i].isOnline = false;
            log_update(&devices[i], "status", 0);
        }
    }
}

