["Below is a C function that manages dynamic memory allocation and concurrent access for JavaScript files and their metadata. It uses linked lists and hash-based maps for efficient data retrieval and modification while ensuring thread safety with mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define HASH_MAP_SIZE 1024

typedef struct record {
    short field1;
    int field2;
    float field3;
} Record;

typedef struct chunk {
    size_t length;
    uint32_t checksum;
} Chunk;

typedef struct node {
    void *data;
    struct node *next;
} Node;

typedef struct linked_list {
    Node *head;
} LinkedList;

typedef struct hash_map_entry {
    int key;
    void *value;
    struct hash_map_entry *next;
} HashMapEntry;

typedef struct hash_map {
    HashMapEntry **buckets;
    pthread_mutex_t lock;
} HashMap;

void init_linked_list(LinkedList *list) {
    list->head = NULL;
}

Node* create_node(void *data) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void append_to_list(LinkedList *list, void *data) {
    Node *new_node = create_node(data);
    if (!list->head) {
        list->head = new_node;
    } else {
        Node *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void init_hash_map(HashMap *map) {
    map->buckets = (HashMapEntry **)calloc(HASH_MAP_SIZE, sizeof(HashMapEntry *));
    pthread_mutex_init(&map->lock, NULL);
}

uint32_t hash_function(int key) {
    return key % HASH_MAP_SIZE;
}

void insert_into_hash_map(HashMap *map, int key, void *value) {
    uint32_t index = hash_function(key);
    HashMapEntry *new_entry = (HashMapEntry *)malloc(sizeof(HashMapEntry));
    new_entry->key = key;
    new_entry->value = value;
    new_entry->next = NULL;

    pthread_mutex_lock(&map->lock);

    if (!map->buckets[index]) {
        map->buckets[index] = new_entry;
    } else {
        HashMapEntry *current = map->buckets[index];
        while (current->next) {
            current = current->next;
        }
        current->next = new_entry;
    }

    pthread_mutex_unlock(&map->lock);
}

void* retrieve_from_hash_map(HashMap *map, int key) {
    uint32_t index = hash_function(key);

    pthread_mutex_lock(&map->lock);

    HashMapEntry *current = map->buckets[index];
    while (current) {
        if (current->key == key) {
            pthread_mutex_unlock(&map->lock);
            return current->value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void free_linked_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp->data); // Assuming data is dynamically allocated
        free(temp);
    }
    list->head = NULL;
}

void free_hash_map(HashMap *map) {
    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        HashMapEntry *current = map->buckets[i];
        while (current) {
            HashMapEntry *temp = current;
            current = current->next;
            free(temp->value); // Assuming value is dynamically allocated
            free(temp);
        }
    }
    free(map->buckets);
}

void initialize_records_and_chunks(LinkedList *records, HashMap *chunks) {
    for (int i = 0; i < 100; ++i) { // Example size
        Record *record = (Record *)malloc(sizeof(Record));
        record->field1 = rand() % 100;
        record->field2 = rand() % 10000;
        record->field3 = (float)(rand() / (RAND_MAX + 1.0));

        append_to_list(records, record);

        Chunk *chunk = (Chunk *)malloc(sizeof(Chunk));
        chunk->length = rand() % 1024; // Example max length
        chunk->checksum = rand(); // Simple checksum

        insert_into_hash_map(chunks, i, chunk);
    }
}

int main() {
    LinkedList records;
    init_linked_list(&records);

    HashMap chunks;
    init_hash_map(&chunks);

    initialize_records_and_chunks(&records, &chunks);

    free_linked_list(&records);
    free_hash_map(&chunks);

    return 0;
}
```

