```javascript
async function loadAndExecuteFile(filePath) {
    try {
        const response = await fetch(filePath);
        if (!response.ok) throw new Error('Network response was not ok');

        const scriptContent = await response.text();
        const scriptElement = document.createElement('script');
        scriptElement.textContent = scriptContent;
        document.body.appendChild(scriptElement);

        console.log(`Successfully executed ${filePath}`);
    } catch (error) {
        console.error(`Failed to load or execute ${filePath}:`, error);
    }
}

async function manageFileLoading(filePaths) {
    const fileLoadPromises = filePaths.map(filePath => loadAndExecuteFile(filePath));

    try {
        await Promise.all(fileLoadPromises);
    } catch (error) {
        console.error('Error loading files:', error);
    }
