#include <openssl/rand.h>

typedef struct Record {
    short sField;
    int iField;
    float fField;
    struct Record* next;
} Record;

// Thread-safe linked list access
pthread_mutex_t recordListMutex = PTHREAD_MUTEX_INITIALIZER;

Record* headRecord = NULL;

EVP_CIPHER_CTX* init_encryption_context(const char *password, const unsigned char *salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[SHA_DIGEST_LENGTH];
    unsigned int key_len;
    EVP_BytesToKey(EVP_sha1(), EVP_aes_256_cbc(), salt, (unsigned char *)password, strlen(password), 1, key, &key_len);

    if (EVP_CIPHER_CTX_init(ctx) <= 0 || !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, salt)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void free_encryption_context(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->offsets = calloc(initial_capacity, sizeof(long));
    array->keys = malloc(initial_capacity * sizeof(int));
    array->capacity = initial_capacity;
    return array;
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    long *new_offsets = realloc(array->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(array->keys, new_capacity * sizeof(int));

    if (new_offsets && new_keys) {
        array->offsets = new_offsets;
        array->keys = new_keys;
        array->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        free_dynamic_array(array);
        fprintf(stderr, "Failed to resize dynamic arrays\n");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_array(DynamicArray *array) {
    if (array) {
        free(array->offsets);
        free(array->keys);
        free(array);
    }
}

int main() {
    const char *password = "secure_password";
    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));

    EVP_CIPHER_CTX *ctx = init_encryption_context(password, salt);
    if (!ctx) {
        fprintf(stderr, "Encryption context initialization failed\n");
        return EXIT_FAILURE;
    }

    DynamicArray *array = init_dynamic_array(10);

    int unique_key_start = rand() % 1000 + 1; // Ensure uniqueness
    long sum_keys = 0;

    for (size_t i = 0; i < array->capacity; ++i) {
        array->keys[i] = unique_key_start++;
        sum_keys += array->keys[i];
        array->offsets[i] = sum_keys + i * 100; // Example constant value

        pthread_mutex_lock(&recordListMutex);
        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            exit(EXIT_FAILURE);
        }

        new_record->sField = rand() % 100;
        new_record->iField = rand() % 1000;
        new_record->fField = (float)rand() / RAND_MAX * 100.0;
        new_record->next = headRecord;
        headRecord = new_record;

        pthread_mutex_unlock(&recordListMutex);
    }

    // Example of adding more records, triggering a resize
    if (array->capacity == 10) {
        resize_dynamic_array(array);
        array->keys[array->capacity - 1] = unique_key_start++;
        sum_keys += array->keys[array->capacity - 1];
        array->offsets[array->capacity - 1] = sum_keys + (array->capacity - 1) * 100;

        pthread_mutex_lock(&recordListMutex);
        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            exit(EXIT_FAILURE);
        }

        new_record->sField = rand() % 100;
        new_record->iField = rand() % 1000;
        new_record->fField = (float)rand() / RAND_MAX * 100.0;
        new_record->next = headRecord;
        headRecord = new_record;

        pthread_mutex_unlock(&recordListMutex);
    }

    // Free resources
    while (headRecord) {
        Record *temp = headRecord;
        headRecord = headRecord->next;
        free(temp);
    }

    free_dynamic_array(array);
    free_encryption_context(ctx);

    return EXIT_SUCCESS;
}
