// Structure to manage double precision floating-point matrix and hash table
typedef struct {
    double **double_matrix;
    size_t rows, cols;
    Node **hash_table;
    size_t hash_size;
    pthread_mutex_t lock;  // For concurrent modification safety

    // For caching frequently accessed entries
    MatrixEntry *cache;
    size_t cache_capacity;
