// Hash function for the hash table
size_t hash_function(size_t key, size_t hash_size) {
    return key % hash_size;
}

// Function to create and initialize the MatrixManager structure
MatrixManager* init_matrix_manager(size_t initial_rows, size_t initial_cols, size_t hash_size, size_t cache_capacity) {
    MatrixManager *manager = (MatrixManager*)memory_pool_alloc(sizeof(MatrixManager));
    manager->rows = initial_rows;
    manager->cols = initial_cols;
