    for (size_t i = 0; i < initial_rows; ++i) {
        manager->double_matrix[i] = (double*)memory_pool_alloc(initial_cols * sizeof(double));
        for (size_t j = 0; j < initial_cols; ++j) {
            manager->double_matrix[i][j] = (double)(i + j); // Initialize with sum of indices
        }
    }

    manager->hash_size = hash_size;
    manager->hash_table = (Node**)memory_pool_alloc(hash_size * sizeof(Node*));
    for (size_t i = 0; i < hash_size; ++i) {
        manager->hash_table[i] = NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->cache_capacity = cache_capacity;
    manager->cache_count = 0;
    manager->cache = (MatrixEntry*)memory_pool_alloc(cache_capacity * sizeof(MatrixEntry));

    // Open a file to save the state periodically
    manager->state_file = fopen("matrix_state.bin", "wb");
    if (!manager->state_file) {
        external_log("Failed to open state file.");
        return NULL;
    }

    return manager;
}

// Function to free resources held by MatrixManager
void cleanup_matrix_manager(MatrixManager *manager) {
    for (size_t i = 0; i < manager->rows; ++i) {
        memory_pool_free(manager->double_matrix[i]);
    }
    memory_pool_free(manager->double_matrix);

    // Free hash table nodes
    for (size_t i = 0; i < manager->hash_size; ++i) {
        Node *node = manager->hash_table[i];
        while (node) {
            Node *temp = node;
            node = node->next;
            memory_pool_free(temp);
        }
    }
    memory_pool_free(manager->hash_table);

    pthread_mutex_destroy(&manager->lock);

    if (manager->cache) {
        memory_pool_free(manager->cache);
    }

    if (manager->state_file) {
        fclose(manager->state_file);
    }

    memory_pool_free(manager);
}

// Function to dynamically resize the double matrix
void resize_double_matrix(MatrixManager *manager, size_t new_rows, size_t new_cols) {
    pthread_mutex_lock(&manager->lock);

    double **new_matrix = (double**)memory_pool_alloc(new_rows * sizeof(double*));
    for (size_t i = 0; i < new_rows; ++i) {
        new_matrix[i] = (double*)memory_pool_alloc(new_cols * sizeof(double));
        for (size_t j = 0; j < new_cols; ++j) {
            new_matrix[i][j] = (double)(i + j); // Initialize with sum of indices
        }
    }

    for (size_t i = 0; i < manager->rows && i < new_rows; ++i) {
        memory_pool_free(manager->double_matrix[i]);
        if (manager->cols <= new_cols) {
            memcpy(new_matrix[i], manager->double_matrix[i], manager->cols * sizeof(double));
        }
    }

    memory_pool_free(manager->double_matrix);
    manager->double_matrix = new_matrix;
    manager->rows = new_rows;
    manager->cols = new_cols;

    pthread_mutex_unlock(&manager->lock);
}

// Function to populate hash table with random values
void populate_hash_table(MatrixManager *manager) {
    srand(time(NULL));  // Seed for randomness

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->hash_size; ++i) {
        Node *node = (Node*)memory_pool_alloc(sizeof(Node));
        node->key = i;
        node->entry.s_value = rand() % 1000;  // Random short
        node->entry.i_value = rand() % 1000000;  // Random int
        node->entry.f_value = ((float)rand()) / RAND_MAX * 100.0f;  // Random float

        size_t hash_index = hash_function(node->key, manager->hash_size);
        node->next = manager->hash_table[hash_index];
        manager->hash_table[hash_index] = node;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to log changes with timestamp and user ID
void log_change(MatrixManager *manager, const char *message, int user_id) {
    extern void external_log(const char *);  // External logging interface

    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", info);
    snprintf(manager->log_message, sizeof(manager->log_message),
             "[%s] User ID: %d - %s", buffer, user_id, message);

    external_log(manager->log_message);
}

// Function to save the current state periodically
void save_state(MatrixManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (fwrite(manager->double_matrix, sizeof(double), manager->rows * manager->cols, manager->state_file) !=
        manager->rows * manager->cols) {
        external_log("Failed to write double matrix to state file.");
    }

    // Example save structure for hash table; implement serialization as needed
    size_t num_entries = 0;
    Node **node_list = (Node**)memory_pool_alloc(manager->hash_size * sizeof(Node*));
    for (size_t i = 0; i < manager->hash_size; ++i) {
        Node *node = manager->hash_table[i];
        while (node) {
            node_list[num_entries++] = node;
            node = node->next;
        }
    }

    // Serialize hash table nodes
    for (size_t i = 0; i < num_entries; ++i) {
        fwrite(&node_list[i]->key, sizeof(size_t), 1, manager->state_file);
        fwrite(&(node_list[i]->entry), sizeof(MatrixEntry), 1, manager->state_file);
    }

    memory_pool_free(node_list);
    fflush(manager->state_file);

    pthread_mutex_unlock(&manager->lock);
}

// Main entry function for the task
void manage_matrices() {
    MatrixManager *manager = init_matrix_manager(10, 10, 100, 50);
    if (!manager) return;

    populate_hash_table(manager);
    resize_double_matrix(manager, 20, 20); // Example of resizing

    save_state(manager);

    cleanup_matrix_manager(manager);
}
