#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the file metadata structure
typedef struct {
    char *file_name;
    time_t last_modified;
    unsigned long file_size;
} FileMetadata;

// Define the list node and list structures
typedef struct Node {
    FileMetadata data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} MetadataList;

// Function prototypes
MetadataList* create_list(void);
void destroy_list(MetadataList* list);
int add_or_update_entry(MetadataList* list, const char *file_name, time_t last_modified, unsigned long file_size);
void sort_by_file_size(MetadataList* list);
void sort_by_last_modified(MetadataList* list);

// Helper function to find a node by file name
static Node* find_node(Node* head, const char *file_name) {
    while (head != NULL) {
        if (strcmp(head->data.file_name, file_name) == 0)
            return head;
        head = head->next;
    }
    return NULL;
}

// Create and initialize the metadata list
MetadataList* create_list(void) {
    MetadataList* list = malloc(sizeof(MetadataList));
    if (!list) {
        perror("Failed to allocate memory for metadata list");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the metadata list and free resources
void destroy_list(MetadataList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.file_name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new entry or update an existing one
int add_or_update_entry(MetadataList* list, const char *file_name, time_t last_modified, unsigned long file_size) {
    pthread_mutex_lock(&list->lock);

    Node* node = find_node(list->head, file_name);
    if (node != NULL) {
        // Update existing entry
        free(node->data.file_name);  // Free the old file name
        node->data.last_modified = last_modified;
        node->data.file_size = file_size;

        // Allocate new memory for updated file name and copy it
        node->data.file_name = strdup(file_name);
        if (!node->data.file_name) {
            perror("Failed to allocate memory for file name");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    } else {
        // Add new entry
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        new_node->data.file_name = strdup(file_name);
        if (!new_node->data.file_name) {
            free(new_node);  // Clean up
            perror("Failed to allocate memory for file name");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        new_node->data.last_modified = last_modified;
        new_node->data.file_size = file_size;
        new_node->next = list->head;
        list->head = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Sort the list by file size
void sort_by_file_size(MetadataList* list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *i, *j;
    for (i = list->head; i != NULL && i->next != NULL; i = i->next) {
        for (j = i->next; j != NULL; j = j->next) {
            if (i->data.file_size > j->data.file_size) {
                // Swap metadata
                FileMetadata temp = i->data;
                i->data = j->data;
                j->data = temp;

                // Swap file names
                char* temp_name = i->data.file_name;
                i->data.file_name = j->data.file_name;
                j->data.file_name = temp_name;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Sort the list by last modified timestamp
void sort_by_last_modified(MetadataList* list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *i, *j;
    for (i = list->head; i != NULL && i->next != NULL; i = i->next) {
        for (j = i->next; j != NULL; j = j->next) {
            if (i->data.last_modified < j->data.last_modified) {
                // Swap metadata
                FileMetadata temp = i->data;
                i->data = j->data;
                j->data = temp;

                // Swap file names
                char* temp_name = i->data.file_name;
                i->data.file_name = j->data.file_name;
                j->data.file_name = temp_name;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}
