#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1048576 // Example: 1MB limit
#define CACHE_SIZE 100

typedef struct {
    int value;
} Record;

typedef struct Node {
    int key;
    Record *record;
    struct Node* next;
} Node;

typedef struct {
    Node** keys_array;
    int size;
    int capacity;
    pthread_mutex_t lock;
    FILE* log_file;
    Node* cache_head;
    Node* cache_tail;
    size_t current_memory_usage;
} KeyRecordManager;

KeyRecordManager* create_manager(int initial_capacity, const char* log_filename) {
    KeyRecordManager* manager = (KeyRecordManager*)malloc(sizeof(KeyRecordManager));
    if (!manager) return NULL;

    manager->keys_array = (Node**)calloc(initial_capacity, sizeof(Node*));
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        free(manager);
        return NULL;
    }
    manager->cache_head = manager->cache_tail = NULL;
    manager->current_memory_usage = 0;

    return manager;
}

void log_error(KeyRecordManager* manager, const char* message) {
    if (manager && manager->log_file)
        fprintf(manager->log_file, "%s\n", message);
}

int allocate_memory(KeyRecordManager* manager, size_t bytes_needed) {
    if ((manager->current_memory_usage + bytes_needed) > MAX_MEMORY_USAGE) {
        log_error(manager, "Memory limit exceeded");
        return 0;
    }
    manager->current_memory_usage += bytes_needed;
    return 1;
}

Node* fetch_from_cache(KeyRecordManager* manager) {
    pthread_mutex_lock(&manager->lock);
    Node* node = NULL;

    if (manager->cache_head) {
        node = manager->cache_head;
        manager->cache_head = node->next;
        if (!manager->cache_head)
            manager->cache_tail = NULL;
        memset(node, 0, sizeof(Node)); // Reset for reuse
    }

    pthread_mutex_unlock(&manager->lock);
    return node;
}

void add_to_cache(KeyRecordManager* manager, Node* node) {
    pthread_mutex_lock(&manager->lock);

    if (manager->cache_tail) {
        manager->cache_tail->next = node;
    } else {
        manager->cache_head = node;
    }
    manager->cache_tail = node;
    node->next = NULL;

    pthread_mutex_unlock(&manager->lock);
}

int insert_record(KeyRecordManager* manager, int key, int value) {
    if (!allocate_memory(manager, sizeof(Record))) return 0;

    Node* node = fetch_from_cache(manager);
    if (!node) {
        node = (Node*)malloc(sizeof(Node));
        if (!node) {
            log_error(manager, "Memory allocation failed for new node");
            return 0;
        }
    }

    node->key = key;
    node->record = (Record*)malloc(sizeof(Record));
    if (!node->record) {
        log_error(manager, "Memory allocation failed for record");
        add_to_cache(manager, node);
        return 0;
    }

    node->record->value = value;
    pthread_mutex_lock(&manager->lock);

    int index = key % manager->capacity;
    while (manager->keys_array[index]) {
        if (manager->keys_array[index]->key == key) { // Handle duplicate keys
            free(node->record);
            add_to_cache(manager, node);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        index = (index + 1) % manager->capacity;
    }

    manager->keys_array[index] = node;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);

    return 1;
}

Record* get_record(KeyRecordManager* manager, int key) {
    if (!manager || !key) return NULL;

    pthread_mutex_lock(&manager->lock);
    int index = key % manager->capacity;
    Node* node = manager->keys_array[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&manager->lock);
            return node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int delete_record(KeyRecordManager* manager, int key) {
    if (!manager || !key) return 0;

    pthread_mutex_lock(&manager->lock);

    int index = key % manager->capacity;
    Node** curr = &manager->keys_array[index];
    while (*curr) {
        if ((*curr)->key == key) {
            Node* to_delete = *curr;
            *curr = to_delete->next;
            free(to_delete->record);
            add_to_cache(manager, to_delete);
            manager->current_memory_usage -= sizeof(Record);
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_manager(KeyRecordManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->capacity; ++i) {
        Node* node = manager->keys_array[i];
        while (node) {
            Node* to_delete = node;
            node = node->next;
            free(to_delete->record);
            add_to_cache(manager, to_delete);
        }
    }

    pthread_mutex_unlock(&manager->lock);

    if (manager->keys_array)
        free(manager->keys_array);
    if (manager->log_file)
        fclose(manager->log_file);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}
