#include <pthread.h>

#define MAX_NAME_LENGTH 256
#define RETRY_LIMIT_PUT 3
#define RETRY_LIMIT_DELETE 5

typedef struct {
    char file_name[MAX_NAME_LENGTH];
    time_t last_modified;
    unsigned long file_size;
} FileMetadata;

typedef struct Node {
    FileMetadata data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t mutex;
} FileList;

FileList* create_file_list() {
    FileList *list = (FileList*)malloc(sizeof(FileList));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_file_list(FileList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_or_update_metadata(FileList *list, const char *file_name, time_t last_modified, unsigned long file_size) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current) {
        if (strcmp(current->data.file_name, file_name) == 0) {
            current->data.last_modified = last_modified;
            current->data.file_size = file_size;
            pthread_mutex_unlock(&list->mutex);
            return 1; // Updated
        }
        current = current->next;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    strcpy(new_node->data.file_name, file_name);
    new_node->data.last_modified = last_modified;
    new_node->data.file_size = file_size;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Added
}

FileMetadata* retrieve_metadata(FileList *list, const char *file_name) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current) {
        if (strcmp(current->data.file_name, file_name) == 0) {
            FileMetadata *metadata = &current->data;
            pthread_mutex_unlock(&list->mutex);
            return metadata;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL; // Not found
}

void sort_metadata(FileList *list, int by_size) {
    pthread_mutex_lock(&list->mutex);

    if (!list->head || !list->head->next) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    Node *sorted = NULL;

    while (list->head) {
        Node **min = &list->head;
        Node *current = list->head;
        Node *prev = NULL;

        while (current->next) {
            if ((by_size && current->next->data.file_size < (*min)->data.file_size) ||
                (!by_size && current->next->data.last_modified < (*min)->data.last_modified)) {
                min = &current->next;
            }
            current = current->next;
        }

        Node *temp = *min;
        if (prev) prev->next = temp->next;
        else list->head = temp->next;

        temp->next = sorted;
        sorted = temp;
    }

    list->head = sorted;

    pthread_mutex_unlock(&list->mutex);
}

int http_put_with_retries(const char *url, FileMetadata *metadata) {
    int attempts = 0;
    while (attempts < RETRY_LIMIT_PUT) {
