// Implementations

Node* create_node(const char *file_name, time_t last_modified, unsigned long file_size) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data.file_name = strdup(file_name);
    new_node->data.last_modified = last_modified;
    new_node->data.file_size = file_size;
    new_node->next = NULL;

    return new_node;
}

void free_list(Node *head) {
