    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp->data.file_name);
        free(tmp);
    }
}

FileMetadata* get_file_metadata(Node *head, const char *file_name) {
    for (Node *current = head; current != NULL; current = current->next) {
        if (strcmp(current->data.file_name, file_name) == 0) {
            return &(current->data);
        }
    }
    return NULL;
}

void update_file_metadata(Node **head, const FileMetadata *metadata) {
    pthread_rwlock_wrlock(&rw_lock); // Assuming rw_lock is defined globally
    Node *current = *head, *prev = NULL;
    while (current != NULL && strcmp(current->data.file_name, metadata->file_name) != 0) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) { // Not found, add new node
        Node *new_node = create_node(metadata->file_name, metadata->last_modified, metadata->file_size);
        if (prev == NULL) {
            new_node->next = *head;
            *head = new_node;
        } else {
            new_node->next = prev->next;
            prev->next = new_node;
        }
    } else { // Update existing node
        current->data.last_modified = metadata->last_modified;
        current->data.file_size = metadata->file_size;
    }
    pthread_rwlock_unlock(&rw_lock);
}

LockFreeHashTable* create_hash_table(size_t size) {
    LockFreeHashTable *hash_table = (LockFreeHashTable *)malloc(sizeof(LockFreeHashTable));
    if (!hash_table) return NULL;

    hash_table->buckets = (HashEntry **)calloc(size, sizeof(HashEntry *));
    if (!hash_table->buckets) {
        free(hash_table);
        return NULL;
    }
    hash_table->size = size;
    pthread_rwlock_init(&hash_table->lock, NULL);

    return hash_table;
}

void hash_insert(LockFreeHashTable *hash_table, const char *key, const char *value) {
    size_t index = strlen(key) % hash_table->size;
    HashEntry *new_entry = (HashEntry *)malloc(sizeof(HashEntry));
    if (!new_entry) return;

    new_entry->key = strdup(key);
    new_entry->value = strdup(value);
    new_entry->last_update = time(NULL);
    new_entry->next = NULL;

    pthread_rwlock_wrlock(&hash_table->lock);
    new_entry->next = hash_table->buckets[index];
    hash_table->buckets[index] = new_entry;
    pthread_rwlock_unlock(&hash_table->lock);
}

char* hash_lookup(LockFreeHashTable *hash_table, const char *key) {
    size_t index = strlen(key) % hash_table->size;

    pthread_rwlock_rdlock(&hash_table->lock);
    HashEntry *entry = hash_table->buckets[index];
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            char *value_copy = strdup(entry->value);
            pthread_rwlock_unlock(&hash_table->lock);
            return value_copy;
        }
        entry = entry->next;
    }
    pthread_rwlock_unlock(&hash_table->lock);

    return NULL;
}

void free_hash_table(LockFreeHashTable *hash_table) {
    for (size_t i = 0; i < hash_table->size; ++i) {
        HashEntry *entry = hash_table->buckets[i];
        while (entry != NULL) {
            HashEntry *temp = entry;
            entry = entry->next;
            free(temp->key);
            free(temp->value);
            free(temp);
        }
    }
    free(hash_table->buckets);
    pthread_rwlock_destroy(&hash_table->lock);
    free(hash_table);
}

ConfigParser* load_config(const char *filename) {
    ConfigParser *config_parser = (ConfigParser *)malloc(sizeof(ConfigParser));
    if (!config_parser) return NULL;

    json_error_t error;
    config_parser->root = json_load_file(filename, 0, &error);
    if (!config_parser->root) {
        free(config_parser);
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    return config_parser;
}

void free_config(ConfigParser *config_parser) {
    if (config_parser) {
        json_decref(config_parser->root);
        free(config_parser);
    }
}

json_t* get_json_node(ConfigParser *config_parser, const char *path) {
    char *sub_path = strdup(path);
    json_t *node = json_object_get(config_parser->root, sub_path);
    free(sub_path);

    if (!node && strcmp(path, "root") != 0) { // Handle non-existing nodes gracefully
        fprintf(stderr, "JSON path %s not found\n", path);
    }

    return node;
}

void manage_memory(void **ptr, size_t size) {
    void *new_ptr = realloc(*ptr, size);
    if (!new_ptr && size > 0) {
        fprintf(stderr, "Memory allocation failed for size %zu\n", size);
        exit(EXIT_FAILURE);
    }
    *ptr = new_ptr;
}

StorageManager* init_storage_manager() {
    StorageManager *manager = (StorageManager *)malloc(sizeof(StorageManager));
    if (!manager) return NULL;

    manager->file_metadata_list = NULL;
    pthread_rwlock_init(&rw_lock, NULL); // Assuming rw_lock is defined globally
    manager->settings_table = create_hash_table(INITIAL_HASH_SIZE);

    return manager;
}

void free_storage_manager(StorageManager *manager) {
    if (manager) {
        free_list(manager->file_metadata_list);
        free_hash_table(manager->settings_table);
        pthread_rwlock_destroy(&rw_lock); // Assuming rw_lock is defined globally
