['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

#define MAX_MEMORY_SIZE 1048576 // 1 MB limit for offsets and keys combined

record* manage_memory(int p) {
    if (p <= 0) return NULL;

    long *offsets = NULL;
    int *keys = NULL;
    size_t offset_size, key_size;

    record *records = malloc(p * sizeof(record));
    if (!records) return NULL; // Initial allocation for records

    size_t current_record_count = 0;
    const size_t initial_alloc_size = 10;

    while (current_record_count < p) {
        // Determine the new sizes required
        offset_size = (current_record_count + 1) * sizeof(long);
        key_size = (current_record_count + 1) * sizeof(int);

        if ((offset_size + key_size) > MAX_MEMORY_SIZE) {
            fprintf(stderr, "Memory limit exceeded.\n");
            free(records);
            return NULL;
        }

        // Attempt to allocate memory with backoff strategy
        for (int retry = 0; retry < 5; ++retry) {
            long *new_offsets = realloc(offsets, offset_size);
            int *new_keys = realloc(keys, key_size);

            if (new_offsets && new_keys) {
                offsets = new_offsets;
                keys = new_keys;

                // Initialize the newly allocated memory
                if (new_offsets + current_record_count == offsets) {
                    memset(new_offsets + current_record_count, 0, sizeof(long));
                }
                if (new_keys + current_record_count == keys) {
                    memset(new_keys + current_record_count, 0, sizeof(int));
                }

                // Set up the new record
                records[current_record_count].offset_ptr = offsets + current_record_count;
                records[current_record_count].key_ptr = keys + current_record_count;

                ++current_record_count;
                break;
            } else {
                fprintf(stderr, "Memory allocation failed. Retrying...\n");
                if (retry == 4) { // If all retries fail
                    free(records);
                    free(offsets); 
                    free(keys);
                    return NULL;
                }
                sleep(1 << retry); // Exponential backoff strategy
            }
        }
    }

    return records;
}

int main() {
    int p = 20; // Example size
    record *records = manage_memory(p);

    if (records) {
        printf("Memory management successful.\n");
        free(records);
    } else {
        fprintf(stderr, "Failed to allocate memory for records.\n");
    }

    return 0;
}
