typedef struct {
    double temperature;
    double humidity;
    char *location;
} EnvironmentalRecord;

typedef struct {
    EnvironmentalRecord *records;
    size_t capacity;
    size_t size;
} RecordArray;

#define INITIAL_CAPACITY 1000

void free_records(RecordArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i].location);
    }
    free(array->records);
}

int init_record_array(RecordArray *array, size_t initial_capacity) {
    if (initial_capacity == 0) return -1;

    array->capacity = initial_capacity;
    array->size = 0;

    array->records = malloc(sizeof(EnvironmentalRecord) * initial_capacity);
    if (!array->records) return -1;

    for (size_t i = 0; i < initial_capacity; ++i) {
        array->records[i].location = NULL;
    }

    return 0;
}

int resize_record_array(RecordArray *array, size_t new_capacity) {
    EnvironmentalRecord *new_records = realloc(array->records, sizeof(EnvironmentalRecord) * new_capacity);
    if (!new_records) return -1;

    array->records = new_records;
    array->capacity = new_capacity;

    for (size_t i = array->size; i < new_capacity; ++i) {
        array->records[i].location = NULL;
    }

    return 0;
}

int add_record(RecordArray *array, double temperature, double humidity, const char *location) {
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (resize_record_array(array, new_capacity)) return -1;
    }

    EnvironmentalRecord *record = &array->records[array->size];
    record->temperature = temperature;
    record->humidity = humidity;

    record->location = malloc(strlen(location) + 1);
    if (!record->location) return -1;
    strcpy(record->location, location);

    array->size++;

    return 0;
}

int get_record_by_location(RecordArray *array, const char *location, double *temperature, double *humidity) {
    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->records[i].location, location) == 0) {
            *temperature = array->records[i].temperature;
            *humidity = array->records[i].humidity;
            return 1;
        }
    }

    return 0;
}

void cleanup_record_array(RecordArray *array) {
    free_records(array);
    array->capacity = 0;
    array->size = 0;
}
