data_structure* initialize_data(int num_elements, int range_min, int range_max) {
    if (range_min >= range_max || num_elements <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    data_structure *ds = malloc(sizeof(data_structure));
    if (!ds) {
        perror("Failed to allocate memory for data structure.");
        return NULL;
    }

    ds->offsets = calloc(num_elements, sizeof(long));
    ds->keys = calloc(num_elements, sizeof(int));
    ds->records = malloc(num_elements * sizeof(record));

    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory for arrays or records.");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->min_key = INT_MAX;
    ds->max_key = INT_MIN;

    pthread_mutex_init(&ds->mutex, NULL);

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_elements; ++i) {
        int value = rand() % (range_max - range_min + 1) + range_min;

        ds->records[i].value = value;

        pthread_mutex_lock(&ds->mutex);
        if (value < ds->min_key) ds->min_key = value;
        if (value > ds->max_key) ds->max_key = value;
        pthread_mutex_unlock(&ds->mutex);

        // Example of setting key, replace with actual logic as needed
        ds->keys[i] = i; 
    }

    return ds;
}

void cleanup_data(data_structure *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->mutex);
        free(ds);
    }
}
```

### Key Points:
- **Memory Allocation**: Uses `malloc` and `calloc` for dynamic memory allocation.
- **Random Number Generation**: Ensures randomness with `srand` seeded by the current time, and values are generated within a specified range.
- **Thread Safety**: Utilizes a mutex (`pthread_mutex_t`) to protect shared data during updates, preventing race conditions.
- **Error Handling**: Checks for invalid input parameters and allocation failures, printing appropriate error messages.
- **Resource Management**: Includes cleanup function `cleanup_data` to free allocated memory and destroy mutexes.']

