#include <string.h>
#include <time.h>

typedef struct {
    char *buffer;
    int value;
    int initialized;
} record_t;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

Node* create_node(void *data) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void free_list(Node **head) {
    Node *current = *head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int resize_array(void **array, size_t element_size, size_t new_size, size_t old_size) {
    void *new_data = realloc(*array, new_size * element_size);
    if (!new_data) return 0;
    *array = new_data;
    memset((char *)*array + old_size * element_size, 0, (new_size - old_size) * element_size);
    return 1;
}

void free_record(record_t *record) {
    if (record && record->buffer) {
        free(record->buffer);
        record->buffer = NULL;
    }
}

int allocate_memory(long **offset_array, int **key_array, record_t ***records_array,
                    size_t initial_size, size_t buffer_size, const char *default_string,
                    int min_value, int max_value, Node **error_log) {
    if (initial_size == 0 || buffer_size == 0) return 0;

    srand(time(NULL));

    // Allocate and initialize offset array
    long *offset_array_data = malloc(initial_size * sizeof(long));
    if (!offset_array_data) {
        log_error(error_log, "Failed to allocate memory for offset array");
        return 0;
    }
    *offset_array = offset_array_data;

    // Allocate and initialize key array
    int *key_array_data = malloc(initial_size * sizeof(int));
    if (!key_array_data) {
        log_error(error_log, "Failed to allocate memory for key array");
        free(offset_array_data);
        return 0;
    }
    *key_array = key_array_data;

    // Allocate and initialize records array
    record_t **records_array_data = malloc(initial_size * sizeof(record_t *));
    if (!records_array_data) {
        log_error(error_log, "Failed to allocate memory for records array");
        free(offset_array_data);
        free(key_array_data);
        return 0;
    }
    *records_array = records_array_data;

    int random_values[initial_size];
    // Optimize random number generation
    for (size_t i = 0; i < initial_size; ++i) {
        random_values[i] = min_value + rand() % (max_value - min_value + 1);
    }

    for (size_t i = 0; i < initial_size; ++i) {
        record_t *record = malloc(sizeof(record_t));
        if (!record) {
            log_error(error_log, "Failed to allocate memory for a record");
            // Free previously allocated resources
            while (i--) free_record(*records_array_data++);
            free(records_array_data);
            free(key_array_data);
            free(offset_array_data);
            return 0;
        }
        *records_array_data++ = record;

        char *buffer = malloc(buffer_size);
        if (!buffer) {
            log_error(error_log, "Failed to allocate memory for buffer");
            // Free previously allocated resources
            while (i--) free_record(*(--records_array_data));
            free(records_array_data);
            free(key_array_data);
            free(offset_array_data);
            return 0;
        }
        strncpy(buffer, default_string, buffer_size - 1);
        buffer[buffer_size - 1] = '\0';

        record->buffer = buffer;
        record->value = random_values[i];
        record->initialized = 1;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < initial_size; ++i) {
        (*offset_array)[i] = i * sizeof(record_t *);
        (*key_array)[i] = rand() % 100; // Placeholder key value
    }

    return 1;
}

void update_record(record_t *record, const char *new_string, int new_value) {
    if (!record || !record->buffer) return;

    size_t buffer_size = strlen(new_string) + 1;
    char *new_buffer = realloc(record->buffer, buffer_size);
    if (new_buffer) {
        strncpy(new_buffer, new_string, buffer_size - 1);
        new_buffer[buffer_size - 1] = '\0';
        record->buffer = new_buffer;
    } else {
        log_error(NULL, "Failed to update buffer for a record");
    }

    record->value = new_value;
}

void free_resources(long *offset_array, int *key_array, record_t **records_array,
                    size_t records_count, Node **error_log) {
    if (!records_array) return;

    for (size_t i = 0; i < records_count; ++i) {
        free_record(records_array[i]);
    }
    free(records_array);

    free(offset_array);
    free(key_array);
}

void log_error(Node **log, const char *message) {
    if (!log || !message) return;
    Node *error_node = create_node(strdup(message));
    if (error_node) {
        error_node->next = *log;
        *log = error_node;
    }
}

int main() {
    Node *error_log = NULL;

    long *offset_array;
    int *key_array;
    record_t **records_array;
    size_t initial_size = 10;
    size_t buffer_size = 50;
    const char *default_string = "Default String";

    if (!allocate_memory(&offset_array, &key_array, &records_array,
                         initial_size, buffer_size, default_string, 1, 100, &error_log)) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Example of partial update
    const char *new_string = "Updated String";
    int new_value = 42;
    if (records_array) {
        update_record(records_array[0], new_string, new_value);
    }

    free_resources(offset_array, key_array, records_array, initial_size, &error_log);

    // Print error log
    Node *current = error_log;
    while (current) {
        printf("Error: %s\n", (char *)current->data);
        current = current->next;
    }
    free_list(&error_log);

    return 0;
}
