#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Error codes
#define MEMORY_ALLOCATION_ERROR -1
#define INVALID_RANGE_ERROR -2

// Record structure
typedef struct {
    int value;
} record;

// Hash table entry
typedef struct {
    int key;
    pthread_mutex_t lock;  // For thread-safe operations
} hash_entry;

// Structure to track min and max values
typedef struct {
    int min_value;
    int max_value;
    pthread_mutex_t lock;
} range_tracker;

void *allocate_and_initialize_data(void *args) {
    size_t num_elements = *(size_t *)args;
    if (num_elements <= 0) return (void *)(intptr_t)INVALID_RANGE_ERROR;

    long *offsets = malloc(num_elements * sizeof(long));
    int *keys = malloc(num_elements * sizeof(int));
    record *records = malloc(num_elements * sizeof(record));
    hash_entry *hash_table = calloc(num_elements, sizeof(hash_entry));
    range_tracker tracker = {INT_MAX, INT_MIN, PTHREAD_MUTEX_INITIALIZER};

    if (!offsets || !keys || !records || !hash_table) {
        free(offsets);
        free(keys);
        free(records);
        free(hash_table);
        return (void *)(intptr_t)MEMORY_ALLOCATION_ERROR;
    }

    srand((unsigned int)time(NULL));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&mutex);

        // Generate unique offset
        offsets[i] = rand();

        // Generate unique key with minimal collision using a simple hash approach
        int seed = rand();
        keys[i] = ((seed << 5) + (seed >> 27)) % num_elements; 

        do {
            pthread_mutex_lock(&hash_table[keys[i]].lock);
            if (!hash_table[keys[i]].key) { // If slot is empty
                hash_table[keys[i]].key = keys[i];
                break;
            }
            pthread_mutex_unlock(&hash_table[keys[i]].lock);

            // Linear probing in case of collision
            keys[i] = (keys[i] + 1) % num_elements;
        } while (1);
        pthread_mutex_unlock(&hash_table[keys[i]].lock);

        // Initialize records with random unique values
        int record_value;
        do {
            record_value = rand() % 100; // Assuming range is 0-99 for example
        } while ((i > 0 && records[i - 1].value == record_value) || (record_value < tracker.min_value && i != 0));

        records[i].value = record_value;

        // Update min and max values in a thread-safe manner
        pthread_mutex_lock(&tracker.lock);
        if (record_value < tracker.min_value)
            tracker.min_value = record_value;
        if (record_value > tracker.max_value)
            tracker.max_value = record_value;
        pthread_mutex_unlock(&tracker.lock);

        pthread_mutex_unlock(&mutex);
    }

    // Cleanup and return
    free(offsets);
    free(keys);
    free(records);
    free(hash_table);

    pthread_mutex_destroy(&mutex);

    printf("Min value: %d, Max value: %d\n", tracker.min_value, tracker.max_value);

    return NULL;
}

int main() {
    size_t num_elements = 1000; // Example number of elements

    pthread_t thread_id;
    int result = pthread_create(&thread_id, NULL, allocate_and_initialize_data, &num_elements);
    if (result != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    void *return_value;
    result = pthread_join(thread_id, &return_value);

    if ((intptr_t)return_value == MEMORY_ALLOCATION_ERROR || (intptr_t)return_value == INVALID_RANGE_ERROR) {
        fprintf(stderr, "Error during data allocation and initialization: %d\n", (intptr_t)return_value);
        return EXIT_FAILURE;
    }

    printf("Data allocation and initialization completed successfully.\n");
    return 0;
}
