#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t count; // Number of initialized records
    size_t capacity; // Total allocated space for records
    pthread_mutex_t lock; // Mutex for thread-safe access
    record *records; // Dynamic array of records
} RecordArray;

// Function prototypes
RecordArray* create_record_array(size_t initial_capacity);
void destroy_record_array(RecordArray *arr);
int resize_and_initialize_records(RecordArray *arr, size_t new_capacity, int (*seed_func)(size_t index));
void update_random_value_range(RecordArray *arr, int (*new_seed_func)(size_t index));

// Thread-safe function to create a record array
RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *arr = (RecordArray*)malloc(sizeof(RecordArray));
    if (!arr) return NULL;

    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    arr->capacity = initial_capacity;
    arr->records = (record*)calloc(arr->capacity, sizeof(record));

    return arr;
}

// Function to destroy a record array
void destroy_record_array(RecordArray *arr) {
    if (!arr) return;

    pthread_mutex_destroy(&arr->lock);
    free(arr->records);
    free(arr);
}

// Resize and initialize records with a seed function
int resize_and_initialize_records(RecordArray *arr, size_t new_capacity, int (*seed_func)(size_t index)) {
    if (!arr || !seed_func) return -1;

    pthread_mutex_lock(&arr->lock);

    record *new_records = (record*)realloc(arr->records, new_capacity * sizeof(record));
    if (!new_records) {
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    size_t min_count = arr->count < new_capacity ? arr->count : new_capacity;
    for (size_t i = 0; i < min_count; ++i) {
        new_records[i].value = seed_func(i);
    }
    for (size_t i = min_count; i < new_capacity; ++i) {
        new_records[i].value = seed_func(i);
    }

    arr->records = new_records;
    arr->capacity = new_capacity;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Update the random value generation logic
void update_random_value_range(RecordArray *arr, int (*new_seed_func)(size_t index)) {
    if (!arr || !new_seed_func) return;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        arr->records[i].value = new_seed_func(i);
    }

    pthread_mutex_unlock(&arr->lock);
}

// Example seed function
int example_seed_function(size_t index) {
    return (index * 31) % 100;
}
