void manage_record_storage(size_t array_size, size_t num_records, size_t max_char_length) {
    if (array_size <= 0 || num_records < 0 || max_char_length == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    // Calculate memory requirements
    size_t offset_array_memory = array_size * sizeof(long);
    size_t key_array_memory = array_size * sizeof(int);
    size_t record_memory = num_records * (sizeof(record) + max_char_length);

    // Check if the total memory exceeds system threshold
    if ((offset_array_memory + key_array_memory + record_memory) > MAX_SYSTEM_MEMORY) {
        fprintf(stderr, "Memory allocation would exceed system limits.\n");
        return;
    }

    // Seed random number generator
    srand(time(NULL));

    long *offsets = (long *)malloc(offset_array_memory);
    int *keys = (int *)malloc(key_array_memory);

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed for offsets or keys.\n");
        free(offsets); // Free what was allocated
        free(keys);
        return;
    }

    record *records = (record *)calloc(num_records, sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
