    fprintf(stderr, "Error: %s\n", message);
}

int initialize_data_structures(int offset_size, int key_size, 
                               long double **offset_array, 
                               long double **key_array, 
                               struct record ***record_array) {

    if (offset_size <= 0 || key_size <= 0) {
        log_error("Invalid array sizes");
        *offset_array = NULL;
        *key_array = NULL;
        *record_array = NULL;
        return -1; // Error status
    }

    int min_size = offset_size < key_size ? offset_size : key_size;

    // Allocate a single block of memory for both arrays to minimize fragmentation
    long double *memory_block = (long double *)malloc((offset_size + key_size) * sizeof(long double));
    if (!memory_block) {
        log_error("Memory allocation failed");
        *offset_array = NULL;
        *key_array = NULL;
        *record_array = NULL;
        return -1; // Error status
    }

    // Initialize offset_array and key_array within the memory block
    *offset_array = &memory_block[0];
    *key_array = &memory_block[offset_size];

    for (int i = 0; i < offset_size; ++i) {
        (*offset_array)[i] = rand() / (long double)RAND_MAX * 1000001;
    }

    for (int j = 0; j < key_size; ++j) {
        (*key_array)[j] = (rand() % 2000001 - 1000000);
    }

    // Allocate memory for record_array
    struct record *record_memory = (struct record *)malloc(min_size * sizeof(struct record));
    if (!record_memory) {
        log_error("Memory allocation failed for records");
        free(memory_block); // Clean up previous allocations
        *offset_array = NULL;
        *key_array = NULL;
        *record_array = NULL;
        return -1; // Error status
    }

    *record_array = &record_memory[0];
    for (int k = 0; k < min_size; ++k) {
        (*record_array)[k].value = rand() % 1000001 - 500000;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    return 0; // Success status
}

void free_resources(long double *offset_array, long double *key_array, struct record **record_array) {
    if (offset_array && key_array) {
        free(offset_array); // Free the combined memory block
    }
    if (record_array && *record_array) {
        free(*record_array);
    }
}

int main() {
    int offset_size = 1000; // Example size, replace with user input as needed
    int key_size = 2000;    // Example size, replace with user input as needed

    long double *offset_array = NULL;
    long double *key_array = NULL;
    struct record **record_array = NULL;

    if (initialize_data_structures(offset_size, key_size, 
                                   &offset_array, &key_array, 
                                   &record_array) != 0) {
        log_error("Initialization failed");
    } else {
        // Use the arrays as needed...

        // Free allocated resources
        free_resources(offset_array, key_array, record_array);
    }

    return 0;
}
