int allocateAndInitialize(int offsetSize, int keySize, int cacheMaxSize) {
    // Validate user input
    if (offsetSize <= 0 || keySize <= 0 || cacheMaxSize <= 0) {
        return -1;
    }

    initializeRandomNumberGenerator();

    // Allocate and initialize arrays
    long* offset_array = malloc(offsetSize * sizeof(long));
    int* key_array = malloc(keySize * sizeof(int));

    if (!offset_array || !key_array) {
        free(offset_array);
        free(key_array);
        return -1;
    }

