        offset_array[i] = generateRandomLong();
    }

    for (int j = 0; j < keySize; ++j) {
        key_array[j] = generateRandomInt(-1000000, 1000000);
    }

    // Determine the size of the record array
    int recordSize = offsetSize < keySize ? offsetSize : keySize;

    Record* head = createLinkedList(recordSize);

    if (!head) {
        free(offset_array);
        free(key_array);
        return -1;
    }

    CacheNode* cache = createCache(cacheMaxSize);
    if (!cache) {
        // Free resources
        freeLinkedList(head);
        free(offset_array);
        free(key_array);
        return -1;
    }

    printf("Allocation and initialization successful.\n");
    return 0;
}

void initializeRandomNumberGenerator() {
    srand((unsigned int)time(NULL));
}

long generateRandomLong() {
    return rand() % 1000001; // Random value between 0 and 1000000
}

int generateRandomInt(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

Record* createLinkedList(int size) {
    if (size <= 0) return NULL;

    Record* head = malloc(sizeof(Record));
    if (!head) return NULL;

    head->value = generateRandomInt(-500000, 500000);
    head->next = NULL;

    Record* current = head;
    for (int i = 1; i < size; ++i) {
        Record* newNode = malloc(sizeof(Record));
        if (!newNode) {
            freeLinkedList(head);
            return NULL;
        }
        newNode->value = generateRandomInt(-500000, 500000);
        newNode->next = NULL;

        current->next = newNode;
        current = newNode;
    }

    // Sort linked list by value
    head = sortLinkedList(head);

    return head;
}

Record* sortLinkedList(Record* head) {
    if (!head || !head->next) return head;

    Record *sorted = NULL, *current = head, *nextNode;

    while (current != NULL) {
        nextNode = current->next;
        sortedInsert(&sorted, current);
        current = nextNode;
    }

    return sorted;
}

void sortedInsert(Record** headRef, Record* newNode) {
    Record* current;
    if (*headRef == NULL || (*headRef)->value >= newNode->value) {
        newNode->next = *headRef;
        *headRef = newNode;
    } else {
        current = *headRef;
        while (current->next != NULL && current->next->value < newNode->value) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

void freeLinkedList(Record* head) {
    Record* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

CacheNode* createCache(int maxSize) {
    if (maxSize <= 0) return NULL;

    CacheNode *cacheHead = malloc(sizeof(CacheNode));
    if (!cacheHead) return NULL;

    cacheHead->record = NULL;
    cacheHead->prev = NULL;
    cacheHead->next = NULL;

    for (int i = 1; i < maxSize; ++i) {
        CacheNode* newNode = malloc(sizeof(CacheNode));
        if (!newNode) {
            freeCache(cacheHead);
            return NULL;
        }

        newNode->record = NULL;
        newNode->prev = cacheHead;
        newNode->next = NULL;

        cacheHead->next = newNode;
        cacheHead = newNode;
    }

    cacheHead->next = NULL;  // Terminate the list
    return cacheHead->prev;
}

void freeCache(CacheNode* head) {
    CacheNode* current = head;
    while (current != NULL) {
        CacheNode* temp = current;
        current = current->next;
        free(temp);
    }
}
