#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t capacity;
    size_t size;
    record *records;
    pthread_mutex_t lock;
} RecordArray;

static void resize_record_array(RecordArray *arr, size_t new_capacity) {
    pthread_mutex_lock(&arr->lock);
    record *new_records = realloc(arr->records, new_capacity * sizeof(record));
    if (new_records != NULL) {
        arr->capacity = new_capacity;
        arr->records = new_records;
    }
    pthread_mutex_unlock(&arr->lock);
}

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *arr = malloc(sizeof(RecordArray));
    if (!arr) return NULL;

    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->records = malloc(initial_capacity * sizeof(record));
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void destroy_record_array(RecordArray *arr) {
    if (arr) {
        free(arr->records);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

int add_random_record(RecordArray *arr, int min_value, int max_value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        resize_record_array(arr, new_capacity);
    }

    record new_rec;
    new_rec.value = rand() % (max_value - min_value + 1) + min_value;

    arr->records[arr->size++] = new_rec;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

void generate_random_records(RecordArray *arr, size_t count, int min_value, int max_value) {
    for (size_t i = 0; i < count; ++i) {
        add_random_record(arr, min_value, max_value);
    }
}

int main() {
    srand(time(NULL));

    const size_t initial_capacity = 10;
    RecordArray *record_array = create_record_array(initial_capacity);

    if (record_array) {
        generate_random_records(record_array, 50, 1, 100);

        for (size_t i = 0; i < record_array->size; ++i) {
            printf("Record %zu: Value = %d\n", i, record_array->records[i].value);
        }

        destroy_record_array(record_array);
    } else {
        fprintf(stderr, "Failed to create record array.\n");
    }

    return 0;
}
