typedef struct record {
    short s;
    int i;
    float f;
    struct record *next;
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record *head;
} LinkedList;

typedef struct {
    long *offsets;
    size_t offsets_size;
    int *keys;
    size_t keys_size;
    LinkedList list;
} DataManager;

#define INITIAL_SIZE 10
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 100
#define SHORT_RANGE_MIN -32768
#define SHORT_RANGE_MAX 32767
#define FLOAT_RANGE_MIN -3.4e38f
#define FLOAT_RANGE_MAX 3.4e38f

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up...\n", signum);
    exit(1);
}

long double_random(float min, float max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

int resize_array(void **array, size_t current_size, size_t new_size, size_t element_size) {
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) return 0;

    *array = new_array;
    ((char**)array)[1] = (char*)*array + new_size * element_size; // update the end pointer
    for (size_t i = current_size; i < new_size; ++i)
        memset(((char*)*array) + i * element_size, 0, element_size);

    return 1;
}

void initialize_data_manager(DataManager *dm) {
    dm->offsets_size = INITIAL_SIZE;
    dm->keys_size = INITIAL_SIZE;

    dm->offsets = malloc(dm->offsets_size * sizeof(long));
    dm->keys = malloc(dm->keys_size * sizeof(int));

    if (!dm->offsets || !dm->keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    long offset_sum = 0;
    for (size_t i = 0; i < dm->keys_size; ++i) {
        dm->keys[i] = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
        offset_sum += dm->keys[i];
        if (i >= dm->offsets_size && !resize_array((void**)&dm->offsets, dm->offsets_size, dm->offsets_size * 2, sizeof(long))) {
            perror("Failed to resize offsets array");
            exit(EXIT_FAILURE);
        }
        dm->offsets[i] = offset_sum;
    }

    pthread_mutex_init(&dm->list.lock, NULL);
    dm->list.head = NULL;

    for (size_t i = 0; i < INITIAL_SIZE; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        record->s = rand() % (SHORT_RANGE_MAX - SHORT_RANGE_MIN + 1) + SHORT_RANGE_MIN;
        record->i = i;
        record->f = double_random(FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);

        pthread_mutex_lock(&dm->list.lock);
        record->next = dm->list.head;
        dm->list.head = record;
        pthread_mutex_unlock(&dm->list.lock);
    }
}

void destroy_data_manager(DataManager *dm) {
    Record *current = dm->list.head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }

    free(dm->offsets);
    free((char*)dm->keys);
    pthread_mutex_destroy(&dm->list.lock);
}

void handle_interrupts() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1)
        perror("Error setting signal handler");
}

int main() {
