int initialize_data(long *offsets, int *keys, record **records, size_t num_elements, int min_value, int max_value, char default_status) {
    if (num_elements <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

