    offsets = malloc(num_elements * sizeof(long));
    keys = malloc(num_elements * sizeof(int));
    *records = malloc(num_elements * sizeof(record));

    if (!offsets || !keys || !*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(*records);
        return -1;
    }

