        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
        (*records)[i].timestamp = time(NULL); // Current system time
        (*records)[i].status_flag = default_status;
    }

    pthread_mutex_unlock(&lock);

    return 0; // Success
}

