#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>

typedef struct record {
    short s;
    int i;
    float f;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

typedef struct memory_pool {
    size_t block_size;
    void* pool;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Signal handler for graceful termination
void signal_handler(int sig) {
    printf("Interrupt received. Cleaning up...\n");
    exit(EXIT_SUCCESS);
}

// Initialize memory pool
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);

    mp->pool = malloc(block_size * total_blocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    return mp;
}

// Allocate a block from the memory pool
void* allocate_block(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks >= mp->total_blocks) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }

    void* block = ((char*)mp->pool) + (mp->block_size * mp->used_blocks);
    mp->used_blocks++;
    pthread_mutex_unlock(&mp->lock);

    return block;
}

// Free the memory pool
void free_memory_pool(MemoryPool* mp) {
    if (!mp) return;
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to dynamically manage memory
void manage_memory(int array_size, int key_range_min, int key_range_max, 
                   int record_int_min, int record_int_max, int short_range_min,
                   int short_range_max, float float_min, float float_max) {

    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    // Allocate and initialize 'offset' and 'key' arrays
    long* offset = malloc(array_size * sizeof(long));
    int* key = malloc(array_size * sizeof(int));

    if (!offset || !key) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    srand((unsigned)time(NULL)); // Seed random number generator

    long cumulative_sum = 0;
    for (int i = 0; i < array_size; ++i) {
        key[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
        cumulative_sum += key[i];
        offset[i] = cumulative_sum + i * 100; // Constant value can be adjusted
    }

    // Allocate memory for 'record' structures
    Record* records = malloc(array_size * sizeof(Record));

    if (!records) {
        perror("Failed to allocate memory");
        free(offset);
        free(key);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < array_size; ++i) {
        records[i].i = record_int_min + rand() % (record_int_max - record_int_min + 1);
    }

    // Initialize linked list with memory pool
    MemoryPool* mp = create_memory_pool(sizeof(Node), array_size);

    if (!mp) {
        perror("Failed to initialize memory pool");
        free(offset);
        free(key);
        free(records);
        exit(EXIT_FAILURE);
    }

    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < array_size; ++i) {
        Node* new_node = (Node*)allocate_block(mp);
        if (!new_node) break;

        new_node->data.s = short_range_min + rand() % (short_range_max - short_range_min + 1);
        new_node->data.i = record_int_min + rand() % (record_int_max - record_int_min + 1);
        new_node->data.f = float_min + ((float)rand() / RAND_MAX) * (float_max - float_min);

        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            tail->next = new_node;
        }

        tail = new_node;
    }

    // Thread-safe iteration over the linked list
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    void* thread_function(void* arg) {
        Node* node = (Node*)arg;
        pthread_mutex_lock(&list_lock);

        while (node) {
            printf("Short: %hd, Int: %d, Float: %.2f\n", node->data.s, node->data.i, node->data.f);
            node = node->next;
        }

        pthread_mutex_unlock(&list_lock);
        return NULL;
    }

    // Example usage with a single thread
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, thread_function, head);
    pthread_join(thread_id, NULL);

    // Cleanup
    free(offset);
    free(key);
    free(records);
    free_memory_pool(mp);
}

int main() {
    manage_memory(1000, 1, 10, -50, 50, -32768, 32767, 0.0, 100.0);
    return 0;
}
