['Below is a C function that addresses the requirements for managing memory and resources dynamically for the specified components: an array of `long` offset values, an array of `int` keys, and a linked list of `record` structures. The implementation includes dynamic resizing, thread-safe iteration, and custom memory pool management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdalign.h>
#include <time.h>

typedef struct record {
    short s;
    int i;
    float f;
} record_t;

typedef struct node {
    record_t data;
    struct node* next;
} node_t;

// Memory pool for linked list nodes
#define NODE_POOL_SIZE 1024
node_t node_pool[NODE_POOL_SIZE];
int pool_index = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* thread_safe_malloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index + size <= NODE_POOL_SIZE) {
        void* ptr = &node_pool[pool_index];
        pool_index += size;
        pthread_mutex_unlock(&pool_lock);
        return ptr;
    }
    pthread_mutex_unlock(&pool_lock);
    return malloc(size);
}

void thread_safe_free(void* ptr, size_t size) {
    // Simple fixed-size block free strategy
    if (ptr >= node_pool && ptr < &node_pool[NODE_POOL_SIZE]) {
        pthread_mutex_lock(&pool_lock);
        pool_index -= size;
        pthread_mutex_unlock(&pool_lock);
    } else {
        free(ptr);
    }
}

void resize_array(void** array, size_t* capacity, size_t new_capacity, size_t element_size) {
    void* new_array = realloc(*array, new_capacity * element_size);
    if (new_array) {
        *array = new_array;
        *capacity = new_capacity;
    } else {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }
}

void initialize_components(size_t initial_size, long constant_value) {
    size_t offset_capacity = initial_size;
    size_t key_capacity = initial_size;
    long* offsets = (long*)calloc(offset_capacity, sizeof(long));
    int* keys = (int*)malloc(key_capacity * sizeof(int));

    if (!offsets || !keys) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < initial_size; ++i) {
        // Generate unique key values
        keys[i] = rand() % 100 + 1;

        if (i > 0) {
            offsets[i] = offsets[i - 1] + keys[i - 1] + constant_value;
        } else {
            offsets[i] = constant_value; // First offset initialization
        }
    }

    node_t* head = NULL;
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < initial_size; ++i) {
        node_t* new_node = (node_t*)thread_safe_malloc(sizeof(node_t));

        new_node->data.s = rand() % 100;
        new_node->data.i = rand() % 1000;
        new_node->data.f = (float)(rand() % 100 + 0.5);

        pthread_mutex_lock(&list_lock);
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&list_lock);
    }

    // Function to dynamically resize and manage keys and offsets
    void add_key_and_offset(int key) {
        size_t current_size = initial_size;

        if (current_size >= key_capacity || current_size >= offset_capacity) {
            size_t new_capacity = current_size * 2;
            resize_array((void**)&keys, &key_capacity, new_capacity, sizeof(int));
            resize_array((void**)&offsets, &offset_capacity, new_capacity, sizeof(long));
        }

        keys[current_size] = key;

        if (current_size > 0) {
            offsets[current_size] = offsets[current_size - 1] + keys[current_size - 1] + constant_value;
        } else {
            offsets[current_size] = constant_value;
        }
    }

    // Function to iterate over linked list in a thread-safe manner
    void* safe_list_iterator(void (*process)(record_t*)) {
        pthread_mutex_lock(&list_lock);
        node_t* current = head;
        while (current) {
            process(current->data);
            current = current->next;
        }
        pthread_mutex_unlock(&list_lock);
        return NULL;
    }

    // Example usage
    add_key_and_offset(rand() % 100 + 1);

    safe_list_iterator([](record_t* rec) {
        printf("Short: %d, Int: %d, Float: %.2f\n", rec->s, rec->i, rec->f);
    });

    // Free allocated memory
    free(keys);
    free(offsets);

    pthread_mutex_destroy(&list_lock);
}

int main() {
    initialize_components(10, 5);
    return 0;
}
```

### Key Features:

1. **Dynamic Resizing:** The function `resize_array` dynamically resizes the offset and key arrays when needed.

2. **Memory Pool for Nodes:** A fixed-size memory pool is used to manage linked list nodes, reducing allocation overhead and fragmentation.

3. **Thread-Safe Iteration:** Mutexes ensure thread-safe access to both the node pool and the linked list.

4. **Initialization and Management:** The `initialize_components` function sets up initial values and provides methods for adding new keys/offsets and iterating over the list safely.

This implementation balances efficiency, scalability, and maintainability while considering concurrency and memory management challenges.']

