typedef struct Connection {
    int socket_fd;
    char metadata[256];
    time_t last_activity;
    unsigned long unique_id;
    struct Connection* next;
} Connection;

typedef struct {
    Connection* head;
    size_t size;
    pthread_mutex_t lock;
} ConnectionPool;

// Memory pool for slab allocation
#define SLAB_SIZE 64
Connection* slab_pool[SLAB_SIZE];
size_t slab_free_index = 0;

void init_slab_pool() {
    for (int i = 0; i < SLAB_SIZE; ++i) {
        slab_pool[i] = (Connection*)malloc(100 * sizeof(Connection));
    }
}

Connection* allocate_connection_from_slab() {
    if (slab_free_index >= SLAB_SIZE || slab_pool[slab_free_index] == NULL)
        return malloc(sizeof(Connection));

    Connection* conn = slab_pool[slab_free_index];
    slab_pool[slab_free_index] = slab_pool[slab_free_index][99].next;
    slab_free_index++;
    memset(conn, 0, sizeof(Connection));
    return conn;
}

void release_connection_to_slab(Connection* conn) {
    if (slab_free_index < SLAB_SIZE) {
        conn->next = slab_pool[slab_free_index];
        slab_pool[slab_free_index] = conn;
    } else {
        free(conn);
    }
}

ConnectionPool* create_connection_pool() {
    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    pool->head = NULL;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    init_slab_pool();
    return pool;
}

void destroy_connection_pool(ConnectionPool* pool) {
    Connection* current = pool->head;
    while (current != NULL) {
        Connection* next = current->next;
        release_connection_to_slab(current);
        current = next;
    }
    free(pool);
}

Connection* create_connection(int socket_fd, const char* metadata, unsigned long unique_id) {
    Connection* conn = allocate_connection_from_slab();
    if (conn == NULL) return NULL;

    conn->socket_fd = socket_fd;
    strncpy(conn->metadata, metadata, sizeof(conn->metadata));
    conn->last_activity = time(NULL);
    conn->unique_id = unique_id;
    return conn;
}

void add_connection(ConnectionPool* pool, Connection* connection) {
    pthread_mutex_lock(&pool->lock);

    connection->next = pool->head;
    pool->head = connection;
    pool->size++;

    // Log addition
    printf("Added connection %lu\n", connection->unique_id);

    pthread_mutex_unlock(&pool->lock);
}

Connection* find_connection(ConnectionPool* pool, unsigned long unique_id) {
    Connection* current = pool->head;
    while (current != NULL) {
        if (current->unique_id == unique_id)
            return current;
        current = current->next;
    }
    return NULL;
}

void remove_connection(ConnectionPool* pool, unsigned long unique_id) {
    pthread_mutex_lock(&pool->lock);

    Connection *prev = NULL, *current = pool->head;
    while (current != NULL && current->unique_id != unique_id) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL)
            pool->head = current->next;
        else
            prev->next = current->next;

        // Log removal
        printf("Removed connection %lu\n", unique_id);

        release_connection_to_slab(current);
        pool->size--;
    }

    pthread_mutex_unlock(&pool->lock);
}

void iterate_connections(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);

    Connection* current = pool->head;
    while (current != NULL) {
        printf("Connection ID: %lu, Socket FD: %d\n", current->unique_id, current->socket_fd);
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void serialize_state(ConnectionPool* pool) {
    // Pseudo code for serialization
    pthread_mutex_lock(&pool->lock);

    FILE* file = fopen("connections.dat", "wb");
    if (file == NULL) return;

    Connection* current = pool->head;
    while (current != NULL) {
        fwrite(current, sizeof(Connection), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    ConnectionPool* pool = create_connection_pool();

    // Example usage
    add_connection(pool, create_connection(1234, "ClientA", 1));
    add_connection(pool, create_connection(5678, "ClientB", 2));

    iterate_connections(pool);

    remove_connection(pool, 1);
    iterate_connections(pool);

    serialize_state(pool);

    destroy_connection_pool(pool);
    return 0;
}
```

