#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

// Structure for network connection records
typedef struct Record {
    int socket_descriptor;
    char *connection_metadata;
    time_t last_activity_timestamp;
    struct Record *next;
} Record;

// Caching mechanism (simple LRU cache simulation)
#define CACHE_SIZE 10

typedef struct CacheNode {
    Record *record;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct LRUCache {
    CacheNode *head, *tail;
    int size;
    pthread_mutex_t lock;
} LRUCache;

// Global variables
Record *head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
LRUCache cache = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to generate random values for testing purposes
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to create a new record
Record *create_record() {
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->socket_descriptor = generate_random(1000, 65535);
    size_t metadata_size = generate_random(10, 50);
    new_record->connection_metadata = malloc(metadata_size + 1);
    for (size_t i = 0; i < metadata_size; ++i) {
        new_record->connection_metadata[i] = 'A' + rand() % 26;
    }
    new_record->connection_metadata[metadata_size] = '\0';
    new_record->last_activity_timestamp = time(NULL);
    new_record->next = NULL;

    return new_record;
}

// Function to add a record to the linked list
void add_record(Record *new_record) {
    pthread_mutex_lock(&list_lock);
    if (!head) {
        head = new_record;
    } else {
        Record *current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to initialize the cache
void init_cache() {
    pthread_mutex_init(&cache.lock, NULL);
    cache.head = malloc(sizeof(CacheNode));
    cache.tail = malloc(sizeof(CacheNode));

    if (!cache.head || !cache.tail) {
        perror("Failed to allocate memory for cache");
        exit(EXIT_FAILURE);
    }

    cache.head->prev = NULL;
    cache.head->next = cache.tail;
    cache.tail->prev = cache.head;
    cache.tail->next = NULL;
    cache.size = 0;
}

// Function to access a record from the cache
Record *access_cache(int socket_descriptor) {
    pthread_mutex_lock(&cache.lock);
    CacheNode *current = cache.head->next;

    while (current != cache.tail) {
        if (current->record && current->record->socket_descriptor == socket_descriptor) {
            // Move accessed node to front
            current->prev->next = current->next;
            current->next->prev = current->prev;

            current->next = cache.head->next;
            current->prev = cache.head;
            cache.head->next->prev = current;
            cache.head->next = current;

            pthread_mutex_unlock(&cache.lock);
            return current->record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

// Function to insert a record into the cache
void insert_cache(Record *record) {
    pthread_mutex_lock(&cache.lock);

    if (cache.size >= CACHE_SIZE) {
        // Remove least recently used item
        CacheNode *lru = cache.tail->prev;
        lru->prev->next = cache.tail;
        cache.tail->prev = lru->prev;

        free(lru);
        --cache.size;
    }

    CacheNode *new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        perror("Failed to allocate memory for cache node");
        pthread_mutex_unlock(&cache.lock);
        return;
    }
    new_node->record = record;

    // Insert at front
    new_node->next = cache.head->next;
    new_node->prev = cache.head;
    cache.head->next->prev = new_node;
    cache.head->next = new_node;

    ++cache.size;

    pthread_mutex_unlock(&cache.lock);
}

// DNS resolution simulation (stub function)
int resolve_dns(const char *domain) {
    // Simulate network delay
    usleep(generate_random(1000, 5000));
    if (rand() % 10 < 2) { // Simulate occasional failure
        return -1;
    }
    printf("Resolved domain: %s\n", domain);
    return 0;
}

// Function to simulate processing log entries
void process_logs(void *arg) {
    while (1) {
        pthread_mutex_lock(&list_lock);
        if (!head) {
            pthread_mutex_unlock(&list_lock);
            usleep(generate_random(100, 500));
            continue;
        }

        Record *record = head;
        head = head->next;

        // Process the record
        printf("Processing record with socket descriptor: %d\n", record->socket_descriptor);

        // Resolve DNS (stub)
        resolve_dns(record->connection_metadata);

        pthread_mutex_unlock(&list_lock);
        insert_cache(record);  // Cache the processed record

        free(record->connection_metadata);
        free(record);
    }
}

// Main function
int main() {
    srand(time(NULL));
    init_cache();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_logs, NULL);
    }

    // Simulate adding records to the list
    while (1) {
        Record *new_record = create_record();
        if (!new_record) {
            perror("Failed to allocate memory for record");
            continue;
        }
        add_record(new_record);

        usleep(generate_random(500, 2000));
    }

    // Join threads (this example will run indefinitely)
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

### Key Points:
- **Thread Safety:** Mutexes ensure thread-safe operations on the linked list and cache.
- **Dynamic Memory Management:** Records are dynamically allocated, initialized with random data, and freed after processing.
- **Caching Mechanism:** A simple LRU (Least Recently Used) cache is implemented to manage frequently accessed records.
- **Concurrency:** Multiple threads process log entries concurrently, simulating a network monitoring tool.
- **DNS Resolution Simulation:** Random delays and occasional failures simulate DNS resolution.

This code provides a basic framework for managing dynamic connection states with thread safety and efficient memory usage. Adjustments may be needed based on specific requirements or performance considerations in real-world scenarios.']

