using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DistributedQueue<T>
{
    private readonly ConcurrentQueue<T> _queue = new();
    private readonly ConcurrentDictionary<T, bool> _processedMessages = new();
    private readonly Random _random;
    private readonly int _minProcessingTimeMs;
    private readonly int _maxProcessingTimeMs;
    private long _pendingCount;
    private long _processedCount;

    public DistributedQueue(int seed, int minProcessingTimeMs, int maxProcessingTimeMs)
    {
        if (minProcessingTimeMs > maxProcessingTimeMs)
            throw new ArgumentException("Min processing time cannot be greater than max processing time.");

        _random = new Random(seed);
        _minProcessingTimeMs = minProcessingTimeMs;
        _maxProcessingTimeMs = maxProcessingTimeMs;
    }

    public void Enqueue(T message)
    {
        _queue.Enqueue(message);
        Interlocked.Increment(ref _pendingCount);
        Log($"Enqueued: {message}");
    }

    public async Task ProcessMessagesAsync(CancellationToken cancellationToken = default)
    {
        while (!cancellationToken.IsCancellationRequested && _queue.TryDequeue(out var message))
        {
            await ProcessMessageAsync(message, cancellationToken).ConfigureAwait(false);
        }
    }

    private async Task ProcessMessageAsync(T message, CancellationToken cancellationToken)
    {
        if (ValidateMessage(message))
        {
            try
            {
                int processingTimeMs = _random.Next(_minProcessingTimeMs, _maxProcessingTimeMs + 1);
                await Task.Delay(processingTimeMs, cancellationToken).ConfigureAwait(false);

                // Simulate message processing logic here
                Log($"Processed: {message}");
                Interlocked.Increment(ref _processedCount);
                _processedMessages[message] = true;
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
                await RetryMessageAsync(message, cancellationToken).ConfigureAwait(false);
            }
        }
    }

    private bool ValidateMessage(T message)
    {
        // Simulate validation logic here
        return true; // Assume all messages are valid for simplicity
    }

    private async Task RetryMessageAsync(T message, CancellationToken cancellationToken)
    {
        int retryCount = 0;
        while (retryCount < 5) // Maximum of 5 retries
        {
            try
            {
                Log($"Retrying: {message} - Attempt {retryCount + 1}");
                await ProcessMessageAsync(message, cancellationToken).ConfigureAwait(false);
                return; // Exit if successful
            }
            catch (Exception ex)
            {
                retryCount++;
                int delayMs = CalculateExponentialBackoff(retryCount);
                LogError($"Retry failed for: {message} - Attempt {retryCount}. Retrying in {delayMs}ms.");
                await Task.Delay(delayMs, cancellationToken).ConfigureAwait(false);
            }
        }

        Log($"Failed to process after retries: {message}");
    }

    private int CalculateExponentialBackoff(int retryCount)
    {
        return (int)Math.Pow(2, retryCount) * 100; // Exponential backoff strategy
    }

    public IEnumerable<T> DequeueProcessedMessages()
    {
        var processed = _processedMessages.Where(kvp => kvp.Value).Select(kvp => kvp.Key).ToList();
        foreach (var message in processed)
        {
            _processedMessages[message] = false;
        }
        return processed;
    }

    private void Log(string message)
    {
        Console.WriteLine($"[{DateTime.UtcNow}] {message}");
        // Implement more sophisticated logging mechanism if needed
    }

    private void LogError(string error)
    {
        Console.Error.WriteLine($"[{DateTime.UtcNow}] ERROR: {error}");
        // Implement more sophisticated error logging mechanism if needed
    }

    public override string ToString()
    {
        return $"Pending Messages: {_pendingCount}, Processed Messages: {_processedCount}";
    }
}
