#define MAX_SESSIONS 10000
#define ACTIVE_PERCENTAGE 30
#define USER_ROLE_COUNT 5
#define ROLE_ARRAY_SIZE 256

typedef struct Session {
    char *session_id;
    int user_attributes[ROLE_ARRAY_SIZE];
    time_t last_activity;
    int active_status;
    pthread_mutex_t lock;
