    strcpy(session->auth_token, "default-token");
    strcpy(session->activity_log, "initialized");
}

Session* allocate_session() {
    if (pool_index < POOL_SIZE) {
        Session *session = session_pool[pool_index++];
        initialize_session(session);
        return session;
    }
    return malloc(sizeof(Session));
}

void deallocate_session(Session *session) {
    if (pool_index > 0) {
        pool_index--;
        session_pool[pool_index] = session;
    } else {
        free(session);
    }
}

int add_session(Session *session) {
    pthread_mutex_lock(&session_collection.lock);
    if (session_collection.count < MAX_SESSIONS) {
        session_collection.sessions[session_collection.count++] = session;
        pthread_mutex_unlock(&session_collection.lock);
        return 0; // Success
    }
    pthread_mutex_unlock(&session_collection.lock);
    return -1; // Failure
}

void remove_session(int index) {
    if (index < 0 || index >= session_collection.count) return;

    pthread_mutex_lock(&session_collection.lock);
    deallocate_session(session_collection.sessions[index]);
    memmove(&session_collection.sessions[index], &session_collection.sessions[index + 1],
