            + ",\"longitude\":" + std::to_string(longitude)
            + ",\"deviceType\":\"" + deviceType
            + "\",\"sessionDuration\":" + std::to_string(sessionDuration) + "}";
    }
};

class LogManager {
public:
    LogManager(size_t maxEntries, size_t cacheSize);
    ~LogManager();

    void addLogEntry(int userId, const std::string& eventType,
                     double latitude, double longitude,
                     const std::string& deviceType,
                     int sessionDuration);

    std::vector<LogEntry> getRecentLogs(size_t count) const;

    void exportToJson(const std::string& filename) const;

private:
    mutable std::shared_mutex logMutex;
    size_t maxEntries;
    std::queue<LogEntry> logs; // Thread-safe access to main storage
    std::unordered_map<int, LogEntry> cache; // LRU Cache for frequently accessed entries

    void updateCache(int userId, const LogEntry& entry);
    bool isCacheFull() const;

    void compressAndArchive();

    static constexpr double DEFAULT_LATITUDE = 0.0;
    static constexpr double DEFAULT_LONGITUDE = 0.0;

    std::atomic<bool> shouldRunCompressThread{true};
    std::thread compressionThread;
};

LogManager::LogManager(size_t maxEntries, size_t cacheSize)
    : maxEntries(maxEntries), logs() {
    compressionThread = std::thread(&LogManager::compressAndArchive, this);
}

LogManager::~LogManager() {
    shouldRunCompressThread.store(false);
    if (compressionThread.joinable()) {
        compressionThread.join();
    }
}

void LogManager::addLogEntry(int userId, const std::string& eventType,
                             double latitude, double longitude,
                             const std::string& deviceType,
                             int sessionDuration) {
    auto entry = LogEntry(userId, eventType, latitude, longitude, deviceType, sessionDuration);

    std::unique_lock lock(logMutex);
    if (logs.size() >= maxEntries) logs.pop(); // maintain rolling retention policy
    logs.push(entry);
    updateCache(userId, entry); // update cache

    lock.unlock();
}

std::vector<LogEntry> LogManager::getRecentLogs(size_t count) const {
    std::shared_lock lock(logMutex);

    std::vector<LogEntry> recentLogs;
    auto it = logs.end();

    for (size_t i = 0; i < count && it != logs.begin(); ++i, --it) {
        recentLogs.push_back(*it);
    }

    return recentLogs;
}

void LogManager::updateCache(int userId, const LogEntry& entry) {
    if (cache.size() >= maxEntries || isCacheFull()) {
        // Implement LRU Cache replacement logic
        cache.erase(cache.begin()->first); // naive removal of first element
    }
    cache[userId] = entry;
}

bool LogManager::isCacheFull() const {
    return cache.size() == maxEntries; 
}

void LogManager::compressAndArchive() {
    while (shouldRunCompressThread.load()) {
        std::this_thread::sleep_for(std::chrono::hours(1));

        std::unique_lock lock(logMutex);
        // Implement compression logic here
        std::cout << "Archiving logs..." << std::endl;

        // For demonstration, assume archiving simply clears the queue.
        while (!logs.empty()) {
            logs.pop();
        }
    }
}

void LogManager::exportToJson(const std::string& filename) const {
    std::shared_lock lock(logMutex);
    std::ofstream file(filename);

    if (file.is_open()) {
        for (auto it = logs.begin(); it != logs.end(); ++it) {
            file << (*it).toJson() << "\n";
        }
        file.close();
    } else {
        throw std::runtime_error("Unable to open file");
    }
}
```

