    if (count == 0 || data_source == NULL) return NULL;

    srand(time(NULL));

    CustomStruct *array = malloc(count * sizeof(CustomStruct));
    if (!array) return NULL;

    for (size_t i = 0; i < count; ++i) {
        array[i].text = malloc(strlen(data_source[i]) + 1);
        if (!array[i].text) {
            // Cleanup on error
            for (size_t j = 0; j < i; ++j) free(array[j].text);
            free(array);
            return NULL;
        }
        strcpy(array[i].text, data_source[i]);

        array[i].number = min_val + rand() % (max_val - min_val + 1);
    }

    return array;
}

void bulkInitializeArray(size_t count, CustomStruct *array, const char *data_source[], int numbers[]) {
    if (!array || !data_source || !numbers) return;

    for (size_t i = 0; i < count && i < sizeof(data_source) / sizeof(data_source[0]); ++i) {
        free(array[i].text);
        array[i].text = malloc(strlen(data_source[i]) + 1);
        if (!array[i].text) continue; // Skip failed allocations
        strcpy(array[i].text, data_source[i]);

        array[i].number = numbers[i];
    }
}

void freeArray(CustomStruct *array, size_t count, int batch_free) {
    if (array == NULL) return;

    for (size_t i = 0; i < count; ++i) {
        free(array[i].text);
        if (!batch_free) {
            array[i].text = NULL;
        }
    }

    free(array);
}

int main() {
