    size_t count = sizeof(data_source) / sizeof(data_source[0]);
    int numbers[] = {10, 20, 30};

    CustomStruct *array = initializeArray(count, data_source, 1, 100);
    if (array) {
        bulkInitializeArray(count, array, data_source, numbers);

        // Use the array for some operations...

        freeArray(array, count, 0); // Set batch_free to 1 for delayed deallocation
    }

    return 0;
}
