#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { STATUS_OK, STATUS_ERROR } Status;
typedef struct {
    char *text;
    int value;
    float field;
} WebScript;

typedef struct Node {
    WebScript script;
    struct Node *next;
} Node;

// Custom allocator structure
typedef struct {
    void *memory_pool;
    size_t pool_size;
    size_t offset;
    pthread_mutex_t lock;
} Allocator;

Allocator* create_allocator(size_t initial_size) {
    Allocator *allocator = malloc(sizeof(Allocator));
    if (!allocator) return NULL;

    allocator->memory_pool = malloc(initial_size);
    if (!allocator->memory_pool) {
        free(allocator);
        return NULL;
    }

    allocator->pool_size = initial_size;
    allocator->offset = 0;
    pthread_mutex_init(&allocator->lock, NULL);

    return allocator;
}

void* allocate_from_allocator(Allocator *allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);

    if (size + allocator->offset > allocator->pool_size) {
        void *new_pool = realloc(allocator->memory_pool, allocator->pool_size * 2);
        if (!new_pool) {
            pthread_mutex_unlock(&allocator->lock);
            return NULL;
        }

        allocator->memory_pool = new_pool;
        allocator->pool_size *= 2;
    }

    void *ptr = (char *)allocator->memory_pool + allocator->offset;
    allocator->offset += size;

    pthread_mutex_unlock(&allocator->lock);
    return ptr;
}

void free_allocator(Allocator *allocator) {
    pthread_mutex_destroy(&allocator->lock);
    free(allocator->memory_pool);
    free(allocator);
}

// Hash function for metadata
unsigned long hash_metadata(const char *key, int index) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash ^ index;
}

// Function to create a new script
WebScript* create_script(Allocator *allocator, const char *text, int range_min, int range_max) {
    WebScript *script = allocate_from_allocator(allocator, sizeof(WebScript));
    if (!script) return NULL;

    size_t text_length = strlen(text);
    script->text = allocate_from_allocator(allocator, text_length + 1);
    if (!script->text) {
        free(script);
        return NULL;
    }

    strcpy((char *)script->text, text);

    // Initialize fields with random values
    srand(time(NULL));
    script->value = range_min + rand() % (range_max - range_min + 1);
    script->field = ((float)rand() / RAND_MAX) * (range_max - range_min) + range_min;

    return script;
}

// Function to add a script node
Node* add_script_node(Node *head, Allocator *allocator, const char *text, int range_min, int range_max) {
    WebScript *script = create_script(allocator, text, range_min, range_max);
    if (!script) return head;

    Node *new_node = allocate_from_allocator(allocator, sizeof(Node));
    if (!new_node) {
        free(script->text);
        free(script);
        return head;
    }

    new_node->script = *script;
    new_node->next = head;
    return new_node;
}

// Function to free all scripts
void free_scripts(Node *head) {
    while (head != NULL) {
        Node *temp = head;
        head = head->next;

        free(temp->script.text);
        free(temp);
    }
}

// Thread-safe linked list operations using read-write locks
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void* thread_safe_add_script(void* arg) {
    Node **head_ptr = (Node **)arg;
    Allocator *allocator = create_allocator(1024);

    pthread_rwlock_wrlock(&rwlock);
    *head_ptr = add_script_node(*head_ptr, allocator, "Sample Text", 0, 100);
    pthread_rwlock_unlock(&rwlock);

    free_allocator(allocator);
    return NULL;
}

// Logging function for memory usage
void log_memory_usage(size_t current_size, size_t max_size) {
    printf("Current Memory Usage: %zu/%zu\n", current_size, max_size);
}

int main() {
    Node *head = NULL;

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_add_script, &head);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_scripts(head);

    pthread_rwlock_destroy(&rwlock);
    return 0;
}
