typedef struct {
    StructArrayElement **elements;
    size_t capacity;
    size_t used;
} StructArray;

void log_memory_action(const char* action, void* ptr) {
    printf("Memory %s at address: %p\n", action, ptr);
}

int initialize_struct_array(StructArray *array, size_t initialCapacity) {
    array->elements = (StructArrayElement **)malloc(initialCapacity * sizeof(StructArrayElement *));
    if (!array->elements) return -1;
    array->capacity = initialCapacity;
    array->used = 0;
    log_memory_action("allocated", array->elements);
    return 0;
}

void resize_struct_array(StructArray *array, size_t newCapacity) {
    StructArrayElement **newElements = (StructArrayElement **)realloc(array->elements, newCapacity * sizeof(StructArrayElement *));
    if (!newElements) return;
    array->elements = newElements;
    array->capacity = newCapacity;
    log_memory_action("resized", array->elements);
}

void initialize_element_with_random_data(StructArrayElement *element, const char *text, int minRange, int maxRange) {
    element->textPtr = strdup(text);
    if (!element->textPtr) return;
    element->intValue = rand() % (maxRange - minRange + 1) + minRange;
    // Initialize union data as needed; example:
    element->data.boolFlag = rand() % 2;
}

void initialize_from_data_source(StructArray *array, const char **texts, int textCount, int minRange, int maxRange) {
    if (textCount > array->capacity) {
        resize_struct_array(array, textCount);
    }
    for (size_t i = 0; i < textCount; ++i) {
        array->elements[i] = (StructArrayElement *)malloc(sizeof(StructArrayElement));
        initialize_element_with_random_data(array->elements[i], texts[i], minRange, maxRange);
        array->used++;
    }
}

void free_struct_array(StructArray *array) {
    for (size_t i = 0; i < array->used; ++i) {
        if (array->elements[i]) {
            free(array->elements[i]->textPtr);
            log_memory_action("freed", array->elements[i]->textPtr);
            free(array->elements[i]);
            log_memory_action("freed", array->elements[i]);
        }
    }
    free(array->elements);
    log_memory_action("freed", array->elements);
}

void batch_free_resources(StructArray *array) {
    // Assuming all elements are to be freed at once
    free_struct_array(array);
}

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    const char *dataSources[] = {"String 1", "String 2", "String 3"};
    size_t dataSourceCount = sizeof(dataSources) / sizeof(dataSources[0]);

