    if (initialize_struct_array(&array, 5) != 0) {
        fprintf(stderr, "Failed to initialize struct array.\n");
        return EXIT_FAILURE;
    }

    initialize_from_data_source(&array, dataSources, dataSourceCount, 10, 100);

    batch_free_resources(&array);

    return EXIT_SUCCESS;
}
