#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

// Define record structure
typedef struct Record {
    short s;
    int i;
    float f;
    char c[10];
} Record;

// Node for the BST
typedef struct TreeNode {
    int key;
    Record data;
    struct TreeNode *left, *right;
} TreeNode;

// Structure to hold all data structures and manage memory
typedef struct DataStructures {
    long *offsets;
    int *keys;
    TreeNode *root;
    char **metadata;
    size_t count;
    pthread_mutex_t bst_lock;
    Record cache[100];
    int cache_size;
    int access_frequency[100];
} DataStructures;

// Function prototypes
void initialize_data_structures(DataStructures *ds, size_t initial_size);
void destroy_data_structures(DataStructures *ds);
int generate_unique_key(int range_start, int range_end, pthread_mutex_t *lock);
void insert_record(DataStructures *ds, TreeNode **root, int key, Record data);
TreeNode* delete_node(TreeNode *root, int key);
TreeNode* search_bst(TreeNode *root, int key);
Record get_random_record();
char* generate_metadata(size_t length);
void log_operation(const char *operation, int key);

// Initialize all data structures
void initialize_data_structures(DataStructures *ds, size_t initial_size) {
    pthread_mutex_init(&ds->bst_lock, NULL);
    ds->count = 0;
    ds->cache_size = 0;

    ds->offsets = malloc(initial_size * sizeof(long));
    ds->keys = malloc(initial_size * sizeof(int));
    ds->metadata = malloc(initial_size * sizeof(char*));

    for (size_t i = 0; i < initial_size; ++i) {
        pthread_mutex_t key_lock;
        pthread_mutex_init(&key_lock, NULL);
        ds->keys[i] = generate_unique_key(1, 1000, &key_lock);
        pthread_mutex_destroy(&key_lock);

        ds->offsets[i] = (i == 0) ? ds->keys[i] + 10 : ds->offsets[i - 1] + ds->keys[i] + 10;
        ds->metadata[i] = generate_metadata(20);
    }

    ds->root = NULL;
}

// Destroy all data structures
void destroy_data_structures(DataStructures *ds) {
    // Free BST recursively
    void free_bst(TreeNode *node) {
        if (node) {
            free_bst(node->left);
            free_bst(node->right);
            free(node);
        }
    }

    free_bst(ds->root);

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->metadata[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->metadata);

    pthread_mutex_destroy(&ds->bst_lock);
}

// Generate a unique key in a thread-safe manner
int generate_unique_key(int range_start, int range_end, pthread_mutex_t *lock) {
    static int keys[1000] = {0};
    pthread_mutex_lock(lock);

    int key;
    do {
        key = rand() % (range_end - range_start + 1) + range_start;
    } while (keys[key]);

    keys[key] = 1;

    pthread_mutex_unlock(lock);
    return key;
}

// Insert a record into the BST
void insert_record(DataStructures *ds, TreeNode **root, int key, Record data) {
    pthread_mutex_lock(&ds->bst_lock);

    if (*root == NULL) {
        *root = malloc(sizeof(TreeNode));
        (*root)->key = key;
        (*root)->data = data;
        (*root)->left = (*root)->right = NULL;
    } else {
        if (key < (*root)->key) {
            insert_record(ds, &(*root)->left, key, data);
        } else if (key > (*root)->key) {
            insert_record(ds, &(*root)->right, key, data);
        }
    }

    pthread_mutex_unlock(&ds->bst_lock);
}

// Search for a node in the BST
TreeNode* search_bst(TreeNode *root, int key) {
    if (root == NULL || root->key == key) {
        return root;
    }

    if (key < root->key) {
        return search_bst(root->left, key);
    } else {
        return search_bst(root->right, key);
    }
}

// Delete a node from the BST
TreeNode* delete_node(TreeNode *root, int key) {
    if (root == NULL) return root;

    pthread_mutex_lock(&ds->bst_lock);

    if (key < root->key) {
        root->left = delete_node(root->left, key);
    } else if (key > root->key) {
        root->right = delete_node(root->right, key);
    } else {
        if (root->left == NULL) {
            TreeNode *temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            TreeNode *temp = root->left;
            free(root);
            return temp;
        }

        TreeNode *temp = root->right;
        while (temp && temp->left != NULL)
            temp = temp->left;

        root->key = temp->key;
        root->data = temp->data;
        root->right = delete_node(root->right, temp->key);
    }

    pthread_mutex_unlock(&ds->bst_lock);
    return root;
}

// Generate a random record
Record get_random_record() {
    Record rec;
    rec.s = rand() % 100;
    rec.i = rand() % 1000;
    rec.f = (float)rand() / RAND_MAX * 100.0f;

    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int i = 0; i < sizeof(rec.c); ++i) {
        int key = rand() % (sizeof(charset) - 1);
        rec.c[i] = charset[key];
    }

    return rec;
}

// Generate metadata string
char* generate_metadata(size_t length) {
    char *metadata = malloc(length + 1);
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        metadata[i] = charset[key];
    }

    metadata[length] = '\0';
    return metadata;
}

// Log an operation
void log_operation(const char *operation, int key) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s, Key: %d\n", ctime(&now), operation, key);
}

int main() {
    srand(time(NULL));
    DataStructures ds;
    initialize_data_structures(&ds, 10);

    // Example operations
    Record rec1 = get_random_record();
    insert_record(&ds, &ds.root, generate_unique_key(1, 1000, NULL), rec1);
    log_operation("Insert", rec1.i);

    TreeNode *found = search_bst(ds.root, rec1.i);
    if (found) {
        log_operation("Search Found", found->key);
    }

    ds.root = delete_node(ds.root, rec1.i);
    log_operation("Delete", rec1.i);

    destroy_data_structures(&ds);
    return 0;
}
```

### Key Points:
- **Memory Management**: Dynamic allocation and deallocation are handled carefully to avoid leaks.
- **Thread Safety**: Mutexes ensure thread-safe key generation and BST operations.
- **Random Initialization**: Records and metadata are initialized with random values.
- **Logging**: Operations are logged with timestamps for traceability.

This code provides a basic framework. Further enhancements can be made for caching, resizing arrays, and optimizing performance as needed.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

// Define structures for Metadata and SessionState
typedef struct {
    uint64_t user_id;
    time_t timestamp;
    char* tags;  // Assume tags are stored as a concatenated string
} Metadata;

typedef struct {
    uint64_t session_id;
    uint64_t user_id_ref;
    int status_flag;  // e.g., active, inactive
} SessionState;

// Node and HashTable structures for dynamic resizing
typedef struct Node {
    void* key;
    void* value;
    struct Node* next;
} Node;

typedef struct {
    size_t size;
    size_t count;
    Node** buckets;
    pthread_mutex_t lock;  // For thread-safe operations
} HashTable;

// Function to create a hash table with initial capacity
HashTable* create_hash_table(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = capacity;
    table->count = 0;
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Hash function for the hash tables
unsigned long hash_function(void* key) {
    uint64_t id = *(uint64_t*)key;
    return id % 97; // Simple modulo prime number for distribution
}

// Resize a hash table dynamically
void resize_hash_table(HashTable* table, size_t new_capacity) {
    pthread_mutex_lock(&table->lock);
    Node** old_buckets = table->buckets;
    size_t old_size = table->size;

    table->buckets = (Node**)calloc(new_capacity, sizeof(Node*));
    table->size = new_capacity;
    table->count = 0;

    for (size_t i = 0; i < old_size; ++i) {
        Node* node = old_buckets[i];
        while (node) {
            // Rehash all nodes
            unsigned long index = hash_function(node->key) % table->size;
            Node* next_node = node->next;

            node->next = table->buckets[index];
            table->buckets[index] = node;

            node = next_node;
            ++table->count;
        }
    }

    free(old_buckets);
    pthread_mutex_unlock(&table->lock);
}

// Insert or update a key-value pair into the hash table
void insert_hash_table(HashTable* table, void* key, void* value) {
    unsigned long index = hash_function(key) % table->size;
    Node** bucket = &table->buckets[index];

    pthread_mutex_lock(&table->lock);

    Node* current = *bucket;
    while (current) {
        if (*(uint64_t*)current->key == *(uint64_t*)key) {
            free(current->value);
            current->value = value;  // Update existing key
            pthread_mutex_unlock(&table->lock);
            return;
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->value = value;
    new_node->next = *bucket;

    *bucket = new_node;
    ++table->count;

    if ((float)table->count / table->size > 0.75) {
        resize_hash_table(table, table->size * 2);
    }

    pthread_mutex_unlock(&table->lock);
}

// Function to initialize metadata with user ID and timestamp
void* create_metadata_entry(uint64_t user_id) {
    Metadata* meta = (Metadata*)malloc(sizeof(Metadata));
    meta->user_id = user_id;
    time_t rawtime;
    time(&rawtime);
    meta->timestamp = rawtime;

    // Generate a unique tag set within specified range
    char* tags = malloc(50);  // Example size, adjust as needed
    snprintf(tags, 50, "Tag%lu", (unsigned long)rand() % 1000);  // Random tags for example
    meta->tags = tags;

    return meta;
}

// Function to link session state to a metadata entry
void* create_session_state(uint64_t session_id, uint64_t user_id_ref, int status_flag) {
    SessionState* sess = (SessionState*)malloc(sizeof(SessionState));
    sess->session_id = session_id;
    sess->user_id_ref = user_id_ref;
    sess->status_flag = status_flag;

    return sess;
}

// Function to iterate over hash tables and perform query operations
void query_hash_table(HashTable* table, void (*callback)(void*, void*)) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            callback(node->key, node->value);
            node = node->next;
        }
    }
}

// Cleanup function to free hash tables
void destroy_hash_table(HashTable* table) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next_node = node->next;
            free(node->key);
            if (node->value) {
                // Cast to Metadata or SessionState and free accordingly
                if (((Metadata*)node->value)->tags) {
                    free(((Metadata*)node->value)->tags);
                }
                free(node->value);
            }
            free(node);
            node = next_node;
        }
    }

    free(table->buckets);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Example callback for query operation
void example_callback(void* key, void* value) {
    uint64_t user_id = *(uint64_t*)key;
    Metadata* meta = (Metadata*)value;

    printf("User ID: %lu, Timestamp: %ld, Tags: %s\n", user_id, meta->timestamp, meta->tags);
}

// Main function to demonstrate functionality
int main() {
    // Initialize hash tables for metadata and session states
    HashTable* user_metadata = create_hash_table(16);
    HashTable* user_sessions = create_hash_table(16);

    // Insert some example entries
    uint64_t user_id = 1;
    Metadata* meta = (Metadata*)create_metadata_entry(user_id);
    insert_hash_table(user_metadata, &user_id, meta);

    uint64_t session_id = 101;
    SessionState* sess = (SessionState*)create_session_state(session_id, user_id, 1);
    insert_hash_table(user_sessions, &session_id, sess);

    // Perform a query operation
    printf("Querying Metadata Table:\n");
    query_hash_table(user_metadata, example_callback);

    // Cleanup hash tables
    destroy_hash_table(user_metadata);
    destroy_hash_table(user_sessions);

    return 0;
}
```

This code provides an implementation that manages two dynamic hash tables with thread-safe operations for user metadata and session states. It includes initialization of data entries, insertion mechanisms with resizing capabilities, a query operation example, and cleanup functions to manage memory effectively.']

