```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    short s;
    int i;
    float f;
    char *str;
    double d;
} Record;

typedef struct Node {
    int key;
    long offset;
    Record record;
    size_t metadata; // Store size and type information
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Function to initialize linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Dynamic allocation and resizing strategy for array
void resize_array_if_needed(Node** array, int* size, int new_size) {
    if (new_size > *size) {
        Node* temp = realloc(*array, sizeof(Node) * new_size);
        if (!temp) return; // handle reallocation failure gracefully
        memset(temp + *size, 0, sizeof(Node) * (new_size - *size));
        *array = temp;
        *size = new_size;
    }
}

// Function to create a random record
Record* create_random_record() {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;

    rec->s = rand() % 32767;
    rec->i = rand() % 2147483647;
    rec->f = (float)(rand() % 1000000) / 10000.0;

    size_t str_len = rand() % 256; // Random string length
    rec->str = (char*)malloc(str_len + 1);
    if (!rec->str) {
        free(rec);
        return NULL;
    }
    for (size_t j = 0; j < str_len; ++j)
        rec->str[j] = 'a' + rand() % 26;
    rec->str[str_len] = '\0';

    rec->d = (double)(rand() % 1000000) / 10000.0;

    return rec;
}

// Function to add a new record with unique key and offset
void add_record(LinkedList* list, int range_start, int range_end) {
    static int last_key = -1;
    int key;
    do {
        key = rand() % (range_end - range_start + 1) + range_start;
    } while (key == last_key);

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // handle malloc failure gracefully
    }

    new_node->key = key;
    new_node->record = *create_random_record();

    // Calculate offset based on cumulative sums of previous keys plus a constant increment (e.g., 100)
    Node* current = list->head;
    long offset = 0;
    while (current) {
        offset += current->key + 100; // example constant increment
        current = current->next;
    }
    new_node->offset = offset;

    new_node->metadata = sizeof(Record);
    new_node->next = list->head;
    list->head = new_node;

    last_key = key;
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the linked list
void iterate_list(const LinkedList* list) {
    pthread_mutex_lock((LinkedList*)list);

    Node* current = list->head;
    while (current) {
        printf("Key: %d, Offset: %ld, Record Size: %zu\n", 
            current->key, current->offset, current->metadata);

        // Example access to record fields
        printf("Short: %hd, Int: %d, Float: %.2f, Char* (str): %s, Double: %.2lf\n",
               current->record.s,
               current->record.i,
               current->record.f,
               current->record.str,
               current->record.d);

        current = current->next;
    }

    pthread_mutex_unlock((LinkedList*)list);
}

// Function to free a record
void free_record(Record* rec) {
    if (rec && rec->str) free(rec->str);
    free(rec);
}

// Function to clean up the linked list and free resources
void destroy_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_record(&(current->record));
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* my_list = init_list();
    if (!my_list) return EXIT_FAILURE;

    // Example usage
    for (int i = 0; i < 10; ++i)
        add_record(my_list, 1000, 9999);

    iterate_list(my_list);
    destroy_list(my_list);

    return EXIT_SUCCESS;
}
```

