#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for initial hash table sizes
#define INITIAL_METADATA_SIZE 16
#define INITIAL_SESSION_SIZE 16

// Metadata entry structure
typedef struct {
    int user_id;
    time_t timestamp;
    char* tags; // Simple string to represent a set of tags
} MetaDataEntry;

// Session state entry structure
typedef struct {
    int session_id;
    int user_id;
    int status_flag;
} SessionStateEntry;

// Node for hash table linked list
struct HashNode {
    void* data;
    struct HashNode* next;
};

// Hash table structure
typedef struct {
    struct HashNode** buckets;
    size_t size;
    pthread_mutex_t lock; // Lock for the entire hash table
} HashTable;

// Function prototypes
void log_memory_event(const char* event, size_t size);
void* allocate_memory(size_t size);
void free_memory(void* ptr, size_t size);

// Initialize a hash table
HashTable* create_hash_table(size_t initial_size) {
    HashTable* table = (HashTable*)allocate_memory(sizeof(HashTable));
    table->buckets = (struct HashNode**)allocate_memory(initial_size * sizeof(struct HashNode*));
    for (size_t i = 0; i < initial_size; ++i) {
        table->buckets[i] = NULL;
    }
    table->size = initial_size;
    pthread_mutex_init(&table->lock, NULL);
    log_memory_event("allocated", sizeof(HashTable) + initial_size * sizeof(struct HashNode*));
    return table;
}

// Simple hash function
unsigned long hash_function(void* data, size_t size, size_t table_size) {
    unsigned char* bytes = (unsigned char*)data;
    unsigned long hash = 5381;
    for (size_t i = 0; i < size; ++i) {
        hash = ((hash << 5) + hash) + bytes[i];
    }
    return hash % table_size;
}

// Insert data into the hash table
void insert_into_hash_table(HashTable* table, void* data, size_t data_size) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash_function(data, data_size, table->size);
    struct HashNode* node = (struct HashNode*)allocate_memory(sizeof(struct HashNode));
    node->data = allocate_memory(data_size);
    memcpy(node->data, data, data_size);

    // Insert at the beginning of the linked list
    node->next = table->buckets[index];
    table->buckets[index] = node;
    pthread_mutex_unlock(&table->lock);
}

// Dynamic resizing of hash tables
void resize_hash_table(HashTable* table) {
    size_t new_size = table->size * 2;
    struct HashNode** new_buckets = (struct HashNode**)allocate_memory(new_size * sizeof(struct HashNode*));
    for (size_t i = 0; i < new_size; ++i) {
        new_buckets[i] = NULL;
    }

    pthread_mutex_lock(&table->lock);
    // Rehash all entries
    for (size_t i = 0; i < table->size; ++i) {
        struct HashNode* node = table->buckets[i];
        while (node) {
            unsigned long new_index = hash_function(node->data, sizeof(void*), new_size);
            struct HashNode* next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    // Free old buckets
    for (size_t i = 0; i < table->size; ++i) {
        struct HashNode* node = table->buckets[i];
        while (node) {
            struct HashNode* temp = node;
            node = node->next;
            free_memory(temp->data, sizeof(void*));
            free_memory(temp, sizeof(struct HashNode));
        }
    }

    free_memory(table->buckets, table->size * sizeof(struct HashNode*));
    table->buckets = new_buckets;
    table->size = new_size;
    pthread_mutex_unlock(&table->lock);
    log_memory_event("resized", new_size * sizeof(struct HashNode*));
}

// Cleanup hash table
void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        struct HashNode* node = table->buckets[i];
        while (node) {
            struct HashNode* temp = node;
            node = node->next;
            free_memory(temp->data, sizeof(void*));
            free_memory(temp, sizeof(struct HashNode));
        }
    }
    pthread_mutex_destroy(&table->lock);
    free_memory(table->buckets, table->size * sizeof(struct HashNode*));
    free_memory(table, sizeof(HashTable));
}

// Memory management functions
void log_memory_event(const char* event, size_t size) {
    printf("Memory %s: %zu bytes\n", event, size);
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Allocation failed");
        exit(EXIT_FAILURE);
    }
    log_memory_event("allocated", size);
    return ptr;
}

void free_memory(void* ptr, size_t size) {
    free(ptr);
    log_memory_event("freed", size);
}

// Main function to demonstrate usage
int main() {
    HashTable* metadata_table = create_hash_table(INITIAL_METADATA_SIZE);
    HashTable* session_state_table = create_hash_table(INITIAL_SESSION_SIZE);

    // Example usage: insert and resize
    MetaDataEntry example_meta = {1, time(NULL), "example_tags"};
    SessionStateEntry example_session = {100, 1, 0};
    insert_into_hash_table(metadata_table, &example_meta, sizeof(example_meta));
    insert_into_hash_table(session_state_table, &example_session, sizeof(example_session));

    // Resize tables
    resize_hash_table(metadata_table);
    resize_hash_table(session_state_table);

    // Cleanup
    destroy_hash_table(metadata_table);
    destroy_hash_table(session_state_table);

    return 0;
}
