#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Record structure
typedef struct record {
    short s;
    int i;
    float f;
    struct record* next;
} Record;

// Cache node for LRU caching mechanism
typedef struct cache_node {
    int key;
    Record* record;
    struct cache_node* prev, *next;
} CacheNode;

// Thread-safe doubly linked list structure for records
typedef struct {
    Record* head;
    pthread_rwlock_t lock; // Reader-writer lock for thread safety
} RecordList;

// LRU Cache structure
typedef struct {
    int capacity;
    int size;
    CacheNode* head;
    CacheNode* tail;
    pthread_rwlock_t lock;
    void** keys_map; // Map of keys to cache nodes
} LRUCache;

// Array and key storage structure with thread safety
typedef struct {
    long* offsets;
    int* keys;
    size_t capacity;
    size_t count;
    RecordList list;
    LRUCache cache;
    pthread_rwlock_t rw_lock; // Reader-writer lock for access to arrays
} DataStructure;

// Function prototypes
DataStructure* create_data_structure(size_t initial_capacity, int key_range);
void destroy_data_structure(DataStructure* ds);
int add_record(DataStructure* ds, Record* record);
Record* get_record(DataStructure* ds, int key);
int update_record(DataStructure* ds, int key, short new_s, int new_i, float new_f);
int delete_record(DataStructure* ds, int key);

// Create a new data structure
DataStructure* create_data_structure(size_t initial_capacity, int key_range) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    pthread_rwlock_init(&ds->rw_lock, NULL);
    pthread_rwlock_init(&ds->list.lock, NULL);

    // Initialize arrays
    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = malloc(initial_capacity * sizeof(int));
    ds->capacity = initial_capacity;
    ds->count = 0;

    // Initialize record list
    ds->list.head = NULL;

    // Initialize cache
    ds->cache.capacity = initial_capacity / 10; // Example cache size
    ds->cache.size = 0;
    ds->cache.keys_map = calloc(ds->capacity, sizeof(void*));
    pthread_rwlock_init(&ds->cache.lock, NULL);

    // Seed random number generator for record initialization
    srand(time(NULL));

    return ds;
}

// Destroy the data structure and free resources
void destroy_data_structure(DataStructure* ds) {
    if (!ds) return;

    // Free offsets and keys arrays
    free(ds->offsets);
    free(ds->keys);

    // Destroy and free record list
    Record* current = ds->list.head;
    while (current) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_rwlock_destroy(&ds->list.lock);

    // Destroy cache nodes
    CacheNode* current_cache_node = ds->cache.head;
    while (current_cache_node) {
        CacheNode* temp = current_cache_node;
        current_cache_node = current_cache_node->next;
        free(temp);
    }

    pthread_rwlock_destroy(&ds->cache.lock);

    // Free cache map
    free(ds->cache.keys_map);

    // Destroy locks
    pthread_rwlock_destroy(&ds->rw_lock);

    free(ds);
}

// Add a new record to the data structure
int add_record(DataStructure* ds, Record* record) {
    if (!ds || !record) return -1;

    pthread_rwlock_wrlock(&ds->rw_lock);

    // Generate unique key within specified range and handle collisions
    int key = rand() % (ds->capacity * 2);
    while ((void*)ds->cache.keys_map[key]) { // Check for collision
        key = rand() % (ds->capacity * 2);
    }

    pthread_rwlock_unlock(&ds->rw_lock);

    pthread_rwlock_wrlock(&ds->list.lock);

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_rwlock_unlock(&ds->list.lock);
        return -1;
    }

    *new_record = *record;
    new_record->next = ds->list.head;
    ds->list.head = new_record;

    // Update keys and offsets
    pthread_rwlock_wrlock(&ds->rw_lock);
    int index = ds->count++;
    if (index >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        long* new_offsets = calloc(new_capacity, sizeof(long));
        int* new_keys = malloc(new_capacity * sizeof(int));

        memcpy(new_offsets, ds->offsets, ds->capacity * sizeof(long));
        memcpy(new_keys, ds->keys, ds->capacity * sizeof(int));

        free(ds->offsets);
        free(ds->keys);

        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->capacity = new_capacity;
    }

    // Calculate offset based on previous keys sum
    long offset_sum = index > 0 ? ds->offsets[index - 1] : 0;
    ds->offsets[index] = offset_sum + key;

    ds->keys[index] = key;
    pthread_rwlock_unlock(&ds->rw_lock);

    // Insert into cache
    CacheNode* node = malloc(sizeof(CacheNode));
    if (!node) {
        pthread_rwlock_unlock(&ds->list.lock);
        return -1;
    }

    node->key = key;
    node->record = new_record;

    pthread_rwlock_wrlock(&ds->cache.lock);

    // Evict LRU if necessary
    if (ds->cache.size == ds->cache.capacity) {
        void* to_remove_key = ds->cache.tail->key;
        CacheNode* prev_node = ds->cache.head;

        while (prev_node && (void*)prev_node->next != to_remove_key) {
            prev_node = prev_node->next;
        }

        if (prev_node && prev_node->next) {
            prev_node->next = prev_node->next->next;
            if (prev_node->next == NULL) {
                ds->cache.tail = prev_node;
            }
            free(ds->cache.keys_map[to_remove_key]);
        }
        ds->cache.size--;
    }

    // Add node to head of LRU cache
    node->next = ds->cache.head;
    node->prev = NULL;

    if (ds->cache.head) {
        ds->cache.head->prev = node;
    } else {
        ds->cache.tail = node;
    }
    ds->cache.head = node;

    // Update key map
    ds->cache.keys_map[key] = (void*)node;
    ds->cache.size++;

    pthread_rwlock_unlock(&ds->cache.lock);

    pthread_rwlock_unlock(&ds->list.lock);

    return 0; // Success
}

// Retrieve a record by key
Record* get_record(DataStructure* ds, int key) {
    if (!ds) return NULL;

    // Check cache first
    pthread_rwlock_rdlock(&ds->cache.lock);

    CacheNode* node = (CacheNode*)ds->cache.keys_map[key];
    if (node) {
        // Move accessed node to head of LRU cache
        if (node != ds->cache.head) {
            if (node->prev) node->prev->next = node->next;
            if (node->next) node->next->prev = node->prev;

            if (ds->cache.tail == node) {
                ds->cache.tail = node->prev;
            }

            node->next = ds->cache.head;
            node->prev = NULL;

            if (ds->cache.head) {
                ds->cache.head->prev = node;
            }
            ds->cache.head = node;

            pthread_rwlock_unlock(&ds->cache.lock);

            return node->record;
        }
    }

    pthread_rwlock_unlock(&ds->cache.lock);

    // Fallback to list search if not in cache
    pthread_rwlock_rdlock(&ds->list.lock);

    Record* current = ds->list.head;
    while (current) {
        if (current->i == key) {  // Assuming 'i' field stores the record's key for simplicity
            pthread_rwlock_unlock(&ds->list.lock);

            // Add to cache after retrieval
            add_record(ds, current); // Reuse existing function to add to cache

            return current;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&ds->list.lock);

    return NULL;  // Record not found
}

// Update an existing record by key
int update_record(DataStructure* ds, int key, short new_s, int new_i, float new_f) {
    if (!ds) return -1;

    pthread_rwlock_rdlock(&ds->list.lock);

    Record* current = ds->list.head;
    while (current) {
        if (current->i == key) { // Assuming 'i' field stores the record's key
            pthread_rwlock_unlock(&ds->list.lock);

            pthread_rwlock_wrlock(&ds->cache.lock);
            CacheNode* node = (CacheNode*)ds->cache.keys_map[key];
            if (node && node->record == current) {
                node->record->s = new_s;
                node->record->i = new_i;
                node->record->f = new_f;
            }
            pthread_rwlock_unlock(&ds->cache.lock);

            return 0; // Success
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&ds->list.lock);

    return -1; // Record not found
}

// Delete a record by key
int delete_record(DataStructure* ds, int key) {
    if (!ds) return -1;

    pthread_rwlock_wrlock(&ds->list.lock);

    Record** current_ptr = &ds->list.head;
    while (*current_ptr) {
        Record* entry = *current_ptr;

        if (entry->i == key) { // Assuming 'i' field stores the record's key
            *current_ptr = entry->next;

            // Remove from cache
            pthread_rwlock_wrlock(&ds->cache.lock);

            CacheNode* node = (CacheNode*)ds->cache.keys_map[key];
            if (node && node->record == entry) {
                if (node->prev) node->prev->next = node->next;
                if (node->next) node->next->prev = node->prev;

                if (ds->cache.head == node) ds->cache.head = node->next;
                if (ds->cache.tail == node) ds->cache.tail = node->prev;

                free(node);
                ds->cache.size--;
            }

            pthread_rwlock_unlock(&ds->cache.lock);

            free(entry);

            return 0; // Success
        }

        current_ptr = &entry->next;
    }

    pthread_rwlock_unlock(&ds->list.lock);

    return -1; // Record not found
}

// Initialize a record with random values (for example purposes)
void init_record(Record* r) {
    if (!r) return;

    r->s = rand() % 1000;     // Random short value in range [0, 999]
    r->i = rand() % 100000;   // Random int value in range [0, 99999]
    r->f = (float)(rand() / (RAND_MAX + 1.0)); // Random float value in range [0.0, 1.0)
}
