// Main function to process CSV and calculate average
double processCSVAndCalculateAverage(const char *csvFilePath, ItemArray *itemArray) {
    FILE *file = fopen(csvFilePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", csvFilePath);
        return -1;
    }

    // CSV parsing logic (pseudo-code)
    int key;
    double value;
    char status[10];
    int existingKeys[MAX_UNIQUE_KEYS] = {0};
    int uniqueKeyCount = 0;

    while (fscanf(file, "%d,%lf,%9s", &key, &value, status) == 3) {
        if (uniqueKeyCount >= MAX_UNIQUE_KEYS) {
            fprintf(stderr, "Maximum unique keys reached: %d\n", MAX_UNIQUE_KEYS);
            break;
        }

        // Ensure key is unique
        int randomKey = generateUniqueRandom(existingKeys, uniqueKeyCount);
        while (randomKey == key || !isValidKey(randomKey)) {
            randomKey = generateUniqueRandom(existingKeys, uniqueKeyCount);
        }

        existingKeys[uniqueKeyCount++] = randomKey;

        Item newItem;
        newItem.key = randomKey;
        newItem.value = value;
        strncpy(newItem.status, status, sizeof(newItem.status) - 1);

        appendItem(itemArray, &newItem);
    }

    fclose(file);

    // Calculate average
    double sum = 0.0;
    for (size_t i = 0; i < itemArray->count; ++i) {
        sum += itemArray->items[i].value;
    }
    return itemArray->count > 0 ? sum / itemArray->count : 0.0;
}

// Append new item to the array
void appendItem(ItemArray *itemArray, const Item *newItem) {
    pthread_mutex_lock(&itemArray->lock);

    if (itemArray->count == itemArray->capacity) {
        size_t newCapacity = itemArray->capacity > 0 ? itemArray->capacity * 2 : 16;
        Item *newItems = realloc(itemArray->items, newCapacity * sizeof(Item));
        if (!newItems) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&itemArray->lock);
            return;
        }
        itemArray->items = newItems;
        itemArray->capacity = newCapacity;
    }

    itemArray->items[itemArray->count++] = *newItem;

    pthread_mutex_unlock(&itemArray->lock);
}

// Free allocated memory
void freeItems(ItemArray *itemArray) {
    if (itemArray && itemArray->items) {
        free(itemArray->items);
        itemArray->items = NULL;
        itemArray->capacity = 0;
        itemArray->count = 0;
    }
    pthread_mutex_destroy(&itemArray->lock);
}

// Generate a unique random number
int generateUniqueRandom(int existingKeys[], int count) {
    srand((unsigned int)time(NULL));
    int randomNum;
    do {
        randomNum = rand() % 201 - 100; // Random between -100 and 100
    } while (!isUnique(randomNum, existingKeys, count));
    return randomNum;
}

