} MemoryPool;

MemoryPool global_pool = {NULL, PTHREAD_MUTEX_INITIALIZER};

void initialize_pool(MemoryPool *pool, size_t initial_size) {
    pool->head = malloc(sizeof(MemoryPoolNode));
    pool->head->size = initial_size;
    pool->head->memory = malloc(initial_size);
    pool->head->next = NULL;
}

void *allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode *current = pool->head;
    while (current != NULL) {
        if (current->size >= size) {
            void *allocated_memory = current->memory;
            current->memory += size;
            current->size -= size;

            pthread_mutex_unlock(&pool->lock);
            return allocated_memory;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);

    // If no suitable block found, create a new one
    MemoryPoolNode *new_node = malloc(sizeof(MemoryPoolNode));
    new_node->size = size + sizeof(size_t);
    new_node->memory = malloc(new_node->size);
    new_node->next = NULL;

    pthread_mutex_lock(&pool->lock);

    new_node->next = pool->head;
    pool->head = new_node;

    pthread_mutex_unlock(&pool->lock);

    return new_node->memory;
}

void free_pool(MemoryPool *pool) {
    MemoryPoolNode *current = pool->head;
    while (current != NULL) {
        MemoryPoolNode *next = current->next;
        free(current->memory);
        free(current);
        current = next;
    }
}

DataStructure create_data_structure(size_t count) {
    DataStructure ds;
    ds.count = count;

    pthread_mutex_init(&ds.lock, NULL);

    size_t offsets_size = sizeof(long) * count;
    ds.offsets = allocate_from_pool(&global_pool, offsets_size);
    for (size_t i = 0; i < count; ++i) {
        ds.offsets[i] = rand() % 10000; // Random values
    }

    size_t keys_size = sizeof(int) * count;
    ds.keys = allocate_from_pool(&global_pool, keys_size);
    for (size_t i = 0; i < count; ++i) {
        bool unique;
        do {
            unique = true;
            int key = rand() % MAX_RECORDS;
            for (size_t j = 0; j < i; ++j) {
                if (ds.keys[j] == key) {
                    unique = false;
                    break;
                }
            }
        } while (!unique);
        ds.keys[i] = key;
    }

    size_t records_size = sizeof(record) * count;
    ds.records = allocate_from_pool(&global_pool, records_size);
    for (size_t i = 0; i < count; ++i) {
        ds.records[i].value = rand() % 100; // Random values within range
    }

    return ds;
}

void destroy_data_structure(DataStructure *ds) {
    pthread_mutex_destroy(&ds->lock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}

void concurrent_access_example(DataStructure *ds, void (*operation)(DataStructure*, size_t)) {
    pthread_t threads[MAX_RECORDS];
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))operation, ds);
    }
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void sample_operation(DataStructure *ds, size_t index) {
    pthread_mutex_lock(&ds->lock);

    if (index < ds->count) {
        printf("Accessing record with key %d\n", ds->keys[index]);
    }

    pthread_mutex_unlock(&ds->lock);
}

int main() {
    srand(time(NULL));

    initialize_pool(&global_pool, 1024 * sizeof(long));

    DataStructure ds = create_data_structure(100);

    concurrent_access_example(&ds, sample_operation);

    destroy_data_structure(&ds);
    free_pool(&global_pool);

    return 0;
}
```

