```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

#define HASH_TABLE_SIZE 1024

typedef struct vector {
    int *data;
    size_t capacity;
    size_t size;
} Vector;

typedef struct variable_record {
    char key[256];
    char *dynamic_string;
    Vector nested_vector;
    struct variable_record *next; // For chaining in hash table
} VariableRecord;

typedef struct matrix_cell {
    double value;
} MatrixCell;

typedef struct matrix {
    MatrixCell **data;
    size_t rows, cols;
} Matrix;

typedef struct lru_node {
    char key[256];
    VariableRecord *record;
    struct lru_node *prev, *next;
} LRUNode;

typedef struct {
    LRUNode *head, *tail;
    size_t capacity;
    size_t count;
} LRU_Cache;

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
VariableRecord* hash_table[HASH_TABLE_SIZE];

// Function prototypes
Matrix create_matrix(size_t rows, size_t cols);
void free_matrix(Matrix *matrix);
double random_double(double min, double max);
Vector create_vector();
void free_vector(Vector *vector);
size_t hash_function(const char *key);
void insert_hash_record(VariableRecord *record);
VariableRecord* find_hash_record(const char *key);
void delete_hash_record(const char *key);
LRU_Cache* create_lru_cache(size_t capacity);
void lru_put(LRU_Cache *cache, const char *key, VariableRecord *record);
VariableRecord* lru_get(LRU_Cache *cache, const char *key);
void free_lru_cache(LRU_Cache *cache);

// Matrix functions
Matrix create_matrix(size_t rows, size_t cols) {
    Matrix matrix;
    matrix.rows = rows;
    matrix.cols = cols;
    matrix.data = (MatrixCell **)malloc(rows * sizeof(MatrixCell *));

    for (size_t i = 0; i < rows; ++i) {
        matrix.data[i] = (MatrixCell *)malloc(cols * sizeof(MatrixCell));

        for (size_t j = 0; j < cols; ++j) {
            double value = random_double(-100.0, 100.0);
            matrix.data[i][j].value = value;
        }
    }

    return matrix;
}

void free_matrix(Matrix *matrix) {
    for (size_t i = 0; i < matrix->rows; ++i) {
        free(matrix->data[i]);
    }
    free(matrix->data);
}

double random_double(double min, double max) {
    return min + ((max - min) * rand() / (RAND_MAX + 1.0));
}

// Vector functions
Vector create_vector() {
    Vector vector;
    vector.capacity = 4;
    vector.size = 0;
    vector.data = malloc(vector.capacity * sizeof(int));

    return vector;
}

void free_vector(Vector *vector) {
    free(vector->data);
}

// Hash table and LRU cache functions
size_t hash_function(const char *key) {
    size_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % HASH_TABLE_SIZE;
}

void insert_hash_record(VariableRecord *record) {
    size_t index = hash_function(record->key);
    pthread_mutex_lock(&hash_table_lock);

    record->next = hash_table[index];
    hash_table[index] = record;

    pthread_mutex_unlock(&hash_table_lock);
}

VariableRecord* find_hash_record(const char *key) {
    size_t index = hash_function(key);
    VariableRecord *current = hash_table[index];

    while (current != NULL) {
        if (strcmp(current->key, key) == 0)
            return current;
        current = current->next;
    }

    return NULL;
}

void delete_hash_record(const char *key) {
    size_t index = hash_function(key);
    pthread_mutex_lock(&hash_table_lock);

    VariableRecord **current = &hash_table[index];
    while (*current != NULL) {
        if (strcmp((*current)->key, key) == 0) {
            VariableRecord *to_delete = *current;
            *current = to_current->next;
            free(to_delete->dynamic_string);
            free_vector(&to_delete->nested_vector);
            free(to_delete);

            pthread_mutex_unlock(&hash_table_lock);
            return;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&hash_table_lock);
}

LRU_Cache* create_lru_cache(size_t capacity) {
    LRU_Cache *cache = malloc(sizeof(LRU_Cache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->capacity = capacity;
    cache->count = 0;

    return cache;
}

void lru_put(LRU_Cache *cache, const char *key, VariableRecord *record) {
    LRUNode *node = malloc(sizeof(LRUNode));
    strcpy(node->key, key);
    node->record = record;
    node->prev = NULL;
    node->next = cache->head;

    if (cache->head != NULL)
        cache->head->prev = node;

    cache->head = node;

    if (cache->tail == NULL)
        cache->tail = node;

    if (cache->count >= cache->capacity) {
        LRUNode *to_free = cache->tail;
        cache->tail = to_free->prev;

        if (cache->tail != NULL)
            cache->tail->next = NULL;

        free(to_free);
        --(cache->count);
    }

    ++(cache->count);
}

VariableRecord* lru_get(LRU_Cache *cache, const char *key) {
    size_t index = hash_function(key);

    for (LRUNode *current = cache->head; current != NULL; current = current->next) {
        if (strcmp(current->key, key) == 0) {
            // Move to front
            if (current == cache->head)
                return current->record;

            if (current->prev)
                current->prev->next = current->next;

            if (current->next)
                current->next->prev = current->prev;

            if (cache->tail == current)
                cache->tail = current->prev;

            current->next = cache->head;
            current->prev = NULL;
            cache->head->prev = current;
            cache->head = current;

            return current->record;
        }
    }

    return NULL;
}

void free_lru_cache(LRU_Cache *cache) {
    LRUNode *current = cache->head;

    while (current != NULL) {
        LRUNode *next = current->next;

        free(current);
        current = next;
    }

    free(cache);
}

// Main function for testing
int main() {
    srand(time(NULL));

    Matrix matrix = create_matrix(10, 10);

    VariableRecord record1;
    strcpy(record1.key, "record1");
    record1.dynamic_string = strdup("Dynamic string 1");
    record1.nested_vector = create_vector();

    insert_hash_record(&record1);

    LRU_Cache *cache = create_lru_cache(5);
    lru_put(cache, record1.key, &record1);

    VariableRecord *cached_record = lru_get(cache, "record1");
    if (cached_record != NULL)
        printf("Found cached record with key: %s\n", cached_record->key);

    delete_hash_record("record1");
    free_lru_cache(cache);
    free_matrix(&matrix);

    return 0;
}
```

### Key Points:

- **Dynamic Memory Management**: The code dynamically allocates memory for matrices, vectors, strings, and hash table records. It ensures proper deallocation to prevent memory leaks.

- **Concurrency**: Uses `pthread_mutex_t` to handle concurrent access to the hash table.

- **LRU Cache**: Implements a simple LRU cache using a doubly linked list for efficient insertion, deletion, and access operations.

- **Hash Table with Chaining**: The hash table uses chaining (linked lists) for collision resolution. Each bucket in the array points to a linked list of `VariableRecord` structures.

- **Logging and Periodic Saving**: For simplicity, logging and periodic saving are not implemented here but should be integrated using appropriate libraries or custom implementations as needed.

This implementation provides a foundation for managing complex data structures with concurrent access while maintaining efficiency and robustness.']

['Below is a C implementation of a dynamic array and linked list system for managing environmental records with consideration for high-performance and scalability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    float temperature;
    float humidity;
    char location[100];
    short shortValue;
    int intValue;
    struct Record* next;
} Record;

#define INITIAL_CAPACITY 1024
#define KEY_RANGE_MIN 1
#define KEY_RANGE_MAX 10000
#define OFFSET_CONSTANT 100

typedef struct {
    Record** array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

typedef struct {
    Record* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void initializeRandom() {
    time_t t;
    srand((unsigned)time(&t));
}

size_t generateUniqueKey(size_t i, int keys[], size_t usedKeys) {
    size_t key = rand() % (KEY_RANGE_MAX - KEY_RANGE_MIN + 1) + KEY_RANGE_MIN;
    while (usedKeys > 0 && keys[--usedKeys] == key);
    return key;
}

void initializeOffsetAndKey(size_t n, int* offset, int* key) {
    for (size_t i = 0; i < n; ++i) {
        key[i] = generateUniqueKey(i, key, i);
        offset[i] = (i == 0 ? 0 : offset[i - 1]) + key[i] + OFFSET_CONSTANT;
    }
}

DynamicArray* createDynamicArray() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = calloc(INITIAL_CAPACITY, sizeof(Record*));
    if (!da->array) { free(da); return NULL; }

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void resizeDynamicArray(DynamicArray* da) {
    size_t newCapacity = da->capacity * 2;
    Record** newArray = realloc(da->array, newCapacity * sizeof(Record*));
    if (!newArray) return; // Handle error in real implementation

    for (size_t i = da->capacity; i < newCapacity; ++i) {
        newArray[i] = NULL;
    }

    da->array = newArray;
    da->capacity = newCapacity;
}

void addRecordToDynamicArray(DynamicArray* da, Record* record) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) resizeDynamicArray(da);

    da->array[da->size++] = record;
    pthread_mutex_unlock(&da->lock);
}

LinkedList* createLinkedList() {
    LinkedList* ll = malloc(sizeof(LinkedList));
    if (!ll) return NULL;

    ll->head = NULL;
    ll->size = 0;
    pthread_mutex_init(&ll->lock, NULL);

    return ll;
}

void addRecordToLinkedList(LinkedList* ll, Record* record) {
    pthread_mutex_lock(&ll->lock);

    record->next = ll->head;
    ll->head = record;

    ++ll->size;
    pthread_mutex_unlock(&ll->lock);
}

Record* createEnvironmentalRecord(float temperature, float humidity, const char* location) {
    Record* rec = malloc(sizeof(Record));
    if (!rec) return NULL;

    rec->temperature = temperature;
    rec->humidity = humidity;
    snprintf(rec->location, sizeof(rec->location), "%s", location);
    rec->shortValue = (short)(rand() % 1000);
    rec->intValue = rand() % 100000;
    rec->next = NULL;

    return rec;
}

void freeDynamicArray(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i]) free(da->array[i]);
    }

    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

void freeLinkedList(LinkedList* ll) {
    pthread_mutex_lock(&ll->lock);

    Record* current = ll->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&ll->lock);
    pthread_mutex_destroy(&ll->lock);
    free(ll);
}

int main() {
    initializeRandom();

    size_t numKeys = 1000000; // Example number of keys
    int* offset = malloc(numKeys * sizeof(int));
    int* key = malloc(numKeys * sizeof(int));

    if (!offset || !key) {
        printf("Memory allocation failed\n");
        return 1;
    }

    initializeOffsetAndKey(numKeys, offset, key);

    DynamicArray* da = createDynamicArray();
    LinkedList* ll = createLinkedList();

    if (!da || !ll) {
        free(offset);
        free(key);
        printf("Failed to initialize data structures\n");
        return 1;
    }

    // Example of adding records
    for (size_t i = 0; i < numKeys; ++i) {
        Record* record = createEnvironmentalRecord(
            rand() % 50,   // Temperature
            rand() % 100,  // Humidity
            "ExampleLocation"
        );

        if (!record) continue;

        addRecordToDynamicArray(da, record);
        addRecordToLinkedList(ll, record);
    }

    free(offset);
    free(key);

    freeDynamicArray(da);
    freeLinkedList(ll);

    return 0;
}
