This code provides a comprehensive system for handling up to one million environmental records using both a dynamic array and linked list. It initializes necessary data structures, manages memory allocation/deallocation safely, and includes thread safety with mutex locks. The function generates unique keys and offsets as specified and fills the `Record` structure with random values within given ranges. Error checking is included for memory allocation failures to ensure robustness.']

['Below is a C code example implementing the described functionality using pthreads for thread safety and POSIX `time.h` for timestamp handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define RETENTION_PERIOD (24 * 60 * 60) // One day in seconds

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

typedef struct {
    char* sensor_id; 
    SensorData data;
} HashTableEntry;

typedef struct {
    size_t capacity;
    size_t size;
    HashTableEntry** entries;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->size = 0;
    table->entries = (HashTableEntry**)calloc(initial_capacity, sizeof(HashTableEntry*));

    if (!table->entries) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable* table);

void insert_or_update_sensor_data(HashTable* table, const char *sensor_id, SensorData data) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(sensor_id) % table->capacity;

    while (table->entries[index]) {
        if (strcmp(table->entries[index]->sensor_id, sensor_id) == 0) {
            table->entries[index]->data = data;
            break;
        }
        index = (index + 1) % table->capacity; // Linear probing
    }

    if (!table->entries[index]) {
        table->entries[index] = (HashTableEntry*)malloc(sizeof(HashTableEntry));
        table->entries[index]->sensor_id = strdup(sensor_id);
        table->entries[index]->data = data;
        table->size++;

        if ((double)table->size / table->capacity > 0.75) { // Load factor threshold
            resize_hash_table(table);
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    HashTableEntry** new_entries = (HashTableEntry**)calloc(new_capacity, sizeof(HashTableEntry*));

    if (!new_entries) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->entries[i]) {
            unsigned long index = hash_function(table->entries[i]->sensor_id) % new_capacity;
            while (new_entries[index]) {
                index = (index + 1) % new_capacity; // Linear probing
            }
            new_entries[index] = table->entries[i];
        }
    }

    free(table->entries);
    table->entries = new_entries;
    table->capacity = new_capacity;
}

SensorData* get_sensor_data(HashTable* table, const char *sensor_id) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(sensor_id) % table->capacity;

    while (table->entries[index]) {
        if (strcmp(table->entries[index]->sensor_id, sensor_id) == 0) {
            pthread_mutex_unlock(&table->lock);
            return &(table->entries[index]->data);
        }
        index = (index + 1) % table->capacity; // Linear probing
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void remove_stale_data(HashTable* table, time_t current_time) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->entries[i]) {
            time_t entry_age = current_time - table->entries[i]->data.timestamp;
            if (entry_age > RETENTION_PERIOD) {
                free(table->entries[i]->sensor_id);
                free(table->entries[i]);
                table->entries[i] = NULL;
                --table->size;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->entries[i]) {
            free(table->entries[i]->sensor_id);
            free(table->entries[i]);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->entries);
    free(table);
}

// Example usage
int main() {
    HashTable* table = create_hash_table(INITIAL_CAPACITY);

    if (!table) return EXIT_FAILURE;

    SensorData data = {23.5, 60.0, time(NULL)};
    insert_or_update_sensor_data(table, "sensor_1", data);

    SensorData* retrieved_data = get_sensor_data(table, "sensor_1");
    if (retrieved_data) {
        printf("Temperature: %.2f, Humidity: %.2f\n", retrieved_data->temperature, retrieved_data->humidity);
    }

    time_t current_time = time(NULL);
    remove_stale_data(table, current_time);

    destroy_hash_table(table);
    return EXIT_SUCCESS;
}
