#include <time.h>

typedef struct {
    int value;
} record_t;

void free_resources(long *offsets, int *keys, record_t *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int is_unique_key(int key, const int *existing_keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (existing_keys[i] == key) return 0;
    }
    return 1;
}

void generate_unique_keys(int *keys, size_t num_keys) {
    srand(time(NULL));
    for (size_t i = 0; i < num_keys;) {
        int new_key = rand() % ((unsigned long long)RAND_MAX * 2); // Increase range
        if (is_unique_key(new_key, keys, i)) {
            keys[i++] = new_key;
        }
    }
}

void generate_random_records(record_t *records, size_t num_keys, int min_val, int max_val) {
    srand(time(NULL));
    for (size_t i = 0; i < num_keys;) {
        int new_value = rand() % (max_val - min_val + 1) + min_val;
        if (!is_unique_key(new_value, (int *)records, i)) continue;
        records[i].value = new_value;
        ++i;
    }
}

void manage_data_structures(size_t num_offsets, size_t num_keys, int min_record_value, int max_record_value, long **offsets_out, int **keys_out, record_t **records_out) {
    // Allocate and initialize offsets
    *offsets_out = (long *)calloc(num_offsets, sizeof(long));
    if (!*offsets_out) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets_out)[i] = rand() % ((unsigned long long)LONG_MAX + 1); // Ensure non-negative
    }

    // Allocate and initialize keys
    *keys_out = (int *)malloc(num_keys * sizeof(int));
    if (!*keys_out) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(*offsets_out);
        exit(EXIT_FAILURE);
    }
    generate_unique_keys(*keys_out, num_keys);

    // Allocate and initialize records
    *records_out = (record_t *)malloc(num_keys * sizeof(record_t));
    if (!*records_out) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(*offsets_out);
        free(*keys_out);
        exit(EXIT_FAILURE);
    }
    generate_random_records(*records_out, num_keys, min_record_value, max_record_value);

    // Ensure internal consistency
    for (size_t i = 0; i < num_keys; ++i) {
        if ((*offsets_out)[i] == (*keys_out)[i]) {
            fprintf(stderr, "Offset value collision with key at index %zu\n", i);
            free_resources(*offsets_out, *keys_out, *records_out);
            exit(EXIT_FAILURE);
        }
    }

    // Validate all offsets are within the valid range
    for (size_t i = 0; i < num_offsets; ++i) {
        if ((*offsets_out)[i] > LONG_MAX || (*offsets_out)[i] < 0) {
            fprintf(stderr, "Invalid offset value at index %zu\n", i);
            free_resources(*offsets_out, *keys_out, *records_out);
            exit(EXIT_FAILURE);
        }
    }

    // Simulate workload
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets_out)[i] += rand() % 100; // Example operation
    }
}

int main() {
    size_t num_offsets = 100000;
    size_t num_keys = 50000;
    int min_record_value = 1, max_record_value = 1000;

