#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define HASH_MAP_SIZE 256
#define MAX_PATH_LENGTH 256

typedef struct record {
    long offset;
    int key;
    int value;
    struct record *next;
} Record;

typedef struct inode {
    mode_t mode;
    uid_t uid;
    gid_t gid;
    off_t size;
    char *path;
    pthread_mutex_t lock;
} Inode;

typedef struct {
    Inode inodes[HASH_MAP_SIZE];
    int directory_count;
    pthread_mutex_t map_lock;
} HashMap;

typedef struct {
    Record *head;
    pthread_mutex_t list_lock;
} LinkedList;

void initialize_random() {
    srand((unsigned) time(NULL));
}

Record* create_record(long offset, int key, int value) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void add_record(LinkedList *list, Record *record) {
    pthread_mutex_lock(&list->list_lock);
    record->next = list->head;
    list->head = record;
    pthread_mutex_unlock(&list->list_lock);
}

Inode* hash_map_insert(HashMap *map, const char *path) {
    unsigned int hash_index = crc32(0L, Z_NULL, 0) & (HASH_MAP_SIZE - 1); // Placeholder for actual CRC calculation
    pthread_mutex_lock(&map->inodes[hash_index].lock);
    if (!map->inodes[hash_index].path) {
        map->inodes[hash_index].path = strdup(path);
        if (!map->inodes[hash_index].path) {
            pthread_mutex_unlock(&map->inodes[hash_index].lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&map->inodes[hash_index].lock);
    return &map->inodes[hash_index];
}

void initialize_collections(LinkedList *list, HashMap *hash_map) {
    initialize_random();

    pthread_mutex_init(&list->list_lock, NULL);
    list->head = NULL;

    for (int i = 0; i < HASH_MAP_SIZE; i++) {
        hash_map->inodes[i].path = NULL;
        pthread_mutex_init(&hash_map->inodes[i].lock, NULL);
    }
    pthread_mutex_init(&hash_map->map_lock, NULL);

    // Example directory paths initialization
    char base_path[MAX_PATH_LENGTH] = "/data/dir";
    for (int i = 0; i < hash_map->directory_count; i++) {
        char path[MAX_PATH_LENGTH];
        snprintf(path, sizeof(path), "%s%d", base_path, i);
        Inode *inode = hash_map_insert(hash_map, path);
        if (inode) {
            inode->mode = S_IFDIR | 0755;
            inode->uid = geteuid();
            inode->gid = getegid();
            inode->size = i * 1024; // Example size calculation
        }
    }

    // Initialize records with random values and add to list
    for (int i = 0; i < 100; i++) {
        Record *record = create_record(rand() % 100000, rand() % 256, rand() % 1024);
        if (record) {
            add_record(list, record);
        }
    }
}

void free_resources(LinkedList *list, HashMap *hash_map) {
    pthread_mutex_lock(&list->list_lock);
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->list_lock);

    for (int i = 0; i < HASH_MAP_SIZE; i++) {
        if (hash_map->inodes[i].path) {
            free(hash_map->inodes[i].path);
        }
        pthread_mutex_destroy(&hash_map->inodes[i].lock);
    }
    pthread_mutex_destroy(&list->list_lock);
    pthread_mutex_destroy(&hash_map->map_lock);
}

int main() {
    LinkedList list = {NULL, PTHREAD_MUTEX_INITIALIZER};
    HashMap hash_map = {{0}, 10, PTHREAD_MUTEX_INITIALIZER};

    initialize_collections(&list, &hash_map);

    // Perform operations...

    free_resources(&list, &hash_map);
    return 0;
}
