#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define MAX_RECORDS 10000000
#define RECORD_LIFESPAN 86400 // seconds (24 hours)
#define INITIAL_ARRAY_SIZE 1024

typedef struct {
    int value;
    char status[16];
    int priority;
} record_t;

typedef struct Node {
    record_t data;
    time_t last_accessed;
    struct Node* next;
} node_t;

typedef struct {
    node_t* head;
    pthread_mutex_t lock;
} record_list_t;

record_list_t record_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

unsigned long *offsets = NULL;
int *keys = NULL;
timestamp_t *timestamps = NULL;
size_t offset_size = 0;
size_t key_size = 0;
size_t timestamp_size = 0;

void resize_array_if_needed(size_t current_size, size_t* array_ptr) {
    if (*array_ptr == current_size) {
        *array_ptr *= 2;
        void* new_mem = realloc(*((void**)array_ptr), sizeof(**array_ptr) * (*array_ptr));
        if (new_mem != NULL)
            *((void**)array_ptr) = new_mem;
    }
}

record_t create_random_record(int min_val, int max_val) {
    record_t rec;
    rec.value = rand() % (max_val - min_val + 1) + min_val;
    strncpy(rec.status, "active", sizeof(rec.status));
    rec.priority = rand() % 10; // example priority range
    return rec;
}

void initialize_memory() {
    offsets = malloc(sizeof(unsigned long) * INITIAL_ARRAY_SIZE);
    keys = malloc(sizeof(int) * INITIAL_ARRAY_SIZE);
    timestamps = malloc(sizeof(time_t) * INITIAL_ARRAY_SIZE);

    offset_size = INITIAL_ARRAY_SIZE;
    key_size = INITIAL_ARRAY_SIZE;
    timestamp_size = INITIAL_ARRAY_SIZE;

    if (!offsets || !keys || !timestamps) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        exit(EXIT_FAILURE);
    }
}

void* fetch_api_data(void* args) {
    // Placeholder for API fetching logic
    return NULL;
}

void purge_expired_records() {
    pthread_mutex_lock(&record_list.lock);

    node_t** curr = &record_list.head;
    while (*curr != NULL) {
        if (time(NULL) - (*curr)->last_accessed > RECORD_LIFESPAN) {
            node_t* expired = *curr;
            *curr = (*curr)->next;
            free(expired);
        } else {
            curr = &(*curr)->next;
        }
    }

    pthread_mutex_unlock(&record_list.lock);
}

void add_record(record_t rec, unsigned long offset, int key) {
    pthread_mutex_lock(&record_list.lock);

    resize_array_if_needed(offset_size, (size_t*)&offsets);
    offsets[offset_size - 1] = offset;

    resize_array_if_needed(key_size, (size_t*)&keys);
    keys[key_size - 1] = key;

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
        pthread_mutex_unlock(&record_list.lock);
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return;
    }

    new_node->data = rec;
    new_node->last_accessed = time(NULL);
    new_node->next = record_list.head;
    record_list.head = new_node;

    pthread_mutex_unlock(&record_list.lock);
}

void export_record_state() {
    FILE* file = fopen("records_export.txt", "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    node_t* curr = record_list.head;
    while (curr != NULL) {
        fprintf(file, "%d %s %d\n", curr->data.value, curr->data.status, curr->data.priority);
        curr = curr->next;
    }

    fclose(file);
}

int main() {
    srand(time(NULL));
    initialize_memory();

    // Example: Add a record
    record_t rec = create_random_record(1, 100);
    add_record(rec, rand(), rand());

    // Periodically purge expired records
    while (1) {
        purge_expired_records();
        sleep(3600); // Check every hour
    }

    return 0;
}
