    INACTIVE,
    TERMINATED
} SessionState;

typedef struct UserSession {
    int UserID;
    time_t LastActivityTime;
    SessionState SessionState;
    struct UserSession* next;
} UserSession;

// Function to create a new session
UserSession* createUserSession(int userID, time_t lastActivityTime, SessionState state) {
    UserSession* newSession = (UserSession*)malloc(sizeof(UserSession));
    if (!newSession) return NULL; // Failed allocation

    newSession->UserID = userID;
    newSession->LastActivityTime = lastActivityTime;
    newSession->SessionState = state;
    newSession->next = NULL;

    return newSession;
}

// Function to add a session
void addSession(UserSession** head, int userID, time_t lastActivityTime, SessionState state) {
    UserSession* newSession = createUserSession(userID, lastActivityTime, state);
    if (!newSession) return; // Failed allocation

    newSession->next = *head;
    *head = newSession;
}

// Function to remove expired sessions
void removeExpiredSessions(UserSession** head) {
    time_t currentTime = time(NULL);
    UserSession* current = *head;
    UserSession* prev = NULL;

    while (current != NULL) {
        if ((currentTime - current->LastActivityTime) > 1800) { // 30 minutes
            UserSession* toDelete = current;
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(toDelete);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Function to get the count of active sessions with a specific state
int countActiveSessions(UserSession* head, SessionState state) {
    int count = 0;

    while (head != NULL) {
        if (head->SessionState == state) {
            ++count;
        }
        head = head->next;
    }

    return count;
}

// Function to batch delete all sessions inactive for more than 30 minutes
void batchDeleteInactiveSessions(UserSession** head) {
    removeExpiredSessions(head);
}

// Cleanup function to free all memory
void freeAllSessions(UserSession* head) {
    while (head != NULL) {
        UserSession* temp = head;
        head = head->next;
        free(temp);
    }
}

// Example usage
int main() {
    UserSession* sessionList = NULL;

    addSession(&sessionList, 1, time(NULL) - 600, ACTIVE); // Active 10 minutes ago
    addSession(&sessionList, 2, time(NULL) - 3600, INACTIVE); // Inactive 60 minutes ago

    printf("Active sessions: %d\n", countActiveSessions(sessionList, ACTIVE));

    batchDeleteInactiveSessions(&sessionList);
    printf("Active sessions after deletion: %d\n", countActiveSessions(sessionList, ACTIVE));

    freeAllSessions(sessionList);

    return 0;
}
```

### Explanation:

- **Data Structure**: A linked list is chosen for its ability to handle dynamic insertions and deletions efficiently without needing resizing. Each node in the list represents a `UserSession`.

- **Memory Management**: The code ensures safe memory allocation and deallocation by checking if allocations succeed and freeing nodes when they're no longer needed.

- **Concurrency Considerations**: The implementation does not include threading or locking mechanisms, which should be added based on specific concurrency needs (e.g., using mutexes for thread safety).

- **Batch Deletion**: Sessions inactive for more than 30 minutes are removed in `batchDeleteInactiveSessions`, which internally calls `removeExpiredSessions`.

This code provides a basic structure and can be extended with additional error handling, logging, or integration features as needed.']

