#include <pthread.h>
#include <time.h>

// Event types enum definition
typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C
} EventType;

// Structure to hold an event
typedef struct Event {
    long timestamp;
    EventType event_type;
    double status_score;
    struct Event* next; // Pointer for linked list structure
} Event;

// Dynamic array and linked list management structure
typedef struct {
    Event** events_array; // Array of pointers to Events
    size_t capacity;      // Current allocated capacity
    size_t count;         // Number of current elements
    Event* head;          // Head pointer for the linked list
    pthread_mutex_t lock; // Mutex for thread safety
} EventLogManager;

// Function prototypes
EventLogManager* initialize_event_log_manager(size_t initial_capacity);
int resize_event_array(EventLogManager* manager, size_t new_capacity);
void insert_event(EventLogManager* manager, long timestamp, EventType event_type, double status_score);
void cleanup_event_log_manager(EventLogManager** manager);

// Random number generator for event types
EventType get_random_event_type() {
    return (EventType)(rand() % 3); // Assuming 3 event types: A, B, C
}

EventLogManager* initialize_event_log_manager(size_t initial_capacity) {
    EventLogManager* manager = malloc(sizeof(EventLogManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->events_array = malloc(initial_capacity * sizeof(Event*));
    if (!manager->events_array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->head = NULL;

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < initial_capacity; ++i) {
        Event* event = malloc(sizeof(Event));
        if (!event) {
            cleanup_event_log_manager(&manager);
            return NULL;
        }
        manager->events_array[i] = event;

        double status_score = ((double)rand() / RAND_MAX) * 100.0; // Range [0, 100]
        long timestamp = i == 0 ? (long)status_score : manager->events_array[i - 1]->timestamp + status_score + 1;

        event->timestamp = timestamp;
        event->event_type = get_random_event_type();
        event->status_score = status_score;
        event->next = NULL;

        // Add to linked list
        pthread_mutex_lock(&manager->lock);
        if (!manager->head) {
            manager->head = event;
        } else {
            Event* current = manager->head;
            while (current->next) {
                current = current->next;
            }
            current->next = event;
        }
        manager->count++;
        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

int resize_event_array(EventLogManager* manager, size_t new_capacity) {
    Event** new_events_array = realloc(manager->events_array, new_capacity * sizeof(Event*));
    if (!new_events_array) return -1;

    manager->events_array = new_events_array;
    manager->capacity = new_capacity;

    for (size_t i = manager->count; i < new_capacity; ++i) {
        Event* event = malloc(sizeof(Event));
        if (!event) {
            // Cleanup partially resized array
            while (manager->count > 0) {
                free(manager->events_array[--manager->count]);
            }
            free(manager->events_array);
            manager->events_array = NULL;
            return -1;
        }

        double status_score = ((double)rand() / RAND_MAX) * 100.0; // Range [0, 100]
        long timestamp = i == 0 ? (long)status_score : manager->events_array[i - 1]->timestamp + status_score + 1;

        event->timestamp = timestamp;
        event->event_type = get_random_event_type();
        event->status_score = status_score;
        event->next = NULL;

        manager->events_array[i] = event;
    }

    return 0;
}

void insert_event(EventLogManager* manager, long timestamp, EventType event_type, double status_score) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        if (resize_event_array(manager, manager->capacity * 2) != 0) {
            printf("Failed to resize event array.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    Event* event = malloc(sizeof(Event));
    if (!event) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    event->timestamp = timestamp;
    event->event_type = event_type;
    event->status_score = status_score;
    event->next = NULL;

    manager->events_array[manager->count++] = event;

    // Add to linked list
    if (!manager->head) {
        manager->head = event;
    } else {
        Event* current = manager->head;
        while (current->next) {
            current = current->next;
        }
        current->next = event;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_event_log_manager(EventLogManager** manager) {
    if (!manager || !(*manager)) return;

    Event* current = (*manager)->head;
    while (current) {
        Event* next = current->next;
        free(current);
        current = next;
    }

    for (size_t i = 0; i < (*manager)->count; ++i) {
        free((*manager)->events_array[i]);
    }

    free((*manager)->events_array);
    pthread_mutex_destroy(&(*manager)->lock);
    free(*manager);
    *manager = NULL;
}

// Main function for demonstration
int main() {
    size_t initial_capacity = 10; // Example initial capacity
    EventLogManager* manager = initialize_event_log_manager(initial_capacity);

    if (!manager) {
        printf("Failed to initialize event log manager.\n");
        return 1;
    }

    // Simulate inserting an additional event
    insert_event(manager, 1234567890L, EVENT_TYPE_A, 42.0);

    // Cleanup resources
    cleanup_event_log_manager(&manager);

    return 0;
}
```

### Explanation:
- **Thread Safety**: The `pthread_mutex_t` is used to ensure that the operations on shared data (both array and linked list) are thread-safe.
- **Dynamic Resizing**: Both the dynamic array and linked list resize dynamically as more events are added. The array doubles in size when its capacity is reached, which minimizes frequent reallocations.
- **Initialization of Timestamps and Status Scores**: Each `timestamp` is calculated based on previous status scores plus a constant increment. Status scores are generated randomly within a specified range (0 to 100).
- **Memory Management**: Proper cleanup functions (`cleanup_event_log_manager`) ensure that all allocated memory is freed, preventing memory leaks.
- **Error Handling**: Checks for successful allocations and handles failures appropriately by cleaning up any partially allocated resources.

This code balances between initial allocation size and resizing efficiency while ensuring thread safety in concurrent environments.']

