```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_TABLE_SIZE 1000
#define MAX_SESSIONS 10000
#define SESSION_DURATION_SECONDS 3600 // e.g., 1 hour

typedef struct {
    int session_id;
    time_t login_time;
    time_t last_activity;
} Session;

typedef struct Node {
    Session data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
    pthread_mutex_t locks[INITIAL_TABLE_SIZE];
} HashTable;

// Hash function
unsigned int hash(int session_id, size_t table_size) {
    return session_id % table_size;
}

// Initialize hash table
HashTable* init_hash_table(size_t initial_size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = (Node**)calloc(initial_size, sizeof(Node*));
    ht->size = initial_size;

    for (size_t i = 0; i < initial_size; ++i)
        pthread_mutex_init(&ht->locks[i], NULL);

    if (!ht->table) {
        free(ht);
        return NULL;
    }

    return ht;
}

// Resize hash table
int resize_hash_table(HashTable* ht, size_t new_size) {
    Node** old_table = ht->table;
    size_t old_size = ht->size;

    ht->table = (Node**)calloc(new_size, sizeof(Node*));
    if (!ht->table) return -1;

    for (size_t i = 0; i < new_size; ++i)
        pthread_mutex_init(&ht->locks[i], NULL);

    ht->size = new_size;

    for (size_t i = 0; i < old_size; ++i) {
        Node* current = old_table[i];
        while (current) {
            Node* next = current->next;
            unsigned int new_index = hash(current->data.session_id, new_size);

            pthread_mutex_lock(&ht->locks[new_index]);
            current->next = ht->table[new_index];
            ht->table[new_index] = current;
            pthread_mutex_unlock(&ht->locks[new_index]);

            current = next;
        }
    }

    free(old_table);
    return 0;
}

// Insert session
int insert_session(HashTable* ht, Session session) {
    unsigned int index = hash(session.session_id, ht->size);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = session;
    new_node->next = NULL;

    pthread_mutex_lock(&ht->locks[index]);
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    pthread_mutex_unlock(&ht->locks[index]);

    return 0;
}

// Find session
Session* find_session(HashTable* ht, int session_id) {
    unsigned int index = hash(session_id, ht->size);

    pthread_mutex_lock(&ht->locks[index]);
    Node* current = ht->table[index];
    while (current) {
        if (current->data.session_id == session_id) {
            pthread_mutex_unlock(&ht->locks[index]);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&ht->locks[index]);

    return NULL;
}

// Delete session
int delete_session(HashTable* ht, int session_id) {
    unsigned int index = hash(session_id, ht->size);

    pthread_mutex_lock(&ht->locks[index]);
    Node *current = ht->table[index], *prev = NULL;

    while (current) {
        if (current->data.session_id == session_id) {
            if (prev)
                prev->next = current->next;
            else
                ht->table[index] = current->next;

            free(current);
            pthread_mutex_unlock(&ht->locks[index]);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&ht->locks[index]);
    return -1;
}

// Periodic synchronization function (placeholder)
void* sync_sessions(void* arg) {
    // Implement logic to periodically synchronize session data
    while (1) {
        sleep(60); // Sync every minute
        printf("Synchronizing sessions...\n");
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    HashTable* ht = init_hash_table(INITIAL_TABLE_SIZE);

    if (!ht) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return 1;
    }

    pthread_t sync_thread;
    pthread_create(&sync_thread, NULL, sync_sessions, NULL);

    // Simulate session insertions
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        Session s;
        s.session_id = rand() % MAX_SESSIONS;
        s.login_time = time(NULL);
        s.last_activity = s.login_time + rand() % SESSION_DURATION_SECONDS;

        if (insert_session(ht, s)) {
            fprintf(stderr, "Failed to insert session\n");
            break;
        }
    }

    // Simulate finding a session
    int test_id = rand() % MAX_SESSIONS;
    Session* found_session = find_session(ht, test_id);
    if (found_session) {
        printf("Found session: ID=%d, Last Activity=%ld\n", found_session->session_id, found_session->last_activity);
    } else {
        printf("Session not found: ID=%d\n", test_id);
    }

    // Clean up
    pthread_cancel(sync_thread);
    for (size_t i = 0; i < ht->size; ++i) {
        Node* current = ht->table[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->locks[0]); // Destroy the first lock as a representative

    return 0;
}
```

### Key Features:
- **Thread-Safety**: Uses mutexes to protect concurrent access.
- **Dynamic Resizing**: Resizes hash table when needed.
- **Session Management**: Insert, find, and delete session operations are provided.
- **Synchronization Placeholder**: A placeholder function for periodic synchronization.
- **Memory Handling**: Robust handling of memory allocation failures.']

