#define MAX_SENSOR_DATA 1000 // Define the size for the sliding window

typedef struct SensorData {
    time_t timestamp;
    int sensor_id;
    float temperature; // Celsius
    float humidity;     // Percentage
    float pressure;     // hPa
} SensorData;

// Memory pool structure
typedef struct {
    SensorData *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemPool;

// Global data structures
MemPool mem_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
SensorData sensor_window[MAX_SENSOR_DATA];
size_t window_start = 0;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Initialize memory pool
void init_mem_pool(size_t initial_capacity) {
    mem_pool.pool = malloc(sizeof(SensorData) * initial_capacity);
    if (!mem_pool.pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mem_pool.capacity = initial_capacity;
}

// Function to allocate memory from the pool
SensorData* alloc_sensor_data() {
    pthread_mutex_lock(&mem_pool.lock);

    if (mem_pool.used >= mem_pool.capacity) {
        // Resize the pool
        size_t new_capacity = mem_pool.capacity * 2;
        SensorData *new_pool = realloc(mem_pool.pool, sizeof(SensorData) * new_capacity);
        if (!new_pool) {
            pthread_mutex_unlock(&mem_pool.lock);
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        mem_pool.pool = new_pool;
        mem_pool.capacity = new_capacity;
    }

    SensorData* data = &mem_pool.pool[mem_pool.used++];
    pthread_mutex_unlock(&mem_pool.lock);
    return data;
}

// Function to add sensor data
void add_sensor_data(int sensor_id, float temperature, float humidity, float pressure) {
    pthread_rwlock_wrlock(&rwlock);

    // Initialize the new data point
    SensorData *data = alloc_sensor_data();
    time(&data->timestamp);
    data->sensor_id = sensor_id;
    data->temperature = temperature; // Probabilistic initialization could be applied here
    data->humidity = humidity;       // Similarly for humidity
    data->pressure = pressure;

    // Add to sliding window
    size_t index = (window_start + mem_pool.used - 1) % MAX_SENSOR_DATA;
    memcpy(&sensor_window[index], data, sizeof(SensorData));

    pthread_rwlock_unlock(&rwlock);
}

// Function to export data to CSV
void export_to_csv(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write header
    fprintf(file, "Timestamp,SensorID,Temperature,Humidity,Pressure\n");

    pthread_rwlock_rdlock(&rwlock);
    for (size_t i = 0; i < mem_pool.used; ++i) {
        size_t index = (window_start + i) % MAX_SENSOR_DATA;
        SensorData *data = &sensor_window[index];
        fprintf(file, "%ld,%d,%.2f,%.2f,%.2f\n", data->timestamp, data->sensor_id,
                data->temperature, data->humidity, data->pressure);
    }
    pthread_rwlock_unlock(&rwlock);

    fclose(file);
}

// Function to handle power outages and network disruptions
void recovery_mechanism() {
    // Implement logging, checkpointing, or other strategies here
    fprintf(stderr, "Recovery mechanism activated\n");
    // Additional logic for handling failures
}

// Main function (for demonstration purposes)
int main() {
    init_mem_pool(1024);

    // Simulate adding data
    add_sensor_data(1, 25.5, 60.0, 1013.25);
    add_sensor_data(2, 26.7, 55.0, 1012.80);

    export_to_csv("sensor_data.csv");

    recovery_mechanism();

    // Cleanup
    free(mem_pool.pool);
    return 0;
}
