['Here is a C implementation for the described DNS resolution function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/nameser.h>
#include <resolv.h>
#include <pthread.h>

#define MAX_DNS_QUERIES 10
#define IP_ADDRESS_BUFFER_SIZE 16

typedef struct {
    u_char ip_address[IP_ADDRESS_BUFFER_SIZE];
    int length;
} IPAddress;

typedef enum {
    SUCCESS,
    INVALID_HOSTNAME,
    DNS_RESOLUTION_FAILED,
    RATE_LIMIT_EXCEEDED
} ErrorCode;

// Mutex for logging and rate limiting
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t query_mutex = PTHREAD_MUTEX_INITIALIZER;

int concurrent_queries = 0;

void log_resolution(const char *hostname, int status) {
    pthread_mutex_lock(&log_mutex);
    FILE *logfile = fopen("dns_logs.txt", "a");
    if (logfile != NULL) {
        fprintf(logfile, "Hostname: %s, Status: %d\n", hostname, status);
        fclose(logfile);
    }
    pthread_mutex_unlock(&log_mutex);
}

int resolve_hostname(const char *hostname, IPAddress *ip_address) {
    int err;
    struct hostent *he;
    struct in_addr addr;

    // Rate limiting
    pthread_mutex_lock(&query_mutex);
    if (concurrent_queries >= MAX_DNS_QUERIES) {
        pthread_mutex_unlock(&query_mutex);
        log_resolution(hostname, RATE_LIMIT_EXCEEDED);
        return RATE_LIMIT_EXCEEDED;
    }
    concurrent_queries++;
    pthread_mutex_unlock(&query_mutex);

    // DNS resolution
    if ((he = gethostbyname(hostname)) == NULL) {
        log_resolution(hostname, DNS_RESOLUTION_FAILED);
        pthread_mutex_lock(&query_mutex);
        concurrent_queries--;
        pthread_mutex_unlock(&query_mutex);
        return DNS_RESOLUTION_FAILED;
    }

    if (inet_ntop(AF_INET, &((struct in_addr *) he->h_addr)->s_addr, 
                  (char*) ip_address->ip_address, IP_ADDRESS_BUFFER_SIZE) == NULL) {
        log_resolution(hostname, DNS_RESOLUTION_FAILED);
        pthread_mutex_lock(&query_mutex);
        concurrent_queries--;
        pthread_mutex_unlock(&query_mutex);
        return DNS_RESOLUTION_FAILED;
    }

    ip_address->length = strlen((const char *) ip_address->ip_address);

    log_resolution(hostname, SUCCESS);

    // Decrement query count after completion
    pthread_mutex_lock(&query_mutex);
    concurrent_queries--;
    pthread_mutex_unlock(&query_mutex);

    return SUCCESS;
}
```

### Key Considerations:
