} Record;

// Structure for Memory Pool Node
typedef struct MPoolNode {
    void *memory;
    struct MPoolNode *next;
} MPoolNode;

// Structure for a Thread-Safe Doubly Linked List of Records
typedef struct RecordNode {
    Record data;
    struct RecordNode *prev, *next;
} RecordNode;

// Global Variables (Memory Pools and Mutexes)
MPoolNode *offsetPool = NULL, *keyPool = NULL, *recordPool = NULL, *timestampPool = NULL, *metadataPool = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
RecordNode *head = NULL, *tail = NULL;

// Function Prototypes
void initializePools(size_t size, int numElements);
void* allocateFromPool(MPoolNode **pool);
void freeToPool(MPoolNode **pool, void *memory);

void trafficFlowManagement(void) {
    // Initialize memory pools for collections
    initializePools(sizeof(int), 1000); // offset pool
    initializePools(sizeof(int), 1000); // key pool
    initializePools(sizeof(Record), 1000); // record pool
    initializePools(sizeof(time_t), 1000); // timestamp pool
    initializePools(sizeof(char *), 1000); // metadata pool

    pthread_mutex_lock(&lock);

    // Example operation: Add a new record
    Record *newRecord = (Record *)allocateFromPool(&recordPool);
    if (newRecord) {
        newRecord->id = rand() % 256;
        newRecord->key = rand() % 1000;
        newRecord->value = (float)rand() / RAND_MAX;
        newRecord->timestamp = time(NULL);
        newRecord->metadata = (char *)allocateFromPool(&metadataPool);

        if (!newRecord->metadata) {
            perror("Failed to allocate metadata");
            freeToPool(&recordPool, newRecord);
            pthread_mutex_unlock(&lock);
            return;
        }

        snprintf(newRecord->metadata, 256, "Metadata for key %d", newRecord->key);

        // Insert into doubly linked list
        RecordNode *newNode = (RecordNode *)allocateFromPool(&recordPool);
        if (!newNode) {
            perror("Failed to allocate record node");
            freeToPool(&recordPool, newRecord);
            pthread_mutex_unlock(&lock);
            return;
        }

        newNode->data = *newRecord;

        if (tail) {
            tail->next = newNode;
            newNode->prev = tail;
        } else {
            head = newNode;
        }
        newNode->next = NULL;
        tail = newNode;

        // Free allocated memory back to pool
        freeToPool(&recordPool, newRecord);
    }

    pthread_mutex_unlock(&lock);

    // Additional functionality would include:
    // - Removing records older than 20 minutes
    // - Querying by IP or protocol type
    // - Generating traffic reports and handling third-party tool failures
}

// Helper functions for memory pool management
void initializePools(size_t size, int numElements) {
    MPoolNode *pool = (MPoolNode *)malloc(numElements * sizeof(MPoolNode));
    char *data = (char *)malloc(numElements * size);

    for (int i = 0; i < numElements; ++i) {
        pool[i].memory = data + i * size;
        pool[i].next = (i == numElements - 1) ? NULL : &pool[i + 1];
    }

    switch(size) {
        case sizeof(int): offsetPool = pool; break;
        case sizeof(int): keyPool = pool; break;
        case sizeof(Record): recordPool = pool; break;
        case sizeof(time_t): timestampPool = pool; break;
        case sizeof(char *): metadataPool = pool; break;
    }
}

void* allocateFromPool(MPoolNode **pool) {
    pthread_mutex_lock(&lock);
    if (*pool) {
        MPoolNode *node = *pool;
        *pool = node->next;
        void *memory = node->memory;
        pthread_mutex_unlock(&lock);
        return memory;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void freeToPool(MPoolNode **pool, void *memory) {
    MPoolNode *node = (MPoolNode *)malloc(sizeof(MPoolNode));
    node->memory = memory;

    pthread_mutex_lock(&lock);
    node->next = *pool;
    *pool = node;
    pthread_mutex_unlock(&lock);
}

int main() {
    trafficFlowManagement();
    return 0;
}
