#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1000

typedef enum {
    MESSAGE,
    LIKE,
    COMMENT
} InteractionType;

typedef struct {
    time_t timestamp;
    InteractionType type;
} Interaction;

typedef struct {
    char *name;
    int age;
    char *location;
    Interaction **interactions; // Dynamic array of pointers to interactions
    size_t interaction_count;
    size_t capacity;
    char **friends; // Dynamic array of friend names
    size_t friends_count;
    size_t friends_capacity;
} UserProfile;

typedef struct {
    UserProfile **profiles;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ProfileManager;

UserProfile* create_user_profile() {
    UserProfile *profile = (UserProfile*)malloc(sizeof(UserProfile));
    profile->name = "User" + rand();
    profile->age = 18 + rand() % 80;
    profile->location = "Location" + rand();
    profile->interactions = NULL;
    profile->interaction_count = 0;
    profile->capacity = 10; // Initial capacity
    profile->interactions = (Interaction**)malloc(profile->capacity * sizeof(Interaction*));

    profile->friends = NULL;
    profile->friends_count = 0;
    profile->friends_capacity = 10;
    profile->friends = (char**)malloc(profile->friends_capacity * sizeof(char*));

    return profile;
}

void destroy_user_profile(UserProfile *profile) {
    for(size_t i = 0; i < profile->interaction_count; ++i) {
        free(profile->interactions[i]);
    }
    free(profile->interactions);
    for(size_t i = 0; i < profile->friends_count; ++i) {
        free(profile->friends[i]);
    }
    free(profile->friends);
    free(profile->name);
    free(profile->location);
    free(profile);
}

void add_interaction(UserProfile *profile, InteractionType type) {
    if (profile->interaction_count >= profile->capacity) {
        size_t new_capacity = profile->capacity * 2;
        profile->interactions = realloc(profile->interactions, new_capacity * sizeof(Interaction*));
        profile->capacity = new_capacity;
    }

    Interaction *interaction = malloc(sizeof(Interaction));
    interaction->timestamp = time(NULL);
    interaction->type = type;

    profile->interactions[profile->interaction_count++] = interaction;
}

void add_friend(UserProfile *profile, const char *friend_name) {
    if (profile->friends_count >= profile->friends_capacity) {
        size_t new_capacity = profile->friends_capacity * 2;
        profile->friends = realloc(profile->friends, new_capacity * sizeof(char*));
        profile->friends_capacity = new_capacity;
    }

    char *friend_copy = strdup(friend_name);
    profile->friends[profile->friends_count++] = friend_copy;
}

void remove_user_profile(ProfileManager *manager, int index) {
    if (index < 0 || index >= manager->count) return;

    destroy_user_profile(manager->profiles[index]);

    for(size_t i = index; i < manager->count - 1; ++i) {
        manager->profiles[i] = manager->profiles[i + 1];
    }

    manager->count--;
}

void initialize_profile_manager(ProfileManager *manager, size_t initial_size) {
    manager->profiles = (UserProfile**)malloc(initial_size * sizeof(UserProfile*));
    manager->count = 0;
    manager->capacity = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_user_profile(ProfileManager *manager) {
    if(manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->profiles = realloc(manager->profiles, new_capacity * sizeof(UserProfile*));
        manager->capacity = new_capacity;
    }

    UserProfile *new_profile = create_user_profile();
    pthread_mutex_lock(&manager->lock);
    manager->profiles[manager->count++] = new_profile;
    pthread_mutex_unlock(&manager->lock);
}

UserProfile* get_user_profile(ProfileManager *manager, int index) {
    if (index < 0 || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    UserProfile *profile = manager->profiles[index];
    pthread_mutex_unlock(&manager->lock);

    return profile;
}

// Example usage
int main() {
    ProfileManager manager;
    initialize_profile_manager(&manager, INITIAL_POOL_SIZE);

    add_user_profile(&manager); // Add a user profile
    add_interaction(manager.profiles[0], MESSAGE); // Add an interaction to the first profile

    UserProfile *retrievedProfile = get_user_profile(&manager, 0);
    if (retrievedProfile) {
        printf("User Name: %s\n", retrievedProfile->name);
    }

    remove_user_profile(&manager, 0); // Remove a user profile
    pthread_mutex_destroy(&manager.lock);
    free(manager.profiles);

    return 0;
}
```

