size_t pool_size = MAX_MEMORY_USAGE; // Maximum allocated size for simplicity
pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Hash Functions
unsigned long hash_int(int key, unsigned long table_size) {
    return (key * 2654435761u) % table_size;
}

unsigned long hash_str(const char* str, unsigned long table_size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % table_size;
}

// Custom memory management
void* custom_malloc(size_t size) {
    pthread_mutex_lock(&mem_pool_lock);
    void* ptr = malloc(size);
    if (!ptr && current_memory_usage + size <= pool_size) {
        // Allocate from memory pool if possible
        void* pool_ptr = (char*)memory_pool + current_memory_usage;
        current_memory_usage += size;
        ptr = pool_ptr;
    }
    pthread_mutex_unlock(&mem_pool_lock);
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);  // In a real implementation, handle memory pool
}

// Function to initialize the hash table with given sizes
HashTable* init_hash_table(unsigned long size1, unsigned long size2) {
    HashTable* ht = (HashTable*)custom_malloc(sizeof(HashTable));

    pthread_mutex_init(&ht->lock, NULL);
    ht->table1 = (Node**)custom_calloc(size1, sizeof(Node*));
    ht->table2 = (Node**)custom_calloc(size2, sizeof(Node*));

    if (!ht->table1 || !ht->table2) {
        custom_free(ht->table1);
        custom_free(ht->table2);
        custom_free(ht);
        return NULL;
    }

    return ht;
}

// Insert function
int insert_key_value(HashTable* ht, void* key, size_t key_size, Record* value) {
    pthread_mutex_lock(&ht->lock);

    unsigned long hash1 = (key_size == sizeof(int)) ? 
                          hash_int(*(int*)key, HASH_TABLE_1_SIZE) : 
                          hash_str((char*)key, HASH_TABLE_1_SIZE);

    unsigned long hash2 = (key_size == sizeof(int)) ?
                          hash_int(*(int*)key, HASH_TABLE_2_SIZE) :
                          hash_str((char*)key, HASH_TABLE_2_SIZE);

    Node* node = custom_malloc(sizeof(Node));
    memcpy(&node->key, key, key_size);
    node->key_size = key_size;
    node->value = value;

    if (insert_node(ht->table1, hash1, node) != 0) {
        custom_free(node);
        pthread_mutex_unlock(&ht->lock);
        return -1; // Fail to insert
    }

    ht->count++;
    pthread_mutex_unlock(&ht->lock);
    return 0;
}

int insert_node(Node** table, unsigned long hash, Node* node) {
    // Implementation of Cuckoo Hashing with collision resolution
    for (int i = 0; i < MAX_KICKS; ++i) { // Assume a constant max number of kicks to prevent infinite loop
        Node* existing = table[hash];
        if (!existing) {
            table[hash] = node;
            return 0;
        }

        node->next = existing;
        unsigned long new_hash = (hash == 0) ? hash2 : hash1; // Swap tables for cuckoo
        table[hash] = node;

        node = existing;
        hash = (hash == 0) ? new_hash : ((key_size == sizeof(int)) ?
                                        hash_int(*(int*)node->key.int_key, 
                                                  (hash == 0 ? HASH_TABLE_2_SIZE : HASH_TABLE_1_SIZE)) :
                                        hash_str((char*)node->key.str_key,
                                                 (hash == 0 ? HASH_TABLE_2_SIZE : HASH_TABLE_1_SIZE)));
    }
    return -1;
}

// Lookup function
Record* lookup_value(HashTable* ht, void* key, size_t key_size) {
    pthread_mutex_lock(&ht->lock);

    unsigned long hash1 = (key_size == sizeof(int)) ? 
                          hash_int(*(int*)key, HASH_TABLE_1_SIZE) : 
                          hash_str((char*)key, HASH_TABLE_1_SIZE);

    unsigned long hash2 = (key_size == sizeof(int)) ?
                          hash_int(*(int*)key, HASH_TABLE_2_SIZE) :
                          hash_str((char*)key, HASH_TABLE_2_SIZE);

    Record* value = lookup_node(ht->table1, hash1, key, key_size);
    if (!value)
        value = lookup_node(ht->table2, hash2, key, key_size);

    pthread_mutex_unlock(&ht->lock);
    return value;
}

Record* lookup_node(Node** table, unsigned long hash, void* key, size_t key_size) {
    Node* node = table[hash];
    while (node) {
        if ((key_size == sizeof(int)) && (*(int*)&(node->key.int_key) == *(int*)key) ||
            (key_size == strlen((char*)key) + 1 && strcmp(node->key.str_key, (char*)key) == 0)) {
            return (Record*)node->value;
        }
        node = node->next;
    }
    return NULL;
}

// Resizing function
void* resize_background(void* arg) {
    // Implementation of asynchronous resizing logic
    while (!is_resizing) { 
        pthread_mutex_lock(&resize_lock);
        if ((hash_table.count / (HASH_TABLE_1_SIZE + HASH_TABLE_2_SIZE)) > 0.75) {
            is_resizing = 1;
        }
        pthread_mutex_unlock(&resize_lock);

        if (is_resizing) {
            // Resize logic here
            // Ensure thread safety and minimize disruption using double buffering or similar techniques
        }

        sleep(1); // Check periodically
    }
    return NULL;
}

// Serialization function
int serialize_hash_table(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return -1;

    pthread_mutex_lock(&hash_table.lock);
    for (unsigned long i = 0; i < HASH_TABLE_1_SIZE; ++i) {
        Node* node = hash_table.table1[i];
        while (node) {
            fwrite(&(node->key), sizeof(KeyUnion), 1, file);
            fwrite(&(node->value), sizeof(Record), 1, file);
            node = node->next;
        }
    }

    for (unsigned long i = 0; i < HASH_TABLE_2_SIZE; ++i) {
        Node* node = hash_table.table2[i];
        while (node) {
            fwrite(&(node->key), sizeof(KeyUnion), 1, file);
            fwrite(&(node->value), sizeof(Record), 1, file);
            node = node->next;
        }
    }

    fclose(file);
    pthread_mutex_unlock(&hash_table.lock);

    return 0;
}

// Main function
int main() {
    // Initialize hash table
    HashTable* ht = init_hash_table(HASH_TABLE_1_SIZE, HASH_TABLE_2_SIZE);

    // Create background resizing thread
    pthread_t resize_thread;
    pthread_create(&resize_thread, NULL, resize_background, NULL);

    // Use the hash table here...

    return 0;
}
```

