#define RECORD_SIZE 128
#define TABLE_SIZE 1000

typedef struct {
    int value;
    char buffer[RECORD_SIZE];
} record;

typedef struct HashTableEntry {
    int key;
    record rec;
    struct HashTableEntry* next;
} HashTableEntry;

typedef struct {
    HashTableEntry** table;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash_function(int key) {
    return (unsigned int)(key % TABLE_SIZE);
}

HashTable* create_hash_table(size_t capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(capacity, sizeof(HashTableEntry*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }
    ht->capacity = capacity;
    pthread_mutex_init(&ht->lock, NULL);

    for (size_t i = 0; i < capacity; ++i)
        ht->table[i] = NULL;

    return ht;
}

void free_hash_table(HashTable* ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->capacity; ++i) {
        HashTableEntry* entry = ht->table[i];
        while (entry) {
            HashTableEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int insert_record(HashTable* ht, int key, record rec) {
    if (!ht) return -1;

    unsigned int index = hash_function(key);

    HashTableEntry** entry = &ht->table[index];

    pthread_mutex_lock(&ht->lock);
    while (*entry) {
        if ((*entry)->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return 0; // Key already exists
        }
        entry = &(*entry)->next;
    }

    HashTableEntry* new_entry = malloc(sizeof(HashTableEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Memory allocation failure
    }

    new_entry->key = key;
    new_entry->rec = rec;
    new_entry->next = *entry;

    *entry = new_entry;
    pthread_mutex_unlock(&ht->lock);

    return 1; // Success
}

record* lookup_record(HashTable* ht, int key) {
    if (!ht) return NULL;

    unsigned int index = hash_function(key);

    HashTableEntry* entry = ht->table[index];

    pthread_mutex_lock(&ht->lock);
    while (entry) {
        if (entry->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return &entry->rec;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL; // Not found
}

void serialize_hash_table(HashTable* ht, const char* filename) {
    if (!ht || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&ht->capacity, sizeof(size_t), 1, file);

    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->capacity; ++i) {
        HashTableEntry* entry = ht->table[i];
        while (entry) {
            fwrite(&entry->key, sizeof(int), 1, file);
            fwrite(&entry->rec.value, sizeof(record), 1, file);
            entry = entry->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);

    fclose(file);
}

void deserialize_hash_table(HashTable* ht, const char* filename) {
    if (!ht || !filename) return;

    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);

    free_hash_table(ht);
    *ht = *(create_hash_table(capacity));

    pthread_mutex_lock(&ht->lock);
    while (fread(&(int){0}, sizeof(int), 1, file)) {
        record rec;
        fread(&rec, sizeof(record), 1, file);
        insert_record(ht, rec.value, rec);
    }
    pthread_mutex_unlock(&ht->lock);

    fclose(file);
}

void test_function(const char* label, void (*f)()) {
    printf("Testing: %s\n", label);
    f();
    // Assume 'blueslip' is reset here.
}

