        memset(rec.buffer, 0, RECORD_SIZE);

        insert_record(ht, i, rec);
    }

    test_function("Insert and lookup", [](){
        for (size_t i = 0; i < TABLE_SIZE; ++i) {
            record* found = lookup_record(ht, (int)i);
            if (!found || found->value != rand() % 100) {
                printf("Test failed: Record not found or incorrect.\n");
