#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record record;
    long offset;
    int key;
    struct Node* next;
} Node;

// Mutex for thread-safe operations on the linked list
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(int key, long cumulative_sum) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->record.s = rand() % 100;  // Random short value between 0 and 99
    node->record.i = rand() % 10000;  // Random int value between 0 and 9999
    node->record.f = (float)(rand() % 1000) / 10.0f;  // Random float value

    node->offset = cumulative_sum;
    node->key = key;
    node->next = NULL;

    return node;
}

void free_linked_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

Node* allocate_and_initialize_records(int num_records, int key_range_start, int key_range_end) {
    if (num_records <= 0 || key_range_start >= key_range_end)
        return NULL;

    Node* head = NULL;
    Node* tail = NULL;
    long cumulative_sum = 0;
    pthread_t tid;

    // Initialize random number generator
    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        int key = key_range_start + rand() % (key_range_end - key_range_start);

        Node* new_node = create_node(key, cumulative_sum);
        if (!new_node) {
            free_linked_list(head);
            return NULL;
        }

        pthread_mutex_lock(&list_mutex);
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
        pthread_mutex_unlock(&list_mutex);

        cumulative_sum += key;

        // Example: spawn a thread for concurrent modification (optional)
        if (pthread_create(&tid, NULL, NULL, NULL) != 0) { 
            perror("Failed to create thread");
        }

        // Detach the thread to allow independent execution
        pthread_detach(tid);
    }

    return head;
}

int main() {
    int num_records = 10;
    int key_range_start = 1;
    int key_range_end = 100;

    Node* records = allocate_and_initialize_records(num_records, key_range_start, key_range_end);

    if (records) {
        // Traverse and print the list for demonstration
        Node* current = records;
        while (current != NULL) {
            printf("Record: s=%d, i=%d, f=%.2f | Offset=%ld, Key=%d\n",
                   current->record.s,
                   current->record.i,
                   current->record.f,
                   current->offset,
                   current->key);
            current = current->next;
        }

        free_linked_list(records);
    } else {
        printf("Failed to allocate and initialize records.\n");
    }

    pthread_mutex_destroy(&list_mutex);

    return 0;
}
```

This code implements a function that dynamically allocates and initializes an array of `Record` structures within a linked list. It safely manages memory, ensuring no leaks occur and supports concurrent modifications using thread-safe operations with mutex locks. The `create_node` function sets each record's fields to random values, while `allocate_and_initialize_records` handles the logic for setting up the list and calculating offset values based on cumulative key sums. Error handling ensures that if any allocation fails, previously allocated memory is freed correctly.']

