    profile->id = id;
    memcpy(&profile->info, info, sizeof(PersonalInfo));
    profile->interaction_count = 0;
    profile->max_interactions = 100; // initial size
    profile->interactions = (Interaction*)memory_pool_alloc(profile->max_interactions * sizeof(Interaction));

    return profile;
}

void add_interaction(UserProfile* profile, const Interaction* interaction) {
    pthread_rwlock_wrlock(&profile->lock);

    if (profile->interaction_count >= profile->max_interactions) {
        size_t new_max = profile->max_interactions * PROFILE_RESIZE_FACTOR;
        Interaction* new_interactions = (Interaction*)memory_pool_alloc(new_max * sizeof(Interaction));

        memcpy(new_interactions, profile->interactions, profile->interaction_count * sizeof(Interaction));
        memory_pool_free(profile->interactions);
        profile->interactions = new_interactions;
        profile->max_interactions = new_max;
    }

    profile->interactions[profile->interaction_count++] = *interaction;

    pthread_rwlock_unlock(&profile->lock);
