['Below is a C function that implements your requirements. The function uses dynamic memory allocation for three arrays: one for `long` offset values, another for `int` keys, and an array of `record` structures containing a single `int` value. It also includes error handling and ensures proper deallocation to prevent memory leaks. Additionally, it incorporates thread-safe mechanisms using mutexes to handle concurrent access.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1000
#define LOG_FILE "memory_usage.log"

typedef struct {
    int value;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t size) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - Allocated memory: %zu bytes\n", ctime(&now), size);
        fclose(log_file);
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

int initialize_arrays(size_t array_size, long range_min, long range_max, size_t *used_memory) {
    pthread_mutex_lock(&lock);

    if (array_size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: Array size exceeds maximum limit.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    long *offsets = malloc(array_size * sizeof(long));
    int *keys = malloc(array_size * sizeof(int));
    record *records = malloc(array_size * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free_memory(offsets, keys, records);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        offsets[i] = range_min + rand() % (range_max - range_min + 1);
        keys[i] = rand();
        records[i].value = rand() % (range_max - range_min + 1); // Random value within the specified range
    }

    *used_memory = array_size * (sizeof(long) + sizeof(int) + sizeof(record));
    log_memory_usage(*used_memory);

    free_memory(offsets, keys, records);

    pthread_mutex_unlock(&lock);
    return 0;
}
```

### Assumptions:
- The system supports multithreading and POSIX threads.
- Memory allocation failures are handled gracefully by logging errors and freeing any allocated memory before returning an error code.
- A mutex is used to ensure thread-safe operations when multiple threads access shared resources like the log file.
- Maximum array size is defined as `MAX_ARRAY_SIZE` for flexibility in configuration.
- The random number generation uses the standard C library, which may not be suitable for cryptographic applications.']

["```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define OFFSET_MIN 0
#define OFFSET_MAX 100000
#define KEY_MIN 1
#define KEY_MAX 10000

typedef struct {
    long offset;
    int key;
    char status;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock;
} Database;

Database* create_database(size_t num_records) {
    if (num_records <= 0) return NULL;

    Database *db = malloc(sizeof(Database));
    if (!db) return NULL;

    db->count = num_records;
    db->records = calloc(num_records, sizeof(record));
    if (!db->records) {
        free(db);
        return NULL;
    }

    pthread_mutex_init(&db->lock, NULL);

    srand(time(NULL)); // Seed for randomness
    for (size_t i = 0; i < num_records; ++i) {
        db->records[i].offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
        db->records[i].key = KEY_MIN + rand() % (KEY_MAX - KEY_MIN + 1);
        db->records[i].status = 'A';
    }

    return db;
}

int update_offset(Database *db, size_t index, long new_offset) {
    if (!db || index >= db->count) return -1;

    pthread_mutex_lock(&db->lock);

    db->records[index].offset = new_offset;

    pthread_mutex_unlock(&db->lock);
    return 0;
}

int update_status(Database *db, size_t index, char new_status) {
    if (!db || index >= db->count) return -1;

    pthread_mutex_lock(&db->lock);

    db->records[index].status = new_status;

    pthread_mutex_unlock(&db->lock);
    return 0;
}

void free_database(Database *db) {
    if (db) {
        if (db->records) {
            free(db->records);
        }
        pthread_mutex_destroy(&db->lock);
        free(db);
    }
}
```"]

['Below is a modular cryptographic framework implemented in C using OpenSSL. It supports AES (128, 192, 256-bit), ChaCha20, XChaCha20 with various modes of operation like GCM, CTR, and CFB. The function dynamically selects the cipher based on user input and returns an `EVP_CIPHER` structure. Key derivation is done using PBKDF2, ensuring thread safety and efficient resource management.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <pthread.h>

// Define supported algorithms and modes
typedef enum {
    AES_128,
    AES_192,
    AES_256,
    CHACHA20,
    XCHACHA20
} Algorithm;

typedef enum {
    MODE_GCM,
    MODE_CTR,
    MODE_CFB
} Mode;

// Structure to hold context for rate-limiting
typedef struct {
    unsigned int attempt_count;
    time_t last_attempt_time;
    pthread_mutex_t lock;
} RateLimitContext;

RateLimitContext rate_limit_ctx = {0, 0, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
EVP_CIPHER *get_cipher(Algorithm algo, Mode mode);
int derive_key(const char *password, const unsigned char *salt, int iterations,
               int key_length, unsigned char *key);
void check_rate_limit(void);

// Main function to get cipher based on algorithm and mode
EVP_CIPHER *get_cipher(Algorithm algo, Mode mode) {
    EVP_CIPHER_CTX *ctx = NULL;
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    switch (algo) {
        case AES_128:
            switch (mode) {
                case MODE_GCM: EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL); break;
                case MODE_CTR: EVP_CIPHER_CTX_set_padding(ctx, 0); EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, NULL, NULL); break;
                case MODE_CFB: EVP_EncryptInit_ex(ctx, EVP_aes_128_cfb8(), NULL, NULL, NULL); break;
            }
            break;

        case AES_192:
            switch (mode) {
                case MODE_GCM: EVP_EncryptInit_ex(ctx, EVP_aes_192_gcm(), NULL, NULL, NULL); break;
                case MODE_CTR: EVP_CIPHER_CTX_set_padding(ctx, 0); EVP_EncryptInit_ex(ctx, EVP_aes_192_ctr(), NULL, NULL, NULL); break;
                case MODE_CFB: EVP_EncryptInit_ex(ctx, EVP_aes_192_cfb8(), NULL, NULL, NULL); break;
            }
            break;

        case AES_256:
            switch (mode) {
                case MODE_GCM: EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL); break;
                case MODE_CTR: EVP_CIPHER_CTX_set_padding(ctx, 0); EVP_EncryptInit_ex(ctx, EVP_aes_256_ctr(), NULL, NULL, NULL); break;
                case MODE_CFB: EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb8(), NULL, NULL, NULL); break;
            }
            break;

        case CHACHA20:
            switch (mode) {
                case MODE_GCM: EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL); break;
                case MODE_CTR: EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL); break;
                // CHACHA20 does not support CFB
            }
            break;

        case XCHACHA20:
            switch (mode) {
                case MODE_GCM: EVP_EncryptInit_ex(ctx, EVP_xchacha20_poly1305_256(), NULL, NULL, NULL); break;
                // XChaCha20 typically uses GCM mode and does not support CTR or CFB
            }
            break;

        default:
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
    }

    if (EVP_CIPHER_CTX_base_cipher(ctx) == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return EVP_CIPHER_CTX_cipher(ctx);
}

// Key derivation function using PBKDF2
int derive_key(const char *password, const unsigned char *salt, int iterations,
               int key_length, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 16, iterations,
                            EVP_sha256(), key_length, key);
}

// Rate-limiting function
void check_rate_limit(void) {
    pthread_mutex_lock(&rate_limit_ctx.lock);

    time_t now = time(NULL);
    if (now - rate_limit_ctx.last_attempt_time > 60) { // Reset every minute
        rate_limit_ctx.attempt_count = 0;
        rate_limit_ctx.last_attempt_time = now;
    }

    if (++rate_limit_ctx.attempt_count > 100) {
        fprintf(stderr, "Rate limit exceeded.\n");
        pthread_mutex_unlock(&rate_limit_ctx.lock);
        exit(EXIT_FAILURE); // Or handle appropriately
    }

    pthread_mutex_unlock(&rate_limit_ctx.lock);
}

int main() {
    // Example usage
    unsigned char key[32];
    derive_key("password", (const unsigned char*)"somesalt123456", 10000, sizeof(key), key);

    EVP_CIPHER *cipher = get_cipher(AES_256, MODE_GCM);
    if (!cipher) {
        fprintf(stderr, "Failed to initialize cipher.\n");
        return EXIT_FAILURE;
    }

    check_rate_limit(); // Example rate-limiting

    EVP_CIPHER_CTX_free(cipher); // Clean up
    return 0;
}
```

### Key Points:
- **Thread Safety:** The framework uses `pthread_mutex_t` for thread-safe operations, especially in the rate-limiting function.
- **Rate Limiting:** Implemented to prevent brute-force attacks by limiting decryption attempts per user within a minute.
- **Dynamic Cipher Selection:** Based on user input, selecting appropriate cipher and mode dynamically.
- **Key Derivation:** Uses PBKDF2 with SHA-256 for secure key derivation from passwords.
- **Memory Management:** Ensures proper initialization and cleanup of `EVP_CIPHER_CTX` to manage memory efficiently.

### Future Extensions:
- Add new algorithms by extending the `Algorithm` enum and updating the `get_cipher` function.
- Leverage hardware acceleration using OpenSSL's built-in support where available.
- Enhance documentation for pluggable architecture, detailing steps to add new algorithms.']

