void* safe_malloc(size_t size);
void log_memory_usage(double memory_used, const char* stage);
void free_resources(long *offsets, int *keys, double *data_points, Record *records);

// Thread-safe logger for memory usage
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Example configuration values
