    int min_key = 1, max_key = 1000;
    double min_data_point = 0.0, max_data_point = 10.0;
    int min_record_int = 0, max_record_int = 100;
    float min_record_float = -50.0f, max_record_float = 50.0f;
    double min_record_double = 1.0, max_record_double = 100.0;

    if (initialize_arrays(offset_count, key_count, data_point_count, record_count,
                          min_offset, max_offset, min_key, max_key,
                          min_data_point, max_data_point, 
                          min_record_int, min_record_float, min_record_double) != 0) {
        fprintf(stderr, "Initialization failed.\n");
    }

    return 0;
}

int initialize_arrays(size_t offset_count, size_t key_count, size_t data_point_count,
                      size_t record_count, long min_offset, long max_offset, int min_key,
                      int max_key, double min_data_point, double max_data_point,
                      int min_record_int, float min_record_float, double min_record_double) {

    pthread_mutex_lock(&log_mutex);

    // Validate configuration
    if (offset_count > MAX_ARRAY_SIZE || key_count > MAX_ARRAY_SIZE ||
        data_point_count > MAX_ARRAY_SIZE || record_count > MAX_ARRAY_SIZE) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    srand(time(NULL));

    long *offsets = safe_malloc(offset_count * sizeof(long));
    int *keys = safe_malloc(key_count * sizeof(int));
    double *data_points = safe_malloc(data_point_count * sizeof(double));
    Record *records = safe_malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !data_points || !records) {
        free_resources(offsets, keys, data_points, records);
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    // Initialize arrays
    for (size_t i = 0; i < offset_count; ++i)
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);

    for (size_t i = 0; i < key_count; ++i)
        keys[i] = min_key + rand() % (max_key - min_key + 1);

    for (size_t i = 0; i < data_point_count; ++i)
        data_points[i] = min_data_point + ((double)rand() / RAND_MAX) * (max_data_point - min_data_point);

    // Initialize records
    for (size_t i = 0; i < record_count; ++i) {
        records[i].intValue = min_record_int + rand() % (max_record_int - min_record_int + 1);
        records[i].floatValue = min_record_float + ((float)rand() / RAND_MAX) * 
                                (max_record_float - min_record_float);
        records[i].doubleValue = min_record_double + ((double)rand() / RAND_MAX) *
                                 (max_record_double - min_record_double);
    }

    // Log memory usage
    log_memory_usage(sizeof(long) * offset_count + sizeof(int) * key_count +
                     sizeof(double) * data_point_count + record_count * sizeof(Record), "Initialization");

    free_resources(offsets, keys, data_points, records);

    pthread_mutex_unlock(&log_mutex);
    return 0;
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void log_memory_usage(double memory_used, const char* stage) {
    printf("Stage: %s, Memory used: %.2f bytes\n", stage, memory_used);
}

void free_resources(long *offsets, int *keys, double *data_points, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (data_points) free(data_points);
    if (records) free(records);
}
```

This implementation demonstrates how to dynamically allocate memory for arrays and records while ensuring thread safety and proper logging of memory usage. It handles memory allocation failures, uses mutexes for synchronization in a multithreaded environment, and logs memory usage during initialization. The function is designed to be extendable and maintainable.']

['Below is an implementation in C for managing a linked list of nodes with thread-safe insertion based on priority levels and efficient substring search:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *str;
    int priority;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} PriorityQueue;

void initPriorityQueue(PriorityQueue *pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

Node* createNode(const char *str, int priority) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->str = strdup(str);
    if (!new_node->str) {
        free(new_node);
        return NULL;
    }

    new_node->priority = priority;
    new_node->next = NULL;
    return new_node;
}

void destroyNode(Node *node) {
    if (node) {
        free(node->str);
        free(node);
    }
}

int insertNode(PriorityQueue *pq, const char *str, int priority) {
    pthread_mutex_lock(&pq->lock);

    Node *new_node = createNode(str, priority);
    if (!new_node) {
        pthread_mutex_unlock(&pq->lock);
        return -1;
    }

    if (!pq->head || pq->head->priority > priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node *current = pq->head;
        while (current->next && current->next->priority <= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
    return 0;
}

void traverseAndMatch(PriorityQueue *pq, const char *substring, void (*callback)(Node*)) {
    pthread_mutex_lock(&pq->lock);

    Node *current = pq->head;
    while (current) {
        if (strstr(current->str, substring)) {
            callback(current);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pq->lock);
}

void freePriorityQueue(PriorityQueue *pq) {
    pthread_mutex_lock(&pq->lock);

    Node *current = pq->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        destroyNode(temp);
    }

    pq->head = NULL;
    pthread_mutex_unlock(&pq->lock);
    pthread_mutex_destroy(&pq->lock);
}

// Example callback function
void printNode(Node *node) {
    printf("String: %s, Priority: %d\n", node->str, node->priority);
}

int main() {
    PriorityQueue pq;
    initPriorityQueue(&pq);

    insertNode(&pq, "apple", 2);
    insertNode(&pq, "banana", 1);
    insertNode(&pq, "apricot", 3);

    traverseAndMatch(&pq, "app", printNode);

    freePriorityQueue(&pq);

    return 0;
}
```

### Key Points:
- **Thread Safety:** The `pthread_mutex_t` is used to ensure that insertions and traversals are thread-safe.
- **Memory Management:** Nodes are dynamically allocated, and their memory is freed properly to prevent leaks.
- **Insertion Logic:** Nodes are inserted in a sorted manner based on priority levels.
- **Substring Search:** Efficient traversal with `strstr()` for substring matching.
- **Cleanup:** Proper destruction of nodes and mutexes to avoid resource leakage. 

This implementation assumes the system has support for POSIX threads (`pthread`). Adjustments may be needed based on specific constraints or requirements of the target environment.']

['Below is a conceptual implementation using Reactor for handling concurrent GET requests, integrating with a Service Mesh, implementing caching and monitoring strategies, and managing retries. This example provides an outline rather than a full application due to its complexity.

```java
import reactor.core.publisher.Flux;
import reactor.core.scheduler.Schedulers;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.function.Function;
import org.springframework.web.reactive.function.client.WebClient;
import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;

public class ReactiveServiceManager {
    private final WebClient webClient;
    private final Cache<String, String> cache;
    private final ThreadPoolExecutor executor;
    private List<String> trustedServices; // Assume this is dynamically updated

    public ReactiveServiceManager() {
        this.webClient = WebClient.builder()
            .baseUrl("http://mock-service-url")
            .build();

        this.cache = Caffeine.newBuilder()
            .maximumSize(10000)
            .expireAfterWrite(java.time.Duration.ofMinutes(5))
            .recordStats()
            .build();

        this.executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(5000);

        // Mocked service configuration
        trustedServices = List.of("http://service1", "http://service2"); 
    }

    public Flux<String> handleRequests(Flux<String> requests, Function<String, String> requestHandler) {
        return requests.publishOn(Schedulers.fromExecutor(executor))
            .flatMap(request -> handleRequestWithRetries(request, 3))
            .doOnNext(response -> logResponse(response))
            .map(this::processResponse);
    }

    private Flux<String> handleRequestWithRetries(String request, int retries) {
        return webClient.get()
            .uri(uriBuilder -> uriBuilder.path("/data").build())
            .retrieve()
            .bodyToMono(String.class)
            .retryWhen(Retry.backoff(3, java.time.Duration.ofSeconds(1))
                .filter(error -> !error.getMessage().equals("Transient error")))
            .onErrorResume(error -> {
                // Log and handle error
                return Flux.just("Failed: " + error.getMessage());
            });
    }

    private String processResponse(String response) {
        if (cache.getIfPresent(response).isEmpty()) {
            cache.put(response, response);
        }
        return response;
    }

    private void logResponse(String response) {
        System.out.println("Request processed with response: " + response);
        // Add detailed logging logic here
    }

    public static void main(String[] args) {
        ReactiveServiceManager manager = new ReactiveServiceManager();

        Flux<String> incomingRequests = Flux.range(1, 5000)
            .map(i -> "request" + i);

        manager.handleRequests(incomingRequests, request -> {
            // Simulate processing logic
            return "Processed: " + request;
        }).subscribe(response -> System.out.println("Response: " + response));
    }
}
```

### Key Components:

- **Reactive WebClient**: Used for non-blocking HTTP requests.
- **Caffeine Cache**: Implements LRU caching policy to optimize memory usage and performance.
- **Dynamic Concurrency Management**: Uses a thread pool executor to manage concurrency based on system resource availability.
- **Retry Logic**: Configured with backoff strategy for handling transient errors.
- **Service Mesh Integration**: Assumed via configuration, typically handled by infrastructure (e.g., Istio) in production environments.
- **Centralized Monitoring & Logging**: Basic logging setup; integrate with tools like Prometheus or ELK stack for comprehensive monitoring.

### Additional Considerations:

1. **Backpressure Strategy**: Monitor CPU and memory usage to adjust thread pool size dynamically using a custom scheduler.
2. **Configuration Management**: Use external configuration services (e.g., Spring Cloud Config) to update trusted service URLs.
3. **Error Handling & Fault Tolerance**: Implement additional fallback mechanisms for different error conditions, ensuring high availability.

### Testing:

- Create comprehensive unit tests with Mockito for mocked components.
- Integration tests should simulate load and network failures to verify resilience and performance under stress.

This example provides a foundation upon which you can build more sophisticated logic and integrations tailored to specific infrastructure needs.']

