          const endTime = Date.now();

          if (logLevel !== 'none') {
            console.log(`Read file: ${filePath}, Size: ${content.length} bytes, Time taken: ${endTime - startTime} ms`);
          }

          return content;
        } catch (error) {
          if (attempt < retryAttempts) {
            const delay = Math.pow(2, attempt); // Exponential backoff
            console.warn(`Read failed for ${filePath}, retrying in ${delay}s. Attempt: ${attempt + 1}`);
            await new Promise(res => setTimeout(res, delay * 1000));
            return readFileWithRetry(filePath, attempt + 1);
          } else {
            throw error;
          }
        }
      };

      const fileContent = await limit(() => readFileWithRetry(filePath, 0));

      cumulativeSize += fileContent.length;

      if (cumulativeSize > sizeThreshold) {
        throw new Error('Cumulative content size exceeds threshold.');
      }

      fileContents += fileContent.toString();
    }

    return fileContents;
  } catch (error) {
    console.error(`Error reading files: ${error.message}`);
    throw error; // Ensure the promise is rejected on failure
  }
}

// Usage example:
readAndConcatenateFiles('/path/to/dir', ['.txt', '.md'], {
  maxConcurrency: 3,
  sizeThreshold: 5 * 1024 * 1024, // 5MB
  retryAttempts: 2,
  logLevel: 'info',
  rootPaths: ['/allowed/root/path']
})
.then(content => console.log('Concatenated Content:', content))
.catch(error => console.error('Failed to read files:', error));
```

