// Define structures
typedef struct {
    int key;
    long offset;
} record;

typedef struct node {
    double value;
    char identifier;
    struct node* next;
} node_t;

// Configuration and logging variables
int upper_bound;
FILE *log_file = NULL;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void init_memory(int num_records, int memory_limit);
void free_resources(record* records, size_t num_records, node_t* head);
int read_upper_bound_from_config(const char* config_path);

void log_message(const char* message) {
    pthread_mutex_lock(&lock);
    if (log_file == NULL) {
        log_file = fopen("memory_usage.log", "w");
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&lock);
}

int read_upper_bound_from_config(const char* config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%d", &upper_bound);
    fclose(file);
    return upper_bound;
}

void init_memory(int num_records, int memory_limit) {
    size_t records_size = sizeof(record) * num_records;
    node_t* head = NULL;
    node_t* current_node = NULL;

    // Check if the total required memory exceeds the limit
    if (records_size > memory_limit) {
        log_message("Memory allocation error: Records exceed memory limit");
        return;
    }

    // Allocate array of records
    record* records = malloc(records_size);
    if (!records) {
        log_message("Failed to allocate memory for records");
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    // Initialize records with random keys and offsets
    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % upper_bound;
        records[i].offset = (long)(rand() * (1.0 / RAND_MAX) * memory_limit);
    }

    log_message("Records initialized successfully");

    // Allocate and initialize linked list with sequential index values
    for (int i = 0; i < num_records; ++i) {
        node_t* new_node = malloc(sizeof(node_t));
        if (!new_node) {
            log_message("Failed to allocate memory for a node");
            break;
        }

        new_node->value = i * 1.0;
        new_node->identifier = 'A' + (i % 26);
        new_node->next = NULL;

        pthread_mutex_lock(&lock);

        if (!head) {
            head = new_node;
        } else {
            current_node->next = new_node;
        }

        current_node = new_node;

        pthread_mutex_unlock(&lock);
    }

    log_message("Linked list initialized successfully");

    // Example of using allocated structures
    // ...

    free_resources(records, num_records, head);  // Clean up resources at the end
}

void free_resources(record* records, size_t num_records, node_t* head) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }

    node_t *current = head;
    while (current) {
        node_t *temp = current;
        current = current->next;
        free(temp);
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <num_records> <memory_limit>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_records = atoi(argv[1]);
    int memory_limit = atoi(argv[2]);

    read_upper_bound_from_config("config.txt");

    init_memory(num_records, memory_limit);

    return 0;
}
```']

['Below is an example implementation for the described modular cryptographic framework in C using OpenSSL:

```c
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/chacha20.h>
#include <openssl/pbkdf2.h>
#include <pthread.h>
#include <stdatomic.h>

// Structure to hold configuration and state information.
typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} CryptoContext;

// Function prototypes
EVP_CIPHER *select_cipher(const char *algorithm, int key_size);
void derive_key_and_iv(const unsigned char *password, const unsigned char *salt,
                       int iterations, int key_len, int iv_len,
                       unsigned char *key, unsigned char *iv);
CryptoContext *init_crypto_context(const char *algorithm, int key_size,
                                   int mode, const unsigned char *password,
                                   const unsigned char *salt, int iterations);

// Main function to create a cryptographic context
CryptoContext *init_crypto_context(const char *algorithm, int key_size,
                                   int mode, const unsigned char *password,
                                   const unsigned char *salt, int iterations) {
    CryptoContext *crypto_ctx = malloc(sizeof(CryptoContext));
    if (!crypto_ctx) return NULL;

    pthread_mutex_init(&crypto_ctx->lock, NULL);
    crypto_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!crypto_ctx->ctx) {
        free(crypto_ctx);
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    derive_key_and_iv(password, salt, iterations, key_size / 8, EVP_MAX_IV_LENGTH,
                      key, iv);

    EVP_CIPHER *cipher = select_cipher(algorithm, key_size);
    if (!cipher) {
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx);
        return NULL;
    }

    int init_result = EVP_EncryptInit_ex(crypto_ctx->ctx, cipher, NULL, key, iv);
    if (init_result != 1) {
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx);
        return NULL;
    }

    // Set mode of operation
    switch (mode) {
        case EVP_CIPH_GCM_MODE:
            EVP_CIPHER_CTX_set_mode(crypto_ctx->ctx, EVP_CIPH_GCM_MODE);
            break;
        case EVP_CIPH_CTR_MODE:
            EVP_CIPHER_CTX_set_padding(crypto_ctx->ctx, 0); // No padding
            EVP_CIPHER_CTX_ctrl(crypto_ctx->ctx, EVP_CTRL_CTRINIT, key_size / 8,
                                iv);
            break;
        case EVP_CIPH_CBC_MODE:
            EVP_CIPHER_CTX_set_padding(crypto_ctx->ctx, 1); // PKCS#7 padding
            break;
    }

    return crypto_ctx;
}

// Function to select the appropriate cipher based on user input
EVP_CIPHER *select_cipher(const char *algorithm, int key_size) {
    if (strcmp(algorithm, "AES") == 0) {
        switch (key_size) {
            case 128: return EVP_aes_128_cbc();
            case 192: return EVP_aes_192_cbc();
            case 256: return EVP_aes_256_cbc();
        }
    } else if (strcmp(algorithm, "ChaCha20") == 0) {
        return EVP_chacha20();
    } else if (strcmp(algorithm, "XChaCha20") == 0) {
        // XChaCha20 implementation is not directly available in OpenSSL.
        // Requires custom implementation or alternative library.
        return NULL;
    }
    return NULL;
}

// Function to derive key and IV using PBKDF2
void derive_key_and_iv(const unsigned char *password, const unsigned char *salt,
                       int iterations, int key_len, int iv_len,
                       unsigned char *key, unsigned char *iv) {
    PKCS5_PBKDF2_HMAC(password, strlen((char *)password), salt,
                      strlen((char *)salt), iterations, EVP_sha256(),
                      key_len + iv_len, key);
}

// Example usage of the framework
int main() {
    const char *algorithm = "AES";
    int key_size = 128;
    int mode = EVP_CIPH_CBC_MODE;
    unsigned char password[] = "mysecretpassword";
    unsigned char salt[] = "randomsalt";

    CryptoContext *crypto_ctx = init_crypto_context(algorithm, key_size,
                                                    mode, password, salt, 10000);
    if (!crypto_ctx) {
        fprintf(stderr, "Failed to initialize cryptographic context\n");
        return 1;
    }

    // Use the crypto_ctx for encryption/decryption operations...

    EVP_CIPHER_CTX_free(crypto_ctx->ctx);
    free(crypto_ctx);

    return 0;
}
```

