// Doubly linked list implementation
struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
}

impl<T> LinkedList<T> {
    fn new() -> Self {
        LinkedList { head: None, tail: None, len: 0 }
    }

    fn push_front(&mut self, value: T) {
        let new_node = Box::new(Node::new(value));
        match &self.head {
            Some(ref mut head_node) => {
                head_node.prev = Some(new_node);
                new_node.next = Some(*head_node.clone());
            }
            None => {
                self.tail = Some(new_node.clone());
            }
        }
        self.head = Some(new_node);
        self.len += 1;
    }

    fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|node| {
            self.head = node.next.take();
            if let Some(ref mut next_node) = self.head {
                next_node.prev = None;
            } else {
                self.tail = None;
            }
            self.len -= 1;
            node.event
        })
    }

