    }

    for (size_t i = *current_size; i < new_size; ++i) {
        (*new_keys)[i] = rand() % 100 + 1;
        if (i == 0)
            (*new_offsets)[i] = (*offsets)[*current_size - 1];
        else
            (*new_offsets)[i] = (*new_offsets)[i - 1] + (*new_keys)[i];
    }

    *current_size = new_size;
    *offsets = new_offsets;
    *keys = new_keys;

    log_change("Arrays resized.");
}

// Randomize record fields to avoid predictable patterns
void randomize_record(record_t* rec) {
    rec->s = rand() % 256;   // Short range: 0-255
    rec->i = rand();         // Int (full range)
    rec->f = ((float)rand() / RAND_MAX) * 100.0f;  // Float in [0, 100]
    rec->timestamp = time(NULL);  // New timestamp
}

