    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for list node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

