dllist_t* create_list() {
    dllist_t* list = (dllist_t*)malloc(sizeof(dllist_t));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for the doubly linked list.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Insert a new record into the doubly linked list
void insert_to_dll(dllist_t* list, record_t data, const char* user_id) {
    pthread_mutex_lock(&list->lock);

    node_t* new_node = create_node(data);

    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;

    pthread_mutex_unlock(&list->lock);
    log_change("Record inserted.");
}

// Example cache retrieval
record_t* cache_get(dllist_t* list, uint64_t timestamp) {
    node_t* current = list->head;

    while (current != NULL) {
        if (current->data.timestamp == timestamp)
            return &current->data;
        current = current->next;
    }

    return NULL;  // Not found in cache
}

// Check if a record is in the cache
int is_in_cache(dllist_t* list, uint64_t timestamp) {
    node_t* current = list->head;

    while (current != NULL) {
        if (current->data.timestamp == timestamp)
            return 1; // Found in cache
        current = current->next;
    }

    return 0;  // Not found in cache
}
