```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_METADATA_LENGTH 256
#define METADATA_CHARSET "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

typedef struct {
    short field1;
    int field2;
    float field3;
    int timestamp;
    char *metadata;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    long* offsets;
    size_t offset_count;
    size_t offset_capacity;

    int* keys;
    size_t key_count;
    size_t key_capacity;

    Record records[10];  // Initial fixed size for demonstration
    size_t record_count;
    pthread_mutex_t lock;

    Node* head;          // Linked list head
    Node* tail;          // Linked list tail
} PipelineState;

void initialize_pipeline(PipelineState *state, int initial_capacity) {
    state->offsets = malloc(initial_capacity * sizeof(long));
    state->keys = malloc(initial_capacity * sizeof(int));

    state->offset_count = 0;
    state->key_count = 0;

    state->offset_capacity = initial_capacity;
    state->key_capacity = initial_capacity;

    pthread_mutex_init(&state->lock, NULL);
    state->head = NULL;
    state->tail = NULL;
    state->record_count = 0;
}

void resize_array(long **array, size_t *capacity, size_t new_capacity) {
    long *new_array = realloc(*array, new_capacity * sizeof(long));
    if (new_array == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

void resize_key_array(int **array, size_t *capacity, size_t new_capacity) {
    int *new_array = realloc(*array, new_capacity * sizeof(int));
    if (new_array == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

void add_key(PipelineState *state, int key_value) {
    pthread_mutex_lock(&state->lock);

    if (state->key_count >= state->key_capacity) {
        resize_key_array(&state->keys, &state->key_capacity, state->key_capacity * 2);
    }

    // Add key and calculate offset
    state->keys[state->key_count++] = key_value;
    long cumulative_sum = 0;
    for (size_t i = 0; i < state->key_count; ++i) {
        cumulative_sum += state->keys[i];
    }

    if (state->offset_count >= state->offset_capacity) {
        resize_array(&state->offsets, &state->offset_capacity, state->offset_capacity * 2);
    }

    state->offsets[state->offset_count++] = cumulative_sum;

    pthread_mutex_unlock(&state->lock);
}

int is_valid_metadata(const char* metadata) {
    while (*metadata != '\0') {
        if (!strchr(METADATA_CHARSET, *metadata)) {
            return 0;
        }
        metadata++;
    }
    return 1;
}

void add_record(PipelineState *state, Record record) {
    pthread_mutex_lock(&state->lock);

    if (state->record_count >= 10) { // Resize logic needed for demonstration
        printf("Record capacity reached. Need to resize.\n");
        pthread_mutex_unlock(&state->lock);
        return;
    }

    if (!is_valid_metadata(record.metadata)) {
        printf("Invalid metadata string\n");
        pthread_mutex_unlock(&state->lock);
        return;
    }

    state->records[state->record_count++] = record;

    Node* new_node = malloc(sizeof(Node));
    new_node->data = record;
    new_node->next = NULL;

    if (state->tail) {
        state->tail->next = new_node;
    } else {
        state->head = new_node;
    }

    state->tail = new_node;

    pthread_mutex_unlock(&state->lock);
}

void cleanup_pipeline(PipelineState *state) {
    Node* current = state->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(state->offsets);
    free(state->keys);
    pthread_mutex_destroy(&state->lock);
}

int main() {
    PipelineState pipeline;
    initialize_pipeline(&pipeline, 10);

    // Example usage:
    add_key(&pipeline, 5);
    add_key(&pipeline, 3);

    char metadata[MAX_METADATA_LENGTH];
    snprintf(metadata, MAX_METADATA_LENGTH, "ValidMetadata123");

    Record new_record = { .field1 = 1, .field2 = 100, .field3 = 12.34f, .timestamp = 1618033988, .metadata = strdup(metadata) };
    add_record(&pipeline, new_record);

    cleanup_pipeline(&pipeline);

    return 0;
}
```

