    coll->metadata_list = malloc(initial_size * sizeof(char*));
    coll->events = malloc(initial_size * sizeof(event_t*));
    coll->count = 0;

    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

void free_collections(collections_t *coll) {
