    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->metadata_list[i]);
        free(coll->records[i].record.metadata);
        free(&coll->records[i]);
    }

    free(coll->offsets);
    free(coll->keys);
    free(coll->timestamps);
    free(coll->events);
    free(coll->metadata_list);
    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

void initialize_collections(collections_t *coll, size_t initial_size, int range_start, int range_end) {
    if (!coll) return;

    long cumulative_offset = 0;

    for (size_t i = 0; i < initial_size; ++i) {
        coll->keys[i] = generate_unique_key(i, range_start, range_end);
        cumulative_offset += coll->keys[i];
        coll->offsets[i] = cumulative_offset;

        coll->timestamps[i] = rand() % 100000; // Example timestamp

