    event_t **new_events = realloc(coll->events, new_size * sizeof(event_t*));

    if (!new_offsets || !new_keys || !new_records || !new_timestamps || !new_metadata_list || !new_events) {
        // Handle allocation failure (cleanup and exit)
        fprintf(stderr, "Memory allocation failed during resizing\n");
        free_collections(coll);
        return;
    }

    coll->offsets = new_offsets;
    coll->keys = new_keys;
    coll->records = new_records;
    coll->timestamps = new_timestamps;
    coll->metadata_list = new_metadata_list;
    coll->events = new_events;

    for (size_t i = coll->count; i < new_size; ++i) {
        char metadata_buf[MAX_METADATA_LEN];
        snprintf(metadata_buf, MAX_METADATA_LEN, "metadata_%zu", i);

        coll->metadata_list[i] = strdup(metadata_buf);
        coll->events[i] = malloc(sizeof(event_t)); // Initialize event as needed

        coll->records[i].record.s_value = (short)rand();
        coll->records[i].record.i_value = rand() % 100;
        coll->records[i].record.f_value = (float)(rand() / RAND_MAX);
        coll->records[i].record.timestamp = rand() % 100000; // Example timestamp
        coll->records[i].record.metadata = coll->metadata_list[i];
        coll->records[i].record.event = coll->events[i];

        coll->records[i].prev = (i > 0) ? &coll->records[i - 1] : NULL;
        coll->records[i].next = (i < new_size - 1) ? &coll->records[i + 1] : NULL;

        if (i > 0) {
            coll->records[i].prev->next = &coll->records[i];
        }

        coll->count++;
    }
}

int main() {
