['Below is a C implementation of a flexible memory management system using linked lists and hash tables for managing key-value pairs where each key is a `long` integer and each value is a `double`. The code includes a thread-safe insertion function.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TABLE_SIZE 10007 // A prime number for better distribution in hash table

typedef struct KeyValue {
    long key;
    double value;
    struct KeyValue *next;
} KeyValue;

typedef struct HashTable {
    KeyValue **buckets;
    pthread_mutex_t *locks;
} HashTable;

// Hash function to determine the bucket index
unsigned int hashFunction(long key, unsigned int size) {
    return (unsigned int)(key % size);
}

// Initialize the hash table with locks for each bucket
HashTable* createHashTable() {
    HashTable *table = malloc(sizeof(HashTable));
    table->buckets = calloc(TABLE_SIZE, sizeof(KeyValue *));
    table->locks = malloc(TABLE_SIZE * sizeof(pthread_mutex_t));

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

// Insert a key-value pair into the hash table
void insertKeyValue(HashTable *table, long key, double value) {
    unsigned int index = hashFunction(key, TABLE_SIZE);

    // Lock the bucket to prevent race conditions
    pthread_mutex_lock(&table->locks[index]);

    KeyValue *newNode = malloc(sizeof(KeyValue));
    newNode->key = key;
    newNode->value = value;

    // Insert at head of linked list for O(1) insertion
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->locks[index]);
}

// Retrieve a value by its key from the hash table
double* getValueByKey(HashTable *table, long key) {
    unsigned int index = hashFunction(key, TABLE_SIZE);

    // Lock the bucket to safely read data
    pthread_mutex_lock(&table->locks[index]);

    KeyValue *node = table->buckets[index];

    while (node != NULL) {
        if (node->key == key) {
            double *value = malloc(sizeof(double));
            *value = node->value;
            pthread_mutex_unlock(&table->locks[index]);
            return value; // Caller is responsible for freeing this memory
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL; // Key not found
}

// Free the hash table and its contents
void freeHashTable(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        KeyValue *node = table->buckets[i];

        while (node != NULL) {
            KeyValue *temp = node;
            node = node->next;
            free(temp);
        }

        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table->buckets);
    free(table->locks);
    free(table);
}

// Example usage
int main() {
    HashTable *table = createHashTable();

    insertKeyValue(table, 1L, 2.5);
    insertKeyValue(table, 2L, 3.7);

    double *value = getValueByKey(table, 1L);
    if (value) {
        printf("Value for key 1: %f\n", *value);
        free(value); // Free memory allocated by getValueByKey
    } else {
        printf("Key not found.\n");
    }

    freeHashTable(table);
    return 0;
}
```

This code implements a hash table with separate chaining using linked lists to handle collisions. Each bucket in the hash table has its own mutex lock, allowing for concurrent insertions and lookups while maintaining thread safety without locking the entire table. Note that this implementation assumes keys are unique; attempts to insert duplicate keys will simply overwrite existing values.']

