        fprintf(stderr, "Warning: Memory usage threshold exceeded!\n");
    }
}

void initializeDataStructures(NodeData **nodes, Event *events, Summary *summaries) {
    size_t memoryUsage = 0;

    // Initialize nodes
    nodes = malloc(NODE_COUNT * sizeof(NodeData *));
    if (!nodes) {
        perror("Failed to allocate memory for node pointers");
        exit(EXIT_FAILURE);
    }
    memoryUsage += NODE_COUNT * sizeof(NodeData *);

    for (int i = 0; i < NODE_COUNT; ++i) {
        nodes[i] = malloc(sizeof(NodeData));
        if (!nodes[i]) {
            perror("Failed to allocate memory for node data");
            exit(EXIT_FAILURE);
        }
        nodes[i]->timestamp = 0;
        nodes[i]->value = 0.0;
        memoryUsage += sizeof(NodeData);
    }

    // Initialize events
    events = malloc(EVENT_COUNT * sizeof(Event));
    if (!events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    memoryUsage += EVENT_COUNT * sizeof(Event);

    for (int i = 0; i < EVENT_COUNT; ++i) {
        events[i].eventType = 0;
        events[i].priorityLevel = 0.0f;
    }

    // Initialize summaries
    summaries = malloc(SUMMARY_COUNT * sizeof(Summary));
    if (!summaries) {
        perror("Failed to allocate memory for summaries");
        exit(EXIT_FAILURE);
    }
    memoryUsage += SUMMARY_COUNT * sizeof(Summary);

    for (int i = 0; i < SUMMARY_COUNT; ++i) {
        summaries[i].message = malloc(256); // Example fixed size message
        if (!summaries[i].message) {
            perror("Failed to allocate memory for summary message");
            exit(EXIT_FAILURE);
        }
        strcpy(summaries[i].message, "Default message");
