#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LEVELS 5
#define LOG_BUFFER_SIZE 1024 * 1024 // 1 MB buffer size

typedef struct {
    int year;
    int month;
    int day;
    int hour;
    int minute;
    int second;
} Timestamp;

typedef struct LogEntry {
    int log_level;
    char message[256];
    Timestamp timestamp;
    unsigned int reference_count;
    struct LogEntry* next;
} LogEntry;

typedef struct {
    LogEntry* buffer[MAX_LOG_LEVELS];
    pthread_mutex_t mutexes[MAX_LOG_LEVELS];
    size_t used_space[MAX_LOG_LEVELS];
    size_t max_space;
} SharedLogBuffer;

typedef struct {
    SharedLogBuffer* shared_buffer;
    int logger_id;
} LoggerContext;

void init_shared_log_buffer(SharedLogBuffer* buffer, size_t max_space) {
    buffer->max_space = max_space;
    for (int i = 0; i < MAX_LOG_LEVELS; i++) {
        buffer->buffer[i] = NULL;
        pthread_mutex_init(&buffer->mutexes[i], NULL);
        buffer->used_space[i] = 0;
    }
}

void cleanup_shared_log_buffer(SharedLogBuffer* buffer) {
    for (int i = 0; i < MAX_LOG_LEVELS; i++) {
        LogEntry* entry = buffer->buffer[i];
        while (entry != NULL) {
            LogEntry* next = entry->next;
            free(entry);
            entry = next;
        }
        pthread_mutex_destroy(&buffer->mutexes[i]);
    }
}

int log_entry_exists(SharedLogBuffer* buffer, int logger_id, int log_level, Timestamp timestamp) {
    pthread_mutex_lock(&buffer->mutexes[log_level]);

    LogEntry* entry = buffer->buffer[log_level];
    while (entry != NULL) {
        if (entry->timestamp.year == timestamp.year &&
            entry->timestamp.month == timestamp.month &&
            entry->timestamp.day == timestamp.day &&
            entry->timestamp.hour == timestamp.hour &&
            entry->timestamp.minute == timestamp.minute &&
            entry->timestamp.second == timestamp.second) {
            pthread_mutex_unlock(&buffer->mutexes[log_level]);
            return 1;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&buffer->mutexes[log_level]);
    return 0;
}

int add_log_entry(SharedLogBuffer* buffer, int logger_id, int log_level, const char* message, Timestamp timestamp) {
    if (buffer->used_space[log_level] + sizeof(LogEntry) > buffer->max_space) {
        fprintf(stderr, "Error: Buffer limit exceeded for log level %d\n", log_level);
        return -1;
    }

    if (log_entry_exists(buffer, logger_id, log_level, timestamp)) {
        fprintf(stderr, "Error: Log entry already exists for given log level and timestamp\n");
        return -1;
    }

    pthread_mutex_lock(&buffer->mutexes[log_level]);

    LogEntry* new_entry = malloc(sizeof(LogEntry));
    if (!new_entry) {
        perror("Failed to allocate memory for log entry");
        pthread_mutex_unlock(&buffer->mutexes[log_level]);
        return -1;
    }

    new_entry->log_level = log_level;
    strncpy(new_entry->message, message, sizeof(new_entry->message) - 1);
    new_entry->timestamp = timestamp;
    new_entry->reference_count = 1;
    new_entry->next = buffer->buffer[log_level];

    buffer->used_space[log_level] += sizeof(LogEntry);
    buffer->buffer[log_level] = new_entry;

    pthread_mutex_unlock(&buffer->mutexes[log_level]);
    return 0;
}

void log_message(LoggerContext* context, int log_level, const char* message) {
    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);

    Timestamp timestamp = {
        .year = local_time->tm_year + 1900,
        .month = local_time->tm_mon + 1,
        .day = local_time->tm_mday,
        .hour = local_time->tm_hour,
        .minute = local_time->tm_min,
        .second = local_time->tm_sec
    };

    if (add_log_entry(context->shared_buffer, context->logger_id, log_level, message, timestamp) != 0) {
        fprintf(stderr, "Failed to log message\n");
    }
}

int main() {
    SharedLogBuffer shared_buffer;
    init_shared_log_buffer(&shared_buffer, LOG_BUFFER_SIZE);

    LoggerContext logger1 = { .shared_buffer = &shared_buffer, .logger_id = 1 };
    log_message(&logger1, 1, "This is an info message");

    // Simulate more logging operations...

    cleanup_shared_log_buffer(&shared_buffer);
    return 0;
}
