#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>

#define LOG_FILE "resource_manager.log"
#define MAX_PATH_LENGTH 4096
#define CACHE_SIZE 1024

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG UE_INFO;
    CRC_INDICATION_REL8_TAG CRC_DATA;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    long key;
    double value;
    struct Node* next;
} Node;

typedef struct HashTable {
    size_t size;
    Node** buckets;
    pthread_mutex_t lock;
} HashTable;

static FILE* log_file = NULL;

void init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void log_message(const char* message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

HashTable* create_hash_table(size_t size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = size;
    table->buckets = calloc(table->size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash_function(long key, size_t size) {
    return (unsigned long)key % size;
}

int insert_hash_table(HashTable* table, long key, double value) {
    unsigned long index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);

    Node* node = malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }
    node->key = key;
    node->value = value;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

double* retrieve_hash_table(HashTable* table, long key) {
    unsigned long index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);

    Node* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            double* value = malloc(sizeof(double));
            if (!value) {
                pthread_mutex_unlock(&table->lock);
                return NULL;
            }
            *value = node->value;
            pthread_mutex_unlock(&table->lock);
            return value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

typedef struct ResourceBundle {
    char** file_paths;
    size_t count;
    size_t capacity;
} ResourceBundle;

ResourceBundle* create_resource_bundle() {
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    bundle->file_paths = calloc(CACHE_SIZE, sizeof(char*));
    if (!bundle->file_paths) {
        free(bundle);
        return NULL;
    }

    bundle->count = 0;
    bundle->capacity = CACHE_SIZE;
    return bundle;
}

int add_file_to_bundle(ResourceBundle* bundle, const char* path) {
    if (bundle->count >= bundle->capacity) {
        size_t new_capacity = bundle->capacity * 2;
        char** new_paths = realloc(bundle->file_paths, new_capacity * sizeof(char*));
        if (!new_paths) return -1;

        bundle->file_paths = new_paths;
        bundle->capacity = new_capacity;
    }

    size_t len = strlen(path) + 1;
    bundle->file_paths[bundle->count] = malloc(len);
    if (!bundle->file_paths[bundle->count]) return -1;

    strcpy(bundle->file_paths[bundle->count], path);
    bundle->count++;
    return 0;
}

void free_resource_bundle(ResourceBundle* bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->file_paths[i]);
    }
    free(bundle->file_paths);
    free(bundle);
}

int load_files_from_directory(const char* directory, const char* extension, ResourceBundle* bundle) {
    DIR* dir = opendir(directory);
    if (!dir) {
        log_message("Failed to open directory");
        return -1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, extension)) {
            char path[MAX_PATH_LENGTH];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

            if (add_file_to_bundle(bundle, path) == -1) {
                log_message("Failed to add file to bundle");
                closedir(dir);
                return -1;
            }
        }
    }

    closedir(dir);
    return 0;
}

void populate_nfa_api_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        list[i].UE_INFO.RNTI = rand() % 100000;
        list[i].CRC_DATA.CRCFLAG = rand() % 2;
    }
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <extension>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_logging();
    log_message("Initializing resource manager");

    HashTable* table = create_hash_table(1024);
    if (!table) {
        log_message("Failed to create hash table");
        return EXIT_FAILURE;
    }

    ResourceBundle* bundle = create_resource_bundle();
    if (!bundle) {
        log_message("Failed to create resource bundle");
        free_hash_table(table);
        return EXIT_FAILURE;
    }

    if (load_files_from_directory(argv[1], argv[2], bundle) == -1) {
        log_message("Failed to load files from directory");
        free_resource_bundle(bundle);
        free_hash_table(table);
        return EXIT_FAILURE;
    }

    log_message("Files loaded successfully");

    NFAPI_CRC_INDICATION_PDU_T* nfa_api_list = malloc(bundle->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_api_list) {
        log_message("Failed to allocate memory for NFAPI list");
        free_resource_bundle(bundle);
        free_hash_table(table);
        return EXIT_FAILURE;
    }

    populate_nfa_api_list(nfa_api_list, bundle->count);

    // Example of inserting into hash table
    for (size_t i = 0; i < bundle->count; ++i) {
        if (insert_hash_table(table, nfa_api_list[i].UE_INFO.RNTI, (double)nfa_api_list[i].CRC_DATA.CRCFLAG) == -1) {
            log_message("Failed to insert into hash table");
            free(nfa_api_list);
            free_resource_bundle(bundle);
            free_hash_table(table);
            return EXIT_FAILURE;
        }
    }

    log_message("Resource manager initialized successfully");

    // Clean up
    free(nfa_api_list);
    free_resource_bundle(bundle);
    free_hash_table(table);

    fclose(log_file);
    return EXIT_SUCCESS;
}
```

