// Define the Event structure
typedef struct {
    short field1;
    int field2;
    float field3;
    long timestamp;
    char *metadata;
} Event;

// Hash map entry for event lookup
typedef struct {
    int eventId;
    Event event;
    UT_hash_handle hh; // makes this structure hashable
} EventHashEntry;

// Memory pool management
typedef struct {
    void **pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->pool = malloc(pool_size * sizeof(void *));
    for (size_t i = 0; i < pool_size; ++i) {
        mp->pool[i] = malloc(block_size);
    }
    pthread_mutex_init(&mp->mutex, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->mutex);
    for (size_t i = 0; i < mp->pool_size; ++i) {
        if (mp->pool[i] != NULL) {
            void *block = mp->pool[i];
            mp->pool[i] = NULL;
            pthread_mutex_unlock(&mp->mutex);
            return block;
        }
    }
    pthread_mutex_unlock(&mp->mutex);
    return malloc(mp->block_size); // Fallback to standard allocation
}

void memory_pool_free(MemoryPool *mp, void *ptr) {
    if (!ptr) return;
    size_t idx = ((char*)ptr - (char*)mp->pool) / mp->block_size;
    if (idx < mp->pool_size) {
        pthread_mutex_lock(&mp->mutex);
        mp->pool[idx] = ptr;
        pthread_mutex_unlock(&mp->mutex);
    } else {
        free(ptr); // Fallback to standard deallocation
    }
}

