// Define structures
typedef struct record {
    short field1;
    int field2;
    float field3;
    int timestamp;
} Record;

typedef struct Node {
    Record data;
    struct Node* prev;
    struct Node* next;
} Node;

// Thread-safe doubly linked list structure
typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* init_list() {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(DoublyLinkedList* list, Record data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Memory pool management
typedef struct MemoryPool {
    size_t block_size;
    unsigned char* pool;
    size_t pool_size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_blocks) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = block_size * initial_blocks;
    mp->pool = calloc(mp->pool_size, 1);
    return mp;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->pool_size < pool->block_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    void* block = pool->pool + (pool->pool_size - pool->block_size);
    pool->pool_size -= pool->block_size;
    return block;
}

// Initialize arrays and records
void initialize_data(long* offsets, int* keys, Record* records, int record_count, MemoryPool* key_pool, MemoryPool* record_pool) {
    srand(time(NULL));
    long offset_sum = 0;

    for (int i = 0; i < record_count; ++i) {
        // Generate unique keys within a range
        do {
            keys[i] = rand() % 1000 + 1;
        } while (i > 0 && keys[i] == keys[i-1]);

        offset_sum += keys[i];
        offsets[i] = offset_sum + 10; // Constant value added for offset

        Record* record = allocate_from_pool(record_pool);
        if (!record) {
            fprintf(stderr, "Failed to allocate memory from pool\n");
            continue;
        }

        record->field1 = rand() % 100;
        record->field2 = rand() % 1000;
        record->field3 = (float)rand() / RAND_MAX * 100.0f;
        record->timestamp = rand() % 100000;

        records[i] = *record;
    }
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    free(pool);
}

// Main function
int main() {
    const int initial_keys_count = 10;
    const int record_count = 100;

    // Memory pools for keys and records
    MemoryPool key_pool = *create_memory_pool(sizeof(int), initial_keys_count);
    MemoryPool record_pool = *create_memory_pool(sizeof(Record), record_count);

    long* offsets = malloc(record_count * sizeof(long));
    int* keys = malloc(initial_keys_count * sizeof(int));
    Record* records = malloc(record_count * sizeof(Record));

    DoublyLinkedList* list = init_list();

    initialize_data(offsets, keys, records, record_count, &key_pool, &record_pool);

    for (int i = 0; i < record_count; ++i) {
        insert_node(list, records[i]);
    }

    // Clean up
    free_memory_pool(&key_pool);
    free_memory_pool(&record_pool);
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
