#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *name;
    int priority;
} node;

// Mutex for thread safety during memory allocation
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

node* allocate_and_initialize_nodes(size_t num_nodes, const char* base_name, int min_priority, int max_priority) {
    if (num_nodes <= 0 || base_name == NULL) return NULL;

    // Calculate the maximum possible size of a name
    size_t name_length = strlen(base_name) + 20; // Allow for index and null terminator

    node *nodes = malloc(num_nodes * sizeof(node));
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        return NULL;
    }

    // Seed the random number generator once
    static pthread_once_t rand_init_done = PTHREAD_ONCE_INIT;
    pthread_once(&rand_init_done, []() { srand((unsigned int)time(NULL)); });

    // Use a mutex to protect allocation from race conditions in concurrent environments
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i].name = malloc(name_length);
        if (!nodes[i].name) {
            fprintf(stderr, "Failed to allocate memory for node name at index %zu\n", i);
            // Free previously allocated nodes
            while (i > 0) {
                free(nodes[--i].name);
            }
            free(nodes);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        snprintf(nodes[i].name, name_length, "%s_%zu", base_name, i);

        // Generate a random priority within the specified range
        nodes[i].priority = min_priority + rand() % (max_priority - min_priority + 1);
    }

    pthread_mutex_unlock(&mutex);
    return nodes;
}

void free_nodes(node *nodes, size_t num_nodes) {
    if (!nodes) return;

    for (size_t i = 0; i < num_nodes; ++i) {
        free(nodes[i].name);
    }
    free(nodes);
}

// Example unit test function
void test_allocate_and_initialize_nodes() {
    size_t num_nodes = 5;
    const char* base_name = "test_node";
    int min_priority = 1, max_priority = 10;

