        if (offsets[i] == offset) {
            return false;
        }
    }
    return true;
}

bool is_unique_key(int *keys, int key, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] == key) {
            return false;
        }
    }
    return true;
}

