    pthread_mutex_lock(&mutex);

    if (count >= MAX_OFFSETS || !is_unique_offset(offsets, offset, count) || 
        !is_unique_key(keys, key, count) || key < KEY_MIN || key > KEY_MAX) {
        fprintf(stderr, "Invalid or duplicate entry\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    offsets[count] = offset;
    keys[count] = key;
    initialize_record(&records[count]);

    pthread_mutex_unlock(&mutex);
}

void free_resources(long *offsets, int *keys, record *records, size_t count) {
