#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* name;
    int priority;
    double duration;
} Task;

void log_task_creation(const Task* task) {
    printf("Task Created: Name=%s, Priority=%d, Duration=%.2f\n", task->name, task->priority, task->duration);
}

Task* create_tasks(int num_tasks, const char* base_name, int priority_min, int priority_max, unsigned int random_seed, void (*logger)(const Task*)) {
    if (num_tasks <= 0 || priority_min > priority_max) return NULL;

    srand(random_seed);

    Task* tasks = malloc(num_tasks * sizeof(Task));
    if (!tasks) return NULL;

    for (int i = 0; i < num_tasks; ++i) {
        char name[64];
        snprintf(name, sizeof(name), "%s_%d", base_name, i);

        tasks[i].name = strdup(name);
        if (!tasks[i].name) {
            // Free any allocated memory on failure
            for (int j = 0; j < i; ++j) free(tasks[j].name);
            free(tasks);
            return NULL;
        }

        tasks[i].priority = priority_min + rand() % (priority_max - priority_min + 1);
        tasks[i].duration = (double)(rand() % 10000) / 100.0;

        if (logger) logger(&tasks[i]);
    }

    return tasks;
}

void free_tasks(Task* tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; ++i) {
        free(tasks[i].name);
    }
    free(tasks);
}
