#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <yaml.h>

// Define structures
typedef struct {
    int seconds, minutes, hours, day, month, year;
} timestamp_t;

typedef struct {
    int value;
    char key[33];
    timestamp_t created_at;
} record_t;

typedef struct node {
    char* name;
    int priority;
} node_t;

// Configuration structure
typedef struct {
    size_t num_nodes;
    size_t num_records;
    int min_priority, max_priority;
    int min_value, max_value;
} config_t;

// Global configuration
config_t config;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to load configuration from a YAML file
void load_config(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Could not open file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    yaml_document_t doc;
    yaml_parser_t parser;

    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, file);

    if (!yaml_parser_load(&parser, &doc)) {
        fprintf(stderr, "Failed to load YAML document\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    yaml_node_t* root = doc.nodes[0];
    yaml_node_t* seq = root->data.sequence;

    for (size_t i = 0; i < seq->length; ++i) {
        yaml_node_item_t *item = &seq->data.sequence[i];

        if (!yaml_scalar_value(item->node, NULL)) continue;

        const char *key = yaml_node_get_string(yaml_document_get_node(&doc, item->value));

        if (strcmp(key, "num_nodes") == 0) config.num_nodes = atoi((const char *)item->node->data.scalar.value);
        else if (strcmp(key, "num_records") == 0) config.num_records = atoi((const char *)item->node->data.scalar.value);
        else if (strcmp(key, "min_priority") == 0) config.min_priority = atoi((const char *)item->node->data.scalar.value);
        else if (strcmp(key, "max_priority") == 0) config.max_priority = atoi((const char *)item->node->data.scalar.value);
        else if (strcmp(key, "min_value") == 0) config.min_value = atoi((const char *)item->node->data.scalar.value);
        else if (strcmp(key, "max_value") == 0) config.max_priority = atoi((const char *)item->node->data.scalar.value);
    }

    yaml_document_delete(&doc);
    yaml_parser_delete(&parser);
    fclose(file);
}

// Function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Function to allocate and initialize nodes
node_t** allocate_nodes(const char* base_name) {
    node_t** nodes = malloc(config.num_nodes * sizeof(node_t*));
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < config.num_nodes; ++i) {
        nodes[i] = malloc(sizeof(node_t));

        // Allocate and initialize name
        char buffer[64];
        snprintf(buffer, sizeof(buffer), "%s_%zu", base_name, i);
        size_t name_len = strlen(buffer);
        nodes[i]->name = malloc((name_len + 1) * sizeof(char));
        strcpy(nodes[i]->name, buffer);

        // Set random priority
        nodes[i]->priority = rand() % (config.max_priority - config.min_priority + 1) + config.min_priority;
    }

    pthread_mutex_unlock(&mutex);
    return nodes;
}

// Function to allocate and initialize records
record_t** allocate_records() {
    record_t** records = malloc(config.num_records * sizeof(record_t*));
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < config.num_records; ++i) {
        records[i] = malloc(sizeof(record_t));

        // Set random value
        records[i]->value = rand() % (config.max_value - config.min_value + 1) + config.min_value;

        // Initialize key with a unique string
        snprintf(records[i]->key, sizeof(records[i]->key), "record_key_%zu", i);

        // Populate timestamp with current time
        time_t t = time(NULL);
        struct tm* now = localtime(&t);
        records[i]->created_at.seconds = now->tm_sec;
        records[i]->created_at.minutes = now->tm_min;
        records[i]->created_at.hours = now->tm_hour;
        records[i]->created_at.day = now->tm_mday;
        records[i]->created_at.month = now->tm_mon + 1;
        records[i]->created_at.year = now->tm_year + 1900;
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

// Function to print node and record data
void print_data(node_t** nodes, record_t** records) {
    for (size_t i = 0; i < config.num_nodes; ++i) {
        printf("Node %zu: Name=%s, Priority=%d\n", i, nodes[i]->name, nodes[i]->priority);
    }

    for (size_t i = 0; i < config.num_records; ++i) {
        printf("Record %zu: Value=%d, Key=%s, Created At=%02d:%02d:%02d %02d/%02d/%04d\n",
               i,
               records[i]->value,
               records[i]->key,
               records[i]->created_at.hours,
               records[i]->created_at.minutes,
               records[i]->created_at.seconds,
               records[i]->created_at.day,
               records[i]->created_at.month,
               records[i]->created_at.year);
    }
}

// Main function demonstrating usage
int main() {
    load_config("config.yaml");
    init_random();

    const char* base_name = "node";
    node_t** nodes = allocate_nodes(base_name);
    record_t** records = allocate_records();

    print_data(nodes, records);

    // Cleanup
    for (size_t i = 0; i < config.num_nodes; ++i) {
        free(nodes[i]->name);
        free(nodes[i]);
    }
    free(nodes);

    for (size_t i = 0; i < config.num_records; ++i) {
        free(records[i]);
    }
    free(records);

    return 0;
}
```

