    Record* head;
    Record* tail;
    size_t record_count;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->record_count = 0;
    return list;
}

void destroy_doubly_linked_list(DoublyLinkedList* list) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current->metadata);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_record(DoublyLinkedList* list, Record* record) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }
    list->record_count++;

    pthread_mutex_unlock(&list->lock);
}

void* memory_pool_manager(void* arg) {
