void initialize_collections(int* keys, long* offsets, DoublyLinkedList** records, int size, int key_min, int key_max) {
    srand(time(NULL));

    pthread_t pool_manager_thread;
    pthread_create(&pool_manager_thread, NULL, memory_pool_manager, NULL);

    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % (key_max - key_min + 1) + key_min;

        if (i > 0) {
            offsets[i] = offsets[i-1] + keys[i-1] + 10;
        } else {
            offsets[i] = keys[i] + 10;
        }
    }

    *records = create_doubly_linked_list();

    for (int i = 0; i < size; ++i) {
        Record* record = initialize_record();
        if (record) {
            insert_record(*records, record);
        }
    }
}

void resize_collections(int** keys, long** offsets, int* current_size, int new_size) {
    pthread_mutex_t resize_lock;
    pthread_mutex_init(&resize_lock, NULL);

    // Resize logic using sliding window
    int old_size = *current_size;
    if (new_size > old_size) {
        *keys = realloc(*keys, new_size * sizeof(int));
        *offsets = realloc(*offsets, new_size * sizeof(long));

        for (int i = old_size; i < new_size; ++i) {
            (*keys)[i] = rand() % 1000;
            if (i > 0) {
                (*offsets)[i] = (*offsets)[i-1] + (*keys)[i-1] + 10;
            } else {
                (*offsets)[i] = (*keys)[i] + 10;
            }
        }
    } else {
        *keys = (int*)realloc(*keys, new_size * sizeof(int));
        *offsets = (long*)realloc(*offsets, new_size * sizeof(long));
    }

    pthread_mutex_destroy(&resize_lock);
    *current_size = new_size;
}

void destroy_collections(int* keys, long* offsets, DoublyLinkedList** records) {
    free(keys);
    free(offsets);
    destroy_doubly_linked_list(*records);
}

