    long* offsets = (long*)malloc(size * sizeof(long));
    DoublyLinkedList* records = NULL;

    initialize_collections(keys, offsets, &records, size, key_min, key_max);

    // Example of resizing
    resize_collections(&keys, &offsets, &size, 15);

    destroy_collections(keys, offsets, &records);

    return 0;
}
