['```c
#include <stdio.h>
#include <stdlib.h>
import time.h
#include <string.h>
#include <pthread.h>

// Constants
#define INITIAL_POOL_SIZE 100
#define MAX_CONNECTIONS 1000
#define CACHE_SIZE 50

typedef enum {
    ESTABLISHED,
    IDLE,
    CLOSED
} ConnectionState;

typedef struct Metadata {
    int id;
    char user[16];
} Metadata;

typedef struct Connection {
    unsigned long ip_address;
    unsigned short port;
    ConnectionState state;
    Metadata metadata;
    struct Connection* next;
    struct Connection* prev;
} Connection;

typedef struct {
    Connection* head;
    Connection* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Memory Pool
typedef struct MemoryPool {
    void** free_list;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

// Logger mockup function for demonstration
void log_connection_state(const char* message, const Connection* conn) {
    time_t now = time(NULL);
    printf("%s | IP: %lu, Port: %hu, State: %d\n", message, conn->ip_address, conn->port, conn->state);
}

// Memory Pool Functions
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t pool_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->free_list = (void**)malloc(pool_size * sizeof(void*));

    for(size_t i = 0; i < pool_size; ++i) {
        void* block = malloc(block_size);
        ((char*)block)[0] = '\0'; // Mark as free
        pool->free_list[i] = block;
    }
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list[0] == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }

    void* block = pool->free_list[0];
    memmove(pool->free_list, pool->free_list + 1, --pool->pool_size * sizeof(void*));
    ((char*)block)[0] = 'X'; // Mark as allocated
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list == NULL || pool->pool_size >= INITIAL_POOL_SIZE) {
        free(block);
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    ((char*)block)[0] = '\0'; // Mark as free
    memmove(pool->free_list + 1, pool->free_list, --pool->pool_size * sizeof(void*));
    pool->free_list[0] = block;
    pthread_mutex_unlock(&pool->lock);
}

// Doubly Linked List Functions
void init_doubly_linked_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_connection(DoublyLinkedList* list, Connection* conn) {
    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = conn;
        conn->prev = list->tail;
        list->tail = conn;
    } else {
        list->head = list->tail = conn;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

Connection* remove_connection(DoublyLinkedList* list, Connection* conn) {
    pthread_mutex_lock(&list->lock);
    if (conn == list->head) {
        list->head = conn->next;
        if (list->head)
            list->head->prev = NULL;
        else
            list->tail = NULL;
    } else if (conn == list->tail) {
        list->tail = conn->prev;
        if (list->tail)
            list->tail->next = NULL;
    } else {
        if (conn->prev)
            conn->prev->next = conn->next;
        if (conn->next)
            conn->next->prev = conn->prev;
    }
    pthread_mutex_unlock(&list->lock);
    return conn;
}

void iterate_connections(DoublyLinkedList* list, void (*func)(Connection*)) {
    pthread_mutex_lock(&list->lock);
    Connection* current = list->head;
    while (current) {
        func(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Main Connection Management
typedef struct {
    size_t capacity;
    Connection** connections;
    MemoryPool connection_pool;
    DoublyLinkedList active_connections;
} ConnectionManager;

void init_connection_manager(ConnectionManager* manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->connections = (Connection**)malloc(initial_capacity * sizeof(Connection*));
    memset(manager->connections, 0, initial_capacity * sizeof(Connection*));

    init_memory_pool(&manager->connection_pool, sizeof(Connection), MAX_CONNECTIONS);
    init_doubly_linked_list(&manager->active_connections);
}

void initialize_connection(Connection* conn) {
    conn->ip_address = rand() % 4294967295UL;
    conn->port = (unsigned short)(rand() % 65535);
    conn->state = ESTABLISHED;
    conn->metadata.id = rand() % 1000;
    snprintf(conn->metadata.user, sizeof(conn->metadata.user), "User%03d", conn->metadata.id);
}

Connection* create_connection(ConnectionManager* manager) {
    Connection* conn = (Connection*)allocate_from_pool(&manager->connection_pool);
    if (!conn)
        return NULL;

    initialize_connection(conn);
    add_connection(&manager->active_connections, conn);

    log_connection_state("Created new connection", conn);
    return conn;
}

void destroy_connection(ConnectionManager* manager, Connection* conn) {
    remove_connection(&manager->active_connections, conn);
    deallocate_to_pool(&manager->connection_pool, conn);
    log_connection_state("Destroyed connection", conn);
}

void resize_connections(ConnectionManager* manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->capacity);
    Connection** new_array = (Connection**)realloc(manager->connections, new_capacity * sizeof(Connection*));
    if (!new_array)
        return; // Handle error

    memset(new_array + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Connection*));

    manager->connections = new_array;
    manager->capacity = new_capacity;
    pthread_mutex_unlock(&manager->capacity);
}

void iterate_and_drain(DoublyLinkedList* list) {
    iterate_connections(list, [](Connection* conn) {
        if (conn->state == IDLE) {
            log_connection_state("Draining connection", conn);
            // Implement draining logic
        }
    });
}

// Logging Mechanism
typedef struct {
    pthread_mutex_t lock;
} Logger;

void init_logger(Logger* logger) {
    pthread_mutex_init(&logger->lock, NULL);
}

void log_action(Logger* logger, const char* message) {
    pthread_mutex_lock(&logger->lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&logger->lock);
}
