// Define log levels and categories for simplicity
typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef enum {
    CATEGORY_SYSTEM,
    CATEGORY_NETWORK,
    CATEGORY_APPLICATION
} Category;

// Log structure definition
typedef struct {
    time_t timestamp;
    LogLevel level;
    Category category;
    char message[256];
    char metadata[128];
} LogEntry;

// Node for the linked list of logs
typedef struct LogNode {
    LogEntry entry;
    struct LogNode* next;
} LogNode;

// Log collection structure with thread safety mechanisms
typedef struct {
    LogNode* head;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
    size_t log_count;
} LogCollection;

// Function prototypes
LogCollection* create_log_collection();
void free_log_collection(LogCollection* collection);
int add_log_entry(LogCollection* collection, const LogEntry* entry);
int remove_log_entry(LogCollection* collection, time_t timestamp);
int modify_log_entry(LogCollection* collection, time_t timestamp, const char* new_message);
LogNode* retrieve_logs(LogCollection* collection, LogLevel level, Category category);
void serialize_log_collection(const LogCollection* collection, const char* filename);
LogCollection* deserialize_log_collection(const char* filename);
void integrate_with_monitoring_service(LogCollection* collection);

// Implementation
LogCollection* create_log_collection() {
    LogCollection* collection = (LogCollection*)malloc(sizeof(LogCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_rwlock_init(&collection->lock, NULL);
    collection->log_count = 0;

    return collection;
}

void free_log_collection(LogCollection* collection) {
    LogNode* current = collection->head;
    while (current) {
        LogNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&collection->lock);
    free(collection);
}

int add_log_entry(LogCollection* collection, const LogEntry* entry) {
    pthread_rwlock_wrlock(&collection->lock);

    LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
    if (!new_node) {
        pthread_rwlock_unlock(&collection->lock);
        return -1;
    }

    memcpy(&(new_node->entry), entry, sizeof(LogEntry));
    new_node->next = collection->head;
    collection->head = new_node;
    collection->log_count++;

    pthread_rwlock_unlock(&collection->lock);
    return 0;
}

int remove_log_entry(LogCollection* collection, time_t timestamp) {
    pthread_rwlock_wrlock(&collection->lock);

    LogNode *current = collection->head, *prev = NULL;
    while (current) {
        if (current->entry.timestamp == timestamp) {
            if (prev)
                prev->next = current->next;
            else
                collection->head = current->next;

            free(current);
            collection->log_count--;
            pthread_rwlock_unlock(&collection->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_rwlock_unlock(&collection->lock);
    return -1; // Log entry not found
}

int modify_log_entry(LogCollection* collection, time_t timestamp, const char* new_message) {
    pthread_rwlock_wrlock(&collection->lock);

    LogNode *current = collection->head;
    while (current) {
        if (current->entry.timestamp == timestamp) {
            strncpy(current->entry.message, new_message, sizeof(current->entry.message));
            pthread_rwlock_unlock(&collection->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&collection->lock);
    return -1; // Log entry not found
}

LogNode* retrieve_logs(LogCollection* collection, LogLevel level, Category category) {
    pthread_rwlock_rdlock(&collection->lock);

    LogNode *result = NULL, *tail = NULL;

    for (LogNode *current = collection->head; current; current = current->next) {
        if ((current->entry.level == level || level == -1) &&
            (current->entry.category == category || category == -1)) {

            LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
            memcpy(&(new_node->entry), &(current->entry), sizeof(LogEntry));
            new_node->next = NULL;

            if (!result)
                result = new_node;
            else
                tail->next = new_node;

            tail = new_node;
        }
    }

    pthread_rwlock_unlock(&collection->lock);
    return result;
}

void serialize_log_collection(const LogCollection* collection, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_rwlock_rdlock(&collection->lock);

    fwrite(&(collection->log_count), sizeof(size_t), 1, file);
    for (LogNode* current = collection->head; current; current = current->next) {
        fwrite(&(current->entry.timestamp), sizeof(time_t), 1, file);
        fwrite(&(current->entry.level), sizeof(LogLevel), 1, file);
        fwrite(&(current->entry.category), sizeof(Category), 1, file);
        fwrite(current->entry.message, sizeof(char), sizeof(current->entry.message), file);
        fwrite(current->entry.metadata, sizeof(char), sizeof(current->entry.metadata), file);
    }

    pthread_rwlock_unlock(&collection->lock);
    fclose(file);
}

LogCollection* deserialize_log_collection(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    LogCollection* collection = create_log_collection();
    if (!collection) {
        fclose(file);
        return NULL;
    }

    size_t log_count;
    fread(&log_count, sizeof(size_t), 1, file);

    pthread_rwlock_wrlock(&collection->lock);
    for (size_t i = 0; i < log_count; ++i) {
        LogEntry entry;
        fread(&(entry.timestamp), sizeof(time_t), 1, file);
        fread(&(entry.level), sizeof(LogLevel), 1, file);
        fread(&(entry.category), sizeof(Category), 1, file);
        fread(entry.message, sizeof(char), sizeof(entry.message), file);
        fread(entry.metadata, sizeof(char), sizeof(entry.metadata), file);

        LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
        memcpy(&(new_node->entry), &entry, sizeof(LogEntry));
        new_node->next = collection->head;
        collection->head = new_node;
    }
    collection->log_count = log_count;

    pthread_rwlock_unlock(&collection->lock);
    fclose(file);

    return collection;
}

void integrate_with_monitoring_service(LogCollection* collection) {
    // Simulate integration with an external monitoring service
    // This is a placeholder for actual implementation
    printf("Integrating with the monitoring service...\n");
}
