        (*records)[i].field1 = rand() % 100;
        (*records)[i].field2 = rand() % 500;
        (*records)[i].field3 = ((float)rand()) / RAND_MAX * 100.0f;
        (*records)[i].timestamp = time(NULL);
        (*records)[i].status = (keys[i] % 2 == 0) ? 1 : 0; // example condition
    }
}

void insert_record(Node** head, record data) {
    pthread_mutex_lock(&lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&lock);
}

void serialize_to_file(const char* filename, Node* head) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    Node* current = head;
    while (current) {
        fwrite(&(current->data), sizeof(record), 1, file);
        current = current->next;
    }

    fclose(file);
}

void iterate_and_process(Node* head) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current) {
        // Process each record; e.g., print or modify
        printf("Record: %d, Status: %d\n", current->data.field2, current->data.status);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void cleanup(Node** head) {
    pthread_mutex_lock(&lock);

    Node* current = *head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;

    pthread_mutex_unlock(&lock);
}

int main() {
