    initialize_records(&records, keys, offsets);

    for (int i = 0; i < 5; ++i) {
        insert_record(&head, records[i]);
    }

    serialize_to_file("data.bin", head);
    iterate_and_process(head);

    cleanup(&head);
    free(records);

    return 0;
}
