['Below is a C code snippet that demonstrates how you might implement the described functionality. Note that this example assumes the use of certain libraries like `libtiff` for TIFF parsing and `libpng` for PNG handling. It also uses `pthread` for thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <tiffio.h>
#include <png.h>

typedef struct {
    int bitsPerSample;
    unsigned char *extraSamples;
    size_t extraSamplesCount;
} TIFFMetadata;

typedef struct Node {
    char tag[256];
    double value;
    struct Node* children;
    size_t childCount;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

TIFFMetadata parseTIFF(const char *filePath) {
    TIFFMetadata metadata = {0};
    TIFF *tiff = TIFFOpen(filePath, "r");
    if (!tiff) return metadata;

    uint16 bitsPerSample;
    TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        TIFFClose(tiff);
        return metadata;
    }

    metadata.bitsPerSample = bitsPerSample;

    // Example of handling extra samples
    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &metadata.extraSamples)) {
        metadata.extraSamplesCount = strlen(metadata.extraSamples);
    }

    TIFFClose(tiff);
    return metadata;
}

double calculateAverage(Node *node) {
    double sum = 0.0;
    size_t count = 0;

    for (size_t i = 0; i < node->childCount; ++i) {
        Node *child = &node->children[i];
        if (child->value != 0) {
            sum += child->value;
            count++;
        }
        double childSum = calculateAverage(child);
        sum += childSum;
        count += (childSum != 0.0) ? 1 : 0;
    }

    return (count > 0) ? sum / count : 0.0;
}

void parsePNGMetadata(const char *filePath, Node **rootNode) {
    FILE *fp = fopen(filePath, "rb");
    if (!fp) return;

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) goto cleanup;

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, NULL, NULL);
        goto cleanup;
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        goto cleanup;
    }

    png_init_io(png_ptr, fp);
    png_read_info(png_ptr, info_ptr);

    // Example of extracting metadata
    int width, height, bit_depth, color_type;
    png_get_IHDR(png_ptr, info_ptr, &width, &height, &bit_depth, &color_type,
                 NULL, NULL, NULL);

    // Create a root node for hierarchical data structure
    *rootNode = malloc(sizeof(Node));
    strcpy((*rootNode)->tag, "PNG Metadata");
    (*rootNode)->value = 0; // Not used in this example
    (*rootNode)->childCount = 1;
    (*rootNode)->children = malloc(sizeof(Node));

    Node *metadataNode = &(*rootNode)->children[0];
    strcpy(metadataNode->tag, "Image Dimensions");
    metadataNode->value = (double)width * height;
    metadataNode->childCount = 2;

    metadataNode->children = malloc(2 * sizeof(Node));
    strcpy(metadataNode->children[0].tag, "Width");
    metadataNode->children[0].value = width;
    strcpy(metadataNode->children[1].tag, "Height");
    metadataNode->children[1].value = height;

    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);

cleanup:
    fclose(fp);
}

void handleImageFile(const char *filePath) {
    pthread_mutex_lock(&lock);

    if (strstr(filePath, ".tiff") || strstr(filePath, ".tif")) {
        TIFFMetadata metadata = parseTIFF(filePath);
        printf("TIFF Bits per Sample: %d\n", metadata.bitsPerSample);
        printf("Extra Samples Count: %zu\n", metadata.extraSamplesCount);
        free(metadata.extraSamples);
    } else if (strstr(filePath, ".png")) {
        Node *rootNode;
        parsePNGMetadata(filePath, &rootNode);

        double average = calculateAverage(rootNode);
        printf("Average Value in PNG Metadata: %.2f\n", average);

        // Free allocated memory
        free(rootNode->children[0].children);
        free(rootNode->children);
        free(rootNode);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    const char *imagePath = "example.png";
    handleImageFile(imagePath);
    return 0;
}
```

This code provides a basic structure for handling TIFF and PNG images, extracting metadata, and calculating averages in a hierarchical data structure. It uses mutexes to ensure thread safety and dynamic memory allocation for managing resources efficiently. Adjustments may be needed based on specific library versions or additional requirements.']

