    int new_capacity = collection->capacity + TASK_INCREMENT;
    Task *new_tasks = realloc(collection->tasks, new_capacity * sizeof(Task));
    if (new_tasks) {
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
