    for (int i = 0; i < collection->task_count; ++i) {
        if (collection->tasks[i].id == id) {
            memmove(&collection->tasks[i], &collection->tasks[i + 1],
                    (--collection->task_count - i) * sizeof(Task));
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void update_task_priority(TaskCollection *collection, int id, int new_priority) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->task_count; ++i) {
        if (collection->tasks[i].id == id) {
            collection->tasks[i].priority = new_priority;
            break;
        }
