```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_WORKERS 10000

typedef struct {
    char log_buffer[256];
    double performance_metric;
    int (*action)(void* data);
    void* history_entries;
} Worker;

typedef struct {
    time_t timestamp;
    int outcome;
    int error_code;
} HistoryEntry;

typedef struct {
    Worker workers[MAX_WORKERS];
    size_t worker_count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    // Simulated network condition parameters
    int network_status; 
} WorkerManager;

void* action_function(void* data) {
    // Placeholder for actual action code, e.g., computation or data processing.
    return NULL;
}

void initialize_workers(WorkerManager *manager, size_t count) {
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    manager->worker_count = 0;

    for (size_t i = 0; i < count && i < MAX_WORKERS; ++i) {
        Worker *worker = &manager->workers[i];
        worker->performance_metric = ((double)rand() / RAND_MAX) * 100.0;
        worker->action = action_function;
        memset(worker->log_buffer, '\0', sizeof(worker->log_buffer));

        // Initialize history entries
        HistoryEntry initial_entry = {time(NULL), 0 /*success*/, 0 /*no error*/};
        worker->history_entries = malloc(sizeof(HistoryEntry) * 10); // Initial capacity of 10
        if (worker->history_entries != NULL) {
            memcpy(worker->history_entries, &initial_entry, sizeof(initial_entry));
        }

        manager->worker_count++;
    }
}

void perform_aggregation(WorkerManager *manager, void (*callback)(int), int is_async) {
    pthread_mutex_lock(&manager->mutex);

    // Simulating processing in segments to prevent memory overflow
    size_t segment_size = 100; // Arbitrary segment size for demonstration

    for (size_t i = 0; i < manager->worker_count; i += segment_size) {
        size_t current_segment_size = fmin(segment_size, manager->worker_count - i);

        // Process each worker in the segment
        for (size_t j = 0; j < current_segment_size; ++j) {
            Worker *worker = &manager->workers[i + j];

            // Simulating action processing with potential failure
            if (worker->action(NULL) == -1) {
                HistoryEntry entry = {time(NULL), -1, 1}; // Log error
                memcpy(worker->history_entries + j % 10, &entry, sizeof(entry));

                // Call the callback with an error code
                if (!is_async || callback != NULL) {
                    callback(1); // Error occurred
                }
            } else {
                HistoryEntry entry = {time(NULL), 0 /*success*/, 0 /*no error*/};
                memcpy(worker->history_entries + j % 10, &entry, sizeof(entry));

                if (!is_async && callback != NULL) {
                    callback(0); // Success
                }
            }
        }

        // Simulate asynchronous behavior by using a condition variable
        if (is_async) {
            pthread_cond_signal(&manager->cond_var);
        } else {
            pthread_mutex_unlock(&manager->mutex);
        }
    }
}

void aggregation_callback(int status) {
    printf("Aggregation completed with status: %d\n", status);
}

int main() {
    srand(time(NULL));

    WorkerManager manager;
    initialize_workers(&manager, 5000);

    // Test synchronous aggregation
    perform_aggregation(&manager, aggregation_callback, 0);

    // Test asynchronous aggregation
    perform_aggregation(&manager, aggregation_callback, 1);

    return 0;
}
```

### Explanation of Key Components:

- **Worker Initialization**: The `initialize_workers` function sets up a specified number of workers with random performance metrics and initial history entries.

- **Aggregation Function**: Handles both synchronous and asynchronous aggregation modes. Utilizes condition variables for asynchronous operations to prevent blocking the main thread while waiting for completion.

- **Error Handling**: Logs errors into worker histories if action functions fail, invoking callbacks as needed.

- **Concurrency and Synchronization**: Uses mutexes and condition variables to ensure safe access and synchronization across threads.

### Test Cases:

1. **Empty List of Workers**: Initialize a `WorkerManager` with zero workers and attempt aggregation.
2. **Non-positive Performance Metrics**: Adjust the random metric generation or set explicitly, test performance behavior.
3. **Error Handling**: Manually trigger errors in worker actions to verify callback invocation.
4. **High Load Simulation**: Test with maximum allowed concurrent workers (10,000) to ensure system stability.

This setup should be expanded and refined based on specific requirements and real-world conditions such as network delays or node failures for full-fledged production use.']

