    Record(short s, int i, float f) : shortField(s), intField(i), floatField(f) {}
};

class CharacterAttackManager {
private:
    struct ListNode {
        Record record;
        std::unique_ptr<ListNode> next;
        ListNode(const Record& rec) : record(rec), next(nullptr) {}
    };

    std::vector<long>* offsets;
    std::vector<int>* keys;
    std::unique_ptr<ListNode> recordsHead;
    std::unordered_map<int, std::shared_ptr<ListNode>> cache;
    std::mutex dataMutex;
    std::atomic<bool> savePending{false};

    // Memory pool for Record allocation
    std::vector<std::unique_ptr<Record>> recordPool;

    static std::random_device rd;
    static std::mt19937 gen;
    static std::uniform_int_distribution<> shortDist, intDist, floatDist;

public:
    CharacterAttackManager(size_t offsetSize, size_t keySize) {
        offsets = new std::vector<long>(offsetSize);
        keys = new std::vector<int>(keySize);

        for (int i = 0; i < keySize; ++i) {
            int uniqueKey;
            do {
                uniqueKey = gen() % 10000; // Assume range is 0-9999
            } while (std::find(keys->begin(), keys->end(), uniqueKey) != keys->end());
            (*keys)[i] = uniqueKey;
        }

        // Initialize records with random values using memory pool
        for (size_t i = 0; i < offsetSize; ++i) {
            recordPool.emplace_back(std::make_unique<Record>(
                shortDist(gen), intDist(gen), floatDist(gen)));
            auto newNode = std::make_unique<ListNode>(recordPool.back()->*recordPool.back());
            if (!recordsHead) {
                recordsHead = std::move(newNode);
            } else {
                ListNode* temp = recordsHead.get();
                while (temp->next) temp = temp->next.get();
                temp->next = std::move(newNode);
            }
        }

        // Start a background thread to save state periodically
        std::thread([this] { periodicSave(); }).detach();
    }

    ~CharacterAttackManager() {
        delete offsets;
        delete keys;
        while (recordsHead) {
            recordsHead = std::move(recordsHead->next);
        }
    }

    void logAndCacheRecord(int key, const Record& rec) {
        std::lock_guard<std::mutex> lock(dataMutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            it->second->record = rec;
        } else {
            auto newNode = std::make_unique<ListNode>(rec);
            if (!recordsHead) {
                recordsHead = std::move(newNode);
            } else {
                ListNode* temp = recordsHead.get();
                while (temp->next) temp = temp->next.get();
                temp->next = std::move(newNode);
            }
            cache[key] = newNode.get();
        }

        LogChange("Record updated", std::time(nullptr), 1); // Example userId
    }

    void resizeArrays(size_t newOffsetSize, size_t newKeySize) {
        std::lock_guard<std::mutex> lock(dataMutex);
        offsets->resize(newOffsetSize);
        keys->resize(newKeySize);

        for (size_t i = offsets->size(); i < newOffsetSize; ++i) {
            recordPool.emplace_back(std::make_unique<Record>(
                shortDist(gen), intDist(gen), floatDist(gen)));
            auto newNode = std::make_unique<ListNode>(recordPool.back()->*recordPool.back());
            if (!recordsHead) {
                recordsHead = std::move(newNode);
            } else {
                ListNode* temp = recordsHead.get();
                while (temp->next) temp = temp->next.get();
                temp->next = std::move(newNode);
            }
        }

        for (size_t i = keys->size(); i < newKeySize; ++i) {
            int uniqueKey;
            do {
                uniqueKey = gen() % 10000; // Assume range is 0-9999
            } while (std::find(keys->begin(), keys->end(), uniqueKey) != keys->end());
            (*keys)[i] = uniqueKey;
        }
    }

    void periodicSave() {
        while (!savePending.load()) {
            std::this_thread::sleep_for(std::chrono::minutes(1));
            std::lock_guard<std::mutex> lock(dataMutex);
            saveState();
        }
    }

    void triggerSave() {
        savePending.store(true);
    }

private:
    void saveState() {
        // Implement state saving to disk, e.g., using a binary file
        std::ofstream outFile("state.bin", std::ios::binary | std::ios::out);
        if (outFile.is_open()) {
            // Example: Save keys and offsets
            for (const auto& offset : *offsets) {
                outFile.write(reinterpret_cast<const char*>(&offset), sizeof(long));
            }
            for (const auto& key : *keys) {
                outFile.write(reinterpret_cast<const char*>(&key), sizeof(int));
            }
            // Include records save logic here

            LogChange("State saved", std::time(nullptr), 1); // Example userId
        }
    }
};

std::random_device CharacterAttackManager::rd;
std::mt19937 CharacterAttackManager::gen(CharacterAttackManager::rd());
std::uniform_int_distribution<> CharacterAttackManager::shortDist(0, 100);
std::uniform_int_distribution<> CharacterAttackManager::intDist(-1000, 1000);
std::uniform_real_distribution<float> CharacterAttackManager::floatDist(-1.0f, 1.0f);

