#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_PAGES 100
#define SESSION_TIMEOUT 1800 // 30 minutes

typedef struct {
    char sessionId[64];
    int isAuthenticated;
    time_t lastActivity;
    char visitedPages[MAX_PAGES][256];
    size_t pageCount;
} Session;

typedef struct Node {
    Session session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SessionList;

static SessionList sessions = {NULL, PTHREAD_MUTEX_INITIALIZER};

void generateSessionId(char* sessionId, const char* ipAddress, const char* userAgent) {
    snprintf(sessionId, 64, "%s_%lu_%s", ipAddress, (unsigned long)time(NULL), userAgent); // Simplified
}

Node* findSession(const char* sessionId) {
    Node* current = sessions.head;
    while (current != NULL) {
        if (strcmp(current->session.sessionId, sessionId) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void addSession(const char* ipAddress, const char* userAgent) {
    pthread_mutex_lock(&sessions.lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for session");
        pthread_mutex_unlock(&sessions.lock);
        return;
    }

    generateSessionId(newNode->session.sessionId, ipAddress, userAgent);
    newNode->session.isAuthenticated = 0;
    newNode->session.lastActivity = time(NULL);
    newNode->session.pageCount = 0;

    newNode->next = sessions.head;
    sessions.head = newNode;

    pthread_mutex_unlock(&sessions.lock);
}

void updateLastActivity(const char* sessionId) {
    pthread_mutex_lock(&sessions.lock);

    Node* sessionNode = findSession(sessionId);
    if (sessionNode != NULL) {
        sessionNode->session.lastActivity = time(NULL);
    }

    pthread_mutex_unlock(&sessions.lock);
}

void addVisitedPage(const char* sessionId, const char* pageUrl) {
    pthread_mutex_lock(&sessions.lock);

    Node* sessionNode = findSession(sessionId);
    if (sessionNode != NULL && sessionNode->session.pageCount < MAX_PAGES) {
        strcpy(sessionNode->session.visitedPages[sessionNode->session.pageCount++], pageUrl);
        updateLastActivity(sessionId);
    }

    pthread_mutex_unlock(&sessions.lock);
}

void removeInactiveSessions() {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&sessions.lock);

    Node *current = sessions.head, *prev = NULL;
    while (current != NULL) {
        if (difftime(currentTime, current->session.lastActivity) > SESSION_TIMEOUT) {
            if (prev == NULL) { // Removing head
                sessions.head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&sessions.lock);
}

void getSessionData(const char* sessionId, Session* outSession) {
    pthread_mutex_lock(&sessions.lock);

    Node* sessionNode = findSession(sessionId);
    if (sessionNode != NULL) {
        *outSession = sessionNode->session;
    }

    pthread_mutex_unlock(&sessions.lock);
}

// Usage
int main() {
    addSession("192.168.1.1", "Mozilla/5.0");
    updateLastActivity("192.168.1_1633036800_Mozilla");
    addVisitedPage("192.168.1_1633036800_Mozilla", "/home");

    Session session;
    getSessionData("192.168.1_1633036800_Mozilla", &session);
    printf("Session ID: %s, Authenticated: %d, Last Activity: %ld\n",
           session.sessionId, session.isAuthenticated, session.lastActivity);

    removeInactiveSessions();

    return 0;
}
```

### Key Points:

- **Memory Management**: A linked list of sessions is used to dynamically manage memory.
- **Session Identification**: Unique IDs are generated using IP, timestamp, and user-agent hash.
- **Concurrency**: `pthread_mutex_t` ensures thread-safe operations on the session list.
- **Inactivity Timeout**: Sessions are removed based on inactivity duration.
- **Recent Activity Retrieval**: Functions allow retrieving session data by ID.
- **Logging and Persistence**: These can be integrated by adding logging functions around critical points and serialization routines for disk I/O.

This implementation is a basic framework. For production, you would want to include more robust error handling, fine-tuned concurrency management (possibly using lock-free structures), caching mechanisms, and detailed integration with external systems like logging services or databases for persistence.']

