void* MemoryPool::Allocate(size_t size) {
    std::lock_guard<std::mutex> lock(poolMutex);

    if (!freeList) {
        AddBlock(size > 0 ? size : 1024); // Default block size
    }

    Block* head = freeList;
    freeList = head->next;

    return head;
}

void MemoryPool::Deallocate(void* ptr) {
    std::lock_guard<std::mutex> lock(poolMutex);

    Block* blockPtr = static_cast<Block*>(ptr);
    blockPtr->next = freeList;
    freeList = blockPtr;
}

void MemoryPool::AddBlock(size_t blockSize) {
    auto newBlock = std::make_unique<char[]>(blockSize);
    blocks.push_back(std::move(newBlock));

    Block* firstBlock = reinterpret_cast<Block*>(blocks.back().get());
    for (size_t i = sizeof(Block); i < blockSize; i += sizeof(Block)) {
        Block* currentBlock = reinterpret_cast<Block*>(firstBlock + i);
        currentBlock->next = freeList;
        freeList = currentBlock;
    }
}

