    timestamp: Instant,
}

#[derive(Debug)]
struct EventLog {
    event_type: String,
    details: String,
    timestamp: Instant,
}

#[derive(Debug)]
struct StatusUpdate {
    status_message: String,
    timestamp: Instant,
}

#[derive(Debug)]
struct NotificationQueueEntry {
    notification_type: String,
    message: String,
    timestamp: Instant,
}

#[derive(Debug)]
struct AuditTrail {
    action: String,
    details: String,
    timestamp: Instant,
}

// Define the memory pool
struct MemoryPool<T> {
    pool: Vec<T>,
}

impl<T> MemoryPool<T>
where
    T: Clone + Default,
{
    fn new(size: usize) -> Self {
        let mut pool = Vec::with_capacity(size);
        for _ in 0..size {
            pool.push(T::default());
        }
        MemoryPool { pool }
    }

    fn allocate(&mut self) -> Option<T> {
        if let Some(item) = self.pool.pop() {
            Some(item)
        } else {
            None
        }
    }

    fn deallocate(&mut self, item: T) {
        self.pool.push(item);
    }
}

// Define the LRU Cache
struct LRUCache<K, V> {
    capacity: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: std::hash::Hash + Eq + Clone, V> LRUCache<K, V> {
    fn new(capacity: usize) -> Self {
        LRUCache {
            capacity,
            map: HashMap::new(),
            order: VecDeque::with_capacity(capacity),
        }
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        if let Some(value) = self.map.get(key) {
            self.order.retain(|k| k != key);
            self.order.push_back(key.clone());
            Some(value)
        } else {
            None
        }
    }

    fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.order.retain(|k| k != &key);
        } else if self.order.len() == self.capacity {
            if let Some(oldest_key) = self.order.pop_front() {
                self.map.remove(&oldest_key);
            }
        }
        self.map.insert(key, value);
        self.order.push_back(key.clone());
    }
}

// Define the main function to initialize collections
fn initialize_collections() -> (
    Arc<RwLock<MemoryPool<UserProfile>>>,
    Arc<RwLock<MemoryPool<TransactionRecord>>>,
    Arc<RwLock<MemoryPool<EventLog>>>,
    Arc<RwLock<MemoryPool<StatusUpdate>>>,
    Arc<RwLock<MemoryLock<NotificationQueueEntry>>>,
    Arc<RwLock<MemoryPool<AuditTrail>>>,
    LRUCache<String, UserProfile>,
) {
    let user_pool = Arc::new(RwLock::new(MemoryPool::<UserProfile>::new(1000)));
    let transaction_pool = Arc::new(RwLock::new(MemoryPool::<TransactionRecord>::new(5000)));
    let event_log_pool = Arc::new(RwLock::new(MemoryPool::<EventLog>::new(2000)));
    let status_update_pool = Arc::new(RwLock::new(MemoryPool::<StatusUpdate>::new(1000)));
    let notification_queue_pool = Arc::new(RwLock::new(MemoryPool::<NotificationQueueEntry>::new(1500)));
    let audit_trail_pool = Arc::new(RwLock::new(MemoryPool::<AuditTrail>::new(3000)));

    // Initialize user profiles with random data
    let mut rng = rand::thread_rng();
    for _ in 0..100 {
        let personal_details: String = (0..10)
            .map(|_| rng.sample(Alphanumeric))
            .collect();
        let preferences = HashMap::from([("theme".to_string(), "dark".to_string())]);
        let recent_activities = vec![format!("Activity {}", rand::random::<u32>())];
        let audit_trails = vec![AuditTrail {
            action: "login".to_string(),
            details: "User logged in".to_string(),
            timestamp: Instant::now(),
        }];

        if let Some(user_profile) = user_pool.write().unwrap().allocate() {
            *user_profile = UserProfile {
                personal_details,
                preferences,
                recent_activities,
                audit_trails,
            };
        }
    }

    // Initialize LRU Cache for user profiles
    let mut lru_cache: LRUCache<String, UserProfile> = LRUCache::new(100);

    // Populate the cache with some user profiles
    if let Some(user_profile) = user_pool.read().unwrap().allocate() {
        lru_cache.put("user_1".to_string(), *user_profile);
    }

    (
        user_pool,
        transaction_pool,
        event_log_pool,
        status_update_pool,
        notification_queue_pool,
        audit_trail_pool,
        lru_cache,
    )
}

fn main() {
    let (
        user_pool,
        transaction_pool,
        event_log_pool,
        status_update_pool,
        notification_queue_pool,
        audit_trail_pool,
        lru_cache,
    ) = initialize_collections();

    // Example usage of the collections
    if let Some(user_profile) = user_pool.write().unwrap().allocate() {
        println!("Allocated user profile: {:?}", user_profile);
    }
}
