typedef struct MemoryPool {
    size_t block_size;
    void *memory;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->memory = aligned_alloc(block_size, block_size * num_blocks);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* memory_pool_allocate(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    static size_t offset = 0;
    if (offset + pool->block_size > pool->total_blocks * pool->block_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory allocation failed
    }
    void* block = ((char*)pool->memory) + offset;
    offset += pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

