    float measurement;
    int timestamp;
    char* status_code;
    unsigned long uid; // Unique Identifier for tracking purposes
} sensor_data;

typedef struct {
    void* pool;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
} memory_pool;

// Custom error codes
#define SUCCESS 0
#define INVALID_INPUT -1
#define MEMORY_ERROR -2

memory_pool* create_memory_pool(size_t initial_size) {
    memory_pool* mp = (memory_pool*)malloc(sizeof(memory_pool));
    if (!mp) return NULL;

    mp->pool = malloc(initial_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->current_size = 0;
    mp->max_size = initial_size;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* pool_allocate(memory_pool* mp, size_t size) {
    if (!mp || !size) return NULL;

    pthread_mutex_lock(&mp->lock);

    void* ptr = (char*)mp->pool + mp->current_size;
    if (mp->current_size + size > mp->max_size) {
        // Resize pool
        size_t new_max_size = mp->max_size * 2;
        void* new_pool = realloc(mp->pool, new_max_size);
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }

        mp->pool = new_pool;
        mp->max_size = new_max_size;
    }

    mp->current_size += size;
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

void pool_free(memory_pool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

int create_sensor_data(float min_value, float max_value, int array_size, int num_entries,
                       sensor_data** data_out, char** status_codes_out, float* precision_values_out) {
    if (array_size <= 0 || num_entries > array_size) return INVALID_INPUT;

    memory_pool* mp = create_memory_pool(INITIAL_POOL_SIZE);
    if (!mp) return MEMORY_ERROR;

    // Allocate and initialize arrays
    *precision_values_out = pool_allocate(mp, array_size * sizeof(float));
    if (!(*precision_values_out)) {
        pool_free(mp);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < array_size; ++i) {
        (*precision_values_out)[i] = 0.0f; // Initialize to zero or any default value
    }

    *status_codes_out = pool_allocate(mp, array_size * sizeof(char));
    if (!(*status_codes_out)) {
        pool_free(mp);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < array_size; ++i) {
        (*status_codes_out)[i] = 'N'; // Default status code
    }

    *data_out = pool_allocate(mp, num_entries * sizeof(sensor_data));
    if (!(*data_out)) {
        pool_free(mp);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < num_entries; ++i) {
