        (*data_out)[i].timestamp = time(NULL); // Use current time as timestamp
        (*data_out)[i].status_code = &((*status_codes_out)[rand() % array_size]); // Assign a random status code
        (*data_out)[i].uid = rand(); // Generate a unique identifier
    }

    return SUCCESS;
}

