#define MAX_TASKS 1000

typedef enum {
    TASK_PENDING,
    TASK_IN_PROGRESS,
    TASK_COMPLETED
} TaskStatus;

typedef struct Task {
    int id;
    int priority;
    TaskStatus status;
    struct Task *next;
} Task;

typedef struct {
    Task *head;
    pthread_mutex_t lock;
    int last_id;
} TaskManager;

TaskManager* create_task_manager() {
    TaskManager *manager = malloc(sizeof(TaskManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->last_id = 0;
    return manager;
}

int generate_unique_id(TaskManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int id = ++manager->last_id;
    pthread_mutex_unlock(&manager->lock);
    return id;
}

Task* create_task(int priority, TaskStatus status) {
    Task *task = malloc(sizeof(Task));
    task->id = generate_unique_id(NULL); // Assuming a global manager
    task->priority = priority;
    task->status = status;
    task->next = NULL;
    return task;
}

void add_task(TaskManager *manager, Task *task) {
    pthread_mutex_lock(&manager->lock);
    task->next = manager->head;
    manager->head = task;
    pthread_mutex_unlock(&manager->lock);
}

Task* remove_task_by_id(TaskManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    Task **ptr = &manager->head;
    while (*ptr && (*ptr)->id != id) {
        ptr = &(*ptr)->next;
    }
    if (*ptr) {
        Task *task = *ptr;
        *ptr = task->next;
        pthread_mutex_unlock(&manager->lock);
        return task;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

Task* get_task_by_id(TaskManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    Task *current = manager->head;
    while (current && current->id != id) {
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return current;
}

void update_task_status(TaskManager *manager, int id, TaskStatus status) {
    pthread_mutex_lock(&manager->lock);
    Task *task = manager->head;
    while (task && task->id != id) {
        task = task->next;
    }
    if (task) {
        task->status = status;
    }
    pthread_mutex_unlock(&manager->lock);
}

Task* filter_tasks(TaskManager *manager, TaskStatus status, int priority) {
    pthread_mutex_lock(&manager->lock);
    Task dummy_head = {0};
    Task *tail = &dummy_head;
    for (Task *current = manager->head; current != NULL; current = current->next) {
        if ((status == TASK_PENDING || current->status == status) &&
            (priority == -1 || current->priority == priority)) {
            tail->next = current;
            tail = current;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    Task *filtered_tasks = dummy_head.next;
    dummy_head.next = NULL; // Break the link to avoid memory leaks
    return filtered_tasks;
}

void free_task(Task *task) {
    if (task) {
        free(task);
    }
}

void free_all_tasks(TaskManager *manager) {
    pthread_mutex_lock(&manager->lock);
    Task *current = manager->head;
    while (current) {
        Task *next = current->next;
        free(current);
        current = next;
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
}

void destroy_task_manager(TaskManager *manager) {
    if (manager) {
        free_all_tasks(manager);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

