// Define structures for user sessions and logs
typedef struct RequestLog {
    time_t timestamp;
    char log[256];
    struct RequestLog* next;
} RequestLog;

typedef struct UserSession {
    int userID;
    time_t createTime;
    time_t lastActivityTime;
    RequestLog* requestLogs;
    struct UserSession* next; // For linked list
} UserSession;

// Memory pool management structures
typedef struct MemoryPool {
    size_t blockSize;
    void** freeList;
    size_t totalBlocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool sessionPool, logPool;

void initMemoryPool(MemoryPool* pool, size_t blockSize, size_t totalBlocks) {
    pool->blockSize = blockSize;
    pool->totalBlocks = totalBlocks;
    pool->freeList = malloc(totalBlocks * sizeof(void*));
    pthread_mutex_init(&pool->lock, NULL);
    for (size_t i = 0; i < totalBlocks; ++i) {
        void* block = malloc(blockSize);
        pool->freeList[i] = block;
    }
}

void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->totalBlocks > 0) {
        void* block = pool->freeList[--pool->totalBlocks];
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);
    return malloc(pool->blockSize); // Fallback to standard allocation
}

void freeToPool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    pool->freeList[pool->totalBlocks++] = block;
    pthread_mutex_unlock(&pool->lock);
}

// Global session management variables
UserSession* headSession = NULL;
size_t sessionArraySize = 0;
UserSession** sessionArray = NULL;
pthread_mutex_t sessionLock;

void initSessions(size_t initialSize) {
    pthread_mutex_init(&sessionLock, NULL);
    sessionArraySize = initialSize;
    sessionArray = (UserSession**)allocateFromPool(&sessionPool);
    memset(sessionArray, 0, sizeof(UserSession*) * sessionArraySize);
}

void addSession(int userID) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&sessionLock);
    if (sessionArraySize <= headSession) {
        size_t newSize = sessionArraySize == 0 ? 1 : sessionArraySize * 2;
        UserSession** newArray = (UserSession**)allocateFromPool(&sessionPool);
        memcpy(newArray, sessionArray, sizeof(UserSession*) * sessionArraySize);
        freeToPool(&sessionPool, sessionArray);
        sessionArray = newArray;
        sessionArraySize = newSize;
    }

    int index = headSession++;
    UserSession* newSession = (UserSession*)allocateFromPool(&sessionPool);
    memset(newSession, 0, sizeof(UserSession));
    newSession->userID = userID;
    newSession->createTime = currentTime;
    newSession->lastActivityTime = currentTime;

    // Add to array
    sessionArray[index] = newSession;

    // Add to linked list
    if (!headSession) {
        headSession = newSession; // Empty list, set as head
    } else {
        UserSession* temp = headSession;
        while (temp->next) temp = temp->next;
        temp->next = newSession;
    }

    pthread_mutex_unlock(&sessionLock);
}

void logActivity(int userID, const char* activity) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&sessionLock);
    for (size_t i = 0; i < sessionArraySize && sessionArray[i]; ++i) {
        UserSession* session = sessionArray[i];
        if (session->userID == userID) {
            RequestLog* logEntry = (RequestLog*)allocateFromPool(&logPool);
            memset(logEntry, 0, sizeof(RequestLog));
            logEntry->timestamp = currentTime;
            strncpy(logEntry->log, activity, sizeof(logEntry->log) - 1);

            if (!session->requestLogs) {
                session->requestLogs = logEntry;
            } else {
                RequestLog* temp = session->requestLogs;
                while (temp->next) temp = temp->next;
                temp->next = logEntry;
            }

            session->lastActivityTime = currentTime;
        }
    }
    pthread_mutex_unlock(&sessionLock);
}

void compressSessions() {
    // Placeholder for compression logic
}

// Thread-safe logging integration
void externalLog(const char* message) {
    static FILE* logFile = NULL;
    if (!logFile) {
        logFile = fopen("activity.log", "a");
    }
    if (logFile) {
        fprintf(logFile, "%s\n", message);
        fflush(logFile); // Ensure the message is written immediately
    }
}

// Background thread for periodic saving to disk
void* saveSessionsToDisk(void* arg) {
    while (1) {
        sleep(60); // Save every minute

        pthread_mutex_lock(&sessionLock);

        FILE* file = fopen("sessions_backup.dat", "wb");
        if (file) {
            fwrite(sessionArray, sizeof(UserSession*), sessionArraySize, file);
            fclose(file);
        }

        pthread_mutex_unlock(&sessionLock);
    }
    return NULL;
}

int main() {
    // Initialize memory pools
    initMemoryPool(&sessionPool, sizeof(UserSession), 100); 
    initMemoryPool(&logPool, sizeof(RequestLog), 500);

    // Setup background disk save thread
    pthread_t saverThread;
    pthread_create(&saverThread, NULL, saveSessionsToDisk, NULL);

    // Initialize session management with an initial array size of 10
    initSessions(10);

    // Example usage
    addSession(rand() % 1000);
    logActivity(rand() % 1000, "User logged in");

    externalLog("Test logging activity");

    return 0;
}
