#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_SIZE 10
#define KEY_RANGE_START 0
#define KEY_RANGE_END 100
#define SLAB_SIZE 50

typedef struct {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    long* offset;
    int* key;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} SlabAllocator;

// Hash function for unique keys
int hash(int x) {
    return (x * 2654435761) % KEY_RANGE_END;
}

// Initialize slab allocator
void init_allocator(SlabAllocator* allocator, size_t initial_size) {
    pthread_mutex_init(&allocator->mutex, NULL);
    allocator->count = 0;
    allocator->capacity = initial_size;
    allocator->offset = malloc(sizeof(long) * initial_size);
    allocator->key = malloc(sizeof(int) * initial_size);
}

// Resize arrays in slab allocator
void resize_allocator(SlabAllocator* allocator) {
    pthread_mutex_lock(&allocator->mutex);

    size_t new_capacity = allocator->capacity * 2;
    long* new_offset = realloc(allocator->offset, sizeof(long) * new_capacity);
    int* new_key = realloc(allocator->key, sizeof(int) * new_capacity);

    if (new_offset && new_key) {
        allocator->offset = new_offset;
        allocator->key = new_key;
        allocator->capacity = new_capacity;
    }

    pthread_mutex_unlock(&allocator->mutex);
}

// Add a key to the slab allocator
int add_key(SlabAllocator* allocator, int key) {
    pthread_mutex_lock(&allocator->mutex);

    if (allocator->count == allocator->capacity) {
        resize_allocator(allocator);
    }

    for (size_t i = 0; i < allocator->count; ++i) {
        if (allocator->key[i] == key) return -1;
    }

    allocator->key[allocator->count] = key;

    long cumulative_sum = (allocator->count > 0)
                          ? allocator->offset[allocator->count - 1]
                          : 0;

    allocator->offset[allocator->count] = cumulative_sum + key + 100; // Constant offset
    allocator->count++;

    pthread_mutex_unlock(&allocator->mutex);
    return 0;
}

// Linked list for records with concurrency safety
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} RecordList;

void init_record_list(RecordList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(const Record* record) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = *record;
    node->next = NULL;
    return node;
}

void add_record(RecordList* list, const Record* record) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = create_node(record);
    if (!new_node) return;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

// Random number generation
uint32_t xorshift32() {
    static uint32_t x = 123456789, y = 362436069, z = 521288629, w = 88675123;
    uint32_t t;
    t = x ^ (x << 11);
    x = y; y = z; z = w;
    return (w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
}

// Iterator for linked list
typedef struct {
    Node* current;
} RecordListIterator;

void init_iterator(RecordListIterator* iterator, RecordList* list) {
    pthread_mutex_lock(&list->mutex);
    iterator->current = list->head;
    pthread_mutex_unlock(&list->mutex);
}

int has_next(RecordListIterator* iterator) {
    return iterator->current != NULL;
}

const Record* next(RecordListIterator* iterator) {
    if (!has_next(iterator)) return NULL;

    const Record* data = &iterator->current->data;
    iterator->current = iterator->current->next;
    return data;
}

// Logging mechanism
typedef struct LogEntry {
    char operation[10];
    Record record;
    struct LogEntry* next;
} LogEntry;

void log_operation(LogEntry** log_head, const char* operation, const Record* record) {
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (!entry) return;

    strncpy(entry->operation, operation, sizeof(entry->operation));
    entry->record = *record;
    entry->next = *log_head;
    *log_head = entry;
}

void print_log(LogEntry* log_head) {
    while (log_head) {
        printf("Operation: %s, Record: {%.2f, %d, %.2f}\n",
               log_head->operation,
               log_head->record.f, log_head->record.i, (float)log_head->record.s);
        log_head = log_head->next;
    }
}

// Main function to initialize and use the components
int main() {
    SlabAllocator allocator;
    RecordList list;
    LogEntry* log_head = NULL;

    init_allocator(&allocator, INITIAL_SIZE);
    init_record_list(&list);

    for (int i = 0; i < SLAB_SIZE; ++i) {
        int key = hash(rand() % (KEY_RANGE_END - KEY_RANGE_START + 1)) + KEY_RANGE_START;
        if (add_key(&allocator, key) == 0) {
            Record record = { .s = xorshift32() & 0xFFFF,
                              .i = rand() % 1000,
                              .f = ((float)xorshift32()) / RAND_MAX };

            add_record(&list, &record);
            log_operation(&log_head, "INSERT", &record);
        }
    }

    RecordListIterator iterator;
    init_iterator(&iterator, &list);

    while (has_next(&iterator)) {
        const Record* rec = next(&iterator);
        printf("Record: {%.2f, %d, %.2f}\n",
               rec->f, rec->i, (float)rec->s);
    }

    print_log(log_head);

    // Clean-up would go here

    return 0;
}
