#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_BUFFER_SIZE 10000
#define MAX_PACKETS_PER_SECOND 10000
#define THROUGHPUT_THRESHOLD 0.8

typedef struct {
    time_t timestamp;
    size_t packet_size;
    char source_ip[16]; // Assuming IPv4, adjust for IPv6 if needed
} Packet;

typedef struct Node {
    Packet data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    int num_buckets;
    int size;
} HashTable;

unsigned int hash_function(const char *source_ip) {
    unsigned int hash = 0;
    while (*source_ip)
        hash = (hash << 5) + *source_ip++;
    return hash;
}

HashTable* create_hash_table(int num_buckets) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(num_buckets, sizeof(Node*));
    table->num_buckets = num_buckets;
    table->size = 0;
    return table;
}

void resize_hash_table(HashTable *table, int new_num_buckets) {
    Node** old_buckets = table->buckets;
    int old_num_buckets = table->num_buckets;

    table->buckets = calloc(new_num_buckets, sizeof(Node*));
    table->num_buckets = new_num_buckets;
    table->size = 0;

    for (int i = 0; i < old_num_buckets; ++i) {
        Node *node = old_buckets[i];
        while (node) {
            Node *next_node = node->next;
            unsigned int index = hash_function(node->data.source_ip) % table->num_buckets;
            node->next = table->buckets[index];
            table->buckets[index] = node;
            table->size++;
            node = next_node;
        }
    }

    free(old_buckets);
}

void add_packet(HashTable *table, Packet packet) {
    unsigned int index = hash_function(packet.source_ip) % table->num_buckets;
    Node* new_node = malloc(sizeof(Node));
    new_node->data = packet;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->size++;

    if ((float)table->size / (table->num_buckets * 0.7) > THROUGHPUT_THRESHOLD) {
        resize_hash_table(table, table->num_buckets * 2);
    }
}

void remove_outdated_packets(HashTable *table, time_t current_time, int age_threshold_seconds) {
    for (int i = 0; i < table->num_buckets; ++i) {
        Node **ptr = &table->buckets[i];
        while (*ptr) {
            if (current_time - (*ptr)->data.timestamp > age_threshold_seconds) {
                Node *old_node = *ptr;
                *ptr = old_node->next;
                free(old_node);
                table->size--;
            } else {
                ptr = &(*ptr)->next;
            }
        }
    }
}

void update_packet_sizes(HashTable *table, size_t new_size) {
    for (int i = 0; i < table->num_buckets; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            node->data.packet_size = new_size;
            node = node->next;
        }
    }
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->num_buckets; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(table->buckets);
    free(table);
}

void fetch_real_time_metrics() {
    // Placeholder function for integrating with an external data source
    // This would be implemented based on the specifics of the data source API.
}

int main() {
    HashTable *packet_table = create_hash_table(INITIAL_BUFFER_SIZE);

    Packet example_packet;
    time(&example_packet.timestamp);
    example_packet.packet_size = 512;
    strcpy(example_packet.source_ip, "192.168.1.1");

    add_packet(packet_table, example_packet);

    time_t current_time;
    time(&current_time);
    remove_outdated_packets(packet_table, current_time, 60); // Remove packets older than 60 seconds

    update_packet_sizes(packet_table, 1024); // Example of updating packet sizes based on congestion

    free_hash_table(packet_table);

