#define MAX_RECORDS 10000000
#define HASH_TABLE_SIZE 1048576 // Closest power of two for efficient hashing

typedef struct {
    long timestamp;
    float value;
    char identifier[256];
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t count;
    pthread_rwlock_t lock;
} HashTable;

// Function prototypes
HashTable* create_hash_table();
void insert_record(HashTable* table, Record* record);
Record* find_record_by_id(HashTable* table, const char* id);
void iterate_and_update(HashTable* table, float (*calc_func)(float));
void compact_data_structure(HashTable* table);
void free_hash_table(HashTable* table);

// Hash function
unsigned long hash_function(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % HASH_TABLE_SIZE;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Node**)calloc(HASH_TABLE_SIZE, sizeof(Node*));
    table->count = 0;
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable* table, Record* record) {
    unsigned long index = hash_function(record->identifier);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record = *record;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_rwlock_wrlock(&table->lock);
    table->count++;
    pthread_rwlock_unlock(&table->lock);
}

Record* find_record_by_id(HashTable* table, const char* id) {
    unsigned long index = hash_function(id);
    Node* node = table->buckets[index];
    while (node != NULL) {
        if (strcmp(node->record.identifier, id) == 0)
            return &node->record;
        node = node->next;
    }
    return NULL;
}

void iterate_and_update(HashTable* table, float (*calc_func)(float)) {
    pthread_rwlock_rdlock(&table->lock);
    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            node->record.value = calc_func(node->record.value);
            node = node->next;
        }
    }
    pthread_rwlock_unlock(&table->lock);
}

void compact_data_structure(HashTable* table) {
