    float kpi_f;
    time_t creation_time;
    time_t last_accessed;
} Record;

typedef struct BSTNode {
    Record data;
    struct BSTNode *left, *right;
    pthread_mutex_t lock;
} BSTNode;

typedef struct MemoryPool {
    void *pool;
    size_t pool_size;
    size_t block_size;
    unsigned char *next_free;
} MemoryPool;

typedef struct Cache {
    Record records[CACHE_SIZE];
    int access_count[CACHE_SIZE];
    pthread_rwlock_t rwlock;
} Cache;

MemoryPool memory_pool = {NULL, 0, POOL_SIZE, NULL};
Cache cache = {{}, {}, PTHREAD_RWLOCK_INITIALIZER};

BSTNode* create_node(Record data) {
    BSTNode *node = (BSTNode *)memory_pool.next_free;
    memory_pool.next_free += sizeof(BSTNode);
    if (memory_pool.next_free >= (unsigned char *)(memory_pool.pool + memory_pool.pool_size)) {
        resize_memory_pool();
    }
    node->data = data;
    node->left = node->right = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void initialize_memory_pool(size_t size) {
    memory_pool.pool = malloc(size);
    memory_pool.pool_size = size;
    memory_pool.block_size = POOL_SIZE;
    memory_pool.next_free = (unsigned char *)memory_pool.pool;
}

void resize_memory_pool() {
    size_t new_size = memory_pool.pool_size * 2;
    void *new_pool = realloc(memory_pool.pool, new_size);
    if (new_pool) {
        memory_pool.pool = new_pool;
        memory_pool.pool_size = new_size;
        memory_pool.next_free = (unsigned char *)memory_pool.pool + 
            ((unsigned char *)memory_pool.next_free - (unsigned char *)memory_pool.pool);
    } else {
        fprintf(stderr, "Memory pool resize failed\n");
        exit(EXIT_FAILURE);
    }
}

BSTNode* insert_node(BSTNode *root, Record data) {
    if (!root) return create_node(data);

    pthread_mutex_lock(&root->lock);
    if (data.key_i < root->data.key_i) {
        BSTNode *left = insert_node(root->left, data);
        root->left = left;
    } else if (data.key_i > root->data.key_i) {
        BSTNode *right = insert_node(root->right, data);
        root->right = right;
    }
    pthread_mutex_unlock(&root->lock);

    return balance_tree(root);
}

BSTNode* balance_tree(BSTNode *node) {
    // Implement AVL or Red-Black Tree balancing logic here
    return node;  // Placeholder for balanced tree
}

void log_change(const char *message) {
    // Integrate with external logging library
