}

BSTNode* iterate_bst(BSTNode *root, void (*process)(Record)) {
    if (!root) return NULL;

    BSTNode *left = iterate_bst(root->left, process);
    pthread_mutex_lock(&root->lock);
    process(root->data);
    root->data.last_accessed = time(NULL);
    pthread_mutex_unlock(&root->lock);
    BSTNode *right = iterate_bst(root->right, process);

    return NULL;  // Just for structure
}

void cache_record(Record record) {
    pthread_rwlock_wrlock(&cache.rwlock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.access_count[i] == 0) {
            cache.records[i] = record;
            cache.access_count[i] = 1;
            break;
        }
    }
    pthread_rwlock_unlock(&cache.rwlock);
}

Record* get_cached_record(int key_i) {
    pthread_rwlock_rdlock(&cache.rwlock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.access_count[i] && cache.records[i].key_i == key_i) {
            cache.access_count[i]++;
            pthread_rwlock_unlock(&cache.rwlock);
            return &cache.records[i];
        }
    }
    pthread_rwlock_unlock(&cache.rwlock);
    return NULL;
}

