typedef struct HashTableEntry {
    char* key;
    Record* value;
    struct HashTableEntry* next;
} HashTableEntry;

// Global data structures and mutexes for thread safety
long *offsetArray;
int *keyArray;
Record *recordListHead;
char **tagArray;
HashTableEntry **hashTable;
size_t hashTableSize = 1024; // Initial size of the hash table

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t hashMutex = PTHREAD_MUTEX_INITIALIZER;

// Hash function for string tags
unsigned long hashString(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % hashTableSize;
}

// Memory pool structure for efficient allocation and deallocation
typedef struct {
    void* start;
    size_t blockSize;
    size_t blockCount;
    size_t usedCount;
} MemoryPool;

MemoryPool memPool;

// Function to initialize memory pool
void initMemoryPool(size_t blockSize, size_t blockCount) {
    memPool.start = malloc(blockSize * blockCount);
    memPool.blockSize = blockSize;
    memPool.blockCount = blockCount;
    memPool.usedCount = 0;

    if (!memPool.start) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
}

// Function to allocate from memory pool
void* allocateFromPool(size_t size) {
    if (size > memPool.blockSize || memPool.usedCount >= memPool.blockCount)
        return NULL;

    void* block = ((char*)memPool.start) + (memPool.usedCount * memPool.blockSize);
    memPool.usedCount++;
    return block;
}

// Function to free memory pool
void freeMemoryPool() {
    free(memPool.start);
}

// Initialize data structures with proper memory management and thread safety
void initializeDataStructures(size_t offsetArraySize, size_t keyArraySize) {
    // Initialize memory pool for record allocation
    initMemoryPool(sizeof(Record), 1000);

    // Allocate arrays dynamically
    offsetArray = (long*)allocateFromPool(offsetArraySize * sizeof(long));
    keyArray = (int*)allocateFromPool(keyArraySize * sizeof(int));
    tagArray = (char**)allocateFromPool(keyArraySize * sizeof(char*));

    if (!offsetArray || !keyArray || !tagArray) {
        fprintf(stderr, "Memory allocation failed\n");
        freeMemoryPool();
        exit(EXIT_FAILURE);
    }

    // Initialize keys and calculate offsets
    int baseValue = 100; // Example constant value for offset calculation
    long cumulativeSum = 0;
    for (size_t i = 0; i < keyArraySize; ++i) {
        keyArray[i] = rand() % 10000 + 1; // Random unique integer within a specified range
        cumulativeSum += keyArray[i];
        offsetArray[i] = cumulativeSum + baseValue;
    }

    // Initialize hash table
    hashTable = (HashTableEntry**)allocateFromPool(hashTableSize * sizeof(HashTableEntry*));
    if (!hashTable) {
        fprintf(stderr, "Hash table allocation failed\n");
        freeMemoryPool();
        exit(EXIT_FAILURE);
    }
    memset(hashTable, 0, hashTableSize * sizeof(HashTableEntry*));

    // Populate records and linked list
    Record* currentRecord = NULL;
    for (size_t i = 0; i < keyArraySize; ++i) {
        // Allocate record from memory pool
        Record* newRecord = (Record*)allocateFromPool(sizeof(Record));
        if (!newRecord) {
            fprintf(stderr, "Failed to allocate record\n");
            freeMemoryPool();
            exit(EXIT_FAILURE);
        }

        // Initialize random values for short and int fields
        newRecord->sField = rand() % 32767;
        newRecord->iField = rand() % 2147483647;

        // Generate unique tag string
        char* tag = (char*)allocateFromPool(20 * sizeof(char)); // Example fixed size for tags
        snprintf(tag, 20, "Tag%d", i);
        newRecord->tag = tag;

        // Add to linked list and hash table
        pthread_mutex_lock(&listMutex);
        if (!recordListHead) {
            recordListHead = newRecord;
        } else {
            currentRecord->next = newRecord;
        }
        currentRecord = newRecord;
        pthread_mutex_unlock(&listMutex);

        pthread_mutex_lock(&hashMutex);
        unsigned long hashIndex = hashString(newRecord->tag);
        HashTableEntry* entry = (HashTableEntry*)allocateFromPool(sizeof(HashTableEntry));
        if (!entry) {
            fprintf(stderr, "Failed to allocate hash table entry\n");
            freeMemoryPool();
            exit(EXIT_FAILURE);
        }
        entry->key = newRecord->tag;
        entry->value = newRecord;
        entry->next = hashTable[hashIndex];
        hashTable[hashIndex] = entry;
        pthread_mutex_unlock(&hashMutex);

        // Store tag in array
        tagArray[i] = newRecord->tag;
    }

    // Seed random number generator
    srand((unsigned)time(NULL));
}

// Cleanup resources to prevent memory leaks
void cleanup() {
    Record* current = recordListHead;
    while (current) {
        Record* next = current->next;
        free(current->tag);
        free(current);
        current = next;
    }

    // Free hash table entries
    for (size_t i = 0; i < hashTableSize; ++i) {
        HashTableEntry* entry = hashTable[i];
        while (entry) {
            HashTableEntry* next = entry->next;
            free(entry);
            entry = next;
        }
    }

    freeMemoryPool();
}

int main() {
    initializeDataStructures(10, 5);

    // Simulate operations...

    cleanup();

    return 0;
}
