int initialize_records(record **records, size_t *count, size_t limit_kb, int offset_min, int offset_max, int key_min, int key_max) {
    const size_t overhead_per_record = sizeof(long) + sizeof(int);
    srand((unsigned int)time(NULL));

    *records = NULL;
    size_t total_memory_used = 0;
    size_t max_records = limit_kb * 1024 / (overhead_per_record + MAX_BUFFER_SIZE);

    for (size_t i = 0; i < max_records; ++i) {
        long offset = rand() % (offset_max - offset_min + 1) + offset_min;
        int key = rand() % (key_max - key_min + 1) + key_min;

        size_t buffer_size = (size_t)(offset + key);
        if (buffer_size > MAX_BUFFER_SIZE) {
            buffer_size = MAX_BUFFER_SIZE;
        }

        size_t record_overhead_and_buffer = overhead_per_record + buffer_size;
        if (total_memory_used + record_overhead_and_buffer > limit_kb * 1024) {
            break;
        }

        *records = realloc(*records, sizeof(record) * (i + 1));
        if (*records == NULL) {
            free_records(*records, i);
            return -1; // Allocation failure
        }

        (*records)[i].offset = offset;
        (*records)[i].key = key;
        (*records)[i].buffer = malloc(buffer_size);
        if ((*records)[i].buffer == NULL) {
            free_records(*records, i + 1);
            return -1; // Allocation failure
        }

        total_memory_used += record_overhead_and_buffer;
    }

    *count = i;
    qsort(*records, *count, sizeof(record), compare_keys);

    return 0; // Success
}

record* find_record_by_key(record *records, size_t count, int key) {
    for (size_t i = 0; i < count; ++i) {
