#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long *offset;
    int *key;
} record;

// Mutex for thread safety in random key generation
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_unique_keys(int *keys, size_t count, int min_val, int max_val) {
    if (count > (max_val - min_val + 1)) return -1; // Not enough unique values available

    for (size_t i = 0; i < count; ++i) {
        int new_key;
        do {
            pthread_mutex_lock(&mutex);
            new_key = rand() % (max_val - min_val + 1) + min_val;
            pthread_mutex_unlock(&mutex);

            // Check uniqueness
            for (size_t j = 0; j < i; ++j) {
                if (keys[j] == new_key) goto retry;
            }
        } while (1);
    retry:;
    }

    return 0;
}

void initialize_components(size_t offset_count, size_t key_count, int min_key_val, int max_key_val) {
    if (offset_count <= 0 || key_count <= 0) return;

    // Allocate memory for arrays
    long *offset_array = (long *)malloc(offset_count * sizeof(long));
    int *key_array = (int *)malloc(key_count * sizeof(int));
    record *record_array = (record *)malloc(key_count * sizeof(record));

    if (!offset_array || !key_array || !record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    // Initialize offset and key arrays
    memset(offset_array, 0, offset_count * sizeof(long));
    if (generate_unique_keys(key_array, key_count, min_key_val, max_key_val) != 0) {
        fprintf(stderr, "Failed to generate unique keys\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    // Initialize record structures
    for (size_t i = 0; i < key_count; ++i) {
        if (i < offset_count) {
            record_array[i].offset = &offset_array[i];
        } else {
            record_array[i].offset = NULL; // Handle case where key_count > offset_count
        }
        record_array[i].key = &key_array[i];
    }

    // Simulate some processing with records...
    for (size_t i = 0; i < key_count; ++i) {
        if (record_array[i].offset != NULL) {
            *record_array[i].offset = (long)i;
        }
        printf("Record %zu: Offset = %ld, Key = %d\n", i, record_array[i].offset ? *record_array[i].offset : -1, *record_array[i].key);
    }

    // Deallocate memory
    free(offset_array);
    free(key_array);
    free(record_array);
}

