#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_BUFFER_SIZE 256
#define PREFIX "Record_"
#define LOG_FILE "memory_log.txt"

typedef struct {
    long offset;
    int key;
    char *buffer;
} record;

typedef struct node {
    record rec;
    struct node* next;
} node_t;

node_t* head = NULL;
pthread_mutex_t lock;

void log_memory_usage(size_t used) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "Memory usage: %zu bytes\n", used);
        fclose(log);
    }
}

void free_records(node_t* node) {
    while (node != NULL) {
        node_t* temp = node;
        node = node->next;
        free(temp->rec.buffer);
        free(temp);
    }
}

void init_random() {
    srand(time(NULL));
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

long generate_random_long(long min, long max) {
    return ((rand() / (RAND_MAX + 1.0)) * (max - min + 1)) + min;
}

record* create_record(int key, long offset, size_t buffer_size) {
    record* rec = malloc(sizeof(record));
    if (!rec) {
        perror("Failed to allocate memory for record");
        return NULL;
    }

    rec->key = key;
    rec->offset = offset;
    rec->buffer = malloc(buffer_size);
    if (!rec->buffer) {
        perror("Failed to allocate memory for buffer");
        free(rec);
        return NULL;
    }

    snprintf(rec->buffer, buffer_size, "%s%d", PREFIX, key);
    rec->buffer[buffer_size - 1] = '\0';
    return rec;
}

void insert_record(record* rec) {
    pthread_mutex_lock(&lock);

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        free(rec);
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->rec = *rec;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

record* retrieve_record(int key) {
    pthread_mutex_lock(&lock);

    node_t* current = head;
    while (current != NULL) {
        if (current->rec.key == key) {
            record* rec_copy = malloc(sizeof(record));
            if (!rec_copy) {
                perror("Failed to allocate memory for record copy");
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            *rec_copy = current->rec;
            pthread_mutex_unlock(&lock);
            return rec_copy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void initialize_records(size_t max_kilobytes, int key_min, int key_max, long offset_min, long offset_max) {
    size_t total_kb = 0;
    size_t total_bytes = 0;

    init_random();
    pthread_mutex_init(&lock, NULL);

    while (total_kb < max_kilobytes) {
        int key = generate_random_int(key_min, key_max);
        long offset = generate_random_long(offset_min, offset_max);

        size_t buffer_size = (size_t)(key + offset);
        if (buffer_size > MAX_BUFFER_SIZE) {
            buffer_size = MAX_BUFFER_SIZE;
        }
        buffer_size += 1; // For null terminator

        record* rec = create_record(key, offset, buffer_size);
        if (!rec) {
            break;
        }

        total_bytes += sizeof(record) + buffer_size - 1; // Subtracting 1 for the null terminator
        insert_record(rec);

        total_kb = (total_bytes + 1023) / 1024;

        log_memory_usage(total_bytes);
    }
}

void cleanup() {
    free_records(head);
    pthread_mutex_destroy(&lock);
}

// Example usage and testing code
int main() {
    initialize_records(1, 0, 100, 0, 500);

    // Test retrieval
    record* rec = retrieve_record(50); 
    if (rec) {
        printf("Retrieved: Key=%d, Offset=%ld, Buffer=%s\n", rec->key, rec->offset, rec->buffer);
        free(rec->buffer);
        free(rec);
    } else {
        printf("Record not found.\n");
    }

    cleanup();
    return 0;
}
```

