['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char *buffer;
} record;

#define MAX_BUFFER_SIZE 1024
#define MEMORY_LIMIT_KB 1024 // Adjust as needed

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache structure
typedef struct {
    int key;
    record rec;
} cache_entry;

cache_entry *cache = NULL;
int cache_size = 0;
int max_cache_size = 10; // Adjust as needed

// Logging function
void log_event(const char *event) {
    printf("%s\n", event);
}

// Function to initialize a random number generator
void init_random() {
    srand(time(NULL));
}

// Function to generate a random record
record generate_record(int key_range, long offset_range) {
    record rec;
    rec.key = rand() % key_range + 1;
    rec.offset = (rand() % (int)(offset_range)) + 1;
    int buffer_size = rec.key + rec.offset;
    if (buffer_size > MAX_BUFFER_SIZE) {
        buffer_size = MAX_BUFFER_SIZE;
    }
    rec.buffer = malloc(buffer_size * sizeof(char));
    if (!rec.buffer) {
        log_event("Memory allocation failed for record buffer");
        exit(EXIT_FAILURE);
    }
    memset(rec.buffer, 'A', buffer_size); // Fill with dummy data
    return rec;
}

// Function to manage memory usage and create records
record* create_records(int num_records, int key_range, long offset_range) {
    pthread_mutex_lock(&mutex);

    size_t total_memory_kb = 0;
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        log_event("Memory allocation failed for records array");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        record rec = generate_record(key_range, offset_range);
        size_t buffer_kb = (strlen(rec.buffer) + 1) / 1024;
        total_memory_kb += buffer_kb;

        if (total_memory_kb > MEMORY_LIMIT_KB * 1024) {
            log_event("Memory limit exceeded");
            break; // Stop creating records if memory limit is reached
        }

        records[i] = rec;
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

// Function to retrieve a record by key with caching
record* get_record_by_key(record *records, int num_records, int key) {
    // Check cache first
    for (int i = 0; i < cache_size; ++i) {
        if (cache[i].key == key) {
            log_event("Cache hit");
            return &cache[i].rec;
        }
    }

    // If not in cache, search the records
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            log_event("Cache miss");

            // Add to cache
            if (cache_size < max_cache_size) {
                cache[cache_size++] = (cache_entry){key, records[i]};
            } else {
                // Simple replacement strategy: replace the first entry
                cache[0] = (cache_entry){key, records[i]};
            }

            pthread_mutex_unlock(&mutex);
            return &records[i];
        }
    }

    pthread_mutex_unlock(&mutex);
    log_event("Record not found");
    return NULL;
}

// Function to free allocated memory and perform garbage collection
void cleanup_records(record *records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].buffer) {
            free(records[i].buffer);
            log_event("Buffer freed");
        }
    }
    free(records);
    records = NULL;

    // Free cache
    for (int i = 0; i < cache_size; ++i) {
        free(cache[i].rec.buffer);
    }
    free(cache);
    cache = NULL;
}

// Example usage
int main() {
    init_random();
    int num_records = 100;
    record *records = create_records(num_records, 100, 1000);

    // Retrieve a record by key
    int search_key = 42; // Example key to search for
    record *found_record = get_record_by_key(records, num_records, search_key);
    if (found_record) {
        printf("Record found: Key=%d, Offset=%ld\n", found_record->key, found_record->offset);
    }

    cleanup_records(records, num_records);
    return 0;
}
