#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
    time_t timestamp;
    struct Record* prev;
    struct Record* next;
} Record;

typedef struct HashTableEntry {
    int key;
    Record* record;
    struct HashTableEntry* next;
} HashTableEntry;

#define INITIAL_SIZE 16
#define MEMORY_BUDGET 1024 * 1024 // 1MB for example

typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = malloc(size);
    mp->size = size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* allocate_from_pool(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + size > mp->size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void* ptr = ((char*)mp->pool) + mp->used;
    mp->used += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    free(mp);
}

// Doubly linked list management
typedef struct LinkedList {
    Record* head;
    Record* tail;
    pthread_rwlock_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* ll = (LinkedList*)malloc(sizeof(LinkedList));
    ll->head = NULL;
    ll->tail = NULL;
    pthread_rwlock_init(&ll->lock, NULL);
    return ll;
}

void add_record_to_list(LinkedList* ll, Record* record) {
    pthread_rwlock_wrlock(&ll->lock);
    if (ll->tail) {
        ll->tail->next = record;
        record->prev = ll->tail;
        ll->tail = record;
    } else {
        ll->head = ll->tail = record;
        record->next = NULL;
        record->prev = NULL;
    }
    pthread_rwlock_unlock(&ll->lock);
}

// Hash table management
typedef struct HashTable {
    HashTableEntry** table;
    size_t capacity;
    pthread_rwlock_t lock;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (key * 2654435761UL) % capacity;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->table = (HashTableEntry**)calloc(capacity, sizeof(HashTableEntry*));
    pthread_rwlock_init(&ht->lock, NULL);
    return ht;
}

void hash_table_insert(HashTable* ht, int key, Record* record) {
    unsigned long index = hash_function(key, ht->capacity);
    HashTableEntry* entry = (HashTableEntry*)allocate_from_pool(memory_pool, sizeof(HashTableEntry));
    if (!entry) return; // Out of memory
    entry->key = key;
    entry->record = record;

    pthread_rwlock_wrlock(&ht->lock);
    entry->next = ht->table[index];
    ht->table[index] = entry;
    pthread_rwlock_unlock(&ht->lock);
}

Record* hash_table_lookup(HashTable* ht, int key) {
    unsigned long index = hash_function(key, ht->capacity);

    pthread_rwlock_rdlock(&ht->lock);
    HashTableEntry* entry = ht->table[index];
    while (entry) {
        if (entry->key == key) {
            pthread_rwlock_unlock(&ht->lock);
            return entry->record;
        }
        entry = entry->next;
    }
    pthread_rwlock_unlock(&ht->lock);
    return NULL;
}

void initialize_data_structures(MemoryPool* mp, long** offsets, int** keys, LinkedList** list, time_t** timestamps, HashTable** hash_table) {
    *list = create_linked_list();
    *hash_table = create_hash_table(INITIAL_SIZE);

    size_t array_size = 5;
    *offsets = (long*)allocate_from_pool(mp, array_size * sizeof(long));
    *keys = (int*)allocate_from_pool(mp, array_size * sizeof(int));
    *timestamps = (time_t*)allocate_from_pool(mp, array_size * sizeof(time_t));

    if (!*offsets || !*keys || !*timestamps) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand((unsigned int)time(NULL));
    long offset_sum = 0;
    for (size_t i = 0; i < array_size; ++i) {
        (*keys)[i] = rand() % 100 + 1; // Unique keys in range [1, 100]
        offset_sum += (*keys)[i];
        (*offsets)[i] = offset_sum + (rand() % 50); // Random constant added
    }

    for (size_t i = 0; i < array_size; ++i) {
        Record* record = (Record*)allocate_from_pool(mp, sizeof(Record));
        if (!record) continue;

        record->s = rand() % 100;
        record->i = rand() % 1000;
        record->f = (float)(rand() % 100.0);
        record->timestamp = (*timestamps)[i] = time(NULL);

        add_record_to_list(*list, record);
        hash_table_insert(*hash_table, (*keys)[i], record);
    }
}

void free_data_structures(MemoryPool* mp, long* offsets, int* keys, LinkedList* list, time_t* timestamps, HashTable* hash_table) {
    // Free linked list
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&list->lock);

    // Free hash table
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        HashTableEntry* entry = hash_table->table[i];
        while (entry) {
            HashTableEntry* next = entry->next;
            free(entry);
            entry = next;
        }
    }
    pthread_rwlock_destroy(&hash_table->lock);
    free(hash_table->table);
    free(hash_table);

    // Free memory pool
    free_memory_pool(mp);
}

int main() {
    MemoryPool* mp = create_memory_pool(MEMORY_BUDGET);

    long* offsets = NULL;
    int* keys = NULL;
    LinkedList* list = NULL;
    time_t* timestamps = NULL;
    HashTable* hash_table = NULL;

    initialize_data_structures(mp, &offsets, &keys, &list, &timestamps, &hash_table);

    // Example usage
    Record* record = hash_table_lookup(hash_table, keys[2]);
    if (record) {
        printf("Record found: %d\n", record->i);
    }

    free_data_structures(mp, offsets, keys, list, timestamps, hash_table);
    return 0;
}
