        printf("Record %d: Key=%d, Offset=%ld, Data=%.2f\n", i, records[i].key, records[i].offset, records[i].data);
    }

    destroy_memory_pool(mp);
    free(records);
    return EXIT_SUCCESS;
}

// Implementations
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->pool_size = num_blocks * block_size;
    mp->pool = malloc(mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->free_list = (unsigned char*)malloc(mp->pool_size);
    if (!mp->free_list) {
        free(mp->pool);
        free(mp);
        return NULL;
    }

    for (size_t i = 0; i < mp->pool_size; ++i) {
        mp->free_list[i] = 1;
    }

    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->free_list);
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    for (size_t i = 0; i < mp->pool_size; ++i) {
        if (mp->free_list[i]) {
            mp->free_list[i] = 0;
            pthread_mutex_unlock(&mp->lock);
            return (void*)((unsigned char*)mp->pool + i * mp->block_size);
        }
    }

    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

Record* initialize_records(int array_size, double mean_offset, double stddev_offset, int key_min, int key_max) {
    Record* records = (Record*)malloc(array_size * sizeof(Record));
    if (!records) return NULL;

    int sum_keys = 0;
    for (int i = 0; i < array_size; ++i) {
        records[i].key = rand() % (key_max - key_min + 1) + key_min;
        while ((i > 0 && records[i].key == records[i-1].key)) {
            records[i].key = rand() % (key_max - key_min + 1) + key_min;
        }
        sum_keys += records[i].key;

        double random_offset = random_normal(mean_offset, stddev_offset);
        records[i].offset = i > 0 ? sum_keys + lround(random_offset) : lround(random_offset);

        records[i].data = (double)rand() / RAND_MAX * 100.0; // Random data between 0 and 100

        // Initialize other fields as needed
    }

    return records;
}

double random_normal(double mean, double stddev) {
    static double n2 = 0.0;
    static int n2_cached = 0;

    if (n2_cached == 0) {
        double u1 = ((double)rand() / RAND_MAX);
        double u2 = ((double)rand() / RAND_MAX);

        double z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        n2 = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);
        n2_cached = 1;

        return mean + z0 * stddev;
    } else {
        n2_cached = 0;
        return mean + n2 * stddev;
    }
}
```

