// Define maximum length for filenames and hash size
#define MAX_FILENAME_LENGTH 255
#define HASH_SIZE 32

typedef struct {
    int disjoint_pairs_count;
    char modified_filename[MAX_FILENAME_LENGTH];
} ProcessResult;

typedef union {
    struct { 
        unsigned int parent; 
        unsigned int rank; 
    };
    unsigned int data;
} UnionFindNode;

UnionFindNode* uf_create_set(size_t size) {
    UnionFindNode *uf = malloc(sizeof(UnionFindNode) * size);
    for (size_t i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

unsigned int uf_find(UnionFindNode *uf, unsigned int x) {
    if (uf[x].parent != x)
        uf[x].parent = uf_find(uf, uf[x].parent);
    return uf[x].parent;
}

void uf_union(UnionFindNode *uf, unsigned int x, unsigned int y) {
    unsigned int rootX = uf_find(uf, x);
    unsigned int rootY = uf_find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

int is_disjoint(UnionFindNode *uf, unsigned int x, unsigned int y) {
    return uf_find(uf, x) != uf_find(uf, y);
}

void make_disjoint(UnionFindNode *uf, unsigned int x, unsigned int y) {
    uf_union(uf, x, y);
}

char* modify_filename(const char* filename, int count) {
    char *modified = malloc(MAX_FILENAME_LENGTH);
    strncpy(modified, filename, MAX_FILENAME_LENGTH - 10);

    // Append extension with count
    char ext[10];
    snprintf(ext, sizeof(ext), "-%d", count);
    strcat(modified, ext);

    // Ensure URL-safe (replace special characters)
    for (char *p = modified; *p != '\0'; ++p) {
        if (!isalnum(*p)) {
            *p = '_';
        }
    }

    return modified;
}

void hash_filename(const char* filename, char* hash_output) {
    // Simple hash function for demonstration
    uint32_t hash = 5381;
    int c;

    while ((c = *filename++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    snprintf(hash_output, HASH_SIZE, "%08x", hash);
}

int process_and_modify(const char* filename, ProcessResult* result) {
    clock_t start_time = clock();

    // Truncate filename if too long
    size_t len = strlen(filename);
    if (len > MAX_FILENAME_LENGTH - 10) {
        len = MAX_FILENAME_LENGTH - 10;
    }
    char truncated_filename[MAX_FILENAME_LENGTH];
    strncpy(truncated_filename, filename, len);
    truncated_filename[len] = '\0';

    // Initialize Union-Find structure
    size_t unique_chars = strlen(unique(truncated_filename));
    UnionFindNode *uf = uf_create_set(unique_chars);

    int count = 0;

    for (size_t i = 0; i < len - 1; ++i) {
        if (!is_disjoint(uf, truncated_filename[i], truncated_filename[i + 1])) {
            make_disjoint(uf, truncated_filename[i], truncated_filename[i + 1]);
        } else {
            count++;
        }
    }

    free(uf);

    // Modify filename
    result->modified_filename = modify_filename(truncated_filename, count);

    // Hash the modified filename for integrity check
    char hash_output[HASH_SIZE];
    hash_filename(result->modified_filename, hash_output);
    printf("Filename Hash: %s\n", hash_output);

    clock_t end_time = clock();
    double processing_time = ((double) (end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Processing time: %.2f seconds\n", processing_time);

    result->disjoint_pairs_count = count;

    return 0; // Success
}

// Define a structure for caching results
typedef struct CacheEntry {
    char filename[MAX_FILENAME_LENGTH];
    ProcessResult result;
    struct CacheEntry* next;
} CacheEntry;

CacheEntry *cache_head = NULL;

ProcessResult get_cached_result(const char *filename) {
    ProcessResult empty_result = {0, ""};
    CacheEntry *current = cache_head;

    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            return current->result;
        }
        current = current->next;
    }

    return empty_result; // Not found
}

void add_to_cache(const char *filename, ProcessResult result) {
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    strncpy(new_entry->filename, filename, MAX_FILENAME_LENGTH);
    new_entry->result = result;

    new_entry->next = cache_head;
    cache_head = new_entry;
}

// Function to process multiple filenames using threads
void* threaded_processing(void* arg) {
    const char *filename = (const char*)arg;
    ProcessResult result;

    if (strcmp(get_cached_result(filename).modified_filename, "") == 0) {
        // Cache miss; need to process the filename
        process_and_modify(filename, &result);
        add_to_cache(filename, result);
    } else {
        // Cache hit; get from cache
        result = get_cached_result(filename);
    }

    printf("Processed: %s\n", result.modified_filename);

    return NULL;
}

void process_multiple_filenames(char** filenames, int num_files) {
    pthread_t threads[num_files];

    for (int i = 0; i < num_files; ++i) {
        pthread_create(&threads[i], NULL, threaded_processing, (void*)filenames[i]);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    char *file_list[] = {"example1.txt", "test2.log", "sample3.dat"};
    int num_files = sizeof(file_list) / sizeof(file_list[0]);

    process_multiple_filenames(file_list, num_files);

    return 0;
}
```

