#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double value;
    char metadata[256];
} data_point;

typedef struct {
    double* doubles;
    unsigned long* timestamps;
    data_point* data_points;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;

    // Operation counters
    size_t insertions;
    size_t deletions;
    size_t reads;
} DataManager;

static void log_operation(DataManager* manager, const char* operation) {
    pthread_mutex_lock(&manager->mutex);
    if (strcmp(operation, "insert") == 0) {
        manager->insertions++;
    } else if (strcmp(operation, "delete") == 0) {
        manager->deletions++;
    } else if (strcmp(operation, "read") == 0) {
        manager->reads++;
    }
    pthread_mutex_unlock(&manager->mutex);
}

static int resize_array(DataManager* manager, size_t new_capacity) {
    double* new_doubles = realloc(manager->doubles, new_capacity * sizeof(double));
    unsigned long* new_timestamps = realloc(manager->timestamps, new_capacity * sizeof(unsigned long));
    data_point* new_data_points = realloc(manager->data_points, new_capacity * sizeof(data_point));

    if (!new_doubles || !new_timestamps || !new_data_points) {
        free(new_doubles);
        free(new_timestamps);
        free(new_data_points);
        return -1;
    }

    manager->doubles = new_doubles;
    manager->timestamps = new_timestamps;
    manager->data_points = new_data_points;
    manager->capacity = new_capacity;

    return 0;
}

int add_data_point(DataManager* manager, double value, const char* metadata, unsigned long timestamp) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2 + 1;
        int resize_result = resize_array(manager, new_capacity);
        if (resize_result != 0) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failure
        }
    }

    manager->doubles[manager->count] = value;
    strncpy(manager->data_points[manager->count].metadata, metadata, sizeof(manager->data_points[manager->count].metadata));
    manager->data_points[manager->count].value = value;
    manager->timestamps[manager->count] = timestamp;

    log_operation(manager, "insert");

    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

double* get_doubles(DataManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    double* result = malloc(manager->count * sizeof(double));
    if (result != NULL) {
        for (size_t i = 0; i < manager->count; ++i) {
            result[i] = manager->doubles[i];
        }
        log_operation(manager, "read");
    }
    pthread_mutex_unlock(&manager->mutex);
    return result;
}

void clear_data(DataManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    free(manager->doubles);
    free(manager->timestamps);
    free(manager->data_points);

    manager->doubles = NULL;
    manager->timestamps = NULL;
    manager->data_points = NULL;
    manager->capacity = 0;
    manager->count = 0;

    log_operation(manager, "delete");

    pthread_mutex_unlock(&manager->mutex);
}

DataManager* create_data_manager(size_t initial_capacity) {
    DataManager* manager = malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->doubles = malloc(initial_capacity * sizeof(double));
    manager->timestamps = malloc(initial_capacity * sizeof(unsigned long));
    manager->data_points = malloc(initial_capacity * sizeof(data_point));

    if (!manager->doubles || !manager->timestamps || !manager->data_points) {
        free(manager->doubles);
        free(manager->timestamps);
        free(manager->data_points);
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->mutex, NULL);

    manager->insertions = 0;
    manager->deletions = 0;
    manager->reads = 0;

    return manager;
}

void free_data_manager(DataManager* manager) {
    clear_data(manager);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
```

### Key Features Implemented:
1. **Dynamic Resizing**: Arrays resize when capacity is reached, doubling the size plus one to minimize reallocations.
2. **Thread Safety**: Mutex locks ensure thread-safe read and write operations.
3. **Logging**: Operation counters for insertions, deletions, and reads are updated within a locked section.
4. **Memory Management**: All allocated memory is freed properly with `clear_data` and during manager deallocation to prevent leaks.
5. **Modularity**: The design allows easy extension, such as adding more fields or handling external data sources, by modifying the `data_point` structure and associated functions.

This solution balances performance and safety for a multi-threaded environment while maintaining efficient memory usage and operations tracking.']

