typedef struct {
    float temperature;
    int sensor_id;
    char timestamp[20]; // Assuming ISO 8601 format: "YYYY-MM-DDTHH:MM:SS"
} sensor_reading;

typedef struct {
    sensor_reading *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} readings_array;

int initialize_readings_array(readings_array *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->data = (sensor_reading *)aligned_alloc(16, sizeof(sensor_reading) * arr->capacity);
    if (!arr->data) return -1; // Allocation failed
    pthread_mutex_init(&arr->lock, NULL);
    return 0;
}

int add_reading(readings_array *arr, sensor_reading reading) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        sensor_reading *new_data = (sensor_reading *)aligned_alloc(16, sizeof(sensor_reading) * new_capacity);
        if (!new_data) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Allocation failed
        }
        memcpy(new_data, arr->data, sizeof(sensor_reading) * arr->count);
        free(arr->data);
        arr->data = new_data;
        arr->capacity = new_capacity;
    }

    arr->data[arr->count++] = reading;

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

int archive_readings(readings_array *arr, const char *archive_path) {
    FILE *file = fopen(archive_path, "a");
    if (!file) return -1; // File open failed

    for (size_t i = 0; i < arr->count; ++i) {
        fprintf(file, "%d,%f,%s\n", arr->data[i].sensor_id, arr->data[i].temperature, arr->data[i].timestamp);
    }

    fclose(file);
    return 0; // Success
}

void free_readings_array(readings_array *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->data);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

int main() {
    readings_array arr;
    if (initialize_readings_array(&arr, 10) != 0) {
        fprintf(stderr, "Failed to initialize readings array\n");
        return EXIT_FAILURE;
    }

    // Example usage
