    if (add_reading(&arr, reading) != 0) {
        fprintf(stderr, "Failed to add reading\n");
    }

    if (archive_readings(&arr, "archive.txt") != 0) {
        fprintf(stderr, "Failed to archive readings\n");
    }

    free_readings_array(&arr);
    return EXIT_SUCCESS;
}
