        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        // More CURL options as needed...

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            spdlog::error("curl_easy_perform() failed: {}", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

// Periodic Memory Compaction (simplified)
void compactMemoryPeriodically(MemoryPool& pool) {
    while (true) {
        std::this_thread::sleep_for(std::chrono::minutes(1)); // Example interval
        // Perform compaction logic here...
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <API_URL>" << std::endl;
        return EXIT_FAILURE;
    }

    spdlog::set_level(spdlog::level::info); // Set global log level
    auto logger = spdlog::stdout_color_mt("console");

    try {
        MemoryPool pool(sizeof(ConfigRecord), 1024);

        std::thread compactionThread(compactMemoryPeriodically, std::ref(pool));
