// Configuration parameters
#define DEFAULT_ITERATIONS 10000
#define KEY_SIZE 32
#define NONCE_SIZE 12

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char nonce[NONCE_SIZE];
} EncryptionContext;

typedef struct ResourceManager {
    pthread_mutex_t lock;
    int active_count;
    // Add more resource management fields as needed
} ResourceManager;

ResourceManager resource_manager = { .lock = PTHREAD_MUTEX_INITIALIZER, .active_count = 0 };

// Key derivation function using a simple PBKDF2 or similar method
void derive_key(const char *passphrase, unsigned char *key, size_t key_len, int iterations) {
    // Implement the KDF here, e.g., PBKDF2 with HMAC-SHA256
    // Use OpenSSL's EVP_BytesToKey if available for simplicity
}

// Secure zeroization of memory
void secure_zero(void *ptr, size_t len) {
    volatile unsigned char *p = ptr;
    while (len--) *p++ = 0;
}

// Thread-safe encryption function
int encrypt_data(const char *passphrase, const unsigned char *plaintext, size_t plaintext_len,
                 unsigned char *ciphertext, size_t *ciphertext_len, int iterations) {

    pthread_mutex_lock(&resource_manager.lock);
    resource_manager.active_count++;
    pthread_mutex_unlock(&resource_manager.lock);

    EncryptionContext ctx;
    derive_key(passphrase, ctx.key, sizeof(ctx.key), iterations);
    generate_nonce(ctx.nonce);  // Implement nonce generation

    chacha20_poly1305_encrypt(plaintext, plaintext_len, ciphertext, &ciphertext_len,
                              ctx.key, ctx.nonce);

    secure_zero(ctx.key, sizeof(ctx.key));
    secure_zero(ctx.nonce, sizeof(ctx.nonce));

    pthread_mutex_lock(&resource_manager.lock);
    resource_manager.active_count--;
    pthread_mutex_unlock(&resource_manager.lock);

    return 0; // Return error codes as needed
}

// Resource manager functions for lifecycle management
void initialize_resource_manager() {
    pthread_mutex_init(&resource_manager.lock, NULL);
}

void cleanup_resource_manager() {
    while (resource_manager.active_count > 0) {
        // Wait or handle active requests gracefully
    }
    pthread_mutex_destroy(&resource_manager.lock);
}

// Metrics and monitoring functions (placeholder)
void log_metrics() {
    printf("Active encryption contexts: %d\n", resource_manager.active_count);
    // Add more detailed metrics logging as needed
}

int main() {
    initialize_resource_manager();

    const char *passphrase = "secure_passphrase";
    unsigned char plaintext[] = "This is a test message.";
    size_t plaintext_len = sizeof(plaintext) - 1;
    unsigned char ciphertext[256];
    size_t ciphertext_len;

    encrypt_data(passphrase, plaintext, plaintext_len, ciphertext, &ciphertext_len, DEFAULT_ITERATIONS);

    log_metrics();

    cleanup_resource_manager();
    return 0;
}
```

### Key Points:
- **Key Derivation**: Uses a KDF with configurable iterations.
- **Secure Memory Handling**: Zeroizes keys and nonces after use.
- **Thread Safety**: Mutexes protect shared resources.
- **Resource Management**: Tracks active encryption contexts.
- **Metrics Logging**: Simple logging of active context count.

### Dependencies:
- You need to implement or link against a ChaCha20-Poly1305 library, such as one provided by OpenSSL or another cryptographic library.
