    destination_ip: String,
    protocol_type: u8,
    packet_length: usize,
    timestamp: NaiveDateTime,
    checksum: u32,
}

#[derive(Debug)]
struct Packet {
    header: PacketHeader,
    payload: Vec<u8>,
    packet_id: u64,
}

type Cache = HashMap<String, Packet>;

struct PacketManager {
    packets: Arc<Mutex<LinkedList<Packet>>>,
    cache: Arc<Mutex<Cache>>,
    rng: StdRng,
}

impl PacketManager {
    fn new(seed: [u8; 32]) -> Self {
        let rng = StdRng::from_seed(seed);
        PacketManager {
            packets: Arc::new(Mutex::new(LinkedList::new())),
            cache: Arc::new(Mutex::new(HashMap::new())),
            rng,
        }
    }

    fn generate_packet(&self, source_ip: Option<String>, destination_ip: Option<String>) -> Packet {
        let packet_id = self.rng.next_u64();
        let timestamp = Utc::now().naive_utc();

        let source_ip = source_ip.unwrap_or_else(|| "0.0.0.0".to_string());
        let destination_ip = destination_ip.unwrap_or_else(|| "255.255.255.255".to_string());

        let header = PacketHeader {
            source_ip,
            destination_ip,
            protocol_type: 6, // Example: TCP
            packet_length: 0, // Placeholder
            timestamp,
            checksum: 0, // Initial checksum
        };

        let payload = vec![]; // Placeholder for actual payload data

        Packet { header, payload, packet_id }
    }

    fn update_checksum(&self, packet: &mut Packet) {
        let mut hasher = Sha256::new();
        hasher.update(&packet.payload);
        packet.header.checksum = hasher.finalize_u32();
    }

    fn add_packet(&self, source_ip: Option<String>, destination_ip: Option<String>) {
        let packet = self.generate_packet(source_ip, destination_ip);

        // Update checksum
        let mut packet = &mut packet;
        self.update_checksum(packet);

        let mut packets = self.packets.lock().unwrap();
        packets.push_back(packet.clone());

        // Cache the packet if needed (example: based on size)
        let cache_key = format!("{:x}", packet.packet_id);
        let mut cache = self.cache.lock().unwrap();
        cache.insert(cache_key, packet);
    }

    fn hash_metadata(&self, metadata: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(metadata.as_bytes());
        format!("{:x}", hasher.finalize())
    }
}

fn main() {
    let seed = [0u8; 32]; // Example seed for RNG
    let packet_manager = PacketManager::new(seed);

    packet_manager.add_packet(Some("192.168.1.1".to_string()), None);
    packet_manager.add_packet(None, Some("10.0.0.1".to_string()));

    external_logging::log("Packet manager initialized.");
}
