#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

record* resize_array(record* array, size_t current_size) {
    size_t new_size = current_size * GROWTH_FACTOR;
    record* new_array = realloc(array, new_size * sizeof(record));
    if (!new_array) {
        perror("Memory allocation failed");
        free(array);
        exit(EXIT_FAILURE);
    }
    return new_array;
}

void load_external_data(record* array, size_t size) {
    // Simulate loading data from an external source
    for (size_t i = 0; i < size; ++i) {
        array[i].offset = rand() % 10000L;
        array[i].key = rand() % 1000;
        array[i].value = (double)(rand() % 100);
    }
}

void manage_memory_array(size_t update_interval, size_t data_count) {
    record* array = malloc(INITIAL_SIZE * sizeof(record));
    if (!array) {
        perror("Initial memory allocation failed");
        exit(EXIT_FAILURE);
    }

    size_t current_size = INITIAL_SIZE;
    size_t count = 0;

    while (count < data_count) {
        if (current_size <= count) {
            array = resize_array(array, current_size);
            current_size *= GROWTH_FACTOR;
        }

        // Populate or update the array
        for (size_t i = 0; i < update_interval && (count + i) < data_count; ++i) {
            array[count + i].offset = rand() % 10000L;
            array[count + i].key = rand() % 1000;
            array[count + i].value = (double)(rand() % 100);
        }

        if (update_interval <= count && (count + update_interval) < data_count) {
            load_external_data(array + count, update_interval);
        }

        count += update_interval;
    }

    printf("Final size: %zu\n", current_size);

    free(array);
}

int main() {
