['Below is a C implementation of a dynamic collection manager for `record` structures in an online social networking application, addressing the outlined constraints and requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_POOL_SIZE 64
#define RESIZE_FACTOR 2
#define RANDOM_VALUE_RANGE 100

typedef struct {
    long offset;
    int key;
    int value;
} record_t;

typedef struct {
    record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} record_collection_t;

record_collection_t* create_record_collection() {
    record_collection_t *collection = (record_collection_t *)malloc(sizeof(record_collection_t));
    collection->capacity = INITIAL_POOL_SIZE;
    collection->count = 0;
    collection->records = (record_t *)calloc(collection->capacity, sizeof(record_t));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_record_collection(record_collection_t *collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

static int resize_if_needed(record_collection_t *collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * RESIZE_FACTOR;
        record_t *new_records = (record_t *)realloc(collection->records, new_capacity * sizeof(record_t));
        if (!new_records) return -1;
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    return 0;
}

static void initialize_record(record_t *record) {
    record->key = rand() % RANDOM_VALUE_RANGE; // Random key initialization
    record->value = rand() % RANDOM_VALUE_RANGE; // Random value initialization
}

void add_record(record_collection_t *collection, long offset) {
    pthread_mutex_lock(&collection->lock);

    if (resize_if_needed(collection) != 0) {
        pthread_mutex_unlock(&collection->lock);
        fprintf(stderr, "Failed to resize record collection\n");
        return;
    }

    record_t *record = &collection->records[collection->count++];
    record->offset = offset;
    initialize_record(record);

    pthread_mutex_unlock(&collection->lock);
}

void update_record_value(record_collection_t *collection, long offset, int new_value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].offset == offset) {
            collection->records[i].value = new_value;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

record_t* get_record(record_collection_t *collection, long offset) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].offset == offset) {
            record_t *record = &collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void remove_record(record_collection_t *collection, long offset) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].offset == offset) {
            memmove(&collection->records[i], &collection->records[i + 1],
                    (--collection->count - i) * sizeof(record_t));
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void iterate_records(record_collection_t *collection, void (*func)(record_t*)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        func(&collection->records[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

void print_record(record_t *record) {
    printf("Offset: %ld, Key: %d, Value: %d\n", record->offset, record->key, record->value);
}
```

### Explanation:
- **Memory Management**: The collection uses a dynamic array with `realloc` for resizing.
- **Initialization**: Random values are generated using `rand()`.
- **Dynamic Resizing**: Implemented via `resize_if_needed`, doubling the capacity when full.
- **Concurrency**: Thread safety is ensured using `pthread_mutex_t`.
- **Iterative Operations**: Iteration uses a mutex lock to ensure safe concurrent access.
- **Performance Constraints**: Basic optimizations like minimizing locking duration are applied.
- **Scalability & Integration**: The design allows for straightforward integration and scaling.

This implementation provides a foundation that can be extended with additional features, such as more sophisticated concurrency mechanisms or integration hooks.']

["```javascript
// Define a utility class for managing dynamic loading of JavaScript files
class ScriptLoader {
  constructor() {
    this.cache = new Map();
    this.manifest = {};
    this.loadQueue = [];
    this.dbName = 'scriptLoaderDB';
    this.initIndexedDB();
  }

  async initIndexedDB() {
    if (!window.indexedDB) return;
    const request = indexedDB.open(this.dbName, 1);

    request.onupgradeneeded = (event) => {
      event.target.result.createObjectStore('scripts', { keyPath: 'url' });
    };

    await new Promise((resolve) => request.onsuccess = resolve);
  }

  async loadScript(url, options = {}) {
    const { version, retries } = Object.assign({ version: null, retries: 3 }, options);

    if (this.isCached(url, version)) return this.cache.get(url).exports;

    const scriptLoadPromise = new Promise((resolve, reject) => {
      try {
        this.loadScriptFile(url)
          .then((moduleExports) => {
            this.updateCache(url, version, moduleExports);
            resolve(moduleExports);
          })
          .catch((error) => {
            if (retries > 0) {
              setTimeout(() => {
                this.loadScript(url, { ...options, retries: retries - 1 }).then(resolve).catch(reject);
              }, 1000); // Backoff strategy
            } else {
              reject(error);
            }
          });
      } catch (error) {
        reject(error);
      }
    });

    return scriptLoadPromise;
  }

  async loadScriptFile(url) {
    const worker = new Worker(URL.createObjectURL(new Blob([`
      self.onmessage = async function(event) {
        try {
          // Assume the file is loaded from URL or blob here
          let response = await fetch(event.data.url);
          if (!response.ok) throw new Error('Network response was not ok');

          const scriptText = await response.text();
          eval(scriptText);

          postMessage({ type: 'success', exports: window.moduleExports });
        } catch (error) {
          postMessage({ type: 'error', error });
        }
      };
    `], { type: 'application/javascript' })));

    worker.onmessage = async (event) => {
      if (event.data.type === 'error') throw event.data.error;
      return event.data.exports;
    };

    await worker.postMessage({ url });

    URL.revokeObjectURL(worker.scriptURI);
  }

  isCached(url, version) {
    const cachedItem = this.cache.get(url);
    if (!cachedItem) return false;

    // Check for version match
    if (version && cachedItem.version !== version) {
      return false;
    }
    return true;
  }

  updateCache(url, version, moduleExports) {
    const cacheEntry = { exports: moduleExports, version };
    this.cache.set(url, cacheEntry);

    const db = await this.openDB();
    const tx = db.transaction('scripts', 'readwrite');
    const store = tx.objectStore('scripts');

    store.put({ url, version, timestamp: Date.now() });
    return tx.complete;
  }

  async openDB() {
    if (!window.indexedDB) throw new Error('IndexedDB not supported.');
    return indexedDB.open(this.dbName);
  }

  async loadDependencies(dependencies) {
    for (const dep of dependencies) {
      await this.loadScript(dep.url, { version: dep.version });
    }
  }

  logError(error) {
    console.error(`Failed to load script: ${error.message}`);
    // Implement further logging mechanism if needed
  }
}

// Example Usage:
(async () => {
  const loader = new ScriptLoader();
  try {
    await loader.loadDependencies([
      { url: 'localFile1.js', version: '1.0' },
      { url: 'https://example.com/externalScript.js', version: '2.3' }
    ]);

    // Dynamically execute loaded scripts
    const localExport = loader.cache.get('localFile1.js').exports;
    if (localExport) {
      localExport.someFunction();
    }

  } catch (error) {
    loader.logError(error);
  }
})();
```"]

