    int compression_flag;
    time_t event_timestamp;
    struct Record* next;
    struct Record* prev;
} Record;

typedef struct RecordsList {
    Record* head;
    Record* tail;
    size_t count;
    size_t capacity;
    long offset_array[1024];
    int key_array[1024];
} RecordsList;

RecordsList* create_records_list(size_t initial_capacity) {
    RecordsList* list = (RecordsList*)malloc(sizeof(RecordsList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    list->capacity = initial_capacity;

    memset(list->offset_array, 0, sizeof(long) * initial_capacity);
    memset(list->key_array, 0, sizeof(int) * initial_capacity);

    return list;
}

void resize_records_list(RecordsList* list) {
    size_t new_capacity = list->capacity * 2;
    long* new_offset_array = (long*)realloc(list->offset_array, sizeof(long) * new_capacity);
    int* new_key_array = (int*)realloc(list->key_array, sizeof(int) * new_capacity);

    if (!new_offset_array || !new_key_array) {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        return;
    }

    list->offset_array = new_offset_array;
    list->key_array = new_key_array;
    list->capacity = new_capacity;
}

void add_record(RecordsList* list, int key, double value, size_t data_size) {
    if (list->count >= list->capacity) {
        resize_records_list(list);
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for record.\n");
        return;
    }

    new_record->key = key;
    new_record->value = value;

    // Generate random binary data
    for (size_t i = 0; i < data_size && i < sizeof(new_record->binary_data); ++i) {
        new_record->binary_data[i] = rand() % 256;
    }
    new_record->data_size = data_size;
    new_record->compression_flag = (rand() % 2 == 0);
    new_record->event_timestamp = time(NULL);

    // Calculate offset
    long offset = 0;
    for (size_t i = 0; i < list->count; ++i) {
        offset += list->key_array[i];
    }
    offset += key; // Example constant value addition
    new_record->offset = offset;

    // Store in arrays
    list->offset_array[list->count] = offset;
    list->key_array[list->count] = key;

    if (list->tail) {
        list->tail->next = new_record;
        new_record->prev = list->tail;
    } else {
        list->head = new_record;
    }
    list->tail = new_record;
    ++list->count;
}

void free_records_list(RecordsList* list) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }

    free(list->offset_array);
    free(list->key_array);
    free(list);
}

void iterate_records_forward(RecordsList* list) {
    for (Record* record = list->head; record != NULL; record = record->next) {
        // Process record
    }
}

void iterate_records_backward(RecordsList* list) {
    for (Record* record = list->tail; record != NULL; record = record->prev) {
        // Process record
    }
}

// Example usage
int main() {
    srand(time(NULL));
    RecordsList* records_list = create_records_list(10);

    for (int i = 0; i < 20; ++i) {
        add_record(records_list, rand() % 100, (double)rand(), rand() % 1024);
    }

    iterate_records_forward(records_list);
    iterate_records_backward(records_list);

    free_records_list(records_list);
    return 0;
}
