This implementation is designed to handle concurrent processing and efficiently manage resources. Adjustments may be needed based on specific application requirements or environment constraints.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
    char message[256];
} Entry;

typedef struct {
    Entry* entry;
    time_t timestamp;
} Summary;

typedef struct {
    Entry** entries;
    size_t entry_count;
    size_t entry_capacity;
    Summary** summaries;
    size_t summary_count;
    size_t summary_capacity;
    pthread_mutex_t mutex;
} MemoryManager;

int init_memory_manager(MemoryManager* manager, size_t initial_capacity) {
    if (pthread_mutex_init(&manager->mutex, NULL) != 0) {
        return -1; // Mutex initialization failed
    }

    manager->entries = malloc(initial_capacity * sizeof(Entry*));
    if (!manager->entries) {
        perror("Failed to allocate memory for entries");
        pthread_mutex_destroy(&manager->mutex);
        return -1;
    }

    manager->entry_count = 0;
    manager->entry_capacity = initial_capacity;

    manager->summaries = malloc(initial_capacity * sizeof(Summary*));
    if (!manager->summaries) {
        perror("Failed to allocate memory for summaries");
        free(manager->entries);
        pthread_mutex_destroy(&manager->mutex);
        return -1;
    }

    manager->summary_count = 0;
    manager->summary_capacity = initial_capacity;

    return 0; // Success
}

void destroy_memory_manager(MemoryManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->entry_count; ++i) {
        free(manager->entries[i]);
    }
    free(manager->entries);

    for (size_t i = 0; i < manager->summary_count; ++i) {
        free(manager->summaries[i]);
    }
    free(manager->summaries);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

int add_entry(MemoryManager* manager, double min_val, double max_val) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->entry_count == manager->entry_capacity) {
        size_t new_capacity = manager->entry_capacity * 2;
        Entry** new_entries = realloc(manager->entries, new_capacity * sizeof(Entry*));

        if (!new_entries) {
            perror("Failed to reallocate memory for entries");
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Reallocation failed
        }

        manager->entries = new_entries;
        manager->entry_capacity = new_capacity;
    }

    Entry* entry = malloc(sizeof(Entry));
    if (!entry) {
        perror("Failed to allocate memory for an entry");
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Allocation failed
    }

    double range = max_val - min_val;
    entry->value = min_val + (rand() / (double)RAND_MAX) * range;
    snprintf(entry->message, sizeof(entry->message), "Entry %zu", manager->entry_count);

    manager->entries[manager->entry_count++] = entry;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

int add_summary(MemoryManager* manager, Entry* entry) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->summary_count == manager->summary_capacity) {
        size_t new_capacity = manager->summary_capacity * 2;
        Summary** new_summaries = realloc(manager->summaries, new_capacity * sizeof(Summary*));

        if (!new_summaries) {
            perror("Failed to reallocate memory for summaries");
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Reallocation failed
        }

        manager->summaries = new_summaries;
        manager->summary_capacity = new_capacity;
    }

    Summary* summary = malloc(sizeof(Summary));
    if (!summary) {
        perror("Failed to allocate memory for a summary");
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Allocation failed
    }

    summary->entry = entry;
    summary->timestamp = time(NULL);

    manager->summaries[manager->summary_count++] = summary;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}
