typedef struct {
    time_t timestamp;
    char *reference_id;
    float amount;
} Transaction;

typedef struct {
    Transaction **transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionArray;

// Helper function to generate a random transaction
Transaction* create_random_transaction() {
    Transaction *transaction = malloc(sizeof(Transaction));
    if (!transaction) return NULL;

    // Random timestamp in the last year
    time_t now = time(NULL);
    time_t year_ago = now - 365 * 24 * 60 * 60;
    transaction->timestamp = (rand() % (now - year_ago)) + year_ago;

    // Random reference ID
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t len = rand() % 10 + 5; // Length between 5 and 15
    transaction->reference_id = malloc(len + 1);
    if (!transaction->reference_id) {
        free(transaction);
        return NULL;
    }
    for (size_t i = 0; i < len; i++) {
        transaction->reference_id[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    transaction->reference_id[len] = '\0';

    // Random amount
    transaction->amount = ((float)rand() / RAND_MAX) * 1000.0;

    return transaction;
}

// Helper function to resize the array when needed
void resize_transaction_array(TransactionArray *array) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity * RESIZE_THRESHOLD) {
        size_t new_capacity = array->capacity * 2;
        Transaction **new_transactions = realloc(array->transactions, sizeof(Transaction*) * new_capacity);
        if (!new_transactions) {
            fprintf(stderr, "Failed to resize transaction array.\n");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->transactions = new_transactions;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to initialize the TransactionArray
TransactionArray* init_transaction_array() {
    TransactionArray *array = malloc(sizeof(TransactionArray));
    if (!array) return NULL;

    array->transactions = malloc(sizeof(Transaction*) * INITIAL_CAPACITY);
    if (!array->transactions) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    // Populate with random transactions
    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        Transaction *transaction = create_random_transaction();
        if (transaction) {
            resize_transaction_array(array);
            array->transactions[array->count++] = transaction;
        }
    }

    return array;
}

// Function to add a new transaction
void add_transaction(TransactionArray *array, Transaction *transaction) {
    pthread_mutex_lock(&array->lock);
    resize_transaction_array(array);
    array->transactions[array->count++] = transaction;
    pthread_mutex_unlock(&array->lock);
}

// Placeholder function for syncing with the remote database
