```c
#include <stdio.h>
#include <stdlib.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <dlfcn.h>

// Define a structure to hold algorithm configurations
typedef struct {
    int enable_aes;
    int enable_camellia;
    int enable_md5;
    int enable_sha1;
    int enable_sha256;
    int enable_rsa_sha1;
} CryptoConfig;

// Initialize default configuration
CryptoConfig crypto_config = {1, 1, 1, 1, 1, 1};

// Function to load OpenSSL algorithms dynamically based on configuration
void load_crypto_algorithms() {
    if (crypto_config.enable_aes) {
        EVP_add_cipher(&evp_aes_128_cbc);
        EVP_add_cipher(&evp_aes_256_cbc);
    }
    if (crypto_config.enable_camellia) {
        EVP_add_cipher(&evp_camellia_128_cbc);
        EVP_add_cipher(&evp_camellia_256_cbc);
    }
    if (crypto_config.enable_md5) {
        EVP_add_digest(&evp_md5);
    }
    if (crypto_config.enable_sha1) {
        EVP_add_digest(&evp_sha1);
    }
    if (crypto_config.enable_sha256) {
        EVP_add_digest(&evp_sha256);
    }
    if (crypto_config.enable_rsa_sha1) {
        // Assume RSA is always available
        EVP_PKEY_assign_RSA(EVP_PKEY_RSA, NULL, d2i_RSAPublicKey(NULL, &rsa_pub_key, rsa_pub_key_der, rsa_pub_key_len));
        EVP_MD_CTX_set_pkey_ctx_data(ctx, pkey);
    }
}

// Initialize the library and load algorithms based on configuration
void initialize_library() {
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Load additional algorithms dynamically
    load_crypto_algorithms();
}

// Function to clean up resources
void cleanup_library() {
    EVP_cleanup();
    CRYPTO_cleanup_all_ex_data();
    ERR_free_strings();
}

int main(int argc, char **argv) {
    // Initialize the library
    initialize_library();

    // Example usage of loaded algorithms
    // ...

    // Cleanup before exit
    cleanup_library();
    return 0;
}
```

### Key Points:
- **Dynamic Loading**: Algorithms are added based on runtime configuration.
- **Configuration Structure**: Allows enabling/disabling specific algorithms.
- **Thread Safety**: OpenSSL is inherently thread-safe when properly initialized and cleaned up.
- **Error Handling**: Use `ERR_load_crypto_strings()` for detailed error messages.
- **Scalability**: Easily extendable by modifying the configuration structure and adding new algorithms in `load_crypto_algorithms()`.
- **Testing**: Thorough testing across platforms should be conducted to ensure robustness.

### Additional Considerations:
- Ensure OpenSSL is correctly installed on your platform.
- Use dynamic linking (`dlfcn.h`) if needed for loading/unloading libraries at runtime.
- Implement logging and error handling for better diagnostics and debugging."]

