#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct entry {
    double value;
    char message[256];
    struct entry *next;
    long identifier;
    unsigned int index;
} entry_t;

typedef struct summary {
    entry_t *entry_ptr;
    time_t timestamp;
} summary_t;

#define INITIAL_CAPACITY 10
#define RANGE_MIN 0.0
#define RANGE_MAX 100.0

static pthread_mutex_t global_counter_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long total_entries_count = 0;
static size_t entries_capacity = INITIAL_CAPACITY;
entry_t **entries_array = NULL;
summary_t *summaries_array = NULL;

// Thread-safe counter for total number of entries
unsigned long get_total_entry_count() {
    pthread_mutex_lock(&global_counter_lock);
    unsigned long count = total_entries_count;
    pthread_mutex_unlock(&global_counter_lock);
    return count;
}

void increment_total_entry_count() {
    pthread_mutex_lock(&global_counter_lock);
    total_entries_count++;
    pthread_mutex_unlock(&global_counter_lock);
}

// Dynamically resize entries array
void ensure_capacity(size_t new_size) {
    if (new_size > entries_capacity) {
        size_t new_capacity = entries_capacity * 2;
        while (new_capacity < new_size) {
            new_capacity *= 2;
        }

        entry_t **new_entries_array = realloc(entries_array, new_capacity * sizeof(entry_t *));
        if (!new_entries_array) {
            fprintf(stderr, "Failed to reallocate memory for entries array\n");
            exit(EXIT_FAILURE);
        }

        memset(new_entries_array + entries_capacity, 0, (new_capacity - entries_capacity) * sizeof(entry_t *));
        entries_array = new_entries_array;
        entries_capacity = new_capacity;
    }
}

// Create and initialize a new entry
entry_t* create_entry(unsigned int index, long identifier) {
    ensure_capacity(get_total_entry_count() + 1);

    entry_t *new_entry = malloc(sizeof(entry_t));
    if (!new_entry) {
        fprintf(stderr, "Failed to allocate memory for new entry\n");
        exit(EXIT_FAILURE);
    }

    new_entry->value = RANGE_MIN + ((double)rand() / RAND_MAX) * (RANGE_MAX - RANGE_MIN);
    snprintf(new_entry->message, sizeof(new_entry->message), "Entry #%lu", identifier);
    new_entry->next = NULL;
    new_entry->identifier = identifier;
    new_entry->index = index;

    entries_array[get_total_entry_count()] = new_entry;
    increment_total_entry_count();

    return new_entry;
}

// Add a summary for the entry
void add_summary(entry_t *entry) {
    time_t current_time = time(NULL);

    size_t num_summaries = get_total_entry_count();
    summaries_array = realloc(summaries_array, (num_summaries + 1) * sizeof(summary_t));
    if (!summaries_array) {
        fprintf(stderr, "Failed to allocate memory for summary array\n");
        exit(EXIT_FAILURE);
    }

    summaries_array[num_summaries].entry_ptr = entry;
    summaries_array[num_summaries].timestamp = current_time;
}

void process_entries(size_t num_entries_to_create) {
    for (size_t i = 0; i < num_entries_to_create; ++i) {
        long identifier = rand();
        entry_t *new_entry = create_entry(i, identifier);

        // Simulate some processing
        add_summary(new_entry);
    }
}

void free_resources() {
    if (entries_array) {
        for (size_t i = 0; i < get_total_entry_count(); ++i) {
            free(entries_array[i]);
        }
        free(entries_array);
    }

    if (summaries_array) {
        free(summaries_array);
    }
}

int main() {
    srand(time(NULL));

    // Simulate processing a large number of entries
    size_t num_entries_to_create = 1000;

    pthread_t threads[4];
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))process_entries, &num_entries_to_create)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            exit(EXIT_FAILURE);
        }
    }

    printf("Total entries processed: %lu\n", get_total_entry_count());

    free_resources();
    return 0;
}
