#include <stdatomic.h>

// Define record structure
typedef struct Record {
    short field1;
    int field2;
    float field3;
    uint32_t timestamp;
    int status;
} Record;

// Node for doubly linked list
typedef struct ListNode {
    Record data;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

// Memory Pool Manager structure
typedef struct MemoryPool {
    size_t block_size;
    void** free_list;
    unsigned int num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Doubly linked list structure
typedef struct LinkedList {
    ListNode* head;
    ListNode* tail;
    pthread_rwlock_t rwlock;
} LinkedList;

// Function prototypes
MemoryPool* create_memory_pool(size_t block_size, unsigned int num_blocks);
void free_memory_pool(MemoryPool* pool);
ListNode* allocate_node(MemoryPool* pool);
void deallocate_node(MemoryPool* pool, ListNode* node);

LinkedList* create_linked_list();
void destroy_linked_list(LinkedList* list);
void append_record(LinkedList* list, Record record);
Record get_first_record(LinkedList* list);
Record get_next_record(LinkedList* list, Record current);

// Random number generator setup
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void secure_rand_init() {
    srand(time(NULL)); // For demonstration; consider a more secure RNG for production
}

Record generate_random_record() {
    Record rec;
    rec.field1 = rand_range(0, SHRT_MAX);
    rec.field2 = rand_range(0, INT_MAX);
    rec.field3 = (float)rand_range(0, RAND_MAX) / RAND_MAX * 100.0f; // Example range
    rec.timestamp = time(NULL); // Use current time or a secure RNG for timestamps
    rec.status = rand_range(0, 1);
    return rec;
}

// Memory pool management
MemoryPool* create_memory_pool(size_t block_size, unsigned int num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_list = (void**)calloc(num_blocks, sizeof(void*));

    pthread_mutex_init(&pool->lock, NULL);

    for (unsigned int i = 0; i < num_blocks; ++i) {
        pool->free_list[i] = malloc(block_size);
        if (!pool->free_list[i]) {
            free_memory_pool(pool);
            return NULL;
        }
    }

    return pool;
}

void free_memory_pool(MemoryPool* pool) {
    for (unsigned int i = 0; i < pool->num_blocks; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

ListNode* allocate_node(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (!pool || !pool->free_list[0]) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    ListNode* node = (ListNode*)pool->free_list[0];
    memmove(pool->free_list, pool->free_list + 1, sizeof(void*) * (--pool->num_blocks));
    pthread_mutex_unlock(&pool->lock);

    return node;
}

void deallocate_node(MemoryPool* pool, ListNode* node) {
    pthread_mutex_lock(&pool->lock);
    if (pool && node) {
        memmove(pool->free_list + 1, pool->free_list, sizeof(void*) * pool->num_blocks);
        pool->free_list[0] = node;
        ++pool->num_blocks;
    }
    pthread_mutex_unlock(&pool->lock);
}

// Linked list management
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);

    return list;
}

void destroy_linked_list(LinkedList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        deallocate_node(pool, current);  // Assuming pool is accessible
        current = next;
    }
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

void append_record(LinkedList* list, Record record) {
    pthread_rwlock_wrlock(&list->rwlock);

    ListNode* node = allocate_node(pool);  // Assuming pool is accessible
    if (!node) {
        pthread_rwlock_unlock(&list->rwlock);
        return;
    }
    node->data = record;
    node->next = NULL;

    if (list->tail) {
        list->tail->next = node;
        node->prev = list->tail;
    } else {
        list->head = node;
        node->prev = NULL;
    }
    list->tail = node;

    pthread_rwlock_unlock(&list->rwlock);
}

Record get_first_record(LinkedList* list) {
    pthread_rwlock_rdlock(&list->rwlock);

    Record rec = (list && list->head) ? list->head->data : (Record){0};

    pthread_rwlock_unlock(&list->rwlock);
    return rec;
}

Record get_next_record(LinkedList* list, Record current) {
    pthread_rwlock_rdlock(&list->rwlock);

    Record next_rec = {0};
    ListNode* node = list->head;

    while (node && (node->data.field1 != current.field1 || 
                    node->data.field2 != current.field2 ||
                    node->data.field3 != current.field3)) {
        node = node->next;
    }

    if (node && node->next) {
        next_rec = node->next->data;
    }

    pthread_rwlock_unlock(&list->rwlock);
    return next_rec;
}

// Main function demonstrating usage
int main() {
    secure_rand_init();

    MemoryPool* pool = create_memory_pool(sizeof(ListNode), 1000);
    if (!pool) return EXIT_FAILURE;

    LinkedList* list = create_linked_list();
    if (!list) {
        free_memory_pool(pool);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 10; ++i) { // Example usage
        Record rec = generate_random_record();
        append_record(list, rec);
    }

    Record first_rec = get_first_record(list);
    printf("First record: %d, %d, %.2f\n", first_rec.field1, first_rec.field2, first_rec.field3);

    destroy_linked_list(list);
    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
```

### Key Features:

- **Memory Pool Management**: A memory pool manager is implemented to handle node allocations efficiently, minimizing fragmentation.

- **Thread-Safe Doubly Linked List**: The linked list uses a read-write lock for thread-safe operations.

- **Random Record Generation**: Uses a simple random number generator; replace with a cryptographically secure RNG in production.

- **Dynamic Resizing**: Not explicitly implemented here but can be added by reallocating the `free_list` array when blocks are exhausted.

- **Logging Integration**: Placeholder for integrating an external logging library, which should be thread-safe and optimized for performance.

This code provides a foundation that can be extended with additional features like dynamic resizing, more sophisticated RNGs, and enhanced logging.']

