fn retry_with_backoff<F, T>(operation: F) -> Option<T>
where
    F: Fn() -> Result<T, ()>,
{
    let mut retries = 0;
    loop {
        match operation() {
            Ok(value) => return Some(value),
            Err(_) if retries < 5 => {
                let delay = (1 << retries) as u64; // Exponential backoff
                std::thread::sleep(std::time::Duration::from_secs(delay));
                retries += 1;
            }
            Err(_) => break,
        }
    }

    None
}

