    OperationLog **operation_logs;
    size_t operation_log_count;
    pthread_mutex_t lock_operation_logs;
} MemoryManager;

void initialize_memory_manager(MemoryManager *manager, size_t initial_chunk_capacity) {
    manager->large_data_chunks = malloc(sizeof(LargeDataChunk*) * 10);
    manager->metadata_tags = malloc(sizeof(MetadataTag*) * 10);
    manager->operation_logs = malloc(sizeof(OperationLog*) * 10);

    manager->large_data_count = 0;
    manager->metadata_count = 0;
    manager->operation_log_count = 0;

    pthread_mutex_init(&manager->lock_large_data, NULL);
    pthread_mutex_init(&manager->lock_metadata, NULL);
    pthread_mutex_init(&manager->lock_operation_logs, NULL);

    for (size_t i = 0; i < 10; ++i) {
        manager->large_data_chunks[i] = malloc(sizeof(LargeDataChunk));
        manager->large_data_chunks[i]->data = calloc(initial_chunk_capacity, sizeof(float));
        manager->large_data_chunks[i]->size = initial_chunk_capacity;
    }
}

void free_memory_manager(MemoryManager *manager) {
    for (size_t i = 0; i < 10; ++i) {
        if (manager->large_data_chunks[i]) {
            free(manager->large_data_chunks[i]->data);
            free(manager->large_data_chunks[i]);
        }
        if (manager->metadata_tags[i]) {
            free(manager->metadata_tags[i]);
        }
        if (manager->operation_logs[i]) {
            free(manager->operation_logs[i]);
        }
    }

    free(manager->large_data_chunks);
    free(manager->metadata_tags);
    free(manager->operation_logs);

    pthread_mutex_destroy(&manager->lock_large_data);
    pthread_mutex_destroy(&manager->lock_metadata);
    pthread_mutex_destroy(&manager->lock_operation_logs);
}

void add_large_data_chunk(MemoryManager *manager, size_t initial_capacity) {
    pthread_mutex_lock(&manager->lock_large_data);

    if (manager->large_data_count >= 10) {
        fprintf(stderr, "Max large data chunks reached.\n");
        pthread_mutex_unlock(&manager->lock_large_data);
        return;
    }

    LargeDataChunk *chunk = malloc(sizeof(LargeDataChunk));
    chunk->data = calloc(initial_capacity, sizeof(float));

    for (size_t i = 0; i < initial_capacity; ++i) {
        unsigned char rand_bytes[4];
        RAND_bytes(rand_bytes, 4);
        chunk->data[i] = *(float*)rand_bytes;
    }

    chunk->size = initial_capacity;

    manager->large_data_chunks[manager->large_data_count++] = chunk;

    pthread_mutex_unlock(&manager->lock_large_data);
}

void log_operation(MemoryManager *manager, MetadataTag *metadata, int status) {
    pthread_mutex_lock(&manager->lock_operation_logs);

    if (manager->operation_log_count >= 10) {
        fprintf(stderr, "Max operation logs reached.\n");
        pthread_mutex_unlock(&manager->lock_operation_logs);
        return;
    }

    OperationLog *log = malloc(sizeof(OperationLog));
    time(&log->timestamp);
    log->status = status;
    log->metadata = metadata;

    manager->operation_logs[manager->operation_log_count++] = log;

    pthread_mutex_unlock(&manager->lock_operation_logs);
}

void iterate_large_data_chunks(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock_large_data);

    for (size_t i = 0; i < manager->large_data_count; ++i) {
        LargeDataChunk *chunk = manager->large_data_chunks[i];

        // Example iteration logic: print data
