            printf("LargeData[%zu][%zu] = %f\n", i, j, chunk->data[j]);
        }
    }

    pthread_mutex_unlock(&manager->lock_large_data);
}

int main() {
    MemoryManager manager;
    initialize_memory_manager(&manager, 100);

    add_large_data_chunk(&manager, 50);

    MetadataTag tag;
    strncpy(tag.tag, "example_tag", sizeof(tag.tag) - 1);
    log_operation(&manager, &tag, 200);

    iterate_large_data_chunks(&manager);

    free_memory_manager(&manager);
    return 0;
}
