typedef enum { TYPE_INT, TYPE_FLOAT, TYPE_STRING } ValueType;

typedef struct {
    void *value;
    ValueType type;
} Value;

// Node structure for key-value pairs
typedef struct ConfigNode {
    char *key;
    Value value;
    struct ConfigNode *next;
} ConfigNode;

// Configuration storage with a mutex and versioning
typedef struct {
    ConfigNode *head;
    pthread_rwlock_t rwlock;
    int version_count;
    Value **version_history; // Array of pointers to snapshot values
} ConfigStorage;

// Memory pool for efficient allocation
#define POOL_SIZE 1024
char memory_pool[POOL_SIZE];
size_t pool_offset = 0;

void* thread_safe_malloc(size_t size) {
    pthread_mutex_t *pool_lock = (pthread_mutex_t*)memory_pool;
    if (pool_offset + size > POOL_SIZE) return NULL; // Pool exhausted

    pthread_mutex_lock(pool_lock);
    void *ptr = memory_pool + pool_offset;
    pool_offset += size;
    pthread_mutex_unlock(pool_lock);

    return ptr;
}

// Serialization format: JSON-like for balance
void serialize_config(const ConfigStorage *storage, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_rwlock_rdlock(&storage->rwlock);
    fprintf(file, "{\n");

    for (ConfigNode *node = storage->head; node != NULL; node = node->next) {
        const char *value_str;
        switch (node->value.type) {
            case TYPE_INT:
                value_str = asprintf(NULL, "%d", *(int*)node->value.value);
                break;
            case TYPE_FLOAT:
                value_str = asprintf(NULL, "%f", *(float*)node->value.value);
                break;
            case TYPE_STRING:
                value_str = (char *)node->value.value;
                break;
        }
        fprintf(file, "\"%s\": \"%s\",\n", node->key, value_str);
        free((void*)value_str);
    }

    fprintf(file, "}\n");
    pthread_rwlock_unlock(&storage->rwlock);
    fclose(file);
}

// Deserialization
void deserialize_config(ConfigStorage *storage, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Parse key-value pairs from JSON-like format and insert into storage
        // Simplified parsing logic here
    }

    fclose(file);
}

// Initialize the configuration storage
void init_config_storage(ConfigStorage *storage) {
    storage->head = NULL;
    pthread_rwlock_init(&storage->rwlock, NULL);
    storage->version_count = 0;
    storage->version_history = malloc(10 * sizeof(Value*)); // Initial capacity
}

// Add or update a configuration entry
void set_config_entry(ConfigStorage *storage, const char *key, Value value) {
    pthread_rwlock_wrlock(&storage->rwlock);

    ConfigNode **node_ptr = &storage->head;
    while (*node_ptr && strcmp((*node_ptr)->key, key) != 0) {
        node_ptr = &(*node_ptr)->next;
    }

    if (*node_ptr) { // Update existing
        free((*node_ptr)->value.value);
        (*node_ptr)->value = value;
    } else { // Insert new
        ConfigNode *new_node = thread_safe_malloc(sizeof(ConfigNode));
        new_node->key = strdup(key);
        new_node->value = value;
        new_node->next = *node_ptr;
        *node_ptr = new_node;
    }

    pthread_rwlock_unlock(&storage->rwlock);
}

// Retrieve a configuration entry
Value get_config_entry(const ConfigStorage *storage, const char *key) {
    Value result = {NULL, TYPE_INT}; // Default return value

    pthread_rwlock_rdlock(&storage->rwlock);
    for (ConfigNode *node = storage->head; node != NULL; node = node->next) {
        if (strcmp(node->key, key) == 0) {
            result = node->value;
            break;
        }
    }
    pthread_rwlock_unlock(&storage->rwlock);

    return result;
}

// Example usage
int main() {
    ConfigStorage storage;
    init_config_storage(&storage);

    Value val_int = {thread_safe_malloc(sizeof(int)), TYPE_INT};
    *(int*)val_int.value = 42;

    set_config_entry(&storage, "example_key", val_int);

    Value retrieved_val = get_config_entry(&storage, "example_key");
    printf("Retrieved value: %d\n", *(int*)retrieved_val.value);

    serialize_config(&storage, "config.json");

    free((void*)val_int.value);
    return 0;
}
