    time_t timestamp;
    char *metadata;
    size_t offset;
    int key;
    struct Record *prev, *next;
} Record;

// Doubly linked list head
struct RecordList {
    Record *head, *tail;
    pthread_mutex_t lock;
};

typedef struct RecordList RecordList;

// Custom memory allocator and pool (simplified)
#define POOL_SIZE 1024

void* custom_alloc(size_t size) {
    static char pool[POOL_SIZE];
    static size_t offset = 0;

    if (offset + size > POOL_SIZE) return NULL; // Pool exhausted
    void *ptr = &pool[offset];
    offset += size;
    return ptr;
}

// Initialization function
void initialize_data(RecordList *list, int range_min, int range_max, int key_count) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;

    // Generate keys with a random seed
    srand((unsigned int)(time(NULL)));
    int *keys = (int *)custom_alloc(key_count * sizeof(int));

    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return;
    }

    size_t cumulative_sum = 0;
    for (int i = 0; i < key_count; ++i) {
        keys[i] = range_min + rand() % (range_max - range_min + 1);
        cumulative_sum += keys[i];
        Record *record = (Record *)custom_alloc(sizeof(Record));

        if (!record) {
            fprintf(stderr, "Memory allocation failed for record.\n");
            return;
        }

        record->key = keys[i];
        record->offset = cumulative_sum * 2; // Example constant factor

        char *metadata = (char *)custom_alloc(256);
        if (!metadata) {
            free(record); // Cleanup
            fprintf(stderr, "Memory allocation failed for metadata.\n");
            return;
        }

        snprintf(metadata, 256, "Metadata for key %d", keys[i]);
        record->metadata = metadata;

        // Random initialization of other fields
        record->field1 = (short)rand();
        record->field2 = rand();
        record->field3 = (float)rand() / RAND_MAX;
        record->timestamp = time(NULL);

        pthread_mutex_lock(&list->lock);

        if (!list->head) {
            list->head = list->tail = record;
        } else {
            list->tail->next = record;
            record->prev = list->tail;
            list->tail = record;
        }

        pthread_mutex_unlock(&list->lock);
    }
}

// Function to resize key and metadata arrays
void resize_arrays(int **keys, char ***metadata, int *key_count) {
    // Example resizing strategy: double the size if needed
    int new_size = (*key_count) * 2;
    int *new_keys = (int *)custom_alloc(new_size * sizeof(int));
    char **new_metadata = (char **)custom_alloc(new_size * sizeof(char *));

    if (!new_keys || !new_metadata) {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        return;
    }

    memcpy(new_keys, *keys, (*key_count) * sizeof(int));
    for (int i = 0; i < *key_count; ++i) {
        new_metadata[i] = strdup((*metadata)[i]);
    }

    free(*keys);
    for (int i = 0; i < *key_count; ++i) {
        free((*metadata)[i]);
    }
    free(*metadata);

    *keys = new_keys;
    *metadata = new_metadata;
    *key_count = new_size;
}

// Function to iterate over linked list with a sliding window
void process_linked_list_with_window(RecordList *list, size_t window_size) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current) {
        // Process current record here
        printf("Processing key: %d\n", current->key);

        if (window_size > 0 && --window_size == 0) break;

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Logging function placeholder
void log_change(const char *message) {
