// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void process_filename(const char *filename, const char *env_seed, char **processed_filename, char **hash) {
    pthread_mutex_lock(&mutex);

    // Handle empty filename
    if (filename == NULL || strlen(filename) == 0) {
        filename = "default";
    }

    size_t length = strlen(filename);
    int trunc_length = (length > 255) ? 255 : length;

    // Filter and truncate invalid characters
    char filtered[256] = {0};
    for (size_t i = 0; i < length && i < 255; ++i) {
        if ((filename[i] >= 'a' && filename[i] <= 'z') ||
            (filename[i] >= 'A' && filename[i] <= 'Z') ||
            (filename[i] >= '0' && filename[i] <= '9') ||
            filename[i] == '_' || filename[i] == '-') {
            filtered[i] = filename[i];
        }
    }

    // Determine file extension
    char ext[6];
    if (filtered[0] >= '0' && filtered[0] <= '9') {
        strcpy(ext, ".data");
    } else {
        strcpy(ext, ".log");
    }

    // Create new processed filename
    char base_name[256];
    snprintf(base_name, sizeof(base_name), "%.*s%s", (int)trunc_length, filtered, ext);

    // Seed the random number generator
    unsigned int seed;
    if (env_seed && *env_seed) {
        sscanf(env_seed, "%u", &seed);
    } else {
        time_t now = time(NULL);
        seed = (unsigned int)(now % 10000); // Default fallback to current timestamp mod 10k
    }
    srand(seed);

    // Create unique identifier using character count, random integer, and current timestamp
    unsigned int random_int = rand() % 10000;
    time_t timestamp = time(NULL);
    char unique_id[50];
    snprintf(unique_id, sizeof(unique_id), "%zu_%u_%lu", length, random_int, (unsigned long)timestamp);

    // Concatenate to form the final processed filename
    *processed_filename = malloc(strlen(base_name) + strlen(unique_id) + 1);
    if (*processed_filename == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    snprintf(*processed_filename, strlen(base_name) + strlen(unique_id) + 1, "%s_%s", base_name, unique_id);

    // Compute MD5 hash
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    if (MD5((unsigned char *)*processed_filename, strlen(*processed_filename), md5_hash)) {
        *hash = malloc(33); // 32 characters + null-terminator
        if (*hash == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            free(*processed_filename);
            pthread_mutex_unlock(&mutex);
            return;
        }
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            sprintf((*hash) + (i * 2), "%02x", md5_hash[i]);
        }
    } else {
        fprintf(stderr, "MD5 computation error\n");
        free(*processed_filename);
        *processed_filename = NULL;
        *hash = strdup("default_hash"); // Default placeholder value
    }

    pthread_mutex_unlock(&mutex);
}

// Example integration into a larger system function
void example_system_function(const char *filename, const char *env_seed) {
    char *processed_filename = NULL;
    char *md5_hash = NULL;

    process_filename(filename, env_seed, &processed_filename, &md5_hash);

    if (processed_filename && md5_hash) {
        printf("Processed Filename: %s\n", processed_filename);
        printf("MD5 Hash: %s\n", md5_hash);
    } else {
        printf("Failed to process filename.\n");
    }

    free(processed_filename);
    free(md5_hash);
}

int main() {
    const char *env_seed = getenv("FILENAME_SEED");
    example_system_function("example123.txt", env_seed);
    return 0;
}
