int validate_line(const char *line, int max_str_length, size_t *num_parts, char ***parts) {
    const char *delimiter = " ";
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);

    if (buffer == NULL) return -1;

    strncpy(buffer, line, buffer_size - 1);
    buffer[buffer_size - 1] = '\0';

    char *save_ptr;
    *parts = strsplit(buffer, delimiter, &save_ptr, num_parts);

    if (*num_parts != 2 || (**parts)[0] == NULL || strlen((**parts)[0]) >= max_str_length) {
        free(buffer);
        return -1;
    }

    free(buffer);
    return 0;
}

char **strsplit(char *line, const char *delimiter, char **save_ptr, size_t *num_parts) {
    *num_parts = 0;
    char **result = malloc(100 * sizeof(char *));

    if (result == NULL) return NULL;

    char *token = strtok_r(line, delimiter, save_ptr);
    while (token != NULL && *num_parts < 99) {
        result[(*num_parts)++] = token;
        token = strtok_r(NULL, delimiter, save_ptr);
    }
    result[*num_parts] = NULL; // Null-terminate the array
    return result;
}

void* read_and_initialize_records(void* args) {
    struct {
        FILE *file;
        record *records;
        int start_line;
        int end_line;
        pthread_mutex_t *mutex;
        int min_value;
        int max_value;
    } *data = (struct{FILE*,record*,int,int,pthread_mutex_t*,int,int}*) args;

    long offsets[10000];
    int keys[10000];

    for (int i = data->start_line; i < data->end_line; ++i) {
        char line[256];
        if (fgets(line, sizeof(line), data->file) == NULL) break;

        size_t num_parts;
        char **parts;
        if (validate_line(line, 100, &num_parts, &parts) != 0) continue;

        pthread_mutex_lock(data->mutex);
        offsets[i] = ftell(data->file);

        // Allocate memory for string and copy
        records[i].str = malloc(strlen(parts[0]) + 1);
        if (records[i].str == NULL) {
            pthread_mutex_unlock(data->mutex);
            continue;
        }
        strcpy(records[i].str, parts[0]);

        keys[i] = atoi(parts[1]);
        records[i].value = rand() % (data->max_value - data->min_value + 1) + data->min_value;

        free(parts[0]);
        free(parts);

        pthread_mutex_unlock(data->mutex);
    }
    return NULL;
}

record* initialize_records_from_file(const char *filename, int min_value, int max_value) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    record *records = malloc(10000 * sizeof(record));
    long *offsets = malloc(10000 * sizeof(long));
    int *keys = malloc(10000 * sizeof(int));

    pthread_t threads[4];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < 4; ++i) {
        struct {
            FILE *file;
            record *records;
            int start_line;
            int end_line;
            pthread_mutex_t *mutex;
            int min_value;
            int max_value;
        } args = { file, records, i * 2500, (i + 1) * 2500, &mutex, min_value, max_value };

        if (pthread_create(&threads[i], NULL, read_and_initialize_records, &args)) {
            perror("Error creating thread");
            free_resources(offsets, keys, records);
            fclose(file);
            return NULL;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    free_resources(offsets, keys, NULL); // Offset and key arrays are not used later

    return records;
}
