typedef struct {
    char *unit;
    double value;
    char type;
} Measurement;

Measurement* readMeasurements(const char *filename, int numMeasurements) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    Measurement *measurements = (Measurement*)malloc(numMeasurements * sizeof(Measurement));
    if (!measurements) {
        fclose(file);
        return NULL;
    }

    char line[513];
    int count = 0;

    while (fgets(line, sizeof(line), file) && count < numMeasurements) {
        Measurement *measurement = &measurements[count];

        char unit[513], type;
        double value;
        if (sscanf(line, "%512s %lf %c", unit, &value, &type) != 3) continue;

        measurement->unit = (char*)malloc(strlen(unit) + 1);
        if (!measurement->unit) {
            for (int i = 0; i < count; ++i) free(measurements[i].unit);
            free(measurements);
            fclose(file);
            return NULL;
        }
        strcpy(measurement->unit, unit);

        measurement->value = value;
        measurement->type = type;

        if (measurement->type == 'T' && strcmp(measurement->unit, "F") == 0) {
            // Convert Fahrenheit to Celsius
            measurement->value = (measurement->value - 32) * 5.0 / 9.0;
            free(measurement->unit);
            measurement->unit = strdup("C");
        } else if (measurement->type == 'P' && strcmp(measurement->unit, "mbar") == 0) {
            // Convert millibars to Pascals
            measurement->value *= 100.0;
            free(measurement->unit);
            measurement->unit = strdup("Pa");
        }

        ++count;
    }

    fclose(file);

    if (count != numMeasurements) {
        for (int i = 0; i < count; ++i) free(measurements[i].unit);
        free(measurements);
        return NULL;
    }

    return measurements;
}

void freeMeasurements(Measurement *measurements, int numMeasurements) {
    if (!measurements) return;

    for (int i = 0; i < numMeasurements; ++i) {
        free(measurements[i].unit);
    }
    free(measurements);
}
