['Below is a C code implementation that addresses your programming task requirements. This solution includes memory management using a memory pool, background resizing, predictive analytics integration, efficient initialization, and thread-safe modifications.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB pool size

typedef struct {
    short s;
    int i;
    float f;
    time_t timestamp;
    char metadata[MAX_METADATA_LENGTH];
    char event[10]; // Assuming fixed length for simplicity
    char status[10];
    int priority;
    double weight;
    double location; // Simplified to one coordinate
    double duration;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    size_t element_size;
    void* pool;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

void* memory_pool_alloc(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void* ptr = (char*)mp->pool + mp->used;
    mp->used += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void init_memory_pool(MemoryPool* mp, size_t element_size) {
    mp->element_size = element_size;
    mp->pool = malloc(MEMORY_POOL_SIZE);
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void free_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

typedef struct {
    Node* head;
    Node* tail;
    pthread_rwlock_t rw_lock;
} LinkedList;

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_rwlock_init(&list->rw_lock, NULL);
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&list->rw_lock);
}

Node* create_node(MemoryPool* mp, const Record* record) {
    void* mem = memory_pool_alloc(mp, sizeof(Node));
    if (!mem) return NULL;
    Node* node = (Node*)mem;
    memcpy(&(node->record), record, sizeof(Record));
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void append_node(LinkedList* list, MemoryPool* mp, const Record* record) {
    pthread_rwlock_wrlock(&list->rw_lock);
    Node* new_node = create_node(mp, record);
    if (!new_node) {
        pthread_rwlock_unlock(&list->rw_lock);
        fprintf(stderr, "Failed to allocate memory for node\n");
        return;
    }
    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    pthread_rwlock_unlock(&list->rw_lock);
}

void iterate_linked_list(LinkedList* list, void (*callback)(Record*)) {
    pthread_rwlock_rdlock(&list->rw_lock);
    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->record));
        current = current->next;
    }
    pthread_rwlock_unlock(&list->rw_lock);
}

// Example usage
void print_record(Record* record) {
    printf("Record: %d, %f, %s\n", record->i, record->f, record->metadata);
}

int main() {
    MemoryPool mp;
    LinkedList list;

    init_memory_pool(&mp, sizeof(Node));
    init_linked_list(&list);

    // Simulate adding records
    for (int i = 0; i < 100; ++i) {
        Record record = { .s = rand(), .i = rand(), .f = (float)rand() / RAND_MAX,
                          .timestamp = time(NULL), .metadata = "Example",
                          .event = "TypeA", .status = "Active", .priority = i % 5,
                          .weight = (double)rand() / RAND_MAX, .location = rand(),
                          .duration = (double)rand() / RAND_MAX };
        append_node(&list, &mp, &record);
    }

    iterate_linked_list(&list, print_record);

    destroy_linked_list(&list);
    free_memory_pool(&mp);

    return 0;
}
```

