```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_KEYS 1000
#define DATA_POOL_SIZE 1024

typedef struct {
    float value;
} Data;

typedef struct {
    int *offsets;
    long *keys;
    Data *data_pool;
    pthread_mutex_t lock;
    size_t pool_index;
} MemoryManager;

void* allocate_data(void* arg) {
    MemoryManager *mm = (MemoryManager*)arg;
    pthread_mutex_lock(&mm->lock);

    if (mm->pool_index < DATA_POOL_SIZE) {
        Data *data = &mm->data_pool[mm->pool_index++];
        pthread_mutex_unlock(&mm->lock);
        return data;
    }

    pthread_mutex_unlock(&mm->lock);
    return NULL;
}

void log_discrepancy(const char* message) {
    FILE *log_file = fopen("discrepancies.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int initialize_memory_manager(MemoryManager *mm, const char *config_file, int num_keys) {
    mm->offsets = (int*)malloc(num_keys * sizeof(int));
    mm->keys = (long*)malloc(num_keys * sizeof(long));
    mm->data_pool = (Data*)calloc(DATA_POOL_SIZE, sizeof(Data));
    pthread_mutex_init(&mm->lock, NULL);
    mm->pool_index = 0;

    if (!mm->offsets || !mm->keys || !mm->data_pool) {
        log_discrepancy("Memory allocation failed.");
        return -1;
    }

    FILE *file = fopen(config_file, "r");
    if (!file) {
        log_discrepancy("Failed to open configuration file.");
        return -1;
    }

    long key;
    int offset = 0;
    for (int i = 0; i < num_keys; ++i) {
        if (fscanf(file, "%ld", &key) != 1) {
            log_discrepancy("Invalid configuration file format.");
            fclose(file);
            return -1;
        }

        mm->keys[i] = key;
        mm->offsets[i] = offset++;
    }

    fclose(file);
    return 0;
}

int populate_data(MemoryManager *mm, const char **data_files, int num_keys) {
    pthread_t threads[num_keys];
    for (int i = 0; i < num_keys; ++i) {
        if (pthread_create(&threads[i], NULL, allocate_data, mm) != 0) {
            log_discrepancy("Failed to create thread.");
            return -1;
        }

        FILE *file = fopen(data_files[i], "r");
        if (!file) {
            log_discrepancy("Failed to open data file.");
            pthread_join(threads[i], NULL);
            continue;
        }

        float value;
        if (fscanf(file, "%f", &value) != 1) {
            log_discrepancy("Invalid data file format.");
            fclose(file);
            pthread_join(threads[i], NULL);
            continue;
        }

        Data *data = (Data*)pthread_getspecific(mm->lock);
        if (data) {
            data->value = value;
        }

        fclose(file);
    }

    for (int i = 0; i < num_keys; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void cleanup_memory_manager(MemoryManager *mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->data_pool);
    pthread_mutex_destroy(&mm->lock);
}
```

This code sets up a memory manager to handle the initialization and population of the data structures using threads. It includes basic error handling, logging discrepancies, and uses a simple memory pool for `Data` objects. The solution is designed to be extensible by allowing new data sources or modifications with minimal changes.']

