    if (!chunk) return NULL;

    chunk->timestamp = (long)(rand() % (TIMESTAMP_MAX - TIMESTAMP_MIN + 1)) + TIMESTAMP_MIN;
    chunk->size = (unsigned int)(rand() % (CHUNK_SIZE_MAX - CHUNK_SIZE_MIN + 1)) + CHUNK_SIZE_MIN;

