}

void addChunkToManager(chunkManager *manager, dataChunk *newChunk) {
    pthread_mutex_lock(&manager->lock);

    manager->chunks = realloc(manager->chunks, sizeof(dataChunk *) * (manager->totalChunks + 1));
    if (!manager->chunks) {
        free(newChunk->buffer);
        free(newChunk);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->chunks[manager->totalChunks] = newChunk;
    manager->totalChunks++;
    manager->totalBufferSize += strlen(newChunk->buffer) + 1;

    pthread_mutex_unlock(&manager->lock);
}

