    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->totalChunks; ++i) {
        if (manager->chunks[i]) {
            free(manager->chunks[i]->buffer);
            free(manager->chunks[i]);
        }
    }

    free(manager->chunks);
