#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_URL_LENGTH 2048
#define RATE_LIMIT 100 // requests per second

typedef struct {
    char scheme[16];
    char host[256];
    char path[1024];
    char query[512];
    char fragment[128];
} URLComponents;

typedef struct {
    pthread_mutex_t lock;
    int request_count;
    time_t start_time;
} RateLimiter;

// Function prototypes
int parseURL(const char *url, URLComponents *components);
void handleHTTPRequest(const char *url);
void *rateLimit(void *arg);

RateLimiter rate_limiter = {PTHREAD_MUTEX_INITIALIZER};

int main() {
    // Example usage of the HTTP request handler
    const char *urls[] = {
        "http://example.com/path?query=value#fragment",
        "https://anotherhost.com/otherpath"
    };

    for (size_t i = 0; i < sizeof(urls) / sizeof(urls[0]); ++i) {
        handleHTTPRequest(urls[i]);
    }

    return 0;
}

int parseURL(const char *url, URLComponents *components) {
    if (!url || !components) return -1;

    const char *scheme_end = strstr(url, "://");
    if (!scheme_end) return -1;

    size_t scheme_len = scheme_end - url;
    strncpy(components->scheme, url, scheme_len);
    components->scheme[scheme_len] = '\0';

    const char *host_start = scheme_end + 3;
    const char *path_start = strstr(host_start, "/");
    const char *query_start = strstr(path_start ? path_start : host_start, "?");
    const char *fragment_start = strstr(query_start ? query_start : path_start ? path_start : host_start, "#");

    if (!path_start) path_start = url + strlen(url);
    size_t host_len = (path_start - 1) - host_start;
    strncpy(components->host, host_start, host_len);
    components->host[host_len] = '\0';

    if (query_start) {
        size_t path_len = query_start - path_start;
        strncpy(components->path, path_start, path_len);
        components->path[path_len] = '\0';

        const char *query_end = fragment_start ? fragment_start : query_start + strlen(query_start);
        size_t query_len = query_end - (query_start + 1);
        strncpy(components->query, query_start + 1, query_len);
        components->query[query_len] = '\0';

        if (fragment_start) {
            size_t fragment_len = strlen(fragment_start + 1);
            strncpy(components->fragment, fragment_start + 1, fragment_len);
            components->fragment[fragment_len] = '\0';
        }
    } else if (path_start) {
        size_t path_len = fragment_start ? fragment_start - path_start : strlen(path_start);
        strncpy(components->path, path_start, path_len);
        components->path[path_len] = '\0';

        if (fragment_start) {
            size_t fragment_len = strlen(fragment_start + 1);
            strncpy(components->fragment, fragment_start + 1, fragment_len);
            components->fragment[fragment_len] = '\0';
        }
    }

    return 0;
}

void handleHTTPRequest(const char *url) {
    pthread_t rate_limit_thread;
    if (pthread_create(&rate_limit_thread, NULL, rateLimit, NULL) != 0) {
        fprintf(stderr, "Failed to create rate limit thread\n");
        return;
    }

    URLComponents components;
    if (parseURL(url, &components) == -1) {
        fprintf(stderr, "Invalid URL: %s\n", url);
        return;
    }

    // Log the parsed components for debugging
    printf("Scheme: %s, Host: %s, Path: %s, Query: %s, Fragment: %s\n",
           components.scheme, components.host, components.path, components.query, components.fragment);

    // Simulate asynchronous processing (e.g., using non-blocking I/O or async libraries)
    // For demonstration purposes, we'll just sleep for a short duration
    struct timespec ts = {0, 100000000}; // 100 ms
    nanosleep(&ts, NULL);

    pthread_join(rate_limit_thread, NULL);
}

void *rateLimit(void *arg) {
    time_t current_time;
    int allowed_request;

    while (1) {
        pthread_mutex_lock(&rate_limiter.lock);

        current_time = time(NULL);
        if (current_time != rate_limiter.start_time) {
            rate_limiter.start_time = current_time;
            rate_limiter.request_count = 0;
        }

        allowed_request = (rate_limiter.request_count < RATE_LIMIT);
        if (allowed_request) {
            rate_limiter.request_count++;
        } else {
            // Sleep for a second before resetting the count
            struct timespec ts = {1, 0};
            nanosleep(&ts, NULL);
            rate_limiter.start_time = time(NULL);
            rate_limiter.request_count = 1;
        }

        pthread_mutex_unlock(&rate_limiter.lock);

        if (!allowed_request) {
            // Sleep briefly to avoid busy waiting
            struct timespec ts = {0, 10000000}; // 10 ms
            nanosleep(&ts, NULL);
        } else {
            break;
        }
    }

    return NULL;
}
