#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
} Record;

typedef struct ListNode {
    Record data;
    struct ListNode* next;
} ListNode;

typedef struct MemoryManager {
    long *offsets;
    int *keys;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex; // For resizing and thread-safe access
    atomic_int head_index; // Atomic index for the head of the linked list
    ListNode* head;
} MemoryManager;

// Thread-local storage for random number generation
__thread struct {
    unsigned int seed;
} tls_random;

void init_tls_random() {
    if (!tls_random.seed) {
        tls_random.seed = rand(); // Initialize with system's random generator
    }
}

short generate_random_short(short min, short max) {
    init_tls_random();
    return (short)((rand_r(&tls_random.seed) % ((max - min) + 1)) + min);
}

int generate_random_int(int min, int max) {
    init_tls_random();
    return rand_r(&tls_random.seed) % (max - min + 1) + min;
}

float generate_random_float(float min, float max) {
    init_tls_random();
    return min + ((float)rand_r(&tls_random.seed) / RAND_MAX) * (max - min);
}

MemoryManager* create_memory_manager(size_t initial_capacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->mutex, NULL);

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));

    if (!manager->offsets || !manager->keys) {
        perror("Failed to allocate memory for arrays");
        exit(EXIT_FAILURE);
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->head_index = ATOMIC_VAR_INIT(0);
    manager->head = NULL;

    return manager;
}

void resize_arrays(MemoryManager* manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->mutex);

    long *new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        perror("Failed to reallocate memory for arrays");
        exit(EXIT_FAILURE);
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->mutex);
}

void initialize_manager(MemoryManager* manager, const int keys[], size_t count) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < count; ++i) {
        if (i == 0) {
            manager->keys[i] = keys[i];
        } else {
            manager->keys[i] = keys[i];
        }

        if (i > 0) {
            manager->offsets[i] = manager->offsets[i - 1] + manager->keys[i - 1];
        }
    }

    manager->count = count;

    pthread_mutex_unlock(&manager->mutex);
}

void add_record(MemoryManager* manager, const Record* record) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }

    *new_node = (ListNode){ .data = *record, .next = NULL };

    int index = atomic_fetch_add(&manager->head_index, 1);

    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->capacity) {
        resize_arrays(manager, manager->capacity * 2);
    }

    if (!manager->head || index == 0) {
        new_node->next = manager->head;
        manager->head = new_node;
    } else {
        ListNode* current = manager->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&manager->mutex);
}

void iterate_records(MemoryManager* manager, void (*process)(Record*)) {
    ListNode* current = manager->head;

    while (current) {
        process(&current->data);
        current = current->next;
    }
}

void free_memory_manager(MemoryManager* manager) {
    ListNode* current = manager->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }

    free(manager->offsets);
    free(manager->keys);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void process_record(Record* record) {
    printf("Short: %d, Int: %d, Float: %f\n", record->s_field, record->i_field, record->f_field);
}
```

This C code defines a `MemoryManager` structure to manage dynamic memory for offset values (`long`), keys (`int`), and records (containing `short`, `int`, and `float`). It uses a linked list to handle records efficiently. The code includes thread-local storage for random number generation, ensuring safe concurrent access without global locks. Additionally, it provides mechanisms for resizing arrays dynamically, adding records safely in a multi-threaded context, and iterating over the records with minimal overhead. Memory is freed appropriately to prevent leaks.']

