```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    char identifier[5]; // Short identifier
    int key;            // Integer key
    float value;        // Float value
    time_t timestamp;   // Timestamp
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataStructure;

typedef struct {
    DataStructure *ds;
    size_t index;
} Iterator;

// Function prototypes
DataStructure* create_data_structure(size_t initial_capacity);
void destroy_data_structure(DataStructure *ds);
int insert_record(DataStructure *ds, const char *identifier, int key, float value);
Iterator* iterator_create(const DataStructure *ds);
const Record* iterator_next(Iterator *it);
void resize_data_structure(DataStructure *ds);

// Helper function to log messages
void log_message(const char *message) {
    printf("%s\n", message); // In a real scenario, this might be directed to a file or logging service.
}

DataStructure* create_data_structure(size_t initial_capacity) {
    DataStructure *ds = (DataStructure *)malloc(sizeof(DataStructure));
    if (!ds) {
        log_message("Memory allocation failed for data structure.");
        return NULL;
    }

    ds->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!ds->records) {
        free(ds);
        log_message("Memory allocation failed for records array.");
        return NULL;
    }

    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < initial_capacity; ++i) {
        snprintf(ds->records[i].identifier, sizeof(ds->records[i].identifier), "ID%zu", i);
        ds->records[i].key = rand() % 100000;
        ds->records[i].value = (float)(rand() / (RAND_MAX + 1.0));
        ds->records[i].timestamp = time(NULL) + rand();
    }

    return ds;
}

void destroy_data_structure(DataStructure *ds) {
    if (!ds) return;

    pthread_mutex_destroy(&ds->lock);
    free(ds->records);
    free(ds);

    log_message("Data structure destroyed.");
}

int insert_record(DataStructure *ds, const char *identifier, int key, float value) {
    pthread_mutex_lock(&ds->lock);

    if (ds->size >= ds->capacity) {
        resize_data_structure(ds);
    }

    snprintf(ds->records[ds->size].identifier, sizeof(ds->records[ds->size].identifier), "%s", identifier);
    ds->records[ds->size].key = key;
    ds->records[ds->size].value = value;
    ds->records[ds->size].timestamp = time(NULL) + rand();

    log_message("Record inserted.");
    ++ds->size;

    pthread_mutex_unlock(&ds->lock);
    return 0; // Success
}

void resize_data_structure(DataStructure *ds) {
    size_t new_capacity = ds->capacity * 2;
    Record *new_records = (Record *)realloc(ds->records, new_capacity * sizeof(Record));
    if (!new_records) {
        log_message("Memory reallocation failed during resizing.");
        return;
    }

    for (size_t i = ds->size; i < new_capacity; ++i) {
        snprintf(new_records[i].identifier, sizeof(new_records[i].identifier), "ID%zu", i);
        new_records[i].key = rand() % 100000;
        new_records[i].value = (float)(rand() / (RAND_MAX + 1.0));
        new_records[i].timestamp = time(NULL) + rand();
    }

    ds->records = new_records;
    ds->capacity = new_capacity;

    log_message("Data structure resized.");
}

Iterator* iterator_create(const DataStructure *ds) {
    Iterator *it = (Iterator *)malloc(sizeof(Iterator));
    if (!it) return NULL;

    it->ds = (const DataStructure*)ds;
    it->index = 0;
    pthread_mutex_lock(&((DataStructure*)ds)->lock);

    log_message("Iterator created.");
    return it;
}

const Record* iterator_next(Iterator *it) {
    if (it == NULL || it->index >= it->ds->size) return NULL;

    const Record *record = &it->ds->records[it->index++];
    pthread_mutex_unlock(&((DataStructure*)it->ds)->lock);

    log_message("Moved to next record in iterator.");
    return record;
}

// Usage example
int main() {
    DataStructure *ds = create_data_structure(4);
    if (!ds) return EXIT_FAILURE;

    insert_record(ds, "R1", 123, 45.67f);
    insert_record(ds, "R2", 456, 89.01f);

    Iterator *it = iterator_create(ds);
    for (const Record *record = iterator_next(it); record != NULL; record = iterator_next(it)) {
        printf("Record: ID=%s, Key=%d, Value=%.2f, Timestamp=%ld\n",
               record->identifier, record->key, record->value, record->timestamp);
    }

    destroy_data_structure(ds);
    free(it);

    return EXIT_SUCCESS;
}
