    system->keys = malloc(initial_size * sizeof(int));
    system->records_head = NULL;
    system->events_head = NULL;
    system->keys_size = initial_size;
    pthread_mutex_init(&system->lock, NULL);

    long cumulative_sum = 0;
    for (size_t i = 0; i < initial_size; ++i) {
        system->keys[i] = random_int(key_min, key_max);
        cumulative_sum += system->keys[i];
