['Below is a C implementation that addresses your requirements for managing memory with a custom allocator, handling keys, offsets, records, dynamic resizing, and providing safe traversal. This example assumes basic knowledge of threading in C (using pthreads) and focuses on achieving the outlined goals:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

typedef struct Record {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct MemoryPool {
    void** pool;
    size_t block_size;
    size_t total_blocks;
    size_t free_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
MemoryPool* create_pool(size_t block_size, size_t num_blocks);
void* pool_alloc(MemoryPool* pool);
void pool_free(MemoryPool* pool, void* ptr);
void destroy_pool(MemoryPool* pool);

#define POOL_SIZE 1024

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Global memory pools
MemoryPool offset_pool;
MemoryPool key_pool;
MemoryPool record_pool;

// Linked List for records
Node* head = NULL;

// Function to create a new memory pool
MemoryPool* create_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->free_blocks = num_blocks;

    void** blocks = malloc(num_blocks * sizeof(void*));
    for (size_t i = 0; i < num_blocks; ++i) {
        blocks[i] = malloc(block_size);
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->pool = blocks;
    return pool;
}

// Allocate memory from a pool
void* pool_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->free_blocks > 0) {
        void** block = (void**)&(pool->pool[--pool->free_blocks]);
        void* ptr = *block;
        *block = NULL;  // Mark as used
        pthread_mutex_unlock(&pool->lock);
        return ptr;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;  // Pool is exhausted
}

// Free memory back to the pool
void pool_free(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->total_blocks; ++i) {
        if (pool->pool[i] == NULL) {
            pool->pool[i] = ptr;
            pool->free_blocks++;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Destroy a memory pool
void destroy_pool(MemoryPool* pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Initialize global pools
void init_memory_pools() {
    offset_pool = *create_pool(sizeof(long), POOL_SIZE);
    key_pool = *create_pool(sizeof(int), POOL_SIZE);
    record_pool = *create_pool(sizeof(Record), POOL_SIZE);
}

// Destroy all global memory pools
void destroy_memory_pools() {
    destroy_pool(&offset_pool);
    destroy_pool(&key_pool);
    destroy_pool(&record_pool);
}

// Function to add a new node to the linked list safely
void add_record_to_list(Record data) {
    Node* new_node = (Node*)pool_alloc(&record_pool);
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

// Example function to generate unique keys
int generate_unique_key(int range_start, int range_end) {
    static int current_key = 0; // Simple static counter for unique keys in a single-threaded context

    if (current_key < range_start) {
        current_key = range_start;
    }

    while (current_key <= range_end) {
        pthread_mutex_lock(&list_lock);
        int key = current_key++;
        pthread_mutex_unlock(&list_lock);

        return key;  // Return a unique key within the specified range
    }

    // Reset or expand range if necessary
    return -1;
}

// Function to initialize offset array with cumulative sum strategy
void init_offsets(int* keys, long* offsets, size_t num_keys) {
    long cumulative_sum = 0;
    for (size_t i = 0; i < num_keys; ++i) {
        cumulative_sum += keys[i];
        offsets[i] = cumulative_sum + 1000; // Constant offset added here
    }
}

// Example main function demonstrating usage
int main() {
    init_memory_pools();

    int num_records = 10;
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = generate_unique_key(1, 100);
    }

    init_offsets(keys, offsets, num_records);

    for (size_t i = 0; i < num_records; ++i) {
        Record record = { .s = rand() % 256, .i = rand() % 10000, .f = (float)(rand() / (double)RAND_MAX) };
        add_record_to_list(record);
    }

    // Iterate and print records
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    while (current != NULL) {
        printf("Record - short: %d, int: %d, float: %.2f\n", current->data.s, current->data.i, current->data.f);
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);

    // Cleanup
    destroy_memory_pools();
    free(offsets);
    free(keys);

    return 0;
}
```

### Explanation:
- **Memory Pools**: This implementation creates custom memory pools for `long`, `int`, and `Record` types to manage allocations efficiently.

- **Thread Safety**: The code employs mutex locks to handle concurrency issues, particularly when accessing shared resources like the linked list and generating unique keys.

- **Key Generation**: A simple static counter is used within a range. This is not thread-safe in a multi-threaded context but illustrates how keys could be generated uniquely.

- **Linked List Management**: The `add_record_to_list` function safely adds records to a linked list, using mutex locks for safe concurrent access.

- **Dynamic Resizing and Initialization**: The initialization of offset values follows the cumulative sum strategy. Dynamic resizing or additional management strategies can be added where necessary depending on further requirements.

This is a baseline solution that addresses concurrency and memory management challenges as described. Further refinement may be needed based on specific application needs, especially for more complex key generation schemes and thread-safe random number generation.']

