                                long.TryParse(parts[0], out long timestamp);
                                double.TryParse(parts[1], out double value);
                                int eventType;
                                float priorityLevel;

                                if (int.TryParse(parts[2], out eventType) && float.TryParse(parts[3], out priorityLevel))
                                {
