                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"Error processing line: {ex.Message}");
                        }
                    }
                }
            }
        }
        catch (IOException ioEx)
        {
            Console.WriteLine($"IO Exception: {ioEx.Message}");
        }
        catch (OutOfMemoryException oomEx)
        {
            Console.WriteLine("Out of memory exception caught.");
        }

        // Convert lists to arrays if needed
        Node[] nodesArray = nodes.ToArray();
        Event[] eventsArray = events.ToArray();
        Summary[] summariesArray = summaries.ToArray();

        // Further processing or integration with existing systems can be done here.
    }

    private void MonitorMemoryUsage()
    {
        long totalMemoryUsed = GC.GetTotalMemory(true);
        if (totalMemoryUsed > MaxMemoryUsage)
        {
            Console.WriteLine("Warning: Memory usage exceeded threshold.");
            // Implement alert mechanism or cleanup logic as needed
        }
    }
}
