    float f;
} Record;

typedef struct ListNode {
    Record data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

typedef struct MemoryPool {
    void** pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void initialize_memory_pool(MemoryPool* mp, size_t initial_size);
Record* allocate_record(MemoryPool* mp);
ListNode* allocate_node(MemoryPool* mp);
void free_memory_pool(MemoryPool* mp);
void insert_record(LinkedList* list, Record record);
void delete_record(LinkedList* list, short sh, int i);
ListNode* find_record(const LinkedList* list, short sh, int i);
float compute_float(short sh, int i);
void log_change(const char* message);

// Initialize memory pool
void initialize_memory_pool(MemoryPool* mp, size_t initial_size) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->size = 0;
    mp->capacity = initial_size;
    mp->pool = (void**)malloc(sizeof(void*) * initial_size);
}

// Allocate a record from the memory pool
Record* allocate_record(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->size >= mp->capacity) {
        mp->capacity *= 2;
        void** new_pool = (void**)realloc(mp->pool, sizeof(void*) * mp->capacity);
        if (!new_pool) return NULL;
        mp->pool = new_pool;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    mp->pool[mp->size++] = record;
    pthread_mutex_unlock(&mp->lock);
    return record;
}

// Allocate a linked list node from the memory pool
ListNode* allocate_node(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->size >= mp->capacity) {
        mp->capacity *= 2;
        void** new_pool = (void**)realloc(mp->pool, sizeof(void*) * mp->capacity);
        if (!new_pool) return NULL;
        mp->pool = new_pool;
    }
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    mp->pool[mp->size++] = node;
    pthread_mutex_unlock(&mp->lock);
    return node;
}

// Free memory pool
void free_memory_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->size; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

// Insert record into the linked list
void insert_record(LinkedList* list, Record record) {
    ListNode* node = allocate_node(NULL); // Assuming a global or passed memory pool for nodes
    if (!node) return;

    node->data = record;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    node->next = list->head;
    list->head = node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    log_change("Record inserted.");
}

// Delete a record from the linked list
void delete_record(LinkedList* list, short sh, int i) {
    pthread_mutex_lock(&list->lock);
    ListNode** current = &list->head;
    while (*current) {
        if ((*current)->data.sh == sh && (*current)->data.i == i) {
            ListNode* to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
            list->count--;
            log_change("Record deleted.");
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Find a record in the linked list
ListNode* find_record(const LinkedList* list, short sh, int i) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    ListNode* current = list->head;
    while (current) {
        if (current->data.sh == sh && current->data.i == i) {
            pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return NULL;
}

// Compute float value based on short and int
float compute_float(short sh, int i) {
    // Simple computation for demonstration
    return (float)(sh + i) / 100.0f;
}

// Log changes to records
void log_change(const char* message) {
    printf("%s\n", message);
}

int main() {
    MemoryPool mp;
    LinkedList list = {NULL, 0};
    pthread_mutex_init(&list.lock, NULL);

    initialize_memory_pool(&mp, 10);

    srand(time(NULL));
    for (int j = 0; j < 100; ++j) {
        Record record;
        record.sh = rand() % 256;
        record.i = rand() % 1000;
        record.f = compute_float(record.sh, record.i);
        insert_record(&list, record);
    }

    ListNode* found = find_record(&list, (short)42, 123);
    if (found) {
        printf("Found: sh=%d, i=%d, f=%.2f\n", found->data.sh, found->data.i, found->data.f);
    } else {
        printf("Record not found.\n");
    }

    delete_record(&list, (short)42, 123);

    free_memory_pool(&mp);
    pthread_mutex_destroy(&list.lock);

    return 0;
}
