['Here's a C implementation for managing a dynamic collection of `message` structures using a binary search tree (BST). The code includes thread-safe insertion, retrieval, and deletion functionalities, while optimizing for high throughput and concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Message {
    time_t timestamp;
    int priority;
    char *payload;
} Message;

typedef struct TreeNode {
    Message message;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

typedef struct BST {
    TreeNode *root;
    pthread_mutex_t lock;
} BST;

BST* create_bst() {
    BST *bst = (BST*)malloc(sizeof(BST));
    bst->root = NULL;
    pthread_mutex_init(&bst->lock, NULL);
    return bst;
}

Message* create_message(const char *payload) {
    Message *msg = (Message*)malloc(sizeof(Message));
    msg->timestamp = time(NULL); // Monotonic timestamp
    msg->priority = determine_priority(payload); // Custom priority logic
    msg->payload = strdup(payload); // Duplicate payload for dynamic storage
    return msg;
}

int determine_priority(const char *payload) {
    // Example: Assign priority based on content length (or other custom rules)
    if (strlen(payload) > 100) return 1; // High priority
    return 0; // Normal priority
}

TreeNode* create_node(Message *msg) {
    TreeNode *node = (TreeNode*)malloc(sizeof(TreeNode));
    node->message = *msg;
    node->left = NULL;
    node->right = NULL;
    free(msg);
    return node;
}

void insert_message(BST *bst, Message *msg) {
    pthread_mutex_lock(&bst->lock);

    TreeNode **cur = &(bst->root), *new_node = create_node(msg);
    while (*cur != NULL) {
        if (msg->timestamp < (*cur)->message.timestamp)
            cur = &((*cur)->left);
        else
            cur = &((*cur)->right);
    }
    *cur = new_node;

    pthread_mutex_unlock(&bst->lock);
}

TreeNode* find_min(TreeNode *node) {
    while (node && node->left != NULL) node = node->left;
    return node;
}

void delete_message(BST *bst, time_t timestamp) {
    pthread_mutex_lock(&bst->lock);

    TreeNode **cur = &(bst->root), *temp;
    while (*cur != NULL) {
        if ((*cur)->message.timestamp == timestamp) {
            temp = *cur;
            if (temp->left == NULL) {
                *cur = temp->right;
            } else if (temp->right == NULL) {
                *cur = temp->left;
            } else {
                TreeNode *min_node = find_min(temp->right);
                temp->message = min_node->message;
                cur = &((*cur)->right);
                while (*cur != NULL && (*cur)->message.timestamp != min_node->message.timestamp)
                    cur = &((*cur)->left);
                *cur = (*cur)->right;
            }
            free(temp->payload);
            free(temp);
            break;
        } else if ((*cur)->message.timestamp < timestamp) {
            cur = &((*cur)->right);
        } else {
            cur = &((*cur)->left);
        }
    }

    pthread_mutex_unlock(&bst->lock);
}

void retrieve_messages(BST *bst, time_t start_ts, time_t end_ts) {
    pthread_mutex_lock(&bst->lock);

    void inorder_retrieve(TreeNode *node, time_t start_ts, time_t end_ts) {
        if (node == NULL) return;
        if (node->message.timestamp > start_ts)
            inorder_retrieve(node->left, start_ts, end_ts);
        if (node->message.timestamp >= start_ts && node->message.timestamp <= end_ts)
            printf("Timestamp: %ld, Priority: %d, Payload: %s\n", 
                   node->message.timestamp, node->message.priority, node->message.payload);
        if (node->message.timestamp < end_ts)
            inorder_retrieve(node->right, start_ts, end_ts);
    }

    inorder_retrieve(bst->root, start_ts, end_ts);

    pthread_mutex_unlock(&bst->lock);
}

void free_bst(TreeNode *node) {
    if (node == NULL) return;
    free_bst(node->left);
    free_bst(node->right);
    free(node->message.payload);
    free(node);
}

void destroy_bst(BST *bst) {
    pthread_mutex_destroy(&bst->lock);
    free_bst(bst->root);
    free(bst);
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the BST.
- **Dynamic Memory Management**: Allocates memory for messages and their payloads dynamically, ensuring no leaks.
- **Timestamps**: Utilizes `time(NULL)` for monotonically increasing timestamps.
- **Priority Assignment**: Custom logic in `determine_priority()` assigns priorities based on message content.
- **Retrieval by Range**: Supports efficient retrieval of messages within a timestamp range using an inorder traversal.
- **Scalability and Performance**: Designed to handle high concurrency and large datasets efficiently.']

