import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class TransactionProcessor {

    private static final Logger logger = Logger.getLogger(TransactionProcessor.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final String EXTERNAL_SERVICE_URL = "http://external-service/validate";

    public static class SummaryReport {
        double totalAmount;
        double averageAmount;
        long flaggedTransactionsCount;
        Map<String, Long> transactionsByStatus;

        // Constructor
        public SummaryReport() {
            this.totalAmount = 0.0;
            this.averageAmount = 0.0;
            this.flaggedTransactionsCount = 0;
            this.transactionsByStatus = new HashMap<>();
            transactionsByStatus.put("verified", 0L);
            transactionsByStatus.put("unverified", 0L);
        }

        // Method to add transaction details
        public void updateReport(double amount, boolean isVerified, boolean flagged) {
            totalAmount += amount;
            if (flagged) flaggedTransactionsCount++;
            String status = isVerified ? "verified" : "unverified";
            transactionsByStatus.put(status, transactionsByStatus.get(status) + 1);
        }

        // Calculate average amount
        public void calculateAverage(int transactionCount) {
            if (transactionCount > 0) {
                this.averageAmount = totalAmount / transactionCount;
            }
        }

        @Override
        public String toString() {
            return "SummaryReport{" +
                    "totalAmount=" + totalAmount +
                    ", averageAmount=" + averageAmount +
                    ", flaggedTransactionsCount=" + flaggedTransactionsCount +
                    ", transactionsByStatus=" + transactionsByStatus +
                    '}';
        }
    }

    // Method to process CSV file
    public static SummaryReport processCSV(String filePath, double threshold, Date startDate, Date endDate, String transactionType) {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        BlockingQueue<Transaction> retryQueue = new LinkedBlockingQueue<>();
        long totalTransactions = 0;

        try (BufferedReader reader = Files.newBufferedReader(Paths.get(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] fields = line.split(",");

                if (!isValidTransaction(fields, startDate, endDate, transactionType)) continue;

                Transaction transaction = new Transaction(fields);
                Callable<Boolean> task = () -> verifyAndProcess(transaction, threshold, retryQueue);

                executor.submit(task).handle((result, throwable) -> {
                    if (throwable != null) {
                        logger.log(Level.WARNING, "Failed to process transaction: " + transaction.id, throwable);
                        retryQueue.offer(transaction);  // Queue for retry
                    }
                    return result;
                });
            }

        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading file", e);
        }

        executor.shutdown();

        while (!retryQueue.isEmpty()) {  // Handle retries
            Transaction transaction = retryQueue.poll();
            if (transaction != null) {
                for (int i = 0; i < MAX_RETRIES; i++) {
                    try {
                        verifyAndProcess(transaction, threshold, retryQueue);
                        break;
                    } catch (Exception e) {
                        logger.log(Level.WARNING, "Retry failed for transaction: " + transaction.id, e);
                    }
                }
            }
        }

        SummaryReport report = new SummaryReport();
        // Logic to update the report with results from processed transactions
        return report;
    }

    private static boolean isValidTransaction(String[] fields, Date startDate, Date endDate, String transactionType) {
        try {
            Date date = new SimpleDateFormat("yyyy-MM-dd").parse(fields[0]);
            if ((startDate != null && date.before(startDate)) || (endDate != null && date.after(endDate))) return false;
            if (transactionType != null && !fields[2].equals(transactionType)) return false;
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Invalid transaction format", e);
            return false;
        }
        return true;
    }

    private static boolean verifyAndProcess(Transaction transaction, double threshold, BlockingQueue<Transaction> retryQueue) throws Exception {
        // Simulate external service call
        boolean isValid = simulateExternalVerification(transaction);

        if (!isValid || transaction.amount > threshold) {
            logger.log(Level.WARNING, "Transaction flagged: ID=" + transaction.id);
            return false;
        }

        transaction.isVerified = true;  // Mark as verified for simplicity
        return true;
    }

    private static boolean simulateExternalVerification(Transaction transaction) throws InterruptedException {
        Random random = new Random();
        if (random.nextBoolean()) { // Simulate possible failure
            Thread.sleep(100);  // Simulate network delay
            return true;  // Assume verification success in this simulation
        } else {
            throw new RuntimeException("Validation failed");
        }
    }

    private static class Transaction {
        String id;
        double amount;
        boolean isVerified;

        Transaction(String[] fields) {
            id = fields[1];
            amount = Double.parseDouble(fields[3]);
            isVerified = false;  // Default unverified
        }
    }
}
