    if (next_free_index < MAX_DATA_POINTS) {
        SensorData* data = memory_pool[next_free_index++];
        pthread_mutex_unlock(&memory_lock);
        return data;
    } else {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Memory pool exhausted
    }
}

void release_data_point(SensorData* data) {
    pthread_mutex_lock(&memory_lock);
    next_free_index--;
    if (next_free_index >= 0) {
        memory_pool[next_free_index] = data;
    }
    pthread_mutex_unlock(&memory_lock);
}

void update_sliding_window(SensorData* new_data) {
    sliding_window[window_end] = new_data;
    window_end = (window_end + 1) % WINDOW_SIZE;
    if (window_end == window_start) { // Buffer is full, remove oldest data
        SensorData* old_data = sliding_window[window_start];
        release_data_point(old_data);
        window_start = (window_start + 1) % WINDOW_SIZE;
    }
}

void add_sensor_data(int sensor_id, float temperature, int humidity, float pressure, long offset, int key) {
    SensorData* data = get_next_data_point();
    if (!data) return;

    time_t now = time(NULL);
    data->timestamp = (long)now;
    data->sensor_id = sensor_id;
    data->temperature = temperature;
    data->humidity = humidity;
    data->pressure = pressure;
    data->offset = offset;
    data->key = key;

    update_sliding_window(data);

    // External logging system placeholder
    printf("Data added: %ld, %d, %.2f, %d, %.1f\n", now, sensor_id, temperature, humidity, pressure);
}

void simulate_data_stream() {
    srand(time(NULL));
    for (int i = 0; i < MAX_DATA_POINTS; ++i) {
        int sensor_id = rand() % 100;
        float temperature = TEMP_RANGE_LOW + ((float)rand() / RAND_MAX * (TEMP_RANGE_HIGH - TEMP_RANGE_LOW));
        int humidity = HUMIDITY_RANGE_LOW + (rand() % (HUMIDITY_RANGE_HIGH - HUMIDITY_RANGE_LOW + 1));
        float pressure = 950.0f + ((float)rand() / RAND_MAX * 105.0f);
        long offset = rand();
        int key = rand() % 100;

        add_sensor_data(sensor_id, temperature, humidity, pressure, offset, key);

        // Sleep to simulate real-time data streaming
        usleep(10000); // 10 ms
    }
}

void export_to_csv(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fprintf(file, "Timestamp,Sensor ID,Temperature,Humidity,Pressure,Offset,Key\n");

    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < next_free_index; ++i) {
        SensorData* data = memory_pool[i];
        if (data) {
            fprintf(file, "%ld,%d,%.2f,%d,%.1f,%ld,%d\n", data->timestamp, data->sensor_id, data->temperature,
                    data->humidity, data->pressure, data->offset, data->key);
        }
    }
    pthread_mutex_unlock(&memory_lock);

    fclose(file);
}

int main() {
    init_memory_pool();
    simulate_data_stream();

    export_to_csv("sensor_data.csv");

    // Free all allocated memory
    for (int i = 0; i < MAX_DATA_POINTS; ++i) {
        if (memory_pool[i]) {
            free(memory_pool[i]);
        }
    }

