['Here is a C implementation for an LRU cache using a hash table combined with a doubly linked list, including features like dynamic resizing, thread safety, efficient iteration, logging, and optimization:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for a cache entry
typedef struct CacheEntry {
    char *key;
    void *value;
    time_t access_time;
    int usage_count;
    struct CacheEntry *prev, *next;
} CacheEntry;

// Define the structure for the doubly linked list node
typedef struct DListNode {
    CacheEntry *entry;
    struct DListNode *prev, *next;
} DListNode;

// Define the hash table entry
typedef struct HashTableEntry {
    char *key;
    DListNode *dlist_node;
} HashTableEntry;

// Define the LRU cache structure
typedef struct LRUCache {
    size_t capacity;
    size_t count;
    size_t bucket_count;
    HashTableEntry **hash_table;
    DListNode *head, *tail;
    pthread_mutex_t lock;
    // Additional fields for logging can be added here if needed
} LRUCache;

// Function prototypes
LRUCache* lru_cache_create(size_t capacity);
void lru_cache_destroy(LRUCache *cache);
int lru_cache_put(LRUCache *cache, const char *key, void *value);
void* lru_cache_get(LRUCache *cache, const char *key);
void lru_cache_remove(LRUCache *cache, const char *key);
static inline size_t hash_function(const char *key, size_t bucket_count);
static DListNode* create_dlist_node(CacheEntry *entry);
static void destroy_dlist_node(DListNode *node);
static CacheEntry* create_cache_entry(const char *key, void *value);
static void update_access_time_and_usage(LRUCache *cache, CacheEntry *entry);
static void move_to_front(DListNode *node);
static DListNode* remove_least_recently_used(LRUCache *cache);
static void resize_hash_table_if_needed(LRUCache *cache);

// Implementations

LRUCache* lru_cache_create(size_t capacity) {
    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->capacity = capacity;
    cache->count = 0;
    cache->bucket_count = next_prime(capacity); // Use a prime number for bucket count
    cache->hash_table = (HashTableEntry**)calloc(cache->bucket_count, sizeof(HashTableEntry*));

    if (!cache->hash_table) {
        free(cache);
        return NULL;
    }

    cache->head = create_dlist_node(NULL);
    cache->tail = create_dlist_node(NULL);
    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;

    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void lru_cache_destroy(LRUCache *cache) {
    if (!cache) return;

    pthread_mutex_lock(&cache->lock);

    DListNode *current = cache->head->next;
    while (current != cache->tail) {
        DListNode *temp = current;
        current = current->next;
        destroy_dlist_node(temp);
    }

    for (size_t i = 0; i < cache->bucket_count; ++i) {
        if (cache->hash_table[i]) {
            free(cache->hash_table[i]->key);
            free(cache->hash_table[i]);
        }
    }

    free(cache->hash_table);
    destroy_dlist_node(cache->head);
    destroy_dlist_node(cache->tail);

    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int lru_cache_put(LRUCache *cache, const char *key, void *value) {
    if (!cache || !key) return -1;

    pthread_mutex_lock(&cache->lock);

    size_t index = hash_function(key, cache->bucket_count);
    HashTableEntry *entry = cache->hash_table[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            CacheEntry *cached_entry = entry->dlist_node->entry;
            cached_entry->value = value;
            update_access_time_and_usage(cache, cached_entry);
            pthread_mutex_unlock(&cache->lock);
            return 1; // Updated existing entry
        }
        entry = entry->next;
    }

    if (cache->count == cache->capacity) {
        remove_least_recently_used(cache);
    }

    CacheEntry *new_entry = create_cache_entry(key, value);
    DListNode *dlist_node = create_dlist_node(new_entry);

    new_entry->prev = dlist_node;
    new_entry->next = NULL;

    HashTableEntry *hash_entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    hash_entry->key = strdup(key); // Deep copy of key
    hash_entry->dlist_node = dlist_node;

    dlist_node->entry = new_entry;

    move_to_front(dlist_node);

    if (!cache->hash_table[index]) {
        cache->hash_table[index] = hash_entry;
        hash_entry->next = NULL;
    } else {
        hash_entry->next = cache->hash_table[index];
        cache->hash_table[index] = hash_entry;
    }

    ++(cache->count);

    resize_hash_table_if_needed(cache);

    pthread_mutex_unlock(&cache->lock);
    return 0; // Inserted new entry
}

void* lru_cache_get(LRUCache *cache, const char *key) {
    if (!cache || !key) return NULL;

    pthread_mutex_lock(&cache->lock);

    size_t index = hash_function(key, cache->bucket_count);
    HashTableEntry *entry = cache->hash_table[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            CacheEntry *cached_entry = entry->dlist_node->entry;
            update_access_time_and_usage(cache, cached_entry);

            move_to_front(entry->dlist_node);

            pthread_mutex_unlock(&cache->lock);
            return cached_entry->value; // Return value
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Key not found
}

void lru_cache_remove(LRUCache *cache, const char *key) {
    if (!cache || !key) return;

    pthread_mutex_lock(&cache->lock);

    size_t index = hash_function(key, cache->bucket_count);
    HashTableEntry *entry = cache->hash_table[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            DListNode *dlist_node = entry->dlist_node;

            // Remove from the doubly linked list
            dlist_node->prev->next = dlist_node->next;
            dlist_node->next->prev = dlist_node->prev;

            if (entry->dlist_node == cache->head->next) {
                cache->head->next = dlist_node->next; // head of the list
            }

            free(entry->key);
            free(dlist_node);
            free(entry);

            --(cache->count);

            pthread_mutex_unlock(&cache->lock);
            return;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Helper functions

static inline size_t hash_function(const char *key, size_t bucket_count) {
    // Simple hash function (djb2)
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % bucket_count;
}

static DListNode* create_dlist_node(CacheEntry *entry) {
    DListNode *node = (DListNode*)malloc(sizeof(DListNode));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

static void destroy_dlist_node(DListNode *node) {
    if (node) {
        free(node);
    }
}

static CacheEntry* create_cache_entry(const char *key, void *value) {
    CacheEntry *entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->key = strdup(key); // Deep copy of key
    entry->value = value;
    entry->access_time = time(NULL);
    entry->usage_count = 0;
    return entry;
}

static void update_access_time_and_usage(LRUCache *cache, CacheEntry *entry) {
    pthread_mutex_lock(&cache->lock);

    entry->access_time = time(NULL); // Update access time
    ++(entry->usage_count); // Increment usage count

    move_to_front(entry->prev); // Move the node to front in the list

    pthread_mutex_unlock(&cache->lock);
}

static void move_to_front(DListNode *node) {
    if (!node || !node->entry) return;

    DListNode *current = cache->head->next;
    while (current != cache->tail && current != node) {
        current = current->next;
    }

    if (current == node) return; // Already at the front

    // Remove node from its current position
    node->prev->next = node->next;
    node->next->prev = node->prev;

    // Insert node right after head
    node->next = cache->head->next;
    node->prev = cache->head;

    cache->head->next->prev = node;
    cache->head->next = node;
}

static DListNode* remove_least_recently_used(LRUCache *cache) {
    if (!cache || cache->count == 0) return NULL;

    DListNode *node_to_remove = cache->tail->prev;
    if (node_to_remove == cache->head) return NULL; // No node to remove

    HashTableEntry *entry = node_to_remove->entry->next;

    while (entry) {
        if (strcmp(entry->key, node_to_remove->entry->key) == 0) {
            entry->dlist_node = NULL;
            break;
        }
        entry = entry->next;
    }

    node_to_remove->prev->next = node_to_remove->next;
    node_to_remove->next->prev = node_to_remove->prev;

    free(node_to_remove->entry->key);
    free(node_to_remove->entry);

    free(node_to_remove);

    --(cache->count);

    return node_to_remove; // Return the removed node
}

static void resize_hash_table_if_needed(LRUCache *cache) {
    float load_factor = (float)cache->count / cache->bucket_count;
    if (load_factor > 0.7) { // Resize threshold
        size_t new_bucket_count = next_prime(cache->capacity * 2);

        HashTableEntry **new_hash_table = (HashTableEntry**)calloc(new_bucket_count, sizeof(HashTableEntry*));

        for (size_t i = 0; i < cache->bucket_count; ++i) {
            HashTableEntry *entry = cache->hash_table[i];

            while (entry) {
                size_t new_index = hash_function(entry->key, new_bucket_count);

                if (!new_hash_table[new_index]) {
                    new_hash_table[new_index] = entry;
                    new_hash_table[new_index]->next = NULL;
                } else {
                    HashTableEntry *temp = new_hash_table[new_index];
                    while (temp->next) {
                        temp = temp->next;
                    }
                    temp->next = entry;
                }

                entry = entry->next;
            }
        }

        free(cache->hash_table);
        cache->hash_table = new_hash_table;
        cache->bucket_count = new_bucket_count;
    }
}

// Utility function to find the next prime number greater than or equal to n
static size_t next_prime(size_t n) {
    if (n <= 1) return 2;

    while (1) {
        int is_prime = 1;
        for (size_t i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                is_prime = 0;
                break;
            }
        }

        if (is_prime) return n;

        ++n;
    }
}
