#define INITIAL_HASH_TABLE_SIZE 1048576 // Start at 2^20
#define MAX_LOAD_FACTOR 0.8

typedef struct {
    char* key;
    char* value;
    time_t timestamp;
} Setting;

typedef struct HashNode {
    Setting setting;
    struct HashNode* next;
} HashNode;

