    HashNode** buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock; // For thread-safe operations
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->buckets = calloc(initial_size, sizeof(HashNode*));
    ht->size = initial_size;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned long hash_function(const char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % INITIAL_HASH_TABLE_SIZE;
}

void insert_setting(HashTable* ht, Setting setting) {
    pthread_mutex_lock(&ht->lock);

    unsigned long index = hash_function(setting.key);
    HashNode* node = malloc(sizeof(HashNode));
    node->setting = setting;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;

