    fclose(file);
    yaml_parser_delete(&parser);
    return NULL;
}

void parse_yaml_files(char** filenames, size_t num_files) {
    pthread_t threads[num_files];

    for (size_t i = 0; i < num_files; ++i) {
        if(pthread_create(&threads[i], NULL, process_yaml_file, (void*)filenames[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_files; ++i) {
