#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10000
#define SESSION_DURATION 3600 // Session duration in seconds
#define RANDOM_OFFSET_RANGE 300 // Random offset range

typedef struct {
    char sessionID[256];
    time_t loginTime;
    time_t lastActivity;
    time_t expirationTime;
} SessionRecord;

typedef struct HashTableNode {
    SessionRecord record;
    struct HashTableNode* next;
} HashTableNode;

typedef struct {
    HashTableNode** buckets;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicHashTable;

unsigned long hashFunction(const char* sessionID) {
    unsigned long hash = 5381;
    int c;
    while ((c = *sessionID++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

DynamicHashTable* initHashTable() {
    DynamicHashTable* table = malloc(sizeof(DynamicHashTable));
    if (!table) return NULL;

    table->capacity = INITIAL_CAPACITY;
    table->buckets = calloc(table->capacity, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void resizeHashTable(DynamicHashTable* table, size_t new_capacity) {
    HashTableNode** old_buckets = table->buckets;
    size_t old_capacity = table->capacity;

    table->buckets = calloc(new_capacity, sizeof(HashTableNode*));
    if (!table->buckets) return;

    for (size_t i = 0; i < old_capacity; ++i) {
        HashTableNode* node = old_buckets[i];
        while (node) {
            HashTableNode* next = node->next;
            unsigned long index = hashFunction(node->record.sessionID) % new_capacity;

            node->next = table->buckets[index];
            table->buckets[index] = node;

            node = next;
        }
    }

    free(old_buckets);
    table->capacity = new_capacity;
}

void insertSession(DynamicHashTable* table, SessionRecord record) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hashFunction(record.sessionID) % table->capacity;

    HashTableNode* newNode = malloc(sizeof(HashTableNode));
    if (!newNode) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    memcpy(&newNode->record, &record, sizeof(SessionRecord));
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->lock);

    // Resize if load factor is too high
    size_t count = 0;
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            ++count;
            node = node->next;
        }
    }

    if ((double)count / table->capacity > 0.7) {
        resizeHashTable(table, table->capacity * 2);
    }
}

void freeHashTable(DynamicHashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void initializeSessionRecord(SessionRecord* record, const char* sessionID) {
    strcpy(record->sessionID, sessionID);

    time_t now = time(NULL);
    record->loginTime = now - (rand() % 86400); // Random login time within the last day

    record->lastActivity = now;

    int randomOffset = rand() % RANDOM_OFFSET_RANGE;
    record->expirationTime = now + SESSION_DURATION + randomOffset;
}

void allocateAndInitializeArrays(long** offsetArray, int** keyArray, size_t count) {
    *offsetArray = malloc(count * sizeof(long));
    if (!*offsetArray) return;

    for (size_t i = 0; i < count; ++i) {
        (*offsetArray)[i] = rand() % 100000;
    }

    *keyArray = malloc(count * sizeof(int));
    if (!*keyArray) {
        free(*offsetArray);
        return;
    }
}

typedef struct {
    int value;
} Record;

void allocateAndInitializeRecords(Record** records, size_t count) {
    *records = malloc(count * sizeof(Record));
    if (!*records) return;

    for (size_t i = 0; i < count; ++i) {
        (*records)[i].value = rand() % 100;
    }
}
