} record;

int initialize_data_structures(long n, int min_value, int max_value, 
                               long **offsets_array, int **keys_array, record ***records_array) {

    if (n <= 0 || offsets_array == NULL || keys_array == NULL || records_array == NULL) {
        return -1; // Invalid input
    }

    // Step 1: Allocate and initialize memory for arrays
    *offsets_array = (long *)calloc(n, sizeof(long));
    if (*offsets_array == NULL) goto cleanup;

    *keys_array = (int *)malloc(n * sizeof(int));
    if (*keys_array == NULL) goto cleanup;

    *records_array = (record **)malloc(n * sizeof(record *));
    if (*records_array == NULL) goto cleanup;

    // Seed random number generator
    srand((unsigned int)time(NULL));

    for (long i = 0; i < n; ++i) {
        (*offsets_array)[i] = rand() % 10000; // Assign some offset values

        uint32_t unique_key = generate_unique_key();
        while (unique_key == 0 || check_duplicate(*keys_array, n, unique_key)) { 
            unique_key = generate_unique_key(); 
        }
        (*keys_array)[i] = unique_key;

        record *rec = (record *)malloc(sizeof(record));
        if (rec == NULL) goto cleanup;

        rec->value = rand() % (max_value - min_value + 1) + min_value;
        rec->offset_ptr = &((*offsets_array)[i]);
        (*records_array)[i] = rec;
    }

    // Step 2: Sort records based on offsets
    qsort(*records_array, n, sizeof(record *), compare_records);

    return 0; // Success

cleanup:
    if (offsets_array && *offsets_array) free(*offsets_array);
    if (keys_array && *keys_array) free(*keys_array);
    for (long i = 0; i < n; ++i) {
        if ((*records_array)[i]) free((*records_array)[i]);
    }
    if (*records_array) free(*records_array);
    return -1; // Failure

// Helper function to check for duplicate keys
int check_duplicate(int *keys, long size, uint32_t key_to_check) {
    for (long i = 0; i < size; ++i) {
        if (keys[i] == key_to_check) {
            return 1;
        }
    }
    return 0;
}

// Comparison function for qsort
int compare_records(const void *a, const void *b) {
    record **recA = (record **)a;
    record **recB = (record **)b;

    if ((*recA)->offset_ptr < (*recB)->offset_ptr)
        return -1;
    if ((*recA)->offset_ptr > (*recB)->offset_ptr)
        return 1;
    return 0;
}
