    Node** buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash(int key, size_t size) {
    return (unsigned long)key % size;
}

HashTable* initializeHashTable(size_t initialSize) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(initialSize, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = initialSize;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void resizeHashTable(HashTable* table);

int insertSession(HashTable* table, int sessionID, time_t loginTime, time_t lastActivityTimestamp) {
    if (table == NULL || (double)table->count / table->size >= LOAD_FACTOR) {
        resizeHashTable(table);
    }

    unsigned long index = hash(sessionID, table->size);

    pthread_mutex_lock(&table->lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    newNode->data.sessionID = sessionID;
    newNode->data.loginTime = loginTime;
    newNode->data.lastActivityTimestamp = lastActivityTimestamp;
    time_t currentTime = time(NULL);
    int offset = rand() % 3600; // Random offset within an hour
    newNode->data.sessionExpiration = currentTime + (7200 + offset); // Predefined duration of 2 hours

    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    table->count++;

    pthread_mutex_unlock(&table->lock);

    return 0;
}

void resizeHashTable(HashTable* table) {
    size_t newSize = table->size * 2;
    Node** newBuckets = calloc(newSize, sizeof(Node*));
    if (!newBuckets) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* nextNode = node->next;
            unsigned long newIndex = hash(node->data.sessionID, newSize);

            node->next = newBuckets[newIndex];
            newBuckets[newIndex] = node;

            node = nextNode;
        }
    }

    free(table->buckets);
    table->buckets = newBuckets;
    table->size = newSize;
}

void cleanupHashTable(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* nextNode = node->next;
            free(node);
            node = nextNode;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

