HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = calloc(size, sizeof(Setting *));
    return table;
}

void insert_setting(HashTable *table, const char *key, const char *value) {
    uint64_t hash = hash_function(key);
    size_t index = hash % table->size;

    Setting *new_setting = malloc(sizeof(Setting));
    new_setting->key = strdup(key);
    new_setting->value = strdup(value);
    new_setting->timestamp = time(NULL);
    new_setting->next = table->buckets[index];
    table->buckets[index] = new_setting;
}

const char* get_setting(const HashTable *table, const char *key) {
    uint64_t hash = hash_function(key);
    size_t index = hash % table->size;

    Setting *setting = table->buckets[index];
    while (setting) {
        if (strcmp(setting->key, key) == 0)
            return setting->value;
        setting = setting->next;
    }
    return NULL;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        Setting *setting = table->buckets[i];
        while (setting) {
            Setting *temp = setting;
            setting = setting->next;
            free(temp->key);
            free(temp->value);
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

uint64_t hash_function(const char *key) {
    uint64_t hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

void render_footer_script_array(const char **keys, const char **scripts, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("<script id='%s'>\n%s\n</script>\n", keys[i], scripts[i]);
    }
}
