#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 20000
#define LOAD_FACTOR 0.75

typedef struct {
    int session_id;
    time_t login_time;
    time_t last_activity;
    time_t expiration;
} Session;

typedef struct Node {
    Session data;
    struct Node *next;
} Node;

typedef struct {
    Node **table;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

uint64_t hash(int session_id) {
    // Simple hash function for demonstration purposes
    return (uint64_t)session_id % INITIAL_SIZE;
}

HashTable* init_hash_table() {
    HashTable *hash_table = malloc(sizeof(HashTable));
    if (!hash_table) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    hash_table->capacity = INITIAL_SIZE;
    hash_table->size = 0;

    hash_table->table = calloc(hash_table->capacity, sizeof(Node*));
    if (!hash_table->table) {
        free(hash_table);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&hash_table->lock, NULL);

    return hash_table;
}

void resize_hash_table(HashTable *hash_table) {
    size_t new_capacity = hash_table->capacity * 2;
    Node **new_table = calloc(new_capacity, sizeof(Node*));
    if (!new_table) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < hash_table->capacity; ++i) {
        Node *node = hash_table->table[i];
        while (node) {
            Node *next_node = node->next;
            size_t new_index = hash(node->data.session_id) % new_capacity;

            node->next = new_table[new_index];
            new_table[new_index] = node;

            node = next_node;
        }
    }

    free(hash_table->table);
    hash_table->table = new_table;
    hash_table->capacity = new_capacity;
}

void insert_session(HashTable *hash_table, Session session) {
    pthread_mutex_lock(&hash_table->lock);

    if ((float)hash_table->size / hash_table->capacity >= LOAD_FACTOR) {
        resize_hash_table(hash_table);
    }

    size_t index = hash(session.session_id) % hash_table->capacity;
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&hash_table->lock);
        exit(EXIT_FAILURE);
    }
    new_node->data = session;
    new_node->next = hash_table->table[index];
    hash_table->table[index] = new_node;

    hash_table->size++;

    pthread_mutex_unlock(&hash_table->lock);
}

void free_hash_table(HashTable *hash_table) {
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        Node *node = hash_table->table[i];
        while (node) {
            Node *next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(hash_table->table);
    pthread_mutex_destroy(&hash_table->lock);
    free(hash_table);
}

void initialize_sessions(HashTable *hash_table, int num_sessions) {
    srand(time(NULL));
    for (int i = 0; i < num_sessions; ++i) {
        Session session;
        session.session_id = rand() % 1000000;
        session.login_time = time(NULL) - rand() % 3600;
        session.last_activity = session.login_time + rand() % 600;
        session.expiration = session.last_activity + (rand() % 1800 + 1800);

        insert_session(hash_table, session);
    }
}

void* allocate_and_initialize_arrays(void* arg) {
    size_t num_elements = *(size_t*)arg;

    long *long_array = malloc(num_elements * sizeof(long));
    if (!long_array) {
        perror("Failed to allocate memory for long array");
        exit(EXIT_FAILURE);
    }

    int *int_keys = malloc(num_elements * sizeof(int));
    if (!int_keys) {
        free(long_array);
        perror("Failed to allocate memory for int keys");
        exit(EXIT_FAILURE);
    }

    Record *records = malloc(num_elements * sizeof(Record));
    if (!records) {
        free(long_array);
        free(int_keys);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        long_array[i] = rand() % 100000;
        int_keys[i] = rand() % 10000;
        records[i].value = rand() % 1000;
    }

    return malloc(sizeof(long*) * 3 + sizeof(int*) + sizeof(Record*));
}
