#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct FileEntry {
    char *name;
    size_t size;
    struct FileEntry *next;
} FileEntry;

typedef struct Directory {
    FileEntry *head;
    pthread_mutex_t lock;
} Directory;

// Initialize a new directory
Directory* create_directory() {
    Directory *dir = (Directory*)malloc(sizeof(Directory));
    dir->head = NULL;
    pthread_mutex_init(&dir->lock, NULL);
    return dir;
}

// Add a file entry to the directory
void add_entry(Directory *dir, const char *name, size_t size) {
    FileEntry *new_entry = (FileEntry*)malloc(sizeof(FileEntry));
    new_entry->name = strdup(name);
    new_entry->size = size;

    pthread_mutex_lock(&dir->lock);

    // Insert at the beginning for simplicity
    new_entry->next = dir->head;
    dir->head = new_entry;

    pthread_mutex_unlock(&dir->lock);
}

// Free all entries and the directory itself
void free_directory(Directory *dir) {
    FileEntry *current, *tmp;

    pthread_mutex_lock(&dir->lock);

    current = dir->head;
    while (current != NULL) {
        tmp = current;
        current = current->next;
        free(tmp->name);
        free(tmp);
    }

    pthread_mutex_unlock(&dir->lock);
    pthread_mutex_destroy(&dir->lock);
    free(dir);
}

// Print all entries in the directory
void print_entries(Directory *dir) {
    FileEntry *current;

    pthread_mutex_lock(&dir->lock);

    current = dir->head;
    while (current != NULL) {
        printf("Name: %s, Size: %zu\n", current->name, current->size);
        current = current->next;
    }

    pthread_mutex_unlock(&dir->lock);
}

// Example usage
int main() {
    Directory *dir = create_directory();

    add_entry(dir, "file1.txt", 1024);
    add_entry(dir, "file2.txt", 2048);

    print_entries(dir);

    free_directory(dir);
    return 0;
}
```

