typedef struct {
    long offset;
    int key;
} record;

int allocate_and_initialize_records(size_t n, size_t m, long low, long high) {
    if (n == 0 || m == 0) {
        LOG_ERROR("Invalid input: n and m must be greater than zero.\n");
        return -1;
    }

    // Allocate memory for offsets
    long **offsets = malloc(n * sizeof(long *));
    if (!offsets) {
        LOG_ERROR("Failed to allocate memory for offset pointers.\n");
        return -1;
    }
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = malloc(m * sizeof(long));
        if (!offsets[i]) {
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(offsets[j]);
            }
            free(offsets);
            LOG_ERROR("Failed to allocate memory for offsets[%zu].\n", i);
            return -1;
        }
    }

    // Allocate memory for keys
    int **keys = malloc(n * sizeof(int *));
    if (!keys) {
        LOG_ERROR("Failed to allocate memory for key pointers.\n");
        free(offsets);
        return -1;
    }
    for (size_t i = 0; i < n; ++i) {
        keys[i] = malloc(m * sizeof(int));
        if (!keys[i]) {
            // Free previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free(keys[j]);
            }
            for (size_t j = 0; j < n; ++j) {
                free(offsets[j]);
            }
            free(offsets);
            free(keys);
            LOG_ERROR("Failed to allocate memory for keys[%zu].\n", i);
            return -1;
        }
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for records
    record *records = malloc(n * sizeof(record));
    if (!records) {
        LOG_ERROR("Failed to allocate memory for records.\n");
        free(offsets);
        for (size_t i = 0; i < n; ++i) {
            free(keys[i]);
        }
        free(keys);
        return -1;
    }

    // Initialize records
    for (size_t i = 0; i < n; ++i) {
        records[i].offset = low + rand() % (high - low + 1);
        records[i].key = i * m; // Example initialization

        // Distribute offset and key to respective arrays
        for (size_t j = 0; j < m; ++j) {
            offsets[i][j] = records[i].offset;
            keys[i][j] = records[i].key + j; // Example distribution pattern
        }
    }

    // Validate offsets
    for (size_t i = 0; i < n; ++i) {
        if (!(records[i].offset >= low && records[i].offset <= high)) {
            LOG_ERROR("Offset validation failed for record %zu: offset %ld out of range [%ld, %ld]\n", 
                      i, records[i].offset, low, high);
            free(records);
            free(offsets);
            for (size_t j = 0; j < n; ++j) {
                free(keys[j]);
            }
            free(keys);
            return -1;
        }
    }

    // Placeholder for integrating with existing systems
    // e.g., database connectors, network libraries

    // Return success
    return 0;
}

int main() {
