from datetime import datetime

#define DEFAULT_PATH "default/path"
#define MAX_DIR_NAME_LENGTH 255
#define RANDOM_SEED 12345
#define INVALID_CHAR_PATTERN r'[^a-zA-Z0-9_-]'

void sanitize_and_truncate(char *name, size_t max_length) {
    for (size_t i = 0; name[i]; ++i) {
        if (!isalnum(name[i]) && name[i] != '_' && name[i] != '-') {
            name[i] = '_';
        }
    }
    if (strlen(name) > max_length - 1) {
        name[max_length - 1] = '\0';
    }
}

void copy_directory(const char *src, const char *dst) {
    for (const auto &entry : os.scandir(src)) {
        std::string src_path = entry.path();
        std::string dst_path = dst + "/" + entry.name();

        if (entry.is_dir()) {
            mkdir(dst_path.c_str(), 0777);
            copy_directory(src_path.c_str(), dst_path.c_str());
        } else {
            shutil.copy2(src_path, dst_path);
        }
    }
}

int process_directory(const char *dir_path) {
    srand(RANDOM_SEED);

    if (!dir_path || strlen(dir_path) == 0) {
        dir_path = DEFAULT_PATH;
    }

    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    int file_count = 0;
    struct dirent *entry;
    std::string last_modified_file;
    time_t latest_mod_time = 0;

    while ((entry = readdir(dir)) != nullptr) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        std::string path = dir_path + "/" + entry->d_name;
        struct stat file_stat;
        if (stat(path.c_str(), &file_stat) == -1) {
            perror("Failed to get file status");
            closedir(dir);
            return -1;
        }

        if (S_ISREG(file_stat.st_mode)) {
            file_count++;
            if (latest_mod_time < file_stat.st_mtime) {
                latest_mod_time = file_stat.st_mtime;
                last_modified_file = entry->d_name;
            }
        }
    }

    closedir(dir);

    int random_int = rand() % 100000;
    time_t mod_timestamp = (time(nullptr));
    char unique_id[20];
    sprintf(unique_id, "%d-%d-%ld", file_count, random_int, mod_timestamp);

    std::string new_subdir_name = "default_name";
    if (!last_modified_file.empty()) {
        std::smatch match;
        if (std::regex_search(last_modified_file, match, std::regex(INVALID_CHAR_PATTERN))) {
            last_modified_file = std::regex_replace(last_modified_file, std::regex(INVALID_CHAR_PATTERN), "_");
        }
        new_subdir_name = last_modified_file.substr(0, 15);
    }

    char safe_dir_path[MAX_DIR_NAME_LENGTH + 1];
    strncpy(safe_dir_path, dir_path, MAX_DIR_NAME_LENGTH);
    sanitize_and_truncate(safe_dir_path, sizeof(safe_dir_path));

    std::string backup_path = safe_dir_path + "/" + unique_id;
    mkdir(backup_path.c_str(), 0777);

    if (copy_directory(dir_path, backup_path.c_str()) == -1) {
        perror("Failed to copy directory");
        return -1;
    }

    printf("Backup created at %s\n", backup_path.c_str());
    return 0;
}
