#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_CONCURRENT_CALLS 10

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    long highest_value;
    long lowest_value;
    double average_value;
} metadata;

typedef struct {
    pthread_mutex_t lock;
    sem_t semaphore;
    int pending_requests;
    // Add more fields if necessary for additional functionality
} request_manager;

request_manager manager = { .lock = PTHREAD_MUTEX_INITIALIZER, .semaphore = SEM_INIT(0), .pending_requests = 0 };

void serialize_data(metadata *meta, const char *filename);
int deserialize_data(metadata **meta, const char *filename);

metadata* initialize_data(size_t num_records, long value_range_min, long value_range_max, int storage_method) {
    if (num_records == 0 || value_range_min >= value_range_max)
        return NULL;

    sem_wait(&manager.semaphore);

    pthread_mutex_lock(&manager.lock);
    manager.pending_requests++;
    pthread_mutex_unlock(&manager.lock);

    metadata *meta = malloc(sizeof(metadata));
    if (!meta) {
        perror("Failed to allocate memory for metadata");
        goto cleanup;
    }

    meta->offsets = calloc(num_records, sizeof(long));
    meta->keys = calloc(num_records, sizeof(int));
    meta->records = calloc(num_records, sizeof(record));
    if (!meta->offsets || !meta->keys || !meta->records) {
        perror("Failed to allocate memory for data structures");
        goto cleanup;
    }

    long range = value_range_max - value_range_min + 1;
    meta->num_records = num_records;
    meta->highest_value = value_range_min;
    meta->lowest_value = value_range_max;

    long current_value = value_range_min;
    double sum_values = 0.0;
    for (size_t i = 0; i < num_records; ++i) {
        do {
            current_value = rand() % range + value_range_min;
        } while (i > 0 && meta->records[i - 1].value == current_value);

        meta->records[i].value = current_value;
        sum_values += current_value;

        if (current_value < meta->lowest_value)
            meta->lowest_value = current_value;
        if (current_value > meta->highest_value)
            meta->highest_value = current_value;
    }

    meta->average_value = sum_values / num_records;

    const char *filename = "data_backup.dat";
    if (storage_method == 1) { // In-memory
        serialize_data(meta, filename);
    } else { // Disk-based
        int result = deserialize_data(&meta, filename);
        if (result != 0 && meta->records) {
            free(meta->offsets);
            free(meta->keys);
            free(meta->records);
            meta = NULL;
        }
    }

cleanup:
    pthread_mutex_lock(&manager.lock);
    manager.pending_requests--;
    sem_post(&manager.semaphore); // Signal that a request has been completed
    pthread_mutex_unlock(&manager.lock);

    if (meta == NULL) {
        printf("Error: Failed to initialize data structures\n");
    } else {
        printf("Data initialized successfully\n");
    }

    return meta;
}

void serialize_data(metadata *meta, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(meta, sizeof(metadata), 1, file);
    fclose(file);
}

int deserialize_data(metadata **meta, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t meta_size = sizeof(metadata);
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);

    if (file_size != meta_size) {
        fprintf(stderr, "Invalid file size for deserialization\n");
        fclose(file);
        return -1;
    }

    *meta = malloc(meta_size);
    if (!*meta) {
        perror("Failed to allocate memory for deserialized metadata");
        fclose(file);
        return -1;
    }

    fseek(file, 0, SEEK_SET);
    fread(*meta, meta_size, 1, file);

    fclose(file);
    return 0;
}

int main() {
    sem_init(&manager.semaphore, 0, MAX_CONCURRENT_CALLS);

    // Example usage
    metadata *data = initialize_data(100, 10, 200, 0); // Disk-based storage
    if (data) {
        free(data->offsets);
        free(data->keys);
        free(data->records);
        free(data);
    }

    sem_destroy(&manager.semaphore);

    return 0;
}
