#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_CONCURRENT_THREADS 10

typedef struct {
    int value;
} record;

typedef struct {
    size_t total_records;
    int highest_value;
    int lowest_value;
    float average_value;
} metadata;

typedef struct {
    long* offset_array;
    int* key_array;
    record* records;
    metadata meta;
} data_storage;

sem_t semaphore;

data_storage* init_data_storage(size_t num_offsets, size_t num_keys, size_t num_records,
                                int min_val, int max_val) {
    sem_wait(&semaphore);

    data_storage* storage = (data_storage*)malloc(sizeof(data_storage));
    if (!storage) {
        fprintf(stderr, "Failed to allocate memory for data_storage\n");
        return NULL;
    }

    // Allocate arrays
    storage->offset_array = (long*)calloc(num_offsets, sizeof(long));
    storage->key_array = (int*)calloc(num_keys, sizeof(int));
    storage->records = (record*)malloc(num_records * sizeof(record));

    if (!storage->offset_array || !storage->key_array || !storage->records) {
        fprintf(stderr, "Failed to allocate memory for data structures\n");
        free(storage->offset_array);
        free(storage->key_array);
        free(storage->records);
        free(storage);
        return NULL;
    }

    // Initialize records with unique random values
    int* used_values = (int*)calloc((max_val - min_val + 1), sizeof(int));
    if (!used_values) {
        fprintf(stderr, "Failed to allocate memory for tracking used values\n");
        free(storage->offset_array);
        free(storage->key_array);
        free(storage->records);
        free(storage);
        return NULL;
    }

    int total_sum = 0;
    storage->meta.total_records = num_records;
    storage->meta.highest_value = min_val - 1;
    storage->meta.lowest_value = max_val + 1;

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % (max_val - min_val + 1) + min_val;
        } while (used_values[value]);

        used_values[value] = 1;
        storage->records[i].value = value;

        if (value > storage->meta.highest_value)
            storage->meta.highest_value = value;
        if (value < storage->meta.lowest_value)
            storage->meta.lowest_value = value;

        total_sum += value;
    }

    // Calculate average
    storage->meta.average_value = (float)total_sum / num_records;

    free(used_values);

    sem_post(&semaphore);

    return storage;
}

void cleanup_data_storage(data_storage* storage) {
    if (!storage) return;

    sem_wait(&semaphore);

    if (storage->offset_array)
        free(storage->offset_array);
    if (storage->key_array)
        free(storage->key_array);
    if (storage->records)
        free(storage->records);

    free(storage);

    sem_post(&semaphore);
}

void serialize_data(const data_storage* storage, const char* filename) {
    // Serialization code goes here
}

data_storage* deserialize_data(const char* filename) {
    // Deserialization code goes here
    return NULL;
}

int main() {
    srand(time(NULL));
    sem_init(&semaphore, 0, MAX_CONCURRENT_THREADS);

    size_t num_offsets = 10;
    size_t num_keys = 5;
    size_t num_records = 100;
    int min_val = 1;
    int max_val = 50;

    data_storage* storage = init_data_storage(num_offsets, num_keys, num_records, min_val, max_val);
    if (storage) {
        // Use the initialized storage
        cleanup_data_storage(storage);
    }

    sem_destroy(&semaphore);

    return 0;
}
