import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.net.HttpURLConnection;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;

public class DistributedCacheManager {

    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private static final Logger logger = LoggerFactory.getLogger(DistributedCacheManager.class);
    private static final int MAX_RETRIES = 3;
    private final ScheduledExecutorService retryScheduler = Executors.newScheduledThreadPool(1);

    public static class CacheEntry {
        String key;
        String value;
        long timestamp;
        long version;

        CacheEntry(String key, String value, long timestamp, long version) {
            this.key = key;
            this.value = value;
            this.timestamp = timestamp;
            this.version = version;
        }
    }

    public void manageModuleDependencies(String moduleKey, String externalApiUrl) {
        retryScheduler.scheduleWithFixedDelay(() -> fetchAndUpdateVersion(moduleKey, externalApiUrl), 0, 10, TimeUnit.SECONDS);
    }

    private void fetchAndUpdateVersion(String moduleKey, String apiUrl) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try {
                HttpURLConnection connection = (HttpURLConnection) new java.net.URL(apiUrl).openConnection();
                connection.setRequestMethod("GET");
                int responseCode = connection.getResponseCode();

                if (responseCode == HttpURLConnection.HTTP_OK) {
                    BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8));
                    String inputLine;
                    StringBuilder content = new StringBuilder();

                    while ((inputLine = in.readLine()) != null) {
                        content.append(inputLine);
                    }

                    in.close();
                    JSONObject jsonResponse = new JSONObject(content.toString());
                    long latestVersion = jsonResponse.getLong("version");
                    updateCache(moduleKey, jsonResponse.getString("value"), latestVersion);
                    sendNotification("Update applied for " + moduleKey);

                    return;
                } else if (responseCode == HttpURLConnection.HTTP_TOO_MANY_REQUESTS) {
                    logger.warn("Rate limited when accessing API. Retrying...");
                }
            } catch (IOException e) {
                logger.error("Network or API error occurred: ", e);
                sendNotification("Issue with fetching updates for " + moduleKey);
            }

            if (attempt == MAX_RETRIES) {
                logger.error("Max retries reached for " + moduleKey + ". Failing operation.");
            }
        }
    }

    private synchronized void updateCache(String key, String value, long version) {
        CacheEntry entry = cache.get(key);

        if (entry == null || entry.version < version) {
            logger.info("Updating cache for key: " + key);
            cache.put(key, new CacheEntry(key, value, System.currentTimeMillis(), version));
        }
    }

    private void sendNotification(String message) {
        // Implement notification logic based on organizational policies
        logger.info("Sending notification: " + message);
    }

    public static void main(String[] args) {
        DistributedCacheManager manager = new DistributedCacheManager();
        String apiUrl = System.getenv("EXTERNAL_API_URL");
        if (apiUrl != null && !apiUrl.isEmpty()) {
            manager.manageModuleDependencies("example-module", apiUrl);
        } else {
            logger.error("API URL not provided. Exiting...");
        }
    }
}
```

