#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdint.h>

typedef struct record {
    int *int_value;
    int unique_key;
    struct record *next; // Pointer to the next record for linked list structure
} record;

// Pseudo-random number generator seed and range
uint32_t prng_seed = 0;
const int PRNG_RANGE_MIN = 1;
const int PRNG_RANGE_MAX = 1000000;

void seed_prng(uint32_t initial_seed) {
    prng_seed = initial_seed;
}

int pseudo_random_int() {
    prng_seed ^= prng_seed << 13;
    prng_seed ^= prng_seed >> 17;
    prng_seed ^= prng_seed << 5;
    return (prng_seed % (PRNG_RANGE_MAX - PRNG_RANGE_MIN + 1)) + PRNG_RANGE_MIN;
}

record *manage_memory(size_t offset_size, size_t key_array_size) {
    // Thread-safe mechanism for handling concurrent writes
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the arrays
    long *offsets = (long *)calloc(offset_size, sizeof(long));
    if (!offsets) return NULL;

    int *unique_keys = (int *)malloc(key_array_size * sizeof(int));
    if (!unique_keys) {
        free(offsets);
        return NULL;
    }

    bool *key_exists = calloc(key_array_size, sizeof(bool));
    if (!key_exists) {
        free(unique_keys);
        free(offsets);
        return NULL;
    }

    record *records_head = NULL;

    // Populate the offset array with pseudo-random values
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = pseudo_random_int();
    }

    // Seed PRNG for unique key initialization
    seed_prng((uint32_t)offsets[0]); 

    size_t record_count = 0;

    for (size_t i = 0; i < key_array_size; ++i) {
        pthread_mutex_lock(&mutex);

        int new_key = pseudo_random_int() % key_array_size;
        if (!key_exists[new_key]) { // Check for duplicates
            key_exists[new_key] = true;

            record *new_record = (record *)malloc(sizeof(record));
            if (!new_record) {
                pthread_mutex_unlock(&mutex);
                free(key_exists);
                free(unique_keys);
                free(offsets);
                return NULL;
            }

            new_record->int_value = malloc(sizeof(int));
            if (!new_record->int_value) {
                free(new_record);
                pthread_mutex_unlock(&mutex);
                free(key_exists);
                free(unique_keys);
                free(offsets);
                return NULL;
            }

            *new_record->int_value = pseudo_random_int();
            new_record->unique_key = new_key;
            new_record->next = records_head;
            records_head = new_record;

            record_count++;
        }

        pthread_mutex_unlock(&mutex);
    }

    // Cleanup
    free(key_exists);
    free(unique_keys);
    return records_head;
}

void free_records(record *head) {
    while (head != NULL) {
        record *temp = head;
        head = head->next;

        if (temp->int_value) {
            free(temp->int_value);
        }

        free(temp);
    }
}
```

