data_collection* create_data_collection() {
    data_collection *collection = malloc(sizeof(data_collection));
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->entries = malloc(collection->capacity * sizeof(data_entry *));
    return collection;
}

void resize_data_collection(data_collection *collection) {
    size_t new_capacity = collection->capacity * 2;
    data_entry **new_entries = realloc(collection->entries, new_capacity * sizeof(data_entry *));

    if (new_entries) {
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed while resizing.\n");
        exit(EXIT_FAILURE);
    }
}

int add_data_entry(data_collection *collection, const char *str, double val) {
    if (collection->count == collection->capacity) {
        resize_data_collection(collection);
    }

    data_entry *new_entry = malloc(sizeof(data_entry));
    new_entry->string = strdup(str);
    new_entry->value = val;
    new_entry->length = strlen(str);

    collection->entries[collection->count++] = new_entry;

    return 0; // Success
}

double calculate_average_length(const data_collection *collection) {
    size_t total_length = 0;
    size_t non_empty_count = 0;

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]->length > 0) {
            total_length += collection->entries[i]->length;
            non_empty_count++;
        }
    }

    return non_empty_count ? (double)total_length / non_empty_count : 0.0;
}

void free_data_collection(data_collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->string);
        free(collection->entries[i]);
    }
    free(collection->entries);
    free(collection);
}

