['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_THRESHOLD 1024 * 1024 // 1MB example threshold

typedef struct Record {
    int* value_ptr;
    int unique_key;
    char* string_data;
    struct Record* next;
} Record;

// Pseudo-random number generator
int generate_random(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Thread-safe memory management function
Record* manage_memory(long num_offsets, long num_keys, char** strings, 
                      size_t string_size_limit, int key_range_min, int key_range_max) {

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Calculate the total required memory and validate against threshold
    size_t offset_array_size = num_offsets * sizeof(long);
    size_t key_array_size = num_keys * sizeof(int);
    size_t total_memory_required = offset_array_size + key_array_size;

    if (total_memory_required > MAX_MEMORY_THRESHOLD) {
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    long* offsets = malloc(offset_array_size);
    int* keys = malloc(key_array_size);

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    // Initialize offsets and validate no buffer overflow
    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = generate_random(1, 100); // Example offset values
    }

    // Validate unique keys and avoid duplicates
    int key_set[MAX_MEMORY_THRESHOLD / sizeof(int)] = {0}; // Assume max possible keys won't exceed threshold

    for (long i = 0; i < num_keys; ++i) {
        int new_key;
        do {
            new_key = generate_random(key_range_min, key_range_max);
        } while (key_set[new_key]);

        if (new_key >= MAX_MEMORY_THRESHOLD / sizeof(int)) {
            free(offsets);
            free(keys);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
        keys[i] = new_key;
        key_set[new_key] = 1; // Mark as used
    }

    Record* head_record = NULL;
    Record** tail_record_ptr = &head_record;

    for (long i = 0; i < num_keys; ++i) {
        char *string = strings[i];

        if (strlen(string) >= string_size_limit - 1) { // Account for null terminator
            free(offsets);
            free(keys);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        Record* new_record = malloc(sizeof(Record));
        if (!new_record) {
            free(offsets);
            free(keys);
            while (head_record) {
                Record* temp = head_record;
                head_record = head_record->next;
                free(temp->value_ptr);
                free(temp->string_data);
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        new_record->value_ptr = malloc(sizeof(int));
        if (!new_record->value_ptr) {
            free(new_record);
            free(offsets);
            free(keys);
            while (head_record) {
                Record* temp = head_record;
                head_record = head_record->next;
                free(temp->string_data);
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        new_record->unique_key = keys[i];
        int random_value = generate_random(key_range_min, key_range_max);
        *new_record->value_ptr = random_value;

        new_record->string_data = malloc(string_size_limit + 1); // Allocate with extra space for null terminator
        if (!new_record->string_data) {
            free(new_record->value_ptr);
            free(new_record);
            free(offsets);
            free(keys);
            while (head_record) {
                Record* temp = head_record;
                head_record = head_record->next;
                free(temp->string_data);
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        strncpy(new_record->string_data, string, string_size_limit);
        new_record->string_data[string_size_limit] = '\0'; // Ensure null termination

        if (strlen(string) < string_size_limit - 1) {
            strcat(new_record->string_data, "/");
        }

        pthread_mutex_lock(&lock);
        *tail_record_ptr = new_record;
        tail_record_ptr = &new_record->next;
        new_record->next = NULL;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return head_record;
}
