use clap::Parser;
use config::{Config, ConfigError, File, Value};
use env_logger::{Builder, Env};
use log::{info, warn};
use reqwest::Client;
use serde::Deserialize;
use serde_json::Value as JsonValue;
use std::time::Duration;
use tokio::sync::Semaphore;
use tokio_retry::{strategy::FixedRetry, retry};
use tracing_subscriber::FmtSubscriber;
use url::Url;

#[derive(Debug, Parser)]
struct Cli {
    #[clap(long, default_value = "config.yaml")]
    config: String,
}

#[derive(Deserialize)]
struct ConfigSettings {
    server_url: String,
    json_schema: JsonValue,
    num_workers: usize,
    max_retries: u8,
    retry_backoff_ms: u64,
}

async fn fetch_with_retry(client: &Client, url: &Url, sem: &Semaphore, semaphore_permits: usize) -> Result<JsonValue, Box<dyn std::error::Error>> {
    let mut attempts = 0;
    let result = retry(FixedRetry::new(ConfigSettings { max_retries: 3 }.max_retries as u32))
        .interval(Duration::from_millis(100))
        .map(move |_| {
            let permit = sem.acquire().await.unwrap();
            client.get(url.clone()).send()
                .and_then(|response| {
                    if response.status().is_success() {
                        response.json::<JsonValue>()
                    } else {
                        Err(reqwest::Error::new(reqwest::StatusCode::from_u16(response.status().as_u16()).unwrap(), reqwest::Body::empty()))
                    }
                })
        })
        .await;

    match result {
        Ok(data) => Ok(data),
        Err(err) if attempts < ConfigSettings { max_retries: 3 }.max_retries as usize => {
            warn!("Request failed, retrying... ({})", attempts);
            attempts += 1;
            fetch_with_retry(client, url, sem, semaphore_permits).await
        }
        Err(err) => Err(Box::new(err)),
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Setup logging
    Builder::from_env(Env::default().default_filter_or("info")).init();
    let subscriber = FmtSubscriber::builder()
        .with_max_level(tracing_subscriber::filter::LevelFilter::INFO)
        .finish();

    tracing::subscriber::set_global_default(subscriber).expect("setting default subscriber failed");

    // Parse command line arguments
    let cli = Cli::parse();

    // Load configuration
    let mut s = Config::new();
    s.merge(File::with_name(&cli.config))?;
    if s.get::<ConfigSettings>().is_err() {
        info!("Using default values.");
    }
    let config: ConfigSettings = s.try_into()?;

    // Validate configurations
    if Url::parse(&config.server_url).is_err() {
        return Err("Invalid server URL".into());
    }

    // Setup HTTP client and semaphore for concurrency control
    let client = Client::builder().timeout(Duration::from_secs(10)).build()?;
    let sem = Semaphore::new(config.num_workers as usize);

    info!("Starting workers: {}", config.num_workers);

    tokio::spawn(async move {
        while let Ok(_) = fetch_with_retry(&client, &Url::parse(&config.server_url).unwrap(), &sem, config.num_workers).await {
            // Simulate ongoing processing
            tokio::time::sleep(Duration::from_secs(1)).await;
        }
    }).await?;

    Ok(())
}
```

