    return time(NULL) + rand(); // Mock a random offset to simulate precision
}

// Create and initialize the data manager with specified capacity
DataManager* create_data_manager(size_t initial_capacity) {
    DataManager* manager = malloc(sizeof(DataManager));
    if (!manager) return NULL;

    pthread_rwlock_init(&manager->lock, NULL);
    manager->offsets = calloc(initial_capacity, sizeof(atomic_int));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->recordsA = malloc(initial_capacity * sizeof(RecordTypeA));
    manager->recordsB = malloc(initial_capacity * sizeof(RecordTypeB));
    manager->capacity = initial_capacity;
    manager->last_timestamp = get_current_time();

    return manager;
}

// Free allocated resources
void free_data_manager(DataManager* manager) {
    if (manager) {
        pthread_rwlock_destroy(&manager->lock);
        free(manager->offsets);
        free(manager->keys);
        free(manager->recordsA);
        free(manager->recordsB);
        free(manager);
    }
}

// Resize the data structures when necessary
int resize_data_manager(DataManager* manager, size_t new_capacity) {
    pthread_rwlock_wrlock(&manager->lock);

    int* temp_keys = realloc(manager->keys, new_capacity * sizeof(int));
    atomic_int* temp_offsets = realloc(manager->offsets, new_capacity * sizeof(atomic_int));
    RecordTypeA* temp_recordsA = realloc(manager->recordsA, new_capacity * sizeof(RecordTypeA));
    RecordTypeB* temp_recordsB = realloc(manager->recordsB, new_capacity * sizeof(RecordTypeB));

    if (!temp_keys || !temp_offsets || !temp_recordsA || !temp_recordsB) {
        pthread_rwlock_unlock(&manager->lock);
        return -1; // Fail to resize
    }

    manager->keys = temp_keys;
    manager->offsets = temp_offsets;
    manager->recordsA = temp_recordsA;
    manager->recordsB = temp_recordsB;
    manager->capacity = new_capacity;

    pthread_rwlock_unlock(&manager->lock);
    return 0; // Success
}

// Initialize the data manager with keys and offsets, and populate records
void initialize_data_manager(DataManager* manager, int range_min, int range_max) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        // Generate unique keys within the specified range
        manager->keys[i] = rand() % (range_max - range_min + 1) + range_min;

        // Calculate cumulative offsets based on previous keys
        if (i == 0)
            atomic_init(&manager->offsets[i], 0);
        else
            atomic_store(&manager->offsets[i], atomic_load(&manager->offsets[i-1]) + manager->keys[i-1] + 10);

        // Populate records with random values and a timestamp
        time_t current_time = get_current_time();
        while (current_time <= manager->last_timestamp) { // Ensure strictly increasing timestamps
            current_time = get_current_time();
        }
        manager->last_timestamp = current_time;

        RecordTypeA* recordA = &manager->recordsA[i];
        RecordTypeB* recordB = &manager->recordsB[i];

        recordA->field1 = rand() % 1000; // Example range
        recordA->field2 = rand();
        recordA->field3 = (float)rand() / RAND_MAX * 100.0;
        recordA->timestamp = current_time;

        recordB->field4 = rand();
        recordB->field5 = (float)rand() / RAND_MAX * 100.0;
        recordB->field6 = (double)rand() / RAND_MAX * 10000.0;
        recordB->timestamp = current_time;
    }

    pthread_rwlock_unlock(&manager->lock);
}

// Example usage
int main() {
    srand(time(NULL)); // Seed the random number generator

    DataManager* manager = create_data_manager(10); // Initial capacity of 10
    if (!manager) return -1;

    initialize_data_manager(manager, 100, 200);

