typedef struct {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    void** pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (void**)calloc(total_blocks, sizeof(void*));
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks < mp->total_blocks) {
        void* block = malloc(mp->block_size);
        mp->pool[mp->used_blocks++] = block;
        pthread_mutex_unlock(&mp->lock);
        return block;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void free_memory_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->used_blocks; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

Node* create_node(Record record, Node* next) {
    Node* node = (Node*)allocate_from_pool(memory_pool);
    if (!node) return NULL;
    node->record = record;
    node->next = next;
    return node;
}

