    return new_node ? new_node : head; // Return original if allocation failed
}

Node* delete_node(Node** head, Record record) {
    Node dummy;
    dummy.next = *head;
    Node *prev = &dummy, *curr = dummy.next;

    while (curr) {
        if (memcmp(&curr->record, &record, sizeof(Record)) == 0) {
            prev->next = curr->next;
            free(curr);
            break;
        }
        prev = curr;
        curr = curr->next;
    }

    *head = dummy.next;
    return *head;
}

Node* find_node(Node* head, Record record) {
    while (head) {
        if (memcmp(&head->record, &record, sizeof(Record)) == 0) {
            return head;
        }
        head = head->next;
    }
    return NULL;
}

void resize_structure(Node** head, size_t new_size) {
