#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
import <time.h>

typedef struct {
    short s;
    int i;
    float f;
    time_t timestamp;
} Record;

typedef struct ListNode {
    Record data;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t count;
    ListNode *head;
    ListNode *tail;
    pthread_mutex_t lock;
} LinkedList;

// Memory pool structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t mutex;
} MemoryPool;

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->mutex);
    if (mp->used_blocks >= mp->total_blocks) {
        pthread_mutex_unlock(&mp->mutex);
        return NULL;  // Resize logic can be added here
    }
    void *block = ((char*)mp->pool) + mp->used_blocks * mp->block_size;
    mp->used_blocks++;
    pthread_mutex_unlock(&mp->mutex);
    return block;
}

void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t total_blocks) {
    pthread_mutex_init(&mp->mutex, NULL);
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    mp->pool = malloc(block_size * total_blocks);
}

LinkedList* create_linked_list(size_t initial_capacity) {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->offsets = (long*)malloc(initial_capacity * sizeof(long));
    list->keys = (int*)malloc(initial_capacity * sizeof(int));
    list->capacity = initial_capacity;
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void init_linked_list(LinkedList *list, int key_range_min, int key_range_max) {
    srand(time(NULL));
    for (size_t i = 0; i < list->capacity; ++i) {
        list->keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        if (i == 0)
            list->offsets[i] = list->keys[0];
        else
            list->offsets[i] = list->offsets[i-1] + list->keys[i] + 10; // Add constant value

        ListNode *node = (ListNode*)memory_pool_alloc(&list->mem_pool);
        node->data.s = rand() % 100;
        node->data.i = rand() % 1000;
        node->data.f = (float)(rand() % 100) / 10.0f;
        node->data.timestamp = time(NULL);

        if (!list->head)
            list->head = node;
        else
            list->tail->next = node;

        node->prev = list->tail;
        list->tail = node;
    }
}

void resize_linked_list(LinkedList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);
    long *new_offsets = (long*)realloc(list->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(list->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle failure
    }

    list->offsets = new_offsets;
    list->keys = new_keys;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->lock);
}

void* iterator(LinkedList *list, int (*callback)(Record *, void *), void *arg) {
    ListNode *current = list->head;
    while (current) {
        callback(&current->data, arg);
        current = current->next;
    }
    return NULL;
}

int add_record_to_list(LinkedList *list, Record record) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity)
        resize_linked_list(list, list->capacity * 2);

    ListNode *node = (ListNode*)memory_pool_alloc(&list->mem_pool);
    node->data = record;
    node->prev = list->tail;

    if (!list->head) {
        list->head = node;
    } else {
        list->tail->next = node;
    }

    list->tail = node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_linked_list(LinkedList *list) {
    ListNode *current = list->head;

    while (current) {
        ListNode *next_node = current->next;
        free(current);
        current = next_node;
    }

    free(list->offsets);
    free(list->keys);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Placeholder function for logging
void log_change(const char* message, int user_id) {
    time_t now = time(NULL);
    printf("[%ld] User %d: %s\n", now, user_id, message);
}

int main() {
    LinkedList *my_list = create_linked_list(10);
    initialize_memory_pool(&my_list->mem_pool, sizeof(ListNode), 100);

    init_linked_list(my_list, 1, 100);

    Record new_record = { .s = 123, .i = 4567, .f = 89.0f, .timestamp = time(NULL) };
    add_record_to_list(my_list, new_record);

    iterator(my_list, [](Record *record, void *arg) {
        printf("Record - s: %d, i: %d, f: %.2f, timestamp: %ld\n", record->s, record->i, record->f, record->timestamp);
    }, NULL);

    destroy_linked_list(my_list);

    return 0;
}
