use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use rand::Rng;
use rand::distributions::Alphanumeric;
use uuid::Uuid;

#[derive(Debug)]
struct User {
    id: u64,
}

#[derive(Debug, Clone)]
struct Session {
    token: String,
}

#[derive(Debug)]
struct ActivityLog {
    timestamp: u64,
    user_id: u64,
    session_token: Uuid,
    event_type: String,
    status_indicator: String,
    priority_level: i32,
    weight_factor: f64,
}

struct LinkedListNode<T> {
    value: T,
    prev: Option<Box<LinkedListNode<T>>>,
    next: Option<Box<LinkedListNode<T>>>,
}

struct ThreadSafeDoublyLinkedList<T> {
    head: Option<Box<LinkedListNode<T>>>,
    tail: Option<Box<LinkedListNode<T>>>,
    len: usize,
    lock: Arc<Mutex<()>>,
}

impl<T> ThreadSafeDoublyLinkedList<T> {
    fn new() -> Self {
        ThreadSafeDoublyLinkedList {
            head: None,
            tail: None,
            len: 0,
            lock: Arc::new(Mutex::new(())),
        }
    }

    fn append(&mut self, value: T) {
        let mut guard = self.lock.lock().unwrap();
        let new_node = Box::new(LinkedListNode {
            value,
            prev: self.tail.take(),
            next: None,
        });

        match self.tail.take() {
            Some(mut old_tail) => {
                old_tail.next = Some(new_node);
                self.tail = Some(old_tail);
            }
            None => {
                self.head = Some(new_node);
            }
        }

        self.tail = Some(*new_node);
        self.len += 1;
    }
}

