        monitor->callback(status);
    }
}

int convert_jpeg_to_pdf_with_theme(const char *input_file, const char *output_file, void *theme_bitmap_arg,
                                   ProgressMonitor *progress_monitor) {
    // Check and recycle theme
    check_and_recycle_theme();

    // Verify and set default theme directory
    char *theme_dir = getenv("THEME_DIR");
    if (!theme_dir || strcmp(theme_dir, "") == 0) {
        set_default_theme_directory(&theme_dir);
    }

    // Parse PNG from cache root (mock implementation)
    char *png_data;
    size_t png_size;
    parse_png_from_cache_root(&png_data, &png_size);

    // Conversion status
    ConversionStatus status = {"Not Started", 0};

    // Start conversion with timeout handling
    if (!perform_conversion(input_file, output_file, &status)) {
        send_notification("Conversion failed or exceeded time limit.");
        return 1;
    }

    monitor_progress(progress_monitor, &status);

    free(theme_bitmap);
    theme_bitmap = NULL;

    return status.status[0] == 'S' ? 0 : 1; // Success if status starts with 'S'
}

void check_and_recycle_theme() {
    pthread_mutex_lock(&cache_lock);
    if (theme_bitmap) {
        free(theme_bitmap);
        theme_bitmap = NULL;
    }
    pthread_mutex_unlock(&cache_lock);
}

void set_default_theme_directory(char **theme_dir) {
    *theme_dir = strdup(DEFAULT_THEME_DIR);
}

void parse_png_from_cache_root(char **png_data, size_t *size) {
    // Mock implementation
    *png_data = malloc(100); // Simulate reading 100 bytes
    *size = 100;
}

int perform_conversion(const char *input_file, const char *output_file, ConversionStatus *status) {
    pthread_mutex_lock(&cache_lock);
    if (current_concurrent_processes >= MAX_CONCURRENT_PROCESSES) {
        status->status = "Queued";
        pthread_mutex_unlock(&cache_lock);
        return 0; // Wait for other processes to complete
    }
    current_concurrent_processes++;
    pthread_mutex_unlock(&cache_lock);

    time_t start_time = time(NULL);
    pthread_t conversion_thread;

    void *conversion_func(void *arg) {
        struct {
            const char *input_file;
            const char *output_file;
            ConversionStatus *status;
        } *args = (void *)arg;

        // Simulate third-party tool call
        convert_jpeg_to_pdf(args->input_file, args->output_file);

        time_t end_time = time(NULL);
        if ((end_time - start_time) > TIMEOUT_SECONDS) {
            args->status->status = "Timeout";
            send_notification("Conversion exceeded time limit.");
        } else {
            args->status->status = "Success";
            args->status->progress = 100;
        }

        pthread_mutex_lock(&cache_lock);
        current_concurrent_processes--;
        pthread_mutex_unlock(&cache_lock);

        free(arg);
        return NULL;
    }

    void *args = malloc(sizeof(struct {
        const char *input_file;
        const char *output_file;
        ConversionStatus *status;
    }));
    if (!args) {
        status->status = "Error";
        current_concurrent_processes--;
        pthread_mutex_unlock(&cache_lock);
        return 0;
    }

    struct {
        const char *input_file;
        const char *output_file;
        ConversionStatus *status;
    } *conv_args = (void *)args;

    conv_args->input_file = input_file;
    conv_args->output_file = output_file;
    conv_args->status = status;

    if (pthread_create(&conversion_thread, NULL, conversion_func, args)) {
        status->status = "Error";
        current_concurrent_processes--;
        pthread_mutex_unlock(&cache_lock);
        return 0;
    }

    pthread_detach(conversion_thread);

    // Wait for the thread to finish
    while (strcmp(status->status, "Success") != 0 && strcmp(status->status, "Timeout") != 0) {
        sleep(1); // Simulate progress monitoring
    }

    return strcmp(status->status, "Success") == 0;
}
