#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int key;
} record;

typedef struct {
    record *records;
    long *offsets;
    int *keys;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double max_memory_usage;
} event_log_system;

void custom_free(void **ptr) {
    if (ptr && *ptr) {
        free(*ptr);
        *ptr = NULL;
    }
}

int allocate_records(event_log_system *sys, size_t new_capacity) {
    record *new_records = realloc(sys->records, new_capacity * sizeof(record));
    if (!new_records) return -1;

    sys->records = new_records;
    sys->capacity = new_capacity;
    return 0;
}

event_log_system* init_event_log_system(size_t initial_capacity, double max_memory_usage) {
    event_log_system *sys = (event_log_system *)malloc(sizeof(event_log_system));
    if (!sys) return NULL;

    sys->records = malloc(initial_capacity * sizeof(record));
    if (!sys->records) {
        free(sys);
        return NULL;
    }

    sys->offsets = malloc(initial_capacity * sizeof(long));
    if (!sys->offsets) {
        custom_free((void**)&sys->records);
        free(sys);
        return NULL;
    }

    sys->keys = malloc(initial_capacity * sizeof(int));
    if (!sys->keys) {
        custom_free((void**)&sys->records);
        custom_free((void**)&sys->offsets);
        free(sys);
        return NULL;
    }

    sys->capacity = initial_capacity;
    sys->count = 0;

    pthread_mutex_init(&sys->lock, NULL);

    sys->max_memory_usage = max_memory_usage;

    return sys;
}

int add_record(event_log_system *sys, int key, int timestamp) {
    if (!sys || !pthread_mutex_lock(&sys->lock)) return -1;

    if (sys->count >= sys->capacity) {
        size_t new_capacity = sys->capacity * 2;
        if (allocate_records(sys, new_capacity)) {
            pthread_mutex_unlock(&sys->lock);
            return -1;
        }
    }

    record rec = { timestamp };
    sys->records[sys->count] = rec;
    sys->keys[sys->count] = key;

    double current_usage = ((double)sys->count / (double)sys->capacity) * 100.0;
    if (current_usage > sys->max_memory_usage * 80.0) {
        size_t new_capacity = sys->capacity * 1.5;
        if (allocate_records(sys, new_capacity)) {
            pthread_mutex_unlock(&sys->lock);
            return -1;
        }
    }

    sys->count++;

    pthread_mutex_unlock(&sys->lock);

    return 0;
}

void free_event_log_system(event_log_system *sys) {
    if (!sys) return;

    custom_free((void**)&sys->records);
    custom_free((void**)&sys->offsets);
    custom_free((void**)&sys->keys);

    pthread_mutex_destroy(&sys->lock);
    free(sys);
}
