#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_TABLE_SIZE 1024

typedef struct {
    long timestamp;
    int key;
    int value;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **table;
    size_t size;
    pthread_mutex_t mutexes[];
} HashTable;

unsigned long hash(int key, size_t size) {
    return (unsigned long)(key % size);
}

HashTable* create_table(size_t initial_size) {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(initial_size, sizeof(HashNode *));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->size = initial_size;
    pthread_mutex_t mutexes[initial_size];
    for (size_t i = 0; i < initial_size; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
    ht->mutexes = mutexes;

    return ht;
}

void free_table(HashTable *ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->size; ++i) {
        HashNode *current = ht->table[i];
        while (current) {
            HashNode *tmp = current;
            current = current->next;
            free(tmp);
        }
    }

    free(ht->table);
    for (size_t i = 0; i < ht->size; ++i) {
        pthread_mutex_destroy(&ht->mutexes[i]);
    }
    free(ht->mutexes);
    free(ht);
}

int insert_record(HashTable *ht, Record rec) {
    if (!ht) return -1;

    unsigned long index = hash(rec.key, ht->size);
    pthread_mutex_lock(&ht->mutexes[index]);

    HashNode *current = ht->table[index];
    while (current) {
        if (current->record.key == rec.key) {
            current->record.timestamp = rec.timestamp;
            current->record.value = rec.value;
            pthread_mutex_unlock(&ht->mutexes[index]);
            return 0; // Updated existing record
        }
        current = current->next;
    }

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&ht->mutexes[index]);
        return -1; // Memory allocation failure
    }

    new_node->record = rec;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;

    pthread_mutex_unlock(&ht->mutexes[index]);
    return 0; // Inserted successfully
}

Record* find_record(HashTable *ht, int key) {
    if (!ht) return NULL;

    unsigned long index = hash(key, ht->size);
    pthread_mutex_lock(&ht->mutexes[index]);

    HashNode *current = ht->table[index];
    while (current) {
        if (current->record.key == key) {
            Record *result = malloc(sizeof(Record));
            if (!result) {
                pthread_mutex_unlock(&ht->mutexes[index]);
                return NULL; // Memory allocation failure
            }
            *result = current->record;
            pthread_mutex_unlock(&ht->mutexes[index]);
            return result; // Found record
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ht->mutexes[index]);
    return NULL; // Record not found
}

int delete_record(HashTable *ht, int key) {
    if (!ht) return -1;

    unsigned long index = hash(key, ht->size);
    pthread_mutex_lock(&ht->mutexes[index]);

    HashNode **current = &ht->table[index];
    while (*current) {
        if ((*current)->record.key == key) {
            HashNode *tmp = *current;
            *current = (*current)->next;
            free(tmp);
            pthread_mutex_unlock(&ht->mutexes[index]);
            return 0; // Deleted successfully
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&ht->mutexes[index]);
    return -1; // Record not found
}

void iterate_records(HashTable *ht, void (*callback)(Record)) {
    if (!ht) return;

    for (size_t i = 0; i < ht->size; ++i) {
        pthread_mutex_lock(&ht->mutexes[i]);

        HashNode *current = ht->table[i];
        while (current) {
            callback(current->record);
            current = current->next;
        }

        pthread_mutex_unlock(&ht->mutexes[i]);
    }
}
