typedef struct {
    record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    // Custom memory allocator state (e.g., free list, allocated blocks)
} RecordManager;

typedef struct {
    unsigned long seed;
    pthread_mutex_t mutex;
} RNGState;

void init_rng(RNGState *rng) {
    rng->seed = time(NULL);  // Using current time as initial seed
    pthread_mutex_init(&rng->mutex, NULL);
}

unsigned int custom_random(RNGState *rng, unsigned int min, unsigned int max) {
    pthread_mutex_lock(&rng->mutex);
    rng->seed = (214013 * rng->seed + 2531011);
    unsigned int rnd = (unsigned int)(rng->seed >> 16) % (max - min + 1) + min;
    pthread_mutex_unlock(&rng->mutex);
    return rnd;
}

void init_record_manager(RecordManager *manager, size_t initial_capacity, unsigned int rng_min, unsigned int rng_max) {
    manager->records = calloc(initial_capacity, sizeof(record));
    if (!manager->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    RNGState rng;
    init_rng(&rng);

    for (size_t i = 0; i < initial_capacity; ++i) {
        record new_record;
        new_record.value = custom_random(&rng, rng_min, rng_max);
        pthread_mutex_lock(&manager->lock);
        manager->records[i] = new_record;
        manager->size++;
        pthread_mutex_unlock(&manager->lock);
    }
}

void monitor_and_resize(RecordManager *manager) {
    size_t used_memory = manager->size * sizeof(record);
    size_t max_capacity = manager->capacity;
    if ((used_memory / (max_capacity * sizeof(record))) > 0.75) {
        size_t new_capacity = max_capacity * 2;
        record *new_records = realloc(manager->records, new_capacity * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
}

