#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define RECORDS_INITIAL_SIZE 10
#define RECORDS_INCREMENT_SIZE 5
#define CACHE_SIZE 5

typedef struct {
    short short_val;
    int int_val;
    float float_val;
    time_t timestamp;
    char *metadata;
} Record;

typedef struct Node {
    Record record;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

typedef struct {
    long offset[RECORDS_INITIAL_SIZE];
    int keys[RECORDS_INITIAL_SIZE];
    Record records[RECORDS_INITIAL_SIZE];
    time_t timestamps[RECORDS_INITIAL_SIZE];
    char metadata_pool[MAX_METADATA_LENGTH * RECORDS_INITIAL_SIZE];
    size_t current_size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    Record* cache[CACHE_SIZE];
    int usage_order[CACHE_SIZE];
    int next_index;
    pthread_mutex_t lock;
} LRUCache;

// Function prototypes
void initialize_memory_pool(MemoryPool* pool);
void resize_memory_pool_if_needed(MemoryPool* pool);
void initialize_doubly_linked_list(DoublyLinkedList* list);
void add_record_to_list(DoublyLinkedList* list, Record record);
Node* get_node_by_index(DoublyLinkedList* list, size_t index);
Record* access_record_from_cache(LRUCache* cache, int key);
void update_lru_cache(LRUCache* cache, Record* record);

// Memory pool initialization
void initialize_memory_pool(MemoryPool* pool) {
    memset(pool->offset, 0, sizeof(pool->offset));
    memset(pool->keys, 0, sizeof(pool->keys));
    memset(pool->records, 0, sizeof(pool->records));
    memset(pool->timestamps, 0, sizeof(pool->timestamps));
    memset(pool->metadata_pool, 0, sizeof(pool->metadata_pool));

    pool->current_size = 0;
    pool->capacity = RECORDS_INITIAL_SIZE;

    pthread_mutex_init(&pool->lock, NULL);
}

// Resize memory pool if needed
void resize_memory_pool_if_needed(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->current_size >= pool->capacity) {
        size_t new_capacity = pool->capacity + RECORDS_INCREMENT_SIZE;

        long *new_offsets = realloc(pool->offset, new_capacity * sizeof(long));
        int *new_keys = realloc(pool->keys, new_capacity * sizeof(int));
        Record *new_records = realloc(pool->records, new_capacity * sizeof(Record));
        time_t *new_timestamps = realloc(pool->timestamps, new_capacity * sizeof(time_t));

        if (new_offsets && new_keys && new_records && new_timestamps) {
            pool->offset = new_offsets;
            pool->keys = new_keys;
            pool->records = new_records;
            pool->timestamps = new_timestamps;

            pool->capacity = new_capacity;
        } else {
            fprintf(stderr, "Failed to resize memory pool\n");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Doubly linked list initialization
void initialize_doubly_linked_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_init(&list->lock, NULL);
}

// Add record to doubly linked list
void add_record_to_list(DoublyLinkedList* list, Record record) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        exit(EXIT_FAILURE);
    }

    memcpy(&new_node->record, &record, sizeof(Record));
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }

    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Get node by index
Node* get_node_by_index(DoublyLinkedList* list, size_t index) {
    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }
    return current;
}

// LRUCache initialization
void initialize_lru_cache(LRUCache* cache) {
    memset(cache->cache, 0, sizeof(Record*) * CACHE_SIZE);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache->usage_order[i] = -1;
    }
    cache->next_index = 0;

    pthread_mutex_init(&cache->lock, NULL);
}

// Access record from cache
Record* access_record_from_cache(LRUCache* cache, int key) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->usage_order[i] == key) {
            // Move accessed record to the end
            int old_index = i;
            while (i > 0 && cache->usage_order[i - 1] > cache->usage_order[i]) {
                int temp = cache->usage_order[i];
                cache->usage_order[i] = cache->usage_order[i - 1];
                cache->usage_order[i - 1] = temp;
                i--;
            }

            pthread_mutex_unlock(&cache->lock);
            return cache->cache[old_index];
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Update LRU cache
void update_lru_cache(LRUCache* cache, Record* record) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->usage_order[i] == -1) {
            // Add new entry to the cache
            cache->cache[i] = record;
            cache->usage_order[i] = cache->next_index++;
            break;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

// Main function demonstrating memory pool and linked list usage
int main() {
    MemoryPool pool;
    DoublyLinkedList list;
    LRUCache cache;

    initialize_memory_pool(&pool);
    initialize_doubly_linked_list(&list);
    initialize_lru_cache(&cache);

    // Example: Adding records to the memory pool and linked list
    for (size_t i = 0; i < pool.capacity; ++i) {
        resize_memory_pool_if_needed(&pool);

        Record record;
        record.short_val = rand() % 1000;
        record.int_val = rand() % 10000;
        record.float_val = (float)(rand()) / RAND_MAX * 100.0f;
        record.timestamp = time(NULL);

        // Random metadata string generation
        size_t metadata_length = rand() % MAX_METADATA_LENGTH;
        snprintf(record.metadata, metadata_length + 1, "metadata_%zu", i);

        pool.records[pool.current_size] = record;
        pool.timestamps[pool.current_size] = record.timestamp;

        if (i > 0) {
            pool.offset[i] = pool.offset[i - 1] + pool.keys[i - 1];
        }
        pool.keys[i] = rand() % 10000; // Unique key generation
        pool.current_size++;

        add_record_to_list(&list, record);
        update_lru_cache(&cache, &record);
    }

    printf("Records added to memory pool and linked list.\n");

    // Clean up resources
    pthread_mutex_destroy(&pool.lock);
    pthread_mutex_destroy(&list.lock);
    pthread_mutex_destroy(&cache.lock);

    return 0;
}
