// Define encryption algorithms and modes
typedef enum {
    AES_128,
    AES_192,
    AES_256,
    CHACHA20,
    XCHACHA20
} Algorithm;

typedef enum {
    MODE_GCM,
    MODE_CTR,
    MODE_CFB
} Mode;

