    time_t window_start;
    pthread_mutex_t lock;
    int attempts;
} RateLimiter;

RateLimiter rate_limiter = {5, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize the cryptographic framework
EVP_CIPHER_CTX* init_cipher(Algorithm algo, Mode mode, const unsigned char *key, size_t key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int bits;

    switch (algo) {
        case AES_128: bits = 128; break;
        case AES_192: bits = 192; break;
        case AES_256: bits = 256; break;
        case CHACHA20: return EVP_CIPHER_CTX_new(); // Key size handled in chacha20
        case XCHACHA20: return EVP_CIPHER_CTX_new(); // Key size handled in xchacha20
    }

    if (!ctx) {
        fprintf(stderr, "Error initializing context\n");
        return NULL;
    }

    switch (algo) {
        case AES_128:
        case AES_192:
        case AES_256:
            if (mode == MODE_GCM) {
                EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, NULL);
                EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL); // GCM standard IV length
            } else if (mode == MODE_CTR) {
                EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, NULL);
            } else if (mode == MODE_CFB) {
                EVP_EncryptInit_ex(ctx, EVP_aes_128_cfb8(), NULL, key, NULL);
            }
            break;
        case CHACHA20:
            if (!EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, NULL)) {
                fprintf(stderr, "Error initializing chacha20\n");
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            }
            break;
        case XCHACHA20:
            if (!EVP_EncryptInit_ex(ctx, EVP_xchacha20(), NULL, key, NULL)) {
                fprintf(stderr, "Error initializing xchacha20\n");
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            }
            break;
    }

    return ctx;
}

// Key derivation using PBKDF2
int derive_key(const char *password, const unsigned char *salt, int salt_len,
               unsigned char *key, size_t key_len) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len,
                             10000, EVP_sha256(), key_len, key);
}

// Rate limiting function
int rate_limit_check() {
    pthread_mutex_lock(&rate_limiter.lock);

    time_t now = time(NULL);
    if (now > rate_limiter.window_start + 60) { // Reset every minute
        rate_limiter.attempts = 0;
        rate_limiter.window_start = now;
    }

    if (rate_limiter.attempts >= rate_limiter.max_attempts) {
        pthread_mutex_unlock(&rate_limiter.lock);
        return -1; // Rate limit exceeded
    }

    rate_limiter.attempts++;
    pthread_mutex_unlock(&rate_limiter.lock);

    return 0; // Allowed
}

// Cleanup function
void cleanup(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Main function for demonstration purposes
int main() {
    unsigned char key[32];
    unsigned char salt[] = "12345678"; // Should be random in production

    const char *password = "securepassword";
    if (derive_key(password, salt, sizeof(salt), key, sizeof(key)) != 1) {
        fprintf(stderr, "Key derivation failed\n");
        return 1;
    }

    if (rate_limit_check() == -1) {
        fprintf(stderr, "Rate limit exceeded\n");
        return 1;
    }

    EVP_CIPHER_CTX *ctx = init_cipher(AES_128, MODE_GCM, key, sizeof(key));
    if (!ctx) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        return 1;
    }

    // Perform encryption/decryption operations...

    cleanup(ctx);

    return 0;
}
