// Configuration header
#include "config.h"

typedef struct record {
    int key;
    long offset;
} Record;

typedef struct node {
    double value;
    char identifier[16];
    struct node* next;
} Node;

#define MAX_RECORDS 1000

Record* records = NULL;
size_t record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize linked list
Node* init_linked_list(size_t size) {
    pthread_mutex_lock(&lock);

    Node* head = malloc(sizeof(Node));
    if (!head) {
        perror("Failed to allocate memory for linked list");
        exit(EXIT_FAILURE);
    }

    Node* current = head;
    for (size_t i = 0; i < size; ++i) {
        current->value = (double)i;
        snprintf(current->identifier, sizeof(current->identifier), "Node%zu", i);

        if (i != size - 1) {
            current->next = malloc(sizeof(Node));
            if (!current->next) {
                perror("Failed to allocate memory for linked list");
                exit(EXIT_FAILURE);
            }
        } else {
            current->next = NULL;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return head;
}

// Dynamic allocation and initialization of records
void init_records(size_t initial_size) {
    pthread_mutex_lock(&lock);

    if (!records || record_count < MAX_RECORDS) {
        records = realloc(records, sizeof(Record) * (record_count + initial_size));
        if (!records) {
            perror("Failed to allocate memory for records");
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < initial_size; ++i) {
            records[record_count].key = rand() % CONFIG_MAX_KEY;
            records[record_count].offset = (long)i * sizeof(Record); // Example initialization
            record_count++;
        }
    }

    pthread_mutex_unlock(&lock);
}

// Free all resources
void free_resources(Node* head) {
    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    if (records) {
        free(records);
        records = NULL;
        record_count = 0;
    }
}

// Resizing the record array
void resize_records(size_t new_size) {
    pthread_mutex_lock(&lock);

    if (!records || new_size > record_count && new_size <= MAX_RECORDS) {
        records = realloc(records, sizeof(Record) * new_size);
        if (!records) {
            perror("Failed to allocate memory for resizing records");
            exit(EXIT_FAILURE);
        }

        // Initialize newly allocated space
        for (size_t i = record_count; i < new_size; ++i) {
            records[i].key = rand() % CONFIG_MAX_KEY;
            records[i].offset = (long)i * sizeof(Record); // Example initialization
        }

        record_count = new_size;
    }

    pthread_mutex_unlock(&lock);
}

// Logging mechanism
void log_memory_usage(size_t memory_used) {
    printf("Memory usage: %zu bytes\n", memory_used);
}

// Main function to demonstrate functionality
int main() {
    init_records(10);

    Node* list_head = init_linked_list(5);

    // Simulate operations...

    resize_records(20);

    free_resources(list_head);

    return 0;
}
```

