} DataManager;

typedef struct {
    int value;
    // Additional metadata fields
} Metadata;

static pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_data_manager(DataManager *dm, size_t initial_capacity);
void free_data_manager(DataManager *dm);

int generate_unique_key(int range_start, int range_end, size_t count) {
    static int used_keys[1000] = { 0 }; // Simplified key management
    for (int i = range_start; i <= range_end; ++i) {
        if (!used_keys[i]) {
            used_keys[i] = 1;
            return i;
        }
    }
    return -1; // Indicate failure to generate a unique key
}

void calculate_offsets(int *offset, int *key, size_t count) {
