    for (size_t i = 0; i < count; ++i) {
        sum += key[i];
        offset[i] = sum + (i == 0 ? 10 : 0); // Example constant
    }
}

void add_record(DataManager *dm, short field1, int field2) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->capacity) {
        if (dm->resize != NULL) {
            dm->resize(dm);
        } else {
            printf("Error: No resize function provided.\n");
            pthread_mutex_unlock(&dm->lock);
            return;
        }
    }

    Record *new_record = malloc(sizeof(Record));
    new_record->field1 = field1;
    new_record->field2 = field2;
    new_record->next = dm->head;
    dm->head = new_record;

    pthread_mutex_unlock(&dm->lock);
}

void resize_data_manager(DataManager *dm) {
    size_t new_capacity = dm->capacity * 2; // Example resizing strategy
    int *new_offset = realloc(dm->offset, new_capacity * sizeof(int));
    int *new_key = realloc(dm->key, new_capacity * sizeof(int));

    if (new_offset && new_key) {
        memset(new_offset + dm->capacity, 0, new_capacity - dm->capacity);
        memset(new_key + dm->capacity, 0, new_capacity - dm->capacity);

        dm->offset = new_offset;
        dm->key = new_key;
        dm->capacity = new_capacity;
    }
}

void serialize_data_manager(const char *filename, const DataManager *dm) {
    pthread_mutex_lock((pthread_mutex_t *)&global_lock);

    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file for serialization.\n");
        pthread_mutex_unlock((pthread_mutex_t *)&global_lock);
        return;
    }

    fwrite(dm->offset, sizeof(int), dm->capacity, file);
    fwrite(dm->key, sizeof(int), dm->capacity, file);

    Record *current = dm->head;
    while (current != NULL) {
        fwrite(&current->field1, sizeof(short), 1, file);
        fwrite(&current->field2, sizeof(int), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t *)&global_lock);
}

void deserialize_data_manager(DataManager *dm, const char *filename) {
    pthread_mutex_lock((pthread_mutex_t *)&global_lock);

    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file for deserialization.\n");
        pthread_mutex_unlock((pthread_mutex_t *)&global_lock);
        return;
    }

    fread(dm->offset, sizeof(int), dm->capacity, file);
    fread(dm->key, sizeof(int), dm->capacity, file);

    while (fread(&current_field1, sizeof(short), 1, file) &&
           fread(&current_field2, sizeof(int), 1, file)) {
        add_record(dm, current_field1, current_field2);
    }

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t *)&global_lock);
}

void analyze_performance(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    // Example analysis: Check memory usage and suggest optimizations
    printf("Current record count: %zu\n", dm->count);
    if (dm->capacity - dm->count > dm->capacity / 4) {
        printf("Consider reducing the data manager's capacity.\n");
    }

    pthread_mutex_unlock(&dm->lock);
}

void initialize_data_manager(DataManager *dm, size_t initial_capacity) {
    pthread_mutex_init(&dm->lock, NULL);

    dm->offset = calloc(initial_capacity, sizeof(int));
    dm->key = calloc(initial_capacity, sizeof(int));

    if (!dm->offset || !dm->key) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    dm->head = NULL;
    dm->count = 0;
    dm->capacity = initial_capacity;

    dm->resize = resize_data_manager;
    dm->serialize = serialize_data_manager;
    dm->deserialize = deserialize_data_manager;
}

void free_data_manager(DataManager *dm) {
    Record *current = dm->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }

    free(dm->offset);
    free(dm->key);

    pthread_mutex_destroy(&dm->lock);
}

int main() {
    DataManager dm;
    initialize_data_manager(&dm, 10);

    // Example usage
    int keys[10];
    for (size_t i = 0; i < 10; ++i) {
        keys[i] = generate_unique_key(1, 100, 10);
    }

    calculate_offsets(dm.offset, keys, 10);
    memcpy(dm.key, keys, sizeof(keys));

    for (int i = 0; i < 15; ++i) { // Add more than capacity to trigger resizing
        add_record(&dm, rand() % 1000, rand() % 10000);
    }

    dm.serialize("data.bin", &dm);

    free_data_manager(&dm);

    return 0;
}
