#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define INITIAL_SIZE 16

typedef struct TaskNode {
    unsigned long timestamp;
    int priority;
    double weight;
    struct TaskNode* parent;
    struct TaskNode** children; // Dynamic array of pointers to children
    size_t children_count;
    pthread_mutex_t lock;       // Mutex for thread safety
} TaskNode;

typedef struct {
    TaskNode** nodes;
    size_t size;
    size_t capacity;
    pthread_mutex_t global_lock; // Global mutex for managing the graph
} DependencyGraph;

// Memory pool management functions
void* memory_pool_alloc(size_t size);
void memory_pool_free(void* ptr);

DependencyGraph* initialize_dependency_graph() {
    DependencyGraph* graph = (DependencyGraph*)malloc(sizeof(DependencyGraph));
    if (!graph) return NULL;

    pthread_mutex_init(&graph->global_lock, NULL);
    graph->size = 0;
    graph->capacity = INITIAL_SIZE;

    graph->nodes = (TaskNode**)memory_pool_alloc(graph->capacity * sizeof(TaskNode*));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    for (size_t i = 0; i < graph->capacity; ++i)
        graph->nodes[i] = NULL;

    return graph;
}

void resize_dependency_graph(DependencyGraph* graph, size_t new_capacity) {
    pthread_mutex_lock(&graph->global_lock);
    TaskNode** temp_nodes = (TaskNode**)memory_pool_alloc(new_capacity * sizeof(TaskNode*));
    if (!temp_nodes) {
        pthread_mutex_unlock(&graph->global_lock);
        return;
    }

    for (size_t i = 0; i < new_capacity; ++i)
        temp_nodes[i] = NULL;

    for (size_t i = 0; i < graph->size; ++i)
        temp_nodes[i] = graph->nodes[i];

    memory_pool_free(graph->nodes);
    graph->nodes = temp_nodes;
    graph->capacity = new_capacity;

    pthread_mutex_unlock(&graph->global_lock);
}

TaskNode* create_task_node(unsigned long timestamp, int priority, double weight) {
    TaskNode* node = (TaskNode*)memory_pool_alloc(sizeof(TaskNode));
    if (!node) return NULL;

    pthread_mutex_init(&node->lock, NULL);
    node->timestamp = timestamp;
    node->priority = priority;
    node->weight = weight;
    node->parent = NULL;
    node->children = NULL; // Will be allocated as needed
    node->children_count = 0;

    return node;
}

void add_task_to_graph(DependencyGraph* graph, TaskNode* task) {
    pthread_mutex_lock(&graph->global_lock);

    if (graph->size == graph->capacity)
        resize_dependency_graph(graph, graph->capacity * 2);

    graph->nodes[graph->size++] = task;

    pthread_mutex_unlock(&graph->global_lock);
}

void traverse_and_validate(DependencyGraph* graph) {
    for (size_t i = 0; i < graph->size; ++i) {
        TaskNode* node = graph->nodes[i];

        // Example validation: Check if priority is within range
        if (node->priority < 1 || node->priority > 10) {
            printf("Invalid priority for task at index %zu\n", i);
            continue;
        }
    }
}

