            if (!new_child) continue;

            pthread_mutex_lock(&node->lock);
            node->children = (TaskNode**)memory_pool_realloc(node->children, 
                (node->children_count + 1) * sizeof(TaskNode*));
            node->children[node->children_count++] = new_child;
            new_child->parent = node;
            pthread_mutex_unlock(&node->lock);

            break; // Assuming task_id matches only one node
        }
    }

    pthread_mutex_unlock(&graph->global_lock);
}

int main() {
