    mutable std::shared_mutex rwMutex;
    int cacheSize;
    std::unordered_map<std::string, std::shared_ptr<TrafficFlow>> cache;

public:
    TrafficManager(int cacheSize) : cacheSize(cacheSize) {}

    void addTrafficFlow(const std::string& srcIP, const std::string& destIP,
                        const std::string& protocol) {
        auto traffic = std::make_shared<TrafficFlow>(srcIP, destIP, protocol);
        std::unique_lock lock(rwMutex);
        trafficMap[srcIP + "->" + destIP] = traffic;
        cache[protocol].push_back(traffic); // Simplified caching strategy
    }

    void removeTrafficFlowByIP(const std::string& srcIP) {
        std::unique_lock lock(rwMutex);
        for (auto it = trafficMap.begin(); it != trafficMap.end();) {
            if (it->second->SourceIP == srcIP) {
                log("Removing Traffic Flow: " + srcIP);
                it = trafficMap.erase(it);
            } else {
                ++it;
            }
        }
    }

    int countFlowsByProtocol(const std::string& protocol) {
        std::shared_lock lock(rwMutex);
        return cache[protocol].size();
    }

    void batchDeleteStaleTrafficFlows() {
        auto fifteenMinutesAgo = std::chrono::steady_clock::now() - 
                                 std::chrono::minutes(15);

        std::unique_lock lock(rwMutex);
        for (auto it = trafficMap.begin(); it != trafficMap.end();) {
            if (it->second->UpdateTimestamp < fifteenMinutesAgo) {
                log("Batch deleting stale flow: " + it->first);
                it = trafficMap.erase(it);
            } else {
                ++it;
            }
        }
    }

    void updateWhitelist(const std::vector<std::string>& whitelist) {
