        // This example doesn't include full logic for simplicity.
        log("Updating whitelist with size: " + std::to_string(whitelist.size()));
    }

    void exportToCSV(const std::string& filePath) {
        std::ofstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Could not open file for writing.");
        }

        std::unique_lock lock(rwMutex);
        for (const auto& entry : trafficMap) {
            const auto& flow = entry.second;
            file << flow->SourceIP << "," << flow->DestinationIP 
                 << "," << flow->ProtocolType << "\n";
        }

        log("Exported TrafficFlows to CSV");
    }
};

int main() {
