    manager.batchDeleteStaleTrafficFlows();
    int tcpCount = manager.countFlowsByProtocol("TCP");

    std::cout << "TCP Traffic Flows: " << tcpCount << "\n";

    manager.exportToCSV("traffic_flows.csv");
