#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_JOBS 1000
#define MEMORY_POOL_SIZE (MAX_JOBS * sizeof(Job))
#define DURATION_MIN 1
#define DURATION_MAX 100
#define START_TIME_MIN 1609459200 // Example: Jan 1, 2021
#define START_TIME_MAX 1640995200 // Example: Dec 31, 2021

typedef struct Job {
    char name[50];
    int status;
    int priority;
    uint64_t estimated_duration;
    time_t start_time;
} Job;

typedef struct Node {
    Job job;
    struct Node* left;
    struct Node* right;
} Node;

typedef struct BST {
    Node* root;
    pthread_mutex_t lock; // For thread-safe operations
} BST;

uint8_t memory_pool[MEMORY_POOL_SIZE];
size_t memory_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (memory_offset + size > MEMORY_POOL_SIZE) {
        // Graceful degradation: return NULL when out of memory
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    void* ptr = &memory_pool[memory_offset];
    memory_offset += size;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void free_memory() {
    pthread_mutex_lock(&pool_lock);
    memory_offset = 0; // Reset the pool
    pthread_mutex_unlock(&pool_lock);
}

Node* create_node(const Job* job) {
    Node* node = (Node*)allocate_memory(sizeof(Node));
    if (!node) return NULL;
    node->job = *job;
    node->left = node->right = NULL;
    return node;
}

BST* initialize_bst() {
    BST* bst = (BST*)malloc(sizeof(BST));
    if (!bst) return NULL;
    pthread_mutex_init(&bst->lock, NULL);
    bst->root = NULL;
    return bst;
}

void destroy_bst(Node* root) {
    if (!root) return;
    destroy_bst(root->left);
    destroy_bst(root->right);
    free(root); // Memory pool will manage this
}

Node* insert_node(Node* node, const Job* job) {
    if (!node) return create_node(job);

    if (job->estimated_duration < node->job.estimated_duration)
        node->left = insert_node(node->left, job);
    else if (job->estimated_duration > node->job.estimated_duration)
        node->right = insert_node(node->right, job);

    return node;
}

void bst_insert(BST* bst, const Job* job) {
    pthread_mutex_lock(&bst->lock);
    bst->root = insert_node(bst->root, job);
    pthread_mutex_unlock(&bst->lock);
}

uint64_t get_random_duration() {
    uint64_t max_range = UINT64_MAX - (DURATION_MAX - DURATION_MIN + 1);
    return ((rand() % max_range) + DURATION_MIN); // Uniform distribution
}

time_t get_random_start_time() {
    time_t max_range = START_TIME_MAX - (START_TIME_MIN - 0 + 1);
    return ((rand() % max_range) + START_TIME_MIN);
}

void generate_job(Job* job, const char* name) {
    snprintf(job->name, sizeof(job->name), "%s", name);
    job->status = rand() % 2;
    job->priority = rand() % 10;
    job->estimated_duration = get_random_duration();
    job->start_time = get_random_start_time();
}

void populate_bst(BST* bst) {
    for (int i = 0; i < MAX_JOBS; ++i) {
        Job job;
        generate_job(&job, "Job");
        bst_insert(bst, &job);
    }
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    BST* bst = initialize_bst();
    if (!bst) {
        fprintf(stderr, "Failed to initialize BST\n");
        return EXIT_FAILURE;
    }

    populate_bst(bst);

    destroy_bst(bst->root);
    free(bst);
    free_memory();

    return 0;
}
```

