#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_IMAGE_SIZE 10 * 1024 * 1024 // 10MB
#define HASH_MAP_INITIAL_CAPACITY 128
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    unsigned int id;
    time_t timestamp;
    char source[256];
    char destinationFormat[64];
    void* payload;
    size_t payloadSize;
} ImageRequest;

typedef struct HashMapNode {
    unsigned int requestId;
    ImageRequest request;
    struct HashMapNode *next;
} HashMapNode;

typedef struct {
    HashMapNode **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashMap;

typedef struct {
    void *memoryPool;
    size_t poolSize;
} MemoryPool;

typedef struct {
    unsigned int intervalId;
    time_t timestamp;
} ProcessingQueueInterval;

// Hash function for requestId
unsigned int hashRequestId(unsigned int requestId, size_t capacity) {
    return requestId % capacity;
}

HashMap* createHashMap(size_t initialCapacity) {
    HashMap *map = malloc(sizeof(HashMap));
    map->buckets = calloc(initialCapacity, sizeof(HashMapNode *));
    map->capacity = initialCapacity;
    map->size = 0;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void resizeHashMap(HashMap *map) {
    size_t newCapacity = map->capacity * 2;
    HashMapNode **newBuckets = calloc(newCapacity, sizeof(HashMapNode *));

    for (size_t i = 0; i < map->capacity; ++i) {
        HashMapNode *node = map->buckets[i];
        while (node) {
            HashMapNode *next = node->next;
            unsigned int newBucketIndex = hashRequestId(node->requestId, newCapacity);

            node->next = newBuckets[newBucketIndex];
            newBuckets[newBucketIndex] = node;

            node = next;
        }
    }

    free(map->buckets);
    map->buckets = newBuckets;
    map->capacity = newCapacity;
}

void insertRequest(HashMap *map, unsigned int requestId, ImageRequest request) {
    pthread_mutex_lock(&map->lock);

    if ((float)map->size / map->capacity > LOAD_FACTOR_THRESHOLD) {
        resizeHashMap(map);
    }

    unsigned int bucketIndex = hashRequestId(requestId, map->capacity);
    HashMapNode *node = malloc(sizeof(HashMapNode));
    node->requestId = requestId;
    node->request = request;
    node->next = map->buckets[bucketIndex];

    map->buckets[bucketIndex] = node;
    ++map->size;

    pthread_mutex_unlock(&map->lock);
}

ImageRequest* getRequestById(HashMap *map, unsigned int requestId) {
    unsigned int bucketIndex = hashRequestId(requestId, map->capacity);
    HashMapNode *node = map->buckets[bucketIndex];

    while (node) {
        if (node->requestId == requestId) {
            return &node->request;
        }
        node = node->next;
    }

    return NULL;
}

void initializeProcessingQueue(ProcessingQueueInterval **queue, size_t intervalCount) {
    *queue = malloc(intervalCount * sizeof(ProcessingQueueInterval));
    srand(time(NULL));

    for (size_t i = 0; i < intervalCount; ++i) {
        (*queue)[i].intervalId = rand();
        (*queue)[i].timestamp = time(NULL) + rand() % 3600;
    }
}

void initializeMemoryPool(MemoryPool *pool, size_t poolSize) {
    pool->memoryPool = malloc(poolSize);
    pool->poolSize = poolSize;
}

void* allocateFromPool(MemoryPool *pool, size_t size) {
    // Simple memory allocation strategy for demonstration
    static void *currentOffset = NULL;
    if (!currentOffset) currentOffset = pool->memoryPool;

    if (size + ((char *)currentOffset - (char *)pool->memoryPool) > pool->poolSize) {
        return NULL; // Pool exhausted
    }

    void *allocatedMemory = currentOffset;
    currentOffset = (char *)currentOffset + size;
    return allocatedMemory;
}

void imageProcessor() {
    // Initialize data structures
    HashMap *imageRequestsMap = createHashMap(HASH_MAP_INITIAL_CAPACITY);
    ProcessingQueueInterval *processingQueue = NULL;
    MemoryPool memoryPool;
    initializeProcessingQueue(&processingQueue, 100); // Example interval count
    initializeMemoryPool(&memoryPool, 10 * 1024 * 1024); // 10MB pool

    // Example usage: Inserting an image request
    ImageRequest request = {1, time(NULL), "source.jpg", "png", NULL, 0};
    insertRequest(imageRequestsMap, request.id, request);

    // Retrieve and process requests (example)
    ImageRequest *retrievedRequest = getRequestById(imageRequestsMap, 1);
    if (retrievedRequest) {
        printf("Processing image: %s\n", retrievedRequest->source);
        // Process the image...
    }

    // Clean up
    free(processingQueue);
    free(memoryPool.memoryPool);
    for (size_t i = 0; i < imageRequestsMap->capacity; ++i) {
        HashMapNode *node = imageRequestsMap->buckets[i];
        while (node) {
            HashMapNode *next = node->next;
            free(node);
            node = next;
        }
    }
    free(imageRequestsMap->buckets);
    free(imageRequestsMap);
}

int main() {
    imageProcessor();
    return 0;
}
```

