#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>
#include <time.h>

typedef struct Point {
    double x;
    double y;
    unsigned int ref_count;
    void *metadata;  // Additional metadata pointers
} Point;

// Define a balanced binary tree node for Point
typedef struct TreeNode {
    Point point;
    struct TreeNode *left;
    struct TreeNode *right;
    pthread_mutex_t lock;  // Mutex for thread-safe operations on this node
} TreeNode;

// Structure to manage the memory pool and collections
typedef struct MemoryPool {
    double *coordinates_pool;
    char **strings_pool;
    size_t coordinates_capacity;
    size_t strings_capacity;
    TreeNode *root;
    pthread_rwlock_t tree_lock;  // Reader-writer lock for thread-safe tree access
} MemoryPool;

// Function to initialize memory pool
MemoryPool* init_memory_pool(size_t initial_coords_capacity, size_t initial_strings_capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->coordinates_capacity = initial_coords_capacity;
    pool->strings_capacity = initial_strings_capacity;

    // Allocate memory for coordinates and strings
    pool->coordinates_pool = calloc(initial_coords_capacity, sizeof(double) * 2);
    pool->strings_pool = malloc(initial_strings_capacity * sizeof(char*));

    if (!pool->coordinates_pool || !pool->strings_pool) {
        free(pool->coordinates_pool);
        free(pool->strings_pool);
        free(pool);
        return NULL;
    }

    // Initialize tree root and lock
    pthread_rwlock_init(&pool->tree_lock, NULL);
    pool->root = NULL;

    return pool;
}

// Function to resize the coordinates collection
void resize_coordinates(MemoryPool *pool, size_t new_capacity) {
    double *new_pool = realloc(pool->coordinates_pool, new_capacity * sizeof(double) * 2);
    if (new_pool) {
        pool->coordinates_pool = new_pool;
        pool->coordinates_capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to resize coordinates memory pool.\n");
    }
}

// Function to insert a Point into the binary tree
void insert_point(MemoryPool *pool, Point point) {
    TreeNode **current = &(pool->root);

    while (*current) {
        pthread_mutex_lock(&(*current)->lock);  // Lock current node for safe traversal

        if (point.x < (*current)->point.x || 
            (point.x == (*current)->point.x && point.y < (*current)->point.y)) {
            current = &((*current)->left);
        } else {
            current = &((*current)->right);
        }

        pthread_mutex_unlock(&(*current)->lock);  // Unlock after traversal
    }

    // Allocate and initialize new TreeNode
    *current = malloc(sizeof(TreeNode));
    if (!*current) return;  // Handle allocation failure

    (*current)->point = point;
    (*current)->left = NULL;
    (*current)->right = NULL;

    pthread_mutex_init(&(*current)->lock, NULL);  // Initialize lock for new node
}

// Function to initialize Points with increasing distances from the origin
void initialize_points(MemoryPool *pool, size_t num_points) {
    srand((unsigned int)time(NULL));  // Seed random number generator

    double distance_increment = 1.0;
    for (size_t i = 0; i < num_points; ++i) {
        if (2 * i >= pool->coordinates_capacity * 2) {
            resize_coordinates(pool, pool->coordinates_capacity * 2);
        }

        double r = sqrt(distance_increment * distance_increment);
        double theta = ((double)rand() / RAND_MAX) * 2 * M_PI;

        // Set x and y based on polar coordinates
        pool->coordinates_pool[2 * i]     = r * cos(theta);  // x
        pool->coordinates_pool[2 * i + 1] = r * sin(theta);  // y

        Point point = {pool->coordinates_pool[2 * i], pool->coordinates_pool[2 * i + 1], 0, NULL};

        pthread_rwlock_wrlock(&pool->tree_lock);
        insert_point(pool, point);
        pthread_rwlock_unlock(&pool->tree_lock);

        distance_increment += 1.0;
    }
}

// Function to perform range queries
void range_query(MemoryPool *pool, double x_min, double y_min, double x_max, double y_max) {
    // Helper function to search within the rectangle bounds
    void search_range(TreeNode* node, double x_min, double y_min, double x_max, double y_max) {
        if (!node) return;

        pthread_mutex_lock(&node->lock);

        if (node->point.x >= x_min && node->point.x <= x_max &&
            node->point.y >= y_min && node->point.y <= y_max) {
            printf("Point found: (%f, %f)\n", node->point.x, node->point.y);
        }

        if (node->point.x > x_min || (node->point.x == x_min && node->point.y > y_min)) {
            search_range(node->left, x_min, y_min, x_max, y_max);
        }

        if (node->point.x < x_max || (node->point.x == x_max && node->point.y < y_max)) {
            search_range(node->right, x_min, y_min, x_max, y_max);
        }

        pthread_mutex_unlock(&node->lock);
    }

    pthread_rwlock_rdlock(&pool->tree_lock);
    search_range(pool->root, x_min, y_min, x_max, y_max);
    pthread_rwlock_unlock(&pool->tree_lock);
}

// Example usage
int main() {
    MemoryPool *pool = init_memory_pool(10, 10);  // Start with small initial capacity

    if (pool) {
        initialize_points(pool, 1000);

        range_query(pool, -5.0, -5.0, 5.0, 5.0);

        // Free allocated memory and clean up
        // This step should properly deallocate the tree nodes and other resources.
    }

    return 0;
}
