#include <time.h>

// Define the Event structure
typedef struct {
    time_t timestamp;
    int event_type;
    char *message;
} Event;

// Global variables for thread-safe allocation and logging
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_memory_allocated = 0;
const size_t MEMORY_THRESHOLD = 1024 * 1024 * 100; // Example threshold of 100 MB

void log_allocation(size_t allocated_size) {
    printf("Allocated %zu bytes. Total memory: %zu bytes\n", allocated_size, total_memory_allocated);
}

void check_memory_threshold() {
    if (total_memory_allocated > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory usage exceeded threshold: %zu bytes\n", total_memory_allocated);
        // Trigger an alert or take necessary action
    }
}

// Function to dynamically create an event
Event* create_event(time_t timestamp, int event_type, const char *message, size_t message_size) {
    pthread_mutex_lock(&mutex);

    Event *event = (Event *)malloc(sizeof(Event));
    if (!event) {
        fprintf(stderr, "Memory allocation for Event structure failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    event->timestamp = timestamp;
    event->event_type = event_type;

    // Allocate memory for the message
    event->message = (char *)malloc(message_size + 1); // +1 for null terminator
    if (!event->message) {
        fprintf(stderr, "Memory allocation for Event message failed\n");
        free(event);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    strncpy(event->message, message, message_size);
    event->message[message_size] = '\0';

    size_t allocated_size = sizeof(Event) + message_size + 1;
    total_memory_allocated += allocated_size;

    log_allocation(allocated_size);
    check_memory_threshold();

    pthread_mutex_unlock(&mutex);
    return event;
}

// Function to safely free an event
void free_event(Event *event) {
    if (event) {
        pthread_mutex_lock(&mutex);

        if (event->message) {
            total_memory_allocated -= (strlen(event->message) + 1);
            free(event->message);
        }

        total_memory_allocated -= sizeof(Event);
        free(event);

        log_allocation(sizeof(Event));
        check_memory_threshold();

        pthread_mutex_unlock(&mutex);
    }
}

// Example usage
int main() {
    time_t now = time(NULL);
    Event *event = create_event(now, 1, "Sample event message", 20);

    if (event) {
        printf("Event created: Type %d, Timestamp %ld, Message '%s'\n",
               event->event_type, event->timestamp, event->message);

        free_event(event);
    }

    return 0;
}
```

This code defines an `Event` structure and provides functions to create and safely free these events. It uses a mutex for thread-safe memory management and includes logging and monitoring of memory usage to alert when it exceeds a specified threshold. The message size is configurable, ensuring flexibility in handling different event data sizes.']

