    if (!check_memory_limit(num_records, total_memory)) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return NULL;
    }

    long *offsets = (long *)malloc(offset_size);
    int *keys = (int *)malloc(key_size);
    Record *records = (Record *)calloc(num_records, sizeof(Record));
    pthread_mutex_t mutex;

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free_resources(offsets, keys, records, NULL);
        return NULL;
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
