        records[i].key_ptr = &keys[i];
        records[i].offset_ptr = &offsets[i];
        records[i].status_flag = 1;
        pthread_mutex_unlock(&mutex);
    }

    log_memory_usage(total_memory, "Memory successfully allocated and initialized.");

