// Define the record structure
#[derive(Clone)]
struct Record {
    short_field: i16,
    int_field: i32,
    float_field: f32,
    timestamp: Instant,
    metadata: Arc<Mutex<Metadata>>,
    event_type: u8,
    status: bool,
    priority: u8,
    weight_factor: f64,
