// Define a node structure for the linked list
struct Node {
    value: f64,
    char_ptr: *mut char,
    next: Option<Box<Node>>,
}

impl Node {
    fn new(value: f64, c_str: &str) -> Self {
        let mut buffer = [0u8; 1];
        unsafe {
            let ptr = buffer.as_mut_ptr() as *mut char;
            std::ptr::copy(c_str.as_ptr(), ptr, c_str.len());
            Node {
                value,
                char_ptr: ptr,
                next: None,
            }
        }
    }

    fn append(&mut self, new_node: Box<Node>) {
        let mut current = &mut self.next;
        while let Some(ref boxed) = current {
            current = &mut boxed.as_mut().next;
        }
        *current = Some(new_node);
    }
}

// Function to manage memory allocation and initialization
fn manage_memory(offset_count: u64, key_range: (i32, i32), record_count: u64) -> Result<(), &'static str> {
