        .map(|_| {
            Record {
                short_field: rand::thread_rng().gen(),
                int_field: rand::thread_rng().gen(),
                float_field: rand::thread_rng().gen(),
                timestamp: Instant::now(),
                metadata: Arc::new(Mutex::new(Metadata::new("metadata"))),
                event_type: rand::random::<u8>(),
                status: rand::random(),
                priority: rand::random::<u8>(),
                weight_factor: rand::thread_rng().gen_range(0.0..1.0),
            }
        })
        .collect();

    // Initialize linked lists
    let mut linked_lists = Vec::with_capacity(offset_count as usize);
    for _ in 0..offset_count {
        linked_lists.push(None);
    }

    // Use threads for concurrent operations
    let handles: Vec<_> = (0..thread::available_parallelism().unwrap_or(1)).map(|_| {
        let record_pool = Arc::clone(&record_pool);
        thread::spawn(move || {
            while let Ok(record) = record_pool.pop() {
                // Process each record, e.g., insert into a data structure
            }
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }

    // Free allocated memory
    for list in linked_lists.iter_mut() {
        if let Some(mut node) = list.take() {
            while let Some(mut boxed_node) = unsafe { Box::from_raw(node.as_ref()) } {
                node = boxed_node.next;
                std::mem::drop(boxed_node); // Explicitly drop to free memory
            }
        }
    }

    Ok(())
}

// Helper function to generate unique keys within a specified range
fn generate_unique_keys(range: u32) -> HashMap<i32, ()> {
    let mut rng = rand::thread_rng();
    let dist = Uniform::from(0..range);
    let mut keys = HashMap::new();

    while keys.len() as i32 < (i32::MAX - range as i32) / 2 {
        let key: i32 = rng.sample(dist) as i32;
        keys.insert(key, ());
    }

    keys
}
