typedef struct {
    short s;
    int i;
    float f;
    unsigned int timestamp;
} Record;

typedef struct ListNode {
    Record data;
    struct ListNode *next;
} ListNode;

typedef struct {
    size_t current_size;
    size_t capacity;
    long *offsets;
    int *keys;
    unsigned int *timestamps;
    pthread_mutex_t lock;
} MemoryPool;

// Custom memory pool
MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->current_size = 0;
    pool->capacity = initial_capacity;
    pool->offsets = (long *)calloc(initial_capacity, sizeof(long));
    pool->keys = (int *)calloc(initial_capacity, sizeof(int));
    pool->timestamps = (unsigned int *)calloc(initial_capacity, sizeof(unsigned int));

    if (!pool->offsets || !pool->keys || !pool->timestamps) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->offsets);
        free(pool->keys);
        free(pool->timestamps);
        free(pool);
    }
}

// Function to resize the arrays within memory pool
int resize_memory_pool(MemoryPool *pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return 0;

    long *new_offsets = (long *)realloc(pool->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(pool->keys, new_capacity * sizeof(int));
    unsigned int *new_timestamps = (unsigned int *)realloc(pool->timestamps, new_capacity * sizeof(unsigned int));

    if (!new_offsets || !new_keys || !new_timestamps) return -1;

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->timestamps = new_timestamps;
    pool->capacity = new_capacity;

    return 0;
}

// Function to initialize keys with unique values
int initialize_keys(MemoryPool *pool, size_t size, int min_val, int max_val) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        int key;
        do {
            key = min_val + rand() % (max_val - min_val + 1);
        } while ((i > 0 && pool->keys[i] == key) || key < min_val || key > max_val);

        pool->keys[i] = key;
    }

    pthread_mutex_unlock(&pool->lock);

    return 0;
}

// Randomly initialize records
void randomize_record(Record *record, unsigned int timestamp_min, unsigned int timestamp_max) {
    record->s = (short)(rand() % 65536);
    record->i = rand();
    record->f = ((float)rand()) / RAND_MAX;
    record->timestamp = timestamp_min + rand() % (timestamp_max - timestamp_min + 1);
}

// Add a new node to the linked list
ListNode* add_record_to_list(ListNode *head, Record data) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->next = head;

    return new_node;
}

// Iterate over the linked list
void iterate_linked_list(ListNode *head) {
    ListNode *current = head;
    while (current != NULL) {
        printf("Record: %hd, %d, %.2f, %u\n", current->data.s, current->data.i, current->data.f, current->data.timestamp);
        current = current->next;
    }
}

// Safe concurrent modification of the linked list
void safe_modify_list(ListNode **head, Record data) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    new_node->next = *head;
    *head = new_node;
    pthread_mutex_unlock(&lock);

    pthread_mutex_destroy(&lock);
}

// Main function to initialize components
void initialize_components(MemoryPool *pool, size_t size, int key_min, int key_max,
                          unsigned int timestamp_min, unsigned int timestamp_max) {
    if (initialize_keys(pool, size, key_min, key_max) != 0) return;

    ListNode *head = NULL;
    for (size_t i = 0; i < size; ++i) {
        Record record;
        randomize_record(&record, timestamp_min, timestamp_max);

        head = add_record_to_list(head, record);
    }

    // Example iteration
    iterate_linked_list(head);

    // Example of concurrent modification
    safe_modify_list(&head, (Record){.s = 123, .i = 456, .f = 789.0, .timestamp = timestamp_min + 100});

    // Free linked list
    ListNode *current = head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
}

// Example usage
int main() {
    size_t initial_capacity = 10;
    MemoryPool *pool = create_memory_pool(initial_capacity);

    if (!pool) {
        printf("Failed to create memory pool\n");
        return -1;
    }

    initialize_components(pool, 5, 1000, 9999, 1609459200, 1704067199);

    free_memory_pool(pool);
    return 0;
}
