// Define record structure
typedef struct {
    short s;
    int i;
    float f;
    time_t timestamp;
    size_t size;
} Record;

// Node for linked list
typedef struct ListNode {
    Record* record;
    struct ListNode* next;
} ListNode;

// Custom memory pool configuration
#define MAX_POOL_SIZE 1024 * 1024 // 1 MB
char memory_pool[MAX_POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe key and offset generation using atomic counters
__thread int thread_local_key = -1; // Local per-thread cache for keys
unsigned long global_offset = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

#define CACHE_SIZE 100

// Utility function to allocate memory from the pool
void* pool_alloc(size_t size) {
    pthread_mutex_lock(&pool_lock);

    if (pool_offset + size > MAX_POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return malloc(size); // Fallback to system allocation
    }

    void* ptr = &memory_pool[pool_offset];
    pool_offset += size;
    pthread_mutex_unlock(&pool_lock);

    return ptr;
}

// Secure random number generator initialization
void init_secure_rng() {
    srand(time(NULL)); // Simple seed, replace with a more secure RNG if needed
}

// Function to initialize records with random values
Record* create_record(size_t size) {
    Record* record = pool_alloc(sizeof(Record));
    record->s = (short)(rand() % 100);
    record->i = rand() % 1000;
    record->f = (float)rand() / RAND_MAX * 100.0;
    record->timestamp = time(NULL);
    record->size = size;

    return record;
}

// Function to generate thread-safe keys
int get_thread_safe_key() {
    if (thread_local_key != -1 && thread_local_key < CACHE_SIZE) {
        int key = thread_local_key++;
        pthread_mutex_unlock(&global_lock); // Unlock early for performance
        return key;
    }

    pthread_mutex_lock(&global_lock);
    global_offset++;
    int key = global_offset;
    pthread_mutex_unlock(&global_lock);

    if (thread_local_key >= CACHE_SIZE) {
        thread_local_key = 0; // Reset local cache
    }

    return key;
}

// Function to add a record to the linked list in a thread-safe manner
void* list_head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void add_record_to_list(Record* record) {
    pthread_mutex_lock(&list_lock);

    ListNode* node = pool_alloc(sizeof(ListNode));
    node->record = record;
    node->next = list_head;
    list_head = node;

    pthread_mutex_unlock(&list_lock);
}

// Function to dynamically resize arrays if needed (simplified example)
