    // Check condition and possibly double the size
    if (*current_size == 0 || *array == NULL) {
        *current_size = 10; // Initial size
        *array = pool_alloc(*current_size * sizeof(long));
    } else if (/* some probabilistic model condition */) {
        size_t new_size = *current_size * 2;
        long* new_array = pool_alloc(new_size * sizeof(long));

        for (size_t i = 0; i < *current_size; ++i) {
            new_array[i] = (*array)[i];
        }

        free(*array);
        *array = new_array;
        *current_size = new_size;
    }
}

// Function to traverse the linked list efficiently
void hybrid_traverse_list() {
    pthread_mutex_lock(&list_lock);

