#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define INITIAL_TRANSACTION_CAPACITY 10
#define HASH_TABLE_INITIAL_CAPACITY 16

typedef struct {
    uint64_t id;
    time_t timestamp;
    double amount;
    char description[256];
} Transaction;

typedef struct HashTableEntry {
    Transaction *transaction;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    size_t capacity;
    size_t size;
    HashTableEntry **buckets;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    Transaction *transactions;
    size_t transaction_count;
    size_t capacity;
    HashTable hash_table;
    pthread_rwlock_t rwlock;
} TransactionManager;

uint64_t generate_random_offset(int range) {
    return rand() % range;
}

uint64_t custom_hash(uint64_t id, size_t table_size) {
    return (id * 0x9e3779b1) >> (32 - __builtin_ctz(table_size));
}

TransactionManager* create_transaction_manager() {
    TransactionManager *manager = malloc(sizeof(TransactionManager));
    if (!manager) return NULL;

    manager->transactions = calloc(INITIAL_TRANSACTION_CAPACITY, sizeof(Transaction));
    if (!manager->transactions) {
        free(manager);
        return NULL;
    }
    manager->transaction_count = 0;
    manager->capacity = INITIAL_TRANSACTION_CAPACITY;

    manager->hash_table.capacity = HASH_TABLE_INITIAL_CAPACITY;
    manager->hash_table.size = 0;
    manager->hash_table.buckets = calloc(manager->hash_table.capacity, sizeof(HashTableEntry*));
    if (!manager->hash_table.buckets) {
        free(manager->transactions);
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->hash_table.lock, NULL);

    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

void resize_transactions(TransactionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Transaction *new_array = realloc(manager->transactions, new_capacity * sizeof(Transaction));
    if (!new_array) return;

    manager->transactions = new_array;
    manager->capacity = new_capacity;
}

void insert_transaction(TransactionManager *manager, uint64_t id, double amount, const char *description) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (manager->transaction_count == manager->capacity) {
        resize_transactions(manager);
    }

    Transaction *transaction = &manager->transactions[manager->transaction_count];
    transaction->id = id;
    time_t now = time(NULL);
    transaction->timestamp = now - generate_random_offset(3600); // within the last hour
    transaction->amount = amount;
    strncpy(transaction->description, description, sizeof(transaction->description) - 1);

    manager->transaction_count++;

    pthread_mutex_lock(&manager->hash_table.lock);
    uint64_t hash_index = custom_hash(id, manager->hash_table.capacity);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (!entry) {
        pthread_rwlock_unlock(&manager->rwlock);
        pthread_mutex_unlock(&manager->hash_table.lock);
        return;
    }
    entry->transaction = transaction;
    entry->next = manager->hash_table.buckets[hash_index];
    manager->hash_table.buckets[hash_index] = entry;
    manager->hash_table.size++;

    if (manager->hash_table.size > manager->hash_table.capacity / 2) {
        // Resize hash table
    }

    pthread_mutex_unlock(&manager->hash_table.lock);
    pthread_rwlock_unlock(&manager->rwlock);
}

void iterate_transactions(TransactionManager *manager) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->transaction_count; ++i) {
        Transaction *transaction = &manager->transactions[i];
        printf("ID: %llu, Timestamp: %ld, Amount: %.2f, Description: %s\n",
               transaction->id, transaction->timestamp, transaction->amount, transaction->description);
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void free_transaction_manager(TransactionManager *manager) {
    for (size_t i = 0; i < manager->hash_table.capacity; ++i) {
        HashTableEntry *entry = manager->hash_table.buckets[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(manager->hash_table.buckets);
    pthread_mutex_destroy(&manager->hash_table.lock);

    free(manager->transactions);

    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

int main() {
    TransactionManager *manager = create_transaction_manager();
    if (!manager) return 1;

    insert_transaction(manager, 1, 100.0, "First transaction");
    insert_transaction(manager, 2, 200.0, "Second transaction");

    iterate_transactions(manager);

    free_transaction_manager(manager);
    return 0;
}
