#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // Maximum memory threshold
#define INITIAL_SIZE 10

typedef struct {
    int short_field;
    int int_field;
    float float_field;
    uint32_t timestamp;
} record;

typedef struct node {
    record data;
    struct node* next;
} node;

typedef struct {
    long* offsets;
    size_t offset_count;
    size_t offset_capacity;

    int* keys;
    size_t key_count;
    size_t key_capacity;

    node* records_head;
    pthread_mutex_t lock;

    uint32_t* timestamps;
    size_t timestamp_count;
    size_t timestamp_capacity;

    pthread_mutex_t sync_lock;
} MemoryManager;

void init_memory_manager(MemoryManager* manager) {
    manager->offsets = malloc(INITIAL_SIZE * sizeof(long));
    manager->offset_count = 0;
    manager->offset_capacity = INITIAL_SIZE;

    manager->keys = malloc(INITIAL_SIZE * sizeof(int));
    manager->key_count = 0;
    manager->key_capacity = INITIAL_SIZE;

    manager->records_head = NULL;
    pthread_mutex_init(&manager->lock, NULL);

    manager->timestamps = malloc(INITIAL_SIZE * sizeof(uint32_t));
    manager->timestamp_count = 0;
    manager->timestamp_capacity = INITIAL_SIZE;

    pthread_mutex_init(&manager->sync_lock, NULL);
}

void* custom_alloc(size_t size) {
    static char pool[MAX_MEMORY];
    static size_t offset = 0;
    if (offset + size > MAX_MEMORY) return NULL;
    void* ptr = &pool[offset];
    offset += size;
    return ptr;
}

int resize_array_if_needed(void** array, size_t* count, size_t* capacity, size_t element_size) {
    if (*count >= *capacity) {
        size_t new_capacity = *capacity == 0 ? INITIAL_SIZE : *capacity * 2;
        void* new_array = custom_alloc(new_capacity * element_size);
        if (!new_array) return -1;

        if (*array != NULL) {
            memcpy(new_array, *array, *count * element_size);
            free(*array);
        }
        *array = new_array;
        *capacity = new_capacity;
    }
    return 0;
}

int generate_unique_key(MemoryManager* manager, int range_min, int range_max) {
    pthread_mutex_lock(&manager->sync_lock);

    for (size_t i = 0; i < manager->key_count; ++i) {
        if ((manager->keys[i] >= range_min && manager->keys[i] <= range_max)) continue;

        int key = rand() % (range_max - range_min + 1) + range_min;
        for (size_t j = 0; j < manager->key_count; ++j) {
            if (manager->keys[j] == key) {
                goto end_lock;
            }
        }

        if (resize_array_if_needed((void**)&manager->keys, &manager->key_count, &manager->key_capacity, sizeof(int)) != 0) {
            pthread_mutex_unlock(&manager->sync_lock);
            return -1;
        }

        manager->keys[manager->key_count++] = key;
        pthread_mutex_unlock(&manager->sync_lock);
        return key;

    end_lock:
        pthread_mutex_unlock(&manager->sync_lock);
    }
    return -1; // No unique key available
}

void populate_record(record* rec) {
    srand(time(NULL)); // Secure seed generation for demonstration
    rec->short_field = rand() % 32767;
    rec->int_field = rand() % 2147483647;
    rec->float_field = (float)rand() / RAND_MAX;
    rec->timestamp = (uint32_t)time(NULL);
}

void add_record(MemoryManager* manager, record data) {
    pthread_mutex_lock(&manager->lock);

    node* new_node = custom_alloc(sizeof(node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_node->data = data;
    new_node->next = manager->records_head;
    manager->records_head = new_node;

    resize_array_if_needed((void**)&manager->timestamps, &manager->timestamp_count, &manager->timestamp_capacity, sizeof(uint32_t));
    manager->timestamps[manager->timestamp_count++] = data.timestamp;

    pthread_mutex_unlock(&manager->lock);
}

void destroy_memory_manager(MemoryManager* manager) {
    node* current = manager->records_head;
    while (current != NULL) {
        node* temp = current;
        current = current->next;
        free(temp);
    }

    if (manager->offsets) free(manager->offsets);
    if (manager->keys) free(manager->keys);
    if (manager->timestamps) free(manager->timestamps);

    pthread_mutex_destroy(&manager->lock);
    pthread_mutex_destroy(&manager->sync_lock);
}

// Example of integration
void integrate_with_system(MemoryManager* manager, int range_min, int range_max) {
    // Generate a unique key and add to keys array.
    if (generate_unique_key(manager, range_min, range_max) != -1) {
        record new_record;
        populate_record(&new_record);
        add_record(manager, new_record);
    }
}

int main() {
    MemoryManager manager;
    init_memory_manager(&manager);

    integrate_with_system(&manager, 100, 200);

    destroy_memory_manager(&manager);
    return 0;
}
