#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
    time_t timestamp;
    int counter;
} Record;

typedef struct Node {
    Record record;
    struct Node *prev, *next;
} Node;

typedef struct MemoryPool {
    size_t block_size;
    char *pool;
    size_t pool_size;
    atomic_uintptr_t offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = block_size * total_blocks;
    mp->pool = (char *)aligned_alloc(64, mp->pool_size);
    atomic_store_explicit(&mp->offset, 0, memory_order_relaxed);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_alloc(MemoryPool *mp) {
    size_t offset;
    do {
        offset = atomic_load_explicit(&mp->offset, memory_order_acquire);
    } while (!atomic_compare_exchange_weak_explicit(&mp->offset, &offset, offset + mp->block_size,
                                                    memory_order_release, memory_order_relaxed));
    return (void *)(mp->pool + offset);
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

typedef struct LinkedList {
    Node *head;
    Node *tail;
    size_t count;
    pthread_rwlock_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void append_record(LinkedList *list, Record record) {
    Node *node = (Node *)pool_alloc(list->memory_pool);
    node->record = record;
    node->prev = list->tail;
    node->next = NULL;

    pthread_rwlock_wrlock(&list->lock);
    if (list->tail) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
    list->count++;
    pthread_rwlock_unlock(&list->lock);
}

void iterate_linked_list(LinkedList *list, void (*callback)(Record)) {
    pthread_rwlock_rdlock(&list->lock);
    Node *current = list->head;
    while (current) {
        callback(current->record);
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);
}

void destroy_linked_list(LinkedList *list) {
    pthread_rwlock_destroy(&list->lock);
    free(list);
}

typedef struct DynamicCollection {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t size;
    LinkedList *records;
    MemoryPool *memory_pool;
    pthread_mutex_t resize_lock;
} DynamicCollection;

DynamicCollection* create_dynamic_collection(size_t initial_capacity) {
    DynamicCollection *dc = (DynamicCollection *)malloc(sizeof(DynamicCollection));
    dc->capacity = initial_capacity;
    dc->size = 0;
    dc->offsets = (long *)malloc(initial_capacity * sizeof(long));
    dc->keys = (int *)malloc(initial_capacity * sizeof(int));
    dc->records = create_linked_list();
    dc->memory_pool = create_memory_pool(sizeof(Record), 1000); // Adjust block size as needed
    pthread_mutex_init(&dc->resize_lock, NULL);
    return dc;
}

void generate_unique_keys(DynamicCollection *dc) {
    int range_start = 1, range_end = 100000;
    for (size_t i = 0; i < dc->capacity; ++i) {
        dc->keys[i] = rand() % (range_end - range_start + 1) + range_start;
    }
}

void initialize_collection(DynamicCollection *dc) {
    generate_unique_keys(dc);
    long sum = 0;
    for (size_t i = 0; i < dc->capacity; ++i) {
        sum += dc->keys[i];
        dc->offsets[i] = sum + i;
    }
}

void resize_collection(DynamicCollection *dc, size_t new_capacity) {
    pthread_mutex_lock(&dc->resize_lock);
    long *new_offsets = (long *)realloc(dc->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(dc->keys, new_capacity * sizeof(int));
    if (new_offsets && new_keys) {
        dc->offsets = new_offsets;
        dc->keys = new_keys;
        dc->capacity = new_capacity;
    }
    pthread_mutex_unlock(&dc->resize_lock);
}

void populate_records(DynamicCollection *dc) {
    for (size_t i = 0; i < dc->capacity; ++i) {
        Record record;
        record.s = rand() % 32768;
        record.i = rand();
        record.f = (float)(rand()) / RAND_MAX;
        record.timestamp = time(NULL);
        record.counter = rand();

        append_record(dc->records, record);
    }
}

void log_changes(DynamicCollection *dc) {
    iterate_linked_list(dc->records, [](Record r) {
        printf("Record: %d, %f, %ld, %d\n", r.s, r.f, (long)r.timestamp, r.counter);
    });
}

void destroy_dynamic_collection(DynamicCollection *dc) {
    free(dc->offsets);
    free(dc->keys);
    destroy_linked_list(dc->records);
    destroy_memory_pool(dc->memory_pool);
    pthread_mutex_destroy(&dc->resize_lock);
    free(dc);
}

int main() {
    srand(time(NULL));
    DynamicCollection *collection = create_dynamic_collection(1000);
    initialize_collection(collection);
    populate_records(collection);
    log_changes(collection);
    resize_collection(collection, 2000); // Example resizing
    destroy_dynamic_collection(collection);
    return 0;
}
