MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = malloc(mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->current_position = mp->pool;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void *memory_pool_allocate(MemoryPool *mp) {
    if (pthread_mutex_lock(&mp->lock)) return NULL;

    void *block = mp->current_position;
    if ((char *)mp->current_position + mp->block_size > (char *)mp->pool + mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // No more space
    }

    mp->current_position += mp->block_size;

    pthread_mutex_unlock(&mp->lock);

    return block;
}

void memory_pool_free(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

