int validateOAuthToken(const char *json_response) {
    pthread_mutex_lock(&validateMutex);

    json_error_t error;
    json_t *root = json_loads(json_response, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        pthread_mutex_unlock(&validateMutex);
        return 0; // false
    }

    int result = 1;

