        result = 0; // false
    }

    json_decref(root);
    pthread_mutex_unlock(&validateMutex);

    return result;
}

int decryptMessage(const char *base64_encoded, const unsigned char *key, const unsigned char *iv, char **decrypted_message) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context.\n");
        return 0;
    }

    int len, ciphertext_len;
    size_t plaintext_len;

    if (EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing decryption.\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    // Decode base64 to ciphertext
    unsigned char *ciphertext = (unsigned char *)malloc(base64_decode_len(base64_encoded));
    if (!ciphertext || base64_decode(ciphertext, &ciphertext_len, base64_encoded) != 1) {
        fprintf(stderr, "Error decoding Base64.\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        return 0;
    }

    *decrypted_message = (char *)malloc(strlen(base64_encoded)); // Allocate enough memory
    if (!*decrypted_message) {
        fprintf(stderr, "Memory allocation failed for decrypted message.\n");
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (EVP_DecryptUpdate(ctx, (unsigned char *)*decrypted_message, &len, ciphertext, ciphertext_len) != 1) {
        fprintf(stderr, "Error during decryption update.\n");
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        free(*decrypted_message);
        return 0;
    }
    plaintext_len = len;

    if (EVP_DecryptFinal_ex(ctx, (unsigned char *)*decrypted_message + len, &len) != 1) {
        fprintf(stderr, "Error during decryption finalization.\n");
        free(ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        free(*decrypted_message);
        return 0;
    }
    plaintext_len += len;

    // Null-terminate the decrypted message
    (*decrypted_message)[plaintext_len] = '\0';

    // Cleanup
    free(ciphertext);
    EVP_CIPHER_CTX_free(ctx);

    return 1; // true
}

