#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

typedef struct {
    short a;
    int b;
    float c;
    time_t timestamp;
    int priority;
} Record;

typedef struct Node {
    void *data;
    size_t size;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

typedef struct {
    char **keys;
    void **values;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} HashMap;

typedef struct {
    void *memory_pool;
    size_t pool_size;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryPool;

void initialize_doubly_linked_list(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_to_doubly_linked_list(DoublyLinkedList *list, void *data, size_t size) {
    Node *node = malloc(sizeof(Node));
    node->data = data;
    node->size = size;
    node->prev = list->tail;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
    pthread_mutex_unlock(&list->lock);
}

void initialize_hash_map(HashMap *map, size_t capacity) {
    map->keys = malloc(capacity * sizeof(char *));
    map->values = malloc(capacity * sizeof(void *));
    map->count = 0;
    map->capacity = capacity;
    pthread_rwlock_init(&map->rwlock, NULL);
}

void hash_map_put(HashMap *map, const char *key, void *value) {
    size_t index = abs((uintptr_t)key % map->capacity);
    pthread_rwlock_wrlock(&map->rwlock);

    for (size_t i = 0; i < map->capacity; ++i) {
        if (!map->keys[index] || strcmp(map->keys[index], key) == 0) {
            free(map->keys[index]);
            map->keys[index] = strdup(key);
            free(map->values[index]);
            map->values[index] = value;
            break;
        }
        index = (index + 1) % map->capacity;
    }

    pthread_rwlock_unlock(&map->rwlock);
}

void initialize_memory_pool(MemoryPool *pool, size_t pool_size) {
    pool->memory_pool = malloc(pool_size);
    pool->pool_size = pool_size;
    pool->used_memory = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate_from_memory_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_memory + size > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *memory = (char*)pool->memory_pool + pool->used_memory;
    pool->used_memory += size;

    pthread_mutex_unlock(&pool->lock);
    return memory;
}

void initialize_collections() {
    DoublyLinkedList offsets, keys, records, file_paths, metadata, chunks, status, errors, metrics;
    HashMap map;
    MemoryPool pool;

    initialize_doubly_linked_list(&offsets);
    initialize_doubly_linked_list(&keys);
    initialize_doubly_linked_list(&records);
    initialize_doubly_linked_list(&file_paths);
    initialize_doubly_linked_list(&metadata);
    initialize_doubly_linked_list(&chunks);
    initialize_doubly_linked_list(&status);
    initialize_doubly_linked_list(&errors);
    initialize_doubly_linked_list(&metrics);

    initialize_hash_map(&map, 16);
    initialize_memory_pool(&pool, 1024 * 1024); // 1 MB pool

    // Initialize collections with unique values
    for (int i = 0; i < 100; ++i) {
        long offset_value = i * 10;
        int key_value = i + 1;

        add_to_doubly_linked_list(&offsets, &offset_value, sizeof(offset_value));
        add_to_doubly_linked_list(&keys, &key_value, sizeof(key_value));

        Record record = { rand() % 1000, rand() % 10000, (float)rand() / RAND_MAX, time(NULL), rand() % 10 };
        void *record_memory = allocate_from_memory_pool(&pool, sizeof(Record));
        memcpy(record_memory, &record, sizeof(Record));
        add_to_doubly_linked_list(&records, record_memory, sizeof(Record));

        char *file_path = "path/to/file";
        char *allocated_file_path = malloc(strlen(file_path) + 1);
        strcpy(allocated_file_path, file_path);
        add_to_doubly_linked_list(&file_paths, allocated_file_path, strlen(file_path) + 1);

        char metadata_attr[] = "attribute_value";
        void *metadata_memory = allocate_from_memory_pool(&pool, sizeof(metadata_attr));
        memcpy(metadata_memory, metadata_attr, sizeof(metadata_attr));
        add_to_doubly_linked_list(&metadata, metadata_memory, sizeof(metadata_attr));

        int chunk_size = rand() % 256;
        void *chunk_memory = allocate_from_memory_pool(&pool, chunk_size);
        memset(chunk_memory, rand() % 256, chunk_size);
        add_to_doubly_linked_list(&chunks, chunk_memory, chunk_size);

        int status_indicator = rand() % 2 ? 1 : 0;
        add_to_doubly_linked_list(&status, &status_indicator, sizeof(status_indicator));

        char error_message[] = "Error message";
        void *error_memory = allocate_from_memory_pool(&pool, sizeof(error_message));
        memcpy(error_memory, error_message, sizeof(error_message));
        add_to_doubly_linked_list(&errors, error_memory, sizeof(error_message));

        float metric_value = (float)rand() / RAND_MAX;
        add_to_doubly_linked_list(&metrics, &metric_value, sizeof(metric_value));
    }
}

int main() {
    initialize_collections();
    printf("Collections initialized successfully.\n");
    return 0;
}
