    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->offset = (long*)malloc(initial_capacity * sizeof(long));
    array->key = (int*)malloc(initial_capacity * sizeof(int));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_dynamic_array(DynamicArray* array) {
    size_t new_capacity = array->capacity * 2;
    long* new_offset = (long*)realloc(array->offset, new_capacity * sizeof(long));
    int* new_key = (int*)realloc(array->key, new_capacity * sizeof(int));

    if (new_offset && new_key) {
        array->offset = new_offset;
        array->key = new_key;
        array->capacity = new_capacity;
    } else {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void set_random_seed(unsigned int seed) {
    srand(seed);
}

int generate_unique_key(size_t count) {
    return rand() % (count * 10 + 1); // Ensuring unique within a range
}

void initialize_dynamic_array(DynamicArray* array, unsigned int seed, size_t num_elements) {
    set_random_seed(seed);

    pthread_mutex_lock(&array->lock);
    if (num_elements > array->capacity) {
        resize_dynamic_array(array);
    }

    for (size_t i = 0; i < num_elements; ++i) {
        while (1) {
            int unique_key = generate_unique_key(i + 1);
            int is_unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (array->key[j] == unique_key) {
                    is_unique = 0;
                    break;
                }
            }
            if (is_unique) {
                array->key[i] = unique_key;
                break;
            }
        }

        long offset_sum = (i > 0) ? array->offset[i - 1] : 0;
        array->offset[i] = offset_sum + array->key[i] + i; // Unique constant value
    }
    pthread_mutex_unlock(&array->lock);
}

Record* create_record(short s, int i, float f) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    rec->s = s;
    rec->i = i;
    rec->f = f;
    rec->next = NULL;

    return rec;
}

void add_record_to_list(Record** head, short s, int i, float f) {
    Record* new_rec = create_record(s, i, f);

    pthread_mutex_lock(&head);
    new_rec->next = *head;
    *head = new_rec;
    pthread_mutex_unlock(&head);
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->offset);
    free(array->key);
    free(array);
}

Record* custom_iterator(Record** head) {
    static Record* current = NULL;

    if (!current || !current->next) {
        current = *head;
    }

    return current++;
}

void cleanup_linked_list(Record** head) {
    Record* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
