#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long *offset;
    int *key;
    int value;
} Record;

Record* allocateAndInitializeData(size_t offsets_size, size_t keys_size, size_t records_count,
                                  int rand_min, int rand_max, size_t max_allocation) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Calculate required memory
    size_t offset_mem = sizeof(long) * offsets_size;
    size_t key_mem = sizeof(int) * keys_size;
    size_t record_struct_mem = sizeof(Record) * records_count;
    size_t value_pointers_mem = sizeof(int *) * records_count;

    if (offset_mem + key_mem + record_struct_mem + value_pointers_mem > max_allocation) {
        return NULL; // Allocation exceeds maximum limit
    }

    long *offsets = malloc(offset_mem);
    int *keys = malloc(key_mem);

    if (!offsets || !keys) {
        free(offsets);  // Free allocated memory if any allocation fails
        free(keys);
        return NULL;
    }

    Record *records = malloc(record_struct_mem + value_pointers_mem);

    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < offsets_size; ++i)
        offsets[i] = i;
    for (size_t i = 0; i < keys_size; ++i)
        keys[i] = i + 1;

    Record *record_array = (Record *)((char *)records + record_struct_mem);

    // Initialize records
    for (size_t i = 0; i < records_count; ++i) {
        pthread_mutex_lock(&lock);
        if ((char *)(record_array + i) - (char *)records > max_allocation - value_pointers_mem)
            break;  // Prevent exceeding memory limits

        record_array[i].offset = &offsets[i % offsets_size];
        record_array[i].key = &keys[i % keys_size];

        record_array[i].value = rand_min + rand() % (rand_max - rand_min + 1);
        pthread_mutex_unlock(&lock);
    }

    // Iterate and print values
    for (size_t i = 0; i < records_count; ++i) {
        printf("Record %zu: Value = %d\n", i, record_array[i].value);
    }

    return record_array;
}
