['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS_PER_SECOND 10000000
#define INITIAL_PROFILE_SIZE 1024
#define PROFILE_NAME_LENGTH 50
#define PROFILE_EMAIL_LENGTH 50

typedef struct Role {
    char *name;
    struct Role *next;
} Role;

typedef struct UserProfile {
    char name[PROFILE_NAME_LENGTH];
    char email[PROFILE_EMAIL_LENGTH];
    time_t last_login;
    Role *roles;
} UserProfile;

typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void* allocate_from_pool(MemoryPool *mp);
void resize_user_profiles(UserProfile **profiles, size_t *current_size);
void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t initial_size);
void free_memory_pool(MemoryPool *mp);

// User profile management functions
UserProfile* create_user_profile(const char *name, const char *email, time_t last_login);
Role* add_role_to_profile(UserProfile *profile, const char *role_name);
void free_user_roles(Role *roles);

// Data processing pipeline function
void data_processing_pipeline() {
    MemoryPool record_pool;
    initialize_memory_pool(&record_pool, sizeof(int), MAX_RECORDS_PER_SECOND);

    // Initialize user profiles memory pool
    MemoryPool profile_pool;
    initialize_memory_pool(&profile_pool, sizeof(UserProfile) + PROFILE_NAME_LENGTH + PROFILE_EMAIL_LENGTH, INITIAL_PROFILE_SIZE * sizeof(UserProfile));

    UserProfile *user_profiles = allocate_from_pool(&profile_pool);
    size_t current_profile_size = INITIAL_PROFILE_SIZE;

    // Simulate data processing loop
    for (size_t i = 0; i < MAX_RECORDS_PER_SECOND; ++i) {
        int *record_value = allocate_from_pool(&record_pool);
        if (!record_value) {
            fprintf(stderr, "Memory allocation failure\n");
            break;
        }
        *record_value = rand() % 100; // Random value within range

        // Process user profiles
        if (i >= current_profile_size) {
            resize_user_profiles(&user_profiles, &current_profile_size);
        }

        UserProfile *profile = &(user_profiles[i]);
        snprintf(profile->name, PROFILE_NAME_LENGTH, "User_%zu", i);
        snprintf(profile->email, PROFILE_EMAIL_LENGTH, "user%zu@example.com", i);
        profile->last_login = time(NULL) - (rand() % 3600); // Random timestamp within last hour
        add_role_to_profile(profile, "default_role");

        // Free record value if needed
        free(record_value);

        // Logging and error handling can be added here
    }

    // Cleanup
    free_user_roles(user_profiles[0].roles);
    for (size_t i = 0; i < current_profile_size; ++i) {
        free_user_roles(user_profiles[i].roles);
    }
    free_memory_pool(&record_pool);
    free_memory_pool(&profile_pool);
}

// Implementations
void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->pool_size >= mp->block_size) {
        void *ptr = mp->pool;
        mp->pool += mp->block_size;
        mp->pool_size -= mp->block_size;
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Out of memory
}

void resize_user_profiles(UserProfile **profiles, size_t *current_size) {
    size_t new_size = (*current_size) * 2;
    UserProfile *new_profiles = realloc(*profiles, new_size * sizeof(UserProfile));
    if (new_profiles) {
        *profiles = new_profiles;
        *current_size = new_size;
    } else {
        fprintf(stderr, "Failed to resize user profiles\n");
        // Handle error gracefully
    }
}

void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t initial_size) {
    mp->block_size = block_size;
    mp->pool_size = initial_size;
    mp->pool = malloc(initial_size);
    if (!mp->pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&mp->lock, NULL);
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

UserProfile* create_user_profile(const char *name, const char *email, time_t last_login) {
    UserProfile *profile = malloc(sizeof(UserProfile));
    if (profile) {
        strncpy(profile->name, name, PROFILE_NAME_LENGTH - 1);
        profile->name[PROFILE_NAME_LENGTH - 1] = '\0';
        strncpy(profile->email, email, PROFILE_EMAIL_LENGTH - 1);
        profile->email[PROFILE_EMAIL_LENGTH - 1] = '\0';
        profile->last_login = last_login;
        profile->roles = NULL;
    }
    return profile;
}

Role* add_role_to_profile(UserProfile *profile, const char *role_name) {
    Role *new_role = malloc(sizeof(Role));
    if (new_role) {
        new_role->name = strdup(role_name);
        new_role->next = profile->roles;
        profile->roles = new_role;
    }
    return new_role;
}

void free_user_roles(Role *roles) {
    while (roles) {
        Role *temp = roles;
        roles = roles->next;
        free(temp->name);
        free(temp);
    }
}
