    private static final Logger logger = Logger.getLogger(DataProcessingPipeline.class.getName());
    private final int maxRecords;
    private final int valueRange;
    private final MemoryPool memoryPool;

    public DataProcessingPipeline(int maxRecords, int valueRange) {
        this.maxRecords = maxRecords;
        this.valueRange = valueRange;
        this.memoryPool = new MemoryPool(maxRecords);
        setupLogger();
    }

    public void processConfiguration() {
        long[] offsets = memoryPool.allocateLongArray(maxRecords);
        int[] keys = memoryPool.allocateIntArray(maxRecords);
        Record[] records = memoryPool.allocateRecordArray(maxRecords);

        // Simulate processing and external command execution
        try {
            executeExternalCommand("ls", "/path/to/directory");
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error executing external command: ", e);
        }

        // Additional logic for data processing

    }

    private void setupLogger() throws IOException {
        Handler fileHandler = new FileHandler("pipeline.log", 1024 * 1024, 3, true);
        SimpleFormatter formatter = new SimpleFormatter();
        fileHandler.setFormatter(formatter);
        logger.addHandler(fileHandler);
        logger.setLevel(Level.ALL);
    }

    private void executeExternalCommand(String command, String workingDir) throws IOException {
        File dir = new File(workingDir);
        File tempFile = new File(dir.getPath(), "tempOutput.txt");
        if (tempFile.exists()) {
            Files.deleteIfExists(tempFile.toPath());
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "))
                .directory(dir)
                .redirectErrorStream(true);

        try (Process process = processBuilder.start();
             BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedWriter stdOutput = new BufferedWriter(new FileWriter(tempFile))) {

            String line;
            while ((line = stdInput.readLine()) != null) {
                stdOutput.write(line);
                stdOutput.newLine();
            }
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Command execution failed with exit code: " + exitCode);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Process interrupted", e);
            throw new IOException("Execution was interrupted", e);
        }
    }

    private class MemoryPool {
        private final ConcurrentLinkedQueue<Long[]> longArrayPool;
        private final ConcurrentLinkedQueue<int[]> intArrayPool;
        private final ConcurrentLinkedQueue<Record[]> recordArrayPool;

        public MemoryPool(int maxRecords) {
            this.longArrayPool = new ConcurrentLinkedQueue<>();
            this.intArrayPool = new ConcurrentLinkedQueue<>();
            this.recordArrayPool = new ConcurrentLinkedQueue<>();

            for (int i = 0; i < Runtime.getRuntime().availableProcessors(); i++) {
                longArrayPool.add(new Long[maxRecords]);
                intArrayPool.add(new int[maxRecords]);
                recordArrayPool.add(new Record[maxRecords]);
            }
        }

        public long[] allocateLongArray(int size) {
            return longArrayPool.poll() != null ? longArrayPool.poll() : new Long[size];
        }

        public int[] allocateIntArray(int size) {
            return intArrayPool.poll() != null ? intArrayPool.poll() : new int[size];
        }

        public Record[] allocateRecordArray(int size) {
            return recordArrayPool.poll() != null ? recordArrayPool.poll() : new Record[size];
        }
    }

    private static class Record {
        private final int value;

        public Record(int value) {
            this.value = value;
        }
    }

    public static void main(String[] args) {
        DataProcessingPipeline pipeline = new DataProcessingPipeline(1000, 100);
        pipeline.processConfiguration();
    }
}
```

