#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    double value;
} Item;

typedef struct FileMetaEntry {
    int id;
    size_t fileSize;
    time_t lastModified;
    time_t *accessTimes;
    int accessCount;
    struct FileMetaEntry *prev, *next; // For LRU
} FileMetaEntry;

typedef struct ComplexStruct {
    double dblValue;
    char *strPtr;
    Item *itemPtr;
    long uniqueLong;
    unsigned short usLength;
} ComplexStruct;

typedef struct {
    FileMetaEntry **entries;
    int capacity;
    int size;
    pthread_mutex_t lock;
    FileMetaEntry *head, *tail; // For LRU
} MetadataCache;

typedef struct {
    ComplexStruct *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ComplexArray;

MetadataCache* create_metadata_cache(int initial_capacity) {
    MetadataCache *cache = (MetadataCache*)malloc(sizeof(MetadataCache));
    cache->entries = (FileMetaEntry**)malloc(initial_capacity * sizeof(FileMetaEntry*));
    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->head = cache->tail = NULL;

    return cache;
}

void resize_metadata_cache(MetadataCache *cache) {
    int new_capacity = cache->capacity * 2;
    FileMetaEntry **new_entries = (FileMetaEntry**)realloc(cache->entries, new_capacity * sizeof(FileMetaEntry*));
    if (!new_entries) return;
    memset(new_entries + cache->capacity, 0, cache->capacity * sizeof(FileMetaEntry*));
    cache->entries = new_entries;
    cache->capacity = new_capacity;
}

FileMetaEntry* create_file_meta_entry(int id, size_t fileSize, time_t lastModified) {
    FileMetaEntry *entry = (FileMetaEntry*)malloc(sizeof(FileMetaEntry));
    entry->id = id;
    entry->fileSize = fileSize;
    entry->lastModified = lastModified;
    entry->accessTimes = NULL;
    entry->accessCount = 0;
    entry->prev = entry->next = NULL;
    return entry;
}

void insert_lru(MetadataCache *cache, FileMetaEntry *entry) {
    if (!cache->head || cache->tail == cache->head) {
        cache->head = cache->tail = entry;
    } else {
        entry->next = cache->head;
        cache->head->prev = entry;
        cache->head = entry;
    }
}

void remove_lru(MetadataCache *cache, FileMetaEntry *entry) {
    if (entry->prev)
        entry->prev->next = entry->next;
    else
        cache->head = entry->next;

    if (entry->next)
        entry->next->prev = entry->prev;
    else
        cache->tail = entry->prev;
}

void access_file_meta_entry(MetadataCache *cache, int id) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < cache->size; ++i) {
        if (cache->entries[i]->id == id) {
            time_t now = time(NULL);
            resize_array(&cache->entries[i]->accessTimes, &cache->entries[i]->accessCount, sizeof(time_t), cache->entries[i]->accessCount + 1);
            cache->entries[i]->accessTimes[cache->entries[i]->accessCount - 1] = now;

            remove_lru(cache, cache->entries[i]);
            insert_lru(cache, cache->entries[i]);
            break;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void resize_array(void **array, int *size, size_t elem_size, int new_count) {
    void *new_array = realloc(*array, new_count * elem_size);
    if (new_array) {
        *array = new_array;
        *size = new_count;
    }
}

ComplexArray* create_complex_array(size_t initial_capacity) {
    ComplexArray *array = (ComplexArray*)malloc(sizeof(ComplexArray));
    array->array = (ComplexStruct*)calloc(initial_capacity, sizeof(ComplexStruct));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void resize_complex_array(ComplexArray *array) {
    size_t new_capacity = array->capacity * 2;
    ComplexStruct *new_array = (ComplexStruct*)realloc(array->array, new_capacity * sizeof(ComplexStruct));
    if (!new_array) return;
    memset(new_array + array->capacity, 0, array->capacity * sizeof(ComplexStruct));
    array->array = new_array;
    array->capacity = new_capacity;
}

void add_complex_struct(ComplexArray *array, ComplexStruct cs) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity)
        resize_complex_array(array);

    array->array[array->count++] = cs;

    pthread_mutex_unlock(&array->lock);
}

ComplexStruct generate_random_struct(const char *key) {
    ComplexStruct cs;
    cs.dblValue = ((double)rand() / RAND_MAX) * 100.0; // Random double
    cs.strPtr = strdup(key); // Use given key as string pointer for simplicity
    cs.itemPtr = (Item*)malloc(sizeof(Item));
    cs.itemPtr->value = cs.dblValue;
    cs.uniqueLong = rand(); // Unique long - Note: This is not guaranteed to be unique across calls
    cs.usLength = strlen(key); // Length of the given key

    return cs;
}

void log_operation(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// A simple test function to show basic usage
void run_test() {
    MetadataCache *cache = create_metadata_cache(INITIAL_CAPACITY);

    pthread_mutex_lock(&cache->lock);
    cache->entries[0] = create_file_meta_entry(1, 1024, time(NULL));
    insert_lru(cache, cache->entries[0]);
    access_file_meta_entry(cache, 1);
