    free(cache->entries[0]);
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);

    for (size_t i = 0; i < complexArray->count; ++i) {
        free(complexArray->array[i].strPtr);
        free(complexArray->array[i].itemPtr);
    }
    free(complexArray->array);
    pthread_mutex_destroy(&complexArray->lock);
    free(complexArray);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    run_test();
    return 0;
}
