['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    int key;
    long offset;
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the dynamic database
void initializeDatabase() {
    pthread_mutex_init(&db_lock, NULL);
}

// Insert a new record into the database while maintaining order based on the 'int' key.
void insertRecord(int key, long offset, Record record) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = key;
    newNode->offset = offset;
    newNode->record = record;
    newNode->next = NULL;

    pthread_mutex_lock(&db_lock);

    if (!head || head->key > key) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;
        while (current->next && current->next->key < key) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&db_lock);
}

// Retrieve a record by its 'int' key.
Record* retrieveRecord(int key) {
    pthread_mutex_lock(&db_lock);

    Node* current = head;
    while (current && current->key != key) {
        current = current->next;
    }

    Record* result = NULL;
    if (current) {
        result = &current->record;
    }

    pthread_mutex_unlock(&db_lock);
    return result;
}

// Free all memory associated with the database
void freeDatabase() {
    Node* current = head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    pthread_mutex_destroy(&db_lock);
}

int main() {
    initializeDatabase();

    Record rec1 = {100};
    insertRecord(10, 0x01, rec1);

    Record rec2 = {200};
    insertRecord(20, 0x02, rec2);

    Record* retrieved = retrieveRecord(10);
    if (retrieved) {
        printf("Retrieved record value: %d\n", retrieved->value);
    }

    freeDatabase();
    return 0;
}
```

This implementation uses a linked list to manage records efficiently. The `insertRecord` function maintains order based on the key, and `retrieveRecord` provides fast access by traversing the list. A mutex ensures thread safety for concurrent read/write operations.']

