                custom_free(node);
            }
            node = next_node;
        }
    }
}

void destroy_hash_table(HashTable* table) {
    for (uintptr_t i = 0; i < atomic_load(&table->capacity); ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next_node = node->next;
            custom_free(node);
            node = next_node;
        }
    }

    custom_free(table->buckets);
    pthread_mutex_destroy(&table->resize_lock);
    custom_free(table);
}

void initialize_records(HashTable* table, uintptr_t num_records) {
    srand(time(NULL));

    for (uintptr_t i = 0; i < num_records; ++i) {
