```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    short s;
    int i;
    float f;
    int timestamp;
    struct record *next;
} record;

typedef struct DataStore {
    long *offsets;
    size_t offset_count;
    size_t offset_capacity;

    int *keys;
    size_t key_count;
    size_t key_capacity;

    record *records_head;
    pthread_mutex_t record_lock;

    int *timestamps;
    size_t timestamp_count;
    size_t timestamp_capacity;

    pthread_mutex_t key_gen_lock;
} DataStore;

void init_data_store(DataStore *store) {
    store->offsets = NULL;
    store->offset_count = 0;
    store->offset_capacity = 0;

    store->keys = NULL;
    store->key_count = 0;
    store->key_capacity = 0;

    store->records_head = NULL;
    pthread_mutex_init(&store->record_lock, NULL);

    store->timestamps = NULL;
    store->timestamp_count = 0;
    store->timestamp_capacity = 0;

    pthread_mutex_init(&store->key_gen_lock, NULL);
}

void resize_array(void **array, size_t *count, size_t *capacity, size_t element_size) {
    if (*count >= *capacity) {
        size_t new_capacity = (*capacity == 0) ? 1 : (*capacity * 2);
        void *new_array = realloc(*array, new_capacity * element_size);
        if (new_array) {
            *array = new_array;
            *capacity = new_capacity;
        } else {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }
    }
}

void add_offset(DataStore *store, long offset) {
    resize_array((void **)&store->offsets, &store->offset_count, &store->offset_capacity, sizeof(long));
    store->offsets[store->offset_count++] = offset;
}

void add_key(DataStore *store, int key) {
    pthread_mutex_lock(&store->key_gen_lock);
    resize_array((void **)&store->keys, &store->key_count, &store->key_capacity, sizeof(int));
    store->keys[store->key_count++] = key;
    pthread_mutex_unlock(&store->key_gen_lock);
}

void add_record(DataStore *store, record *new_record) {
    pthread_mutex_lock(&store->record_lock);

    new_record->next = store->records_head;
    store->records_head = new_record;

    pthread_mutex_unlock(&store->record_lock);
}

void add_timestamp(DataStore *store, int timestamp) {
    resize_array((void **)&store->timestamps, &store->timestamp_count, &store->timestamp_capacity, sizeof(int));
    store->timestamps[store->timestamp_count++] = timestamp;
}

void traverse_records(DataStore *store, void (*callback)(record *)) {
    pthread_mutex_lock(&store->record_lock);

    for (record *current = store->records_head; current != NULL; current = current->next) {
        callback(current);
    }

    pthread_mutex_unlock(&store->record_lock);
}

void free_data_store(DataStore *store) {
    record *curr, *tmp;
    for (curr = store->records_head; curr != NULL;) {
        tmp = curr->next;
        free(curr);
        curr = tmp;
    }

    free(store->offsets);
    free(store->keys);
    free(store->timestamps);

    pthread_mutex_destroy(&store->record_lock);
    pthread_mutex_destroy(&store->key_gen_lock);
}

int main() {
    DataStore store;
    init_data_store(&store);

    // Example usage
    add_offset(&store, 12345L);
    add_key(&store, 6789);
    record *new_rec = malloc(sizeof(record));
    new_rec->s = 10;
    new_rec->i = 20;
    new_rec->f = 30.5;
    new_rec->timestamp = 1617181920;
    add_record(&store, new_rec);
    add_timestamp(&store, 1617181920);

    traverse_records(&store, [](record *r) {
        printf("Record: s=%d, i=%d, f=%.2f, timestamp=%d\n", r->s, r->i, r->f, r->timestamp);
    });

    free_data_store(&store);
    return 0;
}
```

