['Below is a simplified C implementation of a thread-safe LRU cache system managing file metadata entries using mutexes and condition variables. This version uses a combination of data structures like hash tables, doubly linked lists, and dynamic memory allocation techniques:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct AccessTime {
    time_t timestamp;
    struct AccessTime* next;
} AccessTime;

typedef struct FileMetadata {
    int id;
    size_t file_size;
    time_t last_modified;
    AccessTime* access_times;
    char* content_hash; // Assume hash length is fixed, e.g., 32 bytes
    struct FileMetadata* prev;
    struct FileMetadata* next;
} FileMetadata;

typedef struct LRUCache {
    int capacity;
    int size;
    FileMetadata* head;
    FileMetadata* tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    // Hash table for fast access by ID
    FileMetadata** table; 
} LRUCache;

LRUCache* create_cache(int capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->mutex, NULL);
    pthread_cond_init(&cache->cond, NULL);

    cache->table = (FileMetadata**)calloc(capacity, sizeof(FileMetadata*));
    return cache;
}

void free_access_times(AccessTime* at) {
    while (at) {
        AccessTime* next = at->next;
        free(at);
        at = next;
    }
}

void remove_entry(LRUCache* cache, FileMetadata* entry) {
    if (entry->prev)
        entry->prev->next = entry->next;
    else
        cache->head = entry->next;

    if (entry->next)
        entry->next->prev = entry->prev;
    else
        cache->tail = entry->prev;

    free_access_times(entry->access_times);
    free(entry->content_hash);
    free(entry);

    cache->size--;
}

FileMetadata* new_metadata(int id, size_t file_size, time_t last_modified, const char* hash) {
    FileMetadata* meta = (FileMetadata*)malloc(sizeof(FileMetadata));
    meta->id = id;
    meta->file_size = file_size;
    meta->last_modified = last_modified;
    meta->access_times = NULL;

    AccessTime* at = (AccessTime*)malloc(sizeof(AccessTime));
    at->timestamp = time(NULL);
    at->next = NULL;
    meta->access_times = at;

    meta->content_hash = strdup(hash); // Assume hash is fixed size
    meta->prev = NULL;
    meta->next = NULL;

    return meta;
}

void move_to_front(LRUCache* cache, FileMetadata* entry) {
    if (entry == cache->head)
        return;

    remove_entry(cache, entry);
    entry->next = cache->head;
    entry->prev = NULL;

    if (cache->head)
        cache->head->prev = entry;

    cache->head = entry;

    if (!cache->tail)
        cache->tail = entry;
}

void* lru_cache_insert(void* arg) {
    LRUCache* cache = (LRUCache*)arg;
    int id, file_size;
    time_t last_modified;
    char hash[33]; // Assuming SHA-256

    pthread_mutex_lock(&cache->mutex);

    if (cache->size >= cache->capacity) {
        remove_entry(cache, cache->tail);
    }

    // Simulate fetching metadata
    scanf("%d %zu %ld %s", &id, &file_size, &last_modified, hash);

    FileMetadata* entry = new_metadata(id, file_size, last_modified, hash);

    if (cache->table[id % cache->capacity] == NULL) {
        cache->table[id % cache->capacity] = entry;
    } else {
        move_to_front(cache, cache->table[id % cache->capacity]);
        cache->table[id % cache->capacity]->file_size = file_size;
        cache->table[id % cache->capacity]->last_modified = last_modified;
        strcpy(cache->table[id % cache->capacity]->content_hash, hash);
    }

    if (!cache->head) {
        cache->head = entry;
        cache->tail = entry;
    } else {
        move_to_front(cache, entry);
    }

    cache->size++;
    pthread_mutex_unlock(&cache->mutex);

    return NULL;
}

void* lru_cache_access(void* arg) {
    LRUCache* cache = (LRUCache*)arg;
    int id;

    pthread_mutex_lock(&cache->mutex);

    if (id >= 0 && id < cache->capacity && cache->table[id] != NULL) {
        move_to_front(cache, cache->table[id]);
    } else {
        printf("Entry not found.\n");
    }

    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

void destroy_cache(LRUCache* cache) {
    while (cache->head) {
        remove_entry(cache, cache->head);
    }
    free(cache->table);
    pthread_mutex_destroy(&cache->mutex);
    pthread_cond_destroy(&cache->cond);
    free(cache);
}
```

### Key Points:
- **Concurrency Handling**: Mutexes are used to ensure thread-safe operations on the LRU cache.
- **Dynamic Memory Management**: Each metadata entry and its access times are dynamically allocated. The `new_metadata` function initializes these entries, including their content hash.
- **LRU Policy**: Entries are moved to the front of a doubly linked list upon access or insertion to maintain LRU order.
- **Hash Table Lookup**: A simple modulo-based hashing strategy is used for fast ID lookups.
- **Cleanup**: Proper deallocation functions ensure there are no memory leaks.

This code snippet provides a foundational structure and can be expanded with additional features like dynamic resizing, identifier recycling, advanced concurrency strategies (e.g., lock-free techniques), or optimized data structures based on specific needs.']

