    if (result != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->total_memory_used += sizeof(Node);

    // Add node to the head for simplicity
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

