```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the Element structure
typedef struct {
    int key;
    double value;
    char status;
} Element;

// Function to initialize random number generator
void init_random_seed() {
    srand((unsigned) time(NULL));
}

// Function to generate a random double within a given range [min, max]
double random_double(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

// Function to manage resources dynamically
int manage_resources(size_t num_elements, size_t char_array_size, double value_min, double value_max,
                     double **float_array, char **char_array, Element ***element_pointers) {
    // Error handling variables
    int status = 0;

    // Allocate memory for the array of doubles
    *float_array = (double *)malloc(num_elements * sizeof(double));
    if (*float_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for float array.\n");
        return -1;
    }

    // Initialize random seed
    init_random_seed();

    // Allocate memory for the array of chars
    *char_array = (char *)malloc(char_array_size);
    if (*char_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for char array.\n");
        free(*float_array);
        return -1;
    }

    // Allocate memory for the array of pointers to Element structures
    *element_pointers = (Element **)malloc(num_elements * sizeof(Element *));
    if (*element_pointers == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for element pointers.\n");
        free(*float_array);
        free(*char_array);
        return -1;
    }

    // Allocate and initialize each Element structure
    for (size_t i = 0; i < num_elements; ++i) {
        (*element_pointers)[i] = (Element *)malloc(sizeof(Element));
        if ((*element_pointers)[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for element at index %zu.\n", i);
            status = -1;
            // Cleanup in case of failure
            for (size_t j = 0; j < i; ++j) {
                free((*element_pointers)[j]);
            }
            free(*float_array);
            free(*char_array);
            free(*element_pointers);
            return status;
        }

        // Initialize Element's key, value, and status
        (*element_pointers)[i]->key = (int)i;
        (*element_pointers)[i]->value = random_double(value_min, value_max);
        (*element_pointers)[i]->status = 'A';  // Arbitrary default status
    }

    return status; // Return success if all allocations succeeded
}

// Function to free allocated resources
void cleanup_resources(double *float_array, char *char_array, Element **element_pointers, size_t num_elements) {
    if (element_pointers != NULL) {
        for (size_t i = 0; i < num_elements; ++i) {
            free(element_pointers[i]);
        }
        free(element_pointers);
    }
    if (float_array != NULL) {
        free(float_array);
    }
    if (char_array != NULL) {
        free(char_array);
    }
}

int main() {
    // Example usage
    size_t num_elements = 10;
    size_t char_array_size = 100;

    double *float_array;
    char *char_array;
    Element **element_pointers;

    int result = manage_resources(num_elements, char_array_size, 0.0, 1.0,
                                  &float_array, &char_array, &element_pointers);

    if (result == 0) {
        printf("Resources managed successfully.\n");
        // Use allocated resources...
    } else {
        fprintf(stderr, "Failed to manage resources.\n");
    }

    // Cleanup
    cleanup_resources(float_array, char_array, element_pointers, num_elements);

    return 0;
}
```

### Key Points:

- **Error Handling**: Each memory allocation is followed by a check for failure. If an error occurs during any allocation, the code cleans up previously allocated resources to prevent leaks.

- **Random Number Generation**: The function `random_double` generates random numbers within a specified range using `srand` and `rand`.

- **Resource Cleanup**: The `cleanup_resources` function ensures that all dynamically allocated memory is freed properly.

- **Scalability & Performance**: Memory allocation sizes are determined based on input parameters (`num_elements`, `char_array_size`), making the solution scalable. 

- **Dependency Management**: Uses standard C libraries for random number generation and memory management to ensure compatibility with most systems.']

