#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DATA_POINTS 10000
#define MIN_TEMP -50.0
#define MAX_TEMP 120.0

typedef struct {
    char *sensor_id;
    long timestamp[MAX_DATA_POINTS];
    double temperature[MAX_DATA_POINTS];
} SensorData;

typedef struct Node {
    SensorData data;
    struct Node* next;
} Node;

Node* head = NULL;

// Function to generate a unique sensor ID
char* generate_unique_sensor_id(size_t length) {
    static int id_counter = 0;
    char *id = malloc(length + 1);
    if (id == NULL) return NULL;
    sprintf(id, "SENSOR_%05d", ++id_counter);
    return id;
}

// Function to check if sensor ID already exists
int is_unique_sensor_id(char* id) {
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->data.sensor_id, id) == 0) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

// Function to create a new sensor data entry with realistic values
SensorData* initialize_sensor_data(size_t num_sensors) {
    Node** ptr = &head;

    for (size_t i = 0; i < num_sensors; ++i) {
        SensorData* data = malloc(sizeof(SensorData));
        if (!data) break;

        size_t id_length = 10;
        char* sensor_id;
        do {
            sensor_id = generate_unique_sensor_id(id_length);
        } while (!is_unique_sensor_id(sensor_id));

        data->sensor_id = sensor_id;

        srand(time(NULL) + (unsigned int)i); // Seed for randomness
        for (size_t j = 0; j < MAX_DATA_POINTS; ++j) {
            data->timestamp[j] = rand() % 1000000;
            data->temperature[j] = MIN_TEMP + ((double)rand() / RAND_MAX * (MAX_TEMP - MIN_TEMP));
        }

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) break;

        new_node->data = *data;
        new_node->next = NULL;

        *ptr = new_node;
        ptr = &new_node->next;
    }
    return head ? &(head->data) : NULL; // Return first sensor data or NULL
}

// Function to free allocated memory for all sensors
void free_sensor_data() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data.sensor_id);
        free(current);
        current = next;
    }
}

int main() {
    size_t num_sensors = 5; // Example number of sensors
    SensorData* sensors = initialize_sensor_data(num_sensors);

    if (sensors) {
        // Successfully initialized sensor data
        printf("Sensor initialization complete.\n");
    } else {
        // Failed to allocate memory
        printf("Failed to initialize sensors due to insufficient memory.\n");
    }

    free_sensor_data();
    return 0;
}
```

