#include <pthread.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
} Record;

typedef struct Node {
    Record *data;
    struct Node *next;
} Node;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    Node *head;
} DataStructure;

DataStructure* init_data_structure(size_t initial_capacity, int key_min, int key_max) {
    if (initial_capacity <= 0 || key_min >= key_max) return NULL;

    DataStructure *ds = malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    pthread_mutex_init(&ds->lock, NULL);
    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = malloc(initial_capacity * sizeof(int));
    ds->size = 0;
    ds->capacity = initial_capacity;
    ds->head = NULL;

    if (!ds->offsets || !ds->keys) {
        free(ds);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < initial_capacity; ++i) {
        int key = rand() % (key_max - key_min + 1) + key_min;
        ds->keys[i] = key;

        if (i == 0)
            ds->offsets[0] = key;
        else
            ds->offsets[i] = ds->offsets[i - 1] + key + rand() % 10; // Example increment factor

        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            free(ds->head);
            break;
        }

        new_node->data = malloc(sizeof(Record));
        if (!new_node->data) {
            free(new_node);
            break;
        }

        new_node->data->s = rand() % 1000; // Example range
        new_node->data->i = rand() % 10000; // Example range
        new_node->data->f = (float)(rand() % 100) / 10.0f; // Example range

        new_node->next = ds->head;
        ds->head = new_node;

        ds->size++;
    }

    return ds;
}

void resize_data_structure(DataStructure *ds, size_t new_capacity) {
    if (!ds || new_capacity <= ds->capacity) return;

    long *new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(ds->keys, new_capacity * sizeof(int));

    if (new_offsets && new_keys) {
        for (size_t i = ds->size; i < new_capacity; ++i) {
            int key = rand() % 1000; // Example range
            new_keys[i] = key;

            if (i == ds->size)
                new_offsets[i] = ds->offsets[ds->size - 1] + key + rand() % 10;
            else
                new_offsets[i] = new_offsets[i - 1] + key + rand() % 10; // Example increment factor
        }

        ds->capacity = new_capacity;
        ds->offsets = new_offsets;
        ds->keys = new_keys;
    }
}

void free_data_structure(DataStructure *ds) {
    if (!ds) return;

    pthread_mutex_destroy(&ds->lock);

    Node *current = ds->head;
    while (current) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds);
}

void iterate_and_modify(DataStructure *ds, void (*modify_func)(Record *)) {
    if (!ds) return;

    pthread_mutex_lock(&ds->lock);

    Node *current = ds->head;
    while (current) {
        modify_func(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&ds->lock);
}

void example_modify_function(Record *record) {
    if (!record) return;

    record->s += 1; // Example modification
    record->i += 10; // Example modification
    record->f += 0.5f; // Example modification
}
