#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 100 // 100MB, configurable limit
#define LOG_FILE "log.txt"

typedef struct {
    short field1;
    int field2;
    float field3;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t used_memory;
    pthread_mutex_t lock;
} DatasetList;

DatasetList* dataset_list_create() {
    DatasetList* list = (DatasetList*)malloc(sizeof(DatasetList));
    if (!list) {
        log_event("Failed to allocate memory for DatasetList");
        return NULL;
    }
    list->head = NULL;
    list->used_memory = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void log_event(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int dataset_list_insert(DatasetList* list, long offset, int key, Record record) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    size_t new_size = sizeof(Node) + list->used_memory;
    if (new_size > MAX_MEMORY_USAGE) {
        free(new_node);
        log_event("Exceeded maximum memory usage limit");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    new_node->offset = offset;
    new_node->key = key;
    new_node->record = record;
    new_node->next = list->head;

    list->head = new_node;
    list->used_memory += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void dataset_list_destroy(DatasetList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example function to serialize a node
size_t serialize_node(const Node* node, unsigned char** buffer) {
    size_t record_size = sizeof(node->record.field1) +
                         sizeof(node->record.field2) +
                         sizeof(node->record.field3);

    *buffer = (unsigned char*)malloc(record_size);
    if (!(*buffer)) {
        log_event("Failed to allocate memory for serialization");
        return 0;
    }

    memcpy(*buffer, &node->record.field1, sizeof(node->record.field1));
    memcpy((*buffer) + sizeof(node->record.field1), &node->record.field2, sizeof(node->record.field2));
    memcpy((*buffer) + sizeof(node->record.field1) + sizeof(node->record.field2),
           &node->record.field3, sizeof(node->record.field3));

    return record_size;
}

// Example function to deserialize a node
int deserialize_node(Node* node, const unsigned char* buffer) {
    if (!node || !buffer) {
        log_event("Invalid parameters for deserialization");
        return -1;
    }

    memcpy(&node->record.field1, buffer, sizeof(node->record.field1));
    memcpy(&node->record.field2, buffer + sizeof(node->record.field1), sizeof(node->record.field2));
    memcpy(&node->record.field3, buffer + sizeof(node->record.field1) + sizeof(node->record.field2),
           sizeof(node->record.field3));

    return 0;
}

// Additional functions for concurrency management, checkpointing,
// memory monitoring, etc. would be implemented here.

