use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use crossbeam::queue::SegQueue;
use rand::Rng;
use std::fs;
use std::env;

struct Record {
    short_field: i16,
    int_field: i32,
    float_field: f32,
    boolean_flag: bool,
    metadata_flags: u8,
}

struct Node {
    record: Record,
    next: Option<Arc<Mutex<Node>>>,
}

type LinkedList = Arc<Mutex<Option<Node>>>;

fn generate_key(range_start: usize, range_end: usize) -> usize {
    let mut rng = rand::thread_rng();
    rng.gen_range(range_start..=range_end)
}

fn calculate_offset(keys: &[usize]) -> u64 {
    keys.iter().sum::<usize>() as u64 + 100
}

fn initialize_records(record_count: usize, short_range: (i16, i16), int_range: (i32, i32)) -> LinkedList {
    let mut head = Arc::new(Mutex::new(None));
    let mut current_tail = &head;
    let keys: Vec<usize> = (0..record_count)
        .map(|_| generate_key(1000, 9999))
        .collect();
    let offset = calculate_offset(&keys);

    for i in 0..record_count {
        let record = Record {
            short_field: rand::thread_rng().gen_range(short_range.0..=short_range.1),
            int_field: rand::thread_rng().gen_range(int_range.0..=int_range.1),
            float_field: rand::thread_rng().gen(),
            boolean_flag: (keys[i] % 2 == 0) as bool,
            metadata_flags: 0, // Initialize to zero; customize logic if needed
        };

        let new_node = Arc::new(Mutex::new(Node {
            record,
            next: None,
        }));

        {
            let mut tail_lock = current_tail.lock().unwrap();
            (*tail_lock).as_mut().unwrap().next.replace(new_node.clone());
            *current_tail = &new_node;
        }
    }

    head
}

fn create_hash_table(linked_list: &LinkedList) -> HashMap<usize, Arc<Mutex<Node>>> {
    let mut hash_table: HashMap<usize, Arc<Mutex<Node>>> = HashMap::new();
    let mut current = linked_list.lock().unwrap();

    while let Some(node) = *current.as_ref() {
        if let Ok(mut node_lock) = node.lock() {
            hash_table.insert(node_lock.record.metadata_flags as usize, node_lock.clone());
        }
        current = &node_lock.next;
    }

    hash_table
}

fn create_directory_and_set_env(directory_name: &str) -> Result<(), std::io::Error> {
    let path = format!("./{}", directory_name);

    if env::var_os("APP_DIR").is_none() || !path.exists() {
        fs::create_dir_all(&path)?;
        env::set_var("APP_DIR", path);
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let linked_list = initialize_records(1000, (-32768..=32767), (-2147483648..=2147483647));
    let hash_table = create_hash_table(&linked_list);

