    symmetric_encrypt(encrypted_record, sizeof(Record)); // Example encryption
    free(key_id);

    array->data[array->size++] = encrypted_record;
    pthread_rwlock_unlock(&array->lock);
}

// Iterator for the dynamic array
typedef struct {
    EncryptedArray *array;
    size_t index;
} ArrayIterator;

// Create an iterator
ArrayIterator* create_iterator(EncryptedArray *array) {
    ArrayIterator *iter = malloc(sizeof(ArrayIterator));
    if (!iter) return NULL;

    iter->array = array;
    iter->index = 0;
    pthread_rwlock_rdlock(&array->lock);

    return iter;
}

// Get the next record in the iterator
Record get_next_record(ArrayIterator *iter) {
    if (iter->index >= iter->array->size) {
        free(iter);
        return (Record){ .s = 0, .i = 0, .f = 0.0, .b = 0 };
    }

    void *encrypted_record = iter->array->data[iter->index++];
    Record rec;
    decrypt_data(encrypted_record, sizeof(Record)); // Example decryption
    memcpy(&rec, encrypted_record, sizeof(Record));

    return rec;
}

// Free the dynamic array
