    pthread_rwlock_wrlock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    pthread_rwlock_unlock(&array->lock);
    pthread_rwlock_destroy(&array->lock);
    free(array);
}

// Lock-free hash table with dynamic resizing
