    start_tm.tm_year = min_year - 1900;
    end_tm.tm_year = max_year - 1900;

    srand((unsigned int)time(NULL)); // Seed with current time
    return (rand() % (mktime(&end_tm) - mktime(&start_tm))) + mktime(&start_tm);
}

static void initialize_hash_table(HashTable *ht) {
    ht->table = safe_malloc(sizeof(Document*) * HASH_TABLE_SIZE);
    memset(ht->table, 0, sizeof(Document*) * HASH_TABLE_SIZE);
    pthread_mutex_init(&ht->lock, NULL);
    ht->total_storage_used = 0;
    ht->document_count = 0;
}

static void free_document(Document* doc) {
