        free(doc->key);
        // Free content data if needed
        free(doc);
    }
}

static int add_document(HashTable *ht, const char *key, Content content) {
    pthread_mutex_lock(&ht->lock);

    size_t key_length = strlen(key);
    unsigned int index = hash_function(key);
    Document* new_doc = safe_malloc(sizeof(Document));
    new_doc->offset = ht->total_storage_used;
    new_doc->key = strdup(key);
    new_doc->content = content;

    // Insert into hash table
    new_doc->next = ht->table[index];
    ht->table[index] = new_doc;

    // Update metadata
    ht->total_storage_used += key_length + sizeof(Content); // Simplified storage size estimation
    ht->document_count++;

    pthread_mutex_unlock(&ht->lock);

    return 0; // Return status code for success or failure as needed
}

static void iterate_hash_table(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Document* doc = ht->table[i];
        while (doc) {
            printf("Key: %s, Offset: %zu\n", doc->key, doc->offset);
            doc = doc->next;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

static void free_hash_table(HashTable *ht) {
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Document* doc = ht->table[i];
        while (doc) {
            Document* next = doc->next;
            free_document(doc);
            doc = next;
        }
