    if (!new_record) {
        fprintf(stderr, "Memory allocation for record failed\n");
        exit(EXIT_FAILURE);
    }

    populate_record(new_record);
    new_record->next = records_head;
    records_head = new_record;

    pthread_mutex_unlock(&lock);
}

void iterate_records() {
    Record* current = records_head;
    while (current) {
        // Process each record
        process_record(current);

        current = current->next;
    }
}

void garbage_collect() {
    pthread_mutex_lock(&lock);

    Record *prev, *curr;
    for (prev = NULL, curr = records_head; curr != NULL;) {
        if (!is_active(curr)) { // Implement is_active to check if record should be kept
            Record* temp = curr;
            if (prev) prev->next = curr->next;
            else records_head = curr->next;

            free(temp);
            curr = curr->next;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    pthread_mutex_unlock(&lock);
}

void log_record_creation(Record* record) {
