['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_ERROR
} Status;

typedef struct {
    short short_field;
    int int_field;
    float float_field;
    Status status;
    uint64_t metadata; // Hash of key and index
} Record;

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct MemoryPoolNode {
    void *memory;
    size_t size;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *freeList;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct RecordNode {
    Record record;
    struct RecordNode *next;
} RecordNode;

typedef struct {
    RecordNode *head;
    RecordNode *tail;
    size_t capacity;
    size_t size;
    pthread_rwlock_t rwlock;
    MemoryPool pool;
    int (*hash_function)(const char *, size_t, size_t);
} DynamicCollection;

static uint64_t generate_hash(const char *key, size_t index) {
    // Simple hash function for demonstration
    uint64_t hash = 5381;
    while (*key) {
        hash = ((hash << 5) + hash) + (unsigned char)(*key++);
    }
    return hash ^ index;
}

void memory_pool_init(MemoryPool *pool) {
    pool->freeList = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

void *memory_pool_alloc(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode *node = pool->freeList;
    if (node) {
        pool->freeList = node->next;
        pthread_mutex_unlock(&pool->lock);
        return node->memory;
    }

    void *memory = malloc(size + sizeof(MemoryPoolNode));
    if (!memory) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    MemoryPoolNode *newNode = (MemoryPoolNode *)memory;
    newNode->size = size;
    newNode->next = NULL;

    pthread_mutex_unlock(&pool->lock);
    return ((char *)memory) + sizeof(MemoryPoolNode);
}

void memory_pool_free(MemoryPool *pool, void *ptr) {
    if (!ptr) return;

    MemoryPoolNode *node = (MemoryPoolNode *)((char *)ptr - sizeof(MemoryPoolNode));

    pthread_mutex_lock(&pool->lock);
    node->next = pool->freeList;
    pool->freeList = node;
    pthread_mutex_unlock(&pool->lock);
}

void dynamic_collection_init(DynamicCollection *collection, int (*hash_func)(const char *, size_t, size_t)) {
    collection->head = NULL;
    collection->tail = NULL;
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_rwlock_init(&collection->rwlock, NULL);
    memory_pool_init(&collection->pool);
    collection->hash_function = hash_func ? hash_func : generate_hash;
}

void dynamic_collection_free(DynamicCollection *collection) {
    RecordNode *current = collection->head;
    while (current) {
        RecordNode *next = current->next;
        void *memory = ((char *)current) - sizeof(RecordNode);
        memory_pool_free(&collection->pool, memory);
        current = next;
    }
    pthread_rwlock_destroy(&collection->rwlock);
}

void dynamic_collection_resize(DynamicCollection *collection) {
    pthread_rwlock_wrlock(&collection->rwlock);

    size_t new_capacity = collection->capacity * GROWTH_FACTOR;
    RecordNode **new_array = malloc(new_capacity * sizeof(RecordNode *));
    if (!new_array) return;

    for (size_t i = 0; i < collection->size; ++i) {
        new_array[i] = NULL;
    }

    RecordNode *current = collection->head;
    size_t index = 0;
    while (current && index < collection->capacity) {
        new_array[index++] = current;
        current = current->next;
    }

    collection->capacity = new_capacity;
    free(new_array);
    pthread_rwlock_unlock(&collection->rwlock);
}

void dynamic_collection_add_record(DynamicCollection *collection, const char *key, size_t index) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (collection->size == collection->capacity) {
        dynamic_collection_resize(collection);
    }

    RecordNode *node = memory_pool_alloc(&collection->pool, sizeof(RecordNode));
    node->record.short_field = rand() % 1000;
    node->record.int_field = rand() % 10000;
    node->record.float_field = (float)rand() / RAND_MAX * 100.0f;
    node->record.status = STATUS_ACTIVE;
    node->record.metadata = collection->hash_function(key, index, sizeof(uint64_t));

    if (!collection->head) {
        collection->head = node;
    } else {
        collection->tail->next = node;
    }
    collection->tail = node;
    ++collection->size;

    pthread_rwlock_unlock(&collection->rwlock);
}

void dynamic_collection_iterate(DynamicCollection *collection, void (*process_record)(Record *)) {
    pthread_rwlock_rdlock(&collection->rwlock);

    RecordNode *current = collection->head;
    while (current) {
        process_record(&current->record);
        current = current->next;
    }

    pthread_rwlock_unlock(&collection->rwlock);
}

void process_sample_record(Record *record) {
    printf("Processing record: short=%d, int=%d, float=%.2f, status=%d, metadata=%llu\n",
           record->short_field,
           record->int_field,
           record->float_field,
           record->status,
           (unsigned long long)record->metadata);
}

// Example Usage
int main() {
    srand(time(NULL));

    DynamicCollection collection;
    dynamic_collection_init(&collection, NULL);

    for (size_t i = 0; i < 100; ++i) {
        dynamic_collection_add_record(&collection, "key", i);
    }

    dynamic_collection_iterate(&collection, process_sample_record);

    dynamic_collection_free(&collection);

    return 0;
}
```

