using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using ProtoBuf;

public class DataProcessor
{
    private static readonly HttpClient httpClient = new HttpClient();

    public async Task ProcessFilesAsync(string[] filePaths)
    {
        var fileTasks = filePaths.Select(ProcessFileAsync).ToArray();

        try
        {
            await Task.WhenAll(fileTasks);
        }
        catch (Exception ex)
        {
            LogError("An error occurred while processing files: " + ex.Message);
        }
    }

    private async Task ProcessFileAsync(string filePath)
    {
        try
        {
            using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
            var headerBuffer = new byte[4];
            await fileStream.ReadAsync(headerBuffer, 0, headerBuffer.Length);

            int dataTypeId = BitConverter.ToInt32(headerBuffer, 0);

            switch (dataTypeId)
            {
                case 1:
                    ProcessTypeOne(fileStream);
                    break;
                case 2:
                    ProcessTypeTwo(fileStream);
                    break;
                default:
                    LogError($"Unknown data type ID: {dataTypeId} in file: {filePath}");
                    break;
            }

            await ValidateDataAsync(filePath);

        }
        catch (Exception ex)
        {
            LogError($"Failed to process file {filePath}: {ex.Message}");
        }
    }

    private void ProcessTypeOne(Stream inputStream)
    {
        try
        {
            var data = Serializer.Deserialize<TypeOne>(inputStream);
            // Handle the deserialized data for TypeOne
        }
        catch (Exception ex)
        {
            LogError($"Failed to deserialize TypeOne: {ex.Message}");
        }
    }

    private void ProcessTypeTwo(Stream inputStream)
    {
        try
        {
            var data = Serializer.Deserialize<TypeTwo>(inputStream);
            // Handle the deserialized data for TypeTwo
        }
        catch (Exception ex)
        {
            LogError($"Failed to deserialize TypeTwo: {ex.Message}");
        }
    }

    private async Task ValidateDataAsync(string filePath)
    {
        try
        {
            var response = await httpClient.PostAsJsonAsync("https://validation-service.com/validate", new { FilePath = filePath });

            if (!response.IsSuccessStatusCode)
            {
                LogError($"Validation failed for file: {filePath} with status code: {response.StatusCode}");
            }
        }
        catch (HttpRequestException ex)
        {
            LogError($"Network error during validation for file {filePath}: {ex.Message}");
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism, e.g., to a file or monitoring system
        Console.WriteLine(message);
    }
}

