    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    long* offsets;
    int* keys;
    Node* head;
    pthread_mutex_t lock;
} MemoryManager;

// High-quality random number generator
void init_random() {
    srand((unsigned)time(NULL));
}

int generate_unique_key(int range, int* keys, size_t count) {
    while (1) {
        int key = rand() % range;
        for (size_t i = 0; i < count; ++i) {
            if (keys[i] == key) return -1;
        }
        return key;
    }
}

long calculate_offset(int* keys, size_t index) {
    long offset = 0;
    for (size_t i = 0; i <= index; ++i) {
        offset += keys[i];
    }
    return offset + 100; // example constant value
}

void initialize_arrays(MemoryManager* manager, size_t count, int key_range) {
    manager->offsets = malloc(count * sizeof(long));
    manager->keys = malloc(count * sizeof(int));

    for (size_t i = 0; i < count; ++i) {
        while (1) {
            int key = generate_unique_key(key_range, manager->keys, i);
            if (key != -1) break;
        }
        manager->keys[i] = key;
        manager->offsets[i] = calculate_offset(manager->keys, i);
    }
}

Node* create_node() {
    Node* node = malloc(sizeof(Node));
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void initialize_record(Record* record) {
    record->s = rand() % 1000; // example range
    record->i = rand() % 1000000; // example range
    record->f = (float)(rand() / (RAND_MAX + 1.0)); // example range [0, 1)
    record->timestamp = time(NULL);
    record->size = rand() % 1024; // example range
}

void initialize_linked_list(MemoryManager* manager, size_t count) {
    pthread_mutex_init(&manager->lock, NULL);

    Node* current;
    for (size_t i = 0; i < count; ++i) {
        current = create_node();
        initialize_record(&current->record);

        if (!manager->head) {
            manager->head = current;
        } else {
            Node* tail = manager->head;
            while (tail->next) {
                tail = tail->next;
            }
            tail->next = current;
            current->prev = tail;
        }
    }
}

void resize_arrays(MemoryManager* manager, size_t new_count) {
    pthread_mutex_lock(&manager->lock);

    long* new_offsets = realloc(manager->offsets, new_count * sizeof(long));
    int* new_keys = realloc(manager->keys, new_count * sizeof(int));

    if (new_offsets && new_keys) {
        for (size_t i = manager->offsets ? (sizeof(manager->offsets) / sizeof(long)) : 0; i < new_count; ++i) {
            while (1) {
                int key = generate_unique_key(100000, manager->keys, i);
                if (key != -1) break;
            }
            manager->keys[i] = key;
            manager->offsets[i] = calculate_offset(manager->keys, i);
        }
    }

    pthread_mutex_unlock(&manager->lock);

    if (!new_offsets || !new_keys) {
        // handle allocation failure
        fprintf(stderr, "Failed to resize arrays.\n");
        exit(EXIT_FAILURE);
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
}

void iterate_linked_list(MemoryManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        printf("Record: s=%d, i=%d, f=%.2f, timestamp=%ld, size=%zu\n",
               current->record.s,
               current->record.i,
               current->record.f,
               current->record.timestamp,
               current->record.size);
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_memory(MemoryManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(manager->offsets);
    free(manager->keys);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    MemoryManager manager = {0};
    size_t initial_count = 10;
    int key_range = 100000;

    init_random();
    initialize_arrays(&manager, initial_count, key_range);
    initialize_linked_list(&manager, initial_count);

    iterate_linked_list(&manager);

    // Simulate dynamic resizing
    resize_arrays(&manager, 20);
    iterate_linked_list(&manager);

    free_memory(&manager);
    return 0;
}
