#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

// Metadata structure definition
typedef struct {
    time_t timestamp;
    int flags;
} Metadata;

// Record structure definition
typedef struct Record {
    short s_field;
    int i_field;
    float f_field;
    Metadata* metadata;
    struct Record *next, *prev;
} Record;

// Linked list structure definition
typedef struct {
    Record **offsets;
    int *keys;
    int size;
    int capacity;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
LinkedList* create_linked_list(int initial_capacity);
void destroy_linked_list(LinkedList *list);
Record* create_record();
Metadata* create_metadata();
int generate_unique_key(int min, int max, int used_keys[], int num_used_keys);
void resize_arrays_if_needed(LinkedList *list);
void compress_and_free_space(LinkedList *list);

// Create a new linked list
LinkedList* create_linked_list(int initial_capacity) {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->offsets = (Record **)malloc(initial_capacity * sizeof(Record *));
    list->keys = (int *)malloc(initial_capacity * sizeof(int));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    if (!list->offsets || !list->keys) {
        destroy_linked_list(list);
        return NULL;
    }

    for (int i = 0; i < initial_capacity; ++i) {
        list->offsets[i] = NULL;
        list->keys[i] = -1; // Mark as unused
    }

    srand(time(NULL)); // Seed random number generator

    return list;
}

// Destroy the linked list and free memory
void destroy_linked_list(LinkedList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        if (list->offsets[i]) {
            free(list->offsets[i]->metadata); // Free metadata
            free(list->offsets[i]);           // Free record
        }
    }

    free(list->keys);
    free(list->offsets);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

