}

// Generate a unique key within the specified range, ensuring no duplicates
int generate_unique_key(int min, int max, int used_keys[], int num_used_keys) {
    int new_key;
    do {
        new_key = rand() % (max - min + 1) + min;
    } while (is_duplicate(new_key, used_keys, num_used_keys));

    return new_key;
}

// Check if a key is already in use
int is_duplicate(int key, int *used_keys, int num_used_keys) {
    for (int i = 0; i < num_used_keys; ++i) {
        if (used_keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

// Resize arrays if needed to handle more records
void resize_arrays_if_needed(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) { // Need resizing
        int new_capacity = list->capacity * 2;

        Record **new_offsets = (Record **)realloc(list->offsets, new_capacity * sizeof(Record *));
        int *new_keys = (int *)realloc(list->keys, new_capacity * sizeof(int));

        if (!new_offsets || !new_keys) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle reallocation failure gracefully
        }

        list->offsets = new_offsets;
        list->keys = new_keys;

        for (int i = list->capacity; i < new_capacity; ++i) {
            list->offsets[i] = NULL;
            list->keys[i] = -1; // Mark as unused
        }

        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

// Compress and free space in the linked list by removing unused slots or merging blocks
void compress_and_free_space(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    // A simple compression strategy that compacts used records to the beginning of arrays
    int write_index = 0;
    for (int read_index = 0; read_index < list->size; ++read_index) {
        if (list->offsets[read_index]) {
            if (read_index != write_index) {
                // Move record and key forward
                list->offsets[write_index] = list->offsets[read_index];
                list->keys[write_index] = list->keys[read_index];

                // Update linked pointers, assuming they are maintained correctly elsewhere
                if (list->offsets[write_index]->prev) {
                    list->offsets[write_index]->prev = 
                        (write_index > 0) ? list->offsets[write_index - 1] : NULL;
                }
                if (list->offsets[write_index]->next && read_index + 1 < list->size) {
                    list->offsets[write_index]->next = list->offsets[read_index + 1];
                    if (list->offsets[write_index]->next)
                        list->offsets[write_index]->next->prev = list->offsets[write_index];
                }

                // Clear the old location
                list->offsets[read_index] = NULL;
                list->keys[read_index] = -1;
            }
            ++write_index;
        }
    }

    // Adjust size to reflect new compacted array size
    list->size = write_index;

    pthread_mutex_unlock(&list->lock);
}

// Example function usage within main or other functions:
int main() {
    LinkedList *list = create_linked_list(10);

    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return EXIT_FAILURE;
    }

    // Add records and manipulate the list as necessary here

    destroy_linked_list(list);

    return EXIT_SUCCESS;
}
