}

void deserializeLinkedList(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    Record *current = list->head;
    while (current != NULL) {
        Record *newRecord = getFromMemoryPool();
        fread(newRecord, sizeof(Record), 1, file);
        newRecord->next = NULL;

        // Append to linked list
        pthread_mutex_lock(&list->lock);
        if (!list->head) {
            list->head = newRecord;
        } else {
            Record *temp = list->head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newRecord;
        }
        pthread_mutex_unlock(&list->lock);

        current = newRecord;
    }

    fclose(file);
}

// Cleanup function
void cleanupLinkedList(LinkedList *list) {
