#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_OFFSET_SIZE 10
#define INITIAL_KEY_SIZE 10
#define KEY_RANGE 1000

typedef struct Record {
    int short_field;
    int int_field;
    struct Record *next;
    struct Record *prev; // For doubly-linked list
} Record;

typedef struct LinkedList {
    Record *head;
    Record *tail;
    pthread_mutex_t lock;
    int *offsets;
    int *keys;
    size_t offset_size;
    size_t key_size;
} LinkedList;

// Custom allocator for the linked list
LinkedList* create_linked_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->offsets = (int *)malloc(INITIAL_OFFSET_SIZE * sizeof(int));
    list->keys = (int *)malloc(INITIAL_KEY_SIZE * sizeof(int));
    if (!list->offsets || !list->keys) {
        free(list);
        return NULL;
    }
    list->offset_size = INITIAL_OFFSET_SIZE;
    list->key_size = INITIAL_KEY_SIZE;

    memset(list->offsets, 0, INITIAL_OFFSET_SIZE * sizeof(int));
    for (size_t i = 0; i < INITIAL_KEY_SIZE; ++i) {
        list->keys[i] = rand() % KEY_RANGE + 1;
    }

    return list;
}

void resize_arrays(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    if (list->offset_size == list->offsets) {
        int *new_offsets = (int *)realloc(list->offsets, (list->offset_size * 2) * sizeof(int));
        if (!new_offsets) return;
        list->offsets = new_offsets;
        list->offset_size *= 2;
    }
    if (list->key_size == list->keys) {
        int *new_keys = (int *)realloc(list->keys, (list->key_size * 2) * sizeof(int));
        if (!new_keys) return;
        list->keys = new_keys;
        for (size_t i = list->key_size; i < list->key_size * 2; ++i) {
            list->keys[i] = rand() % KEY_RANGE + 1;
        }
        list->key_size *= 2;
    }
    pthread_mutex_unlock(&list->lock);
}

void calculate_offsets(LinkedList *list) {
    int cumulative_sum = 0;
    for (size_t i = 0; i < list->key_size; ++i) {
        cumulative_sum += list->keys[i];
        list->offsets[i] = cumulative_sum;
    }
}

void add_record(LinkedList *list, int short_value, int int_value) {
    pthread_mutex_lock(&list->lock);
    resize_arrays(list);

    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_record->short_field = short_value;
    new_record->int_field = int_value;
    new_record->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_record;
        new_record->prev = NULL;
    } else {
        list->tail->next = new_record;
        new_record->prev = list->tail;
        list->tail = new_record;
    }

    size_t key_index = (list->key_size - 1) % list->key_size;
    list->keys[key_index] = rand() % KEY_RANGE + 1;
    calculate_offsets(list);

    pthread_mutex_unlock(&list->lock);
}

void traverse_forward(LinkedList *list, void (*process)(Record *)) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current) {
        process(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void traverse_backward(LinkedList *list, void (*process)(Record *)) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->tail;
    while (current) {
        process(current);
        current = current->prev;
    }
    pthread_mutex_unlock(&list->lock);
}

void compress_list(LinkedList *list) {
    // Placeholder for compression logic
}

void log_operation(const char *operation, Record *record) {
    // Placeholder for logging logic
}

void destroy_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    free(list->offsets);
    free(list->keys);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList *list = create_linked_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return 1;
    }

    // Example usage
    add_record(list, rand() % 100, rand() % 1000);

    traverse_forward(list, [](Record *record) {
        printf("Short: %d, Int: %d\n", record->short_field, record->int_field);
    });

    destroy_linked_list(list);
    return 0;
}
