char* read_sensor_ids(const char *filename, char sensor_ids[][50], size_t max_ids) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL; // Fallback to default

    char line[50];
    size_t count = 0;
    while (fgets(line, sizeof(line), file)) {
        if (count < max_ids) {
            line[strcspn(line, "\n")] = '\0'; // Remove newline
            strncpy(sensor_ids[count], line, sizeof(sensor_ids[0]));
            count++;
        }
    }

    fclose(file);
    return (count > 0) ? NULL : DEFAULT_SENSOR_ID;
}

void generate_random_timestamp(double *timestamp) {
    *timestamp = TIMESTAMP_MIN + ((double)rand() / RAND_MAX) * (TIMESTAMP_MAX - TIMESTAMP_MIN);
}

SensorData* initialize_trajectory_data(const char *config_file, size_t num_sensors, size_t trajectories_per_sensor) {
    srand(time(NULL));

    SensorData *sensor_data_array = malloc(num_sensors * sizeof(SensorData));
    if (!sensor_data_array) return NULL;

    char sensor_ids[MAX_SENSOR_IDS][50];
    char *fallback_id = read_sensor_ids(config_file, sensor_ids, MAX_SENSOR_IDS);
    size_t num_valid_ids = (fallback_id == NULL) ? strlen(sensor_ids) : 0;

    for (size_t i = 0; i < num_sensors && i < num_valid_ids; ++i) {
        SensorData *sensor_data = &sensor_data_array[i];

        sensor_data->num_trajectories = trajectories_per_sensor;
        sensor_data->trajectories = malloc(trajectories_per_sensor * sizeof(Trajectory*));
        if (!sensor_data->trajectories) {
            // Cleanup and exit
            for (size_t j = 0; j < i; ++j)
                free(sensor_data_array[j].trajectories);
            free(sensor_data_array);
            return NULL;
        }

        char *id_to_use = (fallback_id == NULL) ? sensor_ids[i] : fallback_id;
        char *sensor_id_str = strdup(id_to_use);
        if (!sensor_id_str) {
            // Cleanup and exit
            for (size_t j = 0; j <= i; ++j) free(sensor_data_array[j].trajectories);
            free(sensor_data_array);
            return NULL;
        }

        for (size_t j = 0; j < trajectories_per_sensor; ++j) {
            Trajectory *trajectory = malloc(sizeof(Trajectory));
            if (!trajectory) {
                // Cleanup and exit
                for (size_t k = 0; k <= j; ++k) free(sensor_data->trajectories[k]);
                free(sensor_data->trajectories);
                for (size_t l = 0; l < i; ++l) free(sensor_data_array[l].trajectories);
                free(sensor_data_array);
                free(sensor_id_str);
                return NULL;
            }

            trajectory->sensor_id = sensor_id_str;
            generate_random_timestamp(&trajectory->timestamp);
            sensor_data->trajectories[j] = trajectory;
        }

        // Assign random coordinates for the point
        sensor_data->point.x = (double)rand() / RAND_MAX * 100.0;
        sensor_data->point.y = (double)rand() / RAND_MAX * 100.0;
    }

    return sensor_data_array;
}

void free_trajectory_data(SensorData *sensor_data_array, size_t num_sensors) {
    for (size_t i = 0; i < num_sensors; ++i) {
        SensorData *sensor_data = &sensor_data_array[i];
        for (size_t j = 0; j < sensor_data->num_trajectories; ++j) {
            free(sensor_data->trajectories[j]->sensor_id);
            free(sensor_data->trajectories[j]);
        }
        free(sensor_data->trajectories);
    }
    free(sensor_data_array);
}

int main() {
    size_t num_sensors = 5;
    size_t trajectories_per_sensor = 10;

    SensorData *data = initialize_trajectory_data("sensor_ids.txt", num_sensors, trajectories_per_sensor);
    if (data) {
        // Use the data
        free_trajectory_data(data, num_sensors);
    }

    return 0;
}
