['Below is a C implementation for managing a dynamic collection of records in a multi-threaded environment. The code uses mutexes to ensure thread-safe operations when adding or retrieving records, with error handling for memory allocations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

// Initializes the collection
Collection* init_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->entries = (Entry *)calloc(initial_capacity, sizeof(Entry));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

// Adds a record to the collection
int add_record(Collection *collection, long offset, int key, int value) {
    if (!collection || !pthread_mutex_lock(&collection->lock)) return -1;

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Entry *new_entries = (Entry *)realloc(collection->entries, new_capacity * sizeof(Entry));

        if (!new_entries) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }

        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }

    Entry *entry = &collection->entries[collection->count++];
    entry->offset = offset;
    entry->key = key;
    entry->record.value = value;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

// Retrieves a record by index, ensuring safe access in a multi-threaded environment
int get_record(const Collection *collection, size_t index, Entry **entry) {
    if (!collection || !pthread_mutex_lock(&collection->lock)) return -1;

    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Index out of bounds
    }

    *entry = &collection->entries[index];
    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

// Deallocates the collection and frees memory
void free_collection(Collection **collection) {
    if (!collection || !*collection) return;

    Collection *col = *collection;

    pthread_mutex_lock(&col->lock);
    free(col->entries);
    pthread_mutex_unlock(&col->lock);

    pthread_mutex_destroy(&col->lock);
    free(col);

    *collection = NULL; // Avoid dangling pointer
}

// Example usage of the collection in a multi-threaded application

void* thread_func(void *arg) {
    Collection *collection = (Collection *)arg;

    for (int i = 0; i < 10; ++i) {
        add_record(collection, i * 100L, i, i * 10);
    }

    return NULL;
}

int main() {
    size_t initial_capacity = 5;
    Collection *collection = init_collection(initial_capacity);

    if (!collection) {
        fprintf(stderr, "Failed to initialize collection\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[2];
    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, collection)) {
            free_collection(&collection);
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    Entry *entry;
    for (size_t i = 0; i < collection->count; ++i) {
        if (get_record(collection, i, &entry) == 0) {
            printf("Record %zu: Offset=%ld, Key=%d, Value=%d\n", 
                   i, entry->offset, entry->key, entry->record.value);
        }
    }

    free_collection(&collection);
    return EXIT_SUCCESS;
}
```

### Highlights:
- **Memory Management:** This implementation allows dynamic resizing to handle varying workloads and uses `realloc` for flexible capacity adjustments.
- **Thread Safety:** Mutex locks are used to ensure safe concurrent access, preventing race conditions when modifying the collection.
- **Error Handling:** The code includes checks for memory allocation failures and bounds checking for accessing records by index.
- **Dynamic Allocation vs. Fixed Pool:** A dynamic approach is chosen to handle varying sizes of input efficiently without predefining limits, providing flexibility at the cost of potential reallocation overhead.

This setup provides a thread-safe way to manage dynamically sized collections in multi-threaded applications, balancing performance and safety.']

