    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int key;
        if (sscanf(line, "%d", &key) == 1) {
            manager->key_count++;
            manager->key_array = realloc(manager->key_array, manager->key_count * sizeof(int));
            manager->key_array[manager->key_count - 1] = key;
        } else {
            fprintf(stderr, "Error: Incorrect format in file %s.\n", CSV_FILENAME);
        }
    }
    fclose(file);
}

void populate_trajectory(trajectory *traj) {
    int rand_index = rand() % STRING_POOL_SIZE;
    traj->name = strdup(string_pool[rand_index]);
    traj->value = (double)rand() / RAND_MAX * 100.0; // Random value between 0 and 100
}

void add_record(MemoryManager *manager, trajectory *traj) {
    pthread_mutex_lock(&manager->lock);
    if (manager->record_size >= MAX_RECORDS) {
        free(manager->record_list[0]->name);
        free(manager->record_list[0]);
        memmove(manager->record_list, manager->record_list + 1, (MAX_RECORDS - 1) * sizeof(trajectory *));
        manager->record_size--;
    }
    manager->record_list = realloc(manager->record_list, (manager->record_size + 2) * sizeof(trajectory *));
    manager->record_list[manager->record_size + 1] = traj;
    manager->record_size++;
    pthread_mutex_unlock(&manager->lock);
}

void free_memory(MemoryManager *manager) {
    for (int i = 0; i <= manager->record_size; i++) {
        if (manager->record_list[i]) {
            free(manager->record_list[i]->name);
            free(manager->record_list[i]);
        }
    }
    free(manager->record_list);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL));

    MemoryManager manager;
    init_memory_manager(&manager, MAX_RECORDS);

    load_keys_from_csv(&manager);

    for (int i = 0; i < 10; i++) {
        trajectory *traj = malloc(sizeof(trajectory));
        populate_trajectory(traj);
        add_record(&manager, traj);
    }

    free_memory(&manager);

    return 0;
}
```

### Key Points:

- **Thread Safety:** Uses `pthread_mutex_t` to ensure thread safety when modifying shared data structures.
- **CSV Handling:** Reads keys from a CSV file with error handling for file not found and incorrect formats.
- **LRU Mechanism:** Automatically removes the least recently used record when the list exceeds its maximum size.
- **Logging:** Error messages are printed to `stderr` for debugging purposes.
- **Memory Management:** Allocates and frees memory dynamically, ensuring no leaks.']

