#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <string.h>

// Metadata structure definition
typedef struct {
    time_t timestamp;
    unsigned int flags;
} Metadata;

// Record structure definition
typedef struct {
    short s_val;
    int i_val;
    float f_val;
    Metadata *metadata;
} Record;

// Memory pool for efficient allocation
typedef struct {
    size_t block_size;
    size_t total_blocks;
    void **blocks;
} MemoryPool;

// Data store structure with dynamic arrays and synchronization primitives
typedef struct {
    atomic_uint key_counter;
    pthread_mutex_t lock;
    size_t capacity;
    Record **records;
    size_t *offsets; // For dynamic resizing support
    Metadata **metadata_pool; // Separate memory pool for metadata
} DataStore;

// Function prototypes
void init_memory_pool(MemoryPool *pool, size_t block_size, size_t total_blocks);
void destroy_memory_pool(MemoryPool *pool);

Record* create_record();
Metadata* allocate_metadata();
int populate_record(Record *record);
DataStore* initialize_datastore(size_t initial_capacity);
void resize_datastore(DataStore *ds, size_t new_capacity);
void free_datastore(DataStore *ds);

// Memory pool functions
void init_memory_pool(MemoryPool *pool, size_t block_size, size_t total_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->blocks = malloc(total_blocks * sizeof(void*));

    for (size_t i = 0; i < total_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
}

void destroy_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->total_blocks; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
}

// Record and metadata functions
Record* create_record() {
    return (Record*) malloc(sizeof(Record));
}

Metadata* allocate_metadata() {
    Metadata *metadata = (Metadata *)malloc(sizeof(Metadata));
    if (!metadata) {
        perror("Failed to allocate memory for metadata");
        exit(EXIT_FAILURE);
    }
    return metadata;
}

int populate_record(Record *record) {
    record->s_val = rand() % 10000; // Example range
    record->i_val = rand() % 1000000; // Example range
    record->f_val = (float)(rand() / (RAND_MAX + 1.0)); // Random float [0, 1)
    return 0;
}

// Datastore functions
DataStore* initialize_datastore(size_t initial_capacity) {
    DataStore *ds = (DataStore*)malloc(sizeof(DataStore));
    if (!ds) {
        perror("Failed to allocate memory for datastore");
        exit(EXIT_FAILURE);
    }

    ds->capacity = initial_capacity;
    ds->key_counter = 0;

    pthread_mutex_init(&ds->lock, NULL);

    ds->records = (Record**) malloc(initial_capacity * sizeof(Record*));
    ds->offsets = (size_t*) malloc(initial_capacity * sizeof(size_t));

    // Initialize memory pool for metadata
    init_memory_pool((MemoryPool*)&(ds->metadata_pool), sizeof(Metadata), initial_capacity);

    return ds;
}

void resize_datastore(DataStore *ds, size_t new_capacity) {
    pthread_mutex_lock(&ds->lock);

    Record **new_records = (Record**) realloc(ds->records, new_capacity * sizeof(Record*));
    size_t *new_offsets = (size_t*) realloc(ds->offsets, new_capacity * sizeof(size_size));

    if (new_records && new_offsets) {
        ds->records = new_records;
        ds->offsets = new_offsets;
        ds->capacity = new_capacity;

        // Resize metadata pool as well
        MemoryPool *meta_pool = (MemoryPool*)&(ds->metadata_pool);
        meta_pool->blocks = realloc(meta_pool->blocks, new_capacity * sizeof(void*));

        for (size_t i = ds->capacity / 2; i < new_capacity; ++i) {
            meta_pool->blocks[i] = malloc(sizeof(Metadata));
            ds->records[i] = create_record();
        }
    }

    pthread_mutex_unlock(&ds->lock);
}

void free_datastore(DataStore *ds) {
    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->records[i]) {
            if (ds->records[i]->metadata) {
                free(ds->records[i]->metadata); // Free individual metadata
            }
            free(ds->records[i]); // Free record
        }
    }

    free(ds->records);
    free(ds->offsets);

    // Destroy the memory pool for metadata
    MemoryPool *meta_pool = (MemoryPool*)&(ds->metadata_pool);
    destroy_memory_pool(meta_pool);

    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Entry point to test functionality
int main() {
    DataStore *ds = initialize_datastore(1000);

    // Example: populate records
    for (size_t i = 0; i < ds->capacity; ++i) {
        Record *record = create_record();
        record->metadata = allocate_metadata();

        if (populate_record(record) != 0) {
            fprintf(stderr, "Failed to populate record\n");
            return EXIT_FAILURE;
        }

        pthread_mutex_lock(&ds->lock);
        ds->records[i] = record; // Assign record
        pthread_mutex_unlock(&ds->lock);
    }

    resize_datastore(ds, 2000);

    free_datastore(ds);

    return EXIT_SUCCESS;
}
