int enqueueImageRequest(ProcessingQueue* queue, ImageRequest request) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count >= queue->capacity) {
        // Resize logic for processing queue
        size_t new_capacity = queue->capacity * 2;
        ImageRequest* new_imageRequests = (ImageRequest*)realloc(queue->imageRequests, new_capacity * sizeof(ImageRequest));
        if (!new_imageRequests) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Failed to resize
        }
        queue->imageRequests = new_imageRequests;
        queue->capacity = new_capacity;
    }

    queue->imageRequests[queue->count++] = request;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

