LRUCache* createCache(size_t capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    cache->capacity = capacity;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void addToCache(LRUCache* cache, int id, ImageRequest request) {
    pthread_mutex_lock(&cache->lock);

    // Check if already in cache
    CacheNode* current = cache->head;
    while (current) {
        if (current->id == id) {
            // Move to front and update
            break;
        }
        current = current->next;
    }

    // If not found, add new node
    if (!current) {
        CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
        newNode->request = request;
        newNode->id = id;
        newNode->next = cache->head;

        if (cache->size < cache->capacity) {
            // Insert at head and update tail
            cache->head = newNode;
            if (!cache->tail) {
                cache->tail = newNode;
            }
            cache->size++;
        } else {
            // Evict LRU node, insert new node at head
            CacheNode* lru = cache->tail;
            cache->tail = lru->next;
            free(lru);

            newNode->next = cache->head;
            cache->head = newNode;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void dataManager() {
