use std::collections::{BTreeMap, VecDeque};
use std::sync::{Arc, Mutex, RwLock};
use std::time::{Duration, Instant};
use rand::Rng;
use tokio::sync::Mutex as AsyncMutex;
use futures::future::join_all;

// Constants for configurations
const MAX_WORKER_LOG_SIZE: usize = 1024;
const INITIAL_MEMORY_POOL_SIZE: usize = 1024 * 1024; // 1MB

// Structures for entities and components
struct Worker {
    log_buffer: Vec<u8>,
    performance_metric: f32,
    action_function: Box<dyn Fn() + Send + Sync>,
}

#[derive(Debug, Clone)]
struct HistoryEntry {
    timestamp: Instant,
    activity: String,
}

// Memory Pool using a simple vector for demonstration purposes.
struct MemoryPool {
    pool: Mutex<Vec<u8>>,
}

impl MemoryPool {
    fn new(size: usize) -> Self {
        MemoryPool {
            pool: Mutex::new(vec![0; size]),
        }
    }

    fn allocate(&self, size: usize) -> Option<Vec<u8>> {
        let mut pool = self.pool.lock().unwrap();
        if pool.len() >= size {
            let chunk = pool.split_off(pool.len() - size);
            Some(chunk)
        } else {
            None
        }
    }

    fn deallocate(&self, data: Vec<u8>) {
        let mut pool = self.pool.lock().unwrap();
        pool.extend(data);
    }
}

// Worker Collection using a Balanced Binary Tree (BTreeMap in Rust)
struct WorkerCollection {
    workers: RwLock<BTreeMap<String, Worker>>,
    history: RwLock<Vec<HistoryEntry>>,
}

impl WorkerCollection {
    fn new() -> Self {
        let mut rng = rand::thread_rng();

        // Initialize with random worker entities
        let mut workers = BTreeMap::new();
        for i in 0..10 {
            let log_buffer = vec![0; MAX_WORKER_LOG_SIZE];
            let performance_metric: f32 = rng.gen_range(0.0..100.0);
            let action_function = Box::new(|| println!("Worker {} performing an action", i));
            workers.insert(format!("worker_{}", i), Worker {
                log_buffer,
                performance_metric,
                action_function,
            });
        }

        WorkerCollection {
            workers: RwLock::new(workers),
            history: RwLock::new(vec![]),
        }
    }

    fn prune_history(&self) {
        let mut history = self.history.write().unwrap();
        history.retain(|entry| entry.timestamp.elapsed() < Duration::from_secs(3600));
    }
}

// Bloom filter using a simple HashSet for demonstration
struct BloomFilter {
    set: Mutex<HashSet<String>>,
}

impl BloomFilter {
    fn new() -> Self {
        BloomFilter {
            set: Mutex::new(HashSet::new()),
        }
    }

    fn contains(&self, item: &str) -> bool {
        self.set.lock().unwrap().contains(item)
    }

    fn insert(&self, item: String) {
        let mut set = self.set.lock().unwrap();
        set.insert(item);
    }
}

// LRU Cache using an ordered map
struct LRUCache<K, V> {
    capacity: usize,
    cache: Mutex<LinkedList<(K, V)>>,
    access_order: Mutex<HashMap<K, usize>>,
}

impl<K: Eq + Hash + Clone, V> LRUCache<K, V> {
    fn new(capacity: usize) -> Self {
        LRUCache {
            capacity,
            cache: Mutex::new(LinkedList::new()),
            access_order: Mutex::new(HashMap::new()),
        }
    }

    fn get(&self, key: &K) -> Option<V>
    where
        V: Clone,
    {
        let mut cache = self.cache.lock().unwrap();
        if let Some(pos) = self.access_order.lock().unwrap().get(key) {
            let (value, _) = cache.remove(*pos).unwrap();
            cache.push_front((key.clone(), value));
            *self.access_order.get_mut(key).unwrap() = 0;
            for (i, (_, _)) in cache.iter().enumerate().skip(1) {
                self.access_order.lock().unwrap().insert(key.clone(), i);
            }
            Some(value)
        } else {
            None
        }
    }

    fn put(&self, key: K, value: V) {
        let mut cache = self.cache.lock().unwrap();
        if let Some(pos) = self.access_order.lock().unwrap().get(&key) {
            if let Some(item) = cache.get_mut(*pos) {
                item.1 = value;
            }
            cache.remove(*pos);
        }
        if cache.len() >= self.capacity {
            if let Some((evicted_key, _)) = cache.pop_back() {
                self.access_order.lock().unwrap().remove(&evicted_key);
            }
        }
        cache.push_front((key, value));
        *self.access_order.lock().unwrap().entry(key).or_insert(0) = 0;
        for (i, (_, _)) in cache.iter().enumerate().skip(1) {
            self.access_order.lock().unwrap().insert(key.clone(), i);
        }
    }
}

// Main function
#[tokio::main]
async fn main() {
    let memory_pool = MemoryPool::new(INITIAL_MEMORY_POOL_SIZE);

    // Worker Collection with initial setup and pruning mechanism
    let worker_collection = WorkerCollection::new();
    tokio::spawn(async move {
        loop {
            worker_collection.prune_history();
            tokio::time::sleep(Duration::from_secs(60)).await;
        }
    });

    // Bloom filter for checking existence of workers
    let bloom_filter = Arc::new(BloomFilter::new());

    // LRU Cache to manage cached data efficiently
    let lru_cache = LRUCache::<String, Vec<u8>>::new(100);

    // Example transaction processing with retry mechanism
    let process_transaction = |transaction: i32| async {
        let mut retries = 0;
        loop {
            if retries > 3 {
                println!("Transaction failed after multiple attempts");
                break;
            }
            match simulate_network_request(&transaction).await {
                Ok(_) => {
                    println!("Transaction processed successfully: {}", transaction);
                    break;
                },
                Err(_) => {
                    let wait_time = (2u64.pow(retries) + rand::random::<u32>() as u64) * 100; // exponential backoff with jitter
                    tokio::time::sleep(Duration::from_millis(wait_time)).await;
                    retries += 1;
                }
            }
        }
    };

    async fn simulate_network_request(transaction: &i32) -> Result<(), &'static str> {
        if transaction % 2 == 0 { // Simulate a network error for demonstration
            Err("Network Error")
        } else {
            Ok(())
        }
    }

    let transactions = vec![100, 200, 300, 400, 500];
    let handles: Vec<_> = transactions.into_iter().map(|t| process_transaction(t)).collect();
    join_all(handles).await;

    println!("Simulation complete");
}
```

