#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_BINARY_SIZE 1024
#define KEY_RANGE 1000
#define OFFSET_CONSTANT 10

typedef struct Record {
    short shortField;
    int intField;
    float floatField;
    char charArray[16];
    unsigned char binaryData[MAX_BINARY_SIZE];
    size_t binarySize;
    time_t eventTimestamp;
    int key;
    int offset;

    struct Record* prev;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    Record* tail;
    pthread_mutex_t lock;
    size_t recordCount;
} RecordList;

RecordList* createRecordList() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->recordCount = 0;

    return list;
}

void destroyRecordList(RecordList* list) {
    Record* current = list->head;
    while (current != NULL) {
        Record* toDelete = current;
        current = current->next;
        free(toDelete);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int generateUniqueKey(int lastKey, int range, size_t recordCount) {
    int newKey;
    do {
        newKey = (lastKey + OFFSET_CONSTANT) % range;
    } while (newKey == lastKey || rand() % 2 == 0); // Simulate checking for duplicates
    return newKey;
}

void insertRecord(RecordList* list, short sField, int iField, float fField,
                  const char* cArray, size_t binarySize) {
    pthread_mutex_lock(&list->lock);

    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) return;

    time(&newRecord->eventTimestamp);
    newRecord->shortField = sField;
    newRecord->intField = iField;
    newRecord->floatField = fField;
    strncpy(newRecord->charArray, cArray, sizeof(newRecord->charArray));
    newRecord->binarySize = binarySize < MAX_BINARY_SIZE ? binarySize : MAX_BINARY_SIZE;
    for (size_t i = 0; i < newRecord->binarySize; ++i) {
        newRecord->binaryData[i] = rand() % 256;
    }

    int lastKey = list->tail ? list->tail->key : -1;
    newRecord->key = generateUniqueKey(lastKey, KEY_RANGE, list->recordCount);
    newRecord->offset = (lastKey == -1) ? OFFSET_CONSTANT : 
                        list->tail->offset + lastKey + OFFSET_CONSTANT;

    if (!list->head) {
        list->head = list->tail = newRecord;
        newRecord->prev = newRecord->next = NULL;
    } else {
        list->tail->next = newRecord;
        newRecord->prev = list->tail;
        newRecord->next = NULL;
        list->tail = newRecord;
    }

    ++list->recordCount;

    // Simulate logging insertion time
    printf("Inserted record with timestamp: %ld\n", newRecord->eventTimestamp);

    pthread_mutex_unlock(&list->lock);
}

void* garbageCollector(void* arg) {
    RecordList* list = (RecordList*)arg;
    while (1) {
        sleep(10); // Run every 10 seconds

        time_t currentTime = time(NULL);
        pthread_mutex_lock(&list->lock);

        Record* current = list->head;
        while (current != NULL) {
            if (currentTime - current->eventTimestamp > 60) { // Example condition
                Record* toDelete = current;
                if (toDelete->prev) toDelete->prev->next = toDelete->next;
                else list->head = toDelete->next;

                if (toDelete->next) toDelete->next->prev = toDelete->prev;
                else list->tail = toDelete->prev;

                current = current->next;
                free(toDelete);
                --list->recordCount;
            } else {
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
    }
}

int main() {
    RecordList* list = createRecordList();
    if (!list) return EXIT_FAILURE;

    pthread_t gcThread;
    if (pthread_create(&gcThread, NULL, garbageCollector, list)) {
        fprintf(stderr, "Error creating garbage collector thread\n");
        destroyRecordList(list);
        return EXIT_FAILURE;
    }

    // Simulate concurrent insertions
    for (int i = 0; i < 10; ++i) {
        pthread_t workerThread;
        if (pthread_create(&workerThread, NULL, (void*)insertRecord, list)) {
            fprintf(stderr, "Error creating worker thread\n");
        }
        pthread_join(workerThread, NULL);
    }

    // Wait for garbage collector to finish
    pthread_cancel(gcThread);
    pthread_join(gcThread, NULL);

    destroyRecordList(list);
    return EXIT_SUCCESS;
}
