#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    char buffer[256];
    float value;
    void *client_id; // Pointer to client identifier
} Event;

typedef struct Node {
    double timestamp;
    unsigned int sequence_id;
    Event event_data;
    struct Node *left, *right;
} TreeNode;

typedef struct {
    TreeNode **buckets;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
void initialize_system(HashTable *hash_table, size_t initial_capacity);
void resize_hash_table_if_needed(HashTable *hash_table);
int hash_function(double timestamp);
TreeNode* insert_to_tree(TreeNode *root, double timestamp, unsigned int sequence_id, Event event_data);
TreeNode* find_minimum(TreeNode *node);
TreeNode* delete_from_tree(TreeNode *root, double timestamp);
void free_tree(TreeNode *root);

// Global variables
unsigned long current_sequence_id = 0;
double current_timestamp = time(NULL);
pthread_mutex_t seq_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the system with a hash table and empty tree roots.
void initialize_system(HashTable *hash_table, size_t initial_capacity) {
    hash_table->buckets = (TreeNode **)calloc(initial_capacity, sizeof(TreeNode *));
    pthread_mutex_init(&hash_table->lock, NULL);
}

// Function to resize the hash table if needed
void resize_hash_table_if_needed(HashTable *hash_table) {
    // Placeholder for dynamic resizing logic if necessary
}

// Hash function based on timestamp for distributing events in hash table.
int hash_function(double timestamp) {
    return (unsigned int)(timestamp) % HASH_TABLE_SIZE;
}

// Insert a new event into the tree, maintaining order by timestamps.
TreeNode* insert_to_tree(TreeNode *root, double timestamp, unsigned int sequence_id, Event event_data) {
    if (!root) {
        TreeNode *node = malloc(sizeof(TreeNode));
        node->timestamp = timestamp;
        node->sequence_id = sequence_id;
        node->event_data = event_data;
        node->left = node->right = NULL;
        return node;
    }

    if (timestamp < root->timestamp)
        root->left = insert_to_tree(root->left, timestamp, sequence_id, event_data);
    else
        root->right = insert_to_tree(root->right, timestamp, sequence_id, event_data);

    return root;
}

// Utility function to find the node with minimum timestamp.
TreeNode* find_minimum(TreeNode *node) {
    while (node && node->left != NULL)
        node = node->left;
    return node;
}

// Delete a node from the tree by its timestamp.
TreeNode* delete_from_tree(TreeNode *root, double timestamp) {
    if (!root) return root;

    if (timestamp < root->timestamp)
        root->left = delete_from_tree(root->left, timestamp);
    else if (timestamp > root->timestamp)
        root->right = delete_from_tree(root->right, timestamp);
    else {
        if (!root->left) {
            TreeNode *temp = root->right;
            free(root);
            return temp;
        } else if (!root->right) {
            TreeNode *temp = root->left;
            free(root);
            return temp;
        }

        TreeNode *min_node = find_minimum(root->right);
        root->timestamp = min_node->timestamp;
        root->sequence_id = min_node->sequence_id;
        root->event_data = min_node->event_data;

        root->right = delete_from_tree(root->right, min_node->timestamp);
    }
    return root;
}

// Free the entire tree to prevent memory leaks.
void free_tree(TreeNode *root) {
    if (root) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
}

// Function to generate a random event for testing
Event generate_random_event() {
    Event event;
    snprintf(event.buffer, sizeof(event.buffer), "RandomEvent_%lu", rand());
    event.value = (float)rand() / RAND_MAX * 100.0; // Random float between 0 and 100
    event.client_id = malloc(sizeof(int)); // Example client ID allocation
    *(int *)event.client_id = rand();
    return event;
}

// Function to add an event in a thread-safe manner
void add_event(HashTable *hash_table, double timestamp, unsigned int sequence_id, Event event_data) {
    pthread_mutex_lock(&seq_lock);
    current_sequence_id++;
    current_timestamp += 0.01; // Simulate time passing for monotonicity
    pthread_mutex_unlock(&seq_lock);

    pthread_mutex_lock(&hash_table->lock);
    resize_hash_table_if_needed(hash_table);

    int index = hash_function(timestamp);
    hash_table->buckets[index] = insert_to_tree(hash_table->buckets[index], timestamp, sequence_id, event_data);
    pthread_mutex_unlock(&hash_table->lock);
}

// Example usage
int main() {
    HashTable hash_table;
    initialize_system(&hash_table, HASH_TABLE_SIZE);

    for (int i = 0; i < 100; ++i) {
        Event event = generate_random_event();
        add_event(&hash_table, current_timestamp + rand(), current_sequence_id, event);
    }

    // Free resources
    for (int i = 0; i < HASH_TABLE_SIZE; ++i)
        free_tree(hash_table.buckets[i]);

    free(hash_table.buckets);
    pthread_mutex_destroy(&hash_table.lock);

    return 0;
}
```

