```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    short field1;
    int field2;
} Record;

typedef struct Node {
    Record *recordArray;
    long *offsets;
    int *keys;
    size_t capacity;
    struct Node *next;
} Node;

// Global mutex for thread safety
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Node* createNode(size_t initialCapacity, int keyRangeMin, int keyRangeMax);
void freeNode(Node *node);
int seedPRNG(int deterministic);
long calculateOffset(const int *keys, size_t count);
void resizeArray(void **array, size_t currentSize, size_t newSize, size_t elementSize);

// Node creation and initialization
Node* createNode(size_t initialCapacity, int keyRangeMin, int keyRangeMax) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;

    pthread_mutex_lock(&listMutex);

    node->recordArray = (Record *)malloc(initialCapacity * sizeof(Record));
    node->offsets = (long *)malloc(initialCapacity * sizeof(long));
    node->keys = (int *)malloc(initialCapacity * sizeof(int));
    node->capacity = initialCapacity;
    node->next = NULL;

    if (!node->recordArray || !node->offsets || !node->keys) {
        free(node->recordArray);
        free(node->offsets);
        free(node->keys);
        pthread_mutex_unlock(&listMutex);
        free(node);
        return NULL;
    }

    srand(seedPRNG(0));

    for (size_t i = 0; i < initialCapacity; ++i) {
        node->recordArray[i].field1 = rand() % 100; // Example range
        node->recordArray[i].field2 = rand() % 1000; // Example range

        int key;
        do {
            key = keyRangeMin + (rand() % (keyRangeMax - keyRangeMin + 1));
        } while (i > 0 && bsearch(&key, node->keys, i, sizeof(int), 
                                 (int(*)(const void*, const void*))strcmp)); // Ensure uniqueness

        node->keys[i] = key;
    }

    long offsetSum = 0;
    for (size_t i = 0; i < initialCapacity; ++i) {
        offsetSum += node->keys[i];
        node->offsets[i] = offsetSum + rand(); // Unique identifier
    }

    pthread_mutex_unlock(&listMutex);

    return node;
}

void freeNode(Node *node) {
    if (!node) return;

    pthread_mutex_lock(&listMutex);

    free(node->recordArray);
    free(node->offsets);
    free(node->keys);
    free(node);

    pthread_mutex_unlock(&listMutex);
}

int seedPRNG(int deterministic) {
    static int seeded = 0;
    if (deterministic && !seeded) {
        srand(42); // Fixed seed for reproducibility
        seeded = 1;
    } else if (!seeded) {
        srand((unsigned)time(NULL)); // Non-deterministic seed
        seeded = 1;
    }
    return deterministic ? 42 : (unsigned)time(NULL);
}

long calculateOffset(const int *keys, size_t count) {
    long offsetSum = 0;
    for (size_t i = 0; i < count; ++i) {
        offsetSum += keys[i];
    }
    return offsetSum + rand(); // Unique identifier
}

void resizeArray(void **array, size_t currentSize, size_t newSize, size_t elementSize) {
    if (!*array) {
        *array = malloc(newSize * elementSize);
    } else {
        *array = realloc(*array, newSize * elementSize);
    }
}

Node* insertRecord(Node *head, int keyRangeMin, int keyRangeMax) {
    pthread_mutex_lock(&listMutex);

    if (!head || head->capacity <= 0) { // Resize needed
        Node *newNode = createNode(10, keyRangeMin, keyRangeMax); // Example initial capacity
        newNode->next = head;
        return newNode;
    }

    head->recordArray = (Record *)realloc(head->recordArray, 
                                          (head->capacity + 1) * sizeof(Record));
    head->offsets = (long *)realloc(head->offsets, 
                                    (head->capacity + 1) * sizeof(long));
    head->keys = (int *)realloc(head->keys, 
                                (head->capacity + 1) * sizeof(int));

    if (!head->recordArray || !head->offsets || !head->keys) {
        pthread_mutex_unlock(&listMutex);
        return NULL;
    }

    size_t count = head->capacity++;

    int key;
    do {
        key = keyRangeMin + (rand() % (keyRangeMax - keyRangeMin + 1));
    } while (count > 0 && bsearch(&key, head->keys, count, sizeof(int), 
                                 (int(*)(const void*, const void*))strcmp));

    head->recordArray[count].field1 = rand() % 100;
    head->recordArray[count].field2 = rand() % 1000;

    head->keys[count] = key;
    long offsetSum = calculateOffset(head->keys, count);
    memcpy(&head->offsets[count], &offsetSum, sizeof(long));

    pthread_mutex_unlock(&listMutex);

    return head;
}

void iterateList(Node *head) {
    Node *current = head;

    while (current != NULL) {
        for (size_t i = 0; i < current->capacity; ++i) {
            printf("Record: (%d, %d), Key: %d, Offset: %ld\n", 
                   current->recordArray[i].field1, 
                   current->recordArray[i].field2, 
                   current->keys[i], 
                   current->offsets[i]);
        }
        current = current->next;
    }
}

// Main function for demonstration (not part of the requirement)
int main() {
    Node *head = createNode(5, 0, 100); // Example key range

    head = insertRecord(head, 0, 100);
    iterateList(head);

    freeNode(head);
    return 0;
}
```

### Explanation:
- **Thread Safety**: The global mutex `listMutex` ensures exclusive access to the linked list operations, preventing race conditions.
- **Initialization and Randomization**: Utilizes a PRNG with an option for deterministic seeding. Ensures unique keys within each batch using binary search (`bsearch`) before insertion.
- **Dynamic Resizing**: Implements resizing by reallocating arrays when more capacity is needed, doubling capacity as an example strategy to reduce frequent allocations.
- **Iteration and Access**: Provides simple iteration over the linked list with thread safety considerations.
- **Memory Management**: Ensures proper allocation and deallocation of resources to prevent leaks. 

This implementation balances simplicity with functionality for managing a dynamic array in a multi-threaded environment, ensuring performance, scalability, and reliability. Adjustments like capacity doubling or different randomization strategies can be fine-tuned based on specific use cases or performance metrics gathered during testing.']

