```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define SESSION_ID_MIN 1000
#define SESSION_ID_MAX 9999
#define MAX_SESSIONS 1024

typedef struct {
    int session_id;
    char *user_info;
    time_t last_accessed;
    int active;
} Session;

typedef struct {
    Session *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionList;

// Function prototypes
SessionList* create_session_list(size_t initial_capacity);
int add_session(SessionList *list, const char *user_info);
int remove_session(SessionList *list, int session_id);
Session* find_session_by_id(SessionList *list, int session_id);
void update_last_accessed(SessionList *list, int session_id);

// Helper function prototypes
static void resize_sessions(SessionList *list);
static int generate_unique_session_id(SessionList *list);
static Session* get_idle_or_new_slot(SessionList *list);

SessionList* create_session_list(size_t initial_capacity) {
    SessionList *list = (SessionList*)malloc(sizeof(SessionList));
    if (!list) return NULL;

    list->sessions = (Session *)calloc(initial_capacity, sizeof(Session));
    if (!list->sessions) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_session(SessionList *list, const char *user_info) {
    if (!pthread_mutex_lock(&list->lock)) {
        Session *session = get_idle_or_new_slot(list);
        if (session) {
            session->session_id = generate_unique_session_id(list);
            session->user_info = strdup(user_info);
            session->last_accessed = time(NULL);
            session->active = 0;
            pthread_mutex_unlock(&list->lock);
            return session->session_id;
        }
        pthread_mutex_unlock(&list->lock);
    }
    return -1; // Failed to add session
}

int remove_session(SessionList *list, int session_id) {
    if (!pthread_mutex_lock(&list->lock)) {
        for (size_t i = 0; i < list->count; ++i) {
            if (list->sessions[i].session_id == session_id && list->sessions[i].active) {
                free(list->sessions[i].user_info);
                memset(&list->sessions[i], 0, sizeof(Session));
                pthread_mutex_unlock(&list->lock);
                return 1;
            }
        }
        pthread_mutex_unlock(&list->lock);
    }
    return 0; // Session not found or not active
}

Session* find_session_by_id(SessionList *list, int session_id) {
    if (!pthread_mutex_lock(&list->lock)) {
        for (size_t i = 0; i < list->count; ++i) {
            if (list->sessions[i].session_id == session_id && list->sessions[i].active) {
                pthread_mutex_unlock(&list->lock);
                return &list->sessions[i];
            }
        }
        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

void update_last_accessed(SessionList *list, int session_id) {
    Session *session = find_session_by_id(list, session_id);
    if (session) {
        session->last_accessed = time(NULL);
    }
}

static void resize_sessions(SessionList *list) {
    size_t new_capacity = list->capacity * 2;
    Session *new_sessions = (Session *)realloc(list->sessions, new_capacity * sizeof(Session));
    if (new_sessions) {
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
}

static int generate_unique_session_id(SessionList *list) {
    srand((unsigned int)time(NULL)); // Seed for demonstration purposes
    int session_id;
    do {
        session_id = SESSION_ID_MIN + rand() % (SESSION_ID_MAX - SESSION_ID_MIN + 1);
    } while (find_session_by_id(list, session_id));
    return session_id;
}

static Session* get_idle_or_new_slot(SessionList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        if (!list->sessions[i].active) {
            return &list->sessions[i];
        }
    }

    if (list->count == list->capacity) {
        resize_sessions(list);
    }

    Session *new_session = &list->sessions[list->count++];
    new_session->active = 0;
    return new_session;
}

// Example usage of the functions
int main() {
    SessionList *session_list = create_session_list(10);

    // Add sessions, update, find and remove as needed
    int session_id = add_session(session_list, "User1");
    if (session_id != -1) {
        printf("Added session with ID: %d\n", session_id);
    }

    update_last_accessed(session_list, session_id);

    Session *found_session = find_session_by_id(session_list, session_id);
    if (found_session) {
        printf("Found session with ID: %d\n", found_session->session_id);
    } else {
        printf("Session not found.\n");
    }

    remove_session(session_list, session_id);

    // Clean up
    free(session_list->sessions);
    pthread_mutex_destroy(&session_list->lock);
    free(session_list);

    return 0;
}
```

This code provides a thread-safe, dynamic data structure for managing user sessions. It handles memory allocation efficiently, ensures unique session ID generation, and maintains the last accessed timestamps. The design allows for adding and removing sessions dynamically while optimizing memory usage through session object reuse.']

