#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef enum { PENDING, COMPLETED } TransactionStatus;

typedef struct {
    time_t timestamp;
    double amount;
    TransactionStatus status;
} Transaction;

typedef struct Node {
    Transaction transaction;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} TransactionList;

TransactionList* create_transaction_list(time_t epoch, int interval) {
    TransactionList* list = malloc(sizeof(TransactionList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Initialize random seed
    srand((unsigned int)time(NULL));

    return list;
}

void add_transaction(TransactionList* list, double min_amount, double max_amount) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Generate high-precision timestamp
    time_t now = time(NULL);
    static time_t last_timestamp = 0;

    new_node->transaction.timestamp = (last_timestamp == 0 ? list->head->transaction.timestamp + interval : last_timestamp) + ((now - epoch));
    last_timestamp = new_node->transaction.timestamp;

    // Random amount
    new_node->transaction.amount = min_amount + ((double)rand() / RAND_MAX * (max_amount - min_amount));

    // Random status
    new_node->transaction.status = (TransactionStatus)(rand() % 2);

    // Insert at the beginning of the list for O(1) complexity
    new_node->next = list->head;
    list->head = new_node;

    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void* filter_transactions(TransactionList* list, TransactionStatus status) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    Node dummy;
    Node* new_head = &dummy;
    dummy.next = NULL;

    while (current != NULL) {
        if (current->transaction.status == status) {
            Node* next = current->next;
            current->next = new_head->next;
            new_head->next = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return dummy.next;
}

void iterate_transactions(TransactionList* list, void (*callback)(Transaction*)) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->transaction));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_transaction_list(TransactionList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void log_transaction(Transaction* transaction) {
    printf("Timestamp: %ld, Amount: %.2f, Status: %d\n",
           transaction->timestamp,
           transaction->amount,
           transaction->status);
}
