['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the Record structure
typedef struct {
    int value;
} Record;

// Define the Point structure
typedef struct {
    int identifier;
    double coordinate;
    char *label;
} Point;

/**
 * Initializes and allocates memory for arrays with retry logic.
 *
 * @param num_points Number of points to initialize.
 * @param coord_range The range for initializing 'double' coordinates.
 * @return A pointer to a dynamically allocated structure containing the arrays,
 *         or NULL if any allocation fails after retries.
 */
typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    Point *points;
} DataArrays;

DataArrays* allocate_and_initialize_arrays(size_t num_points, double coord_range) {
    size_t max_retries = 3;
    size_t attempt = 0;

    while (attempt < max_retries) {
        try_again:

        // Allocate memory for arrays
        long *offsets = malloc(num_points * sizeof(long));
        int *keys = malloc(num_points * sizeof(int));
        Record *records = malloc(num_points * sizeof(Record));
        Point *points = malloc(num_points * sizeof(Point));

        if (!offsets || !keys || !records || !points) {
            attempt++;
            fprintf(stderr, "Memory allocation failed on attempt %zu. Retrying...\n", attempt);
            free(offsets); offsets = NULL;
            free(keys); keys = NULL;
            free(records); records = NULL;
            free(points); points = NULL;
            continue; // Retry
        }

        // Initialize arrays with default values
        for (size_t i = 0; i < num_points; ++i) {
            offsets[i] = i * sizeof(Record);
            keys[i] = i;
            records[i].value = i;

            points[i].identifier = i;
            points[i].coordinate = ((double)rand() / RAND_MAX) * coord_range;

            char label_buffer[16];
            snprintf(label_buffer, sizeof(label_buffer), "Point%zu", i);
            points[i].label = strdup(label_buffer); // Allocate and copy the string

            if (!points[i].label) {
                fprintf(stderr, "String allocation failed for point %zu\n", i);
                goto fail_cleanup; // Handle failure
            }
        }

        DataArrays *result = malloc(sizeof(DataArrays));
        if (!result) {
            attempt++;
            fprintf(stderr, "Memory allocation for result structure failed on attempt %zu. Retrying...\n", attempt);
            free(offsets); offsets = NULL;
            free(keys); keys = NULL;
            free(records); records = NULL;
            free(points); points = NULL;
            continue; // Retry
        }

        result->offsets = offsets;
        result->keys = keys;
        result->records = records;
        result->points = points;

        return result;

    fail_cleanup:
        fprintf(stderr, "Memory allocation failed after %zu attempts.\n", max_retries);

        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        for (size_t i = 0; i < num_points && points[i].label != NULL; ++i)
            free(points[i].label); // Free any allocated strings
        if (points) free(points);

        if (!attempt++) return NULL; // Retry
    }

    fprintf(stderr, "Exceeded maximum retries for memory allocation.\n");
    return NULL;
}

/**
 * Frees the allocated memory.
 *
 * @param data_arrays The structure containing dynamically allocated arrays.
 */
void deallocate_data_arrays(DataArrays *data_arrays) {
    if (!data_arrays) return;

    free(data_arrays->offsets);
    free(data_arrays->keys);
    free(data_arrays->records);
    for (size_t i = 0; i < num_points && data_arrays->points[i].label != NULL; ++i)
        free(data_arrays->points[i].label); // Free each label
    free(data_arrays->points);

    free(data_arrays);
}

// Example usage of the function
int main() {
    size_t num_points = 1000000; // One million points as an example
    double coord_range = 100.0;

    DataArrays *data_arrays = allocate_and_initialize_arrays(num_points, coord_range);
    if (!data_arrays) {
        fprintf(stderr, "Failed to allocate and initialize data arrays.\n");
        return EXIT_FAILURE;
    }

    // Use the allocated data here...

    // Deallocate memory after use
    deallocate_data_arrays(data_arrays);

    return EXIT_SUCCESS;
}
```

This code implements a C function that dynamically allocates memory for three arrays (`offsets`, `keys`, and `records`) along with an array of `Point` structures, each containing an identifier, coordinate, and label. It includes retry logic for memory allocation failures and provides error messages upon failure. The function also ensures proper deallocation of memory to avoid leaks.']

