#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000000

typedef struct {
    int value;
} record;

typedef struct {
    int identifier;
    double coordinate;
    char label[256]; // Assuming labels are up to 255 characters + null terminator
} Point;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    Point *points;
    void *expansionBuffer;
    int pointCount;
    int maxPointCount;
    // Additional runtime configuration fields can be added here
} Configuration;

int allocateAndInitialize(Configuration *config, size_t initialPoints) {
    if (!config || initialPoints == 0) return -1;

    config->offsets = malloc(MAX_RECORDS * sizeof(long));
    if (!config->offsets) goto fail;

    config->keys = malloc(MAX_RECORDS * sizeof(int));
    if (!config->keys) goto free_offsets;

    config->records = malloc(MAX_RECORDS * sizeof(record));
    if (!config->records) goto free_keys;

    size_t pointsSize = initialPoints * sizeof(Point);
    config->points = malloc(pointsSize);
    if (!config->points) goto free_records;

    // Allocate a buffer for potential expansion beyond 10 million records
    config->expansionBuffer = malloc(initialPoints * sizeof(int)); // Example allocation
    if (!config->expansionBuffer) goto free_points;

    config->pointCount = initialPoints;
    config->maxPointCount = MAX_RECORDS;

    // Initialize data structures
    memset(config->offsets, 0, MAX_RECORDS * sizeof(long));
    memset(config->keys, 0, MAX_RECORDS * sizeof(int));
    for (int i = 0; i < initialPoints; ++i) {
        config->records[i].value = rand(); // Example initialization
        config->points[i].identifier = i;
        config->points[i].coordinate = (double)(rand() % 100) / 10.0; // Random coordinate in [0, 10)
        snprintf(config->points[i].label, sizeof(config->points[i].label), "Point_%d", i);
    }

    return 0;

free_points:
    free(config->records);
free_records:
    free(config->keys);
free_keys:
    free(config->offsets);
fail:
    fprintf(stderr, "Memory allocation failed\n");
    return -1;
}

void deallocate(Configuration *config) {
    if (!config) return;

    free(config->expansionBuffer);
    free(config->points);
    free(config->records);
    free(config->keys);
    free(config->offsets);
}

int main() {
    Configuration config = {0};
    size_t initialPoints = 500000; // Example: starting with 500,000 points

    if (allocateAndInitialize(&config, initialPoints) != 0) {
        fprintf(stderr, "Failed to initialize configuration\n");
        return EXIT_FAILURE;
    }

    // Use the allocated structures here...

    deallocate(&config);

    return EXIT_SUCCESS;
}
```

