#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define MAX_TRANSACTIONS 10000
#define TIMESTAMP_INCREMENT_USEC 1000
#define EPOCH_TIME 1609459200000000 // Example epoch start: Jan 1, 2021
#define MEMORY_POOL_SIZE (MAX_TRANSACTIONS * sizeof(Transaction))
#define STATUS_COUNT 5

typedef enum {
    PENDING,
    COMPLETED,
    FAILED,
    CANCELLED,
    REVERSAL
} TransactionStatus;

typedef struct Transaction {
    uint64_t timestamp;
    double amount;
    TransactionStatus status;
    struct Transaction* next;
    pthread_mutex_t lock; // For individual transaction locking if needed.
} Transaction;

// Memory pool for transactions
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

Transaction* allocate_transaction() {
    pthread_mutex_lock(&pool_lock);
    if (memory_offset + sizeof(Transaction) > MEMORY_POOL_SIZE) {
        // Handle out of memory or reallocate logic
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }

    Transaction* transaction = (Transaction*) &memory_pool[memory_offset];
    memory_offset += sizeof(Transaction);

    pthread_mutex_init(&transaction->lock, NULL);
    pthread_mutex_unlock(&pool_lock);
    return transaction;
}

void free_transaction(Transaction** transaction) {
    if (*transaction == NULL) return;

    // Deallocate logic if needed
    // For simplicity, we assume freeing means zeroing out and resetting offset.
    memset(*transaction, 0, sizeof(Transaction));
    pthread_mutex_destroy(&(*transaction)->lock);

    pthread_mutex_lock(&pool_lock);
    memory_offset -= sizeof(Transaction);
    *transaction = NULL;
    pthread_mutex_unlock(&pool_lock);
}

// Custom random number generation for amount
double generate_random_amount(double min, double max) {
    return (max - min) * ((double) rand() / RAND_MAX) + min;
}

// Random status with probability distribution
TransactionStatus generate_random_status() {
    int probabilities[STATUS_COUNT] = {30, 50, 10, 5, 5}; // Example probabilities in percentage

    int random_percent = (int) (100.0 * ((double) rand() / RAND_MAX));
    int cumulative_probability = 0;

    for (int i = 0; i < STATUS_COUNT; ++i) {
        cumulative_probability += probabilities[i];
        if (random_percent <= cumulative_probability)
            return (TransactionStatus)i;
    }
    return PENDING; // Fallback
}

typedef struct TransactionList {
    Transaction* head;
    pthread_rwlock_t list_lock; // For concurrent read/write access control.
} TransactionList;

TransactionList* create_transaction_list() {
    TransactionList* list = malloc(sizeof(TransactionList));
    if (!list) {
        fprintf(stderr, "Failed to allocate transaction list\n");
        return NULL;
    }

    list->head = NULL;
    pthread_rwlock_init(&list->list_lock, NULL);
    return list;
}

void add_transaction(TransactionList* list, uint64_t timestamp, double amount, TransactionStatus status) {
    pthread_rwlock_wrlock(&list->list_lock);

    Transaction* new_transaction = allocate_transaction();
    if (!new_transaction) {
        fprintf(stderr, "Failed to allocate transaction\n");
        pthread_rwlock_unlock(&list->list_lock);
        return;
    }

    new_transaction->timestamp = timestamp;
    new_transaction->amount = amount;
    new_transaction->status = status;
    new_transaction->next = list->head;

    list->head = new_transaction;

    pthread_rwlock_unlock(&list->list_lock);
}

// Filtering transactions by status
void filter_transactions_by_status(TransactionList* list, TransactionStatus status) {
    pthread_rwlock_rdlock(&list->list_lock);

    for (Transaction* current = list->head; current != NULL; current = current->next) {
        if (current->status == status) {
            // Process the transaction. For demonstration, just print it.
            printf("Filtered Transaction: %lu, %.2f, %d\n", current->timestamp, current->amount, current->status);
        }
    }

    pthread_rwlock_unlock(&list->list_lock);
}

// Iterator for transactions
void iterate_transactions(TransactionList* list) {
    pthread_rwlock_rdlock(&list->list_lock);

    for (Transaction* current = list->head; current != NULL; current = current->next) {
        printf("Iterating Transaction: %lu, %.2f, %d\n", current->timestamp, current->amount, current->status);
    }

    pthread_rwlock_unlock(&list->list_lock);
}

// Initialize transactions with sequential timestamps
void initialize_transactions(TransactionList* list, size_t count) {
    uint64_t timestamp = EPOCH_TIME;

    for (size_t i = 0; i < count; ++i) {
        double amount = generate_random_amount(1.00, 1000.00);
        TransactionStatus status = generate_random_status();

        add_transaction(list, timestamp + i * TIMESTAMP_INCREMENT_USEC, amount, status);
    }
}

void destroy_transaction_list(TransactionList* list) {
    pthread_rwlock_wrlock(&list->list_lock);

    while (list->head != NULL) {
        Transaction* temp = list->head;
        list->head = list->head->next;

        free_transaction(&temp);
    }

    pthread_rwlock_unlock(&list->list_lock);
    pthread_rwlock_destroy(&list->list_lock);
    free(list);
}

// Main function for demonstration
int main() {
    srand(time(NULL));

    TransactionList* transaction_list = create_transaction_list();
    if (transaction_list) {
        initialize_transactions(transaction_list, 100);

        // Demonstrate filtering and iterating
        filter_transactions_by_status(transaction_list, COMPLETED);
        iterate_transactions(transaction_list);

        destroy_transaction_list(transaction_list);
    }

    return 0;
}
```

