    long lowest_offset;
    int avg_key;
} Metadata;

// Linked list management for records
typedef struct LinkedList {
    Record* head;
    Record* tail;
    pthread_mutex_t lock;
} LinkedList;

// Dynamic arrays and their metadata
typedef struct DynamicArray {
    void** data;
    size_t capacity;
    size_t count;
    int type_size;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
void initLinkedList(LinkedList* list);
Record* createRecord(long offset, int key, short age, float value, const char* binary_data, time_t timestamp);
void appendToLinkedList(LinkedList* list, Record* record);
DynamicArray* createDynamicArray(size_t initial_capacity, int type_size);
void resizeDynamicArray(DynamicArray* array);
void initializeDataStructure(LinkedList** list, DynamicArray** offsets, DynamicArray** keys, Metadata* metadata);
void freeDataStructure(LinkedList* list, DynamicArray* offsets, DynamicArray* keys);

// Helper functions
static inline long generateUniqueOffset(long last_offset) {
    return last_offset + rand() % 1000;
}

static inline int generateUniqueKey(int last_key) {
    return last_key + rand() % 10;
}

static inline float generateRandomFloat() {
    return (float)(rand() % 10000) / 100.0f;
}

static inline void generateBinaryData(char* data, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        data[i] = rand() % 256;
    }
}

// Implementation
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Record* createRecord(long offset, int key, short age, float value, const char* binary_data, time_t timestamp) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->offset = offset;
    record->key = key;
    record->age = age;
    record->value = value;
    strncpy(record->data, binary_data, sizeof(record->data));
    record->timestamp = timestamp;
    record->next = NULL;
    record->prev = NULL;

    return record;
}

void appendToLinkedList(LinkedList* list, Record* record) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = record;
        list->tail = record;
    } else {
        list->tail->next = record;
        record->prev = list->tail;
        list->tail = record;
    }

    pthread_mutex_unlock(&list->lock);
}

DynamicArray* createDynamicArray(size_t initial_capacity, int type_size) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (void**)malloc(initial_capacity * sizeof(void*));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    array->type_size = type_size;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void resizeDynamicArray(DynamicArray* array) {
    size_t new_capacity = array->capacity * 2;
    void** new_data = (void**)realloc(array->data, new_capacity * sizeof(void*));
    if (!new_data) return;

    array->data = new_data;
    array->capacity = new_capacity;
}

void initializeDataStructure(LinkedList** list, DynamicArray** offsets, DynamicArray** keys, Metadata* metadata) {
    srand(time(NULL));

    // Initialize linked list
    *list = (LinkedList*)malloc(sizeof(LinkedList));
    initLinkedList(*list);

    // Initialize dynamic arrays
    *offsets = createDynamicArray(10, sizeof(long));
    *keys = createDynamicArray(10, sizeof(int));

    metadata->total_records = 0;
    metadata->highest_offset = LONG_MIN;
    metadata->lowest_offset = LONG_MAX;
    metadata->avg_key = 0;

    // Example initialization loop
    for (size_t i = 0; i < 100; ++i) {
        long offset = generateUniqueOffset(metadata->highest_offset);
        int key = generateUniqueKey(metadata->avg_key);

        if (*offsets->count == *offsets->capacity) resizeDynamicArray(*offsets);
        if (*keys->count == *keys->capacity) resizeDynamicArray(*keys);

        (*offsets->data)[*offsets->count] = &offset;
        (*keys->data)[*keys->count] = &key;

        (*offsets->count)++;
        (*keys->count)++;

        metadata->highest_offset = (metadata->highest_offset > offset) ? metadata->highest_offset : offset;
        metadata->lowest_offset = (metadata->lowest_offset < offset) ? metadata->lowest_offset : offset;
        metadata->avg_key += key;

        char binary_data[1024];
        generateBinaryData(binary_data, sizeof(binary_data));

        time_t timestamp = time(NULL);
        Record* record = createRecord(offset, key, rand() % 100, generateRandomFloat(), binary_data, timestamp);

        appendToLinkedList(*list, record);
    }

    metadata->avg_key /= *offsets->count;
}

void freeDataStructure(LinkedList* list, DynamicArray* offsets, DynamicArray* keys) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);

    for (size_t i = 0; i < offsets->count; ++i) {
        free(offsets->data[i]);
    }
    free(offsets->data);
    pthread_mutex_destroy(&offsets->lock);

    for (size_t i = 0; i < keys->count; ++i) {
        free(keys->data[i]);
    }
    free(keys->data);
    pthread_mutex_destroy(&keys->lock);

    free(list);
    free(offsets);
    free(keys);
}

int main() {
    LinkedList* list;
    DynamicArray* offsets;
    DynamicArray* keys;
    Metadata metadata;

    initializeDataStructure(&list, &offsets, &keys, &metadata);

    // Use the data structure...

    freeDataStructure(list, offsets, keys);

    return 0;
}
```

