// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

#define MAX_MEMORY 1048576 // 1 MB in bytes

// Error codes
#define SUCCESS 0
#define ERROR_INVALID_INPUT -1
#define ERROR_MEMORY_LIMIT_EXCEEDED -2

int initialize_records(record ***records, size_t count, int key_min, int key_max, unsigned int seed) {
    if (count <= 0 || key_min >= key_max) {
        return ERROR_INVALID_INPUT;
    }

    // Calculate memory requirement for the records
    size_t record_size = sizeof(record);
    size_t total_memory = count * record_size;

    if (total_memory > MAX_MEMORY) {
        return ERROR_MEMORY_LIMIT_EXCEEDED;
    }

    pthread_mutex_lock(&mutex);

    // Allocate memory
    *records = malloc(total_memory);
    if (*records == NULL) {
        pthread_mutex_unlock(&mutex);
        return ERROR_MEMORY_LIMIT_EXCEEDED; // Treat allocation failure as exceeding limit for consistency
    }

    // Seed random number generator and initialize records with unique keys
    srand(seed);
    for (size_t i = 0; i < count; ++i) {
        int key;
        do {
            key = key_min + rand() % (key_max - key_min + 1);
        } while (i > 0 && (*records)[i-1].key == key); // Ensure uniqueness
        (*records)[i].key = key;
    }

    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

void free_records(record **records) {
    if (records != NULL && *records != NULL) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    record *records = NULL;

    int result = initialize_records(&records, 1000, 1, 2000, 42);

    if (result == SUCCESS) {
        for (size_t i = 0; i < 10; ++i) { // Print first 10 records
            printf("Record %zu: key = %d\n", i, records[i].key);
        }
    } else {
        fprintf(stderr, "Error initializing records: %d\n", result);
    }

    free_records(&records);

    return 0;
}
