#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

#define MAX_MEMORY_USAGE 1048576 // 1 MB

// Logging function (mock)
void log_memory_usage(size_t used) {
    printf("Memory usage: %zu bytes\n", used);
}

// Fetch configuration settings (mock)
int fetch_threshold() {
    return MAX_MEMORY_USAGE; // Mock threshold
}

pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_data(int num_records, int rand_min, int rand_max, unsigned int seed) {
    if (num_records <= 0 || rand_min > rand_max || seed == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_mutex);

    size_t record_size = sizeof(record_t);
    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);

    // Calculate total memory needed
    size_t required_memory = num_records * (record_size + long_size + int_size);

    if (required_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory requirement exceeds limit.\n");
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    log_memory_usage(required_memory);

    // Allocate memory
    long* offsets = malloc(num_records * long_size);
    int* keys = malloc(num_records * int_size);
    record_t* records = malloc(num_records * record_size);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&memory_mutex);
        free(offsets); free(keys); free(records);
        return NULL;
    }

    // Initialize random number generator
    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % MAX_MEMORY_USAGE; // Example offset initialization
        keys[i] = rand(); // Random key
        records[i].value = rand_min + rand() % (rand_max - rand_min + 1); // Random record value
    }

    pthread_mutex_unlock(&memory_mutex);

    // Return a struct with the allocated pointers
    typedef struct {
        long* offsets;
        int* keys;
        record_t* records;
    } data_struct;

    data_struct *data = malloc(sizeof(data_struct));
    if (data) {
        data->offsets = offsets;
        data->keys = keys;
        data->records = records;
    }

    return data;
}

void free_data(void* data) {
    if (!data) return;

    pthread_mutex_lock(&memory_mutex);

    data_struct *d = (data_struct*)data;
    free(d->offsets);
    free(d->keys);
    free(d->records);
    free(d);

    pthread_mutex_unlock(&memory_mutex);
}

int main() {
    int num_records = 1000;
    int rand_min = 10, rand_max = 20;
    unsigned int seed = 42;

    void* data = initialize_data(num_records, rand_min, rand_max, seed);
    if (data) {
        free_data(data);
    }

    return 0;
}
