    }

    pthread_rwlock_init(&list->rwlock, NULL);
    list->capacity = initial_capacity;
    list->count = 0;

    // Store the maximum size internally
    list->max_size = max_size;

    return list;
}

int insert_session(SessionList *list, Session session) {
    if (!list) return ERROR_INVALID_INPUT;

    pthread_rwlock_wrlock(&list->rwlock);

    if (list->count >= list->capacity || 
        list->count >= list->max_size ||
        list->sessions == NULL) {

        size_t new_capacity = list->capacity * 2;
        while ((new_capacity * sizeof(Session)) > MAX_MEMORY_USAGE || 
               new_capacity > list->max_size) {
            if (new_capacity / 2 < list->capacity) break;
            new_capacity /= 2;
        }

        Session *new_sessions = realloc(list->sessions, new_capacity * sizeof(Session));
        if (!new_sessions) {
            pthread_rwlock_unlock(&list->rwlock);
            return ERROR_INVALID_INPUT;
        }

        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }

    list->sessions[list->count++] = session;

    // Simulate logging
    log_session_to_external_service(&session);

    pthread_rwlock_unlock(&list->rwlock);
    return SUCCESS;
}

Session* retrieve_session(SessionList *list, size_t index) {
    if (!list || index >= list->count) return NULL;

    Session *result = NULL;
    pthread_rwlock_rdlock(&list->rwlock);

    result = &list->sessions[index];

    pthread_rwlock_unlock(&list->rwlock);
    return result;
}

int delete_session(SessionList *list, size_t index) {
    if (!list || index >= list->count) return ERROR_INVALID_INPUT;

    pthread_rwlock_wrlock(&list->rwlock);

    memmove(&list->sessions[index], &list->sessions[index + 1],
            (list->count - index - 1) * sizeof(Session));
    list->count--;

    // Simulate logging
    log_deletion_to_external_service(index);

    pthread_rwlock_unlock(&list->rwlock);
    return SUCCESS;
}

void destroy_session_list(SessionList *list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->rwlock);

    free(list->sessions);
    pthread_rwlock_unlock(&list->rwlock);

    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

