typedef struct {
    short sh;
    int integer;
    float flt;
    char fixedCharArray[50];
    unsigned char binaryData[MAX_BINARY_SIZE];
} Record;

typedef struct ListNode {
    Record record;
    time_t timestamp;
    size_t key;
    int compressed;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

typedef struct {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} DoublyLinkedList;

DoublyLinkedList list = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

void generate_random_record(Record *record) {
    record->sh = rand() % 1000;
    record->integer = rand() % 10000;
    record->flt = (float)(rand() % 100000.0f);
    for (int i = 0; i < sizeof(record->fixedCharArray); ++i)
        record->fixedCharArray[i] = 'A' + rand() % 26;

    size_t binarySize = rand() % MAX_BINARY_SIZE;
    for (size_t i = 0; i < binarySize; ++i) {
        record->binaryData[i] = rand() % 256;
    }
}

void insert_record(DoublyLinkedList* list, Record* record, size_t key, int compressed) {
    pthread_mutex_lock(&list->lock);

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    assert(newNode);

    memcpy(&newNode->record, record, sizeof(Record));
    newNode->timestamp = time(NULL);
    newNode->key = key;
    newNode->compressed = compressed;

    if (list->head == NULL) {
        list->head = list->tail = newNode;
        newNode->next = newNode->prev = NULL;
    } else {
        newNode->next = list->head;
        newNode->prev = NULL;
        list->head->prev = newNode;
        list->head = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void* cleanup_garbage(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;

    while (1) {
        pthread_mutex_lock(&list->lock);

        time_t currentTime = time(NULL);
        ListNode *current = list->tail, *prev = NULL;

        while (current != NULL && (currentTime - current->timestamp > 3600 || current->compressed)) {
            prev = current->prev;
            if (current == list->head) list->head = prev;
            if (current == list->tail) list->tail = prev;

            ListNode* toDelete = current;
            current = current->prev;

            if (prev != NULL)
                prev->next = NULL;

            free(toDelete);

            pthread_cond_signal(&list->cond_var);
        }

        pthread_mutex_unlock(&list->lock);
        sleep(60); // Run cleanup every minute
    }
}

void init_list(DoublyLinkedList* list) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, cleanup_garbage, list)) {
        fprintf(stderr, "Error creating the garbage collection thread\n");
        exit(1);
    }
}

int main() {
