// Define the client identifier structure
typedef struct Client {
    int id;
} Client;

// Event structure
typedef struct Event {
    char *buffer;
    float value;
    Client *client;
} Event;

// Node for tree-based data structure (e.g., binary search tree)
typedef struct TreeNode {
    double timestamp;
    unsigned int sequence_id;
    Event event;
    struct TreeNode *left, *right;
} TreeNode;

// Hash table entry
typedef struct HashEntry {
    unsigned int sequence_id;
    Event *event;
    struct HashEntry *next;
} HashEntry;

// Global variables for the hash table and tree
#define HASH_TABLE_SIZE 1024
HashEntry *hash_table[HASH_TABLE_SIZE];
TreeNode *root = NULL;
pthread_mutex_t hash_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t tree_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_function(unsigned int sequence_id) {
    return sequence_id % HASH_TABLE_SIZE;
}

// Function to initialize event log system
void init_event_log_system() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

// Function to dynamically allocate and populate an event
Event *create_event(Client *client, const char *buffer_content, float value_range) {
    Event *event = malloc(sizeof(Event));
    if (!event) return NULL;

    event->buffer = strdup(buffer_content);
    if (!event->buffer) {
        free(event);
        return NULL;
    }

    event->value = (float)(rand() / (RAND_MAX / value_range));
    event->client = client;
    return event;
}

// Function to insert an event into the hash table and tree
int insert_event(double timestamp, unsigned int sequence_id, Event *event) {
    pthread_mutex_lock(&hash_lock);

    // Insert into hash table
    unsigned int index = hash_function(sequence_id);
    HashEntry *entry = malloc(sizeof(HashEntry));
    if (!entry) {
        pthread_mutex_unlock(&hash_lock);
        return -1;
    }

    entry->sequence_id = sequence_id;
    entry->event = event;
    entry->next = hash_table[index];
    hash_table[index] = entry;

    pthread_mutex_unlock(&hash_lock);

    // Insert into tree
    pthread_mutex_lock(&tree_lock);

    TreeNode **node = &root;
    while (*node) {
        if (timestamp < (*node)->timestamp) {
            node = &((*node)->left);
        } else {
            node = &((*node)->right);
        }
    }

    TreeNode *new_node = malloc(sizeof(TreeNode));
    if (!new_node) {
        pthread_mutex_unlock(&tree_lock);
        return -1;
    }

    new_node->timestamp = timestamp;
    new_node->sequence_id = sequence_id;
    new_node->event = *event;
    new_node->left = new_node->right = NULL;

    *node = new_node;

    pthread_mutex_unlock(&tree_lock);

    return 0;
}

// Function to monitor system performance (placeholder for actual monitoring logic)
void monitor_performance() {
    // Example: Counting allocated entries
    int count = 0;
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashEntry *entry = hash_table[i];
        while (entry) {
            count++;
            entry = entry->next;
        }
    }

    printf("Currently %d events are stored.\n", count);
}

// Example main function to demonstrate usage
int main() {
    srand(time(NULL));
    init_event_log_system();

    // Simulate event creation and insertion
    Client client = { .id = 1 };
    for (unsigned int i = 0; i < 10; ++i) {
        double timestamp = (double)time(NULL);
        Event *event = create_event(&client, "Example buffer", 100.0f);

        if (!insert_event(timestamp, i, event)) {
            printf("Inserted event with sequence ID: %u\n", i);
        } else {
            fprintf(stderr, "Failed to insert event with sequence ID: %u\n", i);
        }

        // Free allocated memory for the example
        free(event->buffer);
        free(event);
    }

    monitor_performance();

    return 0;
}
