#define MAX_METADATA_LENGTH 256
#define MAX_PATH_LENGTH 512

typedef struct {
    int short_field;
    int int_field;
    float float_field;
    time_t timestamp;
} Record;

typedef struct {
    int short_field;
    int int_field;
    float float_field;
    time_t timestamp;
