    struct ListNode *prev, *next;
} ListNode;

typedef struct HashMapNode {
    char key[MAX_PATH_LENGTH];
    Chunk chunk;
    struct HashMapNode *next;
} HashMapNode;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    pthread_mutex_t mutex;
} Collection;

typedef struct {
    ListNode *head, *tail;
    pthread_rwlock_t rwlock;
} DoublyLinkedList;

typedef struct {
    HashMapNode **buckets;
    size_t bucket_count;
    pthread_rwlock_t rwlock;
} HashMap;

// Utility functions
void init_random_seed() {
    srand((unsigned)time(NULL));
}

int random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

double random_double(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

void init_memory_pool(size_t initial_size, size_t growth_factor, void ***pool, size_t **size, pthread_mutex_t **mutex) {
    *pool = malloc(initial_size * sizeof(void *));
    *size = malloc(sizeof(size_t));
    *mutex = malloc(sizeof(pthread_mutex_t));

    pthread_mutex_init(*mutex, NULL);
    pthread_mutex_lock(*mutex);

    *(*size) = initial_size;
    for (size_t i = 0; i < initial_size; ++i) {
        (*pool)[i] = malloc(growth_factor);
    }

    pthread_mutex_unlock(*mutex);
}

void *allocate_from_pool(void **pool, size_t **size, pthread_mutex_t *mutex, size_t growth_factor) {
    void *memory;

    pthread_mutex_lock(mutex);
    if (**size == 0) {
        size_t new_size = (*growth_factor > 1 ? *growth_factor : initial_size) << 1;
        void **new_pool = realloc(*pool, new_size * sizeof(void *));

        for (size_t i = (**size); i < new_size; ++i) {
            new_pool[i] = malloc(growth_factor);
        }

        *pool = new_pool;
        *(*size) = new_size;
    }

    memory = (*pool)[--(**size)];
    pthread_mutex_unlock(mutex);

    return memory;
}

void free_memory_pool(void **pool, size_t *size, pthread_mutex_t *mutex, size_t growth_factor) {
    pthread_mutex_lock(mutex);

    for (size_t i = 0; i < *size; ++i) {
        if ((*pool)[i]) free((*pool)[i]);
    }

    free(*pool);
    free(size);
    pthread_mutex_destroy(mutex);
    free(mutex);
}

// Thread-safe linked list functions
void init_doubly_linked_list(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
}

ListNode* create_list_node(const Record record) {
    ListNode *node = (ListNode *)allocate_from_pool(/* pool */, /* size */, /* mutex */, /* growth_factor */);
    node->record = record;
    node->prev = node->next = NULL;

    return node;
}

void insert_at_end(DoublyLinkedList *list, ListNode *node) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (!list->tail) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void init_hash_map(HashMap *map, size_t bucket_count) {
    map->buckets = calloc(bucket_count, sizeof(HashMapNode *));
    map->bucket_count = bucket_count;
    pthread_rwlock_init(&map->rwlock, NULL);
}

unsigned int hash_function(const char *str) {
    unsigned int hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash % map.bucket_count;
}

void insert_into_hash_map(HashMap *map, const char *key, const Chunk chunk) {
    pthread_rwlock_wrlock(&map->rwlock);

    unsigned int index = hash_function(key);
    HashMapNode *node = (HashMapNode *)allocate_from_pool(/* pool */, /* size */, /* mutex */, /* growth_factor */);

    strcpy(node->key, key);
    node->chunk = chunk;
    node->next = map->buckets[index];
    map->buckets[index] = node;

    pthread_rwlock_unlock(&map->rwlock);
}

// Main initialization function
