['Below is a C implementation outline for a flexible logging framework supporting multiple backends, log levels, thread safety, structured logging, log rotation, dynamic backend configuration, and rate-limiting.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_LOG_BACKENDS 10
#define LOG_BUFFER_SIZE 1024
#define LOG_ROTATION_INTERVAL 24 * 60 * 60 // 1 day in seconds

typedef enum { DEBUG, INFO, WARNING, ERROR, CRITICAL } LogLevel;

typedef struct {
    char name[50];
    void (*log_func)(LogLevel level, const char* message);
} LogBackend;

typedef struct {
    LogLevel global_level;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int log_count[MAX_THREADS];
    time_t start_time;
    FILE* logfile;
} LoggerConfig;

LoggerConfig logger_config = {.global_level = INFO};

pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
LogBackend log_backends[MAX_LOG_BACKENDS];
int backend_count = 0;

void init_logger() {
    pthread_mutex_init(&logger_config.lock, NULL);
    pthread_cond_init(&logger_config.cond, NULL);
    logger_config.start_time = time(NULL);

    // Example: Register a console backend
    strncpy(log_backends[backend_count].name, "console", sizeof(log_backends[0].name));
    log_backends[backend_count].log_func = &console_log;
    backend_count++;
}

void console_log(LogLevel level, const char* message) {
    if (level >= logger_config.global_level) {
        printf("[%s] %s\n", log_level_to_string(level), message);
    }
}

char* log_level_to_string(LogLevel level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO:  return "INFO";
        case WARNING: return "WARNING";
        case ERROR:  return "ERROR";
        case CRITICAL: return "CRITICAL";
        default: return "UNKNOWN";
    }
}

void log_message(LogLevel level, const char* message) {
    pthread_mutex_lock(&logger_config.lock);

    if (level < logger_config.global_level) {
        pthread_mutex_unlock(&logger_config.lock);
        return;
    }

    for (int i = 0; i < backend_count; i++) {
        log_backends[i].log_func(level, message);
    }

    // Handle log rotation
    time_t current_time = time(NULL);
    if ((current_time - logger_config.start_time) > LOG_ROTATION_INTERVAL) {
        // Rotate logs here
        pthread_mutex_unlock(&logger_config.lock);
        rotate_logs();
        return;
    }

    pthread_mutex_unlock(&logger_config.lock);
}

void rotate_logs() {
    if (fclose(logger_config.logfile)) {
        perror("Error closing log file");
    }
    char new_name[256];
    snprintf(new_name, sizeof(new_name), "logfile_%ld.txt", logger_config.start_time);
    rename("logfile.txt", new_name);
    logger_config.logfile = fopen("logfile.txt", "a");
    if (!logger_config.logfile) {
        perror("Error opening log file");
    }
    logger_config.start_time = time(NULL);
}

void add_log_backend(const char* name, void (*log_func)(LogLevel level, const char* message)) {
    pthread_mutex_lock(&config_mutex);

    if (backend_count < MAX_LOG_BACKENDS) {
        strncpy(log_backends[backend_count].name, name, sizeof(log_backends[0].name));
        log_backends[backend_count].log_func = log_func;
        backend_count++;
    }

    pthread_mutex_unlock(&config_mutex);
}

void udp_log_backend(LogLevel level, const char* message) {
    // Implement UDP logging here
}

// Example function to add a new UDP backend dynamically
void setup_udp_backend() {
    add_log_backend("udp", &udp_log_backend);
}

int main() {
    init_logger();

    // Configure loggers and run application logic...

    return 0;
}
