#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_METADATA_LENGTH 256
#define INITIAL_POOL_SIZE 1024

typedef enum { EVENT_TYPE_A, EVENT_TYPE_B } EventType;

typedef struct Record {
    short s;
    int i;
    float f;
    int timestamp;
    char *metadata;
    EventType event_type;
    struct Record* prev;
    struct Record* next;
} Record;

// Memory pool management structures
typedef struct MemoryPool {
    void* start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->start = malloc(initial_size);
    pool->size = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size < size) {
        void* new_start = realloc(pool->start, pool->size + INITIAL_POOL_SIZE);
        if (!new_start) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->start = new_start;
        pool->size += INITIAL_POOL_SIZE;
    }

    void* result = pool->start;
    pool->start = ((char*)pool->start) + size;
    pool->size -= size;

    pthread_mutex_unlock(&pool->lock);
    return result;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->start);
        free(pool);
    }
}

// Linked list management
typedef struct LinkedList {
    Record *head;
    Record *tail;
    pthread_rwlock_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* ll = malloc(sizeof(LinkedList));
    ll->head = NULL;
    ll->tail = NULL;
    pthread_rwlock_init(&ll->lock, NULL);
    return ll;
}

void insert_record(LinkedList* ll, Record* record) {
    pthread_rwlock_wrlock(&ll->lock);

    if (!ll->head) {
        ll->head = record;
        ll->tail = record;
        record->prev = record->next = NULL;
    } else {
        ll->tail->next = record;
        record->prev = ll->tail;
        record->next = NULL;
        ll->tail = record;
    }

    pthread_rwlock_unlock(&ll->lock);
}

void free_linked_list(LinkedList* ll) {
    Record *current, *next;

    pthread_rwlock_wrlock(&ll->lock);

    current = ll->head;
    while (current != NULL) {
        next = current->next;
        if (current->metadata) free(current->metadata);
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&ll->lock);
    pthread_rwlock_destroy(&ll->lock);
    free(ll);
}

// Initialization and population logic
void initialize_collections(
    long **offsets, int *keys, Record ***records,
    int **timestamps, char ***metadata, EventType **events, size_t count) {

    MemoryPool* record_pool = create_memory_pool(count * sizeof(Record));
    MemoryPool* metadata_pool = create_memory_pool(count * MAX_METADATA_LENGTH);

    *offsets = malloc(count * sizeof(long));
    *keys = malloc(count * sizeof(int));
    *records = malloc(count * sizeof(Record*));
    *timestamps = malloc(count * sizeof(int));
    *metadata = malloc(count * sizeof(char*));
    *events = malloc(count * sizeof(EventType));

    srand((unsigned)time(NULL));

    long offset_sum = 0;
    for (size_t i = 0; i < count; ++i) {
        int key = rand() % 10000 + 1; // Example range
        while (*keys != NULL && bsearch(&key, *keys, i, sizeof(int), cmpfunc)) {
            key = rand() % 10000 + 1;
        }
        offset_sum += key;
        (*offsets)[i] = offset_sum;

        (*keys)[i] = key;

        Record* record = (Record*)allocate_from_pool(record_pool, sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        record->s = rand() % 32768;
        record->i = rand() % 1000;
        record->f = (float)(rand() % 10000) / 100.0;
        (*timestamps)[i] = rand() % 1000000;
        record->timestamp = (*timestamps)[i];

        char* meta_str = (char*)allocate_from_pool(metadata_pool, MAX_METADATA_LENGTH);
        snprintf(meta_str, MAX_METADATA_LENGTH, "Metadata_%zu", i);

        record->metadata = meta_str;
        (*metadata)[i] = meta_str;

        record->event_type = i % 2 == 0 ? EVENT_TYPE_A : EVENT_TYPE_B;
        (*events)[i] = record->event_type;

        record->prev = record->next = NULL;
        *records[i] = record;
    }
}

int cmpfunc(const void* a, const void* b) {
    return (*(const int*)a - *(const int*)b);
}

// Main function
int main() {
    size_t count = 1000;

    long* offsets;
    int* keys;
    Record** records;
    int* timestamps;
    char** metadata;
    EventType* events;

    initialize_collections(&offsets, &keys, &records, &timestamps, &metadata, &events, count);

    // Create and populate the linked list
    LinkedList* record_list = create_linked_list();

    for (size_t i = 0; i < count; ++i) {
        insert_record(record_list, records[i]);
    }

    // Clean up resources
    free_memory_pool(create_memory_pool(0));  // Replace with actual pool
    free_linked_list(record_list);
    free(offsets);
    free(keys);
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);  // Records should be freed individually, metadata is part of records
    }
    free(records);
    free(timestamps);
    free(metadata);
    free(events);

    return 0;
}
