['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset_ptr;
    int key_index;
} record;

// Custom memory pool structure
typedef struct {
    void **pool;
    size_t item_size;
    size_t pool_size;
    size_t used_slots;
    pthread_mutex_t lock; // For thread safety in memory pool access
} memory_pool;

#define MEMORY_POOL_DEFAULT_SIZE 1024

memory_pool *create_memory_pool(size_t item_size, size_t initial_size) {
    memory_pool *mp = malloc(sizeof(memory_pool));
    if (!mp) return NULL;

    mp->item_size = item_size;
    mp->pool_size = initial_size > 0 ? initial_size : MEMORY_POOL_DEFAULT_SIZE;
    mp->used_slots = 0;
    mp->pool = calloc(mp->pool_size, sizeof(void *));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void *allocate_from_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used_slots >= mp->pool_size) { // Pool needs resizing
        size_t new_size = mp->pool_size * 2;
        void **new_pool = realloc(mp->pool, new_size * sizeof(void *));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->pool_size = new_size;
    }

    void *item = malloc(mp->item_size);
    if (item) {
        mp->pool[mp->used_slots++] = item; // Keep track of allocated items
    }

    pthread_mutex_unlock(&mp->lock);
    return item;
}

void free_memory_pool(memory_pool *mp) {
    for (size_t i = 0; i < mp->used_slots; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

int manage_record_storage(int array_size, int num_records, long min_value, long max_value, memory_pool **mp) {
    if (array_size <= 0 || num_records > array_size) return -1;

    *mp = create_memory_pool(sizeof(record), MEMORY_POOL_DEFAULT_SIZE);
    if (!*mp) return -2;

    // Initialize offset and key arrays
    long *offsets = (long *)malloc(array_size * sizeof(long));
    int *keys = (int *)malloc(array_size * sizeof(int));

    if (!offsets || !keys) {
        free_memory_pool(*mp);
        return -3;
    }

    for (int i = 0; i < array_size; ++i) {
        offsets[i] = min_value + rand() % (max_value - min_value + 1); // Unique and valid values
        keys[i] = i; // Simple key initialization, can be adjusted as needed
    }

    // Initialize records with constraints
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        free_memory_pool(*mp);
        return -4;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);

        // Ensure valid offset and key index
        long *offset_ptr = &offsets[rand() % array_size];
        int key_idx = rand() % array_size;

        // Avoid duplicates/mismatches; simplistic check for illustration
        records[i].offset_ptr = offset_ptr;
        records[i].key_index = key_idx;
    }

    // Free dynamically allocated arrays after use
    free(offsets);
    free(keys);

    return 0; // Success
}

void cleanup_and_exit(memory_pool *mp) {
    if (mp) free_memory_pool(mp);
    exit(0);
}
