void* memory_pool_alloc(MemoryPool *pool, size_t size);
void resize_offset_array(double **offsets, int *current_size, int new_size);
int manage_entries_and_summaries(Entry ***entries, Summary ***summaries, int num_entries,
                                 double min_value, double max_value, int user_id);

// Initialize a memory pool
void initialize_memory_pool(MemoryPool *pool, size_t initial_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->memory = malloc(initial_size);
    if (!pool->memory) {
        LOG("ERROR", "Memory allocation failed for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->size = initial_size;
    pool->used = 0;
}

// Free a memory pool
void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->memory) {
        free(pool->memory);
        pool->memory = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Allocate memory from the memory pool
void* memory_pool_alloc(MemoryPool *pool, size_t size) {
    if (size + pool->used > pool->size) {
        size_t new_size = pool->size;
        while (new_size < size + pool->used) {
            new_size *= 2;
        }
        void *new_memory = realloc(pool->memory, new_size);
        if (!new_memory) {
            LOG("ERROR", "Memory reallocation failed in memory pool");
            return NULL;
        }
        pthread_mutex_lock(&pool->lock);
        pool->memory = new_memory;
        pool->size = new_size;
        pthread_mutex_unlock(&pool->lock);
    }

    void *result = (char *)pool->memory + pool->used;
    pthread_mutex_lock(&pool->lock);
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return result;
}

// Resize offset array dynamically
void resize_offset_array(double **offsets, int *current_size, int new_size) {
    double *new_offsets = realloc(*offsets, sizeof(double) * new_size);
    if (!new_offsets) {
        LOG("ERROR", "Failed to reallocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    *offsets = new_offsets;
    *current_size = new_size;
}

// Manage entries and summaries with thread safety
int manage_entries_and_summaries(Entry ***entries, Summary ***summaries, int num_entries,
                                 double min_value, double max_value, int user_id) {
    pthread_mutex_t lock;
    MemoryPool pool;

    initialize_memory_pool(&pool, 1024); // Initial size for demonstration
    *entries = memory_pool_alloc(&pool, sizeof(Entry *) * num_entries);
    if (!*entries) return -1;

    *summaries = memory_pool_alloc(&pool, sizeof(Summary *) * num_entries);
    if (!*summaries) {
        free(*entries);
        return -1;
    }

    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_entries; ++i) {
        (*entries)[i] = memory_pool_alloc(&pool, sizeof(Entry));
        if (!(*entries)[i]) {
            LOG("ERROR", "Failed to allocate entry");
            continue;
        }

        // Initialize entry with random double value and current time
        (*entries)[i]->value = min_value + (rand() / (RAND_MAX / (max_value - min_value)));
        snprintf((*entries)[i]->message, sizeof((*entries)[i]->message), "Description %d", i);

        (*summaries)[i] = memory_pool_alloc(&pool, sizeof(Summary));
        if (!(*summaries)[i]) {
            LOG("ERROR", "Failed to allocate summary");
            continue;
        }

        // Initialize summary with entry pointer and timestamp
        (*summaries)[i]->entry = (*entries)[i];
        (*summaries)[i]->timestamp = time(NULL);

        // Log operation
        LOG("INFO", "Entry %d initialized with value %.2f by user %d", i, (*entries)[i]->value, user_id);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}

// Main function for demonstration purposes only (not part of the requirements)
int main() {
    Entry *entries = NULL;
    Summary *summaries = NULL;

    if (manage_entries_and_summaries(&entries, &summaries, 1000, 1.0, 10.0, 42) == 0) {
        LOG("INFO", "Entries and summaries managed successfully");
    } else {
        LOG("ERROR", "Failed to manage entries and summaries");
    }

    // Cleanup
    free(entries);
    free(summaries);

    return 0;
}
```

### Key Points:
- **Memory Management**: Utilizes a memory pool for efficient allocation and resizing, reducing fragmentation.
- **Thread Safety**: Uses `pthread_mutex_t` for protecting shared data structures.
- **Dynamic Resizing**: Handles dynamic resizing of the offset array with reallocation logic.
- **Error Handling**: Provides error messages upon allocation failures and logs operations using an external logging library placeholder.
- **Initialization**: Populates entries with random double values and timestamps, ensuring efficient initialization.

This code provides a foundational structure that can be extended to include additional fields in `Entry` and `Summary`, integrate more sophisticated caching mechanisms, or adjust locking granularity as needed.']

