typedef struct MemoryPool {
    size_t block_size;
    void* pool;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Global memory pool
MemoryPool mem_pool;

void init_memory_pool(size_t block_size, size_t total_blocks) {
    mem_pool.block_size = block_size;
    mem_pool.total_blocks = total_blocks;
    mem_pool.pool = malloc(block_size * total_blocks);
    pthread_mutex_init(&mem_pool.lock, NULL);
}

void* memory_alloc() {
    pthread_mutex_lock(&mem_pool.lock);
    static void* current_ptr = mem_pool.pool;

    if (current_ptr + mem_pool.block_size > mem_pool.pool + mem_pool.block_size * mem_pool.total_blocks) {
        // Memory exhaustion, fallback to standard allocation
        void* new_block = malloc(mem_pool.block_size);
        pthread_mutex_unlock(&mem_pool.lock);

        if (!new_block) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        return new_block;
    }

    void* block_ptr = current_ptr;
    current_ptr += mem_pool.block_size;
    pthread_mutex_unlock(&mem_pool.lock);

    return block_ptr;
}

void memory_free(void* ptr) {
    // Custom free function not needed as we use a fixed-size pool.
    // In real-world scenarios, you might implement a custom management strategy.
}

Record* create_record(short s, int i, float f, int timestamp, int priority) {
