    for (int i = 0; i < num_elements; ++i) {
        if (key_range_end <= key_range_start) {
            key[i] = rand() % 1000 + 1; // Default fallback range
        } else {
            key[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        }

        cumulative_sum += key[i];
        offset[i] = cumulative_sum + i; // Simplified offset calculation for demonstration

        if (i < num_elements - 1) {
            offset[i + 1] = offset[i] + rand() % 10 + 1; // Incrementing to prevent overlap
        }
    }
}

void initialize_linked_list(Record** head, int size) {
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
    *head = create_record(rand() % 100, rand() % 1000, (float)rand() / RAND_MAX, time(NULL), rand() % 10);

    Record* current = *head;

    for (int i = 1; i < size; ++i) {
        Record* new_record = create_record(rand() % 100, rand() % 1000, (float)rand() / RAND_MAX, time(NULL), rand() % 10);

        if (!new_record) break;

        pthread_mutex_lock(&list_lock);

        current->next = new_record;
        new_record->prev = current;
        current = current->next;

        pthread_mutex_unlock(&list_lock);
    }
}

void iterate_linked_list(Record* head) {
