               current->s, current->i, current->f, current->timestamp, current->priority);

        current = current->next;
    }
}

void resize_array(int** array, int* size, int new_size) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);

    *array = (int*) realloc(*array, sizeof(int) * new_size);
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = *size; i < new_size; ++i) {
        (*array)[i] = rand() % 1000 + 1;
    }

    *size = new_size;

    pthread_mutex_unlock(&lock);
}

void manage_data_pipeline(int num_elements, int key_range_start, int key_range_end) {
    long* offset = (long*) memory_alloc();
    int* keys = (int*) memory_alloc();
    Record* head = NULL;
    int priority_levels[num_elements];

