    initialize_arrays(offset, keys, num_elements, key_range_start, key_range_end);

    for (int i = 0; i < num_elements; ++i) {
        priority_levels[i] = rand() % 10 + 1;
    }

    initialize_linked_list(&head, num_elements);

    iterate_linked_list(head);

    // Demonstrate resizing
    resize_array(&keys, &num_elements, num_elements + 5);
}

int main() {
    srand(time(NULL)); // Seed for randomness

    init_memory_pool(sizeof(Record), 100); // Initialize memory pool with size and block count

    manage_data_pipeline(10, 1, 100);

    return 0;
}
