#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define record structure
typedef struct Record {
    short s;
    int i;
    float f;
    long timestamp;
    size_t sz;
} Record;

// Node for doubly linked list
typedef struct ListNode {
    Record data;
    struct ListNode *prev;
    struct ListNode *next;
} ListNode;

// Hash table entry
typedef struct HashEntry {
    int key;
    ListNode *node;
    struct HashEntry *next;
} HashEntry;

// Memory pool management structures
#define POOL_SIZE 1024
#define INITIAL_ARRAY_SIZE 10

typedef struct MemoryPool {
    size_t block_size;
    void **blocks;
    size_t num_blocks;
} MemoryPool;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    long *timestamps;
    size_t *sizes;
    ListNode *head, *tail;
    HashEntry **hash_table;
    pthread_mutex_t lock;
    MemoryPool pool;
    size_t array_size;
} DataManager;

// Function declarations
void initialize_memory_pool(MemoryPool *pool, size_t block_size, size_t num_blocks);
void* allocate_from_pool(MemoryPool *pool);
DataManager* init_data_manager(size_t initial_array_size);
void free_data_manager(DataManager *dm);
void resize_arrays(DataManager *dm);
void add_record(DataManager *dm, Record record, int key);
Record get_record_by_key(DataManager *dm, int key);
ListNode* get_next_node(ListNode *node);

// Initialize memory pool
void initialize_memory_pool(MemoryPool *pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->blocks = (void **)malloc(num_blocks * sizeof(void *));
    for(size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
    pool->num_blocks = num_blocks;
}

// Allocate memory from pool
void* allocate_from_pool(MemoryPool *pool) {
    if (pool->num_blocks == 0) return NULL;
    void *block = pool->blocks[--pool->num_blocks];
    return block;
}

// Initialize data manager
DataManager* init_data_manager(size_t initial_array_size) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));

    pthread_mutex_init(&dm->lock, NULL);
    initialize_memory_pool(&dm->pool, sizeof(Record), POOL_SIZE);

    dm->array_size = initial_array_size;
    dm->offsets = (long*)malloc(initial_array_size * sizeof(long));
    dm->keys = (int*)malloc(initial_array_size * sizeof(int));
    dm->records = (Record*)malloc(initial_array_size * sizeof(Record));
    dm->timestamps = (long*)malloc(initial_array_size * sizeof(long));
    dm->sizes = (size_t*)malloc(initial_array_size * sizeof(size_t));

    // Initialize hash table
    dm->hash_table = (HashEntry**)calloc(initial_array_size, sizeof(HashEntry*));

    // Initialize linked list
    dm->head = NULL;
    dm->tail = NULL;

    return dm;
}

// Free data manager and its resources
void free_data_manager(DataManager *dm) {
    if (!dm) return;
    pthread_mutex_destroy(&dm->lock);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        free(dm->pool.blocks[i]);
    }
    free(dm->pool.blocks);

    // Free linked list nodes
    ListNode *current = dm->head;
    while(current != NULL) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }

    // Free hash table entries
    for (size_t i = 0; i < dm->array_size; ++i) {
        HashEntry *entry = dm->hash_table[i];
        while(entry != NULL) {
            HashEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }

    free(dm->hash_table);
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    free(dm->timestamps);
    free(dm->sizes);

    free(dm);
}

// Resize arrays when needed
void resize_arrays(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    size_t new_size = dm->array_size * 2;
    long *new_offsets = (long*)realloc(dm->offsets, new_size * sizeof(long));
    int *new_keys = (int*)realloc(dm->keys, new_size * sizeof(int));
    Record *new_records = (Record*)realloc(dm->records, new_size * sizeof(Record));
    long *new_timestamps = (long*)realloc(dm->timestamps, new_size * sizeof(long));
    size_t *new_sizes = (size_t*)realloc(dm->sizes, new_size * sizeof(size_t));

    if(new_offsets && new_keys && new_records && new_timestamps && new_sizes) {
        dm->offsets = new_offsets;
        dm->keys = new_keys;
        dm->records = new_records;
        dm->timestamps = new_timestamps;
        dm->sizes = new_sizes;

        // Resize hash table
        HashEntry **new_hash_table = (HashEntry**)calloc(new_size, sizeof(HashEntry*));
        for(size_t i = 0; i < dm->array_size; ++i) {
            if(dm->hash_table[i]) {
                HashEntry *entry = dm->hash_table[i];
                while(entry != NULL) {
                    HashEntry *next_entry = entry->next;

                    // Calculate new hash index
                    size_t new_index = (size_t)(entry->key % new_size);
                    entry->next = new_hash_table[new_index];
                    new_hash_table[new_index] = entry;

                    entry = next_entry;
                }
            }
        }

        free(dm->hash_table);
        dm->hash_table = new_hash_table;
        dm->array_size = new_size;
    }

    pthread_mutex_unlock(&dm->lock);
}

// Add record to manager
void add_record(DataManager *dm, Record record, int key) {
    pthread_mutex_lock(&dm->lock);

    if (pthread_mutex_trylock(&dm->lock) == 0) { // Check for potential race condition before full lock
        size_t idx = dm->array_size; // Index to insert new element

        // Resize arrays if needed
        if(idx >= dm->array_size) {
            resize_arrays(dm);
        }

        // Update linked list and hash table
        ListNode *new_node = (ListNode*)allocate_from_pool(&dm->pool);
        new_node->data = record;
        new_node->next = NULL;

        if (dm->tail) {
            dm->tail->next = new_node;
            new_node->prev = dm->tail;
            dm->tail = new_node;
        } else {
            dm->head = new_node;
            dm->tail = new_node;
            new_node->prev = NULL;
        }

        // Update hash table
        size_t hash_index = (size_t)(key % dm->array_size);
        HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
        entry->key = key;
        entry->node = new_node;
        entry->next = dm->hash_table[hash_index];
        dm->hash_table[hash_index] = entry;

        // Update arrays
        if (idx == 0) {
            dm->offsets[0] = 0;
        } else {
            dm->offsets[idx] = dm->offsets[idx-1] + key; // Calculate new offset
        }
        dm->keys[idx] = key;

        pthread_mutex_unlock(&dm->lock);
    }

    if (pthread_mutex_trylock(&dm->lock) != 0) { // If couldn't lock, unlock and retry operation
        pthread_mutex_unlock(&dm->lock);
        add_record(dm, record, key); // Retry adding the record
    }
}

// Retrieve record by key from manager
Record get_record_by_key(DataManager *dm, int key) {
    pthread_mutex_lock(&dm->lock);

    size_t hash_index = (size_t)(key % dm->array_size);
    HashEntry *entry = dm->hash_table[hash_index];

    while(entry != NULL && entry->key != key) {
        entry = entry->next;
    }

    Record record = {0};
    if(entry) {
        record = entry->node->data;
    }

    pthread_mutex_unlock(&dm->lock);
    return record;
}

// Iterate over the linked list
ListNode* get_next_node(ListNode *node) {
    return node ? node->next : NULL;
}
