#define MAX_STRINGS 100
#define ALLOWED_VALUES_COUNT 5

typedef struct {
    int id;
    double value;
} item;

int allowed_values[MAX_STRINGS][MAX_STRINGS] = {{"apple", "banana", "cherry", "date", "elderberry"}}; // Example list

pthread_mutex_t lock;

void validate_and_store_string(char **string_array, const char *input_str) {
    int is_valid = 0;
    for (int i = 0; i < ALLOWED_VALUES_COUNT; ++i) {
        if (strcmp(allowed_values[0][i], input_str) == 0) {
            is_valid = 1;
            break;
        }
    }

    if (is_valid) {
        pthread_mutex_lock(&lock);
        int count = 0;
        while (string_array[count] != NULL) {
            ++count;
        }

        string_array[count] = strdup(input_str);
        if (!string_array[count]) {
            fprintf(stderr, "Memory allocation for string failed\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_unlock(&lock);
    } else {
        fprintf(stderr, "Invalid string: %s\n", input_str);
    }
}

void initialize_data_structures(double **double_array, char ***string_array, item ***item_array) {
    pthread_mutex_init(&lock, NULL);

    *double_array = malloc(10 * sizeof(double));
    if (!*double_array) {
        fprintf(stderr, "Memory allocation for double array failed\n");
        exit(EXIT_FAILURE);
    }

    *string_array = malloc(MAX_STRINGS * sizeof(char *));
    if (!*string_array) {
        free(*double_array);
        fprintf(stderr, "Memory allocation for string array failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_STRINGS; ++i) {
        (*string_array)[i] = NULL;
    }

    *item_array = malloc(10 * sizeof(item *));
    if (!*item_array) {
        free(*double_array);
        free(*string_array);
        fprintf(stderr, "Memory allocation for item array failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 10; ++i) {
        (*item_array)[i] = malloc(sizeof(item));
        if (!(*item_array)[i]) {
            free(*double_array);
            for (int j = 0; j < MAX_STRINGS; ++j) {
                free((*string_array)[j]);
            }
            free(*string_array);
            for (int j = 0; j < i; ++j) {
                free((*item_array)[j]);
            }
            free(*item_array);
            fprintf(stderr, "Memory allocation for item struct failed\n");
            exit(EXIT_FAILURE);
        }

        (*item_array)[i]->id = i + 1;
        (*item_array)[i]->value = sin((double)(*item_array)[i]->id); // Using sine function
    }
}

void free_data_structures(double *double_array, char **string_array, item **item_array) {
    pthread_mutex_destroy(&lock);

    free(double_array);

    for (int i = 0; i < MAX_STRINGS; ++i) {
        if (string_array[i]) {
            free(string_array[i]);
        }
    }
    free(string_array);

    for (int i = 0; i < 10; ++i) {
        if (item_array[i]) {
            free(item_array[i]);
        }
    }
    free(item_array);
}
