#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long value;
} record_t;

// Function prototypes
long* initialize_offsets(size_t size, int align);
int* initialize_keys(size_t size);
record_t* initialize_records(size_t size);

void handle_memory_error(const char* msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

long get_random_value() {
    return rand() % 1001;
}

// Initialize offsets with alignment
long* initialize_offsets(size_t size, int align) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, (size_t)align, size * sizeof(long)) != 0) {
        handle_memory_error("Failed to allocate memory for offsets");
    }
    long* offsets = (long*)ptr;

    // Simulating initialization with valid large integer values
    for (size_t i = 0; i < size; ++i) {
        if ((INT_MAX - LLONG_MIN) / sizeof(long) > INT_MAX || 
            (LLONG_MIN + LLONG_MAX) / sizeof(long) < LLONG_MIN) {
            offsets[i] = rand() % LLONG_MAX;
        } else {
            offsets[i] = LLONG_MIN + (rand() % ((LLONG_MAX - LLONG_MIN) / sizeof(long))) * sizeof(long);
        }
    }

    return offsets;
}

// Initialize keys with bounds checking
int* initialize_keys(size_t size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) handle_memory_error("Failed to allocate memory for keys");

    // Simulating valid key indices initialization
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % INT_MAX;
    }

    return keys;
}

// Initialize records with random values, ensuring thread safety
record_t* initialize_records(size_t size) {
    record_t* records = (record_t*)malloc(size * sizeof(record_t));
    if (!records) handle_memory_error("Failed to allocate memory for records");

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    #define NUM_THREADS 4 // Example thread count
    #define CHUNK_SIZE (size / NUM_THREADS)

    void* init_chunk(void* arg) {
        int tid = *(int*)arg;
        pthread_mutex_lock(&mutex);

        for (long i = tid * CHUNK_SIZE; i < (tid + 1) * CHUNK_SIZE && i < size; ++i) {
            records[i].value = get_random_value();
        }

        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, init_chunk, &thread_ids[i])) {
            handle_memory_error("Failed to create threads");
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return records;
}

// Main function managing memory and dependencies
void* process_data_pipeline(size_t offsets_size, size_t keys_size, size_t records_size) {
    // Alignments
    const int ALIGN = sizeof(long);

    long* offsets = initialize_offsets(offsets_size, ALIGN);
    int* keys = initialize_keys(keys_size);
    record_t* records = initialize_records(records_size);

    printf("Offsets, Keys, and Records have been initialized.\n");

    return (void*)offsets;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t offsets_size = 1000; 
    size_t keys_size = 1000;
    size_t records_size = 1000;

    long* offsets = (long*)process_data_pipeline(offsets_size, keys_size, records_size);

    printf("Example offset: %ld\n", offsets[0]);

    free((void*)offsets);
    free((int*)initialize_keys(keys_size));
    free((record_t*)initialize_records(records_size));

    return 0;
}
