    // Memory allocation for keys and offsets
    int *keys = malloc(max_records * sizeof(int));
    long *offsets = malloc(max_records * sizeof(long));

    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation failed for keys or offsets.\n");
        free(records);
        if (keys) free(keys);
        if (offsets) free(offsets);
        return NULL;
