    // Assign pointers in records
    for (int i = 0; i < max_records; ++i) {
        records[i].key_ptr = &keys[i];
        records[i].offset_ptr = &offsets[i];
    }

    return records;
}

// Helper function to check if an array contains a value up to a given index
