#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_CHAR_LENGTH 100

typedef struct {
    int value;
    char *str;
} record;

unsigned long xorshift128(void) {
    static unsigned long s1 = 123456789, s2 = 362436069;
    unsigned long x = s1;
    unsigned long const y = s2;
    s1 = y;
    x ^= x << 23;
    s2 = x ^ y ^ (x >> 17) ^ (y >> 26);
    return s2 + y;
}

void *get_random_bytes(void *buf, size_t n) {
    for (size_t i = 0; i < n; ++i)
        ((unsigned char *)buf)[i] = xorshift128() & 0xFF;
    return buf;
}

int generate_unique_int(int min, int max, int *existing_values, int existing_count) {
    int value;
    do {
        value = (xorshift128() % (max - min + 1)) + min;
    } while (existing_count > 0 && bsearch(&value, existing_values, existing_count, sizeof(int), cmpfunc));
    return value;
}

int cmpfunc(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

char* generate_random_word(size_t max_length) {
    char *word = malloc(max_length + 1); // +1 for null terminator
    if (!word)
        return NULL;
    get_random_bytes(word, max_length);
    for (size_t i = 0; i < max_length; ++i) {
        if ((unsigned char)word[i] >= 128 || (unsigned char)word[i] <= 31) { // Ensure printable ASCII
            word[i] = 'a' + xorshift128() % 26;
        }
    }
    word[max_length] = '\0';
    return word;
}

record* initialize_arrays(size_t num_records, int key_min, int key_max, int record_val_min, int record_val_max) {
    if (num_records > MAX_OFFSETS || num_records > MAX_KEYS)
        return NULL;

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    char **strings_pool = malloc(num_records * MAX_CHAR_LENGTH);

    if (!offsets || !keys || !records || !strings_pool) {
        free(offsets);
        free(keys);
        free(records);
        free(strings_pool);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;

        int unique_key;
        do {
            pthread_mutex_lock(&lock);
            unique_key = generate_unique_int(key_min, key_max, keys, i);
            keys[i] = unique_key;
            pthread_mutex_unlock(&lock);
        } while (i > 0 && bsearch(&unique_key, keys, i, sizeof(int), cmpfunc));

        records[i].value = (xorshift128() % (record_val_max - record_val_min + 1)) + record_val_min;

        char *new_string;
        do {
            new_string = generate_random_word(MAX_CHAR_LENGTH);
        } while (i > 0 && bsearch(new_string, strings_pool, i * MAX_CHAR_LENGTH, sizeof(char), cmpfunc));

        if (!new_string) {
            free(offsets);
            free(keys);
            free(records);
            free(strings_pool);
            return NULL;
        }

        records[i].str = new_string;
    }

    free(strings_pool);

    pthread_mutex_destroy(&lock);

    return records;
}

void free_allocated_memory(record *records, size_t num_records) {
    if (records) {
        for (size_t i = 0; i < num_records; ++i)
            free(records[i].str);
        free(records);
    }
}
