#define CHECKSUM_FREQ 1000
#define DEFAULT_POOL_SIZE 1024

typedef struct {
    int integer;
    double float_value;
} item_t;

// Memory pool structure for thread-safe allocations
typedef struct {
    size_t block_size;
    size_t pool_size;
    void* memory_pool;
    pthread_mutex_t lock;
} mem_pool_t;

static inline unsigned long calculate_checksum(const void* data, size_t size) {
    const unsigned char* bytes = (const unsigned char*)data;
    unsigned long checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}

void initialize_memory_pool(mem_pool_t* pool, size_t block_size, size_t pool_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->pool_size = pool_size;
    pool->memory_pool = malloc(block_size * pool_size);
    if (!pool->memory_pool) {
        fprintf(stderr, "Memory allocation failed for memory pool.\n");
        exit(EXIT_FAILURE);
    }
}

void* thread_safe_malloc(mem_pool_t* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->block_size || !pool->memory_pool) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Requested allocation size exceeds block size or pool is exhausted.\n");
        return NULL;
    }

    void* ptr = pool->memory_pool;  // Simplified: Implement free list for reuse
    pool->memory_pool += pool->block_size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void manage_memory_and_data(size_t float_count, size_t string_count, size_t item_count) {
    mem_pool_t double_pool, string_pool, item_pool;

    initialize_memory_pool(&double_pool, sizeof(double), DEFAULT_POOL_SIZE);
    initialize_memory_pool(&string_pool, 256, DEFAULT_POOL_SIZE); // Assume max string length
    initialize_memory_pool(&item_pool, sizeof(item_t), DEFAULT_POOL_SIZE);

    size_t checksum_count = 0;

    double* doubles = (double*)thread_safe_malloc(&double_pool, float_count * sizeof(double));
    if (!doubles) return;

    char** strings = (char**)thread_safe_malloc(&string_pool, string_count * sizeof(char*));
    if (!strings) {
        free(doubles);
        return;
    }

    item_t* items = (item_t*)thread_safe_malloc(&item_pool, item_count * sizeof(item_t));
    if (!items) {
        for (size_t i = 0; i < string_count; ++i) {
            free(strings[i]);
        }
        free(doubles);
        return;
    }

    for (size_t i = 0; i < float_count; ++i) {
        doubles[i] = sin((double)i); // Example trigonometric function
    }

    for (size_t i = 0; i < string_count; ++i) {
        strings[i] = (char*)thread_safe_malloc(&string_pool, 256);
        if (!strings[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(strings[j]);
            }
            break;
        }
        snprintf(strings[i], 256, "String_%zu", i);
    }

    for (size_t i = 0; i < item_count; ++i) {
        items[i].integer = i + 1;
        items[i].float_value = cos((double)(items[i].integer));
    }

    while (checksum_count++ < CHECKSUM_FREQ) {
        unsigned long double_checksum = calculate_checksum(doubles, float_count * sizeof(double));
        unsigned long string_checksum = 0;
        for (size_t i = 0; i < string_count; ++i) {
            string_checksum += calculate_checksum(strings[i], strlen(strings[i]) + 1);
        }
        unsigned long item_checksum = calculate_checksum(items, item_count * sizeof(item_t));

        FILE* log_file = fopen("checksum_log.txt", "a");
        if (log_file) {
            fprintf(log_file, "Checksum %lu: D=%lu, S=%lu, I=%lu\n",
                    checksum_count, double_checksum, string_checksum, item_checksum);
            fclose(log_file);
        }
    }

    // Cleanup
    for (size_t i = 0; i < string_count; ++i) {
        free(strings[i]);
    }
    free(doubles);
    free(strings);
    free(items);

    pthread_mutex_destroy(&double_pool.lock);
    pthread_mutex_destroy(&string_pool.lock);
    pthread_mutex_destroy(&item_pool.lock);

    free(double_pool.memory_pool);
    free(string_pool.memory_pool);
    free(item_pool.memory_pool);
}

int main() {
