#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    pthread_mutex_t lock;
} data_t;

uint32_t xorshift32(uint32_t state) {
    state ^= state << 13;
    state ^= state >> 17;
    state ^= state << 5;
    return state;
}

data_t* initialize_data(size_t N, int minValue, int maxValue, uint32_t seed) {
    data_t *data = malloc(sizeof(data_t));
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for data structure\n");
        return NULL;
    }

    pthread_mutex_init(&data->lock, NULL);

    data->offsets = calloc(N, sizeof(long));
    if (!data->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets array\n");
        free(data);
        pthread_mutex_destroy(&data->lock);
        return NULL;
    }

    data->keys = calloc(N, sizeof(int));
    if (!data->keys) {
        fprintf(stderr, "Failed to allocate memory for keys array\n");
        free(data->offsets);
        free(data);
        pthread_mutex_destroy(&data->lock);
        return NULL;
    }

    record_t *records = malloc(N * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records array\n");
        free(data->keys);
        free(data->offsets);
        free(data);
        pthread_mutex_destroy(&data->lock);
        return NULL;
    }

    // Populate offsets and keys
    for (size_t i = 0; i < N; ++i) {
        data->offsets[i] = (long)i;
        data->keys[i] = (int)i;
    }

    uint32_t rng_state = seed;

    int range = maxValue - minValue + 1;
    if (range <= 0) {
        fprintf(stderr, "Invalid range: minValue should be less than or equal to maxValue\n");
        free(records);
        free(data->keys);
        free(data->offsets);
        free(data);
        pthread_mutex_destroy(&data->lock);
        return NULL;
    }

    // Populate records with unique random numbers
    for (size_t i = 0; i < N; ++i) {
        int num;
        do {
            rng_state = xorshift32(rng_state);
            num = minValue + (rng_state % range);
        } while (!contains(records, num, i));

        records[i].value = num;
    }

    data->records = records;
    data->size = N;

    return data;
}

int contains(record_t *records, int value, size_t upto) {
    for (size_t i = 0; i < upto; ++i) {
        if (records[i].value == value)
            return 1;
    }
    return 0;
}

void free_data(data_t *data) {
    if (!data) return;

    pthread_mutex_lock(&data->lock);
    if (data->offsets) free(data->offsets);
    if (data->keys) free(data->keys);
    if (data->records) free(data->records);

    pthread_mutex_unlock(&data->lock);
    pthread_mutex_destroy(&data->lock);
    free(data);
}

void log_resource_usage(const char *message, size_t N, double exec_time) {
    printf("%s: N=%zu, Execution Time=%.6f seconds\n", message, N, exec_time);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <N> <minValue> <maxValue>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t N = strtoull(argv[1], NULL, 10);
    int minValue = atoi(argv[2]);
    int maxValue = atoi(argv[3]);

    if (N == 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid input values\n");
        return EXIT_FAILURE;
    }

    uint32_t seed = 12345; // For reproducibility

    data_t *data = initialize_data(N, minValue, maxValue, seed);
    if (!data) {
        return EXIT_FAILURE;
    }

    double start_time = (double)clock() / CLOCKS_PER_SEC;

    // Simulate work
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&data->lock);
        // Access or modify data as needed
        pthread_mutex_unlock(&data->lock);
    }

    double end_time = (double)clock() / CLOCKS_PER_SEC;
    log_resource_usage("Data Processing", N, end_time - start_time);

    free_data(data);

    return EXIT_SUCCESS;
}
