        records[i].id = rand() % 10000 + 1; // Assign random ID
        records[i].timestamp = time(NULL);
        records[i].offsets = malloc(max_offsets * sizeof(long));

        if (!records[i].offsets) {
            perror("Failed to allocate memory for offsets");
            pthread_mutex_lock(&lock);
            for (int j = 0; j < i; ++j) free(records[j].offsets);
            free(records);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    pthread_mutex_destroy(&lock);
    return records;
}

// Function to manage memory cleanup
void freeRecords(Record *records, int num_records) {
    if (!records) return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i].offsets);
    }
    free(records);
}

// Helper function to handle PUT request with retries
int putResource(const char* url, const char* jsonBody) {
    CURL *curl;
    CURLcode res;
    int attempts = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if (curl) {
        while (attempts < MAX_RETRIES) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, jsonBody);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK)
                break;

            attempts++;
            printf("PUT request failed. Retrying... (%d/%d)\n", attempts + 1, MAX_RETRIES);
        }
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return res == CURLE_OK;
}

// Helper function to handle DELETE request with retries
int deleteResource(const char* url) {
    CURL *curl;
    CURLcode res;
    int attempts = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if (curl) {
        while (attempts < MAX_RETRY_DELETE) {
            curl_easy_setopt(curl, CURLOPT_URL, url);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK)
                break;

            attempts++;
            printf("DELETE request failed. Retrying... (%d/%d)\n", attempts + 1, MAX_RETRY_DELETE);
        }
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return res == CURLE_OK;
}

