        const char *delete_url = "http://example.com/api/resource/1";
        if (deleteResource(delete_url)) {
            printf("DELETE resource successful.\n");
        } else {
            printf("DELETE resource failed.\n");
        }

        freeRecords(records, num_records);
    }

    const char* js_files[] = {"file1.js", "file2.js", "file3.js"};
