['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int id;
    size_t file_size;
    time_t last_modified;
    time_t* access_times;
    int access_count;
    char* content_hash;
} MetadataEntry;

typedef struct {
    pthread_mutex_t lock;
    MetadataEntry** entries;
    uint32_t capacity;
    uint32_t count;
    int free_ids[];
} Cache;

static inline uint32_t hash(uint32_t key, size_t cap) {
    return (key * 2654435761u) % cap;
}

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = malloc(sizeof(Cache) + sizeof(int) * initial_capacity);
    if (!cache) return NULL;

    pthread_mutex_init(&cache->lock, NULL);
    cache->capacity = initial_capacity;
    cache->count = 0;
    cache->entries = calloc(initial_capacity, sizeof(MetadataEntry*));

    for (uint32_t i = 0; i < initial_capacity; ++i) {
        cache->free_ids[i] = i;
    }

    return cache;
}

void resize_cache(Cache* cache, size_t new_capacity) {
    pthread_mutex_lock(&cache->lock);
    MetadataEntry** new_entries = realloc(cache->entries, new_capacity * sizeof(MetadataEntry*));
    if (!new_entries) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    uint32_t old_cap = cache->capacity;
    for (uint32_t i = old_cap; i < new_capacity; ++i) {
        cache->free_ids[i] = i;
    }

    cache->entries = new_entries;
    cache->capacity = new_capacity;
    pthread_mutex_unlock(&cache->lock);
}

MetadataEntry* get_metadata_entry(Cache* cache, uint32_t id) {
    if (id >= cache->capacity) return NULL;

    pthread_mutex_lock(&cache->lock);
    MetadataEntry* entry = cache->entries[id];
    pthread_mutex_unlock(&cache->lock);

    return entry;
}

int add_metadata_entry(Cache* cache, size_t file_size, const char* content_hash) {
    uint32_t id;

    pthread_mutex_lock(&cache->lock);
    if (cache->count == cache->capacity) {
        resize_cache(cache, cache->capacity * 2);
        if (cache->count == cache->capacity)
            return -1; // Still full after resizing
    }

    id = cache->free_ids[--(cache->count)];
    MetadataEntry* entry = malloc(sizeof(MetadataEntry));

    entry->id = id;
    entry->file_size = file_size;
    entry->last_modified = time(NULL);
    entry->access_count = 0;
    entry->content_hash = strdup(content_hash);

    cache->entries[id] = entry;
    pthread_mutex_unlock(&cache->lock);

    return id;
}

void free_cache(Cache* cache) {
    pthread_mutex_lock(&cache->lock);

    for (uint32_t i = 0; i < cache->capacity; ++i) {
        MetadataEntry* entry = cache->entries[i];
        if (entry) {
            free(entry->access_times);
            free(entry->content_hash);
            free(entry);
        }
    }

    free(cache->entries);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void initialize_data_structures() {
    size_t long_array_size = 1000;
    size_t int_keys_size = 500;

    long* long_offsets = calloc(long_array_size, sizeof(long));
    int* int_keys = malloc(int_keys_size * sizeof(int));

    typedef struct { int value; } record;
    record* records = malloc(300 * sizeof(record));

    srand(time(NULL));

    for (size_t i = 0; i < long_array_size; ++i) {
        long_offsets[i] = rand() % 1000000L;
    }

    for (size_t i = 0; i < int_keys_size; ++i) {
        int_keys[i] = rand() % 10000;
    }

    for (size_t i = 0; i < 300; ++i) {
        records[i].value = rand() % 500;
    }

    // Cleanup
    free(long_offsets);
    free(int_keys);
    free(records);
}

int main() {
    Cache* cache = create_cache(10000);
    if (!cache) return -1;

    int id = add_metadata_entry(cache, 1024, "d41d8cd98f00b204e9800998ecf8427e");
    if (id == -1) {
        printf("Failed to add metadata entry.\n");
        free_cache(cache);
        return -1;
    }

    MetadataEntry* entry = get_metadata_entry(cache, id);
    if (entry) {
        printf("Retrieved entry ID: %d\n", entry->id);
    } else {
        printf("Metadata entry not found.\n");
    }

    initialize_data_structures();
    free_cache(cache);

    return 0;
}
```

