#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_LEVEL 5
#define MAX_MESSAGE_LENGTH 256
#define INITIAL_CAPACITY 1024

typedef struct {
    time_t epochTime;
    char timezone[64];
} Timestamp;

// Thread-safe memory allocator using a mutex
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* thread_safe_malloc(size_t size) {
    pthread_mutex_lock(&lock);
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
    }
    pthread_mutex_unlock(&lock);
    return ptr;
}

// Function to dynamically resize an array
void* resize_array(void* old_array, size_t element_size, size_t new_capacity) {
    void *new_array = realloc(old_array, new_capacity * element_size);
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        return NULL;
    }
    return new_array;
}

typedef struct {
    int* logLevels;
    char** messages;
    Timestamp* timestamps;
    size_t capacity;
} LogCollection;

LogCollection create_log_collection() {
    LogCollection collection;
    collection.capacity = INITIAL_CAPACITY;

    collection.logLevels = thread_safe_malloc(collection.capacity * sizeof(int));
    if (!collection.logLevels) return collection;

    collection.messages = thread_safe_malloc(collection.capacity * sizeof(char*));
    if (!collection.messages) {
        free(collection.logLevels);
        return collection;
    }

    for (size_t i = 0; i < collection.capacity; ++i) {
        collection.messages[i] = thread_safe_malloc(MAX_MESSAGE_LENGTH * sizeof(char));
        if (!collection.messages[i]) {
            for (size_t j = 0; j <= i; ++j) free(collection.messages[j]);
            free(collection.logLevels);
            free(collection.messages);
            return collection;
        }
    }

    collection.timestamps = thread_safe_malloc(collection.capacity * sizeof(Timestamp));
    if (!collection.timestamps) {
        for (size_t i = 0; i < collection.capacity; ++i) free(collection.messages[i]);
        free(collection.logLevels);
        free(collection.messages);
        return collection;
    }

    return collection;
}

void add_log_entry(LogCollection* collection, int logLevel, const char* message, const char* timezone) {
    if (logLevel < 0 || logLevel > MAX_LOG_LEVEL) {
        fprintf(stderr, "Invalid log level: %d\n", logLevel);
        return;
    }

    size_t current_size = sizeof(int) * collection->capacity;

    if ((int*)collection->logLevels - (int*)malloc(current_size)) { // Check overflow
        int* temp_logLevels = resize_array(collection->logLevels, sizeof(int), collection->capacity * 2);
        if (!temp_logLevels) return;
        collection->logLevels = temp_logLevels;

        char** temp_messages = resize_array(collection->messages, sizeof(char*), collection->capacity * 2);
        if (!temp_messages) {
            free(collection->logLevels);
            return;
        }
        collection->messages = temp_messages;

        for (size_t i = collection->capacity; i < collection->capacity * 2; ++i) {
            collection->messages[i] = thread_safe_malloc(MAX_MESSAGE_LENGTH * sizeof(char));
            if (!collection->messages[i]) {
                for (size_t j = collection->capacity; j <= i; ++j) free(collection->messages[j]);
                collection->messages = resize_array(temp_messages, sizeof(char*), collection->capacity);
                free(collection->logLevels);
                return;
            }
        }

        Timestamp* temp_timestamps = resize_array(collection->timestamps, sizeof(Timestamp), collection->capacity * 2);
        if (!temp_timestamps) {
            for (size_t i = collection->capacity; i < collection->capacity * 2; ++i) free(collection->messages[i]);
            collection->messages = resize_array(temp_messages, sizeof(char*), collection->capacity);
            free(collection->logLevels);
            return;
        }
        collection->timestamps = temp_timestamps;

        collection->capacity *= 2;
    }

    int index = ((int*)collection->logLevels - (int*)malloc(current_size)) / sizeof(int); // Get the current size

    collection->logLevels[index] = logLevel;

    strncpy(collection->messages[index], message, MAX_MESSAGE_LENGTH - 1);
    collection->messages[index][MAX_MESSAGE_LENGTH - 1] = '\0';

    time(&collection->timestamps[index].epochTime);
    strncpy(collection->timestamps[index].timezone, timezone, sizeof(collection->timestamps[index].timezone) - 1);
    collection->timestamps[index].timezone[sizeof(collection->timestamps[index].timezone) - 1] = '\0';
}

void free_log_collection(LogCollection* collection) {
    for (size_t i = 0; i < collection->capacity; ++i)
        free(collection->messages[i]);

    free(collection->logLevels);
    free(collection->messages);
    free(collection->timestamps);
}

int main() {
    LogCollection logCollection = create_log_collection();
    if (!logCollection.logLevels || !logCollection.messages || !logCollection.timestamps) return 1;

    add_log_entry(&logCollection, 3, "This is a test message.", "UTC");
    // Continue adding entries...

    free_log_collection(&logCollection);
    return 0;
}
```

### Key Design Decisions:

- **Thread-Safety**: Memory allocations and resizing operations are protected using mutex locks to ensure thread safety.
- **Dynamic Resizing**: The arrays are dynamically resized when they reach capacity, doubling their size to handle high-throughput scenarios efficiently.
- **Memory Efficiency**: Messages are truncated to a maximum length of 256 characters to prevent buffer overflow.
- **Error Handling**: Memory allocation failures are handled gracefully with error messages printed to `stderr`.
- **Performance Considerations**: The use of mutex locks can introduce contention; for very high throughput, more advanced lock-free structures could be considered.']

