#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <stdatomic.h>

#define CACHE_SIZE 128

typedef struct {
    long value;
} record_t;

// Offset Array and associated metadata
typedef struct {
    long *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} offset_array_t;

// Key Cache for dependency management
typedef struct {
    int *keys;
    size_t size;
    time_t last_updated;
} key_cache_t;

// Record Array with thread-safe access
typedef struct {
    record_t *data;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;  // Read-write lock for concurrent access
    atomic_uint_least64_t cache[2][CACHE_SIZE];
    unsigned int current_cache_index;
} record_array_t;

// Initialize offset array with specified initial capacity
offset_array_t* init_offset_array(size_t capacity) {
    offset_array_t *offsets = malloc(sizeof(offset_array_t));
    offsets->data = aligned_alloc(8, sizeof(long) * capacity);
    offsets->capacity = capacity;
    offsets->count = 0;
    pthread_mutex_init(&offsets->lock, NULL);

    return offsets;
}

// Resize the offset array with minimum reallocations
void resize_offset_array(offset_array_t *offsets, size_t new_capacity) {
    if (new_capacity <= offsets->capacity)
        return;

    long *new_data = aligned_alloc(8, sizeof(long) * new_capacity);
    memcpy(new_data, offsets->data, sizeof(long) * offsets->count);

    free(offsets->data);
    offsets->data = new_data;
    offsets->capacity = new_capacity;
}

// Add an offset with overflow and bounds checking
int add_offset(offset_array_t *offsets, long offset) {
    pthread_mutex_lock(&offsets->lock);

    if (offsets->count == offsets->capacity)
        resize_offset_array(offsets, 2 * offsets->capacity);

    offsets->data[offsets->count++] = offset;

    pthread_mutex_unlock(&offsets->lock);
    return 0; // Success
}

// Initialize key cache with default values and size
key_cache_t* init_key_cache(size_t size) {
    key_cache_t *cache = malloc(sizeof(key_cache_t));
    cache->keys = malloc(sizeof(int) * size);
    memset(cache->keys, -1, sizeof(int) * size);  // Use -1 to indicate invalid keys
    cache->size = size;
    time(&cache->last_updated);

    return cache;
}

// Update the key cache when offsets change, with periodic recomputation
void update_key_cache(key_cache_t *cache, const offset_array_t *offsets) {
    time_t current_time;
    time(&current_time);
    if (difftime(current_time, cache->last_updated) < 5) // 5 seconds threshold for re-computation
        return;

    pthread_mutex_lock((pthread_mutex_t*)&cache->keys);

    for (size_t i = 0; i < cache->size; ++i)
        cache->keys[i] = i % offsets->count;  // Example logic to keep keys valid

    time(&cache->last_updated);

    pthread_mutex_unlock((pthread_mutex_t*)&cache->keys);
}

// Initialize record array with specified capacity
record_array_t* init_record_array(size_t capacity) {
    record_array_t *records = malloc(sizeof(record_array_t));
    records->data = malloc(sizeof(record_t) * capacity);
    for (size_t i = 0; i < capacity; ++i)
        records->data[i].value = rand() % 1001;

    records->capacity = capacity;
    records->count = capacity;
    pthread_rwlock_init(&records->rwlock, NULL);
    records->current_cache_index = 0;

    return records;
}

// Thread-safe access to record
long read_record(record_array_t *records, size_t index) {
    if (index >= records->count)
        return -1; // Return default value for out-of-bounds

    pthread_rwlock_rdlock(&records->rwlock);

    long result = records->data[index].value;
    unsigned int cache_index = records->current_cache_index;
    atomic_store_explicit(&records->cache[cache_index][index % CACHE_SIZE], 
                         (atomic_uint_least64_t)result, memory_order_relaxed);

    pthread_rwlock_unlock(&records->rwlock);
    return result;
}

// Thread-safe update to record
void write_record(record_array_t *records, size_t index, long value) {
    if (index >= records->count)
        return; // Ignore out-of-bounds writes

    pthread_rwlock_wrlock(&records->rwlock);

    records->data[index].value = value;
    unsigned int cache_index = records->current_cache_index;
    atomic_store_explicit(&records->cache[cache_index][index % CACHE_SIZE], 
                         (atomic_uint_least64_t)value, memory_order_relaxed);

    pthread_rwlock_unlock(&records->rwlock);
}

// Speculative execution management and dependency resolution
void speculative_execution(offset_array_t *offsets, record_array_t *records) {
    // Example speculative task, to be customized based on application logic
    for (size_t i = 0; i < offsets->count; ++i) {
        long offset_value = offsets->data[i];

        if (offset_value >= 0 && offset_value < records->count)
            records->data[offset_value].value += 1;
    }
}

// Cleanup and free resources
void cleanup_offset_array(offset_array_t *offsets) {
    pthread_mutex_destroy(&offsets->lock);
    free(offsets->data);
    free(offsets);
}

void cleanup_key_cache(key_cache_t *cache) {
    free(cache->keys);
    free(cache);
}

void cleanup_record_array(record_array_t *records) {
    pthread_rwlock_destroy(&records->rwlock);
    free(records->data);
    free(records);
}

// Main function to demonstrate usage
int main() {
    offset_array_t *offsets = init_offset_array(10);
    key_cache_t *key_cache = init_key_cache(20);
    record_array_t *records = init_record_array(100);

    // Example operations
    add_offset(offsets, 5);
    add_offset(offsets, 10);

    update_key_cache(key_cache, offsets);

    speculative_execution(offsets, records);

    printf("Record value: %ld\n", read_record(records, 5));

    cleanup_offset_array(offsets);
    cleanup_key_cache(key_cache);
    cleanup_record_array(records);

    return 0;
}
