        free(persistentRecords);
        persistentRecords = NULL;
        persistentCount = 0;
    }
}

int generateUniqueRandom(int min, int max, int exclude[], size_t excludeSize) {
    static int lastValue = -1;
    int value;
    do {
        value = rand() % (max - min + 1) + min;
    } while ((lastValue == value) || 
             (excludeSize > 0 && bsearch(&value, exclude, excludeSize, sizeof(int), memcmp)));

    lastValue = value;
    return value;
}

void resetPersistenceState() {
    freePersistentRecords();
}

Record* createRecords(size_t numRecords, int resetPersistence) {
    if (resetPersistence) {
        resetPersistenceState();
    }

    int keyRangeStart, keyRangeEnd, valueRangeStart, valueRangeEnd;
    if (!loadConfig(&keyRangeStart, &keyRangeEnd, &valueRangeStart, &valueRangeEnd)) {
        return NULL;
    }

    size_t totalRecords = persistentCount + numRecords;
    if (totalRecords > MAX_RECORDS) {
        logEvent("Exceeded maximum number of records.");
        return NULL;
    }

    Record *newRecords = realloc(persistentRecords, totalRecords * sizeof(Record));
    if (!newRecords) {
        logEvent("Memory allocation failed.");
        return NULL;
    }
    persistentRecords = newRecords;

    int keys[MAX_KEYS];
    size_t usedKeys = 0;

    for (size_t i = persistentCount; i < totalRecords; ++i) {
        Record *record = &persistentRecords[i];

        record->offset = i;
        record->key = generateUniqueRandom(keyRangeStart, keyRangeEnd, keys, usedKeys);
        if (usedKeys < MAX_KEYS) {
            keys[usedKeys++] = record->key;
        }

        record->record.value = rand() % (valueRangeEnd - valueRangeStart + 1) + valueRangeStart;

        size_t stringLength = rand() % (MAX_STRING_LENGTH + 1);
        for (size_t j = 0; j < stringLength; ++j) {
            record->record.string[j] = 'a' + (rand() % 26);
        }
        record->record.string[stringLength] = '\0';

        record->status = (stringLength > 0) ? 1 : 0;

        logEvent("Record created.");
    }

    persistentCount = totalRecords;
    return persistentRecords;
}

void freeAllMemory() {
    freePersistentRecords();
}
