['Below is a C implementation of the specified requirements. The code includes necessary components like dynamic memory allocation, thread-safety using mutexes, and efficient data structures such as hash sets for unique value management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_STRING_LENGTH 100
#define HASH_TABLE_SIZE 1024

typedef struct {
    int value;
    char *word;
} Record;

typedef struct {
    uint64_t offset;
    uint32_t key;
    Record record;
} DataPoint;

typedef struct HashSetNode {
    uint32_t value;
    struct HashSetNode* next;
} HashSetNode;

typedef struct {
    HashSetNode* table[HASH_TABLE_SIZE];
    pthread_mutex_t mutex;
} HashSet;

uint32_t hash_function(uint32_t x) {
    return x % HASH_TABLE_SIZE;
}

int insert_hash_set(HashSet *set, uint32_t value) {
    uint32_t index = hash_function(value);
    HashSetNode* node = set->table[index];

    while (node != NULL) {
        if (node->value == value) return 0; // Duplicate found
        node = node->next;
    }

    pthread_mutex_lock(&set->mutex);

    node = malloc(sizeof(HashSetNode));
    if (!node) return -1; // Allocation failed

    node->value = value;
    node->next = set->table[index];
    set->table[index] = node;

    pthread_mutex_unlock(&set->mutex);
    return 1;
}

int is_in_hash_set(HashSet *set, uint32_t value) {
    uint32_t index = hash_function(value);

    HashSetNode* node = set->table[index];

    while (node != NULL) {
        if (node->value == value) return 1; // Found
        node = node->next;
    }

    return 0;
}

void free_hash_set(HashSet *set) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashSetNode* node = set->table[i];
        while (node != NULL) {
            HashSetNode* tmp = node;
            node = node->next;
            free(tmp);
        }
    }
}

void cleanup_data_points(DataPoint *dataPoints, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (dataPoints[i].record.word != NULL)
            free(dataPoints[i].record.word);
    }
    free(dataPoints);
}

DataPoint* initialize_dataset(size_t count, uint32_t key_range_start, uint32_t key_range_end,
                              int record_value_min, int record_value_max, 
                              const char **prohibited_words, size_t prohibited_count) {
    if (count == 0 || key_range_start >= key_range_end)
        return NULL;

    DataPoint *dataPoints = malloc(sizeof(DataPoint) * count);
    if (!dataPoints) return NULL;

    HashSet keySet;
    memset(&keySet, 0, sizeof(HashSet));
    pthread_mutex_init(&keySet.mutex, NULL);

    uint64_t atomic_offset = 0;
    static pthread_mutex_t offset_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Function to generate a unique random string
    char* generate_unique_random_string(HashSet *stringSet) {
        const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
        size_t length = rand() % MAX_STRING_LENGTH + 1;
        char *word = malloc(length + 1);
        if (!word) return NULL;

        for (size_t i = 0; i < length; ++i) {
            word[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        word[length] = '\0';

        uint32_t hashValue = *(uint32_t*)word;
        if (!insert_hash_set(stringSet, hashValue))
            free(word);

        // Check against prohibited words
        for (size_t j = 0; j < prohibited_count; ++j) {
            if (strcmp(prohibited_words[j], word) == 0) {
                free(word);
                return generate_unique_random_string(stringSet); // Retry
            }
        }

        return word;
    }

    HashSet stringSet;
    memset(&stringSet, 0, sizeof(HashSet));
    pthread_mutex_init(&stringSet.mutex, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&offset_mutex);
        dataPoints[i].offset = atomic_offset++;
        pthread_mutex_unlock(&offset_mutex);

        uint32_t key;
        do {
            key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        } while (!insert_hash_set(&keySet, key));

        dataPoints[i].key = key;

        dataPoints[i].record.value = rand() % (record_value_max - record_value_min + 1) + record_value_min;
        char *word = generate_unique_random_string(&stringSet);
        if (!word) {
            cleanup_data_points(dataPoints, i);
            free_hash_set(&keySet);
            free_hash_set(&stringSet);
            pthread_mutex_destroy(&offset_mutex);
            return NULL;
        }
        dataPoints[i].record.word = word;
    }

    // Cleanup hash sets and mutexes
    free_hash_set(&keySet);
    free_hash_set(&stringSet);
    pthread_mutex_destroy(&offset_mutex);

    return dataPoints;
}

// Example usage of the function:
/*
int main() {
    const char *prohibited_words[] = {"badword", "inappropriate"};
    size_t prohibited_count = sizeof(prohibited_words) / sizeof(prohibited_words[0]);

    DataPoint* dataset = initialize_dataset(100, 1, 1000, -50, 50, prohibited_words, prohibited_count);

    if (!dataset) {
        printf("Failed to initialize the dataset.\n");
        return EXIT_FAILURE;
    }

    // Use the dataset...

    cleanup_data_points(dataset, 100);
    return EXIT_SUCCESS;
}
*/
