void initialize_memory(int num_offsets, int key_start, int key_end) {
    pthread_mutex_lock(&memory_lock);

    size_t offset_size = sizeof(Offset) * num_offsets;
    offsets = (Offset*)allocate_from_pool(offset_size);

    size_t key_size = sizeof(Key) * num_offsets;
    keys = (Key*)allocate_from_pool(key_size);

    if (!offsets || !keys) {
        log_change("Memory allocation failed", 0);
        pthread_mutex_unlock(&memory_lock);
        exit(EXIT_FAILURE);
    }

    int cumulative_sum = 0;
    for (int i = 0; i < num_offsets; ++i) {
        keys[i].value = key_start + (rand() % (key_end - key_start + 1));
        offsets[i].value = cumulative_sum += keys[i].value;
    }

    Record* current_record = NULL;
    for (int i = 0; i < num_offsets; ++i) {
        Record* new_record = (Record*)allocate_from_pool(sizeof(Record));
        if (!new_record) {
            log_change("Memory allocation failed", 0);
            pthread_mutex_unlock(&memory_lock);
            exit(EXIT_FAILURE);
        }

        new_record->s_value = random_int(1, 100);
        new_record->i_value = random_int(1000, 2000);
        new_record->f_value = (float)rand() / RAND_MAX * 10.0;

        if (!record_head) {
            record_head = new_record;
            current_record = new_record;
        } else {
            current_record->next = new_record;
            current_record = new_record;
        }
    }

    pthread_mutex_unlock(&memory_lock);
}

void free_memory() {
    pthread_mutex_lock(&memory_lock);

    if (offsets) deallocate_to_pool(offsets);
    if (keys) deallocate_to_pool(keys);

    Record* record = record_head;
    while (record) {
        Record* temp = record;
        record = record->next;
        deallocate_to_pool(temp);
    }

    pthread_mutex_unlock(&memory_lock);
}

