#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    long value;
} Offset;

typedef struct {
    short integer;
} Key;

typedef struct {
    long offset_ptr;
    short key;
    int value;
} Record;

void* secure_random(void *arg) {
    unsigned int seed = (unsigned int)(uintptr_t)arg;
    srand48_r(seed, (long int*)seed);
    return malloc(sizeof(int));
}

int random_int(int min, int max, void **random_context) {
    if (!random_context) return -1;

    int *buffer = (int *)secure_random(random_context);
    if (!buffer) return -1;

    lrand48_r((long int*)random_context, buffer);
    return (*buffer = min + ((*buffer % (max - min + 1))));
}

void free_resources(Offset **offsets, Key **keys, Record **records,
                    size_t offset_count, size_t key_count) {
    if (offsets) free(*offsets);
    if (keys) free(*keys);
    if (records) free(*records);
}

int allocate_and_initialize(size_t record_count, long seed_value) {
    Offset *offsets = NULL;
    Key *keys = NULL;
    Record *records = NULL;

    // Allocate memory for arrays
    offsets = malloc(record_count * sizeof(Offset));
    keys = malloc(record_count * sizeof(Key));
    records = malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        free_resources(&offsets, &keys, &records, record_count, record_count);
        return -1;
    }

    void *random_context = NULL;

    // Initialize offsets and keys with predefined values
    for (size_t i = 0; i < record_count; ++i) {
        offsets[i].value = (long)i;
        keys[i].integer = (short)i;

        int value = random_int(10, 100, &random_context);
        if (value == -1) {
            free_resources(&offsets, &keys, &records, record_count, record_count);
            return -1;
        }

        records[i].offset_ptr = (long)&offsets[i];
        records[i].key = keys[i].integer;
        records[i].value = value;
    }

    // Clean up resources
    free(random_context);

    // Output for debugging purposes
    printf("Allocation and initialization successful.\n");

    // Free allocated memory before exiting
    free_resources(&offsets, &keys, &records, record_count, record_count);
    return 0;
}

int main() {
    size_t record_count = 10000; // Example count
    long seed_value = time(NULL);

    if (allocate_and_initialize(record_count, seed_value) != 0) {
        fprintf(stderr, "Failed to allocate and initialize records.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

