    void *metadata;
} Record;

typedef struct Node {
    int key;
    long offset;
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
void initLinkedList(LinkedList* list);
Node* createNode(int key, const Record* record, long offset);
void appendNode(LinkedList* list, int key, const Record* record, long offset);
Record generateRandomRecord();
int* uniqueIntegersInRange(int size, int min, int max);
long calculateOffset(int* keys, int index, int constant);
void resizeLinkedList(LinkedList* list, int newSize);
void serializeToJson(const LinkedList* list, FILE* file);
void serializeToBinary(const LinkedList* list, FILE* file);
void logChangeAsync(const char* message);

// Global constants
#define OFFSET_CONSTANT 100

// Initialize the linked list with a mutex lock
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Create a new node with given key, record and offset
Node* createNode(int key, const Record* record, long offset) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->key = key;
    memcpy(&newNode->record, record, sizeof(Record));
    newNode->offset = offset;
    newNode->next = NULL;
    return newNode;
}

// Append a node to the linked list
void appendNode(LinkedList* list, int key, const Record* record, long offset) {
    Node* newNode = createNode(key, record, offset);
    if (!newNode) return;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

// Generate a random record with fields within specified ranges
Record generateRandomRecord() {
    Record rec;
    rec.s = rand() % 1000; // Example range for short
    rec.i = rand() % 100000; // Example range for int
    rec.f = (float)(rand() / (RAND_MAX + 1.0)) * 100.0; // Example range for float
    rec.d = drand48() * 10000.0; // Example range for double
    rec.metadata = NULL; // Placeholder for metadata
    return rec;
}

// Generate unique integers in a specified range
int* uniqueIntegersInRange(int size, int min, int max) {
    int* result = malloc(size * sizeof(int));
    if (!result) return NULL;

    int rangeSize = max - min + 1;
    if (rangeSize < size) {
        free(result);
        return NULL; // Not enough unique numbers
    }

    for (int i = 0; i < size; ++i) {
        result[i] = rand() % rangeSize + min;
    }

    // Ensure uniqueness
    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            while (result[j] == result[i]) {
                result[j] = rand() % rangeSize + min;
            }
        }
    }

    return result;
}

// Calculate offset as the sum of all previous keys plus a constant
long calculateOffset(int* keys, int index, int constant) {
    long total = 0;
    for (int i = 0; i < index; ++i) {
        total += keys[i];
    }
    return total + constant;
}

// Resize the linked list to handle more nodes if needed
void resizeLinkedList(LinkedList* list, int newSize) {
    // Example resizing logic, this is a placeholder for dynamic resizing mechanism
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL && newSize > 0) {
        current = current->next;
        --newSize;
    }
    if (newSize <= 0) {
        // Perform necessary resizing actions here
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize the linked list to JSON format
void serializeToJson(const LinkedList* list, FILE* file) {
    fprintf(file, "[\n");
    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "  { \"key\": %d, \"offset\": %ld, \"record\": { \"s\": %hd, \"i\": %d, \"f\": %.2f, \"d\": %.2f }}",
                current->key, current->offset,
                current->record.s, current->record.i,
                current->record.f, current->record.d);
        if (current->next != NULL) {
            fprintf(file, ",\n");
        }
        current = current->next;
    }
    fprintf(file, "\n]");
}

// Serialize the linked list to binary format
void serializeToBinary(const LinkedList* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->offset, sizeof(long), 1, file);
        fwrite(&current->record, sizeof(Record), 1, file);
        current = current->next;
    }
}

// Log changes asynchronously to minimize performance impact
void logChangeAsync(const char* message) {
    // Placeholder for asynchronous logging implementation
    printf("Log: %s\n", message); // Example synchronous logging
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    int size = 10; // Example size
    int minKey = 1, maxKey = 100;

    int* keys = uniqueIntegersInRange(size, minKey, maxKey);
    if (!keys) {
        fprintf(stderr, "Failed to generate unique integers\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < size; ++i) {
        Record record = generateRandomRecord();
        long offset = calculateOffset(keys, i, OFFSET_CONSTANT);
        appendNode(&list, keys[i], &record, offset);
        char logMessage[256];
        snprintf(logMessage, sizeof(logMessage), "Added node with key: %d", keys[i]);
        logChangeAsync(logMessage);
    }

    // Example serialization
    FILE* jsonFile = fopen("data.json", "w");
    serializeToJson(&list, jsonFile);
    fclose(jsonFile);

    FILE* binaryFile = fopen("data.bin", "wb");
    serializeToBinary(&list, binaryFile);
    fclose(binaryFile);

    free(keys);
    // Cleanup and deallocation logic should be added here

    return EXIT_SUCCESS;
}
