['Below is a C implementation that addresses the specified tasks. This code includes memory allocation, error handling, threading, logging, and basic database interaction using SQLite for persistent storage.

```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <sqlite3.h>
#include <time.h>

#define LOG_LEVEL 1 // 0 = No logs, 1 = Basic logs, 2 = Detailed logs

typedef struct {
    int value;
} record;

void log_message(int level, const char *message) {
    if (LOG_LEVEL >= level) {
        printf("%s\n", message);
    }
}

int validate_inputs(int N, int minValue, int maxValue) {
    if (N <= 0 || minValue > maxValue) {
        log_message(1, "Invalid input parameters.");
        return 0;
    }
    return 1;
}

void free_resources(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int populate_unique_records(record *records, int N, int minValue, int maxValue) {
    int i, j;
    for (i = 0; i < N; ++i) {
        do {
            records[i].value = random_int(minValue, maxValue);
            for (j = 0; j < i; ++j) {
                if (records[j].value == records[i].value) {
                    break;
                }
            }
        } while (j != i); // Ensure no duplicates
    }
    return 1;
}

int initialize_data(int N, int minValue, int maxValue, long **offsets, int **keys, record **records) {
    *offsets = malloc(N * sizeof(long));
    if (*offsets == NULL) {
        log_message(1, "Failed to allocate memory for offsets.");
        return 0;
    }

    *keys = malloc(N * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        log_message(1, "Failed to allocate memory for keys.");
        return 0;
    }

    *records = malloc(N * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        log_message(1, "Failed to allocate memory for records.");
        return 0;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
        (*offsets)[i] = i;
        (*keys)[i] = i;
        pthread_mutex_unlock(&lock);
    }

    if (!populate_unique_records(*records, N, minValue, maxValue)) {
        log_message(1, "Failed to populate records uniquely.");
        return 0;
    }

    pthread_mutex_destroy(&lock);
    return 1;
}

int store_in_db(const char *db_path, record *records, int N) {
    sqlite3 *db;
    char *err_msg = NULL;
    int rc = sqlite3_open(db_path, &db);

    if (rc != SQLITE_OK) {
        log_message(1, "Cannot open database.");
        return 0;
    }

    char *sql = "CREATE TABLE IF NOT EXISTS Records(id INTEGER PRIMARY KEY, value INTEGER);";
    rc = sqlite3_exec(db, sql, NULL, 0, &err_msg);

    if (rc != SQLITE_OK) {
        log_message(1, sqlite3_errmsg(db));
        sqlite3_free(err_msg);
        sqlite3_close(db);
        return 0;
    }

    for (int i = 0; i < N; ++i) {
        char *sql_insert = sqlite3_mprintf("INSERT INTO Records(id, value) VALUES(%d, %d);", i, records[i].value);
        rc = sqlite3_exec(db, sql_insert, NULL, 0, &err_msg);

        if (rc != SQLITE_OK) {
            log_message(1, sqlite3_errmsg(db));
            sqlite3_free(err_msg);
            sqlite3_free(sql_insert);
            sqlite3_close(db);
            return 0;
        }

        sqlite3_free(sql_insert);
    }

    sqlite3_close(db);
    return 1;
}

int main() {
