#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int value;
    long offset;
    int key;
    double weight;
} Record;

static uint64_t xorshift128plus_state[2] = {123456789, 362436069};

uint64_t xorshift128plus(void) {
    uint64_t s1 = xorshift128plus_state[0];
    const uint64_t s0 = xorshift128plus_state[1];
    xorshift128plus_state[0] = s0;
    s1 ^= s1 << 23; // a
    xorshift128plus_state[1] = s1 ^ s0 ^ (s1 >> 17) ^ (s0 >> 26); // b, c
    return xorshift128plus_state[1] + s0; // d
}

double generate_random_double(double min, double max) {
    return min + ((double)xorshift128plus() / UINT64_MAX) * (max - min);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <N> <minValue> <maxValue>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t N = atoll(argv[1]);
    int minValue = atoi(argv[2]);
    int maxValue = atoi(argv[3]);

    if (N == 0 || minValue >= maxValue) {
        fprintf(stderr, "Invalid input parameters.\n");
        return EXIT_FAILURE;
    }

    long* offsets = calloc(N, sizeof(long));
    int* keys = calloc(N, sizeof(int));
    double* weights = calloc(N, sizeof(double));

    if (!offsets || !keys || !weights) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(weights);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < N; ++i) {
        offsets[i] = i;
        keys[i] = i;
        weights[i] = generate_random_double(0.0, 1.0);
    }

    Record* records = calloc(N, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(weights);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < N; ++i) {
        int value;
        do {
            value = minValue + (int)(generate_random_double(0.0, 1.0) * (maxValue - minValue + 1));
        } while (value > maxValue);

        records[i].value = value;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].weight = weights[i];

        printf("Record %zu: Value=%d, Offset=%ld, Key=%d, Weight=%.6f\n", i, value, records[i].offset, records[i].key, records[i].weight);
    }

    free(offsets);
    free(keys);
    free(weights);
    free(records);

    return EXIT_SUCCESS;
}
