typedef struct SessionData {
    float average_value;
    bool active;
} SessionData;

typedef struct {
    unsigned long session_id;
    SessionData data;
} HashTableEntry;

#define INITIAL_HASH_TABLE_SIZE 1024
#define MAX_SESSIONS 1000000

pthread_mutex_t hash_table_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned int resize_threshold_factor = 2; // Can be set from config file
time_t session_timeout_threshold = 300; // Can be set from config file

HashTableEntry* hash_table[INITIAL_HASH_TABLE_SIZE];
int hash_table_size = INITIAL_HASH_TABLE_SIZE;

unsigned long hash_function(unsigned long key) {
    return key % hash_table_size;
}

void resize_hash_table() {
    pthread_mutex_lock(&hash_table_mutex);

    unsigned int new_size = hash_table_size * resize_threshold_factor;
    HashTableEntry** new_table = calloc(new_size, sizeof(HashTableEntry*));

    for (int i = 0; i < hash_table_size; ++i) {
        if (hash_table[i]) {
            HashTableEntry* entry = hash_table[i];
            while (entry) {
                unsigned long index = entry->session_id % new_size;
                HashTableEntry* next_entry = entry->next;

                entry->next = new_table[index];
                new_table[index] = entry;
                entry = next_entry;
            }
        }
    }

    free(hash_table);
    hash_table = new_table;
    hash_table_size = new_size;

    pthread_mutex_unlock(&hash_table_mutex);
}

void add_session(unsigned long session_id, float average_value) {
    pthread_mutex_lock(&hash_table_mutex);

    if (/* number of sessions exceeds some threshold */) {
        resize_hash_table();
    }

    unsigned long index = hash_function(session_id);
    HashTableEntry* entry = malloc(sizeof(HashTableEntry));
    entry->session_id = session_id;
    entry->data.average_value = average_value;
    entry->data.active = true;

    entry->next = hash_table[index];
    hash_table[index] = entry;

    pthread_mutex_unlock(&hash_table_mutex);
}

void prune_inactive_sessions() {
    time_t current_time = time(NULL);

    for (int i = 0; i < hash_table_size; ++i) {
        HashTableEntry* prev_entry = NULL;
        HashTableEntry* entry = hash_table[i];

        while (entry) {
            if (!entry->data.active && difftime(current_time, entry->timestamp) > session_timeout_threshold) {
                if (prev_entry) {
                    prev_entry->next = entry->next;
                } else {
                    hash_table[i] = entry->next;
                }
                HashTableEntry* to_delete = entry;
                entry = entry->next;
                free(to_delete);
            } else {
                prev_entry = entry;
                entry = entry->next;
            }
        }
    }
}

void* session_manager(void* arg) {
    while (1) {
        prune_inactive_sessions();
        sleep(60); // Run every minute, adjust as needed
    }

    return NULL;
}

int main() {
    pthread_t pruner_thread;
    if (pthread_create(&pruner_thread, NULL, session_manager, NULL) != 0) {
        perror("Failed to create pruning thread");
        exit(EXIT_FAILURE);
    }

    // Example usage
    add_session(12345, 42.0);

    pthread_join(pruner_thread, NULL); // Never actually joins in real-world scenario

    return 0;
}
