}

// Helper functions
HashMap* createHashmap(size_t initialSize) {
    HashMap *map = malloc(sizeof(HashMap));
    map->size = initialSize;
    map->count = 0;
    map->table = calloc(initialSize, sizeof(Node *));
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void hashmapInsert(HashMap *map, size_t key, void *data) {
    pthread_mutex_lock(&map->lock);

    if (map->count / (double)map->size > LOAD_FACTOR_THRESHOLD) {
        resizeHashmap(map);
    }

    size_t index = key % map->size;
    Node *node = malloc(sizeof(Node));
    node->key = key;
    node->data = data;
    node->next = map->table[index];
    map->table[index] = node;
    map->count++;

    pthread_mutex_unlock(&map->lock);
}

void* hashmapGet(HashMap *map, size_t key) {
    pthread_mutex_lock(&map->lock);

    size_t index = key % map->size;
    Node *node = map->table[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&map->lock);
            return node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void resizeHashmap(HashMap *map) {
    size_t newSize = map->size * 2;
    Node **newTable = calloc(newSize, sizeof(Node *));

    for (size_t i = 0; i < map->size; ++i) {
        Node *node = map->table[i];
        while (node) {
            size_t newIndex = node->key % newSize;
            Node *nextNode = node->next;
            node->next = newTable[newIndex];
            newTable[newIndex] = node;
            node = nextNode;
        }
    }

    free(map->table);
    map->table = newTable;
    map->size = newSize;
}

void initializeLRUCache(LRUCache *cache) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void lruCachePut(LRUCache *cache, size_t key, void *data) {
    pthread_mutex_lock(&cache->lock);

    CacheEntry *entry = cache->head;
    while (entry) {
        if (entry->key == key) {
            entry->data = data;
            goto unlock;
        }
        entry = entry->next;
    }

    if (cache->count >= CACHE_SIZE) {
        // Evict LRU
        void *evictedData = cache->head->data;
        CacheEntry *toRemove = cache->head;
        cache->head = cache->head->next;
        free(toRemovedata);
        free(toRemove);

        --cache->count;
    }

    entry = malloc(sizeof(CacheEntry));
    entry->key = key;
    entry->data = data;
    entry->prev = NULL;
    entry->next = cache->head;

    if (cache->head) {
        cache->head->prev = entry;
    }
    cache->head = entry;

    if (!cache->tail) {
        cache->tail = entry;
    }

    ++cache->count;

unlock:
    pthread_mutex_unlock(&cache->lock);
}

void* lruCacheGet(LRUCache *cache, size_t key) {
    pthread_mutex_lock(&cache->lock);

    CacheEntry *entry = cache->head;
    while (entry) {
        if (entry->key == key) {
            // Move accessed entry to head
            if (entry != cache->head) {
                if (entry->prev) {
                    entry->prev->next = entry->next;
                }
                if (entry->next) {
                    entry->next->prev = entry->prev;
                }
                if (cache->tail == entry) {
                    cache->tail = entry->prev;
                }

                entry->prev = NULL;
                entry->next = cache->head;
                cache->head->prev = entry;
                cache->head = entry;
            }
            pthread_mutex_unlock(&cache->lock);
            return entry->data;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}
