```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <math.h>

#define INITIAL_CAPACITY 16
#define ID_LENGTH 8
#define RANGE_MIN 0.0
#define RANGE_MAX 100.0

typedef struct Entry {
    char id[ID_LENGTH + 1];
    float value;
} Entry;

typedef struct HashNode {
    Entry entry;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    Entry* heap;
    size_t size;
    pthread_mutex_t lock;
} BinaryHeap;

// Function prototypes
void initialize_random_seed();
float generate_random_float(float min, float max);
char* generate_unique_id(char charset[], int length, HashTable* table);
HashTable* create_hash_table(size_t capacity);
BinaryHeap* create_binary_heap(size_t capacity);
void hash_insert(HashTable* table, Entry entry);
Entry* hash_lookup(HashTable* table, const char* id);
void binary_heap_insert(BinaryHeap* heap, Entry entry);
Entry binary_heap_extract_min(BinaryHeap* heap);
void update_entry_value(HashTable* table, BinaryHeap* heap, const char* id, float new_value);

// Function definitions
void initialize_random_seed() {
    srand(time(NULL));
}

float generate_random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

char* generate_unique_id(char charset[], int length, HashTable* table) {
    char* id = malloc(length + 1);
    bool unique;
    do {
        for (int i = 0; i < length; ++i) {
            id[i] = charset[rand() % strlen(charset)];
        }
        id[length] = '\0';

        pthread_mutex_lock(&table->lock);
        Entry temp_entry = { .id = "" };
        strcpy(temp_entry.id, id);
        HashNode* node = (HashNode*)hash_lookup(table, id);
        unique = node == NULL;
        if (!unique) {
            free(node);
        }
        pthread_mutex_unlock(&table->lock);
    } while (!unique);

    return id;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->table = calloc(capacity, sizeof(HashNode*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

BinaryHeap* create_binary_heap(size_t capacity) {
    BinaryHeap* heap = malloc(sizeof(BinaryHeap));
    heap->heap = malloc(capacity * sizeof(Entry));
    heap->size = 0;
    pthread_mutex_init(&heap->lock, NULL);
    return heap;
}

unsigned long hash_function(const char* id) {
    unsigned long hash = 5381;
    int c;
    while ((c = *id++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

void hash_insert(HashTable* table, Entry entry) {
    unsigned long index = hash_function(entry.id) % table->capacity;

    pthread_mutex_lock(&table->lock);
    HashNode* node = malloc(sizeof(HashNode));
    node->entry = entry;
    node->next = table->table[index];
    table->table[index] = node;
    pthread_mutex_unlock(&table->lock);
}

Entry* hash_lookup(HashTable* table, const char* id) {
    unsigned long index = hash_function(id) % table->capacity;

    pthread_mutex_lock(&table->lock);
    HashNode* node = table->table[index];
    while (node) {
        if (strcmp(node->entry.id, id) == 0) {
            pthread_mutex_unlock(&table->lock);
            return &node->entry;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void binary_heap_insert(BinaryHeap* heap, Entry entry) {
    pthread_mutex_lock(&heap->lock);
    if (heap->size >= heap->capacity) {
        // Handle capacity exceeded
        heap->heap = realloc(heap->heap, (heap->capacity * 2) * sizeof(Entry));
        heap->capacity *= 2;
    }
    size_t i = ++heap->size;
    while (i > 1 && heap->heap[i / 2].value > entry.value) {
        heap->heap[i] = heap->heap[i / 2];
        i /= 2;
    }
    heap->heap[i] = entry;
    pthread_mutex_unlock(&heap->lock);
}

Entry binary_heap_extract_min(BinaryHeap* heap) {
    Entry min_entry;
    pthread_mutex_lock(&heap->lock);
    if (heap->size == 0) {
        pthread_mutex_unlock(&heap->lock);
        return (Entry){ .value = -1.0 }; // Indicate empty heap
    }
    min_entry = heap->heap[1];
    Entry last_entry = heap->heap[heap->size--];

    size_t i = 1;
    while (i * 2 <= heap->size) {
        size_t smallest = i * 2;
        if (smallest < heap->size && heap->heap[smallest + 1].value < heap->heap[smallest].value)
            ++smallest;
        if (last_entry.value <= heap->heap[smallest].value) break;
        heap->heap[i] = heap->heap[smallest];
        i = smallest;
    }

    heap->heap[i] = last_entry;
    pthread_mutex_unlock(&heap->lock);
    return min_entry;
}

void update_entry_value(HashTable* table, BinaryHeap* heap, const char* id, float new_value) {
    Entry* entry = (Entry*)hash_lookup(table, id);
    if (!entry) return;

    // Remove from binary heap
    pthread_mutex_lock(&heap->lock);
    for (size_t i = 1; i <= heap->size; ++i) {
        if (strcmp(heap->heap[i].id, id) == 0) {
            heap->heap[i] = heap->heap[heap->size--];
            break;
        }
    }
    // Re-insert with new value
    entry->value = new_value;
    binary_heap_insert(heap, *entry);
    pthread_mutex_unlock(&heap->lock);

    // Update hash table
    pthread_mutex_lock(&table->lock);
    for (unsigned long index = hash_function(id) % table->capacity; ; index = (index + 1) % table->capacity) {
        HashNode* node = table->table[index];
        if (!node) break;
        if (strcmp(node->entry.id, id) == 0) {
            node->entry.value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void refresh_data_from_api(HashTable* table, BinaryHeap* heap) {
    // Simulate API call
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->table[i];
        while (node) {
            Entry updated_entry = node->entry;
            float new_value = generate_random_float(RANGE_MIN, RANGE_MAX);
            update_entry_value(table, heap, updated_entry.id, new_value);
            node = node->next;
        }
    }
}

void* periodic_refresh(void* arg) {
    HashTable* table = (HashTable*)arg;
    BinaryHeap* heap = (BinaryHeap*)arg;

    while (1) {
        refresh_data_from_api(table, heap);
        sleep(10); // Simulate periodic refresh
    }

    return NULL;
}

int main() {
    initialize_random_seed();

    HashTable* table = create_hash_table(INITIAL_CAPACITY);
    BinaryHeap* heap = create_binary_heap(INITIAL_CAPACITY);

    char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        Entry entry;
        entry.id = generate_unique_id(charset, ID_LENGTH, table);
        entry.value = generate_random_float(RANGE_MIN, RANGE_MAX);
        hash_insert(table, entry);
        binary_heap_insert(heap, entry);
    }

    pthread_t refresh_thread;
    pthread_create(&refresh_thread, NULL, periodic_refresh, (void*)table);

    // Simulate operations
    update_entry_value(table, heap, table->table[0]->entry.id, 50.0f);

    pthread_join(refresh_thread, NULL);

    free(table->table);
    free(table);
    free(heap->heap);
    free(heap);

    return 0;
}
