['Below is a C implementation for managing a system of records in a multi-threaded environment with an emphasis on thread safety, memory efficiency, and dynamic resizing:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct Record {
    short s;
    int i;
    float f;
    struct Record* next;
} Record;

typedef struct MemoryPool {
    void** free_list;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = pool_size;
    mp->free_list = (void**)calloc(pool_size, sizeof(void*));

    pthread_mutex_init(&mp->mutex, NULL);

    for (size_t i = 0; i < pool_size - 1; ++i) {
        void* block = malloc(block_size);
        *((void**)(block)) = &mp->free_list[i + 1];
        mp->free_list[i] = block;
    }

    void* last_block = malloc(block_size);
    mp->free_list[pool_size - 1] = NULL;
    *((void**)(last_block)) = NULL;

    return mp;
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->mutex);

    if (mp->free_list == NULL) {
        pthread_mutex_unlock(&mp->mutex);
        return NULL; // Pool exhausted
    }

    void** block = mp->free_list;
    mp->free_list = *block;

    pthread_mutex_unlock(&mp->mutex);

    return block;
}

void deallocate_to_pool(MemoryPool* mp, void* block) {
    pthread_mutex_lock(&mp->mutex);

    *((void**)block) = mp->free_list;
    mp->free_list = (void**)(block);

    pthread_mutex_unlock(&mp->mutex);
}

typedef struct LinkedList {
    Record* head;
    atomic_size_t size;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    atomic_store(&list->size, 0);
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void add_record(LinkedList* list, short s, int i, float f) {
    Record* new_record = (Record*)allocate_from_pool(global_memory_pool);
    if (!new_record) return; // Handle allocation failure

    new_record->s = s;
    new_record->i = i;
    new_record->f = f;
    new_record->next = NULL;

    pthread_mutex_lock(&list->mutex);

    new_record->next = list->head;
    list->head = new_record;

    atomic_fetch_add(&list->size, 1);
    pthread_mutex_unlock(&list->mutex);
}

void iterate_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Record* current = list->head;

    while (current != NULL) {
        printf("Record: (%d, %d, %.2f)\n", current->s, current->i, current->f);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        deallocate_to_pool(global_memory_pool, current);
        current = next;
    }

    atomic_store(&list->size, 0);
    pthread_mutex_unlock(&list->mutex);
}

void log_linked_list_state(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    printf("Linked List State:\n");
    iterate_linked_list(list);

    pthread_mutex_unlock(&list->mutex);
}

// Seed the random number generator
void seed_rng() {
    srand((unsigned int)time(NULL));
}

// Generate a random record with specified bounds
Record generate_random_record(short s_min, short s_max, int i_min, int i_max, float f_min, float f_max) {
    Record rec;
    rec.s = (short)(s_min + rand() % (s_max - s_min + 1));
    rec.i = i_min + rand() % (i_max - i_min + 1);
    rec.f = f_min + ((float)rand() / RAND_MAX) * (f_max - f_min);

    return rec;
}

// Global memory pool
MemoryPool* global_memory_pool;

int main() {
    seed_rng();
    size_t block_size = sizeof(Record);
    size_t pool_size = 100; // Adjust as needed

    global_memory_pool = create_memory_pool(block_size, pool_size);

    LinkedList* list = create_linked_list();

    // Example usage: Add random records
    for (int i = 0; i < 10; ++i) {
        Record rec = generate_random_record(1, 100, 1, 1000, 0.0f, 100.0f);
        add_record(list, rec.s, rec.i, rec.f);
    }

    log_linked_list_state(list);

    free_linked_list(list);
    // Free the memory pool and other resources as needed

    return 0;
}
```

### Key Points:
- **Memory Pool**: A custom memory allocator reduces fragmentation and improves allocation performance.
- **Thread Safety**: Mutexes are used to protect linked list operations, ensuring that concurrent access doesn't lead to race conditions or data corruption.
- **Random Number Generation**: Utilizes `rand()` seeded with the current time for simplicity; for more robust applications, consider using `<random>` in C++ or libraries like PCG or Boost in C.
- **Linked List Management**: Efficiently handles dynamic addition and iteration over records while ensuring thread safety.
- **Logging Functionality**: Provides a non-intrusive method to log the state of the linked list.']

