    }
}

int hash_function(const char *str, size_t table_size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % table_size;
}

MinHeap *create_min_heap(size_t capacity) {
    MinHeap *heap = malloc(sizeof(MinHeap));
    heap->data = calloc(capacity, sizeof(Entry *));
    heap->capacity = capacity;
    heap->size = 0;
    return heap;
}

void free_min_heap(MinHeap *heap) {
    if (heap) {
        for (size_t i = 0; i < heap->size; ++i)
            free_entry(heap->data[i]);
        free(heap->data);
        free(heap);
    }
}

void min_heapify(MinHeap *heap, int index) {
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < heap->size && heap->data[left]->value < heap->data[smallest]->value)
        smallest = left;
    if (right < heap->size && heap->data[right]->value < heap->data[smallest]->value)
        smallest = right;

    if (smallest != index) {
        Entry *temp = heap->data[index];
        heap->data[index] = heap->data[smallest];
        heap->data[smallest] = temp;
        min_heapify(heap, smallest);
    }
}

void insert_min_heap(MinHeap *heap, Entry *entry) {
    if (heap->size == heap->capacity)
        return;

    heap->data[heap->size] = entry;
    int i = heap->size++;
    while (i && heap->data[(i - 1) / 2]->value > heap->data[i]->value) {
        Entry *temp = heap->data[i];
        heap->data[i] = heap->data[(i - 1) / 2];
        heap->data[(i - 1) / 2] = temp;
        i = (i - 1) / 2;
    }
}

Entry *extract_min(MinHeap *heap) {
    if (heap->size == 0)
        return NULL;

    Entry *root = heap->data[0];
    heap->data[0] = heap->data[--heap->size];
    min_heapify(heap, 0);

    return root;
}

void update_min_heap(MinHeap *heap, Entry *entry) {
    for (int i = 0; i < heap->size; ++i) {
        if (heap->data[i] == entry) {
            min_heapify(heap, i);
            break;
        }
    }
}

ListNode *create_list_node(Entry *entry) {
    ListNode *node = malloc(sizeof(ListNode));
    node->entry = entry;
    node->next = NULL;
    return node;
}

void free_list_node(ListNode *node) {
    if (node) {
        free(node);
    }
}

ThreadSafeList *create_thread_safe_list(size_t limit) {
    ThreadSafeList *list = malloc(sizeof(ThreadSafeList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->limit = limit;
    return list;
}

void free_thread_safe_list(ThreadSafeList *list) {
    if (list) {
        ListNode *current = list->head;
        while (current) {
            ListNode *next_node = current->next;
            free_list_node(current);
            current = next_node;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void insert_recent_entry(ThreadSafeList *list, Entry *entry) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL || list->head->entry->timestamp < entry->timestamp) {
        ListNode *new_node = create_list_node(entry);
        new_node->next = list->head;
        list->head = new_node;
    } else {
        ListNode *current = list->head;
        while (current->next != NULL && current->next->entry->timestamp >= entry->timestamp) {
            current = current->next;
        }
        if (list->size() < list->limit || strcmp(current->entry->identifier, entry->identifier) != 0) {
            ListNode *new_node = create_list_node(entry);
            new_node->next = current->next;
            current->next = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void log_performance_metrics(const char *message) {
    // Placeholder for logging performance metrics
    printf("%s\n", message);
}

float generate_random_float(float min, float max) {
    return min + ((float)rand() / RAND_MAX) * (max - min);
}

char *generate_unique_identifier(const Config *config, HashTable *hash_table) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t len = config->charset_length;
    char *identifier = malloc(len + 1);

    do {
        for (size_t i = 0; i < len; ++i)
            identifier[i] = charset[rand() % config->charset_length];
        identifier[len] = '\0';

        int index = hash_function(identifier, hash_table->table_size);
        pthread_mutex_lock(&hash_table->lock);
        Node *node = hash_table->table[index];
        while (node) {
            if (strcmp(node->entry->identifier, identifier) == 0) {
                pthread_mutex_unlock(&hash_table->lock);
                free(identifier);
                break;
            }
            node = node->next;
        }

        if (!node) { // Unique
            Node *new_node = malloc(sizeof(Node));
            new_node->entry = create_entry(identifier, time(NULL), 0.0f);
            new_node->next = hash_table->table[index];
            hash_table->table[index] = new_node;
            pthread_mutex_unlock(&hash_table->lock);
            return identifier;
        }
    } while (1);

    free(identifier);
    return NULL; // Should never reach here if memory is sufficient
}

int main() {
    Config config = {
        .charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",
        .charset_length = 62,
        .identifier_length = 10,
        .value_min = 0.0f,
        .value_max = 100.0f,
        .hash_table_size = 1024,
        .heap_capacity = 256,
        .list_limit = 50
    };

    HashTable *hash_table = create_hash_table(config.hash_table_size);
    MinHeap *min_heap = create_min_heap(config.heap_capacity);
    ThreadSafeList *recent_list = create_thread_safe_list(config.list_limit);

    for (int i = 0; i < 1000; ++i) {
        char *identifier = generate_unique_identifier(&config, hash_table);
        int timestamp = time(NULL);
        float value = generate_random_float(config.value_min, config.value_max);

        Entry *entry = create_entry(identifier, timestamp, value);
        insert_recent_entry(recent_list, entry);

        pthread_mutex_lock(&hash_table->lock);
        int index = hash_function(entry->identifier, hash_table->table_size);
        Node *new_node = malloc(sizeof(Node));
        new_node->entry = entry;
        new_node->next = hash_table->table[index];
        hash_table->table[index] = new_node;
        pthread_mutex_unlock(&hash_table->lock);

        insert_min_heap(min_heap, entry);
    }

    log_performance_metrics("Data structures initialized and populated.");

    free_hash_table(hash_table);
    free_min_heap(min_heap);
    free_thread_safe_list(recent_list);

    return 0;
}
