#define MAX_ENTRIES 1000
#define IDENTIFIER_LENGTH 8
#define CHAR_SET "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
#define CHAR_SET_SIZE 62

typedef struct Entry {
    char identifier[IDENTIFIER_LENGTH + 1];
    float value;
} Entry;

typedef struct HashTable {
    Entry* entries[MAX_ENTRIES];
    size_t size;
    pthread_mutex_t lock;
} HashTable;

typedef struct HeapNode {
    Entry entry;
    int index;
} HeapNode;

typedef struct MinHeap {
    HeapNode* nodes[MAX_ENTRIES];
    int size;
    pthread_mutex_t lock;
} MinHeap;

// Function prototypes
void initialize_memory_pool();
Entry* create_entry(const char* identifier, float value);
