unsigned long hash_function(const char* str);
char* generate_unique_identifier(char* buffer, unsigned long seed, size_t length);
float random_float(float min, float max, unsigned long* seed);
void init_hash_table(HashTable* table);
void insert_into_hash_table(HashTable* table, Entry* entry);
Entry* search_in_hash_table(const HashTable* table, const char* identifier);
void delete_from_hash_table(HashTable* table, const char* identifier);
void heapify_up(MinHeap* heap, int index);
void heapify_down(MinHeap* heap, int index);
void insert_into_heap(MinHeap* heap, Entry entry);
Entry extract_min(MinHeap* heap);
void update_value_in_heap(MinHeap* heap, const char* identifier, float newValue);

// Initialize memory pool (simplified for demonstration)
void initialize_memory_pool() {
    // Implement custom memory pool initialization if needed
}

// Create an entry with a unique identifier and random value
Entry* create_entry(const char* identifier, float value) {
    Entry* entry = malloc(sizeof(Entry));
    if (!entry) return NULL;
    strncpy(entry->identifier, identifier, IDENTIFIER_LENGTH);
    entry->value = value;
    return entry;
}

// Free an entry
void free_entry(Entry* entry) {
    free(entry);
}

// Hash function for identifiers
unsigned long hash_function(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % MAX_ENTRIES;
}

// Generate a unique identifier string
char* generate_unique_identifier(char* buffer, unsigned long seed, size_t length) {
    srand(seed);
    const char charset[CHAR_SET_SIZE] = CHAR_SET;
    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        buffer[i] = charset[key];
    }
    buffer[length] = '\0';
    return buffer;
}

// Generate a random float in the range [min, max]
float random_float(float min, float max, unsigned long* seed) {
    srand(*seed);
    *seed += 1; // Update seed for reproducibility
    return min + (rand() / (RAND_MAX + 1.0)) * (max - min);
}

// Initialize hash table
void init_hash_table(HashTable* table) {
    memset(table, 0, sizeof(HashTable));
    pthread_mutex_init(&table->lock, NULL);
}

// Insert an entry into the hash table
void insert_into_hash_table(HashTable* table, Entry* entry) {
    unsigned long index = hash_function(entry->identifier);
    pthread_mutex_lock(&table->lock);
    while (table->entries[index]) {
        if (strcmp(table->entries[index]->identifier, entry->identifier) == 0) {
            free_entry(table->entries[index]);
            break;
        }
        index = (index + 1) % MAX_ENTRIES; // Linear probing
    }
    table->entries[index] = entry;
    pthread_mutex_unlock(&table->lock);
}

// Search for an entry in the hash table
Entry* search_in_hash_table(const HashTable* table, const char* identifier) {
    unsigned long index = hash_function(identifier);
    pthread_mutex_lock(&table->lock);
    while (table->entries[index]) {
        if (strcmp(table->entries[index]->identifier, identifier) == 0) {
            Entry* entry = table->entries[index];
            pthread_mutex_unlock(&table->lock);
            return entry;
        }
        index = (index + 1) % MAX_ENTRIES; // Linear probing
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Delete an entry from the hash table
void delete_from_hash_table(HashTable* table, const char* identifier) {
    unsigned long index = hash_function(identifier);
    pthread_mutex_lock(&table->lock);
    while (table->entries[index]) {
        if (strcmp(table->entries[index]->identifier, identifier) == 0) {
            free_entry(table->entries[index]);
            table->entries[index] = NULL;
            break;
        }
        index = (index + 1) % MAX_ENTRIES; // Linear probing
    }
    pthread_mutex_unlock(&table->lock);
}

// Heapify up operation for min-heap
void heapify_up(MinHeap* heap, int index) {
    while (index > 0 && heap->nodes[(index - 1) / 2]->entry.value > heap->nodes[index]->entry.value) {
        // Swap nodes
        HeapNode temp = heap->nodes[index];
        heap->nodes[index] = heap->nodes[(index - 1) / 2];
        heap->nodes[(index - 1) / 2] = temp;
        index = (index - 1) / 2;
    }
}

// Heapify down operation for min-heap
void heapify_down(MinHeap* heap, int index) {
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < heap->size && heap->nodes[left]->entry.value < heap->nodes[smallest]->entry.value)
        smallest = left;
    if (right < heap->size && heap->nodes[right]->entry.value < heap->nodes[smallest]->entry.value)
        smallest = right;

    if (smallest != index) {
        HeapNode temp = heap->nodes[index];
        heap->nodes[index] = heap->nodes[smallest];
        heap->nodes[smallest] = temp;
        heapify_down(heap, smallest);
    }
}

// Insert an entry into the min-heap
void insert_into_heap(MinHeap* heap, Entry entry) {
    pthread_mutex_lock(&heap->lock);
    if (heap->size == MAX_ENTRIES) return; // Heap is full

    HeapNode* node = malloc(sizeof(HeapNode));
    node->entry = entry;
    node->index = heap->size;
    heap->nodes[heap->size] = node;
    heapify_up(heap, heap->size);
    heap->size++;
    pthread_mutex_unlock(&heap->lock);
}

// Extract the minimum value from the min-heap
Entry extract_min(MinHeap* heap) {
    pthread_mutex_lock(&heap->lock);
    if (heap->size <= 0) {
        pthread_mutex_unlock(&heap->lock);
        Entry empty = { .identifier = "", .value = 0 };
        return empty;
    }

    HeapNode* root = heap->nodes[0];
    HeapNode* lastNode = heap->nodes[--heap->size];
    heap->nodes[0] = lastNode;

    if (heap->size > 0) {
        heapify_down(heap, 0);
    }
    pthread_mutex_unlock(&heap->lock);

    Entry minEntry = root->entry;
    free(root);
    return minEntry;
}

// Update a value in the heap and re-sort
void update_value_in_heap(MinHeap* heap, const char* identifier, float newValue) {
    pthread_mutex_lock(&heap->lock);
    for (int i = 0; i < heap->size; ++i) {
        if (strcmp(heap->nodes[i]->entry.identifier, identifier) == 0) {
            heap->nodes[i]->entry.value = newValue;
            heapify_up(heap, i);
            heapify_down(heap, i);
            break;
        }
    }
    pthread_mutex_unlock(&heap->lock);
}

// Example usage
int main() {
    HashTable table;
    MinHeap heap;
    init_hash_table(&table);
    pthread_mutex_init(&heap.lock, NULL);

    unsigned long seed = time(NULL);
    char buffer[IDENTIFIER_LENGTH + 1];
    Entry* entry;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        generate_unique_identifier(buffer, seed, IDENTIFIER_LENGTH);
        float value = random_float(0.0, 100.0, &seed);
        entry = create_entry(buffer, value);
        insert_into_hash_table(&table, entry);
        insert_into_heap(heap, *entry);
    }

    // Example of updating a value
    update_value_in_heap(&heap, "A1B2C3D4", 50.0);

    Entry minEntry = extract_min(&heap);
    printf("Min entry: %s with value %.2f\n", minEntry.identifier, minEntry.value);

    pthread_mutex_destroy(&heap.lock);
    return 0;
}
