    if (!dm) return;

    free(dm->offsets);
    free(dm->keys);

    for (size_t i = 0; i < dm->num_records; ++i) {
        free(dm->records[i]);
    }
    free(dm->records);

    pthread_mutex_destroy(&dm->lock);
    fclose(dm->log_file);
    free(dm);
