} record;

// Define log levels
#define LOG_LEVEL_ERROR 0
#define LOG_LEVEL_WARN 1
#define LOG_LEVEL_INFO 2

int current_log_level = LOG_LEVEL_INFO; // Configurable verbosity level

void log_message(int level, const char *message) {
    if (level <= current_log_level) {
        printf("[%d] %s\n", level, message);
    }
}

// Custom memory allocation strategy
void* custom_alloc(size_t size, const char* alloc_type) {
    void* ptr = malloc(size);
    if (!ptr) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for type: ");
        log_message(LOG_LEVEL_ERROR, alloc_type);
        return NULL;
    }
    memset(ptr, 0, size); // Initialize memory to zero
    log_message(LOG_LEVEL_INFO, "Allocated memory for type: ");
    log_message(LOG_LEVEL_INFO, alloc_type);
    return ptr;
}

// Custom free with logging
void custom_free(void* ptr, const char* dealloc_type) {
    if (ptr) {
        log_message(LOG_LEVEL_INFO, "Deallocated memory for type: ");
        log_message(LOG_LEVEL_INFO, dealloc_type);
        free(ptr);
    }
}

void init_and_allocate(int num_offsets, int num_keys, int num_records, int value_range_min, int value_range_max) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = custom_alloc(num_offsets * sizeof(long), "long offsets");
    int *keys = custom_alloc(num_keys * sizeof(int), "int keys");
    record *records = custom_alloc(num_records * sizeof(record), "record array");

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        log_message(LOG_LEVEL_ERROR, "Allocation failed. Cleaning up.");
        custom_free(offsets, "long offsets");
        custom_free(keys, "int keys");
        custom_free(records, "record array");
        pthread_mutex_destroy(&lock);
        return;
    }

    srand((unsigned)time(NULL)); // Seed random number generator

    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % value_range_max;
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand() % value_range_max;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = (rand() % (value_range_max - value_range_min + 1)) + value_range_min;
    }

    pthread_mutex_unlock(&lock);

    // Simulate usage
    log_message(LOG_LEVEL_INFO, "Data initialization complete.");

    // Clean up resources
    custom_free(offsets, "long offsets");
    custom_free(keys, "int keys");
    custom_free(records, "record array");

    pthread_mutex_destroy(&lock);
}

int main() {
    init_and_allocate(1000, 1000, 1000, 1, 10000);
    return 0;
}
