void serialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, FILE *file) {
    fwrite(pdu, sizeof(*pdu), 1, file);
}

void deserialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, FILE *file) {
    fread(pdu, sizeof(*pdu), 1, file);
}

uint16_t generate_random_crc_flag(double probability) {
    return (rand() / (double)RAND_MAX < probability) ? 1 : 0;
}

int calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += pdus[i].CRCFLAG + pdus[i].RX_UE_INFORMATION_TAG + pdus[i].RNTI;
    }
    return checksum % 256;
}

char* get_directory_path() {
    static char dir_path[MAX_DIRECTORY_LENGTH];
    const char *env_dir = getenv("DIR_PATH");
    if (env_dir != NULL && strlen(env_dir) < MAX_DIRECTORY_LENGTH - 1) {
        strcpy(dir_path, env_dir);
    } else {
        strncpy(dir_path, ROOT_DIR, sizeof(ROOT_DIR) - 1);
    }
    return dir_path;
}

void manage_memory(int *keys, long *offsets, record *records, NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num_pdus, double crc_flag_prob, int max_memory) {
    pthread_mutex_lock(&global_lock);

    char *file_name = get_directory_path();
    strcat(file_name, "state_file.dat");

    FILE *file = fopen(file_name, "rb+");
    if (file == NULL) {
        log_callback("Error opening file");
        pthread_mutex_unlock(&global_lock);
        return;
    }

    // Read current state from the file
    fread(keys, sizeof(int), ARRAY_SIZE, file);
    fread(offsets, sizeof(long), ARRAY_SIZE, file);

    for (size_t i = 0; i < num_pdus; ++i) {
        deserialize_pdu(&pdus[i], file);
        pdus[i].CRCFLAG = generate_random_crc_flag(crc_flag_prob);
        if (!validate_crc_tag(pdus[i].RX_UE_INFORMATION_TAG)) {
            log_callback("Invalid CRC tag");
            continue;
        }
    }

    // Serialize updated state back to the file
    for (size_t i = 0; i < num_pdus; ++i) {
        serialize_pdu(&pdus[i], file);
    }

    fwrite(keys, sizeof(int), ARRAY_SIZE, file);
    fwrite(offsets, sizeof(long), ARRAY_SIZE, file);

    fclose(file);

    // Initialize records with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        records[i].value = rand() % 100;
    }

    uint32_t checksum = calculate_checksum(pdus, num_pdus);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Checksum: %u", checksum);
    log_callback(log_message);

    pthread_mutex_unlock(&global_lock);
}

int main() {
    int keys[ARRAY_SIZE];
    long offsets[ARRAY_SIZE];
    record records[ARRAY_SIZE];
    NFAPI_CRC_INDICATION_PDU_T pdus[ARRAY_SIZE];

    manage_memory(keys, offsets, records, pdus, ARRAY_SIZE, 0.5, MAX_MEMORY);

    return 0;
}
