```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define INITIAL_LONG_ARRAY_SIZE 10
#define INITIAL_INT_ARRAY_SIZE 10
#define INITIAL_RECORD_ARRAY_SIZE 10
#define MAX_MEMORY 1024 * 1024 // 1MB for example

typedef struct {
    int value;
} record_t;

typedef struct {
    long* offset_array;
    int size_offset;
    int max_size_offset;

    int* key_array;
    int size_key;
    int max_size_key;

    record_t* record_array;
    int num_records;
    int max_num_records;

    size_t current_memory_usage;
} MemoryManager;

void resize_if_needed(MemoryManager *mm, int new_size, void **array, char *name) {
    if (new_size > mm->max_size_offset) {
        int new_max = new_size * 2;
        void *temp = realloc(*array, new_max * sizeof(long));
        if (!temp) {
            fprintf(stderr, "Failed to resize %s\n", name);
            exit(EXIT_FAILURE);
        }
        memset((char*) temp + mm->max_size_offset * sizeof(long), 0, (new_max - mm->max_size_offset) * sizeof(long));
        *array = temp;
        mm->max_size_offset = new_max;
    }
}

void initialize_memory_manager(MemoryManager *mm) {
    mm->offset_array = malloc(INITIAL_LONG_ARRAY_SIZE * sizeof(long));
    memset(mm->offset_array, 0, INITIAL_LONG_ARRAY_SIZE * sizeof(long));

    mm->key_array = malloc(INITIAL_INT_ARRAY_SIZE * sizeof(int));
    memset(mm->key_array, 0, INITIAL_INT_ARRAY_SIZE * sizeof(int));

    mm->record_array = malloc(INITIAL_RECORD_ARRAY_SIZE * sizeof(record_t));
    memset(mm->record_array, 0, INITIAL_RECORD_ARRAY_SIZE * sizeof(record_t));

    mm->size_offset = 0;
    mm->max_size_offset = INITIAL_LONG_ARRAY_SIZE;

    mm->size_key = 0;
    mm->max_size_key = INITIAL_INT_ARRAY_SIZE;

    mm->num_records = 0;
    mm->max_num_records = INITIAL_RECORD_ARRAY_SIZE;

    mm->current_memory_usage = sizeof(MemoryManager) + 
                               (mm->max_size_offset * sizeof(long)) +
                               (mm->max_size_key * sizeof(int)) +
                               (mm->max_num_records * sizeof(record_t));
}

void add_record(MemoryManager *mm, int key, record_t rec) {
    if (mm->num_records >= mm->max_num_records) {
        resize_if_needed(mm, mm->num_records + 1, (void**)&mm->record_array, "record array");
    }
    if (mm->size_key >= mm->max_size_key) {
        resize_if_needed(mm, mm->size_key + 1, (void**)&mm->key_array, "key array");
    }

    // Simplified logic for adding a key
    mm->key_array[mm->size_key++] = key;

    mm->record_array[mm->num_records] = rec;
    mm->num_records++;

    mm->current_memory_usage += sizeof(record_t);
}

void update_record(MemoryManager *mm, int key, int new_value) {
    for (int i = 0; i < mm->size_key; ++i) {
        if (mm->key_array[i] == key) {
            mm->record_array[i].value = new_value;
            printf("Updated record %d to value %d\n", key, new_value);
            return;
        }
    }
    fprintf(stderr, "Key %d not found.\n", key);
}

void log_memory_usage(MemoryManager *mm) {
    printf("Current memory usage: %zu bytes\n", mm->current_memory_usage);
    if (mm->current_memory_usage > MAX_MEMORY) {
        fprintf(stderr, "Warning: Memory limit exceeded!\n");
    }
}

int main() {
    MemoryManager mm;
    initialize_memory_manager(&mm);

    add_record(&mm, 1, (record_t){42});
    update_record(&mm, 1, 100);

    log_memory_usage(&mm);

    free(mm.offset_array);
    free(mm.key_array);
    free(mm.record_array);

    return 0;
}
