typedef struct CustomData {
    // User-defined fields
} CustomData;

typedef struct Record {
    double value;
    short key;
    CustomData* custom_data;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        free(current->custom_data); // Assuming custom_data is dynamically allocated
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_record(LinkedList* list, double value, short key, CustomData* custom_data) {
    pthread_mutex_lock(&list->lock);

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_record->value = value;
    new_record->key = key;
    new_record->custom_data = custom_data;
    new_record->next = list->head;
    list->head = new_record;

    pthread_mutex_unlock(&list->lock);
}

void free_custom_data(CustomData* data) {
    // Implement cleanup for CustomData
}

int initialize_records_from_json(const char* filename, LinkedList* list, size_t num_records) {
    json_error_t error;
    json_t* root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading JSON file: %s\n", error.text);
        return -1;
    }

    json_t* values = json_object_get(root, "values");
    json_t* keys = json_object_get(root, "keys");

    if (!json_is_array(values) || !json_is_array(keys)) {
        fprintf(stderr, "JSON format error: 'values' or 'keys' is not an array\n");
        json_decref(root);
        return -1;
    }

    size_t index;
    json_t* value_item;
    json_t* key_item;

    // Initialize random number generator
    srand(time(NULL));

    for (index = 0; index < num_records && index < json_array_size(values); ++index) {
        value_item = json_array_get(values, index);
        key_item = json_array_get(keys, index);

        if (!json_is_number(value_item) || !json_is_integer(key_item)) continue;

        double value = json_number_value(value_item);
        short key = (short)json_integer_value(key_item);

        // Generate random custom data
        CustomData* custom_data = (CustomData*)malloc(sizeof(CustomData));
        if (!custom_data) {
            fprintf(stderr, "Memory allocation failed for custom data\n");
            continue;
        }

        // Initialize custom data here

        add_record(list, value, key, custom_data);
    }

    json_decref(root);
    return (int)index; // Number of successfully initialized records
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return 1;
    }

    int num_records = initialize_records_from_json("data.json", list, 100);
    if (num_records < 0) {
        destroy_linked_list(list);
        return 1;
    }

    printf("Successfully initialized %d records.\n", num_records);

    // Perform operations on the linked list

    destroy_linked_list(list);
    return 0;
}
